### Step 2 — Write the config loader (`config.js`)

```js
// config.js
const path = require('path');

// Load .env only when NOT in production and NOT in test runner.
// In production, real environment variables should be injected by the platform.
const env = process.env.NODE_ENV || 'development';
if (env !== 'production' && env !== 'test') {
  // dotenv.config() does not overwrite existing env vars by default,
  // which is what we want: real env always wins.
  require('dotenv').config({ path: path.resolve(process.cwd(), '.env') });
}

function required(name) {
  const value = process.env[name];
  if (value === undefined || value === '') {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return value;
}

function optional(name, defaultValue) {
  const value = process.env[name];
  if (value === undefined || value === '') return defaultValue;
  return value;
}

const config = Object.freeze({
  env: optional('NODE_ENV', 'development'),
  port: Number(optional('PORT', '3000')),
  databaseUrl: required('DATABASE_URL'),
  apiKey: required('API_KEY'),
});

// Sanity check: port must be a valid number
if (Number.isNaN(config.port) || config.port <= 0) {
  throw new Error(`Invalid PORT value: ${process.env.PORT}`);
}

module.exports = config;
```

**Why this design?**

- **`dotenv` is conditional**: In production you typically inject env vars via the orchestrator (Docker, Kubernetes, systemd, PaaS). Auto-loading `.env` there can mask missing config.
- **`required()` fails fast**: The app crashes immediately at startup with a clear message instead of failing later during a request.
- **`Object.freeze`**: Prevents accidental mutation (`config.port = 9999` throws in strict mode / silently fails otherwise).
- **Coercion happens once**: `PORT` is converted to a `Number` centrally, so consumers don’t repeat parsing.

