    this.registry.set(type, creator);
  }

  create(type) {
    const creator = this.registry.get(type);
    if (!creator) throw new Error(`Unknown notification type: ${type}`);
    return creator();
  }
}

const factory = new NotificationFactory();

factory.register("email", () => ({
  channel: "email",
