# Minimal robust generic utility example

```ts
function toArray<T>(value: T | T[] | null | undefined): T[] {
  if (value == null) return [];
  if (Array.isArray(value)) return value.slice();
  if (typeof value === "string") return [value as unknown as T];
  if (typeof (value as any)[Symbol.iterator] === "function") {
    return Array.from(value as any);
  }
  return [value as T];
}
```

This combines runtime guards with a generic type parameter, which is the safest pattern in real-world JavaScript/TypeScript.

# Graphs and Traversals in JavaScript

Below is a single, self-contained file implementing an adjacency-list graph with support for **directed/undirected**, **weighted/unweighted** graphs, plus BFS, DFS (recursive + iterative), shortest paths (BFS / Dijkstra / Bellman-Ford / Floyd-Warshall), topological sort, cycle detection, connected/strongly-connected components, and MST (Prim / Kruskal). Run with `node graphs.js`.

```js
// graphs.js — complete, runnable example
// Run: node graphs.js

// ---------- Min-Heap (priority queue) ----------
class MinHeap {
  constructor() { this.a = []; }
  push(x) { this.a.push(x); this._up(this.a.length - 1); }
  pop() {
    if (!this.a.length) return null;
    const top = this.a[0];
    const last = this.a.pop();
    if (this.a.length) { this.a[0] = last; this._down(0); }
    return top;
  }
  isEmpty() { return this.a.length === 0; }
  _up(i) {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.a[p].d <= this.a[i].d) break;
      [this.a[p], this.a[i]] = [this.a[i], this.a[p]];
      i = p;
    }
  }
  _down(i) {
    const n = this.a.length;
    for (;;) {
      let l = 2 * i + 1, r = 2 * i + 2, m = i;
      if (l < n && this.a[l].d < this.a[m].d) m = l;
      if (r < n && this.a[r].d < this.a[m].d) m = r;
      if (m === i) break;
      [this.a[m], this.a[i]] = [this.a[i], this.a[m]];
      i = m;
    }
  }
}

// ---------- Disjoint Set Union (Union-Find) ----------
class DSU {
  constructor(items) {
    this.parent = new Map();
    this.rank = new Map();
    for (const x of items) { this.parent.set(x, x); this.rank.set(x, 0); }
  }
  find(x) {
    if (this.parent.get(x) !== x) this.parent.set(x, this.find(this.parent.get(x)));
    return this.parent.get(x);
  }
  union(a, b) {
    const ra = this.find(a), rb = this.find(b);
    if (ra === rb) return false;
    if (this.rank.get(ra) < this.rank.get(rb)) this.parent.set(ra, rb);
    else if (this.rank.get(ra) > this.rank.get(rb)) this.parent.set(rb, ra);
    else { this.parent.set(rb, ra); this.rank.set(ra, this.rank.get(ra) + 1); }
    return true;
  }
}

// ---------- Graph ----------
class Graph {
  constructor({ directed = false, weighted = false } = {}) {
    this.directed = directed;
    this.weighted = weighted;
    this.adj = new Map(); // vertex -> Map<neighbor, weight>
  }

  // ---- vertex / edge mutation ----
  addVertex(v) {
    if (!this.adj.has(v)) this.adj.set(v, new Map());
    return this;
  }
  removeVertex(v) {
    if (!this.adj.has(v)) return false;
    this.adj.delete(v);
    for (const [, edges] of this.adj) edges.delete(v);
    return true;
  }
  addEdge(u, v, weight = 1) {
    this.addVertex(u); this.addVertex(v);
    this.adj.get(u).set(v, weight);
    if (!this.directed) this.adj.get(v).set(u, weight);
    return this;
  }
  removeEdge(u, v) {
    const removed = this.adj.get(u)?.delete(v) ?? false;
    if (!this.directed) this.adj.get(v)?.delete(u);
    return removed;
  }
  hasVertex(v) { return this.adj.has(v); }
  hasEdge(u, v) { return this.adj.get(u)?.has(v) ?? false; }

  // ---- accessors ----
  vertices() { return [...this.adj.keys()]; }
  vertexCount() { return this.adj.size; }
  edgeCount() {
    let n = 0;
    for (const [, m] of this.adj) n += m.size;
    return this.directed ? n : n / 2;
  }
  neighbors(v) {
    const m = this.adj.get(v);
    if (!m) return [];
    return [...m].map(([to, weight]) => ({ to, weight }));
  }
  degree(v) { return this.adj.get(v)?.size ?? 0; }
  inDegree(v) {
    if (!this.directed) return this.degree(v);
    let d = 0;
    for (const [, m] of this.adj) if (m.has(v)) d++;
    return d;
  }

  toString() {
    const lines = [];
    for (const [u, m] of this.adj) {
      const es = [...m].map(([v, w]) => this.weighted ? `${v}(${w})` : String(v)).join(', ');
      lines.push(`${u} -> [${es}]`);
    }
    return lines.join('\n');
  }

  // ---- traversals ----
  bfs(start, visit = () => {}) {
    if (!this.adj.has(start)) return [];
    const visited = new Set([start]);
    const q = [start];
    const order = [];
    while (q.length) {
      const u = q.shift();
      order.push(u);
      visit(u);
      for (const { to } of this.neighbors(u)) {
        if (!visited.has(to)) { visited.add(to); q.push(to); }
      }
    }
    return order;
  }
  bfsAll(visit = () => {}) {
    const visited = new Set();
    const order = [];
    for (const v of this.adj.keys()) {
      if (!visited.has(v)) {
        // BFS from v, tracking visited globally
        const q = [v];
        visited.add(v);
        while (q.length) {
          const u = q.shift();
          order.push(u); visit(u);
          for (const { to } of this.neighbors(u)) {
            if (!visited.has(to)) { visited.add(to); q.push(to); }
          }
        }
      }
    }
    return order;
  }
  dfs(start, visit = () => {}) {
    if (!this.adj.has(start)) return [];
    const visited = new Set();
    const order = [];
    const rec = (u) => {
      if (visited.has(u)) return;
      visited.add(u);
      order.push(u); visit(u);
      for (const { to } of this.neighbors(u)) rec(to);
    };
    rec(start);
    return order;
  }
  dfsAll(visit = () => {}) {
    const visited = new Set();
    const order = [];
    const rec = (u) => {
      if (visited.has(u)) return;
      visited.add(u);
      order.push(u); visit(u);
      for (const { to } of this.neighbors(u)) rec(to);
    };
    for (const v of this.adj.keys()) if (!visited.has(v)) rec(v);
    return order;
  }
  dfsIterative(start, visit = () => {}) {
    if (!this.adj.has(start)) return [];
    const visited = new Set();
    const stack = [start];
    const order = [];
    while (stack.length) {
      const u = stack.pop();
      if (visited.has(u)) continue;
      visited.add(u);
      order.push(u); visit(u);
      // reverse so neighbors are processed in natural order
      for (const { to } of this.neighbors(u).slice().reverse()) {
        if (!visited.has(to)) stack.push(to);
      }
    }
    return order;
  }

  // ---- shortest paths ----
  shortestPath(start, target) { // unweighted BFS
    if (!this.adj.has(start) || !this.adj.has(target)) return null;
    const prev = new Map([[start, null]]);
    const q = [start];
    while (q.length) {
      const u = q.shift();
      if (u === target) break;
      for (const { to } of this.neighbors(u)) {
        if (!prev.has(to)) { prev.set(to, u); q.push(to); }
      }
    }
    if (!prev.has(target)) return null;
    const path = [];
    for (let cur = target; cur !== null; cur = prev.get(cur)) path.unshift(cur);
    return { distance: path.length - 1, path };
  }

  dijkstra(start) {
    if (!this.adj.has(start)) return null;
    const dist = new Map();
    const prev = new Map();
    for (const v of this.adj.keys()) dist.set(v, Infinity);
    dist.set(start, 0);
    const pq = new MinHeap();
    pq.push({ node: start, d: 0 });
    const done = new Set();
    while (!pq.isEmpty()) {
      const { node: u, d } = pq.pop();
      if (done.has(u)) continue;
      done.add(u);
      if (d > dist.get(u)) continue;
      for (const { to, weight } of this.neighbors(u)) {
        const nd = d + weight;
        if (nd < dist.get(to)) {
          dist.set(to, nd);
          prev.set(to, u);
          pq.push({ node: to, d: nd });
        }
      }
    }
    return { dist, prev };
  }

  dijkstraPath(start, target) {
    const r = this.dijkstra(start);
    if (!r || r.dist.get(target) === Infinity) return null;
    const path = [];
    for (let cur = target; cur !== undefined; cur = r.prev.get(cur)) {
      path.unshift(cur);
      if (cur === start) break;
    }
    return { distance: r.dist.get(target), path };
  }

  bellmanFord(start) {
    if (!this.adj.has(start)) return null;
    const dist = new Map();
    const prev = new Map();
    for (const v of this.adj.keys()) dist.set(v, Infinity);
    dist.set(start, 0);
    const edges = [];
    for (const [u, m] of this.adj) for (const [v, w] of m) edges.push([u, v, w]);
    const V = this.adj.size;
    for (let i = 0; i < V - 1; i++) {
      let relaxed = false;
      for (const [u, v, w] of edges) {
        if (dist.get(u) !== Infinity && dist.get(u) + w < dist.get(v)) {
          dist.set(v, dist.get(u) + w);
          prev.set(v, u);
          relaxed = true;
        }
      }
      if (!relaxed) break;
    }
    for (const [u, v, w] of edges) {
      if (dist.get(u) !== Infinity && dist.get(u) + w < dist.get(v)) {
        return { negativeCycle: true };
      }
    }
    return { dist, prev };
  }

  floydWarshall() {
    const V = [...this.adj.keys()];
    const idx = new Map(V.map((v, i) => [v, i]));
    const n = V.length;
    const INF = Infinity;
    const D = Array.from({ length: n }, () => Array(n).fill(INF));
    for (let i = 0; i < n; i++) D[i][i] = 0;
    for (const [u, m] of this.adj) for (const [v, w] of m) {
      const i = idx.get(u), j = idx.get(v);
      if (w < D[i][j]) D[i][j] = w;
    }
    for (let k = 0; k < n; k++)
      for (let i = 0; i < n; i++) {
        if (D[i][k] === INF) continue;
        for (let j = 0; j < n; j++) {
          if (D[k][j] === INF) continue;
          if (D[i][k] + D[k][j] < D[i][j]) D[i][j] = D[i][k] + D[k][j];
        }
      }
    return { vertices: V, dist: D, index: idx };
  }

  // ---- topological sort (directed) ----
  topologicalSort() {
    if (!this.directed) throw new Error('topological sort requires a directed graph');
    const inDeg = new Map();
    for (const v of this.adj.keys()) inDeg.set(v, 0);
    for (const [, m] of this.adj) for (const v of m.keys()) inDeg.set(v, inDeg.get(v) + 1);
    const q = [];
    for (const [v, d] of inDeg) if (d === 0) q.push(v);
    const order = [];
    while (q.length) {
      const u = q.shift();
      order.push(u);
      for (const { to } of this.neighbors(u)) {
        inDeg.set(to, inDeg.get(to) - 1);
        if (inDeg.get(to) === 0) q.push(to);
      }
    }
    return order.length === this.adj.size ? order : null; // null => cycle
  }

  // ---- cycle detection ----
  hasCycle() {
    if (this.directed) {
      const color = new Map(); // 0 white, 1 gray, 2 black
      for (const v of this.adj.keys()) color.set(v, 0);
      let found = false;
      const dfs = (u) => {
        color.set(u, 1);
        for (const { to } of this.neighbors(u)) {
          if (color.get(to) === 0) { if (dfs(to)) return true; }
          else if (color.get(to) === 1) { found = true; return true; }
        }
        color.set(u, 2);
        return false;
      };
      for (const v of this.adj.keys()) if (color.get(v) === 0 && dfs(v)) return true;
      return found;
    }
    // undirected
    const visited = new Set();
    const dfs = (u, parent) => {
      visited.add(u);
      for (const { to } of this.neighbors(u)) {
        if (!visited.has(to)) { if (dfs(to, u)) return true; }
        else if (to !== parent) return true;
      }
      return false;
    };
    for (const v of this.adj.keys()) if (!visited.has(v) && dfs(v, null)) return true;
    return false;
  }

  // ---- components ----
  connectedComponents() {
    const visited = new Set();
    const comps = [];
    for (const v of this.adj.keys()) {
      if (visited.has(v)) continue;
      const comp = [];
      const stack = [v];
      visited.add(v);
      while (stack.length) {
        const u = stack.pop();
        comp.push(u);
        for (const { to } of this.neighbors(u)) {
          if (!visited.has(to)) { visited.add(to); stack.push(to); }
        }
      }
      comps.push(comp);
    }
    return comps;
  }

  stronglyConnected() { // Kosaraju
    if (!this.directed) return this.connectedComponents();
    const visited = new Set();
    const order = [];
    const dfs1 = (u) => {
      visited.add(u);
      for (const { to } of this.neighbors(u)) if (!visited.has(to)) dfs1(to);
      order.push(u);
    };
    for (const v of this.adj.keys()) if (!visited.has(v)) dfs1(v);

    const radj = new Map();
    for (const v of this.adj.keys()) radj.set(v, []);
    for (const [u, m] of this.adj) for (const v of m.keys()) radj.get(v).push(u);

    const compOf = new Map();
    const visited2 = new Set();
    const dfs2 = (u, label) => {
      visited2.add(u);
      compOf.set(u, label);
      for (const p of radj.get(u)) if (!visited2.has(p)) dfs2(p, label);
    };
    let label = 0;
    for (let i = order.length - 1; i >= 0; i--) {
      const v = order[i];
      if (!visited2.has(v)) dfs2(v, label++);
    }
    const groups = Array.from({ length: label }, () => []);
    for (const [v, c] of compOf) groups[c].push(v);
    return groups;
  }

  // ---- MST (undirected) ----
  prim(start = [...this.adj.keys()][0]) {
    if (this.directed) throw new Error('Prim requires an undirected graph');
    if (this.adj.size === 0) return { total: 0, edges: [] };
    const inMST = new Set();
    const key = new Map();
    const parent = new Map();
    for (const v of this.adj.keys()) key.set(v, Infinity);
    key.set(start, 0);
    const pq = new MinHeap();
    pq.push({ node: start, d: 0 });
    let total = 0;
    const edges = [];
    while (!pq.isEmpty()) {
      const { node: u } = pq.pop();
      if (inMST.has(u)) continue;
      inMST.add(u);
      total += key.get(u);
      if (parent.has(u)) edges.push([parent.get(u), u, key.get(u)]);
      for (const { to, weight } of this.neighbors(u)) {
        if (!inMST.has(to) && weight < key.get(to)) {
          key.set(to, weight);
          parent.set(to, u);
          pq.push({ node: to, d: weight });
        }
      }
    }
    return { total, edges };
  }

  kruskal() {
    if (this.directed) throw new Error('Kruskal requires an undirected graph');
    // collect each undirected edge once
    const seen = new Set();
    const edges = [];
    for (const [u, m] of this.adj) for (const [v, w] of m) {
      const rkey = `${v}->${u}`;
      if (seen.has(rkey)) continue;
      seen.add(`${u}->${v}`);
      edges.push({ u, v, w });
    }
    edges.sort((a, b) => a.w - b.w);
    const dsu = new DSU(this.vertices());
    const chosen = [];
    let total = 0;
    for (const e of edges) {
      if (dsu.union(e.u, e.v)) { chosen.push([e.u, e.v, e.w]); total += e.w; }
    }
    return { total, edges: chosen };
  }

  transpose() {
    if (!this.directed) throw new Error('transpose requires a directed graph');
    const g = new Graph({ directed: true, weighted: this.weighted });
    for (const v of this.adj.keys()) g.addVertex(v);
    for (const [u, m] of this.adj) for (const [v, w] of m) g.addEdge(v, u, w);
    return g;
  }
}

