## Implementation 2: Fractional Knapsack (best ratio first)

```js
/**
 * Greedy: Fractional Knapsack
 * Can take fractions of items. Maximize value within capacity.
 * Strategy: sort by value/weight descending, fill capacity greedily.
 *
 * @param {Array<{value:number, weight:number}>} items
 * @param {number} capacity
 * @returns {number} maximum value
 */
function fractionalKnapsack(items, capacity) {
  if (!items || items.length === 0 || capacity <= 0) return 0;

  // Sort by value-per-weight ratio (greedy key) descending.
  const sorted = [...items].sort(
    (a, b) => b.value / b.weight - a.value / a.weight
  );

  let remaining = capacity;
  let totalValue = 0;

  for (const it of sorted) {
    if (remaining <= 0) break;
    // Take as much as we can of this (best ratio) item.
    const take = Math.min(it.weight, remaining);
    totalValue += take * (it.value / it.weight);
    remaining -= take;
  }
  return totalValue;
}

// --- demo ---
const items = [
  { value: 60, weight: 10 }, // ratio 6
  { value: 100, weight: 20 }, // ratio 5
  { value: 120, weight: 30 }, // ratio 4
];
console.log(fractionalKnapsack(items, 50)); // 240.0
```

