### Key takeaways

- **HOFs return functions**, letting you configure behavior (`addTax(0.08)`) and compose small units (`pipe`/`compose`).
- **Closures** capture configuration (`predicate`, `rate`) without global state.
- **`memoize`/`curry` are themselves HOFs** — they transform functions into enhanced functions.
- Prefer **`pipe`** for readability in data pipelines (left-to-right matches reading order); use **`compose`** when porting math-style right-to-left code.
- Always ensure memoized functions are **pure**; impure ones (using `Date.now`, random, I/O) will return stale results.

## Higher-Order Functions (HOFs) in JavaScript

A **higher-order function** is any function that does at least one of:

1. **Takes one or more functions as arguments** (callbacks), or  
2. **Returns a function** as its result.

This is possible because JavaScript treats functions as **first-class values**—they can be stored in variables, passed around, and returned just like numbers or objects.

### Common examples you already use

- `Array.prototype.map`, `filter`, `reduce`, `forEach` – take a callback.
- `setTimeout(fn, ms)` – takes a callback.
- Event listeners `el.addEventListener('click', handler)` – takes a handler.
- `Function.prototype.bind` – returns a new function.
- React `useEffect(callback, deps)` – callback + cleanup function.

### Why they matter

- **Abstraction**: describe *what* to do, not *how* to loop.
- **Reuse**: write generic algorithms (sort, retry, memoize) once.
- **Composition**: build complex behavior from small, testable pieces.

---

## Implementing the “core” from scratch

Below is a small, dependency-free module that reimplements the most common HOFs. Each function is written to mirror the native API (callback receives `(value, index, collection)`), with comments explaining the design.

```js
// hof.js — core higher-order function utilities

/**
 * map: transform every element, returning a NEW array.
 * @param {Array} arr
 * @param {(value:any, index:number, arr:Array) => any} fn
 * @returns {Array}
 */
function map(arr, fn) {
  const out = [];
  for (let i = 0; i < arr.length; i++) {
    // Only visit own enumerable indices (sparse arrays handled like native map)
    if (Object.prototype.hasOwnProperty.call(arr, i)) {
      out[i] = fn(arr[i], i, arr);
    }
  }
  return out;
}

/**
 * filter: keep elements where predicate returns truthy.
 */
function filter(arr, predicate) {
  const out = [];
  for (let i = 0; i < arr.length; i++) {
    if (Object.prototype.hasOwnProperty.call(arr, i) && predicate(arr[i], i, arr)) {
      out.push(arr[i]);
    }
  }
  return out;
}

/**
 * reduce: fold array into a single value.
 * If no initialValue is given, first element becomes accumulator.
 */
function reduce(arr, reducer, initialValue) {
  let acc;
  let start = 0;

  if (arguments.length < 3) {
    if (arr.length === 0) throw new TypeError('Reduce of empty array with no initial value');
    acc = arr[0];
    start = 1;
  } else {
    acc = initialValue;
  }

  for (let i = start; i < arr.length; i++) {
    if (Object.prototype.hasOwnProperty.call(arr, i)) {
      acc = reducer(acc, arr[i], i, arr);
    }
  }
  return acc;
}

/**
 * forEach: side-effecting iteration (returns undefined).
 */
function forEach(arr, fn) {
  for (let i = 0; i < arr.length; i++) {
    if (Object.prototype.hasOwnProperty.call(arr, i)) {
      fn(arr[i], i, arr);
    }
  }
}

/**
 * compose: right-to-left function composition.
 * compose(f, g)(x) === f(g(x))
 */
function compose(...fns) {
  return (x) => fns.reduceRight((acc, fn) => fn(acc), x);
}

/**
 * pipe: left-to-right composition (often more readable).
 * pipe(f, g)(x) === g(f(x))
 */
function pipe(...fns) {
  return (x) => fns.reduce((acc, fn) => fn(acc), x);
}

/**
 * curry: transform f(a,b,c) into f(a)(b)(c).
 * Works for fixed-arity functions.
 */
function curry(fn) {
  return function curried(...args) {
    if (args.length >= fn.length) {
      return fn.apply(this, args);
    }
    return (...more) => curried.apply(this, args.concat(more));
  };
}

/**
 * memoize: cache results by serialized arguments.
 * Great for pure, expensive functions.
 */
function memoize(fn) {
  const cache = new Map();
  return function (...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

module.exports = { map, filter, reduce, forEach, compose, pipe, curry, memoize };
```

### Quick sanity checks (interview-style tests)

```js
const { map, filter, reduce, compose, pipe, curry, memoize } = require('./hof');

// map
console.log(map([1, 2, 3], x => x * 2)); // [2, 4, 6]

// filter
console.log(filter([1, 2, 3, 4], x => x % 2 === 0)); // [2, 4]

// reduce (sum)
console.log(reduce([1, 2, 3, 4], (a, b) => a + b, 0)); // 10

// compose: add1 then double
const add1 = x => x + 1;
const double = x => x * 2;
console.log(compose(double, add1)(5)); // 12  (double(add1(5)))

// pipe: same but left-to-right
console.log(pipe(add1, double)(5)); // 12

// curry
const add = (a, b, c) => a + b + c;
const curriedAdd = curry(add);
console.log(curriedAdd(1)(2)(3)); // 6
console.log(curriedAdd(1, 2)(3)); // 6

// memoize
let calls = 0;
const slowSquare = memoize((n) => { calls++; return n * n; });
console.log(slowSquare(4), slowSquare(4), calls); // 16 16 1
```

### Interview talking points

- **Native vs. custom**: In production you’d use `Array.prototype.map` etc.; reimplementing proves you understand iteration, callback contracts, and immutability.
- **Purity**: HOFs shine with pure functions (no side effects). `memoize` assumes purity; otherwise caching is unsafe.
- **Arity & `this`**: We use `fn.apply(this, args)` so methods can be partially applied or bound correctly.
- **Edge cases handled**: empty arrays in `reduce`, sparse arrays, optional initial value, fixed-arity currying.
- **Performance**: For huge arrays, native C++ implementations beat JS loops; these are for clarity/learning.

If you want, I can extend this with `flatMap`, `some`/`every`, or an async HOF like `retry(fn, attempts)`.

# Edge Cases When Using Higher-Order Functions in JavaScript

Below are the most important edge cases, grouped by theme, with runnable examples and fixes.

---

## 1. `this` is lost when passing a method as a callback

Array methods invoke the callback as a plain function, so `this` becomes `undefined` (strict mode) or the global object.

```js
const obj = {
  factor: 2,
  scale(arr) {
    return arr.map(this.double); // ❌ 'this' is undefined inside double
  },
  double(x) {
    return x * this.factor;
  }
};

// Fixes:
obj.scale = function (arr) {
  return arr.map(x => this.double(x));          // arrow keeps lexical 'this'
  // or: return arr.map(this.double.bind(this));
  // or: return arr.map(this.double, this);     // thisArg parameter
};
```

**Note:** `thisArg` is ignored by arrow functions.

---

## 2. Mutating the array while iterating

Index bookkeeping breaks; elements get skipped or visited twice.

```js
const a = [1, 2, 3, 4, 5];
a.forEach((x, i, arr) => {
  if (x % 2 === 0) arr.splice(i, 1); // ❌ mutates during traversal
});
console.log(a); // [1, 3, 4, 5]  (4 was skipped)

// Fix: build a new array instead of mutating in place
const odds = a.filter(x => x % 2 !== 0);
```

`forEach`/`map`/`filter` capture the **initial length**; pushing beyond it during iteration won't be visited, but splicing shifts indices.

---

## 3. Sparse arrays (holes)

Holes are treated inconsistently across methods.

```js
const a = [1, , 3]; // hole at index 1

a.map(x => x * 2);        // [2, <1 empty item>, 6]  (hole preserved)
a.filter(() => true);     // [1, 3]                  (hole dropped)
a.forEach(x => console.log(x)); // logs 1, 3 (hole skipped)
a.reduce((s, x) => s + x, 0); // 4 (hole skipped)
[3, , 1].sort();          // [1, 3, <1 empty item>] (holes moved to end)
```

If you need holes to count, normalize first: `Array.from(a)` or `[...a]` (both convert holes to `undefined`).

---

## 4. `reduce` with no initial value

```js
[].reduce((a, b) => a + b);        // ❌ TypeError: Reduce of empty array with no initial value
[42].reduce((a, b) => a + b);     // 42 (callback never called)
[1, 2, 3].reduce((a, b) => a + b); // 6

// Always provide an initial value for robustness:
const sum = arr.reduce((s, x) => s + x, 0);

// Object accumulation: don't mutate a shared default
const grouped = items.reduce((acc, x) => {
  (acc[x.type] ??= []).push(x);
  return acc;
}, {});
```

---

## 5. `sort` comparator contract

The comparator **must return a number**, not a boolean, and must be consistent/transitive.

```js
[10, 2, 1].sort((a, b) => a > b);   // ❌ returns boolean → wrong order
[10, 2, 1].sort((a, b) => a - b);   // ✅ [1, 2, 10]

// NaN breaks ordering
[3, 1, 2].sort((a, b) => a - b);    // fine
[3, NaN, 1].sort((a, b) => a - b);  // ❌ NaN comparator → unstable/implementation-defined

// Inconsistent comparator → undefined behavior
[1, 2, 3].sort((a, b) => Math.random() - 0.5); // ❌ non-deterministic

// Always coerce to number and handle NaN:
const safeCmp = (a, b) => {
  if (Number.isNaN(a)) return 1;
  if (Number.isNaN(b)) return -1;
  return a - b;
};
```

Also remember: `sort()` mutates in place and converts elements to strings by default (`[10,2,1].sort()` → `["1","10","2"]`).

---

## 6. Extra arguments passed to the callback

Array methods pass `(value, index, array)`. A common trap:

```js
['1', '2', '3'].map(parseInt);        // [1, NaN, NaN]
// parseInt('2', 1)  → NaN (radix 1 invalid)
// parseInt('3', 2)  → NaN

// Fix: wrap to control arity
['1', '2', '3'].map(x => parseInt(x, 10)); // [1, 2, 3]
```

Same trap with `parseFloat`, `Number`, etc. when passed directly.

---

## 7. Async callbacks in synchronous HOFs

`forEach` does not await promises; errors become unhandled rejections.

```js
const urls = ['/a', '/b'];
urls.forEach(async (url) => {
  await fetch(url); // ❌ fire-and-forget; outer code continues immediately
});

// Fixes:
await Promise.all(urls.map(url => fetch(url)));            // parallel
for (const url of urls) await fetch(url);                 // sequential
```

`map` with an async callback returns `Promise[]`, not resolved values — you must `await Promise.all(...)`.

---

## 8. Closure over a loop variable (`var`)

```js
const fns = [];
for (var i = 0; i < 3; i++) {
  fns.push(() => i);
}
fns.map(f => f()); // [3, 3, 3]

// Fix: use let (block scope) or capture via IIFE/parameter
for (let i = 0; i < 3; i++) fns.push(() => i);
// or: arr.forEach((_, i) => fns.push(() => i));
```

---

## 9. Arrow functions as methods / constructors

Arrows have no own `this`, `arguments`, `super`, or `[[Construct]]`.

```js
function Person(name) { this.name = name; }
Person.prototype.greet = () => `hi ${this.name}`; // ❌ 'this' is outer scope

const p = new Person('Ada');
p.greet(); // "hi undefined"

// Also:
const Foo = () => {};
new Foo(); // ❌ TypeError: Foo is not a constructor

// Fix: use a regular function (or class method)
Person.prototype.greet = function () { return `hi ${this.name}`; };
```

---

## 10. Ignored vs. used return values

`forEach` always returns `undefined`; using its result is a bug.

```js
const doubled = arr.forEach(x => x * 2); // ❌ undefined
const doubled2 = arr.map(x => x * 2);    // ✅ new array

// filter/map callbacks must return a value; forgetting returns undefined → falsy
arr.filter(x => { x > 2; }); // ❌ all removed (undefined is falsy)
arr.filter(x => x > 2);      // ✅
```

---

## 11. Throwing inside callbacks

Exceptions propagate and abort iteration; partial results are lost.

```js
try {
  [1, 2, 3].map(x => {
    if (x === 2) throw new Error('boom');
    return x * 2;
  });
} catch (e) {
  // iteration stopped at index 1; no array returned
}

// If you want per-element error handling, catch inside:
const results = arr.map(x => {
  try { return transform(x); }
  catch (e) { return { error: e.message }; }
});
```

---

## 12. Iterating objects: inherited / non-enumerable properties

`for...in` walks the prototype chain; `Object.keys` does not.

```js
const base = { inherited: 1 };
const o = Object.create(base);
o.own = 2;

for (const k in o) console.log(k); // "own", "inherited" ❌
Object.keys(o);                    // ["own"] ✅
Object.entries(o);                 // [["own", 2]]

// When writing a HOF over an object, normalize:
function mapValues(obj, fn) {
  return Object.fromEntries(
    Object.entries(obj).map(([k, v]) => [k, fn(v, k)])
  );
}
```

Also beware of inherited `toString` etc. when using objects as dictionaries; prefer `Map`.

---

## 13. Function arity, defaults, and rest params

`.length` reflects only parameters before the first default/rest, which breaks naive currying.

```js
function f(a, b = 2, ...rest) {}
f.length; // 1  (not 3)

function curry(f) {
  return function curried(...args) {
    if (args.length >= f.length) return f(...args);
    return (...more) => curried(...args, ...more);
  };
}
curry(f)(1); // works, but f.length=1 means it calls f too early
```

For robust currying, use an explicit arity argument or inspect defaults.

---

## 14. Memoization and reference equality

Using a `Map` with object/array args keys by **reference**, not value.

```js
const cache = new Map();
function memoize(f) {
  return (...args) => {
    const key = args; // ❌ array identity, not contents
    if (cache.has(key)) return cache.get(key);
    const r = f(...args);
    cache.set(key, r);
    return r;
  };
}
memoize(x => x)( {a:1} ); // miss every call with a new object

// Better: serialize primitives, or use WeakMap for single object arg
function memoizeObj(f) {
  const cache = new WeakMap();
  return (obj) => {
    if (cache.has(obj)) return cache.get(obj);
    const r = f(obj);
    cache.set(obj, r);
    return r;
  };
}
```

---

## 15. Returning functions and `new` / binding

A factory returning a function can be misused with `new` or `.bind`.

```js
function makeAdder(n) {
  return function (x) { return x + n; };
}
const add5 = makeAdder(5);
new add5(10); // ❌ TypeError: add5 is not a constructor (non-arrow is constructible though!)
// Actually regular functions ARE constructible; `new` creates an object whose
// prototype is add5.prototype, and returns it (ignoring the numeric return).
// Use arrow or explicit guard if construction is invalid:
const add5b = (x) => x + 5;
// new add5b(10); // ❌ TypeError (arrow not constructible) — safer
```

Also, binding a returned function: `makeAdder(5).bind(null, 10)` works but changes arity expectations.

---

## 16. Generator / async functions passed where sync is expected

```js
function runAll(fns) { return fns.map(f => f()); }

runAll([function* () { yield 1; }]); // returns [generator object] (truthy, not value)
runAll([async () => 42]);           // returns [Promise] — not awaited

// If the HOF should support async, make it async-aware:
async function runAllAsync(fns) {
  return Promise.all(fns.map(f => f()));
}
```

---

## 17. `arguments` in arrow functions

Arrows don't have their own `arguments`; they close over the enclosing function's.

```js
function outer() {
  const inner = () => arguments[0]; // refers to outer's arguments
  return inner();
}
outer(7); // 7  (surprising if you expected inner's)

// Fix: use rest params in arrows
const inner = (...args) => args[0];
```

---

## 18. Sort mutates the original

```js
const data = [3, 1, 2];
const sorted = data.sort((a, b) => a - b);
console.log(data);   // [1, 2, 3]  (mutated!)
console.log(sorted === data); // true

// Fix: copy first
const sortedCopy = [...data].sort((a, b) => a - b);
```

---

## 19. Modifying length during iteration (advanced)

```js
const a = [1, 2, 3, 4];
a.forEach((x, i) => {
  if (i === 0) a.length = 2; // truncates
});
// Only index 0 processed (length was 4 at start? forEach fixes len=4 at start,
// but splice/truncate can skip). Behavior is subtle — avoid mutation.
```

---

## 20. Pure vs. impure callbacks in `reduce` / `sort`

Relying on external mutable state inside a comparator or reducer makes results order-dependent and hard to debug.

```js
let counter = 0;
[1, 2, 3].reduce((acc, x) => {
  counter++;
  return acc + x + counter; // ❌ result depends on call order & external state
}, 0);
```

Keep callbacks **pure**: output depends only on inputs.

---

### Quick checklist

| Pitfall | Safe practice |
|---|---|
| `this` loss | Arrow function, `.bind`, or `thisArg` |
| Mutation during iteration | Return new arrays; use `filter`/`map` |
| Sparse holes | Normalize with `Array.from`/spread |
| `reduce` empty | Always pass initial value |
| `sort` comparator | Return number; copy array first |
| `parseInt` as callback | Wrap: `x => parseInt(x, 10)` |
| Async in `forEach` | `Promise.all(arr.map(async...))` or `for...of` |
| Loop `var` | Use `let` or `forEach` |
| Object iteration | `Object.keys/entries`, not `for...in` |
| Memoization | Serialize keys or use `WeakMap` |
| Throwing | Catch inside callback if partial results needed |

These cover the vast majority of real-world bugs seen with higher-order functions in JavaScript.

Here is a complete, runnable Node.js example that implements immutability in several practical ways:

1. **Deep freeze** for plain objects/arrays/Maps/Sets.
2. **Copy-on-write update helpers** that return new values instead of mutating.
3. **Persistent immutable collections** (`ImmutableArray`, `ImmutableMap`) with structural-ish copy-on-write behavior.
4. **Read-only proxy views** that throw on mutation attempts.

Save as `immutability.js` and run with `node immutability.js`.

```js
'use strict';

const assert = require('assert');

/* -------------------------------------------------------------------------- */
/* 1. Deep freeze                                                             */
/* -------------------------------------------------------------------------- */

function deepFreeze(value, seen = new WeakSet()) {
  if (value === null || typeof value !== 'object') return value;
  if (seen.has(value)) return value;
  seen.add(value);

  if (Array.isArray(value)) {
    value.forEach((item, index) => {
      value[index] = deepFreeze(item, seen);
    });
  } else if (value instanceof Map) {
    for (const [k, v] of [...value.entries()]) {
      value.delete(k);
      value.set(deepFreeze(k, seen), deepFreeze(v, seen));
    }
  } else if (value instanceof Set) {
    for (const v of [...value]) {
      value.delete(v);
      value.add(deepFreeze(v, seen));
    }
  } else if (!(value instanceof Date) && !(value instanceof RegExp)) {
    for (const key of Reflect.ownKeys(value)) {
      value[key] = deepFreeze(value[key], seen);
    }
  }

  Object.freeze(value);
  return value;
}

/* -------------------------------------------------------------------------- */
/* 2. Immutable update helpers for plain objects and arrays                   */
/* -------------------------------------------------------------------------- */

function toPath(path) {
  return Array.isArray(path) ? path : String(path).split('.').filter(Boolean);
}

function cloneContainer(value) {
  return Array.isArray(value) ? value.slice() : { ...value };
}

function setAtPath(root, path, value) {
  if (path.length === 0) return value;
  const [head, ...rest] = path;

  const clone = cloneContainer(root == null ? (Number.isInteger(head) ? [] : {}) : root);
  clone[head] = setAtPath(root == null ? undefined : root[head], rest, value);
  return clone;
}

function immutableSet(root, path, value) {
  const clonedValue =
    value !== null && typeof value === 'object'
      ? structuredClone(value)
      : value;

  return deepFreeze(setAtPath(root, toPath(path), clonedValue));
}

function merge(target, source) {
  const result = { ...target };

  for (const [key, value] of Object.entries(source)) {
    if (
      value !== null &&
      typeof value === 'object' &&
      !Array.isArray(value) &&
      result[key] !== null &&
      typeof result[key] === 'object' &&
      !Array.isArray(result[key])
    ) {
      result[key] = merge(result[key], value);
    } else if (value !== null && typeof value === 'object') {
      result[key] = structuredClone(value);
    } else {
      result[key] = value;
    }
  }

  return deepFreeze(result);
}

/* -------------------------------------------------------------------------- */
/* 3. Persistent immutable collections                                        */
/* -------------------------------------------------------------------------- */

class ImmutableArray {
  constructor(items = []) {
    this._items = Object.freeze(items.map(deepFreeze));
    Object.freeze(this);
  }

  get length() {
    return this._items.length;
  }

  get(index) {
    return this._items[index];
  }

  push(value) {
    return new ImmutableArray([...this._items, value]);
  }

  set(index, value) {
    if (index < 0 || index >= this._items.length) {
      throw new RangeError('Index out of bounds');
    }
    const next = [...this._items];
    next[index] = value;
    return new ImmutableArray(next);
  }

  map(fn) {
    return new ImmutableArray(this._items.map((value, index) => fn(value, index)));
  }

  toArray() {
    return [...this._items];
  }

  [Symbol.iterator]() {
    return this._items[Symbol.iterator]();
  }
}

class ImmutableMap {
  constructor(source = new Map()) {
    this._map = new Map(source);
    for (const [key, value] of this._map) {
      this._map.set(key, deepFreeze(value));
    }
    Object.freeze(this);
  }

  get size() {
    return this._map.size;
  }

  get(key) {
    return this._map.get(key);
  }

  has(key) {
    return this._map.has(key);
  }

  set(key, value) {
    const next = new Map(this._map);
    next.set(key, deepFreeze(value));
    return new ImmutableMap(next);
  }

  delete(key) {
    const next = new Map(this._map);
    next.delete(key);
    return new ImmutableMap(next);
  }

  keys() {
    return [...this._map.keys()];
  }

  entries() {
    return [...this._map.entries()];
  }

  toMap() {
    return new Map(this._map);
  }
}

/* -------------------------------------------------------------------------- */
/* 4. Read-only proxy view                                                    */
/* -------------------------------------------------------------------------- */

function asReadOnly(value, seen = new WeakMap()) {
  if (value === null || typeof value !== 'object') return value;
  if (seen.has(value)) return seen.get(value);

  // Leave exotic objects frozen rather than proxied awkwardly.
  if (
    value instanceof Date ||
    value instanceof RegExp ||
    value instanceof Map ||
    value instanceof Set
  ) {
    return deepFreeze(value);
  }

  const proxy = new Proxy(value, {
    get(target, prop, receiver) {
      return asReadOnly(Reflect.get(target, prop, receiver), seen);
    },
    set() {
      throw new TypeError('Cannot mutate a read-only object');
    },
    deleteProperty() {
      throw new TypeError('Cannot delete a property from a read-only object');
    },
    defineProperty() {
      throw new TypeError('Cannot define a property on a read-only object');
    },
  });

  seen.set(value, proxy);
  return proxy;
}

/* -------------------------------------------------------------------------- */
/* Demo / tests                                                               */
/* -------------------------------------------------------------------------- */

function runDemo() {
  // Deep freeze
  const original = structuredClone({
    user: { name: 'Ada', scores: [10, 20] },
    created: new Date().toISOString(),
  });

  const frozen = deepFreeze(structuredClone(original));

  let threw = false;
  try {
    frozen.user.name = 'Grace';
  } catch (error) {
    threw = true;
  }
  assert(threw, 'deepFreeze should prevent property mutation');
  assert.deepStrictEqual(frozen, original);

  // Immutable path update
  const nested = { a: { b: 1, c: [1, 2] } };
  const updated = immutableSet(nested, 'a.b', 99);
  assert.strictEqual(nested.a.b, 1, 'original must remain unchanged');
  assert.strictEqual(updated.a.b, 99);
  assert.deepStrictEqual(updated.a.c, [1, 2]);

  // Merge
  const merged = merge(
    { person: { name: 'Ada', tags: ['math'] } },
    { person: { age: 36, tags: ['logic'] } }
  );
  assert.deepStrictEqual(merged.person, {
    name: 'Ada',
    age: 36,
    tags: ['logic'],
  });

  // ImmutableArray
  const arr = new ImmutableArray([1, 2, 3]);
  const arr2 = arr.push(4).set(0, 10);
  assert.deepStrictEqual(arr.toArray(), [1, 2, 3]);
  assert.deepStrictEqual(arr2.toArray(), [10, 2, 3, 4]);

  // ImmutableMap
  const map = new ImmutableMap([['x', 1]]);
  const map2 = map.set('y', 2);
  assert.strictEqual(map.size, 1);
  assert.strictEqual(map2.size, 2);
  assert.strictEqual(map.get('y'), undefined);
  assert.strictEqual(map2.get('y'), 2);

  // Read-only proxy
  const view = asReadOnly({ items: [1, 2, 3] });
  let viewThrew = false;
  try {
    view.items.push(999);
  } catch (error) {
    viewThrew = true;
  }
  assert(viewThrew, 'read-only proxy should reject array mutation');

  console.log('All immutability demo checks passed.');
}

runDemo();
```

### Key ideas demonstrated

- **Immutability is not just “no mutation”** — updates must produce new values while leaving the original intact.
- `Object.freeze()` is shallow, so a real implementation needs recursion.
- `Map` and `Set` are special because freezing the object does not prevent `.set()` or `.add()`; persistent wrappers solve that cleanly.
- For everyday state updates, **path-based immutable updates** and **deep merge** are usually more useful than manually cloning objects.
- A `Proxy` can provide a convenient read-only view, but it has overhead and edge cases with exotic objects such as `Date`. For true correctness, persistent immutable collections are preferable.

```js
// ❌ Mistake: mutating the original array while "updating" state
const items = [1, 2, 3];

function addItem(items, newItem) {
  items.push(newItem);   // mutates the original array
  return items;          // returns same reference
}

const updated = addItem(items, 4);

console.log(items);   // [1, 2, 3, 4]  (original was changed!)
console.log(updated === items); // true
```

**What went wrong**

- `Array.prototype.push` mutates the array in place.
- Returning the same reference means callers cannot distinguish “before” from “after.”
- In UI frameworks (React, Vue, Redux, etc.), change detection often relies on reference equality, so the mutation may not trigger a re-render or may cause subtle stale-state bugs.

**Corrected version**

```js
// ✅ Create a new array; leave the original untouched
function addItem(items, newItem) {
  return [...items, newItem]; // or items.concat(newItem)
}

const items = [1, 2, 3];
const updated = addItem(items, 4);

console.log(items);   // [1, 2, 3]  (unchanged)
console.log(updated); // [1, 2, 3, 4]
console.log(updated === items); // false
```

**Why this is better**

- **Predictability**: the input `items` is never modified, so callers can safely reuse it.
- **Referential integrity**: a new array reference signals that state changed, which frameworks and memoization logic rely on.
- **Debugging**: time-travel debugging and immutability-based optimizations work correctly.

---

### A nested-object variant (common in React state updates)

```js
// ❌ Mistake
const user = { name: "Ada", profile: { age: 30 } };

function birthday(user) {
  user.profile.age += 1; // mutates nested object
  return user;
}

// ✅ Corrected
function birthday(user) {
  return {
    ...user,
    profile: {
      ...user.profile,
      age: user.profile.age + 1,
    },
  };
}
```

**Key takeaway:** immutability means creating **new** structures at every level that changes, not just shallow-copying the top level. If you mutate a nested object, the parent’s reference may still be “new,” but the shared nested reference is still mutated—so the bug survives. Spread operators (`...`) at each changed level, or use a library like Immer, to keep updates fully immutable.

# Common immutability pitfalls in JavaScript

Below are the most frequent mistakes, each with a “bad” example and a safer alternative.

## 1. Assuming `const` makes a value immutable

`const` only prevents reassigning the variable binding; the value itself can still be mutated.

```js
const user = { name: "Ada", roles: ["admin"] };

user.name = "Grace";          // ✅ allowed
user.roles.push("editor");     // ✅ allowed
// user = { name: "X" };      // ❌ TypeError: Assignment to constant variable
```

Safer:

```js
const user = Object.freeze({ name: "Ada", roles: Object.freeze(["admin"]) });
// or use Immer / a recursive freeze helper for deep immutability
```

---

## 2. Shallow copies still share nested references

Spread and `Object.assign` copy only the top level.

```js
const original = {
  profile: { name: "Ada" },
  tags: ["js"],
};

const copy = { ...original };

copy.profile.name = "Grace"; // mutates original.profile too
copy.tags.push("ts");        // mutates original.tags too

console.log(original.profile.name); // "Grace"
console.log(original.tags);         // ["js", "ts"]
```

Safer: clone nested values explicitly or use a deep-clone/immutable-update utility.

```js
const copy = {
  ...original,
  profile: { ...original.profile },
  tags: [...original.tags],
};
```

---

## 3. Mutating array methods

Methods such as `sort`, `reverse`, `splice`, `push`, `pop`, `shift`, `unshift`, `fill`, and `copyWithin` mutate the original array.

```js
const nums = [3, 1, 2];
const sorted = nums.sort(); // mutates nums

console.log(nums);   // [1, 2, 3]
console.log(sorted); // [1, 2, 3] (same array)
```

Safer: copy first, or use the non-mutating ES2023 methods.

```js
const sorted1 = [...nums].sort((a, b) => a - b);
const sorted2 = nums.toSorted((a, b) => a - b); // does not mutate nums
const reversed = nums.toReversed();
const spliced = nums.toSpliced(1, 1, 99);
```

---

## 4. `Object.freeze()` is shallow

Freezing an object does not freeze nested objects or arrays.

```js
const state = Object.freeze({
  user: { name: "Ada" },
  items: [1, 2],
});

state.user.name = "Grace"; // ✅ works
state.items.push(3);       // ✅ works
state.newKey = 4;          // ❌ TypeError in strict mode
```

Safer: recursive freeze, or better, use immutable update patterns / Immer.

```js
function deepFreeze(obj) {
  if (obj && typeof obj === "object") {
    Object.freeze(obj);
    Object.keys(obj).forEach((key) => deepFreeze(obj[key]));
  }
  return obj;
}
```

---

## 5. `JSON` deep cloning loses types and values

`JSON.parse(JSON.stringify(x))` is a common “quick deep clone,” but it is not general-purpose.

```js
const original = {
  created: new Date(),
  action: () => "hi",
  missing: undefined,
  count: NaN,
  map: new Map([["a", 1]]),
};

const clone = JSON.parse(JSON.stringify(original));

console.log(clone.created); // string, not Date
console.log(clone.action);  // undefined
console.log(clone.missing); // undefined (key removed)
console.log(clone.count);   // null
console.log(clone.map);     // {}
```

Safer: use `structuredClone` where supported, or a library, depending on the data.

```js
const clone = structuredClone(original);
// structuredClone handles Date, Map, Set, ArrayBuffer, etc.
// but it cannot clone functions, DOM nodes, or class instances with methods
```

---

## 6. Mutating React state directly

React compares state by reference. Mutating the existing object/array often prevents re-rendering.

```js
const [items, setItems] = useState([1, 2]);

function addItem(item) {
  items.push(item);   // mutates existing state
  setItems(items);     // same reference -> React may skip update
}
```

Safer: create a new reference.

```js
function addItem(item) {
  setItems((prev) => [...prev, item]);
}

// For objects:
setUser((prev) => ({ ...prev, name: "Grace" }));
```

---

## 7. Mutating Redux/state-store state in reducers

Reducers must be pure. Mutating state breaks time-travel, change detection, and memoized selectors.

```js
function reducer(state, action) {
  if (action.type === "INCREMENT") {
    state.count += 1; // mutates input state
    return state;      // same reference
  }
  return state;
}
```

Safer:

```js
function reducer(state, action) {
  if (action.type === "INCREMENT") {
    return { ...state, count: state.count + 1 };
  }
  return state;
}
```

---

## 8. `Object.assign` mutates its first argument

This is easy to miss when “merging” objects.

```js
const base = { a: 1 };
const merged = Object.assign(base, { b: 2 });

console.log(base);   // { a: 1, b: 2 }  (base was mutated)
console.log(merged); // { a: 1, b: 2 }  (same object as base)
```

Safer: pass an empty object as the target.

```js
const merged = Object.assign({}, base, { b: 2 });
// or
const merged2 = { ...base, b: 2 };
```

---

## 9. Map and Set values are mutable references

Reading a value from a `Map` gives you the stored reference; mutating it mutates the collection’s data.

```js
const users = new Map([["ada", { role: "admin" }]]);

const ada = users.get("ada");
ada.role = "editor"; // mutates the object stored in the Map

console.log(users.get("ada").role); // "editor"
```

Safer: replace the entry with a new object.

```js
const ada = users.get("ada");
users.set("ada", { ...ada, role: "editor" });
```

---

## 10. Shared mutable default parameters

A default value defined outside a function can be accidentally shared and mutated.

```js
const defaultOptions = { retries: 3 };

function request(url, options = defaultOptions) {
  options.retries -= 1; // mutates shared default
  return options;
}

console.log(request("/a").retries); // 2
console.log(request("/b").retries); // 1
```

Safer: create defaults inside the function or clone them.

```js
function request(url, options = {}) {
  const opts = { retries: 3, ...options };
  opts.retries -= 1;
  return opts;
}
```

---

## 11. Immer: mutating the draft and returning a value

With Immer, a producer should either mutate the draft **or** return a new value, not both.

```js
import produce from "immer";

const next = produce(state, (draft) => {
  draft.count += 1;          // mutation
  return { count: 0 };       // replacement; draft mutation is ignored/confusing
});
```

Safer: choose one style.

```js
// Mutate draft, return nothing
const next1 = produce(state, (draft) => {
  draft.count += 1;
});

// Or return a new value, do not mutate draft
const next2 = produce(state, () => ({ count: 0 }));
```

---

## 12. Reference equality after “in-place” updates

If you mutate a nested value but keep the same top-level reference, equality checks may incorrectly say nothing changed.

```js
const prev = { a: { b: 1 } };
const next = prev;

next.a.b = 2;

console.log(prev === next); // true
console.log(prev.a.b);      // 2
// A memoized component/selector may not update because the reference did not change
```

Safer: create new references along the changed path.

```js
const next = {
  ...prev,
  a: { ...prev.a, b: 2 },
};

console.log(prev === next); // false
```

---

## 13. Mutating during render or in derived data

Sorting/reversing data while rendering can mutate props or cached values.

```js
function List({ items }) {
  const sorted = items.sort(); // mutates the prop array
  return sorted.map((x) => <li key={x}>{x}</li>);
}
```

Safer:

```js
function List({ items }) {
  const sorted = [...items].sort((a, b) => a - b);
  return sorted.map((x) => <li key={x}>{x}</li>);
}
```

---

## 14. Performance cost of repeated deep cloning

Deep cloning on every update is correct but can be expensive for large state trees.

```js
// Works, but clones the entire large object each time
setState((prev) => structuredClone({ ...prev, count: prev.count + 1 }));
```

Safer: update only the changed path, or use a library that provides structural sharing.

```js
// Path update
setState((prev) => ({
  ...prev,
  nested: { ...prev.nested, count: prev.nested.count + 1 },
}));

// Or use Immer for ergonomic structural sharing
```

---

### Practical checklist

- `const` protects bindings, not contents.
- Prefer spread at every changed level, not just the top level.
- Avoid mutating array methods; use `toSorted`, `toReversed`, `toSpliced`, or copy first.
- Treat `Object.freeze`, `Object.assign`, and `JSON` cloning as shallow or lossy.
- In React/Redux, always return new references for changed state.
- For complex state, use **Immer** or a purpose-built immutable library rather than hand-rolled deep clones.

## Exercise: Update a list of users immutably

You have this starting state:

```js
const users = [
  { id: 1, name: "Alice", email: "alice@old.com" },
  { id: 2, name: "Bob",   email: "bob@old.com" }
];
```

Do the following **without mutating `users` or any object inside it**:

1. Change Alice's email to `"alice@new.com"`.
2. Add a new user: `{ id: 3, name: "Charlie", email: "charlie@new.com" }`.
3. Remove Bob.

Return the new array. Also verify that `users` is unchanged.

---

## Step-by-step solution

### Step 1 — Understand what "mutating" means here

These are all mutations and should be avoided:

```js
users[0].email = "alice@new.com";   // mutates an object inside the array
users.push(charlie);                 // mutates the array
users.splice(1, 1);                  // mutates the array
```

Instead, create *new* arrays and *new* objects, copying only what you need.

### Step 2 — Update Alice's email with `map`

`Array.prototype.map` returns a new array. For the matching user, return a *new* object with the updated email; otherwise return the original object (which is fine because we aren't changing it).

```js
const withUpdatedEmail = users.map(user =>
  user.id === 1
    ? { ...user, email: "alice@new.com" }   // new object, shallow copy + override
    : user                                   // unchanged reference, no mutation
);
```

`{ ...user, email: ... }` creates a shallow copy of `user` and overwrites `email`. The original `user` object is untouched.

### Step 3 — Remove Bob with `filter`

`filter` also returns a new array and leaves the original alone.

```js
const withoutBob = withUpdatedEmail.filter(user => user.id !== 2);
```

### Step 4 — Add Charlie with spread (or `concat`)

```js
const charlie = { id: 3, name: "Charlie", email: "charlie@new.com" };

const result = [...withoutBob, charlie];
// or: const result = withoutBob.concat(charlie);
```

`[...withoutBob, charlie]` creates a brand-new array; `withoutBob` is unchanged.

### Step 5 — Combine into one pipeline

```js
const result = users
  .map(user =>
    user.id === 1
      ? { ...user, email: "alice@new.com" }
      : user
  )
  .filter(user => user.id !== 2)
  .concat({ id: 3, name: "Charlie", email: "charlie@new.com" });
```

### Step 6 — Verify immutability

```js
console.log("original:", JSON.stringify(users));
// original: [{"id":1,"name":"Alice","email":"alice@old.com"},{"id":2,"name":"Bob","email":"bob@old.com"}]

console.log("result:", JSON.stringify(result));
// result: [{"id":1,"name":"Alice","email":"alice@new.com"},{"id":3,"name":"Charlie","email":"charlie@new.com"}]

// Reference checks
console.log(users !== result);                 // true — new array
console.log(users[0] !== result[0]);            // true — Alice is a new object
console.log(users[1] === undefined);            // true — Bob removed, but original untouched
```

---

## Final, reusable solution

```js
function updateUsers(users) {
  return users
    .map(user =>
      user.id === 1
        ? { ...user, email: "alice@new.com" }
        : user
    )
    .filter(user => user.id !== 2)
    .concat({ id: 3, name: "Charlie", email: "charlie@new.com" });
}

const users = [
  { id: 1, name: "Alice", email: "alice@old.com" },
  { id: 2, name: "Bob",   email: "bob@old.com" }
];

const next = updateUsers(users);

// users is still exactly as before
console.log(users.length); // 2
```

### Important caveat: shallow vs. deep immutability

The spread `{ ...user }` is a **shallow** copy. If `user` had nested objects (e.g., `address: { city }`), those nested objects would still be shared references. For deeply nested updates you'd either spread at each level:

```js
{ ...user, address: { ...user.address, city: "NYC" } }
```

or use a helper like Immer (`produce`) for complex state. For flat records like these, shallow copying is enough and is the idiomatic approach.

## Immutability in JavaScript – Interview Answer

**Immutability** means that once a value is created, it can never be changed. Instead of mutating the original, you create a *new* value that reflects the desired change. In JS the built‑in primitives (strings, numbers, booleans, `null`, `undefined`, symbols, bigints) are already immutable; the challenge is **objects and arrays**, which are mutable by default.

### Why it matters
- **Predictability / debugging** – shared references can’t surprise you later.
- **Referential equality** – cheap change detection (`===`) powers React `PureComponent`, Redux, and memoization.
- **Time‑travel / undo** – keep previous states instead of patching in place.
- **Concurrency safety** – no accidental shared‑state races.

### Built‑in helpers
- `const` only blocks *reassignment*, not mutation of properties.
- `Object.freeze(obj)` makes an object shallowly immutable (throws in strict mode if you try to mutate).
- Spread / `Object.assign` / `Array.prototype.slice` create shallow copies.

### “Core” implementation
Below is a small, dependency‑free module that gives you the two pillars of practical immutability in JS:

1. **`deepFreeze`** – truly lock an object tree at runtime.  
2. **`setIn` / `updateIn`** – produce *new* objects/arrays with structural sharing (the heart of libraries like Immer/Immutable.js).

```js
/* ============================================================
 * 1. Deep freeze – make a value (and everything reachable)
 *    read‑only at runtime.
 * ============================================================ */

/**
 * Recursively freeze an object/array so no nested property can be
 * added, removed, or changed.  Returns the same value for chaining.
 *
 * @param {*} value
 * @returns {*} the frozen value
 */
function deepFreeze(value) {
  // Primitives (and null) have nothing to freeze.
  if (value === null || typeof value !== 'object') return value;

  // Avoid re‑freezing the same object (handles cycles).
  if (Object.isFrozen(value)) return value;

  // Freeze the current level first.
  Object.freeze(value);

  // Then recurse into enumerable own properties.
  for (const key of Object.keys(value)) {
    deepFreeze(value[key]);
  }

  // Also handle non‑enumerable / symbol keys if you want strictness.
  for (const sym of Object.getOwnPropertySymbols(value)) {
    deepFreeze(value[sym]);
  }

  return value;
}

/* ============================================================
 * 2. Immutable updates with structural sharing
 *    setIn(obj, ['a','b',0], newVal)  -> new object, unchanged
 *    paths unchanged keep the original reference.
 * ============================================================ */

/**
 * Get a value safely by path.
 */
function getIn(obj, path) {
  let cur = obj;
  for (const key of path) {
    if (cur == null) return undefined;
    cur = cur[key];
  }
  return cur;
}

/**
 * Set a value at a (possibly nested) path, returning a NEW root.
 * Arrays and objects are cloned only along the path; siblings keep
 * their original references (structural sharing).
 *
 * @param {*}       root   original (never mutated)
 * @param {Array}   path   e.g. ['users', 0, 'name']
 * @param {*}       value   new leaf value
 * @returns {*}     new root
 */
function setIn(root, path, value) {
  if (path.length === 0) return value; // replace whole thing

  const [head, ...tail] = path;

  if (Array.isArray(root)) {
    // Clone array shallowly, then recurse into the target slot.
    const next = root.slice();
    next[head] = setIn(root[head], tail, value);
    return next;
  }

  // Plain object (or missing key -> create object on the fly).
  const next = { ...root };
  next[head] = setIn(root != null ? root[head] : undefined, tail, value);
  return next;
}

/**
 * Update a value using a function: (old) => new.
 */
function updateIn(root, path, fn) {
  const old = getIn(root, path);
  return setIn(root, path, fn(old));
}

/* ============================================================
 * 3. Tiny demo / usage
 * ============================================================ */

const state = deepFreeze({
  users: [
    { id: 1, name: 'Ada',  tags: ['admin'] },
    { id: 2, name: 'Bob',  tags: [] },
  ],
  meta: { version: 1 },
});

// Attempted mutation throws in strict mode:
// state.users[0].name = 'Grace'; // TypeError

// Immutable update – original unchanged:
const next = setIn(state, ['users', 0, 'name'], 'Grace');
console.log('original still Ada:', state.users[0].name);   // 'Ada'
console.log('new is Grace:     ', next.users[0].name);    // 'Grace'
console.log('structural share: ', next.users[1] === state.users[1]); // true
console.log('meta shared:     ', next.meta === state.meta);          // true

// Functional update:
const bumped = updateIn(state, ['meta', 'version'], (v) => v + 1);
console.log('version bump:', bumped.meta.version); // 2
console.log('orig version:', state.meta.version);  // 1
```

### Interview talking points
- **Shallow vs. deep**: `Object.freeze` is shallow; `deepFreeze` walks the graph. Libraries often skip non‑plain objects (Date, Map, Set) and only freeze POJOs/arrays.
- **Structural sharing**: `setIn` clones only the path, so memory stays O(depth) instead of O(n).
- **Immer vs. Immutable.js**: Immer uses proxies to let you *write* mutable‑looking code while producing immutable output; Immutable.js uses persistent data structures (HAMT) for O(1) updates. The code above is the “hand‑rolled Immer‑lite” approach.
- **Pitfalls**: circular references (handled by `isFrozen` guard), class instances (Date/Map), and `const` ≠ immutability.

If asked to extend this, mention adding a `mergeDeep`, a `removeIn`, and TypeScript typings for paths (e.g., `lodash`‑style string paths `'users[0].name'`).

Immutability in JavaScript is mostly “by convention”: the language has no real immutable types, so you must deliberately avoid mutation. Below are the common edge cases, with runnable examples and fixes.

---

## 1. Shallow copies still allow nested mutation

Spread/Object.assign only copy one level.

```js
const original = { a: { b: 1 } };

const copy = { ...original };
copy.a.b = 2;

console.log(original.a.b); // 2  (unexpected)
```

Fix: recursively clone nested objects, or use `structuredClone` / Immer for deep updates.

```js
const copy = structuredClone(original);
copy.a.b = 2;
console.log(original.a.b); // 1
```

---

## 2. Arrays mutate in place

Many array methods mutate the original: `push`, `pop`, `splice`, `sort`, `reverse`, `fill`, `copyWithin`.

```js
const arr = [3, 1, 2];
const sorted = arr.sort(); // mutates arr too

console.log(arr);    // [1, 2, 3]
console.log(sorted); // [1, 2, 3]
```

Fix: copy first, but remember the copy is still shallow.

```js
const sorted = [...arr].sort((a, b) => a - b);
```

---

## 3. `Object.freeze` is shallow

```js
const obj = Object.freeze({ nested: { x: 1 } });
obj.nested.x = 99; // allowed
console.log(obj.nested.x); // 99
```

Fix: deep-freeze recursively, or freeze at creation boundaries.

```js
function deepFreeze(obj) {
  Object.keys(obj).forEach(key => {
    if (typeof obj[key] === "object" && obj[key] !== null) deepFreeze(obj[key]);
  });
  return Object.freeze(obj);
}
```

---

## 4. Mutable built-ins: `Date`, `RegExp`, etc.

`Date` methods mutate the instance.

```js
const d = new Date("2024-01-01");
const d2 = d;
d2.setDate(15);
console.log(d.toISOString()); // changed too
```

Fix: construct a new one.

```js
const d2 = new Date(d);
```

`RegExp` has mutable `lastIndex` state, especially with the `g`/`y` flags.

```js
const r = /a/g;
r.lastIndex = 10;
const r2 = r; // same object
r2.lastIndex = 0;
console.log(r.lastIndex); // 0
```

Fix: create a new regex when you need independent state.

```js
const r2 = new RegExp(r.source, r.flags);
```

---

## 5. `Map` and `Set` are mutable

Even if the container is “const”, its contents can change.

```js
const m = new Map([["a", 1]]);
m.set("b", 2); // allowed
```

“Immutable update” means creating a new collection. But nested values are still shared.

```js
const m2 = new Map(m);
m2.set("c", 3);

// nested object is still shared
const n = new Map([["a", { x: 1 }]]);
const n2 = new Map(n);
n2.get("a").x = 99;
console.log(n.get("a").x); // 99
```

Fix: clone nested values too.

---

## 6. TypedArrays share buffers

Two views over the same `ArrayBuffer` mutate each other.

```js
const buf = new ArrayBuffer(4);
const v1 = new Uint8Array(buf);
const v2 = new Uint8Array(buf);

v1[0] = 42;
console.log(v2[0]); // 42
```

Fix: copy the buffer or use `.slice()`.

```js
const v2 = v1.slice(); // new backing store
```

---

## 7. Deep-clone pitfalls

### `JSON.stringify` is not a general clone

```js
const o = {
  date: new Date(),
  fn: () => 1,
  undef: undefined,
  nan: NaN,
  sym: Symbol("x"),
};

const clone = JSON.parse(JSON.stringify(o));
console.log(clone);
// date becomes string, fn/undef/sym disappear, nan becomes null
```

### `structuredClone` is better but has limits

```js
const o = { a: 1 };
o.self = o;
const clone = structuredClone(o); // works, handles cycles

// But these fail or lose data:
// structuredClone(() => {})        // throws DataCloneError
// structuredClone(document.body)   // throws
// structuredClone(new Foo())       // prototype/methods lost
```

### Circular references break naive recursive clones

```js
function naiveClone(x) {
  if (typeof x !== "object" || x === null) return x;
  const out = Array.isArray(x) ? [] : {};
  for (const k in x) out[k] = naiveClone(x[k]);
  return out;
}

const o = {};
o.self = o;
// naiveClone(o) -> RangeError: Maximum call stack size exceeded
```

Fix: use `structuredClone` for supported types, or track visited objects in a `Map`/`WeakMap`.

---

## 8. Class instances, prototypes, and methods

Spread creates a plain object and drops the prototype.

```js
class User {
  constructor(name) { this.name = name; }
  greet() { return `hi ${this.name}`; }
}

const u = new User("Ada");
const copy = { ...u };

console.log(copy instanceof User); // false
console.log(typeof copy.greet);    // "undefined"
```

Fix: reconstruct via constructor, or use a clone method.

```js
const copy = new User(u.name);
```

---

## 9. Getters/setters become data properties

```js
const o = {
  x: 5,
  get doubled() { return this.x * 2; },
};

const copy = { ...o };
console.log(Object.getOwnPropertyDescriptor(copy, "doubled"));
// becomes { value: 10, writable: true, enumerable: true, configurable: true }
```

The getter logic is lost; `copy.doubled` no longer tracks `x`.

---

## 10. Property descriptors and non-enumerable properties

Spread/Object.assign only copy *own enumerable* properties.

```js
const o = {};
Object.defineProperty(o, "hidden", {
  value: 42,
  enumerable: false,
  writable: true,
});

const copy = { ...o };
console.log(copy.hidden); // undefined
```

Fix: copy descriptors explicitly if needed.

```js
const copy = Object.create(Object.getPrototypeOf(o));
for (const key of Object.getOwnPropertyNames(o)) {
  Object.defineProperty(copy, key, Object.getOwnPropertyDescriptor(o, key));
}
```

---

## 11. Symbols

`Object.keys` ignores symbols, but spread copies enumerable symbol properties. This causes inconsistent “cloning” behavior.

```js
const s = Symbol("id");
const o = { [s]: 1, a: 2 };

console.log(Object.keys(o)); // ["a"]
console.log({ ...o }[s]);     // 1
console.log(JSON.stringify(o)); // '{"a":2}'  symbol lost
```

Fix: include `Object.getOwnPropertySymbols` when manually cloning.

---

## 12. Sparse arrays

Holes behave differently across copy methods.

```js
const a = [1, , 3];

console.log([...a]);           // [1, undefined, 3]
console.log(Object.assign([], a)); // [1, empty, 3]-ish? elements copied
console.log(JSON.stringify(a)); // "[1,null,3]"
```

Fix: decide whether holes should become `undefined` and handle explicitly. Avoid sparse arrays in immutable state if possible.

---

## 13. Shared references / aliasing

Two “copies” may still point to the same nested object.

```js
const a = { x: { y: 1 } };
const b = a;
const c = { ...a };

a.x.y = 99;
console.log(b.x.y); // 99
console.log(c.x.y); // 99 too
```

Fix: structural sharing with explicit nested replacement.

```js
const c = { ...a, x: { ...a.x, y: 99 } };
```

---

## 14. React/state-management reference equality

Mutating then passing the same reference prevents updates.

```js
state.items.push(newItem);
setState(state); // no re-render: same reference
```

Fix: create a new reference at every changed level.

```js
setState(prev => ({ ...prev, items: [...prev.items, newItem] }));
```

For nested updates, use Immer to avoid manual deep copying.

---

## 15. Prototype pollution when cloning untrusted data

Naively copying `__proto__` can pollute `Object.prototype`.

```js
const malicious = JSON.parse('{"__proto__": {"isAdmin": true}}');
// If clone logic does target[key] = source[key], may pollute prototype.
```

Fix: only copy own enumerable string/symbol keys; validate keys; use `Object.create(null)` for dictionaries or `Map`.

---

## Practical recommendation

For most apps:

- Use spread for one-level updates.
- Use `structuredClone` for deep, independent copies of plain data.
- Use Immer for complex immutable state updates.
- Preserve class instances via constructors/factory methods, not generic cloning.
- Treat `Date`, `RegExp`, `Map`, `Set`, TypedArrays, and class instances as special cases.
- Avoid mutating array methods; prefer `map`, `filter`, `concat`, `toSorted`, `toReversed`, `with`.

Below is a complete, self-contained implementation of persistent (immutable) data structures in JavaScript:

- **`ImmutableMap`** — a persistent hash map with structural sharing (HAMT-style path copying).
- **`ImmutableList`** — a persistent singly-linked (cons) list.
- **`ImmutableSet`** — built on top of the map.

Every mutating operation returns a *new* structure and leaves the original untouched. Unchanged subtrees are shared between versions.

```js
// ============================================================
// immutable.js — persistent data structures in JavaScript
// Run with: node immutable.js
// ============================================================

'use strict';

// ---------------- hashing & equality ----------------
const objectIds = new WeakMap();
let objectCounter = 0;

function hashKey(key) {
  let str;
  if (key === null) str = '\u0000null';
  else if (typeof key === 'object') {
    if (!objectIds.has(key)) objectIds.set(key, ++objectCounter);
    str = '\u0000obj#' + objectIds.get(key);
  } else {
    str = (typeof key) + ':' + String(key);
  }
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = (Math.imul(h, 31) + str.charCodeAt(i)) >>> 0;
  }
  return h;
}

function keyEqual(a, b) {
  return Object.is(a, b);
}

// ============================================================
// ImmutableMap — persistent hash map (path copying over a trie)
// ============================================================
const BITS = 5;
const WIDTH = 1 << BITS;          // 32
const MASK = WIDTH - 1;
const MAX_DEPTH = 7;             // 5 * 7 = 35 bits
const LEAF_SHIFT = MAX_DEPTH * BITS;

class ImmutableMap {
  constructor(root, size) {
    this._root = root === undefined ? null : root;
    this._size = size === undefined ? 0 : size;
  }

  static empty() { return new ImmutableMap(null, 0); }

  static of(entries) {
    let m = ImmutableMap.empty();
    for (const [k, v] of entries) m = m.set(k, v);
    return m;
  }

  get(key) { return mapGet(this._root, key); }
  has(key) { return mapHas(this._root, key); }

  set(key, value) {
    const existed = this.has(key);
    const newRoot = mapSet(this._root, key, value);
    return new ImmutableMap(newRoot, existed ? this._size : this._size + 1);
  }

  delete(key) {
    if (!this.has(key)) return this;
    const newRoot = mapDelete(this._root, key);
    return new ImmutableMap(newRoot, this._size - 1);
  }

  get size() { return this._size; }

  keys()   { return collectEntries(this._root).map(([k]) => k); }
  values() { return collectEntries(this._root).map(([, v]) => v); }
  entries(){ return collectEntries(this._root); }

  forEach(fn, thisArg) {
    for (const [k, v] of this.entries()) fn.call(thisArg, v, k, this);
  }

  map(fn, thisArg) {
    let m = ImmutableMap.empty();
    for (const [k, v] of this.entries()) m = m.set(k, fn.call(thisArg, v, k, this));
    return m;
  }

  filter(pred, thisArg) {
    let m = ImmutableMap.empty();
    for (const [k, v] of this.entries()) if (pred.call(thisArg, v, k, this)) m = m.set(k, v);
    return m;
  }

  merge(other) {
    let m = this;
    for (const [k, v] of other.entries()) m = m.set(k, v);
    return m;
  }

  toArray() { return [...this.entries()]; }
  toJSON()  { return Object.fromEntries(this.entries()); }
  [Symbol.iterator]() { return this.entries()[Symbol.iterator](); }
  toString() { return `ImmutableMap(${this._size})`; }
}

function mapGet(node, key) {
  const h = hashKey(key);
  let cur = node;
  let shift = 0;
  while (cur !== null) {
    if (cur.kind === 'leaf') {
      for (const [k, v] of cur.entries) if (keyEqual(k, key)) return v;
      return undefined;
    }
    if (shift >= LEAF_SHIFT) return undefined;
    const idx = (h >>> shift) & MASK;
    cur = cur.children[idx];
    shift += BITS;
  }
  return undefined;
}

function mapHas(node, key) {
  const h = hashKey(key);
  let cur = node;
  let shift = 0;
  while (cur !== null) {
    if (cur.kind === 'leaf') {
      for (const [k] of cur.entries) if (keyEqual(k, key)) return true;
      return false;
    }
    if (shift >= LEAF_SHIFT) return false;
    const idx = (h >>> shift) & MASK;
    cur = cur.children[idx];
    shift += BITS;
  }
  return false;
}

function mapSet(node, key, value) {
  const h = hashKey(key);
  return mapSetNode(node, key, value, h, 0);
}

function mapSetNode(node, key, value, h, shift) {
  if (node === null) {
    if (shift >= LEAF_SHIFT) {
      return { kind: 'leaf', entries: [[key, value]] };
    }
    const idx = (h >>> shift) & MASK;
    const child = mapSetNode(null, key, value, h, shift + BITS);
    const children = new Array(WIDTH).fill(null);
    children[idx] = child;
    return { kind: 'node', children };
  }
  if (node.kind === 'leaf') {
    const entries = node.entries.map(e => e.slice());
    let found = false;
    for (let i = 0; i < entries.length; i++) {
      if (keyEqual(entries[i][0], key)) { entries[i][1] = value; found = true; break; }
    }
    if (!found) entries.push([key, value]);
    return { kind: 'leaf', entries };
  }
  if (shift >= LEAF_SHIFT) return node;
  const idx = (h >>> shift) & MASK;
  const newChild = mapSetNode(node.children[idx], key, value, h, shift + BITS);
  if (newChild === node.children[idx]) return node;
  const children = node.children.slice();
  children[idx] = newChild;
  return { kind: 'node', children };
}

function mapDelete(node, key) {
  const h = hashKey(key);
  return mapDeleteNode(node, key, h, 0);
}

function mapDeleteNode(node, key, h, shift) {
  if (node === null) return null;
  if (node.kind === 'leaf') {
    const entries = node.entries.filter(([k]) => !keyEqual(k, key));
    if (entries.length === node.entries.length) return node;
    if (entries.length === 0) return null;
    return { kind: 'leaf', entries };
  }
  if (shift >= LEAF_SHIFT) return node;
  const idx = (h >>> shift) & MASK;
  const newChild = mapDeleteNode(node.children[idx], key, h, shift + BITS);
  if (newChild === node.children[idx]) return node;
  const children = node.children.slice();
  children[idx] = newChild;
  if (children.every(c => c === null)) return null;
  return { kind: 'node', children };
}

function collectEntries(node, out = []) {
  if (node === null) return out;
  if (node.kind === 'leaf') {
    for (const [k, v] of node.entries) out.push([k, v]);
    return out;
  }
  for (let i = 0; i < WIDTH; i++) {
    if (node.children[i]) collectEntries(node.children[i], out);
  }
  return out;
}

// ============================================================
// ImmutableList — persistent cons list
// ============================================================
class ImmutableList {
  constructor(head, tail, size) {
    this.head = head;
    this.tail = tail;
    this._size = size;
  }

  static empty() { return new ImmutableList(null, null, 0); }

  static of(...values) {
    let list = ImmutableList.empty();
    for (let i = values.length - 1; i >= 0; i--) list = list.prepend(values[i]);
    return list;
  }

  prepend(value) { return new ImmutableList(value, this, this._size + 1); }

  append(value) {
    if (this._size === 0) return this.prepend(value);
    return ImmutableList.of(...this.toArray(), value);
  }

  get(index) {
    if (index < 0 || index >= this._size) return undefined;
    let cur = this;
    for (let i = 0; i < index; i++) cur = cur.tail;
    return cur.head;
  }

  set(index, value) {
    if (index < 0 || index >= this._size) return this;
    const arr = this.toArray();
    arr[index] = value;
    return ImmutableList.of(...arr);
  }

  get size() { return this._size; }

  toArray() {
    const out = [];
    let cur = this;
    while (cur && cur._size > 0) {
      out.push(cur.head);
      cur = cur.tail;
    }
    return out;
  }

  [Symbol.iterator]() { return this.toArray()[Symbol.iterator](); }

  map(fn, thisArg) {
    return ImmutableList.of(...this.toArray().map((v, i) => fn.call(thisArg, v, i, this)));
  }

  filter(pred, thisArg) {
    return ImmutableList.of(...this.toArray().filter((v, i) => pred.call(thisArg, v, i, this)));
  }

  reduce(fn, init) {
    let acc = init;
    let i = 0;
    for (const v of this) acc = fn(acc, v, i++, this);
    return acc;
  }

  concat(other) { return ImmutableList.of(...this.toArray(), ...other.toArray()); }
  reverse()     { return ImmutableList.of(...this.toArray().slice().reverse()); }

  forEach(fn, thisArg) { this.toArray().forEach((v, i) => fn.call(thisArg, v, i, this)); }
  toString() { return `ImmutableList(${this.toArray().join(', ')})`; }
}

// ============================================================
// ImmutableSet — built on ImmutableMap
// ============================================================
class ImmutableSet {
  constructor(map) { this._map = map; }

  static empty() { return new ImmutableSet(ImmutableMap.empty()); }
  static of(...values) {
    let s = ImmutableSet.empty();
    for (const v of values) s = s.add(v);
    return s;
  }

  has(v) { return this._map.has(v); }
  add(v) { return new ImmutableSet(this._map.set(v, true)); }
  delete(v) { return new ImmutableSet(this._map.delete(v)); }
  get size() { return this._map.size; }
  values() { return this._map.keys(); }
  toArray() { return [...this.values()]; }
  [Symbol.iterator]() { return this.values()[Symbol.iterator](); }

  union(other) { let s = this; for (const v of other) s = s.add(v); return s; }
  intersection(other) {
    let s = ImmutableSet.empty();
    for (const v of this) if (other.has(v)) s = s.add(v);
    return s;
  }
  difference(other) {
    let s = ImmutableSet.empty();
    for (const v of this) if (!other.has(v)) s = s.add(v);
    return s;
  }
  toString() { return `ImmutableSet(${this.toArray().join(', ')})`; }
}

// ============================================================
// Demo / self-test
// ============================================================
function assert(cond, msg) { if (!cond) throw new Error('ASSERT FAILED: ' + msg); }

// --- Map basics & persistence ---
const m0 = ImmutableMap.empty();
const m1 = m0.set('a', 1).set('b', 2);
assert(m0.size === 0, 'empty unchanged');
assert(m1.size === 2, 'size after sets');
assert(m1.get('a') === 1 && m1.get('b') === 2, 'get');

const m2 = m1.set('a', 10);
assert(m1.get('a') === 1, 'original version unchanged (persistence)');
assert(m2.get('a') === 10, 'new version updated');
assert(m2.size === 2, 'size unchanged on update');

const m3 = m2.delete('b');
assert(m3.size === 1 && m2.has('b'), 'delete is persistent');
assert(!m3.has('b'), 'delete removes key');

// --- many keys (trie depth) ---
let big = ImmutableMap.empty();
for (let i = 0; i < 2000; i++) big = big.set('key-' + i, i * 2);
assert(big.size === 2000, 'bulk size');
for (let i = 0; i < 2000; i++) assert(big.get('key-' + i) === i * 2, 'bulk get ' + i);

// --- object keys by identity ---
const o1 = { x: 1 }, o2 = { x: 1 };
const mo = ImmutableMap.empty().set(o1, 'first');
assert(mo.get(o1) === 'first', 'object key identity');
assert(mo.get(o2) === undefined, 'distinct objects not equal');

// --- NaN key ---
const mn = ImmutableMap.empty().set(NaN, 'nan');
assert(mn.get(NaN) === 'nan', 'NaN key');

// --- map/filter/merge ---
const doubled = m1.map((v) => v * 10);
assert(doubled.get('a') === 10 && doubled.get('b') === 20, 'map');
const filtered = m1.filter((v) => v > 1);
assert(filtered.size === 1 && filtered.get('b') === 2, 'filter');
const merged = m1.merge(ImmutableMap.of([['c', 3], ['a', 99]]));
assert(merged.get('a') === 99 && merged.get('c') === 3 && merged.size === 3, 'merge');

// --- List ---
const l0 = ImmutableList.empty();
const l1 = l0.prepend(1).prepend(2).prepend(3); // 3,2,1
assert(l1.toArray().join(',') === '3,2,1', 'prepend');
assert(l1.get(1) === 2, 'get index');
const l2 = l1.set(1, 99);
assert(l1.get(1) === 2, 'list persistence');
assert(l2.get(1) === 99 && l2.size === 3, 'list set');
assert(l1.concat(ImmutableList.of(4, 5)).toArray().join(',') === '3,2,1,4,5', 'concat');
assert(l1.reverse().toArray().join(',') === '1,2,3', 'reverse');
assert(l1.reduce((a, v) => a + v, 0) === 6, 'reduce');
assert(l1.map((v) => v * 2).toArray().join(',') === '6,4,2', 'list map');
assert(l1.filter((v) => v > 1).toArray().join(',') === '3,2', 'list filter');

// --- Set ---
const s = ImmutableSet.of(1, 2, 3);
const s2 = s.add(2);
assert(s2.size === 3, 'set add duplicate');
assert(s.has(4) === false, 'set has');
const s3 = s.union(ImmutableSet.of(3, 4));
assert(s3.toArray().sort().join(',') === '1,2,3,4', 'set union');
assert(s.intersection(ImmutableSet.of(2, 3, 9)).toArray().sort().join(',') === '2,3', 'set intersection');
assert(s.difference(ImmutableSet.of(2)).toArray().sort().join(',') === '1,3', 'set difference');

// --- structural sharing sanity: versions don't alias ---
const base = ImmutableMap.empty().set('x', 1);
const a = base.set('y', 2);
const b = base.set('z', 3);
assert(a.has('z') === false && b.has('y') === false, 'branch independence');

console.log('All assertions passed.');
console.log('m1  =', JSON.stringify(m1.toJSON()));
console.log('l1  =', l1.toString());
console.log('s3  =', s3.toString());
```

### How it works

1. **Persistence via path copying.**  
   `ImmutableMap` is a trie (32-way, 5 bits per level, 7 levels = 35 bits). On `set`/`delete` only the nodes along the path from root to the affected leaf are cloned; every other subtree is shared by reference. This makes updates *O(log n)* with a small constant, and unchanged branches cost nothing.

2. **Collision handling.**  
   When several keys land in the same leaf slot, that leaf stores an array of `[key, value]` pairs and is updated copy-on-write. `keyEqual` uses `Object.is`, so `NaN` keys work and `+0`/`-0` are distinguished.

3. **Identity-based object keys.**  
   Objects are hashed via a `WeakMap`-assigned id, so two different object instances never collide incorrectly and no GC roots are leaked.

4. **ImmutableList** is a classic cons list: `prepend` is *O(1)* and shares the tail; `get`/`set`/`append` are *O(n)* (acceptable for the use cases where cons lists shine; swap in a persistent vector for random access).

5. **ImmutableSet** is just a map whose values are `true`, reusing all the persistence machinery.

### Complexity summary

| Operation | Map | List |
|-----------|-----|------|
| get/has   | O(log₃₂ n) | O(n) |
| set/delete| O(log₃₂ n) | O(n) (rebuild) |
| prepend   | — | O(1) |
| iterate   | O(n) | O(n) |

### Production note
For real applications, prefer battle-tested libraries such as **Immutable.js**, **Immer** (for draft-based mutations over plain JS), or **immer**-style structural sharing, plus native `Object.freeze` for shallow immutability. The implementation above is intentionally compact and readable while still demonstrating the core ideas: structural sharing, path copying, and version independence.

## Immutable data structures in JavaScript

### 1. The idea

In JavaScript, **primitive values** (`string`, `number`, `boolean`, `null`, `undefined`, `symbol`, `bigint`) are immutable:

```js
let x = 5;
x = 7; // reassigns x, does not mutate 5
```

But **objects and arrays** are mutable by default:

```js
const user = { name: "Ada" };
user.name = "Grace"; // mutates the same object
```

“Immutable data structures” usually means: **treat objects/arrays as values that cannot change**. To “update” them, you create a new object/array containing the changed data, while leaving the original unchanged.

```js
const user = { name: "Ada" };
const updated = { ...user, name: "Grace" };

console.log(user.name);    // "Ada"
console.log(updated.name); // "Grace"
```

This matters because:

- **Predictability**: functions do not accidentally change shared state.
- **Change detection**: comparing references (`old === new`) tells you whether something changed.
- **Time travel / undo**: keeping old versions is cheap if unchanged parts are shared.
- **Concurrency safety**: immutable values can be shared without locks.

A common implementation idea is **structural sharing**: the new structure reuses unchanged parts of the old one.

---

### 2. Core syntax

#### Shallow object update with spread

```js
const state = { count: 0, user: { name: "Ada" } };

const next = {
  ...state,
  count: state.count + 1,
};

// state is unchanged
console.log(state.count); // 0
console.log(next.count);  // 1
```

#### Nested object update

Spread is shallow, so nested objects must be copied too:

```js
const state = { user: { name: "Ada", age: 30 } };

const next = {
  ...state,
  user: {
    ...state.user,
    age: 31,
  },
};
```

#### Array append / remove / update

```js
const items = [1, 2, 3];

// Append
const added = [...items, 4];

// Remove by index
const removed = items.filter((_, i) => i !== 1);

// Update by index
const updated = items.map((x, i) => (i === 1 ? 99 : x));

console.log(items);   // [1, 2, 3]
console.log(added);   // [1, 2, 3, 4]
console.log(removed); // [1, 3]
console.log(updated); // [1, 99, 3]
```

#### Immutable array methods (ES2023)

Modern JavaScript provides non-mutating alternatives:

```js
const arr = [3, 1, 2];

const sorted = arr.toSorted();      // [1, 2, 3]
const reversed = arr.toReversed();  // [2, 1, 3]
const spliced = arr.toSpliced(1, 1, 9); // [3, 9, 2]
const replaced = arr.with(0, 99);   // [99, 1, 2]

console.log(arr); // still [3, 1, 2]
```

#### `Object.freeze` (shallow)

`Object.freeze` prevents top-level mutation, but does not freeze nested objects:

```js
const obj = { nested: { a: 1 } };
Object.freeze(obj);

obj.x = 2;          // ignored in strict mode, fails otherwise
obj.nested.a = 2;   // still works! shallow freeze only

console.log(obj.nested.a); // 2
```

A deep-freeze helper:

```js
function deepFreeze(value) {
  if (value && typeof value === "object") {
    Object.freeze(value);
    for (const key of Object.keys(value)) {
      deepFreeze(value[key]);
    }
  }
  return value;
}
```

Use carefully: freezing can affect performance and may break libraries expecting mutation.

---

### 3. Libraries for persistent immutable structures

For large or deeply nested data, hand-written spread copies can be expensive and verbose. Libraries provide **persistent data structures** with structural sharing.

#### Immer: mutable-looking updates, immutable results

```js
import { produce } from "immer";

const state = {
  user: { name: "Ada", scores: [10, 20] },
};

const next = produce(state, (draft) => {
  draft.user.name = "Grace";
  draft.user.scores.push(30);
});

console.log(state.user.scores); // [10, 20]
console.log(next.user.scores);  // [10, 20, 30]
```

Immer is popular in Redux Toolkit and React state updates.

#### Immutable.js: persistent Map/List

```js
import { Map, List } from "immutable";

const state = Map({
  user: Map({ name: "Ada" }),
  items: List([1, 2, 3]),
});

const next = state.setIn(["user", "name"], "Grace");

console.log(state.getIn(["user", "name"])); // "Ada"
console.log(next.getIn(["user", "name"]));  // "Grace"
```

Tradeoff: better structural sharing, but requires converting to/from plain JS and can add API complexity.

---

### 4. Typical use cases

#### React state

```js
const [state, setState] = useState({ count: 0 });

// Bad: mutates existing state
state.count++;
setState(state);

// Good: new object
setState((prev) => ({ ...prev, count: prev.count + 1 }));
```

#### Redux / global stores

Reducers should be pure and return new state:

```js
function reducer(state = { todos: [] }, action) {
  switch (action.type) {
    case "ADD_TODO":
      return {
        ...state,
        todos: [...state.todos, action.payload],
      };
    default:
      return state;
  }
}
```

#### Functional data pipelines

```js
const result = users
  .filter((u) => u.active)
  .map((u) => ({ ...u, displayName: u.name.toUpperCase() }));
```

#### Undo / redo

```js
const history = [state0, state1, state2];
const previous = history[history.length - 2];
```

Because older states are not mutated, history snapshots remain valid.

#### Memoization and caching

```js
const memo = new Map();

function expensive(input) {
  if (memo.has(input)) return memo.get(input);
  const result = compute(input);
  memo.set(input, result);
  return result;
}
```

Immutable inputs make cache keys safer and behavior predictable.

---

### 5. Common pitfalls

- **Shallow copies can still share nested references**:

  ```js
  const a = { nested: { x: 1 } };
  const b = { ...a };
  b.nested.x = 2;
  console.log(a.nested.x); // 2, because nested object is shared
  ```

- **`Object.assign` is also shallow**:

  ```js
  const next = Object.assign({}, state, { count: 2 });
  ```

- **`JSON.parse(JSON.stringify(obj))`** creates a deep copy but loses functions, `Date`, `Map`, `Set`, `undefined`, and can fail on circular references.

- **Performance**: copying very large objects on every update can be costly. Persistent structures or Immer can help.

- **Reference equality tricks**: React/Redux rely on new references for changed data. Mutating and returning the same object can prevent updates from rendering.

---

### Summary

Immutable data in JavaScript is mainly a **discipline**: do not mutate existing objects/arrays; create new ones with spread, immutable array methods, or libraries. Use it for state management, UI updates, pure functions, undo history, and predictable sharing of data. For complex nested updates, prefer Immer or persistent immutable libraries.

## Typical mistake: mutating what you thought was a copy

```js
const user = { name: "Ada", tags: ["admin"] };

// Looks like we're creating an "updated" user...
const updated = user;
updated.name = "Grace";
updated.tags.push("editor");

console.log(user.name);   // "Grace"   ← original changed!
console.log(user.tags);   // ["admin", "editor"]
```

### Why it's wrong

- `const updated = user;` does **not** copy the object — it copies the *reference*. Both variables point at the exact same object in memory.
- So `updated.name = ...` and `updated.tags.push(...)` are mutating the original `user`.
- Even `const` doesn't help here: `const` only prevents reassigning the variable binding (`updated = ...`), not mutating the object it points to.
- Nested structures make it worse: a shallow spread like `{ ...user }` would still share the same `tags` array, so `updated.tags.push(...)` would still leak into `user`.

---

## Corrected version

```js
const user = { name: "Ada", tags: ["admin"] };

// Create a new object and a new array (deep enough for this shape)
const updated = {
  ...user,
  name: "Grace",
  tags: [...user.tags, "editor"],
};

console.log(user.name);     // "Ada"          (unchanged)
console.log(user.tags);     // ["admin"]      (unchanged)
console.log(updated.name);  // "Grace"
console.log(updated.tags);  // ["admin", "editor"]
```

### Key fixes

1. **New object identity**: `{ ...user, ... }` creates a brand-new object instead of aliasing the old one.
2. **New array identity**: `[...user.tags, "editor"]` creates a new array; the original `tags` array is never touched.
3. **No mutation of inputs**: the original `user` remains intact, which is what "immutable update" means.

### Common gotchas to remember

- **Shallow copies aren't enough for nested data.** `{ ...user }` copies top-level keys, but nested objects/arrays are still shared. For arbitrary nesting, use `structuredClone(user)` (modern JS) or a library like Immer.
- **Methods that mutate in place** are a frequent source of bugs: `Array.prototype.sort`, `reverse`, `splice`, `push`, `pop`, and `Object.assign(target, ...)` mutate their target. Prefer non-mutating alternatives (`toSorted`, `toReversed`, `toSpliced`, `concat`, spread).
- **Immer** is a popular way to write "mutable-looking" code that produces immutable updates safely:

```js
import { produce } from "immer";
const updated = produce(user, (draft) => {
  draft.name = "Grace";
  draft.tags.push("editor");
});
```

Here `draft` is a proxy; the original `user` is left untouched and `updated` is a new, structurally shared immutable value.

### Rule of thumb

> Treat data as read-only. To "change" something, build and return a **new** value rather than editing the existing one.

# Common Pitfalls with Immutable Data Structures in JavaScript

Below are the most common pitfalls, grouped by area. Each includes a short explanation and runnable code.

---

## 1. Shallow copies leave nested data shared

The spread operator and `Object.assign` copy only the top level. Nested objects/arrays are still shared by reference.

```js
const original = { user: { name: "Ada", roles: ["admin"] } };

// Pitfall: only top level is copied
const copy = { ...original };
copy.user.name = "Grace";
copy.user.roles.push("editor");

console.log(original.user.name);   // "Grace"  ← mutated!
console.log(original.user.roles);  // ["admin", "editor"] ← mutated!
```

**Fix:** deep-clone or update immutably at every changed level.

```js
const safe = {
  ...original,
  user: {
    ...original.user,
    name: "Grace",
    roles: [...original.user.roles, "editor"],
  },
};
```

---

## 2. Mutating nested values after an “immutable” update

Even if you create a new top-level object, mutating a nested reference later mutates the shared subtree.

```js
const state = { items: [{ id: 1, done: false }] };
const next = { ...state, items: [...state.items] };

next.items[0].done = true; // mutates shared item object

console.log(state.items[0].done); // true ← bug
```

**Fix:** clone nested objects you intend to change.

```js
const next = {
  ...state,
  items: state.items.map((item) =>
    item.id === 1 ? { ...item, done: true } : item
  ),
};
```

---

## 3. In-place array methods

Many array methods mutate the original array.

```js
const arr = [3, 1, 2];

const sorted = arr.sort();          // mutates arr
const reversed = arr.reverse();     // mutates arr again
arr.push(4);                        // mutates arr
arr.splice(1, 1);                   // mutates arr

console.log(arr); // [4, 2, 1] (or similar) — original destroyed
```

**Fix:** use non-mutating alternatives.

```js
const arr = [3, 1, 2];
const sorted = [...arr].sort((a, b) => a - b); // or arr.toSorted()
const reversed = [...arr].reverse();            // or arr.toReversed()
const added = [...arr, 4];
const removed = arr.filter((_, i) => i !== 1);
```

Modern JS (ES2023) provides `toSorted`, `toReversed`, `toSpliced`, `with`.

```js
const a = [3, 1, 2];
const b = a.toSorted((x, y) => x - y); // a unchanged
```

---

## 4. `Object.freeze` is shallow

`Object.freeze` prevents top-level property changes but not nested mutation.

```js
const obj = Object.freeze({ nested: { value: 1 } });
obj.nested.value = 2; // succeeds (in non-strict) or silently fails
console.log(obj.nested.value); // 2
```

**Fix:** deep freeze recursively, or use a library/Immer.

```js
function deepFreeze(obj) {
  Object.freeze(obj);
  for (const value of Object.values(obj)) {
    if (value && typeof value === "object" && !Object.isFrozen(value)) {
      deepFreeze(value);
    }
  }
  return obj;
}
```

---

## 5. `JSON.parse(JSON.stringify(x))` is not a universal deep clone

It drops functions, `undefined`, symbols, `Date` becomes string, `Map`/`Set` become objects, and fails on circular references.

```js
const x = {
  date: new Date(),
  fn: () => 42,
  undef: undefined,
  map: new Map([["a", 1]]),
};

const clone = JSON.parse(JSON.stringify(x));
console.log(clone.date instanceof Date); // false
console.log(typeof clone.fn);            // "undefined"
console.log(clone.map);                  // {} (plain object)
```

**Fix:** use `structuredClone` (modern) for most cases, or a deep-clone library for exotic values.

```js
const clone = structuredClone(x); // preserves Date, Map, Set, etc.
```

`structuredClone` still cannot clone functions or DOM nodes.

---

## 6. Reference equality (`===`) traps

Immutable updates create new references, so `===` on objects/arrays is identity, not value equality.

```js
const a = { x: 1 };
const b = { x: 1 };

console.log(a === b); // false

// In React/memo, this causes unnecessary re-renders if you create new objects each render
```

**Fix:** compare by value when needed, or use memoization/selectors.

```js
function shallowEqual(a, b) {
  if (a === b) return true;
  if (!a || !b || typeof a !== "object" || typeof b !== "object") return false;
  const ka = Object.keys(a), kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  return ka.every((k) => a[k] === b[k]);
}
```

---

## 7. Mutating React state directly

React relies on new references to detect changes. Mutating state breaks rendering and can cause stale UI.

```js
function Component() {
  const [user, setUser] = useState({ name: "Ada", tags: [] });

  const addTag = (tag) => {
    user.tags.push(tag); // mutates state
    setUser(user);       // same reference → React may skip re-render
  };
}
```

**Fix:** create new state.

```js
const addTag = (tag) => {
  setUser((prev) => ({ ...prev, tags: [...prev.tags, tag] }));
};
```

---

## 8. Reducers that mutate instead of returning new state

In Redux (and similar), returning a mutated object or forgetting to return breaks change detection.

```js
function reducer(state, action) {
  if (action.type === "INCREMENT") {
    state.count += 1; // mutation
    return state;     // same reference
  }
  return state;
}
```

**Fix:** return a new object.

```js
function reducer(state, action) {
  if (action.type === "INCREMENT") {
    return { ...state, count: state.count + 1 };
  }
  return state;
}
```

---

## 9. Immer misuse

Immer’s `produce` gives a draft you may mutate, but you must not mutate the original or mix patterns incorrectly.

```js
import { produce } from "immer";

const base = { count: 0 };

// Pitfall: mutating base directly
base.count = 1;

// Pitfall: not using returned value
produce(base, (draft) => {
  draft.count += 1;
}); // result discarded
```

**Fix:** use the returned next state and avoid mutating base.

```js
const next = produce(base, (draft) => {
  draft.count += 1;
});
```

Also avoid mutating objects outside the draft that are referenced by it.

---

## 10. Immutable.js API and conversion pitfalls

Immutable.js collections are not plain JS objects. Access, equality, and conversion have traps.

```js
import { Map } from "immutable";

const m = Map({ a: 1 });
console.log(m.a);            // undefined (not a property)
console.log(m.get("a"));     // 1

const m2 = m.set("a", 2);
console.log(m === m2);       // false (new instance)

// Expensive conversion
const plain = m.toJS();      // deep conversion cost; avoid in hot paths
```

**Pitfalls:**
- Forgetting `.get`/`.set`.
- Using `===` expecting value equality (Immutable.js does value equality for its collections, but only among Immutable collections).
- `toJS()` creates new objects and can be expensive.
- Mixing Immutable.js with plain objects loses immutability guarantees.

---

## 11. Default parameters and shared mutable defaults

Default values are evaluated once per call? Actually default parameter expressions are evaluated each call, but object literals create new objects each call—still, aliasing shared constants is a trap.

```js
const DEFAULTS = { retries: 3, tags: [] };

function run(opts = DEFAULTS) {
  opts.tags.push("x"); // mutates shared DEFAULTS.tags
}
run();
run();
console.log(DEFAULTS.tags); // ["x", "x"]
```

**Fix:** clone defaults or create fresh objects.

```js
function run(opts = {}) {
  const config = { retries: 3, tags: [], ...opts };
  config.tags = [...config.tags];
  // ...
}
```

---

## 12. Destructuring does not clone

Destructuring extracts references; mutating extracted nested values mutates original.

```js
const state = { user: { name: "Ada" } };
const { user } = state;
user.name = "Grace";
console.log(state.user.name); // "Grace"
```

**Fix:** clone when you need independence.

```js
const user = { ...state.user };
user.name = "Grace";
```

---

## 13. Sorting comparator side effects

`sort` mutates and comparators should be pure. Side effects in comparators are especially dangerous with immutable workflows.

```js
const items = [{ v: 2 }, { v: 1 }];
items.sort((a, b) => {
  a.v += 1; // mutation side effect
  return a.v - b.v;
});
```

**Fix:** never mutate in comparator; use `toSorted`.

```js
const sorted = items.toSorted((a, b) => a.v - b.v);
```

---

## 14. `Map`, `Set` mutation

`Map.prototype.set` and `Set.prototype.add` mutate in place.

```js
const map = new Map([["a", 1]]);
const next = map;
next.set("a", 2);
console.log(map.get("a")); // 2 ← mutated

const set = new Set([1]);
const nextSet = set;
nextSet.add(2);
console.log(set.has(2)); // true
```

**Fix:** create new collections.

```js
const nextMap = new Map(map);
nextMap.set("a", 2);

const nextSet = new Set(set);
nextSet.add(2);
```

---

## 15. `Date` objects are mutable

`Date` methods mutate the instance.

```js
const d = new Date("2024-01-01");
const copy = d;
copy.setDate(copy.getDate() + 1);
console.log(d.toISOString()); // changed
```

**Fix:** create a new Date.

```js
const next = new Date(d);
next.setDate(next.getDate() + 1);
```

---

## 16. TypeScript `readonly` is compile-time only

`readonly` does not prevent runtime mutation.

```ts
type User = { readonly name: string };
const u: User = { name: "Ada" };
(u as any).name = "Grace"; // runtime mutation possible
```

**Fix:** combine with runtime immutability (`Object.freeze`, Immer, or defensive copying) when needed.

---

## 17. Losing prototypes/functions during cloning

Deep cloning via structured clone or JSON drops methods and prototype chain details (structured clone preserves some, but not functions).

```js
class Point { constructor(x, y) { this.x = x; this.y = y; } }
const p = new Point(1, 2);
const clone = structuredClone(p);
console.log(clone instanceof Point); // false
```

**Fix:** reconstruct instances or use class-aware cloning.

```js
const clone = new Point(p.x, p.y);
```

---

## 18. Accidental mutation via `delete`

`delete` mutates objects in place; it is not an immutable update.

```js
const obj = { a: 1, b: 2 };
const next = obj;
delete next.a;
console.log(obj); // { b: 2 } ← mutated
```

**Fix:** omit property immutably.

```js
const { a, ...rest } = obj;
// rest is new object without a
```

---

## 19. Array index assignment

Direct index assignment mutates.

```js
const arr = [1, 2, 3];
const next = arr;
next[0] = 99;
console.log(arr); // [99, 2, 3]
```

**Fix:** use `with` or map.

```js
const next = arr.with(0, 99); // ES2023
// or
const next = arr.map((v, i) => (i === 0 ? 99 : v));
```

---

## 20. Circular references and cloning

Naive recursive clone fails on cycles; some APIs throw.

```js
const a = {};
a.self = a;

// JSON.stringify(a) // throws TypeError
// structuredClone(a) // works (handles cycles)
```

**Fix:** use `structuredClone` or a cycle-aware clone utility.

---

## 21. Performance: over-copying

Immutability can create excessive allocations. Updating one field in a large object/array copies everything.

```js
const big = Array.from({ length: 100000 }, (_, i) => ({ id: i }));
const next = big.map((x) => (x.id === 5 ? { ...x, v: 1 } : x));
// copies 100k references (cheap-ish) but still allocates
```

**Fix:** structural sharing, Immer, or persistent data structures (Immutable.js) for very large state. Profile before optimizing.

---

## 22. Equality checks in memoization

`React.memo`, `useMemo`, `useCallback` depend on stable references. Creating new objects/functions each render defeats memoization.

```js
function Parent() {
  const config = { a: 1 }; // new object every render
  return <Child config={config} />; // Child re-renders every time
}
```

**Fix:** memoize values/functions.

```js
const config = useMemo(() => ({ a: 1 }), []);
const onClick = useCallback(() => {}, []);
```

---

## Quick checklist

- Treat all objects/arrays as read-only unless explicitly cloning.
- Prefer `map`, `filter`, spread, `toSorted`, `with`.
- Clone nested levels that change.
- Use `structuredClone` for deep copies when appropriate.
- In React/Redux, never mutate state; return new references.
- Use Immer carefully: mutate only the draft, use returned value.
- Remember `readonly`/`freeze` are shallow or compile-time.
- Watch out for mutable built-ins: `Date`, `Map`, `Set`, arrays.

If you want, I can also provide a small utility library of immutable helpers or a React-specific deep dive.

## Short Practical Exercise

**Exercise:** Build an immutable shopping-cart state module.

You have a cart shaped like:

```js
{
  id: "cart-1",
  items: [
    { id: "p1", name: "Book", qty: 2, price: 12.5 },
    { id: "p2", name: "Pen",  qty: 1, price: 1.25 }
  ],
  coupon: null
}
```

Implement these **pure, non-mutating** operations:

1. `addItem(cart, item)` — add `item`; if its `id` already exists, increment `qty` instead of duplicating.
2. `removeItem(cart, id)` — remove the item with that id.
3. `setQuantity(cart, id, qty)` — set quantity; if `qty <= 0`, remove the item.
4. `applyCoupon(cart, code)` — set `coupon` to `code` (or `null` to clear).
5. `total(cart)` — return the cart total.

**Constraints:** never mutate the input `cart` or any nested object/array. Return new structures. Use only plain JS.

---

## Step-by-Step Solution

### Step 1: Decide the update pattern

For immutable updates in JS we use **structural sharing**:

- Replace the top-level object with a new object.
- Replace only the arrays/objects on the path that changed.
- Reuse unchanged nested values by reference.

This keeps updates cheap and makes change detection easy (`oldCart !== newCart`).

### Step 2: `addItem`

We must not push into `cart.items`. Instead:

- Find the existing item by `id`.
- If found, return a new cart whose `items` is a new array produced by `map`, replacing that one item with a new item object.
- If not found, return a new cart whose `items` is `[...cart.items, newItemCopy]`.

```js
function addItem(cart, item) {
  const idx = cart.items.findIndex((x) => x.id === item.id);

  if (idx === -1) {
    return {
      ...cart,
      items: [...cart.items, { ...item }]
    };
  }

  return {
    ...cart,
    items: cart.items.map((x, i) =>
      i === idx ? { ...x, qty: x.qty + item.qty } : x
    )
  };
}
```

Notes:
- `{ ...item }` prevents external mutation of the incoming item from affecting cart state.
- Unchanged items keep their original references (`x` is reused), so `oldItems[i] === newItems[i]` for unchanged entries.

### Step 3: `removeItem`

Use `filter`, which always returns a new array:

```js
function removeItem(cart, id) {
  return {
    ...cart,
    items: cart.items.filter((x) => x.id !== id)
  };
}
```

### Step 4: `setQuantity`

Combine the “update one” and “remove” ideas:

```js
function setQuantity(cart, id, qty) {
  if (qty <= 0) return removeItem(cart, id);

  const exists = cart.items.some((x) => x.id === id);
  if (!exists) return cart; // nothing to do; returning same ref signals "no change"

  return {
    ...cart,
    items: cart.items.map((x) =>
      x.id === id ? { ...x, qty } : x
    )
  };
}
```

Returning the original `cart` when nothing changes is a common optimization, but be careful: callers must not assume a new object. For strict immutability semantics you could always return a new object; here we optimize only the no-op branch.

### Step 5: `applyCoupon`

Simple top-level field update:

```js
function applyCoupon(cart, code) {
  return { ...cart, coupon: code ?? null };
}
```

### Step 6: `total`

Pure derivation, no state change:

```js
function total(cart) {
  return cart.items.reduce((sum, x) => sum + x.qty * x.price, 0);
}
```

### Step 7: Immutability verification

A good habit is to add a tiny guard in tests:

```js
function sameRef(a, b) { return a === b; }
```

After an operation, the original cart must still equal its deep snapshot, and the new cart must differ by reference.

---

## Final Solution

```js
// cart.js

export function createCart(id = "cart-1", items = [], coupon = null) {
  return {
    id,
    items: items.map((x) => ({ ...x })),
    coupon
  };
}

export function addItem(cart, item) {
  if (!item || !item.id) throw new Error("item must have an id");

  const idx = cart.items.findIndex((x) => x.id === item.id);

  if (idx === -1) {
    return {
      ...cart,
      items: [...cart.items, { ...item, qty: item.qty ?? 1 }]
    };
  }

  return {
    ...cart,
    items: cart.items.map((x, i) =>
      i === idx ? { ...x, qty: x.qty + (item.qty ?? 1) } : x
    )
  };
}

export function removeItem(cart, id) {
  return {
    ...cart,
    items: cart.items.filter((x) => x.id !== id)
  };
}

export function setQuantity(cart, id, qty) {
  if (qty <= 0) return removeItem(cart, id);

  if (!cart.items.some((x) => x.id === id)) return cart;

  return {
    ...cart,
    items: cart.items.map((x) =>
      x.id === id ? { ...x, qty } : x
    )
  };
}

export function applyCoupon(cart, code) {
  return { ...cart, coupon: code ?? null };
}

export function total(cart) {
  return cart.items.reduce((sum, x) => sum + x.qty * x.price, 0);
}

// ---------- demo / self-check ----------
if (import.meta.url === `file://${process.argv[1]}`) {
  const original = createCart("c1", [
    { id: "p1", name: "Book", qty: 2, price: 12.5 },
    { id: "p2", name: "Pen",  qty: 1, price: 1.25 }
  ]);

  const snap = structuredClone(original);

  const afterAdd = addItem(original, { id: "p1", name: "Book", qty: 1, price: 12.5 });
  const afterNew = addItem(afterAdd, { id: "p3", name: "Mug", qty: 1, price: 8 });
  const afterQty = setQuantity(afterNew, "p2", 3);
  const afterRemove = removeItem(afterQty, "p1");
  const afterCoupon = applyCoupon(afterRemove, "SAVE10");

  // Immutability checks
  console.log("original unchanged:", JSON.stringify(original) === JSON.stringify(snap));
  console.log("new cart is new ref:", afterCoupon !== original);
  console.log("unchanged item reused (p3):",
    original.items.find((x) => x.id === "p3") === undefined &&
    afterNew.items.find((x) => x.id === "p3") !== undefined);

  console.log("items after ops:", afterCoupon.items);
  console.log("coupon:", afterCoupon.coupon);
  console.log("total:", total(afterCoupon).toFixed(2));
}
```

### Why this matters

- **Predictability:** state changes are explicit; debugging is easier because old states remain intact.
- **Performance:** libraries like React/Redux rely on reference equality (`===`) to skip re-renders; structural sharing makes that cheap.
- **Undo/redo & time-travel:** since you never overwrite old state, keeping a history array is trivial.
- **Concurrency safety:** no shared mutable references means fewer race conditions.

If you want even less boilerplate, `immer` (`produce`) gives the same guarantees with mutable-looking code, but understanding the manual spread/map/filter approach above is essential for performance and for debugging immutable data bugs.

## Immutable Data Structures in JavaScript

### What they are

An **immutable data structure** never changes after it is created. Instead of mutating the existing value, an update returns a **new** value:

```js
const a = [1, 2, 3];
const b = [...a, 4]; // a is still [1, 2, 3]
```

### Why they matter

| Benefit | Explanation |
|---|---|
| **Predictability** | No hidden side effects; functions are easier to reason about. |
| **Change detection** | `old !== new` is a cheap, reliable equality check (React, Redux). |
| **Time travel / undo** | Old versions remain valid because they were never mutated. |
| **Concurrency** | Shared state cannot be corrupted by another thread/fiber. |

### The naive approach vs. the real core

- **Naive (copy-on-write):** `const next = { ...prev, x: 5 }`. Simple, but copying an entire object/array is **O(n)** and creates lots of garbage.
- **Real core (structural sharing):** Keep the old structure and create only the **path** that changed. Unchanged branches are shared between versions. This gives **O(log n)** updates and O(1) equality checks.

A classic example is a **persistent vector** (like Clojure’s vector or Immutable.js `List`): a trie with branching factor 32, plus a small “tail” buffer for fast `push`.

---

## Implementation: a persistent vector with structural sharing

```js
// persistent-vector.js

const BRANCH = 32;   // trie width
const MASK = 31;     // BRANCH - 1

class Node {
  constructor(array) {
    // array holds either child Nodes (internal level) or values (leaf level)
    this.array = array;
  }
}

/**
 * A persistent (immutable) vector.
 *
 * Invariants:
 *  - size: number of elements
 *  - shift: 5 * (number of trie levels). Minimum meaningful value is 5.
 *  - root: top trie node, or null when size <= 32 (everything lives in tail)
 *  - tail: array of the last 0..32 elements
 */
export class PersistentVector {
  constructor(size = 0, shift = 5, root = null, tail = []) {
    this.size = size;
    this.shift = shift;
    this.root = root;
    this.tail = tail;
  }

  static empty() {
    return new PersistentVector();
  }

  static from(array) {
    let v = PersistentVector.empty();
    for (const x of array) v = v.push(x);
    return v;
  }

  // ---------- helpers ----------

  _tailOffset() {
    return this.size - this.tail.length;
  }

  _cloneNode(node) {
    return node ? new Node(node.array.slice()) : new Node(new Array(BRANCH));
  }

  // ---------- read ----------

  get(i) {
    if (i < 0 || i >= this.size) return undefined;

    // Fast path: element is in the tail buffer.
    if (i >= this._tailOffset()) {
      return this.tail[i - this._tailOffset()];
    }

    // Trie path: walk down `shift` levels, 5 bits at a time.
    let node = this.root;
    let level = this.shift;
    while (level > 5) {
      node = node.array[(i >>> level) & MASK];
      level -= 5;
    }
    const leaf = node.array[(i >>> 5) & MASK];
    return leaf.array[i & MASK];
  }

  // ---------- update (path copying) ----------

  set(i, value) {
    if (i < 0 || i >= this.size) return this;

    // Tail update: clone only the tail.
    if (i >= this._tailOffset()) {
      const newTail = this.tail.slice();
      newTail[i - this._tailOffset()] = value;
      return new PersistentVector(this.size, this.shift, this.root, newTail);
    }

    // Trie update: clone each node along the path.
    const newRoot = this._assoc(this.shift, this.root, i, value);
    return new PersistentVector(this.size, this.shift, newRoot, this.tail);
  }

  _assoc(shift, node, i, value) {
    const n = new Node(node.array.slice());

    if (shift === 5) {
      // node.array contains leaf arrays
      const leafIndex = (i >>> 5) & MASK;
      const leaf = n.array[leafIndex];
      const newLeaf = new Node(leaf.array.slice());
      newLeaf.array[i & MASK] = value;
      n.array[leafIndex] = newLeaf;
      return n;
    }

    const childIndex = (i >>> shift) & MASK;
    n.array[childIndex] = this._assoc(shift - 5, node.array[childIndex], i, value);
    return n;
  }

  // ---------- push (amortized O(1), structural sharing) ----------

  push(value) {
    // Room in tail: just append (clone tail).
    if (this.tail.length < BRANCH) {
      const newTail = this.tail.slice();
      newTail.push(value);
      return new PersistentVector(this.size + 1, this.shift, this.root, newTail);
    }

    // Tail is full: move it into the trie, start a fresh tail.
    const tailOffset = this.size - this.tail.length; // first index of the old tail
    let shift = this.shift;
    let root = this.root;

    // Ensure a root node exists.
    if (root === null) {
      root = new Node(new Array(BRANCH));
    }

    // Grow the trie height if the new block does not fit.
    const blockIndex = tailOffset / BRANCH;
    while (blockIndex >= (1 << shift)) {
      const newRoot = new Node(new Array(BRANCH));
      newRoot.array[0] = root;
      root = newRoot;
      shift += 5;
    }

    // Insert the old tail as a leaf at `tailOffset`.
    root = this._insertLeaf(shift, root, new Node(this.tail.slice()), tailOffset);

    const newTail = [value];
    return new PersistentVector(this.size + 1, shift, root, newTail);
  }

  _insertLeaf(shift, node, leaf, index) {
    const n = this._cloneNode(node);

    if (shift === 5) {
      n.array[(index >>> 5) & MASK] = leaf;
      return n;
    }

    const childIndex = (index >>> shift) & MASK;
    const child = n.array[childIndex];
    n.array[childIndex] = this._insertLeaf(shift - 5, child, leaf, index);
    return n;
  }

  // ---------- pop ----------

  pop() {
    if (this.size === 0) return this;

    // More than one element in tail: drop the last.
    if (this.tail.length > 1) {
      const newTail = this.tail.slice(0, this.tail.length - 1);
      return new PersistentVector(this.size - 1, this.shift, this.root, newTail);
    }

    // Single element in tail.
    if (this.size === 1) return PersistentVector.empty();

    const newSize = this.size - 1;
    const trieSize = newSize; // elements now entirely in trie

    // Pull the last trie leaf into the tail.
    const lastBlockIndex = (trieSize - 1) >>> 5;
    const leaf = this._leafAt(this.shift, this.root, lastBlockIndex);
    const elemsInLastBlock = trieSize - (lastBlockIndex << 5);
    const newTail = leaf.array.slice(0, elemsInLastBlock);

    // Remove that leaf from the trie (path copying).
    let newRoot = this._removeLeaf(this.shift, this.root, lastBlockIndex << 5);
    let newShift = this.shift;

    // If the trie is now empty, drop it.
    if (newSize <= BRANCH) {
      newRoot = null;
      newShift = 5;
    }

    return new PersistentVector(newSize, newShift, newRoot, newTail);
  }

  _leafAt(shift, node, blockIndex) {
    const i = blockIndex * BRANCH;
    let n = node;
    let level = shift;
    while (level > 5) {
      n = n.array[(i >>> level) & MASK];
      level -= 5;
    }
    return n.array[(i >>> 5) & MASK];
  }

  _removeLeaf(shift, node, index) {
    const n = new Node(node.array.slice());
    if (shift === 5) {
      n.array[(index >>> 5) & MASK] = undefined;
      return n;
    }
    const childIndex = (index >>> shift) & MASK;
    n.array[childIndex] = this._removeLeaf(shift - 5, node.array[childIndex], index);
    return n;
  }

  // ---------- iteration / conversion ----------

  toArray() {
    const out = new Array(this.size);
    for (let i = 0; i < this.size; i++) out[i] = this.get(i);
    return out;
  }

  forEach(fn) {
    for (let i = 0; i < this.size; i++) fn(this.get(i), i, this);
  }

  map(fn) {
    let v = PersistentVector.empty();
    for (let i = 0; i < this.size; i++) v = v.push(fn(this.get(i), i, this));
    return v;
  }

  [Symbol.iterator]() {
    let i = 0;
    const size = this.size;
    const get = (idx) => this.get(idx);
    return {
      next() {
        if (i < size) return { value: get(i++), done: false };
        return { value: undefined, done: true };
      },
    };
  }

  toString() {
    return `PersistentVector(${this.toArray().join(', ')})`;
  }
}
```

### Usage example

```js
const v0 = PersistentVector.from([1, 2, 3]);
const v1 = v0.push(4);          // structural sharing
const v2 = v1.set(1, 99);

console.log(v0.toArray()); // [1, 2, 3]
console.log(v1.toArray()); // [1, 2, 3, 4]
console.log(v2.toArray()); // [1, 99, 3, 4]

console.log(v0 === v1);    // false (different versions)
console.log(v0.get(0));    // 1 (old version untouched)

// Iteration
for (const x of v2) console.log(x); // 1 99 3 4

// Undo is free: just keep the old reference
const previous = v1;
```

### Complexity summary

| Operation | Time | Space (new nodes) |
|---|---|---|
| `get(i)` | O(log₃₂ n) ≈ O(1) | O(1) |
| `set(i, v)` | O(log₃₂ n) | O(log₃₂ n) |
| `push(v)` | amortized O(1) | O(1) amortized |
| `pop()` | O(log₃₂ n) | O(log₃₂ n) |
| equality (`a === b`) | O(1) | — |

### How this extends to Maps / Sets

The same idea generalizes to **persistent hash maps** (HAMT): a 32-way trie keyed by hash bits, where leaves store key/value pairs and collisions become small arrays. Updates clone only the path from root to the affected leaf, sharing everything else. Sets are just maps with a sentinel value.

### Interview talking points

1. **Why 32?** Balances tree height (≈ 6–7 for millions of elements) against node size and cache locality.
2. **Tail buffer** makes `push` effectively O(1) amortized and improves locality for recent elements.
3. **Structural sharing** is what makes immutability affordable; without it, immutable updates would be O(n).
4. **Trade-off:** Higher memory overhead and slightly slower single operations than mutable arrays, but vastly cheaper versioning and equality checks.

# Edge cases when using “immutable” data structures in JavaScript

JavaScript has no built-in deep immutability. `Object.freeze`, spread syntax, and most “immutable update” patterns are **shallow** by default, and several built-in types have mutable internal state that freezing does not touch.

Below are the important edge cases, with examples.

---

## 1. `Object.freeze` is shallow

Freezing an object prevents adding/removing/changing its **own top-level properties**, but nested objects remain mutable.

```js
const user = { profile: { name: "Ada" } };
const frozen = Object.freeze(user);

frozen.profile.name = "Grace"; // allowed
console.log(frozen.profile.name); // "Grace"

// Also note: freeze is in-place
console.log(user === frozen); // true
```

**Handle it:** use a recursive deep-freeze for plain objects/arrays, or prefer a library such as Immer/Immutable.js.

```js
function deepFreeze(value, seen = new WeakSet()) {
  if (value === null || typeof value !== "object") return value;
  if (seen.has(value)) return value; // circular reference guard

  seen.add(value);

  if (Array.isArray(value)) {
    value.forEach((v, i) => {
      value[i] = deepFreeze(v, seen);
    });
  } else {
    // Include symbol-keyed properties too
    [...Object.keys(value), ...Object.getOwnPropertySymbols(value)].forEach(key => {
      value[key] = deepFreeze(value[key], seen);
    });
  }

  return Object.freeze(value);
}
```

---

## 2. Circular references break naive deep clone/freeze

A recursive deep operation without a `seen` set will stack-overflow.

```js
const a = {};
a.self = a;

// Without a WeakSet/WeakMap guard:
// deepClone(a) -> infinite recursion
```

The `seen` WeakSet in `deepFreeze` above handles this. For cloning, use the same pattern:

```js
function deepClone(value, seen = new WeakMap()) {
  if (value === null || typeof value !== "object") return value;
  if (seen.has(value)) return seen.get(value);

  let clone;
  if (Array.isArray(value)) clone = [];
  else if (value instanceof Date) clone = new Date(value.getTime());
  else if (value instanceof Map) clone = new Map();
  else if (value instanceof Set) clone = new Set();
  else clone = {};

  seen.set(value, clone);

  if (Array.isArray(value)) {
    value.forEach((v, i) => clone[i] = deepClone(v, seen));
  } else if (value instanceof Date) {
    // already cloned
  } else if (value instanceof Map) {
    for (const [k, v] of value) clone.set(deepClone(k, seen), deepClone(v, seen));
  } else if (value instanceof Set) {
    for (const v of value) clone.add(deepClone(v, seen));
  } else {
    for (const key of [...Object.keys(value), ...Object.getOwnPropertySymbols(value)]) {
      clone[key] = deepClone(value[key], seen);
    }
  }

  return clone;
}
```

---

## 3. Built-in mutable objects are not frozen by `Object.freeze`

`Date`, `RegExp`, `Map`, `Set`, typed arrays, and `ArrayBuffer` store mutable state in internal slots. Freezing only affects ordinary properties.

```js
const d = new Date();
Object.freeze(d);
d.setDate(d.getDate() + 1); // still works

const m = new Map([["x", 1]]);
Object.freeze(m);
m.set("x", 2); // still works

const arr = new Uint8Array([1, 2, 3]);
Object.freeze(arr);
arr[0] = 9; // may still be mutable depending on engine/exotic behavior
```

**Handle it:** clone instead of sharing, and treat the original as private.

```js
function immutableDate(d) {
  return new Date(d.getTime()); // return a fresh copy to callers
}

function immutableMap(m) {
  return new Map(m); // shallow copy; deep-clone values if needed
}
```

For true immutability, convert mutable built-ins to plain serializable values where possible:

```js
const state = {
  createdAt: date.getTime(), // number instead of Date
  selectedIds: [...set],     // array instead of Set
};
```

---

## 4. Array methods that mutate

`push`, `pop`, `shift`, `unshift`, `splice`, `sort`, `reverse`, and direct index assignment mutate arrays.

```js
const items = [3, 1, 2];
const sorted = items.sort(); // mutates items too
```

**Handle it:** copy first, then mutate the copy.

```js
const items = [3, 1, 2];
const sorted = [...items].sort((a, b) => a - b);
const reversed = items.toReversed(); // ES2023 non-mutating
const withoutFirst = items.slice(1);  // non-mutating
```

Useful non-mutating alternatives: `toSorted`, `toReversed`, `toSpliced`, `with`.

```js
const next = items.with(1, 99); // replace index 1 immutably
```

---

## 5. Nested immutable updates require copying every level on the path

A common bug is updating a nested field by mutating a shared reference.

```js
const state = {
  user: { name: "Ada", tags: ["admin"] },
};

// BAD: mutates shared nested object
state.user.name = "Grace";

// GOOD: new references along changed path only
const next = {
  ...state,
  user: {
    ...state.user,
    name: "Grace",
    tags: [...state.user.tags, "editor"],
  },
};
```

Unchanged branches keep their references (structural sharing), which is important for performance and equality checks.

---

## 6. Symbols, non-enumerable properties, and getters are easy to miss

`Object.keys`, spread, and `JSON.stringify` do not handle all property kinds correctly.

```js
const sym = Symbol("id");
const obj = {
  [sym]: { x: 1 },
  get random() { return Math.random(); },
};

Object.defineProperty(obj, "hidden", {
  value: { y: 2 },
  enumerable: false,
});

const copy = { ...obj };
console.log(copy[sym]);      // copied if enumerable symbol
console.log(copy.hidden);    // undefined
console.log(copy.random);    // getter copied, still random each access
```

**Handle it:** enumerate symbols and own property descriptors when cloning.

```js
function cloneOwnProps(value) {
  const clone = {};
  for (const key of Object.getOwnPropertyNames(value)) {
    clone[key] = value[key];
  }
  for (const sym of Object.getOwnPropertySymbols(value)) {
    clone[sym] = value[sym];
  }
  return clone;
}
```

For getters, decide whether to preserve getter behavior or snapshot the value. For immutable data, usually snapshot:

```js
function snapshotGetters(obj) {
  const out = {};
  for (const key of Object.keys(obj)) {
    out[key] = obj[key]; // invokes getter once
  }
  return out;
}
```

---

## 7. Prototypes and inheritance

`Object.freeze(obj)` does not freeze its prototype.

```js
const proto = { shared: { count: 0 } };
const obj = Object.create(proto);
Object.freeze(obj);

proto.shared.count = 5; // allowed
```

**Handle it:** freeze the prototype too, or avoid prototype-based mutable shared state in immutable designs.

```js
Object.freeze(Object.getPrototypeOf(obj));
```

Also avoid relying on `__proto__` mutation; use `Object.create` and immutable extension.

---

## 8. `seal`, `freeze`, and `preventExtensions` are different

```js
const a = { x: 1 };

Object.preventExtensions(a); // cannot add props, but can change/remove existing
const b = { x: 1 };
Object.seal(b);              // cannot add/remove, but can change existing values
const c = { x: 1 };
Object.freeze(c);             // cannot add/remove/change
```

Choosing the wrong one creates false confidence.

---

## 9. Proxy objects can throw or behave unexpectedly

Freezing or cloning a Proxy may trigger traps.

```js
const p = new Proxy({}, {
  set() { throw new Error("no writes"); },
  getPrototypeOf() { return null; },
});

try {
  Object.freeze(p);
} catch (e) {
  console.error("freeze failed:", e.message);
}
```

**Handle it:** test proxy-based objects separately; do not assume they support all `Object.*` operations.

---

## 10. toJSON, serialization, and circular references

`JSON.stringify` throws on circular references and drops `undefined`, functions, and symbols. `BigInt` throws unless handled.

```js
const state = {
  count: 1n,          // BigInt
  fn: () => 1,        // function
  undef: undefined,   // dropped
  self: null,
};
state.self = state;

try {
  JSON.stringify(state);
} catch (e) {
  console.error(e.message); // Converting circular structure to JSON
}
```

**Handle it:** use a replacer and remove/transform unsupported values.

```js
function serialize(value) {
  const seen = new WeakSet();
  return JSON.stringify(value, (key, val) => {
    if (typeof val === "bigint") return val.toString();
    if (typeof val === "function") return undefined;
    if (typeof val === "symbol") return val.toString();
    if (typeof val === "object" && val !== null) {
      if (seen.has(val)) return "[Circular]";
      seen.add(val);
    }
    return val;
  });
}
```

---

## 11. Equality and identity

Immutable data should use reference equality (`===`) for “changed?” checks. But deep equality is sometimes needed, and it can be expensive or wrong for special values.

```js
const a = { x: NaN };
const b = { x: NaN };

console.log(a === b);        // false
console.log(a.x === b.x);    // false, even though both NaN
console.log(Object.is(a.x, b.x)); // true
```

**Handle it:**

- Use `Object.is` for primitive value comparison.
- Use reference equality for immutable objects.
- Avoid deep equality in hot paths; rely on structural sharing and changed references.

---

## 12. Functions and closures are not data

You can freeze a function object, but you cannot freeze its closure state.

```js
function makeCounter() {
  let n = 0;
  const fn = () => ++n;
  Object.freeze(fn);
  return fn;
}

const c = makeCounter();
console.log(c(), c()); // 1, 2 (mutable closure state)
```

**Handle it:** keep mutable behavior separate from immutable state; store counters/state in immutable structures and return new state.

---

## 13. Host objects may reject freezing

DOM nodes and other host objects often cannot be frozen or cloned reliably.

```js
try {
  Object.freeze(document.body);
} catch (e) {
  console.error("host object freeze failed");
}
```

**Handle it:** never put host objects inside immutable state. Store IDs/selectors instead.

---

## 14. Concurrency and async snapshots

Immutable references are safe to share across async boundaries, but only if they are **truly** immutable. A shallow copy can still be mutated by another async task.

```js
const state = { items: [1, 2, 3] };
const snapshot = { ...state }; // shallow

// Another task mutates nested array
state.items.push(4);

console.log(snapshot.items); // [1, 2, 3, 4] (shared)
```

**Handle it:** deep-clone or deep-freeze before crossing async boundaries, or use persistent data structures.

---

## 15. Performance and memory

Deep copying large graphs is expensive and can duplicate shared subtrees.

```js
const big = { data: new Array(1_000_000).fill(0) };
const copy = structuredClone(big); // expensive
```

**Handle it:**

- Use structural sharing for updates.
- Use `structuredClone` when you need a true deep copy of supported types.
- Consider Immutable.js or Immer for persistent/structural-sharing semantics.

```js
import produce from "immer";

const base = { a: { b: 1 }, c: [1, 2] };
const next = produce(base, draft => {
  draft.a.b = 2; // Immer tracks and creates new references
});
```

---

## Practical checklist

- Treat `Object.freeze` as **shallow**.
- Deep-freeze only plain objects/arrays; handle `Date`, `Map`, `Set`, typed arrays separately.
- Guard recursive operations against circular references.
- Copy arrays before `sort`, `reverse`, `splice`.
- Update nested data by copying each level on the changed path.
- Include symbols and non-enumerable descriptors when cloning.
- Freeze prototypes if prototype state matters.
- Do not store functions, host objects, or mutable built-ins in immutable state.
- Use `structuredClone` or libraries for complex cloning.
- Use reference equality for immutable objects and `Object.is` for primitives.

If you want, I can also show a production-ready `deepFreeze`/`deepClone` utility that handles all of these cases, or compare Immer vs Immutable.js for a specific use case.

# Inheritance in JavaScript

JavaScript uses **prototypal inheritance**: objects inherit from other objects via an internal `[[Prototype]]` link (exposed as `__proto__` / `Object.getPrototypeOf`). The `class` syntax introduced in ES2015 is syntactic sugar over this mechanism. Below are three complete, runnable approaches, from modern to foundational.

---

## 1. Modern approach: ES6 `class` + `extends` (recommended)

```js
// base.js — runnable in Node or browser console

class Animal {
  // Private field (ES2022) — truly private, not accessible outside
  #energy = 100;

  constructor(name) {
    if (new.target === Animal) {
      // optional: prevent direct instantiation of abstract-ish base
    }
    this.name = name;
  }

  // instance method
  speak() {
    return `${this.name} makes a sound.`;
  }

  // getter / setter
  get energy() {
    return this.#energy;
  }
  set energy(v) {
    this.#energy = Math.max(0, Math.min(100, v));
  }

  eat(amount = 10) {
    this.#energy = Math.min(100, this.#energy + amount);
    return this;
  }

  // static method — inherited by subclasses
  static isAnimal(x) {
    return x instanceof Animal;
  }

  // static factory
  static create(name) {
    return new this(name); // `this` = the subclass when called as Dog.create()
  }
}

class Dog extends Animal {
  constructor(name, breed) {
    super(name);            // MUST call before using `this`
    this.breed = breed;
  }

  // override
  speak() {
    return `${this.name} barks.`;
  }

  // new method
  fetch(item) {
    this.energy -= 5;
    return `${this.name} fetches ${item}.`;
  }

  // override + extend via super
  eat(amount = 10) {
    super.eat(amount);
    return `${this.name} happily eats.`;
  }
}

class Cat extends Animal {
  speak() {
    return `${this.name} meows.`;
  }
}

// ---------- usage ----------
const rex = new Dog("Rex", "Labrador");
console.log(rex.speak());          // Rex barks.
console.log(rex.fetch("ball"));    // Rex fetches ball.
console.log(rex.eat(20));          // Rex happily eats.
console.log("energy:", rex.energy); // energy: 100 (capped)

const whiskers = new Cat("Whiskers");
console.log(whiskers.speak());     // Whiskers meows.

// polymorphism
const animals = [rex, whiskers, Animal.create("Generic")];
for (const a of animals) console.log(a.speak());

// introspection
console.log(rex instanceof Dog);            // true
console.log(rex instanceof Animal);         // true
console.log(Object.getPrototypeOf(rex) === Dog.prototype); // true
console.log(Object.getPrototypeOf(Dog.prototype) === Animal.prototype); // true
console.log(Dog.isAnimal(rex));            // true (static inherited)
console.log(Animal.isAnimal(rex));         // true

// private field is truly private
console.log("#energy" in rex);              // false
// rex.#energy;                            // SyntaxError if uncommented
```

**Key rules of `class`/`extends`:**
- In a derived constructor, you must call `super(...)` before accessing `this`.
- `super.method()` invokes the parent's version.
- Methods defined in the class body go on the prototype (shared, memory-efficient).
- Fields initialized in the constructor become own properties.
- Private fields (`#name`) are per-instance and inaccessible from subclasses or outside.

---

## 2. Classic approach: constructor functions + prototype

This is what `class` compiles to under the hood. Still useful to understand (and required in older environments).

```js
function Animal(name) {
  this.name = name;
}
Animal.prototype.speak = function () {
  return this.name + " makes a sound.";
};
Animal.prototype.eat = function (amount) {
  amount = amount || 10;
  this.energy = Math.min(100, (this.energy || 0) + amount);
  return this;
};

function Dog(name, breed) {
  Animal.call(this, name);   // call parent constructor with correct `this`
  this.breed = breed;
}
// wire up the prototype chain
Dog.prototype = Object.create(Animal.prototype);
Dog.prototype.constructor = Dog; // restore constructor reference
Dog.prototype.speak = function () {
  return this.name + " barks.";
};
Dog.prototype.fetch = function (item) {
  this.energy -= 5;
  return this.name + " fetches " + item + ".";
};

const r2 = new Dog("Rex2", "Beagle");
console.log(r2.speak());            // Rex2 barks.
console.log(r2 instanceof Animal);  // true
console.log(r2 instanceof Dog);     // true
console.log(r2.constructor === Dog); // true  (thanks to restoring constructor)
```

**Pitfalls to avoid here:**
- `Dog.prototype = Animal.prototype;` would make them the *same* object — mutations affect both. Always use `Object.create(Animal.prototype)`.
- Forgetting to restore `.constructor` makes `instance.constructor` point at `Animal`.
- Forgetting `Animal.call(this, ...)` means parent initialization never runs.

---

## 3. Pure prototypal inheritance with `Object.create`

No constructors, no `new` — just objects delegating to other objects.

```js
const animalProto = {
  init(name) {
    this.name = name;
    this.energy = 100;
    return this; // allow chaining: Object.create(proto).init("x")
  },
  speak() {
    return `${this.name} makes a sound.`;
  },
  eat(amount = 10) {
    this.energy = Math.min(100, this.energy + amount);
    return this;
  },
};

const dogProto = Object.create(animalProto);
dogProto.speak = function () {
  return `${this.name} barks.`;
};
dogProto.fetch = function (item) {
  this.energy -= 5;
  return `${this.name} fetches ${item}.`;
};

const buddy = Object.create(dogProto).init("Buddy", "Mixed");
console.log(buddy.speak());        // Buddy barks.
console.log(buddy.fetch("stick")); // Buddy fetches stick.
console.log(Object.getPrototypeOf(buddy) === dogProto); // true
```

This style is what powers most of JS's built-in objects (e.g., `Array.prototype`).

---

## 4. Common pitfalls & best practices

| Pitfall | Why it breaks | Fix |
|---|---|---|
| `new Dog()` forgotten | `this` is `undefined` (strict) or global | Always use `new`; or factory that guards |
| Arrow function as method | `this` is lexically bound to outer scope | Use regular methods in classes, or bind |
| Mutating a shared prototype after instances exist | Affects every instance (can be intended, but surprising) | Add to prototype before creating instances, or use own props |
| `class` hoisting | Classes are **not** hoisted (TDZ) | Define before use |
| Calling `super()` twice or after `this` | SyntaxError / ReferenceError | Call once, first line of derived constructor |
| Overriding without `super` | Loses parent behavior | Call `super.method()` when extending |
| `instanceof` across iframes/realms | Different constructors → false | Use `Object.prototype.toString` or duck-typing for cross-realm |

### Checking the chain programmatically

```js
function describeChain(obj) {
  const chain = [];
  let cur = Object.getPrototypeOf(obj);
  while (cur && cur !== Object.prototype) {
    chain.push(cur.constructor?.name || "(anonymous)");
    cur = Object.getPrototypeOf(cur);
  }
  chain.push("Object");
  return chain.join(" → ");
}
console.log(describeChain(rex)); // Dog → Animal → Object
```

### Mixins (multiple inheritance workaround)

JS has single inheritance. Compose behavior with mixins:

```js
const Swimmer = (Base) =>
  class extends Base {
    swim() { return `${this.name} swims.`; }
  };
const Flyer = (Base) =>
  class extends Base {
    fly() { return `${this.name} flies.`; }
  };

class Duck extends Flyer(Swimmer(Animal)) {}
const d = new Duck("Donald");
console.log(d.speak(), d.swim(), d.fly());
```

---

## Summary

- **Prefer ES6 `class`/`extends`** for new code — readable, supports private fields, statics, getters.
- **Understand the prototype chain** (`Object.getPrototypeOf`, `instanceof`, `constructor`) — it's what makes everything work.
- **Use `Object.create`** for lightweight, constructor-free delegation.
- **Avoid** mutating prototypes of built-ins or of already-instantiated classes in hot paths; **prefer composition/mixins** over deep hierarchies.

All snippets above are self-contained and run as-is in Node ≥ 14 (private fields need ≥ 12, static fields ≥ 16 for some; the examples use stable features available in modern Node/Browsers).

# Inheritance in JavaScript

JavaScript uses **prototypal inheritance**: objects delegate behavior to other objects through a hidden `[[Prototype]]` link, not classical class-based copying. ES6 `class` syntax is “sugar” over this prototype mechanism.

---

## 1. Core Idea

When you access a property on an object, JS first checks the object itself. If not found, it walks up the **prototype chain** until it finds the property or reaches `null`.

```js
const animal = { eats: true };
const rabbit = Object.create(animal);
rabbit.jumps = true;

console.log(rabbit.eats);   // true (found on prototype)
console.log(rabbit.jumps);  // true (own property)
```

---

## 2. Constructor Functions + Prototype (Pre-ES6)

```js
function Animal(name) {
  this.name = name;
}

Animal.prototype.speak = function () {
  return `${this.name} makes a sound`;
};

function Dog(name, breed) {
  Animal.call(this, name);   // call parent constructor
  this.breed = breed;
}

// Link Dog's prototype to Animal's prototype
Dog.prototype = Object.create(Animal.prototype);
Dog.prototype.constructor = Dog;

Dog.prototype.speak = function () {
  return `${this.name} barks`;
};

const d = new Dog("Rex", "Shepherd");
console.log(d.speak());          // Rex barks
console.log(d instanceof Dog);   // true
console.log(d instanceof Animal); // true
```

Key points:

- `Object.create(Animal.prototype)` creates a new object whose prototype is `Animal.prototype`.
- `Animal.call(this, ...) ` runs the parent constructor in child context.
- Restore `constructor` to keep `instanceof`/identity meaningful.

---

## 3. ES6 `class` Syntax (Recommended)

```js
class Animal {
  constructor(name) {
    this.name = name;
  }
  speak() {
    return `${this.name} makes a sound`;
  }
}

class Dog extends Animal {
  constructor(name, breed) {
    super(name);          // must call before using this
    this.breed = breed;
  }
  speak() {
    return `${this.name} barks`; // override
  }
  fetch() {
    return `${this.name} fetches`;
  }
}

const d = new Dog("Rex", "Shepherd");
console.log(d.speak());   // Rex barks
console.log(d.fetch());    // Rex fetches
console.log(d instanceof Animal); // true
```

- `extends` sets up the prototype chain automatically.
- `super()` invokes the parent constructor.
- `super.method()` can call parent methods.

---

## 4. Method Overriding & `super`

```js
class Rectangle {
  constructor(w, h) { this.w = w; this.h = h; }
  area() { return this.w * this.h; }
}

class Square extends Rectangle {
  constructor(side) { super(side, side); }
  area() {
    const base = super.area(); // reuse parent logic
    return base;
  }
}
```

---

## 5. Static Members

```js
class MathUtils {
  static add(a, b) { return a + b; }
}
class AdvancedMath extends MathUtils {
  static multiply(a, b) { return a * b; }
}

console.log(AdvancedMath.add(2, 3));      // 5 (inherited static)
console.log(AdvancedMath.multiply(2,3)); // 6
```

---

## 6. Private Fields & Encapsulation (Modern JS)

```js
class BankAccount {
  #balance = 0;              // truly private
  constructor(initial) { this.#balance = initial; }
  deposit(n) { this.#balance += n; }
  get balance() { return this.#balance; }
}

class SavingsAccount extends BankAccount {
  constructor(initial, rate) {
    super(initial);
    this.rate = rate;
  }
  // Cannot access #balance directly here
}
```

Private fields are **not inherited** as accessible members; subclasses interact via public methods/getters.

---

## 7. Mixins (Multiple Behavior Composition)

JS has single inheritance via `extends`, but you can compose behavior:

```js
const CanFly = (Base) => class extends Base {
  fly() { return `${this.name} flies`; }
};

const CanSwim = (Base) => class extends Base {
  swim() { return `${this.name} swims`; }
};

class Animal { constructor(name) { this.name = name; } }

class Duck extends CanFly(CanSwim(Animal)) {}

const d = new Duck("Donald");
console.log(d.fly());  // Donald flies
console.log(d.swim()); // Donald swims
```

---

## 8. Typical Use Cases

| Use case | Pattern |
|---|---|
| Domain models (User → Admin) | `class Admin extends User` |
| Extending built-ins (careful) | `class MyArray extends Array` |
| Framework components | React: `class MyComp extends React.Component` |
| Sharing utility behavior | Mixins for cross-cutting concerns |
| Polymorphism / template method | Base defines algorithm, subclass overrides steps |

---

## 9. Gotchas

- **`this` binding**: methods passed as callbacks lose `this`; use arrow functions or bind.
- **Extending built-ins** (e.g., `Array`, `Error`) works in modern engines but can have edge cases with some internals.
- **Prototype mutation after creation** affects all instances; use carefully.
- Prefer **composition over deep inheritance**; deep hierarchies become hard to maintain.

---

## Summary

- **Idea**: delegation via prototype chain.
- **Syntax**: ES6 `class`/`extends`/`super` over constructor+prototype.
- **Best practice**: use classes for clear hierarchies, mixins/composition for flexible reuse, and keep inheritance shallow.

## Typical mistake: “inheritance by prototype only” (forgot to call the parent constructor)

### ❌ Buggy version

```js
function Animal(name) {
  this.name = name;
}

Animal.prototype.speak = function () {
  return `${this.name} makes a sound`;
};

function Dog(name, breed) {
  // BUG: never calls Animal(...)
  this.breed = breed;
}

// BUG: prototype chain is set, but `constructor` is now Animal, not Dog
Dog.prototype = Object.create(Animal.prototype);

Dog.prototype.bark = function () {
  return `${this.name} barks`;
};

const d = new Dog('Rex', 'Labrador');

console.log(d.bark());   // "undefined barks"  (name was never set)
console.log(d.speak());  // "undefined makes a sound"
console.log(d.constructor === Dog); // false (it's Animal)
```

### ✅ Corrected version

```js
function Animal(name) {
  this.name = name;
}

Animal.prototype.speak = function () {
  return `${this.name} makes a sound`;
};

function Dog(name, breed) {
  // 1. Initialize parent state on THIS instance
  Animal.call(this, name);

  // 2. Then add child-specific state
  this.breed = breed;
}

// 3. Set up prototype chain WITHOUT invoking Animal as a constructor
Dog.prototype = Object.create(Animal.prototype);

// 4. Restore the constructor reference
Dog.prototype.constructor = Dog;

Dog.prototype.bark = function () {
  return `${this.name} barks`;
};

const d = new Dog('Rex', 'Labrador');

console.log(d.bark());   // "Rex barks"
console.log(d.speak());  // "Rex makes a sound"
console.log(d.constructor === Dog); // true
console.log(d instanceof Animal);   // true
console.log(d instanceof Dog);     // true
```

---

## What was wrong and why

### 1. The parent constructor was never invoked
Setting `Dog.prototype = Object.create(Animal.prototype)` only links **methods** (the prototype chain). It does **not** run `Animal`, so instance properties like `this.name` are never created on the `Dog` instance.

Fix: call the parent constructor with the child’s `this`:

```js
Animal.call(this, name);
```

This is the classic “pseudo-classical inheritance” pattern in pre-ES6 JavaScript.

---

### 2. `constructor` got clobbered
`Object.create(Animal.prototype)` creates a new object whose internal prototype is `Animal.prototype`. That new object has no own `constructor` property, so JavaScript walks the chain and finds `Animal.prototype.constructor`, which is `Animal`.

Consequences:
- `d.constructor === Dog` becomes `false`
- Some libraries/frameworks rely on `constructor` for cloning, type checks, or serialization.
- `instanceof Dog` still works (because it checks the prototype chain, not `constructor`), but code that uses `.constructor` breaks.

Fix:

```js
Dog.prototype.constructor = Dog;
```

---

### 3. Why not just do `Dog.prototype = new Animal()`?
A common older mistake is:

```js
Dog.prototype = new Animal(); // ❌ runs Animal as a constructor
```

Problems:
- It executes `Animal` immediately, possibly with `undefined` arguments.
- If `Animal` has side effects (logging, network calls, DOM access), they run at **class definition time**, not instance creation time.
- It can create shared mutable state if `Animal` initializes arrays/objects on `this` (they end up on the prototype, shared by all instances).

`Object.create(Animal.prototype)` avoids all of that: it only links prototypes, no constructor execution.

---

## Modern alternative (ES6 classes)
Today you’d usually write this with `class`, which handles the above correctly:

```js
class Animal {
  constructor(name) {
    this.name = name;
  }
  speak() {
    return `${this.name} makes a sound`;
  }
}

class Dog extends Animal {
  constructor(name, breed) {
    super(name);          // calls Animal constructor with this bound
    this.breed = breed;
  }
  bark() {
    return `${this.name} barks`;
  }
}

const d = new Dog('Rex', 'Labrador');
console.log(d.bark()); // "Rex barks"
console.log(d instanceof Dog);    // true
console.log(d instanceof Animal);  // true
```

`extends` + `super()` takes care of both:
- invoking the parent constructor with the right `this`
- maintaining the correct `constructor` and prototype chain.

---

## Bonus: another very common inheritance bug — shared mutable prototype state

```js
function Team() {}
Team.prototype.members = []; // ❌ shared array on prototype

const a = new Team();
const b = new Team();
a.members.push('Alice');
console.log(b.members); // ['Alice']  ← unexpected sharing
```

Fix: initialize per-instance in the constructor:

```js
function Team() {
  this.members = []; // ✅ own property per instance
}
```

Below are common inheritance pitfalls in JavaScript, with runnable examples and fixes.

## 1. Calling a constructor function without `new`

Constructor functions rely on `this`. Without `new`, `this` is `undefined` in strict mode (or the global object in sloppy mode), so the instance is never created.

```js
function Animal(name) {
  this.name = name;
}

const a = Animal("Rex"); // forgot new
console.log(a);          // undefined
// In strict mode: TypeError: Cannot set properties of undefined
```

**Fix:** use `new`, or better, use `class`, which throws if called without `new`:

```js
class Animal {
  constructor(name) { this.name = name; }
}
// Animal("Rex"); // TypeError: Class constructor Animal cannot be invoked without 'new'
```

---

## 2. Forgetting to call the parent constructor

In constructor functions, subclass constructors do not automatically call the parent constructor.

```js
function Parent(name) {
  this.name = name;
}

function Child(name, age) {
  // forgot: Parent.call(this, name);
  this.age = age;
}

const c = new Child("Rex", 3);
console.log(c.name); // undefined
```

**Fix:**

```js
function Child(name, age) {
  Parent.call(this, name); // initialize parent state
  this.age = age;
}
```

With classes, forgetting `super()` in a derived constructor is a `ReferenceError` before you can use `this`:

```js
class Child extends Parent {
  constructor(name, age) {
    // this.age = age; // ReferenceError: Must call super constructor first
    super(name);
    this.age = age;
  }
}
```

---

## 3. Losing the `constructor` property after replacing the prototype

A very common bug when wiring inheritance manually.

```js
function Parent() {}
function Child() {}

Child.prototype = Object.create(Parent.prototype);

const c = new Child();
console.log(c.constructor === Child); // false
console.log(c.constructor === Parent); // true
```

**Fix:** restore `constructor`:

```js
Child.prototype = Object.create(Parent.prototype);
Child.prototype.constructor = Child;
```

---

## 4. Shared mutable state on the prototype

Properties placed on the prototype are shared by all instances. Mutable objects there become shared state.

```js
function Animal() {}
Animal.prototype.traits = []; // shared array

const a = new Animal();
const b = new Animal();

a.traits.push("friendly");
console.log(b.traits); // ["friendly"]  (unexpected)
```

**Fix:** initialize per-instance data in the constructor:

```js
function Animal() {
  this.traits = []; // own property per instance
}
```

---

## 5. Losing `this` when passing a method as a callback

Methods are not bound to their instance. Extracting them loses `this`.

```js
class Counter {
  constructor() { this.n = 0; }
  inc() { this.n++; }
}

const c = new Counter();
const inc = c.inc;
inc(); // TypeError: Cannot read properties of undefined (strict mode)
```

**Fixes:**

```js
// bind explicitly
const inc = c.inc.bind(c);

// or define as an own arrow-function field (per-instance, higher memory)
class Counter {
  constructor() { this.n = 0; }
  inc = () => { this.n++; };
}
```

Trade-off: arrow fields are not on the prototype, so they cost memory per instance and are not shared.

---

## 6. `for...in` enumerates inherited enumerable properties

```js
function Base() {}
Base.prototype.shared = 1;

const o = new Base();
o.own = 2;

for (const key in o) {
  console.log(key); // "own", then "shared"
}
```

**Fix:** filter with `hasOwnProperty`, or use `Object.keys` / `Object.entries`, which only return own enumerable properties:

```js
for (const key of Object.keys(o)) {
  console.log(key); // "own"
}

// or
for (const key in o) {
  if (Object.prototype.hasOwnProperty.call(o, key)) {
    console.log(key);
  }
}
```

Note: class methods are non-enumerable by default, but manually assigned prototype methods are enumerable.

---

## 7. Replacing an instance method with an own property breaks polymorphism expectations

Shadowing a prototype method with an own property can look like overriding, but it changes dispatch and enumeration behavior.

```js
class Base {
  greet() { return "base"; }
}

const x = new Base();
x.greet = () => "instance"; // own data property shadows prototype method

console.log(x.greet()); // "instance"
delete x.greet;
console.log(x.greet()); // "base"
```

This is sometimes useful, but as an accidental override it can hide bugs. Prefer explicit subclass overriding.

---

## 8. Private fields (`#`) are not accessible from subclasses

Private fields are truly private to the declaring class.

```js
class Base {
  #secret = 42;
  getSecret() { return this.#secret; }
}

class Derived extends Base {
  trySecret() {
    // return this.#secret; // SyntaxError: Private field '#secret' must be declared in an enclosing class
    return this.getSecret(); // correct: use public/protected accessor
  }
}
```

**Pitfall:** assuming `#field` behaves like “protected”. It does not; use accessor methods or conventional `_field` (convention only, not enforced).

---

## 9. `super` is lexical and only valid in certain contexts

In derived classes, `super()` must be called before `this` is used. Also, `super.method()` works in regular methods, not in arbitrary nested functions unless they are methods/arrow functions with the right home object.

```js
class Base {
  value() { return 10; }
}

class Derived extends Base {
  value() {
    const fn = () => super.value(); // OK: arrow inherits super from enclosing method
    return fn() + 5;
  }
}

console.log(new Derived().value()); // 15
```

But this throws:

```js
class Derived2 extends Base {
  value() {
    function inner() {
      return super.value(); // SyntaxError: 'super' keyword unexpected here
    }
    return inner();
  }
}
```

**Fix:** use arrow functions or pass values explicitly.

---

## 10. `instanceof` is fragile across realms and prototype tampering

```js
const iframe = document.createElement("iframe");
document.body.appendChild(iframe);
const OtherArray = iframe.contentWindow.Array;

const a = new OtherArray();
console.log(a instanceof Array); // false, even though it is an array-like Array
```

Also, changing prototypes can break `instanceof`:

```js
function A() {}
const x = new A();
Object.setPrototypeOf(x, null);
console.log(x instanceof A); // false
```

**Fix:** prefer duck typing or `Array.isArray`, and avoid mutating prototypes of live objects.

---

## 11. Deep inheritance and the fragile base class problem

Long chains make small base changes ripple through subclasses.

```js
class Animal { move() { return "moving"; } }
class Mammal extends Animal { move() { return super.move() + " on land"; } }
class Dog extends Mammal { move() { return super.move() + " happily"; } }

// Changing Animal.move() can break Dog indirectly.
```

**Mitigation:** favor composition over inheritance:

```js
class Mover { move() { return "moving"; } }

class Dog {
  constructor() { this.mover = new Mover(); }
  move() { return this.mover.move() + " happily"; }
}
```

---

## 12. Static members are inherited, but `this` can surprise you

Static methods are inherited by subclasses, and `this` refers to the class that invoked them.

```js
class Base {
  static create() {
    return new this(); // `this` is the subclass when called as Sub.create()
  }
}

class Sub extends Base {}

const s = Sub.create();
console.log(s instanceof Sub); // true
```

This is often desired, but if you intended `Base` instances, use `new Base()` explicitly.

---

## 13. `Object.create(proto)` creates an object without running a constructor

```js
function Parent(name) { this.name = name; }
const o = Object.create(Parent.prototype);
console.log(o.name); // undefined; constructor never ran
console.log(o instanceof Parent); // true
```

**Pitfall:** assuming `instanceof` implies initialized state. If you need construction, call the constructor explicitly:

```js
Parent.call(o, "Rex");
console.log(o.name); // "Rex"
```

---

## 14. Class declarations are not hoisted

Unlike function declarations, class declarations are in the temporal dead zone until their definition is evaluated.

```js
const x = new Foo(); // ReferenceError: Cannot access 'Foo' before initialization
class Foo {}
```

**Fix:** define classes before use, or use class expressions assigned carefully.

---

### Quick checklist

- Always call `super(...)` / parent constructor before using `this`.
- Restore `constructor` when replacing prototypes.
- Initialize mutable state in constructors, not on prototypes.
- Bind methods or use arrow fields deliberately.
- Guard `for...in` with `hasOwnProperty` or use `Object.keys`.
- Avoid deep inheritance; prefer composition.
- Treat `#private` as class-private, not protected.
- Don’t rely solely on `instanceof` across realms.

# Exercise: Inheritance in JavaScript

## The task

Build a small **vehicle fleet** using inheritance.

You must implement:

1. A base class `Vehicle` with:
   - `constructor(brand, year)`
   - method `describe()` returning `"<brand> <year>"`
   - method `start()` returning `"Engine started for <brand>"`

2. A subclass `Car` that:
   - calls the base constructor with `super(...)`
   - adds `doors` property
   - overrides `describe()` to append `" (car, N doors)"`
   - adds `honk()` returning `"Beep beep!"`

3. A subclass `Motorcycle` that:
   - calls the base constructor
   - adds `hasSidecar` property
   - overrides `start()` to return `"Kick-started motorcycle: <brand>"`
   - inherits `describe()` unchanged

4. A standalone function `isVehicle(obj)` that returns `true` only for instances created from `Vehicle` (or its subclasses).

Then write a short demo that constructs one of each and prints results, proving `instanceof` works up the chain.

---

## Step-by-step solution

### Step 1 — Base class

```js
class Vehicle {
  constructor(brand, year) {
    this.brand = brand;
    this.year = year;
  }

  describe() {
    return `${this.brand} ${this.year}`;
  }

  start() {
    return `Engine started for ${this.brand}`;
  }
}
```

**Why classes?** ES6 `class` syntax is syntactic sugar over JavaScript's prototype-based inheritance, but it's the idiomatic, readable way to express it today. Under the hood, `Car.prototype` is linked to `Vehicle.prototype`.

### Step 2 — Subclass `Car`

```js
class Car extends Vehicle {
  constructor(brand, year, doors) {
    super(brand, year);   // must call before using this
    this.doors = doors;
  }

  describe() {
    return `${super.describe()} (car, ${this.doors} doors)`;
  }

  honk() {
    return "Beep beep!";
  }
}
```

**Key points:**
- `extends` sets up the prototype chain.
- `super(...)` invokes the parent constructor; **it must run before you assign `this.*`**.
- `super.describe()` calls the parent's method from inside the override — a clean way to reuse logic rather than duplicating it.
- `honk()` is new functionality only cars have.

### Step 3 — Subclass `Motorcycle`

```js
class Motorcycle extends Vehicle {
  constructor(brand, year, hasSidecar) {
    super(brand, year);
    this.hasSidecar = hasSidecar;
  }

  start() {
    return `Kick-started motorcycle: ${this.brand}`;
  }
}
```

Here we **override `start`** but **inherit `describe`** unchanged — demonstrating selective overriding.

### Step 4 — `isVehicle` helper

```js
function isVehicle(obj) {
  return obj instanceof Vehicle;
}
```

Because `Car` and `Motorcycle` extend `Vehicle`, `instanceof` returns `true` for all of them. Plain objects and unrelated instances return `false`.

### Step 5 — Demo

```js
const v = new Vehicle("Generic", 2020);
const c = new Car("Toyota", 2022, 4);
const m = new Motorcycle("Harley", 2019, false);

console.log(v.describe());   // "Generic 2020"
console.log(v.start());      // "Engine started for Generic"

console.log(c.describe());   // "Toyota 2022 (car, 4 doors)"
console.log(c.start());      // "Engine started for Toyota"  (inherited)
console.log(c.honk());       // "Beep beep!"

console.log(m.describe());   // "Harley 2019"  (inherited)
console.log(m.start());      // "Kick-started motorcycle: Harley"

console.log(isVehicle(v));   // true
console.log(isVehicle(c));   // true
console.log(isVehicle(m));   // true
console.log(isVehicle({}));  // false
console.log(c instanceof Car);        // true
console.log(c instanceof Vehicle);    // true
console.log(m instanceof Car);        // false
```

---

## Final complete solution

```js
class Vehicle {
  constructor(brand, year) {
    this.brand = brand;
    this.year = year;
  }

  describe() {
    return `${this.brand} ${this.year}`;
  }

  start() {
    return `Engine started for ${this.brand}`;
  }
}

class Car extends Vehicle {
  constructor(brand, year, doors) {
    super(brand, year);
    this.doors = doors;
  }

  describe() {
    return `${super.describe()} (car, ${this.doors} doors)`;
  }

  honk() {
    return "Beep beep!";
  }
}

class Motorcycle extends Vehicle {
  constructor(brand, year, hasSidecar) {
    super(brand, year);
    this.hasSidecar = hasSidecar;
  }

  start() {
    return `Kick-started motorcycle: ${this.brand}`;
  }
}

function isVehicle(obj) {
  return obj instanceof Vehicle;
}

// ---- demo ----
const v = new Vehicle("Generic", 2020);
const c = new Car("Toyota", 2022, 4);
const m = new Motorcycle("Harley", 2019, false);

console.log(v.describe());
console.log(v.start());

console.log(c.describe());
console.log(c.start());
console.log(c.honk());

console.log(m.describe());
console.log(m.start());

console.log(isVehicle(v), isVehicle(c), isVehicle(m), isVehicle({}));
console.log(c instanceof Car, c instanceof Vehicle, m instanceof Car);
```

