Refactor using **prototype-based inheritance without `class`**:

```js
function VehicleP(brand, year) { this.brand = brand; this.year = year; }
VehicleP.prototype.describe = function () { return `${this.brand} ${this.year}`; };
VehicleP.prototype.start    = function () { return `Engine started for ${this.brand}`; };

function CarP(brand, year, doors) {
