  .ok { color:#080; } .bad { color:#c00; }
  pre { background:#f5f5f5; padding:1rem; border-radius:.5rem; white-space:pre-wrap; }
</style>
</head>
<body>
<h1>Signup Form with Validation</h1>

<form id="signup" novalidate>
  <div class="field" data-field="username">
    <label for="username">Username</label>
    <input id="username" name="username" type="text" autocomplete="username">
    <div class="error"></div>
  </div>

  <div class="field" data-field="email">
    <label for="email">Email</label>
    <input id="email" name="email" type="email" autocomplete="email">
    <div class="error"></div>
  </div>

  <div class="field" data-field="age">
    <label for="age">Age</label>
    <input id="age" name="age" type="number" min="0" max="150">
    <div class="error"></div>
  </div>

  <div class="field" data-field="password">
    <label for="password">Password</label>
    <input id="password" name="password" type="password" autocomplete="new-password">
    <div class="error"></div>
  </div>

  <div class="field" data-field="confirm">
    <label for="confirm">Confirm Password</label>
    <input id="confirm" name="confirm" type="password" autocomplete="new-password">
    <div class="error"></div>
  </div>

  <div class="field" data-field="birthdate">
    <label for="birthdate">Birthdate (YYYY-MM-DD)</label>
    <input id="birthdate" name="birthdate" type="text" placeholder="1990-05-20">
    <div class="error"></div>
  </div>

  <button type="submit">Create Account</button>
  <div class="status" id="status"></div>
</form>

<h2>Validation Rules</h2>
<pre id="rules"></pre>

<script>
/* ============================================================
   1. Reusable Validator
   ============================================================ */
class Validator {
  constructor(value) { this.value = value; this.errors = []; }
  required(msg = 'This field is required.') {
    if (this.value === null || this.value === undefined || String(this.value).trim() === '')
      this.errors.push(msg);
    return this;
  }
  minLength(n, msg) {
    if (String(this.value).length < n)
      this.errors.push(msg || `Must be at least ${n} characters.`);
    return this;
  }
  maxLength(n, msg) {
    if (String(this.value).length > n)
      this.errors.push(msg || `Must be at most ${n} characters.`);
    return this;
  }
  email(msg = 'Must be a valid email address.') {
    // reasonably strict RFC-ish check
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
    if (!re.test(String(this.value).trim()))
      this.errors.push(msg);
    return this;
  }
  number(msg = 'Must be a number.') {
    if (this.value === '' || isNaN(Number(this.value)))
      this.errors.push(msg);
    return this;
  }
  range(min, max, msg) {
    const v = Number(this.value);
    if (isNaN(v) || v < min || v > max)
      this.errors.push(msg || `Must be between ${min} and ${max}.`);
    return this;
  }
  dateISO(msg = 'Must be a valid date (YYYY-MM-DD).') {
    const re = /^\d{4}-\d{2}-\d{2}$/;
    if (!re.test(String(this.value))) { this.errors.push(msg); return this; }
    const d = new Date(this.value + 'T00:00:00Z');
    if (isNaN(d.getTime())) this.errors.push(msg);
    return this;
  }
  regex(re, msg = 'Invalid format.') {
    if (!re.test(String(this.value))) this.errors.push(msg);
    return this;
  }
  matches(other, msg = 'Values do not match.') {
    if (this.value !== other) this.errors.push(msg);
    return this;
  }
  custom(fn, msg = 'Invalid value.') {
    if (!fn(this.value)) this.errors.push(msg);
    return this;
  }
  ok() { return this.errors.length === 0; }
  first() { return this.errors[0] || null; }
}

/* ============================================================
   2. Form schema / rules
   ============================================================ */
const rules = {
  username: v => new Validator(v)
    .required()
    .minLength(3, 'Username must be at least 3 characters.')
    .maxLength(20, 'Username must be at most 20 characters.')
    .regex(/^[a-zA-Z0-9_]+$/, 'Username may only contain letters, numbers, underscores.'),
  email: v => new Validator(v)
    .required()
    .email()
    .maxLength(254),
  age: v => new Validator(v)
    .required('Age is required.')
    .number()
    .range(13, 120, 'You must be between 13 and 120 years old.'),
  password: v => new Validator(v)
    .required()
    .minLength(8, 'Password must be at least 8 characters.')
    .regex(/[A-Z]/, 'Password must contain an uppercase letter.')
    .regex(/[a-z]/, 'Password must contain a lowercase letter.')
    .regex(/\d/, 'Password must contain a digit.'),
  confirm: (v, all) => new Validator(v)
    .required()
    .matches(all.password, 'Passwords do not match.'),
  birthdate: v => new Validator(v)
    .required()
    .dateISO()
    .custom(val => {
      const d = new Date(val + 'T00:00:00Z');
      const today = new Date();
      return d <= today;
    }, 'Birthdate cannot be in the future.')
};

/* ============================================================
   3. UI wiring
   ============================================================ */
const form = document.getElementById('signup');
const statusEl = document.getElementById('status');

function getValues() {
  const fd = new FormData(form);
  const obj = {};
  for (const [k, v] of fd.entries()) obj[k] = v;
  return obj;
}

function validateField(name, values) {
  const fieldEl = form.querySelector(`[data-field="${name}"]`);
  const input = fieldEl.querySelector('input');
  const errEl = fieldEl.querySelector('.error');
  const v = values[name];
  const res = rules[name](v, values);
  errEl.textContent = res.first() || '';
  fieldEl.classList.toggle('invalid', !res.ok());
  return res.ok();
}

function validateAll() {
  const values = getValues();
  let allOk = true;
  Object.keys(rules).forEach(name => {
    if (!validateField(name, values)) allOk = false;
  });
  return { ok: allOk, values };
}

// Live validation on blur / input
form.querySelectorAll('input').forEach(inp => {
  inp.addEventListener('blur', () => validateField(inp.name, getValues()));
  inp.addEventListener('input', () => {
    // clear error while typing if previously shown
    const fieldEl = inp.closest('.field');
    if (fieldEl.classList.contains('invalid')) validateField(inp.name, getValues());
  });
});

form.addEventListener('submit', e => {
  e.preventDefault();
  const { ok, values } = validateAll();
  if (!ok) {
    statusEl.textContent = 'Please fix the errors above.';
    statusEl.className = 'status bad';
    return;
  }
  // Sanitize for display (never inject raw user input into HTML)
  const safe = Object.fromEntries(Object.entries(values).map(([k,v]) =>
    [k, String(v).replace(/[<>&"']/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;'}[c]))]));
  statusEl.textContent = 'Success! Account data (sanitized): ' + JSON.stringify(safe);
  statusEl.className = 'status ok';
});

/* ============================================================
   4. Self-tests (console)
   ============================================================ */
function assert(cond, msg) { if (!cond) { console.error('FAIL:', msg); } else { console.log('PASS:', msg); } }

// required
assert(!new Validator('').required().ok(), 'required rejects empty');
assert(new Validator('x').required().ok(), 'required accepts non-empty');
// email
assert(new Validator('a@b.com').email().ok(), 'email valid');
assert(!new Validator('nope').email().ok(), 'email invalid');
// range
assert(new Validator('5').range(1,10).ok(), 'range in bounds');
assert(!new Validator('0').range(1,10).ok(), 'range low');
assert(!new Validator('11').range(1,10).ok(), 'range high');
// dateISO
assert(new Validator('2020-01-01').dateISO().ok(), 'date valid');
assert(!new Validator('2020-13-01').dateISO().ok(), 'date invalid month');
// matches
assert(new Validator('abc').matches('abc').ok(), 'matches equal');
assert(!new Validator('abc').matches('def').ok(), 'matches unequal');
// chained first error priority
assert(new Validator('').required('req').minLength(3,'min').first() === 'req', 'first error is required');

console.log('--- Validation demo ready ---');

/* ============================================================
   5. Show rules in page
   ============================================================ */
document.getElementById('rules').textContent =
  Object.keys(rules).map(k => `${k}: ${rules[k].toString().replace(/\n/g,' ')}`).join('\n');
</script>
</body>
</html>
```

### Key points illustrated

| Concern | How it’s handled |
|---|---|
| **Reusable rules** | `Validator` class with chainable methods; each returns `this` |
| **Schema-driven validation** | `rules` object maps field name → validator factory; `confirm` receives all values to support cross-field checks |
| **Live UX** | `blur` validates a field; `input` re-validates only if already marked invalid |
| **Submit flow** | `validateAll()` runs every rule, toggles `.invalid` classes, reports first error per field |
| **Security** | User input is never injected via `innerHTML`; on success it is HTML-escaped manually before display; better yet, use `textContent` |
| **Extensibility** | Add new rules by extending `Validator` or adding entries to `rules` |

### Production notes

1. **Client-side validation is UX, not security.** Always re-validate on the server; treat the client as untrusted.
2. **Sanitization vs. escaping** – escaping is for display; sanitization/parsing is for persistence. Never store escaped HTML if you might render it differently later.
3. **Accessibility** – pair errors with `aria-live="polite"` and `aria-invalid="true"` on inputs (omitted here for brevity but easy to add).
4. **Libraries** – for large apps consider Zod, Yup, or Valibot; they provide the same chaining with TypeScript inference and schema reuse across client/server.

# Input Validation in JavaScript

## The Idea

Input validation is the practice of **checking data before you trust it**. In JavaScript (browser or Node.js), user input arrives as strings, numbers, or objects that may be missing, malformed, malicious, or simply out of range. Validation answers three questions:

1. **Is it present?** (required fields)
2. **Is it the right type/shape?** (string, number, email, ISO date, etc.)
3. **Is it within allowed bounds?** (length, min/max, enum values, business rules)

Validation should happen **at the boundary** (UI form, API route, message handler) and ideally **twice**: once on the client for fast UX, once on the server because client code can be bypassed.

---

## Syntax & Approaches

### 1. Manual checks (vanilla JS)

```js
function validateUser(input) {
  const errors = {};

  if (typeof input.email !== "string" || !input.email.includes("@")) {
    errors.email = "Invalid email";
  }
  if (typeof input.age !== "number" || input.age < 0 || input.age > 130) {
    errors.age = "Age must be 0–130";
  }
  if (!Array.isArray(input.roles) || input.roles.length === 0) {
    errors.roles = "At least one role required";
  }

  return { ok: Object.keys(errors).length === 0, errors };
}
```

**Pros:** zero deps, full control.  
**Cons:** verbose, easy to miss edge cases.

---

### 2. Regular expressions

```js
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const SLUG_RE  = /^[a-z0-9-]{3,40}$/;

function isEmail(v) { return EMAIL_RE.test(String(v)); }
function isSlug(v)  { return SLUG_RE.test(String(v)); }
```

Use regex for **format**, not for security-critical parsing (e.g., don’t regex-parse JSON or HTML).

---

### 3. HTML5 / browser built-ins (client only)

```html
<form id="signup">
  <input name="email" type="email" required minlength="5" />
  <input name="age"   type="number" min="13" max="120" />
  <button>Submit</button>
</form>

<script>
  const form = document.getElementById("signup");
  form.addEventListener("submit", (e) => {
    if (!form.checkValidity()) {
      e.preventDefault();          // block submit
      form.reportValidity();       // show native tooltips
    }
  });
</script>
```

Good for UX; **never** rely on it alone.

---

### 4. Schema libraries (recommended for real apps)

**Zod** (TypeScript-friendly, runtime validation):

```js
import { z } from "zod";

const UserSchema = z.object({
  email: z.string().email(),
  age: z.number().int().min(0).max(130),
  roles: z.array(z.enum(["admin", "user"])).min(1),
  createdAt: z.coerce.date().optional(),
});

// Safe parse returns { success, data, error }
const result = UserSchema.safeParse(req.body);
if (!result.success) {
  return res.status(400).json({ errors: result.error.flatten() });
}
const user = result.data; // typed & sanitized
```

**Joi** (classic Node.js):

```js
const Joi = require("joi");

const schema = Joi.object({
  email: Joi.string().email().required(),
  age: Joi.number().integer().min(0).max(130),
});

const { error, value } = schema.validate(req.body, { abortEarly: false });
if (error) return res.status(400).json({ details: error.details });
```

