## A Complete, Idiomatic Example (Express + Zod)

```js
import express from "express";
import { z } from "zod";

const app = express();
app.use(express.json());

const CreatePost = z.object({
  title: z.string().trim().min(1).max(200),
  body:  z.string().trim().min(1),
  tags:  z.array(z.string().toLowerCase()).max(5).default([]),
  published: z.boolean().default(false),
});

app.post("/posts", (req, res) => {
  const parsed = CreatePost.safeParse(req.body);
  if (!parsed.success) {
    return res.status(422).json({
      message: "Validation failed",
      issues: parsed.error.issues.map(i => ({
        path: i.path.join("."),
        message: i.message,
      })),
    });
  }

  // parsed.data is clean, typed, and has defaults applied
  const post = await db.posts.create(parsed.data);
  res.status(201).json(post);
});
```

