## 1. Native lambda functions in JavaScript (arrow functions)

JavaScript already has first-class lambda functions: **arrow functions**. They are expressions that create functions without a name.

```js
// Basic forms
const add = (a, b) => a + b;
const square = x => x * x;                 // one parameter: parentheses optional
const greet = name => `Hello, ${name}!`;
const log = () => console.log("hi");       // no parameters

// Block body
const factorial = n => {
  let result = 1;
  for (let i = 2; i <= n; i++) result *= i;
  return result;
};

// Higher-order functions
const compose = (f, g) => x => f(g(x));
const inc = x => x + 1;
const double = x => x * 2;
const incThenDouble = compose(double, inc);
console.log(incThenDouble(3)); // 8

// Closures / state
function makeCounter() {
  let count = 0;
  return () => ++count; // lambda capturing `count`
}
const counter = makeCounter();
console.log(counter(), counter(), counter()); // 1 2 3

// Currying
const addCurried = a => b => a + b;
console.log(addCurried(2)(3)); // 5

// Array pipelines
const nums = [1, 2, 3, 4, 5];
const result = nums
  .filter(x => x % 2 === 1)
  .map(x => x * x)
  .reduce((acc, x) => acc + x, 0);
console.log(result); // 1 + 9 + 25 = 35
```

Important properties of arrow functions:

- They do **not** have their own `this`; they capture `this` lexically.
- They do **not** have `arguments`, `super`, or `new.target`.
- They cannot be used as constructors: `new (() => {})` throws.
- They are ideal for callbacks, pipelines, currying, and closures.

---

## 2. A complete lambda-calculus implementation in JavaScript

If by “implement lambda functions” you mean implementing the **lambda calculus itself**, here is a small but complete interpreter with:

- AST terms: variable, abstraction (`λx.M`), application (`M N`)
- capture-avoiding substitution
- normal-order beta reduction
- Church booleans and Church numerals
- conversion back to JavaScript numbers/booleans

```js
// ---------- Lambda calculus AST ----------
const V = name => ({ type: "var", name });
const L = (param, body) => ({ type: "lam", param, body });
const A = (fn, arg) => ({ type: "app", fn, arg });

// ---------- Free variables ----------
function freeVars(term) {
  switch (term.type) {
    case "var": return new Set([term.name]);
    case "lam": {
      const s = freeVars(term.body);
      s.delete(term.param);
      return s;
    }
    case "app": {
      const s = freeVars(term.fn);
      for (const x of freeVars(term.arg)) s.add(x);
      return s;
    }
  }
}

// ---------- Fresh variable names ----------
function fresh(base, forbidden) {
  let name = base;
  let i = 0;
  while (forbidden.has(name)) name = base + (i === 0 ? "'" : i++);
  return name;
}

// ---------- Capture-avoiding substitution ----------
function substitute(term, varName, replacement) {
  switch (term.type) {
    case "var":
      return term.name === varName ? clone(replacement) : term;

    case "lam":
      if (term.param === varName) return term; // shadowed
      if (freeVars(replacement).has(term.param)) {
        const newParam = fresh(term.param, new Set([...freeVars(term.body), ...freeVars(replacement)]));
        const renamedBody = substitute(term.body, term.param, V(newParam));
        return L(newParam, substitute(renamedBody, varName, replacement));
      }
      return L(term.param, substitute(term.body, varName, replacement));

    case "app":
      return A(
        substitute(term.fn, varName, replacement),
        substitute(term.arg, varName, replacement)
      );
  }
}

function clone(t) {
  return JSON.parse(JSON.stringify(t));
}

// ---------- Normal-order reduction ----------
function reduce(term) {
  switch (term.type) {
    case "var":
      return term;
    case "lam":
      return L(term.param, reduce(term.body));
    case "app": {
      const fn = reduce(term.fn);
      if (fn.type === "lam") {
        // Substitute unreduced argument (normal order)
        return reduce(substitute(fn.body, fn.param, term.arg));
      }
      const arg = reduce(term.arg);
      return A(fn, arg);
    }
  }
}

// ---------- Pretty printer ----------
function pretty(term) {
  switch (term.type) {
    case "var": return term.name;
    case "lam": return `(λ${term.param}.${pretty(term.body)})`;
    case "app": return `(${pretty(term.fn)} ${pretty(term.arg)})`;
  }
}

// ---------- Church encodings ----------
const TRUE  = L("x", L("y", V("x")));
const FALSE = L("x", L("y", V("y")));

const AND = L("p", L("q", A(A(V("p"), V("q")), V("p"))));
const OR  = L("p", L("q", A(A(V("p"), V("p")), V("q"))));
const NOT = L("p", A(A(V("p"), FALSE), TRUE));

const ZERO = L("f", L("x", V("x")));
const SUCC = L("n", L("f", L("x", A(V("f"), A(A(V("n"), V("f")), V("x"))))));
const ADD  = L("m", L("n", L("f", L("x", A(A(V("m"), V("f")), A(A(V("n"), V("f")), V("x")))))));
const MULT = L("m", L("n", L("f", A(V("m"), A(V("n"), V("f"))))));

// ONE = succ ZERO
const ONE = reduce(A(SUCC, ZERO));
const TWO = reduce(A(SUCC, ONE));
const THREE = reduce(A(SUCC, TWO));

// ---------- Convert Church numerals/booleans to JS values ----------
function churchToNumber(term) {
  // A Church numeral is λf.λx. f^n x.
  // Apply it to a JS successor and 0.
  const f = x => x + 1;
  const x = 0;
  // Evaluate lambda term as a JS function
  function toJS(t) {
    switch (t.type) {
      case "var": throw new Error("unbound variable in toJS");
      case "lam": return arg => toJSWithEnv(t.body, { [t.param]: arg });
      case "app": {
        const fn = toJS(t.fn); // not env-aware; use env version below
        return fn;
      }
    }
  }
  // Simpler robust version:
  function evalJS(t, env = {}) {
    switch (t.type) {
      case "var": return env[t.name];
      case "lam": return arg => evalJS(t.body, { ...env, [t.param]: arg });
      case "app": return evalJS(t.fn, env)(evalJS(t.arg, env));
    }
  }
  return evalJS(term)(f)(x);
}

function churchToBool(term) {
  function evalJS(t, env = {}) {
    switch (t.type) {
      case "var": return env[t.name];
      case "lam": return arg => evalJS(t.body, { ...env, [t.param]: arg });
      case "app": return evalJS(t.fn, env)(evalJS(t.arg, env));
    }
  }
  return evalJS(term)(true)(false);
}

// ---------- Demo ----------
console.log("ONE   =", pretty(ONE));
console.log("TWO   =", pretty(TWO));
console.log("THREE =", pretty(THREE));

const FOUR = reduce(A(A(ADD, TWO), TWO));
const SIX  = reduce(A(A(MULT, TWO), THREE));

console.log("2 + 2 =", churchToNumber(FOUR)); // 4
console.log("2 * 3 =", churchToNumber(SIX));  // 6

const T = reduce(A(A(AND, TRUE), FALSE));
const O = reduce(A(A(OR, FALSE), TRUE));
const N = reduce(A(NOT, TRUE));

console.log("TRUE AND FALSE =", churchToBool(T)); // false
console.log("FALSE OR TRUE  =", churchToBool(O)); // true
console.log("NOT TRUE       =", churchToBool(N)); // false

// Identity lambda
const ID = L("x", V("x"));
console.log("identity(42) via JS eval =",
  ((t => arg => {
    function evalJS(x, env = {}) {
      switch (x.type) {
        case "var": return env[x.name];
        case "lam": return a => evalJS(x.body, { ...env, [x.param]: a });
        case "app": return evalJS(x.fn, env)(evalJS(x.arg, env));
      }
    }
    return evalJS(t)(arg);
  })(ID))(42)
);
```

### How this works

1. **Terms are plain JavaScript objects**, so lambdas are data, not just syntax.
2. **`substitute`** avoids variable capture by renaming bound variables when needed.
3. **`reduce`** uses normal order: it reduces the function position first and does not reduce arguments before substitution. This is what makes Church numerals and booleans work cleanly.
4. **`churchToNumber` / `churchToBool`** interpret the resulting lambda term as a JavaScript function, allowing interoperation between lambda calculus and ordinary JS.

### Practical takeaway

- For real JavaScript programs, use **arrow functions**.
- For studying or embedding lambda calculus, represent terms as objects and implement substitution + reduction as shown above.

## Lambda functions in JavaScript (arrow functions)

JavaScript has no `lambda` keyword; its lambda expression is the **arrow function** (`=>`). It is an anonymous (or sometimes named via assignment) function value that can be created inline, passed around, and returned.

---

### 1. The idea

- **First-class functions**: functions are values; you can assign them to variables, pass them as arguments, return them.
- **Expression-oriented**: an arrow function is an *expression* that evaluates to a function, so it composes naturally inside other expressions.
- **Lexical `this`**: unlike regular functions, arrow functions do not create their own `this`; they inherit it from the enclosing scope. This is the single biggest behavioral difference and the main reason they were introduced.

```js
const add = (a, b) => a + b;   // a value of type function
console.log(add(2, 3));         // 5
```

---

### 2. Syntax

```js
// No params
const now = () => Date.now();

// One param: parentheses optional
const square = x => x * x;
const square2 = (x) => x * x;

// Multiple params
const sum = (a, b) => a + b;

// Block body: explicit return required
const greet = (name) => {
  const msg = `Hello, ${name}`;
  return msg;
};

// Implicit return of an object literal: wrap in parentheses
const makePoint = (x, y) => ({ x, y });

// Rest / default params work normally
const log = (level = 'info', ...args) => console.log(level, ...args);
```

Key points:
- **Implicit return** only when the body is a single expression (no braces).
- `{ x, y }` alone would be parsed as a block, so object literals need `({ ... })`.
- Arrow functions cannot be used as constructors (`new` throws) and have no `prototype`.

---

### 3. Typical use cases

#### a) Array methods (map/filter/reduce)
```js
const nums = [1, 2, 3, 4];
const doubled = nums.map(n => n * 2);          // [2,4,6,8]
const evens   = nums.filter(n => n % 2 === 0); // [2,4]
const total   = nums.reduce((a, b) => a + b, 0); // 10
```

#### b) Sorting with a comparator
```js
const people = [{name:'Zoe',age:30},{name:'Ada',age:25}];
people.sort((a, b) => a.age - b.age);
```

#### c) Event handlers / timers preserving `this`
```js
class Timer {
  constructor() { this.count = 0; }
  start() {
    setInterval(() => { this.count++; }, 1000); // `this` = Timer instance
  }
}
```
With a regular function you’d need `.bind(this)` or a closure variable.

#### d) Closures / factory functions
```js
const makeAdder = (x) => (y) => x + y;
const add5 = makeAdder(5);
add5(3); // 8
```

#### e) Currying and partial application
```js
const curry = (f) => (a) => (b) => f(a, b);
const add = curry((a, b) => a + b);
add(2)(3); // 5
```

#### f) Inline predicates / guards
```js
const isAdult = (p) => p.age >= 18;
users.filter(isAdult);
```

#### g) IIFE for scoping (less common now, but valid)
```js
const result = ((x) => x * 2)(21); // 42
```

---

### 4. Differences from regular functions (important)

| Feature | Arrow function | Regular function |
|---|---|---|
| `this` | lexical (inherited) | dynamic (call-site) |
| `arguments` | not defined (use rest params) | available |
| `prototype` | none | exists |
| `new` | throws TypeError | works |
| hoisting | not hoisted (const/let rules) | function declarations hoisted |
| `super` / `new.target` | lexical | own |

```js
function Regular() { console.log(this); }
const Arrow = () => console.log(this);

const obj = { Regular, Arrow };
obj.Regular(); // obj
obj.Arrow();   // outer `this` (e.g., global/undefined in strict)
```

---

### 5. Pitfalls and when NOT to use arrows

1. **Object methods** — you usually want dynamic `this`:
   ```js
   const obj = {
     n: 5,
     double: () => this.n * 2,   // WRONG: `this` is not obj
   };
   ```
   Use a method shorthand instead: `double() { return this.n * 2; }`.

2. **Event handlers needing `this` as the element**:
   ```js
   button.addEventListener('click', function () {
     this.classList.toggle('active'); // `this` = button
   });
   ```

3. **Prototype methods / classes** where `this` semantics matter.

4. **Recursion / named functions** — arrow functions can’t be named at definition; assign to a `const` and reference by name (careful with reassignment and TDZ).

5. **Debugging**: anonymous arrows show up as `(anonymous)` in stack traces; naming via assignment helps but isn’t perfect:
   ```js
   const handler = (e) => { ... }; // shows as "handler" in many engines
   ```

---

### 6. A compact “cheat sheet” example

```js
// Data pipeline: filter → map → reduce, all with lambdas
const orders = [
  { item: 'book', qty: 2, price: 12 },
  { item: 'pen',  qty: 5, price: 1.5 },
  { item: 'mug',  qty: 1, price: 8 },
];

const total = orders
  .filter(o => o.qty > 1)
  .map(o => o.qty * o.price)
  .reduce((sum, v) => sum + v, 0);

console.log(total); // 2*12 + 5*1.5 = 24 + 7.5 = 31.5
```

### Summary
Arrow functions are JavaScript’s lambda: concise, expression-friendly, lexically scoped for `this`, ideal for callbacks, pipelines, closures, and functional-style code. Use regular functions when you need dynamic `this`, constructors, or hoisting.

## Common mistake 1: closure captures the variable, not its value

```js
const callbacks = [];

for (var i = 0; i < 3; i++) {
  callbacks.push(() => console.log(i));
}

callbacks.forEach(cb => cb());
// Prints:
// 3
// 3
// 3
```

### Corrected version

```js
const callbacks = [];

for (let i = 0; i < 3; i++) {
  callbacks.push(() => console.log(i));
}

callbacks.forEach(cb => cb());
// Prints:
// 0
// 1
// 2
```

### Why it was wrong

- `var i` is function-scoped, so there is only **one** `i` shared by every arrow function.
- Each lambda closes over that same variable binding, not over the value `i` had when the lambda was created.
- By the time the callbacks run, the loop has finished and `i` is `3`.
- Using `let` creates a fresh block-scoped binding for each iteration, so each lambda closes over its own `i`.

---

## Common mistake 2: arrow functions do not have their own `this`

```js
const person = {
  name: "Ada",
  greet: () => {
    console.log(`Hi, I'm ${this.name}`);
  }
};

person.greet();
// Usually prints: "Hi, I'm undefined"
// In non-strict/global contexts, `this` may be `window`/`global`, not `person`
```

### Corrected version

```js
const person = {
  name: "Ada",
  greet() {
    console.log(`Hi, I'm ${this.name}`);
  }
};

person.greet();
// Prints: "Hi, I'm Ada"
```

### Why it was wrong

- Arrow functions inherit `this` from the surrounding lexical scope where they were defined.
- They do not get a dynamic `this` based on how they are called.
- A normal method or regular function receives `this` from the call site, so `person.greet()` correctly sets `this` to `person`.

---

### Practical takeaway

Use arrow functions for short callbacks and lexical `this` behavior, but use regular functions/methods when you need dynamic `this`, such as object methods, constructors, or prototype methods. Also prefer `let`/`const` over `var` in loops to avoid accidental shared closure state.

## Exercise

**Task:** Given an array of product objects:

```js
const products = [
  { name: "Laptop", price: 1200, inStock: true },
  { name: "Mouse", price: 25, inStock: true },
  { name: "Keyboard", price: 80, inStock: false },
  { name: "Monitor", price: 300, inStock: true },
  { name: "Cable", price: 15, inStock: true }
];
```

1. Use **arrow functions** (lambdas) to compute the **total discounted price** of in-stock products costing more than `$50`, with a `10%` discount applied.
2. Wrap the computation in a **higher-order function** `withLogging(fn)` that logs the input and result.
3. Implement a **counter factory** using closures and arrow functions.

---

## Step-by-step solution

### Step 1 — Filter, map, reduce with arrow functions

We chain three array methods, each receiving an arrow function:

```js
const discountedTotal = products
  .filter(p => p.inStock && p.price > 50)   // keep qualifying products
  .map(p => p.price * 0.9)                  // apply 10% discount
  .reduce((sum, price) => sum + price, 0);  // sum them up
```

- `p => ...` is a lambda taking one product.
- `(sum, price) => ...` is a lambda taking two arguments.

### Step 2 — Higher-order function `withLogging`

A function that takes another function and returns a new function:

```js
const withLogging = fn => (...args) => {
  console.log("Input:", args);
  const result = fn(...args);
  console.log("Result:", result);
  return result;
};
```

- `fn => ...` returns a lambda.
- `...args => ...` collects all arguments.

### Step 3 — Counter factory with closure

```js
const makeCounter = (start = 0) => {
  let count = start;
  return () => ++count; // arrow function closing over `count`
};
```

### Step 4 — Put it together

```js
const computeTotal = withLogging(products => {
  return products
    .filter(p => p.inStock && p.price > 50)
    .map(p => p.price * 0.9)
    .reduce((sum, price) => sum + price, 0);
});

const total = computeTotal(products);
console.log("Total:", total);

const counter = makeCounter(5);
console.log(counter()); // 6
console.log(counter()); // 7
```

---

## Final solution

```js
const products = [
  { name: "Laptop", price: 1200, inStock: true },
  { name: "Mouse", price: 25, inStock: true },
  { name: "Keyboard", price: 80, inStock: false },
  { name: "Monitor", price: 300, inStock: true },
  { name: "Cable", price: 15, inStock: true }
];

// Higher-order wrapper using arrow functions
const withLogging = fn => (...args) => {
  console.log("Input:", args);
  const result = fn(...args);
  console.log("Result:", result);
  return result;
};

// Core computation using lambdas
const computeTotal = withLogging(products =>
  products
    .filter(p => p.inStock && p.price > 50)
    .map(p => p.price * 0.9)
    .reduce((sum, price) => sum + price, 0)
);

// Counter factory using closure + arrow function
const makeCounter = (start = 0) => {
  let count = start;
  return () => ++count;
};

// Run
const total = computeTotal(products);
console.log("Discounted total:", total); // 1350 (1080 + 270)

const counter = makeCounter(5);
console.log(counter()); // 6
console.log(counter()); // 7
```

### Expected output

```
Input: [ [ { name: 'Laptop', ... }, ... ] ]
Result: 1350
Discounted total: 1350
6
7
```

### Key takeaways
- Arrow functions shine for short, single-expression callbacks (`p => p.price * 0.9`).
- Higher-order functions (`withLogging`) are naturally expressed with arrow functions.
- Closures (`makeCounter`) capture variables from the enclosing scope, enabling private state.

## 1. Lambda (arrow) functions in JavaScript

In JavaScript, **lambda functions** are most commonly expressed as **arrow functions** (`=>`). They are:

- **Anonymous by default** (can be assigned to a variable or passed inline).
- **Lexically scoped for `this`** (they don’t create their own `this`, `arguments`, `super`, or `new.target`).
- **Not constructible** (can’t be used with `new`).
- **Concise** for single-expression bodies.

### Syntax variations

```js
// Single param, implicit return
const inc = x => x + 1;

// Multiple params
const add = (a, b) => a + b;

// Block body (explicit return)
const greet = name => {
  const msg = `Hello, ${name}`;
  return msg;
};

// Returning an object literal needs parentheses
const makePoint = (x, y) => ({ x, y });

// Higher-order: a function returning a function
const multiplyBy = factor => value => factor * value;
const double = multiplyBy(2);
double(5); // 10
```

### Key semantic differences from `function`

| Feature | `function` | Arrow function |
|---|---|---|
| `this` | Dynamic (call site) | Lexical (definition site) |
| `arguments` | Own binding | From enclosing scope |
| `new` | Allowed | `TypeError` |
| `prototype` | Has one | None |
| Hoisting | Function declarations hoisted | Not hoisted (if `const`/`let`) |

### Common pitfalls

```js
const obj = {
  value: 42,
  // BAD: arrow loses method `this`
  broken: () => this.value,
  // GOOD: regular method or bind
  good() { return this.value; }
};
```

---

## 2. Implementing the *core* of lambda: a tiny lambda-calculus interpreter

Arrow functions are JavaScript’s surface syntax; the underlying idea is **lambda calculus**:  
- **Variable**: `x`  
- **Abstraction**: `λx. body` (a function)  
- **Application**: `(f arg)` (calling a function)

Below is a small, self-contained interpreter that parses, pretty-prints, and **beta-reduces** pure lambda terms to normal form (with alpha-renaming to avoid variable capture).

```js
// ---------- AST node constructors ----------
const Var = name => ({ tag: 'Var', name });
const Lam = (param, body) => ({ tag: 'Lam', param, body });
const App = (fn, arg) => ({ tag: 'App', fn, arg });

// ---------- Free variables ----------
function freeVars(term) {
  switch (term.tag) {
    case 'Var':
      return new Set([term.name]);
    case 'Lam': {
      const s = freeVars(term.body);
      s.delete(term.param);
      return s;
    }
    case 'App':
      return new Set([...freeVars(term.fn), ...freeVars(term.arg)]);
    default:
      throw new Error('Unknown term: ' + term.tag);
  }
}

// ---------- Capture-avoiding substitution: term[x := subst] ----------
function subst(term, x, replacement) {
  switch (term.tag) {
    case 'Var':
      return term.name === x ? clone(replacement) : term;

    case 'App':
      return App(subst(term.fn, x, replacement), subst(term.arg, x, replacement));

    case 'Lam': {
      // Shadowed: x is bound here, nothing to do inside.
      if (term.param === x) return term;

      // If the bound variable would be captured by `replacement`,
      // alpha-rename it to a fresh name first.
      if (freeVars(replacement).has(term.param)) {
        const used = new Set([
          ...freeVars(term.body),
          ...freeVars(replacement),
          x,
        ]);
        let fresh = term.param;
        while (used.has(fresh)) fresh += "'";
        const renamedBody = subst(term.body, term.param, Var(fresh));
        return Lam(fresh, subst(renamedBody, x, replacement));
      }

      return Lam(term.param, subst(term.body, x, replacement));
    }

    default:
      throw new Error('Unknown term: ' + term.tag);
  }
}

// Shallow clone so substitutions never mutate shared nodes
function clone(t) {
  switch (t.tag) {
    case 'Var': return Var(t.name);
    case 'Lam': return Lam(t.param, clone(t.body));
    case 'App': return App(clone(t.fn), clone(t.arg));
  }
}

// ---------- One normal-order reduction step ----------
// Returns { term, changed: true } or null if no redex remains.
function step(term) {
  switch (term.tag) {
    case 'App': {
      // Beta-redex: (λx.body) arg  ->  body[x := arg]
      if (term.fn.tag === 'Lam') {
        return { term: subst(term.fn.body, term.fn.param, term.arg), changed: true };
      }
      // Otherwise reduce leftmost subterm first (normal order)
      const rFn = step(term.fn);
      if (rFn) return { term: App(rFn.term, term.arg), changed: true };
      const rArg = step(term.arg);
      if (rArg) return { term: App(term.fn, rArg.term), changed: true };
      return null;
    }
    case 'Lam': {
      const rBody = step(term.body);
      if (rBody) return { term: Lam(term.param, rBody.term), changed: true };
      return null;
    }
    case 'Var':
      return null;
    default:
      throw new Error('Unknown term: ' + term.tag);
  }
}

// ---------- Reduce to normal form ----------
function evalNF(term, maxSteps = 100000) {
  let current = term;
  for (let i = 0; i < maxSteps; i++) {
    const r = step(current);
    if (!r) return current; // normal form reached
    current = r.term;
  }
  throw new Error('Exceeded max reduction steps (possible non-termination)');
}

// ---------- Parser: \x. body  or  λx. body ----------
function tokenize(src) {
  const tokens = [];
  let i = 0;
  while (i < src.length) {
    const c = src[i];
    if (/\s/.test(c)) { i++; continue; }
    if (c === '\\' || c === 'λ') { tokens.push({ type: 'lambda' }); i++; continue; }
    if (c === '.') { tokens.push({ type: 'dot' }); i++; continue; }
    if (c === '(') { tokens.push({ type: 'lparen' }); i++; continue; }
    if (c === ')') { tokens.push({ type: 'rparen' }); i++; continue; }
    if (/[a-zA-Z_]/.test(c)) {
      let j = i;
      while (j < src.length && /[a-zA-Z0-9_']/.test(src[j])) j++;
      tokens.push({ type: 'ident', value: src.slice(i, j) });
      i = j;
      continue;
    }
    throw new Error(`Unexpected character: ${c}`);
  }
  return tokens;
}

class Parser {
  constructor(tokens) {
    this.tokens = tokens;
    this.pos = 0;
  }

  parse() {
    const expr = this.expr();
    if (this.pos !== this.tokens.length) {
      throw new Error('Unexpected trailing tokens');
    }
    return expr;
  }

  expr() {
    // Abstraction has lowest precedence and is right-nested
    if (this.peek()?.type === 'lambda') {
      this.next();
      const param = this.expect('ident').value;
      this.expect('dot');
      const body = this.expr();
      return Lam(param, body);
    }
    return this.app();
  }

  // Application is left-associative: f g h  =>  ((f g) h)
  app() {
    let left = this.atom();
    while (this.peek() && (this.peek().type === 'ident' || this.peek().type === 'lparen')) {
      const right = this.atom();
      left = App(left, right);
    }
    return left;
  }

  atom() {
    const t = this.peek();
    if (!t) throw new Error('Unexpected end of input');
    if (t.type === 'ident') { this.next(); return Var(t.value); }
    if (t.type === 'lparen') {
      this.next();
      const e = this.expr();
      this.expect('rparen');
      return e;
    }
    throw new Error(`Unexpected token: ${t.type}`);
  }

  peek() { return this.tokens[this.pos]; }
  next() { return this.tokens[this.pos++]; }
  expect(type) {
    const t = this.next();
    if (!t || t.type !== type) throw new Error(`Expected ${type}`);
    return t;
  }
}

function parse(src) {
  return new Parser(tokenize(src)).parse();
}

// ---------- Pretty printer ----------
function show(term) {
  switch (term.tag) {
    case 'Var': return term.name;
    case 'Lam': return `λ${term.param}.${show(term.body)}`;
    case 'App': return `(${show(term.fn)} ${show(term.arg)})`;
    default: throw new Error('Unknown term: ' + term.tag);
  }
}

// ---------- Demo / sanity checks ----------
function run(src) {
  const t = parse(src);
  const nf = evalNF(t);
  console.log(`${src}  =>  ${show(nf)}`);
}

// Identity
run('(\\x.x) y');                 // y
run('(\\x.x) (\\y.y)');           // λy.y

// Church booleans
run('(\\p.\\q.p) a b');           // a   (TRUE)
run('(\\p.\\q.q) a b');           // b   (FALSE)

// Church numeral 2 applied to f and x: f (f x)
run('(\\f.\\x.f (f x)) f x');     // (f (f x))

// Capture-avoiding substitution test:
// (λx.λy.x) y  should NOT capture y -> λz.y (renamed)
run('(\\x.\\y.x) y');             // λy'.y  (renamed bound var)

// Non-termination (commented out; would throw after max steps)
// run('(\\x.x x) (\\x.x x)');
```

### Why this is the “core”

- **Abstraction (`Lam`)** mirrors a JS arrow function: it binds a parameter and has a body.
- **Application (`App`)** mirrors calling a function.
- **Substitution + alpha-renaming** is exactly what makes lexical scope and closures work in real languages: when you pass a value into a function, you replace the parameter everywhere in the body, renaming bound variables if needed so they don’t accidentally “capture” free variables from the argument.
- **Normal-order reduction** is the evaluation strategy that guarantees finding a normal form whenever one exists (unlike call-by-value, which can diverge on terms like `(λx.y) (Ω)`).

In production JavaScript engines, arrow functions compile down to closures with captured environments; this interpreter shows the mathematical skeleton underneath that machinery.

# Edge cases when using arrow functions (lambdas) in JavaScript

Arrow functions are not just shorter syntax; they change `this`, `arguments`, constructor behavior, and parsing rules. Below are the important edge cases, with examples.

---

## 1. Lexical `this` breaks object methods and event handlers that expect the receiver

```js
const player = {
  health: 100,
  damage(amount) {
    this.health -= amount;      // `this` is player
  },
  heal: (amount) => {
    this.health += amount;      // `this` is outer lexical scope, NOT player
  }
};

player.heal(10);
console.log(player.health);     // still 100 in modules; maybe window/global in scripts
```

**Handling:** use a regular method when the function needs the object as `this`.

```js
const player = {
  health: 100,
  heal(amount) { this.health += amount; }  // correct
};
```

Arrow functions are great when you *want* the outer `this`, e.g. inside class methods:

```js
class Team {
  members = [];
  add(member) {
    this.members.push(member);
    // arrow inherits `this` from add()
    setTimeout(() => console.log(this.members.length), 0);
  }
}
```

---

## 2. `.bind()`, `.call()`, and `.apply()` cannot change an arrow's `this`

```js
function outer() {
  const arrow = () => this;
  // thisArg is ignored
  return arrow.call({ id: 'ignored' });
}

const result = outer.call({ id: 'lexical' });
console.log(result); // { id: 'lexical' }, not { id: 'ignored' }
```

Arguments are still passed normally:

```js
const add = (a, b) => a + b;
console.log(add.call(null, 2, 3)); // 5
```

**Handling:** if `this` must be dynamic at call time, use a regular function.

---

## 3. Arrow functions have no `arguments` object

```js
function outer(a, b) {
  const inner = () => arguments; // lexical outer arguments
  return inner(9, 9, 9);
}

const args = outer(1, 2);
console.log([...args]); // [1, 2], not [9, 9, 9]
```

**Handling:** use rest parameters:

```js
const inner = (...args) => args;
console.log(inner(9, 9, 9)); // [9, 9, 9]
```

---

## 4. `this` in default parameters is also lexical

This surprises people because the object containing the arrow is often assumed to be `this`.

```js
const obj = {
  value: 42,
  read: (x = this.value) => x
};

console.log(obj.read()); // not 42; uses outer `this`
```

**Handling:** avoid relying on `this` in default values of arrow functions. Use an explicit source instead:

```js
const obj = {
  value: 42,
  read: (x = obj.value) => x
};
```

Or use a regular function.

---

## 5. Cannot be used as constructors

```js
const Point = (x, y) => ({ x, y });

try {
  new Point(1, 2);
} catch (e) {
  console.error(e.name); // TypeError
}

console.log(Point.prototype); // undefined
```

**Handling:** use a regular function or class when instantiation is needed:

```js
class Point {
  constructor(x, y) { this.x = x; this.y = y; }
}
```

---

## 6. Cannot contain `yield`, and no async generator arrow

```js
// SyntaxError: Unexpected keyword 'yield'
const gen = () => { yield 1; };

// Valid generator:
function* gen2() { yield 1; }

// Async arrow is valid, but it returns a Promise
const load = async (id) => {
  const response = await fetch(`/users/${id}`);
  return response.json();
};
```

Async arrows also turn thrown exceptions into rejected promises, so callers must handle them:

```js
load(42).catch(err => console.error(err));
```

---

## 7. Implicit return only works for expressions

```js
const a = () => 42;               // returns 42
const b = () => { return 42; };   // returns 42
const c = () => { 42; };          // returns undefined
```

Returning an object literal requires parentheses:

```js
const makeUser = (name, age) => ({ name, age });

// Without parentheses, this is parsed as a block:
const broken = (name, age) => { name, age };
console.log(broken('Ada', 30)); // undefined
```

---

## 8. Destructured parameters need parentheses

```js
const getName = ({ name }) => name;          // OK
// const bad = { name } => name;             // SyntaxError
```

Default parameters with destructuring also need care:

```js
const greet = ({ name = 'guest' } = {}) => `Hello, ${name}`;
console.log(greet()); // Hello, guest
```

---

## 9. No line terminator between parameters and `=>`

```js
const f = ()
=> 1; // SyntaxError
```

Keep the arrow on the same line as the closing parenthesis:

```js
const f = () => 1;
```

---

## 10. Classic closure/loop bug with `var`

```js
const callbacks = [];

for (var i = 0; i < 3; i++) {
  callbacks.push(() => i);
}

callbacks.forEach(cb => console.log(cb())); // 3, 3, 3
```

Arrow functions capture the variable, not its current value at creation time. Since `var` is function-scoped, all callbacks share the same `i`.

**Handling:** use `let`, or pass the value as a parameter:

```js
for (let i = 0; i < 3; i++) {
  callbacks.push(() => i);
}
callbacks.forEach(cb => console.log(cb())); // 0, 1, 2
```

---

## 11. Recursion via outer variable can break after reassignment

```js
let factorial = n => (n <= 1 ? 1 : n * factorial(n - 1));

const saved = factorial;
factorial = () => 'corrupted';

console.log(saved(5)); // NaN, because saved calls the reassigned variable
```

**Handling:** use a named function for recursion:

```js
function factorial(n) {
  return n <= 1 ? 1 : n * factorial(n - 1);
}
```

---

## 12. `super` and `new.target` are lexical

Arrow functions inherit `super` and `new.target` from the enclosing scope.

```js
class Base {
  type() { return 'base'; }
}

class Derived extends Base {
  constructor() {
    super();
    this.action = () => super.type(); // lexical super property access
  }
}

const d = new Derived();
console.log(d.action()); // base
```

Constructors are different: `super()` must be called directly in the constructor, not inside an arrow.

`new.target` is also inherited:

```js
class A {
  constructor() {
    const f = () => new.target;
    console.log(f() === A); // true
  }
}
new A();
```

---

## 13. Class fields with arrows are instance-owned, not prototype methods

```js
class Counter {
  count = 0;
  increment = () => {
    this.count++;
  };
}

const c = new Counter();
const inc = c.increment;
inc(); // works: lexical this

console.log(Object.hasOwn(c, 'increment')); // true
console.log(Counter.prototype.increment);    // undefined
```

This is convenient for callbacks, but it creates a separate function for every instance.

**Handling:** if many instances are created and `this` does not need to be preserved after extraction, prefer prototype methods plus explicit binding.

---

## 14. Top-level `this` differs between scripts, modules, and strict mode

```js
// In an ES module, top-level `this` is undefined.
const show = () => this;
console.log(show()); // undefined in a module
```

In a browser script, top-level `this` is `window`; in strict mode functions, `this` may be `undefined`. Arrow functions inherit whatever the enclosing scope provides, so top-level arrows are especially environment-sensitive.

---

## 15. Parsing edge cases with optional chaining, ASI, and named arrows

Arrow functions are anonymous and rely on outer binding for their name:

```js
const fetchUser = (id) => fetch(`/users/${id}`);
console.log(fetchUser.name); // fetchUser

const obj = {
  load: (id) => fetch(`/users/${id}`)
};
console.log(obj.load.name); // load
```

But recursion or reassignment of the outer variable can undermine that. Also, optional chaining and arrow syntax can require extra parentheses:

```js
// Fine:
const get = (x) => x?.value;

// Grouping may be needed to avoid ambiguity:
const wrap = (x) => (x => x + 1)(x);
```

---

## 16. Removing listeners works only if the exact arrow reference is retained

Arrow class fields are stable per instance, so this works:

```js
class View {
  onClick = () => console.log(this.id);
  mount(button) { button.addEventListener('click', this.onClick); }
  unmount(button) { button.removeEventListener('click', this.onClick); }
}
```

But creating a fresh arrow each time prevents removal:

```js
button.addEventListener('click', () => console.log(this.id));
button.removeEventListener('click', () => console.log(this.id)); // does nothing
```

---

## Quick reference

| Situation | Use arrow? | Reason |
|---|---:|---|
| Array callbacks (`map`, `filter`) | Yes | Lexical `this` and concise syntax |
| Object methods needing receiver | No | `this` is not the object |
| Constructor / `class` base | No | Arrows are not constructible |
| Generator / async generator | No | Arrows cannot yield |
| Recursive core algorithm | Usually no | Named functions are safer |
| DOM callback needing element as `this` | No | Lexical `this` may be wrong |
| Preserving `this` in class field callback | Yes | Lexical `this` is the instance |
| Simple factory returning object | Yes | Use `({ ... })` for object |

Arrow functions are excellent for callbacks and preserving lexical scope, but their differences from regular functions must be handled deliberately.

Layered architecture separates an application into distinct layers, usually **presentation**, **application (use cases)**, **domain**, and **infrastructure**. Dependencies point inward: outer layers depend on inner abstractions, while inner layers know nothing about databases, HTTP, or frameworks.

Below is a complete, runnable Node.js example implementing a small Todo API. It uses only Node’s built-in modules, so you can run it directly.

## Architecture of the example

- **Domain layer**: `Todo` entity, domain errors, repository contract (`TodoRepository`).
- **Application layer**: use cases (`CreateTodo`, `ListTodos`, `CompleteTodo`, `DeleteTodo`), commands, and DTOs.
- **Infrastructure layer**: `InMemoryTodoRepository`, which implements the domain repository contract.
- **Presentation layer**: HTTP controller, routing, JSON parsing, response formatting.
- **Composition root**: wires all dependencies together at startup.

## Complete runnable example: `app.js`

```js
'use strict';

const http = require('http');
const { randomUUID } = require('crypto');

/* =========================== DOMAIN LAYER =========================== */

class DomainError extends Error {
  constructor(message, code = 'DOMAIN_ERROR') {
    super(message);
    this.name = 'DomainError';
    this.code = code;
  }
}

class TodoNotFoundError extends Error {
  constructor(id) {
    super(`Todo not found: ${id}`);
    this.name = 'TodoNotFoundError';
  }
}

class Todo {
  constructor({ id, title, completed = false, createdAt = new Date() }) {
    if (!id) {
      throw new DomainError('Todo id is required');
    }
    if (typeof title !== 'string' || title.trim() === '') {
      throw new DomainError('Todo title is required');
    }

    this.id = id;
    this.title = title.trim();
    this.completed = Boolean(completed);
    this.createdAt = createdAt instanceof Date ? createdAt : new Date(createdAt);
  }

  complete() {
    this.completed = true;
  }

  rename(title) {
    if (typeof title !== 'string' || title.trim() === '') {
      throw new DomainError('Todo title is required');
    }
    this.title = title.trim();
  }

  toObject() {
    return {
      id: this.id,
      title: this.title,
      completed: this.completed,
      createdAt: this.createdAt.toISOString(),
    };
  }
}

/**
 * A port/abstraction. Infrastructure implements this.
 * Domain and application depend on this interface, not on concrete storage.
 */
class TodoRepository {
  async findById(id) {
    throw new Error('TodoRepository#findById must be implemented');
  }
  async findAll() {
    throw new Error('TodoRepository#findAll must be implemented');
  }
  async save(todo) {
    throw new Error('TodoRepository#save must be implemented');
  }
  async delete(id) {
    throw new Error('TodoRepository#delete must be implemented');
  }
}

/* ======================== APPLICATION LAYER ======================== */

class CreateTodoCommand {
  constructor(title) {
    this.title = title;
  }
}

class TodoDto {
  constructor({ id, title, completed, createdAt }) {
    this.id = id;
    this.title = title;
    this.completed = completed;
    this.createdAt = createdAt;
  }

  static fromDomain(todo) {
    return new TodoDto(todo.toObject());
  }
}

class CreateTodoUseCase {
  constructor(repository) {
    if (!repository) {
      throw new Error('repository is required');
    }
    this.repository = repository;
  }

  async execute(command) {
    const todo = new Todo({
      id: randomUUID(),
      title: command.title,
    });

    await this.repository.save(todo);
    return TodoDto.fromDomain(todo);
  }
}

class ListTodosUseCase {
  constructor(repository) {
    this.repository = repository;
  }

  async execute() {
    const todos = await this.repository.findAll();
    return todos.map(TodoDto.fromDomain);
  }
}

class CompleteTodoUseCase {
  constructor(repository) {
    this.repository = repository;
  }

  async execute(id) {
    const todo = await this.repository.findById(id);
    if (!todo) {
      throw new TodoNotFoundError(id);
    }

    todo.complete();
    await this.repository.save(todo);
    return TodoDto.fromDomain(todo);
  }
}

class DeleteTodoUseCase {
  constructor(repository) {
    this.repository = repository;
  }

  async execute(id) {
    const todo = await this.repository.findById(id);
    if (!todo) {
      throw new TodoNotFoundError(id);
    }

    await this.repository.delete(id);
  }
}

/* ===================== INFRASTRUCTURE LAYER ===================== */

class InMemoryTodoRepository extends TodoRepository {
  constructor() {
    super();
    this.items = new Map();
  }

  async findById(id) {
    return this.items.get(id) || null;
  }

  async findAll() {
    return Array.from(this.items.values());
  }

  async save(todo) {
    this.items.set(todo.id, todo);
    return todo;
  }

  async delete(id) {
    this.items.delete(id);
  }
}

/* ===================== PRESENTATION LAYER ===================== */

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.name = 'HttpError';
    this.status = status;
  }
}

function sendJson(res, status, payload) {
  const body = payload === undefined ? '' : JSON.stringify(payload);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
  });
  res.end(body);
}

function readJson(req) {
  return new Promise((resolve, reject) => {
    let raw = '';

    req.setEncoding('utf8');
    req.on('data', (chunk) => {
      raw += chunk;
      if (raw.length > 1_000_000) {
        req.destroy();
        reject(new HttpError(413, 'Request body is too large'));
      }
    });

    req.on('end', () => {
      if (raw.trim() === '') {
        return resolve({});
      }
      try {
        resolve(JSON.parse(raw));
      } catch (error) {
        reject(new HttpError(400, 'Invalid JSON body'));
      }
    });

    req.on('error', reject);
  });
}

class TodoController {
  constructor(useCases) {
    this.createTodo = useCases.createTodo;
    this.listTodos = useCases.listTodos;
    this.completeTodo = useCases.completeTodo;
    this.deleteTodo = useCases.deleteTodo;
  }

  async list(_req, res) {
    const todos = await this.listTodos.execute();
    sendJson(res, 200, todos);
  }

  async create(req, res) {
    const body = await readJson(req);
    const command = new CreateTodoCommand(body.title);
    const todo = await this.createTodo.execute(command);
    sendJson(res, 201, todo);
  }

  async complete(_req, res, id) {
    const todo = await this.completeTodo.execute(id);
    sendJson(res, 200, todo);
  }

  async remove(_req, res, id) {
    await this.deleteTodo.execute(id);
    sendJson(res, 204);
  }
}

function createServer(controller) {
  return http.createServer(async (req, res) => {
    try {
      const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
      const { pathname } = url;
      const method = req.method;

      if (method === 'GET' && pathname === '/todos') {
        await controller.list(req, res);
        return;
      }

      if (method === 'POST' && pathname === '/todos') {
        await controller.create(req, res);
        return;
      }

      const completeMatch = pathname.match(/^\/todos\/([^/]+)\/complete$/);
      if (method === 'PATCH' && completeMatch) {
        await controller.complete(req, res, decodeURIComponent(completeMatch[1]));
        return;
      }

      const itemMatch = pathname.match(/^\/todos\/([^/]+)$/);
      if (method === 'DELETE' && itemMatch) {
        await controller.remove(req, res, decodeURIComponent(itemMatch[1]));
        return;
      }

      sendJson(res, 404, { error: 'Not found' });
    } catch (error) {
      let status = 500;

      if (error instanceof HttpError) {
        status = error.status;
      } else if (error instanceof TodoNotFoundError) {
        status = 404;
      } else if (error instanceof DomainError) {
        status = 400;
      }

      sendJson(res, status, { error: error.message });
    }
  });
}

/* ====================== COMPOSITION ROOT ====================== */

function buildApp() {
  const repository = new InMemoryTodoRepository();

  const useCases = {
    createTodo: new CreateTodoUseCase(repository),
    listTodos: new ListTodosUseCase(repository),
    completeTodo: new CompleteTodoUseCase(repository),
    deleteTodo: new DeleteTodoUseCase(repository),
  };

  const controller = new TodoController(useCases);
  return createServer(controller);
}

async function runDemo() {
  const repository = new InMemoryTodoRepository();

  const createTodo = new CreateTodoUseCase(repository);
  const listTodos = new ListTodosUseCase(repository);
  const completeTodo = new CompleteTodoUseCase(repository);
  const deleteTodo = new DeleteTodoUseCase(repository);

  const created = await createTodo.execute(new CreateTodoCommand('Buy milk'));
  console.log('Created:', created);

  const completed = await completeTodo.execute(created.id);
  console.log('Completed:', completed);

  console.log('All todos:', await listTodos.execute());

  await deleteTodo.execute(created.id);
  console.log('After deletion:', await listTodos.execute());
}

if (require.main === module) {
  if (process.argv.includes('--demo')) {
    runDemo().catch((error) => {
      console.error(error);
      process.exitCode = 1;
    });
  } else {
    const server = buildApp();
    const port = Number(process.env.PORT) || 3000;

    server.listen(port, () => {
      console.log(`Todo API listening on http://localhost:${port}`);
    });
  }
}
```

