## Implementation (core of a small Order domain)

### `domain/errors/ValidationError.js`
```js
export class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}
```

### `domain/value-objects/Money.js`
```js
export class Money {
  constructor(amount, currency = 'USD') {
    if (typeof amount !== 'number' || Number.isNaN(amount)) {
      throw new Error('Money amount must be a number');
    }
    if (amount < 0) throw new Error('Money amount cannot be negative');
    this.amount = amount;
    this.currency = currency;
  }

  add(other) {
    if (this.currency !== other.currency) throw new Error('Currency mismatch');
    return new Money(this.amount + other.amount, this.currency);
  }

  multiply(factor) {
    return new Money(this.amount * factor, this.currency);
  }

  toString() {
    return `${this.currency} ${this.amount.toFixed(2)}`;
  }
}
```

### `domain/entities/OrderItem.js`
```js
import { Money } from '../value-objects/Money.js';

export class OrderItem {
  constructor({ productId, quantity, unitPrice }) {
    if (!productId) throw new Error('productId is required');
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new Error('quantity must be a positive integer');
    }
    if (!(unitPrice instanceof Money)) {
      throw new Error('unitPrice must be a Money instance');
    }
    this.productId = productId;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  lineTotal() {
    return this.unitPrice.multiply(this.quantity);
  }
}
```

### `domain/entities/Order.js`
```js
import { Money } from '../value-objects/Money.js';
import { OrderItem } from './OrderItem.js';

export class Order {
  constructor({ id, customerId, items = [], status = 'draft' }) {
    if (!id) throw new Error('id is required');
    if (!customerId) throw new Error('customerId is required');
    this.id = id;
    this.customerId = customerId;
    this.items = items.map((i) => (i instanceof OrderItem ? i : new OrderItem(i)));
    this.status = status;
  }

  addItem(item) {
    if (this.status !== 'draft') throw new Error('Cannot modify a placed order');
    this.items.push(item instanceof OrderItem ? item : new OrderItem(item));
  }

  total() {
    const currency = this.items[0]?.unitPrice?.currency ?? 'USD';
    return this.items.reduce(
      (sum, item) => sum.add(item.lineTotal()),
      new Money(0, currency)
    );
  }

  place() {
    if (this.items.length === 0) throw new Error('Order must contain at least one item');
    if (this.status !== 'draft') throw new Error('Order already placed');
    this.status = 'placed';
  }
}
```

### `domain/repositories/IOrderRepository.js` (port / interface)
```js
export class IOrderRepository {
  async save(_order) { throw new Error('IOrderRepository.save not implemented'); }
  async findById(_id) { throw new Error('IOrderRepository.findById not implemented'); }
  async findAll() { throw new Error('IOrderRepository.findAll not implemented'); }
}
```

### `application/use-cases/CreateOrderUseCase.js`
```js
import { Order } from '../../domain/entities/Order.js';
import { OrderItem } from '../../domain/entities/OrderItem.js';
import { Money } from '../../domain/value-objects/Money.js';
import { ValidationError } from '../../domain/errors/ValidationError.js';

export class CreateOrderUseCase {
  constructor({ orderRepository, idGenerator }) {
    this.orderRepository = orderRepository; // depends on interface, not concrete
    this.idGenerator = idGenerator;
  }

  async execute({ customerId, items }) {
    if (!customerId) throw new ValidationError('customerId is required');
    if (!Array.isArray(items) || items.length === 0) {
      throw new ValidationError('items must be a non-empty array');
    }

    const order = new Order({ id: this.idGenerator(), customerId });

    for (const raw of items) {
      order.addItem(
        new OrderItem({
          productId: raw.productId,
          quantity: raw.quantity,
          unitPrice: new Money(raw.unitPrice, raw.currency ?? 'USD'),
        })
      );
    }

    order.place(); // enforce domain invariant
    await this.orderRepository.save(order);
    return order;
  }
}
```

### `application/use-cases/GetOrderUseCase.js`
```js
import { ValidationError } from '../../domain/errors/ValidationError.js';

export class GetOrderUseCase {
  constructor({ orderRepository }) {
    this.orderRepository = orderRepository;
  }

  async execute(id) {
    if (!id) throw new ValidationError('id is required');
    return this.orderRepository.findById(id);
  }
}
```

### `infrastructure/repositories/InMemoryOrderRepository.js` (adapter)
```js
import { IOrderRepository } from '../../domain/repositories/IOrderRepository.js';

export class InMemoryOrderRepository extends IOrderRepository {
  constructor() {
    super();
    this.store = new Map();
  }

  async save(order) {
    this.store.set(order.id, order);
    return order;
  }

  async findById(id) {
    return this.store.get(id) ?? null;
  }

  async findAll() {
    return [...this.store.values()];
  }
}
```

### `presentation/controllers/OrderController.js`
```js
import { ValidationError } from '../../domain/errors/ValidationError.js';

export class OrderController {
  constructor({ createOrder, getOrder }) {
    this.createOrder = createOrder;
    this.getOrder = getOrder;
  }

  async create(req, res) {
    try {
      const order = await this.createOrder.execute(req.body);
      res.status(201).json({
        id: order.id,
        status: order.status,
        total: order.total().toString(),
      });
    } catch (err) {
      if (err instanceof ValidationError) {
        return res.status(400).json({ error: err.message });
      }
      res.status(500).json({ error: 'Internal server error' });
    }
  }

  async get(req, res) {
    try {
      const order = await this.getOrder.execute(req.params.id);
      if (!order) return res.status(404).json({ error: 'Order not found' });
      res.json({
        id: order.id,
        customerId: order.customerId,
        status: order.status,
        total: order.total().toString(),
      });
    } catch (err) {
      if (err instanceof ValidationError) {
        return res.status(400).json({ error: err.message });
      }
      res.status(500).json({ error: 'Internal server error' });
    }
  }
}
```

### `app.js` (composition root / wiring)
```js
import { InMemoryOrderRepository } from './infrastructure/repositories/InMemoryOrderRepository.js';
import { CreateOrderUseCase } from './application/use-cases/CreateOrderUseCase.js';
import { GetOrderUseCase } from './application/use-cases/GetOrderUseCase.js';
import { OrderController } from './presentation/controllers/OrderController.js';

// Infrastructure
const orderRepository = new InMemoryOrderRepository();

// Application
const createOrder = new CreateOrderUseCase({
  orderRepository,
  idGenerator: () => crypto.randomUUID(),
});
const getOrder = new GetOrderUseCase({ orderRepository });

// Presentation
const orderController = new OrderController({ createOrder, getOrder });

// Example usage without Express:
const fakeRes = {
  status(code) { this.code = code; return this; },
  json(payload) { console.log(this.code ?? 200, payload); },
};
orderController.create(
  { body: { customerId: 'u1', items: [{ productId: 'p1', quantity: 2, unitPrice: 10 }] } },
  fakeRes
);
```

---

### Why this shape works in an interview
- **Swap storage:** replace `InMemoryOrderRepository` with a Postgres/Prisma adapter implementing `IOrderRepository`; use cases don’t change.
- **Test use cases:** inject a fake repo + deterministic id generator; no DB/HTTP needed.
- **Business rules live in domain:** `Order.place()` enforces invariants; controllers stay thin.
- **Dependency direction:** `domain` ← `application` ← `presentation/infrastructure`; nothing points inward-out.

# Edge cases in layered JavaScript architecture

A typical JS layering:

```
presentation/   → HTTP handlers, controllers, views
application/    → use-cases, orchestration, DTOs
domain/         → entities, value objects, business rules (pure)
infrastructure/ → DB, HTTP clients, queues, cache
```

The golden rule: **dependencies point inward** (presentation → application → domain ← infrastructure). Most bugs come from violating that or from boundaries between sync/async, stateful/stateless, and trusted/untrusted data.

Below are the most common edge cases, each with a “bad” and “good” snippet.

---

## 1. Circular dependencies between layers

**Problem:** `UserService` imports `OrderRepository`, `OrderService` imports `UserRepository`, and they end up importing each other → module load deadlock or `undefined` at runtime.

```js
// BAD: application/userService.js
import { orderRepo } from '../infrastructure/orderRepo.js';
export const userService = { /* uses orderRepo */ };

// BAD: application/orderService.js
import { userRepo } from '../infrastructure/userRepo.js';
export const orderService = { /* uses userRepo */ };
```

**Fix:** Invert the dependency. Domain/application defines an interface; infrastructure implements it. Or use domain events instead of direct calls.

```js
// domain/ports/UserRepository.js
export const UserRepository = {}; // interface (TS: interface)

// application/createOrder.js
export async function createOrder({ userId, items }, { users, orders, events }) {
  const user = await users.findById(userId);
  if (!user) throw new Error('UserNotFound');
  const order = { id: crypto.randomUUID(), userId, items, status: 'pending' };
  await orders.save(order);
  events.emit('OrderCreated', order);
  return order;
}

// infrastructure/wiring.js
import { createOrder } from '../application/createOrder.js';
import { pgUserRepo } from './pgUserRepo.js';
import { pgOrderRepo } from './pgOrderRepo.js';
import { eventBus } from './eventBus.js';

export const createOrderUseCase = (input) =>
  createOrder(input, { users: pgUserRepo, orders: pgOrderRepo, events: eventBus });
```

---

## 2. Infrastructure errors leaking into domain

**Problem:** A Mongo duplicate-key error bubbles up with a stack trace and driver-specific code; controllers end up `instanceof MongoError` checks.

```js
// BAD
try { await userRepo.save(user); }
catch (e) { res.status(409).json({ code: e.code }); } // leaks Mongo
```

**Fix:** Map at the boundary. Repositories throw domain errors; controllers only know domain errors.

```js
// domain/errors.js
export class DuplicateEmail extends Error { constructor() { super('DuplicateEmail'); this.code = 'DUPLICATE_EMAIL'; } }
export class NotFound extends Error { constructor(entity) { super(`${entity}NotFound`); this.code = 'NOT_FOUND'; } }

// infrastructure/pgUserRepo.js
import { DuplicateEmail } from '../domain/errors.js';
export const pgUserRepo = {
  async save(user) {
    try {
      await db.query('INSERT INTO users ...', [user.email]);
    } catch (e) {
      if (e.code === '23505') throw new DuplicateEmail();
      throw e; // unknown -> let global handler deal with 500
    }
  },
};

// presentation/userController.js
app.post('/users', async (req, res, next) => {
  try { res.status(201).json(await createUser(req.body)); }
  catch (e) {
    if (e.code === 'DUPLICATE_EMAIL') return res.status(409).json({ error: e.message });
    next(e);
  }
});
```

---

## 3. Transaction boundaries spanning multiple repositories

**Problem:** `createOrder` writes to `orders` and `inventory`. If the second fails, you get a partial write. Passing a `client`/`tx` through every function is noisy and error-prone.

```js
// BAD: manual tx threading
async function createOrder(input, { orders, inventory, db }) {
  const tx = await db.begin();
  try {
    await orders.save(order, tx);
    await inventory.decrement(sku, qty, tx);
    await tx.commit();
  } catch (e) { await tx.rollback(); throw e; }
}
```

**Fix:** Use a Unit of Work or `AsyncLocalStorage` so repositories join the ambient transaction automatically.

```js
// infrastructure/unitOfWork.js
import { AsyncLocalStorage } from 'node:async_hooks';
const als = new AsyncLocalStorage();

export function runInTransaction(fn) {
  return db.transaction(async (tx) => als.run(tx, fn));
}
export function currentTx() { return als.getStore(); }

// infrastructure/pgOrderRepo.js
export const pgOrderRepo = {
  async save(order) {
    const tx = currentTx();
    const q = tx ?? db;
    await q.query('INSERT INTO orders ...', [order.id]);
  },
};

// application/createOrder.js
export async function createOrder(input, deps) {
  return runInTransaction(async () => {
    const order = await deps.orders.save(buildOrder(input));
    await deps.inventory.decrement(input.sku, input.qty);
    return order;
  });
}
```

Edge case: nested transactions. Decide policy (reuse outer tx vs. savepoint). The snippet above reuses the outer tx because `db.transaction` should detect an active ALS store.

---

## 4. DTO ↔ domain model leakage

**Problem:** Controllers pass raw `req.body` (with extra fields, wrong types) straight to repositories; DB rows (snake_case, nulls) leak to the API as camelCase entity.

```js
// BAD
app.post('/users', async (req, res) => {
  const row = await db.query('INSERT ... RETURNING *', [req.body]);
  res.json(row); // leaks password_hash, uses DB column names
});
```

**Fix:** Validate at the boundary, map to domain, map back to DTO at the edge.

```js
// application/dto.js
import { z } from 'zod';
export const CreateUserDTO = z.object({
  email: z.string().email(),
  password: z.string().min(8),
});

// domain/User.js
export class User {
  constructor({ id, email, passwordHash }) {
    this.id = id; this.email = email; this.passwordHash = passwordHash;
  }
  static create({ email, password }) {
    return new User({ id: crypto.randomUUID(), email, passwordHash: hash(password) });
  }
}

// infrastructure/mappers/userMapper.js
export const toDomain = (row) => new User({ id: row.id, email: row.email, passwordHash: row.password_hash });
export const toDTO = (u) => ({ id: u.id, email: u.email });

// presentation/userController.js
app.post('/users', async (req, res, next) => {
  const parsed = CreateUserDTO.safeParse(req.body);
  if (!parsed.success) return res.status(400).json(parsed.error.flatten());
  const user = await createUser(parsed.data);          // returns domain entity
  res.status(201).json(toDTO(user));                    // boundary mapping
});
```

---

## 5. Race conditions / stale reads (concurrency)

**Problem:** Two requests read `balance=100`, both subtract 60, both write 40 → lost update.

```js
// BAD
async function withdraw(id, amount) {
  const { balance } = await accounts.findById(id);
  if (balance < amount) throw new Error('Insufficient');
  await accounts.update(id, balance - amount);
}
```

**Fix:** Optimistic locking with a version column; retry on conflict. Or atomic conditional update.

```js
// infrastructure/pgAccountRepo.js
export const pgAccountRepo = {
  async withdraw(id, amount) {
    const r = await db.query(
      'UPDATE accounts SET balance = balance - $1, version = version + 1 ' +
      'WHERE id = $2 AND balance >= $1 RETURNING balance, version',
      [amount, id]
    );
    if (r.rowCount === 0) throw new Error('InsufficientOrConflict');
    return r.rows[0];
  },
};

// application/withdraw.js (retry wrapper for optimistic conflicts)
export async function withdrawWithRetry(id, amount, deps, retries = 3) {
  for (let i = 0; i < retries; i++) {
    try { return await deps.accounts.withdraw(id, amount); }
    catch (e) {
      if (e.code === 'CONFLICT' && i < retries - 1) continue;
      throw e;
    }
  }
}
```

---

## 6. Hard-coded dependencies (untestable layers)

**Problem:** `userService` does `import { db } from '../db.js'` → unit tests hit a real DB.

```js
// BAD
import { db } from '../infrastructure/db.js';
export async function findUser(id) { return db.query('SELECT ...', [id]); }
```

**Fix:** Dependency injection via a factory or constructor. Tests pass fakes.

```js
// application/findUser.js
export function makeFindUser({ users }) {
  return async function findUser(id) {
    const u = await users.findById(id);
    if (!u) throw new NotFound('User');
    return u;
  };
}

// production wiring
const findUser = makeFindUser({ users: pgUserRepo });

// test
test('throws NotFound', async () => {
  const findUser = makeFindUser({ users: { findById: async () => null } });
  await expect(findUser('x')).rejects.toThrow('UserNotFound');
});
```

---

## 7. Caching invalidation across layers

**Problem:** Cache lives in the repository; writes in another code path bypass it → stale reads. Or cache stores serialized domain entities with methods stripped.

```js
// BAD: cache in repo, but bulk import writes via raw SQL
```

**Fix:** Cache at a single choke point (decorator) and invalidate by key pattern; store plain DTOs, rehydrate on read.

```js
// infrastructure/cachedUserRepo.js
export function cached(repo, cache) {
  return {
    async findById(id) {
      const hit = await cache.get(`user:${id}`);
      if (hit) return toDomain(JSON.parse(hit));   // rehydrate
      const u = await repo.findById(id);
      if (u) await cache.set(`user:${id}`, JSON.stringify(toDTO(u)), 'EX', 60);
      return u;
    },
    async save(u) {
      await repo.save(u);
      await cache.del(`user:${u.id}`);             // invalidate
    },
  };
}
```

Edge case: thundering herd on cache miss → use a single-flight lock (`async-mutex` or `p-memoize`).

---

## 8. Partial failure in batch / saga operations

**Problem:** Processing 100 orders: 3 fail midway; you’ve already charged some customers.

```js
// BAD
for (const o of orders) await charge(o); // stops on first throw, leaves partial state
```

**Fix:** Either all-or-nothing transaction, or a saga with compensating actions + per-item result reporting.

```js
// application/batchCharge.js
export async function batchCharge(orders, deps) {
  const results = [];
  for (const o of orders) {
    try {
      await deps.payments.charge(o);
      results.push({ id: o.id, ok: true });
    } catch (e) {
      results.push({ id: o.id, ok: false, error: e.code });
      // compensating: refund previously charged in this batch if policy requires
    }
  }
  return results; // caller decides retry/rollback
}
```

For true atomicity, wrap the loop in `runInTransaction` (see §3) and let one failure roll back all.

---

## 9. Serialization boundaries (Date, BigInt, undefined)

**Problem:** `JSON.stringify(new Date())` → string; `JSON.parse` gives string, not Date. `undefined` fields vanish. BigInt throws.

```js
// BAD
res.json({ createdAt: user.createdAt }); // Date becomes ISO string silently
const x = JSON.parse(body); x.big; // if BigInt was sent, parse already failed
```

**Fix:** Explicit serializers at the presentation boundary; never trust parsed JSON types in domain.

```js
// presentation/serializer.js
export const serializeUser = (u) => ({
  id: u.id,
  email: u.email,
  createdAt: u.createdAt.toISOString(),   // explicit
});

// application/parseCreateUser.js
export function parseCreateUser(raw) {
  return {
    email: String(raw?.email ?? ''),
    birthDate: raw?.birthDate ? new Date(raw.birthDate) : null, // validate with zod
  };
}
```

Use `zod`/`io-ts` to coerce and validate at the edge so domain never sees `unknown`.

---

## 10. Cross-cutting concerns sprinkled through layers

**Problem:** `console.log` / `auth.check` inside services → impossible to test, inconsistent.

```js
// BAD
async function createUser(input) {
  console.log('creating', input.email);
  if (!isAdmin()) throw new Error('Forbidden');
  ...
}
```

**Fix:** Keep services pure; inject logger/auth as deps, or use middleware/decorators.

```js
// application/createUser.js
export function makeCreateUser({ users, logger, authorize }) {
  return async function createUser(input, ctx) {
    authorize(ctx, 'user:create');
    logger.info('creating', { email: input.email });
    const u = User.create(input);
    await users.save(u);
    return u;
  };
}

// presentation: ctx carries { user, requestId }
app.post('/users', (req, res) =>
  createUser(req.body, { user: req.user, requestId: req.id })
    .then(u => res.status(201).json(toDTO(u)))
    .catch(next));
```

---

## 11. Environment/config leaking into domain

**Problem:** `process.env.DB_URL` read inside a service; tests must mutate global env.

```js
// BAD
const stripe = new Stripe(process.env.STRIPE_KEY);
```

**Fix:** Construct infrastructure at the composition root; pass configured instances inward.

```js
// main.js (composition root)
const stripe = new Stripe(process.env.STRIPE_KEY);
const payments = makeStripePayments(stripe);
const createOrder = makeCreateOrder({ payments, orders: pgOrderRepo });
```

---

## 12. N+1 across layer boundaries

**Problem:** Application loop calls `userRepo.findById` per order → N queries; the repository abstraction hides it.

```js
// BAD
const orders = await orderRepo.list();
const users = await Promise.all(orders.map(o => userRepo.findById(o.userId)));
```

**Fix:** Add batch methods to the port; repositories implement efficient joins.

```js
// domain/ports/UserRepository.js
// findByIds(ids): User[]

// application/listOrders.js
const orders = await orderRepo.list();
const users = await userRepo.findByIds([...new Set(orders.map(o => o.userId))]);
const byId = new Map(users.map(u => [u.id, u]));
return orders.map(o => ({ ...o, user: byId.get(o.userId) }));
```

---

## Quick checklist

| Edge case | Guard |
|---|---|
| Circular deps | Dependency inversion / events |
| Error leakage | Map infra errors → domain errors at repo boundary |
| Transactions | Unit of Work / AsyncLocalStorage |
| DTO leakage | Validate + map at presentation boundary |
| Concurrency | Atomic conditional updates / optimistic locking |
| Testability | Factory functions + injected deps |
| Cache staleness | Single choke point + invalidate on write |
| Batch partial failure | Transaction or saga + per-item results |
| Serialization | Explicit serializers; schema validation |
| Cross-cutting | Middleware/decorators, not inline |
| Config | Composition root only |
| N+1 | Batch port methods |

The unifying principle: **keep domain pure, push I/O and policy to the edges, and make every boundary explicit (types, errors, transactions, serialization).**

## Lazy Evaluation in JavaScript

Below is a self-contained, runnable module that builds lazy evaluation from scratch:

- **Lazy values (thunks)** – deferred, memoized computation.
- **Lazy streams** – infinite sequences with deferred heads *and* tails.
- **Lazy collection ops** – `map`, `filter`, `take`, `drop` that build new streams without forcing anything.
- **Lazy function arguments** – simulate call-by-name.
- **Lazy object properties** – computed on first access.
- **Memoization** – caching pure functions.

Save as `lazy.js` and run with `node lazy.js`.

```js
'use strict';

// ============================================================
// 1. LAZY VALUES (thunks)
// ============================================================
function lazy(compute) {
  if (typeof compute !== 'function') throw new TypeError('lazy() expects a function');
  let done = false, value, error;
  const thunk = function force() {
    if (!done) {
      try { value = compute(); }
      catch (e) { error = e; }
      done = true;
    }
    if (error) throw error;
    return value;
  };
  thunk.force = thunk;
  thunk.isForced = () => done;
  thunk.map = (f) => lazy(() => f(thunk()));
  thunk.flatMap = (f) => lazy(() => f(thunk()).force());
  thunk.toString = () => done ? `Lazy(${value})` : 'Lazy(<unevaluated>)';
  return thunk;
}

// ============================================================
// 2. LAZY STREAMS
// ============================================================
class Stream {
  constructor(headThunk, tailThunk) {
    this._headThunk = headThunk;
    this._tailThunk = tailThunk;
    this._head = undefined; this._headForced = false; this._headError = null;
    this._tail = undefined; this._tailForced = false; this._tailError = null;
  }
  head() {
    if (!this._headForced) {
      try { this._head = this._headThunk(); }
      catch (e) { this._headError = e; }
      this._headForced = true;
    }
    if (this._headError) throw this._headError;
    return this._head;
  }
  tail() {
    if (!this._tailForced) {
      try { this._tail = this._tailThunk(); }
      catch (e) { this._tailError = e; }
      this._tailForced = true;
    }
    if (this._tailError) throw this._tailError;
    return this._tail;
  }
  map(f) {
    const self = this;
    if (self == null) return null;
    return new Stream(
      () => f(self.head()),
      () => { const t = self.tail(); return t == null ? null : t.map(f); }
    );
  }
  filter(pred) {
    const self = this;
    if (self == null) return null;
    // Lazily find the first matching node; cache the result.
    let cached = null;
    const findFirst = () => {
      if (cached) return cached;
      let s = self;
      while (s != null) {
        const h = s.head();
        if (pred(h)) { cached = { node: s, val: h }; return cached; }
        s = s.tail();
      }
      cached = { node: null, val: undefined };
      return cached;
    };
    return new Stream(
      () => {
        const c = findFirst();
        if (c.node == null) throw new Error('Stream.filter: no element satisfies predicate');
        return c.val;
      },
      () => {
        const c = findFirst();
        if (c.node == null) return null;
        const t = c.node.tail();
        return t == null ? null : t.filter(pred);
      }
    );
  }
  take(n) {
    const self = this;
    if (self == null || n <= 0) return null;
    return new Stream(
      () => self.head(),
      () => {
        const t = self.tail();
        return t == null ? null : t.take(n - 1);
      }
    );
  }
  drop(n) {
    const self = this;
    if (self == null) return null;
    if (n <= 0) return self;
    return new Stream(
      () => { const t = self.tail(); return t == null ? undefined : t.drop(n - 1) == null ? undefined : t.drop(n - 1).head(); },
      () => { const t = self.tail(); return t == null ? null : t.drop(n - 1) == null ? null : t.drop(n - 1).tail(); }
    );
  }
  toArray(limit = 1000) {
    const res = [];
    let s = this;
    let i = 0;
    while (s != null && i < limit) {
      res.push(s.head());
      s = s.tail();
      i++;
    }
    return res;
  }
  [Symbol.iterator]() {
    let s = this;
    return {
      next() {
        if (s == null) return { done: true };
        const v = s.head();
        s = s.tail();
        return { value: v, done: false };
      }
    };
  }
}

function cons(headThunk, tailThunk) {
  return new Stream(headThunk, tailThunk);
}
const StreamEmpty = null;

function nats(start = 0) {
  return new Stream(() => start, () => nats(start + 1));
}
function repeat(value) {
  return new Stream(() => value, () => repeat(value));
}
function fromArray(arr, i = 0) {
  if (i >= arr.length) return null;
  return new Stream(() => arr[i], () => fromArray(arr, i + 1));
}

// ============================================================
// 3. LAZY FUNCTION ARGUMENTS (call-by-name simulation)
// ============================================================
function lazyIf(cond, thenThunk, elseThunk) {
  // Only the chosen branch is evaluated.
  return cond ? thenThunk() : elseThunk();
}

// ============================================================
// 4. LAZY OBJECT PROPERTIES
// ============================================================
function lazyProperty(obj, prop, compute) {
  let done = false, value, error;
  Object.defineProperty(obj, prop, {
    get() {
      if (!done) {
        try { value = compute.call(obj); }
        catch (e) { error = e; }
        done = true;
      }
      if (error) throw error;
      return value;
    },
    enumerable: true,
    configurable: true
  });
}

// ============================================================
// 5. MEMOIZATION
// ============================================================
function memoize(fn, keyFn = (...a) => JSON.stringify(a)) {
  const cache = new Map();
  return function (...args) {
    const key = keyFn(...args);
    if (cache.has(key)) return cache.get(key);
    const r = fn.apply(this, args);
    cache.set(key, r);
    return r;
  };
}

// ============================================================
// DEMO / SELF-TEST
// ============================================================
function section(title) { console.log('\n=== ' + title + ' ==='); }

section('1. Lazy values are not evaluated until forced');
let evalCount = 0;
const v = lazy(() => { evalCount++; return 40 + 2; });
console.log('created lazy value; evalCount =', evalCount);
console.log('isForced =', v.isForced());
console.log('force() =', v());
console.log('evalCount =', evalCount, '(computed once)');
console.log('second force() =', v.force(), '(no recomputation)');
console.log('evalCount =', evalCount);
console.log('map: v.map(x=>x*2)() =', v.map(x => x * 2)());
console.log('toString =', String(v));

section('2. Lazy streams: infinite sequences');
let headEvals = 0;
const squares = nats(1).map(x => { headEvals++; return x * x; });
console.log('created infinite stream of squares; headEvals =', headEvals);
const first5 = squares.take(5).toArray();
console.log('take(5).toArray() =', first5);
console.log('headEvals =', headEvals, '(only first 5 squared)');
const evens = nats(0).filter(x => x % 2 === 0);
console.log('first 6 evens =', evens.take(6).toArray());

section('3. Composed lazy pipeline');
const pipeline = nats(1)
  .map(x => x * x)
  .filter(x => x % 2 !== 0)   // odd squares
  .map(x => x + 1);
console.log('first 8 of (n^2+1 for odd squares) =', pipeline.take(8).toArray());

section('4. Lazy function arguments');
let aEval = 0, bEval = 0;
const expensiveA = () => { aEval++; return 'A-result'; };
const expensiveB = () => { bEval++; return 'B-result'; };
const r = lazyIf(true, expensiveA, expensiveB);
console.log('lazyIf(true,...) =', r, '| aEval =', aEval, 'bEval =', bEval, '(only chosen branch ran)');

section('5. Lazy object properties');
const obj = {};
lazyProperty(obj, 'heavy', function () {
  console.log('  computing heavy property...');
  return 7 * 6;
});
console.log('accessing obj.heavy:', obj.heavy);
console.log('accessing again:', obj.heavy, '(cached)');

section('6. Memoization');
const slowFib = memoize(function fib(n) {
  if (n < 2) return n;
  return slowFib(n - 1) + slowFib(n - 2);
});
console.log('fib(30) =', slowFib(30), '(fast due to memoization)');

section('7. Iteration with for...of (finite slice)');
let count = 0;
for (const x of nats(10).take(4)) {
  console.log('  iter', ++count, x);
}

section('8. drop()');
console.log('nats(0).drop(5).take(4).toArray() =', nats(0).drop(5).take(4).toArray());

console.log('\nAll demos completed.');
```

### How it works

- **`lazy(fn)`** returns a callable thunk. The first call runs `fn`, caches the result (or error), and every later call returns the cached value — so the expensive computation happens **at most once**, and only when something actually needs the value.
- **`Stream`** stores both `head` and `tail` as thunks. Nothing is computed until `.head()` / `.tail()` is called, and memoized per node. `map`/`filter`/`take` return new streams whose thunks close over the previous stream — building a **lazy pipeline** with no intermediate arrays.
- **`filter`** scans forward only when forced, and caches the first matching node so `head()` and `tail()` don't rescan.
- **`lazyIf`** takes thunks (functions) instead of values, so the unused branch is never evaluated — simulating call-by-name in a strict language.
- **`lazyProperty`** uses `Object.defineProperty` with a getter that computes once and caches.
- **`memoize`** caches by a key derived from arguments.

### Notes / pitfalls

- JS is **strict**: arguments are evaluated before a function runs. True lazy arguments require passing thunks (`() => expr`) and calling them inside, as shown.
- Infinite streams are safe only with terminating operations (`take`, `drop`, manual loops with breaks).
- `drop` above is a simplified, somewhat eager implementation for demonstration; a production version would cache the dropped prefix.
- For real-world use, prefer native generators (`function*`) plus `for...of`, which give laziness with less boilerplate — but the above shows the underlying mechanics.

## Lazy evaluation in JavaScript

JavaScript is **eager by default**: arguments are evaluated before a function runs, and expressions are computed as soon as they appear. “Lazy evaluation” means **deferring work until the result is actually needed**, usually by wrapping computation in a function (a *thunk*) or using a generator/iterator.

### 1. The core idea: thunks

A thunk is a zero-argument function that produces a value later.

```js
// Eager: expensive() runs immediately
const value = expensive();

// Lazy: expensive() runs only when value() is called
const value = () => expensive();

if (shouldCompute) {
  console.log(value());
}
```

This is the most common JS “lazy evaluation”: **functions are first-class values**, so you can pass around unevaluated computations.

### 2. Lazy properties with closures / memoization

Compute once, only when first accessed, then cache.

```js
function lazyProp(compute) {
  let cached;
  let done = false;
  return () => {
    if (!done) {
      cached = compute();
      done = true;
    }
    return cached;
  };
}

const getUser = lazyProp(() => {
  console.log("fetching...");
  return { id: 1, name: "Ada" };
});

// Nothing happens yet
console.log("ready");

// First access computes
console.log(getUser().name);

// Later accesses reuse cached value
console.log(getUser().id);
```

### 3. Lazy object properties with `Proxy`

Useful when you want property access itself to trigger computation.

```js
const data = new Proxy({}, {
  get(target, prop) {
    if (!(prop in target)) {
      target[prop] = `computed:${String(prop)}`;
    }
    return target[prop];
  }
});

console.log(data.a); // computed:a
console.log(data.a); // computed:a  (cached)
```

### 4. Generators and iterators (lazy sequences)

Generators produce values **on demand**, which is ideal for large or infinite sequences.

```js
function* range(start, end) {
  for (let i = start; i < end; i++) yield i;
}

const nums = range(0, 1_000_000);

console.log(nums.next().value); // 0
console.log(nums.next().value); // 1
// The rest are never generated unless requested
```

Lazy transformation pipelines:

```js
function* map(iter, fn) {
  for (const x of iter) yield fn(x);
}

function* filter(iter, pred) {
  for (const x of iter) if (pred(x)) yield x;
}

const result = filter(
  map(range(0, 100), x => x * x),
  x => x % 2 === 0
);

// Only computes as much as needed
for (const n of result) {
  if (n > 20) break;
  console.log(n);
}
```

### 5. Built-in “lazy-ish” evaluation

Some JS constructs already avoid evaluating parts of an expression.

```js
// Short-circuit: right side runs only if left is truthy/falsy as needed
const name = user && user.profile && user.profile.name;

// Nullish coalescing
const title = input ?? "Untitled";

// Conditional expression
const label = isAdmin ? "Admin" : "User";

// Logical assignment
config.timeout ??= 3000;
```

These are not full lazy evaluation, but they are **conditional evaluation**.

### 6. Lazy module loading

Dynamic `import()` defers loading code until needed.

```js
button.addEventListener("click", async () => {
  const { heavyFeature } = await import("./heavy-feature.js");
  heavyFeature();
});
```

This reduces initial bundle cost and only loads code on demand.

### 7. Promises and async functions

A Promise constructor runs its executor immediately, so it is not truly lazy. But the *consumption* of async work can be deferred.

```js
// Eager executor starts now
const p = new Promise((resolve) => {
  console.log("starting work");
  resolve(42);
});

// Lazy-ish: work starts only when .then is attached? 
// Not exactly; executor already ran. Prefer thunks for true laziness.
const lazyTask = () => fetch("/api/data").then(r => r.json());
```

For true lazy async work, wrap in a function:

```js
const loadUser = () => fetch("/users/1").then(r => r.json());

// Nothing happens until called
if (needsUser) {
  const user = await loadUser();
}
```

### 8. Typical use cases

- **Expensive computations** that may not be needed.
- **Infinite or very large data streams** using generators.
- **Conditional feature loading** with dynamic `import()`.
- **Lazy initialization** of objects/services.
- **Memoized derived values** in UI/state logic.
- **Short-circuit checks** to avoid null dereferences.
- **Pagination/virtualization**: compute/render only visible items.

### Summary

JavaScript does not have built-in call-by-need lazy evaluation like Haskell, but you can achieve it with:

- **Thunks**: `() => value`
- **Generators/iterators**: `function*`
- **Proxy**: lazy property access
- **Dynamic import**: lazy module loading
- **Short-circuit operators**: conditional evaluation

Use eager evaluation for simple, cheap values; use lazy patterns when work is expensive, optional, or potentially infinite.

A classic JavaScript mistake is assuming a closure “captures the value” of a variable at the time the closure is created. In reality, it captures the variable binding, and the variable is evaluated later when the closure runs.

### Mistaken version

```js
for (var i = 0; i < 3; i++) {
  setTimeout(() => {
    console.log("mistake:", i);
  }, 0);
}
```

Expected output:

```text
mistake: 0
mistake: 1
mistake: 2
```

Actual output:

```text
mistake: 3
mistake: 3
mistake: 3
```

### Corrected version

Use block-scoped `let`, which creates a fresh binding for each loop iteration:

```js
for (let i = 0; i < 3; i++) {
  setTimeout(() => {
    console.log("correct:", i);
  }, 0);
}
```

Output:

```text
correct: 0
correct: 1
correct: 2
```

### Another corrected version: capture the value eagerly

If you must use `var`, pass the current value into an immediately invoked function expression:

```js
for (var i = 0; i < 3; i++) {
  (function (capturedI) {
    setTimeout(() => {
      console.log("captured:", capturedI);
    }, 0);
  })(i);
}
```

Output:

```text
captured: 0
captured: 1
captured: 2
```

### Why the mistake happens

1. `var i` is function-scoped, not block-scoped.
2. All three callbacks close over the same `i` binding.
3. `setTimeout` does not run the callback immediately; it schedules it for later.
4. By the time the callbacks actually execute, the loop has finished and `i` is `3`.
5. The expression `i` inside the callback is therefore evaluated lazily at callback execution time, not at callback creation time.

Using `let` fixes this because JavaScript creates a new lexical environment for each iteration of a `for` loop when `let` is used. Each callback then closes over its own separate `i`.

The IIFE version fixes it differently: it evaluates `i` immediately during the loop and stores that value in `capturedI`, so the callback no longer depends on the later value of the loop variable.

## Common pitfalls with lazy evaluation in JavaScript

JavaScript has no built-in “lazy by default” evaluation, but lazy patterns are common via **generators, iterators, thunks, lazy getters, Proxies, streams, and memoized functions**. Most pitfalls come from the gap between *when work is scheduled* and *when it actually runs*.

---

### 1. Side effects happen at consumption time, not creation time

Lazy code can make side effects appear “delayed” or surprising.

```js
function* numbers() {
  console.log("start");
  yield 1;
  console.log("middle");
  yield 2;
  console.log("end");
}

const gen = numbers(); // Nothing printed yet
console.log("created");

const first = gen.next().value; // prints "start"
console.log(first); // 1
```

**Pitfall:** Logs, network calls, mutations, or DOM updates may occur later than readers expect.  
**Fix:** Keep lazy computations pure; perform side effects eagerly or in explicitly controlled boundaries.

---

### 2. Repeated evaluation without memoization

A thunk or generator-derived value may be computed more than once.

```js
function makeThunk(fn) {
  return () => fn(); // evaluated every call
}

const expensive = makeThunk(() => {
  console.log("computing");
  return 42;
});

expensive(); // computing
expensive(); // computing again
```

**Fix:** Memoize the result.

```js
function memoThunk(fn) {
  let done = false;
  let value;
  return () => {
    if (!done) {
      value = fn();
      done = true;
    }
    return value;
  };
}
```

---

### 3. Capturing mutable variables by reference

Lazy closures capture variables, not their values at creation time.

```js
const thunks = [];
for (let i = 0; i < 3; i++) {
  thunks.push(() => i); // captures i by reference
}
console.log(thunks.map(f => f())); // [3, 3, 3] if using var; with let each iteration binding is separate but still easy to misuse
```

With `var`, all closures share one binding:

```js
const thunks2 = [];
for (var i = 0; i < 3; i++) {
  thunks2.push(() => i);
}
console.log(thunks2.map(f => f())); // [3, 3, 3]
```

**Fix:** Capture the current value explicitly.

```js
for (let i = 0; i < 3; i++) {
  thunks.push(() => i); // let creates per-iteration binding, so this is okay
}
// or
for (var i = 0; i < 3; i++) {
  thunks2.push(((x) => () => x)(i));
}
```

---

### 4. Iterators are single-use

Lazy iterables can usually be consumed only once.

```js
function* nums() {
  yield 1;
  yield 2;
}

const it = nums();
console.log([...it]); // [1, 2]
console.log([...it]); // [] — exhausted
```

**Pitfall:** Passing the same iterator to multiple consumers yields empty results later.  
**Fix:** Create a new generator each time, or materialize into an array when reuse is needed.

---

### 5. Infinite sequences without bounded consumption

Lazy generators make infinite streams easy, but forcing them eagerly crashes or hangs.

```js
function* naturals() {
  let n = 1;
  while (true) yield n++;
}

const all = [...naturals()]; // RangeError / hang
```

**Fix:** Always bound consumption.

```js
function take(iterable, n) {
  const result = [];
  const it = iterable[Symbol.iterator]();
  for (let i = 0; i < n; i++) {
    const { value, done } = it.next();
    if (done) break;
    result.push(value);
  }
  return result;
}

console.log(take(naturals(), 5)); // [1, 2, 3, 4, 5]
```

---

### 6. Exceptions surface at consumption, not construction

Errors in lazy code are thrown when `.next()` or spread runs, not when the lazy object is created.

```js
function* bad() {
  yield 1;
  throw new Error("boom");
}

const g = bad(); // no error yet
try {
  console.log([...g]); // error thrown here
} catch (e) {
  console.error(e.message);
}
```

**Pitfall:** Stack traces and `try/catch` placement can be misleading.  
**Fix:** Wrap consumption boundaries; document where evaluation occurs.

---

### 7. Non-strict ordering of side effects

Lazy pipelines may reorder or skip work depending on consumption.

```js
function* source() {
  yield 1;
  console.log("produced 2");
  yield 2;
}

const pipeline = Array.from(source()).map(x => x * 10);
// "produced 2" printed during Array.from, before map runs
```

With conditional consumption, later items may never be produced:

```js
function firstEven(gen) {
  for (const x of gen) {
    if (x % 2 === 0) return x;
  }
}

function* nums2() {
  console.log("yield 1");
  yield 1;
  console.log("yield 2");
  yield 2;
}

console.log(firstEven(nums2()));
// prints "yield 1", "yield 2", then 2
// but if first value were even, "yield 2" would never print
```

**Pitfall:** Side-effectful generators are hard to reason about.  
**Fix:** Avoid side effects inside lazy producers; separate data production from effects.

---

### 8. Lazy values can retain large inputs

A thunk or closure can keep an entire large array or object alive.

```js
function makeSummary(data) {
  return () => data.length; // retains `data`
}

const huge = new Array(10_000_000).fill(0);
const summary = makeSummary(huge);
// `huge` cannot be GC'd while `summary` exists
```

**Fix:** Extract only needed primitive state, or null out large references after computation.

---

### 9. Async lazy evaluation and interleaving

Async generators and lazy Promises can interleave in unexpected ways.

```js
async function* fetchPages(urls) {
  for (const url of urls) {
    const res = await fetch(url);
    yield await res.json();
  }
}

// Consumption order determines request order
for await (const page of fetchPages(urls)) {
  console.log(page);
}
```

Also, creating a lazy Promise does not start work until `.then()` or `await`:

```js
const p = (async () => {
  console.log("started");
  return 42;
})();

// Work starts immediately because IIFE executes eagerly.
// A true lazy async thunk:
const lazyAsync = () => (async () => {
  console.log("started lazily");
  return 42;
})();

const thunk = lazyAsync(); // still not started until awaited
await thunk; // now starts
```

**Pitfall:** Mixing eager async IIFEs with lazy thunks creates confusing timing.  
**Fix:** Be explicit about whether async work starts at creation or consumption.

---

### 10. Resource cleanup with generators

Generators may hold resources (files, sockets, locks). If abandoned early, cleanup may not run unless `return()`/`throw()` is called or the generator is closed.

```js
function* withResource() {
  const resource = { close() { console.log("closed"); } };
  try {
    yield resource;
    yield "more";
  } finally {
    resource.close();
  }
}

const g = withResource();
console.log(g.next().value); // resource
// If we stop here, "closed" may not print until GC/finalization in some engines
g.return(); // explicitly closes, runs finally
```

**Fix:** Use `try/finally`, call `.return()` on early exit, or prefer higher-level stream APIs with disposal.

---

### 11. `this` binding in lazy getters

Lazy property getters can lose `this` depending on how they are accessed.

```js
class User {
  constructor(name) {
    this.name = name;
  }
  get displayName() {
    return this.name.toUpperCase();
  }
}

const u = new User("ada");
const getter = Object.getOwnPropertyDescriptor(
  Object.getPrototypeOf(u),
  "displayName"
).get;

// getter(); // TypeError: Cannot read properties of undefined
console.log(getter.call(u)); // "ADA"
```

**Fix:** Access lazy getters as properties (`obj.prop`), not detached functions, or bind explicitly.

---

### 12. Debugging and logging are delayed

Because values are not computed until used, breakpoints and `console.log` may appear out of source order.

```js
const lazy = () => {
  console.log("evaluating");
  return 1 + 2;
};

console.log("before");
const value = lazy(); // "evaluating" prints here, not where lazy was defined
console.log("after", value);
```

**Fix:** Add explicit evaluation markers, use eager computation in debug builds, or materialize lazy pipelines before inspecting.

---

### Practical guidelines

- Prefer **pure** lazy computations.
- Memoize expensive thunks.
- Bound all infinite or large lazy sequences.
- Avoid side effects inside generators and lazy pipelines.
- Treat iterators as **single-use**.
- Close generators/resources explicitly.
- Make async laziness explicit.
- Separate “describe work” from “perform work.”

A common safe pattern:

```js
function lazyPipe(source, ...transforms) {
  return function* () {
    let it = source[Symbol.iterator]();
    for (const transform of transforms) {
      it = transform(it);
    }
    yield* it;
  };
}
```

This keeps evaluation lazy, bounded, and composable while avoiding hidden side effects.

## Exercise

Implement a **lazy number pipeline** in JavaScript:

- Start from an *infinite* range `0, 1, 2, …`
- Keep only numbers `n` such that `n * n` is divisible by `3`
- Map each kept number to `n * n`
- Take only the first `5` results
- Materialize to an array

**Constraint:** Do not generate the whole infinite sequence. Only compute values as needed.

---

## Step-by-step solution

### 1. Core idea: wrap an iterable factory

Lazy evaluation means “describe the computation now, execute it later.”  
We wrap a **generator function** in a small class. Each operation (`map`, `filter`, `take`) returns a *new* lazy sequence whose generator pulls from the previous one only when iterated.

### 2. Implement `LazySeq`

```js
class LazySeq {
  constructor(factory) {
    // factory: () => Iterable
    this._factory = factory;
  }

  [Symbol.iterator]() {
    return this._factory()[Symbol.iterator]();
  }

  static fromIterable(iterable) {
    return new LazySeq(() => iterable);
  }

  map(fn) {
    const source = this;
    return new LazySeq(function* () {
      for (const x of source) yield fn(x);
    });
  }

  filter(pred) {
    const source = this;
    return new LazySeq(function* () {
      for (const x of source) if (pred(x)) yield x;
    });
  }

  take(n) {
    const source = this;
    return new LazySeq(function* () {
      let count = 0;
      for (const x of source) {
        if (count >= n) break;
        yield x;
        count++;
      }
    });
  }

  toArray() {
    return [...this];
  }
}
```

### 3. Infinite range helper

```js
function InfiniteRange(start = 0) {
  return new LazySeq(function* () {
    for (let i = start; ; i++) yield i;
  });
}
```

### 4. Build the pipeline

```js
const result = InfiniteRange(0)
  .filter(n => (n * n) % 3 === 0)
  .map(n => n * n)
  .take(5)
  .toArray();

console.log(result);
// [0, 9, 36, 81, 144]
```

### 5. Why this is lazy

- `InfiniteRange(0)` never loops forever by itself.
- `filter` only tests numbers when the consumer asks for the next value.
- `take(5)` stops pulling after 5 accepted values, so the infinite source stops early.
- `toArray()` is the only eager step; everything before it is a description of work.

### 6. Quick verification of laziness

You can add a side-effect counter to prove minimal work:

```js
let inspected = 0;

const lazy = InfiniteRange(0)
  .filter(n => { inspected++; return (n * n) % 3 === 0; })
  .map(n => n * n)
  .take(5);

console.log("before toArray, inspected =", inspected); // 0
const out = lazy.toArray();
console.log("after toArray, inspected =", inspected);   // 9 (0..8 needed for 5 hits)
console.log(out);
```

Only 9 numbers are inspected, not an infinite amount.

---

## Final solution

```js
class LazySeq {
  constructor(factory) { this._factory = factory; }
  [Symbol.iterator]() { return this._factory()[Symbol.iterator](); }
  static fromIterable(it) { return new LazySeq(() => it); }
  map(fn) {
    const s = this;
    return new LazySeq(function* () { for (const x of s) yield fn(x); });
  }
  filter(pred) {
    const s = this;
    return new LazySeq(function* () { for (const x of s) if (pred(x)) yield x; });
  }
  take(n) {
    const s = this;
    return new LazySeq(function* () {
      let c = 0;
      for (const x of s) { if (c >= n) break; yield x; c++; }
    });
  }
  toArray() { return [...this]; }
}

function InfiniteRange(start = 0) {
  return new LazySeq(function* () { for (let i = start; ; i++) yield i; });
}

const result = InfiniteRange(0)
  .filter(n => (n * n) % 3 === 0)
  .map(n => n * n)
  .take(5)
  .toArray();

console.log(result); // [0, 9, 36, 81, 144]
```

## Lazy evaluation in JavaScript (interview answer)

**Concept.** Lazy evaluation means *don’t compute a value until it is actually needed*, and (with “call-by-need”) *never compute it more than once*. JavaScript is eager by default: arguments are evaluated before the function runs, array methods like `.map` build full intermediate arrays immediately, etc. We can *simulate* laziness with:

1. **Thunks** – a zero-arg function wrapping a computation (`() => expensive()`).
2. **Memoization** – cache the thunk’s result so repeated “forcing” is cheap (this turns call-by-name into call-by-need).
3. **Lazy data structures** – e.g. streams, where the tail is a suspended computation. Demand (`take`, indexing) drives evaluation.
4. **Demand-driven pipelines** – combinators (`map`, `filter`) build new thunks but do no work until consumed.

**Why it matters:** infinite sequences, better memory/perf (no intermediate arrays), and modular “generate everything, consume a little” pipelines. Trade-offs: harder debugging/stack traces, retained closures (memory), and side effects happen at unpredictable times.

### Core implementation

```js
/* ============================================================
 * 1. Memoized thunk = lazy value (call-by-need)
 *    force() computes at most once; afterwards returns cached value.
 * ============================================================ */
function lazy(compute) {
  let done = false;
  let cached;
  return function force() {
    if (!done) {
      cached = compute();
      done = true;          // even if compute throws, you may want to reset; omitted for clarity
    }
    return cached;
  };
}

// Usage:
// const v = lazy(() => { console.log('computing'); return 42; });
// v(); // logs "computing", returns 42
// v(); // no log, returns 42


/* ============================================================
 * 2. Lazy streams (infinite lists)
 *    A node = { head, tail() } where tail() is memoized.
 *    EMPTY (null) terminates finite streams.
 * ============================================================ */
const EMPTY = null;

function cons(head, tailFn) {
  // tailFn: () => stream  (suspended computation)
  let cache;
  let evaluated = false;
  return Object.freeze({
    head,
    tail() {
      if (!evaluated) {
        cache = tailFn();   // compute once
        evaluated = true;
      }
      return cache;
    }
  });
}

// --- combinators: build thunks, do no work until forced ---

function map(f, stream) {
  if (stream === EMPTY) return EMPTY;
  return cons(f(stream.head), () => map(f, stream.tail()));
}

function filter(pred, stream) {
  if (stream === EMPTY) return EMPTY;
  if (pred(stream.head)) {
    return cons(stream.head, () => filter(pred, stream.tail()));
  }
  // skip current element; stays lazy because tail() is a thunk
  return filter(pred, stream.tail());
}

// Consumer: pulls `n` elements, forcing only what is needed.
function take(n, stream) {
  const out = [];
  let s = stream;
  for (let i = 0; i < n && s !== EMPTY; i++) {
    out.push(s.head);
    s = s.tail(); // forces next node on demand
  }
  return out;
}

// Infinite source
function naturals(start = 0) {
  return cons(start, () => naturals(start + 1));
}


/* ============================================================
 * 3. Demos
 * ============================================================ */

// Infinite evens: nothing computed until take() pulls.
const evens = filter(x => x % 2 === 0, naturals());
console.log(take(5, evens));   // [0, 2, 4, 6, 8]

// Squares of first 4 odd numbers, computed lazily.
const odds   = filter(x => x % 2 !== 0, naturals(1));
const squares = map(x => x * x, odds);
console.log(take(4, squares)); // [1, 9, 25, 49]

// Lazy value reuse
const heavy = lazy(() => {
  console.log('heavy running once');
  return 7 * 6;
});
console.log(heavy(), heavy()); // logs once, prints 42 42
```

### How demand flows (the “core” idea)

1. `naturals()` returns one cons node; its tail is a **thunk**, not a value.
2. `filter`/`map` wrap results in more cons nodes whose tails are thunks — still no traversal.
3. `take(n, stream)` is the *consumer*: it reads `.head`, then calls `.tail()` which finally invokes the thunk, materializing exactly one more node.
4. Because `tail()` memoizes, sharing a stream (e.g. `const a = evens; const b = evens;`) does not recompute nodes.

### Common interview follow-ups

- **Generators as laziness in JS:** `function*` + `yield` gives lazy iteration natively; streams above are the “manual” version that compose like values.
- **Lazy object properties:** use a `Proxy` or getter that caches on first read.
- **`&&` / `||` / `??`** are already lazy (short-circuit evaluation).
- **Pitfalls:** thunks capture scope (memory leaks), error handling gets deferred, and strict-mode/TS typing of lazy values can be awkward; many libs wrap lazy values in an `{ force() }` or monadic type.

If you’d like, I can extend this with **lazy Promise/async streams**, a **lazy `zipWith`**, or a **Proxy-based lazy record**.

Lazy evaluation in JavaScript usually appears as **thunks**, **getters**, **generators/iterators**, **Proxy-based virtual objects**, or **lazy chains** (e.g. lodash).  
The main risk is that deferring work changes *when* (and *how many times*) code runs, which interacts badly with side effects, mutation, errors, `this`, coercion, serialization, and infinite data.

Below are the important edge cases with runnable examples.

---

## 1. Side effects run late and possibly multiple times

```js
// A plain thunk: nothing runs until called
const lazy = () => {
  console.log('computing');
  return Math.random();
};

console.log('before');
const a = lazy();   // logs "computing"
const b = lazy();   // logs "computing" AGAIN
console.log(a !== b); // true
```

**Fix: memoize if the value should be computed once.**

```js
function memoThunk(fn) {
  let done = false, value;
  return () => {
    if (!done) { value = fn(); done = true; }
    return value;
  };
}

const lazyOnce = memoThunk(() => {
  console.log('computing once');
  return Math.random();
});

lazyOnce(); // computes
lazyOnce(); // no log, same value
```

---

## 2. Mutation of captured state between creation and use

```js
let data = [1, 2, 3];

// Lazy closure captures the *variable binding*, not a snapshot
const lazy = () => data.map(x => x * 2);

data = [10, 20];          // reassign
console.log(lazy());      // [20, 40] — surprising if you expected [2,4,6]

// Also dangerous with arrays mutated in place:
const arr = [1, 2, 3];
const lazy2 = () => arr.map(x => x * 2);
arr.push(4);
console.log(lazy2());     // [2,4,6,8]
```

**Fix: snapshot inputs eagerly if the lazy value must be stable.**

```js
const snapshot = data.slice();
const lazyStable = () => snapshot.map(x => x * 2);
```

---

## 3. Re-entrant / recursive getters cause stack overflow

```js
const obj = {};
Object.defineProperty(obj, 'x', {
  get() {
    // BUG: reading this.x invokes the getter again
    return this.x + 1;
  }
});

try {
  console.log(obj.x);
} catch (e) {
  console.log(e instanceof RangeError); // true
}
```

**Fix: compute into a backing field or use a WeakMap.**

```js
const store = new WeakMap();
const obj2 = {};
Object.defineProperty(obj2, 'x', {
  get() {
    if (!store.has(this)) store.set(this, 1);
    return store.get(this);
  }
});
```

---

## 4. Errors are thrown at consumption time, not definition time

```js
const lazy = () => {
  throw new Error('boom');
};

// Definition site: no exception
let v;
try {
  v = lazy;          // just stores function
} catch {
  console.log('caught at def'); // never runs
}

// Consumption site: exception escapes here
try {
  v();
} catch (e) {
  console.log('caught at use:', e.message);
}
```

**Implication:** stack traces and `try/catch` boundaries must surround the *use*, not the *creation*. In async code, unhandled lazy errors can become unhandled promise rejections.

---

## 5. Infinite sequences must be explicitly bounded

```js
function* naturals() {
  let i = 0;
  while (true) yield i++;
}

// BAD: materializes forever
// const all = [...naturals()];

// GOOD: take only what you need
function take(gen, n) {
  const out = [];
  for (const x of gen) {
    if (out.length >= n) break;
    out.push(x);
  }
  return out;
}
console.log(take(naturals(), 5)); // [0,1,2,3,4]
```

Also beware `for await...of` on async infinite generators without cancellation.

---

## 6. Generators hold state and can be driven externally

```js
function* gen() {
  console.log('start');
  const x = yield 1;
  console.log('received', x);
  yield 2;
}

const g = gen();
console.log(g.next());        // {value:1, done:false}, logs "start"
// Inject a value / throw / close early:
console.log(g.next(42));      // logs "received 42"
g.return('done');             // forces completion
console.log(g.next());        // {value:undefined, done:true}
```

**Edge cases:**
- Calling `.next()` after completion keeps returning `{done:true}`.
- `.throw(err)` injects an exception at the current `yield`.
- Forgetting to close generators can retain references (memory).

---

## 7. `this` binding is lost when extracting lazy values

```js
const obj = {
  factor: 2,
  get value() {
    return this.factor * 10;   // depends on `this`
  }
};

const v = obj.value;          // evaluated immediately with this=obj -> 20
console.log(v);               // 20, not a lazy function

// If you want a lazy method, use a thunk and bind:
const lazyMethod = obj.value.bind?.(obj); // already evaluated, not lazy

// Correct pattern: store a thunk that closes over obj
const lazy2 = () => obj.factor * 10;
```

Getters are **eager on access**; they are not thunks. Confusing the two leads to `this` bugs.

---

## 8. Coercion and operators trigger evaluation unexpectedly

```js
const lazy = {
  get value() {
    console.log('evaluated');
    return 5;
  },
  [Symbol.toPrimitive](hint) {
    return this.value;
  }
};

// These all evaluate:
console.log(+lazy);            // logs "evaluated", 5
console.log(lazy == 5);        // logs "evaluated"
console.log(String(lazy));      // logs "evaluated"

// But boolean context does NOT coerce via toPrimitive for objects:
if (lazy) console.log('truthy without evaluating value?'); // object is truthy, no toPrimitive call
```

**Implication:** using lazy objects in arithmetic, comparisons, template strings, or `JSON.stringify` will evaluate them.

---

## 9. Serialization invokes getters and may throw

```js
const o = {
  get x() {
    console.log('getter ran');
    return 42;
  },
  get y() {
    throw new Error('nope');
  }
};

console.log(JSON.stringify(o)); // invokes x, then throws on y
```

Also, non-enumerable getters are skipped by `JSON.stringify`, while enumerable getters are invoked. If you want lazy data excluded from serialization, define getters as non-enumerable.

---

## 10. Proxy-based laziness has invariants

```js
const target = {};
const p = new Proxy(target, {
  get(t, prop) {
    if (prop === 'then') return undefined; // avoid thenable detection
    console.log('lazy get', prop);
    return 123;
  }
});

console.log(p.foo); // logs and returns 123

// Invariant pitfalls:
// - If target has a non-writable, non-configurable property, get must return same value.
// - If target is non-extensible, has/get invariants apply.
// - Returning a different value for 'then' can make the proxy thenable.
```

Also, `Object.keys`, spread, and destructuring will trigger many traps at once.

---

## 11. Destructuring and spread fully evaluate lazy iterables

```js
function* lazySeq() {
  console.log('yield 1'); yield 1;
  console.log('yield 2'); yield 2;
}

const [a, b] = lazySeq();        // evaluates both
console.log(a, b);

const copy = [...lazySeq()];      // evaluates all
```

If the generator is infinite, spread/destructuring hangs. Use partial consumption.

---

## 12. Async laziness: backpressure, cancellation, and ordering

```js
async function* lazyFetch(urls) {
  for (const u of urls) {
    const res = await fetch(u);   // runs only when consumed
    yield res.json();
  }
}

const g = lazyFetch(['/a', '/b']);

// Pull-based: second fetch won't start until first is consumed
console.log(await g.next()); // fetches /a
console.log(await g.next()); // fetches /b
```

**Edge cases:**
- If the consumer stops early, in-flight fetches may still complete unless you use `AbortController`.
- Errors surface at `await g.next()`, not at creation.
- Concurrent consumers sharing one generator will interleave pulls.

---

## 13. Memory retention in closures

```js
function makeLazy() {
  const huge = new Array(1_000_000).fill('x');
  // The thunk keeps `huge` alive even after makeLazy returns
  return () => huge.length;
}

const f = makeLazy();
// `huge` cannot be GC'd until f is GC'd
```

**Fix:** compute and release references inside the thunk when possible.

```js
function makeLazy2() {
  const huge = new Array(1_000_000).fill('x');
  const len = huge.length; // extract needed value
  return () => len;        // huge can be collected
}
```

---

## 14. Equality and identity surprises

```js
const lazyA = () => ({ n: 1 });
const lazyB = () => ({ n: 1 });

console.log(lazyA() === lazyB()); // false (new object each call)
console.log(lazyA() === lazyA()); // false (unless memoized)
```

If you use lazy values as React props, dependency-array items, or Map keys, non-memoized thunks break referential equality and cause re-renders / cache misses.

---

## 15. Nested laziness and evaluation order

```js
const inner = () => { console.log('inner'); return 2; };
const outer = () => { console.log('outer'); return inner() + 1; };

// Nothing logs until called:
outer(); // logs "outer" then "inner"
```

If `inner` has side effects, its timing depends on when `outer` is evaluated, which may differ from source order expectations. Keep lazy functions **pure** when possible.

---

## Practical checklist

- Make lazy functions **pure** and **idempotent**; memoize if side effects must run once.  
- Snapshot mutable inputs if stability matters.  
- Guard getters against recursion with backing storage.  
- Bound infinite generators with `take`/`limit`.  
- Surround **consumption** (not creation) with error handling.  
- Be careful with `this`, coercion, `JSON.stringify`, spread, and destructuring—they force evaluation.  
- For async laziness, handle cancellation and partial consumption.  
- Release large captured references after extracting needed data.  

If you tell me which lazy pattern you’re using (thunks, generators, getters, Proxy, or a library like lodash), I can give more targeted pitfalls.

Below is a complete, runnable Node.js example that covers:

1. **JavaScript’s built-in arrays** (dynamic, list-like behavior).
2. A **from-scratch dynamic array** (like `ArrayList`) with growth/shrink logic.
3. A **from-scratch singly linked list** with common operations.
4. A small demo with assertions so you can run it directly.

Save as `lists_arrays.js` and run with `node lists_arrays.js`.

```js
// lists_arrays.js
// Run with: node lists_arrays.js

/* ============================================================
   1) Built-in Array (JavaScript's default "list")
   ============================================================ */

function demoBuiltinArray() {
  console.log("=== Built-in Array ===");
  const a = [];                 // dynamic list
  a.push(10, 20, 30);          // amortized O(1)
  a.unshift(5);                 // O(n) (shifts elements)
  console.log("after push/unshift:", a); // [5,10,20,30]

  a.splice(2, 1, 99);           // insert/remove at index
  console.log("after splice:", a); // [5,10,99,30]

  const popped = a.pop();       // O(1)
  console.log("popped:", popped, "remaining:", a);

  console.log("indexOf 99:", a.indexOf(99));
  console.log("includes 10:", a.includes(10));

  // Iteration
  for (const x of a) console.log("  item:", x);

  // Functional style
  const doubled = a.map(x => x * 2);
  const evens = a.filter(x => x % 2 === 0);
  console.log("doubled:", doubled, "evens:", evens);
}

/* ============================================================
   2) Dynamic Array implemented from scratch
   ============================================================ */

class DynamicArray {
  constructor(initialCapacity = 4) {
    if (initialCapacity < 1) throw new Error("capacity must be >= 1");
    this._capacity = initialCapacity;
    this._size = 0;
    this._data = new Array(this._capacity);
  }

  get length() { return this._size; }
  get capacity() { return this._capacity; }

  _resize(newCapacity) {
    if (newCapacity < this._size) throw new Error("new capacity too small");
    const next = new Array(newCapacity);
    for (let i = 0; i < this._size; i++) next[i] = this._data[i];
    this._data = next;
    this._capacity = newCapacity;
  }

  _ensureCapacity(min) {
    if (this._capacity >= min) return;
    let c = this._capacity;
    while (c < min) c *= 2;
    this._resize(c);
  }

  push(value) {
    this._ensureCapacity(this._size + 1);
    this._data[this._size++] = value;
    return this; // chainable
  }

  pop() {
    if (this._size === 0) throw new RangeError("pop from empty array");
    const value = this._data[--this._size];
    this._data[this._size] = undefined; // help GC
    // shrink if too sparse
    if (this._size > 0 && this._size <= this._capacity / 4 && this._capacity > 4) {
      this._resize(Math.floor(this._capacity / 2));
    }
    return value;
  }

  get(index) {
    this._checkIndex(index);
    return this._data[index];
  }

  set(index, value) {
    this._checkIndex(index);
    this._data[index] = value;
    return this;
  }

  insert(index, value) {
    if (index < 0 || index > this._size) throw new RangeError("index out of range");
    this._ensureCapacity(this._size + 1);
    // shift right
    for (let i = this._size; i > index; i--) this._data[i] = this._data[i - 1];
    this._data[index] = value;
    this._size++;
    return this;
  }

  remove(index) {
    this._checkIndex(index);
    const value = this._data[index];
    for (let i = index; i < this._size - 1; i++) this._data[i] = this._data[i + 1];
    this._data[--this._size] = undefined;
    if (this._size > 0 && this._size <= this._capacity / 4 && this._capacity > 4) {
      this._resize(Math.floor(this._capacity / 2));
    }
    return value;
  }

  indexOf(value) {
    for (let i = 0; i < this._size; i++) if (this._data[i] === value) return i;
    return -1;
  }

  contains(value) { return this.indexOf(value) !== -1; }

  clear() {
    this._data = new Array(this._capacity);
    this._size = 0;
  }

  toArray() {
    const out = new Array(this._size);
    for (let i = 0; i < this._size; i++) out[i] = this._data[i];
    return out;
  }

  _checkIndex(index) {
    if (index < 0 || index >= this._size) throw new RangeError("index out of range");
  }

  [Symbol.iterator]() {
    let i = 0;
    const data = this._data;
    const size = this._size;
    return {
      next() {
        if (i < size) return { value: data[i++], done: false };
        return { done: true };
      }
    };
  }

  toString() { return `DynamicArray(${this._size}/${this._capacity}) [${this.toArray().join(", ")}]`; }
}

/* ============================================================
   3) Singly Linked List implemented from scratch
   ============================================================ */

class ListNode {
  constructor(value) {
    this.value = value;
    this.next = null;
  }
}

class LinkedList {
  constructor() {
    this.head = null;
    this.tail = null;
    this.length = 0;
  }

  // O(1)
  prepend(value) {
    const node = new ListNode(value);
    if (!this.head) {
      this.head = this.tail = node;
    } else {
      node.next = this.head;
      this.head = node;
    }
    this.length++;
    return this;
  }

  // O(1) with tail pointer
  append(value) {
    const node = new ListNode(value);
    if (!this.head) {
      this.head = this.tail = node;
    } else {
      this.tail.next = node;
      this.tail = node;
    }
    this.length++;
    return this;
  }

  // O(n) worst case
  insert(index, value) {
    if (index < 0 || index > this.length) throw new RangeError("index out of range");
    if (index === 0) return this.prepend(value);
    if (index === this.length) return this.append(value);

    const node = new ListNode(value);
    let prev = this.head;
    for (let i = 0; i < index - 1; i++) prev = prev.next;
    node.next = prev.next;
    prev.next = node;
    this.length++;
    return this;
  }

  get(index) {
    if (index < 0 || index >= this.length) return undefined;
    let cur = this.head;
    for (let i = 0; i < index; i++) cur = cur.next;
    return cur.value;
  }

  remove(index) {
    if (index < 0 || index >= this.length) throw new RangeError("index out of range");
    let removed;
    if (index === 0) {
      removed = this.head.value;
      this.head = this.head.next;
      if (this.length === 1) this.tail = null;
    } else {
      let prev = this.head;
      for (let i = 0; i < index - 1; i++) prev = prev.next;
      removed = prev.next.value;
      prev.next = prev.next.next;
      if (index === this.length - 1) this.tail = prev;
    }
    this.length--;
    return removed;
  }

  indexOf(value) {
    let cur = this.head;
    let i = 0;
    while (cur) {
      if (cur.value === value) return i;
      cur = cur.next;
      i++;
    }
    return -1;
  }

  contains(value) { return this.indexOf(value) !== -1; }

  find(predicate) {
    let cur = this.head;
    while (cur) {
      if (predicate(cur.value)) return cur.value;
      cur = cur.next;
    }
    return undefined;
  }

  toArray() {
    const out = [];
    let cur = this.head;
    while (cur) { out.push(cur.value); cur = cur.next; }
    return out;
  }

  reverse() {
    let prev = null;
    let cur = this.head;
    this.tail = this.head;
    while (cur) {
      const next = cur.next;
      cur.next = prev;
      prev = cur;
      cur = next;
    }
    this.head = prev;
    return this;
  }

  clear() {
    this.head = this.tail = null;
    this.length = 0;
  }

  [Symbol.iterator]() {
    let cur = this.head;
    return {
      next() {
        if (cur) {
          const value = cur.value;
          cur = cur.next;
          return { value, done: false };
        }
        return { done: true };
      }
    };
  }

  toString() { return `LinkedList(${this.length}) [${this.toArray().join(" -> ")}]`; }
}

/* ============================================================
   4) Demo / smoke tests
   ============================================================ */

function assert(cond, msg) {
  if (!cond) { console.error("FAIL:", msg); process.exitCode = 1; }
  else console.log("PASS:", msg);
}

function demoDynamicArray() {
  console.log("\n=== DynamicArray ===");
  const da = new DynamicArray(2);
  da.push(1).push(2).push(3).push(4).push(5);
  console.log(da.toString());
  assert(da.length === 5, "length 5");
  assert(da.capacity >= 5, "grew");
  assert(da.get(2) === 3, "get index 2");
  da.set(2, 30);
  assert(da.get(2) === 30, "set");
  da.insert(1, 15);
  console.log("after insert:", da.toArray());
  assert(da.toArray().join(",") === "1,15,2,30,4,5", "insert");
  const removed = da.remove(3);
  console.log("removed:", removed, da.toArray());
  assert(removed === 30, "remove returns value");
  // pop shrinking
  while (da.length > 0) da.pop();
  console.log("after pop all:", da.toString());
  assert(da.length === 0, "empty after pops");

  // iterator
  const da2 = new DynamicArray();
  da2.push(7).push(8).push(9);
  console.log("iter:", [...da2]);
  assert([...da2].join(",") === "7,8,9", "iterator");
}

function demoLinkedList() {
  console.log("\n=== LinkedList ===");
  const ll = new LinkedList();
  ll.append(1).append(2).append(3);
  ll.prepend(0);
  console.log(ll.toString());
  assert(ll.length === 4, "length 4");
  assert(ll.get(0) === 0 && ll.get(3) === 3, "get");
  ll.insert(2, 15);
  console.log("after insert:", ll.toArray());
  assert(ll.toArray().join(",") === "0,1,15,2,3", "insert");
  const r = ll.remove(2);
  console.log("removed:", r);
  assert(r === 15, "remove returns 15");
  console.log("indexOf 2:", ll.indexOf(2));
  assert(ll.contains(3), "contains 3");
  ll.reverse();
  console.log("reversed:", ll.toString());
  assert(ll.toArray().join(",") === "3,2,1,0", "reverse");
  console.log("iter:", [...ll]);
  assert([...ll].join(",") === "3,2,1,0", "iterator");
}

function main() {
  demoBuiltinArray();
  demoDynamicArray();
  demoLinkedList();
  console.log("\nDone.");
}

main();
```

### Key ideas

- **Built-in arrays** are dynamic arrays under the hood; `push`/`pop` are amortized O(1), but `unshift`/`splice` at the front are O(n).
- **DynamicArray** mimics that: it stores elements in a contiguous buffer, doubles capacity on overflow, and halves when too sparse. Indexing is O(1); insert/remove in the middle is O(n).
- **LinkedList** trades O(1) indexing for O(1) prepend/append (with a tail pointer) and O(1) splice once you have a node reference; random access is O(n).
- All three support iteration via `[Symbol.iterator]`, so they work with `for...of`, spread, and destructuring.

### When to use which

| Operation | Array / DynamicArray | Linked List |
|---|---|---|
| Random access by index | O(1) | O(n) |
| Push/pop at end | O(1) amortized | O(1) |
| Insert/remove at front | O(n) | O(1) |
| Insert/remove in middle (with node ref) | O(n) | O(1) |
| Memory locality / cache | Excellent | Poor |
| Extra per-element overhead | None (contiguous) | Pointer per node |

In JavaScript, prefer the built-in `Array` for almost everything; reach for a linked list only when you need many front/middle insertions or stable node references.

Here's a classic array mutation bug:

## Mistaken version

```js
const items = [1, 2, 3, 4, 5];

for (let i = 0; i < items.length; i++) {
  if (items[i] % 2 === 0) {
    items.splice(i, 1); // remove even numbers
  }
}

console.log(items);
// Expected: [1, 3, 5]
// Actual:   [1, 3, 4, 5]
```

## Corrected version (Option 1: iterate backwards)

```js
const items = [1, 2, 3, 4, 5];

for (let i = items.length - 1; i >= 0; i--) {
  if (items[i] % 2 === 0) {
    items.splice(i, 1);
  }
}

console.log(items); // [1, 3, 5]
```

## Corrected version (Option 2: non-mutating, preferred)

```js
const items = [1, 2, 3, 4, 5];
const result = items.filter(n => n % 2 !== 0);

console.log(result); // [1, 3, 5]
console.log(items);  // [1, 2, 3, 4, 5] (original untouched)
```

## What was wrong and why

1. **Index shifting after splice**  
   `splice(i, 1)` removes the element at index `i` and shifts every subsequent element one position to the left. The `for` loop then does `i++`, so the element that moved into position `i` is never examined. In the example, after removing `2` at index 1, `3` moves into index 1, but the loop advances to index 2, skipping `3` and never removing `4` properly until later conditions.

2. **Mutating while iterating forward**  
   Combining index-based iteration with in-place removal is fragile because the array's length and indices change during traversal. Backward iteration avoids this because removals only affect indices you've already processed.

3. **Better approach: avoid mutation when possible**  
   `Array.prototype.filter` creates a new array and leaves the original unchanged. This is usually clearer, less error-prone, and easier to test. If you truly need mutation (for memory/performance reasons), iterate from the end or use a `while` loop with manual index control.

### Extra pitfall to notice
`items.splice(i, 1)` also changes `items.length` during the loop, so a cached `length` or a forward condition like `i < items.length` can terminate early or late depending on how many items are removed. Always be explicit about whether you want to mutate the original or produce a new array.

## Common JavaScript array pitfalls (with code)

### 1. Many array methods mutate the original array
Methods like `push`, `pop`, `splice`, `sort`, `reverse`, `fill`, `copyWithin` mutate. People often expect a new array.

```js
const a = [3, 1, 2];
const b = a.sort();        // mutates a
console.log(a);            // [1, 2, 3]
console.log(b === a);      // true

// Safer: use non-mutating alternatives
const c = [...a].sort();   // or a.toSorted() in modern JS
```

### 2. `sort()` sorts as strings by default
```js
[10, 2, 1].sort();         // [1, 10, 2]
[10, 2, 1].sort((a, b) => a - b); // [1, 2, 10]
```

### 3. Sparse arrays / “holes”
Arrays can have missing indices. Several methods skip holes, while others preserve or convert them.

```js
const arr = [1, , 3];       // hole at index 1
console.log(arr.length);    // 3

arr.forEach(x => console.log(x)); // 1, 3 (hole skipped)
console.log(arr.map(x => x * 2)); // [2, empty, 6] (hole preserved)

// for...of yields undefined for holes
for (const x of arr) console.log(x); // 1, undefined, 3

// Array.from / spread turn holes into undefined
console.log(Array.from(arr)); // [1, undefined, 3]
console.log([...arr]);        // [1, undefined, 3]

// delete creates a hole instead of removing
const a2 = [1, 2, 3];
delete a2[1];
console.log(a2);              // [1, empty, 3]
console.log(a2.length);       // 3
```

### 4. `new Array(n)` creates a sparse array, not an array of `n`
```js
const a = new Array(3);
console.log(a);               // [empty × 3]
console.log(a.map(x => 1));   // [empty × 3] (map skips holes)

// Usually intended:
const b = Array.from({ length: 3 }, (_, i) => i); // [0, 1, 2]
const c = new Array(3).fill(0);                   // [0, 0, 0]
```

### 5. `fill()` with objects shares one reference
```js
const grid = new Array(3).fill([]);
grid[0].push(1);
console.log(grid); // [[1], [1], [1]] — same array!

// Fix: create distinct objects
const grid2 = Array.from({ length: 3 }, () => []);
```

### 6. Shallow copies share nested references
```js
const original = [[1, 2], [3, 4]];
const copy = [...original]; // or original.slice()

copy[0].push(99);
console.log(original); // [[1, 2, 99], [3, 4]] — mutated!

// Deep copy options
const deep1 = structuredClone(original);
const deep2 = JSON.parse(JSON.stringify(original)); // loses undefined/functions/Dates
```

### 7. Array methods return surprising values
```js
const a = [1, 2];
console.log(a.push(3));     // 3 (new length), not the array
console.log(a.unshift(0));  // 4 (new length)
console.log(a.splice(1, 1)); // [2] (removed elements)
console.log(a.pop());       // 3 (removed element)

// Common mistake:
const result = [1, 2, 3].map(x => x * 2);
console.log(result); // [2, 4, 6] — map returns new array; original unchanged
```

### 8. `reduce()` on an empty array throws without initial value
```js
[].reduce((a, b) => a + b); // TypeError: Reduce of empty array with no initial value

[].reduce((a, b) => a + b, 0); // 0
```

### 9. `every()` on empty is `true`, `some()` on empty is `false`
```js
[].every(x => x > 0); // true
[].some(x => x > 0);  // false
```

### 10. Searching: `indexOf` cannot find `NaN`; `includes` can
```js
[NaN].indexOf(NaN);   // -1
[NaN].includes(NaN);  // true

// Object identity matters
const obj = { x: 1 };
[{ x: 1 }].indexOf(obj); // -1
```

### 11. `delete` does not remove array elements properly
```js
const a = [1, 2, 3];
delete a[1];
console.log(a);        // [1, empty, 3]
console.log(a.length); // 3

// Use splice or filter
a.splice(1, 1);        // mutates
// or
const b = a.filter((_, i) => i !== 1); // new array
```

### 12. Type coercion and comparison traps
```js
[] == false;           // true
[1] == "1";            // true
[] + [];               // ""
[1, 2] + [3, 4];       // "1,23,4"

console.log(typeof []); // "object"
console.log(Array.isArray([])); // true

// Cross-frame / iframe arrays
// iframeArray instanceof Array may be false; use Array.isArray
```

### 13. `toString()` flattens nested arrays in string form
```js
[[1, 2], [3]].toString(); // "1,2,3"
`${[[1, 2], [3]]}`;       // "1,2,3"
```

### 14. JSON serialization drops/converts values
```js
JSON.stringify([1, undefined, 3, () => {}, new Date()]);
// "[1,null,3,null,\"2024-...\"]" (undefined/function -> null; holes -> null)

JSON.stringify([1, , 3]); // "[1,null,3]"
```

### 15. Modifying an array while iterating
```js
const a = [1, 2, 3];

// forEach fixes length at call time; appended items may be skipped
a.forEach((x, i) => {
  if (i === 0) a.push(4);
});
console.log(a); // [1, 2, 3, 4] (4 may or may not be visited depending)

// Safer: iterate over a copy or use index loop with care
for (let i = 0; i < a.length; i++) {
  // length changes are visible
}
```

### 16. Async functions inside `forEach` are not awaited
```js
const urls = ["/a", "/b"];

// Does NOT wait
urls.forEach(async (url) => {
  await fetch(url);
});
console.log("done"); // runs before fetches finish

// Correct options
for (const url of urls) {
  await fetch(url);
}

// Or parallel:
await Promise.all(urls.map(url => fetch(url)));
```

### 17. `map(async fn)` returns an array of promises
```js
const results = [1, 2, 3].map(async x => x * 2);
console.log(results); // [Promise, Promise, Promise]

const resolved = await Promise.all(results);
```

### 18. Array-like objects are not arrays
```js
function f() {
  console.log(arguments.map); // undefined
}
f(1, 2, 3);

// Convert
function g() {
  const arr = Array.from(arguments);
  // or [...arguments]
  // or Array.prototype.slice.call(arguments)
}
```

NodeList, HTMLCollection, and `arguments` need conversion before using array methods.

### 19. `for...in` on arrays is usually wrong
```js
const a = [10, 20, 30];
a.custom = "x";

for (const key in a) {
  console.log(key); // "0", "1", "2", "custom"
}

// Use for...of, forEach, or indexed loop
for (const value of a) console.log(value);
```

### 20. Array constructor ambiguity
```js
new Array(5);     // sparse array length 5
new Array(5, 6);  // [5, 6]
Array.of(5);      // [5] (safer)
```

### 21. `Array.prototype.concat` flattens only one level
```js
[1].concat([2, [3]]); // [1, 2, [3]]
[1, [2, [3]]].flat(); // [1, 2, [3]] (default depth 1)
[1, [2, [3]]].flat(2); // [1, 2, 3]
```

### 22. `unshift`/`shift` are O(n)
```js
const queue = [];
queue.unshift(1); // O(n) because all indices shift
// For large queues, use a linked list / deque library
```

### 23. `push.apply` can overflow the call stack
```js
const big = new Array(200000).fill(1);
const target = [];
target.push(...big); // may throw RangeError: Maximum call stack size exceeded

// Safer for huge arrays:
for (const x of big) target.push(x);
// or target.push.apply(target, big) has same stack issue
```

### 24. Destructuring defaults only apply to `undefined`, not `null`
```js
const [a = 1] = [undefined]; // a = 1
const [b = 1] = [null];      // b = null
```

### 25. Negative indices are not special (except newer `.at()`)
```js
const a = [10, 20, 30];
a[-1] = 99;          // sets property "-1", not last element
console.log(a);      // [10, 20, 30, "-1": 99]

console.log(a.at(-1)); // 30 (modern)
```

### 26. `Array.prototype.includes` uses SameValueZero
```js
[0].includes(-0); // true
[NaN].includes(NaN); // true
```

### 27. `copyWithin` mutates and can create surprising overlaps
```js
[1, 2, 3, 4, 5].copyWithin(0, 3); // [4, 5, 3, 4, 5]
```

### 28. Iteration method callbacks receive `(value, index, array)`
```js
[10, 20, 30].forEach((value, index, arr) => {
  console.log(value, index);
});

// Mistake: using index as value
[10, 20, 30].map((i) => i * 2); // [20, 40, 60] (works by accident here)
// Better be explicit:
[10, 20, 30].map((value, index) => value * 2);
```

### 29. `Array.prototype.reverse()` mutates; use `toReversed()` when available
```js
const a = [1, 2, 3];
const b = a.reverse();
console.log(a); // [3, 2, 1]
console.log(b === a); // true

// Modern non-mutating:
const c = [1, 2, 3].toReversed(); // [3, 2, 1]
```

### 30. Using arrays as dictionaries / objects
```js
const a = [];
a["foo"] = "bar";
console.log(a.length); // 0
console.log(a.foo);    // "bar"
// Arrays are objects, but non-numeric keys don't affect length.
// Use Map or plain object for dictionaries.
```

### Quick checklist
- Treat most array methods as either **mutating** or **returning new arrays**—check docs.
- Prefer `Array.isArray`, not `instanceof Array`.
- Convert array-like objects before array methods.
- Avoid sparse arrays unless intentional; use `Array.from({ length: n }, ...)`.
- Deep-copy nested arrays with `structuredClone` when needed.
- Use initial values with `reduce`.
- Use `includes` for `NaN`, `indexOf` for strict reference checks.
- Don’t mutate while iterating unless you fully understand length capture rules.
- Don’t use `forEach` for async work; use `for...of` or `Promise.all(map(...))`.

## Interview answer: Lists and arrays in JavaScript

### 1) What “arrays” mean in JavaScript

A JavaScript `Array` is a **dynamic, ordered, zero-indexed collection**.

Key properties:
- **Dynamic length**: grows/shrinks automatically (`push`, `pop`, `splice`).
- **Heterogeneous**: can store mixed types (`[1, "a", {x:2}]`).
- **Index-based access**: `arr[i]` is O(1) in practice (engines optimize contiguous storage).
- **Sparse arrays possible**: `arr[1000] = 1` creates holes; engines may switch to dictionary-like storage.
- **Built-in methods**: `map`, `filter`, `reduce`, `slice`, `splice`, etc.

Typical complexity (amortized/practical):
| Operation | Array |
|---|---|
| Access by index | O(1) |
| Push/pop end | O(1) amortized |
| Insert/remove middle | O(n) |
| Search (linear) | O(n) |

### 2) What “lists” mean (linked lists)

JavaScript has no built-in linked list, but we implement it with nodes:

- **Singly linked list**: each node has `value` + `next`.
- **Doubly linked list**: node has `value` + `next` + `prev`.

Complexity:
| Operation | Singly linked |
|---|---|
| Access by index | O(n) |
| Prepend | O(1) |
| Append (with tail pointer) | O(1) |
| Insert/delete after known node | O(1) |
| Search | O(n) |

### 3) When to use which

- Use **Array** for random access, iteration, and most everyday work.
- Use **linked list** when you need frequent insertions/deletions at known positions and want O(1) splice without shifting elements (e.g., LRU cache nodes, undo history).

---

## Core implementations

Below are two clean, commented implementations: a **dynamic array** (resizable array) and a **singly linked list**. I also include a small test harness at the bottom.

```js
/* ============================================================
   1) Dynamic Array (resizable array)
   ============================================================ */
class DynamicArray {
  constructor(initialCapacity = 4) {
    if (initialCapacity < 1) throw new Error("capacity must be >= 1");
    this.capacity = initialCapacity;
    this.size = 0;
    this.data = new Array(this.capacity); // underlying storage
  }

  // O(1) amortized
  push(value) {
    if (this.size === this.capacity) this._resize(this.capacity * 2);
    this.data[this.size++] = value;
  }

  // O(1)
  pop() {
    if (this.size === 0) return undefined;
    const value = this.data[--this.size];
    this.data[this.size] = undefined; // help GC
    // Optional shrink to save memory
    if (this.size > 0 && this.size === Math.floor(this.capacity / 4)) {
      this._resize(Math.max(4, Math.floor(this.capacity / 2)));
    }
    return value;
  }

  // O(1)
  get(index) {
    this._checkIndex(index);
    return this.data[index];
  }

  // O(1)
  set(index, value) {
    this._checkIndex(index);
    this.data[index] = value;
  }

  // O(n) in worst case
  insert(index, value) {
    if (index < 0 || index > this.size) throw new RangeError("index out of range");
    if (this.size === this.capacity) this._resize(this.capacity * 2);

    // shift elements to the right
    for (let i = this.size; i > index; i--) {
      this.data[i] = this.data[i - 1];
    }
    this.data[index] = value;
    this.size++;
  }

  // O(n) in worst case
  remove(index) {
    this._checkIndex(index);
    const removed = this.data[index];

    for (let i = index; i < this.size - 1; i++) {
      this.data[i] = this.data[i + 1];
    }
    this.data[--this.size] = undefined;
    return removed;
  }

  // O(n)
  indexOf(value) {
    for (let i = 0; i < this.size; i++) {
      if (this.data[i] === value) return i;
    }
    return -1;
  }

  // O(n)
  toString() {
    const out = [];
    for (let i = 0; i < this.size; i++) out.push(this.data[i]);
    return `[${out.join(", ")}]`;
  }

  _resize(newCapacity) {
    const next = new Array(newCapacity);
    for (let i = 0; i < this.size; i++) next[i] = this.data[i];
    this.data = next;
    this.capacity = newCapacity;
  }

  _checkIndex(index) {
    if (index < 0 || index >= this.size) throw new RangeError("index out of range");
  }
}

/* ============================================================
   2) Singly Linked List
   ============================================================ */
class Node {
  constructor(value) {
    this.value = value;
    this.next = null;
  }
}

class SinglyLinkedList {
  constructor() {
    this.head = null;
    this.tail = null;
    this.length = 0;
  }

  // O(1)
  prepend(value) {
    const node = new Node(value);
    if (!this.head) {
      this.head = this.tail = node;
    } else {
      node.next = this.head;
      this.head = node;
    }
    this.length++;
  }

  // O(1) with tail pointer
  append(value) {
    const node = new Node(value);
    if (!this.tail) {
      this.head = this.tail = node;
    } else {
      this.tail.next = node;
      this.tail = node;
    }
    this.length++;
  }

  // O(n) (index-based)
  insertAt(index, value) {
    if (index < 0 || index > this.length) throw new RangeError("index out of range");
    if (index === 0) return this.prepend(value);
    if (index === this.length) return this.append(value);

    const prev = this._nodeAt(index - 1);
    const node = new Node(value);
    node.next = prev.next;
    prev.next = node;
    this.length++;
  }

  // O(n) (index-based)
  removeAt(index) {
    if (index < 0 || index >= this.length) throw new RangeError("index out of range");
    if (index === 0) {
      const removed = this.head.value;
      this.head = this.head.next;
      if (!this.head) this.tail = null;
      this.length--;
      return removed;
    }

    const prev = this._nodeAt(index - 1);
    const removedNode = prev.next;
    prev.next = removedNode.next;
    if (index === this.length - 1) this.tail = prev;
    this.length--;
    return removedNode.value;
  }

  // O(n)
  get(index) {
    return this._nodeAt(index).value;
  }

  // O(n)
  toArray() {
    const out = [];
    let cur = this.head;
    while (cur) {
      out.push(cur.value);
      cur = cur.next;
    }
    return out;
  }

  // O(n)
  toString() {
    return `[${this.toArray().join(" -> ")}]`;
  }

  _nodeAt(index) {
    if (index < 0 || index >= this.length) throw new RangeError("index out of range");
    let cur = this.head;
    for (let i = 0; i < index; i++) cur = cur.next;
    return cur;
  }
}

/* ============================================================
   3) Quick sanity tests (run with node)
   ============================================================ */
(function test() {
  const arr = new DynamicArray(2);
  arr.push(10); arr.push(20); arr.push(30); // triggers resize
  console.log("Array:", arr.toString());        // [10, 20, 30]
  console.log("get(1):", arr.get(1));           // 20
  arr.insert(1, 15);
  console.log("after insert:", arr.toString()); // [10, 15, 20, 30]
  console.log("pop:", arr.pop());              // 30
  console.log("Array:", arr.toString());        // [10, 15, 20]

  const list = new SinglyLinkedList();
  list.append(1); list.append(2); list.prepend(0);
  console.log("List:", list.toString());        // [0 -> 1 -> 2]
  list.insertAt(2, 1.5);
  console.log("List:", list.toString());        // [0 -> 1 -> 1.5 -> 2]
  console.log("removeAt(1):", list.removeAt(1)); // 1
  console.log("List:", list.toString());        // [0 -> 1.5 -> 2]
  console.log("get(2):", list.get(2));         // 2
})();
```

### Notes for interview discussion

- **Array resize strategy**: doubling on growth and halving when quarter-full keeps amortized O(1) push/pop.
- **Linked list tail pointer**: makes `append` O(1); without it, append is O(n).
- **Doubly linked list** adds `prev` and makes backward traversal/deletion-before-node O(1), at the cost of extra memory and pointer updates.
- **Real-world use**: JS engines implement arrays as dynamic arrays with optimizations; linked lists are usually implemented manually for specialized needs (LRU cache, graph adjacency with frequent edge removals).

Below are important edge cases when working with JavaScript arrays (and array-like “lists”), with runnable examples.

## 1. Sparse arrays and holes

A hole is an index that does not exist as an own property. Many methods treat holes differently from `undefined`.

```js
const a = [1, , 3]; // hole at index 1
console.log(a.length);        // 3
console.log(1 in a);           // false
console.log(a[1]);             // undefined
console.log(Object.keys(a));   // ['0', '2']

a.forEach((x, i) => console.log(i, x)); // skips index 1
console.log(a.map(x => x * 2));          // [2, <1 empty item>, 6]
```

Densify holes when needed:

```js
const dense = Array.from(a);      // [1, undefined, 3]
const dense2 = [...a];            // [1, undefined, 3]
console.log(JSON.stringify(a));   // "[1,null,3]"
```

## 2. `delete` creates holes; it does not shrink `length`

```js
const a = [10, 20, 30];
delete a[1];
console.log(a);        // [10, <1 empty item>, 30]
console.log(a.length); // 3
console.log(a[1]);     // undefined
```

## 3. `length` is mutable and can truncate data

```js
const a = [1, 2, 3, 4];
a.length = 2;
console.log(a); // [1, 2]

a.length = 5;   // creates holes
console.log(a); // [1, 2, <3 empty items>]
```

Invalid lengths throw:

```js
const a = [];
try {
  a.length = -1;
} catch (e) {
  console.log(e.name); // RangeError
}
try {
  a.length = 2 ** 32;
} catch (e) {
  console.log(e.name); // RangeError
}
```

## 4. `new Array(n)` is not `[n]`

```js
console.log(new Array(3));      // [<3 empty items>]
console.log(Array.of(3));       // [3]
console.log(Array(1, 2, 3));    // [1, 2, 3]
```

## 5. Index boundaries and non-canonical keys

Valid array indices are integers from `0` to `2^32 - 2`. Other property names do not update `length`.

```js
const a = [];
a[4294967294] = 'max valid index'; // length becomes 4294967295
console.log(a.length);               // 4294967295

a[4294967295] = 'not an array index'; // normal property
console.log(a.length);               // 4294967295
console.log(a['4294967295']);       // 'not an array index'

a[-1] = 'negative'; // normal property
a['01'] = 'leading zero'; // not canonical index
console.log(a.length); // still 4294967295
```

## 6. Mutating while iterating

Forward iteration plus mutation can skip elements or process the wrong item.

```js
const a = [1, 2, 3, 4];
a.forEach((x, i) => {
  if (x % 2 === 0) a.splice(i, 1);
});
console.log(a); // [1, 3, 4] — bug: 4 was skipped
```

Safer patterns:

```js
const a = [1, 2, 3, 4];
for (let i = a.length - 1; i >= 0; i--) {
  if (a[i] % 2 === 0) a.splice(i, 1);
}
console.log(a); // [1, 3]

// Or build a new array:
const b = [1, 2, 3, 4].filter(x => x % 2 !== 0);
console.log(b); // [1, 3]
```

## 7. Sorting defaults to string comparison

```js
const nums = [10, 2, 1];
console.log(nums.sort()); // [1, 10, 2]

nums.sort((a, b) => a - b);
console.log(nums); // [1, 2, 10]
```

Comparator edge cases:

```js
const data = [3, 1, 2];
data.sort((a, b) => a > b ? 1 : -1); // missing 0 can be inconsistent
// Prefer explicit three-way comparison:
data.sort((a, b) => (a < b) - (a > b));
```

`NaN` in comparators can make sorting implementation-defined/unstable in practice; sanitize values first.

## 8. Search and equality inconsistencies

```js
const a = [NaN];
console.log(a.indexOf(NaN));   // -1
console.log(a.includes(NaN)); // true

const b = [1, 2, 3];
console.log(b.indexOf('2'));   // -1 (strict equality)
```

`find` and `findIndex` skip holes:

```js
const a = [1, , 3];
console.log(a.find(x => x === undefined)); // undefined, because hole skipped
console.log(a.findIndex(x => true));       // 0
```

## 9. Empty-array method edge cases

```js
console.log([].every(x => false)); // true (vacuous)
console.log([].some(x => true));   // false

try {
  [].reduce((a, b) => a + b);
} catch (e) {
  console.log(e.name); // TypeError: no initial value
}

// Holes-only array still has no callable elements:
try {
  [,,,].reduce((a, b) => a + b);
} catch (e) {
  console.log(e.name); // TypeError
}
```

## 10. Shallow copies share nested references

```js
const original = [{ n: 1 }, [2, 3]];
const copy = original.slice(); // or [...original]
copy[0].n = 99;
copy[1].push(4);

console.log(original); // [{ n: 99 }, [2, 3, 4]]
```

Deep-copy only when needed:

```js
const deep = structuredClone(original);
```

## 11. Array-like objects are not arrays

```js
function f() {
  console.log(Array.isArray(arguments)); // false
  const arr = Array.from(arguments);
  console.log(arr.map(x => x * 2));
}
f(1, 2, 3);
```

`NodeList`, `HTMLCollection`, `arguments`, and objects with `length` are array-like. Use `Array.from` or spread where iterable.

```js
const arrayLike = { 0: 'a', 1: 'b', length: 2 };
console.log(Array.from(arrayLike)); // ['a', 'b']

// Array.prototype methods can be borrowed:
console.log(Array.prototype.join.call(arrayLike, '-')); // 'a-b'
```

`Array.from` densifies holes in array-like inputs:

```js
const sparse = [1, , 3];
console.log(Array.from(sparse)); // [1, undefined, 3]
```

## 12. `concat` flattening is shallow and one level

```js
const a = [1, [2, [3]]];
console.log(a.concat([4, [5]])); // [1, [2, [3]], 4, [5]]
```

`concat` does not flatten arbitrary iterables beyond one level; sparse holes are preserved in the result.

## 13. `splice` argument edge cases

```js
const a = [1, 2, 3, 4];
console.log(a.splice(1));        // [2, 3, 4]; a is [1]
const b = [1, 2, 3, 4];
console.log(b.splice(1, 2, 9));  // [2, 3]; b is [1, 9, 4]
const c = [1, 2, 3];
console.log(c.splice(-1, 1));    // [3]; c is [1, 2]
```

Omitting `deleteCount` deletes to the end.

## 14. `slice`, negative indices, and holes

```js
const a = [1, 2, 3, 4];
console.log(a.slice(-2));   // [3, 4]
console.log(a.slice(1, -1)); // [2, 3]

const sparse = [1, , 3];
console.log(sparse.slice(0, 2)); // [1, <1 empty item>]
```

## 15. `at()` for negative indexing

```js
const a = [10, 20, 30];
console.log(a.at(-1)); // 30
console.log(a.at(-10)); // undefined
```

## 16. Iteration and `for...in`

`for...in` enumerates string keys, including inherited enumerable properties. Avoid it for arrays.

```js
Array.prototype.custom = 'x';
const a = [1, 2];
for (const key in a) console.log(key); // '0', '1', 'custom'
delete Array.prototype.custom;

for (const value of a) console.log(value); // 1, 2
```

`for...of` turns holes into `undefined`:

```js
for (const x of [1, , 3]) console.log(x); // 1, undefined, 3
```

## 17. `copyWithin` overlapping ranges

```js
const a = [1, 2, 3, 4, 5];
a.copyWithin(0, 3);
console.log(a); // [4, 5, 3, 4, 5]

const b = [1, 2, 3, 4, 5];
b.copyWithin(1, 0, 2); // overlap handled correctly
console.log(b); // [1, 1, 2, 4, 5]
```

## 18. `fill` with holes and objects

```js
const a = new Array(3).fill(0);
console.log(a); // [0, 0, 0]

// Filling with an object reuses the same reference:
const objs = new Array(2).fill({ n: 1 });
objs[0].n = 2;
console.log(objs); // [{ n: 2 }, { n: 2 }]
```

## 19. Typed arrays have fixed length and coercion

```js
const t = new Uint8Array([1, 2, 3]);
t[0] = 300;          // wraps modulo 256
console.log(t[0]);   // 44
try {
  t.push(4);
} catch (e) {
  console.log(e.name); // TypeError: fixed length
}
console.log(t.length); // 3

// Views share memory:
const view = t.subarray(1, 3);
view[0] = 99;
console.log(t); // Uint8Array [44, 99, 3]
```

Use `slice()` for an independent typed array, `subarray()` for a view.

## 20. Cross-realm `instanceof` issues

```js
const a = [];
console.log(Array.isArray(a));              // true
console.log(a instanceof Array);            // true in same realm

// In iframes/workers, prefer:
console.log(Array.isArray(a));              // robust
```

## 21. JSON serialization differences

```js
const a = [1, undefined, () => {}, 4];
console.log(JSON.stringify(a)); // "[1,null,null,4]"

const sparse = [1, , 3];
console.log(JSON.stringify(sparse)); // "[1,null,3]"
```

`undefined`, functions, and symbols become `null` in arrays, but are omitted in objects.

## 22. Modern non-mutating alternatives

ES2023 adds methods that avoid accidental mutation:

```js
const a = [3, 1, 2];
console.log(a.toSorted());   // [1, 2, 3]
console.log(a);              // [3, 1, 2] unchanged

const b = [1, 2, 3];
console.log(b.toSpliced(1, 1, 9)); // [1, 9, 3]
console.log(b);                    // [1, 2, 3]
```

## 23. Practical checklist

- Treat arrays as potentially sparse; densify with `Array.from` or spread before algorithms that assume dense data.
- Never mutate an array while iterating forward over it.
- Always pass a comparator to `sort()` for non-string data.
- Use `includes` when `NaN` matters.
- Remember `reduce` needs an initial value for possibly-empty arrays.
- Prefer `Array.isArray` over `instanceof Array`.
- Avoid `for...in` on arrays.
- Copy nested structures deeply when independence is required.
- Use typed arrays for fixed-size numeric/binary data.
- Check method return values: `splice`, `push`, `pop`, etc. have different return semantics.

Here is a complete, runnable JavaScript logging implementation. It supports log levels, child loggers, redaction, multiple transports (console, file, in-memory), and structured output. Save it as `logger.js` and run it with `node logger.js`.

```js
'use strict';

const fs = require('fs');

const LEVELS = Object.freeze({
  TRACE: 10,
  DEBUG: 20,
  INFO: 30,
  WARN: 40,
  ERROR: 50,
  FATAL: 60,
  SILENT: 100,
});

function parseLevel(value) {
  if (value == null) return null;
  if (typeof value === 'number') return value;
  const found = LEVELS[String(value).toUpperCase()];
  return found == null ? null : found;
}

function levelName(level) {
  for (const [name, value] of Object.entries(LEVELS)) {
    if (value === level) return name;
  }
  return 'UNKNOWN';
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function serialize(value, seen = new WeakSet()) {
  if (value === null || typeof value !== 'object') return value;

  if (value instanceof Error) {
    return {
      name: value.name,
      message: value.message,
      stack: value.stack,
    };
  }

  if (value instanceof Date) return value.toISOString();
  if (value instanceof RegExp) return value.toString();

  if (Array.isArray(value)) {
    return value.map((item) => serialize(item, seen));
  }

  if (seen.has(value)) return '[Circular]';
  seen.add(value);

  const output = {};
  for (const [key, item] of Object.entries(value)) {
    output[key] = serialize(item, seen);
  }
  return output;
}

const DEFAULT_SENSITIVE = /password|passwd|token|secret|authorization|cookie|api[-_]?key/i;

function redactValue(value, sensitive = DEFAULT_SENSITIVE, seen = new WeakSet()) {
  if (value === null || typeof value !== 'object') return value;
  if (value instanceof Error || value instanceof Date || value instanceof RegExp) return value;
  if (seen.has(value)) return value;

  seen.add(value);

  if (Array.isArray(value)) {
    return value.map((item) => redactValue(item, sensitive, seen));
  }

  const output = {};
  for (const [key, item] of Object.entries(value)) {
    if (sensitive.test(key)) {
      output[key] = '[REDACTED]';
    } else {
      output[key] = redactValue(item, sensitive, seen);
    }
  }
  return output;
}

class Transport {
  write(entry) {
    throw new Error('Transport.write must be implemented');
  }
}

class ConsoleTransport extends Transport {
  constructor(options = {}) {
    super();
    this.colors = options.colors !== false;
    this.stderrForWarnAndError = options.stderrForWarnAndError !== false;
  }

  write(entry) {
    const method =
      entry.level >= LEVELS.ERROR
        ? 'error'
        : entry.level >= LEVELS.WARN
        ? 'warn'
        : entry.level >= LEVELS.INFO
        ? 'info'
        : entry.level >= LEVELS.DEBUG
        ? 'debug'
        : 'trace';

    const colorCode = {
      TRACE: '90',
      DEBUG: '36',
      INFO: '32',
      WARN: '33',
      ERROR: '31',
      FATAL: '35',
    }[entry.levelName] || '0';

    const prefix = `${entry.timestamp} ${entry.levelName.padEnd(5)} [${entry.name}]`;
    const coloredPrefix = this.colors ? `\x1b[${colorCode}m${prefix}\x1b[0m` : prefix;

    const args = [];
    if (entry.context && Object.keys(entry.context).length > 0) {
      args.push(entry.context);
    }
    if (entry.args.length > 0) {
      args.push(...entry.args);
    }

    if (typeof console[method] === 'function') {
      console[method](coloredPrefix, entry.message, ...args);
    } else {
      console.log(coloredPrefix, entry.message, ...args);
    }
  }
}

class FileTransport extends Transport {
  constructor(filePath, options = {}) {
    super();
    this.filePath = filePath;
    this.encoding = options.encoding || 'utf8';

    if (options.truncate) {
      fs.writeFileSync(this.filePath, '', this.encoding);
    }
  }

  write(entry) {
    const line = JSON.stringify(serialize(entry)) + '\n';
    fs.appendFileSync(this.filePath, line, this.encoding);
  }
}

class MemoryTransport extends Transport {
  constructor() {
    super();
    this.entries = [];
  }

  write(entry) {
    this.entries.push(entry);
  }

  clear() {
    this.entries.length = 0;
  }
}

class Logger {
  constructor(options = {}) {
    const envLevel =
      typeof process !== 'undefined' && process.env
        ? process.env.LOG_LEVEL
        : undefined;

    this.name = options.name || 'app';
    this.level =
      options.level != null
        ? parseLevel(options.level)
        : parseLevel(envLevel);

    if (this.level == null) this.level = LEVELS.INFO;

    this.transports =
      options.transports && options.transports.length > 0
        ? options.transports
        : [new ConsoleTransport()];

    this.context = options.context || {};
    this.sensitive = options.sensitive || DEFAULT_SENSITIVE;
  }

  isLevelEnabled(level) {
    return level >= this.level;
  }

  _log(level, message, args) {
    if (!this.isLevelEnabled(level)) return;

    let finalMessage = message;
    const finalArgs = Array.isArray(args) ? [...args] : [];

    if (message instanceof Error) {
      finalMessage = message.message;
      finalArgs.unshift(message);
    }

    const entry = {
      timestamp: new Date().toISOString(),
      level,
      levelName: levelName(level),
      name: this.name,
      message: String(finalMessage),
      args: finalArgs.map((arg) =>
        redactValue(
          isPlainObject(arg) ? { ...arg } : arg,
          this.sensitive
        )
      ),
      context: redactValue({ ...this.context }, this.sensitive),
    };

    for (const transport of this.transports) {
      try {
        transport.write(entry);
      } catch (transportError) {
        console.error('Logger transport failed:', transportError);
      }
    }
  }

  trace(message, ...args) {
    this._log(LEVELS.TRACE, message, args);
  }

  debug(message, ...args) {
    this._log(LEVELS.DEBUG, message, args);
  }

  info(message, ...args) {
    this._log(LEVELS.INFO, message, args);
  }

  warn(message, ...args) {
    this._log(LEVELS.WARN, message, args);
  }

  error(message, ...args) {
    this._log(LEVELS.ERROR, message, args);
  }

  fatal(message, ...args) {
    this._log(LEVELS.FATAL, message, args);
  }

  child(options = {}) {
    return new Logger({
      name: options.name ? `${this.name}:${options.name}` : this.name,
      level: options.level != null ? options.level : this.level,
      transports: options.transports || this.transports,
      context: { ...this.context, ...(options.context || {}) },
      sensitive: options.sensitive || this.sensitive,
    });
  }
}

module.exports = {
  LEVELS,
  Logger,
  ConsoleTransport,
  FileTransport,
  MemoryTransport,
  parseLevel,
  serialize,
};

// ---------------------------------------------------------------------------
// Complete runnable example
// ---------------------------------------------------------------------------
if (require.main === module) {
  const logger = new Logger({
    name: 'demo',
    level: process.env.LOG_LEVEL || 'DEBUG',
  });

  logger.info('Application started', { port: 3000, user: 'alice' });
  logger.debug('Debugging details', { requestId: 'abc-123' });

  const dbLogger = logger.child({
    name: 'db',
    context: { component: 'database' },
  });

  // Sensitive fields are redacted automatically.
  dbLogger.debug('Connecting to database', {
    host: 'localhost',
    password: 'super-secret-password',
    apiKey: '1234567890',
  });

  try {
    throw new Error('Something went wrong');
  } catch (error) {
    logger.error('Request failed', error, { requestId: 42 });
  }

  // In-memory transport is useful for tests and assertions.
  const memory = new MemoryTransport();
  const testLogger = new Logger({
    name: 'test',
    transports: [memory],
    level: 'TRACE',
  });

  testLogger.trace('trace message');
  testLogger.info('info message', { ok: true });

  console.log('\nCaptured log entries:', memory.entries.length);
  console.log(JSON.stringify(memory.entries[0], null, 2));

  // File transport writes structured JSON Lines.
  const fileTransport = new FileTransport('./app.log', { truncate: true });
  const fileLogger = new Logger({
    name: 'file-demo',
    transports: [fileTransport],
  });

  fileLogger.warn('This message was written to app.log');
  fileLogger.error('Error with stack', new Error('file error'));

  console.log('\nCreated ./app.log');
}
```

Run it:

```bash
node logger.js
```

Optional:

```bash
LOG_LEVEL=TRACE node logger.js
```

### What this implementation includes

- **Levels**: `TRACE`, `DEBUG`, `INFO`, `WARN`, `ERROR`, `FATAL`, `SILENT`
- **Environment support**: reads `LOG_LEVEL`
- **Child loggers**: inherit transports, level, context, and redaction rules
- **Redaction**: automatically masks keys such as `password`, `token`, `secret`, `apiKey`
- **Transports**:
  - `ConsoleTransport`: colored, level-aware console output
  - `FileTransport`: structured JSON Lines file output
  - `MemoryTransport`: useful for tests and assertions
- **Error handling**: logs `Error` objects with stack traces
- **Safety**: transport failures do not crash the application
- **Structured data**: context and metadata are preserved for file/memory transports

For very high-throughput production systems, you may later replace this with specialized libraries such as `pino` or `winston`, but this implementation is fully usable and demonstrates the core concepts clearly.

# Logging in JavaScript

Logging is the practice of recording events, state, and diagnostics from a running program so you can understand what happened—especially when something goes wrong. In JavaScript the built-in entry point is the global **`console`** object, but production apps usually layer on structured loggers.

---

## 1. The idea

- **Observability**: logs are one of three pillars (with metrics and traces) for understanding system behavior.
- **Levels**: not every message is equal. Typical severity: `trace < debug < info < warn < error < fatal`.
- **Context**: a good log line includes *when*, *where*, *who*, and *what* (request id, user id, stack trace).
- **Structure**: machine-readable (JSON) logs beat free-form strings in production; human-readable formatting is for dev.
- **Cost**: logging has overhead (I/O, serialization). Don't log in hot loops; sample or guard.

---

## 2. Syntax: the `console` API

Available in browsers and Node.js (with minor differences).

```js
console.log("hello", { a: 1 });          // general info
console.info("user signed in");          // informational
console.warn("deprecated API used");     // warning
console.error("request failed", err);    // error
console.debug("cache hit", key);         // debug (often hidden by default)

console.trace("where am I?");            // prints stack trace
console.assert(x > 0, "x must be positive"); // logs only if condition false

console.table([{ id: 1, name: "a" }, { id: 2, name: "b" }]);
console.dir(obj, { depth: 3, colors: true });

console.group("request");
console.log("url", url);
console.log("status", status);
console.groupEnd();

console.time("fetch");
await fetch(url);
console.timeEnd("fetch");                // "fetch: 123.456ms"

console.count("click");                  // click: 1, click: 2, ...
console.clear();
```

### Formatting

```js
console.log("user %s id=%d", "alice", 42);
console.log("data: %o", { nested: { x: 1 } });
console.log("styled %cRED", "color: red; font-weight: bold");
```

### Node-specific

```js
// process.stderr / stdout directly
process.stderr.write("fatal\n");

// util.inspect for pretty objects
const { inspect } = require("node:util");
console.log(inspect(obj, { depth: null, colors: true }));
```

---

## 3. Typical use cases

| Use case | Example |
|---|---|
| Debugging | `console.debug("parsed payload", payload)` |
| Request logging | log method, path, status, duration per HTTP request |
| Error reporting | catch + `console.error(err)` with stack |
| Audit trail | "user 7 deleted resource 42" |
| Performance | `console.time` around DB query |
| Feature flags | log which branch executed |
| Lifecycle | app start/stop, config loaded |

---

## 4. From `console` to production logging

`console` is fine for dev but lacks levels, filtering, transports, and structure. Production code usually uses a logger.

### Minimal custom logger

```js
const LEVELS = { trace: 0, debug: 1, info: 2, warn: 3, error: 4, fatal: 5 };
const minLevel = LEVELS[process.env.LOG_LEVEL || "info"];

function log(level, msg, ctx = {}) {
  if (LEVELS[level] < minLevel) return;
  const entry = {
    ts: new Date().toISOString(),
    level,
    msg,
    ...ctx,
  };
  const line = JSON.stringify(entry);
  if (LEVELS[level] >= LEVELS.warn) process.stderr.write(line + "\n");
  else process.stdout.write(line + "\n");
}

log.info("server started", { port: 3000 });
log.error("db failed", { err: err.message, stack: err.stack });
```

### Popular libraries

**pino** (fast, JSON-first):
```js
import pino from "pino";
const log = pino({ level: process.env.LOG_LEVEL || "info" });
log.info({ userId: 7, action: "login" }, "user signed in");
const child = log.child({ requestId: "abc" });
child.warn("slow query");
```

**winston** (flexible transports):
```js
import winston from "winston";
const log = winston.createLogger({
  level: "info",
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: "app.log" }),
  ],
});
log.error("boom", { stack: err.stack });
```

---

## 5. Structured logging & correlation

```js
// Express middleware example
app.use((req, res, next) => {
  const requestId = crypto.randomUUID();
  req.log = log.child({ requestId, method: req.method, path: req.path });
  const start = Date.now();
  res.on("finish", () => {
    req.log.info({ status: res.statusCode, ms: Date.now() - start }, "request");
  });
  next();
});
```

This lets you grep one request across services by `requestId`.

---

## 6. Error logging done right

```js
try {
  await doWork();
} catch (err) {
  // Preserve stack + cause; don't swallow
  log.error("work failed", {
    err: { message: err.message, stack: err.stack, code: err.code },
  });
  throw err; // or handle
}
```

In browsers, also hook global handlers:

```js
window.addEventListener("error", (e) => log.error("uncaught", { message: e.message, stack: e.error?.stack }));
window.addEventListener("unhandledrejection", (e) => log.error("unhandled promise", { reason: String(e.reason) }));
```

---

## 7. Best practices

- **Never log secrets** (tokens, passwords, PII). Redact: `pino` has `redact` option.
- **Log at boundaries**: HTTP in/out, DB calls, queue messages—not every loop iteration.
- **Use levels deliberately**: `debug` for dev noise, `info` for business events, `error` for failures needing action.
- **Include context**: request id, user id, version, environment.
- **Avoid sync I/O** in hot paths; use async transports or buffering.
- **Don't `console.log` in libraries** you publish; expose a logger or stay silent.
- **Gate verbose logs**: `if (log.isLevelEnabled("debug"))` for expensive serialization.
- **Rotate files** (logrotate) and ship to aggregator (ELK, Datadog, Loki).
- **Source maps**: in production minified stacks are useless without source maps.

---

## 8. Quick decision guide

- **Dev / scripts**: `console.log` / `console.error`.
- **Node service**: `pino` (performance) or `winston` (ecosystem).
- **Browser app**: `console` + error tracking SDK (Sentry) for uncaught errors.
- **Shared library**: accept a logger via options or use `debug` package for namespaced debug output.

```js
// debug package (great for libs)
import createDebug from "debug";
const dbg = createDebug("mylib:parser");
dbg("parsed %d tokens", tokens.length); // enabled via DEBUG=mylib:* env var
```

That covers the idea, syntax, and where logging fits in real JavaScript codebases.

## Mistake

```js
function processOrder(order) {
  console.log("Processing order:", order);

  order.status = "processing";
  // ... do work ...
  order.status = "completed";
  order.completedAt = new Date();

  return order;
}

processOrder({ id: 42, customer: "Alice", status: "new" });
```

### Why this is wrong

1. **Logged object references can change after the fact.**  
   In browsers and Node.js, `console.log` often stores a reference to an object rather than a deep snapshot. By the time you inspect the output, the object may already have been mutated, so the console can misleadingly show `status: "completed"` even though it was `"new"` at log time.

2. **It logs the whole object, including sensitive or irrelevant fields.**  
   If `order` contains payment tokens, PII, or large nested structures, those get dumped into logs. That is a security and performance problem.

3. **No log level or context.**  
   Using `console.log` for everything makes it hard to filter debug noise from real errors in production.

---

## Corrected version

```js
function processOrder(order) {
  // Log a stable snapshot with only the fields you need.
  console.info("Processing order", {
    id: order.id,
    customer: order.customer,
    status: order.status, // captured before mutation
    startedAt: new Date().toISOString(),
  });

  const workingOrder = { ...order, status: "processing" };

  // ... do work ...

  const completedOrder = {
    ...workingOrder,
    status: "completed",
    completedAt: new Date().toISOString(),
  };

  console.info("Order completed", {
    id: completedOrder.id,
    status: completedOrder.status,
    completedAt: completedOrder.completedAt,
  });

  return completedOrder;
}

processOrder({ id: 42, customer: "Alice", status: "new" });
```

### What changed and why

- **Snapshot fields instead of the whole object.**  
  This prevents later mutations from altering what was already logged and avoids leaking sensitive data.

- **Avoid mutating the input object.**  
  Creating `workingOrder` and `completedOrder` keeps the original input stable, which makes logs truthful and reduces side effects.

- **Use a log level (`info`).**  
  In production, route logs through a real logger (Winston, Pino, Bunyan, etc.) so you can set levels, add request IDs, and redact secrets centrally.

- **Structured data, not string interpolation.**  
  Passing an object as the second argument preserves fields for log aggregation tools. Instead of:
  ```js
  console.log("Processing order " + order.id + " status " + order.status);
  ```
  prefer:
  ```js
  console.info("Processing order", { id: order.id, status: order.status });
  ```

### Extra tips

- **Never log secrets:** passwords, tokens, full card numbers, raw auth headers.
- **Don’t log inside tight loops without sampling or rate limiting.**
- **Don’t stringify huge objects synchronously** on hot paths; use lazy field selection.
- **For errors, log the `Error` object itself**, not just `error.message`, so stack traces survive:
  ```js
  try { ... }
  catch (err) { console.error("Order failed", { id: order.id, error: err }); }
  ```
- In production, prefer a logger that supports redaction, child loggers, and async transports.

# Common JavaScript Logging Pitfalls

Below are the most common mistakes, each with a “bad” and “better” snippet. Examples target Node.js, but most apply to browsers too.

---

## 1. Leaving `console.log` in production

**Pitfall:** Debug logs ship to users, leak internals, and can’t be filtered by level.

```js
// BAD
function getUser(id) {
  console.log('getUser called', id);   // always runs, no level
  return db.find(id);
}

// BETTER (pino)
import pino from 'pino';
const log = pino({ level: process.env.LOG_LEVEL || 'info' });

function getUser(id) {
  log.debug({ id }, 'getUser called');
  return db.find(id);
}
```

**Fix:** Use a real logger, configure level via env, and strip `console.*` in build (ESLint `no-console`, bundler drop).

---

## 2. Logging sensitive data / secrets

**Pitfall:** Tokens, passwords, PII end up in log aggregators.

```js
// BAD
log.info({ user, password, authorization: req.headers.authorization }, 'login');

// BETTER: redact at logger config
const log = pino({
  redact: ['password', 'authorization', 'req.headers.cookie', '*.token'],
});
log.info({ user, password, authorization: req.headers.authorization }, 'login');
// logs: {"user":"alice","password":"[Redacted]","authorization":"[Redacted]"}
```

**Fix:** Centralize redaction in logger config; never ad-hoc string templates with secrets.

---

## 3. String interpolation that eagerly evaluates

**Pitfall:** Expensive computation runs even when level is disabled.

```js
// BAD: stringify runs regardless of level
log.debug('payload: ' + JSON.stringify(hugeObject));

// BETTER: pass object, lazy serialization by transport
log.debug({ payload: hugeObject }, 'request payload');
```

**Fix:** Prefer structured fields; let the logger decide whether to serialize.

---

## 4. Logging objects by reference (mutation confusion)

**Pitfall:** By the time logs are flushed, the object changed.

```js
const ctx = { status: 'pending' };
log.info(ctx, 'start');
ctx.status = 'done';          // console shows 'done' even for "start" line
```

**Fix:** Snapshot immutable data.

```js
log.info({ ...ctx, snapshotAt: Date.now() }, 'start');
// or
log.info(JSON.parse(JSON.stringify(ctx)), 'start');
```

---

## 5. `console.log(error)` instead of passing the Error object

**Pitfall:** Stack traces lost or printed as `{}`.

```js
// BAD
try { throw new Error('boom'); }
catch (e) { console.log('failed:', e); }   // browsers: "failed: Error: boom" ok, but Node objects may drop stack in JSON

// BETTER
catch (e) { log.error({ err: e }, 'failed'); }  // pino serializes err with stack
```

**Fix:** Use `err`/`error` field conventions (pino/winston serializers) and log the Error instance, not `e.message`.

---

## 6. Swallowing errors in catch blocks

```js
// BAD
try { await doThing(); }
catch (e) { /* TODO */ }

// BETTER
try { await doThing(); }
catch (e) {
  log.error({ err: e, op: 'doThing' }, 'operation failed');
  throw e; // or handle deliberately
}
```

---

## 7. Circular references crash `JSON.stringify`

```js
const a = {}; a.self = a;
// JSON.stringify(a) -> TypeError

// pino handles circulars with [Circular] by default;
// winston needs a replacer or a circular-safe lib.
import stringify from 'json-stringify-safe';
log.info(stringify(a));
```

**Fix:** Use a logger with circular handling, or `flatted`/`json-stringify-safe`.

---

## 8. Mixing sync I/O on the hot path

**Pitfall:** `fs.appendFileSync` blocks the event loop.

```js
// BAD
function requestHandler(req, res) {
  fs.appendFileSync('app.log', `${Date.now()} ${req.url}\n`); // blocks
  res.end('ok');
}

// BETTER: async transport / batching (pino with pino-transport, or winston async)
const log = pino(pino.transport({ target: 'pino/file', options: { destination: 'app.log' } }));
```

**Fix:** Batched async transports; never sync file writes in request path.

---

## 9. Not correlating logs (no request ID)

**Pitfall:** Can’t trace a request across async calls.

```js
// BAD
app.get('/user/:id', async (req, res) => {
  log.info('fetching user');
  const u = await svc.get(req.params.id);
  log.info('done');
  res.json(u);
});

// BETTER
import { AsyncLocalStorage } from 'node:async_hooks';
const als = new AsyncLocalStorage();

app.use((req, res, next) => {
  const id = req.headers['x-request-id'] || crypto.randomUUID();
  als.run({ requestId: id }, next);
});

const log = base.child({}); // bind per-request
app.get('/user/:id', async (req, res) => {
  const { requestId } = als.getStore();
  const rlog = log.child({ requestId });
  rlog.info('fetching user');
  const u = await svc.get(req.params.id);
  rlog.info('done');
  res.json(u);
});
```

---

## 10. Inconsistent levels / using `debug` in prod unknowingly

```js
// BAD: everything 'info', no granularity
log.info('cache hit'); log.info('cache miss');

// BETTER: reserve levels
log.trace('enter fn');   // very verbose
log.debug('cache hit');  // dev-only typically
log.info('request completed');
log.warn('retrying');
log.error('failed');
log.fatal('process aborting');
```

**Fix:** Document a level policy; gate `debug`/`trace` by env.

---

## 11. Logging huge payloads / full bodies

**Pitfall:** Memory blowup, cost, PII.

```js
// BAD
log.info({ body: req.body }, 'request');

// BETTER: truncate + allowlist
function summarize(body) {
  const s = JSON.stringify(body);
  return s.length > 500 ? s.slice(0, 500) + '…' : s;
}
log.info({ bodySize: Buffer.byteLength(JSON.stringify(req.body)), keys: Object.keys(req.body) }, 'request');
```

---

## 12. Not handling uncaught errors / unhandled rejections

```js
// BAD: process exits silently or default prints ugly stack

// BETTER
process.on('uncaughtException', (err) => {
  log.fatal({ err }, 'uncaughtException');
  process.exit(1);
});
process.on('unhandledRejection', (reason) => {
  log.error({ err: reason }, 'unhandledRejection');
});
```

**Fix:** Log then exit for uncaught; for unhandled rejections, log and decide policy.

---

## 13. Global mutable logger in tests (state leakage)

```js
// BAD
let logger = console;
function setLogger(l) { logger = l; } // tests mutate global

// BETTER: dependency injection
function makeService({ log }) {
  return {
    async run() { log.info('running'); }
  };
}
// test
const spy = { info: jest.fn() };
const svc = makeService({ log: spy });
```

---

## 14. Timezone / timestamp inconsistencies

```js
// BAD: new Date().toString() -> local tz, not sortable

// BETTER: ISO UTC at logger
const log = pino({ timestamp: pino.stdTimeFunctions.isoTime });
log.info('x'); // "time":"2025-01-02T03:04:05.678Z"
```

---

## 15. Browser: `console.log(object)` shows live reference

Same as #4; additionally, collapsed object state. Fix with `structuredClone` or serialize.

```js
console.log(structuredClone(obj));
```

Also beware: DevTools formats `Error` specially only when passed directly, not inside objects—pass `{ err }`? Actually pass the error as first arg positionally when possible: `console.error(err)`.

---

## 16. Mixing formats (text vs JSON) breaking pipelines

**Fix:** Pick JSON for machines, pretty-print only in dev.

```js
const log = pino({
  transport: process.env.NODE_ENV !== 'production'
    ? { target: 'pino-pretty', options: { colorize: true } }
    : undefined, // raw JSON in prod
});
```

---

## Quick checklist

- [ ] Levels via env, not `console`.
- [ ] Redaction configured centrally.
- [ ] Structured fields, not string concat of secrets.
- [ ] Snapshot mutable state.
- [ ] Pass `Error` instances.
- [ ] Async transports, no sync FS.
- [ ] Request/correlation IDs.
- [ ] Truncate large payloads.
- [ ] uncaughtException/unhandledRejection handlers.
- [ ] ISO timestamps, JSON in prod.

If you want, I can expand any one pitfall into a full production setup (e.g., pino + OpenTelemetry correlation, or Winston redaction pipelines).

## Exercise

Build a small structured logger factory for JavaScript:

```js
const log = createLogger('orders', { minLevel: 'info' });

log.info('Order created', { orderId: 42 });
log.debug('This should not appear'); // filtered out

const paymentLog = log.child('payment');
paymentLog.warn('Payment retry', { attempt: 2 });
```

Requirements:

- Levels: `debug`, `info`, `warn`, `error`.
- Each log entry must contain: ISO timestamp, namespace, level, message, and optional metadata.
- Respect `minLevel`.
- Child loggers inherit namespace and settings, but can override `minLevel` or writer.
- Use a `write(level, entry)` function instead of hard-coding `console`.
- Handle `Error` objects in metadata safely.

---

## Step-by-step solution

### 1. Define level ranking

Levels need numeric ranks so we can compare them:

```js
const LEVELS = Object.freeze({
  debug: 10,
  info: 20,
  warn: 30,
  error: 40,
});
```

### 2. Create the factory

The factory closes over `namespace`, `minLevel`, and `write`:

```js
function createLogger(namespace, options = {}) {
  const minLevel = normalizeLevel(options.minLevel ?? 'info');
  const write = options.write ?? defaultWrite;

  function shouldLog(level) {
    return LEVELS[level] >= LEVELS[minLevel];
  }

  function log(level, message, meta) {
    if (!shouldLog(level)) return;

    const entry = {
      timestamp: new Date().toISOString(),
      namespace,
      level,
      message,
    };

    if (meta !== undefined) {
      entry.meta = normalizeMeta(meta);
    }

    write(level, entry);
  }

  // level methods...
}
```

### 3. Add level methods

Each method delegates to `log`:

```js
const logger = {
  debug: (message, meta) => log('debug', message, meta),
  info: (message, meta) => log('info', message, meta),
  warn: (message, meta) => log('warn', message, meta),
  error: (message, meta) => log('error', message, meta),
  child: (childNamespace, childOptions = {}) => createLogger(
    `${namespace}:${childNamespace}`,
    {
      minLevel: childOptions.minLevel ?? minLevel,
      write: childOptions.write ?? write,
      ...childOptions,
    }
  ),
};
```

### 4. Handle `Error` metadata safely

`Error` properties such as `stack` are non-enumerable, so plain object spreading loses them:

```js
function normalizeMeta(meta) {
  if (meta instanceof Error) {
    return {
      name: meta.name,
      message: meta.message,
      stack: meta.stack,
    };
  }
  return meta;
}
```

### 5. Provide a sensible default writer

The default writer uses the matching `console` method and preserves structure:

```js
function defaultWrite(level, entry) {
  const method = typeof console[level] === 'function'
    ? console[level]
    : console.log;

  const { timestamp, namespace, level: lvl, message, ...rest } = entry;
  const prefix = `${timestamp} [${namespace}] ${lvl.toUpperCase()}`;

  if (Object.keys(rest).length === 0) {
    method(`${prefix}: ${message}`);
  } else {
    method(`${prefix}: ${message}`, rest);
  }
}
```

### 6. Add a quick test using a fake writer

```js
const entries = [];
const log = createLogger('orders', {
  minLevel: 'debug',
  write: (level, entry) => entries.push(entry),
});

log.info('Order created', { orderId: 42 });
log.debug('Debug detail');
const paymentLog = log.child('payment');
paymentLog.warn('Payment retry', { attempt: 2 });

console.assert(entries.length === 3);
console.assert(entries[0].namespace === 'orders');
console.assert(entries[2].namespace === 'orders:payment');
```

