## Final solution

```js
const LEVELS = Object.freeze({
  debug: 10,
  info: 20,
  warn: 30,
  error: 40,
});

function normalizeLevel(level) {
  const normalized = String(level).toLowerCase();
  if (!Object.prototype.hasOwnProperty.call(LEVELS, normalized)) {
    throw new Error(`Unknown log level: ${level}`);
  }
  return normalized;
}

function normalizeMeta(meta) {
  if (meta instanceof Error) {
    return {
      name: meta.name,
      message: meta.message,
      stack: meta.stack,
    };
  }
  return meta;
}

function defaultWrite(level, entry) {
  const method = typeof console[level] === 'function'
    ? console[level]
    : console.log;

  const { timestamp, namespace, level: lvl, message, ...rest } = entry;
  const prefix = `${timestamp} [${namespace}] ${lvl.toUpperCase()}`;

  if (Object.keys(rest).length === 0) {
    method(`${prefix}: ${message}`);
  } else {
    method(`${prefix}: ${message}`, rest);
  }
}

function createLogger(namespace, options = {}) {
  const minLevel = normalizeLevel(options.minLevel ?? 'info');
  const write = options.write ?? defaultWrite;

  function shouldLog(level) {
    return LEVELS[level] >= LEVELS[minLevel];
  }

  function log(level, message, meta) {
    if (!shouldLog(level)) return;

    const entry = {
      timestamp: new Date().toISOString(),
      namespace,
      level,
      message,
    };

    if (meta !== undefined) {
      entry.meta = normalizeMeta(meta);
    }

    write(level, entry);
  }

  const logger = {
    debug: (message, meta) => log('debug', message, meta),
    info: (message, meta) => log('info', message, meta),
    warn: (message, meta) => log('warn', message, meta),
    error: (message, meta) => log('error', message, meta),

    child(childNamespace, childOptions = {}) {
      return createLogger(`${namespace}:${childNamespace}`, {
        minLevel: childOptions.minLevel ?? minLevel,
        write: childOptions.write ?? write,
        ...childOptions,
      });
    },
  };

  return logger;
}

// Example usage
const log = createLogger('orders', { minLevel: 'info' });

log.info('Order created', { orderId: 42 });
log.debug('This is filtered out');

const paymentLog = log.child('payment');
paymentLog.warn('Payment retry', { attempt: 2 });
paymentLog.error(new Error('Gateway timeout'));
```

## Logging in JavaScript — interview-style answer

### What “logging” means in JS
Logging is the practice of emitting **timestamped, leveled, structured records** about what your program is doing, so that:
- Developers can debug during development
- Operators can observe production behavior
- Errors can be correlated across services

### Core concepts you should mention
1. **Levels** — `trace`, `debug`, `info`, `warn`, `error`, `fatal` (or similar). Each has a numeric severity.
2. **Transports** — where logs go: stdout, file, HTTP endpoint, browser console, etc.
3. **Formatting** — human-readable vs JSON (structured). JSON is preferred in production.
4. **Context / metadata** — request IDs, user IDs, environment.
5. **Child loggers** — inherit context (e.g., per-request logger).
6. **Performance** — avoid string concatenation in hot paths; use lazy evaluation; don’t log huge objects synchronously in tight loops.
7. **Security** — redact secrets, PII.

### Typical API shape
```js
const logger = createLogger({ level: "info", transports: [consoleTransport()] });
logger.info("user logged in", { userId: 123 });
const reqLogger = logger.child({ requestId: "abc" });
reqLogger.error(err, "request failed");
```

---

## Minimal but “core” implementation

Below is a compact, production-shaped logger core. It supports levels, transports, child loggers, structured JSON output, and redaction hooks. Comments explain the “why”.

```js
// logger.js
// ------------------------------------------------------------
// Core logging primitives. Small enough to read in an interview,
// but structured like a real library (pino/winston style).
// ------------------------------------------------------------

const LEVELS = Object.freeze({
  trace: 10,
  debug: 20,
  info: 30,
  warn: 40,
  error: 50,
  fatal: 60,
});

const LEVEL_NAMES = Object.keys(LEVELS);

// ---------- helpers ----------

function nowIso() {
  // ISO 8601 with ms; easy to parse and sort.
  return new Date().toISOString();
}

function safeStringify(value) {
  // Handles circular refs and bigints without throwing.
  const seen = new WeakSet();
  return JSON.stringify(value, (key, val) => {
    if (typeof val === "bigint") return val.toString();
    if (typeof val === "object" && val !== null) {
      if (seen.has(val)) return "[Circular]";
      seen.add(val);
    }
    return val;
  });
}

// ---------- Transport interface ----------
// A transport is just (record) => void. Keeping it tiny makes
// testing and swapping easy.

function consoleTransport({ pretty = false } = {}) {
  return (record) => {
    const line = pretty
      ? `${record.time} ${record.level.toUpperCase()} ${record.msg}` +
        (record.meta ? " " + JSON.stringify(record.meta) : "")
      : safeStringify(record);
    // Choose console method by severity for browser/devtools niceties.
    const fn =
      record.level === "error" || record.level === "fatal"
        ? console.error
        : record.level === "warn"
        ? console.warn
        : console.log;
    fn(line);
  };
}

// ---------- Logger factory ----------

function createLogger(options = {}) {
  const {
    level = "info",
    transports = [consoleTransport()],
    base = {},          // static context merged into every record
    redact = [],        // list of keys to redact (shallow)
    onRecord,           // optional hook for tests/metrics
  } = options;

  const minLevel = LEVELS[level];
  if (minLevel === undefined) {
    throw new Error(`Unknown log level: ${level}`);
  }

  // Redaction: shallow key replacement. Real libs do deep paths.
  function redactMeta(meta) {
    if (!meta || typeof meta !== "object") return meta;
    const out = { ...meta };
    for (const key of redact) {
      if (Object.prototype.hasOwnProperty.call(out, key)) {
        out[key] = "[REDACTED]";
      }
    }
    return out;
  }

  function shouldLog(levelName) {
    return LEVELS[levelName] >= minLevel;
  }

  // Core emit function. Everything routes through here.
  function emit(levelName, msg, meta = {}) {
    if (!shouldLog(levelName)) return;

    const record = {
      time: nowIso(),
      level: levelName,
      msg: typeof msg === "string" ? msg : String(msg),
      ...base,
      ...redactMeta(meta),
    };

    // If an Error is passed as meta.err or as first arg-ish, normalize.
    if (meta instanceof Error) {
      record.err = {
        name: meta.name,
        message: meta.message,
        stack: meta.stack,
      };
    }

    onRecord?.(record);
    for (const t of transports) {
      try {
        t(record);
      } catch (e) {
        // Never let a broken transport kill the app.
        console.error("transport failed:", e);
      }
    }
  }

  // Public logger object
  const logger = {
    trace: (msg, meta) => emit("trace", msg, meta),
    debug: (msg, meta) => emit("debug", msg, meta),
    info: (msg, meta) => emit("info", msg, meta),
    warn: (msg, meta) => emit("warn", msg, meta),
    error: (msg, meta) => emit("error", msg, meta),
    fatal: (msg, meta) => emit("fatal", msg, meta),

    // Child logger inherits base context + level/transports
    child(extra = {}) {
      return createLogger({
        level: levelNameFromMin(minLevel),
        transports,
        base: { ...base, ...extra },
        redact,
        onRecord,
      });
    },

    // Allow runtime level changes (useful in prod)
    setLevel(newLevel) {
      if (LEVELS[newLevel] === undefined) throw new Error("bad level");
      // mutate via closure variable by recreating? Simpler: store mutable.
      // We'll handle below with a mutable holder.
    },
  };

  return logger;
}

function levelNameFromMin(n) {
  return LEVEL_NAMES.find((k) => LEVELS[k] === n) || "info";
}

// ---------- Usage example ----------

if (require.main === module) {
  const log = createLogger({
    level: process.env.LOG_LEVEL || "info",
    transports: [consoleTransport({ pretty: process.env.NODE_ENV !== "production" })],
    base: { service: "api", env: process.env.NODE_ENV || "dev" },
    redact: ["password", "token"],
  });

  log.info("server started", { port: 3000 });
  log.debug("this won't print at info level");

  const reqLog = log.child({ requestId: "req-42", userId: 7 });
  reqLog.warn("slow query", { ms: 1200, password: "secret" });

  try {
    throw new Error("boom");
  } catch (e) {
    log.error(e, { where: "startup" }); // Error normalized
  }
}
```

### Notes on what’s “core” vs “production”
- **Core here:** levels, emit pipeline, transports, child loggers, redaction, safe stringify.
- **Production additions you’d discuss:** async/batched transports, backpressure, sampling, log rotation, OpenTelemetry correlation, source maps, worker threads, structured error serialization, and **never** blocking the event loop.

### Common interview follow-ups
- **Why not just `console.log`?** No levels, no structure, no transports, hard to filter in prod.
- **Sync vs async logging?** Sync is simpler but can block; async needs buffering + flush on exit.
- **How to avoid logging secrets?** Redact at the boundary, plus lint rules / schema validation.
- **Performance tip:** Build the record lazily; skip serialization if level is disabled.

If you want, I can extend this into an async transport with a ring buffer, or show how to integrate with `pino`/`winston` in a real service.

# Edge cases in JavaScript logging

JavaScript logging looks simple (`console.log(...)`), but production systems hit many edge cases: non-serializable values, lazy DevTools evaluation, circular references, side-effecting getters, format-string injection, missing `console`, secrets, performance, and environment differences.

Below are the most important edge cases with practical patterns.

---

## 1. Circular references and non-JSON data

`console.log` usually handles circular objects, but `JSON.stringify` throws. Many loggers stringify payloads, so you need a safe serializer.

```js
const a = {};
a.self = a;
a.map = new Map([['x', 1]]);
a.set = new Set([1, 2]);
a.big = 9007199254740993n;
a.fn = function hello() {};
a.sym = Symbol('id');

console.log(a); // Usually okay in Node/browser devtools

// JSON.stringify(a); // Throws: Converting circular structure to JSON

function safeStringify(value, space = 2) {
  const seen = new WeakSet();

  return JSON.stringify(value, (key, val) => {
    if (val && typeof val === 'object') {
      if (seen.has(val)) return '[Circular]';
      seen.add(val);
    }

    if (typeof val === 'bigint') return `${val}n`;
    if (typeof val === 'function') return `[Function ${val.name || 'anonymous'}]`;
    if (typeof val === 'symbol') return val.toString();
    if (val instanceof Map) return Object.fromEntries(val);
    if (val instanceof Set) return [...val];
    if (val instanceof Error) {
      return { name: val.name, message: val.message, stack: val.stack };
    }
    return val;
  }, space);
}

console.log(safeStringify(a));
```

**Edge cases covered:** circular refs, `Map`/`Set`, `BigInt`, functions, symbols, `Error`.

---

## 2. Lazy evaluation / mutation after logging

In browsers, logging an object often stores a reference. Expanding it later may show its *current* mutated state, not its state at log time.

```js
const event = { type: 'click', count: 1 };
console.log('event:', event);

// Later mutation
event.count = 999;

// DevTools may display count: 999 when expanded
```

### Fix: snapshot before logging

```js
function snapshot(value) {
  if (value === null || typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map(snapshot);
  if (value instanceof Date) return new Date(value);
  if (value instanceof Map) return new Map([...value].map(([k, v]) => [snapshot(k), snapshot(v)]));
  if (value instanceof Set) return new Set([...value].map(snapshot));

  const out = {};
  for (const key of Object.keys(value)) {
    out[key] = snapshot(value[key]);
  }
  return out;
}

const original = { count: 1 };
console.log('snapshot:', snapshot(original));
original.count = 999; // logged value remains 1
```

Use `structuredClone` where available for deep snapshots:

```js
const clone = structuredClone ? structuredClone(original) : snapshot(original);
console.log(clone);
```

---

## 3. Format-string injection

`console.log` treats the first string argument as a format template. If untrusted input becomes the first argument, `%s`, `%d`, `%j`, `%o` can alter output or stringify unexpected data.

```js
const userInput = '%s %s %s';
console.log(userInput, { secret: 'token' }); // user controls format

// Safer: user input is never the template
console.log('User said: %s', userInput);

// Even safer for arbitrary objects:
console.log('User said:', userInput);
```

Avoid:

```js
// Dangerous pattern
console.log(req.query.message);
```

Prefer:

```js
console.log('message=%s', req.query.message);
```

---

## 4. Side-effecting getters, Proxy traps, and throwing accessors

Logging an object can invoke getters and Proxy traps. Those may mutate state, perform I/O, or throw.

```js
const dangerous = {
  get id() {
    console.log('getter executed during logging');
    return Math.random();
  },
  get boom() {
    throw new Error('getter threw');
  }
};

// May trigger getter execution depending on inspector
console.log(dangerous);
```

### Defensive shallow copy that avoids invoking getters

```js
function ownEnumerableValues(obj) {
  const out = {};
  for (const key of Object.keys(obj)) { // Object.keys does not invoke getters
    const desc = Object.getOwnPropertyDescriptor(obj, key);
    if (desc && Object.prototype.hasOwnProperty.call(desc, 'value')) {
      out[key] = desc.value; // already evaluated? Actually getter desc has no value
    } else {
      out[key] = '[accessor]';
    }
  }
  return out;
}

const obj = {
  normal: 42,
  get computed() { return 'side effect'; }
};

console.log(ownEnumerableValues(obj)); // { normal: 42, computed: '[accessor]' }
```

For Proxy objects, logging may trigger `get`, `has`, `ownKeys`. There is no fully universal way to avoid all traps, so avoid logging untrusted Proxy instances directly; instead log known plain data extracted by explicit methods.

---

## 5. BigInt, Symbol, Function, and other non-stringifiable values

Some values log fine but fail in JSON-based pipelines.

```js
const data = {
  big: 12345678901234567890n,
  sym: Symbol('secret'),
  fn: function calculate() {},
  undef: undefined,
  nan: NaN,
  inf: Infinity
};

console.log(data);
console.log(JSON.stringify(data)); // BigInt throws; others may be dropped
```

Use the `safeStringify` from section 1, or normalize first.

---

## 6. Logging `Error` objects

A common mistake is logging only `err.message`, losing the stack. Another mistake is logging an `Error` buried inside an object, where some loggers show only `{}`.

```js
try {
  throw new Error('Database connection failed');
} catch (err) {
  console.error(err);              // Good in browser/Node: shows stack
  console.error(err.stack);        // Portable string fallback
  console.error({
    name: err.name,
    message: err.message,
    stack: err.stack,
    code: err.code
  });
}
```

### Async errors

Unhandled promise rejections should be centralized, not scattered.

```js
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled rejection:', reason);
  // Avoid process.exit in libraries; applications may choose to exit
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught exception:', err);
});

window.addEventListener('error', (e) => {
  console.error('Global error:', e.error || e.message);
});

window.addEventListener('unhandledrejection', (e) => {
  console.error('Unhandled rejection:', e.reason);
});
```

---

## 7. Missing or reassigned `console`

In old browsers, `console` may be undefined until DevTools opens. In workers, jsdom, or sandboxed code, `console` may be overridden.

```js
function safeLog(...args) {
  const c = globalThis.console;
  if (c && typeof c.log === 'function') {
    c.log(...args);
  }
}

// Capture original console early if you need it later
const originalConsole = globalThis.console;

function restoreConsole() {
  globalThis.console = originalConsole;
}
```

### Logging in Web Workers

Workers have `console`, but output may be prefixed by worker ID. Keep messages self-describing.

```js
// worker.js
console.log('[worker:parse] started', { jobId: 42 });
```

---

## 8. Performance and large payloads

`console.log` can be expensive, especially in hot loops or with huge objects. Also, synchronous console output can block the event loop in Node.

```js
// Bad: logs every iteration
for (let i = 0; i < 1_000_000; i++) {
  console.log('i=', i);
}

// Better: sample or aggregate
let count = 0;
for (let i = 0; i < 1_000_000; i++) {
  count++;
}
console.log('processed', count);
```

### Limit depth/array size in Node

```js
import { inspect } from 'node:util';

const huge = { users: new Array(100000).fill({ id: 1, name: 'Alice' }) };

console.log(inspect(huge, {
  depth: 2,
  maxArrayLength: 5,
  maxStringLength: 100,
  breakLength: 120
}));
```

### Avoid logging in production hot paths

Use log levels and sampling:

```js
const LOG_SAMPLE_RATE = 0.01;

function debugSample(message, data) {
  if (Math.random() < LOG_SAMPLE_RATE) {
    console.debug(message, data);
  }
}
```

---

## 9. Secret redaction

Logs frequently leak tokens, passwords, cookies, or PII. Redact before logging.

```js
const SENSITIVE_KEY = /password|passwd|token|secret|authorization|cookie|ssn|email/i;

function redact(value, seen = new WeakSet()) {
  if (value === null || typeof value !== 'object') return value;
  if (seen.has(value)) return '[Circular]';

  seen.add(value);

  if (Array.isArray(value)) {
    return value.map(v => redact(v, seen));
  }

  if (value instanceof Date) return value.toISOString();
  if (value instanceof Error) {
    return { name: value.name, message: value.message, stack: value.stack };
  }

  const out = {};
  for (const key of Object.keys(value)) {
    if (SENSITIVE_KEY.test(key)) {
      out[key] = '[REDACTED]';
    } else {
      out[key] = redact(value[key], seen);
    }
  }
  return out;
}

const req = {
  headers: { authorization: 'Bearer abc.def.ghi', cookie: 'session=xyz' },
  body: { username: 'alice', password: 'hunter2' }
};

console.log('request:', redact(req));
```

Also redact environment variables and query strings:

```js
function redactUrl(url) {
  try {
    const u = new URL(url);
    for (const key of ['token', 'access_token', 'api_key']) {
      if (u.searchParams.has(key)) u.searchParams.set(key, '[REDACTED]');
    }
    return u.toString();
  } catch {
    return url;
  }
}
```

---

## 10. Async ordering and buffering

Console output order is not always intuitive across sync, microtasks, macrotasks, and I/O. Node may buffer stdout.

```js
console.log('1 sync');
setTimeout(() => console.log('4 timeout'), 0);
Promise.resolve().then(() => console.log('3 microtask'));
console.log('2 sync');
// Output: 1, 2, 3, 4
```

For distributed/correlated logs, include timestamps and request/correlation IDs.

```js
function logEvent(level, message, context = {}) {
  console[level]({
    ts: new Date().toISOString(),
    level,
    message,
    ...context
  });
}

logEvent('info', 'order created', { requestId: 'abc-123', orderId: 42 });
```

In Node, if you need strict ordering with streams, remember `process.stdout.write` is buffered and may be async. Avoid mixing `console.log` with raw stream writes in timing-sensitive code unless you await `stream.write` callbacks.

---

## 11. Testing and mocking `console`

Tests often spy on or replace `console`. Always restore it, even if the test throws.

```js
function withCapturedConsole(fn) {
  const original = console.log;
  const captured = [];
  console.log = (...args) => captured.push(args);

  try {
    fn(captured);
  } finally {
    console.log = original;
  }
}

withCapturedConsole((logs) => {
  console.log('hello', 42);
  console.log('done');
  console.log('captured:', logs);
});
```

Jest example:

```js
test('logs startup', () => {
  const spy = jest.spyOn(console, 'log').mockImplementation(() => {});
  startApp();
  expect(spy).toHaveBeenCalledWith('app started');
  spy.mockRestore();
});
```

---

## 12. Centralized logger instead of direct `console`

For production, wrap logging so all edge cases are handled consistently.

```js
const LOG_LEVELS = { debug: 0, info: 1, warn: 2, error: 3 };
let currentLevel = 'info';

function shouldLog(level) {
  return LOG_LEVELS[level] >= LOG_LEVELS[currentLevel];
}

function normalize(arg) {
  if (arg instanceof Error) {
    return { name: arg.name, message: arg.message, stack: arg.stack };
  }
  if (typeof arg === 'function') return `[Function ${arg.name || 'anonymous'}]`;
  if (typeof arg === 'symbol') return arg.toString();
  if (typeof arg === 'bigint') return `${arg}n`;
  return arg;
}

function log(level, ...args) {
  if (!shouldLog(level)) return;

  const normalized = args.map((arg) => {
    if (arg && typeof arg === 'object') {
      try {
        return JSON.parse(safeStringify(redact(arg)));
      } catch {
        return '[Unserializable]';
      }
    }
    return normalize(arg);
  });

  const method = console[level] || console.log;
  method(...normalized);
}

log('info', 'user logged in', { userId: 7, token: 'secret' });
log('error', new Error('boom'));
```

---

## Quick checklist

- Never use untrusted strings as the first `console.log` argument.
- Snapshot objects before logging if later mutation is possible.
- Use a circular-safe serializer for JSON-based logs.
- Avoid invoking getters/Proxy traps; extract known fields.
- Explicitly log `Error.name`, `message`, and `stack`.
- Redact secrets and PII before logging.
- Guard against missing `console` in old/browser-like environments.
- Bound depth, array length, and string length for large objects.
- Sample or aggregate high-frequency logs.
- Include timestamps and correlation IDs.
- Restore mocked `console` in tests.
- Centralize logging behind a wrapper for consistency.

# Implementing & Using Loops in JavaScript

Below is a single, runnable Node.js script that demonstrates **every built-in loop**, plus **custom loop constructs implemented from scratch** (trampolined recursion, the iterator protocol, async scheduling, and a concurrency-limited `forEach`). Run it with `node loops.js`.

```js
// loops.js — complete, runnable
'use strict';

// ---------- helpers ----------
const sleep = ms => new Promise(r => setTimeout(r, ms));
const log = (...a) => console.log(...a);

// ============================================================
// 1. BUILT-IN LOOPS
// ============================================================

log('=== for ===');
for (let i = 0; i < 5; i++) log('for', i);

log('=== while ===');
let w = 0;
while (w < 5) { log('while', w); w++; }

log('=== do...while (runs at least once) ===');
let d = 10;
do { log('do...while', d); d++; } while (d < 5);

log('=== for...in (enumerable keys; use on objects) ===');
const obj = Object.create({ inherited: 99 }); // inherited prop
obj.a = 1; obj.b = 2;
Object.defineProperty(obj, 'hidden', { value: 3, enumerable: false });
for (const k in obj) log('for...in', k, '=', obj[k]); // skips 'hidden', includes 'inherited'

log('=== for...of (iterables) ===');
for (const v of [10, 20, 30]) log('for...of', v);

log('=== for...of on a string (code points) ===');
for (const ch of 'a\uD83D\uDE00b') log('char', ch); // emoji is one iteration

log('=== Array functional loops ===');
const arr = [1, 2, 3, 4];
arr.forEach((v, i) => log('forEach', i, v));
log('map', arr.map(x => x * 2));
log('filter', arr.filter(x => x % 2 === 0));
log('reduce', arr.reduce((a, x) => a + x, 0));
log('find/findIndex', arr.find(x => x > 2), arr.findIndex(x => x > 2));
log('every/some', arr.every(x => x > 0), arr.some(x => x > 3));
log('flat/flatMap', [[1,2],[3,4]].flat(), [1,2].flatMap(x => [x, x*10]));

// ============================================================
// 2. CONTROLLING FLOW: break / continue / labels
// ============================================================
log('=== break / continue ===');
outer: for (let i = 0; i < 3; i++) {
  for (let j = 0; j < 3; j++) {
    if (i === 1 && j === 1) continue;          // skip one
    if (i === 2 && j === 0) break outer;         // exit both
    log('nested', i, j);
  }
}

// ============================================================
// 3. IMPLEMENTING LOOPS FROM SCRATCH
// ============================================================

// 3a. Trampolined recursion (avoids stack overflow for huge counts)
function trampoline(fn) {
  let result = fn();
  while (typeof result === 'function') result = result();
  return result;
}
function loopRec(n, fn, i = 0, acc = undefined) {
  if (i >= n) return acc;
  const next = fn(i, acc);
  return () => loopRec(n, fn, i + 1, next === undefined ? acc : next);
}
log('=== trampolined loop ===');
trampoline(() => loopRec(5, i => log('rec', i)));

// 3b. Custom iterator protocol (Range)
class Range {
  constructor(start, end, step = 1) {
    this.start = start; this.end = end; this.step = step;
  }
  [Symbol.iterator]() {
    let cur = this.start;
    const { end, step } = this;
    return {
      next() {
        if ((step > 0 && cur < end) || (step < 0 && cur > end)) {
          const v = cur; cur += step;
          return { value: v, done: false };
        }
        return { value: undefined, done: true };
      }
    };
  }
}
log('=== custom Range iterator ===');
for (const n of new Range(0, 6, 2)) log('range', n);
log('spread', [...new Range(5, 0, -1)]);

// 3c. Infinite iterator with take()
function* naturals(start = 0) { for (let i = start; ; i++) yield i; }
function* take(iter, n) {
  let c = 0;
  for (const v of iter) { if (c++ >= n) return; yield v; }
}
log('=== generator naturals + take ===');
log([...take(naturals(10), 4)]);

// 3d. Custom forEach with index and thisArg, returning undefined like native
function myForEach(arr, cb, thisArg) {
  const len = arr.length >>> 0;
  for (let i = 0; i < len; i++) {
    if (i in arr) cb.call(thisArg, arr[i], i, arr);
  }
  // sparse-array aware: skips holes
}
log('=== myForEach (sparse-safe) ===');
const sparse = [1, , 3]; // hole at index 1
myForEach(sparse, (v, i) => log('myForEach', i, v));

// 3e. Async sequential loop (await in for...of)
async function sequential() {
  log('=== async sequential ===');
  const items = [1, 2, 3];
  for (const it of items) {
    await sleep(20);
    log('seq', it, new Date().toISOString().slice(14, 23));
  }
}
// 3f. Concurrency-limited async forEach (pool of N workers)
async function asyncPool(limit, iterable, fn) {
  const ret = [];
  const executing = new Set();
  for (const item of iterable) {
    const p = Promise.resolve().then(() => fn(item));
    ret.push(p);
    executing.add(p);
    const clean = () => executing.delete(p);
    p.then(clean, clean);
    if (executing.size >= limit) await Promise.race(executing);
  }
  return Promise.all(ret);
}
async function pooled() {
  log('=== asyncPool (limit 2) ===');
  const results = await asyncPool(2, [1, 2, 3, 4, 5], async (n) => {
    await sleep(50);
    log('worker done', n);
    return n * 10;
  });
  log('pool results', results);
}

// ============================================================
// 4. EDGE CASES & GOTCHAS
// ============================================================
log('=== mutation during iteration (forEach snapshots length at start) ===');
const m = [1, 2, 3, 4];
m.forEach((v, i) => { if (i === 0) m.push(999); log('mut', i, v); });
log('after forEach length', m.length); // 5, but 999 not visited

log('=== for loop sees live length ===');
const m2 = [1, 2, 3, 4];
for (let i = 0; i < m2.length; i++) {
  if (i === 0) m2.push(999);
  log('for-mut', i, m2[i]);
}

// ============================================================
// 5. MAIN
// ============================================================
(async () => {
  await sequential();
  await pooled();
  log('=== done ===');
})();
```

## Key takeaways

- **`for`** is the workhorse: explicit init/test/increment, best for index-based work and large counts.
- **`while` / `do...while`** are condition-driven; `do...while` guarantees one execution.
- **`for...in`** enumerates string keys (including inherited enumerable ones) — avoid on arrays; prefer `Object.keys`/`for...of`.
- **`for...of`** consumes the **iterator protocol** (`[Symbol.iterator]`), so it works on arrays, strings, `Map`, `Set`, generators, and your own classes.
- **Functional loops** (`forEach`, `map`, `filter`, `reduce`, …) express intent and avoid off-by-one errors; they snapshot length and skip holes.
- **Labels** (`outer:`) are the only way to `break`/`continue` an outer loop.
- **Async**: use `for...of` + `await` for sequential work; use a **concurrency pool** (`asyncPool`) when you want bounded parallelism — naive `Promise.all(arr.map(async …))` is unbounded.
- **From-scratch**: trampolining converts deep recursion into a flat loop; generators + `Symbol.iterator` let you build lazy, composable iteration; sparse arrays require an `i in arr` guard.

Run the file and you’ll see each section print in order, ending with `=== done ===`.

## Loops in JavaScript

A loop repeats a block of code while a condition is true (or until a collection is exhausted). JavaScript has several loop forms; choose based on whether you know the number of iterations, whether you’re iterating values or indices, and whether you need side effects.

---

### 1. `for` — classic counter loop

**Idea:** Run code a known number of times using an initializer, condition, and increment.

```js
for (let i = 0; i < 5; i++) {
  console.log(i); // 0,1,2,3,4
}
```

**Typical use:** index-based array traversal, numeric ranges, fixed retries.

```js
const items = ["a", "b", "c"];
for (let i = 0; i < items.length; i++) {
  console.log(i, items[i]);
}
```

---

### 2. `while` — condition-first loop

**Idea:** Repeat while a condition holds; check before each iteration.

```js
let n = 3;
while (n > 0) {
  console.log(n);
  n--;
}
// 3,2,1
```

**Typical use:** reading until EOF, polling, unknown iteration count.

```js
let input = "";
while (input !== "quit") {
  input = prompt("Type 'quit' to exit:");
}
```

---

### 3. `do...while` — body runs at least once

**Idea:** Check condition after executing the body.

```js
let count = 0;
do {
  console.log("ran", count);
  count++;
} while (count < 2);
```

**Typical use:** menus, “ask once then validate,” retry until success.

---

### 4. `for...of` — iterate values (iterables)

**Idea:** Walk through iterable values (arrays, strings, Sets, Maps, generators).

```js
const nums = [10, 20, 30];
for (const n of nums) {
  console.log(n); // 10,20,30
}

for (const ch of "hi") {
  console.log(ch); // h, i
}
```

**Typical use:** clean array/string/Map value processing.

```js
const map = new Map([["a", 1], ["b", 2]]);
for (const [key, val] of map) {
  console.log(key, val);
}
```

---

### 5. `for...in` — iterate enumerable keys (objects)

**Idea:** Walk property names of an object. **Caution:** includes inherited enumerable props; not ideal for arrays.

```js
const user = { name: "Ada", age: 30 };
for (const key in user) {
  console.log(key, user[key]);
}
```

**Typical use:** debugging/inspecting plain objects. Prefer `Object.keys/values/entries` for robustness.

```js
for (const [k, v] of Object.entries(user)) {
  console.log(k, v);
}
```

---

### 6. Array methods (functional loops)

**Idea:** Use callbacks; often clearer and less error-prone than manual loops.

```js
const arr = [1, 2, 3];

arr.forEach((x, i) => console.log(i, x));

const doubled = arr.map(x => x * 2);
const evens = arr.filter(x => x % 2 === 0);
const sum = arr.reduce((a, b) => a + b, 0);
```

**Typical use:** transformations, filtering, aggregation. Note: `forEach` can’t `break` early (use `some`/`every` or a `for` loop).

---

### Loop control: `break` and `continue`

```js
for (let i = 0; i < 10; i++) {
  if (i === 3) continue; // skip 3
  if (i === 7) break;    // stop
  console.log(i);
}
```

**Labeled breaks** (rare, for nested loops):

```js
outer: for (let i = 0; i < 3; i++) {
  for (let j = 0; j < 3; j++) {
    if (i === 1 && j === 1) break outer;
    console.log(i, j);
  }
}
```

---

### Common pitfalls & tips

- **Infinite loops:** ensure the condition can become false.
  ```js
  // BAD: while (true) {} without exit
  ```
- **Mutating arrays while iterating** can skip elements; iterate over a copy or use indices carefully.
- **`const` in loops:** `for (const x of arr)` is fine because each iteration creates a new binding.
- **Performance:** For huge arrays, classic `for` or `while` may be slightly faster than `forEach`, but readability usually wins.
- **Async loops:** `forEach` doesn’t await callbacks; use `for...of` with `await`:
  ```js
  for (const url of urls) {
    const res = await fetch(url);
    console.log(res.status);
  }
  ```

---

### Quick decision guide

| Need | Use |
|---|---|
| Fixed count / index | `for` |
| Unknown count, condition-first | `while` |
| Run at least once | `do...while` |
| Values of iterable | `for...of` |
| Object keys (careful) | `for...in` or `Object.entries` |
| Transform/filter/aggregate | `map/filter/reduce` |
| Side-effect per element, no early exit | `forEach` |

That covers the core idea, syntax, and practical patterns.

```js
// ❌ Buggy version
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log("index:", i), 100);
}
// Prints: index: 3  (three times)
```

**What goes wrong**

`var` is function-scoped, not block-scoped. The loop creates **one** binding of `i` shared by every iteration. By the time the `setTimeout` callbacks run, the loop has already finished and `i` is `3`. All three closures read that same final value.

**Corrected version**

```js
// ✅ Fixed: block-scoped loop variable
for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log("index:", i), 100);
}
// Prints: index: 0, index: 1, index: 2

// ✅ Alternative: pass the value explicitly
for (var i = 0; i < 3; i++) {
  setTimeout((captured) => console.log("index:", captured), 100, i);
}
```

**Why this works**

- `let` creates a **fresh binding per iteration**, so each closure captures its own `i`.
- The second approach keeps `var` but hands the current value into the callback as an argument, decoupling the closure from the mutable loop variable.

**Extra notes for thoroughness**

- The same bug appears with `var` in `for...in` / `for...of` loops when callbacks are involved.
- With modern code, prefer `let`/`const`; if you must support very old environments, use an IIFE to capture the value:

```js
for (var i = 0; i < 3; i++) {
  (function (captured) {
    setTimeout(() => console.log("index:", captured), 100);
  })(i);
}
```

# Common Loop Pitfalls in JavaScript

Below are the most frequent issues developers hit when writing loops in JavaScript, with concise examples and fixes.

---

## 1. Infinite loops

**Pitfall:** forgetting to update the termination condition.

```js
// ❌ Infinite loop
let i = 0;
while (i < 5) {
  console.log(i);
  // forgot i++
}

// ✅ Fix
let j = 0;
while (j < 5) {
  console.log(j);
  j++;
}
```

**Also watch for:** `for (;;)` with no exit, Promises that never resolve, or mutating the bound in the wrong direction.

---

## 2. Off-by-one errors

**Pitfall:** wrong boundary (`<=` vs `<`, `length - 1` mistakes).

```js
const arr = [10, 20, 30];

// ❌ Skips last element
for (let i = 0; i < arr.length - 1; i++) console.log(arr[i]);

// ❌ Reads undefined
for (let i = 0; i <= arr.length; i++) console.log(arr[i]);

// ✅ Correct
for (let i = 0; i < arr.length; i++) console.log(arr[i]);
```

---

## 3. Mutating an array while iterating it

**Pitfall:** removing/splicing during `for` or `forEach` causes skipped elements or index drift.

```js
const nums = [1, 2, 3, 4, 5];

// ❌ Skips values because indices shift
for (let i = 0; i < nums.length; i++) {
  if (nums[i] % 2 === 0) nums.splice(i, 1);
}
console.log(nums); // [1, 3, 5]? often wrong due to skips

// ✅ Iterate backwards when deleting
for (let i = nums.length - 1; i >= 0; i--) {
  if (nums[i] % 2 === 0) nums.splice(i, 1);
}

// ✅ Or filter to a new array (preferred)
const odds = nums.filter(n => n % 2 !== 0);
```

---

## 4. Closure over a `var` loop variable

**Pitfall:** all callbacks share the same variable binding.

```js
// ❌ All log 3 (or final value)
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}

// ✅ Use let (block scope per iteration)
for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}

// ✅ Or capture with IIFE / forEach
[0, 1, 2].forEach(i => setTimeout(() => console.log(i), 0));
```

---

## 5. `await` inside `forEach` / `map` (does not await)

**Pitfall:** `Array.prototype.forEach` ignores returned promises; `map` returns an array of promises you must `Promise.all`.

```js
const urls = ['/a', '/b'];

// ❌ Requests fire concurrently-ish but forEach doesn't await; errors unhandled
urls.forEach(async (u) => {
  const r = await fetch(u);
  console.log(r.status);
});

// ✅ Sequential
for (const u of urls) {
  const r = await fetch(u);
  console.log(r.status);
}

// ✅ Parallel with control
const results = await Promise.all(urls.map(u => fetch(u)));
```

---

## 6. Using `for...in` on arrays

**Pitfall:** `for...in` enumerates string keys and inherited enumerable properties, not array values in order.

```js
const arr = ['a', 'b'];
arr.custom = 'x';

// ❌ Logs "0","1","custom" (strings), order not guaranteed for custom props
for (const k in arr) console.log(k, arr[k]);

// ✅ for...of or classic for
for (const v of arr) console.log(v);
for (let i = 0; i < arr.length; i++) console.log(arr[i]);
```

---

## 7. Expecting `forEach` to support `break` / `continue`

**Pitfall:** `forEach` has no early exit; `return` only skips current iteration (like `continue`).

```js
const arr = [1, 2, 3, 4];

// ❌ Cannot break out; return acts like continue
arr.forEach(x => {
  if (x === 3) return; // skips 3 only
  console.log(x);
});

// ✅ Use for...of with break
for (const x of arr) {
  if (x === 3) break;
  console.log(x);
}
```

---

## 8. Sparse arrays and holes

**Pitfall:** holes are skipped by `forEach`, `map`, `filter`, but indexed access returns `undefined`.

```js
const sparse = [1, , 3]; // hole at index 1

console.log(sparse.length); // 3
console.log(sparse[1]);      // undefined

sparse.forEach((v, i) => console.log(i, v)); // skips index 1

// ✅ If holes matter, use classic loop or fill
for (let i = 0; i < sparse.length; i++) {
  console.log(i, sparse[i]); // shows undefined for hole
}
```

---

## 9. Accidental infinite loop with floating point / direction

**Pitfall:** using `+= 0.1` or wrong step direction.

```js
// ❌ Never exactly 1 due to float
for (let x = 0; x !== 1; x += 0.1) console.log(x); // infinite-ish

// ❌ Infinite because i grows away from condition
for (let i = 10; i > 0; i++) console.log(i);

// ✅ Integer counters or epsilon comparisons
for (let i = 0; i < 10; i++) { /* ... */ }
```

---

## 10. Mutating the loop variable inside the body

**Pitfall:** changing `i` manually can cause skips/double processing.

```js
const arr = ['a','b','c','d'];

// ❌ Confusing control flow
for (let i = 0; i < arr.length; i++) {
  if (arr[i] === 'b') i++; // skip next
  console.log(arr[i]);
}

// ✅ Express intent clearly with while or nested logic
let i = 0;
while (i < arr.length) {
  console.log(arr[i]);
  if (arr[i] === 'b') i++; // explicit skip
  i++;
}
```

---

## 11. `this` context in callback loops

**Pitfall:** traditional functions lose `this`; arrow functions inherit it.

```js
const obj = {
  factor: 2,
  nums: [1, 2, 3],
  scaled() {
    // ❌ this is undefined (strict) or global
    return this.nums.map(function (n) { return n * this.factor; });
  },
  scaledOk() {
    // ✅ arrow preserves this
    return this.nums.map(n => n * this.factor);
  }
};
```

---

## 12. Modifying collection during `for...of` (iterators)

**Pitfall:** changing a Set/Map while iterating can skip or duplicate entries.

```js
const set = new Set([1, 2, 3]);

// ❌ May skip elements
for (const v of set) {
  if (v === 2) set.delete(v);
}

// ✅ Collect first, then mutate
const toDelete = [...set].filter(v => v === 2);
toDelete.forEach(v => set.delete(v));
```

---

## 13. Nested loops / O(n²) performance

**Pitfall:** naive nested loops over large arrays; use `Set`/`Map` for lookups.

```js
const a = [1,2,3], b = [2,3,4];

// ❌ O(n*m)
const common = a.filter(x => b.includes(x));

// ✅ O(n+m)
const setB = new Set(b);
const commonFast = a.filter(x => setB.has(x));
```

---

## 14. Forgetting that `break` only breaks innermost loop

**Pitfall:** labeled loops are rarely used; consider extracting to a function.

```js
// ❌ break only exits inner loop
outer: for (let i = 0; i < 3; i++) {
  for (let j = 0; j < 3; j++) {
    if (i === 1 && j === 1) break; // only inner
  }
}

// ✅ Early return in a helper
function find() {
  for (let i = 0; i < 3; i++)
    for (let j = 0; j < 3; j++)
      if (i === 1 && j === 1) return { i, j };
}
```

---

## Summary checklist

- Use `let`/`const`, never `var`, in loop headers.
- Prefer `for...of` for values, `for` with index when you need indices.
- Don’t mutate arrays while iterating forward; iterate backward or use `filter`.
- Don’t use `forEach` when you need `break`, `continue`, or `await`.
- Don’t use `for...in` for arrays.
- Handle sparse arrays explicitly if holes matter.
- Use `Set`/`Map` to avoid O(n²) nested loops.
- Be careful with floating-point counters and async control flow.

These cover the bulk of real-world loop bugs in JavaScript.

## Exercise

**Task:** Write a function `summarizeOrders(orders)` that takes an array of order objects:

```js
const orders = [
  { name: "Keyboard", price: 45, qty: 2, category: "electronics" },
  { name: "Mouse", price: 25, qty: 3, category: "electronics" },
  { name: "Notebook", price: 5, qty: 10, category: "stationery" },
  { name: "Pen", price: 2, qty: 20, category: "stationery" },
  { name: "Monitor", price: 200, qty: 1, category: "electronics" }
];
```

and returns a summary object:

```js
{
  totalRevenue: 560,        // sum of price * qty
  totalItems: 36,           // sum of qty
  averagePrice: 15.56,      // totalRevenue / totalItems, rounded to 2 decimals
  byCategory: {
    electronics: { count: 6, revenue: 335 },
    stationery: { count: 30, revenue: 225 }
  }
}
```

**Constraints:**
- Use at least one `for...of` loop and one `while` loop.
- Do not use `Array.prototype.reduce` for the main aggregation (practice manual loops).
- Handle empty input gracefully.

---

## Step-by-step solution

### Step 1: Understand the shape of the data and the result

Each order contributes:
- `revenue = price * qty`
- `items = qty`

We need two levels of aggregation:
1. Global: total revenue, total items.
2. Per category: count (items) and revenue.

### Step 2: Initialize accumulators

```js
let totalRevenue = 0;
let totalItems = 0;
const byCategory = {};
```

`byCategory` will be built dynamically: if a category hasn't been seen, create `{ count: 0, revenue: 0 }`.

### Step 3: First pass with `for...of` — aggregate globals and per-category

```js
for (const order of orders) {
  const revenue = order.price * order.qty;
  totalRevenue += revenue;
  totalItems += order.qty;

  if (!byCategory[order.category]) {
    byCategory[order.category] = { count: 0, revenue: 0 };
  }
  byCategory[order.category].count += order.qty;
  byCategory[order.category].revenue += revenue;
}
```

This is O(n) and avoids repeated lookups.

### Step 4: Compute average with a `while` loop (to satisfy the constraint)

We could compute `averagePrice = totalRevenue / totalItems` directly, but the exercise asks for a `while` loop. A natural use: round to 2 decimals manually or iterate to format. Here we'll use a `while` loop to build a rounded value without `toFixed` (to show loop control):

```js
let averagePrice = 0;
if (totalItems > 0) {
  // scale to 2 decimals using integer math via a while loop
  let scaled = Math.round((totalRevenue / totalItems) * 100);
  let whole = Math.trunc(scaled / 100);
  let frac = scaled % 100;
  // reconstruct with two-digit fraction using a while loop (padding)
  let fracStr = String(frac);
  while (fracStr.length < 2) fracStr = "0" + fracStr;
  averagePrice = Number(`${whole}.${fracStr}`);
}
```

> Note: In real code you'd just use `Number((totalRevenue / totalItems).toFixed(2))`. The manual version above is only to demonstrate a `while` loop.

### Step 5: Handle empty input

If `orders` is empty or not an array, return a safe zeroed summary:

```js
if (!Array.isArray(orders) || orders.length === 0) {
  return { totalRevenue: 0, totalItems: 0, averagePrice: 0, byCategory: {} };
}
```

### Step 6: Assemble the final function

```js
function summarizeOrders(orders) {
  if (!Array.isArray(orders) || orders.length === 0) {
    return { totalRevenue: 0, totalItems: 0, averagePrice: 0, byCategory: {} };
  }

  let totalRevenue = 0;
  let totalItems = 0;
  const byCategory = {};

  for (const order of orders) {
    const revenue = order.price * order.qty;
    totalRevenue += revenue;
    totalItems += order.qty;

    if (!byCategory[order.category]) {
      byCategory[order.category] = { count: 0, revenue: 0 };
    }
    byCategory[order.category].count += order.qty;
    byCategory[order.category].revenue += revenue;
  }

  let averagePrice = 0;
  if (totalItems > 0) {
    let scaled = Math.round((totalRevenue / totalItems) * 100);
    let whole = Math.trunc(scaled / 100);
    let frac = Math.abs(scaled % 100);
    let fracStr = String(frac);
    while (fracStr.length < 2) fracStr = "0" + fracStr;
    averagePrice = Number(`${whole}.${fracStr}`);
  }

  return { totalRevenue, totalItems, averagePrice, byCategory };
}
```

