**Key takeaways:**
- `for...of` is ideal for iterating array elements directly.
- A `while` loop shines when you don't know iteration count upfront (here, padding a string).
- Always guard against empty/division-by-zero cases.
- Build nested aggregates lazily (create the category bucket on first sight).

# Loops in JavaScript — Interview Answer

## 1. Conceptual overview

JavaScript has several looping constructs, each with a distinct purpose:

| Construct | Best for | Notes |
|---|---|---|
| `for` | Index-based iteration, known count | `for (let i=0; i<n; i++)` |
| `while` | Condition-driven, unknown count | Checks before body |
| `do...while` | At least one execution guaranteed | Checks after body |
| `for...in` | Enumerating **keys** of an object | Includes inherited enumerable props — use `hasOwnProperty` |
| `for...of` | Iterating **values** of iterables (Array, String, Map, Set, generators) | Uses `Symbol.iterator` |
| `Array.prototype.forEach` | Side-effect per element | No `break`/`continue`; returns `undefined` |

Key interview points:
- `for...in` walks keys (strings), order not guaranteed for objects; avoid on arrays.
- `for...of` requires the iterable protocol (`[Symbol.iterator]`).
- `forEach` cannot be short-circuited; use `some`/`every`/`find` for early exit.
- `break`/`continue` only work in statement loops, not in `forEach`.
- Performance: classic `for` with cached length is fastest; `for...of` is usually fine.

---

## 2. Implementing the "core" — custom loop primitives

Below I reimplement the most common loop utilities from scratch to show the underlying mechanics, plus a small iterable class.

```js
'use strict';

/* ------------------------------------------------------------------ */
/* 1. Classic index-based loop (the foundation of everything)         */
/* ------------------------------------------------------------------ */

/**
 * Calls `callback(element, index, array)` for each item.
 * Mirrors Array.prototype.forEach but returns nothing.
 *
 * @param {Array} array
 * @param {(el:any, i:number, arr:Array)=>void} callback
 * @param {any} [thisArg]
 */
function myForEach(array, callback, thisArg) {
  if (typeof callback !== 'function') {
    throw new TypeError('callback must be a function');
  }
  // Cache length so mutations during iteration are handled predictably.
  const len = array.length;
  for (let i = 0; i < len; i++) {
    // Skip holes in sparse arrays (matches spec behavior).
    if (i in array) {
      callback.call(thisArg, array[i], i, array);
    }
  }
}

/* ------------------------------------------------------------------ */
/* 2. Transform loop: map                                             */
/* ------------------------------------------------------------------ */

/**
 * Returns a new array where each element is `callback(element, index)`.
 */
function myMap(array, callback, thisArg) {
  if (typeof callback !== 'function') {
    throw new TypeError('callback must be a function');
  }
  const result = new Array(array.length);
  const len = array.length;
  for (let i = 0; i < len; i++) {
    if (i in array) {
      result[i] = callback.call(thisArg, array[i], i, array);
    }
    // holes stay holes (sparse preservation)
  }
  return result;
}

/* ------------------------------------------------------------------ */
/* 3. Filter with early-exit friendly variant (some/every style)      */
/* ------------------------------------------------------------------ */

/**
 * Returns first element satisfying predicate, or undefined.
 * Demonstrates short-circuiting that forEach cannot do.
 */
function myFind(array, predicate, thisArg) {
  const len = array.length;
  for (let i = 0; i < len; i++) {
    if (i in array && predicate.call(thisArg, array[i], i, array)) {
      return array[i]; // early exit
    }
  }
  return undefined;
}

/* ------------------------------------------------------------------ */
/* 4. Object enumeration (what for...in does, made explicit)            */
/* ------------------------------------------------------------------ */

/**
 * Iterates only OWN enumerable string keys of an object.
 * (Avoids the for...in inherited-property pitfall.)
 */
function forEachOwn(obj, callback, thisArg) {
  const keys = Object.keys(obj); // own enumerable, string keys only
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    callback.call(thisArg, obj[key], key, obj);
  }
}

/* ------------------------------------------------------------------ */
/* 5. Custom iterable: implementing Symbol.iterator                   */
/*    This is the "core" that makes for...of work.                    */
/* ------------------------------------------------------------------ */

class Range {
  constructor(start, end, step = 1) {
    if (step === 0) throw new RangeError('step cannot be 0');
    this.start = start;
    this.end = end;
    this.step = step;
  }

  /**
   * The iterator protocol: return an object with `next()`.
   * for...of calls this automatically.
   */
  [Symbol.iterator]() {
    let current = this.start;
    const { end, step } = this;
    const ascending = step > 0;

    return {
      next() {
        // Termination condition depends on direction.
        const done = ascending
          ? current >= end
          : current <= end;
        if (done) {
          return { value: undefined, done: true };
        }
        const value = current;
        current += step;
        return { value, done: false };
      },
    };
  }
}

/* ------------------------------------------------------------------ */
/* 6. A generic "loop" helper that works on anything iterable         */
/* ------------------------------------------------------------------ */

/**
 * Universal loop: arrays, strings, Maps, Sets, generators, Range...
 * Demonstrates consuming an iterator manually (the engine's job).
 */
function loop(iterable, callback) {
  const iterator = iterable[Symbol.iterator]();
  let result = iterator.next();
  let index = 0;
  while (!result.done) {
    // callback may return false to break (like some())
    const keepGoing = callback(result.value, index);
    if (keepGoing === false) break;
    result = iterator.next();
    index++;
  }
  // Close iterator if it supports return() (generators do).
  if (typeof iterator.return === 'function') {
    iterator.return();
  }
}

/* ------------------------------------------------------------------ */
/* Demo / sanity checks                                                */
/* ------------------------------------------------------------------ */
if (require.main === module) {
  console.log('--- myForEach ---');
  myForEach([10, 20, 30], (v, i) => console.log(i, v));

  console.log('--- myMap ---');
  console.log(myMap([1, 2, 3], (x) => x * x)); // [1,4,9]

  console.log('--- myFind (short-circuit) ---');
  console.log(myFind([1, 2, 3, 4], (x) => x > 2)); // 3

  console.log('--- forEachOwn ---');
  forEachOwn({ a: 1, b: 2 }, (v, k) => console.log(k, v));

  console.log('--- Range via for...of ---');
  for (const n of new Range(0, 10, 2)) console.log(n); // 0,2,4,6,8

  console.log('--- universal loop with break ---');
  loop(new Range(0, 100, 1), (v) => {
    if (v === 5) return false; // break
    console.log(v);
  });
}
```

### Interview talking points to weave in
- **Sparse arrays**: `i in array` check mirrors the spec; naive loops would visit holes.
- **`thisArg`**: all built-ins support it; we use `Function.prototype.call`.
- **Short-circuiting**: only statement loops (`for`/`while`) and `some`/`every`/`find` allow `break`; `forEach` does not.
- **Iterator protocol**: `next()` returns `{value, done}`; `for...of` is syntactic sugar over this.
- **Generators** are the easiest way to write custom iterables: `function* range(...) { for (...) yield n; }`.
- **Performance**: hoist `array.length` out of the condition; avoid `for...in` on arrays.

# Edge Cases When Using Loops in JavaScript

Below are the most important edge cases, grouped by loop type, with runnable examples.

---

## 1. Traditional `for` loops

### Off-by-one with `<=`
```js
const arr = [10, 20, 30];
for (let i = 0; i <= arr.length; i++) {
  console.log(arr[i]); // 10, 20, 30, undefined
}
```
**Fix:** use `< arr.length`.

### Mutating the array while iterating
```js
const arr = [1, 2, 3, 4];
for (let i = 0; i < arr.length; i++) {
  if (arr[i] === 2) arr.splice(i, 1); // removes 2, shifts 3,4 left
}
console.log(arr); // [1, 3, 4]  -- 3 was skipped!
```
**Fix:** iterate backwards, or collect indices first, or use `filter`.

### Closure capturing a `var` index
```js
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0); // 3, 3, 3
}
for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0); // 0, 1, 2
}
```

### Floating-point accumulation
```js
for (let x = 0; x !== 1; x += 0.1) {
  console.log(x);
}
// May print 0, 0.1, ..., 0.9, then 1.0000000000000002? Actually !== 1 may never be true exactly.
```
**Fix:** use an integer counter and derive the value:
```js
for (let i = 0; i < 10; i++) {
  const x = i / 10;
}
```

### Resetting the loop variable inside the body
```js
for (let i = 0; i < 5; i++) {
  i = 10; // jumps out after first iteration
}
```

### Empty statement after `for`
```js
for (let i = 0; i < 5; i++); {
  console.log("runs once, i is not in scope here with let");
}
```
The `;` makes the loop body empty; the block is just a block.

### NaN / Infinity counters
```js
for (let i = NaN; i < 5; i++) console.log(i);   // never runs (NaN < 5 is false)
for (let i = 0; i < Infinity; i++) { /* infinite */ }
for (let i = 5; i > 0; i--) { /* fine */ }
for (let i = 0; i < 5; i--) { /* infinite: goes negative */ }
```

---

## 2. `while` / `do...while`

### `do...while` runs at least once
```js
let i = 5;
do {
  console.log(i); // prints 5 even though condition is false
  i++;
} while (i < 5);
```

### Infinite loops from inexact termination
```js
let x = 1;
while (x !== 0) {
  x -= 0.1; // may never hit exactly 0
}
```

### Condition evaluated before first iteration
```js
let ready = false;
while (ready) {
  console.log("never runs");
}
```

---

## 3. `for...in` (enumerates keys, including inherited)

### Prototype chain leakage
```js
const obj = Object.create({ inherited: 1 });
obj.own = 2;
for (const k in obj) console.log(k); // "own", "inherited"
```
**Fix:** guard with `hasOwnProperty`:
```js
for (const k in obj) {
  if (Object.prototype.hasOwnProperty.call(obj, k)) console.log(k);
}
```

### Numeric-looking keys are sorted, not insertion-ordered
```js
const obj = {};
obj["2"] = "b";
obj["10"] = "a";
obj["1"] = "c";
for (const k in obj) console.log(k); // "1", "2", "10"
```

### Arrays: indices as strings + extra properties
```js
const arr = [10, 20];
arr.foo = "bar";
for (const k in arr) console.log(k, arr[k]);
// "0" 10, "1" 20, "foo" "bar"
```
Also, sparse arrays still enumerate existing indices only:
```js
const a = [1, , 3];
for (const k in a) console.log(k); // "0", "2"
```

### Order is not guaranteed for non-integer keys in older engines
Modern engines mostly follow insertion order for string keys, but do not rely on it for `for...in`.

---

## 4. `for...of` (iterables)

### Does not work on plain objects
```js
for (const x of {}) {} // TypeError: {} is not iterable
```
**Fix:** use `Object.keys`, `Object.values`, or `Object.entries`.

### Sparse arrays yield `undefined` for holes
```js
const a = [1, , 3];
for (const x of a) console.log(x); // 1, undefined, 3
```
(Contrast with `forEach`, which skips holes.)

### Mutating a collection during iteration
Arrays grow the iterator:
```js
const arr = [1, 2, 3];
for (const x of arr) {
  arr.push(4); // infinite loop! iterator checks length each step
}
```
Sets/Maps are safer but have rules:
```js
const set = new Set([1, 2, 3]);
for (const x of set) {
  if (x === 2) set.delete(x); // OK: deletes current
  set.add(4);                 // 4 may or may not be visited depending on timing
}
```

### Strings iterate by code points, not UTF-16 units
```js
for (const c of "😀") console.log(c); // one iteration: "😀"
"😀".length; // 2 (surrogate pair)
"😀"[0];     // "\ud83d"
```

### Async iteration needs `for await...of`
```js
async function* gen() { yield 1; yield 2; }
for await (const x of gen()) console.log(x);
```
Using plain `for...of` on an async iterable gives a thenable, not the value.

### Iterating array-likes
```js
const arrayLike = { 0: "a", 1: "b", length: 2 };
for (let i = 0; i < arrayLike.length; i++) console.log(arrayLike[i]); // works
for (const x of arrayLike) {} // TypeError (not iterable)
```

---

## 5. Array methods (`forEach`, `map`, `filter`, ...)

### `forEach` cannot be broken out of
```js
[1, 2, 3].forEach(x => {
  if (x === 2) return; // only skips this callback, not the loop
  console.log(x);      // 1, 3
});
```
**Fix:** use a `for` loop or `some`/`every` for early exit.

### `forEach` skips holes in sparse arrays
```js
const a = [1, , 3];
a.forEach(x => console.log(x)); // 1, 3  (hole skipped)
```

### `this` binding
```js
[1, 2].forEach(function (x) {
  console.log(this.label, x);
}, { label: "item" }); // "item 1", "item 2"
// Arrow functions ignore the second arg.
```

### Async callbacks are not awaited
```js
const urls = ["/a", "/b"];
urls.forEach(async url => {
  await fetch(url); // fires all at once; forEach returns immediately
});
// Fix: use for...of with await
for (const url of urls) await fetch(url);
```

### Mutating during `forEach`
```js
const arr = [1, 2, 3];
arr.forEach((x, i) => {
  if (x === 2) arr.splice(i, 1); // may skip or revisit; behavior is implementation-defined-ish
});
```
Avoid mutating the array being iterated.

### `map`/`filter` create new arrays; chaining costs memory
Not an edge case per se, but large arrays + chaining can be expensive. Use a single `reduce` or loop when performance matters.

---

## 6. Cross-cutting edge cases

### Labelled `break` / `continue`
```js
outer: for (let i = 0; i < 3; i++) {
  for (let j = 0; j < 3; j++) {
    if (i === 1 && j === 1) break outer;
    console.log(i, j);
  }
}
```

### `continue` inside `switch` inside a loop
`continue` refers to the enclosing loop, not the `switch`. This is legal but often surprising.

### Destructuring in loop headers
```js
const pairs = [[1, 2], [3]];
for (const [a, b] of pairs) {
  console.log(a, b); // 1 2, then 3 undefined
}
```

### `const` in `for` loop header creates new binding per iteration
```js
for (const i = 0; i < 3; i++) {} // SyntaxError: Assignment to constant variable? Actually `i++` tries to reassign const -> TypeError at runtime.
```
Use `let` for counters you mutate.

### Empty collections
```js
for (const x of []) console.log("never");
[].forEach(x => console.log("never"));
```
Fine, but watch downstream code assuming at least one iteration.

### `arguments` / array-like in loops
```js
function f() {
  for (let i = 0; i < arguments.length; i++) console.log(arguments[i]);
}
```
`arguments` is array-like but not an array; no `forEach` unless converted.

---

## Quick checklist

1. Use `< length`, not `<=`.
2. Prefer `let`/`const` over `var` in loop headers.
3. Don't mutate the collection while iterating unless you know the semantics.
4. Don't use `for...in` on arrays unless you handle inherited/extra keys.
5. Don't use `forEach` if you need `break`, `await`, or index-aware mutation.
6. Guard floating-point termination with integer counters.
7. Remember sparse arrays behave differently across loop types.
8. Use `for await...of` for async iterables.

If you want, I can drill into any one of these (e.g., a deep dive on `for...of` mutation semantics or performance comparisons).

Below is a complete, runnable JavaScript implementation of a `Matrix` class with common operations. It works in Node.js or any modern browser (ES2015+). Save as `matrix.js` and run with `node matrix.js`.

```javascript
// matrix.js
class Matrix {
  constructor(rows, cols, fill = 0) {
    if (Array.isArray(rows)) {
      // Allow Matrix([[1,2],[3,4]])
      const data = rows;
      this.rows = data.length;
      this.cols = data[0].length;
      this.data = data.map(r => r.slice());
      return;
    }
    this.rows = rows;
    this.cols = cols;
    this.data = Array.from({ length: rows }, () => Array(cols).fill(fill));
  }

  // ---------- factories ----------
  static fromArray(arr) { return new Matrix(arr); }
  static zeros(r, c) { return new Matrix(r, c, 0); }
  static ones(r, c) { return new Matrix(r, c, 1); }
  static identity(n) {
    const m = new Matrix(n, n, 0);
    for (let i = 0; i < n; i++) m.data[i][i] = 1;
    return m;
  }
  static random(r, c, min = 0, max = 1) {
    const m = new Matrix(r, c);
    for (let i = 0; i < r; i++)
      for (let j = 0; j < c; j++)
        m.data[i][j] = Math.random() * (max - min) + min;
    return m;
  }

  // ---------- access ----------
  get(r, c) { return this.data[r][c]; }
  set(r, c, v) { this.data[r][c] = v; return this; }

  // ---------- basic ----------
  clone() {
    const m = new Matrix(this.rows, this.cols);
    for (let i = 0; i < this.rows; i++)
      for (let j = 0; j < this.cols; j++)
        m.data[i][j] = this.data[i][j];
    return m;
  }

  equals(other, eps = 1e-9) {
    if (this.rows !== other.rows || this.cols !== other.cols) return false;
    for (let i = 0; i < this.rows; i++)
      for (let j = 0; j < this.cols; j++)
        if (Math.abs(this.data[i][j] - other.data[i][j]) > eps) return false;
    return true;
  }

  // ---------- arithmetic ----------
  add(other) {
    if (this.rows !== other.rows || this.cols !== other.cols)
      throw new Error('Dimension mismatch for add');
    const out = new Matrix(this.rows, this.cols);
    for (let i = 0; i < this.rows; i++)
      for (let j = 0; j < this.cols; j++)
        out.data[i][j] = this.data[i][j] + other.data[i][j];
    return out;
  }

  sub(other) {
    if (this.rows !== other.rows || this.cols !== other.cols)
      throw new Error('Dimension mismatch for sub');
    const out = new Matrix(this.rows, this.cols);
    for (let i = 0; i < this.rows; i++)
      for (let j = 0; j < this.cols; j++)
        out.data[i][j] = this.data[i][j] - other.data[i][j];
    return out;
  }

  // matrix multiplication (this * other)
  mul(other) {
    if (typeof other === 'number') {
      const out = new Matrix(this.rows, this.cols);
      for (let i = 0; i < this.rows; i++)
        for (let j = 0; j < this.cols; j++)
          out.data[i][j] = this.data[i][j] * other;
      return out;
    }
    if (other instanceof Matrix) {
      if (this.cols !== other.rows)
        throw new Error('Dimension mismatch for mul');
      const out = new Matrix(this.rows, other.cols);
      for (let i = 0; i < this.rows; i++) {
        for (let k = 0; k < this.cols; k++) {
          if (this.data[i][k] === 0) continue;
          const aik = this.data[i][k];
          for (let j = 0; j < other.cols; j++)
            out.data[i][j] += aik * other.data[k][j];
        }
      }
      return out;
    }
    throw new Error('mul expects number or Matrix');
  }

  transpose() {
    const out = new Matrix(this.cols, this.rows);
    for (let i = 0; i < this.rows; i++)
      for (let j = 0; j < this.cols; j++)
        out.data[j][i] = this.data[i][j];
    return out;
  }

  // ---------- linear algebra ----------
  trace() {
    if (this.rows !== this.cols) throw new Error('Trace requires square matrix');
    let s = 0;
    for (let i = 0; i < this.rows; i++) s += this.data[i][i];
    return s;
  }

  determinant() {
    if (this.rows !== this.cols) throw new Error('Determinant requires square matrix');
    const n = this.rows;
    // copy
    const a = this.clone().data;
    let det = 1;
    for (let col = 0; col < n; col++) {
      // partial pivot
      let pivot = col;
      let best = Math.abs(a[col][col]);
      for (let r = col + 1; r < n; r++) {
        if (Math.abs(a[r][col]) > best) { best = Math.abs(a[r][col]); pivot = r; }
      }
      if (best < 1e-12) return 0;
      if (pivot !== col) {
        [a[col], a[pivot]] = [a[pivot], a[col]];
        det = -det;
      }
      det *= a[col][col];
      for (let r = col + 1; r < n; r++) {
        const factor = a[r][col] / a[col][col];
        for (let c = col; c < n; c++) a[r][c] -= factor * a[col][c];
      }
    }
    return det;
  }

  inverse() {
    if (this.rows !== this.cols) throw new Error('Inverse requires square matrix');
    const n = this.rows;
    // augmented [A | I]
    const a = Array.from({ length: n }, (_, i) =>
      [...this.data[i], ...Array.from({ length: n }, (_, j) => (i === j ? 1 : 0))]
    );
    // Gaussian elimination with partial pivot
    for (let col = 0; col < n; col++) {
      let pivot = col;
      let best = Math.abs(a[col][col]);
      for (let r = col + 1; r < n; r++) {
        if (Math.abs(a[r][col]) > best) { best = Math.abs(a[r][col]); pivot = r; }
      }
      if (best < 1e-12) throw new Error('Matrix is singular');
      if (pivot !== col) [a[col], a[pivot]] = [a[pivot], a[col]];
      const pv = a[col][col];
      for (let c = 0; c < 2 * n; c++) a[col][c] /= pv;
      for (let r = 0; r < n; r++) {
        if (r === col) continue;
        const factor = a[r][col];
        for (let c = 0; c < 2 * n; c++) a[r][c] -= factor * a[col][c];
      }
    }
    const out = new Matrix(n, n);
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++)
        out.data[i][j] = a[i][n + j];
    return out;
  }

  // solve A x = b (b can be Matrix column or array)
  solve(b) {
    if (this.rows !== this.cols) throw new Error('solve requires square matrix');
    const n = this.rows;
    const B = Array.isArray(b) ? b.slice() : b.data.map(r => r[0]);
    if (B.length !== n) throw new Error('Dimension mismatch in solve');
    const a = this.clone().data.map((r, i) => [...r, B[i]]);
    for (let col = 0; col < n; col++) {
      let pivot = col;
      let best = Math.abs(a[col][col]);
      for (let r = col + 1; r < n; r++) {
        if (Math.abs(a[r][col]) > best) { best = Math.abs(a[r][col]); pivot = r; }
      }
      if (best < 1e-12) throw new Error('Singular matrix');
      if (pivot !== col) [a[col], a[pivot]] = [a[pivot], a[col]];
      const pv = a[col][col];
      for (let c = col; c <= n; c++) a[col][c] /= pv;
      for (let r = 0; r < n; r++) {
        if (r === col) continue;
        const factor = a[r][col];
        for (let c = col; c <= n; c++) a[r][c] -= factor * a[col][c];
      }
    }
    return a.map(r => r[n]);
  }

  // ---------- output ----------
  toString() {
    return this.data.map(r => r.map(v => (Number.isInteger(v) ? v : v.toFixed(4))).toString().padStart(8)).join(' ')).join('\n');
  }
  toArray() { return this.data.map(r => r.slice()); }
}

// ---------- runnable demo ----------
if (typeof require !== 'undefined' && require.main === module) {
  const A = Matrix.fromArray([[2, 1, 3], [1, 0, 2], [3, 1, 1]]);
  const B = Matrix.fromArray([[1, 2], [3, 4], [5, 6]]);
  console.log('A ='); console.log(A.toString());
  console.log('\nB ='); console.log(B.toString());

  const C = A.mul(B);
  console.log('\nA * B ='); console.log(C.toString());

  console.log('\nA^T ='); console.log(A.transpose().toString());
  console.log('\ndet(A) =', A.determinant());
  console.log('trace(A) =', A.trace());

  const inv = A.inverse();
  console.log('\nA^{-1} ='); console.log(inv.toString());
  console.log('\nA * A^{-1} ≈ I ?'); console.log(A.mul(inv).toString());

  // solve A x = b
  const x = A.solve([1, 2, 3]);
  console.log('\nSolution A x = [1,2,3]:', x);

  const I = Matrix.identity(3);
  console.log('\nI + 2I ='); console.log(I.add(I.mul(2)).toString());
}

module.exports = Matrix;
```

