### Mistake: aliasing the input matrix

```js
function addMatrices(A, B) {
  // BUG: result is just another reference to A
  const result = A;

  for (let i = 0; i < A.length; i++) {
    for (let j = 0; j < A[i].length; j++) {
      result[i][j] = A[i][j] + B[i][j];
    }
  }

  return result;
}

const A = [[1, 2], [3, 4]];
const B = [[10, 20], [30, 40]];

const C = addMatrices(A, B);
console.log(C); // [[11, 22], [33, 44]]
console.log(A); // [[11, 22], [33, 44]]  <-- input was mutated!
```

### What went wrong

- `const result = A;` does **not** copy the matrix. It creates a second name for the exact same array-of-arrays object.
- Every write to `result[i][j]` therefore writes into `A[i][j]`.
- So the function has an invisible side effect: it destroys the original input. This is a classic bug in numerical code, especially when the caller reuses `A` later.
- There are also no dimension checks: if `B` is smaller, `B[i][j]` becomes `undefined`, and `number + undefined` becomes `NaN`, silently poisoning the whole computation.

### Corrected version

```js
function addMatrices(A, B) {
  if (!Array.isArray(A) || !Array.isArray(B)) {
    throw new TypeError("Both arguments must be 2D arrays");
  }
  if (A.length !== B.length) {
    throw new RangeError("Matrices must have the same number of rows");
  }

  const result = new Array(A.length);

  for (let i = 0; i < A.length; i++) {
    if (!Array.isArray(A[i]) || !Array.isArray(B[i])) {
      throw new TypeError("Each row must be an array");
    }
    if (A[i].length !== B[i].length) {
      throw new RangeError(`Row ${i} has mismatched column counts`);
    }

    // Allocate a fresh row so we never touch A or B
    const row = new Array(A[i].length);
    for (let j = 0; j < A[i].length; j++) {
      const a = A[i][j];
      const b = B[i][j];
      if (typeof a !== "number" || typeof b !== "number") {
        throw new TypeError(`Non-numeric value at [${i}][${j}]`);
      }
      row[j] = a + b;
    }
    result[i] = row;
  }

  return result;
}

const A = [[1, 2], [3, 4]];
const B = [[10, 20], [30, 40]];

const C = addMatrices(A, B);
console.log(C); // [[11, 22], [33, 44]]
console.log(A); // [[1, 2], [3, 4]]  (unchanged)
console.log(B); // [[10, 20], [30, 40]] (unchanged)
```

### Key takeaways

1. **Never alias matrices you intend to write into.** Create a new outer array and new inner arrays (`new Array(...)` or `.map(row => [...row])`).
2. **Validate dimensions early.** Matrix bugs are often silent `NaN` propagation; fail fast with clear errors.
3. **Validate element types** if your API is meant to be numeric; JavaScript’s loose typing makes `undefined + 5` legal but useless.
4. **Prefer immutable helpers** for small codebases: `const result = A.map((row, i) => row.map((v, j) => v + B[i][j]));` is concise, but still needs dimension/type checks in production code.

# Common Pitfalls in Matrix Operations in JavaScript

Below are the most common pitfalls, grouped logically, each with a “bad” example and a “good” fix. All examples use plain nested arrays (the most common representation), but the same ideas apply to typed arrays / flattened buffers.

---

## 1. Mutating the input matrix (aliasing)

**Pitfall:** Functions that modify their argument in place surprise callers and break referential transparency.

```js
// BAD: mutates input
function scaleBad(M, k) {
  for (let i = 0; i < M.length; i++)
    for (let j = 0; j < M[i].length; j++)
      M[i][j] *= k;
  return M;
}

const A = [[1,2],[3,4]];
const B = scaleBad(A, 2);
console.log(A); // [[2,4],[6,8]] — original destroyed
```

```js
// GOOD: pure function, deep copy
function scale(M, k) {
  return M.map(row => row.map(x => x * k));
}
const A = [[1,2],[3,4]];
const B = scale(A, 2);
console.log(A); // [[1,2],[3,4]] unchanged
console.log(B); // [[2,4],[6,8]]
```

---

## 2. Shallow copies of nested arrays

**Pitfall:** `slice()`, spread `...`, `Array.from` only copy the outer array; inner rows are still shared.

```js
// BAD
const A = [[1,2],[3,4]];
const B = A.map(row => row); // or [...A], or A.slice()
B[0][0] = 999;
console.log(A[0][0]); // 999 — aliasing bug
```

```js
// GOOD: deep copy of rectangular numeric matrix
const deepCopy = M => M.map(row => [...row]);

// Or for arbitrary nesting:
const deepCopyGeneric = M => JSON.parse(JSON.stringify(M));
// (works for plain numbers; breaks on NaN/Infinity/Date/functions)
```

---

## 3. Dimension mismatches not caught at runtime

**Pitfall:** JS has no static shape checking; malformed matrices silently produce `NaN`, `undefined`, or wrong results.

```js
// BAD: no validation
function add(A, B) {
  return A.map((row, i) => row.map((x, j) => x + B[i][j]));
}
const R = add([[1,2],[3,4]], [[1,2,3],[4,5,6]]); // no error thrown
console.log(R); // [NaN, NaN, ...] / undefined access
```

```js
// GOOD: validate shapes explicitly
function assertMatrix(M, name = 'M') {
  if (!Array.isArray(M) || M.length === 0) throw new Error(`${name} is not a non-empty array`);
  const cols = M[0].length;
  if (!Number.isInteger(cols) || cols <= 0) throw new Error(`${name} has invalid columns`);
  for (const row of M) {
    if (!Array.isArray(row) || row.length !== cols) throw new Error(`${name} is ragged`);
    if (!row.every(x => typeof x === 'number' && Number.isFinite(x)))
      throw new Error(`${name} contains non-finite/non-number`);
  }
  return { rows: M.length, cols };
}

function add(A, B) {
  const a = assertMatrix(A, 'A'), b = assertMatrix(B, 'B');
  if (a.rows !== b.rows || a.cols !== b.cols) throw new Error('shape mismatch');
  return A.map((row, i) => row.map((x, j) => x + B[i][j]));
}
```

---

## 4. Floating-point precision

**Pitfall:** `0.1 + 0.2 !== 0.3`; accumulation in sums/products drifts.

```js
// BAD: naive equality after operations
const dot = (a, b) => a.reduce((s, x, i) => s + x * b[i], 0);
console.log(dot([0.1, 0.2], [0.3, 0.4]) === 0.11); // false
```

```js
// GOOD: tolerance-based comparison
const EPS = 1e-9;
const approxEqual = (a, b) => Math.abs(a - b) < EPS;
console.log(approxEqual(dot([0.1, 0.2], [0.3, 0.4]), 0.11)); // true

// For accumulation, use compensated summation (Kahan) when summing many terms:
function kahanSum(xs) {
  let sum = 0, c = 0;
  for (const x of xs) {
    const y = x - c;
    const t = sum + y;
    c = (t - sum) - y;
    sum = t;
  }
  return sum;
}
```

---

## 5. Transpose bugs (ragged / non-square)

**Pitfall:** Transpose assumes rectangular shape; naive implementations break on jagged arrays or produce wrong dimensions.

```js
// BAD: assumes square
function transposeBad(M) {
  const R = M.map(row => [...row]);
  for (let i = 0; i < M.length; i++)
    for (let j = 0; j < M.length; j++)
      R[j][i] = M[i][j];
  return R; // wrong for non-square; also mutates if not copied fully
}
```

```js
// GOOD: derive dimensions from data
function transpose(M) {
  if (M.length === 0) return [];
  const rows = M.length, cols = M[0].length;
  const out = Array.from({ length: cols }, () => Array(rows));
  for (let i = 0; i < rows; i++)
    for (let j = 0; j < cols; j++)
      out[j][i] = M[i][j];
  return out;
}
console.log(transpose([[1,2,3],[4,5,6]]));
// [[1,4],[2,5],[3,6]]
```

---

## 6. Matrix multiplication order and dimension rules

**Pitfall:** `A * B` is not commutative; inner dimensions must match; people confuse `m×n` with `n×m`.

```js
// BAD: wrong loop order / dimension assumption
function mulBad(A, B) {
  const n = A.length;
  // assumes square and B same size
  const C = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++)
    for (let j = 0; j < n; j++)
      for (let k = 0; k < n; k++)
        C[i][j] += A[i][k] * B[k][j];
  return C;
}
```

```js
// GOOD: general m×n times n×p
function mul(A, B) {
  const m = A.length, n = A[0].length, p = B[0].length;
  if (B.length !== n) throw new Error('inner dimensions mismatch');
  const C = Array.from({ length: m }, () => Array(p).fill(0));
  for (let i = 0; i < m; i++)
    for (let k = 0; k < n; k++) {
      const aik = A[i][k];
      if (aik === 0) continue; // small optimization
      const Brow = B[k];
      const Crow = C[i];
      for (let j = 0; j < p; j++) Crow[j] += aik * Brow[j];
    }
  return C;
}
// cache-friendly: i-k-j loop order
```

---

## 7. Confusing 1D “flat” buffers with 2D matrices

**Pitfall:** Row-major vs column-major indexing; forgetting stride.

```js
// Flat row-major: index = i * cols + j
function getFlat(Mflat, rows, cols, i, j) {
  return Mflat[i * cols + j];
}
function setFlat(Mflat, cols, i, j, v) {
  Mflat[i * cols + j] = v;
}

// BAD: using rows as stride when data is row-major
const flat = [1,2,3,4,5,6]; // 2x3
console.log(flat[1 * 2 + 2]); // wrong stride (should be *3)
```

```js
// GOOD: keep metadata alongside buffer
class Matrix {
  constructor(rows, cols, data = null) {
    this.rows = rows; this.cols = cols;
    this.data = data ?? new Float64Array(rows * cols);
  }
  get(i, j) { return this.data[i * this.cols + j]; }
  set(i, j, v) { this.data[i * this.cols + j] = v; }
}
```

---

## 8. `Array.prototype.map` pitfalls with sparse/holes and `thisArg`

**Pitfall:** `map` skips holes; passing a callback that uses `this` incorrectly.

```js
// BAD: holes produce undefined, not 0
const M = new Array(2).fill().map(() => new Array(2)); // holes inside rows
console.log(M); // [ [ <2 empty items> ], [ <2 empty items> ] ]

// BAD: map with parseInt-like callback
[[1,2],[3,4]].map(parseInt); // [[NaN, NaN], ...]
```

```js
// GOOD: initialize explicitly
const zeros = (r, c) => Array.from({ length: r }, () => Array(c).fill(0));
```

---

## 9. In-place algorithms destroying data needed later

**Pitfall:** Gaussian elimination, LU, etc. overwrite input; callers expect original preserved.

```js
// BAD: mutates A and b
function solveBad(A, b) {
  const n = A.length;
  for (let k = 0; k < n; k++)
    for (let i = k + 1; i < n; i++) {
      const f = A[i][k] / A[k][k];
      for (let j = k; j < n; j++) A[i][j] -= f * A[k][j];
      b[i] -= f * b[k];
    }
  // back substitution...
  return b; // A and b inputs now corrupted
}
```

```js
// GOOD: clone first
function solve(A, b) {
  const M = A.map(row => [...row]);
  const rhs = [...b];
  const n = M.length;
  // ... operate on M, rhs ...
  return rhs;
}
```

---

## 10. Singular / near-singular matrices not handled

**Pitfall:** Division by (near-)zero pivot; no check for determinant or condition number.

```js
// BAD: naive inverse
function invBad(M) {
  const det = M[0][0]*M[1][1] - M[0][1]*M[1][0];
  return [[M[1][1]/det, -M[0][1]/det],
          [-M[1][0]/det, M[0][0]/det]];
}
console.log(invBad([[1,2],[2,4]])); // Infinity/NaN
```

```js
// GOOD: check determinant / use partial pivoting / SVD for real code
function inv2x2(M) {
  const det = M[0][0]*M[1][1] - M[0][1]*M[1][0];
  if (Math.abs(det) < 1e-12) throw new Error('matrix is singular or near-singular');
  const invDet = 1 / det;
  return [[ M[1][1]*invDet, -M[0][1]*invDet],
          [-M[1][0]*invDet,  M[0][0]*invDet]];
}
```

---

## 11. Performance: O(n³) with poor cache locality

**Pitfall:** Naive triple loop with column-major access pattern causes cache misses; creating many intermediate arrays.

```js
// BAD: j-i-k order (strided access into B's columns)
for (let i=0;i<m;i++)
  for (let j=0;j<p;j++)
    for (let k=0;k<n;k++)
      C[i][j] += A[i][k] * B[k][j]; // B[k][j] strided
```

```js
// GOOD: i-k-j order (sequential access)
for (let i = 0; i < m; i++) {
  const Ci = C[i], Ai = A[i];
  for (let k = 0; k < n; k++) {
    const aik = Ai[k];
    if (aik === 0) continue;
    const Bk = B[k];
    for (let j = 0; j < p; j++) Ci[j] += aik * Bk[j];
  }
}
// For large matrices, consider blocked/tiled multiplication or WebAssembly/SIMD.
```

---

## 12. Forgetting that matrices are not “values” for `===`

**Pitfall:** Comparing matrices with `===` compares references.

```js
const A = [[1,2],[3,4]];
const B = [[1,2],[3,4]];
console.log(A === B); // false
console.log(A == B);  // false
```

```js
const matEqual = (A, B) =>
  A.length === B.length &&
  A.every((row, i) => row.length === B[i].length &&
    row.every((x, j) => x === B[i][j]));
// or use tolerance version for floats
```

---

## 13. Empty / 1×1 / vector edge cases

**Pitfall:** Code assumes at least 2×2; empty arrays cause `M[0]` to be `undefined`.

```js
// BAD
function rows(M){ return M.length; }
function cols(M){ return M[0].length; } // throws if M empty
```

```js
// GOOD
function shape(M) {
  if (!Array.isArray(M) || M.length === 0) return [0, 0];
  return [M.length, Array.isArray(M[0]) ? M[0].length : 1];
}
```

---

## 14. Using `reduce` without initial value on empty rows

**Pitfall:** `row.reduce((a,b)=>a+b)` on an empty row throws or returns wrong type.

```js
// BAD
[].reduce((a,b)=>a+b); // TypeError: Reduce of empty array with no initial value
```

```js
// GOOD
const sum = row.reduce((a, b) => a + b, 0);
```

---

## 15. JSON serialization of special numbers

**Pitfall:** `JSON.stringify` turns `NaN`, `Infinity`, `-Infinity` into `null`, breaking round-trip.

```js
const M = [[NaN, Infinity], [-Infinity, 1/0]];
console.log(JSON.stringify(M)); // [[null,null],[null,null]]
```

Fix: store as strings or use a typed-array binary format; or validate finiteness before serializing.

---

## 16. Mixing up row-vector vs column-vector conventions

**Pitfall:** A vector is stored as `[[x,y,z]]` (1×3) vs `[[x],[y],[z]]` (3×1); multiplication orientation changes results.

```js
// If v is a row vector, v * M; if column, M * v.
// Be explicit:
const asColumn = v => v.map(x => [x]);
const asRow    = v => [v];

function matVec(M, vCol) { // M (m×n) * v (n×1) -> (m×1)
  return M.map(row => [row.reduce((s, x, j) => s + x * vCol[j][0], 0)]);
}
```

---

## Recommended: use a library for production

Hand-rolling all of this is error-prone. For real work, prefer:

- **mathjs** — general-purpose, big (but has matrix type)
- **ml-matrix** — lightweight, fast, well-tested
- **ndarray** / **numjs** — ndarray-style
- For heavy compute: **WebAssembly** (e.g., Eigen via wasm) or **GPU.js** / **TensorFlow.js**

```js
// ml-matrix example
import { Matrix } from 'ml-matrix';
const A = new Matrix([[1,2],[3,4]]);
const B = A.clone();          // deep copy guaranteed
const C = A.mmul(B);          // validated multiplication
const T = A.transpose();
```

---

## Quick checklist before shipping matrix code

1. Never mutate inputs; always return new matrices.
2. Deep-copy nested arrays (not `slice`/spread on outer only).
3. Validate shapes and finiteness at boundaries.
4. Use tolerance (`EPS`) for float comparisons.
5. Handle empty / 1×1 / ragged inputs gracefully.
6. Choose loop order for cache locality (`i-k-j`).
7. Preserve and check determinants/pivots for division.
8. Be explicit about row vs column vectors.
9. Avoid `JSON` for special floats.
10. Prefer a tested library for non-trivial math.

If you want, I can go deeper into any one of these (e.g., a full, robust matrix class with tests, or performance benchmarking of different multiplication orders).

## Exercise

Write a tiny, reusable matrix module in JavaScript that supports:

1. `createMatrix(rows, cols, value = 0)` – build a matrix filled with a value.
2. `add(A, B)` – element-wise addition (same dimensions).
3. `multiply(A, B)` – standard matrix multiplication (A is `m×n`, B is `n×p` → result `m×p`).
4. `transpose(A)` – swap rows and columns.

Then use it to compute:

- `A = [[1, 2, 3], [4, 5, 6]]` (2×3)
- `B = [[7, 8], [9, 10], [11, 12]]` (3×2)
- `C = A × B` (should be 2×2)
- `D = transpose(C)`

---

## Step-by-step solution

### 1. Represent a matrix
In JavaScript, a matrix is naturally an array of arrays (rows).  
Each row has the same length (number of columns).

```js
const A = [
  [1, 2, 3],
  [4, 5, 6]
];
// A has 2 rows, 3 columns → dimensions 2×3
```

### 2. Helper: dimensions
Before operating, validate that inputs have consistent shapes.

```js
function dims(M) {
  const rows = M.length;
  const cols = rows > 0 ? M[0].length : 0;
  // (Assume rectangular; production code would validate every row.)
  return { rows, cols };
}
```

### 3. `createMatrix`
Allocate a fresh matrix so callers don’t accidentally share references.

```js
function createMatrix(rows, cols, value = 0) {
  return Array.from({ length: rows }, () =>
    Array.from({ length: cols }, () => value)
  );
}
```

### 4. `add`
Both matrices must have identical dimensions. Add corresponding entries.

```js
function add(A, B) {
  const { rows: rA, cols: cA } = dims(A);
  const { rows: rB, cols: cB } = dims(B);
  if (rA !== rB || cA !== cB) {
    throw new Error(`Cannot add ${rA}×${cA} and ${rB}×${cB} matrices`);
  }
  const result = createMatrix(rA, cA);
  for (let i = 0; i < rA; i++) {
    for (let j = 0; j < cA; j++) {
      result[i][j] = A[i][j] + B[i][j];
    }
  }
  return result;
}
```

### 5. `multiply`
Standard rule: entry `(i, k)` of the result is the dot product of row `i` of `A` and column `k` of `B`.

```js
function multiply(A, B) {
  const { rows: m, cols: n } = dims(A);
  const { rows: n2, cols: p } = dims(B);
  if (n !== n2) {
    throw new Error(
      `Cannot multiply ${m}×${n} by ${n2}×${p}: inner dimensions differ`
    );
  }
  const result = createMatrix(m, p);
  for (let i = 0; i < m; i++) {
    for (let k = 0; k < p; k++) {
      let sum = 0;
      for (let j = 0; j < n; j++) {
        sum += A[i][j] * B[j][k];
      }
      result[i][k] = sum;
    }
  }
  return result;
}
```

### 6. `transpose`
Swap `M[i][j]` with `M[j][i]`. Result is `cols × rows`.

```js
function transpose(M) {
  const { rows: r, cols: c } = dims(M);
  const result = createMatrix(c, r);
  for (let i = 0; i < r; i++) {
    for (let j = 0; j < c; j++) {
      result[j][i] = M[i][j];
    }
  }
  return result;
}
```

### 7. Run the exercise

```js
const A = [[1, 2, 3], [4, 5, 6]];
const B = [[7, 8], [9, 10], [11, 12]];

const C = multiply(A, B);   // 2×2
const D = transpose(C);     // 2×2 (symmetric-ish here)

console.log("C = A × B:");
console.log(C);
// [
//   [ 1*7+2*9+3*11,  1*8+2*10+3*12 ] = [58, 64]
//   [ 4*7+5*9+6*11,  4*8+5*10+6*12 ] = [139, 154]
// ]

console.log("D = transpose(C):");
console.log(D);
// [
//   [58, 139],
//   [64, 154]
// ]
```

Expected output:

```
C = A × B:
[ [ 58, 64 ], [ 139, 154 ] ]
D = transpose(C):
[ [ 58, 139 ], [ 64, 154 ] ]
```

