## Final solution (complete module)

```js
// matrix.js
function dims(M) {
  const rows = M.length;
  const cols = rows > 0 ? M[0].length : 0;
  return { rows, cols };
}

function createMatrix(rows, cols, value = 0) {
  return Array.from({ length: rows }, () =>
    Array.from({ length: cols }, () => value)
  );
}

function add(A, B) {
  const { rows: rA, cols: cA } = dims(A);
  const { rows: rB, cols: cB } = dims(B);
  if (rA !== rB || cA !== cB) {
    throw new Error(`Cannot add ${rA}×${cA} and ${rB}×${cB} matrices`);
  }
  const result = createMatrix(rA, cA);
  for (let i = 0; i < rA; i++) {
    for (let j = 0; j < cA; j++) {
      result[i][j] = A[i][j] + B[i][j];
    }
  }
  return result;
}

function multiply(A, B) {
  const { rows: m, cols: n } = dims(A);
  const { rows: n2, cols: p } = dims(B);
  if (n !== n2) {
    throw new Error(`Cannot multiply ${m}×${n} by ${n2}×${p}`);
  }
  const result = createMatrix(m, p);
  for (let i = 0; i < m; i++) {
    for (let k = 0; k < p; k++) {
      let sum = 0;
      for (let j = 0; j < n; j++) {
        sum += A[i][j] * B[j][k];
      }
      result[i][k] = sum;
    }
  }
  return result;
}

function transpose(M) {
  const { rows: r, cols: c } = dims(M);
  const result = createMatrix(c, r);
  for (let i = 0; i < r; i++) {
    for (let j = 0; j < c; j++) {
      result[j][i] = M[i][j];
    }
  }
  return result;
}

// ---- Demo ----
const A = [[1, 2, 3], [4, 5, 6]];
const B = [[7, 8], [9, 10], [11, 12]];

const C = multiply(A, B);
const D = transpose(C);

console.log("C =", C);
console.log("D =", D);

// Export for reuse (Node/CommonJS)
module.exports = { createMatrix, add, multiply, transpose };
```

### Notes for real projects
- For performance-critical code, consider typed arrays (`Float64Array`) or libraries like `ml-matrix`.
- Always validate rectangular shape in production; the helper above assumes well-formed input.
- Matrix multiplication is `O(m·n·p)`; for large matrices, use optimized BLAS-backed libraries.

## Matrix Operations in JavaScript — Interview-Style Walkthrough

### 1. Representation
A matrix is just a 2D array: `data[row][col]`. I store dimensions separately (`rows`, `cols`) so I never recompute them, and I validate shapes on every binary op. I follow an **immutable** style — operations return *new* matrices — which prevents aliasing bugs.

### 2. Core operations & complexities
| Op | Complexity (n×n) | Notes |
|---|---|---|
| Add / Subtract | O(n²) | element-wise, shapes must match |
| Scalar mult | O(n²) | |
| Multiply | O(n³) | loop order `i-k-j` for cache friendliness |
| Transpose | O(n²) | |
| Determinant | O(n!) naive / O(n³) with LU | recursive cofactor expansion shown for clarity |
| Inverse | O(n³) | Gauss-Jordan on `[A | I]` |

### 3. Implementation

```js
class Matrix {
  constructor(rows, cols, fill = 0) {
    if (!Number.isInteger(rows) || !Number.isInteger(cols) || rows < 1 || cols < 1) {
      throw new Error('Dimensions must be positive integers');
    }
    this.rows = rows;
    this.cols = cols;
    // row-major storage
    this.data = Array.from({ length: rows }, () => Array(cols).fill(fill));
  }

  // --- factories ---
  static fromArray(arr) {
    if (!Array.isArray(arr) || !arr.length || !Array.isArray(arr[0])) {
      throw new Error('Expected non-empty 2D array');
    }
    const cols = arr[0].length;
    if (arr.some((r) => !Array.isArray(r) || r.length !== cols)) {
      throw new Error('Jagged array is not a valid matrix');
    }
    const m = new Matrix(arr.length, cols);
    m.data = arr.map((r) => [...r]); // defensive copy
    return m;
  }

  static identity(n) {
    const m = new Matrix(n, n);
    for (let i = 0; i < n; i++) m.data[i][i] = 1;
    return m;
  }

  // --- helpers ---
  _checkSameShape(other, op) {
    if (this.rows !== other.rows || this.cols !== other.cols) {
      throw new Error(`${op}: shape mismatch ${this.rows}x${this.cols} vs ${other.rows}x${other.cols}`);
    }
  }

  clone() {
    return Matrix.fromArray(this.data);
  }

  // --- arithmetic ---
  add(other) {
    this._checkSameShape(other, 'add');
    const out = new Matrix(this.rows, this.cols);
    for (let i = 0; i < this.rows; i++)
      for (let j = 0; j < this.cols; j++)
        out.data[i][j] = this.data[i][j] + other.data[i][j];
    return out;
  }

  subtract(other) {
    this._checkSameShape(other, 'subtract');
    const out = new Matrix(this.rows, this.cols);
    for (let i = 0; i < this.rows; i++)
      for (let j = 0; j < this.cols; j++)
        out.data[i][j] = this.data[i][j] - other.data[i][j];
    return out;
  }

  scale(k) {
    const out = new Matrix(this.rows, this.cols);
    for (let i = 0; i < this.rows; i++)
      for (let j = 0; j < this.cols; j++)
        out.data[i][j] = this.data[i][j] * k;
    return out;
  }

  // i-k-j ordering: better cache locality than i-j-k
  multiply(other) {
    if (this.cols !== other.rows) {
      throw new Error(`multiply: ${this.rows}x${this.cols} * ${other.rows}x${other.cols} invalid`);
    }
    const out = new Matrix(this.rows, other.cols);
    for (let i = 0; i < this.rows; i++) {
      for (let k = 0; k < this.cols; k++) {
        const a = this.data[i][k];
        if (a === 0) continue; // cheap skip
        for (let j = 0; j < other.cols; j++) {
          out.data[i][j] += a * other.data[k][j];
        }
      }
    }
    return out;
  }

  transpose() {
    const out = new Matrix(this.cols, this.rows);
    for (let i = 0; i < this.rows; i++)
      for (let j = 0; j < this.cols; j++)
        out.data[j][i] = this.data[i][j];
    return out;
  }

  // --- linear algebra ---
  determinant() {
    if (this.rows !== this.cols) throw new Error('determinant requires square matrix');
    const n = this.rows;
    if (n === 1) return this.data[0][0];
    if (n === 2) {
      return this.data[0][0] * this.data[1][1] - this.data[0][1] * this.data[1][0];
    }
    // cofactor expansion (O(n!) — fine for small n; use LU for large)
    let det = 0;
    for (let j = 0; j < n; j++) {
      const minor = this._minor(0, j);
      const sign = j % 2 === 0 ? 1 : -1;
      det += sign * this.data[0][j] * minor.determinant();
    }
    return det;
  }

  _minor(row, col) {
    const out = new Matrix(this.rows - 1, this.cols - 1);
    let r = 0;
    for (let i = 0; i < this.rows; i++) {
      if (i === row) continue;
      let c = 0;
      for (let j = 0; j < this.cols; j++) {
        if (j === col) continue;
        out.data[r][c++] = this.data[i][j];
      }
      r++;
    }
    return out;
  }

  // Gauss-Jordan elimination on [A | I]
  inverse() {
    if (this.rows !== this.cols) throw new Error('inverse requires square matrix');
    const n = this.rows;
    // build augmented matrix
    const aug = Array.from({ length: n }, (_, i) => [
      ...this.data[i],
      ...Array.from({ length: n }, (_, j) => (i === j ? 1 : 0)),
    ]);

    for (let col = 0; col < n; col++) {
      // partial pivoting: pick row with largest |value| in this column
      let pivot = col;
      for (let r = col + 1; r < n; r++) {
        if (Math.abs(aug[r][col]) > Math.abs(aug[pivot][col])) pivot = r;
      }
      if (Math.abs(aug[pivot][col]) < 1e-12) {
        throw new Error('Matrix is singular (no inverse)');
      }
      [aug[col], aug[pivot]] = [aug[pivot], aug[col]];

      // normalize pivot row
      const pv = aug[col][col];
      for (let j = 0; j < 2 * n; j++) aug[col][j] /= pv;

      // eliminate this column from all other rows
      for (let r = 0; r < n; r++) {
        if (r === col) continue;
        const factor = aug[r][col];
        for (let j = 0; j < 2 * n; j++) {
          aug[r][j] -= factor * aug[col][j];
        }
      }
    }

    const out = new Matrix(n, n);
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++) out.data[i][j] = aug[i][n + j];
    return out;
  }

  toString() {
    return this.data.map((r) => r.map((v) => v.toFixed(3)).join('\t')).join('\n');
  }
}

// ---- demo ----
const A = Matrix.fromArray([[1, 2], [3, 4]]);
const B = Matrix.fromArray([[5, 6], [7, 8]]);

console.log('A + B:\n' + A.add(B));
console.log('A * B:\n' + A.multiply(B));
console.log('A^T:\n' + A.transpose());
console.log('det(A):', A.determinant());          // -2
console.log('A^-1:\n' + A.inverse());
console.log('A * A^-1 ≈ I:\n' + A.multiply(A.inverse()));
```

### 4. Interview talking points
- **Why immutable?** Avoids subtle bugs where `A.add(B)` mutates `A`. Cost is O(n²) copies — acceptable; for huge matrices you'd add an in-place variant.
- **Pivoting in inverse** is essential for numerical stability; always partial-pivot.
- **Real-world JS**: for large workloads use typed arrays (`Float64Array`), SIMD/WebGPU, or libraries (mathjs, ndarray, ml-matrix). Sparse matrices need CSR/CSC formats, not dense arrays.
- **Determinant naive is O(n!)** — mention LU decomposition (O(n³)) as the production approach.

That gives you a clean, extensible core: validation, factories, arithmetic, and two non-trivial linear-algebra routines.

Below are the most important edge cases to handle when doing matrix work in JavaScript, grouped by category, with runnable code for each.

---

### 1. Representation & validation

Always validate inputs before operating. A “matrix” in JS is usually `number[][]`, but nothing enforces that.

```js
function isMatrix(m) {
  if (!Array.isArray(m) || m.length === 0) return false;
  const cols = m[0].length;
  return m.every(row =>
    Array.isArray(row) &&
    row.length === cols &&
    row.every(x => typeof x === 'number' && Number.isFinite(x))
  );
}

// Edge: empty outer array
console.log(isMatrix([]));        // false (define your own policy)
// Edge: row of different length
console.log(isMatrix([[1,2],[3]])); // false
// Edge: contains NaN/Infinity/string
console.log(isMatrix([[1,2],[3,NaN]])); // false
```

---

### 2. Empty and zero-dimension matrices

Decide semantics: is `[]` a 0×n matrix, `n×0`, or invalid? Many libraries treat `[]` as 0×0.

```js
function zeros(rows, cols) {
  if (!Number.isInteger(rows) || !Number.isInteger(cols) || rows < 0 || cols < 0) {
    throw new RangeError('dimensions must be non-negative integers');
  }
  return Array.from({ length: rows }, () => Array(cols).fill(0));
}

// Edge: 0x0, 0x3, 3x0
console.log(zeros(0, 0)); // []
console.log(zeros(0, 3)); // []
console.log(zeros(3, 0)); // [[], [], []]
```

**Multiplication with empties:**  
A (m×0) times B (0×n) yields an m×n zero matrix; (m×n) times (n×0) yields m×0.

```js
function multiply(A, B) {
  if (!isMatrix(A) || !isMatrix(B)) throw new TypeError('invalid matrix');
  const m = A.length, n = A[0].length;
  const p = B.length, q = B[0].length;
  if (n !== p) throw new Error(`dimension mismatch: ${m}x${n} * ${p}x${q}`);

  // Edge: handle zero dimensions explicitly
  if (m === 0 || q === 0) return zeros(m, q);

  const C = zeros(m, q);
  for (let i = 0; i < m; i++)
    for (let k = 0; k < n; k++) {
      if (A[i][k] === 0) continue; // tiny optimization, also avoids 0*NaN issues
      for (let j = 0; j < q; j++)
        C[i][j] += A[i][k] * B[k][j];
    }
  return C;
}
```

---

### 3. Jagged (non-rectangular) arrays

JavaScript arrays don’t enforce rectangularity. Always check.

```js
function assertRectangular(m, name = 'matrix') {
  if (!Array.isArray(m) || m.length === 0) throw new Error(`${name} is empty`);
  const cols = m[0].length;
  if (!m.every(r => Array.isArray(r) && r.length === cols)) {
    throw new Error(`${name} is not rectangular`);
  }
}
```

---

### 4. Type coercion & numeric validity

JS silently coerces: `'2' * 3 === 6`, `null + 1 === 1`, `undefined + 1 === NaN`. Matrices often arrive from JSON or user input.

```js
function toNumberMatrix(raw) {
  if (!Array.isArray(raw)) throw new TypeError('expected array');
  return raw.map(row => {
    if (!Array.isArray(row)) throw new TypeError('expected row array');
    return row.map(v => {
      const n = Number(v);
      if (!Number.isFinite(n)) throw new TypeError(`non-finite value: ${v}`);
      return n;
    });
  });
}

// Edge: strings, null, undefined
console.log(toNumberMatrix([['1', '2'], [null, undefined]]));
// throws on null/undefined -> Number(null)=0 would be dangerous
```

**NaN / Infinity propagation:**  
If you allow them, arithmetic spreads. Decide whether to reject or sanitize.

```js
function sanitize(m) {
  return m.map(row => row.map(x => (Number.isFinite(x) ? x : 0)));
}
```

---

### 5. Floating-point precision

Matrix multiplication and inversion accumulate error. Use tolerance for comparisons.

```js
const EPS = 1e-9;

function approxEqual(a, b, eps = EPS) {
  return Math.abs(a - b) <= eps * (1 + Math.abs(a) + Math.abs(b));
}

// Example: rotation matrix should be orthogonal
const theta = Math.PI / 3;
const R = [[Math.cos(theta), -Math.sin(theta)],
           [Math.sin(theta),  Math.cos(theta)]];
// R * R^T should be identity, but entries may be 1.0000000000000002
```

**Better:** use tolerance in equality checks and consider `decimal.js` or `big.js` for high precision.

---

### 6. Mutability & aliasing

Never mutate inputs unless documented. Aliasing (same matrix passed twice) is dangerous.

```js
function add(A, B) {
  // Edge: A and B may be the same reference
  const m = A.length, n = A[0].length;
  const C = Array.from({ length: m }, (_, i) =>
    Array.from({ length: n }, (_, j) => A[i][j] + B[i][j])
  );
  return C;
}

// Dangerous in-place version:
function addInPlace(A, B) {
  for (let i = 0; i < A.length; i++)
    for (let j = 0; j < A[0].length; j++)
      A[i][j] += B[i][j]; // corrupts if A === B
}
```

**Deep copy helper** (JSON fails on undefined/NaN/Infinity/Date/etc.):

```js
function cloneMatrix(m) {
  return m.map(row => row.slice());
}
```

---

### 7. Dimension compatibility for all operations

| Op | Requirement |
|----|-------------|
| Add/Sub | same m×n |
| Multiply | n(A) === m(B) |
| Transpose | always |
| Inverse | square & non-singular |

```js
function transpose(A) {
  assertRectangular(A);
  const m = A.length, n = A[0].length;
  // Edge: empty / single row / single col all handled
  return Array.from({ length: n }, (_, j) =>
    Array.from({ length: m }, (_, i) => A[i][j])
  );
}
```

---

### 8. Singular & non-invertible matrices

Determinant zero → division by zero → `Infinity`/`NaN`.

```js
function determinant2x2(M) {
  return M[0][0] * M[1][1] - M[0][1] * M[1][0];
}

function inverse2x2(M) {
  const det = determinant2x2(M);
  if (Math.abs(det) < EPS) {
    throw new Error('matrix is singular or near-singular');
  }
  const [[a,b],[c,d]] = M;
  return [
    [ d/det, -b/det],
    [-c/det,  a/det]
  ];
}

// Edge: identity-like singular
console.log(() => inverse2x2([[1,2],[2,4]])); // throws
```

**Condition number:** even non-singular matrices can be ill-conditioned; small input errors blow up. Consider checking `|det|` against a threshold relative to matrix scale.

---

### 9. Recursion depth & performance

Recursive determinant (Laplace expansion) is O(n!) and overflows the call stack for n ≳ 10–12.

```js
// BAD for large n
function detRecursive(M) {
  const n = M.length;
  if (n === 1) return M[0][0];
  if (n === 2) return determinant2x2(M);
  let d = 0;
  for (let j = 0; j < n; j++) {
    const minor = M.slice(1).map(row => row.filter((_, k) => k !== j));
    d += (j % 2 === 0 ? 1 : -1) * M[0][j] * detRecursive(minor);
  }
  return d;
}

// BETTER: LU decomposition (iterative, O(n^3))
function detLU(M) {
  const n = M.length;
  const A = cloneMatrix(M);
  let det = 1;
  for (let k = 0; k < n; k++) {
    // partial pivot
    let pivot = k;
    for (let i = k + 1; i < n; i++) {
      if (Math.abs(A[i][k]) > Math.abs(A[pivot][k])) pivot = i;
    }
    if (pivot !== k) { [A[k], A[pivot]] = [A[pivot], A[k]]; det = -det; }
    if (Math.abs(A[k][k]) < EPS) return 0; // singular
    det *= A[k][k];
    for (let i = k + 1; i < n; i++) {
      const factor = A[i][k] / A[k][k];
      for (let j = k; j < n; j++) A[i][j] -= factor * A[k][j];
    }
  }
  return det;
}
```

---

### 10. Sparse / missing entries

If you use objects or holes: `[[1,,3],[4,5]]`. `undefined` arithmetic → `NaN`.

```js
const sparse = [[1, , 3], [4, 5]];
// sparse[0][1] is undefined
console.log(sparse[0][0] + sparse[0][1]); // NaN

// Normalize holes to 0
function dense(m) {
  const cols = m[0]?.length ?? 0;
  return m.map(row =>
    Array.from({ length: cols }, (_, j) => (row[j] ?? 0))
  );
}
```

---

### 11. Integer safety

JS numbers are IEEE-754 doubles; safe integers only up to 2^53-1. Large matrix entries or accumulators can lose precision.

```js
console.log(Number.isSafeInteger(9007199254740992)); // false
// If you need exact big integers, use BigInt matrices (but then no Math.* functions)
```

---

### 12. Complex numbers

JS has no native complex type. Operations on complex matrices require a custom `{re, im}` representation or a library (e.g., `mathjs`).

```js
class Complex {
  constructor(re = 0, im = 0) { this.re = re; this.im = im; }
  add(o) { return new Complex(this.re + o.re, this.im + o.im); }
  mul(o) { return new Complex(this.re*o.re - this.im*o.im, this.re*o.im + this.im*o.re); }
}
// Edge: mixing real numbers and Complex objects in same matrix
```

---

### 13. Transpose aliasing bug

A common bug: transposing by swapping in place corrupts data when m ≠ n, and even when square it can double-swap.

```js
// WRONG (in-place, only works square and even then buggy)
function transposeInPlaceBad(M) {
  for (let i = 0; i < M.length; i++)
    for (let j = 0; j < i; j++)
      [M[i][j], M[j][i]] = [M[j][i], M[i][j]];
}

// CORRECT: always return new matrix (see transpose() above)
```

---

### 14. Determinant sign & row swaps

When implementing Gaussian elimination, track row swaps or the determinant sign will be wrong.

```js
function detWithPivoting(M) {
  const A = cloneMatrix(M);
  const n = A.length;
  let swaps = 0;
  for (let k = 0; k < n; k++) {
    let piv = k;
    for (let i = k+1; i < n; i++)
      if (Math.abs(A[i][k]) > Math.abs(A[piv][k])) piv = i;
    if (piv !== k) { [A[k], A[piv]] = [A[piv], A[k]]; swaps++; }
    if (Math.abs(A[k][k]) < EPS) return 0;
    for (let i = k+1; i < n; i++) {
      const f = A[i][k] / A[k][k];
      for (let j = k; j < n; j++) A[i][j] -= f * A[k][j];
    }
  }
  let d = 1;
  for (let i = 0; i < n; i++) d *= A[i][i];
  return (swaps % 2 === 0 ? 1 : -1) * d;
}
```

---

### 15. Memory / large matrices

Very large matrices (e.g., 10^4 × 10^4) can exceed memory or cause GC pauses. Consider:
- Typed arrays (`Float64Array`) for cache efficiency.
- Strassen or tiling for large multiplications.
- Web Workers / WASM for heavy computation.

```js
// Typed-array matrix (flat, row-major)
function matMulTyped(A, B, m, n, p) {
  const C = new Float64Array(m * p);
  for (let i = 0; i < m; i++)
    for (let k = 0; k < n; k++) {
      const a = A[i*n + k];
      if (a === 0) continue;
      for (let j = 0; j < p; j++)
        C[i*p + j] += a * B[k*p + j];
    }
  return C;
}
```

---

### Summary checklist

| Edge case | Guard |
|-----------|-------|
| Empty / 0-dim | explicit `zeros(m, q)` handling |
| Jagged arrays | `assertRectangular` |
| Non-numbers / NaN / Infinity | `Number.isFinite` validation |
| Type coercion from input | `Number()` + finite check |
| Float precision | tolerance `EPS` in comparisons |
| Mutation / aliasing | return new arrays; never mutate unless documented |
| Dimension mismatch | check before loops |
| Singular matrices | determinant threshold before divide |
| Deep copy | `row.slice()` (not JSON) |
| Recursion depth | iterative LU for determinant/inverse |
| Sparse holes | normalize `?? 0` |
| Large integers | `Number.isSafeInteger` or BigInt |
| Complex | custom type or library |
| Row swaps | track sign in pivoting |

