# JavaScript Micro-Optimizations — Complete Runnable Example

> **Caveat first:** Modern engines (V8, SpiderMonkey, JavaScriptCore) are extremely good at optimizing idiomatic code. Micro-optimizations often **do not** help, can **hurt** readability, and sometimes **hurt** performance (e.g., by de-optimizing). Always **measure** with a profiler before changing code. The example below is a benchmark harness so you can see real numbers on *your* engine.

## Runnable benchmark (Node.js)

Save as `bench.js` and run with `node bench.js`.

```js
// bench.js
// Run: node bench.js
// Node 18+ recommended (performance global available).

const { performance } = require('perf_hooks');

const N = 2_000_000;
const arr = Array.from({ length: 1000 }, (_, i) => i + 1);

function bench(name, fn, iterations = 200_000) {
  // Warm up (lets V8 compile & tier up).
  for (let i = 0; i < 2_000; i++) fn();
  // Force GC-ish stability by discarding warmup result.
  const start = performance.now();
  let acc = 0;
  for (let i = 0; i < iterations; i++) acc += fn() | 0;
  const ms = performance.now() - start;
  const ops = (iterations / (ms / 1000)).toFixed(0);
  console.log(`${name.padEnd(42)} ${ms.toFixed(2).padStart(8)} ms  (${ops} ops/s)  acc=${acc}`);
}

console.log('=== Loop variants ===');
bench('uncached .length', () => {
  let s = 0;
  for (let i = 0; i < arr.length; i++) s += arr[i];
  return s;
});
bench('cached length', () => {
  let s = 0;
  const n = arr.length;
  for (let i = 0; i < n; i++) s += arr[i];
  return s;
});
bench('reverse loop', () => {
  let s = 0;
  for (let i = arr.length - 1; i >= 0; i--) s += arr[i];
  return s;
});
bench('forEach', () => {
  let s = 0;
  arr.forEach((x) => (s += x));
  return s;
});
bench('for...of', () => {
  let s = 0;
  for (const x of arr) s += x;
  return s;
});

console.log('\n=== Function call / inlining ===');
function add(a, b) { return a + b; }
bench('function call per element', () => {
  let s = 0;
  const n = arr.length;
  for (let i = 0; i < n; i++) s = add(s, arr[i]);
  return s;
});
bench('inlined arithmetic', () => {
  let s = 0;
  const n = arr.length;
  for (let i = 0; i < n; i++) s = s + arr[i];
  return s;
});

console.log('\n=== Object shape stability ===');
function makeStable(a, b, c) {
  const o = { x: a };
  o.y = b;
  o.z = c;
  return o;
}
function makeUnstable(a, b, c) {
  const o = {};
  if (a) o.x = a;
  if (b) o.y = b;
  if (c) o.z = c;
  return o;
}
bench('stable shape (consistent props)', () => {
  const o = makeStable(1, 2, 3);
  return o.x + o.y + o.z;
});
bench('unstable shape (conditional props)', () => {
  const o = makeUnstable(1, 2, 3);
  return (o.x || 0) + (o.y || 0) + (o.z || 0);
});

console.log('\n=== delete vs undefined ===');
bench('property delete (deopts shape)', () => {
  const o = { a: 1, b: 2, c: 3 };
  delete o.b;
  return o.a + (o.c || 0);
});
bench('set to undefined (keeps shape)', () => {
  const o = { a: 1, b: 2, c: 3 };
  o.b = undefined;
  return o.a + (o.c || 0);
});

console.log('\n=== Local caching of globals ===');
bench('Math.sqrt each time', () => {
  let s = 0;
  const n = arr.length;
  for (let i = 0; i < n; i++) s += Math.sqrt(arr[i]);
  return s;
});
const _sqrt = Math.sqrt;
bench('cached sqrt reference', () => {
  let s = 0;
  const n = arr.length;
  for (let i = 0; i < n; i++) s += _sqrt(arr[i]);
  return s;
});

console.log('\n=== Bitwise vs Math.floor (32-bit range only) ===');
const floats = Array.from({ length: 1000 }, (_, i) => i * 1.7 + 0.3);
bench('Math.floor', () => {
  let s = 0;
  const n = floats.length;
  for (let i = 0; i < n; i++) s += Math.floor(floats[i]);
  return s;
});
bench('bitwise | 0', () => {
  let s = 0;
  const n = floats.length;
  for (let i = 0; i < n; i++) s += (floats[i] | 0);
  return s;
});

console.log('\n=== String building ===');
const parts = Array.from({ length: 100 }, (_, i) => `p${i}`);
bench('+= in loop', () => {
  let s = '';
  const n = parts.length;
  for (let i = 0; i < n; i++) s += parts[i];
  return s.length;
});
bench('array join', () => {
  const out = [];
  const n = parts.length;
  for (let i = 0; i < n; i++) out.push(parts[i]);
  return out.join('').length;
});

console.log('\n=== Typed arrays for numeric work ===');
const TYPED_N = 100_000;
const typed = new Float64Array(TYPED_N);
for (let i = 0; i < TYPED_N; i++) typed[i] = i * 1.5;
const plain = Array.from(typed);
bench('plain Array sum', () => {
  let s = 0;
  const n = plain.length;
  for (let i = 0; i < n; i++) s += plain[i];
  return s;
}, 200);
bench('Float64Array sum', () => {
  let s = 0;
  const n = typed.length;
  for (let i = 0; i < n; i++) s += typed[i];
  return s;
}, 200);

console.log('\n=== Avoiding `arguments` ===');
function withArguments() {
  let s = 0;
  for (let i = 0; i < arguments.length; i++) s += arguments[i];
  return s;
}
function withRest(...args) {
  let s = 0;
  const n = args.length;
  for (let i = 0; i < n; i++) s += args[i];
  return s;
}
bench('arguments object', () => withArguments(1, 2, 3, 4, 5, 6, 7, 8), 50_000);
bench('rest params', () => withRest(1, 2, 3, 4, 5, 6, 7, 8), 50_000);

console.log('\n=== Allocation avoidance (object pooling) ===');
function allocPerIter() {
  const o = { x: 0, y: 0 };
  o.x = 1; o.y = 2;
  return o.x + o.y;
}
const pooled = { x: 0, y: 0 };
function reusePooled() {
  pooled.x = 1; pooled.y = 2;
  return pooled.x + pooled.y;
}
bench('allocate each iteration', allocPerIter, 500_000);
bench('reuse pooled object', reusePooled, 500_000);
```

## What each optimization does (and its caveats)

| Technique | Why it can help | Caveat |
|---|---|---|
| **Cache `.length`** | Avoids repeated property lookup in older engines | V8 hoists it automatically in simple loops; difference often ~0 |
| **Reverse `for` loop** | Some engines optimize `i >= 0` slightly | Rarely measurable; hurts readability |
| **`for` over `forEach`/`for...of`** | No callback/closure allocation, no iterator protocol | `forEach` is often inlined by V8; measure first |
| **Stable object shapes** | Keeps objects on same hidden class → monomorphic inline caches | The biggest real win in V8-heavy code |
| **Avoid `delete`** | `delete` forces transition to dictionary mode (slow) | Set to `undefined` (or use `Map`) instead |
| **Cache globals (`Math`, `document`)** | Shorter scope chain lookup | Modern engines cache globals well; helps in tight loops |
| **Bitwise `| 0`** | Faster than `Math.floor` for 32-bit ints | Only valid for 32-bit range; wrong for large/float values |
| **Typed arrays** | Contiguous memory, no boxing, SIMD-friendly | Fixed type; conversion cost if mixing with plain arrays |
| **Avoid `arguments`** | `arguments` disables some optimizations, allocates | Rest params are the modern, optimizable choice |
| **Object pooling** | Reduces GC pressure in hot paths | Adds statefulness; only worth it in genuinely hot code |
| **String `+=` vs `join`** | V8 uses ropes; `+=` is usually fine now | `join` can win for huge concatenations |

## Browser-specific micro-optimizations (not in the Node script)

```js
// 1. Batch DOM reads/writes to avoid layout thrashing.
const els = document.querySelectorAll('.item');
const widths = [...els].map((e) => e.offsetWidth); // read phase
els.forEach((e, i) => (e.style.width = widths[i] + 10 + 'px')); // write phase

// 2. rAF for visual updates; passive listeners for scroll/touch.
window.addEventListener('scroll', onScroll, { passive: true });
requestAnimationFrame(() => applyUpdates());

// 3. Avoid forced synchronous layout: don't interleave reads/writes.

// 4. Web Workers for CPU-heavy work; transfer (not copy) large buffers.
worker.postMessage(buffer, [buffer]); // transfer ownership

// 5. Debounce/throttle high-frequency events.
function throttle(fn, ms) {
  let last = 0, timer;
  return (...args) => {
    const now = performance.now();
    if (now - last >= ms) { last = now; fn(...args); }
    else { clearTimeout(timer); timer = setTimeout(() => { last = now; fn(...args); }, ms - (now - last)); }
  };
}
```

## Decision checklist

1. **Profile first** (Chrome DevTools Performance, Node `--prof`, `0x`).
2. Optimize the **hottest** function, not the prettiest.
3. Keep changes **measurable** and **reversible**.
4. Prefer algorithmic wins (e.g., `O(n²)` → `O(n)`) over micro-wins.
5. Don't sacrifice correctness (bitwise floor, integer overflow) for speed.

Run the script, compare your engine's numbers, and only keep the optimizations that show a real, repeated win.

## Micro-optimizations in JavaScript

**Idea**  
Micro-optimizations are tiny, local code changes that reduce per-operation overhead so a *hot path* (tight loop, parser, animation frame, game tick) runs faster. They usually target:

- fewer property lookups / scope-chain walks  
- fewer allocations (less GC pressure)  
- more predictable types/shapes (so engines like V8 can keep optimized machine code)  
- cheaper numeric operations  

They are **not** a substitute for algorithmic improvements; modern engines already optimize a lot. Measure with a profiler before changing readable code.

---

### 1. Cache values you read repeatedly

**Bad (re-evaluates `arr.length` and object lookup every iteration):**

```js
for (let i = 0; i < data.items.length; i++) {
  process(data.items[i]);
}
```

**Better:**

```js
const items = data.items;
for (let i = 0, n = items.length; i < n; i++) {
  process(items[i]);
}
```

---

### 2. Keep functions monomorphic (one shape / type)

Engines optimize a function for the *types* it actually receives. Changing types can cause deoptimization.

```js
// Good: always numbers
function add(a, b) {
  return a + b;
}

// Risky: sometimes string, sometimes number
function concatOrAdd(a, b) {
  return a + b; // type instability
}
```

---

### 3. Avoid `delete` on hot objects (hidden-class churn)

`delete` can force an object into dictionary mode / new hidden class.

```js
// Avoid in hot code
delete obj.temp;

// Prefer
obj.temp = undefined;   // keeps shape
// or split into two objects if lifecycle differs
```

---

### 4. Reuse temporaries to reduce GC (carefully)

```js
const tmp = { x: 0, y: 0 };

function normalize(v) {
  const len = Math.hypot(v.x, v.y);
  tmp.x = v.x / len;
  tmp.y = v.y / len;
  return tmp; // caller must not retain across calls
}
```

Trade-off: mutation bugs are easy; only do this in tightly controlled internals.

---

### 5. Use typed arrays for large numeric data

```js
// Array of numbers: boxed, slower, more memory
const a = new Array(1_000_000);

// Typed: contiguous, cache-friendly, SIMD-friendly
const b = new Float64Array(1_000_000);
for (let i = 0; i < b.length; i++) b[i] = i * 0.5;
```

---

### 6. Prefer simple loops where it matters

Engines optimize `for`/`while` well; callback-based methods add call overhead.

```js
// Fine for normal code
arr.forEach(x => work(x));

// Hot loop: explicit for is often faster and avoids callback overhead
for (let i = 0, n = arr.length; i < n; i++) {
  work(arr[i]);
}
```

---

### 7. Integer-friendly bitwise tricks (use sparingly)

```js
// Truncate to 32-bit signed int (fast, but changes semantics for large values)
const i = x | 0;

// Double bitwise NOT (also truncates)
const j = ~~x;
```

Only use when values are safely within 32-bit range and you truly need integer math.

---

### 8. Precompute constants / inline small helpers

```js
// Instead of recomputing
function area(r) {
  return Math.PI * r * r; // fine
}

// Hot path: hoist if called millions of times? Usually not needed; measure.
const TWO_PI = 2 * Math.PI;
```

---

### 9. Avoid try/catch around the hottest statements (engine-specific)

Some engines deoptimize functions containing `try/catch` in certain older versions; modern V8 is better, but still avoid wrapping inner loops:

```js
// Better: validate once, then tight loop
if (!isValid(data)) throw new Error("bad");
for (let i = 0; i < n; i++) hotWork(data[i]);
```

---

### 10. DOM / layout: batch reads and writes

Micro-optimization is often about *not touching the DOM* inside loops.

```js
// Bad: forces layout each iteration
for (const el of els) {
  el.style.width = el.offsetWidth + 10 + "px"; // read + write
}

// Better: read all, then write all
const widths = els.map(el => el.offsetWidth);
els.forEach((el, i) => { el.style.width = widths[i] + 10 + "px"; });
```

---

## When to use micro-optimizations

**Good use cases**
- Canvas/WebGL/game loops
- Large JSON/CSV parsing
- Audio processing, physics
- Sorting/comparing millions of items
- Mobile/low-end device constraints

**Avoid when**
- Code is not profiled as hot
- Readability matters more than 2–5% gains
- Engines already optimize the pattern (e.g., `const`, template literals)

---

## How to verify

```js
const t0 = performance.now();
for (let i = 0; i < 1_000_000; i++) work();
const t1 = performance.now();
console.log("ms:", t1 - t0);
```

Use Chrome DevTools Performance, `node --prof`, or benchmarks (`benchmark.js`). If the gain is within noise, revert and keep clean code.

## Mistaken version

```js
// "Optimized" removal of negative numbers
function removeNegatives(arr) {
  const len = arr.length; // cached for "speed"
  for (let i = 0; i < len; i++) {
    if (arr[i] < 0) {
      arr.splice(i, 1); // removes current element, shifts the rest left
    }
  }
  return arr;
}

removeNegatives([1, -2, 3, -4, 5]);
// Expected: [1, 3, 5]
// Actual:   [1, 3, -4, 5]  (or similar, depending on inputs)
```

## Corrected version

```js
// Option A: iterate backwards so splicing doesn't affect unprocessed indices
function removeNegatives(arr) {
  for (let i = arr.length - 1; i >= 0; i--) {
    if (arr[i] < 0) arr.splice(i, 1);
  }
  return arr;
}

// Option B: avoid mutation entirely (usually clearer and less bug-prone)
function removeNegatives(arr) {
  return arr.filter((x) => x >= 0);
}
```

## What went wrong and why

1. **The micro-optimization created a stale bound.**  
   Caching `arr.length` assumes the array’s size is constant during the loop. But `splice` shrinks the array, so `len` becomes larger than the new length. The loop then reads `undefined` slots or skips elements that slid into already-visited indices.

2. **Skipped elements after removal.**  
   Even if the length were re-evaluated each iteration, removing element `i` makes element `i+1` slide into position `i`. Incrementing `i` afterward skips that newly shifted element. That is why `-4` survives in the example.

3. **The “optimization” was not worth it.**  
   Modern JavaScript engines (V8, SpiderMonkey, JavaScriptCore) already optimize property access such as `arr.length` in hot loops. The cached version saves at most a tiny, usually immeasurable amount, while introducing a correctness bug. Readability and correctness should come first; measure before optimizing.

### Takeaway
Micro-optimizations that change loop invariants (cached lengths, manually unrolled loops, bitwise truncation hacks, etc.) are a common source of subtle bugs. Prefer straightforward code (`filter`, `for...of`, simple `for` loops), and only optimize after profiling proves a bottleneck.

# Common Pitfalls in JavaScript Micro-Optimizations

Micro-optimizations in JS are notoriously treacherous: engines (V8, SpiderMonkey, JavaScriptCore) optimize dynamically, so “obvious” speedups are often neutral or slower, and they frequently cost readability and maintainability. Below are the most common traps, with code.

---

## 1. Trusting a single benchmark (no warmup, no variance control)

**Pitfall:** Measuring cold code, not accounting for JIT tiers, GC pauses, or dead-code elimination.

```js
// ❌ Bad benchmark
function bench(label, fn) {
  const t0 = performance.now();
  fn();
  console.log(label, performance.now() - t0);
}

bench('A', () => { for (let i=0;i<1e7;i++) {} });
bench('B', () => { let i=0; while(i<1e7) i++; });
```

**Why it’s wrong:** First run is interpreted; later runs are optimized. Also, empty loops may be eliminated entirely.

```js
// ✅ Better: warm up, repeat, median, prevent DCE
function bench(fn) {
  for (let i=0;i<5;i++) fn(); // warmup
  const times = [];
  for (let r=0;r<20;r++) {
    const t0 = performance.now();
    fn();
    times.push(performance.now()-t0);
  }
  times.sort((a,b)=>a-b);
  return times[Math.floor(times.length/2)];
}

// Force use of result so it can't be deleted
function work(n) {
  let s=0;
  for (let i=0;i<n;i++) s += i*i;
  return s;
}
console.log(bench(()=>work(1e6)));
```

---

## 2. Assuming `for` is always faster than `forEach`/`map`

**Pitfall:** Manual loops can be slower if they fight the engine’s inlining/vectorization, and they’re less readable.

```js
// ❌ Often not faster, sometimes slower
const out = [];
for (let i=0;i<arr.length;i++) out.push(arr[i]*2);

// ✅ Usually comparable or better; JIT can inline callbacks
const out2 = arr.map(x => x*2);
```

**Reality:** For simple transforms, `map`/`forEach` are often as fast (or faster) because the engine specializes them. Measure in *your* engine/version.

---

## 3. Bitwise tricks instead of `Math` / logical ops

**Pitfall:** `~~x`, `x|0`, `x>>0` look clever but can be slower or wrong for large numbers.

```js
// ❌ Truncation via bitwise (fails > 2^31, can deopt)
const n = ~~(str);          // also slower in some engines
const idx = i | 0;

// ✅ Clear and fast
const n2 = Math.trunc(Number(str));
const idx2 = i; // already integer if you maintain invariants
```

**Also:** `x >>> 0` for unsigned is fine, but don’t sprinkle bitwise ops everywhere—engines optimize arithmetic well.

---

## 4. Hidden-class (shape) deoptimizations

**Pitfall:** Adding/removing properties dynamically, or mixing types, breaks inline caches.

```js
// ❌ Shape churn: each object has different hidden class
function make(x) {
  const o = {};
  if (x) o.a = 1;
  o.b = 2;
  return o;
}

// ✅ Stable shape: initialize all properties in same order
function make2(x) {
  const o = { a: x ? 1 : undefined, b: 2 };
  return o;
}
```

**Also avoid:** `delete obj.prop` (shape transition to “dictionary mode”). Set to `undefined` instead if shape must stay.

---

## 5. Polymorphic call sites

**Pitfall:** Calling the same function with different argument types/arity causes megamorphic ICs.

```js
// ❌ One function, many shapes
function area(s) { return s.w * s.h; }
area({w:1,h:2}); area({w:1,h:2,r:3}); area({width:1,height:2});

// ✅ Monomorphic: consistent shapes
function area2(r) { return r.w * r.h; }
```

---

## 6. Allocating in hot loops (GC pressure)

**Pitfall:** Creating objects/arrays/closures inside tight loops.

```js
// ❌ Allocation storm
for (let i=0;i<N;i++) {
  const tmp = { x: i, y: i*2 };
  process(tmp);
}

// ✅ Reuse / primitive locals
let x, y;
for (let i=0;i<N;i++) {
  x = i; y = i*2;
  processXY(x,y);
}
```

**Note:** Sometimes allocation is unavoidable; then tune *frequency*, not micro-syntax.

---

## 7. Closures capturing loop variables

**Pitfall:** Classic `var` + closure, or allocating function per iteration.

```js
// ❌ All callbacks see last i (with var) + function alloc per iter
const fns = [];
for (var i=0;i<5;i++) fns.push(() => i);

// ✅ let + factory outside, or map
const fns2 = Array.from({length:5}, (_,i) => () => i);
```

---

## 8. String building with `+` in loops vs `join`

**Pitfall:** Assuming `+=` is always bad; engines optimize small concatenations well. But huge loops still favor arrays.

```js
// ❌ Quadratic in some engines for very large
let s = '';
for (let i=0;i<1e5;i++) s += i;

// ✅ Array join for huge
const parts = [];
for (let i=0;i<1e5;i++) parts.push(i);
const s2 = parts.join('');
```

**Modern note:** V8 has “cons strings” and flattening; `+=` is often fine. Measure.

---

## 9. `arguments` object and rest params

**Pitfall:** Using `arguments` can deopt or prevent inlining in older engines; modern engines handle rest params better.

```js
// ❌ arguments (legacy deopt risk, no array methods)
function sum() {
  let s=0;
  for (let i=0;i<arguments.length;i++) s += arguments[i];
  return s;
}

// ✅ Rest params
function sum2(...args) {
  let s=0;
  for (const v of args) s += v;
  return s;
}
```

---

## 10. `delete` on objects / arrays

**Pitfall:** `delete` makes objects “dictionary mode” and arrays “holey.”

```js
// ❌ Holey array + dictionary object
const a = [1,2,3]; delete a[1];
const o = {x:1}; delete o.x;

// ✅ Set undefined / splice
a[1] = undefined;
o.x = undefined;
// or for arrays: a.splice(1,1) if removal needed
```

**Holey arrays** lose fast paths (PACKED → HOLEY transitions).

---

## 11. Sparse / holey arrays

**Pitfall:** Creating arrays with holes or non-contiguous indices.

```js
// ❌ Holey
const a = [];
a[1000] = 1; // holey + dictionary-ish

// ✅ Dense
const a2 = new Array(1001).fill(0);
a2[1000] = 1;
```

---

## 12. `try/catch` in hot code (historical + minor)

**Pitfall:** Older V8 couldn’t optimize functions containing try/catch. Modern TurboFan can, but still avoid in *innermost* hot loops if profiling shows deopt.

```js
// ❌ (legacy) entire function deoptimized
function hot(arr) {
  try {
    for (let i=0;i<arr.length;i++) work(arr[i]);
  } catch(e) {}
}

// ✅ isolate try/catch
function hot2(arr) {
  for (let i=0;i<arr.length;i++) {
    try { work(arr[i]); }
    catch(e) { handle(e); }
  }
}
```

---

## 13. `eval`, `with`, dynamic `Function` in hot paths

**Pitfall:** These force scope analysis to be conservative and block inlining.

```js
// ❌
function hot(x) {
  eval('var y = x*2');
  return y;
}

// ✅ no eval; static scope
function hot2(x) { return x*2; }
```

---

## 14. Property access: dot vs bracket vs caching

**Pitfall:** Repeated deep property access in loops; not caching base.

```js
// ❌ repeated lookup
for (let i=0;i<arr.length;i++) {
  total += arr[i].user.profile.score;
}

// ✅ cache
const len = arr.length;
for (let i=0;i<len;i++) {
  const u = arr[i].user;
  total += u.profile.score;
}
```

**Also:** `obj['prop']` vs `obj.prop`—engines treat them similarly for literal keys; computed keys can be slower if not stable.

---

## 15. `parseInt` without radix / `Number()` confusion

**Pitfall:** `parseInt('08')` legacy octal; `Number()` vs `+` vs `parseFloat`.

```js
// ❌
const n = parseInt(str); // radix default 10 only if str doesn't start 0x; '08' -> 0 in old
// ✅
const n2 = parseInt(str, 10);
const n3 = Number(str); // faster for simple numeric strings
```

---

## 16. Truthiness checks vs strict comparisons

**Pitfall:** `if (x)` vs `if (x !== undefined)` can change behavior and occasionally performance (branch prediction).

```js
// ❌ truthiness may hide 0/'' and is less predictable
if (val) process(val);

// ✅ explicit when semantics matter
if (val !== null && val !== undefined) process(val);
```

**Perf note:** Branch prediction favors consistent patterns; correctness first.

---

## 17. Manual loop unrolling / Duff’s device

**Pitfall:** Hand-unrolling rarely beats JIT unrolling and hurts readability.

```js
// ❌
let i=0, n=arr.length;
for (; i+3<n; i+=4) { /* 4x */ }
for (; i<n; i++) { /* rest */ }

// ✅ simple loop; let engine unroll
for (let i=0;i<arr.length;i++) work(arr[i]);
```

---

## 18. Forgetting that engines remove dead code

**Pitfall:** Benchmarking code whose result is unused gets eliminated.

```js
// ❌ result unused -> whole loop may be deleted
function bench() {
  for (let i=0;i<1e7;i++) Math.sqrt(i);
}

// ✅ consume result
function bench2() {
  let s=0;
  for (let i=0;i<1e7;i++) s += Math.sqrt(i);
  return s;
}
```

---

## 19. Object pooling misuse

**Pitfall:** Pooling objects to “avoid GC” can keep memory high and hurt cache; modern GC is fast for short-lived objects.

```js
// ❌ pool everything
const pool = [];
function get() { return pool.pop() || {x:0,y:0}; }
function release(o){ pool.push(o); }

// ✅ allocate normally; profile GC first
function work() { return {x:0,y:0}; }
```

**Rule:** Only pool when profiling proves GC is the bottleneck and objects are large/long-lived.

---

## 20. Micro-optimizing the wrong bottleneck

**Pitfall:** Shaving nanoseconds in CPU while I/O, layout, or algorithm dominates.

```js
// ❌ optimizing inner loop of O(n^2) sort
for (...) for (...) swap(...); // should use built-in sort

// ✅ fix algorithm
arr.sort((a,b)=>a-b);
```

---

## Practical checklist

1. **Profile first** (Chrome Performance, `--prof`, `0x`, clinic.js).
2. **Measure with warmup + repetitions + median**; prevent DCE.
3. **Check deopts** (`--trace-deopt`, `--trace-opt`).
4. **Keep shapes stable**; avoid `delete`; avoid holes.
5. **Prefer clarity** unless profiling shows a hot path.
6. **Test across engines** (V8, SpiderMonkey, JSC) if library code.
7. **Don’t optimize cold code.**

---

### Minimal “safe” optimization template

```js
// Hot path: stable shapes, no alloc, cached locals, simple loop
function sumSquares(arr) {
  let s = 0;
  const n = arr.length;
  for (let i = 0; i < n; i++) {
    const v = arr[i];
    s += v * v;
  }
  return s;
}
```

If you want, I can tailor this to a specific engine (V8 flags, Node profiling) or to a concrete snippet you’re optimizing.

## Exercise

Optimize this event-analysis function without changing its output. Focus on small, measurable loop-level changes.

```js
function analyzeEvents(events) {
  const byTag = {};
  const cleanEvents = [];
  let maxDuration = 0;

  for (let i = 0; i < events.length; i++) {
    const e = events[i];
    const tag = (e.tag || "unknown").trim().toLowerCase();

    cleanEvents.push({ ...e, tag });

    if (!byTag[tag]) {
      byTag[tag] = { count: 0, totalDuration: 0 };
    }

    byTag[tag].count += 1;
    byTag[tag].totalDuration += e.duration || 0;

    if (e.duration > maxDuration) {
      maxDuration = e.duration;
    }
  }

  return {
    byTag,
    cleanEvents,
    total: events.length,
    maxDuration,
  };
}
```

Assume each event has at least `id`, `tag`, and `duration`.

## Step-by-step optimization

### 1. Cache `.length`
`events.length` is evaluated every iteration. Hoist it once.

```js
const n = events.length;
for (let i = 0; i < n; i++) { ... }
```

### 2. Cache repeated property reads
`e.duration` is read multiple times. Store it in a local variable. Local variables are cheaper to access than repeated property lookups.

```js
const duration = e.duration || 0;
```

Also cache the bucket after creating it, so `byTag[tag]` is not looked up three times per iteration.

```js
let bucket = byTag[tag];
if (!bucket) {
  bucket = byTag[tag] = { count: 0, totalDuration: 0 };
}
bucket.count += 1;
bucket.totalDuration += duration;
```

### 3. Avoid repeated tag fallback work
Only convert to string when needed, and compute the fallback once.

```js
const rawTag = e.tag;
const tag = rawTag == null
  ? "unknown"
  : String(rawTag).trim().toLowerCase();
```

### 4. Stabilize array growth
`push` is fast, but preallocating can reduce reallocations for large arrays. Also assigning by index avoids dynamic growth checks in some engines.

```js
const cleanEvents = new Array(n);
...
cleanEvents[i] = { id: e.id, tag, duration: e.duration };
```

This assumes a known schema. If events can have arbitrary extra fields, keep `{ ...e, tag }` instead.

### 5. Keep `maxDuration` based on the cached value
Use the already-cached `duration`, not another property read.

```js
if (duration > maxDuration) maxDuration = duration;
```

## Final solution

```js
function analyzeEvents(events) {
  const n = events.length;
  const byTag = {};
  const cleanEvents = new Array(n);
  let maxDuration = 0;

  for (let i = 0; i < n; i++) {
    const e = events[i];
    const duration = e.duration || 0;

    const rawTag = e.tag;
    const tag = rawTag == null
      ? "unknown"
      : String(rawTag).trim().toLowerCase();

    // Known-schema clone; use { ...e, tag } if arbitrary fields must be preserved.
    cleanEvents[i] = {
      id: e.id,
      tag,
      duration: e.duration,
    };

    let bucket = byTag[tag];
    if (bucket === undefined) {
      bucket = byTag[tag] = { count: 0, totalDuration: 0 };
    }

    bucket.count += 1;
    bucket.totalDuration += duration;

    if (duration > maxDuration) {
      maxDuration = duration;
    }
  }

  return {
    byTag,
    cleanEvents,
    total: n,
    maxDuration,
  };
}
```

## Notes

- These are micro-optimizations: in many apps, the difference is small. Measure with a realistic dataset before committing to less readable code.
- Algorithmic wins usually beat micro-optimizations. For example, if you do not actually need `cleanEvents`, remove it entirely.
- Avoid mutating the original `events` objects; the final version still creates new objects for `cleanEvents`.

## Micro-optimizations in JavaScript (interview-style)

**What they are:** Tiny, low-level changes that reduce interpreter/JIT overhead in *hot paths* (tight loops, large arrays, per-frame game logic). They trade readability for speed, so they belong only after profiling.

**Common ones**

1. **Cache property lookups / length**  
   `arr.length` is a property access; hoist it: `const n = arr.length;`
2. **Local variables over object properties**  
   Reading `this.x` repeatedly is slower than `const x = this.x;`.
3. **Avoid repeated function calls in loops**  
   Inline small helpers or store the function reference locally.
4. **Loop shape**  
   Classic `for` with cached bound is usually fastest; `forEach`/`for...of` add callback/iterator overhead.
5. **Integer hints (careful)**  
   `| 0` can force 32-bit ints in some engines, but can hurt if values aren’t ints.
6. **String building**  
   Array `push` + `join('')` often beats `+=` for many chunks; for few chunks `+=` is fine.
7. **Typed arrays**  
   `Float64Array`/`Int32Array` avoid boxing and enable SIMD-friendly layouts.

**Caveats:** Modern engines (V8) optimize many patterns automatically; micro-opts can become no-ops or even pessimize. Always measure with `performance.now()` and real data.

---

### Core implementation: optimized sum + benchmark

```js
'use strict';

/**
 * Micro-optimized numeric sum.
 * - Caches array length (avoids repeated property lookup).
 * - Uses a local accumulator (avoids global/scope churn).
 * - Classic for-loop (minimal iterator overhead).
 *
 * @param {number[]} arr
 * @returns {number}
 */
function fastSum(arr) {
  let total = 0;
  const n = arr.length; // hoist bound
  for (let i = 0; i < n; i++) {
    total += arr[i];
  }
  return total;
}

/**
 * Naive version for comparison (baseline).
 */
function naiveSum(arr) {
  let total = 0;
  for (let i = 0; i < arr.length; i++) {
    total += arr[i];
  }
  return total;
}

/**
 * Run a function many times and report average ms.
 * @param {(a:number[])=>number} fn
 * @param {number[]} data
 * @param {number} iters
 */
function benchmark(fn, data, iters = 1000) {
  // Warm up JIT
  for (let w = 0; w < 50; w++) fn(data);
  const t0 = performance.now();
  let sink = 0;
  for (let k = 0; k < iters; k++) sink += fn(data);
  const t1 = performance.now();
  return { ms: (t1 - t0) / iters, sink };
}

// ---- Demo ----
const N = 1_000_000;
const data = new Array(N);
for (let i = 0; i < N; i++) data[i] = (i % 100) * 0.5;

const a = benchmark(naiveSum, data);
const b = benchmark(fastSum, data);

console.log('naive:', a.ms.toFixed(4), 'ms/iter, sink=', a.sink);
console.log('fast :', b.ms.toFixed(4), 'ms/iter, sink=', b.sink);
console.log('speedup:', (a.ms / b.ms).toFixed(2) + 'x');
```

### Optional: micro-optimized “hot loop” utilities

```js
/**
 * Fast in-place map for numeric arrays (avoids new array allocation).
 * Only use when mutation is acceptable.
 */
function fastMapInPlace(arr, fn) {
  const n = arr.length;
  for (let i = 0; i < n; i++) {
    arr[i] = fn(arr[i], i);
  }
  return arr;
}

/**
 * Fast filter into a pre-sized buffer (reduces GC churn).
 * Returns count written; caller slices if needed.
 */
function fastFilterToBuffer(src, dst, pred) {
  const n = src.length;
  let w = 0;
  for (let i = 0; i < n; i++) {
    const v = src[i];
    if (pred(v, i)) dst[w++] = v;
  }
  return w;
}
```

**Interview takeaway:** Mention *measure first*, *hot paths only*, and that readability/maintainability usually beat micro-opts unless you have a proven bottleneck.

Below are common JavaScript micro-optimizations and the edge cases that can silently break correctness, performance, or both. Each example shows the “fast” pattern, the edge case, and a safer alternative.

---

## 1. Bitwise truncation (`| 0`, `~~`, `>> 0`)

**Why people use it:** faster than `Math.trunc`/`Math.floor` for integers.

**Edge cases**
- Values outside signed 32-bit range wrap.
- `NaN`, `Infinity`, `-Infinity` become `0`.
- `-0` becomes `0` (sign lost).
- Truncation is *toward zero*, not floor (differs for negatives).

```js
// Fast but dangerous
const fastTrunc = x => x | 0;

console.log(fastTrunc(2 ** 31));        // -2147483648  (wrapped!)
console.log(fastTrunc(NaN));            // 0
console.log(fastTrunc(Infinity));       // 0
console.log(fastTrunc(-1.7));           // -1  (toward zero, not floor)
console.log(Object.is(fastTrunc(-0), -0)); // false  (-0 lost)

// Safer
const safeTrunc = x => (Number.isFinite(x) ? Math.trunc(x) : 0);
// Or for guaranteed 32-bit domains only:
const safe32 = x => (x | 0); // document/validate range first
```

**Unsigned variant edge case**

```js
const u = x => x >>> 0;
console.log(u(-1));        // 4294967295
console.log(u(2 ** 32));   // 0  (wraps modulo 2^32)
```

---

## 2. Caching array `.length`

**Why:** avoids property lookup each iteration.

**Edge cases**
- Array is mutated during iteration (push/splice) → stale bound.
- Array-like objects with getter `length` → caching changes semantics.
- Sparse arrays: `length` includes holes; cached bound still okay, but value access differs.

```js
const arr = [1, 2, 3];

// Fast
for (let i = 0, n = arr.length; i < n; i++) {
  if (i === 1) arr.push(99); // mutation
}
// Loop stops at original n=3; index 3's 99 is never visited.

// Safer when mutation is possible
for (let i = 0; i < arr.length; i++) { /* live bound */ }

// Or iterate a snapshot if you must mutate source:
for (const x of [...arr]) { /* ... */ }
```

---

## 3. Replacing `forEach` with `for`

**Why:** `for` is often faster and allows `break`.

**Edge cases**
- `forEach` skips holes in sparse arrays; `for` reads `undefined`.
- `forEach` passes `(value, index, array)`; hand-rolled loops may omit arguments.
- `forEach` callback `this` binding must be preserved.

```js
const sparse = [1, , 3];

sparse.forEach(v => console.log(v)); // 1, 3  (hole skipped)

for (let i = 0; i < sparse.length; i++) {
  console.log(sparse[i]);            // 1, undefined, 3
}

// Safer equivalence if you want forEach semantics:
for (let i = 0; i < sparse.length; i++) {
  if (!(i in sparse)) continue;    // skip holes explicitly
  const v = sparse[i];
  // ...
}
```

---

## 4. Property access micro-opts (caching, destructuring)

**Why:** fewer repeated lookups.

**Edge cases**
- Getters with side effects or non-deterministic values.
- Proxies where each access runs traps.
- Objects whose shape changes (hidden-class transitions) → deoptimization.
- Inherited/enumerable properties.

```js
const obj = {
  get x() { return Math.random(); }, // side-effecting getter
};

// Fast but wrong if getter is non-pure
const cached = obj.x;
console.log(cached === obj.x); // often false

// Fast shape-stable pattern
function makePoint(x, y) {
  this.x = x;
  this.y = y;
  // Always add properties in same order to keep one hidden class
}
```

**Prototype pollution / missing own property**

```js
const map = {};
// Fast lookup
if (map[key]) { /* ... */ }

// Edge: key = 'toString' or '__proto__'
console.log(map['toString']); // function from Object.prototype

// Safer
const safeMap = Object.create(null); // no prototype
// or
if (Object.prototype.hasOwnProperty.call(map, key)) { /* ... */ }
```

---

## 5. Lookup tables instead of `switch`

**Why:** O(1) dispatch.

**Edge cases**
- Prototype pollution if using plain objects.
- Missing default case.
- Keys coerced to strings (`1` and `'1'` collide).

```js
const handlers = {
  add: (a, b) => a + b,
};

function dispatch(type, ...args) {
  return handlers[type](...args); // TypeError if missing; prototype props callable
}

// Safer
const safeHandlers = Object.create(null);
safeHandlers.add = (a, b) => a + b;

function safeDispatch(type, ...args) {
  const fn = safeHandlers[type];
  if (typeof fn !== 'function') throw new Error('unknown type: ' + type);
  return fn(...args);
}
```

---

## 6. Numeric coercion (`+x`, `!!x`, `x + ''`)

**Why:** shorter/faster than `Number()`, `Boolean()`, `String()`.

**Edge cases**
- `+null === 0`, `+undefined === NaN`, `+'' === 0`.
- `!!new Boolean(false) === true` (objects are truthy).
- `'' + null === 'null'`, `'' + undefined === 'undefined'`.
- Large integers lose precision beyond 2^53.

```js
console.log(+null);          // 0
console.log(+undefined);     // NaN
console.log(!![]);           // true  (empty array is truthy object)
console.log('' + null);      // 'null'

// Safer conversions
const toNum = x => (x === null || x === undefined ? NaN : Number(x));
const toStr = x => (x === null || x === undefined ? '' : String(x));
```

---

## 7. `parseInt` / `Number()` shortcuts

```js
// Fast-ish but risky
const n = +str;

// Edge: whitespace, signs, hex, empty
console.log(+'  42  ');   // 42
console.log(+'');          // 0
console.log(+'0x10');      // 16
console.log(+'1e3');       // 1000

// If you need strict integer parsing:
const strictInt = s => {
  if (typeof s !== 'string' || !/^[+-]?\d+$/.test(s.trim())) return NaN;
  const n = Number(s);
  return Number.isSafeInteger(n) ? n : NaN;
};
```

---

## 8. Memoization / caching

**Why:** avoid recomputation.

**Edge cases**
- Mutable arguments → stale cache.
- `this` binding lost or changed.
- Memory leaks (unbounded cache).
- Functions with side effects should not be memoized.
- Object keys use reference identity, not deep equality.

```js
const cache = new Map();

function memoized(obj) {
  if (cache.has(obj)) return cache.get(obj);
  const result = expensive(obj);
  cache.set(obj, result);
  return result;
}

const o = { value: 1 };
memoized(o);          // caches
o.value = 2;
memoized(o);          // returns stale result! (same identity)

// Safer: only memoize pure functions with primitive args,
// or use a WeakMap and accept identity semantics:
const weakCache = new WeakMap();
```

---

## 9. Avoiding `try/catch` in hot paths

**Why:** historically deoptimized in some engines.

**Edge cases**
- Errors still can occur; removing handling changes failure behavior.
- Async errors not caught by synchronous try/catch.
- Modern V8 optimizes try/catch reasonably well; micro-gain may be negligible.

```js
// Risky: assumes no throw
function hot(arr) {
  // no try/catch
  return arr.map(x => x.value); // throws if x is null
}

// Safer: validate cheaply, isolate cold error path
function safeHot(arr) {
  for (let i = 0; i < arr.length; i++) {
    const x = arr[i];
    if (x == null) return null; // cheap guard
  }
  return arr.map(x => x.value);
}
```

---

## 10. `arguments` object leakage

**Why:** using `arguments` can deoptimize; rest params are cleaner.

**Edge cases**
- `arguments` is array-like, not array (`slice` needed).
- Aliasing between `arguments` and named params in non-strict mode.
- Rest params create a real array and are optimizable.

```js
// Deopt-prone / legacy
function legacy() {
  return Array.prototype.slice.call(arguments);
}

// Better
function modern(...args) {
  return args;
}

// Edge: non-strict aliasing
function alias(a) {
  arguments[0] = 99;
  console.log(a); // 99 in non-strict; a stays original in strict
}
```

---

## 11. Typed arrays

**Why:** fast numeric storage.

**Edge cases**
- Values are clamped/modulo to type range.
- Endianness matters for `DataView` vs typed arrays.
- Detached buffers after transfer.
- Out-of-bounds reads return `0`/`undefined`? Actually typed array out-of-bounds returns `undefined` for get, ignores set.

```js
const u8 = new Uint8Array([300, -1]);
console.log(u8); // Uint8Array [ 44, 255 ]  (mod 256)

const buf = new ArrayBuffer(4);
const view = new Uint32Array(buf);
const dv = new DataView(buf);
// Endianness differs by platform for typed array; DataView lets you specify.

// Detached buffer edge
const t = new Uint8Array([1, 2, 3]);
const transferred = t.buffer.transfer(); // if supported
// t.length === 0 after transfer; accessing throws? Actually returns 0 length
```

---

## 12. Object creation patterns

**Why:** `Object.create(null)` avoids prototype overhead; `{}` is fast when shape-stable.

**Edge cases**
- `Object.create(null)` has no `toString`, `hasOwnProperty`, etc.
- Adding/deleting properties changes hidden class → deopt.
- Deleting properties (`delete obj.x`) is especially deoptimizing.

```js
const fast = { x: 1, y: 2 }; // stable shape
// fast.z = 3; // adding later changes hidden class

const dict = Object.create(null);
dict.key = 'value';
// dict.toString(); // TypeError: not a function

// Avoid delete in hot paths
const o = { a: 1, b: 2 };
delete o.a; // deopts; better: o.a = undefined (if semantics allow)
```

---

## 13. String building

**Why:** `+` vs template literals vs `Array.join`.

**Edge cases**
- Repeated concatenation creates many intermediate strings (O(n²) behavior in some cases).
- Very large strings can hit engine limits (~512 MB–1 GB).
- Coercion of non-strings.

```js
// Potentially quadratic for huge loops
let s = '';
for (let i = 0; i < 100000; i++) s += i;

// Better for many parts
const parts = [];
for (let i = 0; i < 100000; i++) parts.push(i);
const s2 = parts.join('');

// Template literals are usually optimized well for small fixed counts:
const msg = `${a} ${b} ${c}`;
```

---

## 14. Loop type and integer overflow

**Why:** `for` vs `while` vs `for...of`.

**Edge cases**
- `for...in` on arrays yields string keys and inherited enumerable props.
- `for...of` uses iterator protocol (slower but correct for iterables).
- Counting down to 0: `i--` with `i` becoming `-1` if not careful; `>>> 0` tricks.

```js
const arr = [10, 20, 30];
arr.custom = 99;

for (const k in arr) console.log(k); // '0','1','2','custom' (strings!)

for (const v of arr) console.log(v); // 10,20,30

// Micro-opt counting down
for (let i = arr.length; i-- > 0; ) {
  // i goes length-1..0; stops when i becomes -1 after condition? Check carefully.
}
```

---

## 15. Floating-point and precision

**Why:** using `0.1 + 0.2` comparisons.

**Edge cases**
- `0.1 + 0.2 !== 0.3`.
- Safe integer limit `2^53 - 1`.
- `-0` equality: `-0 === 0` is true but `Object.is(-0, 0)` false.

```js
console.log(0.1 + 0.2 === 0.3); // false

// Safer comparison
const approxEqual = (a, b, eps = 1e-9) => Math.abs(a - b) < eps;

console.log(Number.isSafeInteger(2 ** 53)); // false
console.log(Object.is(-0, 0));              // false
```

---

## 16. Short-circuit evaluation

**Why:** skip expensive work.

**Edge cases**
- Side effects in skipped operands don’t run.
- Operator precedence mistakes.
- Falsy values that are valid (0, '', false, null) get skipped unintentionally.

```js
// Fast but wrong if 0 is valid
const value = input || defaultValue; // '' or 0 replaced

// Safer for null/undefined only
const value2 = input ?? defaultValue;

// Side-effect edge
if (cheap() && expensiveWithSideEffect()) {
  // if cheap() false, side effect skipped—maybe desired, maybe not
}
```

---

## 17. Inlining / avoiding function calls

**Why:** remove call overhead.

**Edge cases**
- Recursion depth → stack overflow.
- Loss of stack traces for debugging.
- Polymorphic call sites deoptimize if inlined assumptions fail.

```js
// Deep recursion micro-opt can crash
function sum(n) {
  if (n <= 0) return 0;
  return n + sum(n - 1); // RangeError for large n
}

// Safer iterative
function sumSafe(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) total += i;
  return total;
}
```

---

## 18. `Map`/`Set` vs plain objects

**Why:** `Map` has better performance for frequent add/delete.

**Edge cases**
- `Map` keys use SameValueZero: `NaN` equals `NaN`, `-0` equals `0`.
- Iteration order guaranteed insertion order (unlike objects for integer-like keys).
- Memory overhead larger for small collections.

```js
const m = new Map();
m.set(NaN, 'a');
console.log(m.get(NaN)); // 'a'  (NaN === NaN in Map)

const o = {};
o[NaN] = 'a'; // key becomes 'NaN' string
console.log(o['NaN']); // 'a'
```

---

## 19. Avoiding repeated DOM / global lookups (browser)

**Why:** cache references.

**Edge cases**
- DOM node removed from document → stale reference; operations may throw or do nothing.
- `window`/`document` can be shadowed in some contexts.
- Cross-origin iframes have different globals.

```js
const doc = document;
const el = doc.getElementById('app');

// If el is removed later, cached reference still points to detached node
el.textContent = 'x'; // silently updates detached node
```

---

## 20. Async micro-optimizations (`Promise` chaining)

**Why:** avoid `async/await` overhead? (Usually negligible.)

**Edge cases**
- Unhandled rejections.
- `async` functions always return a Promise; `await` of non-thenable wraps.
- Microtask ordering affects observable state.

```js
// Fast but loses error handling clarity
doWork()
  .then(x => transform(x))
  .then(save);

// Safer with explicit catch and finally
doWork()
  .then(transform)
  .then(save)
  .catch(err => { /* handle */ })
  .finally(cleanup);
```

---

## Practical checklist

Before applying a micro-optimization, verify:

1. **Range:** Are numbers guaranteed within 32-bit / safe-integer range?
2. **Purity:** Are cached values immutable or safely identity-based?
3. **Shape stability:** Do objects keep consistent property order/count?
4. **Sparse data:** Are holes/`undefined` handled intentionally?
5. **Coercion:** Do `+`, `!!`, `+''` preserve intended types?
6. **Prototype safety:** Use `Object.create(null)` or `hasOwnProperty` for dictionaries.
7. **Mutation:** Is iteration bound recomputed when needed?
8. **Error paths:** Are expected failures still handled?
9. **Measurement:** Did profiling show this code is actually hot?
10. **Readability:** Is the gain worth maintenance cost?

Micro-optimizations are most valuable in tight loops over large data; elsewhere, prefer clarity and correctness. Always benchmark with realistic data and engine versions.

# Mocking & Test Doubles in JavaScript

Below is a **complete, dependency-free, runnable example** using Node’s built-in test runner (`node:test`), plus explanations of every kind of test double and how to build them by hand and with libraries.

---

## 1. The code under test

`user-service.js`

```js
// user-service.js
class UserService {
  constructor(repo, emailer) {
    this.repo = repo;
    this.emailer = emailer;
  }

  async register({ name, email }) {
    if (!name || !email) throw new Error('name and email are required');
    const existing = await this.repo.findByEmail(email);
    if (existing) throw new Error('email already registered');
    const user = await this.repo.create({ name, email });
    await this.emailer.sendWelcome(email, name);
    return user;
  }

  async getProfile(id) {
    const user = await this.repo.findById(id);
    if (!user) throw new Error('user not found');
    return { ...user, displayName: `${user.name} <${user.email}>` };
  }
}

module.exports = { UserService };
```

---

## 2. Terminology (quick reference)

| Double | Purpose |
|---|---|
| **Dummy** | Passed to satisfy a signature; never used. |
| **Stub** | Returns canned answers; no behavior verification. |
| **Spy** | Records calls; can delegate to real impl. |
| **Mock** | Spy + expectations verified at end of test. |
| **Fake** | Working lightweight implementation (e.g. in-memory DB). |

---

## 3. Hand-rolled doubles (no libraries)

Save as `user-service.test.js` and run with `node --test user-service.test.js`.

```js
// user-service.test.js
const { test, describe, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const { UserService } = require('./user-service');

// ---------- tiny helpers ----------
function spy(impl) {
  const calls = [];
  const fn = function (...args) {
    calls.push({ args, thisArg: this });
    return impl ? impl.apply(this, args) : undefined;
  };
  fn.calls = calls;
  fn.calledWith = (...expected) =>
    calls.some(c => JSON.stringify(c.args) === JSON.stringify(expected));
  fn.callCount = () => calls.length;
  fn.lastCall = () => (calls.length ? calls[calls.length - 1].args : undefined);
  return fn;
}

function stub(returnValue) {
  const s = spy(() => returnValue);
  return s;
}

function mock(impl, expectations = {}) {
  const m = spy(impl);
  m.expectations = expectations;
  m.verify = () => {
    if (expectations.called !== undefined && m.callCount() !== expectations.called) {
      throw new Error(`expected ${expectations.called} calls, got ${m.callCount()}`);
    }
    if (expectations.calledWith && !m.calledWith(...expectations.calledWith)) {
      throw new Error(`expected call with ${JSON.stringify(expectations.calledWith)}`);
    }
  };
  return m;
}

// ---------- tests ----------

describe('UserService.register', () => {
  let repo, emailer, service;

  beforeEach(() => {
    // Fake-ish repo as stubs
    repo = {
      findByEmail: stub(null),          // default: no existing user
      create: stub({ id: 1, name: 'Ada', email: 'ada@example.com' }),
    };
    // Mock: must be called exactly once with welcome args
    emailer = {
      sendWelcome: mock(async () => undefined, {
        called: 1,
        calledWith: ['ada@example.com', 'Ada'],
      }),
    };
    service = new UserService(repo, emailer);
  });

  test('creates user and sends welcome email', async () => {
    const user = await service.register({ name: 'Ada', email: 'ada@example.com' });

    assert.deepEqual(user, { id: 1, name: 'Ada', email: 'ada@example.com' });
    assert.equal(repo.findByEmail.callCount(), 1);
    assert.ok(repo.findByEmail.calledWith('ada@example.com'));
    assert.equal(repo.create.callCount(), 1);
    emailer.sendWelcome.verify(); // mock expectation check
  });

  test('rejects duplicate email', async () => {
    repo.findByEmail = stub({ id: 9, name: 'Existing', email: 'ada@example.com' });

    await assert.rejects(
      service.register({ name: 'Ada', email: 'ada@example.com' }),
      /email already registered/
    );
    assert.equal(repo.create.callCount(), 0);
    assert.equal(emailer.sendWelcome.callCount(), 0);
  });

  test('validates required fields', async () => {
    await assert.rejects(
      service.register({ name: '', email: 'x@y.com' }),
      /name and email are required/
    );
  });
});

describe('UserService.getProfile', () => {
  test('returns decorated profile', async () => {
    const repo = { findById: stub({ id: 7, name: 'Grace', email: 'grace@example.com' }) };
    const service = new UserService(repo, { sendWelcome: stub() });

    const profile = await service.getProfile(7);
    assert.deepEqual(profile, {
      id: 7,
      name: 'Grace',
      email: 'grace@example.com',
      displayName: 'Grace <grace@example.com>',
    });
  });

  test('throws when user missing', async () => {
    const repo = { findById: stub(null) };
    const service = new UserService(repo, { sendWelcome: stub() });

    await assert.rejects(service.getProfile(404), /user not found/);
  });
});

// ---------- dummy example ----------
test('dummy argument example', () => {
  // A dummy is just a placeholder never exercised.
  const dummyLogger = { log() {} };
  const svc = new UserService(
    { findByEmail: stub(null), create: stub({ id: 1 }) },
    { sendWelcome: stub() }
  );
  assert.ok(svc);
  void dummyLogger;
});
```

Run:

```bash
node --test user-service.test.js
```

---

## 4. Using Node’s built-in `mock` (modern, recommended)

Node 18+ ships `node:test`’s `mock` helper—no extra deps.

```js
const { test, mock } = require('node:test');
const assert = require('node:assert/strict');
const { UserService } = require('./user-service');

test('register with node:test mock', async () => {
  const repo = {
    findByEmail: mock.fn(async () => null),
    create: mock.fn(async () => ({ id: 1, name: 'Ada', email: 'ada@example.com' })),
  };
  const emailer = { sendWelcome: mock.fn(async () => {}) };

  const svc = new UserService(repo, emailer);
  await svc.register({ name: 'Ada', email: 'ada@example.com' });

  assert.equal(repo.findByEmail.mock.calls.length, 1);
  assert.deepEqual(repo.findByEmail.mock.calls[0].arguments, ['ada@example.com']);
  assert.equal(emailer.sendWelcome.mock.calls.length, 1);

  mock.reset(); // clean global-ish state between tests
});
```

Mocking a method on an existing object:

```js
const obj = { save: async (x) => x };
mock.method(obj, 'save', async (x) => ({ ...x, id: 1 }));
// ... exercise ...
mock.restoreAll(); // restores originals
```

---

## 5. Sinon.js example (most popular standalone)

```bash
npm i -D sinon
```

```js
const sinon = require('sinon');
const { UserService } = require('./user-service');

const repo = { findByEmail: sinon.stub(), create: sinon.stub() };
const emailer = { sendWelcome: sinon.stub() };

repo.findByEmail.resolves(null);
repo.create.resolves({ id: 1, name: 'Ada', email: 'ada@example.com' });
emailer.sendWelcome.resolves();

const svc = new UserService(repo, emailer);
await svc.register({ name: 'Ada', email: 'ada@example.com' });

sinon.assert.calledOnce(repo.findByEmail);
sinon.assert.calledWith(repo.findByEmail, 'ada@example.com');
sinon.assert.calledOnce(emailer.sendWelcome);

sinon.restore(); // reset all stubs
```

Sinon also provides **fake timers** and **fake XHR**:

```js
const clock = sinon.useFakeTimers(new Date('2024-01-01'));
clock.tick(1000);
clock.restore();
```

