## Mocking and Test Doubles (JavaScript)

A **test double** is any object/function that stands in for a real dependency during a test. The term comes from Gerard Meszaros. The common kinds are:

| Double | Purpose |
|---|---|
| **Dummy** | Passed around but never actually used (fills a parameter). |
| **Stub** | Provides canned answers to calls; no verification of how it was called. |
| **Spy** | Records how it was called (args, count, `this`) while usually still delegating to the real implementation. |
| **Mock** | Pre-programmed with expectations; the test verifies that specific calls happened. |
| **Fake** | A working but simplified implementation (e.g. in-memory DB). |

**Mocking** usually means *replacing* a dependency with a controllable double and then *asserting* on its interactions. In JS this is easy because functions are first-class values and objects are mutable: you can overwrite `obj.method` with a function and restore it later.

Key ideas a mocking lib must provide:

1. **Record calls** (arguments, return value, thrown error, `this`).
2. **Control behavior** (return value, throw, delegate to a fake).
3. **Restore** the original implementation so tests don’t leak.
4. **Assertions** (called, called with, call count).

Popular libs (Jest, Sinon) are essentially these primitives plus matchers and module interception.

---

### Minimal implementation (core only)

```js
'use strict';

/* ------------------------------------------------------------------ */
/* Helpers                                                            */
/* ------------------------------------------------------------------ */

function argsEqual(a, b) {
  if (a === b) return true;
  // Good enough for an interview-grade demo; production libs use
  // deep equality (e.g. expect's equality).
  try {
    return JSON.stringify(a) === JSON.stringify(b);
  } catch {
    return false;
  }
}

/* ------------------------------------------------------------------ */
/* Spy: wraps a function, records calls, still calls through           */
/* ------------------------------------------------------------------ */

function spy(implementation) {
  const calls = [];

  const fn = function (...args) {
    const thisArg = this;
    let result;
    let thrown = null;

    try {
      result = implementation ? implementation.apply(thisArg, args) : undefined;
    } catch (err) {
      // Record the failure, then re-throw so callers observe it.
      calls.push({ args, thisArg, result: undefined, thrown: err });
      throw err;
    }

    calls.push({ args, thisArg, result, thrown: null });
    return result;
  };

  // Introspection API
  fn.calls = calls;
  fn.callCount = () => calls.length;
  fn.called = () => calls.length > 0;
  fn.calledWith = (...expected) =>
    calls.some((c) => argsEqual(c.args, expected));
  fn.lastCall = () => (calls.length ? calls[calls.length - 1] : null);
  fn.returnValues = () => calls.map((c) => c.result);
  fn.reset = () => {
    calls.length = 0;
  };

  return fn;
}

/* ------------------------------------------------------------------ */
/* Stub: configurable behavior, records calls                          */
/* ------------------------------------------------------------------ */

function stub() {
  let behavior = () => undefined;
  const s = spy((...args) => behavior(...args));

  // Chainable configurators
  s.returns = (value) => {
    behavior = () => value;
    return s;
  };
  s.throws = (error) => {
    behavior = () => {
      throw error;
    };
    return s;
  };
  s.callsFake = (fn) => {
    behavior = fn;
    return s;
  };
  s.resolves = (value) => s.returns(Promise.resolve(value));
  s.rejects = (reason) => s.returns(Promise.reject(reason));

  return s;
}

/* ------------------------------------------------------------------ */
/* Object-level helpers                                               */
/* ------------------------------------------------------------------ */

function spyOn(obj, method) {
  if (!obj || typeof obj[method] !== 'function') {
    throw new TypeError(`spyOn: "${method}" is not a function on the target`);
  }
  const original = obj[method];
  const s = spy((...args) => original.apply(obj, args));
  obj[method] = s;
  s.restore = () => {
    obj[method] = original;
  };
  return s;
}

function stubOn(obj, method) {
  const original = (obj && typeof obj[method] === 'function') ? obj[method] : undefined;
  const s = stub();
  obj[method] = s;
  s.restore = () => {
    if (original) obj[method] = original;
    else delete obj[method];
  };
  return s;
}

/* ------------------------------------------------------------------ */
/* Tiny assertion helpers (throw on failure)                          */
/* ------------------------------------------------------------------ */

function assertCalled(double) {
  if (!double.called()) throw new Error('Expected the double to have been called');
}
function assertCalledWith(double, ...expected) {
  if (!double.calledWith(...expected))
    throw new Error(`Expected call with ${JSON.stringify(expected)}`);
}
function assertCallCount(double, n) {
  if (double.callCount() !== n)
    throw new Error(`Expected ${n} calls, got ${double.callCount()}`);
}

/* ------------------------------------------------------------------ */
/* Demo                                                               */
/* ------------------------------------------------------------------ */

function runDemo() {
  // 1) Stubbing a pure function
  const add = stub().returns(42);
  console.log('stub returns:', add(1, 2)); // 42
  console.log('call count:', add.callCount()); // 1
  console.log('called with [1,2]:', add.calledWith(1, 2)); // true

  // 2) Spying on an object method (calls through)
  const calculator = {
    multiply(a, b) {
      return a * b;
    },
  };
  const multSpy = spyOn(calculator, 'multiply');
  console.log('spy result:', calculator.multiply(3, 4)); // 12 (real impl)
  console.log('spy called:', multSpy.called()); // true
  multSpy.restore();
  console.log('restored:', calculator.multiply(3, 4)); // 12

  // 3) Stubbing an object method
  const api = { fetchUser: async (id) => ({ id, name: 'Real' }) };
  const fetchStub = stubOn(api, 'fetchUser').resolves({ id: 7, name: 'Stubbed' });
  api.fetchUser(7).then((u) => console.log('stubbed user:', u));
  fetchStub.restore();

  // 4) Throwing
  const boom = stub().throws(new Error('kaboom'));
  try {
    boom();
  } catch (e) {
    console.log('threw:', e.message);
  }

  // 5) Assertion helpers
  const s = stub().returns('ok');
  s('x');
  assertCalled(s);
  assertCalledWith(s, 'x');
  assertCallCount(s, 1);
  console.log('all assertions passed');
}

runDemo();
```

### How you’d use this in a real test (Jest-like style)

```js
// System under test
function Checkout(paymentGateway) {
  this.pay = (amount) => paymentGateway.charge(amount);
}

// Test
const gateway = { charge: () => {} };
const chargeSpy = stubOn(gateway, 'charge').returns({ ok: true });

const checkout = new Checkout(gateway);
const result = checkout.pay(100);

assertCalledWith(chargeSpy, 100);
console.log(result); // { ok: true }
chargeSpy.restore();
```

### Interview talking points

- **Don’t over-mock.** Mock boundaries (I/O, time, randomness), not pure logic.
- **Restore** doubles in `afterEach`/`finally` to avoid cross-test contamination.
- **Prefer spies over mocks** when you only need to observe; they keep tests less coupled to implementation.
- **Module mocking** (e.g. `jest.mock`) intercepts `require`/`import`; object spying only works if the SUT receives the dependency via injection.
- **Async doubles** should return promises (`resolves`/`rejects`) so `await` works naturally.
- **Deep equality** for `calledWith` is the usual pain point; production libs use sophisticated matchers and asymmetric matchers (e.g. `expect.any(Number)`).

This implementation captures the *core* mechanics: record, control, restore, assert. Production frameworks add module registries, automatic cleanup, spies on getters/setters, and richer matchers.

Below are common edge cases when using mocks/test doubles in JavaScript (examples use Jest, but the concepts apply to Vitest/Sinon too). Each section shows the pitfall and the fix.

---

## 1. `jest.mock` factory hoisting vs. outer variables

`jest.mock` is hoisted above imports, so referencing a variable defined later throws.

```js
// BAD
const mockFetch = jest.fn();
jest.mock('./api', () => ({ fetch: mockFetch })); // ReferenceError
```

**Fix:** define the mock inside the factory, or use `jest.doMock` + dynamic `require`.

```js
jest.mock('./api', () => ({ fetch: jest.fn() }));

const api = require('./api');

beforeEach(() => api.fetch.mockReset());
```

Or for late binding:

```js
jest.doMock('./api', () => ({ fetch: jest.fn() }));
const api = require('./api');
```

---

## 2. Module mocks don’t affect internal calls

If `a()` calls `b()` inside the same module, mocking the export of `b` won’t change `a()`.

```js
// service.js
export function a() { return b() + 1; }
export function b() { return 10; }

// test
jest.mock('./service', () => ({
  ...jest.requireActual('./service'),
  b: jest.fn(() => 999),
}));
// a() still returns 11, because a references the internal b binding
```

**Fix:** restructure to call through an object/namespace, or mock at a boundary (HTTP/DB).

```js
// service.js
export const svc = { b() { return 10; } };
export function a() { return svc.b() + 1; }
// test can spy on svc.b
```

---

## 3. Spying loses `this` binding

Extracting a spied method detaches `this`.

```js
const obj = { x: 5, getX() { return this.x; } };
const spy = jest.spyOn(obj, 'getX');

const fn = obj.getX;
fn(); // TypeError: Cannot read properties of undefined
```

**Fix:** call via the object, or bind.

```js
obj.getX();        // ok
const fn = obj.getX.bind(obj);
```

---

## 4. Arrow-function / class-field methods

Arrow methods are own properties bound at construction; spying on the prototype won’t catch them, and spying on the instance replaces the binding.

```js
class Foo { bar = () => this.x; }
const f = new Foo();
jest.spyOn(f, 'bar'); // replaces instance property; original binding lost if not careful
```

**Fix:** spy on the instance property and provide an implementation that preserves `this`, or refactor to prototype methods.

---

## 5. Non-writable / read-only properties

`jest.spyOn` throws if the property is non-configurable.

```js
const o = {};
Object.defineProperty(o, 'id', { value: 1, writable: false, configurable: false });
jest.spyOn(o, 'id'); // Error
```

**Fix:** redefine with configurability, or replace the whole object.

```js
Object.defineProperty(o, 'id', { value: 2, writable: true, configurable: true });
```

---

## 6. Getters / setters need the accessor flag

```js
const o = { get x() { return 1; } };
jest.spyOn(o, 'x'); // spies on value, not getter — often wrong
```

**Fix:**

```js
jest.spyOn(o, 'x', 'get').mockReturnValue(42);
jest.spyOn(o, 'x', 'set'); // for setters
```

---

## 7. Mock return exhaustion (`*Once`)

Chained one-shot returns fall back to `undefined` after exhaustion.

```js
const m = jest.fn()
  .mockReturnValueOnce(1)
  .mockReturnValueOnce(2);

m(); m(); m(); // 1, 2, undefined  -> third call breaks code expecting a number
```

**Fix:** add a default tail.

```js
const m = jest.fn()
  .mockReturnValueOnce(1)
  .mockReturnValueOnce(2)
  .mockReturnValue(3);
```

---

## 8. Async mocks and unhandled rejections

Forgetting `mockRejectedValue` vs `mockImplementation` async can swallow errors.

```js
const m = jest.fn().mockResolvedValue({ ok: true });
// If code expects throw:
m.mockRejectedValue(new Error('boom'));
```

Always await and assert:

```js
await expect(fn()).rejects.toThrow('boom');
```

---

## 9. Fake timers + async/microtasks

`jest.useFakeTimers()` mocks `setTimeout`, but microtasks and `process.nextTick` need care; sync timer runners deadlock on recursive timers.

```js
jest.useFakeTimers();
doWork(); // schedules setTimeout recursively
jest.runAllTimers(); // infinite loop / hang
```

**Fix:** advance by bounded time, and flush microtasks.

```js
jest.useFakeTimers();
doWork();
jest.advanceTimersByTime(1000);
await Promise.resolve(); // flush microtasks
jest.useRealTimers();
```

For async timer code:

```js
jest.useFakeTimers();
const p = doAsyncWork();
await jest.runAllTimersAsync();
await p;
jest.useRealTimers();
```

---

## 10. Mocking `Date` and `Math.random`

Mutating globals leaks across tests.

```js
// BAD: permanent
Date.now = () => 12345;
```

**Fix:** spy + restore, or fake timers.

```js
beforeEach(() => jest.useFakeTimers().setSystemTime(new Date('2024-01-01')));
afterEach(() => jest.useRealTimers());

// or
const spy = jest.spyOn(Math, 'random').mockReturnValue(0.5);
afterEach(() => spy.mockRestore());
```

---

## 11. Mocking `fetch` / HTTP globals

`fetch` returns a `Response`; mocking only JSON loses status/headers.

```js
global.fetch = jest.fn().mockResolvedValue({
  json: async () => ({ data: 1 }),
  ok: true,
  status: 200,
});
```

**Fix:** use a helper or MSW for fidelity; always restore.

```js
afterEach(() => jest.restoreAllMocks());
```

---

## 12. Reset strategy confusion

- `mockClear`: clears calls/instances/contexts, keeps implementation.
- `mockReset`: also clears implementation (returns `undefined`).
- `mockRestore`: restores original (only for spies).

```js
const spy = jest.spyOn(obj, 'm').mockReturnValue(1);
// between tests you usually want:
beforeEach(() => spy.mockClear());   // keep impl
// NOT mockReset unless you re-set impl
```

Use `jest.restoreAllMocks()` in `afterEach` for spies; `jest.clearAllMocks()` for call data.

---

## 13. Constructor / class mocking

Auto-mocked classes return instances whose methods are `undefined` unless set.

```js
jest.mock('./Foo', () => jest.fn().mockImplementation(function () {
  this.bar = jest.fn(() => 42);
}));
```

If you need `new Foo()` to be a real instance with mocked deps, use `jest.requireActual`:

```js
jest.mock('./Foo', () => {
  const Actual = jest.requireActual('./Foo').default;
  return class extends Actual {
    bar = jest.fn();
  };
});
```

Note: mock constructors must be regular functions, not arrows (arrows can’t be `new`-ed).

---

## 14. Default vs. named exports

Factories must mirror the module shape.

```js
// module: export default fn; export { named }
jest.mock('./m', () => ({
  __esModule: true,
  default: jest.fn(),
  named: jest.fn(),
}));
```

Missing `__esModule: true` breaks `import m from './m'` interop.

---

## 15. ESM mocking limitations

Jest’s `jest.mock` is CJS-oriented. With native ESM (`"type": "module"`), use Vitest or dynamic `vi.mock`, or transform. A common failure: mocking a namespace import.

```js
import * as m from './m';
jest.spyOn(m, 'foo'); // works only if m is the module namespace object
m.foo();               // must call through namespace, not a destructured binding
```

Destructured `import { foo }` binds by value in CJS; spying won’t reflect. Call `m.foo()`.

---

## 16. Mocking modules with side effects

`jest.mock` replaces the module, so side effects (global registration) won’t run.

```js
jest.mock('./register', () => ({})); // side-effect module becomes empty
```

**Fix:** partial mock preserving side effects:

```js
jest.mock('./register', () => {
  const actual = jest.requireActual('./register');
  return { ...actual, hook: jest.fn() };
});
```

---

## 17. Shared mock state across tests (pollution)

A mock defined at module scope accumulates calls.

```js
const m = jest.fn();
test('a', () => { m(); expect(m).toHaveBeenCalledTimes(1); });
test('b', () => { expect(m).toHaveBeenCalledTimes(0); }); // fails
```

**Fix:** reset in `beforeEach`/`afterEach`, or create mocks inside tests/factories.

```js
beforeEach(() => m.mockClear());
```

---

## 18. Spying on imported functions (binding)

```js
import { foo } from './m';
jest.spyOn({ foo }, 'foo'); // spies on a throwaway object, not the module
```

**Fix:** spy on the module namespace.

```js
import * as m from './m';
const spy = jest.spyOn(m, 'foo');
m.foo(); // invoke through namespace
```

---

## 19. Mocking non-existent / misspelled methods

`jest.spyOn(obj, 'methd')` throws at definition time — good, but auto-mocks silently create `undefined` properties, masking typos.

```js
jest.mock('./m'); // auto-mock
m.doThingg(); // calls undefined mock? Actually auto-mock returns jest.fn() for all props, so no error
```

**Fix:** prefer manual mocks or assert `toHaveBeenCalled` to catch unused mocks; disable automocking for critical modules.

---

## 20. Environment variables and global process state

```js
process.env.API_KEY = 'test';
// leaks to other tests / files
```

**Fix:** save/restore.

```js
const prev = process.env.API_KEY;
beforeEach(() => { process.env.API_KEY = 'test'; });
afterEach(() => { process.env.API_KEY = prev; });
```

---

## 21. Mocking `console` and suppressing real errors

Over-mocking hides failures.

```js
jest.spyOn(console, 'error').mockImplementation(() => {});
// later: real bug logs error but test passes
```

**Fix:** assert the call and restore.

```js
const spy = jest.spyOn(console, 'error').mockImplementation(() => {});
// ... act ...
expect(spy).toHaveBeenCalled();
spy.mockRestore();
```

---

## 22. Partial mocking with `jest.requireActual` recursion

Calling `requireActual` for the same module inside its own factory is fine, but for a module that re-exports the mocked module you can loop.

```js
jest.mock('./index', () => ({
  ...jest.requireActual('./index'), // if index re-exports mocked dep, may be stale
  foo: jest.fn(),
}));
```

**Fix:** mock leaf modules, not barrels; or mock in test setup before imports.

---

## 23. Mock implementation referencing itself (infinite recursion)

```js
const m = jest.fn();
m.mockImplementation(() => m()); // stack overflow
```

**Fix:** guard with a counter or use `mockReturnValueOnce`.

---

## 24. Mocking read-only globals (`window.location`, etc.)

```js
window.location.href = 'x'; // in jsdom, location is read-only
```

**Fix:**

```js
delete window.location;
window.location = { href: 'x', assign: jest.fn() };
// or
Object.defineProperty(window, 'location', { value: { href: 'x' }, writable: true });
```

---

## 25. Timers: `Date` constructor vs `Date.now`

Fake timers’ `setSystemTime` affects `new Date()` and `Date.now()`, but not `performance.now()` unless configured.

```js
jest.useFakeTimers().setSystemTime(new Date('2024-01-01T00:00:00Z'));
expect(new Date().toISOString()).toBe('2024-01-01T00:00:00.000Z');
expect(Date.now()).toBe(1704067200000);
```

Enable all timers you need:

```js
jest.useFakeTimers({ apis: ['setTimeout', 'Date'] });
```

---

## 26. Mocking `fs` / Node built-ins

Mocking `fs` globally can break Jest’s own module loading.

```js
jest.mock('fs'); // may break tooling
```

**Fix:** mock only needed methods, or use `memfs`, or spy on specific functions.

```js
jest.mock('fs', () => ({
  ...jest.requireActual('fs'),
  readFileSync: jest.fn(() => 'mocked'),
}));
```

---

## 27. Async test ordering and shared mocks

With `test.concurrent`, mock state races.

```js
test.concurrent('a', async () => { m.mockReturnValue(1); ... });
test.concurrent('b', async () => { m.mockReturnValue(2); ... }); // race
```

**Fix:** avoid mutating shared mocks in concurrent tests, or create per-test mocks.

---

## 28. Restoring after partial spies in loops

```js
for (const key of keys) {
  jest.spyOn(obj, key).mockReturnValue(0);
}
// restoreAllMocks restores all
afterEach(() => jest.restoreAllMocks());
```

---

## 29. Mocking modules imported by the test subject (not the test)

If `service.js` imports `db.js` at top level, mocking `db.js` in the test works only if mock is hoisted before `service` import.

```js
jest.mock('./db');          // hoisted
import { service } from './service'; // sees mocked db
```

Ordering matters; keep `jest.mock` above imports.

---

## 30. Verifying call arguments with matchers and async

```js
expect(m).toHaveBeenCalledWith(expect.objectContaining({ id: 1 }), expect.any(Function));
```

For async callbacks, ensure they were actually invoked:

```js
await waitFor(() => expect(m).toHaveBeenCalled());
```

---

## Quick checklist

- Hoist `jest.mock` above imports; use `jest.doMock` for late binding.
- Prefer spying on module namespaces, not destructured bindings.
- Use `mockClear`/`mockReset`/`mockRestore` deliberately; restore in `afterEach`.
- Bound `this` carefully; use regular functions for constructors.
- Mirror module shape (`__esModule`, default + named).
- Bound timer advancement; flush microtasks.
- Save/restore globals, env, console.
- Avoid shared mutable mock state across tests; isolate.

If you want, I can tailor this to Vitest or Sinon specifically, or show a full example test suite combining several of these.

## MVC in JavaScript (browser, no dependencies)

Below is a **complete, runnable single-file example** implementing classic MVC with an **Observer (pub/sub)** model. Save it as `mvc-todo.html` and open in any browser.

### Roles
- **Model** – owns data + business rules; emits `"change"` events. Knows nothing about the DOM.
- **View** – renders state; captures user input; exposes *callbacks* (`onAdd`, `onDelete`, `onToggle`) instead of talking to the Model directly.
- **Controller** – wires Model ↔ View: translates view events into model calls, and model changes into view re-renders.

### Data flow
```
User action → View → (callback) → Controller → Model → (notify) → View.render
```

### Code (`mvc-todo.html`)

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>MVC Todo – JavaScript</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 480px; margin: 2rem auto; }
    li { display: flex; align-items: center; gap: .5rem; margin: .25rem 0; }
    .done span { text-decoration: line-through; color: #888; }
    button { cursor: pointer; }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    /* ---------- Utilities ---------- */
    const esc = s => String(s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

    /* ---------- Model ---------- */
    class TodoModel {
      constructor() {
        this.items = [];          // { id, text, done }
        this.listeners = new Set();
      }

      // Observer API
      subscribe(fn) {
        this.listeners.add(fn);
        return () => this.listeners.delete(fn); // unsubscribe
      }
      _notify() {
        // notify with a shallow copy so views can't mutate internals
        this.listeners.forEach(fn => fn([...this.items]));
      }

      // Business logic
      add(text) {
        const trimmed = text.trim();
        if (!trimmed) return false;
        this.items.push({ id: Date.now() + Math.random(), text: trimmed, done: false });
        this._notify();
        return true;
      }
      remove(id) {
        const before = this.items.length;
        this.items = this.items.filter(i => i.id !== id);
        if (this.items.length !== before) this._notify();
      }
      toggle(id) {
        const item = this.items.find(i => i.id === id);
        if (item) { item.done = !item.done; this._notify(); }
      }
      // (optional) computed state lives in the model, not the view
      stats() {
        const total = this.items.length;
        const done = this.items.filter(i => i.done).length;
        return { total, done, remaining: total - done };
      }
    }

    /* ---------- View ---------- */
    class TodoView {
      constructor(root) {
        this.root = root;
        // Callbacks the controller will assign
        this.onAdd = null;
        this.onDelete = null;
        this.onToggle = null;
        this.render([]); // initial empty render
      }

      render(items) {
        const { total, done, remaining } = computeStats(items);

        this.root.innerHTML = `
          <h1>Todos</h1>
          <form id="addForm">
            <input id="input" placeholder="What needs doing?" autocomplete="off" />
            <button type="submit">Add</button>
          </form>
          <p class="stats">${done}/${total} done · ${remaining} remaining</p>
          <ul id="list"></ul>
        `;

        const list = this.root.querySelector('#list');
        items.forEach(item => {
          const li = document.createElement('li');
          li.className = item.done ? 'done' : '';
          li.innerHTML = `
            <input type="checkbox" ${item.done ? 'checked' : ''} data-id="${item.id}" />
            <span>${esc(item.text)}</span>
            <button data-del="${item.id}" aria-label="delete">✕</button>
          `;
          list.appendChild(li);
        });

        // Bind events (fresh elements each render, so no stale listeners)
        this._bindEvents();
      }

      _bindEvents() {
        const form = this.root.querySelector('#addForm');
        const input = this.root.querySelector('#input');

        form.addEventListener('submit', e => {
          e.preventDefault();
          const value = input.value;
          if (this.onAdd) this.onAdd(value);
          input.value = '';
          input.focus();
        });

        this.root.querySelectorAll('input[type="checkbox"]').forEach(cb => {
          cb.addEventListener('change', e => {
            if (this.onToggle) this.onToggle(Number(e.target.dataset.id));
          });
        });

        this.root.querySelectorAll('button[data-del]').forEach(btn => {
          btn.addEventListener('click', e => {
            if (this.onDelete) this.onDelete(Number(e.target.dataset.del));
          });
        });
      }
    }

    function computeStats(items) {
      const total = items.length;
      const done = items.filter(i => i.done).length;
      return { total, done, remaining: total - done };
    }

    /* ---------- Controller ---------- */
    class TodoController {
      constructor(model, view) {
        this.model = model;
        this.view = view;

        // View → Controller → Model
        view.onAdd    = text => model.add(text);
        view.onDelete = id   => model.remove(id);
        view.onToggle = id   => model.toggle(id);

        // Model → View (single source of truth for rendering)
        model.subscribe(items => view.render(items));
      }
    }

    /* ---------- Bootstrap ---------- */
    (function init() {
      const model = new TodoModel();
      const view = new TodoView(document.getElementById('app'));
      const controller = new TodoController(model, view);

      // Seed data (optional)
      model.add('Learn MVC');
      model.add('Ship the app');
      model.toggle(model.items[0].id);
    })();
  </script>
</body>
</html>
```

### Why this shape works

1. **Single source of truth** – only the Model mutates state; the View is a pure function of `items`.
2. **Decoupling** – the View never imports the Model; the Model never touches the DOM. You can swap the View (e.g., React, Canvas, CLI) without touching Model/Controller logic.
3. **Testability** – `TodoModel` is trivially unit-testable in Node; `TodoView` can be tested with a fake root + stubbed callbacks.
4. **Observer pattern** – `subscribe`/`_notify` means multiple views (or a logger) can react to one model change.

### Possible improvements (production)
- Use **event delegation** on `<ul>` instead of re-binding per item each render.
- Diff/patch the DOM (or use a framework) instead of `innerHTML` for large lists.
- Move `computeStats` into the Model (shown above as `model.stats()`) so business logic stays in one place.
- Persist via a Repository/Service layer injected into the Controller, keeping Model pure.

Run it: save the file, double-click, or `python3 -m http.server` and open `http://localhost:8000/mvc-todo.html`.

# MVC in JavaScript

**MVC** splits an app into three roles:

- **Model** – data, business rules, persistence. Knows nothing about the UI.
- **View** – renders the Model and captures user gestures. Knows nothing about business rules.
- **Controller** – the mediator: translates user input into Model updates and tells the View to re-render.

In JavaScript the roles are usually implemented with **classes/functions + an event bus/pub-sub** so the pieces stay decoupled.

---

## 1. The idea

```
User ──► View ──► Controller ──► Model
  ▲                               │
  └──────── (notify / re-render) ◄┘
```

Key rules of thumb:

| Role | Owns | Does NOT own |
|---|---|---|
| Model | state, validation, API calls | DOM, events from buttons |
| View | markup, rendering, input capture | data mutations, fetch logic |
| Controller | wiring, orchestration | rendering details, SQL/DB |

---

## 2. Syntax (vanilla browser example)

A tiny **todo list** using an event bus for decoupling.

### HTML
```html
<div id="app">
  <input placeholder="New todo" />
  <ul></ul>
</div>
```

### JavaScript
```js
// ---------- tiny event bus ----------
const bus = {
  listeners: {},
  on(event, cb) { (this.listeners[event] ||= []).push(cb); },
  emit(event, payload) { (this.listeners[event] || []).forEach(cb => cb(payload)); }
};

// ---------- Model ----------
class TodoModel {
  constructor() {
    this.items = [];
  }
  add(text) {
    if (!text.trim()) return;
    const item = { id: Date.now(), text: text.trim(), done: false };
    this.items.push(item);
    bus.emit('todos:changed', this.items);
    return item;
  }
  toggle(id) {
    const t = this.items.find(x => x.id === id);
    if (t) { t.done = !t.done; bus.emit('todos:changed', this.items); }
  }
}

// ---------- View ----------
class TodoView {
  constructor(root) {
    this.root = root;
    this.input = root.querySelector('input');
    this.list = root.querySelector('ul');

    // Model -> View (react to data changes)
    bus.on('todos:changed', items => this.render(items));
  }

  render(items) {
    this.list.innerHTML = items.map(t => `
      <li data-id="${t.id}" class="${t.done ? 'done' : ''}">${t.text}</li>
    `).join('');
  }

  // View -> Controller (delegate gestures)
  bindAdd(handler) {
    this.input.addEventListener('keydown', e => {
      if (e.key === 'Enter') { handler(e.target.value); e.target.value = ''; }
    });
  }
  bindToggle(handler) {
    this.list.addEventListener('click', e => {
      const li = e.target.closest('li');
      if (li) handler(Number(li.dataset.id));
    });
  }
}

// ---------- Controller ----------
class TodoController {
  constructor(model, view) {
    this.model = model;
    this.view = view;

    // wire user gestures -> model
    view.bindAdd(text => model.add(text));
    view.bindToggle(id => model.toggle(id));
  }
}

// ---------- bootstrap ----------
const app = new TodoController(
  new TodoModel(),
  new TodoView(document.getElementById('app'))
);
```

### Why this shape helps
- You can **swap the View** (e.g., React component, canvas renderer) without touching `TodoModel`.
- You can **unit-test the Model** with no DOM.
- The **Controller stays thin**; if it grows fat, logic probably belongs in the Model.

---

## 3. Typical use cases

| Scenario | How MVC fits |
|---|---|
| **Dashboards / admin panels** | Model = API + state; View = charts/tables; Controller = filters, pagination |
| **Complex forms/wizards** | Model = form data + validation; View = steps; Controller = navigation |
| **Offline-first apps** | Model = IndexedDB cache; View = optimistic UI; Controller = sync queue |
| **Backend (Express + EJS/Pug)** | Model = Mongoose/Sequelize; View = templates; Controller = route handlers |
| **Legacy jQuery/Backbone apps** | Backbone `Model/View/Router` is literally MVC |

---

## 4. Backend variant (Express)

```js
// model/userModel.js
const mongoose = require('mongoose');
const User = mongoose.model('User', new mongoose.Schema({ name: String, email: String }));
module.exports = User;

// controllers/userController.js
const User = require('../model/userModel');
exports.list = async (req, res) => {
  const users = await User.find().lean();
  res.render('users/index', { users }); // View
};

// routes/users.js
const express = require('express');
const c = require('../controllers/userController');
const r = express.Router();
r.get('/', c.list);
module.exports = r;
```

Here the **route** is effectively the controller, the **template** is the view, and the **Mongoose model** is the model.

---

## 5. Modern relatives you’ll actually meet

| Pattern | Where you see it | Difference from classic MVC |
|---|---|---|
| **MVVM** (Angular, Vue) | Two-way binding; ViewModel exposes observable state | View binds directly to ViewModel; less explicit controller |
| **Component-based** (React) | UI = `f(state)`; state often in Redux/Zustand | View *is* the component; “controller” logic lives in hooks/reducers |
| **Flux/Redux** | Unidirectional data flow | Single store (Model) + actions (Controller) + selectors (View) |

**Practical advice:** Don’t force MVC onto React/Angular. Use MVC when you have a clear **data layer**, a **rendering layer**, and **orchestration** that changes independently—common in vanilla JS, Backbone, or server-rendered apps.

---

## 6. Common mistakes to avoid

1. **Fat controllers** – move validation/persistence into the Model.
2. **View touching the Model directly** – route through the Controller or an event bus.
3. **No single source of truth** – keep authoritative state in the Model; the View is a projection.
4. **Tight coupling via globals** – use constructor injection or a small event bus as shown.

---

### Minimal checklist to refactor toward MVC
1. Extract all `fetch`/DB calls into a `*Model` class.
2. Extract all DOM writes into a `*View` class that only renders given data.
3. Put event wiring in a `*Controller` that calls Model methods and lets the View subscribe to Model changes.
4. Communicate via events or injected callbacks—not global variables.

That gives you testable, swappable pieces while keeping the JavaScript idiomatic.

## Typical MVC mistake

A common mistake is letting the **Model** reach into the DOM and letting the **View** own business rules. That makes the model impossible to test without a browser, and allows invalid data to enter the system through any path that bypasses the view.

### Mistaken version

```js
class TodoModel {
  constructor() {
    this.todos = [];
  }

  addTodo(text) {
    // Business rule-ish check, but only enforced here if called this way.
    if (!text.trim()) throw new Error("Todo text is required");

    const todo = { text: text.trim(), done: false };
    this.todos.push(todo);

    // Mistake 1: the model creates and updates DOM nodes.
    const li = document.createElement("li");
    li.textContent = todo.text;
    document.querySelector("#todo-list").appendChild(li);
  }
}

class TodoView {
  constructor() {
    this.input = document.querySelector("#todo-input");
    this.button = document.querySelector("#add-todo");
  }

  // Mistake 2: the view owns a domain rule ("spam" is not a UI concept).
  canSubmit() {
    const value = this.input.value.trim();
    return value.length > 3 && !value.toLowerCase().includes("spam");
  }
}

class TodoController {
  constructor(model, view) {
    this.model = model;
    this.view = view;

    this.view.button.addEventListener("click", () => {
      // The controller delegates validation to the view.
      if (this.view.canSubmit()) {
        this.model.addTodo(this.view.input.value);
      }
    });
  }
}
```

### What is wrong

1. **Model knows about the DOM.**  
   `TodoModel.addTodo()` creates `<li>` elements and appends them to `#todo-list`. The model should only represent and protect data. If the UI changes, or if todos are loaded from an API, the model now has irrelevant rendering code and becomes hard to unit test.

2. **View owns a business rule.**  
   `TodoView.canSubmit()` decides that `"spam"` is invalid. That rule belongs to the domain/model layer. If another controller, background sync, or test calls `model.addTodo("spam todo")`, the rule is bypassed.

3. **Validation is split and inconsistent.**  
   Empty text is checked in the model, while length and spam checks are checked in the view. The model can end up containing invalid data depending on how it is used.

4. **No clear rendering boundary.**  
   Because rendering happens inside `addTodo()`, the view cannot re-render the whole list after deletion, toggling, filtering, or initial load without duplicating model logic.

---

### Corrected version

```js
class TodoModel {
  constructor() {
    this.todos = [];
    this.listeners = new Set();
  }

  onChange(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  _emit() {
    for (const listener of this.listeners) {
      listener(this.todos);
    }
  }

  addTodo(text) {
    const value = text.trim();

    // All domain invariants live in the model.
    if (!value) {
      throw new Error("Todo text is required");
    }
    if (value.length <= 3) {
      throw new Error("Todo text must be longer than 3 characters");
    }
    if (value.toLowerCase().includes("spam")) {
      throw new Error("Todo text contains forbidden content");
    }

    const todo = {
      id: crypto.randomUUID(),
      text: value,
      done: false,
    };

    // Immutable update makes changes easy to observe.
    this.todos = [...this.todos, todo];
    this._emit();

    return todo;
  }

  toggleTodo(id) {
    this.todos = this.todos.map((todo) =>
      todo.id === id ? { ...todo, done: !todo.done } : todo
    );
    this._emit();
  }
}

class TodoView {
  constructor(root) {
    this.root = root;
    this.list = root.querySelector("#todo-list");
    this.input = root.querySelector("#todo-input");
    this.button = root.querySelector("#add-todo");
    this.error = root.querySelector("#todo-error");
  }

  render(todos) {
    this.list.innerHTML = "";

    for (const todo of todos) {
      const li = document.createElement("li");
      li.textContent = todo.text;

      if (todo.done) {
        li.classList.add("done");
      }

      const toggleButton = document.createElement("button");
      toggleButton.type = "button";
      toggleButton.dataset.id = todo.id;
      toggleButton.textContent = todo.done ? "Undo" : "Done";

      li.appendChild(toggleButton);
      this.list.appendChild(li);
    }
  }

  getInputValue() {
    return this.input.value;
  }

  clearInput() {
    this.input.value = "";
  }

  showError(message) {
    this.error.textContent = message;
  }

  clearError() {
    this.error.textContent = "";
  }
}

class TodoController {
  constructor(model, view) {
    this.model = model;
    this.view = view;

    // The view renders whenever the model changes.
    this.unsubscribe = model.onChange((todos) => {
      this.view.render(todos);
    });

    this.view.button.addEventListener("click", () => {
      this.handleAdd();
    });

    // Event delegation keeps toggle handling in the controller.
    this.view.list.addEventListener("click", (event) => {
      const button = event.target.closest("button[data-id]");
      if (button) {
        this.model.toggleTodo(button.dataset.id);
      }
    });

    // Initial render.
    this.view.render(model.todos);
  }

  handleAdd() {
    this.view.clearError();

    try {
      this.model.addTodo(this.view.getInputValue());
      this.view.clearInput();
    } catch (error) {
      this.view.showError(error.message);
    }
  }

  destroy() {
    this.unsubscribe?.();
  }
}
```

### Example usage

```js
const model = new TodoModel();
const view = new TodoView(document);
const controller = new TodoController(model, view);
```

### Why the corrected version is better

- **Model is UI-agnostic.**  
  It stores todos, enforces all invariants, emits change events, and never touches `document`. It can be tested with plain JavaScript.

- **View is presentation-only.**  
  It renders whatever todos it receives and exposes small UI helpers such as `getInputValue()`, `showError()`, and `clearInput()`. It does not decide what data is valid.

- **Controller mediates.**  
  It listens for user actions, calls model methods, catches domain errors, and updates the view. Business rules are not duplicated between UI and domain code.

- **Rendering is centralized.**  
  `TodoView.render()` can redraw the entire list after adding, toggling, deleting, filtering, or loading data. The model does not need to know how each item is displayed.

- **State changes are observable.**  
  The model emits updates, so the view stays synchronized without the model directly manipulating DOM nodes.

This separation keeps each layer focused: the model protects data, the view displays data, and the controller connects user input to both.

# Common MVC Pitfalls in JavaScript

Below are frequent mistakes, why they hurt, and idiomatic fixes. Examples use a small browser-style MVC, but the principles apply to Node/Express and frameworks too.

---

## 1. Fat controllers (business logic in the controller)

**Pitfall:** controllers calculate discounts, validate rules, format data, etc. They become hard to test and reuse.

```js
// BAD: controller does domain work
class OrderController {
  constructor(model, view) {
    this.model = model;
    this.view = view;
  }

  checkout(cart) {
    // business logic leaked into controller
    const total = cart.reduce((s, i) => s + i.price * i.qty, 0);
    const discount = total > 100 ? 0.1 : 0;
    const final = total * (1 - discount);
    this.model.setTotal(final);
    this.view.renderReceipt(final);
  }
}
```

```js
// GOOD: model owns domain rules; controller only coordinates
class Order {
  constructor(items) { this.items = items; }

  total() {
    return this.items.reduce((s, i) => s + i.price * i.qty, 0);
  }

  checkoutTotal() {
    const base = this.total();
    const discount = base > 100 ? 0.1 : 0;
    return base * (1 - discount);
  }
}

class OrderController {
  constructor(model, view) {
    this.model = model;
    this.view = view;
  }

  checkout() {
    const final = this.model.checkoutTotal();
    this.model.setTotal(final);
    this.view.renderReceipt(final);
  }
}
```

---

## 2. Views reaching into models (tight coupling)

**Pitfall:** views fetch or mutate model state directly, making them impossible to reuse or test.

```js
// BAD: view knows model internals
class CartView {
  constructor(model) { this.model = model; }

  render() {
    const items = this.model.items.filter(i => i.qty > 0);
    document.querySelector('#cart').innerHTML =
      items.map(i => `<li>${i.name}: ${i.qty}</li>`).join('');
  }
}
```

```js
// GOOD: controller passes a plain view-model / state snapshot
class CartView {
  render(state) {
    const items = state.items.filter(i => i.qty > 0);
    document.querySelector('#cart').innerHTML =
      items.map(i => `<li>${i.name}: ${i.qty}</li>`).join('');
  }
}

class CartController {
  constructor(model, view) {
    this.model = model;
    this.view = view;
  }

  refresh() {
    this.view.render({ items: this.model.getItems() });
  }
}
```

---

## 3. Mutable shared model state and accidental aliasing

**Pitfall:** returning internal arrays/objects lets views/controllers mutate model state without going through methods.

```js
// BAD: leaking internal reference
class TodoModel {
  constructor() { this.todos = []; }
  getTodos() { return this.todos; } // same reference
}

const m = new TodoModel();
const t = m.getTodos();
t.push({ text: 'hack', done: false }); // model changed silently
```

```js
// GOOD: return copies / expose read-only views
class TodoModel {
  constructor() { this.todos = []; }
  getTodos() { return this.todos.map(t => ({ ...t })); }
  addTodo(todo) { this.todos.push({ ...todo }); }
}
```

---

## 4. Event listener leaks in views

**Pitfall:** views subscribe to model events but never unsubscribe; destroyed views keep firing.

```js
// BAD: no cleanup
class UserView {
  constructor(model) {
    this.model = model;
    this.model.on('change', () => this.render());
  }
  // when view removed from DOM, listener remains
}
```

```js
// GOOD: explicit destroy / AbortController / bound handler
class UserView {
  constructor(model) {
    this.model = model;
    this.controller = new AbortController();
    this.onChange = () => this.render();
    this.model.on('change', this.onChange, { signal: this.controller.signal });
  }

  destroy() {
    this.controller.abort(); // removes listener
  }
}
```

If your event emitter doesn’t support `AbortSignal`, keep the handler reference and call `off`:

```js
destroy() {
  this.model.off('change', this.onChange);
}
```

---

## 5. Two-way binding loops

**Pitfall:** model updates view, view updates model, and both trigger each other endlessly.

```js
// BAD: circular updates
class ProfileModel {
  constructor() { this.name = ''; }
  setName(v) { this.name = v; this.emit('change'); }
}

class ProfileView {
  constructor(model) {
    this.model = model;
    this.input = document.querySelector('#name');
    this.model.on('change', () => { this.input.value = this.model.name; });
    this.input.addEventListener('input', e => this.model.setName(e.target.value));
  }
}
```

```js
// GOOD: guard against redundant updates / unidirectional flow
class ProfileModel {
  constructor() { this.name = ''; }
  setName(v) {
    if (v === this.name) return; // no-op guard
    this.name = v;
    this.emit('change');
  }
}

class ProfileView {
  constructor(model) {
    this.model = model;
    this.input = document.querySelector('#name');
    this.rendering = false;

    this.model.on('change', () => {
      if (this.rendering) return;
      this.rendering = true;
      this.input.value = this.model.name;
      this.rendering = false;
    });

    this.input.addEventListener('input', e => {
      if (this.rendering) return;
      this.model.setName(e.target.value);
    });
  }
}
```

Often a cleaner fix is to use one-way data flow: view dispatches actions, controller/model updates, view re-renders from state.

---

## 6. Async races in controllers

**Pitfall:** firing multiple async operations without cancellation or ordering can produce stale renders.

```js
// BAD: last request may not be last to resolve
class SearchController {
  constructor(model, view) {
    this.model = model;
    this.view = view;
  }

  async search(q) {
    const results = await this.model.search(q);
    this.view.render(results); // stale if older request resolves later
  }
}
```

```js
// GOOD: track latest request / abort previous
class SearchController {
  constructor(model, view) {
    this.model = model;
    this.view = view;
    this.requestId = 0;
  }

  async search(q) {
    const id = ++this.requestId;
    const results = await this.model.search(q);
    if (id !== this.requestId) return; // stale
    this.view.render(results);
  }
}
```

Or use `AbortController` for fetch:

```js
async search(q, signal) {
  const res = await fetch(`/api/search?q=${encodeURIComponent(q)}`, { signal });
  return res.json();
}
```

---

## 7. God models

**Pitfall:** one model handles users, carts, settings, caching, API calls, validation.

```js
// BAD: one model does everything
class AppModel {
  user = null;
  cart = [];
  settings = {};
  async login() { /* auth */ }
  async loadCart() { /* api */ }
  validateEmail() { /* ... */ }
  saveSettings() { /* ... */ }
}
```

```js
// GOOD: split by bounded context
class UserModel { /* auth, profile */ }
class CartModel { /* items, totals */ }
class SettingsModel { /* prefs */ }

class AppController {
  constructor(user, cart, settings, view) {
    this.user = user;
    this.cart = cart;
    this.settings = settings;
    this.view = view;
  }
}
```

---

## 8. Views containing routing or business decisions

**Pitfall:** view decides navigation or permissions instead of controller/router.

```js
// BAD: view triggers route based on data
class DashboardView {
  render(user) {
    if (!user.isAdmin) location.href = '/login';
    document.querySelector('#app').innerHTML = '<h1>Dashboard</h1>';
  }
}
```

```js
// GOOD: controller decides flow; view only renders
class DashboardController {
  constructor(userModel, view, router) {
    this.userModel = userModel;
    this.view = view;
    this.router = router;
  }

  show() {
    if (!this.userModel.isAdmin()) {
      this.router.go('/login');
      return;
    }
    this.view.render(this.userModel.getProfile());
  }
}
```

---

## 9. DOM queries and rendering inside models/controllers

**Pitfall:** non-UI layers depend on `document`, making logic untestable.

```js
// BAD: model reads DOM
class FormModel {
  validate() {
    const email = document.querySelector('#email').value;
    return email.includes('@');
  }
}
```

```js
// GOOD: pure functions / injected values
class FormModel {
  validate(email) {
    return typeof email === 'string' && email.includes('@');
  }
}

class FormController {
  constructor(model, view) {
    this.model = model;
    this.view = view;
  }

  submit() {
    const email = this.view.getEmail();
    if (!this.model.validate(email)) {
      this.view.showError('Invalid email');
      return;
    }
    // proceed
  }
}
```

---

## 10. Over-rendering the whole view on every change

**Pitfall:** rebuilding large DOM trees on each tiny model update causes jank.

```js
// BAD: full re-render for one item
class ListView {
  constructor(model) {
    this.model = model;
    this.model.on('change', () => this.renderAll());
  }

  renderAll() {
    document.querySelector('#list').innerHTML =
      this.model.getItems().map(i => `<li>${i.text}</li>`).join('');
  }
}
```

```js
// GOOD: granular updates / virtual DOM / keyed patching
class ListView {
  constructor(model) {
    this.model = model;
    this.model.on('itemAdded', item => this.appendItem(item));
    this.model.on('itemRemoved', id => this.removeItem(id));
  }

  appendItem(item) {
    const li = document.createElement('li');
    li.dataset.id = item.id;
    li.textContent = item.text;
    document.querySelector('#list').appendChild(li);
  }

  removeItem(id) {
    document.querySelector(`[data-id="${id}"]`)?.remove();
  }
}
```

In real apps, prefer a rendering library (React/Vue/Svelte) or a small keyed diff.

---

## 11. Missing single source of truth

**Pitfall:** same data duplicated in model, view state, and URL; they drift.

```js
// BAD: view keeps its own copy
class PageView {
  constructor() { this.localFilter = 'all'; }
  setFilter(f) { this.localFilter = f; this.render(); }
}
```

```js
// GOOD: model/query state is source of truth; view derives from it
class FilterModel {
  constructor() { this.filter = 'all'; }
  setFilter(f) { this.filter = f; this.emit('change'); }
}

class PageView {
  constructor(model) {
    this.model = model;
    this.model.on('change', () => this.render(this.model.filter));
  }
  render(filter) { /* ... */ }
}
```

---

## 12. Global event bus spaghetti

**Pitfall:** components communicate through a global bus, making data flow invisible and debugging hard.

```js
// BAD: hidden dependencies
const bus = new EventTarget();
bus.addEventListener('user:login', e => cartModel.load(e.detail.id));
bus.addEventListener('cart:changed', () => headerView.updateBadge());
```

```js
// GOOD: explicit controller wiring or a small store with subscriptions
class AppController {
  constructor(userModel, cartModel, headerView) {
    this.userModel = userModel;
    this.cartModel = cartModel;
    this.headerView = headerView;

    this.userModel.on('login', user => {
      this.cartModel.loadFor(user.id);
    });

    this.cartModel.on('change', () => {
      this.headerView.updateBadge(this.cartModel.count());
    });
  }
}
```

---

## 13. Not handling loading/error states

**Pitfall:** controller only handles success; views show stale or broken UI.

```js
// BAD
async loadUser(id) {
  const user = await this.model.fetchUser(id);
  this.view.render(user);
}
```

```js
// GOOD: explicit states
async loadUser(id) {
  this.view.render({ status: 'loading' });
  try {
    const user = await this.model.fetchUser(id);
    this.view.render({ status: 'success', user });
  } catch (err) {
    this.view.render({ status: 'error', message: err.message });
  }
}
```

---

## 14. Framework-specific code leaking across layers

**Pitfall:** controllers import React hooks, Express `req/res`, etc., making core logic framework-bound.

```js
// BAD: controller knows Express response
app.get('/users', async (req, res) => {
  const users = await userModel.all();
  res.json(users); // transport concern in controller
});
```

```js
// GOOD: separate HTTP adapter from application controller
class UserController {
  constructor(userModel) { this.userModel = userModel; }
  async list() { return this.userModel.all(); }
}

// route adapter
app.get('/users', async (req, res) => {
  const controller = new UserController(userModel);
  const users = await controller.list();
  res.json(users);
});
```

