### Why this is good MVC

- The Model has no DOM code.
- The View has no business logic.
- The Controller is the only place that knows both.
- You can later replace the View (for example, with a React or CLI view) without rewriting the Model.

## MVC in JavaScript — interview-style answer

### 1. What MVC is (and isn't)

**MVC** splits an app into three roles with a strict dependency rule:

| Role | Responsibility | Knows about |
|---|---|---|
| **Model** | Data + business rules + state transitions. Emits change events. | Nothing (pure) |
| **View** | Renders UI, captures raw DOM events, exposes *intent* callbacks (`onAdd`, `onToggle`). | Nothing about Model |
| **Controller** | Wires View intents → Model actions, and Model changes → View re-render. | Both |

**Data flow (unidirectional):**

```
User clicks  →  View emits intent  →  Controller calls Model
                                              ↓
View re-renders  ←  Controller receives change  ←  Model updates + notifies
```

Key interview points:
- **Model is the source of truth**, not the DOM.
- **View is dumb** — it renders what it's given and reports *what the user did*, not *what should happen*.
- **Controller is thin glue** — if it accumulates business logic, that logic belongs in the Model.
- In modern JS (React/Vue/Angular) the roles are often merged (e.g., React components blur View+Controller), but the *principle* — separate state from rendering — still applies.

---

### 2. Core implementation (vanilla JS, one file)

```js
// ============================================================
// MODEL — pure state + business rules + observer (pub/sub)
// ============================================================
class TodoModel {
  constructor() {
    this.todos = [];          // source of truth
    this.listeners = new Set(); // observers (views/controllers)
  }

  // --- observer API ---
  subscribe(listener) {
    this.listeners.add(listener);
    // return an unsubscribe handle (good hygiene)
    return () => this.listeners.delete(listener);
  }
  _notify() {
    // hand out a shallow copy so callers can't mutate internals
    const snapshot = this.todos.map(t => ({ ...t }));
    this.listeners.forEach(l => l(snapshot));
  }

  // --- business logic ---
  add(text) {
    const trimmed = text.trim();
    if (!trimmed) return; // guard: no empty todos
    this.todos.push({ id: Date.now(), text: trimmed, done: false });
    this._notify();
  }

  toggle(id) {
    const todo = this.todos.find(t => t.id === id);
    if (todo) { todo.done = !todo.done; this._notify(); }
  }

  remove(id) {
    const before = this.todos.length;
    this.todos = this.todos.filter(t => t.id !== id);
    if (this.todos.length !== before) this._notify();
  }

  // derived state lives in the model, not the view
  get stats() {
    return {
      total: this.todos.length,
      done:  this.todos.filter(t => t.done).length,
    };
  }
}

// ============================================================
// VIEW — DOM rendering + raw event capture, exposes intents
// ============================================================
class TodoView {
  constructor(root) {
    this.root = root;
    this._renderShell();
    // intent callbacks are wired by the controller
    this.onAdd = null;
    this.onToggle = null;
    this.onRemove = null;
  }

  _renderShell() {
    this.root.innerHTML = `
      <form class="add-form">
        <input class="input" placeholder="New todo..." />
        <button type="submit">Add</button>
      </form>
      <ul class="list"></ul>
      <p class="stats"></p>
    `;
    this.form  = this.root.querySelector('.add-form');
    this.input = this.root.querySelector('.input');
    this.list  = this.root.querySelector('.list');
    this.stats = this.root.querySelector('.stats');

    // capture raw DOM events, translate to intents
    this.form.addEventListener('submit', e => {
      e.preventDefault();
      const text = this.input.value;
      this.input.value = '';
      this.onAdd?.(text);
    });

    // event delegation: one listener for all items
    this.list.addEventListener('click', e => {
      const li = e.target.closest('li[data-id]');
      if (!li) return;
      const id = Number(li.dataset.id);
      if (e.target.matches('.toggle')) this.onToggle?.(id);
      if (e.target.matches('.remove')) this.onRemove?.(id);
    });
  }

  // pure render: given data, produce DOM. No state, no logic.
  render(todos) {
    this.list.innerHTML = todos.map(t => `
      <li data-id="${t.id}" class="${t.done ? 'done' : ''}">
        <span class="toggle">${t.done ? '☑' : '☐'}</span>
        <span class="text">${this._escape(t.text)}</span>
        <button class="remove">✕</button>
      </li>
    `).join('');
  }

  renderStats(stats) {
    this.stats.textContent = `${stats.done}/${stats.total} done`;
  }

  _escape(s) {
    return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }
}

// ============================================================
// CONTROLLER — thin glue between Model and View
// ============================================================
class TodoController {
  constructor(model, view) {
    this.model = model;
    this.view  = view;

    // Model changes → View re-render
    this.unsubscribe = model.subscribe(todos => {
      this.view.render(todos);
      this.view.renderStats(this.model.stats);
    });

    // View intents → Model actions
    this.view.onAdd    = text => this.model.add(text);
    this.view.onToggle = id   => this.model.toggle(id);
    this.view.onRemove = id   => this.model.remove(id);

    // initial paint
    this.view.render(this.model.todos);
    this.view.renderStats(this.model.stats);
  }

  // cleanup hook (important in SPAs to avoid leaks)
  destroy() {
    this.unsubscribe();
    this.view.onAdd = this.view.onToggle = this.view.onRemove = null;
  }
}

// ============================================================
// BOOTSTRAP
// ============================================================
const app = document.querySelector('#app');
const model = new TodoModel();
const view  = new TodoView(app);
const controller = new TodoController(model, view);

// (optional) seed data
model.add('Learn MVC');
model.add('Write clean code');
```

### 3. Why this design earns points in an interview

- **Testability**: `TodoModel` has zero DOM deps — unit test it with plain JS. `TodoView.render` is a pure function of data.
- **No memory leaks**: controller returns an `unsubscribe` handle and a `destroy()` method.
- **XSS safety**: view escapes text before injection.
- **Event delegation**: one listener handles N items → O(1) listeners regardless of list size.
- **Derived state in model** (`stats` getter) — view never recomputes business logic.
- **Swap-ability**: you could replace `TodoView` with a Canvas/CLI view without touching Model or Controller wiring beyond the constructor.

### 4. Common follow-up questions & answers

- **"Where does routing go?"** → A router is just another controller-ish component that swaps views/models; keep it out of the model.
- **"How do you handle async (fetch)?"** → Model exposes async methods (`async load()`) that update state and notify; controller awaits or chains `.then`. View shows loading state via a `status` field in model.
- **"MVC vs MVVM?"** → MVVM replaces Controller with data-binding; View binds directly to Model via a ViewModel. MVC keeps an explicit mediator (Controller), which is easier to trace in vanilla JS.
- **"Isn't this over-engineered for a small app?"** → Yes. For a counter, a single component is fine. MVC pays off when state has multiple consumers or complex transitions.

### 5. Minimal HTML to run it

```html
<!DOCTYPE html>
<html>
  <head>
    <style>
      .done .text { text-decoration: line-through; opacity: .6; }
      li { list-style: none; padding: 4px; }
      .toggle { cursor: pointer; margin-right: 8px; }
    </style>
  </head>
  <body>
    <div id="app"></div>
    <script type="module" src="mvc.js"></script>
  </body>
</html>
```

Drop the JS into `mvc.js` and open the page — you have a working, testable MVC todo app.

# Edge cases in JavaScript MVC (and how to handle them)

The examples below use a tiny, framework-agnostic MVC skeleton. The same pitfalls appear in React/Redux, Vue, Angular, etc.; the fixes translate directly.

```js
// Minimal shared skeleton used by the examples
class Observable {
  constructor(initial) {
    this._state = initial;
    this._listeners = new Set();
  }
  get() { return this._state; }
  set(next) {
    const prev = this._state;
    this._state = typeof next === 'function' ? next(prev) : next;
    // notify on a copy so listeners can unsubscribe during iteration
    for (const fn of [...this._listeners]) fn(this._state, prev);
  }
  subscribe(fn) { this._listeners.add(fn); return () => this._listeners.delete(fn); }
}

class View {
  constructor(model, root) {
    this.model = model;
    this.root = root;
    this._unsub = model.subscribe(s => this.render(s));
  }
  render(state) { /* override */ }
  destroy() { this._unsub(); this.root.replaceChildren(); }
}
```

---

## 1. Stale references after mutation

**Problem.** If a view (or controller) caches a reference to a nested object and the model later replaces it, the cached reference is stale. Mutating it silently corrupts state; reading it shows old data.

```js
// BUG
const user = model.get().user;          // same reference
model.set(s => ({ ...s, user: { name: 'Grace' } }));
console.log(user.name);                 // 'Ada' — stale, no error thrown
```

**Fix.** Treat state as immutable; never cache nested references across a `set`. Read through the model at use time, or return frozen snapshots.

```js
class Model extends Observable {
  get() { return Object.freeze(structuredClone(this._state)); }
}
// always re-read
const name = model.get().user.name;
```

---

## 2. Reentrant update loops (infinite render)

**Problem.** Input event → controller updates model → model notifies → view re-renders → input event fires again (or focus/cursor resets). Classic with controlled inputs.

```js
// BUG: render() innerHTML wipes the <input>, cursor jumps, keydown re-fires
view.render = (s) => {
  view.root.innerHTML = `<input id="q" value="${s.query}">`;
};
input.addEventListener('input', e => controller.setQuery(e.target.value));
```

**Fix.** Either (a) patch only the changed attribute without replacing the node, or (b) guard reentrancy and use uncontrolled + read-on-blur.

```js
// Patch-only approach
render(s) {
  const el = this.root.querySelector('#q');
  if (el && el.value !== s.query) el.value = s.query;
  // only touch DOM when value actually differs
}
```

Add a reentrancy guard for any path that can recurse:

```js
let updating = false;
model.subscribe(s => {
  if (updating) return;
  updating = true;
  try { view.render(s); } finally { updating = false; }
});
```

---

## 3. Out-of-order async updates

**Problem.** Two requests resolve in reverse order; the older one overwrites the newer.

```js
// BUG
async function loadUser(id) {
  const r = await fetch(`/users/${id}`);
  model.set(await r.json()); // late, stale response wins
}
loadUser(1); loadUser(2); // if /users/1 resolves last, UI shows user 1
```

**Fix.** Use a request token or `AbortController` so only the latest request commits.

```js
let requestId = 0;
async function loadUser(id) {
  const myId = ++requestId;
  const r = await fetch(`/users/${id}`);
  const data = await r.json();
  if (myId !== requestId) return; // stale, discard
  model.set(data);
}

// or cancel outright:
const ctrl = new AbortController();
fetch(url, { signal: ctrl.signal });
// on new request: ctrl.abort();
```

---

## 4. Memory leaks from subscriptions

**Problem.** Views subscribe but never unsubscribe; destroyed views still render, touching detached DOM and leaking memory. Very common in single-page apps.

```js
// BUG: no destroy(); listeners accumulate across route changes
class UserView extends View {
  constructor(m, root) { super(m, root); }
  // forgot unsubscribe
}
```

**Fix.** Always return and store the unsubscribe; destroy in reverse order of creation (unsubscribe first, then DOM).

```js
class UserView extends View {
  destroy() {
    this._unsub();                 // 1. stop receiving updates
    this.root.replaceChildren();   // 2. then tear down DOM
    this.root = null;
  }
}
```

Also remove DOM event listeners, or use a single delegated listener per view root:

```js
this.root.addEventListener('click', this._onClick = e => { ... });
// in destroy:
this.root.removeEventListener('click', this._onClick);
```

---

## 5. XSS via template interpolation

**Problem.** Rendering model strings with `innerHTML` executes injected markup.

```js
// BUG
view.root.innerHTML = `<h1>${model.get().name}</h1>`;
// name === '<img src=x onerror="steal()">'
```

**Fix.** Use `textContent` for text, and a sanitizer/whitelist for any HTML you must render. Prefer building nodes.

```js
const h1 = document.createElement('h1');
h1.textContent = model.get().name; // safe
view.root.replaceChildren(h1);
```

If rich text is required, sanitize with DOMPurify before `innerHTML`.

---

## 6. Partial updates destroying focus / scroll / selection

**Problem.** Re-rendering a subtree replaces inputs, losing focus, caret position, scroll, and any in-flight composition (IME).

```js
// BUG: every keystroke rebuilds the list including the active field
render(s) {
  list.innerHTML = s.items.map(i => `<li><input value="${i.title}"></li>`).join('');
}
```

**Fix.** Diff and patch instead of replacing; key nodes; preserve focus.

```js
render(s) {
  // update only text nodes / attributes that changed
  for (const [i, item] of s.items.entries()) {
    const li = list.children[i] ?? createLi();
    const input = li.querySelector('input');
    if (document.activeElement !== input && input.value !== item.title) {
      input.value = item.title;
    }
    // move focus back if it was lost
    if (wasFocused && document.activeElement !== input) input.focus();
  }
  // remove extras
  while (list.children.length > s.items.length) list.lastChild.remove();
}
```

For production, use a diffing library (morphdom, lit-html) rather than hand-rolling.

---

## 7. Double submission / race on controller actions

**Problem.** User clicks “Save” twice before the first promise settles; two writes, conflicting state, duplicate rows.

```js
// BUG
saveBtn.addEventListener('click', async () => {
  await api.save(model.get()); // no guard
});
```

**Fix.** Disable + track in-flight with a token; ignore stale completions.

```js
let saving = false;
saveBtn.addEventListener('click', async () => {
  if (saving) return;
  saving = true;
  saveBtn.disabled = true;
  try {
    await api.save(model.get());
    status.textContent = 'Saved';
  } catch (e) {
    status.textContent = 'Error: ' + e.message;
  } finally {
    saving = false;
    saveBtn.disabled = false;
  }
});
```

Also make the server idempotent (idempotency keys) so retries are safe.

---

## 8. Non-transactional multi-field updates

**Problem.** Updating fields one at a time emits a notification per field; a view renders intermediate invalid state (e.g., email set, password not yet). If validation throws midway, the model is half-updated.

```js
// BUG
model.set(s => ({ ...s, email }));
model.set(s => ({ ...s, password })); // if this throws, email already committed
```

**Fix.** Validate first, then commit as a single patch; optionally support rollback.

```js
function updateUser(patch) {
  const prev = model.get();
  // validate against the *merged* candidate, not partial
  const candidate = { ...prev, ...patch };
  const errors = validate(candidate);
  if (Object.keys(errors).length) {
    view.showErrors(errors);
    return false; // no state changed
  }
  model.set(candidate); // single notification
  return true;
}
```

For true atomicity, snapshot + restore on failure:

```js
const snapshot = model.get();
try { model.set(applyPatch); }
catch (e) { model.set(snapshot); throw e; }
```

---

## 9. Null / undefined in nested paths

**Problem.** Accessing `model.get().user.profile.name` throws when `profile` is null, crashing the whole render and leaving the UI blank.

```js
// BUG
render(s) { title.textContent = s.user.profile.name; } // TypeError if profile null
```

**Fix.** Defensive access + schema defaults + error boundary around render.

```js
render(s) {
  try {
    title.textContent = s?.user?.profile?.name ?? 'Anonymous';
  } catch (e) {
    console.error('render failed', e);
    title.textContent = '—';
  }
}
```

Also normalize on ingest so the model never holds `undefined` where an object is expected:

```js
model.set(raw => ({ ...raw, user: raw.user ?? { profile: null } }));
```

---

## 10. Destroy ordering and dangling subscriptions

**Problem.** Destroying view first leaves a model subscription pointing at a dead view; the next change calls `render` on null DOM → crash. Or destroying model first leaves views subscribed to a dead object.

```js
// BUG
view.destroy();          // removes DOM
model.set({ ... });     // subscription still fires → this.root is null → crash
```

**Fix.** Establish a single owner and a strict order: unsubscribe → detach DOM → null references. Make render a no-op after destroy.

```js
class SafeView extends View {
  constructor(m, root) { super(m, root); this._alive = true; }
  render(s) {
    if (!this._alive || !this.root) return;
    // ...
  }
  destroy() {
    this._alive = false;
    this._unsub?.();
    this._unsub = null;
    this.root?.replaceChildren();
    this.root = null;
    this.model = null;
  }
}
```

---

## 11. Observer mutation during notification

**Problem.** A listener unsubscribes (or a new view subscribes) while `notify` is iterating the listener set → skipped callbacks or `ConcurrentModification`-style bugs. Also reentrant `set` inside a listener.

```js
// BUG: iterating a Set/Array while mutating it
notify() { for (const fn of this.listeners) fn(); } // listener removes itself → skip next
```

**Fix.** Iterate a snapshot; guard reentrancy.

```js
set(next) {
  if (this._notifying) { this._pending = next; return; } // or queue
  this._notifying = true;
  try {
    const prev = this._state;
    this._state = typeof next === 'function' ? next(prev) : next;
    for (const fn of [...this._listeners]) fn(this._state, prev);
  } finally {
    this._notifying = false;
    if (this._pending) { const p = this._pending; this._pending = null; this.set(p); }
  }
}
```

---

## 12. Batching / notification storms

**Problem.** One user action triggers several model writes → several renders per frame → jank. Multiple views on the same model amplify it.

```js
// BUG: 3 sets → 3 renders → 3 layout passes
controller.addTag('a'); controller.addTag('b'); controller.save();
```

**Fix.** Batch updates into a single notification, e.g., via microtask or explicit transaction.

```js
class BatchedModel extends Observable {
  constructor(initial) { super(initial); this._queue = []; this._flushing = false; }
  set(next) {
    this._queue.push(next);
    if (!this._flushing) {
      this._flushing = true;
      queueMicrotask(() => {
        let s = this._state;
        for (const n of this._queue) s = typeof n === 'function' ? n(s) : n;
        this._queue = [];
        this._flushing = false;
        Observable.prototype.set.call(this, s);
      });
    }
  }
}
// or explicit:
model.transaction(() => { model.set(...); model.set(...); }); // one notify
```

---

## 13. Equality / no-op updates causing needless renders

**Problem.** `model.set(sameValue)` still notifies; every subscriber re-renders. Worse with objects: `set({ ...state })` always looks "changed".

**Fix.** Shallow (or deep) equality check before notifying.

```js
set(next) {
  const candidate = typeof next === 'function' ? next(this._state) : next;
  if (Object.is(candidate, this._state)) return; // same ref
  if (shallowEqual(candidate, this._state)) return;
  this._state = candidate;
  for (const fn of [...this._listeners]) fn(this._state);
}
```

---

## 14. Binding `this` in event handlers and callbacks

**Problem.** Passing `view.render` as a callback loses `this`; `removeEventListener` with a different function reference fails silently, leaking the listener.

```js
// BUG
model.subscribe(view.render); // this === undefined inside render
btn.removeEventListener('click', onClick); // different bound fn → not removed
```

**Fix.** Use arrow functions stored as instance fields, or `bind` once and keep the reference.

```js
class View {
  constructor(m, root) {
    this.model = m;
    this.root = root;
    this._render = (s) => this.render(s);   // stable ref
    this._onClick = (e) => this.handleClick(e);
    this._unsub = m.subscribe(this._render);
    this.root.addEventListener('click', this._onClick);
  }
  destroy() {
    this._unsub();
    this.root.removeEventListener('click', this._onClick);
  }
}
```

---

## 15. Circular dependencies between model and view

**Problem.** Model imports View for formatting; View imports Model for data → bundle cycle, or runtime `undefined` binding. Also controller and view often end up mutually imported.

**Fix.** Keep the dependency graph strictly one-way: `Model ← Controller → View`, with View depending only on a generic `Observable` interface. Inject dependencies via constructor; never import concrete classes across layers cyclically. Use an event bus / DI container for the rare cross-cutting need.

```js
// view.js
export class View {
  constructor(model, root) { /* only uses model.subscribe/get */ }
}
// controller.js
import { Model } from './model.js';
import { View } from './view.js';   // controller may compose both
// model.js imports nothing from view/controller
```

---

## 16. History / browser back-forward and stale model

**Problem.** Route changes but the model (and old view's subscriptions) persist; back button shows stale data or triggers a render for a detached view.

**Fix.** Scope models to a route/screen; create on mount, destroy on unmount. Sync URL state explicitly rather than implicitly.

```js
router.on('/user/:id', ({ id }) => {
  const model = new UserModel();
  const view = new UserView(model, root);
  controllers.push(new UserController(model, id));
  // on leave:
  return () => { view.destroy(); model.destroy(); };
});
```

---

## Quick checklist

- Treat state as immutable; never cache nested refs.
- Snapshot iteration of listeners; guard reentrancy.
- Debounce/batch notifications per frame.
- Always implement `destroy()` (unsubscribe → DOM → null).
- Escape all interpolated text or use `textContent`.
- Diff/patch DOM, preserving focus and IME.
- Cancel or token-gate async commits.
- Validate then commit atomically.
- Use optional chaining + defaults at render boundaries.
- Keep imports acyclic: Model has no knowledge of View/Controller.

If you're on a real framework (React/Vue/Svelte), most of these are handled by the framework's reconciliation and hooks—but the *async ordering*, *stale closure*, and *cleanup* versions of them still bite, so the same guards (dependency arrays, abort controllers, cleanup functions) apply.

# JavaScript Modules and Imports — Complete Runnable Example

Below is a small multi-file project that demonstrates **ES modules** (the modern standard), plus notes for **CommonJS** and the **browser**.

---

## 1. Project setup

Create a folder and these files:

```
my-mods/
├── package.json
├── math.js
├── greeting.js
├── reexports.js
└── index.js
```

### `package.json`

```json
{
  "name": "my-mods",
  "version": "1.0.0",
  "type": "module"
}
```

> `"type": "module"` tells Node.js to treat `.js` files as **ES modules** (use `import`/`export`).

---

## 2. Module files

### `math.js` — named + default exports

```js
// Named exports
export const PI = Math.PI;

export function add(a, b) {
  return a + b;
}

export function subtract(a, b) {
  return a - b;
}

// Default export (one per module)
export default function multiply(a, b) {
  return a * b;
}
```

### `greeting.js` — importing from another module

```js
import { add } from './math.js';

export function greet(name) {
  return `Hello, ${name}! 2 + 3 = ${add(2, 3)}`;
}

// Side-effect example: runs when imported
console.log('[greeting.js loaded]');
```

### `reexports.js` — re-exporting (barrel file)

```js
// Re-export everything from math.js
export * from './math.js';

// Re-export a specific binding with a new name
export { default as mul } from './math.js';
```

### `index.js` — main entry point

```js
// 1. Default + named imports
import multiply, { PI, add } from './math.js';

// 2. Namespace import
import * as math from './math.js';

// 3. Import from another module
import { greet } from './greeting.js';

// 4. Re-exports via barrel
import { mul, subtract } from './reexports.js';

console.log('multiply(4,5) =', multiply(4, 5));
console.log('PI =', PI);
console.log('math.add(10,20) =', math.add(10, 20));
console.log('subtract(9,4) =', subtract(9, 4));
console.log('mul(6,7) =', mul(6, 7));
console.log(greet('Ada'));

// 5. Dynamic import (lazy loading)
const lazy = await import('./math.js');
console.log('dynamic default(8,9) =', lazy.default(8, 9));

// 6. import.meta (module metadata)
console.log('module URL:', import.meta.url);
```

---

## 3. Run it

```bash
cd my-mods
node index.js
```

Expected output (order may vary slightly due to side effects):

```
[greeting.js loaded]
multiply(4,5) = 20
PI = 3.141592653589793
math.add(10,20) = 30
subtract(9,4) = 5
mul(6,7) = 42
Hello, Ada! 2 + 3 = 5
dynamic default(8,9) = 72
module URL: file:///.../my-mods/index.js
```

---

## 4. CommonJS (legacy Node style)

If you need `.cjs` or older code, use `require`/`module.exports`:

### `math.cjs`

```js
const PI = Math.PI;
function add(a, b) { return a + b; }
function multiply(a, b) { return a * b; }

module.exports = { PI, add, multiply };
// or: module.exports.multiply = multiply;
```

### `index.cjs`

```js
const { PI, add, multiply } = require('./math.cjs');
console.log(add(1, 2), PI, multiply(3, 4));
```

Run with:

```bash
node index.cjs
```

> You can mix ESM and CJS carefully using `.mjs`/`.cjs` extensions or conditional `"type"`.

---

## 5. Browser usage

ES modules work natively in modern browsers:

### `index.html`

```html
<!DOCTYPE html>
<html>
<body>
  <script type="module">
    import { add } from './math.js';
    import greet from './greeting.js'; // if default export existed
    console.log(add(1, 2));
  </script>

  <!-- Dynamic import on demand -->
  <button id="btn">Load extra</button>
  <script type="module">
    document.getElementById('btn').addEventListener('click', async () => {
      const mod = await import('./math.js');
      console.log('lazy:', mod.add(5, 6));
    });
  </script>
</body>
</html>
```

Serve over HTTP (modules need a server, not `file://`):

```bash
npx serve .
# or: python3 -m http.server 8080
```

---

## 6. Key concepts to remember

| Feature | Syntax |
|---|---|
| Named export | `export const x = 1;` / `export { x };` |
| Default export | `export default fn;` |
| Named import | `import { x } from './m.js';` |
| Default import | `import x from './m.js';` |
| Namespace | `import * as m from './m.js';` |
| Rename | `import { x as y } from './m.js';` |
| Side-effect only | `import './setup.js';` |
| Dynamic import | `const m = await import('./m.js');` |
| Re-export | `export * from './m.js';` / `export { default } from './m.js';` |

**Rules & gotchas**

- Module paths in ESM **must include the extension** (`./math.js`, not `./math`).
- Top-level `await` is allowed in ESM.
- Imports are **hoisted** and **read-only live bindings** (changes in the exporting module reflect in importers).
- Circular dependencies can work but be careful with temporal dead zones.
- In Node, ESM requires `"type": "module"` or `.mjs` extension.

---

## 7. Minimal “from scratch” bundler-free checklist

1. Add `"type": "module"` to `package.json`.
2. Use relative paths with extensions.
3. Export with `export`, consume with `import`.
4. Run with `node entry.js`.
5. For browsers, use `<script type="module">` and serve via HTTP.

That’s a complete, runnable foundation for modules and imports in JavaScript.

A common mistake is confusing a **default export** with a **named export**.

### Mistaken version

`math.js`

```js
export function add(a, b) {
  return a + b;
}

export default function multiply(a, b) {
  return a * b;
}
```

`app.js`

```js
import { multiply } from './math.js';

console.log(multiply(2, 3));
```

### What goes wrong

`multiply` is exported as the **default export**, but `app.js` tries to import it as a **named export**:

```js
import { multiply } from './math.js';
```

With ES modules, named imports look for an export whose name is exactly `multiply`. Since `math.js` only has a default export plus a named export called `add`, `multiply` is `undefined`. Calling `multiply(2, 3)` then throws:

```text
TypeError: multiply is not a function
```

### Corrected version

Option 1: import the default export directly.

`app.js`

```js
import multiply from './math.js';

console.log(multiply(2, 3)); // 6
```

Option 2: import the default export under an explicit alias.

`app.js`

```js
import { default as multiply } from './math.js';

console.log(multiply(2, 3)); // 6
```

Option 3: change `math.js` to make `multiply` a named export instead.

`math.js`

```js
export function add(a, b) {
  return a + b;
}

export function multiply(a, b) {
  return a * b;
}
```

`app.js`

```js
import { multiply } from './math.js';

console.log(multiply(2, 3)); // 6
```

### Why the distinction matters

In ES modules:

- `export default value;` creates the special `default` export.
- `export const x = ...;` or `export function x() {}` creates a named export called `x`.
- `import x from './module.js';` imports the default export.
- `import { x } from './module.js';` imports the named export `x`.

So the import syntax must match how the value was exported. A mismatch usually does not cause a syntax error at import time; instead, the imported binding becomes `undefined`, and the failure appears later when the value is used.

Below are common JavaScript module/import pitfalls, with small runnable examples. Most examples assume ESM unless noted.

## 1. Default vs. named export/import mismatch

```js
// math.js
export default function add(a, b) { return a + b; }
export function multiply(a, b) { return a * b; }

// app.js
import add, { multiply } from './math.js';        // correct
import { add } from './math.js';                 // undefined/wrong: add is default
import * as math from './math.js';
math.default(1, 2);                             // works, but awkward
```

Pitfall: `export default` and `export { ... }` are different shapes. Use one consistently, especially in libraries.

## 2. Omitting extensions or relying on index resolution in Node ESM

```js
// Node ESM
import './utils';          // ERR_MODULE_NOT_FOUND
import './utils.js';       // correct
import './components';     // may fail even if components/index.js exists
import './components/index.js'; // robust
```

Bundlers often allow extensionless/index imports; Node ESM does not for relative paths.

## 3. Case-sensitive file paths

```js
// File is button.js
import './Button.js';     // works on Windows/macOS, fails on Linux/CI
import './button.js';     // portable
```

Always match the real filename exactly.

## 4. Circular dependencies and temporal dead zone

```js
// a.js
import { b } from './b.js';
export const a = 'A';
console.log('a sees b:', b);

// b.js
import { a } from './a.js';
export const b = 'B';
console.log('b sees a:', a); // ReferenceError: Cannot access 'a' before initialization
```

Because `a` is a `const` binding not yet initialized when `b.js` runs. Prefer function declarations, dependency inversion, or restructuring modules.

## 5. Mutating imported bindings

```js
// counter.js
export let count = 0;
export function increment() { count++; }

// app.js
import { count } from './counter.js';
count++; // TypeError: Assignment to constant variable
```

Imported bindings are read-only from the consumer’s side. Mutate through exported functions instead.

## 6. Destructuring loses live bindings

```js
// state.js
export let value = 1;
export function setValue(v) { value = v; }

// app.js
import { value } from './state.js';
console.log(value); // 1
setValue(2);
console.log(value); // 2 (live binding)

const snapshot = value; // copied primitive
setValue(3);
console.log(snapshot); // still 2
```

If you need “live” updates, keep using the imported binding; do not snapshot unless intended.

## 7. Mixing ESM and CommonJS

```js
// legacy.cjs
module.exports = { greet() { return 'hi'; } };

// app.mjs
import legacy from './legacy.cjs';   // usually module.exports
legacy.greet();

import { greet } from './legacy.cjs'; // may work in Node, but not universally
```

Also, `require` is not available in ESM:

```js
// app.mjs
const fs = require('fs'); // ReferenceError: require is not defined

import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const fs = require('fs');
```

## 8. Dual-package hazard / two instances

```js
// package has both ESM and CJS entries
import pkg from 'my-lib';          // ESM instance
const pkg2 = require('my-lib');   // CJS instance

pkg.state.count = 1;
console.log(pkg2.state.count);    // 0: separate module instances/state
```

Avoid mixing `import` and `require` for the same stateful package.

## 9. Barrel files causing large bundles and circular deps

```js
// components/index.js
export * from './Button.js';
export * from './Modal.js';
export * from './Chart.js'; // heavy

// app.js
import { Button } from './components/index.js';
```

Bundlers may include far more than `Button`, and barrel + deep imports can create cycles. Prefer direct imports for large apps:

```js
import { Button } from './components/Button.js';
```

## 10. Side effects and tree-shaking

```js
// utils.js
export function used() {}
export function unused() { console.log('side effect'); }

// app.js
import { used } from './utils.js';
```

If `package.json` has `"sideEffects": false`, bundlers may remove `unused` and its side effect. If removal is wrong, declare side effects:

```json
{
  "sideEffects": [
    "./src/polyfills.js",
    "*.css"
  ]
}
```

Also mark intentional side-effect imports:

```js
import './polyfills.js';
```

## 11. Re-export pitfalls: default and star exports

```js
// a.js
export default 'A';
export const x = 1;

// reexports.js
export * from './a.js';          // re-exports x, NOT default
export { default } from './a.js'; // needed for default

// app.js
import { default as aDefault, x } from './reexports.js';
```

Also, ambiguous star exports can fail:

```js
// a.js and b.js both export `foo`
export * from './a.js';
export * from './b.js';
// importing `foo` can throw SyntaxError: The requested module ... contains conflicting star exports
```

## 12. Import hoisting surprises

```js
console.log('start');
import './side-effect.js'; // runs before "start"
console.log('end');
```

Import declarations are hoisted and evaluated before the importing module body continues. Do not assume top-to-bottom execution around imports.

## 13. Dynamic import is async and bundler-sensitive

```js
// Runtime dynamic path
const name = userInput;
const mod = await import(`./plugins/${name}.js`); // works at runtime if file exists

// Bundler may not know all possible files
const mod2 = await import(variablePath); // may not be code-split/chunked as expected
```

Always handle failures:

```js
try {
  const mod = await import('./optional-feature.js');
  mod.enable();
} catch (err) {
  console.warn('Optional feature unavailable', err);
}
```

## 14. Top-level await blocks dependents

```js
// config.js
export const config = await fetch('/config.json').then(r => r.json());

// app.js
import { config } from './config.js'; // waits for fetch before app evaluates
```

This can delay or stall the module graph. Use lazy loading or explicit initialization where possible.

## 15. `__dirname` and `__filename` are unavailable in ESM

```js
// CommonJS
console.log(__dirname, __filename);

// ESM
import { fileURLToPath } from 'node:url';
import { dirname } from 'node:path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
```

## 16. TypeScript path aliases are not runtime paths

```json
// tsconfig.json
{ "compilerOptions": { "paths": { "@/*": ["src/*"] } } }
```

```ts
import { helper } from '@/helper'; // type-checks, but Node may fail at runtime
```

Fix with bundler/Node subpath imports or a resolver, or use relative paths:

```js
import { helper } from './src/helper.js';
```

## 17. Non-standard imports: JSON, CSS, images

```js
// CommonJS
const data = require('./data.json');

// ESM: needs import attribute (support varies)
import data from './data.json' with { type: 'json' };

// CSS/images are bundler features, not standard JS
import './styles.css';
import logo from './logo.png';
```

Do not assume these work in plain Node ESM.

## 18. Automatic strict mode and `this`

```js
// module.js (ESM)
console.log(this); // undefined

function f() {
  console.log(this); // undefined in strict mode
}
f();
```

ESM is always strict. Code that relied on sloppy-mode global `this` breaks.

## Practical defaults

- Use explicit `.js`/`.mjs` relative paths in Node ESM.
- Prefer named exports for libraries unless a single default makes sense.
- Avoid circular dependencies; export functions rather than reading mutable bindings during load.
- Do not mix `import` and `require` for the same package.
- Keep barrel files small, or import deep paths.
- Treat JSON/CSS/image imports as bundler-specific.
- Test on case-sensitive filesystems/CI.

## Exercise

Create a tiny ES-module utility library with these requirements:

1. `math.mjs` exports named functions `add` and `subtract`, plus a default export `multiply`.
2. `logger.mjs` exports a default logging function.
3. `utils.mjs` re-exports `add` from `math.mjs` and defines `divide`.
4. `main.mjs` statically imports from `math.mjs` and `utils.mjs`, dynamically imports `logger.mjs`, and prints results.

---

## Step-by-step solution

### 1. Create the project folder

```bash
mkdir js-modules-exercise
cd js-modules-exercise
```

Using `.mjs` lets Node treat the files as ES modules without needing `"type": "module"` in `package.json`.

### 2. Create `math.mjs`

```js
// math.mjs

export function add(a, b) {
  return a + b;
}

export const subtract = (a, b) => a - b;

export default function multiply(a, b) {
  return a * b;
}
```

**What this shows**
- `export function` and `export const` are **named exports**.
- `export default` is the **default export**.
- A module can have many named exports but only one default export.

### 3. Create `logger.mjs`

```js
// logger.mjs

export default function log(message) {
  console.log(`[LOG] ${message}`);
}
```

This module has only a default export.

### 4. Create `utils.mjs`

```js
// utils.mjs

export { add } from './math.mjs';

export function divide(a, b) {
  if (b === 0) {
    throw new Error('Division by zero');
  }
  return a / b;
}
```

**What this shows**
- `export { add } from './math.mjs'` is a **re-export**.
- Consumers can import `add` from either `math.mjs` or `utils.mjs`.

### 5. Create `main.mjs`

```js
// main.mjs

import multiply, { add, subtract } from './math.mjs';
import * as Utils from './utils.mjs';

// Dynamic import returns a module namespace object.
const loggerModule = await import('./logger.mjs');
const log = loggerModule.default;

log(`2 + 3 = ${add(2, 3)}`);
console.log('5 - 2 =', subtract(5, 2));
console.log('4 * 6 =', multiply(4, 6));
console.log('10 / 2 =', Utils.divide(10, 2));
console.log('Utils.add(1, 1) =', Utils.add(1, 1));
```

**What this shows**
- `import multiply, { add, subtract }` mixes **default** and **named** imports.
- `import * as Utils` imports the whole module as a namespace object.
- `await import(...)` is a **dynamic import**, useful for lazy loading.
- Top-level `await` works in ES modules.

### 6. Run it

```bash
node main.mjs
```

Expected output:

```text
[LOG] 2 + 3 = 5
5 - 2 = 3
4 * 6 = 24
10 / 2 = 5
Utils.add(1, 1) = 2
```

---

## Key concepts recap

| Syntax | Meaning |
|---|---|
| `export function add() {}` | Named export |
| `export default function multiply() {}` | Default export |
| `import { add } from './math.mjs'` | Named import |
| `import multiply from './math.mjs'` | Default import |
| `import * as Utils from './utils.mjs'` | Namespace import |
| `export { add } from './math.mjs'` | Re-export |
| `await import('./logger.mjs')` | Dynamic import |

### Optional: CommonJS equivalent

If you were using CommonJS instead of ESM, the equivalent pattern would look like:

```js
// math.cjs
function add(a, b) { return a + b; }
function subtract(a, b) { return a - b; }
function multiply(a, b) { return a * b; }

module.exports = { add, subtract, multiply };
```

```js
// main.cjs
const { add, subtract, multiply } = require('./math.cjs');
console.log(add(2, 3), subtract(5, 2), multiply(4, 6));
```

For modern JavaScript projects, prefer ES modules (`.mjs` or `"type": "module"`) because they support static analysis, tree-shaking, and dynamic `import()`.

## Modules & Imports in JavaScript (interview-style)

### 1. What a module is
A **module** is a file/scope that:
- has its own top-level scope (no global pollution),
- explicitly **exports** values,
- explicitly **imports** values from other modules.

Modules give you **encapsulation**, **reusability**, and **dependency graphs**.

---

### 2. The two big systems

#### ES Modules (ESM) — the standard
```js
// math.js
export function add(a, b) { return a + b; }
export const PI = 3.14159;
export default function mul(a, b) { return a * b; }

// app.js
import mul, { add, PI } from "./math.js";
import * as ns from "./math.js";   // namespace object
```

Key properties:
- **Static**: imports/exports are analyzed before execution (enables tree-shaking).
- **Live bindings**: imported bindings reflect later changes in the source module.
- **Strict mode** is implicit.
- **Top-level `await`** is allowed.
- Browsers load via `<script type="module">`; Node via `.mjs` or `"type": "module"`.

#### CommonJS (CJS) — Node’s classic system
```js
// math.js
function add(a, b) { return a + b; }
module.exports = { add };
// or: exports.add = add;

// app.js
const { add } = require("./math");
```

Key properties:
- **Dynamic**: `require()` can be called anywhere, conditionally.
- **Synchronous** loading.
- **Cached**: a module is evaluated once; later `require()` returns cached `exports`.
- `module.exports` is the actual exported object; `exports` is just an alias to it (reassigning `exports = ...` breaks the link).

---

### 3. Core concepts interviewers probe

| Concept | ESM | CommonJS |
|---|---|---|
| Loading | Static graph, async-capable | Sync, runtime |
| Bindings | Live | Snapshot-ish (object reference) |
| Circular deps | Partially initialized namespace | Partially initialized `exports` |
| Caching | Module instance cache | `require.cache` |
| Default export | `export default x` | `module.exports = x` |
| Interop | `import cjs from "cjs"` (namespace) | `require("esm")` may need `.default` |

**Circular dependency example (CommonJS):**
```js
// a.js
const b = require("./b");
module.exports = { name: "a", b };

// b.js
const a = require("./a"); // a.exports is {} at this moment
module.exports = { name: "b", a };
```
When `a` requires `b`, and `b` requires `a`, `a`’s `exports` object already exists (empty), so `b` gets a partial reference. Order matters.

---

### 4. Implementing the core (a mini module system)

Below is a **clean, commented, dependency-free** implementation of the *core* of a module system:
- module registry (`define`)
- `require` with caching
- relative resolution
- circular-dependency-safe `exports` object
- dynamic `import()` (promise-based)
- a small demo

This mirrors how bundlers/loaders (Webpack, Rollup dev, Node’s internal loader) think about modules: **an id → module record → factory → exports**.

```js
/**
 * MiniModuleSystem
 * A teaching implementation of CommonJS-style modules + a dynamic import().
 *
 * Design:
 *   - Each module has a unique id and a factory function.
 *   - The factory receives (require, module, exports).
 *   - Modules are cached by id (singleton evaluation).
 *   - Circular deps are safe because `exports` object is created before factory runs.
 */
function createModuleSystem() {
  // id -> factory(require, module, exports)
  const registry = new Map();

  // id -> module record { id, exports, loaded, loading }
  const cache = new Map();

  // ---- Resolution (simplified) ----
  // Supports: relative "./" and "../", and bare ids via an alias map.
  const aliases = new Map(); // bare id -> resolved id

  function resolve(specifier, fromId = null) {
    // Bare module / alias
    if (!specifier.startsWith(".")) {
      if (aliases.has(specifier)) return aliases.get(specifier);
      // In a real system this would search node_modules.
      return specifier;
    }

    // Relative resolution
    const baseParts = fromId ? fromId.split("/").slice(0, -1) : [];
    const specParts = specifier.split("/");

    for (const part of specParts) {
      if (part === "" || part === ".") continue;
      if (part === "..") {
        if (baseParts.length) baseParts.pop();
      } else {
        baseParts.push(part);
      }
    }

    let resolved = baseParts.join("/");
    // Default extension handling (teaching simplification)
    if (!resolved.endsWith(".js")) resolved += ".js";
    return resolved;
  }

  // ---- require factory bound to a base module ----
  function makeRequire(fromId) {
    function req(specifier) {
      const id = resolve(specifier, fromId);

      // Cache hit: return existing exports (singleton)
      if (cache.has(id)) {
        return cache.get(id).exports;
      }

      const factory = registry.get(id);
      if (!factory) {
        throw new Error(`Module not found: "${specifier}" (resolved: "${id}")`);
      }

      // Create module record BEFORE running factory -> circular-dep safety
      const moduleRecord = { id, exports: {}, loaded: false, loading: true };
      cache.set(id, moduleRecord);

      try {
        // Factory mutates moduleRecord.exports (or reassigns moduleRecord.exports)
        factory(makeRequire(id), moduleRecord, moduleRecord.exports);
        moduleRecord.loaded = true;
      } catch (err) {
        // On failure, remove from cache so a retry can happen
        cache.delete(id);
        throw err;
      } finally {
        moduleRecord.loading = false;
      }

      return moduleRecord.exports;
    }
    return req;
  }

  // ---- Public API ----

  // Register a module factory
  function define(id, factory) {
    if (registry.has(id)) throw new Error(`Duplicate module id: ${id}`);
    registry.set(id, factory);
  }

  // Alias bare specifiers (like package names)
  function alias(name, id) {
    aliases.set(name, id);
  }

  // CommonJS-style require from the "root"
  const require = makeRequire(null);

  // ESM-ish dynamic import: always async, returns a promise
  function importModule(specifier, fromId = null) {
    return Promise.resolve().then(() => makeRequire(fromId)(specifier));
  }

  // Inspect cache (useful for debugging / testing)
  function getCache() {
    return cache;
  }

  return { define, alias, require, import: importModule, resolve, getCache };
}

// =========================
// Demo / Usage
// =========================
const system = createModuleSystem();

// --- Module: utils.js ---
system.define("utils.js", (require, module, exports) => {
  exports.add = (a, b) => a + b;
  exports.PI = 3.14159;
});

// --- Module: math.js (depends on utils) ---
system.define("math.js", (require, module, exports) => {
  const { add, PI } = require("./utils.js");

  exports.add = add;
  exports.area = (r) => PI * r * r;

  // default export pattern (CommonJS style)
  module.exports = Object.assign(module.exports, {
    default: (a, b) => a * b,
  });
});

// --- Circular dependency demo ---
system.define("a.js", (require, module, exports) => {
  // At this point b.js may partially load a's exports
  const b = require("./b.js");
  exports.name = "A";
  exports.bName = () => b.name; // live-ish access via closure
});

system.define("b.js", (require, module, exports) => {
  const a = require("./a.js"); // a.exports exists but may be partial
  exports.name = "B";
  exports.sawA = a && typeof a.name; // "undefined" ok during cycle
});

// --- Run ---
const math = system.require("./math.js");
console.log("add:", math.add(2, 3));          // 5
console.log("area:", math.area(2));           // ~12.566
console.log("default:", math.default(2, 3));  // 6

const a = system.require("./a.js");
console.log("a.name:", a.name);               // A
console.log("a.bName():", a.bName());         // B

// Dynamic import
system.import("./utils.js").then((u) => {
  console.log("dynamic import add:", u.add(10, 20)); // 30
});

// Cache check
console.log("cached ids:", [...system.getCache().keys()]);
```

---

### 5. How this maps to real systems

| This demo | Real world |
|---|---|
| `registry` | Webpack module map / Node internal module cache |
| `cache` | `require.cache` / ESM module map |
| `resolve` | Node’s `MODULE_RESOLUTION` / bundler resolver |
| factory `(require, module, exports)` | Transpiled CJS output |
| `importModule` | Native `import()` / dynamic `require()` |
| alias map | `package.json` `"imports"` / `"exports"` / bundler `resolve.alias` |

---

### 6. Interview follow-ups you should be ready for
- **ESM live bindings**: `export let x = 1; x++` reflects in importers; CJS gives a snapshot of the value at require time (unless you export a getter/object).
- **Tree-shaking** needs static ESM; CJS is harder because `require` can be conditional.
- **Top-level await** changes module evaluation to async, affecting load order.
- **Circular deps**: ESM gives TDZ errors if you read a binding before initialization; CJS gives partial objects.
- **Interop**: Node can `require()` ESM only in limited cases; ESM can import CJS and gets a default-ish namespace.

If you want, I can extend this into a **true ESM loader** (with `import`/`export` syntax parsing, live bindings, and top-level await) or a **mini bundler** that produces a single file.

## Multithreading in JavaScript

JavaScript itself runs on a single event loop, so true parallelism requires **workers**:

- **Node.js** → `worker_threads` module (real OS threads).
- **Browsers** → `Web Workers` (and `SharedArrayBuffer` + `Atomics` for shared memory).

Below is a **complete, runnable Node.js example** in a single file. It splits a CPU-bound task (counting primes up to `N`) across all CPU cores and aggregates the results.

### Runnable example: `primes-parallel.js`

```js
// primes-parallel.js
// Run with: node primes-parallel.js
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');
const os = require('os');

// ---------- Worker thread ----------
if (!isMainThread) {
  const { from, to } = workerData;

  let count = 0;
  for (let n = from; n <= to; n++) {
    if (isPrime(n)) count++;
  }

  // Send result back to main thread
  parentPort.postMessage(count);
  return;
}

// ---------- Main thread ----------
function isPrime(n) {
  if (n < 2) return false;
  if (n % 2 === 0) return n === 2;
  const limit = Math.sqrt(n);
  for (let i = 3; i <= limit; i += 2) {
    if (n % i === 0) return false;
  }
  return true;
}

const N = 200_000;
const numWorkers = Math.min(os.cpus().length, 8);
const chunkSize = Math.ceil((N - 1) / numWorkers); // numbers 2..N

let completed = 0;
let total = 0;
const t0 = Date.now();

for (let i = 0; i < numWorkers; i++) {
  const from = 2 + i * chunkSize;
  const to = Math.min(N, 1 + (i + 1) * chunkSize);
  if (from > to) continue;

  const worker = new Worker(__filename, { workerData: { from, to } });

  worker.on('message', (count) => {
    total += count;
    completed++;
    if (completed === numWorkers) {
      console.log(`Primes up to ${N}: ${total}`);
      console.log(`Workers: ${numWorkers}, time: ${Date.now() - t0} ms`);
    }
  });

  worker.on('error', (err) => {
    console.error('Worker error:', err);
  });

  worker.on('exit', (code) => {
    if (code !== 0) console.error(`Worker exited with code ${code}`);
  });
}

// Prevent the event loop from exiting before workers finish
// (the 'message' handlers above keep it alive anyway).
```

### How it works

1. **`isMainThread`** splits the file into two roles:
   - **Main thread** creates workers, hands out ranges, collects results.
   - **Worker threads** run the heavy loop and `postMessage` the partial count.
2. **`workerData`** is cloned with the structured clone algorithm (safe, no shared refs).
3. **`parentPort.postMessage`** is how a worker talks back.
4. Results are aggregated in the main thread; the main thread exits naturally once all workers report.

### Shared memory variant (SharedArrayBuffer + Atomics)

When you need threads to mutate the *same* buffer without copying, use `SharedArrayBuffer`:

```js
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

if (isMainThread) {
  const N = 4;
  const sab = new SharedArrayBuffer(4 * N);        // 4 int32 per worker slot
  const view = new Int32Array(sab);

  let done = 0;
  for (let i = 0; i < N; i++) {
    const w = new Worker(__filename, { workerData: { sab, index: i } });
    w.on('exit', () => {
      if (++done === N) {
        console.log('Shared results:', Array.from(view));
      }
    });
  }
} else {
  const { sab, index } = workerData;
  const view = new Int32Array(sab);

  // Atomic increment so updates never tear/race
  Atomics.add(view, index, 42 * (index + 1));

  // Publish a fence so the main thread sees consistent data
  Atomics.store(view, index, view[index]); // no-op-ish, illustrates publication
  parentPort.postMessage('done');
}
```

Key points:

- `SharedArrayBuffer` memory is shared by reference across threads.
- Use `Atomics.*` for concurrent reads/writes (`add`, `load`, `store`, `wait`, `notify`).
- In browsers, `SharedArrayBuffer` requires **COOP/COEP headers** (`Cross-Origin-Opener-Policy: same-origin`, `Cross-Origin-Embedder-Policy: require-corp`) for security.

### Browser equivalent

```js
// main.js
const worker = new Worker('worker.js');
worker.postMessage({ from: 2, to: 100_000 });
worker.onmessage = (e) => console.log('prime count:', e.data);

// worker.js
self.onmessage = (e) => {
  const { from, to } = e.data;
  let count = 0;
  for (let n = from; n <= to; n++) if (isPrime(n)) count++;
  self.postMessage(count);
};
function isPrime(n) { /* ... */ }
```

### Practical guidelines

- **Don't over-thread.** Workers have overhead; for tiny tasks the single thread is faster.
- **CPU-bound** work benefits most; **I/O-bound** work usually doesn't need workers (use async I/O).
- Prefer **transferable objects** (`ArrayBuffer` transfer lists) over cloning large payloads:
  ```js
  const buf = new ArrayBuffer(1e6);
  worker.postMessage(buf, [buf]); // ownership moves, no copy
  ```
- Always handle `error` and `exit` events; an unhandled worker crash can hang your process.
- For Node, cap worker count to `os.cpus().length` (or fewer) to avoid scheduler thrashing.
- Use a **worker pool** (e.g., `piscina`, `workerpool`) for production instead of spawning per task.

## The idea

JavaScript is **single-threaded by default**: one call stack, one event loop, one “main thread.”  
That keeps the programming model simple, but it means a heavy CPU task (image processing, big loops, crypto, parsing) **blocks** the UI or the server from handling events.

**Multithreading in JS is achieved with Workers**:

- Each worker runs in its own OS thread with its own event loop and memory.
- Workers **do not share memory by default**; they communicate by **message passing** (`postMessage`).
- In browsers: **Web Workers** (Dedicated / Shared / Service).
- In Node.js: **`worker_threads`**.
- Optional shared memory: **`SharedArrayBuffer` + `Atomics`** (requires special security headers in browsers).

---

## Browser Web Workers

### Syntax

```js
// main.js
const worker = new Worker('worker.js');

worker.postMessage({ task: 'sum', n: 100_000_000 });

worker.onmessage = (e) => {
  console.log('Result from worker:', e.data);
};

worker.onerror = (err) => console.error(err);
worker.terminate(); // stop it
```

```js
// worker.js  (runs in worker thread)
self.onmessage = (e) => {
  const { task, n } = e.data;
  if (task === 'sum') {
    let sum = 0;
    for (let i = 0; i < n; i++) sum += i;
    self.postMessage(sum);   // send result back
  }
};
```

**Key points**
- `worker.js` must be a separate file (or a Blob URL).
- Workers have **no access to `document`/DOM** and no `window`; they have `self`.
- Data is copied with the **structured clone algorithm** (not JSON; supports `Map`, `Set`, `ArrayBuffer`, etc.).
- Large buffers can be **transferred** (zero-copy) instead of copied:
  ```js
  const buf = new ArrayBuffer(1024);
  worker.postMessage(buf, [buf]); // buf is detached in main thread
  ```

### Types of browser workers
- **Dedicated Worker**: one-to-one with a page (most common).
- **Shared Worker**: shared across tabs/windows of same origin.
- **Service Worker**: background proxy for caching/offline/PWA (not for CPU work).

---

## Node.js `worker_threads`

### Syntax

```js
// app.js
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

if (isMainThread) {
  const worker = new Worker(__filename, {
    workerData: 100_000_000
  });

  worker.on('message', (result) => console.log('Result:', result));
  worker.on('error', (err) => console.error(err));
  worker.on('exit', (code) => console.log('Worker exited:', code));
} else {
  // Worker thread code
  const n = workerData;
  let sum = 0;
  for (let i = 0; i < n; i++) sum += i;
  parentPort.postMessage(sum);
}
```

Run with `node app.js`.  
Node can also load a separate file: `new Worker('./worker.js', { workerData })`.

**Key points**
- `isMainThread` lets one file act as both entry and worker.
- `workerData` is cloned into the worker (structured clone).
- Communication uses `parentPort.postMessage` / `worker.on('message')`.
- You can use ES modules with `--experimental-vm-modules` or `.mjs`.

---

## Shared memory: `SharedArrayBuffer` + `Atomics`

For tight loops where copying is too expensive, threads can share an `ArrayBuffer`.

```js
// main.js
const sab = new SharedArrayBuffer(4);          // 4 bytes
const view = new Int32Array(sab);
Atomics.store(view, 0, 0);

const worker = new Worker('worker.js');
worker.postMessage(sab);                       // shared, not copied

setInterval(() => {
  console.log('counter =', Atomics.load(view, 0));
}, 500);
```

```js
// worker.js
self.onmessage = (e) => {
  const view = new Int32Array(e.data);
  while (true) {
    Atomics.add(view, 0, 1);                   // atomic increment
    // Atomics.wait/notify can coordinate threads
  }
};
```

**Caveats**
- Browser requires **cross-origin isolation** (`COOP`/`COEP` headers) for `SharedArrayBuffer`.
- Data races are possible; always use `Atomics` for reads/writes.
- `Atomics.wait` blocks the worker thread (allowed) but never the main thread (would freeze UI).

---

## Typical use cases

| Use case | Why workers help |
|---|---|
| Heavy computation (ML inference, crypto, hashing) | Keeps UI/server responsive |
| Image/video processing, canvas pixel ops | Offload CPU-intensive loops |
| Large JSON/CSV parsing & transformation | Avoid main-thread jank |
| Parallel map/reduce over chunks | Scale across cores |
| Background indexing/search | Non-blocking I/O + CPU |
| Game physics / simulation | Stable frame rate |

**Anti-patterns**
- Don’t spin up workers for tiny tasks (overhead > benefit).
- Don’t share mutable state casually; prefer message passing.
- Don’t try to manipulate DOM from a worker.

---

## Practical patterns

### 1. Worker pool (Node)
Reuse a fixed number of workers instead of creating per task.

```js
const { Worker } = require('worker_threads');
const os = require('os');

class Pool {
  constructor(file, size = os.cpus().length) {
    this.workers = Array.from({ length: size }, () => new Worker(file));
    this.queue = [];
  }
  run(data) {
    return new Promise((resolve, reject) => {
      const worker = this.workers.pop();
      if (!worker) { this.queue.push({ data, resolve, reject }); return; }
      const onMsg = (r) => { cleanup(); resolve(r); };
      const onErr = (e) => { cleanup(); reject(e); };
      const cleanup = () => {
        worker.off('message', onMsg);
        worker.off('error', onErr);
        this.workers.push(worker);
        if (this.queue.length) {
          const next = this.queue.shift();
          this.run(next.data).then(next.resolve).catch(next.reject);
        }
      };
      worker.on('message', onMsg);
      worker.on('error', onErr);
      worker.postMessage(data);
    });
  }
}
```

### 2. Transferable for zero-copy
```js
const buf = new Uint8Array(1_000_000).buffer;
worker.postMessage(buf, [buf]); // moved, not copied
```

### 3. Abort/cancel
Workers can’t be “cancelled” mid-task easily; design tasks to check a flag or use `worker.terminate()` (hard kill).

