**`index.js`**
```js
const { Worker } = require('worker_threads');
const os = require('os');

const N = 50_000_000;

function runWorker(start, end) {
  return new Promise((resolve, reject) => {
    const w = new Worker('./worker.js', { workerData: { start, end } });
    w.on('message', resolve);
    w.on('error', reject);
    w.on('exit', (c) => c !== 0 && reject(new Error(`exit ${c}`)));
  });
}

async function parallel(n, workers = os.cpus().length) {
  const chunk = Math.ceil(n / workers);
  const tasks = [];
  for (let i = 0; i < workers; i++) {
    const s = i * chunk + 1;
    const e = Math.min((i + 1) * chunk, n);
    if (s <= e) tasks.push(runWorker(s, e));
  }
  return (await Promise.all(tasks)).reduce((a, b) => a + b, 0);
}

(async () => {
