  console.log(await parallel(N));
  console.timeEnd('parallel');
})();
```

Run with `node index.js`. This is the idiomatic, production-friendly pattern for CPU-bound parallelism in Node.js.

## Multithreading in JavaScript — Interview Answer

### 1. The honest truth: JS is single-threaded by default
JavaScript runs on one call stack. Concurrency comes from the **event loop** + async I/O (timers, network, file system). That gives *concurrency* (interleaving), not *parallelism* (true simultaneous execution on multiple cores).

### 2. Real parallelism: Workers
- **Browser:** `Web Workers` (Dedicated / Shared / Service Workers).
- **Node.js:** `worker_threads`.
- Each worker has its own V8 isolate, event loop, and memory heap. They do **not** share the call stack.

### 3. Communication models
| Model | How | Pros/Cons |
|---|---|---|
| **Message passing** | `postMessage` (structured clone) | Safe, simple; copying cost for large data |
| **Shared memory** | `SharedArrayBuffer` + `Atomics` | Zero-copy, fast; requires careful synchronization (race conditions) |

### 4. Shared memory primitives (Node/Browser)
- `SharedArrayBuffer` — shared raw bytes.
- `Atomics.load/store/add/sub/compareExchange/wait/notify` — atomic ops + blocking primitives for synchronization.

### 5. Key limitations
- Workers can’t touch the DOM (browser) or share closures with the main thread.
- Functions must be serialized (`.toString()`) or loaded from a file.
- Overhead: spawning workers and copying data isn’t free; use a pool.

---

## Core implementation: a reusable Worker Thread Pool (Node.js)

Below is a minimal but production-shaped **thread pool** that parallelizes `Array.prototype.map`. It uses message passing and reuses workers.

```js
// pool.js  — run with: node pool.js
const { Worker, isMainThread, parentPort } = require('worker_threads');
const os = require('os');

/* ------------------------------------------------------------------ */
/* WORKER CODE (runs in each spawned thread)                            */
/* ------------------------------------------------------------------ */
if (!isMainThread) {
  parentPort.on('message', ({ fnSrc, chunk }) => {
    try {
      // Reconstruct the function from its source text.
      // NOTE: closures over outer variables are NOT captured.
      const fn = new Function('return ' + fnSrc)();
      const out = chunk.map((v, i, a) => fn(v, i, a));
      parentPort.postMessage({ ok: true, result: out });
    } catch (err) {
      parentPort.postMessage({ ok: false, error: err.message });
    }
  });
  // Do not run main-thread code in the worker.
} else {
  /* ---------------------------------------------------------------- */
  /* MAIN THREAD CODE                                                  */
  /* ---------------------------------------------------------------- */

  class ThreadPool {
    constructor(size = os.cpus().length) {
      this.size = size;
      this.workers = [];
      this.queue = [];          // pending tasks
      this.active = new Map();  // worker -> task

      for (let i = 0; i < size; i++) {
        const w = new Worker(__filename); // re-execute this file as a worker
        w.on('message', (msg) => this._onMessage(w, msg));
        w.on('error', (e) => console.error('Worker error:', e));
        w.on('exit', (code) => {
          if (code !== 0) console.error(`Worker exited with code ${code}`);
        });
        this.workers.push(w);
      }
    }

    /** Internal: handle a finished task and schedule the next one. */
    _onMessage(worker, msg) {
      const task = this.active.get(worker);
      if (!task) return;
      this.active.delete(worker);

      if (msg.ok) task.resolve(msg.result);
      else task.reject(new Error(msg.error));

      this._dispatch();
    }

    /** Internal: assign queued work to any idle worker. */
    _dispatch() {
      if (this.queue.length === 0) return;
      const free = this.workers.find((w) => !this.active.has(w));
      if (!free) return;

      const task = this.queue.shift();
      this.active.set(free, task);
      free.postMessage({ fnSrc: task.fnSrc, chunk: task.chunk });
    }

    /**
     * Parallel map.
     * @param {any[]} arr
     * @param {(v:any,i:number,a:any[])=>any} fn
     * @returns {Promise<any[]>}
     */
    map(arr, fn) {
      const fnSrc = fn.toString();
      const chunks = this._chunk(arr, this.size);

      return new Promise((resolveAll, rejectAll) => {
        const results = new Array(chunks.length);
        let done = 0;

        chunks.forEach((chunk, i) => {
          const task = {
            fnSrc,
            chunk,
            resolve: (r) => {
              results[i] = r;
              if (++done === chunks.length) resolveAll(results.flat());
            },
            reject: (e) => rejectAll(e),
          };
          this.queue.push(task);
          this._dispatch();
        });
      });
    }

    _chunk(arr, n) {
      const size = Math.ceil(arr.length / n);
      const out = [];
      for (let i = 0; i < arr.length; i += size) {
        out.push(arr.slice(i, i + size));
      }
      return out;
    }

    async terminate() {
      await Promise.all(this.workers.map((w) => w.terminate()));
    }
  }

  /* ---------------------------------------------------------------- */
  /* DEMO                                                             */
  /* ---------------------------------------------------------------- */
  (async () => {
    const pool = new ThreadPool(4);

    const data = Array.from({ length: 2_000_000 }, (_, i) => i);

    const t0 = Date.now();
    const squared = await pool.map(data, (x) => x * x);
    console.log('parallel ms:', Date.now() - t0);
    console.log('sample:', squared.slice(0, 5));

    await pool.terminate();
  })();
}
```

### How it works
1. **Spawn:** `new Worker(__filename)` re-runs this file in a new thread. The `isMainThread` guard ensures only the worker branch executes there.
2. **Chunking:** input array is split into `N` slices (one per worker).
3. **Dispatch:** idle workers pick tasks from a FIFO queue.
4. **Serialization:** `fn.toString()` ships the function source; the worker rebuilds it with `new Function`. (Closures are not captured — pass data explicitly.)
5. **Aggregation:** results are placed back in chunk order and flattened.

### Shared-memory variant (conceptual snippet)
```js
const sab = new SharedArrayBuffer(4);          // 4 bytes
const view = new Int32Array(sab);
Atomics.add(view, 0, 5);                       // atomic increment
Atomics.wait(view, 0, 5);                      // block until value changes (worker side)
Atomics.notify(view, 0, 1);                    // wake one waiter
```
Use this when you need **zero-copy** shared state; always guard accesses with `Atomics` to avoid data races.

### Interview talking points
- **Why not just `async/await`?** Async avoids blocking but still runs on one thread; CPU-bound work needs workers.
- **When to use workers?** Heavy computation (image processing, crypto, large sorts), not I/O.
- **Pool sizing:** usually `os.cpus().length`; more workers than cores adds context-switch overhead.
- **Transferables:** for large buffers, use `postMessage(buf, [buf])` to transfer ownership instead of copying.

# Multithreading in JavaScript: Edge Cases & Code Examples

JavaScript multithreading happens via **Web Workers** (browsers) and **`worker_threads`** (Node.js). Both use message passing plus optional shared memory (`SharedArrayBuffer`). Below are the edge cases that bite in practice, with runnable idioms.

---

## 1. Structured clone vs. transfer (detached buffers)

`postMessage` **clones** by default. Large `ArrayBuffer`s should be **transferred** (zero-copy), but then the sender's buffer becomes *detached*.

```js
// main.js (browser or Node worker_threads)
const worker = new Worker('./worker.js');
const buf = new ArrayBuffer(1024 * 1024);

// ❌ Bad: clones 1MB (slow, doubles memory)
worker.postMessage({ buf });

// ✅ Good: zero-copy transfer
worker.postMessage({ buf }, [buf]);
console.log(buf.byteLength); // 0  -> detached in sender
```

**Edge cases**
- Accessing a detached buffer's `.byteLength` returns `0`; slicing it throws `TypeError`.
- Listing the same buffer twice in the transfer list throws `DataCloneError`.
- Functions, DOM nodes, `WeakRef`, and `Proxy` objects **cannot** be cloned at all.

```js
// worker.js
self.onmessage = (e) => {
  const v = new Uint8Array(e.data.buf);
  console.log(v.length); // 1048576
};
```

---

## 2. Race conditions on shared memory

Without synchronization, increments are lost.

```js
// ❌ Racy
self.onmessage = () => {
  const v = new Int32Array(sharedBuf);
  for (let i = 0; i < 1e6; i++) v[0]++; // lost updates
};
```

```js
// ✅ Atomic
const v = new Int32Array(sharedBuf);
for (let i = 0; i < 1e6; i++) Atomics.add(v, 0, 1);
```

**Note:** `Atomics` only works on **integer** TypedArrays backed by `SharedArrayBuffer`. Floats need manual CAS loops or scaled integers.

---

## 3. `Atomics.wait` is illegal on the main thread (browsers)

Calling `Atomics.wait` on the main thread throws `TypeError` (it would freeze the UI). Use `Atomics.waitAsync` (returns a Promise) on the main thread.

```js
// main thread
const sab = new SharedArrayBuffer(4);
const view = new Int32Array(sab);

const { async, value } = Atomics.waitAsync(view, 0, 0);
if (async) {
  value.then(() => console.log('worker notified me'));
}
```

```js
// worker
Atomics.store(view, 0, 1);
Atomics.notify(view, 0, 1);
```

---

## 4. Deadlocks with locks / `wait`/`notify`

A classic two-lock deadlock, plus the risk of a worker dying while holding a mutex.

```js
// Minimal (buggy) mutex
function lock(view, idx) {
  while (Atomics.compareExchange(view, idx, 0, 1) !== 0) {
    Atomics.wait(view, idx, 1); // blocks until notify
  }
}
function unlock(view, idx) {
  Atomics.store(view, idx, 0);
  Atomics.notify(view, idx, 1);
}
```

**Edge cases**
- If the holder is `terminate()`d, the lock stays held forever → all waiters hang. Add an **owner id** + **timeout** (`Atomics.wait(view, idx, expected, timeoutMs)` returns `'timed-out'`).
- Lock ordering must be global to avoid AB-BA deadlocks.
- `Atomics.wait` with no matching `notify` hangs permanently.

Safer pattern:

```js
function tryLock(view, idx, timeoutMs = 1000) {
  const start = Date.now();
  while (true) {
    if (Atomics.compareExchange(view, idx, 0, 1) === 0) return true;
    const r = Atomics.wait(view, idx, 1, Math.max(0, timeoutMs - (Date.now() - start)));
    if (r === 'timed-out') return false;
  }
}
```

---

## 5. Worker errors, load failures, and termination

Workers fail silently unless you wire handlers. A missing script fires `error`, not a thrown exception in the caller.

```js
const w = new Worker('./maybe-missing.js');

w.onerror = (e) => {
  console.error('worker error:', e.message, e.filename, e.lineno);
  e.preventDefault(); // prevent default console dump in some browsers
};
w.onmessageerror = (e) => console.error('deserialization failed', e);

// Uncaught promise rejections inside worker
w.addEventListener('message', (e) => { /* ... */ });
```

Inside the worker:

```js
// worker.js
self.addEventListener('unhandledrejection', (e) => {
  self.postMessage({ type: 'fatal', reason: String(e.reason) });
  e.preventDefault();
});
```

**Termination edge cases**
- `worker.terminate()` (browser) / `worker.terminate()` (Node) kills immediately; in-flight `postMessage` may be dropped.
- Terminating a worker that is inside `Atomics.wait` releases it abruptly; do not assume cleanup ran.

---

## 6. Message ordering & correlation

`postMessage` is FIFO **per worker**, but if you process asynchronously (e.g., `await fetch`), responses can overtake each other. Always correlate with request ids.

```js
let nextId = 0;
const pending = new Map();

function request(worker, payload) {
  const id = ++nextId;
  return new Promise((resolve) => {
    pending.set(id, resolve);
    worker.postMessage({ id, payload });
  });
}

worker.onmessage = (e) => {
  const { id, result } = e.data;
  pending.get(id)?.(result);
  pending.delete(id);
};
```

---

## 7. Scope isolation (no closures)

Workers run in a separate global scope. They cannot see main-thread variables, DOM, or modules unless imported.

```js
// ❌ ReferenceError inside worker
const factor = 2;
const w = new Worker('./w.js'); // w.js tries to use `factor`
```

Pass data explicitly:

```js
const w = new Worker('./w.js');
w.postMessage({ factor: 2 });
```

```js
// w.js
self.onmessage = ({ data }) => {
  self.postMessage(data.factor * 42);
};
```

---

## 8. Module workers vs. classic workers

```js
// Module worker (ESM)
const w = new Worker('./worker.mjs', { type: 'module' });
```

**Edge cases**
- Module workers require same-origin or CORS; Blob workers inherit the page origin.
- `importScripts()` is **not available** in module workers; use `import`.
- Top-level `await` in a module worker delays `message` events until resolution.
- Classic workers cannot use `import` statements.

---

## 9. `SharedArrayBuffer` availability (COOP/COEP)

In browsers, `SharedArrayBuffer` is only available in a **cross-origin isolated** context.

```js
if (typeof SharedArrayBuffer === 'undefined') {
  console.warn('SAB unavailable; require COOP/COEP headers');
}
console.log('crossOriginIsolated =', crossOriginIsolated);
```

Required response headers:

```
Cross-Origin-Opener-Policy: same-origin
Cross-Origin-Embedder-Policy: require-corp
```

Node.js: `SharedArrayBuffer` is always available; pass via `workerData` or `postMessage` (shared, not copied).

---

## 10. Node.js `worker_threads` specifics

```js
// main.js
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

if (isMainThread) {
  const sab = new SharedArrayBuffer(4);
  const v = new Int32Array(sab);
  Atomics.store(v, 0, 0);

  const w = new Worker(__filename, { workerData: sab });
  w.on('message', (m) => console.log('from worker:', m));
  w.on('error', (e) => console.error(e));
  w.on('exit', (code) => console.log('exit', code));
} else {
  const v = new Int32Array(workerData);
  Atomics.add(v, 0, 1);
  // stdout may be buffered/interleaved across workers
  parentPort.postMessage('done');
}
```

**Edge cases**
- `workerData` is **cloned** (structured clone) unless you pass a `SharedArrayBuffer`/`ArrayBuffer` and transfer it.
- `stdout: true` option is needed to capture worker `console.log`; otherwise output may be lost/buffered.
- Unhandled rejections in a worker emit `'error'` on the `Worker` instance in Node (not `unhandledrejection` globally).
- `resourceLimits` (maxOldGenerationSizeMb, etc.) can cause silent OOM kills.
- Workers are not OS threads; `Atomics.wait` blocks the worker's event loop entirely.

---

## 11. Backpressure / unbounded queues

Posting messages faster than the worker consumes them grows memory without bound.

```js
// Flow control with acks
async function pump(worker, items) {
  for (const item of items) {
    worker.postMessage(item);
    await new Promise((res) => {
      const handler = (e) => {
        if (e.data?.ack) { worker.removeEventListener('message', handler); res(); }
      };
      worker.addEventListener('message', handler);
    });
  }
}
```

Better: batch work and use a fixed-size worker pool.

---

## 12. Atomics on non-shared / wrong backing (throws)

```js
try {
  const v = new Int32Array(new ArrayBuffer(4)); // not shared
  Atomics.add(v, 0, 1);
} catch (e) {
  console.log(e.name); // TypeError
}
```

Also, `Atomics.wait` requires the typed array's buffer to be a `SharedArrayBuffer`; otherwise `TypeError`.

---

## 13. Resizable buffers & views

With resizable `ArrayBuffer`/`SharedArrayBuffer`, a view's `.length` can change. Don't cache lengths across await points; re-read.

```js
const sab = new SharedArrayBuffer(4, { maxByteLength: 1024 });
const v = new Int32Array(sab);
// Another thread may grow it; v.length reflects current size at read time for resizable? 
// Access via v.length each iteration rather than a captured constant.
```

---

## 14. Floating point & non-integer atomics

`Atomics` has no float operations. For a shared float counter, scale to integer or use a lock.

```js
// Store cents as integer to avoid float races
Atomics.add(intView, 0, Math.round(delta * 100));
```

---

## 15. Cross-origin & CSP restrictions

- Worker script URL must be same-origin or CORS-enabled; `blob:`/`data:` URLs inherit origin.
- `importScripts`/module imports are subject to CSP `worker-src`.
- `SharedArrayBuffer` in iframes requires the iframe itself to be cross-origin isolated.

---

## 16. Worker pool reuse & startup cost

Creating a worker costs ~a few ms and memory. Reuse via a pool; don't spawn per task.

```js
class Pool {
  constructor(size, url) {
    this.workers = Array.from({ length: size }, () => new Worker(url));
    this.queue = [];
    this.free = [...this.workers];
    this.workers.forEach((w) => {
      w.onmessage = (e) => {
        const cb = w._cb; w._cb = null;
        this.free.push(w);
        cb?.(e.data);
        this.drain();
      };
    });
  }
  run(payload) {
    return new Promise((resolve) => {
      const job = { payload, resolve };
      this.queue.push(job);
      this.drain();
    });
  }
  drain() {
    while (this.free.length && this.queue.length) {
      const w = this.free.pop();
      const job = this.queue.shift();
      w._cb = job.resolve;
      w.postMessage(job.payload);
    }
  }
}
```

---

## Summary checklist

| Risk | Mitigation |
|---|---|
| Lost updates on shared state | `Atomics.*` |
| Main-thread `Atomics.wait` | Use `Atomics.waitAsync` |
| Deadlock / abandoned lock | Timeouts + owner ids |
| Detached buffers | Don't use after transfer |
| Uncaught worker errors | `onerror`, `unhandledrejection` |
| Reordered async responses | Request-id correlation |
| Memory blowup | Backpressure / pooling |
| No SAB available | Check `crossOriginIsolated` |
| Non-cloneable payloads | Transfer or restructure |
| Node stdout/OOM | `stdout: true`, `resourceLimits` |

If you want, I can drill into any one of these (e.g., a full mutex/condition-variable implementation, or a worker pool with cancellation).

Below is a complete, runnable JavaScript file that demonstrates common, idiomatic naming conventions. You can save it as `namingConventions.js` and run it with Node.js (`node namingConventions.js`).

```js
// namingConventions.js
// Demonstrates idiomatic JavaScript naming conventions.

'use strict';

// ---------------------------------------------------------------------------
// 1. CONSTANTS: UPPER_SNAKE_CASE
//    Use for values that never change at runtime.
// ---------------------------------------------------------------------------
const MAX_RETRY_COUNT = 3;
const DEFAULT_TIMEOUT_MS = 5000;
const API_BASE_URL = 'https://api.example.com';

// ---------------------------------------------------------------------------
// 2. Variables & parameters: camelCase
//    Use for mutable/immutable local variables and function parameters.
// ---------------------------------------------------------------------------
let retryCount = 0;
let lastError = null;

// ---------------------------------------------------------------------------
// 3. Booleans: prefix with is/has/can/should (camelCase)
// ---------------------------------------------------------------------------
let isLoading = false;
let hasPermission = true;
let canRetry = true;
let shouldLogErrors = true;

// ---------------------------------------------------------------------------
// 4. Functions: camelCase, verb-first, descriptive
// ---------------------------------------------------------------------------
function fetchUserProfile(userId) {
  // Simulated async fetch
  return Promise.resolve({
    id: userId,
    name: 'Ada Lovelace',
    email: 'ada@example.com',
  });
}

function calculateTotalPrice(items, taxRate) {
  const subtotal = items.reduce((sum, item) => sum + item.price, 0);
  return subtotal * (1 + taxRate);
}

// ---------------------------------------------------------------------------
// 5. Classes & constructors: PascalCase
// ---------------------------------------------------------------------------
class HttpClient {
  // Private fields: #camelCase (true privacy)
  #baseUrl;
  #defaultHeaders;

  constructor(baseUrl, defaultHeaders = {}) {
    this.#baseUrl = baseUrl;
    this.#defaultHeaders = defaultHeaders;
  }

  // Public methods: camelCase
  async get(path) {
    const url = `${this.#baseUrl}${path}`;
    // Simulated request
    return { url, status: 200, data: {} };
  }

  // Getter: noun phrase, camelCase
  get baseUrl() {
    return this.#baseUrl;
  }
}

// ---------------------------------------------------------------------------
// 6. Enums / frozen constant objects: PascalCase object, UPPER_SNAKE keys
// ---------------------------------------------------------------------------
const HttpStatus = Object.freeze({
  OK: 200,
  NOT_FOUND: 404,
  SERVER_ERROR: 500,
});

// ---------------------------------------------------------------------------
// 7. Event handlers: handle<EventName> or on<EventName>
// ---------------------------------------------------------------------------
function handleUserClick(event) {
  console.log('Clicked:', event.target.id);
}

// ---------------------------------------------------------------------------
// 8. Factory functions: createX or makeX (camelCase)
// ---------------------------------------------------------------------------
function createUserProfile({ name, email }) {
  return {
    id: crypto.randomUUID(),
    name,
    email,
    createdAt: new Date(),
  };
}

// ---------------------------------------------------------------------------
// 9. Module-level "private" helpers: underscore prefix (convention only)
//    Note: prefer #private fields in classes; _ is a soft convention for
//    module/function scope.
// ---------------------------------------------------------------------------
function _formatDate(date) {
  return date.toISOString().split('T')[0];
}

// ---------------------------------------------------------------------------
// 10. Acronyms: treat as words (Http, not HTTP) except in constants
// ---------------------------------------------------------------------------
class HttpServerError extends Error {
  constructor(message) {
    super(message);
    this.name = 'HttpServerError';
  }
}

// ---------------------------------------------------------------------------
// Demo / runnable usage
// ---------------------------------------------------------------------------
async function main() {
  console.log('--- Constants ---');
  console.log(MAX_RETRY_COUNT, DEFAULT_TIMEOUT_MS, API_BASE_URL);

  console.log('\n--- Variables & booleans ---');
  retryCount = 1;
  isLoading = true;
  console.log({ retryCount, isLoading, hasPermission, canRetry });

  console.log('\n--- Functions ---');
  const profile = await fetchUserProfile(42);
  console.log(profile);

  const total = calculateTotalPrice(
    [{ price: 10 }, { price: 20 }],
    0.08
  );
  console.log('Total:', total);

  console.log('\n--- Class ---');
  const client = new HttpClient(API_BASE_URL, { 'X-Api-Key': 'secret' });
  const response = await client.get('/users');
  console.log(response);
  console.log('Base URL:', client.baseUrl);

  console.log('\n--- Enum ---');
  console.log(HttpStatus.OK, HttpStatus.NOT_FOUND);

  console.log('\n--- Factory ---');
  const user = createUserProfile({ name: 'Grace', email: 'grace@example.com' });
  console.log(user);

  console.log('\n--- Helper ---');
  console.log(_formatDate(new Date()));

  console.log('\n--- Error class ---');
  try {
    throw new HttpServerError('Something broke');
  } catch (err) {
    console.log(err.name, err.message);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
```

### Naming convention summary

| Kind | Convention | Example |
|---|---|---|
| Constants (immutable) | `UPPER_SNAKE_CASE` | `MAX_RETRY_COUNT` |
| Variables / params | `camelCase` | `retryCount` |
| Booleans | `is/has/can/should` + camelCase | `isLoading` |
| Functions | camelCase, verb-first | `fetchUserProfile` |
| Classes / constructors | `PascalCase` | `HttpClient` |
| Private class fields | `#camelCase` | `#baseUrl` |
| Enum objects | `PascalCase` object, `UPPER_SNAKE` keys | `HttpStatus.OK` |
| Event handlers | `handleX` / `onX` | `handleUserClick` |
| Factories | `createX` / `makeX` | `createUserProfile` |
| Acronyms in identifiers | Treat as word (unless constant) | `HttpClient`, `HttpServerError` |
| Soft-private helpers | `_camelCase` (convention only) | `_formatDate` |

### Notes for real projects
- Prefer **`#private` fields** over `_underscore` for true encapsulation.
- Avoid Hungarian notation (e.g., `strName`, `arrItems`)—types belong in TypeScript/JSDoc, not names.
- Name things by **intent**, not implementation (`getUserById`, not `queryUsersTable`).
- Keep abbreviations consistent and short (`id`, `url`, `http` are fine; `usr`, `btn` are usually unnecessary).
- In TypeScript, interfaces/types often use `PascalCase` too (`interface User`, `type UserId = string`).

## Naming Conventions in JavaScript

### 1. The idea

Naming conventions are **agreed-upon stylistic rules** for identifiers (variables, functions, classes, etc.). The JavaScript engine only enforces *syntax*; conventions are for humans:

- **Readability** – code reads like prose.
- **Predictability** – `getUserById` clearly does what it says.
- **Scope signaling** – `MAX_RETRIES` vs. `retryCount` vs. `RetryManager` tell you the kind of thing you’re looking at.
- **Tooling consistency** – linters (ESLint) and formatters rely on conventions.

There is no single “official” standard, but the community largely follows **camelCase for identifiers**, **PascalCase for types/constructors**, and **UPPER_SNAKE_CASE for constants**.

---

### 2. Syntax rules (what the engine allows)

```js
// Valid identifiers
let userName;
let _private;
let $element;
let π;            // Unicode letter allowed (but avoid in practice)
let user2;

// Invalid
// let 2user;     // cannot start with digit
// let user-name; // '-' is subtraction
// let class;     // reserved word
```

Key points:

- **Case-sensitive**: `name` ≠ `Name` ≠ `NAME`.
- **Reserved words** cannot be used as identifiers in certain contexts (`class`, `function`, `let`, etc.).
- **Unicode** is technically allowed, but stay with ASCII for portability.
- **No hyphens** in identifiers; use camelCase instead.

---

### 3. Common styles and use cases

#### camelCase — variables & functions

```js
let firstName = "Ada";
let itemCount = 0;

function calculateTotal(price, taxRate) {
  return price * (1 + taxRate);
}
```

#### PascalCase — classes, constructors, components (React/Vue)

```js
class UserRepository {
  constructor(db) {
    this.db = db;
  }
}

function Person(name) {   // constructor function (legacy style)
  this.name = name;
}
```

#### UPPER_SNAKE_CASE — constants (especially module-level)

```js
const MAX_RETRIES = 3;
const API_BASE_URL = "https://api.example.com";
const DEFAULT_TIMEOUT_MS = 5000;
```

> Tip: Only use `UPPER_SNAKE` for values that are truly constant across the module. A `const` that holds a mutable object or a derived value usually stays camelCase.

#### Boolean prefixes — `is`, `has`, `can`, `should`

```js
const isActive = true;
const hasPermission = user.roles.includes("admin");
const canEdit = isActive && hasPermission;
```

#### Collections — plural nouns

```js
const users = [];
const activeSessions = new Map();
```

#### Event handlers — `handleX` / `onX`

```js
function handleClick(event) { /* ... */ }
button.addEventListener("click", handleClick);

// React-style
<Button onClick={handleClick} />
```

#### Private members — `_` (convention) vs `#` (real privacy)

```js
// Convention only (still accessible)
class Counter {
  constructor() {
    this._count = 0;
  }
  increment() {
    this._count++;
  }
}

// True privacy (ES2022)
class SafeCounter {
  #count = 0;
  increment() {
    this.#count++;
  }
  get value() {
    return this.#count;
  }
}
```

#### Async functions — verb-first, describe the action

```js
async function fetchUser(id) { /* ... */ }
async function loadConfig() { /* ... */ }
```

#### File/module names — often kebab-case or camelCase

```text
user-repository.js     // kebab-case (common in Node/web)
userRepository.js      // camelCase (also common)
UserRepository.ts      // PascalCase (sometimes for class-per-file)
```

---

### 4. Putting it together

```js
// constants.js
export const MAX_LOGIN_ATTEMPTS = 5;
export const DEFAULT_LOCALE = "en-US";

// user-service.js
import { MAX_LOGIN_ATTEMPTS } from "./constants.js";

class UserService {
  #attempts = 0;

  constructor(apiClient) {
    this.apiClient = apiClient;
  }

  async fetchUserById(id) {
    return this.apiClient.get(`/users/${id}`);
  }

  canRetry() {
    return this.#attempts < MAX_LOGIN_ATTEMPTS;
  }
}

function handleLoginSuccess(user) {
  console.log(`Welcome, ${user.name}`);
}

export { UserService, handleLoginSuccess };
```

---

### 5. Practical guidelines

- **Be consistent** within a codebase; pick a style guide (Airbnb, Standard, Google) and enforce with ESLint.
- **Avoid abbreviations** unless universally understood (`id`, `url`, `ctx` are fine; `usrNm` is not).
- **Name by intent**, not implementation: `calculateTax` > `doMath`.
- **Match casing to kind**: a function returning a class/factory may be PascalCase; otherwise camelCase.
- **Don’t encode types in names** (`userArray` → `users`; TypeScript/JSDoc already carry types).

These conventions are not enforced by the runtime, but following them makes JavaScript codebases far easier to read, review, and maintain.

## Mistaken version

```js
function user(name, email) {
  this.name = name;
  this.email = email;
}

const User = new user("Ada", "ada@example.com");
const isactive = true;

console.log(User, isactive);
```

## Corrected version

```js
function User(name, email) {
  this.name = name;
  this.email = email;
}

const user = new User("Ada", "ada@example.com");
const isActive = true;

console.log(user, isActive);
```

## What was wrong and why

1. **Constructor/class name was lowercase (`user`)**  
   In JavaScript, constructor functions and classes conventionally use **PascalCase** (`User`). This signals to readers that the function is meant to be called with `new`. A lowercase name suggests an ordinary function, making the code harder to understand and increasing the risk of calling it incorrectly.

2. **Instance variable was uppercase (`User`)**  
   Ordinary variables and object instances conventionally use **camelCase** (`user`). Uppercase names are usually reserved for constructors/classes or constants, so `const User = new user(...)` visually reverses the expected roles.

3. **Boolean was not prefixed clearly (`isactive`)**  
   Boolean values are commonly named with prefixes such as `is`, `has`, `can`, or `should`, and use camelCase: `isActive`. This makes the variable’s meaning obvious without needing to inspect its value.

### Convention summary

- **Classes / constructors**: `PascalCase` → `User`, `HttpClient`
- **Variables / functions / methods**: `camelCase` → `user`, `getUser`, `isActive`
- **Constants**: `UPPER_SNAKE_CASE` → `MAX_RETRIES`
- **Booleans**: prefer `is…`, `has…`, `can…`, `should…`

These conventions are not enforced by the language, but following them makes code self-documenting and consistent with most JavaScript style guides.

## Common naming-convention pitfalls in JavaScript

Below are frequent pitfalls, why they matter, and idiomatic fixes.

### 1. Mixing casing conventions
JavaScript convention: `camelCase` for variables/functions, `PascalCase` for classes/constructors, `UPPER_SNAKE_CASE` for true compile-time constants.

```js
// Bad
const user_name = "Ada";
class userAccount {}
function GetUserName() {}

// Good
const userName = "Ada";
class UserAccount {}
function getUserName() {}
```

### 2. Vague or generic names
Names like `data`, `info`, `temp`, `obj` force readers to inspect implementation.

```js
// Bad
function process(data) {
  return data.map(x => x.value);
}

// Good
function extractValues(records) {
  return records.map(record => record.value);
}
```

### 3. Unclear abbreviations
Short names save keystrokes but cost readability.

```js
// Bad
const usr = getUser();
const btn = document.querySelector("#submit");

// Good
const user = getUser();
const submitButton = document.querySelector("#submit");
```

### 4. Booleans without a predicate prefix
A boolean should read like a question/condition.

```js
// Bad
const active = true;
const visible = false;

// Good
const isActive = true;
const isVisible = false;
```

### 5. Singular/plural confusion for collections
Use plural for arrays/collections and singular for single items.

```js
// Bad
const user = ["Ada", "Grace"];
for (const users of user) console.log(users);

// Good
const users = ["Ada", "Grace"];
for (const user of users) console.log(user);
```

### 6. Shadowing built-ins or outer variables
Reusing names like `name`, `length`, `constructor`, or loop variables can cause subtle bugs.

```js
// Bad
const name = "Ada"; // shadows window.name in browsers
function describe(user) {
  const name = user.name; // shadows outer `name`
  return name;
}

// Good
const displayName = "Ada";
function describe(user) {
  const userName = user.name;
  return userName;
}
```

### 7. Using reserved/awkward words
Avoid reserved words and names that collide with common globals.

```js
// Bad
const class = "A";        // SyntaxError
const default = 5;        // SyntaxError
let name = "Ada";         // string coercion quirks in some contexts

// Good
const className = "A";
const defaultValue = 5;
const userName = "Ada";
```

### 8. Hungarian notation / type-encoded names
Modern JS + TypeScript makes type prefixes noise.

```js
// Bad
const strName = "Ada";
const arrUsers = [];
const bIsActive = true;

// Good
const name = "Ada";
const users = [];
const isActive = true;
```

### 9. Missing units in numeric names
Ambiguous time/size values cause integration bugs.

```js
// Bad
const timeout = 5000;
const maxFileSize = 10;

// Good
const timeoutMs = 5000;
const maxFileSizeBytes = 10 * 1024 * 1024;
```

### 10. Negated boolean names
Double negatives make conditions hard to read.

```js
// Bad
const isNotValid = !isValid;
if (!isNotValid) { /* ... */ }

// Good
const isValid = true;
if (isValid) { /* ... */ }
```

### 11. Relying on underscore for “privacy”
`_private` is only a convention; use `#private` for real encapsulation.

```js
// Bad (convention only, still accessible)
class Counter {
  _count = 0;
  increment() { this._count++; }
}

// Good (truly private)
class Counter {
  #count = 0;
  increment() { this.#count++; }
  get value() { return this.#count; }
}
```

### 12. Overusing UPPER_CASE for non-constants
Reserve `UPPER_SNAKE_CASE` for immutable, compile-time constants.

```js
// Bad
let MAX_RETRIES = 3; // mutable, not a true constant
MAX_RETRIES = 5;

// Good
const MAX_RETRIES = 3;
let retriesLeft = MAX_RETRIES;
```

### 13. Inconsistent event-handler naming
Pick one convention (`handleX` for internal handlers, `onX` for props/callbacks).

```js
// Bad
<button onClick={clickHandler}>Save</button>
// mixed with
<button onClick={onClick}>Save</button>

// Good
<button onClick={handleSaveClick}>Save</button>
// and for a reusable component prop:
<UserCard onUserSelect={handleUserSelect} />
```

### 14. Async functions without clear intent (optional but helpful)
When async matters for correctness, name it explicitly or document it.

```js
// Ambiguous
async function getUser(id) { /* network call */ }

// Clearer
async function fetchUser(id) { /* network call */ }
function getCachedUser(id) { /* sync cache read */ }
```

### 15. Destructuring rename pitfalls
Renaming can obscure source; keep names aligned unless there’s a reason.

```js
// Bad: confusing rename
const { name: n, age: a } = user;

// Good
const { name, age } = user;

// Acceptable when resolving collisions
const { name: userName, age: userAge } = user;
```

### 16. Default export name mismatches
Default exports can be imported under any name, causing inconsistency.

```js
// Bad: file exports default but callers name it differently
// utils.js
export default function formatCurrency() {}
// app.js
import money from "./utils.js"; // name drift

// Good: prefer named exports for shared utilities
export function formatCurrency() {}
import { formatCurrency } from "./utils.js";
```

### 17. Inconsistent acronym casing
Choose a rule and apply it everywhere (common: capitalize only first letter).

```js
// Bad
const XMLHTTPRequest = ...;
const HTTPServer = ...;

// Good (consistent)
const XmlHttpRequest = ...;
const HttpServer = ...;

// Also acceptable if team standard is all-caps acronyms, but be consistent:
const XMLHttpRequest = ...;
```

### 18. Single-letter variables outside tiny scopes
`i`, `j`, `x` are fine in tight loops; elsewhere they hurt readability.

```js
// Bad
const x = calculateTotal(cart);
const y = applyDiscount(x);

// Good
const subtotal = calculateTotal(cart);
const finalTotal = applyDiscount(subtotal);
```

### 19. Catch-all error names
Use `error` (or domain-specific) instead of `e`/`err` inconsistently.

```js
// Bad
try { ... } catch (e) { console.error(e); }

// Good
try { ... } catch (error) {
  console.error("Failed to load user:", error);
}
```

### 20. Magic numbers without named constants
Unnamed literals hide intent and make updates risky.

```js
// Bad
if (retries > 3) { ... }
setTimeout(fn, 86400000);

// Good
const MAX_RETRIES = 3;
const ONE_DAY_MS = 24 * 60 * 60 * 1000;

if (retries > MAX_RETRIES) { ... }
setTimeout(fn, ONE_DAY_MS);
```

### Practical checklist
- Use `camelCase` / `PascalCase` / `UPPER_SNAKE_CASE` consistently.
- Prefer descriptive names over abbreviations.
- Prefix booleans with `is`, `has`, `can`, `should`.
- Keep units in numeric names (`Ms`, `Bytes`, `Px`).
- Avoid shadowing and reserved words.
- Use real private fields (`#`) when encapsulation matters.
- Prefer named exports for shared APIs.

## Exercise

You are given this small, inconsistently named JavaScript module. Refactor only the **identifiers** so the code follows common JavaScript naming conventions:

- Constants: `UPPER_SNAKE_CASE`
- Variables, parameters, functions: `camelCase`, descriptive
- Classes/constructors: `PascalCase`
- Booleans: `is…`, `has…`, or `can…`
- Avoid abbreviations and single-letter names except tiny loop indices

### Starting code

```js
