let usr = null;

function fetchusr(id, cb) {
  if (usr !== null) return usr;
  // pretend async fetch
  usr = { id, name: "Ada" };
  cb(usr);
}

class profile {
  constructor(name) {
    this.name = name;
  }
}

let flag = true;

