## Quick checklist

| Edge case | Symptom | Fix |
|---|---|---|
| Forgotten unsubscribe | Memory leak | Return handle; use `WeakRef` |
| Duplicate subscription | Double notification | `Set`/`Map` keyed by identity or id |
| `this` loss | TypeError | `bind` or arrow wrapper |
| Throwing observer | Chain aborted | try/catch per observer |
| Mutation during notify | Skipped observers | Snapshot with `[...collection]` |
| Re-entrancy | Nested/unbounded calls | Queue + `notifying` flag |
| Async observers | Ordering/rejection issues | Define sync/async contract; `allSettled` |
| Stale closures | Wrong captured values | Pass state via payload |
| Payload mutation | Cross-observer corruption | `freeze`/`clone` |
| Handle reuse | Throws on second unsub | Idempotent unsubscribe |
| GC of observers | Leaked or premature GC | `WeakRef` + `FinalizationRegistry` |
| Identity dedup | Bound fns not deduped | Key by explicit id |
| Destroyed subject | Use-after-destroy | `destroyed` guard |
| Backpressure | Producer stalls | Coalesce/batch/queue |
| AbortSignal | Manual cleanup boilerplate | `signal` option |
| Ordering | Wrong precedence | Priority buckets |
| Error policy | Inconsistent handling | Single documented policy |

If you tell me your runtime (browser vs Node) and whether observers are sync or async, I can tailor this to a smaller, focused implementation.

JavaScript has **no native operator overloading**. Operators like `+`, `*`, `==` are hard-wired by the language: for objects, `+` always coerces via `ToPrimitive` (which must yield a primitive), and `==`/`===` compare references or primitives. You cannot make `a + b` return an arbitrary object purely with language syntax.

What you *can* do, in increasing power:

1. **Native coercion hooks** (`Symbol.toPrimitive`, `valueOf`, `toString`) — partial overloading, result must be a primitive.
2. **Method dispatch** (`a.add(b)`) — full control, not infix.
3. **Infix via a tagged-template DSL** — real infix syntax, operators dispatched to methods.
4. **Transpilation** (Babel) — true infix on variables, build step required.

Below is a complete, runnable Node script demonstrating (1) and (3), plus a `Money` and `Complex` type.

## Complete runnable example

Save as `overload.js` and run with `node overload.js`.

```js
/* ============================================================
   1. Native coercion hooks (partial operator overloading)
   ============================================================ */
class Money {
  constructor(amount, currency = 'USD') {
    this.amount = amount;
    this.currency = currency;
  }
  // Arithmetic on Money coerces to a number (loses type, but works for scalars)
  valueOf() { return this.amount; }
  [Symbol.toPrimitive](hint) {
    if (hint === 'string') return this.toString();
    return this.amount;
  }
  toString() { return `${this.currency} ${this.amount.toFixed(2)}`; }

  // Real Money arithmetic (keep type)
  add(o) {
    const other = o instanceof Money ? o.amount : o;
    if (o instanceof Money && o.currency !== this.currency) throw new Error('currency mismatch');
    return new Money(this.amount + other, this.currency);
  }
  sub(o) {
    const other = o instanceof Money ? o.amount : o;
    return new Money(this.amount - other, this.currency);
  }
  mul(o) {
    const other = o instanceof Money ? o.amount : o;
    return new Money(this.amount * other, this.currency);
  }
  neg() { return new Money(-this.amount, this.currency); }
  eq(o) {
    return o instanceof Money && o.currency === this.currency && o.amount === this.amount;
  }
}

/* ============================================================
   2. A richer type: Complex numbers
   ============================================================ */
class Complex {
  constructor(re, im) { this.re = re; this.im = im; }
  add(o) { return new Complex(this.re + o.re, this.im + o.im); }
  sub(o) { return new Complex(this.re - o.re, this.im - o.im); }
  mul(o) { return new Complex(this.re * o.re - this.im * o.im, this.re * o.im + this.im * o.re); }
  div(o) {
    const d = o.re * o.re + o.im * o.im;
    return new Complex((this.re * o.re + this.im * o.im) / d,
                      (this.im * o.re - this.re * o.im) / d);
  }
  pow(n) {
    if (typeof n !== 'number' || !Number.isInteger(n)) throw new TypeError('Complex.pow expects integer');
    if (n === 0) return new Complex(1, 0);
    if (n < 0) return this.pow(-n).inv();
    let res = new Complex(1, 0), base = this, e = n;
    while (e > 0) {
      if (e & 1) res = res.mul(base);
      base = base.mul(base);
      e >>= 1;
    }
    return res;
  }
  inv() { const d = this.re * this.re + this.im * this.im; return new Complex(this.re / d, -this.im / d); }
  neg() { return new Complex(-this.re, -this.im); }
  eq(o) { return o instanceof Complex && o.re === this.re && o.im === this.im; }
  ne(o) { return !this.eq(o); }
  toString() { return `${this.re}${this.im >= 0 ? '+' : ''}${this.im}i`; }
  // magnitude as primitive coercion
  valueOf() { return Math.hypot(this.re, this.im); }
  [Symbol.toPrimitive](hint) {
    if (hint === 'string') return this.toString();
    return this.re; // cannot represent fully as one number; honest limitation
  }
}

/* ============================================================
   3. Infix operator overloading via a tagged template DSL
      Usage:  calc`${a} + ${b} * ${c}`
   ============================================================ */
function tokenize(s) {
  const toks = [];
  let i = 0;
  while (i < s.length) {
    if (/\s/.test(s[i])) { i++; continue; }
    if (/\d/.test(s[i]) || (s[i] === '.' && /\d/.test(s[i + 1] || ''))) {
      let j = i;
      while (j < s.length && /[\d.]/.test(s[j])) j++;
      toks.push({ type: 'num', value: s.slice(i, j) });
      i = j; continue;
    }
    if (/[A-Za-z_]/.test(s[i])) {
      let j = i;
      while (j < s.length && /\w/.test(s[j])) j++;
      toks.push({ type: 'id', value: s.slice(i, j) });
      i = j; continue;
    }
    const two = s.slice(i, i + 2);
    if (['**', '==', '!=', '<=', '>='].includes(two)) {
      toks.push({ type: 'op', value: two }); i += 2; continue;
    }
    if ('+-*/%()<>'.includes(s[i])) {
      toks.push({ type: 'op', value: s[i] }); i++; continue;
    }
    throw new Error('Unexpected character: ' + JSON.stringify(s[i]));
  }
  return toks;
}

const PREC = {
  '||': 1, '&&': 2,
  '==': 3, '!=': 3, '<': 3, '>': 3, '<=': 3, '>=': 3,
  '+': 4, '-': 4,
  '*': 5, '/': 5, '%': 5,
  '**': 6,
};

const METHOD = {
  '+': 'add', '-': 'sub', '*': 'mul', '/': 'div', '**': 'pow',
  '%': 'mod', '==': 'eq', '!=': 'ne', '<': 'lt', '>': 'gt',
  '<=': 'le', '>=': 'ge',
};

function applyOp(op, a, b) {
  const m = METHOD[op];
  // Try left operand's method first
  if (m && a != null && typeof a[m] === 'function') return a[m](b);
  // Commutative fallback: right operand's method
  if (m && b != null && typeof b[m] === 'function' && ['+', '*', '==', '!='].includes(op)) {
    return b[m](a);
  }
  // Native fallback
  switch (op) {
    case '+': return a + b;
    case '-': return a - b;
    case '*': return a * b;
    case '/': return a / b;
    case '%': return a % b;
    case '**': return a ** b;
    case '==': return a == b;
    case '!=': return a != b;
    case '<': return a < b;
    case '>': return a > b;
    case '<=': return a <= b;
    case '>=': return a >= b;
    default: throw new Error('Unknown operator ' + op);
  }
}

function applyUnaryMinus(v) {
  if (v != null && typeof v.neg === 'function') return v.neg();
  return -v;
}

function evaluate(expr, scope) {
  const tokens = tokenize(expr);
  let pos = 0;
  const parse = (minPrec) => {
    let left = parseUnary();
    while (true) {
      const tok = tokens[pos];
      if (!tok || tok.type !== 'op') break;
      const prec = PREC[tok.value];
      if (prec == null || prec < minPrec) break;
      const op = tok.value;
      pos++;
      const nextMin = op === '**' ? prec : prec + 1;
      const right = parse(nextMin);
      left = applyOp(op, left, right);
    }
    return left;
  };
  const parseUnary = () => {
    const tok = tokens[pos];
    if (tok && tok.type === 'op' && (tok.value === '-' || tok.value === '+')) {
      pos++;
      const v = parseUnary();
      return tok.value === '-' ? applyUnaryMinus(v) : v;
    }
    return parseAtom();
  };
  const parseAtom = () => {
    const tok = tokens[pos++];
    if (!tok) throw new Error('Unexpected end of expression');
    if (tok.type === 'num') return Number(tok.value);
    if (tok.type === 'id') {
      if (!(tok.value in scope)) throw new Error('Unknown identifier: ' + tok.value);
      return scope[tok.value];
    }
    if (tok.type === 'op' && tok.value === '(') {
      const v = parse(0);
      if (!tokens[pos] || tokens[pos].value !== ')') throw new Error('Expected )');
      pos++;
      return v;
    }
    throw new Error('Unexpected token: ' + JSON.stringify(tok));
  };
  const result = parse(0);
  if (pos !== tokens.length) throw new Error('Trailing tokens in expression');
  return result;
}

function calc(strings, ...values) {
  // Rebuild expression with placeholder identifiers bound to the interpolated values.
  let expr = '';
  strings.forEach((s, i) => {
    expr += s;
    if (i < values.length) expr += ` __${i}__ `;
  });
  const scope = {};
  values.forEach((v, i) => { scope[`__${i}__`] = v; });
  return evaluate(expr, scope);
}

