## Final answer

Use `worker.js` to perform the factorial computation in an isolated subprocess, and `parent.js` to spawn workers concurrently, collect their `stdout`, validate exit codes, and aggregate the results. This gives you a small but realistic example of process creation, inter-process communication through pipes, asynchronous result collection, and centralized error handling in Node.js.

## Processes & Subprocesses in JavaScript

JavaScript is **single-threaded per execution context** (one call stack, one event loop), but that does not mean “one OS process.” Modern runtimes give you three concurrency models:

| Concept | Memory | Communication | Use case |
|---|---|---|---|
| **Process** (Node.js main) | Own heap/V8 isolate | — | Normal app |
| **Subprocess** (`child_process`) | Separate OS process, separate V8 instance | IPC channel / stdio pipes | CPU-heavy work, isolation, spawning other binaries |
| **Worker Thread** (`worker_threads`) | Same process, separate V8 isolate (can share `SharedArrayBuffer`) | `postMessage` (structured clone) | CPU-bound JS without process overhead |
| **Web Worker** (browser) | Separate thread | `postMessage` | Off-main-thread browser work |
| **Cluster** (`cluster`) | Multiple processes sharing a port | IPC | Scaling HTTP servers across cores |

Key points for an interview:
- **`fork()`** creates a subprocess that runs a JS file and auto-sets up an IPC channel (`process.send` / `child.on('message')`).
- **`spawn()`** is lower-level: streams for stdio, no IPC unless you request it.
- **`exec()` / `execFile()`** buffer stdout; good for short commands, bad for big output.
- Subprocesses are **isolated**: a crash in a child does not kill the parent. Worker threads share a process, so a fatal error can take down the whole app.
- Communication is **message passing** (structured clone), not shared memory by default. `SharedArrayBuffer` + `Atomics` is the opt-in shared-memory path.
- Backpressure & lifecycle matter: always handle `error`, `exit`, and clean up to avoid zombie processes / leaked workers.

---

### Core implementation: a reusable Worker Thread pool

Below is a self-contained, runnable Node.js module that implements the *core* of subprocess/thread management: **spawn a fixed pool, dispatch tasks, collect results, queue overflow, graceful shutdown**. It uses `worker_threads` so it runs from a single file (true OS subprocesses via `child_process` follow the same lifecycle pattern, just with `fork` + IPC).

```js
// pool.js  — run with: node pool.js
const { Worker, isMainThread, parentPort } = require('worker_threads');

/* ------------------------------------------------------------------ */
/* Worker side: runs in each thread. Listens for tasks, computes, replies */
/* ------------------------------------------------------------------ */
if (!isMainThread) {
  parentPort.on('message', (task) => {
    try {
      // --- replace with real CPU work ---
      const result = heavyCompute(task.payload);
      parentPort.postMessage({ id: task.id, ok: true, result });
    } catch (err) {
      parentPort.postMessage({ id: task.id, ok: false, error: err.message });
    }
  });

  function heavyCompute(n) {
    // Deliberately CPU-bound to demonstrate offloading the main thread.
    let s = 0;
    for (let i = 0; i < n; i++) s += Math.sqrt(i);
    return s;
  }
}

/* ------------------------------------------------------------------ */
/* Main-thread side: pool manager                                       */
/* ------------------------------------------------------------------ */
class WorkerPool {
  constructor(size = 4) {
    this.workers = [];   // { worker, busy, currentJob }
    this.idle = [];      // refs to idle worker objects
    this.queue = [];     // pending jobs when all workers busy
    this.nextId = 1;

    for (let i = 0; i < size; i++) this._spawn();
  }

  _spawn() {
    const w = new Worker(__filename);
    const handle = { worker: w, busy: false, currentJob: null };

    w.on('message', (msg) => this._onMessage(handle, msg));
    w.on('error', (err) => this._onError(handle, err));
    w.on('exit', (code) => {
      if (code !== 0) console.error(`worker exited with code ${code}`);
    });

    this.workers.push(handle);
    this.idle.push(handle);
  }

  /**
   * Run a task on the pool. Returns a Promise resolving to the result.
   * taskPayload: anything structured-cloneable.
   */
  run(taskPayload) {
    const id = this.nextId++;
    return new Promise((resolve, reject) => {
      const job = { id, payload: taskPayload, resolve, reject };

      const handle = this.idle.pop();
      if (handle) {
        this._dispatch(handle, job);
      } else {
        // All workers busy -> queue it (backpressure).
        this.queue.push(job);
      }
    });
  }

  _dispatch(handle, job) {
    handle.busy = true;
    handle.currentJob = job;
    handle.worker.postMessage({ id: job.id, payload: job.payload });
  }

  _onMessage(handle, msg) {
    const job = handle.currentJob;
    handle.currentJob = null;
    handle.busy = false;

    if (msg.ok) job.resolve(msg.result);
    else job.reject(new Error(msg.error));

    // Pull next queued job or mark idle.
    const next = this.queue.shift();
    if (next) this._dispatch(handle, next);
    else this.idle.push(handle);
  }

  _onError(handle, err) {
    const job = handle.currentJob;
    handle.currentJob = null;
    handle.busy = false;
    if (job) job.reject(err);

    // Respawn a fresh worker to keep pool size stable.
    const idx = this.workers.indexOf(handle);
    if (idx !== -1) this.workers.splice(idx, 1);
    const idleIdx = this.idle.indexOf(handle);
    if (idleIdx !== -1) this.idle.splice(idleIdx, 1);

    try { handle.worker.terminate(); } catch (_) {}
    this._spawn();

    const next = this.queue.shift();
    // find the newly spawned handle (last pushed)
    const fresh = this.workers[this.workers.length - 1];
    if (next) this._dispatch(fresh, next);
  }

  async close() {
    await Promise.all(this.workers.map((h) => h.worker.terminate()));
    this.workers = [];
    this.idle = [];
    this.queue = [];
  }
}

/* ------------------------------------------------------------------ */
/* Demo                                                               */
/* ------------------------------------------------------------------ */
(async () => {
  const pool = new WorkerPool(4);

  const inputs = [1e7, 2e7, 3e7, 4e7, 5e7, 6e7];
  const t0 = Date.now();
  const results = await Promise.all(inputs.map((n) => pool.run(n)));
  console.log('results:', results.map((r) => r.toFixed(2)));
  console.log('elapsed:', Date.now() - t0, 'ms');

  await pool.close();
})();
```

### What this demonstrates (interview talking points)

1. **Offloading**: heavy CPU work moves off the main thread; the event loop stays responsive.
2. **Bounded concurrency**: pool size caps resource use; overflow goes into a FIFO queue (backpressure).
3. **Message protocol**: every task carries an `id` so responses can be correlated even if ordering changes.
4. **Failure isolation**: a worker error rejects only its job and triggers a respawn, keeping pool size stable.
5. **Lifecycle**: `close()` terminates all workers; no lingering handles.

### If you truly need *processes* (not threads)

Swap `Worker` for `child_process.fork`:

```js
const { fork } = require('child_process');
const child = fork('./worker.js');          // separate V8 instance
child.send({ id: 1, payload: 1e7 });       // IPC
child.on('message', (msg) => { /* result */ });
child.on('exit', (code) => { /* cleanup */ });
```

Same lifecycle rules apply, but each child costs more memory and startup time, and you lose `SharedArrayBuffer` sharing. Choose subprocesses when you need **crash isolation, sandboxing, or running non-JS binaries**; choose worker threads for **cheap, same-process parallelism**.

Below are the edge cases that most often break production code using Node.js `child_process` (and the same ideas largely apply to Deno/Bun). Each section includes a compact example of the bad pattern and the safer pattern.

---

## 1. `exit` vs. `close`: truncated stdout/stderr

`'exit'` fires when the process terminates, but its pipes may still contain buffered data. `'close'` fires after all stdio streams have ended.

```js
const { spawn } = require('child_process');

const child = spawn('node', ['-e', "process.stdout.write('hello');"]);

let out = '';
child.stdout.on('data', d => { out += d; });

// BUG: may print 0 or partial output
child.on('exit', code => console.log('exit', code, out.length));

// CORRECT: wait for streams to drain
child.on('close', (code, signal) => console.log('close', code, out));
```

Also handle `'error'` before any `await`/`setTimeout`, because spawn failures are delivered asynchronously but you must have the listener attached synchronously.

---

## 2. Shell injection and quoting

`exec`/`execSync` pass the command through a shell. `spawn` (without `shell: true`) does not.

```js
const { exec, spawn } = require('child_process');
const userInput = 'foo; rm -rf /';

// DANGEROUS
exec(`echo ${userInput}`, (err, stdout) => console.log(stdout));

// SAFER: argument is never interpreted by a shell
spawn('echo', [userInput], { stdio: 'inherit' });
```

If you must use a shell, validate/quote arguments (e.g. with `shell-quote`) and prefer `execFile` for executing binaries without a shell. On Windows, spawning `.cmd`/`.bat` usually requires `shell: true` or calling `cmd.exe` explicitly; `npm` is actually `npm.cmd`.

---

## 3. `maxBuffer` truncation in `exec`/`execFile`

The default buffer is small (about 1 MiB). Exceeding it kills the child and returns an error.

```js
const { exec } = require('child_process');

// Can throw: stdout maxBuffer length exceeded
exec('find / -type f', (err, stdout) => {
  if (err) {
    console.error(err.code, err.killed, err.signal);
    return;
  }
  console.log(stdout.length);
});

// BETTER for large/unbounded output: stream it
const { spawn } = require('child_process');
const child = spawn('find', ['/', '-type', 'f']);
child.stdout.on('data', chunk => process.stdout.write(chunk));
child.on('close', code => console.log('done', code));
```

If you use `exec`, only increase `maxBuffer` when you can bound memory; otherwise stream.

---

## 4. Deadlocks from unconsumed pipes

If the child writes a lot to stdout **and** stderr, or the parent writes to stdin without draining, OS pipe buffers fill and the child blocks forever while the parent waits for exit.

```js
const { spawn } = require('child_process');

const child = spawn('tool', []);

// BAD: only reading stdout; stderr fills its buffer and tool hangs
// child.stdout.on('data', ...);

// GOOD: consume or ignore every stream you pipe
child.stdout.pipe(process.stdout);
child.stderr.pipe(process.stderr);

child.on('close', code => console.log('exit', code));
```

If you do not need output, use `stdio: 'ignore'` instead of leaving pipes unconsumed. When writing to stdin, respect backpressure:

```js
const ok = child.stdin.write(bigChunk);
if (!ok) {
  child.stdin.once('drain', () => child.stdin.write(nextChunk));
}
child.stdin.end();
```

Also listen for `'error'` on `stdin` — writing after the child exits gives `EPIPE`.

---

## 5. UTF-8 and binary data chunking

`'data'` chunks can split multibyte characters. Concatenating strings naively can corrupt output.

```js
const { spawn } = require('child_process');
const child = spawn('producer');

// Option A: let Node decode safely
child.stdout.setEncoding('utf8');
let text = '';
child.stdout.on('data', d => { text += d; });

// Option B: collect Buffers, decode once
const chunks = [];
child.stdout.on('data', c => chunks.push(c));
child.on('close', () => {
  const full = Buffer.concat(chunks).toString('utf8');
  console.log(full);
});
```

For binary, never set an encoding; keep `Buffer`.

---

## 6. Killing children and process groups (orphans)

`child.kill()` kills only that process. If it spawned its own children, they become orphans. Only POSIX supports process-group signaling.

```js
const { spawn } = require('child_process');

// Create a new process group (POSIX)
const child = spawn('sh', ['-c', 'sleep 1000 & wait'], {
  detached: true,
  stdio: 'ignore'
});
child.unref();

// Later: kill the whole group on POSIX
function killGroup(child, signal = 'SIGTERM') {
  try {
    if (process.platform !== 'win32') {
      process.kill(-child.pid, signal); // note the minus
    } else {
      // Windows: taskkill kills the tree
      spawn('taskkill', ['/pid', String(child.pid), '/t', '/f']);
    }
  } catch (e) {
    if (e.code !== 'ESRCH') throw e; // already dead
  }
}
```

Important details:
- `child.killed` means “a signal was sent,” not “it has exited.” Wait for `'close'`.
- `child.kill()` can throw or return `false` if the process is already gone; wrap it.
- With `unref()`, the parent can exit while the child keeps running; make sure you actually want that, or implement parent-exit cleanup via `process.on('exit')` / signal handlers.
- Detached behavior differs on Windows; test there.

---

## 7. Timeouts and escalation (SIGTERM is not guaranteed)

Node’s `timeout` option sends one signal and then gives up if the child ignores it.

```js
const { spawn } = require('child_process');

const child = spawn('misbehaved', [], { timeout: 5000, killSignal: 'SIGTERM' });

// If the child ignores SIGTERM, add escalation yourself
const hardKill = setTimeout(() => {
  try { child.kill('SIGKILL'); } catch {}
}, 7000);

child.on('close', () => clearTimeout(hardKill));
```

Also note that Windows does not support POSIX signals well; `kill('SIGTERM')` there often maps to forceful termination. For graceful shutdown, prefer IPC or a stdin “quit” command.

---

## 8. `spawnSync` / `execSync` in production

Synchronous variants block the event loop for the entire duration. Use them only in CLIs/build scripts, not servers.

```js
const { spawnSync } = require('child_process');

// OK in a build script; dangerous in a request handler
const r = spawnSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' });
if (r.error) throw r.error;
if (r.status !== 0) throw new Error(r.stderr);
console.log(r.stdout.trim());
```

Always check `error`, `status`, and `signal`; a non-zero status does not throw.

---

## 9. Environment, `cwd`, and type coercion

`env` replaces the entire environment unless you spread `process.env`. Values should be strings. `cwd` must exist or spawn emits `'error'`.

```js
const { spawn } = require('child_process');

const child = spawn('node', ['worker.js'], {
  cwd: '/var/app',
  env: { ...process.env, NODE_ENV: 'production', PORT: String(3000) }
});

child.on('error', err => {
  // ENOENT if cwd/binary missing
  console.error('spawn failed:', err.code, err.message);
});
```

---

## 10. IPC with `fork`: serialization, backpressure, crashes

`fork()` gives a `v8`/`JSON` channel. Messages are copied, not shared, and sending too fast can buffer memory. Cross-boundary functions, circular refs, and huge objects fail or spike memory.

```js
// parent.js
const { fork } = require('child_process');
const path = require('path');

const child = fork(path.join(__dirname, 'worker.js'), [], {
  serialization: 'advanced' // v8.serialize; allows more types
});

const sent = child.send({ job: 1, data: Buffer.from('x') }, (err) => {
  if (err) console.error('send failed', err);
});
console.log('send queued?', sent); // false means channel full/backpressured

child.on('message', msg => console.log('child says', msg));
child.on('disconnect', () => console.log('ipc disconnected'));
child.on('exit', (code, signal) => console.log('exit', code, signal));

// worker.js
process.on('message', async (msg) => {
  try {
    await doWork(msg);
    process.send({ ok: true, id: msg.job });
  } catch (e) {
    process.send({ ok: false, error: e.message });
  }
});
```

Edge cases:
- `child.send` throws if called after exit; check readiness or catch.
- If the child crashes, `'exit'`/`'disconnect'` fire; do not assume an ack will arrive.
- Use request IDs and timeouts for RPC; messages are not inherently request/response.
- Keep messages small; for large payloads use files/shared memory/streams.

---

## 11. Cross-platform binary resolution

On Windows, `spawn('npm', ...)` without a shell often fails with `ENOENT` because there is no `npm` executable, only `npm.cmd`.

```js
const { spawn } = require('child_process');

const cmd = process.platform === 'win32' ? 'npm.cmd' : 'npm';

const child = spawn(cmd, ['test'], { stdio: 'inherit', shell: false });

// Or use shell:true (reintroduces quoting concerns)
// spawn('npm', ['test'], { stdio: 'inherit', shell: true });
```

Also differences:
- Path separators and `PATHEXT`.
- Signal support and process trees.
- `detached` semantics.

---

## 12. Closing stdin, `EPIPE`, and partial writes

If the child exits early, writes to stdin throw `EPIPE` asynchronously.

```js
const { spawn } = require('child_process');
const child = spawn('head', ['-n', '1']);

child.stdin.on('error', err => {
  // EPIPE is expected if child exits before we finish writing
  if (err.code !== 'EPIPE') console.error(err);
});

child.stdin.write('line 1\nline 2\nline 3\n');
child.stdin.end();

child.on('close', code => console.log('exit', code));
```

Large stdin payloads should be streamed with backpressure (see section 4).

---

## 13. Process exit in children: flushing stdio

`process.exit()` terminates immediately and can truncate buffered stdout/stderr.

```js
// BAD in a child process
process.stdout.write('result');
process.exit(0); // may not flush

// GOOD: set exit code and let the event loop drain
process.stdout.write('result', () => {
  process.exitCode = 0;
});

// or simply
process.exitCode = 0; // process exits naturally when work is done
```

In the parent, always wait for `'close'`, not just `'exit'`, before reading final output.

---

## 14. Signal forwarding and graceful parent shutdown

When the parent receives `SIGTERM`/`SIGINT`, children do not automatically receive it unless you forward it.

```js
const { spawn } = require('child_process');

const children = [
  spawn('./server-a'),
  spawn('./server-b')
];

function shutdown(signal) {
  for (const c of children) {
    try { c.kill(signal); } catch {}
  }
  // Escalate if needed
  setTimeout(() => {
    for (const c of children) {
      try { c.kill('SIGKILL'); } catch {}
    }
  }, 5000).unref();
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
```

Avoid `process.on('exit')` for async cleanup; it cannot wait. Use signal handlers and keep the process alive until children close.

---

## 15. Security: environment injection and command length

- Do not pass user-controlled data through `env` without validation; it can alter loader behavior (`LD_PRELOAD`, `PATH`, `NODE_OPTIONS`).
- Very long argument lists hit `ARG_MAX`; pass data via stdin or a temp file.
- If you spawn with `shell: true`, treat all args as shell code.

```js
const { spawn } = require('child_process');
const userInput = process.argv[2];

// SAFER: fixed command, user data via stdin
const child = spawn('grep', ['needle']);
child.stdin.end(userInput);
child.stdout.pipe(process.stdout);
```

---

## 16. File descriptors and `stdio` numbers

You can pass existing FDs, but they must be open and inherited correctly. `'pipe'` creates streams; `'ignore'` maps to `/dev/null`; `'inherit'` uses parent FDs.

```js
const { spawn } = require('child_process');
const fs = require('fs');

const log = fs.openSync('/tmp/child.log', 'a');

const child = spawn('app', [], {
  stdio: ['ignore', log, log] // stdin /dev/null, stdout+stderr to file
});

// Close your own copy after spawn if no longer needed
fs.closeSync(log);
```

Edge case: if you keep the FD open in the parent, the child’s pipe may not close properly after exit; close deterministic resources.

---

## 17. EMFILE / resource exhaustion

Spawning many children concurrently can hit file descriptor or process limits. Handle `error`, implement concurrency limits, and back off.

```js
const { spawn } = require('child_process');

function run(cmd, args) {
  return new Promise((resolve, reject) => {
    const c = spawn(cmd, args);
    c.on('error', reject);
    c.on('close', code => code === 0 ? resolve() : reject(new Error(`exit ${code}`)));
  });
}

// Example: simple concurrency limiter
async function runAll(tasks, limit = 4) {
  const executing = new Set();
  const results = [];
  for (const t of tasks) {
    const p = run(t.cmd, t.args).finally(() => executing.delete(p));
    executing.add(p);
    results.push(p);
    if (executing.size >= limit) await Promise.race(executing);
  }
  return Promise.all(results);
}
```

---

## 18. Distinguishing exit codes and signals

`'exit'` provides `(code, signal)`. A process killed by a signal has `code === null`. Map these explicitly; do not treat `null` as success.

```js
const { spawn } = require('child_process');

const child = spawn('maybe-fail');

child.on('close', (code, signal) => {
  if (signal) {
    console.error('killed by signal', signal);
    process.exitCode = 1;
    return;
  }
  if (code !== 0) {
    console.error('failed with code', code);
    process.exitCode = code ?? 1;
    return;
  }
  console.log('success');
});
```

Also remember Node convention: exit code `128 + signal number` when killed by signal in shell wrappers, but `child_process` gives you `signal` directly.

---

## 19. Worker threads are not child processes

If you only need concurrency without separate address spaces, `worker_threads` avoids fork/exec costs but introduces shared-state risks (`SharedArrayBuffer`, `Atomics`). Do not use child processes for tiny tasks, and do not assume threads behave like processes for crash isolation.

```js
const { Worker } = require('worker_threads');

const worker = new Worker('./worker.js', { workerData: { n: 5 } });
worker.on('message', console.log);
worker.on('error', console.error);
worker.on('exit', code => console.log('worker exit', code));
```

Terminating a worker with `worker.terminate()` is immediate and can leak resources; design cooperative shutdown like processes.

---

## Quick checklist

- Attach `'error'` immediately on every spawned child.
- Use `'close'`, not `'exit'`, to decide output is complete.
- Consume or ignore every piped stream; beware pipe-buffer deadlocks.
- Prefer `spawn`/`execFile`; avoid `exec` with user input.
- Collect output as `Buffer[]` then decode, or use `setEncoding`.
- Enforce timeouts and escalate `SIGTERM` → `SIGKILL`.
- Kill process groups, not just parents, on POSIX.
- Forward signals and clean up children on parent shutdown.
- Never call `process.exit()` blindly in children; flush first or set `exitCode`.
- Treat Windows as a separate platform for signals and `.cmd` resolution.
- Bound concurrency and memory; stream large data instead of buffering.

If you want, I can tailor this to a specific pattern, such as a CLI spawning long-running daemons, a test runner, or a job queue.

# Pure Functions in JavaScript

A **pure function** must satisfy two rules:

1. **Deterministic** — same inputs always produce the same output.
2. **No side effects** — it doesn't mutate external state, perform I/O, or depend on anything other than its arguments.

Below is a complete, runnable example (`node pure-functions.js`) that demonstrates pure functions, contrasts them with impure ones, and shows practical patterns (immutability, memoization, composition, and testing).

```js
// pure-functions.js
// Run with: node pure-functions.js

'use strict';

// ============================================================
// 1. BASIC PURE FUNCTIONS
// ============================================================

// Pure: depends only on arguments, no mutation
function add(a, b) {
  return a + b;
}

function multiply(a, b) {
  return a * b;
}

// Pure: works on a copy, never mutates the input
function appendItem(list, item) {
  return [...list, item];          // new array
}

function setProperty(obj, key, value) {
  return { ...obj, [key]: value }; // new object
}

// Pure: deterministic string transform
function slugify(text) {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-');
}

// ============================================================
// 2. IMPURE COUNTERPARTS (for contrast)
// ============================================================

let globalCounter = 0;

// Impure: mutates external state
function incrementGlobal() {
  globalCounter += 1;
  return globalCounter;
}

// Impure: mutates its argument
function pushItem(list, item) {
  list.push(item);   // side effect
  return list;
}

// Impure: depends on external (mutable) state
function greetByTime(name) {
  const hour = new Date().getHours(); // depends on "now"
  const period = hour < 12 ? 'morning' : 'afternoon';
  return `Good ${period}, ${name}`;
}

// Impure: non-deterministic
function randomId() {
  return Math.random().toString(36).slice(2);
}

// ============================================================
// 3. PURE DATA TRANSFORMATIONS (immutable pipelines)
// ============================================================

const users = Object.freeze([
  { id: 1, name: 'Ada',  age: 36, active: true  },
  { id: 2, name: 'Bob',  age: 24, active: false },
  { id: 3, name: 'Cy',   age: 31, active: true  },
  { id: 4, name: 'Dan',  age: 19, active: true  },
]);

// Pure: returns a new array, never touches `users`
function activeUsers(list) {
  return list.filter(u => u.active);
}

function namesOf(list) {
  return list.map(u => u.name);
}

function averageAge(list) {
  if (list.length === 0) return 0;
  const total = list.reduce((sum, u) => sum + u.age, 0);
  return total / list.length;
}

function sortByAge(list, direction = 'asc') {
  // copy first so the original is untouched
  const copy = [...list];
  copy.sort((a, b) => direction === 'asc' ? a.age - b.age : b.age - a.age);
  return copy;
}

// Compose small pure functions into a larger pure function
function activeUserNamesSorted(list) {
  return namesOf(sortByAge(activeUsers(list), 'asc'));
}

// ============================================================
// 4. PURE VALIDATION (returns data, no throwing required)
// ============================================================

function validateEmail(email) {
  const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  return ok
    ? { valid: true,  value: email.trim().toLowerCase() }
    : { valid: false, error: 'Invalid email format' };
}

function validateAge(age) {
  if (typeof age !== 'number' || Number.isNaN(age)) {
    return { valid: false, error: 'Age must be a number' };
  }
  if (age < 0 || age > 150) {
    return { valid: false, error: 'Age out of range' };
  }
  return { valid: true, value: Math.floor(age) };
}

// ============================================================
// 5. MEMOIZATION (only works reliably with pure functions)
// ============================================================

function memoize(fn) {
  const cache = new Map();
  return function memoized(...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = fn(...args);
    cache.set(key, result);
    return result;
  };
}

// Expensive pure function
function fibonacci(n) {
  if (n < 0) throw new RangeError('n must be >= 0');
  if (n < 2) return n;
  return fibonacci(n - 1) + fibonacci(n - 2);
}

const fibFast = memoize(fibonacci);

// ============================================================
// 6. PURE REDUCER (Redux-style)
// ============================================================

const initialState = Object.freeze({ count: 0, history: [] });

function reducer(state, action) {
  switch (action.type) {
    case 'INCREMENT':
      return {
        count: state.count + (action.by ?? 1),
        history: [...state.history, state.count],
      };
    case 'DECREMENT':
      return {
        count: state.count - (action.by ?? 1),
        history: [...state.history, state.count],
      };
    case 'RESET':
      return { count: 0, history: [] };
    default:
      return state; // unknown action -> unchanged (still pure)
  }
}

// ============================================================
// 7. DEMO / ASSERTIONS
// ============================================================

function assertEqual(actual, expected, label) {
  const a = JSON.stringify(actual);
  const b = JSON.stringify(expected);
  if (a !== b) {
    console.error(`FAIL: ${label}\n  actual:   ${a}\n  expected: ${b}`);
    process.exitCode = 1;
  } else {
    console.log(`PASS: ${label}`);
  }
}

function assertSameReference(actual, expected, label) {
  if (actual !== expected) {
    console.error(`FAIL (ref): ${label}`);
    process.exitCode = 1;
  } else {
    console.log(`PASS (ref): ${label}`);
  }
}

console.log('--- basic pure functions ---');
assertEqual(add(2, 3), 5, 'add');
assertEqual(multiply(4, 5), 20, 'multiply');
assertEqual(appendItem([1, 2], 3), [1, 2, 3], 'appendItem returns new array');
assertSameReference(appendItem([1, 2], 3), appendItem([1, 2], 3), 'appendItem is deterministic (value eq)');

const original = [1, 2];
appendItem(original, 99);
assertEqual(original, [1, 2], 'appendItem does not mutate input');

assertEqual(setProperty({ a: 1 }, 'b', 2), { a: 1, b: 2 }, 'setProperty');
assertEqual(slugify('  Hello, World!  '), 'hello-world', 'slugify');

console.log('\n--- immutable pipelines ---');
const active = activeUsers(users);
assertEqual(namesOf(active), ['Ada', 'Cy', 'Dan'], 'active user names');
assertEqual(averageAge(active), (36 + 31 + 19) / 3, 'average age');
assertEqual(activeUserNamesSorted(users), ['Ada', 'Cy', 'Dan'], 'sorted active names');
// original untouched
assertEqual(users.length, 4, 'users unchanged');

console.log('\n--- validation ---');
assertEqual(validateEmail('  Foo@Bar.COM '), { valid: true, value: 'foo@bar.com' }, 'email valid');
assertEqual(validateEmail('nope'), { valid: false, error: 'Invalid email format' }, 'email invalid');
assertEqual(validateAge(25.7), { valid: true, value: 25 }, 'age floors');
assertEqual(validateAge('x'), { valid: false, error: 'Age must be a number' }, 'age type');

console.log('\n--- memoization ---');
const t0 = Date.now();
const r1 = fibFast(40);
const t1 = Date.now();
const r2 = fibFast(40);
const t2 = Date.now();
assertEqual(r1, 102334155, 'fib(40)');
assertEqual(r2, r1, 'memoized result identical');
console.log(`first call: ${t1 - t0}ms, second call: ${t2 - t1}ms (should be ~0)`);

console.log('\n--- reducer ---');
let s = initialState;
s = reducer(s, { type: 'INCREMENT' });
assertEqual(s, { count: 1, history: [0] }, 'increment');
s = reducer(s, { type: 'INCREMENT', by: 5 });
assertEqual(s, { count: 6, history: [0, 1] }, 'increment by 5');
s = reducer(s, { type: 'RESET' });
assertEqual(s, { count: 0, history: [] }, 'reset');
// original state untouched
assertEqual(initialState, { count: 0, history: [] }, 'initialState unchanged');

console.log('\n--- impurity demo (why it matters) ---');
console.log('incrementGlobal() ->', incrementGlobal(), incrementGlobal(), incrementGlobal());
console.log('randomId() ->', randomId(), randomId(), '(different each time)');
console.log('greetByTime ->', greetByTime('Ada'), '(depends on clock)');

console.log('\nAll checks done. exitCode =', process.exitCode ?? 0);
```

### Key takeaways

| Property | Pure | Impure |
|---|---|---|
| Same input → same output | ✅ | ❌ (time, randomness, globals) |
| No mutation of inputs | ✅ | ❌ (`pushItem`, `incrementGlobal`) |
| Safe to memoize | ✅ | ❌ (would cache stale/wrong values) |
| Safe to reorder / parallelize | ✅ | ❌ (order matters with side effects) |
| Easy to unit-test | ✅ | needs mocking |

### Patterns shown
- **Immutability via spread** (`[...list]`, `{ ...obj }`) keeps inputs untouched.
- **Returning result objects** (`{ valid, value/error }`) instead of throwing keeps validation pure and composable.
- **Memoization** wraps any pure function and caches by serialized arguments.
- **Reducers** are the canonical pure-function pattern for state transitions.
- **Composition** (`activeUserNamesSorted`) chains small pure functions; because each is pure, the whole pipeline is pure.

## Pure functions in JavaScript

### The idea

A **pure function** has two properties:

1. **Deterministic output**: for the same arguments, it always returns the same value.
2. **No side effects**: it does not modify anything outside itself—no global variables, no mutation of input arguments, no I/O, no DOM changes, no `console.log` (technically), no randomness, no time-based behavior.

Because of this, pure functions are **referentially transparent**: you can replace a call with its result without changing program behavior.

```js
const add = (a, b) => a + b;

// This call can be replaced by 5 anywhere:
add(2, 3);
```

### Syntax

Purity is not a language keyword; it is a *discipline*. Any normal function can be pure if written carefully.

```js
// Pure
const square = x => x * x;

const greet = name => `Hello, ${name}`;

const addItem = (items, item) => [...items, item];

// Impure: mutates input
const addItemImpure = (items, item) => {
  items.push(item);
  return items;
};

// Impure: depends on external mutable state
let taxRate = 0.2;
const priceWithTax = price => price * (1 + taxRate);
```

### Typical use cases

#### 1. Data transformations

```js
const users = [
  { id: 1, name: "Ada" },
  { id: 2, name: "Grace" }
];

const getName = user => user.name;
const upper = s => s.toUpperCase();

const names = users.map(getName).map(upper);
// ["ADA", "GRACE"]
```

#### 2. Reducers (state updates)

```js
function cartReducer(state = [], action) {
  switch (action.type) {
    case "ADD":
      return [...state, action.item];
    case "REMOVE":
      return state.filter(x => x.id !== action.id);
    default:
      return state;
  }
}
```

#### 3. Validation and formatting

```js
const isEmail = value => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);

const formatCurrency = (amount, currency = "USD") =>
  new Intl.NumberFormat("en-US", { style: "currency", currency }).format(amount);
```

#### 4. Memoization

Pure functions are ideal for caching because identical inputs guarantee identical outputs.

```js
function memoize(fn) {
  const cache = new Map();
  return (...args) => {
    const key = JSON.stringify(args);
    if (!cache.has(key)) cache.set(key, fn(...args));
    return cache.get(key);
  };
}

const slowSquare = n => {
  // expensive work
  return n * n;
};

const fastSquare = memoize(slowSquare);
fastSquare(42); // computed once, cached after
```

#### 5. Composition

```js
const compose = (...fns) => x => fns.reduceRight((v, f) => f(v), x);

const trim = s => s.trim();
const lower = s => s.toLowerCase();
const slugify = compose(trim, lower, s => s.replace(/\s+/g, "-"));

slugify("  Hello World  "); // "hello-world"
```

### Common pitfalls

- **Mutating arguments** even when returning a new reference elsewhere.
- **Reading mutable closures**: a function that reads a variable that changes over time is not pure.
- **Hidden nondeterminism**: `Math.random()`, `Date.now()`, `fetch`, DOM access.
- **Console logging**: technically a side effect; acceptable in debugging, but avoid in production pure utilities.
- **Exceptions**: throwing can be seen as a side effect; often okay for invalid input, but handle explicitly when purity matters.

### Practical summary

Use pure functions for:
- calculations
- data shaping
- validation
- state transitions
- reusable utilities

Keep impure code at the edges of your app: event handlers, API calls, storage, rendering. This separation makes code easier to test, refactor, cache, and reason about.

A common mistake is mutating the input object/array and treating that as a “pure” function:

```js
// Mistaken version
function addItem(cart, item) {
  cart.push(item); // side effect: mutates caller's array
  return cart;
}

const originalCart = ["apple"];
const result = addItem(originalCart, "banana");

console.log(originalCart); // ["apple", "banana"]  (unexpected mutation)
console.log(result === originalCart); // true
```

Corrected version:

```js
// Pure version
function addItem(cart, item) {
  return [...cart, item]; // creates a new array, leaves input untouched
}

const originalCart = ["apple"];
const result = addItem(originalCart, "banana");

console.log(originalCart); // ["apple"]  (unchanged)
console.log(result);      // ["apple", "banana"]
console.log(result === originalCart); // false
```

### What was wrong

1. **Side effect / mutation**  
   `cart.push(item)` changes the array passed by the caller. A pure function must not modify its inputs or any external state.

2. **Not referentially transparent in practice**  
   Calling `addItem(originalCart, "banana")` changes `originalCart`, so the same input no longer produces the same observable result later. The function’s behavior depends on hidden mutable state.

3. **Shared-reference bugs**  
   Because arrays/objects are passed by reference, mutating them can affect unrelated parts of the program, making debugging and testing harder.

### Why the corrected version is better

- It returns a **new array**, preserving the original input.
- Given the same `cart` and `item`, it always returns an equivalent new array.
- It has no observable side effects, so it is easier to test, memoize, compose, and reason about.

### One extra caution

For nested objects, a shallow copy is not enough if you mutate nested values:

```js
// Still impure if nested data is mutated
function updateName(user, name) {
  const copy = { ...user };
  copy.profile.name = name; // mutates nested object shared with original
  return copy;
}
```

A truly pure update should also avoid mutating nested structures, for example by copying the nested path:

```js
function updateName(user, name) {
  return {
    ...user,
    profile: {
      ...user.profile,
      name,
    },
  };
}
```

In short: pure functions should **read inputs, compute a result, and return new data without changing anything outside their own scope**.

# Common Pitfalls When Working with Pure Functions in JavaScript

A pure function: **same inputs → same output**, and **no side effects** (no mutation of external state, no I/O, no randomness, no reliance on mutable globals). Below are the most common ways purity silently breaks, with code.

---

## 1. Mutating input arguments

The #1 pitfall. Objects/arrays are passed by reference.

```js
// Impure: mutates the caller's array
function addItem(list, item) {
  list.push(item);          // side effect on argument
  return list;
}

const a = [1, 2];
const b = addItem(a, 3);
console.log(a); // [1, 2, 3]  ← surprise mutation
console.log(a === b); // true
```

**Fix:** create a new array.

```js
function addItem(list, item) {
  return [...list, item];
}
```

---

## 2. Mutating nested state (shallow copies)

Spread/`Object.assign` are shallow — nested objects are still shared.

```js
function updateUser(user, name) {
  const copy = { ...user };
  copy.profile.name = name;   // mutates nested original!
  return copy;
}

const u = { profile: { name: 'Ada' } };
const u2 = updateUser(u, 'Grace');
console.log(u.profile.name); // 'Grace'  ← original corrupted
```

**Fix:** deep-clone or immutable update at every level.

```js
function updateUser(user, name) {
  return { ...user, profile: { ...user.profile, name } };
}
```

---

## 3. Using mutating array methods

`sort`, `reverse`, `splice`, `push`, `pop`, `shift`, `unshift`, `fill`, `copyWithin` mutate in place.

```js
function sorted(xs) {
  return xs.sort((a, b) => a - b); // mutates xs!
}

const data = [3, 1, 2];
sorted(data);
console.log(data); // [1, 2, 3]
```

**Fix:** copy first.

```js
function sorted(xs) {
  return [...xs].sort((a, b) => a - b);
}
```

---

## 4. Relying on external / global state

```js
let rate = 0.1;
function priceWithTax(price) {
  return price * (1 + rate); // depends on mutable global
}
rate = 0.2;
// same input, different output over time
```

**Fix:** pass everything as arguments.

```js
function priceWithTax(price, rate) {
  return price * (1 + rate);
}
```

---

## 5. Non-determinism: time, randomness, environment

```js
function token() {
  return Math.random().toString(36); // not pure
}
function nowLabel() {
  return new Date().toISOString();   // not pure
}
function userAgent() {
  return navigator.userAgent;         // environment-dependent
}
```

**Fix:** inject these as parameters (or treat as effects at the boundary).

```js
function token(rng) { return rng().toString(36); }
function nowLabel(now) { return now.toISOString(); }
```

---

## 6. Hidden side effects (I/O, logging, DOM)

```js
function compute(x) {
  console.log('computing', x);   // side effect
  fetch('/log', { method: 'POST' }); // side effect
  document.title = 'done';      // side effect
  return x * 2;
}
```

Even `console.log` makes a function impure. Keep effects at the edges (controllers/handlers), not in core logic.

---

## 7. Closure over mutable variables

```js
function makeCounter() {
  let n = 0;
  return function () {
    n += 1;        // mutates closed-over state
    return n;
  };
}
const c = makeCounter();
c(); // 1
c(); // 2  ← same "input" (none), different output
```

**Fix:** make state explicit; return new state instead of mutating.

```js
function increment(state) {
  return { ...state, count: state.count + 1 };
}
```

---

## 8. `this` binding surprises

Methods passed as callbacks lose `this`, and `this` makes output depend on call site.

```js
const obj = {
  factor: 2,
  scale(x) { return x * this.factor; }, // depends on `this`
};
const fn = obj.scale;
fn(5); // NaN / TypeError in strict mode
```

**Fix:** avoid `this` in pure logic; use plain functions or bind explicitly.

```js
function scale(factor, x) {
  return x * factor;
}
```

---

## 9. Default parameters that mutate or are non-deterministic

```js
function create(items = []) {   // new array each call — OK
  items.push(1);               // but mutation inside is the problem
  return items;
}
```

Also dangerous: default params referencing mutable globals or `Date.now()`.

```js
function log(msg, ts = Date.now()) { /* impure default */ }
```

---

## 10. Floating-point & equality gotchas

Pure doesn't mean "predictable equality." Same inputs can produce tiny numeric differences, and `NaN !== NaN`.

```js
function half(x) { return x / 3 * 3; } // floating point drift
half(0.1); // 0.10000000000000002

function isSame(a, b) { return a === b; }
isSame(NaN, NaN); // false
```

**Fix:** use tolerance comparisons for floats; handle `NaN` with `Number.isNaN`.

---

## 11. Object key ordering / iteration dependence

Relying on insertion order or `Object.keys` order can differ across engines or mutation history.

```js
function keys(obj) {
  return Object.keys(obj); // order not guaranteed semantically
}
```

**Fix:** sort keys when order matters; don't treat objects as ordered maps (use `Map`).

---

## 12. Shared references / aliasing

Returning the same (possibly mutable) reference lets callers corrupt your cache/memo.

```js
const cache = new Map();
function getTemplate() {
  const t = { a: 1 };
  cache.set('t', t);
  return t; // caller can mutate the cached object
}
const x = getTemplate();
x.a = 999;
console.log(getTemplate().a); // 999
```

**Fix:** return frozen or cloned values.

```js
return Object.freeze({ ...t });
// or structuredClone(t)
```

---

## 13. Memoization pitfalls

Memoizing on object identity can be wrong; memoizing mutable args can return stale results.

```js
const memo = new Map();
function heavy(obj) {
  if (memo.has(obj)) return memo.get(obj); // identity-based
  const r = obj.x * 2;
  memo.set(obj, r);
  return r;
}
const o = { x: 5 };
heavy(o);        // 10
o.x = 7;
heavy(o);        // still 10 (stale) — input changed but identity same
```

**Fix:** memoize on a serialized key, and only memoize pure, immutable inputs.

---

## 14. Async / Promises are effects

A function returning a Promise is doing I/O or scheduling — not pure, even if deterministic-ish.

```js
async function fetchUser(id) {
  const r = await fetch(`/users/${id}`); // effect
  return r.json();
}
```

Treat async boundaries as impure; keep the pure transformation (parsing/validating) separate.

```js
function parseUser(json) { /* pure */ }
```

---

## 15. Throwing exceptions

Exceptions are a form of control flow / effect and make "same input → same output" fail (different exception paths, stack traces).

```js
function divide(a, b) {
  if (b === 0) throw new Error('div by zero');
  return a / b;
}
```

Prefer returning a result type (`{ ok, value }` or `null`) for pure core logic; throw at boundaries.

---

## 16. Using impure built-ins inside

`Array.prototype.sort` mutates; `Date.now`, `Math.random`, `crypto.randomUUID` are impure; `console.*` are effects.

```js
function ids(n) {
  return Array.from({ length: n }, () => crypto.randomUUID()); // impure
}
```

**Fix:** inject entropy/time as parameters, or mark the function as effectful.

---

## 17. Default mutation via rest/spread on arguments

```js
function f(...args) {
  args.push('x'); // mutates the rest array — local, but still a side effect within
  return args;
}
```

Minor, but avoid mutating even local temporaries when aiming for purity; prefer new arrays.

---

## 18. Assuming `const` means immutable

```js
const user = { name: 'Ada' };
user.name = 'Grace'; // allowed! const only blocks reassignment
```

`const` does not make an object pure/immutable. Use `Object.freeze` (shallow) or libraries like Immer for deep immutability.

---

## Quick checklist for a pure function

- [ ] All inputs are parameters (no globals, no `this`)
- [ ] No mutation of arguments or closed-over state
- [ ] No `Date`, `Math.random`, I/O, `console`, DOM, `fetch`
- [ ] Returns a value (not `undefined`) for all inputs
- [ ] Deterministic: no dependence on iteration order of objects
- [ ] Returns new structures; no shared mutable references leaked
- [ ] Handles `NaN`, `null`, `undefined` explicitly

---

## Summary table

| Pitfall | Symptom | Fix |
|---|---|---|
| Mutating inputs | Caller's data changes | Return new copy |
| Shallow copy | Nested mutation leaks | Deep/structural update |
| Mutating array methods | Original reordered | `[...xs].sort()` |
| Global state | Output varies over time | Pass as arg |
| Non-determinism | Unreproducible results | Inject time/rng |
| Side effects | I/O/logging in core | Move to boundary |
| Closure mutation | Stateful factory | Explicit state param |
| `this` binding | Wrong/lost context | Plain functions |
| Floats/NaN | Equality surprises | Tolerance / `Number.isNaN` |
| Aliasing | Cached data corrupted | Freeze/clone |
| Memoization | Stale results | Key on value, not identity |

The single biggest discipline: **treat data as immutable and push all effects (I/O, time, randomness, mutation of the world) to the outermost layer** of your program.

## Exercise

**Refactor an impure shopping-cart module into pure functions.**

Given this impure code:

```js
let cart = [
  { name: 'Keyboard', price: 50, qty: 1 },
  { name: 'Mouse',    price: 20, qty: 2 }
];

function addItem(cart, item) {
  cart.push(item);          // mutates input
  return cart;
}

function applyDiscount(cart, percent) {
  cart.forEach(i => i.price *= (1 - percent)); // mutates input objects
  return cart;
}

function totalPrice(cart) {
  let total = 0;
  for (const i of cart) total += i.price * i.qty;
  return total;
}
```

**Task:** Rewrite `addItem`, `applyDiscount`, and `totalPrice` (and optionally `expensiveItems`) so that:

1. They never mutate their inputs.
2. They return new values instead.
3. Given the same inputs, they always return the same output.
4. They do not read or write external/global state.

---

## Step-by-step solution

### Step 1: Spot the impurities

- `addItem` mutates the original array with `push`.
- `applyDiscount` mutates every product object’s `price`.
- `totalPrice` is actually pure already (it only reads inputs), but it can be made more idiomatic and clearly functional.
- All functions receive `cart` as a parameter, which is good, but mutation makes them unsafe to reuse or test.

### Step 2: Define pure replacements

A pure function should:
- take all needed data as arguments,
- return a new value,
- leave arguments untouched.

For arrays/objects, use spread syntax and `map`/`reduce`/`filter` instead of in-place mutation.

### Step 3: Implement each function

```js
const cart = [
  { name: 'Keyboard', price: 50, qty: 1 },
  { name: 'Mouse',    price: 20, qty: 2 }
];

// Pure: returns a new array, original cart is unchanged
function addItemPure(cart, item) {
  return [...cart, { ...item }];
}

// Pure: returns new array with new product objects; prices are discounted
function applyDiscountPure(cart, percent) {
  if (percent < 0 || percent > 1) {
    throw new Error('percent must be between 0 and 1');
  }
  const factor = 1 - percent;
  return cart.map(item => ({
    ...item,
    price: item.price * factor
  }));
}

// Pure: deterministic sum, no mutation
function totalPricePure(cart) {
  return cart.reduce((sum, item) => sum + item.price * item.qty, 0);
}

// Pure: filters without mutating
function expensiveItemsPure(cart, minLineTotal) {
  return cart.filter(item => item.price * item.qty >= minLineTotal);
}
```

### Step 4: Verify purity with a quick test

```js
const original = [
  { name: 'Keyboard', price: 50, qty: 1 },
  { name: 'Mouse',    price: 20, qty: 2 }
];

const withItem = addItemPure(original, { name: 'Pad', price: 10, qty: 1 });
const discounted = applyDiscountPure(original, 0.1); // 10% off
const total = totalPricePure(original);
const expensive = expensiveItemsPure(original, 30);

console.log('original unchanged:', original);
console.log('withItem:', withItem);
console.log('discounted:', discounted);
console.log('total:', total);        // 90
console.log('expensive:', expensive);
```

Expected behavior:
- `original` remains exactly as declared.
- `discounted` has reduced prices, but `original` does not.
- Re-running any function with the same arguments gives the same result.

---

## Final solution

```js
/**
 * Pure shopping cart helpers.
 * None of these functions mutate their inputs.
 */

function addItemPure(cart, item) {
  return [...cart, { ...item }];
}

function applyDiscountPure(cart, percent) {
  if (typeof percent !== 'number' || percent < 0 || percent > 1) {
    throw new Error('percent must be a number between 0 and 1');
  }
  const factor = 1 - percent;
  return cart.map(item => ({
    ...item,
    price: item.price * factor
  }));
}

function totalPricePure(cart) {
  return cart.reduce((sum, item) => sum + item.price * item.qty, 0);
}

function expensiveItemsPure(cart, minLineTotal) {
  return cart.filter(item => item.price * item.qty >= minLineTotal);
}

// --- Example usage ---
const cart = [
  { name: 'Keyboard', price: 50, qty: 1 },
  { name: 'Mouse',    price: 20, qty: 2 }
];

const updatedCart = addItemPure(cart, { name: 'Pad', price: 10, qty: 1 });
const discountedCart = applyDiscountPure(cart, 0.1);
const total = totalPricePure(cart);
const pricey = expensiveItemsPure(cart, 30);

console.log('original:', cart);
console.log('updated:', updatedCart);
console.log('discounted:', discountedCart);
console.log('total:', total);
console.log('pricey:', pricey);
```

### Why this is pure

- **No mutation:** spread + `map` create new arrays/objects.
- **Deterministic:** output depends only on arguments.
- **No side effects:** no global state, no I/O, no `push`/`forEach` mutation.
- **Referentially transparent:** you can replace `totalPricePure(cart)` with its result anywhere without changing behavior.

## Pure Functions in JavaScript

A **pure function** has two strict properties:

1. **Deterministic** – given the same inputs, it always returns the same output.
2. **No side effects** – it does not mutate external state, perform I/O, use randomness or time, or change anything outside its own scope.

```js
// Pure
const add = (a, b) => a + b;

// Impure: depends on external state
let tax = 0.1;
const priceWithTax = (price) => price * (1 + tax);

// Impure: mutates input
const pushItem = (arr, item) => { arr.push(item); return arr; };

// Impure: non-deterministic
const now = () => Date.now();
```

### Why they matter (interview talking points)

- **Testable**: no setup/teardown of global state.
- **Memoizable**: results can be cached by inputs.
- **Composable**: can be chained safely.
- **Concurrency-safe**: no shared mutable state.
- **Referentially transparent**: a call can be replaced by its result.

### Core implementation

Below is a small, clean module that demonstrates the *core* of pure-function thinking:

1. **Pure data transformations** that never mutate inputs.
2. **`deepFreeze`** to enforce immutability at runtime.
3. **`memoize`** which is only valid for pure functions.
4. **`isDeterministic`** heuristic to check one half of purity.

```js
/* ============================================================
 * Pure Function Core Utilities
 * ============================================================ */

/**
 * Deep-freeze an object so no nested mutation can occur.
 * This enforces the "no side effects" property at runtime.
 *
 * @param {unknown} obj
 * @returns {unknown} the frozen object
 */
function deepFreeze(obj) {
  if (obj === null || typeof obj !== "object") return obj;

  Object.freeze(obj);

  for (const key of Object.keys(obj)) {
    deepFreeze(obj[key]);
  }
  // Also handle arrays / Map / Set if needed; kept simple here.
  return obj;
}

/**
 * Pure map: returns a NEW array, never mutates the input.
 *
 * @template T, U
 * @param {T[]} arr
 * @param {(item: T, index: number) => U} fn
 * @returns {U[]}
 */
function pureMap(arr, fn) {
  // Validate inputs without mutating them.
  if (!Array.isArray(arr)) throw new TypeError("arr must be an array");
  if (typeof fn !== "function") throw new TypeError("fn must be a function");

  const result = new Array(arr.length);
  for (let i = 0; i < arr.length; i++) {
    result[i] = fn(arr[i], i);
  }
  return result;
}

/**
 * Pure filter: returns a NEW array.
 */
function pureFilter(arr, predicate) {
  if (!Array.isArray(arr)) throw new TypeError("arr must be an array");
  if (typeof predicate !== "function") throw new TypeError("predicate must be a function");

  const result = [];
  for (let i = 0; i < arr.length; i++) {
    if (predicate(arr[i], i)) result.push(arr[i]);
  }
  return result;
}

/**
 * Pure immutable update: returns a NEW object with overrides applied.
 * Does NOT mutate the source.
 *
 * @param {object} source
 * @param {object} overrides
 * @returns {object}
 */
function pureUpdate(source, overrides) {
  if (source === null || typeof source !== "object") {
    throw new TypeError("source must be an object");
  }
  if (overrides === null || typeof overrides !== "object") {
    throw new TypeError("overrides must be an object");
  }
  // Shallow copy + merge. For deep immutability, combine with deepFreeze.
  return Object.freeze({ ...source, ...overrides });
}

/**
 * Memoize a PURE function. Only safe for pure functions because
 * results are cached solely by serialized arguments.
 *
 * @param {Function} fn
 * @returns {Function}
 */
function memoize(fn) {
  if (typeof fn !== "function") throw new TypeError("fn must be a function");

  const cache = new Map();

  return function memoized(...args) {
    // Simple key via JSON. Production code may use a better serializer.
    const key = JSON.stringify(args);

    if (cache.has(key)) {
      return cache.get(key);
    }

    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

/**
 * Heuristic purity check: verifies determinism only.
 * Cannot detect side effects automatically, so this is a smoke test,
 * not a proof.
 *
 * @param {Function} fn
 * @param {any[]} args
 * @param {number} trials
 * @returns {boolean}
 */
function isDeterministic(fn, args, trials = 5) {
  if (typeof fn !== "function") throw new TypeError("fn must be a function");
  if (!Array.isArray(args)) throw new TypeError("args must be an array");

  const baseline = fn(...args);
  for (let i = 1; i < trials; i++) {
    if (!deepEqual(fn(...args), baseline)) return false;
  }
  return true;
}

/**
 * Minimal deep equality helper for the heuristic above.
 */
function deepEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) {
    return false;
  }
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  return keysA.every((k) => deepEqual(a[k], b[k]));
}

/* ============================================================
 * Demo / smoke tests
 * ============================================================ */

const nums = Object.freeze([1, 2, 3, 4]);

// Pure transformations leave `nums` untouched.
const doubled = pureMap(nums, (x) => x * 2);
const evens = pureFilter(nums, (x) => x % 2 === 0);
const updated = pureUpdate({ id: 1, name: "Ada" }, { name: "Grace" });

console.log("original:", nums);        // [1,2,3,4]
console.log("doubled:", doubled);      // [2,4,6,8]
console.log("evens:", evens);         // [2,4]
console.log("updated:", updated);     // {id:1, name:"Grace"}

// Memoization is valid because `add` is pure.
const add = (a, b) => a + b;
const memoAdd = memoize(add);
console.log(memoAdd(2, 3)); // 5
console.log(memoAdd(2, 3)); // 5 (cached)

// Determinism check (heuristic only).
console.log("add deterministic?", isDeterministic(add, [2, 3])); // true
console.log("Math.random deterministic?", isDeterministic(Math.random, [])); // false

// Enforce immutability.
const frozen = deepFreeze({ user: { name: "Ada" } });
// frozen.user.name = "X"; // throws in strict mode
```

### Interview takeaway

When asked “what is a pure function?”, answer with the two properties and a small example, then mention **referential transparency**, **testability**, and **memoization**. When asked to “implement the core,” showing **immutable transformations + memoization + determinism checking** demonstrates you understand both the *concept* and its *practical constraints*.

## Pure functions in JavaScript: edge cases and how to handle them

A **pure function** must be **deterministic** (same inputs → same output) and have **no observable side effects** (no mutation of inputs, no I/O, no global state changes). JavaScript makes this hard because objects are mutable, the runtime is stateful, and many APIs are impure by design.

Below are the most common edge cases, grouped by theme, with concise examples and fixes.

---

### 1. Mutating inputs (the #1 cause of impurity)

```js
// IMPURE: mutates the caller's object
function addItem(arr, item) {
  arr.push(item);
  return arr;
}

const a = [1, 2];
const b = addItem(a, 3);
console.log(a); // [1, 2, 3] — surprise mutation

// PURE: return a new array
function addItemPure(arr, item) {
  return [...arr, item];
}
```

**Nested mutation trap (shallow copy is not enough):**

```js
const user = { profile: { name: 'Ada' } };

// Still impure: nested object is shared
const copy = { ...user };
copy.profile.name = 'Grace'; // mutates original nested object

// Safer: deep immutable update
const copy2 = {
  ...user,
  profile: { ...user.profile, name: 'Grace' }
};
```

**Use `structuredClone` for deep cloning when needed:**

```js
const safe = structuredClone(user);
safe.profile.name = 'Grace'; // original untouched
```

---

### 2. Array methods that mutate in place

```js
function sorted(arr) {
  return arr.sort(); // mutates original
}

// Pure version
function sortedPure(arr) {
  return [...arr].sort((a, b) => a - b);
}
```

Also avoid: `push`, `pop`, `shift`, `unshift`, `splice`, `reverse`, `fill`, `copyWithin`.

---

### 3. `this` binding and method extraction

```js
const counter = {
  value: 0,
  inc() { this.value++; return this.value; } // impure + this-dependent
};

const f = counter.inc;
f(); // NaN or global mutation

// Pure: make dependencies explicit
function inc(value) {
  return value + 1;
}
```

Arrow functions capture `this` lexically, but if `this` refers to mutable state, purity is still broken.

---

### 4. Closures over mutable state

```js
let counter = 0;
function next() {
  return ++counter; // nondeterministic across calls
}

// Pure: pass state in, return new state
function nextPure(state) {
  return { count: state.count + 1 };
}
```

---

### 5. Non-deterministic built-ins

```js
function makeId() {
  return Math.random().toString(36); // impure
}

function now() {
  return Date.now(); // impure
}

// If you need these, inject them as arguments (dependency injection)
function makeIdPure(rng) {
  return rng().toString(36);
}
```

Same issue with `crypto.getRandomValues`, `performance.now` (mostly monotonic but environment-dependent), `new Date()`.

---

### 6. RegExp with the `g` or `y` flag (stateful `lastIndex`)

```js
const re = /a/g;

function countA(str) {
  const m = str.match(re);
  return m ? m.length : 0;
}

console.log(countA('aaa')); // 3
console.log(countA('aaa')); // 0  (lastIndex leaked!)

// Pure: reset lastIndex or create a fresh regex
function countAPure(str) {
  return (str.match(/a/g) || []).length;
}
```

---

### 7. Equality edge cases: `NaN`, `-0`, and object identity

```js
console.log(NaN === NaN);        // false
console.log(0 === -0);           // true
console.log({} === {});          // false

// Use Object.is for SameValue semantics
console.log(Object.is(NaN, NaN)); // true
console.log(Object.is(0, -0));    // false
```

**Implication for pure functions:**  
- Don’t use `===` to compare `NaN`.  
- Don’t assume two fresh objects are “the same” even if structurally equal.  
- Memoization keyed by reference will miss structurally equal inputs.

---

### 8. Deep equality vs referential equality

```js
function isEqual(a, b) {
  return a === b; // only reference equality
}

// For value equality, implement structural comparison or use a library
function deepEqual(a, b) {
  return JSON.stringify(a) === JSON.stringify(b); // crude; has many edge cases
}
```

Caveat: `JSON.stringify` drops `undefined`, functions, Symbols, and breaks on circular references. For production, use `structuredClone` + recursive comparison or a library like `fast-deep-equal`.

---

### 9. Proxies and getters with hidden side effects

```js
const obj = new Proxy({ x: 1 }, {
  get(target, key) {
    console.log('accessed', key); // side effect on read
    return target[key];
  }
});

function readX(o) { return o.x; } // calling it logs — impure observable effect

// There is no general fix; avoid proxies/getters with side effects in pure pipelines.
```

---

### 10. `arguments` object aliasing (non-strict mode)

```js
function f(a) {
  arguments[0] = 99;
  return a; // 99 in non-strict mode
}

// Fix: use rest parameters and strict mode
function fPure(...args) {
  const a = args[0];
  return a; // no aliasing
}
```

---

### 11. Default parameters with side effects

```js
function logAndReturn(x = console.log('evaluated')) {
  return x;
}

logAndReturn(); // logs — impurity leaks through default
```

Keep defaults pure (constants or pure expressions).

---

### 12. Iterators and generators (consumption is a side effect)

```js
function first(iter) {
  return iter.next().value; // mutates iterator state
}

const g = (function* () { yield 1; yield 2; })();
console.log(first(g)); // 1
console.log(first(g)); // 2 — same input, different output
```

Pure functions should treat iterators as **stateful resources**, not values. Convert to arrays first if you need purity: `[...iter]`.

---

### 13. Sparse arrays and holes

```js
const arr = [1, , 3];

console.log(arr.map(x => x * 2)); // [2, empty, 6] — holes skipped
console.log(arr.length);          // 3

// If you need dense behavior, normalize first
function dense(arr) {
  return Array.from(arr, x => x ?? 0);
}
```

---

### 14. Object property enumeration order

```js
const obj = { b: 1, a: 2, 10: 3, 1: 4 };

console.log(Object.keys(obj));
// ["1", "10", "b", "a"] — integer keys sorted first
```

Pure functions that depend on key order are fragile. If order matters, sort keys explicitly:

```js
function sortedKeys(obj) {
  return Object.keys(obj).sort();
}
```

---

### 15. Locale, timezone, and formatting

```js
function formatDate(d) {
  return d.toLocaleDateString(); // depends on runtime locale/timezone
}

// Pure-ish: pin locale and timezone
function formatDatePure(d, locale = 'en-US', tz = 'UTC') {
  return new Intl.DateTimeFormat(locale, { timeZone: tz }).format(d);
}
```

Same issue with `String.prototype.localeCompare`, `Number.prototype.toLocaleString`, `Intl.Collator`.

---

### 16. Date mutation

```js
function addDay(date) {
  date.setDate(date.getDate() + 1); // mutates input
  return date;
}

// Pure
function addDayPure(date) {
  const d = new Date(date);
  d.setDate(d.getDate() + 1);
  return d;
}
```

---

### 17. Floating-point determinism

```js
console.log(0.1 + 0.2 === 0.3); // false

// For comparisons, use epsilon
function approxEqual(a, b, eps = 1e-10) {
  return Math.abs(a - b) < eps;
}
```

Also beware of `NaN` propagation, `Infinity`, and `-0`.

---

### 18. Unicode normalization

```js
const a = 'é';            // single code point U+00E9
const b = 'e\u0301';      // e + combining acute

console.log(a === b);     // false
console.log(a.normalize() === b.normalize()); // true
```

Pure string functions should `.normalize('NFC')` before comparison if equivalence is intended.

---

### 19. `WeakMap` / `WeakSet` / `FinalizationRegistry` (GC nondeterminism)

```js
const wm = new WeakMap();
function cache(obj, val) { wm.set(obj, val); } // depends on GC lifetime

const fr = new FinalizationRegistry(held => console.log('finalized', held));
// Finalization timing is nondeterministic
```

Avoid relying on finalization or weak collection timing in pure logic.

---

### 20. Shared memory and atomics (worker contexts)

```js
const sab = new SharedArrayBuffer(4);
const view = new Int32Array(sab);
Atomics.add(view, 0, 1); // observable shared state
```

Pure functions must not touch shared buffers.

---

### 21. Async, timers, and scheduling

```js
function delayed(x) {
  setTimeout(() => console.log(x), 0); // side effect
  return x;
}
```

Async functions can still be “pure” in the sense of returning a promise for a deterministic value, **but** any timer, I/O, or event listener makes the program impure. Keep effects at the boundary (e.g., in an effect handler), not in reducers/selectors.

---

### 22. Module-level and global state

```js
// Impure: depends on global
function getApiBase() {
  return window.API_BASE;
}

// Pure: make it a parameter
function getApiBasePure(config) {
  return config.apiBase;
}
```

Same for `process.env`, `import.meta.env`, `localStorage`, etc.

---

### 23. `eval`, `Function`, and `with`

```js
function makeAdder(n) {
  return new Function('x', `return x + ${n}`); // dynamic code generation
}
```

Avoid in pure pipelines; output depends on scope and is hard to reason about.

---

### 24. Prototype mutation and `__proto__`

```js
const obj = {};
obj.__proto__ = { hacked: true }; // mutates prototype chain
```

Never mutate prototypes in pure code. Use `Object.create` or class instances instead.

---

### 25. Property descriptors (non-writable / non-configurable)

```js
const o = {};
Object.defineProperty(o, 'x', { value: 1, writable: false });

// Attempted mutation silently fails in non-strict, throws in strict
o.x = 2;
console.log(o.x); // 1
```

Pure functions should not assume they can mutate arbitrary inputs; check descriptors or clone first.

---

### 26. `Object.freeze`, `seal`, `preventExtensions`

```js
const frozen = Object.freeze({ x: 1 });
// frozen.x = 2; // throws in strict mode
```

Frozen inputs are safer, but a pure function still shouldn’t attempt mutation. Treat all inputs as read-only.

---

### 27. Symbols as property keys

```js
const s = Symbol('id');
const obj = { [s]: 42 };

console.log(Object.keys(obj)); // [] — symbols are not enumerable by default
console.log(Object.getOwnPropertySymbols(obj)); // [Symbol(id)]
```

Enumeration-based pure functions may miss symbol keys. Use `Reflect.ownKeys` if you need all keys.

---

### 28. `BigInt` and mixed arithmetic

```js
// 1n + 1 // TypeError: Cannot mix BigInt and other types
function add(a, b) {
  if (typeof a === 'bigint' || typeof b === 'bigint') {
    return BigInt(a) + BigInt(b); // explicit
  }
  return a + b;
}
```

---

### 29. JSON serialization edge cases

```js
const obj = {
  a: undefined,
  b: () => {},
  c: Symbol('x'),
  d: NaN,
  e: Infinity,
  f: new Date()
};

console.log(JSON.stringify(obj));
// {"d":null,"e":null,"f":"2024-..."} — data loss!
```

Pure functions that serialize should validate or transform these explicitly.

---

### 30. React / state-management specific (if applicable)

```js
// IMPURE reducer: mutates state
function reducer(state, action) {
  state.count++; // mutation
  return state;
}

// PURE reducer
function reducerPure(state, action) {
  return { ...state, count: state.count + 1 };
}
```

Also memoization with `useMemo`/`useCallback` depends on referential equality; impure functions break memoization.

---

## Practical checklist for writing pure functions

1. **Never mutate inputs** — clone or use immutable updates.
2. **No `this` dependence** — make all dependencies explicit parameters.
3. **No closures over mutable variables** — pass state explicitly.
4. **No time/random/env access** — inject them.
5. **Reset or avoid stateful APIs** (RegExp, iterators, streams).
6. **Use `Object.is` for special values** (`NaN`, `-0`).
7. **Clone `Date`, `URL`, `RegExp`, and other mutable objects.**
8. **Avoid proxies/getters with side effects.**
9. **Pin locale/timezone** in formatting.
10. **Normalize Unicode** before string comparison.
11. **Treat all inputs as read-only** (freeze in tests to catch mutations).
12. **Keep effects at the boundary**, not in core logic.

---

### A “pure by construction” helper

```js
function pure(fn) {
  return Object.freeze(function (...args) {
    // Shallow freeze args to catch accidental mutation in strict mode
    const frozenArgs = args.map(a =>
      (a !== null && typeof a === 'object') ? Object.freeze(a) : a
    );
    return fn(...frozenArgs);
  });
}

// Usage
const add = pure((a, b) => a + b);
```

This won’t catch deep mutation or non-determinism, but it helps enforce “no mutation” discipline.

