If you want, I can go deeper into **one specific category** (e.g., deep immutability strategies, testing pure functions, or React reducer purity) with more examples.

JavaScript has three very different “random number” needs:

| Need | Best tool | Properties |
|---|---|---|
| Quick, non-critical randomness | `Math.random()` | Fast, not seedable, not cryptographically secure |
| Deterministic/reproducible sequences | A seeded PRNG | Repeatable from seed, still not secure |
| Security (tokens, passwords, IDs) | Web Crypto / Node `crypto` | OS entropy, unseedable, secure |

Below is a single, runnable Node.js file (`random.js`) that demonstrates all three, plus common helpers: ranges, booleans, choices, Fisher–Yates shuffles, and sample-without-replacement. It works in modern browsers too.

Save as `random.js` and run with:

```bash
node random.js
```

```js
// random.js
// Runnable with Node.js >= 18 (global crypto) or a modern browser.

/* ------------------------------ utilities ------------------------------ */

function hashString(str) {
  // FNV-1a 32-bit: convert a string seed into a numeric seed.
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

/* ------------------------------- PRNGs -------------------------------- */

// Each factory returns a function `next()` producing a float in [0, 1).

function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a |= 0;
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function xorshift32(seed) {
  let x = (seed >>> 0) || 1;
  return function next() {
    x ^= x << 13; x >>>= 0;
    x ^= x >>> 17; x >>>= 0;
    x ^= x << 5; x >>>= 0;
    return x / 0x100000000;
  };
}

function lcg(seed) {
  let state = seed >>> 0;
  const a = 1664525;
  const c = 1013904223;
  return function next() {
    state = (Math.imul(state, a) + c) >>> 0;
    return state / 0x100000000;
  };
}

const PRNG_FACTORIES = { mulberry32, xorshift32, lcg };

/* --------------------------- secure randomness --------------------------- */

function getSecureUint32() {
  if (typeof globalThis.crypto !== 'undefined' &&
      typeof globalThis.crypto.getRandomValues === 'function') {
    const a = new Uint32Array(1);
    globalThis.crypto.getRandomValues(a);
    return a[0];
  }
  throw new Error('Secure RNG unavailable: globalThis.crypto.getRandomValues is missing.');
}

function secureRandomFloat() {
  // [0, 1)
  return getSecureUint32() / 0x100000000;
}

function secureRandomInt(min, max) {
  // Integer in [min, max) with rejection sampling to avoid modulo bias.
  if (!Number.isInteger(min) || !Number.isInteger(max)) {
    throw new TypeError('min and max must be integers');
  }
  if (max <= min) throw new RangeError('max must be greater than min');

  const range = max - min;
  if (range === 1) return min;

  const limit = 0x100000000 - (0x100000000 % range);
  let r;
  do {
    r = getSecureUint32();
  } while (r >= limit);
  return min + (r % range);
}

/* ---------------------------- SeededRandom ------------------------------- */

class SeededRandom {
  constructor(seed = 123456789, algorithm = 'mulberry32') {
    const factory = PRNG_FACTORIES[algorithm];
    if (!factory) throw new Error(`Unknown PRNG algorithm: ${algorithm}`);

    const numericSeed = typeof seed === 'string' ? hashString(seed) : (seed >>> 0);
    this.algorithm = algorithm;
    this.seed = numericSeed;
    this.next = factory(numericSeed);
  }

  // Core output, float in [0, 1).
  random() {
    return this.next();
  }

  // Float in [min, max).
  float(min = 0, max = 1) {
    if (!(max > min)) throw new RangeError('max must be greater than min');
    return min + this.random() * (max - min);
  }

  // Integer in [min, max)  (half-open, like most RNG APIs).
  int(min = 0, max = 2) {
    if (!Number.isInteger(min) || !Number.isInteger(max)) {
      throw new TypeError('min and max must be integers');
    }
    if (max <= min) throw new RangeError('max must be greater than min');
    return min + Math.floor(this.random() * (max - min));
  }

  // Integer in [min, max] inclusive.
  intInclusive(min, max) {
    return this.int(min, max + 1);
  }

  // Boolean with optional probability of true.
  bool(probability = 0.5) {
    if (probability < 0 || probability > 1) throw new RangeError('probability must be in [0, 1]');
    return this.random() < probability;
  }

  // Random element.
  choice(array) {
    if (!Array.isArray(array) || array.length === 0) {
      throw new TypeError('choice() requires a non-empty array');
    }
    return array[this.int(0, array.length)];
  }

  // Fisher-Yates shuffle; returns a new array (does not mutate input).
  shuffle(array) {
    if (!Array.isArray(array)) throw new TypeError('shuffle() requires an array');
    const result = array.slice();
    for (let i = result.length - 1; i > 0; i--) {
      const j = this.int(0, i + 1);
      [result[i], result[j]] = [result[j], result[i]];
    }
    return result;
  }

  // Sample k distinct elements without replacement (partial Fisher-Yates).
  sample(array, k) {
    if (!Array.isArray(array)) throw new TypeError('sample() requires an array');
    if (!Number.isInteger(k) || k < 0 || k > array.length) {
      throw new RangeError('sample() k must be an integer between 0 and array.length');
    }
    const copy = array.slice();
    const out = [];
    for (let i = 0; i < k; i++) {
      const j = this.int(i, copy.length);
      [copy[i], copy[j]] = [copy[j], copy[i]];
      out.push(copy[i]);
    }
    return out;
  }

  // Deterministic reset.
  reset(seed = this.seed, algorithm = this.algorithm) {
    const factory = PRNG_FACTORIES[algorithm];
    if (!factory) throw new Error(`Unknown PRNG algorithm: ${algorithm}`);
    const numericSeed = typeof seed === 'string' ? hashString(seed) : (seed >>> 0);
    this.algorithm = algorithm;
    this.seed = numericSeed;
    this.next = factory(numericSeed);
  }
}

/* -------------------------------- demo --------------------------------- */

function demo() {
  console.log('=== Built-in Math.random() ===');
  console.log('Math.random():', Math.random()); // [0, 1), not seedable

  console.log('\n=== Seeded PRNGs ===');
  const rng = new SeededRandom('hello world', 'mulberry32');
  console.log('floats:', Array.from({ length: 5 }, () => rng.random().toFixed(6)));
  console.log('ints 1..10:', Array.from({ length: 10 }, () => rng.int(1, 11)));
  console.log('bools:', Array.from({ length: 8 }, () => rng.bool(0.3)));
  console.log('choice:', rng.choice(['red', 'green', 'blue']));
  console.log('shuffle:', rng.shuffle([1, 2, 3, 4, 5]));
  console.log('sample(3):', rng.sample([1, 2, 3, 4, 5], 3));

  console.log('\n=== Reproducibility ===');
  const a = new SeededRandom(42, 'xorshift32');
  const b = new SeededRandom(42, 'xorshift32');
  const seqA = Array.from({ length: 5 }, () => a.int(0, 1000));
  const seqB = Array.from({ length: 5 }, () => b.int(0, 1000));
  console.log('seqA:', seqA);
  console.log('seqB:', seqB);
  console.log('equal?', JSON.stringify(seqA) === JSON.stringify(seqB));

  console.log('\n=== Algorithm comparison (first 3 values) ===');
  for (const alg of ['mulberry32', 'xorshift32', 'lcg']) {
    const r = new SeededRandom(1, alg);
    console.log(alg, Array.from({ length: 3 }, () => r.random().toFixed(6)));
  }

  console.log('\n=== Secure randomness ===');
  try {
    console.log('secure float:', secureRandomFloat());
    console.log('secure int [1, 7):', secureRandomInt(1, 7));   // die roll 1..6
    console.log('secure int [0, 100):', secureRandomInt(0, 100));
    console.log('secure bool-ish [0,2):', secureRandomInt(0, 2));
  } catch (e) {
    console.log('secure RNG unavailable:', e.message);
  }

  console.log('\n=== Reset demo ===');
  const r2 = new SeededRandom('reset-me');
  console.log('before reset:', r2.int(0, 1000), r2.int(0, 1000));
  r2.reset('reset-me');
  console.log('after reset :', r2.int(0, 1000), r2.int(0, 1000));
}

demo();
```

### Key points to remember

1. **`Math.random()`** returns a float in `[0, 1)`. It is fast and global, but you cannot seed it and it is not suitable for security.
2. **Seeded PRNGs** are deterministic: the same seed and algorithm produce the same sequence. Use them for tests, simulations, procedural generation, and reproducible experiments. `mulberry32` is a good default; `xorshift32` and `lcg` are included for comparison.
3. **Do not use a seeded PRNG for secrets.** Its internal state can be recovered from observed outputs.
4. **For security**, use `crypto.getRandomValues` (browser) or `crypto.randomBytes`/`randomUUID` (Node). The example’s `secureRandomInt` uses rejection sampling to remove modulo bias.
5. **Ranges are half-open** `[min, max)` in this code. If you want inclusive bounds, use `intInclusive(min, max)`.
6. **Shuffles** must use an unbiased index (`int(0, i + 1)` in the Fisher–Yates loop), not `Math.floor(Math.random() * n)` repeatedly in a naive way, or you bias the result.
7. **String seeds** are hashed to 32-bit integers before being used. If you need 64-bit+ state, use a larger PRNG state; for most applications 32-bit state is sufficient.

# Random Numbers in JavaScript

## The idea

JavaScript exposes randomness through **`Math.random()`**, which returns a **pseudo-random** floating-point number in the half-open interval **`[0, 1)`** — that is, `0` is possible, `1` is never returned.

A few important properties:

- **Pseudo-random, not truly random.** The engine runs a deterministic PRNG (e.g., V8 uses xorshift128+). Given the same internal state it produces the same sequence. The seed is chosen by the engine from OS entropy (time, etc.), and **standard JS gives you no way to set or read the seed**.
- **Not cryptographically secure.** Outputs can be predicted if enough values are observed. For passwords, tokens, lottery-style draws, or anything security-sensitive, use the Web Crypto / Node crypto APIs instead.
- **Uniform-ish over `[0,1)`.** Each call is independent (in the PRNG sense) and each value in the range is approximately equally likely.

## The syntax

```js
Math.random(); // e.g. 0.374928102348...
```

From that single primitive you build everything else.

### Integer in `[0, n)` (n exclusive)

```js
function randInt(n) {
  return Math.floor(Math.random() * n);
}
randInt(6); // 0..5
```

### Integer in `[min, max]` (both inclusive)

```js
function randBetween(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}
randBetween(1, 6); // dice roll 1..6
```

### Float in `[min, max)`

```js
function randFloat(min, max) {
  return Math.random() * (max - min) + min;
}
```

### Boolean coin flip

```js
const heads = Math.random() < 0.5;
```

### Pick a random array element

```js
const items = ["a", "b", "c"];
const pick = items[Math.floor(Math.random() * items.length)];
```

### Pitfalls to avoid

- **Don't use `%` for ranges** — `Math.random() * 10 % 6` introduces modulo bias. Multiply then `Math.floor`.
- **Off-by-one**: `max - min + 1` is needed for an inclusive upper bound.
- **`Math.random()` never returns `1`**, so `Math.floor(Math.random() * n)` can never produce `n`.

## Typical use cases

### 1. Dice / random integer

```js
const roll = () => Math.floor(Math.random() * 6) + 1;
```

### 2. Random item from a list

```js
const colors = ["red", "green", "blue"];
const color = colors[Math.floor(Math.random() * colors.length)];
```

### 3. Shuffle an array (Fisher–Yates, in place)

```js
function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}
```

### 4. Random hex color

```js
const hex = "#" + Math.floor(Math.random() * 0xffffff)
  .toString(16).padStart(6, "0");
```

### 5. Random delay (jitter)

```js
setTimeout(task, 1000 + Math.random() * 500); // 1000–1500 ms
```

### 6. Weighted choice

```js
function weightedPick(items, weights) {
  const total = weights.reduce((a, b) => a + b, 0);
  let r = Math.random() * total;
  for (let i = 0; i < items.length; i++) {
    r -= weights[i];
    if (r < 0) return items[i];
  }
  return items[items.length - 1];
}
```

## Cryptographically secure randomness

For anything security-sensitive, don't use `Math.random()`.

**Browser:**

```js
// random bytes
const bytes = new Uint8Array(16);
crypto.getRandomValues(bytes);

// random integer in [0, max)
function secureInt(max) {
  const arr = new Uint32Array(1);
  crypto.getRandomValues(arr);
  return arr[0] % max; // note: still has modulo bias for non-power-of-2 max
}

// UUID v4
const id = crypto.randomUUID();
```

**Node.js:**

```js
const crypto = require("crypto");

crypto.randomBytes(16);          // Buffer
crypto.randomInt(1, 7);           // 1..6, no modulo bias
crypto.randomUUID();             // UUID v4
```

`crypto.randomInt(min, max)` is especially nice because it avoids modulo bias by rejection sampling internally.

## Summary

- `Math.random()` → pseudo-random double in `[0, 1)`, fast and fine for games/UI/non-security.
- Build integers with `Math.floor(Math.random() * (max - min + 1)) + min`.
- Shuffle with Fisher–Yates.
- For security/tokens/IDs use `crypto.getRandomValues`, `crypto.randomUUID`, or Node's `crypto.randomInt`/`randomBytes`.

## Mistake

```js
function randomInt(min, max) {
  // "Pick a random integer between min and max (inclusive)"
  return Math.round(Math.random() * (max - min)) + min;
}
```

## Corrected version

```js
function randomInt(min, max) {
  // Inclusive on both ends
  const range = max - min + 1;
  return Math.floor(Math.random() * range) + min;
}
```

## What was wrong and why

1. **Off-by-one range size**  
   `Math.random()` returns a value in `[0, 1)` (0 included, 1 excluded). To cover `N` distinct integers you need a multiplier of `N`.  
   - Number of integers from `min` to `max` inclusive is `max - min + 1`.  
   - The buggy code uses `max - min`, so it can never produce `max` and the distribution is shifted.

2. **`Math.round` skews the distribution**  
   `Math.round` rounds to the nearest integer, which makes the first and last values in the range only half as likely as the middle values.  
   - Example: with multiplier `5`, `Math.round(Math.random() * 5)` yields `0` only for inputs in `[0, 0.5)`, but `1` for `[0.5, 1.5)`, and so on.  
   - `Math.floor` maps each integer to an equal-width interval `[k, k+1)`, giving a uniform distribution.

3. **Implicit assumption about inclusivity**  
   The comment says “inclusive,” but the code behaves as if `max` were exclusive and the endpoints were half-weighted. Always state and implement the boundary convention explicitly.

### Quick sanity check

```js
const counts = {};
for (let i = 0; i < 1_000_000; i++) {
  const v = randomInt(1, 6); // die roll
  counts[v] = (counts[v] || 0) + 1;
}
console.log(counts);
// Each face should be ~166,667
```

## Related pitfalls worth knowing

- **Modulo bias**: `Math.floor(Math.random() * 2**53) % n` is not uniform for large `n` because `2**53` is rarely divisible by `n`. For small `n` (like dice) it’s usually fine; for cryptographic or large ranges, use rejection sampling or `crypto.getRandomValues`.
- **Not cryptographically secure**: `Math.random()` is a PRNG, not CSPRNG. For tokens, passwords, or security-sensitive values use:
  ```js
  const arr = new Uint32Array(1);
  crypto.getRandomValues(arr);
  const secureInt = arr[0];
  ```
- **Floating-point endpoints**: If you need a random float in `[min, max)`, use `min + Math.random() * (max - min)` and don’t “round to nearest” unless you account for the half-open interval.

# Common Pitfalls with Random Numbers in JavaScript

## 1. Using `Math.random()` for security-sensitive values

`Math.random()` is **not cryptographically secure** — its output is predictable given enough samples. Never use it for tokens, passwords, session IDs, or anything security-related.

```js
// ❌ BAD: predictable "token"
const token = Math.random().toString(36).slice(2);

// ✅ GOOD (browser)
const bytes = new Uint8Array(32);
crypto.getRandomValues(bytes);
const token = Array.from(bytes, b => b.toString(16).padStart(2, "0")).join("");

// ✅ GOOD (Node)
const { randomBytes } = require("node:crypto");
const token = randomBytes(32).toString("hex");
```

---

## 2. Modulo bias when mapping to a range

`Math.random() % n` (or `randomInt % n`) is biased because 2^53 is not divisible by most n. Some values come out slightly more often.

```js
// ❌ BAD: biased distribution
function badDie() {
  return Math.floor(Math.random() * 6) + 1; // actually OK for small n? see note
}
// The classic bias appears with: randomInt % n
function biasedModulo(n) {
  return Math.floor(Math.random() * 0x100000000) % n; // biased
}

// ✅ GOOD: rejection sampling for uniform int in [0, n)
function uniformInt(n) {
  if (n <= 0 || n > 2 ** 53) throw new RangeError("bad n");
  const limit = 2 ** 53 - (2 ** 53 % n); // largest multiple of n ≤ 2^53
  let x;
  do {
    x = Math.floor(Math.random() * 2 ** 53); // still not crypto; demo only
  } while (x >= limit);
  return x % n;
}
```

> Note: `Math.floor(Math.random() * 6)` is *approximately* uniform because 2^53 is huge relative to 6, but for small moduli of large randoms, bias matters. For crypto, use `crypto.getRandomValues` with rejection.

---

## 3. Off-by-one in inclusive ranges

`Math.random()` returns `[0, 1)` — 0 inclusive, 1 exclusive. Forgetting this causes off-by-one errors.

```js
// ❌ BAD: Math.round skews endpoints (0 and n less likely)
function badRange(min, max) {
  return Math.round(Math.random() * (max - min)) + min;
}

// ✅ GOOD: integer in [min, max] inclusive
function randInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

// ✅ GOOD: float in [min, max)
function randFloat(min, max) {
  return Math.random() * (max - min) + min;
}
```

---

## 4. Floating-point precision for large ranges

Numbers above `Number.MAX_SAFE_INTEGER` (2^53 − 1) lose integer precision. Random IDs or large counters get rounded.

```js
// ❌ BAD
const big = Math.floor(Math.random() * 1e18); // not uniform, precision lost
console.log(big === big + 1); // sometimes true

// ✅ GOOD: use BigInt + crypto, or split into chunks
function randomBigInt(bits) {
  const bytes = new Uint8Array(Math.ceil(bits / 8));
  crypto.getRandomValues(bytes);
  let v = 0n;
  for (const b of bytes) v = (v << 8n) | BigInt(b);
  return v & ((1n << BigInt(bits)) - 1n);
}
```

---

## 5. Naïve array shuffle using `sort(() => Math.random() - 0.5)`

This is **not uniform** and can be biased or even infinite-loop-ish in some engines. Use Fisher–Yates.

```js
// ❌ BAD
const arr = [1,2,3,4,5];
arr.sort(() => Math.random() - 0.5);

// ✅ GOOD: Fisher–Yates (in place)
function shuffle(a) {
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
```

---

## 6. Assuming `Math.random()` is seedable / reproducible

It isn't. You cannot seed it. For reproducible sequences (tests, simulations), use a PRNG you control.

```js
// ❌ No seed API exists:
Math.seed(42); // TypeError: not a function

// ✅ A tiny mulberry32 PRNG (deterministic, NOT crypto)
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rng = mulberry32(12345);
console.log(rng(), rng(), rng()); // reproducible
```

---

## 7. Weighted random with floating accumulation errors

Comparing cumulative weights with `<=` and floats can drop or duplicate outcomes at boundaries.

```js
// ❌ RISKY
const weights = [0.1, 0.2, 0.7];
function pickBad() {
  const r = Math.random();
  let acc = 0;
  for (let i = 0; i < weights.length; i++) {
    acc += weights[i];
    if (r <= acc) return i; // boundary issues
  }
}

// ✅ BETTER: integer weights + integer random, or normalize + strict <
function weightedPick(items, weights) {
  // weights: array of non-negative numbers
  const total = weights.reduce((a, b) => a + b, 0);
  let r = Math.random() * total;
  for (let i = 0; i < items.length; i++) {
    r -= weights[i];
    if (r < 0) return items[i];
  }
  return items[items.length - 1]; // floating-point safety
}
```

---

## 8. Confusing “random boolean” idioms

`Math.random() < 0.5` is fine; `Math.round(Math.random())` is biased toward... actually endpoints; `!!Math.random()` is always true (since 0 is rare but possible and truthy-ish—actually 0 is falsy, so `!!0 === false`, but probability ~0; still not idiomatic).

```js
// ❌ Weird / biased
const b1 = Math.round(Math.random()); // 0 or 1, but 0.5 rounds to 1 (bias)
const b2 = Math.random() > 0.5 ? true : false; // OK but verbose

// ✅ GOOD
const coin = Math.random() < 0.5;
// crypto:
const secureCoin = crypto.getRandomValues(new Uint8Array(1))[0] < 128;
```

---

## 9. Generating random strings incorrectly

`Math.random().toString(36)` has limited entropy (~52 bits max, often less), includes predictable prefixes, and isn't uniform across characters.

```js
// ❌ BAD: low entropy, biased chars, not crypto
function randomStr(n) {
  return Math.random().toString(36).slice(2, 2 + n);
}

// ✅ GOOD: crypto + rejection / unbiased alphabet
function randomString(length, alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789") {
  const bytes = new Uint8Array(length * 2);
  crypto.getRandomValues(bytes);
  let out = "";
  for (let i = 0; i < length; ) {
    const b = bytes[i * 2] | (bytes[i * 2 + 1] << 8);
    if (b < Math.floor(65536 / alphabet.length) * alphabet.length) {
      out += alphabet[b % alphabet.length];
      i++;
    }
  }
  return out;
}
```

---

## 10. Using `Date.now()` or `performance.now()` as randomness

Timestamps are predictable and low entropy, especially in tight loops (collisions).

```js
// ❌ BAD
const id = Date.now() + Math.random(); // still mostly timestamp

// ✅ GOOD
const id = crypto.randomUUID(); // browser/Node 19+
```

---

## 11. Assuming `Math.random()` never returns 0 or 1 exactly

It *can* return 0 (rarely). Code that divides by the result or uses it as a divisor can crash or produce `Infinity`.

```js
// ❌ DANGEROUS
const scale = 1 / Math.random(); // Infinity if 0

// ✅ SAFE
let r;
do { r = Math.random(); } while (r === 0);
const scale = 1 / r;
```

---

## 12. Sampling without replacement mistakes

Picking `k` distinct items by repeatedly calling `random` and checking `includes` is O(n²) and biased if you don't remove.

```js
// ❌ BAD: biased + slow
function pickBad(arr, k) {
  const out = [];
  while (out.length < k) {
    const x = arr[Math.floor(Math.random() * arr.length)];
    if (!out.includes(x)) out.push(x);
  }
  return out;
}

// ✅ GOOD: Fisher–Yates partial
function sample(arr, k) {
  const a = arr.slice();
  const n = Math.min(k, a.length);
  for (let i = 0; i < n; i++) {
    const j = i + Math.floor(Math.random() * (a.length - i));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a.slice(0, n);
}
```

---

## 13. Race conditions with a shared PRNG in async code

If you use a stateful seeded PRNG across concurrent async operations, interleaving can make results depend on scheduling. Prefer per-call stateless crypto or pass RNG instances explicitly.

```js
// ❌ BAD: shared mutable rng across async tasks
const rng = mulberry32(1);
async function task() { return rng(); } // order-dependent

// ✅ BETTER: each task creates its own, or use crypto.getRandomValues (stateless)
async function task() {
  const b = new Uint32Array(1);
  crypto.getRandomValues(b);
  return b[0] / 2 ** 32;
}
```

---

## 14. Floating “random” in tests (non-determinism)

Tests that rely on `Math.random()` become flaky. Inject a deterministic RNG.

```js
// ✅ GOOD: dependency injection
function makeService(rng = Math.random) {
  return { roll: () => Math.floor(rng() * 6) + 1 };
}
// in tests:
const svc = makeService(() => 0.5); // deterministic
```

---

## Quick reference checklist

| Pitfall | Fix |
|---|---|
| Security use | `crypto.getRandomValues` / `crypto.randomUUID` |
| Modulo bias | rejection sampling |
| Inclusive range | `floor(random * (max-min+1)) + min` |
| Shuffle | Fisher–Yates |
| Large ints | BigInt + crypto |
| Seedable RNG | mulberry32 / seedrandom |
| Weighted pick | subtract from running total |
| Random string | crypto + rejection |
| Div by random | guard against 0 |
| Sampling k items | partial Fisher–Yates |
| Async shared state | per-call crypto or injected RNG |

