## Random numbers in JavaScript

### What JS gives you
- **`Math.random()`** returns a 64-bit IEEE-754 float in **`[0, 1)`** (inclusive 0, exclusive 1).  
- It’s **pseudo-random**: deterministic given the engine’s hidden state; you cannot seed it.  
- It’s **fast** but **not cryptographically secure** (don’t use for tokens/passwords).  
- Practical distribution is “good enough” for games/UI, but it has tiny biases and limited precision (~53 bits of mantissa).  
- For secure randomness use **`crypto.getRandomValues()`** (browser) or **`crypto.randomBytes()`** (Node).  
- Engines differ: V8 historically uses xorshift128+; SpiderMonkey/JavaScriptCore use their own PRNGs.

### Common patterns
```js
// integer in [0, n)
const r = Math.floor(Math.random() * n);

// integer in [min, max] inclusive
const r2 = Math.floor(Math.random() * (max - min + 1)) + min;

// float in [min, max)
const r3 = Math.random() * (max - min) + min;
```

### “Core” implementation: a seeded PRNG
Since `Math.random` can’t be seeded, here’s a clean, dependency-free **mulberry32** PRNG plus range helpers. It’s small, fast, and good for simulations/tests.

```js
/**
 * mulberry32: small 32-bit PRNG with good statistical quality.
 * Returns a function that yields floats in [0, 1).
 *
 * @param {number} seed - any 32-bit (or coercible) seed
 * @returns {() => number}
 */
function makeRng(seed) {
  // Coerce seed to unsigned 32-bit for stable behavior.
  let state = seed >>> 0;

  return function rand() {
    // Advance state with a LCG-like step.
    state = (state + 0x6D2B79F5) >>> 0;

    // Mix bits (mulberry32 finalization).
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296; // / 2^32
  };
}

/**
 * Create helpers bound to one RNG instance.
 */
function makeRandom(seed) {
  const rand = makeRng(seed);

  return {
    /** float in [0, 1) */
    float() { return rand(); },

    /** float in [min, max) */
    floatRange(min, max) {
      if (max <= min) throw new Error('max must be > min');
      return rand() * (max - min) + min;
    },

    /** integer in [0, n) */
    int(n) {
      if (!Number.isInteger(n) || n <= 0) throw new Error('n must be positive integer');
      return Math.floor(rand() * n);
    },

    /** integer in [min, max] inclusive */
    intRange(min, max) {
      if (!Number.isInteger(min) || !Number.isInteger(max)) {
        throw new Error('min/max must be integers');
      }
      if (max < min) throw new Error('max must be >= min');
      return Math.floor(rand() * (max - min + 1)) + min;
    },

    /** pick one item from an array */
    choice(arr) {
      if (!Array.isArray(arr) || arr.length === 0) {
        throw new Error('arr must be non-empty array');
      }
      return arr[this.int(arr.length)];
    },

    /** Fisher–Yates shuffle (returns new array) */
    shuffle(arr) {
      if (!Array.isArray(arr)) throw new Error('arr must be array');
      const out = arr.slice();
      for (let i = out.length - 1; i > 0; i--) {
        const j = this.int(i + 1);
        [out[i], out[j]] = [out[j], out[i]];
      }
      return out;
    },
  };
}

// ---- demo ----
const r = makeRandom(42);
console.log(r.float());                 // deterministic
console.log(r.intRange(1, 6));          // die roll
console.log(r.choice(['a', 'b', 'c']));
console.log(r.shuffle([1, 2, 3, 4, 5]));
```

### When to use which
| Need | Use |
|---|---|
| Games, animations, non-security | `Math.random()` or seeded PRNG above |
| Reproducible tests/simulations | Seeded PRNG (`makeRandom`) |
| Tokens, passwords, crypto | `crypto.getRandomValues()` / `crypto.randomUUID()` |

### Notes on “fairness”
- `Math.floor(rand * n)` is slightly biased unless `n` divides `2^53`; for dice you usually don’t care.  
- For perfect uniformity over large ranges, use rejection sampling.  
- Never use `Math.random` for security-sensitive values.

## Edge cases when using random numbers in JavaScript

JavaScript’s built-in `Math.random()` is simple, but it has several important limitations. The examples below use `Math.random()` for non-security cases and `crypto.getRandomValues()` for security-sensitive cases.

---

### 1. Range and endpoint bugs

`Math.random()` returns a value in `[0, 1)` — it can be `0`, but it will never be `1`.

```js
// BAD: can produce n, and is wrong for n <= 0
function badInt(n) {
  return Math.floor(Math.random() * n);
}

// GOOD: explicit, half-open interval [min, max)
function randomInt(min, max) {
  if (!Number.isInteger(min) || !Number.isInteger(max)) {
    throw new TypeError("min and max must be integers");
  }
  if (min >= max) {
    throw new RangeError("min must be less than max");
  }
  const span = max - min;
  return min + Math.floor(Math.random() * span);
}
```

Edge cases:
- `randomInt(5, 5)` must fail (empty range).
- `randomInt(5, 3)` must fail (inverted range).
- `randomInt(0, 1)` always returns `0`.
- Very large spans can lose precision because numbers are IEEE-754 doubles.

---

### 2. Floating-point intervals can occasionally hit the upper bound

When mapping to `[min, max)`, rounding can rarely produce `max`.

```js
function randomFloat(min, max) {
  if (!Number.isFinite(min) || !Number.isFinite(max) || min >= max) {
    throw new RangeError("invalid finite interval");
  }

  let value = min + Math.random() * (max - min);

  // Extremely unlikely, but possible due to floating-point rounding.
  if (value === max) {
    value = Math.nextDown?.(max) ?? max - Number.EPSILON;
  }
  return value;
}
```

If the upper bound must be strict, use rejection when exact endpoint behavior matters.

---

### 3. Precision limits for large integers

Doubles safely represent integers only up to `2^53 - 1`. Do not use `Math.random()` to choose among very large integer ranges.

```js
const MAX_SAFE = Number.MAX_SAFE_INTEGER; // 9007199254740991

// BAD for huge ranges: many integers are not representable.
function badBigIntRange(n) {
  return Math.floor(Math.random() * n);
}

// BETTER: use crypto + BigInt for large ranges.
function secureBigIntBelow(limit) {
  if (typeof limit !== "bigint" || limit <= 0n) {
    throw new RangeError("limit must be a positive BigInt");
  }

  const bytes = secureBytes(8);
  let x = 0n;
  for (const b of bytes) x = (x << 8n) | BigInt(b);

  // Rejection sampling for uniformity.
  const max = 1n << 64n;
  const threshold = max - (max % limit);
  if (x >= threshold) {
    return secureBigIntBelow(limit); // recursive retry; tail-ish, rare
  }
  return x % limit;
}

function secureBytes(len) {
  const out = new Uint8Array(len);
  const chunk = 65536;
  for (let i = 0; i < len; i += chunk) {
    crypto.getRandomValues(out.subarray(i, Math.min(i + chunk, len)));
  }
  return out;
}
```

---

### 4. Modulo bias

`random % n` is biased unless the random source’s range is divisible by `n`.

```js
// BAD: biased
function biasedDie() {
  return (crypto.getRandomValues(new Uint32Array(1))[0] % 6) + 1;
}

// GOOD: rejection sampling
function secureInt(min, max) {
  if (!Number.isInteger(min) || !Number.isInteger(max) || min >= max) {
    throw new RangeError("invalid integer range");
  }
  const range = max - min; // [min, max)
  if (range > 0x100000000) {
    throw new RangeError("range too large for 32-bit rejection sampler; use BigInt");
  }

  const maxUint32 = 0x100000000;
  const limit = maxUint32 - (maxUint32 % range);

  let x;
  do {
    x = crypto.getRandomValues(new Uint32Array(1))[0];
  } while (x >= limit);

  return min + (x % range);
}
```

For Node.js older than 19, `crypto` may not be global:

```js
const { webcrypto } = require("crypto");
const crypto = globalThis.crypto ?? webcrypto;
```

Also note some browsers limit `getRandomValues` to 65,536 bytes per call, so chunk large requests as shown in `secureBytes`.

---

### 5. Cryptographic vs. non-cryptographic randomness

`Math.random()` is not cryptographically secure. Never use it for tokens, passwords, session IDs, or reset links.

```js
// BAD
function badToken() {
  return Math.random().toString(36).slice(2);
}

// GOOD
function secureToken(bytes = 32) {
  const arr = secureBytes(bytes);
  return [...arr].map(b => b.toString(16).padStart(2, "0")).join("");
}

// GOOD: use built-in UUID when available
function secureId() {
  if (typeof crypto !== "undefined" && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  // Fallback: generate RFC4122 v4 manually.
  const b = secureBytes(16);
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  const hex = [...b].map(x => x.toString(16).padStart(2, "0")).join("");
  return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`;
}
```

---

### 6. Seeding and reproducibility

`Math.random()` cannot be seeded. That makes deterministic tests, simulations, and replay debugging difficult.

```js
// Deterministic PRNG for tests/simulations only; NOT cryptographically secure.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rng = mulberry32(12345);
console.log(rng(), rng(), rng()); // reproducible

// Inject RNG for testability.
function rollDie(rng = Math.random) {
  return 1 + Math.floor(rng() * 6);
}
```

Edge cases:
- Seeds are coerced to 32 bits.
- Two tabs/workers get independent `Math.random` state, but standard JS provides no way to inspect or reset it.
- Never use `Date.now()` or `Math.random()` as a cryptographic seed.

---

### 7. Shuffling and sampling without replacement

Using `sort(() => Math.random() - 0.5)` is wrong: the comparator is not transitive, so results can be biased and engine-dependent.

```js
// BAD
function badShuffle(arr) {
  return arr.slice().sort(() => Math.random() - 0.5);
}

// GOOD: Fisher-Yates
function shuffle(arr, rng = Math.random) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1)); // [0, i]
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// Secured version
function secureShuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = secureInt(0, i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
```

When sampling without replacement, use a set of selected indices or partial Fisher-Yates.

```js
function sample(arr, k, rng = Math.random) {
  if (k > arr.length) throw new RangeError("sample larger than population");
  const a = arr.slice();
  const result = [];
  for (let i = 0; i < k; i++) {
    const j = i + Math.floor(rng() * (a.length - i));
    [a[i], a[j]] = [a[j], a[i]];
    result.push(a[i]);
  }
  return result;
}
```

---

### 8. Weighted random selection

Cumulative weights can suffer from floating-point accumulation and degenerate weights.

```js
function weightedPick(items, weights, rng = Math.random) {
  if (items.length !== weights.length) {
    throw new RangeError("items and weights must have same length");
  }
  if (items.length === 0) {
    throw new RangeError("cannot pick from empty set");
  }

  let total = 0;
  for (const w of weights) {
    if (!Number.isFinite(w) || w < 0) {
      throw new RangeError("weights must be finite and non-negative");
    }
    total += w;
  }
  if (total <= 0) {
    throw new RangeError("total weight must be > 0");
  }

  let r = rng() * total;
  let acc = 0;
  for (let i = 0; i < items.length; i++) {
    acc += weights[i];
    if (r < acc) return items[i];
  }

  // Floating-point fallback: r should be < total, but accumulation may land slightly short.
  return items[items.length - 1];
}
```

Edge cases:
- Zero or negative weights must be rejected.
- `NaN` weights compare falsely and can cause infinite loops or wrong picks.
- If weights are integers and very large, consider using integer arithmetic or a BigInt/alias method.

---

### 9. Random elements from arrays

Always handle empty arrays and validate inputs.

```js
function randomElement(arr, rng = Math.random) {
  if (!Array.isArray(arr)) throw new TypeError("expected array");
  if (arr.length === 0) return undefined;
  return arr[Math.floor(rng() * arr.length)];
}
```

For cryptographic selection:

```js
function secureElement(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return undefined;
  return arr[secureInt(0, arr.length)];
}
```

---

### 10. Random dates and timestamps

Use numeric timestamps, not `Date` objects directly, and remember timestamp ranges must be validated.

```js
function randomDate(min, max) {
  const minTime = min instanceof Date ? min.getTime() : Number(min);
  const maxTime = max instanceof Date ? max.getTime() : Number(max);

  if (!Number.isFinite(minTime) || !Number.isFinite(maxTime) || minTime >= maxTime) {
    throw new RangeError("invalid date range");
  }

  const span = maxTime - minTime;
  const offset = Math.floor(Math.random() * span);
  return new Date(minTime + offset);
}
```

Edge cases:
- Timestamps beyond safe integer ranges lose millisecond precision.
- Avoid local-time/DST assumptions; timestamps are UTC-based.
- If you need second or day precision, generate at that granularity instead of relying on millisecond rounding.

---

### 11. Random strings, IDs, and collision probability

Short random strings have surprisingly high collision rates due to the birthday paradox. Use cryptographically secure bytes or `crypto.randomUUID()`.

```js
function randomBase64Url(bytes = 16) {
  const arr = secureBytes(bytes);
  // Convert to base64url without padding.
  const b64 = btoa(String.fromCharCode(...arr));
  return b64.replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
```

Edge cases:
- `btoa`/`atob` are browser-oriented; in Node prefer `Buffer`.
- If generated IDs are stored in a unique database column, always handle unique-constraint violations.
- UUID v4 is usually better than hand-rolled short strings.

---

### 12. Sorting with randomness

Random comparators break sort invariants.

```js
// BAD
items.sort(() => Math.random() - 0.5);

// GOOD
const shuffled = shuffle(items);
```

Also avoid depending on `Math.random()` in comparators passed to `Array.prototype.sort`, which may behave inconsistently across engines.

---

### 13. Boolean randomness

Simple and usually fine, but still subject to the same cryptographic distinction.

```js
const coinFlip = () => Math.random() < 0.5;

// Cryptographic
function secureCoinFlip() {
  return crypto.getRandomValues(new Uint8Array(1))[0] >= 128;
}
```

For biased coins, use `rng() < p`, but validate `0 <= p <= 1`.

---

### 14. Testing and mocking

Global randomness makes tests flaky. Inject an RNG and mock it.

```js
function generateToken({ rng = Math.random, secure = false } = {}) {
  if (secure) return secureToken();
  return Math.floor(rng() * 1e9).toString(36);
}

// Test
const fixedRng = () => 0.25;
console.log(generateToken({ rng: fixedRng }));
```

For cryptographic code, mock at the boundary (`crypto.getRandomValues`) rather than changing production algorithms.

---

### 15. Environment and API differences

- In browsers, `crypto` is `window.crypto` or `globalThis.crypto`.
- In Node.js, use `require("crypto").webcrypto` or global `crypto` on newer versions.
- Web Workers and realms have separate `Math.random` state.
- Some older engines had weaker `Math.random` implementations; modern engines use better algorithms, but still not cryptographic.
- `crypto.getRandomValues` may throw for oversized typed arrays; chunk large reads.

---

### Practical checklist

- Validate `min`, `max`, finite numbers, and integer requirements.
- Reject empty arrays and invalid weights.
- Use `Math.floor(Math.random() * span)` for non-security integer ranges.
- Use rejection sampling for cryptographically uniform integers.
- Never use `Math.random()` for secrets, IDs, tokens, or security-sensitive choices.
- Do not sort with a random comparator.
- Use Fisher-Yates for shuffling.
- Inject RNGs for testability.
- Use `crypto.randomUUID()` or secure byte generation for IDs.
- Prefer BigInt/crypto for ranges above `2^53`.

If you want, I can also provide a small reusable utility module containing all the safe helpers above.

# Reading Other People’s Code in JavaScript

Below is a **complete, runnable Node.js tool** that reads a codebase (someone else’s repo) and produces a structured “map” of it: files, imports/exports, functions, classes, variables, complexity heuristics, and (optionally) runtime-export introspection. It uses a real parser (`acorn`) when available and falls back to regex extraction so it runs even without dependencies.

## 1. Install (optional parser)

```bash
npm init -y
npm i acorn   # optional; tool works without it
```

## 2. `codereader.js`

```js
// codereader.js  --  read & summarize "other people's code"
// Usage: node codereader.js [targetDir] [--json] [--inspect] [--top=N]
//   --inspect : attempts to require modules to list runtime exports (UNTRUSTED CODE RISK)

const fs = require('fs');
const path = require('path');

const args = process.argv.slice(2);
const opts = {
  dir: '.',
  json: false,
  inspect: false,
  top: 20,
};
for (const a of args) {
  if (a === '--json') opts.json = true;
  else if (a === '--inspect') opts.inspect = true;
  else if (a.startsWith('--top=')) opts.top = Number(a.slice(6)) || 20;
  else if (!a.startsWith('--')) opts.dir = a;
}

// ---------- optional parser ----------
let acorn = null;
try { acorn = require('acorn'); } catch (_) {}

const EXT = new Set(['.js', '.mjs', '.cjs', '.ts', '.tsx', '.jsx']);
const IGNORE = new Set(['node_modules', '.git', 'dist', 'build', 'coverage', '.next', '.cache']);

// ---------- walking ----------
function walk(root) {
  const out = [];
  function rec(dir) {
    let entries;
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); }
    catch (e) { return; }
    for (const e of entries) {
      if (IGNORE.has(e.name)) continue;
      const full = path.join(dir, e.name);
      if (e.isDirectory()) rec(full);
      else if (EXT.has(path.extname(e.name))) out.push(full);
    }
  }
  rec(path.resolve(root));
  return out;
}

function safeRead(file) {
  try { return fs.readFileSync(file, 'utf8'); }
  catch (e) { return null; }
}

// ---------- regex fallback ----------
function regexAnalyze(code, file) {
  const lines = code.split(/\r?\n/);
  const lineOf = (idx) => code.slice(0, idx).split(/\r?\n/).length;

  const imports = [];
  const requires = [];
  let m;
  const impRe = /import\s+(?:(?:\{[^}]*\}|\*\s+as\s+\w+|\w+)\s*,?\s*)*\s*from\s*['"]([^'"]+)['"]/g;
  while ((m = impRe.exec(code))) imports.push({ spec: m[1], line: lineOf(m.index) });
  const reqRe = /require\(\s*['"]([^'"]+)['"]\s*\)/g;
  while ((m = reqRe.exec(code))) requires.push({ spec: m[1], line: lineOf(m.index) });

  const exports = [];
  const expRe = /export\s+(default\s+)?(function|class|const|let|var)?\s*(\w+)?/g;
  while ((m = expRe.exec(code))) {
    exports.push({ default: !!m[1], kind: m[2] || 'default', name: m[3] || null, line: lineOf(m.index) });
  }
  const moduleExports = /module\.exports\s*=/g;
  while ((m = moduleExports.exec(code))) exports.push({ default: true, kind: 'module.exports', name: null, line: lineOf(m.index) });

  const functions = [];
  const fnRe = /(?:^|\s)(?:async\s+)?function\s*\*?\s*(\w+)\s*\(([^)]*)\)/gm;
  while ((m = fnRe.exec(code))) {
    functions.push({ name: m[1], params: splitParams(m[2]), async: /async\s+function/.test(m[0]), line: lineOf(m.index) });
  }
  const arrowRe = /(?:const|let|var)\s+(\w+)\s*=\s*(async\s*)?\(([^)]*)\)\s*=>/g;
  while ((m = arrowRe.exec(code))) {
    functions.push({ name: m[1], params: splitParams(m[3]), async: !!m[2], arrow: true, line: lineOf(m.index) });
  }

  const classes = [];
  const clsRe = /class\s+(\w+)(?:\s+extends\s+(\w+))?/g;
  while ((m = clsRe.exec(code))) {
    classes.push({ name: m[1], extends: m[2] || null, line: lineOf(m.index) });
  }

  const consts = [];
  const varRe = /(?:const|let|var)\s+(\w+)\s*=/g;
  while ((m = varRe.exec(code))) consts.push({ name: m[1], line: lineOf(m.index) });

  const complexity = cyclomatic(code);
  return { file, parser: 'regex', lines: lines.length, imports, requires, exports,
           functions, classes, variables: consts, complexity };
}

function splitParams(s) {
  return s.trim() ? s.split(',').map(x => x.trim()).filter(Boolean) : [];
}

function cyclomatic(code) {
  // strip strings/comments roughly
  const stripped = code.replace(/\/\/.*$/gm, '').replace(/\/\*[\s\S]*?\*\//g, '').replace(/'[^']*'/g, '').replace(/"[^"]*"/g, '').replace(/`[^`]*`/g, '');
  const tokens = stripped.match(/\b(if|for|while|case|catch)\b|&&|\|\||\?/g) || [];
  return tokens.length + 1;
}

// ---------- AST analysis ----------
function astAnalyze(code, file) {
  let ast;
  try {
    ast = acorn.parse(code, { ecmaVersion: 'latest', sourceType: 'module', locations: true, allowHashBang: true });
  } catch (e) {
    // try script mode
    try { ast = acorn.parse(code, { ecmaVersion: 'latest', sourceType: 'script', locations: true, allowHashBang: true }); }
    catch (e2) { return null; }
  }

  const imports = [], exports = [], functions = [], classes = [], variables = [];
  let requires = [];

  function walk(node, parent) {
    if (!node || typeof node !== 'object') return;
    // imports
    if (node.type === 'ImportDeclaration') {
      imports.push({ spec: node.source.value, kind: node.importKind || 'value', line: node.loc.start.line, names: node.specifiers.map(s => s.local?.name || '*') });
    }
    if (node.type === 'ExportNamedDeclaration') {
      if (node.declaration) {
        const d = node.declaration;
        if (d.type === 'FunctionDeclaration') functions.push({ name: d.id?.name, params: d.params.map(p => p.name || '...'), async: d.async, exported: true, line: d.loc.start.line });
        if (d.type === 'ClassDeclaration') classes.push({ name: d.id?.name, exported: true, line: d.loc.start.line });
        if (d.type === 'VariableDeclaration') d.declarations.forEach(v => variables.push({ name: v.id?.name, exported: true, line: v.loc.start.line }));
      }
      if (node.specifiers) node.specifiers.forEach(s => exports.push({ name: s.exported.name, line: node.loc.start.line }));
    }
    if (node.type === 'ExportDefaultDeclaration') {
      exports.push({ name: 'default', kind: node.declaration?.type, line: node.loc.start.line });
      const d = node.declaration;
      if (d?.type === 'FunctionDeclaration') functions.push({ name: d.id?.name || 'default', params: d.params.map(p=>p.name||'...'), async: d.async, exported: true, default: true, line: d.loc.start.line });
      if (d?.type === 'ClassDeclaration') classes.push({ name: d.id?.name || 'default', exported: true, default: true, line: d.loc.start.line });
    }
    // functions
    if (node.type === 'FunctionDeclaration' && !parentExported(node, parent)) {
      functions.push({ name: node.id?.name, params: node.params.map(p => p.name || '...'), async: node.async, generator: node.generator, line: node.loc.start.line });
    }
    if (node.type === 'FunctionExpression' && node.id) {
      functions.push({ name: node.id.name, params: node.params.map(p=>p.name||'...'), expr: true, line: node.loc.start.line });
    }
    if (node.type === 'ArrowFunctionExpression') {
      // only record if assigned to a variable (handled via VariableDeclarator)
    }
    if (node.type === 'VariableDeclarator' && node.init && (node.init.type === 'ArrowFunctionExpression' || node.init.type === 'FunctionExpression')) {
      const fn = node.init;
      functions.push({ name: node.id?.name, params: node.id?.type === 'ObjectPattern' ? ['...'] : (fn.params.map(p=>p.name||'...')), async: fn.async, arrow: fn.type === 'ArrowFunctionExpression', line: node.loc.start.line });
    }
    if (node.type === 'ClassDeclaration') {
      const methods = (node.body?.body || []).filter(m => m.type === 'MethodDefinition').map(m => m.key?.name || m.kind);
      classes.push({ name: node.id?.name, extends: node.superClass?.name || null, methods, line: node.loc.start.line });
    }
    if (node.type === 'VariableDeclaration') {
      node.declarations.forEach(v => {
        if (!(v.init && (v.init.type === 'ArrowFunctionExpression' || v.init.type === 'FunctionExpression'))) {
          variables.push({ name: v.id?.name, kind: node.kind, line: v.loc.start.line });
        }
      });
    }
    // requires
    if (node.type === 'CallExpression' && node.callee?.name === 'require' && node.arguments[0]?.type === 'Literal') {
      requires.push({ spec: node.arguments[0].value, line: node.loc.start.line });
    }
    for (const k in node) {
      const v = node[k];
      if (Array.isArray(v)) v.forEach(n => walk(n, node));
      else if (v && v.type) walk(v, node);
    }
  }
  walk(ast, null);

  // module.exports assignment
  const modExpRe = /module\.exports\s*=/g;
  let mm;
  while ((mm = modExpRe.exec(code))) exports.push({ name: 'module.exports', default: true, line: code.slice(0, mm.index).split(/\n/).length });

  return { file, parser: 'acorn', lines: code.split(/\r?\n/).length, imports, requires, exports, functions, classes, variables, complexity: cyclomatic(code) };
}

function parentExported(node, parent) {
  return false; // simplified
}

// ---------- analyze file ----------
function analyze(file) {
  const code = safeRead(file);
  if (code == null) return { file, error: 'unreadable' };
  if (acorn) {
    const r = astAnalyze(code, file);
    if (r) return r;
  }
  return regexAnalyze(code, file);
}

// ---------- runtime inspect (optional) ----------
function inspectModule(file) {
  const abs = path.resolve(file);
  try {
    // Clear cache
    delete require.cache[abs];
    const m = require(abs);
    const keys = (m && typeof m === 'object') ? Object.keys(m) : [];
    return { ok: true, exports: keys, type: typeof m, default: m && m.default ? Object.keys(m.default) : null };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

// ---------- main ----------
function main() {
  const files = walk(opts.dir);
  const reports = files.map(analyze);

  // sort by lines desc
  reports.sort((a, b) => (b.lines || 0) - (a.lines || 0));

  if (opts.json) {
    const payload = { root: path.resolve(opts.dir), fileCount: reports.length, files: reports };
    if (opts.inspect) payload.inspect = reports.slice(0, opts.top).map(r => ({ file: r.file, ...inspectModule(r.file) }));
    console.log(JSON.stringify(payload, null, 2));
    return;
  }

  console.log(`# Code reading report: ${path.resolve(opts.dir)}`);
  console.log(`Files: ${reports.length}\n`);

  // Project-level dependencies
  const depMap = new Map();
  for (const r of reports) {
    for (const im of (r.imports || [])) depMap.set(im.spec, (depMap.get(im.spec) || 0) + 1);
    for (const rq of (r.requires || [])) depMap.set(rq.spec, (depMap.get(rq.spec) || 0) + 1);
  }
  console.log('## Top dependencies');
  [...depMap.entries()].sort((a,b)=>b[1]-a[1]).slice(0, opts.top).forEach(([s,n]) => console.log(`  ${n}x  ${s}`));
  console.log('');

  console.log('## Largest files');
  reports.slice(0, opts.top).forEach(r => {
    console.log(`  ${r.lines || 0} lines  ${path.relative(opts.dir, r.file)}  [${r.parser}]${r.error ? '  ERR' : ''}`);
  });
  console.log('');

  for (const r of reports.slice(0, opts.top)) {
    console.log('---');
    console.log(`### ${path.relative(opts.dir, r.file)}  (${r.lines} lines, complexity~${r.complexity})`);
    if (r.error) { console.log(`  ERROR: ${r.error}`); continue; }
    if (r.imports?.length) console.log('  imports:', r.imports.map(x=>x.spec).join(', '));
    if (r.requires?.length) console.log('  requires:', [...new Set(r.requires.map(x=>x.spec))].join(', '));
    if (r.exports?.length) console.log('  exports:', r.exports.map(x=>x.name||x.kind).filter(Boolean).join(', '));
    if (r.classes?.length) console.log('  classes:', r.classes.map(c => `${c.name}${c.extends?' extends '+c.extends:''}${c.methods? ' { '+c.methods.join(', ')+' }':''}`).join('; '));
    if (r.functions?.length) console.log('  functions:', r.functions.map(f => `${f.name||'(anon)'}(${(f.params||[]).join(',')})${f.async?' async':''}${f.arrow?' =>':''}`).join(', '));
    if (r.variables?.length) {
      const names = r.variables.map(v=>v.name).filter(Boolean).slice(0, 15);
      if (names.length) console.log('  vars:', names.join(', '), r.variables.length > 15 ? `...(+${r.variables.length-15})` : '');
    }
    if (opts.inspect) {
      const ins = inspectModule(r.file);
      console.log('  runtime:', ins.ok ? `exports=[${ins.exports.join(', ')}]` : `inspect failed: ${ins.error}`);
    }
  }

  if (reports.length > opts.top) console.log(`\n... and ${reports.length - opts.top} more files (use --top=N)`);
}

main();
```

