## A reusable "refactoring helper" core (clean JavaScript)

Below is a tiny, dependency-free utility that supports the *mechanics* of refactoring in JS codebases: **finding duplicate code blocks** (a common smell driver) and **suggesting extract-function candidates** via simple AST-free heuristics. It's intentionally small and well-commented.

```js
// refactor-core.js
// NOTE: This is a heuristic aid, not a replacement for human judgment or a real AST tool.

/**
 * Normalize a code snippet to make comparison resilient to whitespace/comments.
 * @param {string} src
 * @returns {string}
 */
function normalize(src) {
  return src
    .replace(/\/\/.*$/gm, '')          // strip line comments
    .replace(/\/\*[\s\S]*?\*\//g, '') // strip block comments
    .replace(/\s+/g, ' ')             // collapse whitespace
    .trim()
    .toLowerCase();
}

/**
 * Split source into "chunks" (here: lines) and find duplicate blocks of size `window`.
 * Returns groups of identical normalized windows — candidates for Extract Function.
 *
 * @param {string} src
 * @param {number} [window=3]
 * @returns {Array<{text:string, lines:number[]}>}
 */
function findDuplicateBlocks(src, window = 3) {
  const lines = src.split(/\r?\n/);
  const buckets = new Map();

  for (let i = 0; i + window <= lines.length; i++) {
    const slice = lines.slice(i, i + window);
    const key = normalize(slice.join('\n'));
    if (!key) continue;
    if (!buckets.has(key)) buckets.set(key, { text: slice.join('\n').trim(), lines: [] });
    buckets.get(key).lines.push(i + 1); // 1-based line numbers
  }

  // Keep only groups that appear more than once and are non-trivial.
  return [...buckets.values()].filter((g) => g.lines.length > 1 && g.text.length > 20);
}

/**
 * Score a function for "long method" smell.
 * Returns a report with cyclomatic-ish complexity and line count.
 *
 * @param {Function} fn
 * @returns {{name:string, lines:number, complexity:number, smells:string[]}}
 */
function analyzeFunction(fn) {
  const src = fn.toString();
  const lines = src.split(/\r?\n/).length;
  const branches = (src.match(/\b(if|for|while|case|catch|\?\?|\|\||&&)\b/g) || []).length;
  const complexity = 1 + branches; // McCabe (approx)
  const smells = [];
  if (lines > 20) smells.push('long-method');
  if (complexity > 10) smells.push('high-complexity');
  if ((src.match(/\b\d{2,}\b/g) || []).length > 0) smells.push('magic-number');
  if (src.includes('TODO') || src.includes('FIXME')) smells.push('marker-comment');

  return { name: fn.name || '<anonymous>', lines, complexity, smells };
}

/**
 * Demonstration: refactor a "processOrder"-like function by extracting
 * a pricing step. applyRefactor takes the original and a map of
 * { oldSnippet -> newSnippet } replacements (must be exact matches).
 *
 * @param {string} src
 * @param {Record<string,string>} replacements
 * @returns {string}
 */
function applyReplacements(src, replacements) {
  let out = src;
  for (const [from, to] of Object.entries(replacements)) {
    if (!out.includes(from)) {
      throw new Error(`Snippet not found (refactor aborted): ${from.slice(0, 40)}...`);
    }
    out = out.replace(from, to);
  }
  return out;
}

module.exports = { normalize, findDuplicateBlocks, analyzeFunction, applyReplacements };

/* --------------------------- usage example --------------------------- */
if (require.main === module) {
  const sample = `
    function a(x){ if (x>10) return x*0.9; return x; }
    function b(y){ if (y>10) return y*0.9; return y; }
  `;
  console.log('Duplicate blocks:', findDuplicateBlocks(sample, 2));
  console.log('Analysis:', analyzeFunction(function demo() {
    // TODO
    let t = 0;
    for (let i = 0; i < 5; i++) if (i > 2) t += i * 42;
    return t;
  }));
}
```

### How I'd run this in an interview whiteboard/test
```js
const { analyzeFunction } = require('./refactor-core');
const report = analyzeFunction(processOrder);
// report.smells -> ['long-method', 'high-complexity', 'magic-number']
```

### Summary talking points
- Refactoring = **behavior-preserving structural change**, driven by smells, done in small steps, protected by tests.
- The mental model: identify smell → pick transformation → apply mechanically → run tests → commit.
- In JS specifically, watch for: callback hell (extract/async-await), mutation of shared state (immutability), magic numbers, stringly-typed branching, and "god" modules.
- Tools that automate it: ESLint rules, Prettier, jscodeshift (codemods), and AST-based tools (Babel, ts-morph) for large-scale refactors.

