  console.log('A.symmetricDifference(B):', [...A.symmetricDifference(B)]);
  console.log('A.isSubsetOf(B):', A.isSubsetOf(B));
  console.log('A.isSupersetOf(B):', A.isSupersetOf(B));
  console.log('A.isDisjointFrom(B):', A.isDisjointFrom(B));
}

/* ============================================================
   4. From-scratch implementation: ArraySet (O(n), educational)
      Mirrors the Set contract, including SameValueZero & iterator protocol.
   ============================================================ */
class ArraySet {
  #items = [];

  constructor(iterable = []) {
    for (const v of iterable) this.add(v);
  }

  get size() { return this.#items.length; }

  #indexOf(value) {
    return this.#items.findIndex(v => sameValueZero(v, value));
  }

  has(value) { return this.#indexOf(value) !== -1; }

  add(value) {
    if (!this.has(value)) this.#items.push(value);
    return this;                       // chaining
  }

  delete(value) {
    const i = this.#indexOf(value);
    if (i === -1) return false;
    this.#items.splice(i, 1);
    return true;
  }

  clear() { this.#items = []; }

  *values() { yield* this.#items; }
  *keys()   { yield* this.#items; }   // Set keys === values
  *entries(){ for (const v of this.#items) yield [v, v]; }

  [Symbol.iterator]() { return this.values(); }

  forEach(callback, thisArg) {
    for (const v of this) callback.call(thisArg, v, v, this);
  }

  // Set algebra helpers
  union(other) { return new ArraySet([...this, ...new ArraySet(other)]); }
  intersection(other) {
    const O = new ArraySet(other);
    const out = new ArraySet();
    for (const v of this) if (O.has(v)) out.add(v);
    return out;
  }
  difference(other) {
    const O = new ArraySet(other);
    const out = new ArraySet();
    for (const v of this) if (!O.has(v)) out.add(v);
    return out;
  }

  toString() {
    return `ArraySet(${this.size}) { ${[...this].map(String).join(', ')} }`;
  }
}

function demoArraySet() {
