  console.log('after add:', [...s]);
  console.log('has(3):', s.has(3), 'has(99):', s.has(99));
  console.log('delete(2):', s.delete(2), 'delete(2):', s.delete(2));
  console.log('NaN handling:', new ArraySet([NaN, NaN]).size); // 1
  console.log('0/-0 handling:', new ArraySet([0, -0]).size);  // 1
  console.log('forEach:');
