## Typical use cases

### 1. Remove duplicates from an array

```js
const nums = [1, 2, 2, 3, 3, 3];
const unique = [...new Set(nums)]; // [1, 2, 3]
```

For objects/strings with composite keys, map to a key first:

```js
const users = [{ id: 1 }, { id: 2 }, { id: 1 }];
const uniqueById = [...new Map(users.map(u => [u.id, u])).values()];
```

### 2. Fast membership lookup

```js
const allowed = new Set(["admin", "editor", "viewer"]);

function canAccess(role) {
  return allowed.has(role); // O(1)
}
```

### 3. Tracking visited items (graphs, DFS/BFS)

```js
function hasCycle(adj, start) {
  const visited = new Set();
  const stack = [start];

  while (stack.length) {
    const node = stack.pop();
    if (visited.has(node)) return true;
    visited.add(node);
    for (const next of adj[node] ?? []) stack.push(next);
  }
  return false;
}
```

### 4. Deduplicating work / caching keys

```js
const processed = new Set();

function process(id) {
  if (processed.has(id)) return;
  processed.add(id);
  // ... expensive work
}
```

### 5. Set operations (union, intersection, difference)

Modern engines (ES2025) provide built-in methods:

```js
const a = new Set([1, 2, 3]);
const b = new Set([2, 3, 4]);

a.union(b);               // Set {1, 2, 3, 4}
a.intersection(b);        // Set {2, 3}
a.difference(b);          // Set {1}
a.symmetricDifference(b); // Set {1, 4}

a.isSubsetOf(b);   // false
a.isSupersetOf(b); // false
a.isDisjointFrom(b); // false
```

If you need to support older environments, implement manually:

```js
function union(a, b) {
  return new Set([...a, ...b]);
}
function intersection(a, b) {
  const out = new Set();
  for (const x of a) if (b.has(x)) out.add(x);
  return out;
}
function difference(a, b) {
  const out = new Set(a);
  for (const x of b) out.delete(x);
  return out;
}
```

### 6. Counting distinct values

```js
const words = ["apple", "banana", "apple", "cherry"];
const distinct = new Set(words).size; // 3
```

### 7. WeakSet (brief)

`WeakSet` holds objects weakly—entries are garbage-collected when no other references exist, and it’s **not iterable**. Useful for tagging objects without preventing GC:

```js
const seen = new WeakSet();
function mark(obj) {
  if (seen.has(obj)) return "already seen";
  seen.add(obj);
  return "new";
}
```

