## Signals and timers in JavaScript

### Timers
Timers (`setTimeout`, `setInterval`, `queueMicrotask`, `requestAnimationFrame`) are **not precise clocks**. They are requests to run a callback later through the event loop. Key points:

- `setTimeout(fn, delay)` means “run after at least `delay` ms,” not “exactly after.”
- The event loop waits until the call stack is clear before picking up macrotasks.
- Nested timers may be clamped (browsers often clamp to 4 ms).
- `setInterval` can drift or overlap if the callback takes longer than the interval.
- `clearTimeout` / `clearInterval` cancel by id.

### Signals
“Signal” can mean several things in JS:

1. **Cancellation signals (`AbortSignal`)**  
   Used to cancel fetches, streams, async operations. A signal has `aborted`, `reason`, and `abort` listeners.
2. **Process signals (Node.js)**  
   `SIGINT`, `SIGTERM`, etc. indicate lifecycle events from the OS.
3. **Reactive signals (Solid/Svelte-style)**  
   State containers that notify subscribers when value changes.

Below, I implement the **core of a timer scheduler** and an **AbortSignal-style cancellation signal**. The same subscriber idea also works for reactive signals.

---

## Core implementation

```js
/**
 * Minimal binary heap used by the timer scheduler.
 * We store timer objects and order them by `due` time.
 */
class MinHeap {
  constructor(compare) {
    this.items = [];
    this.compare = compare;
  }

  push(value) {
    this.items.push(value);
    this._bubbleUp(this.items.length - 1);
  }

  pop() {
    if (this.items.length === 0) return undefined;
    const top = this.items[0];
    const last = this.items.pop();
    if (this.items.length > 0) {
      this.items[0] = last;
      this._sinkDown(0);
    }
    return top;
  }

  peek() {
    return this.items[0];
  }

  get size() {
    return this.items.length;
  }

  _bubbleUp(index) {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (this.compare(this.items[index], this.items[parent]) < 0) {
        [this.items[index], this.items[parent]] =
          [this.items[parent], this.items[index]];
        index = parent;
      } else {
        break;
      }
    }
  }

  _sinkDown(index) {
    const n = this.items.length;
    while (true) {
      const left = 2 * index + 1;
      const right = 2 * index + 2;
      let smallest = index;

      if (left < n && this.compare(this.items[left], this.items[smallest]) < 0) {
        smallest = left;
      }
      if (right < n && this.compare(this.items[right], this.items[smallest]) < 0) {
        smallest = right;
      }
      if (smallest === index) break;

      [this.items[index], this.items[smallest]] =
        [this.items[smallest], this.items[index]];
      index = smallest;
    }
  }
}

/**
 * A small timer scheduler core.
 *
 * It does not use the real event loop; instead, call `tick(now)` to run
 * due timers. This makes the core deterministic and easy to test.
 */
class TimerScheduler {
  constructor(nowFn = () => performance.now()) {
    this.nowFn = nowFn;
    this.heap = new MinHeap((a, b) => a.due - b.due);
    this.nextId = 1;
    this.cancelled = new Set();
  }

  /**
   * Schedule a one-shot timer.
   * Returns an id that can be passed to clearTimeout.
   */
  setTimeout(callback, delay = 0, ...args) {
    const id = this.nextId++;
    const due = this.nowFn() + Math.max(0, delay);
    this.heap.push({ id, callback, args, due, interval: 0 });
    return id;
  }

  /**
   * Schedule a repeating timer.
   */
  setInterval(callback, delay = 0, ...args) {
    const id = this.nextId++;
    const due = this.nowFn() + Math.max(0, delay);
    this.heap.push({ id, callback, args, due, interval: Math.max(0, delay) });
    return id;
  }

  clearTimeout(id) {
    this.cancelled.add(id);
  }

  clearInterval(id) {
    this.cancelled.add(id);
  }

  /**
   * Run all timers whose `due` time is <= `now`.
   * Repeating timers are rescheduled.
   */
  tick(now = this.nowFn()) {
    // Process every currently due timer. New timers scheduled during
    // a callback are handled on the next tick, matching macrotask semantics.
    while (this.heap.size > 0 && this.heap.peek().due <= now) {
      const timer = this.heap.pop();

      // Skip cancelled timers.
      if (this.cancelled.has(timer.id)) {
        this.cancelled.delete(timer.id);
        continue;
      }

      try {
        timer.callback(...timer.args);
      } catch (error) {
        // In a real runtime, uncaught timer errors may terminate the process
        // or be reported to the global error handler.
        console.error("Timer callback threw:", error);
      }

      // Reschedule intervals. Use `now + interval` to avoid drift accumulation
      // in this simple model; production runtimes often use more nuanced rules.
      if (timer.interval > 0 && !this.cancelled.has(timer.id)) {
        timer.due = now + timer.interval;
        this.heap.push(timer);
      }
    }
  }
}

/**
 * Minimal AbortSignal core.
 *
 * This mirrors the essential behavior:
 * - `aborted` becomes true once.
 * - `reason` explains why.
 * - listeners are notified.
 * - `throwIfAborted()` supports cooperative cancellation.
 */
class AbortSignal {
  constructor() {
    this.aborted = false;
    this.reason = undefined;
    this.listeners = new Set();
  }

  addEventListener(type, listener) {
    if (type !== "abort" || typeof listener !== "function") return;
    this.listeners.add(listener);
  }

  removeEventListener(type, listener) {
    if (type !== "abort") return;
    this.listeners.delete(listener);
  }

  throwIfAborted() {
    if (this.aborted) throw this.reason;
  }

  // Internal method used by AbortController.
  _abort(reason) {
    if (this.aborted) return; // Abort is final and idempotent enough.
    this.aborted = true;
    this.reason = reason;

    // Notify listeners. Copy to avoid mutation during iteration.
    for (const listener of [...this.listeners]) {
      try {
        listener({ type: "abort", target: this });
      } catch (error) {
        console.error("Abort listener threw:", error);
      }
    }
  }
}

class AbortController {
  constructor() {
    this.signal = new AbortSignal();
  }

  abort(reason = new Error("Aborted")) {
    this.signal._abort(reason);
  }
}

/**
 * Example: combine timers and signals.
 * Abort a simulated async operation after a timeout.
 */
function runWithTimeout(scheduler, work, timeoutMs) {
  const controller = new AbortController();
  const { signal } = controller;

  // Schedule cancellation.
  const timerId = scheduler.setTimeout(() => {
    controller.abort(new Error(`Timed out after ${timeoutMs}ms`));
  }, timeoutMs);

  try {
    // Cooperative async work checks the signal.
    signal.throwIfAborted();
    work(signal);
    signal.throwIfAborted();
    console.log("Work completed before timeout.");
  } catch (error) {
    console.log("Work did not complete:", error.message);
  } finally {
    scheduler.clearTimeout(timerId);
  }
}

