// socket-demo.js
const net = require('net');
const readline = require('readline');

const HOST = '127.0.0.1';
const PORT = 8124;

// ---------- Server ----------
const server = net.createServer((socket) => {
  console.log(`[server] client connected: ${socket.remoteAddress}:${socket.remotePort}`);

  socket.setEncoding('utf8');
  socket.setTimeout(10000, () => {
    console.log('[server] socket timed out');
    socket.end();
  });

  // Treat the byte stream as lines.
  const rl = readline.createInterface({
    input: socket,
    crlfDelay: Infinity,
  });

  rl.on('line', (line) => {
    console.log(`[server] received: ${line}`);
    socket.write(`echo: ${line}\n`);
  });

  socket.on('end', () => {
    console.log('[server] client sent FIN (half-close)');
  });

  socket.on('close', (hadError) => {
    console.log(`[server] socket closed (error=${hadError})`);
    // Stop accepting new connections after the demo client disconnects.
    server.close(() => console.log('[server] server closed'));
  });

  socket.on('error', (err) => {
    console.error('[server] socket error:', err.message);
  });
});

server.on('error', (err) => {
  console.error('[server] server error:', err.message);
  process.exit(1);
});

server.listen(PORT, HOST, () => {
  console.log(`[server] listening on ${HOST}:${PORT}`);

  // ---------- Client ----------
  const client = net.createConnection({ host: HOST, port: PORT }, () => {
    console.log('[client] connected to server');

    // Send two separate messages. TCP may coalesce them on the wire,
    // but readline on the server still emits two "line" events.
    client.write('Hello, socket!\n');
    client.write('Second message\n');
  });

  client.setEncoding('utf8');

  const clientRl = readline.createInterface({
    input: client,
    crlfDelay: Infinity,
  });

  let receivedCount = 0;

  clientRl.on('line', (line) => {
    console.log(`[client] received: ${line}`);
    receivedCount++;

    // After receiving both echoes, gracefully close.
    if (receivedCount === 2) {
      client.end(() => console.log('[client] end() finished'));
    }
  });

  client.on('end', () => {
    console.log('[client] server closed connection');
  });

  client.on('close', (hadError) => {
    console.log(`[client] socket closed (error=${hadError})`);
  });

  client.on('error', (err) => {
    console.error('[client] client error:', err.message);
  });

  client.setTimeout(10000, () => {
    console.error('[client] timed out');
    client.destroy();
  });
});
```

### Expected output

```text
[server] listening on 127.0.0.1:8124
[client] connected to server
[server] client connected: 127.0.0.1:...
[server] received: Hello, socket!
[client] received: echo: Hello, socket!
[server] received: Second message
[client] received: echo: Second message
[client] end() finished
[client] server closed connection
[client] socket closed (error=false)
[server] client sent FIN (half-close)
[server] socket closed (error=false)
[server] server closed
```

Exact interleaving of log lines may vary because server and client run in the same event loop.

---

## What this example demonstrates

### 1. TCP sockets are streams, not messages
`net.Socket` is a duplex stream. Writing twice does not guarantee two separate TCP packets; the kernel may merge them. That is why the example uses **newline-delimited messages** and `readline` instead of assuming one `data` event equals one message.

### 2. Graceful close vs. abrupt close
- `socket.end()` sends a FIN and waits for queued writes to flush.
- `socket.destroy()` forcibly closes the socket.
- `end` event means the remote side sent FIN.
- `close` event means the socket is fully closed.

### 3. Backpressure
For large transfers, always check the return value of `socket.write()`:

```js
const ok = socket.write(chunk);
if (!ok) {
  socket.once('drain', () => {
    // Safe to write more now.
  });
}
```

Ignoring backpressure can cause unbounded memory growth.

### 4. Timeouts
`socket.setTimeout(ms, callback)` is an **inactivity** timeout, not a connection timeout. It fires when no data has been sent or received for the given duration.

### 5. Error handling
Always attach `error` listeners to both server and sockets. Unhandled socket errors can crash the process.

