## UDP example (datagram sockets)

UDP is connectionless and message-oriented. Use `dgram`:

```js
const dgram = require('dgram');

const server = dgram.createSocket('udp4');
server.on('message', (msg, rinfo) => {
  console.log(`UDP received "${msg}" from ${rinfo.address}:${rinfo.port}`);
  server.send(`ack: ${msg}`, rinfo.port, rinfo.address);
});
server.bind(9000, () => console.log('UDP server on 9000'));

const client = dgram.createSocket('udp4');
client.send('ping', 9000, '127.0.0.1', (err) => {
  if (err) console.error(err);
});
client.on('message', (msg) => {
  console.log('UDP client received:', msg.toString());
  client.close();
});
```

Run the server and client in separate terminals, or guard startup with `process.argv`.

---

## TLS / encrypted sockets

For production, wrap TCP in TLS using the `tls` module:

```js
const tls = require('tls');
const fs = require('fs');

const options = {
  key: fs.readFileSync('server.key'),
  cert: fs.readFileSync('server.crt'),
};

const server = tls.createServer(options, (socket) => {
  socket.write('secure hello\n');
  socket.pipe(socket); // echo
});

server.listen(8443, () => console.log('TLS server on 8443'));
```

Clients use `tls.connect({ port, host, rejectUnauthorized: true })`.

