## 3. UDP (`dgram`)

Connectionless, fast, no delivery guarantee — good for games, DNS, metrics.

```js
const dgram = require('dgram');
const sock = dgram.createSocket('udp4');

sock.on('message', (msg, rinfo) => {
  console.log(`from ${rinfo.address}:${rinfo.port}: ${msg}`);
  sock.send('ack', rinfo.port, rinfo.address);
});

sock.bind(41234, () => console.log('udp listening'));
```

---

## 4. WebSockets (browser + Node)

Browser API (same everywhere):
```js
const ws = new WebSocket('wss://example.com/socket');

ws.addEventListener('open', () => ws.send(JSON.stringify({ type: 'hello' })));
ws.addEventListener('message', (e) => {
  const msg = JSON.parse(e.data);
  console.log('server says', msg);
});
ws.addEventListener('close', (e) => console.log('closed', e.code, e.reason));
ws.addEventListener('error', (e) => console.error('ws error', e));
```

Node server with the `ws` library:
```js
const { WebSocketServer } = require('ws');
const wss = new WebSocketServer({ port: 8080 });

wss.on('connection', (ws, req) => {
  const ip = req.socket.remoteAddress;
  ws.send(JSON.stringify({ type: 'welcome', ip }));

  ws.on('message', (raw) => {
    const msg = JSON.parse(raw);
    // broadcast to everyone
    wss.clients.forEach((c) => {
      if (c.readyState === 1) c.send(JSON.stringify(msg));
    });
  });
});
```

**Important**: WebSockets start as an HTTP upgrade (`Upgrade: websocket`), then switch protocols. Use `wss://` (TLS) in production.

---

## 5. HTTP/HTTPS (still the workhorse)

Node server:
```js
const http = require('http');

http.createServer((req, res) => {
  if (req.url === '/api/ping') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ ok: true, t: Date.now() }));
  } else {
    res.writeHead(404).end();
  }
}).listen(3000);
```

Client (`fetch` in browser or Node 18+):
```js
const res = await fetch('https://api.example.com/data');
const data = await res.json();
```

