If you want a single file for quick copy-paste:

```js
// chat.js
const net = require('net');
const readline = require('readline');

const isServer = process.argv[2] === 'server';
const PORT = 4000;

if (isServer) {
  const clients = new Set();
  let next = 1;
  const srv = net.createServer((s) => {
    const id = `u${next++}`; s.id = id; clients.add(s);
    let buf = '';
    s.write(`you are ${id}\n`);
    const fanout = (from, text) => {
      const line = `[${from}] ${text}\n`;
      for (const c of clients) if (c !== from && !c.destroyed) c.write(line);
    };
    fanout(s, `${id} joined`);
    s.on('data', (d) => {
      buf += d;
      let i;
      while ((i = buf.indexOf('\n')) >= 0) {
        const m = buf.slice(0, i).trim();
        buf = buf.slice(i + 1);
        if (m) fanout(s, m);
      }
    });
    s.on('close', () => { clients.delete(s); fanout(s, `${id} left`); });
    s.on('error', (e) => console.error(id, e.message));
  });
  srv.listen(PORT, () => console.log('server on', PORT));
} else {
  const s = net.createConnection({ port: PORT }, () => console.log('connected'));
  let buf = '';
  s.on('data', (d) => {
    buf += d;
    let i;
    while ((i = buf.indexOf('\n')) >= 0) { process.stdout.write(buf.slice(0, i) + '\n'); buf = buf.slice(i + 1); }
  });
  const rl = readline.createInterface({ input: process.stdin });
  rl.on('line', (l) => { if (l === '/quit') { s.end(); rl.close(); } else s.write(l + '\n'); });
  s.on('close', () => process.exit(0));
}
```

