### Final takeaway

The “short exercise” is really about four habits: (1) treat TCP as a byte stream and frame with delimiters, (2) keep per-connection state in closures, (3) always handle `'error'`/`'close'`, and (4) broadcast by iterating a client set while guarding `destroyed`. Master those and you can build almost any custom TCP protocol in Node.js.

## Sockets & Networking in JavaScript (Interview-Style Answer)

### 1. Core concepts

- **Socket**: an endpoint for communication. In Node.js, `net.Socket` represents a TCP connection; `dgram` is UDP.
- **TCP vs UDP**: TCP is reliable, ordered, stream-based (no message boundaries). UDP is datagram-based, unreliable, lower latency.
- **Client/Server**: server `listen()`s on a port; client `connect()`s. After handshake, both sides read/write bytes.
- **Stream nature**: TCP delivers a *byte stream*. You must implement **framing** (e.g., newline-delimited JSON) to recover messages.
- **Events**: Node uses an event loop + non-blocking I/O. Sockets emit `data`, `end`, `close`, `error`, `drain`.
- **Backpressure**: `socket.write()` returns `false` when the kernel buffer is full; wait for `drain` before writing more.
- **Security**: use `tls` (or HTTPS/WSS) in production; never send secrets over plain TCP.

### 2. Implementation: minimal TCP server/client with NDJSON framing

Below is a clean, dependency-free Node.js implementation. It demonstrates:
- connection lifecycle
- message framing
- broadcast
- graceful shutdown
- basic client reconnect with exponential backoff

```js
// net-chat.js
const net = require('net');
const { EventEmitter } = require('events');

/* ------------------------------------------------------------------ */
/* Framing helper: newline-delimited JSON (NDJSON)                     */
/* ------------------------------------------------------------------ */
function parseFrames(buffer, onMessage, onError) {
  let idx;
  while ((idx = buffer.indexOf('\n')) !== -1) {
    const line = buffer.slice(0, idx).trim();
    buffer = buffer.slice(idx + 1);
    if (!line) continue;
    try {
      onMessage(JSON.parse(line));
    } catch (e) {
      onError(new Error(`Invalid JSON frame: ${line}`));
    }
  }
  return buffer; // leftover partial frame
}

/* ------------------------------------------------------------------ */
/* Server-side connection wrapper                                     */
/* ------------------------------------------------------------------ */
class Connection extends EventEmitter {
  constructor(socket) {
    super();
    this.socket = socket;
    this.buffer = '';
    socket.setEncoding('utf8');

    socket.on('data', (chunk) => {
      this.buffer = parseFrames(this.buffer + chunk, (msg) => this.emit('message', msg), (e) => this.emit('error', e));
    });
    socket.on('close', () => this.emit('close'));
    socket.on('error', (e) => this.emit('error', e));
    socket.on('drain', () => this.emit('drain'));
  }

  send(msg) {
    if (this.socket.destroyed) return false;
    // write returns false when backpressure builds up
    return this.socket.write(JSON.stringify(msg) + '\n');
  }

  close() {
    this.socket.end(); // FIN; allows pending writes to flush
  }

  destroy() {
    this.socket.destroy();
  }
}

/* ------------------------------------------------------------------ */
/* TCP Server                                                         */
/* ------------------------------------------------------------------ */
class TcpServer extends EventEmitter {
  constructor({ host = '0.0.0.0', port = 0 } = {}) {
    super();
    this.host = host;
    this.port = port;
    this.server = net.createServer((socket) => this._handleSocket(socket));
    this.clients = new Set();
  }

  _handleSocket(socket) {
    const conn = new Connection(socket);
    this.clients.add(conn);

    conn.on('message', (msg) => this.emit('message', conn, msg));
    conn.on('close', () => {
      this.clients.delete(conn);
      this.emit('disconnect', conn);
    });
    conn.on('error', (e) => this.emit('error', e, conn));

    this.emit('connection', conn);
  }

  start() {
    return new Promise((resolve, reject) => {
      this.server.listen(this.port, this.host, () => {
        const addr = this.server.address();
        this.port = addr.port;
        this.emit('listening', addr);
        resolve(addr);
      });
      this.server.on('error', reject);
    });
  }

  broadcast(msg) {
    for (const c of this.clients) c.send(msg);
  }

  stop() {
    return new Promise((resolve) => {
      for (const c of this.clients) c.destroy();
      this.server.close(() => resolve());
    });
  }
}

/* ------------------------------------------------------------------ */
/* TCP Client                                                         */
/* ------------------------------------------------------------------ */
class TcpClient extends EventEmitter {
  constructor({ host, port, reconnect = true, maxRetries = 5 }) {
    super();
    this.host = host;
    this.port = port;
    this.reconnect = reconnect;
    this.maxRetries = maxRetries;
    this.retries = 0;
    this.socket = null;
    this.buffer = '';
    this.closedManually = false;
  }

  connect() {
    this.closedManually = false;
    return this._connectOnce();
  }

  _connectOnce() {
    return new Promise((resolve, reject) => {
      const socket = net.createConnection({ host: this.host, port: this.port }, () => {
        this.retries = 0;
        this.emit('connect');
        resolve();
      });

      this.socket = socket;
      socket.setEncoding('utf8');

      socket.on('data', (chunk) => {
        this.buffer = parseFrames(this.buffer + chunk, (msg) => this.emit('message', msg), (e) => this.emit('error', e));
      });

      socket.on('close', () => {
        this.emit('close');
        if (!this.closedManually && this.reconnect && this.retries < this.maxRetries) {
          const delay = Math.min(1000 * 2 ** this.retries, 10000);
          this.retries++;
          this.emit('reconnecting', { attempt: this.retries, delay });
          setTimeout(() => this._connectOnce().catch(() => {}), delay);
        }
      });

      socket.on('error', (e) => {
        this.emit('error', e);
        reject(e);
      });
    });
  }

  send(msg) {
    if (!this.socket || this.socket.destroyed) return false;
    return this.socket.write(JSON.stringify(msg) + '\n');
  }

  close() {
    this.closedManually = true;
    if (this.socket) this.socket.end();
  }
}

module.exports = { TcpServer, TcpClient, Connection };

/* ------------------------------------------------------------------ */
/* Demo usage                                                         */
/* ------------------------------------------------------------------ */
if (require.main === module) {
  (async () => {
    const server = new TcpServer({ port: 9000 });
    await server.start();
    console.log('Server listening on', server.port);

    server.on('connection', (c) => console.log('Client connected'));
    server.on('message', (c, msg) => {
      console.log('Server got:', msg);
      c.send({ type: 'echo', payload: msg });
      server.broadcast({ type: 'notice', text: 'someone spoke' });
    });

    const client = new TcpClient({ host: '127.0.0.1', port: 9000 });
    await client.connect();
    client.on('message', (m) => console.log('Client got:', m));

    client.send({ type: 'hello', from: 'client-1' });

    setTimeout(async () => {
      await server.stop();
      client.close();
      console.log('Shutdown complete');
    }, 2000);
  })();
}
```

### 3. Browser side: WebSocket (conceptual + minimal)

Browsers cannot open raw TCP sockets for security reasons; they use **WebSocket** (HTTP upgrade to a framed, full-duplex protocol).

```js
// Browser client
const ws = new WebSocket('wss://example.com/chat');
ws.onopen    = () => ws.send(JSON.stringify({ type: 'join', room: 'lobby' }));
ws.onmessage = (e) => console.log('msg:', JSON.parse(e.data));
ws.onclose   = () => console.log('closed');
ws.onerror   = (e) => console.error('ws error', e);
```

Server side (Node, using the popular `ws` library):

```js
const WebSocket = require('ws');
const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', (ws) => {
  ws.on('message', (data) => {
    // broadcast to all clients
    wss.clients.forEach((c) => {
      if (c.readyState === WebSocket.OPEN) c.send(data);
    });
  });
});
```

### 4. Interview talking points / pitfalls

| Topic | What to say |
|---|---|
| **Message boundaries** | TCP is a stream; always frame (length-prefix or delimiter). |
| **Backpressure** | Check `write()` return value; pause reads if needed. |
| **Partial reads** | Buffer data until a full frame arrives (shown in `parseFrames`). |
| **Security** | Use TLS (`tls` module / `wss://`); validate & sanitize messages. |
| **Scaling** | Single Node process = single event loop; use cluster or multiple processes + Redis pub/sub for horizontal scale. |
| **Heartbeats** | Implement ping/pong to detect dead peers; TCP keepalive alone is slow. |
| **Graceful shutdown** | `server.close()` stops new connections; `socket.end()` flushes writes. |
| **UDP** | Use `dgram` for low-latency, loss-tolerant traffic (games, DNS). |

### 5. Complexity / mental model

- **Time**: O(n) per message where n = bytes received; framing scans for delimiter.
- **Space**: O(buffer size) for partial frames; bounded by max frame size in production.
- **Concurrency**: event-loop driven; thousands of sockets per process if I/O-bound.

If you want, I can extend this with a **length-prefixed binary protocol**, **TLS wrapper**, or a **minimal WebSocket handshake from scratch** (HTTP upgrade + RFC 6455 framing).

Below are the most common socket/networking edge cases in JavaScript (Node.js examples, with browser notes where relevant), plus idiomatic handling patterns.

---

## 1. TCP sockets (`net`) — connection & lifecycle

### Edge cases
- DNS failure / refused connection
- Connect timeout
- Idle timeout
- Abrupt close (`ECONNRESET`)
- Half-open / FIN handling
- `EADDRINUSE` on listen
- IPv4 vs IPv6

```js
const net = require('net');

function createClient(host, port) {
  const socket = net.createConnection({ host, port, family: 4 }, () => {
    console.log('connected');
  });

  // Connect + idle timeout
  socket.setTimeout(10_000, () => {
    socket.destroy(new Error('socket timeout'));
  });

  socket.on('error', (err) => {
    // ECONNREFUSED, ENOTFOUND, ECONNRESET, ETIMEDOUT, etc.
    console.error('socket error:', err.code, err.message);
  });

  socket.on('close', (hadError) => {
    console.log('closed, hadError=', hadError);
  });

  return socket;
}

// Server: handle EADDRINUSE
const server = net.createServer((sock) => { /* ... */ });
server.on('error', (err) => {
  if (err.code === 'EADDRINUSE') {
    console.error('port in use, retrying...');
    setTimeout(() => server.listen(port), 1000);
  } else throw err;
});
server.listen(8080);
```

**Notes**
- Always attach `'error'` before/with connection; unhandled socket errors crash Node.
- `socket.destroy(err)` is the safe way to force close; `end()` only half-closes.

---

## 2. Backpressure on writes

### Edge case
`socket.write()` returns `false` when the kernel buffer is full. Ignoring this can OOM or drop data.

```js
function writeAll(socket, chunks) {
  return new Promise((resolve, reject) => {
    let i = 0;
    function next() {
      while (i < chunks.length) {
        const ok = socket.write(chunks[i++]);
        if (!ok) {
          socket.once('drain', next);
          return;
        }
      }
      socket.end(() => resolve());
    }
    next();
    socket.on('error', reject);
  });
}
```

---

## 3. Framing / partial reads (TCP has no message boundaries)

### Edge case
Data arrives in arbitrary chunks; you must buffer and parse frames.

```js
function createFrameParser(onMessage) {
  let buf = Buffer.alloc(0);
  return (chunk) => {
    buf = Buffer.concat([buf, chunk]);
    while (buf.length >= 4) {
      const len = buf.readUInt32BE(0);
      if (buf.length < 4 + len) break;
      const msg = buf.subarray(4, 4 + len);
      buf = buf.subarray(4 + len);
      onMessage(msg);
    }
  };
}

const parser = createFrameParser((msg) => console.log('msg', msg.toString()));
socket.on('data', parser);
```

**Also handle**
- Max frame size to prevent memory exhaustion.
- Invalid length fields → destroy socket.

---

## 4. Reconnection with backoff

### Edge case
Network blips; naive immediate reconnect causes thundering herd.

```js
function connectWithRetry(makeSocket) {
  let delay = 1000;
  let stopped = false;

  function attempt() {
    if (stopped) return;
    const s = makeSocket();
    s.on('connect', () => { delay = 1000; });
    s.on('error', () => {}); // swallow; close will fire
    s.on('close', (hadError) => {
      if (stopped) return;
      console.log('reconnecting in', delay, 'ms');
      setTimeout(attempt, delay);
      delay = Math.min(delay * 2, 30_000);
    });
  }
  attempt();
  return () => { stopped = true; };
}
```

---

## 5. TLS / certificate validation

### Edge cases
- Self-signed certs in dev
- Hostname mismatch
- Expired certs
- MITM via proxy

```js
const tls = require('tls');

const socket = tls.connect({
  host: 'example.com',
  port: 443,
  servername: 'example.com', // SNI
  rejectUnauthorized: true,   // NEVER disable in prod
  // ca: fs.readFileSync('ca.pem') // custom CA
}, () => {
  if (socket.authorized) console.log('TLS OK');
  else console.error('TLS not authorized:', socket.authorizationError);
});

socket.on('error', (e) => console.error(e));
```

**Browser note:** `fetch`/`WebSocket` enforce TLS automatically; do not use `rejectUnauthorized: false` in production.

---

## 6. HTTP client (`fetch` / `http`)

### Edge cases
- Timeouts (no default in some clients)
- Unconsumed response bodies (connection stalls)
- Non-2xx status
- Redirect loops
- Keep-alive socket exhaustion
- Large responses / memory

```js
async function safeFetch(url, opts = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), opts.timeout ?? 10_000);
  try {
    const res = await fetch(url, { ...opts, signal: controller.signal });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    // consume body explicitly
    const text = await res.text();
    return text;
  } catch (e) {
    if (e.name === 'AbortError') throw new Error('request timeout');
    throw e;
  } finally {
    clearTimeout(timer);
  }
}
```

Node `http` with keep-alive agent:

```js
const http = require('http');
const agent = new http.Agent({ keepAlive: true, maxSockets: 50, maxFreeSockets: 10 });

http.get('http://example.com/', { agent }, (res) => {
  let data = '';
  res.setEncoding('utf8');
  res.on('data', (c) => { data += c; });
  res.on('end', () => console.log(data.length));
  res.on('error', (e) => console.error(e));
}).on('error', (e) => console.error(e));
```

---

## 7. WebSockets

### Edge cases
- Abnormal closure / network drop
- Heartbeat / dead peer detection
- Message fragmentation & backpressure
- Reconnect + message queue
- Close codes (1006 = abnormal)

```js
const WebSocket = require('ws');

class ReconnectingWS {
  constructor(url) {
    this.url = url;
    this.queue = [];
    this.connect();
  }

  connect() {
    this.ws = new WebSocket(this.url);
    this.alive = true;

    this.ws.on('open', () => {
      // flush queue
      while (this.queue.length && this.ws.readyState === WebSocket.OPEN) {
        this.ws.send(this.queue.shift());
      }
    });

    this.ws.on('pong', () => { this.alive = true; });

    this.ws.on('message', (data) => {
      // handle
    });

    this.ws.on('close', (code, reason) => {
      console.log('ws closed', code, reason.toString());
      setTimeout(() => this.connect(), 2000);
    });

    this.ws.on('error', (e) => console.error('ws error', e.message));

    // heartbeat
    this.hb = setInterval(() => {
      if (!this.alive) { this.ws.terminate(); return; }
      this.alive = false;
      if (this.ws.readyState === WebSocket.OPEN) this.ws.ping();
    }, 30_000);
  }

  send(data) {
    if (this.ws.readyState === WebSocket.OPEN && this.ws.bufferedAmount === 0) {
      this.ws.send(data, (err) => {
        if (err) this.queue.unshift(data);
      });
    } else {
      this.queue.push(data);
    }
  }
}
```

**Browser note:** use `new WebSocket(url)`; implement reconnect in `onclose`; `ping` not available client-side, rely on server pings or application heartbeat.

