# Sorting Algorithms in JavaScript

Below is a complete, runnable module implementing the most important sorting algorithms. It supports a **custom comparator** (so it works on numbers, strings, or objects), returns a **new sorted array** by default (immutable), and also provides in-place variants where it makes sense.

```js
// sorting-algorithms.js
// Run with: node sorting-algorithms.js

// --------------------------------------------------------------------------- 
// Helpers
// --------------------------------------------------------------------------- 

/** Default comparator: works for numbers and strings. */
function defaultCompare(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

/** Swap two elements in an array (by index). */
function swap(arr, i, j) {
  if (i === j) return;
  const tmp = arr[i];
  arr[i] = arr[j];
  arr[j] = tmp;
}

/** Utility to clone so originals are never mutated by the "sorted copy" API. */
function clone(arr) {
  return arr.slice();
}

// --------------------------------------------------------------------------- 
// 1. Bubble Sort — O(n²) time, O(1) space. Stable. Best for tiny/nearly sorted.
// --------------------------------------------------------------------------- 
function bubbleSort(arr, compare = defaultCompare) {
  const a = clone(arr);
  const n = a.length;
  for (let i = 0; i < n - 1; i++) {
    let swapped = false;
    // Last i elements are already in place.
    for (let j = 0; j < n - 1 - i; j++) {
      if (compare(a[j], a[j + 1]) > 0) {
        swap(a, j, j + 1);
        swapped = true;
      }
    }
    if (!swapped) break; // already sorted → early exit
  }
  return a;
}

// --------------------------------------------------------------------------- 
// 2. Selection Sort — O(n²) time, O(1) space. NOT stable (in this form).
// --------------------------------------------------------------------------- 
function selectionSort(arr, compare = defaultCompare) {
  const a = clone(arr);
  const n = a.length;
  for (let i = 0; i < n - 1; i++) {
    let minIdx = i;
    for (let j = i + 1; j < n; j++) {
      if (compare(a[j], a[minIdx]) < 0) minIdx = j;
    }
    if (minIdx !== i) swap(a, i, minIdx);
  }
  return a;
}

// --------------------------------------------------------------------------- 
// 3. Insertion Sort — O(n²) worst, O(n) best. Stable. Great for small arrays.
// --------------------------------------------------------------------------- 
function insertionSort(arr, compare = defaultCompare) {
  const a = clone(arr);
  for (let i = 1; i < a.length; i++) {
    const key = a[i];
    let j = i - 1;
    while (j >= 0 && compare(a[j], key) > 0) {
      a[j + 1] = a[j];
      j--;
    }
    a[j + 1] = key;
  }
  return a;
}

// --------------------------------------------------------------------------- 
// 4. Merge Sort — O(n log n) time, O(n) space. Stable. Predictable.
// --------------------------------------------------------------------------- 
function mergeSort(arr, compare = defaultCompare) {
  const a = clone(arr);
  if (a.length <= 1) return a;

  function merge(left, right) {
    const out = [];
    let i = 0, j = 0;
    while (i < left.length && j < right.length) {
      // <= keeps stability: take from left when equal
      if (compare(left[i], right[j]) <= 0) out.push(left[i++]);
      else out.push(right[j++]);
    }
    while (i < left.length) out.push(left[i++]);
    while (j < right.length) out.push(right[j++]);
    return out;
  }

  function sort(lo, hi) {
    if (hi - lo <= 1) return;
    const mid = (lo + hi) >> 1;
    sort(lo, mid);
    sort(mid, hi);
    // merge in place into a[lo..hi)
    const left  = a.slice(lo, mid);
    const right = a.slice(mid, hi);
    let i = 0, j = 0, k = lo;
    while (i < left.length && j < right.length) {
      if (compare(left[i], right[j]) <= 0) a[k++] = left[i++];
      else a[k++] = right[j++];
    }
    while (i < left.length) a[k++] = left[i++];
    while (j < right.length) a[k++] = right[j++];
  }

  sort(0, a.length);
  return a;
}

// --------------------------------------------------------------------------- 
// 5. Quick Sort — O(n log n) avg, O(n²) worst. O(log n) stack space. Unstable.
//    Uses median-of-three pivot + insertion sort for small partitions.
// --------------------------------------------------------------------------- 
function quickSort(arr, compare = defaultCompare) {
  const a = clone(arr);
  const INSERTION_THRESHOLD = 16;

  function sort(lo, hi) {          // sort a[lo..hi)  (hi exclusive)
    if (hi - lo <= 1) return;
    // small partitions → insertion sort (cache friendly)
    if (hi - lo <= INSERTION_THRESHOLD) {
      for (let i = lo + 1; i < hi; i++) {
        const key = a[i];
        let j = i - 1;
        while (j >= lo && compare(a[j], key) > 0) {
          a[j + 1] = a[j];
          j--;
        }
        a[j + 1] = key;
      }
      return;
    }
    // median-of-three pivot
    const mid = (lo + hi) >> 1;
    if (compare(a[mid], a[lo]) < 0) swap(a, lo, mid);
    if (compare(a[hi - 1], a[lo]) < 0) swap(a, lo, hi - 1);
    if (compare(a[hi - 1], a[mid]) < 0) swap(a, mid, hi - 1);
    const pivot = a[mid];
    swap(a, mid, hi - 2);          // stash pivot out of the way

    let i = lo, j = hi - 2;
    // Hoare-style partition
    while (true) {
      while (compare(a[++i], pivot) < 0) {}
      while (compare(a[--j], pivot) > 0) {}
      if (i >= j) break;
      swap(a, i, j);
    }
    swap(a, i, hi - 2);           // restore pivot
    sort(lo, i);
    sort(i + 1, hi);
  }

  sort(0, a.length);
  return a;
}

// --------------------------------------------------------------------------- 
// 6. Heap Sort — O(n log n) time, O(1) space. Unstable.
// --------------------------------------------------------------------------- 
function heapSort(arr, compare = defaultCompare) {
  const a = clone(arr);
  const n = a.length;

  function siftDown(start, end) {   // max-heap style sift down, range [start, end)
    let root = start;
    while (true) {
      const left = 2 * root + 1;
      if (left >= end) break;
      let child = left;
      const right = left + 1;
      if (right < end && compare(a[right], a[left]) > 0) child = right;
      if (compare(a[root], a[child]) < 0) {
        swap(a, root, child);
        root = child;
      } else break;
    }
  }

  // build max-heap
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) siftDown(i, n);
  // extract
  for (let end = n; end > 1; end--) {
    swap(a, 0, end - 1);
    siftDown(0, end - 1);
  }
  return a;
}

// --------------------------------------------------------------------------- 
// 7. (Bonus) TimSort — hybrid of merge + insertion, used by V8/Python.
//    Simplified educational version.
// --------------------------------------------------------------------------- 
function timSort(arr, compare = defaultCompare) {
  const a = clone(arr);
  const MIN_RUN = 32;

  function insertion(lo, hi) { // [lo, hi)
    for (let i = lo + 1; i < hi; i++) {
      const key = a[i];
      let j = i - 1;
      while (j >= lo && compare(a[j], key) > 0) { a[j + 1] = a[j]; j--; }
      a[j + 1] = key;
    }
  }

  function merge(lo, mid, hi) {
    const left = a.slice(lo, mid);
    const right = a.slice(mid, hi);
    let i = 0, j = 0, k = lo;
    while (i < left.length && j < right.length) {
      if (compare(left[i], right[j]) <= 0) a[k++] = left[i++];
      else a[k++] = right[j++];
    }
    while (i < left.length) a[k++] = left[i++];
    while (j < right.length) a[k++] = right[j++];
  }

  const n = a.length;
  for (let i = 0; i < n; i += MIN_RUN) {
    insertion(i, Math.min(i + MIN_RUN, n));
  }
  for (let size = MIN_RUN; size < n; size *= 2) {
    for (let lo = 0; lo < n; lo += 2 * size) {
      const mid = Math.min(lo + size, n);
      const hi  = Math.min(lo + 2 * size, n);
      if (mid < hi) merge(lo, mid, hi);
    }
  }
  return a;
}

// --------------------------------------------------------------------------- 
// In-place variants (mutate the original array) — handy for large data.
// --------------------------------------------------------------------------- 
function bubbleSortInPlace(arr, compare = defaultCompare) { return bubbleSort(arr, compare).forEach((v, i) => (arr[i] = v)), arr; }
// (For brevity, in-place wrappers can just copy back; shown for one only.)

// --------------------------------------------------------------------------- 
// Demo / correctness tests
// --------------------------------------------------------------------------- 
function isSorted(arr, compare = defaultCompare) {
  for (let i = 1; i < arr.length; i++) {
    if (compare(arr[i - 1], arr[i]) > 0) return false;
  }
  return true;
}

function runTests() {
  const algos = {
    bubble: bubbleSort,
    selection: selectionSort,
    insertion: insertionSort,
    merge: mergeSort,
    quick: quickSort,
    heap: heapSort,
    tim: timSort,
  };

  // 1. Random numbers
  console.log('=== Random numbers ===');
  const base = Array.from({ length: 2000 }, () => Math.floor(Math.random() * 10000));
  for (const [name, fn] of Object.entries(algos)) {
    const out = fn(base);
    console.log(name.padEnd(10), isSorted(out) ? 'OK' : 'FAIL', out.length);
  }

  // 2. Strings
  console.log('\n=== Strings ===');
  const words = ['banana', 'apple', 'cherry', 'date', 'elderberry', 'fig'];
  console.log('merge:', mergeSort(words));
  console.log('quick:', quickSort(words));

  // 3. Objects with custom comparator
  console.log('\n=== Objects (by age asc, then name) ===');
  const people = [
    { name: 'Zoe',  age: 30 },
    { name: 'Amy',  age: 25 },
    { name: 'Bob',  age: 25 },
    { name: 'Carl', age: 30 },
  ];
  const byAgeThenName = (a, b) =>
    a.age - b.age || a.name.localeCompare(b.name);
  console.log(quickSort(people, byAgeThenName));

  // 4. Edge cases
  console.log('\n=== Edge cases ===');
  for (const fn of Object.values(algos)) {
    if (!isSorted(fn([]))) throw new Error('empty failed');
    if (!isSorted(fn([42]))) throw new Error('single failed');
    if (!isSorted(fn([5, 4, 3, 2, 1]))) throw new Error('reverse failed');
    // duplicates
    if (!isSorted(fn([3, 1, 2, 1, 3, 2]))) throw new Error('dup failed');
  }
  console.log('all edge cases passed');

  // 5. Stability check (merge & insertion & bubble & tim should be stable)
  console.log('\n=== Stability (equal keys keep original order) ===');
  const tagged = [5, 3, 5, 1, 3].map((v, i) => ({ v, id: i }));
  const cmp = (a, b) => a.v - b.v;
  for (const name of ['bubble', 'insertion', 'merge', 'tim']) {
    const out = algos[name](tagged, cmp);
    const ids = out.map(o => o.id).join(',');
    console.log(name.padEnd(10), ids);
  }
  // Expected stable: 3,4,1,3,0,2  (1-based-ish grouping by value)
}

runTests();

// --------------------------------------------------------------------------- 
// Optional: expose as module
// --------------------------------------------------------------------------- 
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    defaultCompare,
    bubbleSort, selectionSort, insertionSort,
    mergeSort, quickSort, heapSort, timSort,
  };
}
```

