}

console.log(mergeSort(products, compareProducts));
```

## Sorting algorithms in JavaScript (interview-style)

In JavaScript, `Array.prototype.sort()` sorts **in place** and, by default, converts elements to strings and compares UTF-16 code units. For numbers you must pass a comparator:

```js
arr.sort((a, b) => a - b); // ascending
```

Modern engines (V8) use **TimSort** (a hybrid of merge sort + insertion sort) for `Array.prototype.sort`, which is stable and O(n log n) worst-case. But interviewers usually want you to *implement* the classic algorithms.

---

### 1. Big-picture taxonomy

| Algorithm | Best | Average | Worst | Space | Stable? |
|---|---|---|---|---|---|
| Bubble | O(n) | O(n²) | O(n²) | O(1) | Yes |
| Selection | O(n²) | O(n²) | O(n²) | O(1) | No |
| Insertion | O(n) | O(n²) | O(n²) | O(1) | Yes |
| Merge | O(n log n) | O(n log n) | O(n log n) | O(n) | Yes |
| Quick | O(n log n) | O(n log n) | O(n²) | O(log n) | No |
| Heap | O(n log n) | O(n log n) | O(n log n) | O(1) | No |
| Counting/Radix | O(n + k) | O(n + k) | O(n + k) | O(n + k) | Yes |

**Key ideas to mention:**
- **Stability**: equal keys keep original order (important for multi-key sorts).
- **In-place vs extra space**: heap/quick (in-place-ish) vs merge (needs O(n)).
- **Adaptive**: insertion sort is fast on nearly-sorted data.
- **Divide & conquer**: merge/quick reduce problem size.

---

### 2. Core implementations (clean, commented)

#### Bubble Sort — simplest, good for teaching
```js
// Repeatedly swap adjacent out-of-order elements.
// After each pass, the largest unsorted element "bubbles" to the end.
function bubbleSort(arr) {
  const n = arr.length;
  for (let i = 0; i < n - 1; i++) {
    let swapped = false;
    // Last i elements are already in place
    for (let j = 0; j < n - 1 - i; j++) {
      if (arr[j] > arr[j + 1]) {
        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]]; // ES6 swap
        swapped = true;
      }
    }
    if (!swapped) break; // early exit if already sorted
  }
  return arr;
}
```

#### Insertion Sort — great for small / nearly-sorted data
```js
// Build sorted prefix one element at a time by inserting into correct spot.
function insertionSort(arr) {
  for (let i = 1; i < arr.length; i++) {
    const key = arr[i];
    let j = i - 1;
    // Shift elements greater than key to the right
    while (j >= 0 && arr[j] > key) {
      arr[j + 1] = arr[j];
      j--;
    }
    arr[j + 1] = key;
  }
  return arr;
}
```

#### Merge Sort — stable, guaranteed O(n log n)
```js
// Divide into halves, sort each, merge two sorted halves.
function mergeSort(arr) {
  if (arr.length <= 1) return arr;

  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid));
  const right = mergeSort(arr.slice(mid));

  return merge(left, right);
}

function merge(left, right) {
  const result = [];
  let i = 0, j = 0;

  // Compare fronts and take smaller
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.push(left[i++]); // <= keeps stability
    } else {
      result.push(right[j++]);
    }
  }
  // Append remainder
  while (i < left.length) result.push(left[i++]);
  while (j < right.length) result.push(right[j++]);

  return result;
}
```

#### Quick Sort — fast in practice, in-place partitioning
```js
// Pick pivot, partition into < pivot and > pivot, recurse.
// Uses Lomuto partition scheme; random pivot avoids worst-case on sorted input.
function quickSort(arr, left = 0, right = arr.length - 1) {
  if (left >= right) return arr;

  // Random pivot to avoid O(n²) on sorted/reverse-sorted input
  const pivotIndex = left + Math.floor(Math.random() * (right - left + 1));
  [arr[pivotIndex], arr[right]] = [arr[right], arr[pivotIndex]];

  const p = partition(arr, left, right);
  quickSort(arr, left, p - 1);
  quickSort(arr, p + 1, right);
  return arr;
}

function partition(arr, left, right) {
  const pivot = arr[right];
  let i = left - 1; // boundary of "less than pivot" region

  for (let j = left; j < right; j++) {
    if (arr[j] < pivot) {
      i++;
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  }
  // Place pivot in final position
  [arr[i + 1], arr[right]] = [arr[right], arr[i + 1]];
  return i + 1;
}
```

#### Heap Sort — in-place O(n log n), no recursion stack
```js
// Build max-heap, then repeatedly extract max to end.
function heapSort(arr) {
  const n = arr.length;

  // Build max-heap (bottom-up)
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
    heapify(arr, n, i);
  }

  // Extract elements one by one
  for (let end = n - 1; end > 0; end--) {
    [arr[0], arr[end]] = [arr[end], arr[0]]; // move max to end
    heapify(arr, end, 0);
  }
  return arr;
}

function heapify(arr, heapSize, root) {
  let largest = root;
  const left = 2 * root + 1;
  const right = 2 * root + 2;

  if (left < heapSize && arr[left] > arr[largest]) largest = left;
  if (right < heapSize && arr[right] > arr[largest]) largest = right;

  if (largest !== root) {
    [arr[root], arr[largest]] = [arr[largest], arr[root]];
    heapify(arr, heapSize, largest); // sift down
  }
}
```

---

### 3. How to choose in an interview

- **Small arrays (< ~20–50)** → Insertion sort (low overhead, adaptive).
- **Need stability + guaranteed perf** → Merge sort (but costs O(n) space).
- **Memory constrained, in-place** → Heap sort.
- **Average-case speed, don't care about worst-case** → Quick sort (with random pivot).
- **Integers in small range** → Counting sort (O(n + k)).
- **Large integers / strings** → Radix sort.

### 4. Common follow-ups

**Q: Why does `Array.prototype.sort()` behave weirdly with numbers?**  
Because default comparator stringifies: `[10, 2, 1].sort()` → `["1","10","2"]`. Always pass `(a,b) => a-b`.

**Q: Is `Array.prototype.sort` stable?**  
Yes in modern engines (ES2019 spec requires stability), but historically not guaranteed—don't rely on it for cross-engine code without a comparator that breaks ties explicitly.

**Q: Quick sort worst case?**  
Sorted input with naive pivot (first/last) → O(n²). Fix with random pivot or median-of-three.

**Q: Merge vs Quick space?**  
Merge needs O(n) auxiliary; quick is O(log n) stack (in-place partitioning).

---

### 5. Mini test harness (runnable)
```js
function test(sortFn) {
  const cases = [
    [],
    [1],
    [5, 4, 3, 2, 1],
    [1, 2, 3, 4, 5],
    [3, 1, 4, 1, 5, 9, 2, 6],
    [-3, 0, 7, -1, 2],
  ];
  for (const c of cases) {
    const copy = [...c];
    const sorted = sortFn([...c]);
    const ok = JSON.stringify(sorted) === JSON.stringify([...c].sort((a,b)=>a-b));
    console.log(sortFn.name, c, '->', sorted, ok ? 'OK' : 'FAIL');
  }
}

test(bubbleSort);
test(insertionSort);
test(mergeSort);
test(quickSort);
test(heapSort);
```

**Interview tip:** Always clarify constraints first—size of input, value range, memory limits, stability requirement—then pick the algorithm. That answer scores higher than just reciting complexities.

# Edge Cases When Sorting in JavaScript

Below are the most important edge cases, each with a runnable example and the fix.

## 1. Default sort coerces to strings (the #1 trap)

`Array.prototype.sort()` with no comparator converts elements to strings and compares UTF-16 code units.

```js
const nums = [10, 2, 1, 20];
console.log(nums.sort());        // [1, 10, 2, 20]  ❌ string order
console.log([...nums].sort((a, b) => a - b)); // [1, 2, 10, 20] ✅
```

**Rule:** Always pass a comparator for non-string data.

## 2. In-place mutation

`sort()` mutates the original array. If you need immutability (React state, Redux, etc.), copy first.

```js
const original = [3, 1, 2];
const sorted = original.sort((a, b) => a - b); // mutates original!
console.log(original); // [1, 2, 3]
console.log(sorted === original); // true

// Fix:
const safe = [...original].sort((a, b) => a - b);
```

## 3. `undefined` vs other values

`undefined` elements are sorted to the **end**. `null` is coerced to `"null"` string (or compared as 0 in numeric comparator).

```js
console.log([3, undefined, 1, null].sort((a, b) => a - b));
// [null, 1, 3, undefined]  (null -> 0 in subtraction)
```

Be explicit about placement:

```js
const cmp = (a, b) => {
  if (a == null && b == null) return 0;
  if (a == null) return 1;   // push nulls/undefined to end
  if (b == null) return -1;
  return a - b;
};
```

## 4. Sparse arrays (holes)

Holes are treated as `undefined` and moved to the end; they do *not* occupy a real index after sort in most cases, but the array length is preserved with trailing holes.

```js
const a = [3, , 1, , 2];
console.log(a.sort((x, y) => x - y));
// [1, 2, 3, <2 empty items>]  (holes at end)
console.log(a.length); // 5
```

If you want holes removed, compact first: `arr.filter(x => x !== undefined)` (careful: can't distinguish hole from explicit undefined).

## 5. NaN and -0

- `NaN` comparisons always return `false`, so `NaN - NaN` is `NaN`. Sort order of `NaN` is implementation-defined → results vary by engine.
- `-0` and `+0` compare equal numerically but are distinct values.

```js
console.log([NaN, 2, 1].sort((a, b) => a - b));
// commonly [1, 2, NaN] or [NaN, 1, 2] depending on engine

// Fix: normalize
const cmp = (a, b) => {
  const an = Number.isNaN(a) ? Infinity : a; // or -Infinity to push first
  const bn = Number.isNaN(b) ? Infinity : b;
  return an - bn;
};
```

## 6. BigInt mixed with Number

You cannot mix `BigInt` and `Number` in subtraction (`1n - 1` throws `TypeError`). Sort comparators must handle types explicitly.

```js
const mixed = [5n, 3, 10n, 1];
// mixed.sort((a, b) => a - b); // TypeError

const cmp = (a, b) => {
  const A = typeof a === 'bigint' ? a : BigInt(a);
  const B = typeof b === 'bigint' ? b : BigInt(b);
  return A < B ? -1 : A > B ? 1 : 0;
};
console.log(mixed.sort(cmp)); // [1, 3, 5n, 10n]
```

## 7. Inconsistent comparator → undefined behavior

A comparator must define a **total order**: antisymmetric, transitive, consistent. Returning `NaN`, or being inconsistent, gives engine-dependent (sometimes crash-inducing) results.

```js
const bad = (a, b) => Math.random() - 0.5; // not a valid order
console.log([1,2,3,4,5].sort(bad)); // garbage / infinite? (engines may hang or produce weird output)

// Also bad: comparator depends on external mutable state
let counter = 0;
const flaky = (a, b) => (counter++ % 2 === 0 ? -1 : 1);
```

**Always:** return negative/0/positive consistently; never use randomness or mutable external state.

## 8. Stability (pre-ES2019)

Since ES2019, `Array.prototype.sort` is **stable**. But custom sort implementations (or older environments like IE) may not be. If you sort by secondary keys first then primary, stability matters.

```js
const items = [
  { priority: 1, name: 'b' },
  { priority: 1, name: 'a' },
  { priority: 2, name: 'c' },
];
// Stable sort preserves original relative order for equal keys:
console.log(items.sort((a, b) => a.priority - b.priority));
// [{p:1,b}, {p:1,a}, {p:2,c}] — original order among equals preserved

// For a fully deterministic multi-key sort, encode all keys in comparator:
const cmp = (a, b) =>
  a.priority - b.priority || a.name.localeCompare(b.name);
```

## 9. Locale / case / accent sensitivity

Default string sort uses code-point order: uppercase before lowercase, accented letters after Z.

```js
console.log(['banana', 'Apple', 'cherry', 'Äpfel'].sort());
// ['Apple', 'cherry', 'banana', 'Äpfel']  (code-point order, not alphabetical)

// Fix:
console.log(['banana', 'Apple', 'cherry', 'Äpfel'].sort((a, b) =>
  a.localeCompare(b, 'de', { sensitivity: 'base' })
));
```

For numeric substrings within strings, use `{ numeric: true }`:

```js
['file10', 'file2', 'file1'].sort((a,b)=>
  a.localeCompare(b, undefined, { numeric: true })); // ['file1','file2','file10']
```

## 10. Sorting objects by a property that may be missing

```js
const users = [{ name: 'Zoe' }, { name: 'Amy' }, {}];
const byName = (a, b) => (a.name ?? '').localeCompare(b.name ?? '');
console.log(users.sort(byName));
```

## 11. Very large arrays / recursion depth

A hand-written recursive quicksort can blow the call stack on ~10⁵+ elements. Use iterative mergesort or the built-in (TimSort) which handles large inputs.

```js
// Risky on large input:
function quicksort(arr, lo=0, hi=arr.length-1) {
  if (lo >= hi) return arr;
  const p = partition(arr, lo, hi);
  quicksort(arr, lo, p-1);   // may exceed stack
  quicksort(arr, p+1, hi);
  return arr;
}
```

Prefer `arr.sort(...)` (engine-implemented, iterative-safe) or an iterative algorithm.

## 12. Mutating the array during sort

Comparators or accessors that mutate the array being sorted cause undefined behavior.

```js
const arr = [3, 1, 2];
arr.sort((a, b) => {
  arr.push(999); // ❌ never do this
  return a - b;
});
```

## 13. Sorting with a non-array / exotic objects

`Array.prototype.sort` works on array-like objects with a `length` and integer indices, but mutates them:

```js
const obj = { 0: 'c', 1: 'a', 2: 'b', length: 3 };
Array.prototype.sort.call(obj);
console.log(obj); // {0:'a',1:'b',2:'c',length:3}
```

## 14. Performance: comparator cost

A comparator called O(n log n) times. Avoid expensive work inside it (regex, localeCompare on every call without caching). Cache sort keys:

```js
// Schwartzian transform
const keyed = arr.map(x => ({ key: expensiveKey(x), value: x }));
keyed.sort((a, b) => a.key - b.key);
const result = keyed.map(x => x.value);
```

## 15. Type coercion gotchas with `-`

`'10' - '2'` is `8` (numeric coercion), but `'a' - 'b'` is `NaN`. Mixed types can silently produce NaN.

```js
['10','2','1'].sort((a,b)=>a-b); // works by coercion: [1,2,10]
['a','b','c'].sort((a,b)=>a-b);  // NaN → unstable order
```

## Summary checklist

| Edge case | Mitigation |
|---|---|
| Default string sort | Always provide comparator |
| Mutation | `[...arr].sort(...)` |
| `undefined`/`null` | Explicit null handling in comparator |
| Holes | Compact first if needed |
| `NaN` | Normalize to sentinel |
| BigInt + Number | Convert to common type |
| Inconsistent comparator | Ensure total order, no side effects |
| Stability | Encode all keys, or rely on ES2019+ |
| Locale/case/accents | `localeCompare` with options |
| Missing props | Nullish coalescing defaults |
| Stack overflow | Use built-in or iterative sort |
| Mutation during sort | Pure comparators |
| Performance | Cache sort keys (Schwartzian) |

The single most important habit: **never call `.sort()` without a comparator on heterogeneous or numeric data, and never assume it doesn't mutate.**

Below is a complete, runnable JavaScript implementation of both a **stack** (LIFO) and a **binary heap** (priority queue). The heap is generic: by default it is a min-heap, but you can pass a comparator to make it a max-heap or order objects.

### Runnable example

Save as `stack-heap.js` and run with `node stack-heap.js`.

```js
// ---------- Stack ----------
class Stack {
  constructor() {
    this.items = [];
  }

  push(value) {
    this.items.push(value);
  }

  pop() {
    if (this.isEmpty()) throw new Error("Stack underflow");
    return this.items.pop();
  }

  peek() {
    if (this.isEmpty()) throw new Error("Stack is empty");
    return this.items[this.items.length - 1];
  }

  isEmpty() {
    return this.items.length === 0;
  }

  size() {
    return this.items.length;
  }

  clear() {
    this.items.length = 0;
  }

  toArray() {
    return [...this.items];
  }
}

// ---------- Binary Heap (Priority Queue) ----------
class Heap {
  /**
   * compare(a, b) < 0  => a has higher priority than b
   * Default is a min-heap (numeric ascending).
   */
  constructor(compare = (a, b) => a - b) {
    this.heap = [];
    this.compare = compare;
  }

  size() {
    return this.heap.length;
  }

  isEmpty() {
    return this.heap.length === 0;
  }

  peek() {
    if (this.isEmpty()) throw new Error("Heap is empty");
    return this.heap[0];
  }

  insert(value) {
    this.heap.push(value);
    this._siftUp(this.heap.length - 1);
  }

  extract() {
    if (this.isEmpty()) throw new Error("Heap underflow");

    const root = this.heap[0];
    const last = this.heap.pop();

    if (!this.isEmpty()) {
      this.heap[0] = last;
      this._siftDown(0);
    }
    return root;
  }

  _parent(i) {
    return Math.floor((i - 1) / 2);
  }

  _left(i) {
    return 2 * i + 1;
  }

  _right(i) {
    return 2 * i + 2;
  }

  _siftUp(i) {
    while (i > 0) {
      const p = this._parent(i);
      if (this.compare(this.heap[i], this.heap[p]) < 0) {
        [this.heap[i], this.heap[p]] = [this.heap[p], this.heap[i]];
        i = p;
      } else {
        break;
      }
    }
  }

  _siftDown(i) {
    const n = this.heap.length;
    while (true) {
      let best = i;
      const l = this._left(i);
      const r = this._right(i);

      if (l < n && this.compare(this.heap[l], this.heap[best]) < 0) {
        best = l;
      }
      if (r < n && this.compare(this.heap[r], this.heap[best]) < 0) {
        best = r;
      }

      if (best !== i) {
        [this.heap[i], this.heap[best]] = [this.heap[best], this.heap[i]];
        i = best;
      } else {
        break;
      }
    }
  }

  // Build a heap from an array in O(n)
  static fromArray(arr, compare = (a, b) => a - b) {
    const h = new Heap(compare);
    h.heap = [...arr];
    for (let i = Math.floor(h.heap.length / 2) - 1; i >= 0; i--) {
      h._siftDown(i);
    }
    return h;
  }

  toArray() {
    return [...this.heap];
  }
}

// ---------- Demo / Tests ----------
function assert(cond, msg) {
  if (!cond) throw new Error(msg || "Assertion failed");
}

// Stack demo
const stack = new Stack();
stack.push(10);
stack.push(20);
stack.push(30);
assert(stack.peek() === 30, "peek should be 30");
assert(stack.pop() === 30, "pop should be 30");
assert(stack.pop() === 20, "pop should be 20");
assert(stack.size() === 1, "size should be 1");
assert(!stack.isEmpty(), "stack should not be empty");
stack.clear();
assert(stack.isEmpty(), "stack should be empty");

// Min-heap demo
const minHeap = new Heap();
[5, 3, 8, 1, 2].forEach((x) => minHeap.insert(x));
assert(minHeap.peek() === 1, "min peek should be 1");
assert(minHeap.extract() === 1, "extract min should be 1");
assert(minHeap.extract() === 2, "extract min should be 2");
assert(minHeap.extract() === 3, "extract min should be 3");

// Max-heap demo (via comparator)
const maxHeap = new Heap((a, b) => b - a);
[5, 3, 8, 1, 2].forEach((x) => maxHeap.insert(x));
assert(maxHeap.peek() === 8, "max peek should be 8");
assert(maxHeap.extract() === 8, "extract max should be 8");
assert(maxHeap.extract() === 5, "extract max should be 5");

// Heap from array demo
const h = Heap.fromArray([9, 4, 7, 1, 3]);
assert(h.extract() === 1);
assert(h.extract() === 3);
assert(h.extract() === 4);

// Object priority queue demo
const pq = new Heap((a, b) => a.priority - b.priority);
pq.insert({ name: "low", priority: 10 });
pq.insert({ name: "high", priority: 1 });
pq.insert({ name: "mid", priority: 5 });
assert(pq.extract().name === "high");
assert(pq.extract().name === "mid");
assert(pq.extract().name === "low");

console.log("All tests passed.");
console.log("Stack contents example:", new Stack().toArray());
```

### Notes

- **Stack**: backed by a JavaScript array; `push`/`pop` are O(1) amortized.
- **Heap**: binary min-heap (or max-heap via comparator). `insert` and `extract` are O(log n); `peek` is O(1); `fromArray` builds in O(n).
- JavaScript engines manage the actual memory heap and call stack automatically; this code implements the **data structures**, not the runtime memory allocator.

## Stack vs. Heap in JavaScript

JavaScript is a garbage-collected language, so you never allocate or free memory explicitly.  
Conceptually, the runtime uses two memory regions:

| Region | What lives there | Lifetime | Access pattern |
|---|---|---|---|
| **Call stack** | Execution contexts, local variables, function arguments, primitive values | Tied to function calls; automatically popped when a function returns | LIFO (last-in, first-out) |
| **Heap** | Objects, arrays, functions, closures, and other dynamically sized data | Lives until no references remain; freed by the garbage collector | Random access via references |

> **Engine caveat:** V8/SpiderMonkey/JSC optimize aggressively. Small integers may be unboxed, strings may be interned, and some “primitives” can live on the heap temporarily. The *language-level* model below is what you should reason about.

---

## 1. The stack: execution and primitives

The stack stores **execution frames**. Each time a function is called, a frame is pushed containing:

- the function’s parameters
- local variables
- the return address

Primitive values (`number`, `string`, `boolean`, `null`, `undefined`, `symbol`, `bigint`) are typically stored **by value** in the frame.

```js
function add(a, b) {
  const sum = a + b;   // `a`, `b`, `sum` live in this frame
  return sum;
}

const result = add(2, 3); // frame pushed, then popped; result gets the value 5
```

### Stack overflow

Because stack size is limited, deep recursion throws `RangeError: Maximum call stack size exceeded`.

```js
function recurse(n) {
  if (n === 0) return 0;
  return n + recurse(n - 1); // each call adds a frame
}
// recurse(100000); // RangeError in most engines
```

**Typical use cases for stack-heavy code:**

- small, bounded recursion (tree traversal with known depth)
- synchronous, nested function calls
- local scratch variables

---

## 2. The heap: objects and references

Objects (including arrays, functions, dates, Maps, Sets, regexes) are allocated on the **heap**.  
The stack only holds a **reference** (pointer) to that heap object.

```js
const user = { name: "Ada", age: 36 };
// `user` (the binding) is on the stack; { name, age } is on the heap
```

### Reference vs. value semantics

```js
// Primitives: copied by value
let x = 10;
let y = x;
y = 20;
console.log(x, y); // 10 20

// Objects: copied by reference
const a = { v: 1 };
const b = a;        // same heap object
b.v = 2;
console.log(a.v);   // 2

// Reassigning the binding changes only that variable
b = { v: 99 };      // now b points elsewhere; a unchanged
```

### `const` does not mean “deeply immutable”

```js
const arr = [1, 2, 3];
arr.push(4);          // OK: mutating the heap object
// arr = [5, 6];      // Error: cannot reassign the stack binding
```

---

## 3. Garbage collection (how heap memory is freed)

The GC frees heap objects that are **unreachable** from the roots (global object, stack frames, closures).

```js
function make() {
  return { data: new Array(1_000_000).fill(0) };
}
let big = make(); // heap array reachable via `big`
big = null;       // now unreachable → eligible for GC
```

### Common leak patterns

```js
// 1. Forgotten global
window.leak = new Array(1_000_000).fill(0);

// 2. Closure retaining a large scope
function heavy() {
  const huge = new Array(1_000_000).fill(0);
  return function () {
    return huge.length; // closure keeps `huge` alive
  };
}

// 3. Detached DOM nodes (in browsers)
let node = document.getElementById("x");
document.body.removeChild(node);
// `node` still references the detached subtree → leak until `node = null`
```

---

## 4. Closures and the heap

Closures capture variables from their lexical environment. Those captured variables are stored in **heap-allocated environment records**, not on the stack, so they survive after the outer function returns.

```js
function counter() {
  let count = 0; // conceptually moved to heap because of closure
  return function () {
    count += 1;
    return count;
  };
}

const c = counter();
console.log(c()); // 1
console.log(c()); // 2
```

---

## 5. Typical use cases and design implications

| Scenario | Stack/heap reasoning | Practical advice |
|---|---|---|
| Large datasets (millions of rows) | Lives on heap | Use typed arrays (`Uint8Array`, etc.) for compact heap storage; avoid deep copying |
| Recursion (DFS, quicksort) | Consumes stack | Prefer iterative versions for large inputs; use trampolining if needed |
| Caching / memoization | Caches on heap | Bound cache size (LRU) to avoid leaks |
| Event listeners / timers | Callbacks + closures on heap | Remove listeners and clear timers when done |
| Passing data to workers | Structured clone crosses heap boundaries | Use `postMessage` with Transferable objects for zero-copy (`ArrayBuffer`) |

### Transferable example (zero-copy heap move)

```js
const buf = new ArrayBuffer(1_000_000);
worker.postMessage(buf, [buf]); // ownership transferred; buf.byteLength === 0 in sender
```

---

## 6. Quick mental checklist

- **Primitive assignment** → new value on stack (copy).  
- **Object assignment** → new reference on stack, same heap object.  
- **Function call** → new stack frame; locals die when frame pops (unless captured by closure).  
- **Unreachable heap object** → GC eventually reclaims it.  
- **Deep recursion** → risk of stack overflow; iterate instead.  

If you keep these in mind, you’ll avoid most JavaScript memory bugs while writing idiomatic, predictable code.

## Common stack/heap pitfalls in JavaScript

A useful mental model: the **call stack** holds execution contexts and (usually) primitive values, while the **heap** holds objects, arrays, functions, closures, and shared mutable state. Most bugs come from confusing **references** with **values**, retaining heap objects longer than intended, or exhausting the stack.

---

### 1. Deep recursion causes stack overflow

JavaScript does not guarantee tail-call optimization in most engines, and the call stack is limited.

```js
function sum(n) {
  if (n <= 0) return 0;
  return n + sum(n - 1);
}

sum(100_000); // RangeError: Maximum call stack size exceeded
```

**Fix:** use iteration, or an explicit stack.

```js
function sum(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) total += i;
  return total;
}
```

---

### 2. Objects and arrays are assigned by reference, not copied

```js
const user = { name: 'Ada' };
const alias = user;

alias.name = 'Grace';
console.log(user.name); // 'Grace'
```

The same applies to arrays:

```js
const a = [1, 2, 3];
const b = a;
b.push(4);
console.log(a); // [1, 2, 3, 4]
```

**Fix:** copy explicitly, and know whether the copy is shallow or deep.

```js
const shallow = { ...user };
const deep = structuredClone(user);
```

---

### 3. Shallow copies still share nested objects

```js
const original = { profile: { age: 30 } };
const copy = { ...original };

copy.profile.age = 31;
console.log(original.profile.age); // 31
```

**Fix:** use `structuredClone` for deep cloning of supported data. Be aware that it cannot clone functions, DOM nodes, or some special objects.

```js
const copy = structuredClone(original);
```

---

### 4. `const` does not make objects immutable

```js
const config = { debug: false };
config.debug = true; // allowed
```

**Fix:** freeze the object if you want immutability. Note that `Object.freeze` is shallow.

```js
const config = Object.freeze({ debug: false });
config.debug = true; // ignored in non-strict; throws in strict mode
```

---

### 5. Closures can retain large heap objects

A closure keeps its entire lexical environment alive.

```js
function createHandler() {
  const huge = new Array(10_000_000).fill(0);
  return () => huge.length;
}

const handler = createHandler();
// `huge` remains reachable through `handler`
```

**Fix:** extract only what you need before returning the closure.

```js
function createHandler() {
  const huge = new Array(10_000_000).fill(0);
  const length = huge.length;
  return () => length;
}
```

---

### 6. Accidental globals pollute the global heap

In non-strict mode, assigning to an undeclared variable creates a property on the global object.

```js
function init() {
  cache = []; // becomes global
}
init();
console.log(globalThis.cache); // []
```

**Fix:** always use strict mode and declare variables.

```js
'use strict';
function init() {
  const cache = [];
}
```

---

### 7. `var` in loops creates shared closure state

```js
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}
// Prints 3, 3, 3
```

**Fix:** use `let`, which creates a fresh binding per iteration.

```js
for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}
// Prints 0, 1, 2
```

---

### 8. Circular references are okay, but reachable cycles retain everything

Modern GCs collect unreachable cycles. The pitfall is keeping one reference alive.

```js
const a = {};
const b = {};
a.child = b;
b.parent = a;

// If `a` is reachable, both `a` and `b` stay alive.
```

**Fix:** break references when done, especially for caches, graphs, or large object graphs.

```js
a.child = null;
b.parent = null;
```

---

### 9. Maps and Sets retain keys forever

```js
const cache = new Map();
cache.set(someObject, expensiveResult);
// someObject and expensiveResult remain reachable as long as `cache` exists
```

**Fix:** use `WeakMap` or `WeakSet` when keys are objects and you want cache entries to disappear when keys are no longer used elsewhere.

```js
const cache = new WeakMap();
cache.set(someObject, expensiveResult);
```

Note: `WeakMap` keys must be objects, and you cannot iterate over all entries.

---

### 10. Detached DOM nodes stay in memory

```js
let button = document.querySelector('button');
document.body.removeChild(button);

// `button` still references the detached node and its subtree
button = null; // allow GC
```

Event listeners can also keep nodes alive:

```js
const onClick = () => console.log('clicked');
button.addEventListener('click', onClick);

// Later:
button.removeEventListener('click', onClick);
```

**Modern fix:** use `AbortController` for easy cleanup.

```js
const controller = new AbortController();
button.addEventListener('click', handler, { signal: controller.signal });

// Remove all listeners registered with this signal:
controller.abort();
```

---

### 11. Uncleared timers and intervals

```js
const id = setInterval(() => {
  doExpensiveWork();
}, 1000);

// If never cleared, the callback and its closure stay alive.
```

**Fix:** store the ID and clear it.

```js
clearInterval(id);
```

For one-time delayed work, prefer `setTimeout` and clear it if the component/task is destroyed.

---

### 12. Anonymous event listeners cannot be removed

```js
button.addEventListener('click', () => save());
button.addEventListener('click', () => save());

// You cannot remove either listener with removeEventListener
// because you do not have the same function reference.
```

**Fix:** store a named function reference.

```js
function onSave() { save(); }
button.addEventListener('click', onSave);
button.removeEventListener('click', onSave);
```

---

### 13. `delete` on arrays creates holes instead of removing elements

```js
const arr = [1, 2, 3];
delete arr[1];

console.log(arr);       // [1, <1 empty item>, 3]
console.log(arr.length); // 3
```

This can leave sparse arrays, which are slower and can retain unexpected structure.

**Fix:** use methods that adjust length.

```js
arr.splice(1, 1); // [1, 3]
// or
arr.pop();
arr.shift();
```

---

### 14. TypedArray views can retain large buffers

A view shares the underlying `ArrayBuffer`.

```js
const buffer = new ArrayBuffer(1_000_000);
const view = new Uint8Array(buffer, 0, 10);

// The entire 1 MB buffer may remain alive because `view` references it.
```

**Fix:** copy into a smaller owned buffer if you only need a small slice.

```js
const copy = new Uint8Array(view); // owns a 10-byte buffer
```

---

### 15. Hot loops that allocate many objects cause GC pressure

```js
for (let i = 0; i < 1_000_000; i++) {
  process({ x: i, y: i });
}
```

This can trigger frequent garbage collection pauses.

**Fix:** reuse objects when safe, but be careful not to accidentally share mutable state.

```js
const point = { x: 0, y: 0 };

for (let i = 0; i < 1_000_000; i++) {
  point.x = i;
  point.y = i;
  process(point);
}
```

Only pool objects if the consumer does not retain them.

---

### 16. Console logging can retain objects in development

```js
const big = new Array(10_000_000).fill(0);
console.log(big);
```

DevTools may keep a reference to logged objects, making memory profiling misleading.

**Fix:** log summaries, not entire large objects.

```js
console.log({ length: big.length });
```

---

### 17. `JSON.stringify` and `structuredClone` have important limitations

```js
const obj = {
  fn: () => 1,
  date: new Date(),
  map: new Map([['a', 1]]),
  circular: null,
};
obj.circular = obj;

JSON.stringify(obj); // throws on circular reference
```

`structuredClone` handles more types and circular references, but still cannot clone functions, DOM nodes, or prototype chains.

**Fix:** choose serialization based on data shape.

```js
const clone = structuredClone({ date: new Date(), nested: { x: 1 } });
```

---

### 18. Treating `WeakRef` as deterministic cleanup

```js
const ref = new WeakRef(largeObject);

// Later
const obj = ref.deref();
if (obj) {
  // Object still alive; use it
}
```

The object may be collected at any time, and `FinalizationRegistry` callbacks are not guaranteed to run promptly or at all.

**Fix:** use `WeakRef` only as an optimization, never for correctness.

---

### 19. Recursive data structures can overflow even with “tail-recursive-looking” code

```js
function flatten(arr) {
  return arr.reduce((acc, item) => {
    return acc.concat(Array.isArray(item) ? flatten(item) : item);
  }, []);
}

flatten(Array(10_000).fill([1])); // may overflow
```

**Fix:** use an explicit stack.

```js
function flatten(arr) {
  const result = [];
  const stack = [...arr];

  while (stack.length) {
    const item = stack.pop();
    if (Array.isArray(item)) {
      stack.push(...item);
    } else {
      result.push(item);
    }
  }
  return result;
}
```

---

### Quick checklist

- Use strict mode.
- Prefer `let`/`const` over `var`.
- Copy objects deliberately; know shallow vs deep.
- Break references to large or detached objects.
- Clear timers, listeners, and observers.
- Use `WeakMap`/`WeakSet` for object-keyed caches.
- Avoid deep recursion; use iteration.
- Profile memory in DevTools, but remember console logging can distort results.
- Treat `WeakRef` and finalizers as best-effort only.

## Exercise

**Part A – Predict the output (and why)**

```js
// 1. Object reference
let a = { x: 1 };
let b = a;
b.x = 2;
console.log("1:", a.x);

// 2. Array passed to function
const arr = [1, 2, 3];
function pushFour(x) { x.push(4); }
pushFour(arr);
console.log("2:", arr);

// 3. Closures over heap variables
function makeCounter() {
  let n = 0;          // heap-captured by closure
  return () => ++n;
}
const c1 = makeCounter();
const c2 = makeCounter();
console.log("3:", c1(), c1(), c2());

// 4. Deep recursion
function sumTo(n) {
  if (n === 0) return 0;
  return n + sumTo(n - 1);
}
console.log("4:", sumTo(100000));
```

**Part B – Practical task**

Write `deepClone(value)` that:
- returns a fully independent copy for plain objects/arrays,
- does not mutate the input,
- handles cyclic references safely,
- avoids stack overflow on deeply nested structures (use an iterative approach).

Then use it to implement `immutableUpdate(obj, path, value)` that returns a new object with a nested property changed (structural sharing is a bonus).

---

## Step-by-step solution

### Part A – reasoning

#### 1. Object reference → `2`
`a` holds a reference to a heap object `{ x: 1 }`. `b = a` copies the **reference**, not the object. Both point to the same heap allocation, so mutating via `b` is visible through `a`.

#### 2. Array argument → `[1, 2, 3, 4]`
Arrays are objects (heap). Parameters receive the reference, so `pushFour` mutates the caller's array. Primitives would be copied by value (stack slot), but objects are shared.

#### 3. Closures → `1 2 1`
Each call to `makeCounter` creates a *new* heap-allocated environment record containing `n`. The returned arrow function closes over that environment. `c1` and `c2` have independent `n`'s, so counts are independent.

#### 4. Deep recursion → `RangeError: Maximum call stack size exceeded`
Each call pushes a new stack frame (local `n`, return address). ~100k frames exceed V8's stack limit (typically ~10k–50k depending on frame size). Primitives/locals live on the stack; the overflow is a stack-space failure, not a heap failure. Fix: convert to iteration (tail-recursive? JS engines don't guarantee TCO).

---

### Part B – implementation

```js
// ---------- deepClone (iterative, cycle-safe) ----------
function deepClone(value) {
  // Fast path for primitives & null
  if (value === null || typeof value !== "object") return value;

  // Map from original object -> its clone (handles cycles + sharing)
  const clones = new Map();

  // Stack of work items: { src, dst, key? }
  // We use a root wrapper so arrays/objects unify.
  const root = Array.isArray(value) ? [] : {};
  clones.set(value, root);

  // Worklist: pairs (source, destination container to fill)
  // We'll process by copying enumerable own props.
  const stack = [{ src: value, dst: root }];

  while (stack.length) {
    const { src, dst } = stack.pop();

    // Enumerate own enumerable keys (arrays include indices)
    for (const key of Object.keys(src)) {
      const v = src[key];

      if (v !== null && typeof v === "object") {
        // Reuse existing clone if we've seen this object (cycle / shared ref)
        if (clones.has(v)) {
          dst[key] = clones.get(v);
        } else {
          const child = Array.isArray(v) ? [] : {};
          clones.set(v, child);
          dst[key] = child;
          stack.push({ src: v, dst: child });
        }
      } else {
        // Primitives: copied by value (new stack slot / primitive)
        dst[key] = v;
      }
    }
  }

  return root;
}

// ---------- immutableUpdate (path-based, non-mutating) ----------
function immutableUpdate(obj, path, value) {
  if (!path.length) return deepClone(value); // replacing root
  // Walk path, cloning along the way (structural sharing for untouched branches)
  const root = Array.isArray(obj) ? [...obj] : { ...obj };
  let cur = root;
  for (let i = 0; i < path.length - 1; i++) {
    const k = path[i];
    const next = objAtPath(obj, path.slice(0, i + 1));
    // clone the next node we're about to descend into
    const cloned = Array.isArray(next) ? [...next] : (next && typeof next === "object" ? { ...next } : next);
    cur[k] = cloned;
    cur = cloned;
  }
  cur[path[path.length - 1]] = deepClone(value);
  return root;
}

function objAtPath(obj, path) {
  return path.reduce((acc, k) => (acc == null ? undefined : acc[k]), obj);
}

// ---------- safe sumTo (iterative, no stack overflow) ----------
function sumToIterative(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) total += i;
  return total;
}
```

