## 1. Stack vs. Heap in JavaScript (memory model)

### Call stack
- **LIFO** structure used by the engine to manage **execution contexts** (global, function calls).
- Holds **primitive values** and **references** to heap objects for the current frame.
- Synchronous: when a function is called, a frame is pushed; when it returns, it is popped.
- **Size is limited** → deep recursion can throw `RangeError: Maximum call stack size exceeded`.
- Very fast: allocation/deallocation is just moving a pointer.

### Heap
- Large, unstructured region for **objects, arrays, functions, closures**.
- Allocation is dynamic; **garbage collector** (mark-and-sweep in V8, etc.) reclaims unreachable memory.
- Slower than stack; GC pauses can affect latency.
- Variables on the stack often store **pointers** into the heap.

### JS-specific nuances
- Primitives (`number`, `string`, `boolean`, `null`, `undefined`, `symbol`, `bigint`) are immutable and usually stack-resident by value.
- Objects are heap-allocated; assignment copies the **reference**, not the object.
- Closures capture variables via **lexical environments** that are themselves heap objects, so captured variables survive after the creating function returns.
- `const`/`let` live in temporal dead zone until initialized; `var` hoisted with `undefined`.

---

## 2. Implementing the core (data structures)

Below are two common interview implementations: a **Stack** and a **binary Min-Heap** (often called “heap” in interviews). Both are array-backed for cache locality and O(1) random access for the heap’s parent/child math.

### Stack (dynamic array-backed)

```js
/**
 * A simple dynamic-array-backed stack.
 * LIFO: last in, first out.
 */
class Stack {
  #items = [];

  /** Push a value onto the stack. O(1) amortized. */
  push(value) {
    this.#items.push(value);
  }

  /** Remove and return the top value. O(1). Throws if empty. */
  pop() {
    if (this.isEmpty()) throw new Error("Stack underflow");
    return this.#items.pop();
  }

  /** Peek at the top without removing. O(1). */
  peek() {
    if (this.isEmpty()) throw new Error("Stack is empty");
    return this.#items[this.#items.length - 1];
  }

  isEmpty() {
    return this.#items.length === 0;
  }

  size() {
    return this.#items.length;
  }

  /** For debugging / iteration (top -> bottom). */
  toArray() {
    return [...this.#items].reverse();
  }
}
```

### Min-Heap (binary heap)

```js
/**
 * Binary min-heap backed by an array.
 * Parent of i: floor((i-1)/2)
 * Left child: 2*i + 1
 * Right child: 2*i + 2
 */
class MinHeap {
  #heap = [];

  size() {
    return this.#heap.length;
  }

  isEmpty() {
    return this.#heap.length === 0;
  }

  peek() {
    if (this.isEmpty()) throw new Error("Heap is empty");
    return this.#heap[0];
  }

  /** Insert value and restore heap property. O(log n). */
  push(value) {
    this.#heap.push(value);
    this.#siftUp(this.#heap.length - 1);
  }

  /** Remove and return the minimum. O(log n). */
  pop() {
    if (this.isEmpty()) throw new Error("Heap underflow");
    const min = this.#heap[0];
    const last = this.#heap.pop();
    if (!this.isEmpty()) {
      this.#heap[0] = last;
      this.#siftDown(0);
    }
    return min;
  }

  // --- internals ---

  #siftUp(index) {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (this.#heap[parent] <= this.#heap[index]) break;
      [this.#heap[parent], this.#heap[index]] = [this.#heap[index], this.#heap[parent]];
      index = parent;
    }
  }

  #siftDown(index) {
    const n = this.#heap.length;
    while (true) {
      const left = 2 * index + 1;
      const right = 2 * index + 2;
      let smallest = index;

      if (left < n && this.#heap[left] < this.#heap[smallest]) smallest = left;
      if (right < n && this.#heap[right] < this.#heap[smallest]) smallest = right;

      if (smallest === index) break;
      [this.#heap[index], this.#heap[smallest]] = [this.#heap[smallest], this.#heap[index]];
      index = smallest;
    }
  }
}
```

### Optional: Max-Heap via comparator (more reusable)

```js
/**
 * Generic heap with a comparator. compar(a,b) < 0 means a has higher priority.
 * Min-heap: (a,b) => a - b
 * Max-heap: (a,b) => b - a
 */
class Heap {
  #heap = [];
  #compar;

  constructor(compar = (a, b) => a - b) {
    this.#compar = compar;
  }

  size() { return this.#heap.length; }
  isEmpty() { return this.#heap.length === 0; }

  peek() {
    if (this.isEmpty()) throw new Error("Heap is empty");
    return this.#heap[0];
  }

  push(value) {
    this.#heap.push(value);
    this.#siftUp(this.#heap.length - 1);
  }

  pop() {
    if (this.isEmpty()) throw new Error("Heap underflow");
    const top = this.#heap[0];
    const last = this.#heap.pop();
    if (!this.isEmpty()) {
      this.#heap[0] = last;
      this.#siftDown(0);
    }
    return top;
  }

  #siftUp(i) {
    while (i > 0) {
      const p = Math.floor((i - 1) / 2);
      if (this.#compar(this.#heap[p], this.#heap[i]) <= 0) break;
      [this.#heap[p], this.#heap[i]] = [this.#heap[i], this.#heap[p]];
      i = p;
    }
  }

  #siftDown(i) {
    const n = this.#heap.length;
    while (true) {
      const l = 2 * i + 1, r = 2 * i + 2;
      let best = i;
      if (l < n && this.#compar(this.#heap[l], this.#heap[best]) < 0) best = l;
      if (r < n && this.#compar(this.#heap[r], this.#heap[best]) < 0) best = r;
      if (best === i) break;
      [this.#heap[i], this.#heap[best]] = [this.#heap[best], this.#heap[i]];
      i = best;
    }
  }
}
```

### Quick sanity check

```js
const s = new Stack();
s.push(1); s.push(2);
console.log(s.pop()); // 2
console.log(s.peek()); // 1

const h = new MinHeap();
[5, 3, 8, 1].forEach(v => h.push(v));
console.log(h.pop(), h.pop(), h.pop(), h.pop()); // 1 3 5 8

const maxH = new Heap((a, b) => b - a);
[5, 3, 8, 1].forEach(v => maxH.push(v));
console.log(maxH.pop()); // 8
```

### Complexity summary
| Operation | Stack (array) | Binary Heap |
|---|---|---|
| push | O(1) amortized | O(log n) |
| pop | O(1) | O(log n) |
| peek/top | O(1) | O(1) |
| search | O(n) | O(n) |

### Interview tips
- Mention **stack overflow** vs **heap exhaustion** (`out of memory`).
- When asked “is `Array.prototype.push/pop` a stack?” → yes, amortized O(1); but not fixed-size.
- When asked for a heap, clarify **min vs max** and whether you need **decrease-key** (not included here; would require an index map).
- For priority queues in real code, prefer well-tested libraries or `heap-js`; custom heaps shine in algorithm interviews (Dijkstra, top-K, median maintenance).

JavaScript does not expose a literal “stack” or “heap” API. In practice, the distinction shows up as **value semantics for primitives** and **reference semantics for objects/functions**. Most edge cases come from closures, shared mutable objects, garbage-collection timing, and engine limits.

Below are common edge cases with idiomatic fixes.

---

## 1. Call stack overflow from recursion

Deep recursion can exceed the engine’s maximum call stack size. Tail recursion is **not guaranteed** to be optimized in JavaScript.

```js
function sumTo(n) {
  if (n <= 0) return 0;
  return n + sumTo(n - 1); // grows the call stack
}

try {
  sumTo(100_000);
} catch (err) {
  console.error(err.name); // RangeError: Maximum call stack size exceeded
}

// Prefer iteration
function sumToIterative(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) total += i;
  return total;
}
```

---

## 2. Closures capturing variables by reference

A closure captures the **variable binding**, not a copy of its value at creation time.

```js
const handlers = [];

for (var i = 0; i < 3; i++) {
  handlers.push(() => console.log(i));
}

handlers.forEach(h => h()); // 3, 3, 3

// Fix: block-scoped binding
const handlers2 = [];
for (let i = 0; i < 3; i++) {
  handlers2.push(() => console.log(i));
}
handlers2.forEach(h => h()); // 0, 1, 2
```

---

## 3. Shared heap mutation and shallow copies

Objects are references. Spreading creates only a **shallow** copy.

```js
const original = {
  user: { name: 'Ada' },
  tags: ['js'],
};

const shallow = { ...original };

shallow.user.name = 'Grace';
shallow.tags.push('heap');

console.log(original.user.name); // "Grace"
console.log(original.tags);      // ["js", "heap"]

// Deep clone for structured data
const deep = structuredClone(original);
deep.user.name = 'Linus';
deep.tags.push('clone');

console.log(original.user.name); // "Grace"
console.log(original.tags);      // ["js", "heap"]
```

Edge case: `structuredClone()` cannot clone functions, DOM nodes, or some host objects.

```js
structuredClone({ fn() {} }); // throws DataCloneError
```

---

## 4. JSON serialization limits

`JSON.stringify` drops or transforms many heap values.

```js
const value = {
  date: new Date(),
  regex: /abc/g,
  fn() {},
  undef: undefined,
  big: 123n,          // BigInt throws in modern engines
  circular: null,
};
value.circular = value;

console.log(JSON.stringify(value));
// Dates become strings, RegExp becomes {}, functions/undefined omitted
// BigInt throws: TypeError: Do not know how to serialize a BigInt
// Circular structure throws: TypeError: Converting circular structure to JSON

// Safer cloning for supported structured types
const clone = structuredClone({ date: new Date(), map: new Map([['a', 1]]) });
```

---

## 5. Memory leaks through retained references

Garbage collection only removes unreachable objects. Common leak sources:

```js
// A: closure retaining a large array
function createReader() {
  const huge = new Array(10_000_000).fill('x');
  return () => huge.length; // huge remains reachable
}
let read = createReader();
read = null; // allow collection if no other references

// B: event listener not removed
const onClick = () => console.log('clicked');
button.addEventListener('click', onClick);
button.removeEventListener('click', onClick); // must use same reference

// C: timer not cleared
const id = setInterval(() => {}, 1000);
clearInterval(id);

// D: detached DOM node still referenced
let node = document.createElement('div');
document.body.append(node);
document.body.removeChild(node);
node = null; // remove last reference
```

---

## 6. Weak references and finalizers are non-deterministic

Do not use `WeakRef` or `FinalizationRegistry` for correctness-critical cleanup.

```js
let target = { payload: 'large' };
const ref = new WeakRef(target);

target = null; // object may be collected later

const value = ref.deref();
if (value) {
  console.log(value.payload);
} else {
  console.log('already collected');
}

const registry = new FinalizationRegistry((heldValue) => {
  console.log('finalized:', heldValue);
});

let obj = {};
registry.register(obj, 'my-object');
obj = null; // callback may run later, or not at all during process lifetime
```

---

## 7. Numeric edge cases

```js
console.log(0.1 + 0.2 === 0.3); // false
console.log(Number.MAX_SAFE_INTEGER + 1 === Number.MAX_SAFE_INTEGER + 2); // true

// Use BigInt for exact integers
const big = 9007199254740991n + 1n;

// Mixing Number and BigInt throws
// 1n + 1; // TypeError

// NaN comparisons
console.log(NaN === NaN);          // false
console.log(Number.isNaN(NaN));    // true
console.log(isNaN('abc'));         // true, because of coercion; avoid

// -0 vs 0
console.log(-0 === 0);            // true
console.log(Object.is(-0, 0));    // false
console.log(JSON.stringify(-0));  // "0"
```

---

## 8. Typed arrays and buffer transfer

Typed arrays are views over heap-allocated `ArrayBuffer`s. Mutating one view affects others sharing the same buffer.

```js
const buffer = new ArrayBuffer(8);
const view1 = new Uint8Array(buffer);
const view2 = new DataView(buffer);

view1[0] = 255;
console.log(view2.getUint8(0)); // 255

// Transferring detaches the original buffer
const transferred = buffer.transfer(); // modern engines
console.log(buffer.byteLength);        // 0
console.log(transferred.byteLength);   // 8
```

For compatibility, copy with `buffer.slice(0)` or use `structuredClone(buffer, { transfer: [buffer] })`.

---

## 9. Array holes and sparse arrays

Holes are not the same as `undefined` values in some operations.

```js
const sparse = [1, , 3];

console.log(sparse[1]); // undefined
console.log(1 in sparse); // false, it's a hole

const mapped = sparse.map(n => n * 2);
console.log(mapped); // [2, <1 empty item>, 6]

// Normalize holes before processing
const normalized = Array.from(sparse, n => (n ?? 0) * 2);
console.log(normalized); // [2, 0, 6]
```

---

## 10. Object key coercion and prototype risks

Object keys are coerced to strings or symbols. `Map` preserves key identity.

```js
const obj = {};
obj[{}] = 'value';
console.log(Object.keys(obj)); // ["[object Object]"]

const map = new Map();
map.set({}, 1);
map.set({}, 2);
console.log(map.size); // 2
```

Avoid prototype pollution when merging untrusted data.

```js
function safeAssign(target, source) {
  for (const key of Object.keys(source)) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue;
    target[key] = source[key];
  }
  return target;
}

// Even safer for arbitrary keys:
const safe = new Map();
```

---

## 11. Shallow freeze is not deep

`Object.freeze` prevents top-level changes only.

```js
const config = Object.freeze({
  api: { timeout: 1000 },
});

config.api = {};        // TypeError in strict mode
config.api.timeout = 2000; // succeeds, nested object is not frozen

function deepFreeze(value) {
  if (value && typeof value === 'object') {
    Object.freeze(value);
    for (const key of Object.keys(value)) {
      deepFreeze(value[key]);
    }
  }
  return value;
}
```

---

## 12. Hoisting and temporal dead zone

```js
console.log(varValue); // undefined
var varValue = 1;

// console.log(letValue); // ReferenceError: Cannot access before initialization
let letValue = 2;

// Closure over a TDZ variable can throw if called too early
const read = () => value;
// read(); // ReferenceError if called before declaration below
let value = 42;
console.log(read()); // 42
```

---

## 13. `arguments` aliasing in non-strict functions

```js
function legacy(a) {
  arguments[0] = 99;
  return a; // 99 in non-strict mode
}

function modern(a) {
  'use strict';
  arguments[0] = 99;
  return a; // original a
}
```

Prefer rest parameters:

```js
function modern2(...args) {
  return args[0];
}
```

---

## 14. Destructuring defaults do not catch `null`

Defaults apply only when the value is `undefined`, not `null`.

```js
const { timeout = 3000 } = { timeout: null };
console.log(timeout); // null

// Explicit fallback
const { timeout: t = 3000 } = { timeout: null };
const finalTimeout = t ?? 3000;
```

---

## 15. `this` binding edge cases

```js
const counter = {
  value: 0,
  increment() {
    this.value++;
  },
};

const increment = counter.increment;
// increment(); // TypeError in strict mode: Cannot read properties of undefined

// Fix with bound function
const boundIncrement = counter.increment.bind(counter);
boundIncrement();
console.log(counter.value); // 1

// Arrow functions retain lexical `this`
const obj = {
  value: 42,
  getValue: () => this.value, // usually wrong for methods
};
```

---

## 16. Async shared-state races

JavaScript is single-threaded, but `await` yields control. Shared heap state can be modified between suspension points.

```js
let balance = 100;

function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function withdraw(amount) {
  const current = balance;
  await delay(10);
  balance = current - amount; // lost update possible
}

await Promise.all([withdraw(30), withdraw(40)]);
console.log(balance); // often 60 or 70, not 30

// Safer: update synchronously before awaiting external work
async function withdrawSafe(amount) {
  balance -= amount;
  await delay(10);
  return balance;
}
```

---

## 17. Unhandled promise rejections

```js
async function main() {
  throw new Error('boom');
}

main(); // unhandled rejection in many environments

// Handle explicitly
main().catch(err => console.error(err));
```

---

## Practical checklist

- Treat primitives as values and objects as references.
- Normalize input with `structuredClone`, `Array.from`, or explicit validation.
- Avoid retaining closures, timers, listeners, or detached DOM nodes.
- Use `Map`/`Set` for arbitrary keys, not plain objects.
- Use `BigInt` for exact large integers and `Number.isNaN` for NaN.
- Deep-freeze config only if nested mutation must be prevented.
- Do not rely on GC timing for correctness.
- Bound or arrow-function `this` deliberately.
- Avoid `var` hoisting surprises; handle TDZ errors.
- Serialize with awareness of what `JSON.stringify` drops.

# Stacks and Queues in JavaScript

Below is a complete, runnable implementation. It includes:

- **`Stack`** — LIFO, array-backed, O(1) amortized `push`/`pop`.
- **`Queue`** — FIFO, backed by a **circular buffer** with dynamic resizing, O(1) amortized `enqueue`/`dequeue` (avoids the O(n) cost of `Array.shift()`).
- **`Deque`** — double-ended queue, useful as the building block for both.
- A small **demo + mini test suite** and a **benchmark**.

Save as `ds.js` and run with `node ds.js`.

---

## 1. Stack

```js
// stack.js
class Stack {
  #items = [];

  push(value) {
    this.#items.push(value);
    return this; // chainable
  }

  pop() {
    return this.#items.pop(); // undefined if empty (like Array)
  }

  peek() {
    return this.#items.length ? this.#items[this.#items.length - 1] : undefined;
  }

  get size() { return this.#items.length; }
  isEmpty() { return this.#items.length === 0; }

  clear() { this.#items.length = 0; return this; }

  toArray() { return [...this.#items]; } // bottom -> top

  // Iterate top -> bottom (most useful for a stack)
  *[Symbol.iterator]() {
    for (let i = this.#items.length - 1; i >= 0; i--) yield this.#items[i];
  }

  toString() { return `Stack(${this.#items.length}) [${this.#items.join(', ')}]`; }
}

module.exports = { Stack };
```

**Why this is good:** `push`/`pop` at the end of a JS array are O(1) amortized (engine may occasionally grow the backing store). No shifting, no copying.

---

## 2. Queue (circular buffer)

The naive `queue.push(x); queue.shift()` is **O(n)** per dequeue because every element moves. The circular buffer below keeps `head`/`tail` pointers and grows/shrinks in powers of two.

```js
// queue.js
class Queue {
  #buf;
  #head = 0;
  #tail = 0;
  #size = 0;
  #cap;

  constructor(initialCapacity = 8) {
    if (!Number.isInteger(initialCapacity) || initialCapacity < 1) {
      throw new RangeError('initialCapacity must be a positive integer');
    }
    this.#cap = 1;
    while (this.#cap < initialCapacity) this.#cap <<= 1;
    this.#buf = new Array(this.#cap);
  }

  #resize(newCap) {
    const next = new Array(newCap);
    for (let i = 0; i < this.#size; i++) {
      next[i] = this.#buf[(this.#head + i) % this.#cap];
    }
    this.#buf = next;
    this.#head = 0;
    this.#tail = this.#size % newCap;
    this.#cap = newCap;
  }

  enqueue(value) {
    if (this.#size === this.#cap) this.#resize(this.#cap << 1);
    this.#buf[this.#tail] = value;
    this.#tail = (this.#tail + 1) % this.#cap;
    this.#size++;
    return this;
  }

  dequeue() {
    if (this.#size === 0) return undefined;
    const value = this.#buf[this.#head];
    this.#buf[this.#head] = undefined; // help GC
    this.#head = (this.#head + 1) % this.#cap;
    this.#size--;
    // Shrink when mostly empty (keep a floor to avoid thrashing).
    if (this.#size > 0 && this.#size <= this.#cap >> 2 && this.#cap > 8) {
      this.#resize(Math.max(8, this.#cap >> 1));
    }
    return value;
  }

  peek() { return this.#size ? this.#buf[this.#head] : undefined; }

  get size() { return this.#size; }
  get capacity() { return this.#cap; }
  isEmpty() { return this.#size === 0; }

  clear() {
    this.#buf = new Array(this.#cap);
    this.#head = this.#tail = this.#size = 0;
    return this;
  }

  toArray() {
    const out = new Array(this.#size);
    for (let i = 0; i < this.#size; i++) out[i] = this.#buf[(this.#head + i) % this.#cap];
    return out;
  }

  *[Symbol.iterator]() {
    for (let i = 0; i < this.#size; i++) yield this.#buf[(this.#head + i) % this.#cap];
  }

  toString() { return `Queue(${this.#size}/${this.#cap}) [${this.toArray().join(', ')}]`; }
}

module.exports = { ...(module.exports || {}), Queue };
```

**Invariants maintained:**
- `0 <= size <= cap`
- `head, tail` always valid indices in `[0, cap)`
- When `size === cap`, we grow before writing, so we never overwrite live data.
- Shrink only when `size <= cap/4` (amortizes), and never below 8 slots.

