## 3. Deque (double-ended queue)

A deque supports push/pop at **both** ends in O(1) amortized. It is the natural generalization and is what you'd use to implement a sliding-window or monotonic queue.

```js
// deque.js
class Deque {
  #buf; #head; #tail; #size; #cap;

  constructor(initialCapacity = 8) {
    this.#cap = 1;
    while (this.#cap < initialCapacity) this.#cap <<= 1;
    this.#buf = new Array(this.#cap);
    this.#head = 0; this.#tail = 0; this.#size = 0;
  }

  #resize(newCap) {
    const next = new Array(newCap);
    for (let i = 0; i < this.#size; i++) next[i] = this.#buf[(this.#head + i) % this.#cap];
    this.#buf = next; this.#head = 0; this.#tail = this.#size % newCap; this.#cap = newCap;
  }

  pushBack(v)  { return this.#push(v, 'back'); }
  pushFront(v) { return this.#push(v, 'front'); }

  #push(v, side) {
    if (this.#size === this.#cap) this.#resize(this.#cap << 1);
    if (side === 'back') {
      this.#buf[this.#tail] = v;
      this.#tail = (this.#tail + 1) % this.#cap;
    } else {
      this.#head = (this.#head - 1 + this.#cap) % this.#cap;
      this.#buf[this.#head] = v;
    }
    this.#size++;
    return this;
  }

  popBack()  { return this.#pop('back'); }
  popFront() { return this.#pop('front'); }

  #pop(side) {
    if (this.#size === 0) return undefined;
    let v;
    if (side === 'back') {
      this.#tail = (this.#tail - 1 + this.#cap) % this.#cap;
      v = this.#buf[this.#tail];
      this.#buf[this.#tail] = undefined;
    } else {
      v = this.#buf[this.#head];
      this.#buf[this.#head] = undefined;
      this.#head = (this.#head + 1) % this.#cap;
    }
    this.#size--;
    if (this.#size > 0 && this.#size <= this.#cap >> 2 && this.#cap > 8) {
      this.#resize(Math.max(8, this.#cap >> 1));
    }
    return v;
  }

  peekFront() { return this.#size ? this.#buf[this.#head] : undefined; }
  peekBack()  { return this.#size ? this.#buf[(this.#tail - 1 + this.#cap) % this.#cap] : undefined; }

  get size() { return this.#size; }
  isEmpty() { return this.#size === 0; }

  toArray() {
    const out = new Array(this.#size);
    for (let i = 0; i < this.#size; i++) out[i] = this.#buf[(this.#head + i) % this.#cap];
    return out;
  }
  *[Symbol.iterator]() { for (const v of this.toArray()) yield v; }
  toString() { return `Deque(${this.#size}) [${this.toArray().join(', ')}]`; }
}

module.exports = { ...(module.exports || {}), Deque };
```

