}

const N = 2_000_000;
bench('Stack push+pop', (n) => { const s = new Stack(); for (let i=0;i<n;i++) s.push(i); for (let i=0;i<n;i++) s.pop(); }, N);
bench('Queue enqueue+dequeue (circular)', (n) => { const q = new Queue(); for (let i=0;i<n;i++) q.enqueue(i); for (let i=0;i<n;i++) q.dequeue(); }, N);
bench('Naive array queue (shift)', (n) => { const a=[]; for (let i=0;i<n;i++) a.push(i); for (let i=0;i<n;i++) a.shift(); }, 200_000);

