## 4. Short, realistic examples

### A. Typed React component (TSX)

```tsx
interface ButtonProps {
  label: string;
  onClick: () => void;
  disabled?: boolean;
}

export function Button({ label, onClick, disabled = false }: ButtonProps) {
  return <button onClick={onClick} disabled={disabled}>{label}</button>;
}
```

### B. Typed API fetch with a generic helper

```ts
async function getJson<T>(url: string): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(res.statusText);
  return res.json() as Promise<T>;
}

interface Post { id: number; title: string }

const posts = await getJson<Post[]>("/api/posts");
// posts is Post[] — autocomplete works
```

### C. Discriminated union (exhaustive state handling)

```ts
type State =
  | { status: "loading" }
  | { status: "success"; data: string }
  | { status: "error"; message: string };

function render(s: State): string {
  switch (s.status) {
    case "loading": return "…";
    case "success": return s.data;
    case "error":   return s.message;
    default:        return assertNever(s); // compile error if a case is missing
  }
}

function assertNever(x: never): never {
  throw new Error("Unexpected: " + x);
}
```

### D. Runtime validation boundary (TS + Zod)

```ts
import { z } from "zod";

const UserSchema = z.object({
  id: z.number(),
  email: z.string().email(),
});

type User = z.infer<typeof UserSchema>;

async function loadUser(raw: unknown): Promise<User> {
  return UserSchema.parse(raw); // throws if shape is wrong
}
```

