## 8. Full Tiny Example: Summary Report

```js
function summarize(arr) {
  if (!arr.length) return null;
  const sorted = [...arr].sort((a, b) => a - b);
  const sum = arr.reduce((a, b) => a + b, 0);
  const mean = sum / arr.length;
  const mid = Math.floor(sorted.length / 2);
  const median = sorted.length % 2
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2;
  const variance = arr.reduce((acc, x) => acc + (x - mean) ** 2, 0) / arr.length;
  return {
    count: arr.length,
    min: sorted[0],
    max: sorted[sorted.length - 1],
    sum,
    mean: +mean.toFixed(3),
    median,
    stdDev: +Math.sqrt(variance).toFixed(3)
  };
}

console.log(summarize([4, 8, 6, 5, 3, 2, 8, 9, 2, 5]));
```

---

### Key Takeaways

- Use **`Math`** for scalar math, rounding, trig, random.
- Implement **statistics manually** only for simple cases; use **libraries** for anything serious.
- Watch **floating-point**, **safe integer limits**, and **stack limits** with spread operators.
- Prefer **`crypto.getRandomValues`** for security-sensitive randomness.

## Typical mistake: using the population formula for a *sample* standard deviation

### Mistaken version

```js
function sampleStdDev(values) {
  const n = values.length;
  const mean = values.reduce((a, b) => a + b, 0) / n;

  // BUG: divides by n, which is the population variance formula
  const variance = values.reduce((sum, x) => sum + (x - mean) ** 2, 0) / n;

  return Math.sqrt(variance);
}

const data = [2, 4, 4, 4, 5, 5, 7, 9];
console.log(sampleStdDev(data)); // 2.0  (too small for a sample)
```

### Corrected version

```js
function sampleStdDev(values) {
  const n = values.length;

  if (n < 2) {
    // A sample standard deviation is undefined for fewer than 2 observations.
    return NaN;
  }

  const mean = values.reduce((a, b) => a + b, 0) / n;

  // Use n - 1 (Bessel's correction) for an unbiased sample variance estimate.
  const variance = values.reduce((sum, x) => sum + (x - mean) ** 2, 0) / (n - 1);

  return Math.sqrt(variance);
}

const data = [2, 4, 4, 4, 5, 5, 7, 9];
console.log(sampleStdDev(data)); // 2.138089935299395
```

### What was wrong and why

1. **Population vs. sample variance**
   - Dividing the sum of squared deviations by `n` gives the **population variance**. That is correct only when `values` contains *every* member of the population.
   - When `values` is a **sample** drawn from a larger population, dividing by `n` systematically underestimates the true population variance. The sample mean is fitted to the sample, so squared deviations are, on average, too small.

2. **Bessel’s correction**
   - Using `n - 1` in the denominator compensates for the fact that the sample mean is estimated from the same data. This produces an **unbiased estimator** of the population variance: on average, it equals the true variance.
   - The correction matters most for small samples. For large `n`, `n` and `n - 1` are nearly the same, but for small datasets the difference is substantial.

3. **Edge case**
   - With `n === 1`, division by `n - 1` would be division by zero, producing `Infinity` or `NaN` depending on the numerator. Explicitly returning `NaN` for `n < 2` makes the function’s contract clear and avoids misleading results.

4. **Floating-point note**
   - For very large datasets or values with many digits, catastrophic cancellation can occur in the naive two-pass formula above. In production code, consider a numerically stable algorithm such as Welford’s online algorithm:

```js
function sampleStdDevStable(values) {
  const n = values.length;
  if (n < 2) return NaN;

  let mean = 0;
  let m2 = 0;

  for (let i = 0; i < n; i++) {
    const x = values[i];
    const delta = x - mean;
    mean += delta / (i + 1);
    const delta2 = x - mean;
    m2 += delta * delta2;
  }

  return Math.sqrt(m2 / (n - 1));
}
```

### Summary

The core mistake was treating a sample as if it were the entire population. In statistics, the denominator must reflect whether you are describing observed data (`n`) or estimating an unknown population parameter from a sample (`n - 1`).

Below are common pitfalls when doing statistics/math in JavaScript, with runnable examples and safer patterns.

## 1. Floating-point representation (`0.1 + 0.2 !== 0.3`)

JavaScript numbers are IEEE-754 doubles. Many decimal values cannot be represented exactly.

```js
console.log(0.1 + 0.2);        // 0.30000000000000004
console.log(0.1 + 0.2 === 0.3); // false

// Safer: tolerance comparison
function approxEqual(a, b, eps = 1e-9) {
  return Math.abs(a - b) <= eps * Math.max(1, Math.abs(a), Math.abs(b));
}
console.log(approxEqual(0.1 + 0.2, 0.3)); // true

// For money/statistics, use scaled integers or a decimal library
const cents = 10 + 20; // work in cents
console.log(cents / 100); // 0.3
```

## 2. Integer overflow beyond `Number.MAX_SAFE_INTEGER`

```js
console.log(Number.MAX_SAFE_INTEGER); // 9007199254740991
const id = 9007199254740992;
console.log(id + 1 === id); // true (lost precision)

// Use BigInt for exact large integers
const big = 9007199254740993n;
console.log(big + 1n); // 9007199254740994n

// Pitfall: BigInt doesn't mix with Number math functions
// Math.sqrt(16n) // TypeError
console.log(Math.sqrt(Number(16n))); // 4
```

## 3. `NaN`, `Infinity`, and `-0` propagation

```js
console.log(0 / 0);          // NaN
console.log(1 / 0);          // Infinity
console.log(-1 / 0);         // -Infinity
console.log(Math.sqrt(-1));  // NaN

// NaN poisons aggregates
const data = [1, 2, NaN, 4];
console.log(data.reduce((a, b) => a + b, 0)); // NaN

// Filter/validate first
function cleanNumbers(arr) {
  return arr.filter(x => typeof x === "number" && Number.isFinite(x));
}
console.log(cleanNumbers(data).reduce((a, b) => a + b, 0)); // 7

// Negative zero
console.log(1 / -Infinity); // -0
console.log(Object.is(-0, 0)); // false
console.log(-0 === 0);        // true
```

## 4. Trig functions use **radians**, not degrees

A very common source of wrong results.

```js
console.log(Math.sin(90)); // 0.893996... (radians), not 1

function sinDeg(deg) {
  return Math.sin(deg * Math.PI / 180);
}
console.log(sinDeg(90)); // 1
```

## 5. Default `Array.prototype.sort()` sorts lexicographically

```js
const nums = [10, 2, 1, 20];
console.log(nums.sort()); // [1, 10, 2, 20]

// Fix: numeric comparator
const sorted = [...nums].sort((a, b) => a - b);
console.log(sorted); // [1, 2, 10, 20]

// Better for large/float values (avoids subtraction overflow/NaN)
const safeSorted = [...nums].sort((a, b) => Math.sign(a - b));
```

## 6. `Math.min` / `Math.max` with empty arrays

```js
console.log(Math.min());  // Infinity
console.log(Math.max());  // -Infinity

const empty = [];
console.log(Math.min(...empty)); // Infinity (often unexpected)

function safeMin(arr) {
  if (!arr.length) return null;
  return Math.min(...arr);
}
```

## 7. `reduce` without an initial value

```js
const arr = [];
console.log(arr.reduce((a, b) => a + b)); // TypeError: Reduce of empty array with no initial value

// Always provide initial value
console.log(arr.reduce((a, b) => a + b, 0)); // 0

// Also: single-element arrays behave differently without initial
console.log([5].reduce((a, b) => a + b)); // 5 (no function call semantics issues here, but empty breaks)
```

## 8. Population vs sample standard deviation

Many libraries/examples use the wrong denominator.

```js
function mean(arr) {
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

function variance(arr, sample = false) {
  const m = mean(arr);
  const sq = arr.reduce((s, x) => s + (x - m) ** 2, 0);
  return sq / (sample ? arr.length - 1 : arr.length);
}

function stdDev(arr, sample = false) {
  return Math.sqrt(variance(arr, sample));
}

const data = [2, 4, 4, 4, 5, 5, 7, 9];
console.log("population:", stdDev(data, false)); // ~2.0
console.log("sample:", stdDev(data, true));       // ~2.138
```

Pitfall: with one data point, sample variance divides by zero → `Infinity`/`NaN`.

## 9. Percentile/quartile definitions are not standardized

Different tools use different interpolation methods.

```js
function percentile(sorted, p) {
  // Linear interpolation between closest ranks (common "inclusive" method)
  if (!sorted.length) return NaN;
  const pos = (sorted.length - 1) * p;
  const base = Math.floor(pos);
  const rest = pos - base;
  if (sorted[base + 1] !== undefined) {
    return sorted[base] + rest * (sorted[base + 1] - sorted[base]);
  }
  return sorted[base];
}

const s = [1, 2, 3, 4, 5, 6, 7, 8];
console.log(percentile(s, 0.25)); // 2.75 (method-dependent)
```

Always document which method you use; results differ from Excel/Python/numpy defaults.

## 10. Correlation with zero variance → division by zero

```js
function pearson(x, y) {
  const n = x.length;
  const mx = mean(x), my = mean(y);
  let num = 0, dx = 0, dy = 0;
  for (let i = 0; i < n; i++) {
    const a = x[i] - mx, b = y[i] - my;
    num += a * b;
    dx += a * a;
    dy += b * b;
  }
  const denom = Math.sqrt(dx * dy);
  if (denom === 0) return NaN; // or 0 depending on convention
  return num / denom;
}

console.log(pearson([1,1,1], [2,3,4])); // NaN
```

## 11. `Math.random()` is not cryptographically secure

Also, naive range mapping can introduce bias.

```js
// Not secure
console.log(Math.random());

// Secure (browser/Node)
function secureRandomInt(min, max) {
  const range = max - min + 1;
  const maxUint = 0xFFFFFFFF;
  const limit = maxUint - (maxUint % range);
  const buf = new Uint32Array(1);
  let v;
  do {
    crypto.getRandomValues(buf);
    v = buf[0];
  } while (v > limit);
  return min + (v % range);
}
// (In Node, use crypto.randomInt instead)
```

Bias example:

```js
// Biased if range doesn't divide 2^53
function biasedRandInt(max) {
  return Math.floor(Math.random() * max);
}
```

## 12. `toFixed()` returns a string and uses banker-ish/rounding quirks

```js
console.log((2.345).toFixed(2)); // "2.35" or "2.34" depending on representation
console.log(typeof (5).toFixed(2)); // "string"

// Parse back carefully
const n = Number((2.345).toFixed(2));
console.log(n); // 2.35 (maybe)
```

For exact decimal rounding, use integer math or a decimal library.

## 13. `parseInt` pitfalls (radix, leading zeros)

```js
console.log(parseInt("08"));     // 8 (modern), but historically octal in old engines
console.log(parseInt("10px"));   // 10 (stops at non-digit)
console.log(parseInt(""));       // NaN

// Always pass radix
console.log(parseInt("08", 10)); // 8
console.log(Number("08"));       // 8 (cleaner for full strings)
```

## 14. Summation precision for large datasets

Naive summation accumulates floating-point error.

```js
const big = Array(1_000_000).fill(0.1);
const naive = big.reduce((a, b) => a + b, 0);
console.log(naive); // ~100000.00000159 (error)

// Kahan summation
function kahanSum(arr) {
  let sum = 0, c = 0;
  for (const x of arr) {
    const y = x - c;
    const t = sum + y;
    c = (t - sum) - y;
    sum = t;
  }
  return sum;
}
console.log(kahanSum(big)); // closer to 100000
```

## 15. Locale-dependent number parsing

```js
console.log(Number("1,234.56")); // NaN (US format with comma)
console.log(Number("1.234,56")); // NaN (EU format)

// Use Intl or explicit normalization
function parseLocaleNumber(str, locale = "en-US") {
  const formatter = new Intl.NumberFormat(locale);
  const parts = formatter.formatToParts(1234.5);
  // Build a normalization based on decimal/group separators, or use a library
  return Number(str.replace(/\s/g, "").replace(/,/g, ""));
}
```

In production, prefer a dedicated parsing library or `Intl`-aware logic.

## 16. Modulo with negative numbers

```js
console.log(-1 % 5); // -1 (not 4)

// Mathematical modulo
function mod(a, n) {
  return ((a % n) + n) % n;
}
console.log(mod(-1, 5)); // 4
```

## 17. `Math.pow` vs `**` and large exponents

```js
console.log(2 ** 1024); // Infinity
console.log(Math.pow(2, 1024)); // Infinity

// For integer powers beyond safe range, use BigInt
console.log(2n ** 1024n); // exact huge integer
```

## 18. Outliers and mean sensitivity

```js
const incomes = [30000, 32000, 31000, 1_000_000];
const meanIncome = incomes.reduce((a,b)=>a+b,0)/incomes.length;
console.log(meanIncome); // 273250 (misleading)

// Prefer median for skewed data
function median(sorted) {
  const a = [...sorted].sort((x,y)=>x-y);
  const mid = Math.floor(a.length / 2);
  return a.length % 2 ? a[mid] : (a[mid-1]+a[mid])/2;
}
console.log(median(incomes)); // 31500
```

## 19. In-place mutation when sorting statistics

```js
function topK(arr, k) {
  return arr.sort((a,b)=>b-a).slice(0,k); // mutates input!
}
const original = [3,1,2];
console.log(topK(original,2)); // [3,2]
console.log(original);        // [3,2,1] (mutated)

// Clone first
function topKSafe(arr, k) {
  return [...arr].sort((a,b)=>b-a).slice(0,k);
}
```

## 20. Object keys for numeric indices / sparse arrays

```js
const counts = {};
counts[1.5] = 5; // key becomes "1.5" (string), fine but watch types
console.log(Object.keys(counts)); // ["1.5"]

// Sparse arrays break length-based stats
