Always validate arrays are dense and numeric.

---

### Practical checklist

- Validate with `Number.isFinite`, reject `NaN`/`Infinity`.
- Use tolerance comparisons, never `===` for floats.
- Sort with `(a,b) => a-b` or `Math.sign`.
- Use `BigInt` for exact large integers; never mix with `Number` math directly.
- Choose population vs sample variance explicitly.
- Document percentile method.
- Use Kahan summation for large aggregations.
- Clone arrays before sorting.
- Prefer median/robust stats for skewed data.
- Use secure RNG for security-sensitive randomness.

# Exercise: "Daily Sales Analyzer"

**Task:** Given an array of daily sales numbers, write a JavaScript function that computes a full statistical summary **and** demonstrates common `Math` utilities. Handle edge cases (empty input, single value, multiple modes, even/odd counts).

**Sample data:** `[120, 95, 130, 110, 95, 140, 125, 100, 135, 95, 115, 120]` (12 days).

---

## Step-by-step solution

### 1. Guard the input
Always validate before computing. An empty array would make mean/division undefined.

```js
if (!Array.isArray(data) || data.length === 0) {
  throw new Error('data must be a non-empty array of numbers');
}
```

### 2. Sort a copy (never mutate input)
Median/quartiles need sorted values; `sort()` mutates, so clone first.

```js
const sorted = [...data].sort((a, b) => a - b);
```

### 3. Central tendency
- **Sum** via `reduce`.
- **Mean** = sum / n.
- **Median**: middle value (odd n) or average of two middles (even n). `Math.floor(n/2)` picks the lower middle index.

### 4. Mode
Count frequencies with a `Map`, find the max count, collect all values matching it. If every value appears once, report `null` (no mode); if several tie, return an array.

### 5. Spread
- **Variance**: average of squared deviations. Population divides by `n`; sample divides by `n-1` (Bessel's correction).
- **Std dev** = `Math.sqrt(variance)`.
- **Range** = max − min (use sorted ends or `Math.max`/`Math.min` with spread).

### 6. Quartiles (linear interpolation)
A robust method: position = `(n-1) * p`, then interpolate between floor/ceil indices. This matches NumPy's default and avoids off-by-one surprises.

### 7. `Math` utilities demonstrated
`Math.floor`, `Math.ceil`, `Math.round`, `Math.sqrt`, `Math.pow`/`**`, `Math.abs`, `Math.max`, `Math.min`, `Math.random` (for generating a random sample).

### 8. Bonus: z-scores
Show how many standard deviations each point is from the mean: `(x - mean) / stdDev`.

---

## Final solution

```js
'use strict';

/**
 * Compute a full statistical summary of a numeric array.
 * @param {number[]} data
 * @returns {object}
 */
function analyze(data) {
  if (!Array.isArray(data) || data.length === 0) {
    throw new Error('data must be a non-empty array of numbers');
  }
  if (!data.every(Number.isFinite)) {
    throw new Error('all elements must be finite numbers');
  }

  const n = data.length;
  const sorted = [...data].sort((a, b) => a - b);

  // --- Central tendency ---
  const sum = data.reduce((acc, x) => acc + x, 0);
  const mean = sum / n;

  const mid = Math.floor(n / 2);
  const median = n % 2 === 1
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2;

  // Mode
  const freq = new Map();
  for (const x of data) freq.set(x, (freq.get(x) || 0) + 1);
  const maxFreq = Math.max(...freq.values());
  const modes = [...freq.entries()]
    .filter(([, c]) => c === maxFreq)
    .map(([v]) => v);
  const mode = maxFreq === 1
    ? null
    : (modes.length === 1 ? modes[0] : modes);

  // --- Spread ---
  const squaredDevs = data.map(x => Math.pow(x - mean, 2));
  const ss = squaredDevs.reduce((acc, x) => acc + x, 0); // sum of squares
  const popVariance = ss / n;
  const sampleVariance = n > 1 ? ss / (n - 1) : NaN;
  const popStdDev = Math.sqrt(popVariance);
  const sampleStdDev = Math.sqrt(sampleVariance);

  const min = sorted[0];
  const max = sorted[n - 1];
  const range = max - min;

  // --- Quartiles via linear interpolation ---
  function quantile(p) {
    if (n === 1) return sorted[0];
    const pos = (n - 1) * p;
    const lo = Math.floor(pos);
    const hi = Math.ceil(pos);
    if (lo === hi) return sorted[lo];
    return sorted[lo] + (sorted[hi] - sorted[lo]) * (pos - lo);
  }
  const q1 = quantile(0.25);
  const q3 = quantile(0.75);
  const iqr = q3 - q1;

  // --- Z-scores ---
  const zScores = data.map(x => (x - mean) / popStdDev);

  return {
    n, sum, mean, median, mode,
    min, max, range,
    populationVariance: popVariance,
    sampleVariance,
    populationStdDev: popStdDev,
    sampleStdDev,
    q1, q3, iqr,
    zScores,
  };
}

// ---------- Demo ----------
const sales = [120, 95, 130, 110, 95, 140, 125, 100, 135, 95, 115, 120];
console.log('Sales:', sales);
console.log(JSON.stringify(analyze(sales), null, 2));

// Demonstrate extra Math utilities
console.log('\nExtra Math demos:');
console.log('Math.round(mean-ish):', Math.round(12.345 * 100) / 100);
console.log('Math.abs(-7):', Math.abs(-7));
console.log('Math.max(...sales):', Math.max(...sales));
console.log('Math.min(...sales):', Math.min(...sales));
console.log('Math.ceil(4.2):', Math.ceil(4.2), 'Math.floor(4.9):', Math.floor(4.9));

// Generate a random sample using Math.random (uniform [0,1))
const randomSample = Array.from({ length: 5 }, () =>
  Math.round(Math.random() * 100)
);
console.log('Random sample:', randomSample);
console.log('Its stats:', analyze(randomSample));

// Edge cases
console.log('\nEdge cases:');
console.log(analyze([42]));                       // single value
console.log(analyze([1, 2, 3, 4]));               // no mode (all unique)
console.log(analyze([5, 5, 5, 5]));              // single mode
console.log(analyze([1, 1, 2, 2, 3]));           // bimodal -> [1, 2]
```

