### Key takeaways
- Always clone before `sort()` to avoid mutating inputs.
- Distinguish **population** vs **sample** variance (`n` vs `n-1`).
- Handle **multi-modal** data explicitly rather than silently picking one.
- Use **interpolation-based quantiles** for consistent, well-defined quartiles.
- Combine `Math` primitives (`sqrt`, `pow`, `floor`, `ceil`, `round`, `random`) to implement higher-level statistics cleanly.

## Interview-style answer

### 1. Explain the concepts first

In JavaScript, the built-in `Math` object gives us primitive math helpers:

- `Math.abs`, `Math.sign`
- `Math.floor`, `Math.ceil`, `Math.round`, `Math.trunc`
- `Math.min`, `Math.max`
- `Math.pow`, `Math.sqrt`, `Math.cbrt`
- `Math.log`, `Math.exp`
- `Math.random`
- `Math.PI`, `Math.E`

Statistics are not built into JS as a standard library, so we usually build them on top of arrays. The core ideas:

**Central tendency**
- **Mean**: average value. Sensitive to outliers.
- **Median**: middle value after sorting. Robust to outliers.
- **Mode**: most frequent value. Can have multiple modes.

**Dispersion**
- **Range**: `max - min`
- **Variance**: average squared distance from the mean
- **Standard deviation**: square root of variance
- **IQR**: `Q3 - Q1`, useful for outlier detection

**Important distinction**
- **Population variance**: divide by `n`
- **Sample variance**: divide by `n - 1`

**Numerical concerns**
- Floating-point addition can accumulate error, so use Kahan summation for `sum`.
- Welford’s algorithm is better for variance than “sum of squares”.
- Sorting dominates median/quartiles: `O(n log n)`.

---

### 2. Core implementation

```js
/**
 * statsMath.js
 * Small, dependency-free statistics + math utilities.
 *
 * Design notes:
 * - Inputs are never mutated.
 * - Finite numbers are required for statistical functions.
 * - Variance supports both population and sample formulas.
 */

const MAX_SAFE_FACTORIAL = 18; // 18! is still a safe integer; 19! is not.

/* ----------------------------- Validation ----------------------------- */

function assertArray(values, name = "values") {
  if (!Array.isArray(values)) {
    throw new TypeError(`${name} must be an array`);
  }
  if (values.length === 0) {
    throw new RangeError(`${name} must not be empty`);
  }
  for (const value of values) {
    if (typeof value !== "number" || !Number.isFinite(value)) {
      throw new TypeError(`${name} must contain only finite numbers`);
    }
  }
  return values;
}

function assertInteger(value, name = "value") {
  if (!Number.isInteger(value)) {
    throw new TypeError(`${name} must be an integer`);
  }
}

function assertNonNegativeInteger(value, name = "value") {
  assertInteger(value, name);
  if (value < 0) {
    throw new RangeError(`${name} must be non-negative`);
  }
}

function assertFiniteNumber(value, name = "value") {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new TypeError(`${name} must be a finite number`);
  }
}

/* ----------------------------- Statistics ----------------------------- */

/**
 * Kahan summation reduces floating-point accumulation error.
 * Time: O(n), Space: O(1)
 */
function sum(values) {
  assertArray(values);
  let total = 0;
  let compensation = 0;

  for (const x of values) {
    const y = x - compensation;
    const temporary = total + y;
    compensation = (temporary - total) - y;
    total = temporary;
  }

  return total;
}

/**
 * Arithmetic mean.
 * Time: O(n)
 */
function mean(values) {
  assertArray(values);
  return sum(values) / values.length;
}

/**
 * Median.
 * Time: O(n log n) because of sorting.
 */
function median(values) {
  assertArray(values);

  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);

  if (sorted.length % 2 === 1) {
    return sorted[middle];
  }

  return (sorted[middle - 1] + sorted[middle]) / 2;
}

/**
 * Mode(s).
 * Returns all values tied for highest frequency.
 * Returns [] when every value appears only once.
 * Time: O(n)
 */
function mode(values) {
  assertArray(values);

  const counts = new Map();
  for (const value of values) {
    counts.set(value, (counts.get(value) || 0) + 1);
  }

  let maxCount = 0;
  for (const count of counts.values()) {
    if (count > maxCount) maxCount = count;
  }

  // If no value repeats, there is no useful single mode.
  if (maxCount <= 1) return [];

  const modes = [];
  for (const [value, count] of counts.entries()) {
    if (count === maxCount) modes.push(value);
  }

  return modes.sort((a, b) => a - b);
}

/**
 * Population or sample variance using Welford's algorithm.
 * This is more numerically stable than summing squared deviations directly.
 *
 * Time: O(n), Space: O(1)
 */
function variance(values, { sample = false } = {}) {
  assertArray(values);

  let n = 0;
  let currentMean = 0;
  let m2 = 0; // sum of squared deviations

  for (const x of values) {
    n += 1;
    const delta = x - currentMean;
    currentMean += delta / n;
    const delta2 = x - currentMean;
    m2 += delta * delta2;
  }

  if (sample && n < 2) {
    throw new RangeError("Sample variance requires at least two values");
  }

  const denominator = sample ? n - 1 : n;
  return m2 / denominator;
}

/**
 * Standard deviation.
 */
function standardDeviation(values, options = {}) {
  return Math.sqrt(variance(values, options));
}

/**
 * Array min/max without spreading, so large arrays do not overflow the stack.
 */
function min(values) {
  assertArray(values);
  let result = values[0];
  for (let i = 1; i < values.length; i++) {
    if (values[i] < result) result = values[i];
  }
  return result;
}

function max(values) {
  assertArray(values);
  let result = values[0];
  for (let i = 1; i < values.length; i++) {
    if (values[i] > result) result = values[i];
  }
  return result;
}

/**
 * Range = max - min.
 */
function range(values) {
  assertArray(values);
  return max(values) - min(values);
}

/**
 * Quartiles using the "median of halves" method.
 * Returns an object with q1, median, q3, and iqr.
 */
function quartiles(values) {
  assertArray(values);

  const sorted = [...values].sort((a, b) => a - b);
  const n = sorted.length;

  if (n === 1) {
    const value = sorted[0];
    return { q1: value, median: value, q3: value, iqr: 0 };
  }

  const middle = Math.floor(n / 2);
  const lowerHalf = n % 2 === 0
    ? sorted.slice(0, middle)
    : sorted.slice(0, middle);
  const upperHalf = n % 2 === 0
    ? sorted.slice(middle)
    : sorted.slice(middle + 1);

  const q1 = median(lowerHalf);
  const med = median(sorted);
  const q3 = median(upperHalf);

  return {
    q1,
    median: med,
    q3,
    iqr: q3 - q1
  };
}

/* ----------------------------- Math utilities ----------------------------- */

function clamp(value, lower, upper) {
  assertFiniteNumber(value);
  assertFiniteNumber(lower);
  assertFiniteNumber(upper);

  if (lower > upper) {
    throw new RangeError("lower bound must not be greater than upper bound");
  }

  return Math.min(Math.max(value, lower), upper);
}

/**
 * Linear interpolation.
 * t = 0 returns a, t = 1 returns b.
 */
function lerp(a, b, t) {
  assertFiniteNumber(a);
  assertFiniteNumber(b);
  assertFiniteNumber(t);
  return a + (b - a) * t;
}

/**
 * Round to a fixed number of decimal places.
 * Note: binary floating point may still produce values such as 1.0000000000000002.
 */
function roundTo(value, decimals) {
  assertFiniteNumber(value);
  assertInteger(decimals);
  if (decimals < 0) {
    throw new RangeError("decimals must be non-negative");
  }

  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

/**
 * Greatest common divisor for integers.
 * gcd(0, 0) returns 0.
 */
function gcd(a, b) {
  assertInteger(a);
  assertInteger(b);

  a = Math.abs(a);
  b = Math.abs(b);

  while (b !== 0) {
    const temporary = b;
    b = a % b;
    a = temporary;
  }

  return a;
}

/**
 * Least common multiple.
 */
function lcm(a, b) {
  assertInteger(a);
  assertInteger(b);

  if (a === 0 || b === 0) return 0;

  const divisor = gcd(a, b);
  return Math.abs((a / divisor) * b);
}

/**
 * Trial-division primality test.
 * Good for small and medium integers; not suitable for cryptographic-size numbers.
 */
function isPrime(n) {
  assertInteger(n);
  if (n < 2) return false;
  if (n === 2) return true;
  if (n % 2 === 0) return false;

  for (let i = 3; i * i <= n; i += 2) {
    if (n % i === 0) return false;
  }

  return true;
}

/**
 * Factorial for reasonably small n.
 * Limited to safe integers to avoid silent precision loss.
 */
function factorial(n) {
  assertNonNegativeInteger(n);

  if (n > MAX_SAFE_FACTORIAL) {
    throw new RangeError(
      `factorial is only supported up to ${MAX_SAFE_FACTORIAL} for safe integers`
    );
  }

  let result = 1;
  for (let i = 2; i <= n; i++) {
    result *= i;
  }
  return result;
}

/**
 * Exact factorial using BigInt.
 * Useful when exact large values are needed.
 */
function factorialBigInt(n) {
  assertNonNegativeInteger(n);

  let result = 1n;
  for (let i = 2n; i <= BigInt(n); i++) {
    result *= i;
  }
  return result;
}

/**
 * Binomial coefficient "n choose k".
 * Computed multiplicatively to avoid huge intermediate factorials.
 */
function combinations(n, k) {
  assertNonNegativeInteger(n);
  assertNonNegativeInteger(k);

  if (k > n) {
    throw new RangeError("k cannot be greater than n");
  }

  // Use symmetry: C(n, k) = C(n, n - k)
  k = Math.min(k, n - k);

  let result = 1;
  for (let i = 1; i <= k; i++) {
    result = (result * (n - k + i)) / i;
  }

  if (!Number.isSafeInteger(result)) {
    throw new RangeError("combinations result exceeds safe integer precision");
  }

  return result;
}

/**
 * Permutations: P(n, k) = n! / (n - k)!
 */
function permutations(n, k) {
  assertNonNegativeInteger(n);
  assertNonNegativeInteger(k);

  if (k > n) {
    throw new RangeError("k cannot be greater than n");
  }

  let result = 1;
  for (let i = 0; i < k; i++) {
    result *= n - i;
  }

  if (!Number.isSafeInteger(result)) {
    throw new RangeError("permutations result exceeds safe integer precision");
  }

  return result;
}

/* ----------------------------- Random helpers ----------------------------- */

/**
 * Box-Muller transform for a standard/normal random value.
 */
function randomNormal(mean = 0, standardDeviation = 1) {
  assertFiniteNumber(mean);
  assertFiniteNumber(standardDeviation);
  if (standardDeviation < 0) {
    throw new RangeError("standardDeviation must be non-negative");
  }

  // Avoid Math.log(0)
  const u = 1 - Math.random();
  const v = Math.random();

  const z = Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  return mean + z * standardDeviation;
}

/**
 * Partial Fisher-Yates shuffle.
 * Returns a new array with `size` unique sampled elements.
 */
function sampleWithoutReplacement(values, size) {
  assertArray(values);
  assertNonNegativeInteger(size);

  if (size > values.length) {
    throw new RangeError("sample size cannot exceed array length");
  }

  const copy = [...values];

  for (let i = 0; i < size; i++) {
    const j = i + Math.floor(Math.random() * (copy.length - i));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }

  return copy.slice(0, size);
}

/* ----------------------------- Public API ----------------------------- */

const statsMath = {
  sum,
  mean,
  median,
  mode,
  variance,
  standardDeviation,
  min,
  max,
  range,
  quartiles,
  clamp,
  lerp,
  roundTo,
  gcd,
  lcm,
  isPrime,
  factorial,
  factorialBigInt,
  combinations,
  permutations,
  randomNormal,
  sampleWithoutReplacement
};

export default statsMath;
```

