## 8. Statistics-Specific Edge Cases

### 8.1 Pearson correlation with constant series (zero std-dev)
```js
function pearson(x, y) {
  const n = x.length;
  const mx = x.reduce((s,v)=>s+v,0)/n;
  const my = y.reduce((s,v)=>s+v,0)/n;
  const num = x.reduce((s,v,i)=>s+(v-mx)*(y[i]-my),0);
  const dx = Math.sqrt(x.reduce((s,v)=>s+(v-mx)**2,0));
  const dy = Math.sqrt(y.reduce((s,v)=>s+(v-my)**2,0));
  if (dx === 0 || dy === 0) return NaN; // division by zero
  return num/(dx*dy);
}
console.log(pearson([1,1,1],[2,3,4])); // NaN
```

### 8.2 Median of unsorted input (must copy)
```js
function medianBad(arr) {
  arr.sort((a,b)=>a-b); // mutates input!
  // ...
}
```

### 8.3 Percentile with non-integer index
```js
function percentile(sorted, p) {
  if (sorted.length === 0) return NaN;
  const idx = (sorted.length - 1) * p;
  const lo = Math.floor(idx), hi = Math.ceil(idx);
  if (lo === hi) return sorted[lo];
  return sorted[lo] + (sorted[hi]-sorted[lo])*(idx-lo);
}
```

### 8.4 Mode with ties / empty
```js
function mode(arr) {
  if (arr.length === 0) return []; // or NaN depending on contract
  const counts = new Map();
  for (const v of arr) counts.set(v, (counts.get(v)||0)+1);
  const max = Math.max(...counts.values());
  return [...counts].filter(([,c])=>c===max).map(([v])=>v);
}
console.log(mode([])); // []
console.log(mode([1,1,2,2])); // [1,2]
```

### 8.5 Weighted mean with zero total weight
```js
function wmean(xs, ws) {
  const num = xs.reduce((s,x,i)=>s+x*ws[i],0);
  const den = ws.reduce((s,w)=>s+w,0);
  if (den === 0) return NaN;
  return num/den;
}
```

### 8.6 Covariance population vs sample
```js
// same n vs n-1 distinction as variance; also need matching lengths
function cov(x,y,sample=true){
  if(x.length!==y.length || x.length===0) return NaN;
  if(sample && x.length<2) return NaN;
  const mx=x.reduce((s,v)=>s+v,0)/x.length;
  const my=y.reduce((s,v)=>s+v,0)/y.length;
  const s=x.reduce((a,v,i)=>a+(v-mx)*(y[i]-my),0);
  return s/(sample?x.length-1:x.length);
}
```

### 8.7 Outlier handling / robust stats
```js
// Median absolute deviation; empty -> NaN
function mad(arr) {
  if (!arr.length) return NaN;
  const m = median(arr);
  const devs = arr.map(v=>Math.abs(v-m));
  return median(devs);
}
```

