## 12. Randomness & Sampling

### 12.1 `Math.random()` is not cryptographically secure
```js
// Use crypto.getRandomValues for security
const buf = new Uint32Array(1);
crypto.getRandomValues(buf);
const r = buf[0] / 2**32;
```

### 12.2 Fisher-Yates must iterate correctly
```js
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
// Edge: empty / single returns same
```

### 12.3 Reservoir sampling for streaming
```js
function sample(stream, k) {
  const res = [];
  let i = 0;
  for (const x of stream) {
    if (i < k) res.push(x);
    else {
      const j = Math.floor(Math.random() * (i + 1));
      if (j < k) res[j] = x;
    }
    i++;
  }
  return res;
}
```

