## 17. Practical Defensive Patterns

```js
// A robust stats toolkit skeleton
function safeStats(arr) {
  const nums = arr.filter(x => typeof x === 'number' && Number.isFinite(x));
  if (nums.length === 0) return { mean: NaN, median: NaN, std: NaN, n: 0 };
  const n = nums.length;
  const mean = nums.reduce((s,x)=>s+x,0)/n;
  const variance = nums.reduce((s,x)=>s+(x-mean)**2,0)/Math.max(1, n-1); // sample
  return {
    n,
    mean,
    median: median(nums),
    std: Math.sqrt(variance),
    min: Math.min(...nums), // safe if n small
    max: Math.max(...nums),
  };
}
```

