## Typical Use Cases

### 1. Parsing input

```js
function parseName(input) {
  return input.trim().replace(/\s+/g, " ");
}

console.log(parseName("   Ada   Lovelace   ")); // "Ada Lovelace"
```

### 2. Slugifying text

```js
function slugify(text) {
  return text
    .toLowerCase()
    .trim()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // remove accents
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

console.log(slugify("Café & Tea!")); // "cafe-tea"
```

### 3. Extracting data

```js
const log = "[2025-01-01] ERROR: disk full";
const match = log.match(/^\[(.+?)\]\s+(\w+):\s+(.+)$/);

if (match) {
  const [, date, level, message] = match;
  console.log(date, level, message);
}
```

### 4. Masking sensitive data

```js
function maskEmail(email) {
  const [local, domain] = email.split("@");
  if (!domain) return email;
  const maskedLocal = local[0] + "*".repeat(Math.max(local.length - 1, 0));
  return `${maskedLocal}@${domain}`;
}

console.log(maskEmail("ada@example.com")); // "a***@example.com"
```

### 5. Formatting text

```js
function formatCurrency(value) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD"
  }).format(value);
}

console.log(formatCurrency(1234.5)); // "$1,234.50"
```

### 6. Reading/writing bytes

```js
const encoder = new TextEncoder();
const bytes = encoder.encode("hello");
console.log(bytes); // Uint8Array

const decoder = new TextDecoder();
console.log(decoder.decode(bytes)); // "hello"
```

### 7. Safe-ish HTML escaping

```js
function escapeHtml(text) {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

console.log(escapeHtml(`<script>alert("x")</script>`));
```

Use DOM or a trusted sanitizer for real security; this is basic escaping.

