Below is a complete, runnable Node.js implementation of C-like structs. It stores data in an `ArrayBuffer`, uses a `DataView` for typed access, supports nested structs, fixed-size arrays, alignment/padding, and interop with raw buffers.

Save as `structs.js` and run with `node structs.js`.

```js
'use strict';

/**
 * Lightweight struct implementation backed by ArrayBuffer/DataView.
 *
 * Supported field types:
 *   int8, uint8, int16, uint16, int32, uint32,
 *   float32, float64, bool, char
 *
 * A field may also be:
 *   - another struct constructor (nested struct)
 *   - { type, count|length } for fixed-size arrays
 */

const TYPES = {
  int8:    { kind: 'primitive', size: 1, align: 1, get: (dv, o) => dv.getInt8(o),    set: (dv, o, v) => dv.setInt8(o, v) },
  uint8:   { kind: 'primitive', size: 1, align: 1, get: (dv, o) => dv.getUint8(o),   set: (dv, o, v) => dv.setUint8(o, v) },
  int16:   { kind: 'primitive', size: 2, align: 2, get: (dv, o) => dv.getInt16(o, true),  set: (dv, o, v) => dv.setInt16(o, v, true) },
  uint16:  { kind: 'primitive', size: 2, align: 2, get: (dv, o) => dv.getUint16(o, true), set: (dv, o, v) => dv.setUint16(o, v, true) },
  int32:   { kind: 'primitive', size: 4, align: 4, get: (dv, o) => dv.getInt32(o, true),  set: (dv, o, v) => dv.setInt32(o, v, true) },
  uint32:  { kind: 'primitive', size: 4, align: 4, get: (dv, o) => dv.getUint32(o, true), set: (dv, o, v) => dv.setUint32(o, v, true) },
  float32: { kind: 'primitive', size: 4, align: 4, get: (dv, o) => dv.getFloat32(o, true), set: (dv, o, v) => dv.setFloat32(o, v, true) },
  float64: { kind: 'primitive', size: 8, align: 8, get: (dv, o) => dv.getFloat64(o, true), set: (dv, o, v) => dv.setFloat64(o, v, true) },
  bool:    { kind: 'primitive', size: 1, align: 1, get: (dv, o) => dv.getUint8(o) !== 0,   set: (dv, o, v) => dv.setUint8(o, v ? 1 : 0) },
  char:    { kind: 'primitive', size: 1, align: 1, get: (dv, o) => String.fromCharCode(dv.getUint8(o)), set: (dv, o, v) => dv.setUint8(o, String(v).charCodeAt(0) & 0xff) }
};

function isStructCtor(value) {
  return typeof value === 'function' && Number.isInteger(value.SIZE);
}

function align(offset, alignment) {
  if (!alignment || alignment <= 1) return offset;
  return (offset + alignment - 1) & ~(alignment - 1);
}

function normalizeSpec(raw, packed) {
  let spec = raw;
  if (typeof spec === 'function') spec = { type: spec };
  if (typeof spec === 'string') spec = { type: spec };

  const rawType = spec.type;
  let base;

  if (isStructCtor(rawType)) {
    base = { kind: 'struct', type: rawType, size: rawType.SIZE, align: rawType.ALIGN || 1 };
  } else {
    const info = TYPES[rawType];
    if (!info) throw new Error(`Unknown struct field type: ${rawType}`);
    base = { kind: info.kind, ...info };
  }

  const count = spec.length || spec.count || 1;
  if (!Number.isInteger(count) || count < 1) throw new Error('Field count/length must be a positive integer');

  const alignment = packed ? 1 : (spec.align ?? base.align);

  return {
    ...base,
    count,
    align: alignment
  };
}

function toPlain(value) {
  if (Array.isArray(value)) return value.map(toPlain);
  if (value && typeof value.toObject === 'function') return value.toObject();
  return value;
}

function Struct(schema, options = {}) {
  const packed = !!options.packed;

  // Compute layout.
  const fields = [];
  let offset = 0;
  let maxAlign = 1;

  for (const [name, raw] of Object.entries(schema)) {
    const field = normalizeSpec(raw, packed);
    field.name = name;

    maxAlign = Math.max(maxAlign, field.align);
    offset = align(offset, field.align);
    field.offset = offset;
    offset += field.size * field.count;

    fields.push(field);
  }

  // C-like: total size is aligned to the strictest member alignment.
  if (!packed) offset = align(offset, maxAlign);
  const size = offset;

  class StructType {
    constructor(init, byteOffset = 0) {
      if (init instanceof ArrayBuffer) {
        if (byteOffset + size > init.byteLength) {
          throw new RangeError('Buffer is too small for this struct');
        }
        this.buffer = init;
        this.base = byteOffset;
      } else if (ArrayBuffer.isView(init)) {
        if (byteOffset + size > init.byteLength) {
          throw new RangeError('View is too small for this struct');
        }
        this.buffer = init.buffer;
        this.base = init.byteOffset + byteOffset;
      } else {
        this.buffer = new ArrayBuffer(size);
        this.base = 0;
        if (init != null) this.set(init);
      }

      this.view = new DataView(this.buffer, this.base, size);
    }

    set(values) {
      if (values == null) return this;

      for (const key of Object.keys(values)) {
        const field = fields.find(f => f.name === key);
        if (!field) throw new Error(`Unknown field: ${key}`);
        this[key] = values[key];
      }
      return this;
    }

    toObject() {
      const out = {};
      for (const field of fields) {
        out[field.name] = toPlain(this[field.name]);
      }
      return out;
    }

    clone() {
      return new this.constructor(this.buffer.slice(this.base, this.base + size));
    }

    equals(other) {
      if (!(other instanceof this.constructor)) return false;
      const a = new Uint8Array(this.buffer, this.base, size);
      const b = new Uint8Array(other.buffer, other.base, size);
      if (a.length !== b.length) return false;
      for (let i = 0; i < a.length; i++) {
        if (a[i] !== b[i]) return false;
      }
      return true;
    }
  }

  StructType.SIZE = size;
  StructType.ALIGN = maxAlign;
  StructType.fields = fields;
  StructType.packed = packed;

  // Define typed accessors.
  for (const field of fields) {
    Object.defineProperty(StructType.prototype, field.name, {
      enumerable: true,
      get() {
        const dv = this.view;
        const off = field.offset;

        if (field.kind === 'struct') {
          if (field.count === 1) {
            return new field.type(dv.buffer, dv.byteOffset + off);
          }
          const result = new Array(field.count);
          for (let i = 0; i < field.count; i++) {
            result[i] = new field.type(dv.buffer, dv.byteOffset + off + i * field.size);
          }
          return result;
        }

        if (field.count === 1) {
          return field.get(dv, off);
        }

        const result = new Array(field.count);
        for (let i = 0; i < field.count; i++) {
          result[i] = field.get(dv, off + i * field.size);
        }
        return result;
      },
      set(value) {
        const dv = this.view;
        const off = field.offset;

        if (field.kind === 'struct') {
          if (field.count === 1) {
            const target = new field.type(dv.buffer, dv.byteOffset + off);

            if (value instanceof field.type) {
              const src = new Uint8Array(value.buffer, value.base, field.size);
              const dst = new Uint8Array(dv.buffer, dv.byteOffset + off, field.size);
              dst.set(src);
            } else if (value && typeof value === 'object') {
              target.set(value);
            } else {
              throw new TypeError(`Field "${field.name}" expects a struct or plain object`);
            }
            return;
          }

          if (!Array.isArray(value) || value.length !== field.count) {
            throw new RangeError(`Field "${field.name}" expects an array of length ${field.count}`);
          }

          for (let i = 0; i < field.count; i++) {
            const target = new field.type(dv.buffer, dv.byteOffset + off + i * field.size);
            const item = value[i];
            if (item instanceof field.type) {
              const src = new Uint8Array(item.buffer, item.base, field.size);
              const dst = new Uint8Array(dv.buffer, dv.byteOffset + off + i * field.size, field.size);
              dst.set(src);
            } else if (item && typeof item === 'object') {
              target.set(item);
            } else {
              throw new TypeError(`Field "${field.name}[${i}]" expects a struct or plain object`);
            }
          }
          return;
        }

        if (field.count === 1) {
          field.set(dv, off, value);
          return;
        }

        if (!Array.isArray(value) || value.length !== field.count) {
          throw new RangeError(`Field "${field.name}" expects an array of length ${field.count}`);
        }

        for (let i = 0; i < field.count; i++) {
          field.set(dv, off + i * field.size, value[i]);
        }
      }
    });
  }

  return StructType;
}

// ---------------------------------------------------------------------------
// Example usage
// ---------------------------------------------------------------------------

const assert = require('assert');

const Vec3 = Struct({
  x: 'float64',
  y: 'float64',
  z: 'float64'
});

const Particle = Struct({
  id: 'uint32',
  active: 'bool',
  position: Vec3,                       // nested struct
  velocity: { type: 'float32', count: 3 }, // fixed-size array
  name: { type: 'char', count: 8 }       // fixed-size char array
});

console.log('Particle.SIZE =', Particle.SIZE);
console.log('Particle.ALIGN =', Particle.ALIGN);

const p = new Particle({
  id: 42,
  active: true,
  position: { x: 1, y: 2, z: 3 },
  velocity: [10, 20, 30],
  name: [...'Particle'.padEnd(8)]
});

console.log('toObject():');
console.log(JSON.stringify(p.toObject(), null, 2));

// Nested mutation through a temporary view.
p.position.y = 99;
assert.strictEqual(p.toObject().position.y, 99);

// Binary round-trip.
const copy = p.clone();
assert.ok(p.equals(copy), 'clone should be equal');

const fromBuffer = new Particle(p.buffer.slice(p.base, p.base + Particle.SIZE));
assert.ok(p.equals(fromBuffer), 'buffer reconstruction should be equal');

// Raw buffer interop.
const raw = new ArrayBuffer(Particle.SIZE);
const view = new DataView(raw);
view.setUint32(0, 7, true);
const fromRaw = new Particle(raw);
assert.strictEqual(fromRaw.id, 7);

// Packed struct (no padding).
const Packed = Struct({ a: 'uint8', b: 'uint32' }, { packed: true });
console.log('Packed.SIZE =', Packed.SIZE); // 5, not 8
const packed = new Packed({ a: 1, b: 2 });
assert.strictEqual(packed.a, 1);
assert.strictEqual(packed.b, 2);

console.log('\nAll assertions passed.');
```

### What this gives you

- **Fixed binary layout**: Every instance is backed by an `ArrayBuffer` of exactly `Struct.SIZE` bytes.
- **Typed access**: `DataView` reads/writes with correct sizes and endianness.
- **Nested structs**: A field can be another struct constructor.
- **Fixed arrays**: `{ type, count }` creates repeated typed fields.
- **Alignment**: Natural alignment and trailing padding by default; `{ packed: true }` disables it.
- **Buffer interop**: Construct from `ArrayBuffer`, `TypedArray`, or plain objects; `clone()`, `equals()`, and `toObject()` are included.
- **Mutation**: Nested struct getters return views into the same underlying buffer, so `p.position.y = 99` mutates `p`.

If you want a more object-oriented style instead of binary layout, the common JavaScript idiom is simply a class with a constructor:

```js
class Point { constructor(x = 0, y = 0) { this.x = x; this.y = y; } }
```

The implementation above is the closer equivalent to C/C++/Rust structs when you need precise memory layout or binary serialization.

JavaScript has **no native `struct` keyword**. Instead, a “struct” is usually modeled as a **named collection of fields** using objects, classes, or (for binary/memory layouts) typed arrays. The idea is the same as in C/C++: group related data into one value with predictable fields.

---

## 1. The basic idea: objects as structs

The simplest struct is a plain object literal.

```js
const point = { x: 10, y: 20 };

console.log(point.x); // 10
console.log(point.y); // 20
```

This gives you named fields, but no fixed type enforcement and no methods by default.

---

## 2. Syntax options

### A. Plain object + factory function

Useful for simple data records.

```js
function makePoint(x, y) {
  return { x, y };
}

const p = makePoint(3, 4);
console.log(p); // { x: 3, y: 4 }
```

### B. Class (the closest to a “typed struct”)

Classes add constructors, methods, and (optionally) private fields.

```js
class Point {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }

  distanceTo(other) {
    return Math.hypot(this.x - other.x, this.y - other.y);
  }
}

const a = new Point(0, 0);
const b = new Point(3, 4);
console.log(a.distanceTo(b)); // 5
```

### C. Private fields (encapsulation)

```js
class SecretPoint {
  #x;
  #y;

  constructor(x, y) {
    this.#x = x;
    this.#y = y;
  }

  get coords() {
    return { x: this.#x, y: this.#y };
  }
}

const s = new SecretPoint(1, 2);
console.log(s.coords); // { x: 1, y: 2 }
// s.#x; // SyntaxError: private field
```

### D. Immutable struct (freeze)

```js
const user = Object.freeze({ id: 1, name: "Ada" });
// user.name = "Bob"; // TypeError in strict mode
```

---

## 3. Binary / memory-layout structs

For performance, network protocols, or file formats, use **ArrayBuffer + DataView** or typed arrays. This is where JS gets closest to C structs.

```js
// A 12-byte struct: int32 x, int32 y, float32 z
const buffer = new ArrayBuffer(12);
const view = new DataView(buffer);

view.setInt32(0, 10, true);   // x at offset 0, little-endian
view.setInt32(4, 20, true);   // y at offset 4
view.setFloat32(8, 3.5, true); // z at offset 8

console.log(view.getInt32(0, true));   // 10
console.log(view.getFloat32(8, true)); // 3.5
```

You can wrap this in a class for a nicer API:

```js
class Vec3 {
  constructor(buffer, offset = 0) {
    this.view = new DataView(buffer, offset, 12);
  }
  get x() { return this.view.getInt32(0, true); }
  set x(v) { this.view.setInt32(0, v, true); }
  get y() { return this.view.getInt32(4, true); }
  set y(v) { this.view.setInt32(4, v, true); }
  get z() { return this.view.getFloat32(8, true); }
  set z(v) { this.view.setFloat32(8, v, true); }
}

const buf = new ArrayBuffer(12);
const v = new Vec3(buf);
v.x = 7; v.y = 8; v.z = 9.25;
console.log(v.x, v.y, v.z); // 7 8 9.25
```

---

## 4. TypeScript / JSDoc: compile-time “structs”

JavaScript itself is dynamic, but you can describe shapes with types.

```ts
// TypeScript
interface Point {
  x: number;
  y: number;
}

const p: Point = { x: 1, y: 2 };
```

With JSDoc in plain JS:

```js
/**
 * @typedef {Object} Point
 * @property {number} x
 * @property {number} y
 */

/** @type {Point} */
const p = { x: 1, y: 2 };
```

These do not exist at runtime; they only help tooling.

---

## 5. Typical use cases

| Use case | Best approach |
|---|---|
| Simple data records (user, config) | Plain object or factory |
| Domain models with behavior | Class |
| Immutable state (Redux, React) | Frozen object or class instance copied immutably |
| Binary protocols, files, WebGL | `ArrayBuffer` + `DataView` / typed arrays |
| Interop with C/WASM | Typed arrays or WASM memory views |
| Compile-time safety | TypeScript interfaces / JSDoc |

---

## 6. Important caveats

- **Reference semantics**: objects are passed by reference.
  ```js
  const a = { x: 1 };
  const b = a;
  b.x = 99;
  console.log(a.x); // 99
  ```
- **No fixed memory layout** for plain objects; engines optimize (hidden classes), but you shouldn’t rely on byte offsets.
- **No value equality**: `{x:1} === {x:1}` is `false`.
- **GC overhead**: many small objects can cause GC pressure; use typed arrays for hot loops.

---

### Summary

In JavaScript, a struct is not a language primitive. You choose the representation based on need:

- **Plain objects/classes** for everyday data.
- **Typed arrays/DataView** when you need bytes, performance, or interoperability.
- **TypeScript/JSDoc** when you want compile-time shape checking.

## Exercise

Build a **`Book` struct** in JavaScript that:

1. Stores `title`, `author`, and `pages`.
2. Rejects invalid input (`title`/`author` must be non-empty strings, `pages` must be a positive integer).
3. Provides a method `readingTime()` that returns estimated hours at 250 pages/hour.
4. Provides a method `equals(other)` that compares all fields.
5. Exposes data as a plain immutable object when needed.

Because JavaScript has no built-in `struct`, we’ll model it with an **ES6 class + private fields + factory validation** (a common idiomatic approach).

---

## Step-by-step solution

### Step 1: Define private backing fields

Use `#` private fields so external code cannot mutate internal state directly.

```js
class Book {
  #title;
  #author;
  #pages;
  // ...
}
```

### Step 2: Validate in the constructor

Fail fast: throw early if any invariant is violated. This keeps every `Book` instance valid by construction.

```js
constructor(title, author, pages) {
  if (typeof title !== "string" || title.trim() === "") {
    throw new TypeError("title must be a non-empty string");
  }
  if (typeof author !== "string" || author.trim() === "") {
    throw new TypeError("author must be a non-empty string");
  }
  if (!Number.isInteger(pages) || pages <= 0) {
    throw new TypeError("pages must be a positive integer");
  }

  this.#title = title.trim();
  this.#author = author.trim();
  this.#pages = pages;
}
```

### Step 3: Add read-only getters

Getters expose values without allowing assignment.

```js
get title() { return this.#title; }
get author() { return this.#author; }
get pages() { return this.#pages; }
```

### Step 4: Add behavior methods

```js
readingTime() {
  return this.#pages / 250; // hours
}

equals(other) {
  return (
    other instanceof Book &&
    other.title === this.#title &&
    other.author === this.#author &&
    other.pages === this.#pages
  );
}
```

### Step 5: Provide a plain object view

Useful for serialization/logging without leaking internals.

```js
toObject() {
  return Object.freeze({
    title: this.#title,
    author: this.#author,
    pages: this.#pages,
  });
}
```

### Step 6: Add a static factory for safer construction

Lets callers avoid `new` and keeps construction consistent.

```js
static create(title, author, pages) {
  return new Book(title, author, pages);
}
```

---

## Final solution

```js
class Book {
  #title;
  #author;
  #pages;

  constructor(title, author, pages) {
    if (typeof title !== "string" || title.trim() === "") {
      throw new TypeError("title must be a non-empty string");
    }
    if (typeof author !== "string" || author.trim() === "") {
      throw new TypeError("author must be a non-empty string");
    }
    if (!Number.isInteger(pages) || pages <= 0) {
      throw new TypeError("pages must be a positive integer");
    }

    this.#title = title.trim();
    this.#author = author.trim();
    this.#pages = pages;
  }

  get title() {
    return this.#title;
  }

  get author() {
    return this.#author;
  }

  get pages() {
    return this.#pages;
  }

  readingTime() {
    return this.#pages / 250; // hours at 250 pages/hour
  }

  equals(other) {
    return (
      other instanceof Book &&
      other.title === this.#title &&
      other.author === this.#author &&
      other.pages === this.#pages
    );
  }

  toObject() {
    return Object.freeze({
      title: this.#title,
      author: this.#author,
      pages: this.#pages,
    });
  }

  static create(title, author, pages) {
    return new Book(title, author, pages);
  }
}

// ---- Demo usage ----
const b1 = Book.create("Clean Code", "Robert C. Martin", 464);
const b2 = Book.create("Clean Code", "Robert C. Martin", 464);

console.log(b1.readingTime());          // 1.856
console.log(b1.equals(b2));             // true
console.log(b1.toObject());             // frozen plain object

// Invalid construction throws:
try {
  Book.create("", "Author", 100);
} catch (e) {
  console.error(e.message);             // "title must be a non-empty string"
}
```

### Why this works well as a “struct”

- **Encapsulation:** Private fields prevent accidental mutation.
- **Invariants:** Validation lives in one place (constructor).
- **Value semantics-ish:** `equals()` compares contents, not identity.
- **Interop:** `toObject()` gives a plain, serializable representation.
- **Immutability surface:** No setters; callers must create a new instance to “change” data, which is typical for struct-like value objects.

## Structs in JavaScript (interview answer)

### 1. What a “struct” means

A **struct** is a **value type / composite record**: a fixed-shape bundle of named fields with known types and a predictable memory layout.

JavaScript has **no built-in `struct`**. In practice you choose one of three levels:

| Need | JS idiom |
|---|---|
| Plain data record / JSON shape | Plain object `{ x, y }` (dynamic, GC'd, no fixed layout) |
| Compile-time shape / API contract | TypeScript `interface` / `type` |
| Real fixed-layout / binary / interop (C structs, WebGL, WASM, network packets) | `ArrayBuffer` + `DataView` with explicit offsets |

So “implementing structs” in JS usually means building a **small schema-driven factory** that gives you:
- named field access,
- type validation,
- predictable byte size,
- `ArrayBuffer` serialization (pack/unpack).

Below is a clean, reusable core implementation.

---

### 2. Core implementation

```js
// ---- Type metadata -----------------------------------------------------------
// Each type knows its size, alignment, and DataView accessors.
const TYPES = Object.freeze({
  int8:    { size: 1, align: 1, get: (dv, o) => dv.getInt8(o),    set: (dv, o, v) => dv.setInt8(o, v) },
  uint8:   { size: 1, align: 1, get: (dv, o) => dv.getUint8(o),   set: (dv, o, v) => dv.setUint8(o, v) },
  int16:   { size: 2, align: 2, get: (dv, o) => dv.getInt16(o, true),  set: (dv, o, v) => dv.setInt16(o, v, true) },
  uint16:  { size: 2, align: 2, get: (dv, o) => dv.getUint16(o, true), set: (dv, o, v) => dv.setUint16(o, v, true) },
  int32:   { size: 4, align: 4, get: (dv, o) => dv.getInt32(o, true),  set: (dv, o, v) => dv.setInt32(o, v, true) },
  uint32:  { size: 4, align: 4, get: (dv, o) => dv.getUint32(o, true), set: (dv, o, v) => dv.setUint32(o, v, true) },
  float32: { size: 4, align: 4, get: (dv, o) => dv.getFloat32(o, true), set: (dv, o, v) => dv.setFloat32(o, v, true) },
  float64: { size: 8, align: 8, get: (dv, o) => dv.getFloat64(o, true), set: (dv, o, v) => dv.setFloat64(o, v, true) },
});

// ---- Factory ----------------------------------------------------------------
/**
 * Create a struct "class" from a field schema.
 *
 * @param {Array<{name:string, type:keyof TYPES}>} fields
 * @returns {Function} constructor producing struct instances
 */
function createStruct(fields) {
  if (!Array.isArray(fields) || fields.length === 0) {
    throw new TypeError("fields must be a non-empty array");
  }

  // Compute layout with natural alignment + padding.
  let cursor = 0;
  const layout = fields.map((f, i) => {
    const meta = TYPES[f.type];
    if (!meta) throw new TypeError(`Unknown type "${f.type}" at field ${i} (${f.name})`);
    if (typeof f.name !== "string" || !f.name) {
      throw new TypeError(`Invalid field name at index ${i}`);
    }

    // Align cursor to this field's alignment.
    const pad = (meta.align - (cursor % meta.align)) % meta.align;
    cursor += pad;

    const offset = cursor;
    cursor += meta.size;

    return { name: f.name, offset, ...meta };
  });

  // Pad total size to the struct's overall alignment.
  const structAlign = Math.max(...layout.map((f) => f.align));
  const byteSize = Math.ceil(cursor / structAlign) * structAlign;

  // ---- Constructor -----------------------------------------------------------
  class Struct {
    constructor(values = {}) {
      // Each instance owns one packed buffer.
      this._buffer = new ArrayBuffer(byteSize);
      this._view = new DataView(this._buffer);

      // Apply provided values (or defaults).
      for (const field of layout) {
        const v = Object.prototype.hasOwnProperty.call(values, field.name)
          ? values[field.name]
          : 0;
        this[field.name] = v; // routes through setter below
      }
    }

    /** Copy bytes out (safe clone). */
    toBuffer() {
      return this._buffer.slice(0);
    }

    /** Plain JS object snapshot (useful for debugging/JSON). */
    toJSON() {
      const out = {};
      for (const field of layout) out[field.name] = this[field.name];
      return out;
    }

    /** Human-readable debug string. */
    toString() {
      return `${this.constructor.name}(${JSON.stringify(this.toJSON())})`;
    }
  }

  // ---- Per-field accessors (closed over `layout`) ----------------------------
  // Defining on the prototype keeps instances small and V8-friendly.
  for (const field of layout) {
    Object.defineProperty(Struct.prototype, field.name, {
      enumerable: true,
      configurable: false,
      get() {
        return field.get(this._view, field.offset);
      },
      set(value) {
        // Minimal type coercion guard; extend as needed per type.
        if (typeof value !== "number" || !Number.isFinite(value)) {
          throw new TypeError(
            `Field "${field.name}" expects a finite number, got ${typeof value}`
          );
        }
        field.set(this._view, field.offset, value);
      },
    });
  }

  // ---- Static helpers --------------------------------------------------------
  Struct.byteSize = byteSize;
  Struct.fields = layout.map(({ name, type: _t, ...rest }) => ({ name, ...rest }));

  /** Build an instance by copying from an existing buffer. */
  Struct.fromBuffer = (buffer, byteOffset = 0) => {
    if (!(buffer instanceof ArrayBuffer)) {
      throw new TypeError("fromBuffer expects an ArrayBuffer");
    }
    if (byteOffset + byteSize > buffer.byteLength) {
      throw new RangeError("Buffer too small for struct");
    }
    const instance = new Struct();
    const src = new Uint8Array(buffer, byteOffset, byteSize);
    const dst = new Uint8Array(instance._buffer);
    dst.set(src);
    return instance;
  };

  return Struct;
}
```

---

### 3. Usage example

```js
const Vec2 = createStruct([
  { name: "x", type: "float64" },
  { name: "y", type: "float64" },
]);

const v = new Vec2({ x: 3, y: 4 });
console.log(v.x, v.y);          // 3 4
console.log(Vec2.byteSize);     // 16

v.x = 10;
console.log(v.toJSON());        // { x: 10, y: 4 }

// Binary round-trip (e.g. for WASM / sockets / files)
const buf = v.toBuffer();
const v2 = Vec2.fromBuffer(buf);
console.log(v2.toString());     // Vec2({"x":10,"y":4})

// Arrays of structs = ArrayBuffer with stride = byteSize
const points = new ArrayBuffer(Vec2.byteSize * 3);
const p0 = Vec2.fromBuffer(points, 0 * Vec2.byteSize);
const p1 = Vec2.fromBuffer(points, 1 * Vec2.byteSize);
p0.x = 1; p0.y = 2;
p1.x = 3; p1.y = 4;
```

---

### 4. Interview talking points (what to say)

- **No native struct**: JS objects are hash maps; use them for everyday records. Reach for `ArrayBuffer`/`DataView` only when layout matters.
- **Alignment matters**: fields often need padding (e.g. `int32` after `int8` → 3 bytes padding). This implementation handles it.
- **Value vs reference**: JS objects are always references; this “struct” is still an object wrapping a buffer. True value semantics would require copying (`toBuffer` / `fromBuffer` / spread).
- **Trade-offs**: property access has dispatch overhead; for hot loops you may prefer direct `DataView`/typed-array indexing.
- **Extensions**: add enums, nested structs, bitfields, endianness flags, or validation hooks.

If you want, I can extend this to **nested structs, string fields, or BigInt (int64)**.

## Synchronization and locks in JavaScript

JavaScript is single-threaded per execution context, but races still happen in two common cases:

1. **Async interleaving on one thread** – multiple `async` functions await I/O/timers and resume in a different order. A **mutex/semaphore** serializes their critical sections.
2. **Multiple threads (Worker threads / `SharedArrayBuffer`)** – true parallelism. Here you need **atomic operations** (`Atomics`) and a real lock (spinlock + wait/notify).

Below are two complete, runnable Node.js examples.

---

### 1) Async mutex + semaphore (single thread, async tasks)

Save as `async-lock.js` and run with `node async-lock.js`.

```js
class Mutex {
  constructor() {
    this._locked = false;
    this._queue = [];
  }

  acquire() {
    return new Promise((resolve) => {
      if (!this._locked) {
        this._locked = true;
        resolve();
      } else {
        this._queue.push(resolve);
      }
    });
  }

  release() {
    if (this._queue.length > 0) {
      const next = this._queue.shift();
      next();               // hand the lock to the next waiter (stays locked)
    } else {
      this._locked = false; // no waiters: unlock
    }
  }

  async runExclusive(fn) {
    await this.acquire();
    try {
      return await fn();
    } finally {
      this.release();
    }
  }
}

class Semaphore {
  constructor(permits) {
    this.permits = permits;
    this.waiters = [];
  }

  acquire() {
    return new Promise((resolve) => {
      if (this.permits > 0) {
        this.permits--;
        resolve();
      } else {
        this.waiters.push(resolve);
      }
    });
  }

  release() {
    if (this.waiters.length > 0) {
      const next = this.waiters.shift();
      next();
    } else {
      this.permits++;
    }
  }
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

async function main() {
  // ---- Mutex demo ----
  const mutex = new Mutex();
  let counter = 0;

  const tasks = Array.from({ length: 6 }, (_, id) =>
    (async () => {
      await mutex.runExclusive(async () => {
        const before = counter;
        await sleep(Math.random() * 40); // simulate async work
        counter = before + 1;
        console.log(`task ${id}: ${before} -> ${counter}`);
      });
    })()
  );

  await Promise.all(tasks);
  console.log("mutex final counter:", counter); // always 6

  // ---- Semaphore demo (max 2 concurrent) ----
  const sem = new Semaphore(2);
  let active = 0;
  let maxActive = 0;

  const jobs = Array.from({ length: 6 }, (_, id) =>
    (async () => {
      await sem.acquire();
      active++;
      maxActive = Math.max(maxActive, active);
      console.log(`job ${id} start (active=${active})`);
      await sleep(50);
      active--;
      console.log(`job ${id} end   (active=${active})`);
      sem.release();
    })()
  );

  await Promise.all(jobs);
  console.log("max concurrent jobs:", maxActive); // <= 2
}

main().catch(console.error);
```

**Key ideas**

- `runExclusive` guarantees the critical section runs one at a time, even with `await` inside.
- Waiters are stored in a FIFO queue → fair ordering.
- `finally` ensures the lock is released on exceptions.
- A mutex is **not reentrant**: the same async flow calling `acquire()` twice will deadlock. If you need reentrancy, track an owner id.

---

### 2) Real multi-thread lock with `SharedArrayBuffer` + `Atomics`

Save as `atomics-lock.js` and run with `node atomics-lock.js`.

```js
const { Worker, isMainThread, parentPort, workerData } = require("worker_threads");

if (isMainThread) {
  const NUM_WORKERS = 4;
  const ITERS = 100_000;

  const counterBuffer = new SharedArrayBuffer(4);
  const lockBuffer = new SharedArrayBuffer(4);
  const counter = new Int32Array(counterBuffer);
  const lock = new Int32Array(lockBuffer);
  // both are zero-initialized

  let finished = 0;
  for (let i = 0; i < NUM_WORKERS; i++) {
    const w = new Worker(__filename, {
      workerData: { counterBuffer, lockBuffer, iters: ITERS, id: i },
    });

    w.on("message", () => {
      finished++;
      if (finished === NUM_WORKERS) {
        console.log("expected:", NUM_WORKERS * ITERS);
        console.log("actual  :", Atomics.load(counter, 0));
      }
    });

    w.on("error", (e) => {
      console.error(e);
      process.exit(1);
    });
  }
} else {
  const { counterBuffer, lockBuffer, iters } = workerData;
  const counter = new Int32Array(counterBuffer);
  const lock = new Int32Array(lockBuffer);

  function acquire() {
    // Spin only briefly; block efficiently when contended.
    while (Atomics.compareExchange(lock, 0, 0, 1) !== 0) {
      Atomics.wait(lock, 0, 1); // wait while lock value === 1
    }
  }

  function release() {
    Atomics.store(lock, 0, 0);
    Atomics.notify(lock, 0, 1); // wake one waiter
  }

  for (let i = 0; i < iters; i++) {
    acquire();
    Atomics.add(counter, 0, 1); // critical section
    release();
  }

  parentPort.postMessage("done");
}
```

**How the lock works**

- `lock[0]` is `0` (free) or `1` (held).
- `acquire`: `compareExchange(lock, 0, 0, 1)` atomically sets `0 → 1` only if it was `0`.  
  - Returns old value; if `0`, we got the lock.  
  - Otherwise we `Atomics.wait(lock, 0, 1)` (block until someone sets it back to `0`).
- `release`: store `0`, then `notify` one blocked worker.

Without the lock, `Atomics.add` calls would still be atomic individually, but the read-modify-write sequence (and any larger critical section) would race; the final count would be less than `400000`. With the lock, it is exact.

---

### Practical notes

- **Browser caveat**: `Atomics.wait` is **not allowed on the main thread** in browsers; use it only in Web Workers. In Node, worker threads are fine.
- **Prefer higher-level tools** in production: `async-mutex`, `Atomics`-based libraries, or message-passing designs that avoid shared state.
- **Deadlocks**: never acquire two locks in inconsistent order across tasks; use timeouts or a single global lock if unsure.
- **Starvation**: FIFO queues (as shown) prevent indefinite starvation; pure spinlocks without queues can starve.
- **Condition variables**: build on top of a mutex + a waiter list; wake waiters with `notify`/resolve when a predicate becomes true.

If you want, I can extend this with a **read/write lock**, a **condition variable**, or a **timeout-capable lock** (`tryAcquire(timeout)`).

## 1. Core idea

JavaScript is **single-threaded per realm** (one call stack, one event loop).  
So “synchronization” usually means **coordinating asynchronous work**, not protecting shared memory from simultaneous CPU access. True parallelism + shared memory only happens with **Web Workers / worker_threads + `SharedArrayBuffer` + `Atomics`**.

Two different worlds:

| World | Mechanism | “Locks” |
|-------|-----------|---------|
| Main thread / Node event loop | Promises, `async/await`, queues | Cooperative async mutexes |
| Workers / threads | `SharedArrayBuffer` + `Atomics` | Spinlocks / futex-like waits |

---

## 2. Cooperative synchronization (event loop)

### Idea
You serialize async operations so only one runs a critical section at a time.

### Async mutex (idiomatic pattern)

```js
class AsyncMutex {
  constructor() {
    this._locked = false;
    this._queue = [];
  }

  acquire() {
    return new Promise(resolve => {
      const release = () => {
        const next = this._queue.shift();
        if (next) next(release);
        else this._locked = false;
      };
      if (this._locked) this._queue.push(resolve.bind(null, release));
      else { this._locked = true; resolve(release); }
    });
  }
}

// usage
const mutex = new AsyncMutex();

async function criticalSection(id) {
  const release = await mutex.acquire();
  try {
    console.log("start", id);
    await doWork();
    console.log("end", id);
  } finally {
    release();
  }
}
```

**Key points**
- No OS thread blocking; just promise scheduling.
- Always use `try/finally` to release.
- Common in DB transactions, file writes, rate-limited API calls.

### Simpler: sequential queue

```js
let chain = Promise.resolve();
function runExclusive(fn) {
  const next = chain.then(fn);
  chain = next.catch(() => {}); // keep chain alive
  return next;
}
```

---

## 3. True locks with `SharedArrayBuffer` + `Atomics`

### Idea
Workers share memory; `Atomics` provides atomic read-modify-write and blocking wait/notify.

### Shared lock (worker-safe)

```js
// main.js
const sab = new SharedArrayBuffer(4);
const view = new Int32Array(sab); // view[0] = lock state

const worker = new Worker("worker.js");
worker.postMessage(sab);
```

```js
// worker.js
self.onmessage = ({ data: sab }) => {
  const lock = new Int32Array(sab);

  function acquire() {
    // spin + wait until we win CAS: 0 -> 1
    while (Atomics.compareExchange(lock, 0, 0, 1) !== 0) {
      Atomics.wait(lock, 0, 1); // block thread until notified
    }
  }

  function release() {
    Atomics.store(lock, 0, 0);
    Atomics.notify(lock, 0, 1); // wake one waiter
  }

  acquire();
  try { /* critical section */ }
  finally { release(); }
};
```

### Main-thread caveat
`Atomics.wait` **blocks the thread** and is forbidden on the browser main thread. Use `Atomics.waitAsync` (returns a Promise) instead:

```js
const { value, async } = Atomics.waitAsync(lock, 0, 1);
if (async) {
  value.then(() => { /* lock acquired or timed out */ });
}
```

---

## 4. Typical use cases

| Use case | Best tool |
|----------|-----------|
| Prevent interleaved async DB writes | Async mutex / sequential promise chain |
| Rate-limit outgoing requests | Async semaphore (counter-based mutex) |
| Worker pool sharing a buffer | `Atomics` lock + `SharedArrayBuffer` |
| One-time init / lazy singleton | Promise memoization (`if (!p) p = init()`) |
| Cross-tab coordination | `BroadcastChannel` + leader election, or Web Locks API |

### Web Locks API (browser, high-level)

```js
await navigator.locks.request("resource", async (lock) => {
  // exclusive while callback runs
  await updateSharedState();
});
```

### Node `worker_threads` equivalent
Use `Atomics` on `SharedArrayBuffer`; no built-in named locks except via packages.

---

## 5. Pitfalls

- **Deadlocks**: always release in `finally`; avoid nested locks with inconsistent order.
- **Starvation**: FIFO queue avoids it; raw spinlocks may not.
- **Main thread blocking**: never `Atomics.wait` on UI thread.
- **False sharing**: keep lock word separate from hot data to reduce cache contention.
- **Reentrancy**: JS mutexes above are non-reentrant; a lock holder calling acquire again deadlocks.

---

## 6. Quick decision guide

- **Only async code, no workers?** → Async mutex / promise chain.
- **Workers sharing memory?** → `Atomics` CAS lock + `wait/notify`.
- **Browser, need named locks?** → `navigator.locks`.
- **Node multi-process?** → OS-level locks via `flock`/`proper-lockfile`, not JS primitives.

If you want, I can show a **semaphore** (N concurrent) or a **read-write lock** built on the same primitives.

A common JavaScript synchronization mistake is assuming an `await` in the middle of an operation is “protected” just because JavaScript is single-threaded. It is not: other async work can run while the current task is suspended.

## Buggy version: lost update

```js
let counter = 0;

function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function incrementUnsafe() {
  const snapshot = counter;   // read
  await delay(10);            // yield to the event loop
  counter = snapshot + 1;     // write stale value
}

// Start 5 increments at once
Promise.all(
  Array.from({ length: 5 }, () => incrementUnsafe())
).then(() => {
  console.log("Unsafe counter:", counter); // often less than 5
});
```

### What goes wrong

1. `incrementUnsafe()` reads `counter`.
2. It then `await`s, yielding control back to the event loop.
3. Another call to `incrementUnsafe()` can run, read the same old `counter`, and later write the same new value.
4. Updates are lost.

This is the classic read-modify-write race, even in single-threaded async JavaScript.

## Corrected version: serialize with a promise-based mutex

```js
let counter = 0;

function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// A simple async mutex implemented as a promise chain.
let lockTail = Promise.resolve();

function withLock(task) {
  const previous = lockTail;

  let release;
  lockTail = new Promise(resolve => {
    release = resolve;
  });

  // Wait for the previous holder, run the task, then release.
  return previous.then(() => task()).finally(release);
}

async function incrementSafe() {
  return withLock(async () => {
    const snapshot = counter;
    await delay(10);
    counter = snapshot + 1;
  });
}

Promise.all(
  Array.from({ length: 5 }, () => incrementSafe())
).then(() => {
  console.log("Safe counter:", counter); // 5
});
```

### Why this fixes it

- `withLock()` chains each critical section behind the previous one using promises.
- Only one `task()` runs at a time from the perspective of the locked region.
- Even though `await delay(10)` yields, no other locked task can enter until the current one finishes.
- `.finally(release)` releases the lock even if the task throws, preventing deadlock.

## Important caveats

- This promise mutex coordinates work in the same JavaScript execution context / event loop. It does not protect shared memory accessed by real OS threads, such as `SharedArrayBuffer` accessed from Worker threads. For those, use `Atomics` and proper atomic lock implementations.
- Do not put synchronous infinite loops or heavy CPU work inside the lock without yielding; you can still block the event loop.
- Keep critical sections as small as possible to avoid unnecessary serialization.

## Common pitfalls with synchronization and locks in JavaScript

JavaScript is single-threaded per **agent** (main thread / worker), but async work can interleave at `await`, timer, I/O, and message boundaries. True parallelism only happens across workers/threads via `SharedArrayBuffer` + `Atomics`. Most bugs come from mixing these two worlds.

Below are the most common pitfalls, with idiomatic code.

---

### 1. Assuming “single-threaded” means no races

Async functions can interleave between `await` points.

```js
let balance = 100;

async function withdraw(amount) {
  if (balance >= amount) {
    await Promise.resolve(); // simulated I/O / timer
    balance -= amount;
  }
}

withdraw(60);
withdraw(60); // both can pass the check before either subtracts
// balance can become -20
```

**Fix:** protect the whole check-then-act sequence with an async mutex.

```js
class AsyncMutex {
  constructor() {
    this.locked = false;
    this.queue = [];
  }
  lock() {
    return new Promise(resolve => {
      if (!this.locked) {
        this.locked = true;
        resolve();
      } else {
        this.queue.push(resolve);
      }
    });
  }
  unlock() {
    if (this.queue.length) {
      const next = this.queue.shift();
      next(); // lock stays held
    } else {
      this.locked = false;
    }
  }
}

const m = new AsyncMutex();

async function safeWithdraw(amount) {
  await m.lock();
  try {
    if (balance >= amount) {
      await Promise.resolve();
      balance -= amount;
    }
  } finally {
    m.unlock();
  }
}
```

---

### 2. Not releasing the lock on an exception

If code throws between `lock()` and `unlock()`, the mutex stays locked forever.

```js
await m.lock();
doSomethingThatMayThrow(); // if this throws, unlock is skipped
m.unlock();
```

**Fix:** always use `try/finally`.

```js
await m.lock();
try {
  await riskyOperation();
} finally {
  m.unlock();
}
```

---

### 3. Holding a lock across an `await` boundary

This serializes unrelated work and can cause starvation or deadlock.

```js
await dbMutex.lock();
try {
  const user = await fetchUser(id);     // network I/O while holding lock
  const posts = await fetchPosts(user); // more I/O while holding lock
  return posts;
} finally {
  dbMutex.unlock();
}
```

**Better:** keep critical sections tiny; fetch outside, then lock only for shared-state mutation.

```js
const user = await fetchUser(id);
const posts = await fetchPosts(user);

await dbMutex.lock();
try {
  cache.set(id, posts);
} finally {
  dbMutex.unlock();
}
```

---

### 4. Deadlock from inconsistent lock ordering

Two tasks acquire the same two locks in opposite order.

```js
const a = new AsyncMutex();
const b = new AsyncMutex();

async function task1() {
  await a.lock();
  await b.lock(); // waits for b
  // ...
  b.unlock();
  a.unlock();
}

async function task2() {
  await b.lock();
  await a.lock(); // waits for a -> deadlock
  // ...
}
```

**Fix:** define a global lock order and always acquire in that order. If you cannot, use `tryLock`/timeout and back off.

```js
// Always a before b
async function task2Fixed() {
  await a.lock();
  await b.lock();
  // ...
  b.unlock();
  a.unlock();
}
```

---

### 5. Non-reentrant locks and recursive acquisition

A non-reentrant mutex deadlocks if the same logical owner locks it twice.

```js
async function outer() {
  await m.lock();
  await inner(); // inner also locks m -> never resolves
  m.unlock();
}

async function inner() {
  await m.lock();
  // ...
  m.unlock();
}
```

**Fix:** either make the mutex reentrant (track owner + count), or restructure so nested calls do not lock. Reentrant version:

```js
class ReentrantMutex {
  constructor() {
    this.owner = null;
    this.count = 0;
    this.queue = [];
  }
  async lock() {
    const id = this._callerId();
    if (this.owner === id) { this.count++; return; }
    await new Promise(resolve => {
      if (!this.owner) { this.owner = id; this.count = 1; resolve(); }
      else this.queue.push({ id, resolve });
    });
  }
  unlock() {
    if (--this.count === 0) {
      this.owner = null;
      const next = this.queue.shift();
      if (next) { this.owner = next.id; this.count = 1; next.resolve(); }
    }
  }
  _callerId() { return Symbol.for("caller"); } // placeholder; use AsyncLocalStorage in Node
}
```

In real code, identify owners with `AsyncLocalStorage` (Node) or a token passed explicitly.

---

### 6. Waiting for an event that needs the lock you hold

Classic self-deadlock: you hold a lock and `await` something that can only complete if another task acquires the same lock.

```js
const q = [];
const m = new AsyncMutex();

async function producer(item) {
  await m.lock();
  try {
    q.push(item);
    // waiting for consumer to drain, but consumer needs m
    await waitForDrain(); // never happens
  } finally {
    m.unlock();
  }
}
```

**Fix:** release the lock before waiting, or use condition variables / message passing.

```js
await m.lock();
q.push(item);
m.unlock();
await waitForDrain(); // no lock held
```

---

### 7. Misusing `Atomics` on the main thread

`Atomics.wait()` blocks the thread. In browsers it is not allowed on the main thread and throws; in Node it blocks the event loop.

```js
// Browser main thread
const sab = new SharedArrayBuffer(4);
const view = new Int32Array(sab);
Atomics.wait(view, 0, 0); // TypeError in browser main thread
```

**Fix:** use `Atomics.waitAsync()` on the main thread, or move blocking waits to a worker.

```js
const { value, async } = Atomics.waitAsync(view, 0, 0);
if (async) {
  value.then(() => console.log("woken"));
} else {
  console.log("already changed");
}
```

---

### 8. Memory visibility bugs without `Atomics`

Plain reads/writes to a `SharedArrayBuffer` are not guaranteed to be visible across threads in the way you expect; use `Atomics`.

```js
// Thread A
shared[0] = 42; // may not be visible to B promptly / safely

// Thread B
console.log(shared[0]); // can see stale or torn values
```

**Fix:** use atomic operations.

```js
Atomics.store(shared, 0, 42);   // Thread A
// ...
const v = Atomics.load(shared, 0); // Thread B
```

---

### 9. Check-then-act races across workers

Even simple `if` + assignment is a race when multiple threads touch shared memory.

```js
// Worker A and B both run:
if (Atomics.load(counter, 0) === 0) {
  Atomics.store(counter, 0, 1); // both can enter
}
```

**Fix:** use atomic compare-exchange.

```js
const old = Atomics.compareExchange(counter, 0, 0, 1);
if (old === 0) {
  // exactly one thread wins
}
```

---

### 10. Lost wakeups and spurious wakeups with condition variables

With `Atomics.wait/notify`, a notify that happens before the wait is lost. Also waits can wake spuriously, so always re-check the predicate in a loop.

```js
// Buggy: single wait, no predicate recheck
Atomics.wait(view, 0, 0);
console.log("proceed"); // may proceed on spurious wakeup
```

**Fix:** loop on the condition.

```js
// Waiter
while (Atomics.load(view, 0) !== 1) {
  Atomics.wait(view, 0, 0);
}

// Signaler
Atomics.store(view, 0, 1);
Atomics.notify(view, 0, 1);
```

---

### 11. Starvation from unfair or recursive locking

A FIFO mutex can still starve if a task keeps re-locking before others get a turn, or if high-priority tasks dominate.

```js
// A hot loop keeps reacquiring; others wait forever
while (running) {
  await m.lock();
  doQuickWork();
  m.unlock();
  // no yield point for waiters in some patterns
}
```

**Fix:** yield with `setTimeout(0)` or `setImmediate`, use fair queues, and avoid tight lock/unlock loops. In Node, `setImmediate` helps the event loop serve waiters.

```js
while (running) {
  await m.lock();
  try { doQuickWork(); }
  finally { m.unlock(); }
  await new Promise(r => setImmediate(r));
}
```

---

### 12. Livelock

Tasks keep responding to each other but make no progress.

```js
async function taskA() {
  while (!done) {
    await lockA.lock();
    if (!canProceedA()) { lockA.unlock(); continue; } // yields and retries
  }
}
```

**Fix:** add backoff, randomized delays, or a single coordinator. Avoid “polite” retry loops without progress guarantees.

---

### 13. Releasing a lock more than once

Double-unlock can hand the lock to two waiters or corrupt state.

```js
m.unlock();
m.unlock(); // second call may wake another waiter incorrectly
```

**Fix:** track ownership and throw on invalid unlock.

```js
unlock(token) {
  if (this.owner !== token) throw new Error("Not owner");
  this.owner = null;
  // wake one waiter
}
```

---

### 14. Locks do not automatically span workers/realms

A mutex object in the main thread is not shared with a worker. Each realm has its own.

```js
// main.js
const m = new AsyncMutex();
worker.postMessage({ type: "work" }); // worker has its own m, no coordination
```

**Fix:** use a `SharedArrayBuffer`-based lock (Atomics) or message-passing ownership.

```js
// Shared lock state
const sab = new SharedArrayBuffer(4);
const lock = new Int32Array(sab);

function tryLock() {
  return Atomics.compareExchange(lock, 0, 0, 1) === 0;
}
function unlock() {
  Atomics.store(lock, 0, 0);
  Atomics.notify(lock, 0, 1);
}
```

---

### 15. Unhandled rejections inside lock queues

If a queued waiter’s callback throws or a promise rejects unexpectedly, the queue can stall.

```js
this.queue.push(resolve);
// later: resolve() is fine, but if resolve callback throws, queue breaks
```

**Fix:** wrap resolution in try/catch and ensure `unlock` always runs in `finally`. Also avoid throwing inside lock acquisition.

```js
lock() {
  return new Promise((resolve, reject) => {
    const run = () => {
      try { resolve(); }
      catch (e) { reject(e); }
    };
    // ...
  });
}
```

---

### 16. False sharing and cache-line contention

Two unrelated counters in the same cache line cause threads to invalidate each other’s caches.

```js
const shared = new Int32Array(sab); // [counterA, counterB] adjacent
// Thread A writes counterA; Thread B writes counterB -> cache bouncing
```

**Fix:** pad to separate cache lines (typically 64 bytes).

```js
const STRIDE = 16; // 16 Int32s = 64 bytes
const aIndex = 0;
const bIndex = STRIDE;
Atomics.add(shared, aIndex, 1);
Atomics.add(shared, bIndex, 1);
```

---

### Quick checklist

- Treat every `await` as a possible context switch.
- Always `try/finally` around unlock.
- Keep critical sections small and avoid I/O while locked.
- Use a consistent lock order.
- Use `Atomics` for all shared-memory coordination.
- Re-check predicates in wait loops.
- Never block the main thread; use `waitAsync` or workers.
- Do not share ordinary mutex objects across workers.

If you want, I can also provide a production-ready async mutex/semaphore implementation with timeout, cancellation, and `Symbol.asyncDispose` support.

## Exercise

Write two async functions that each increment a shared counter 1,000 times, but simulate real async work between reading and writing the counter (for example, `await new Promise(r => setTimeout(r, 0))`). Run both concurrently with `Promise.all`. Without synchronization, the final count will usually be **less than 2,000** because of lost updates.

Then implement an **async mutex/lock** so the critical section is serialized, and verify the final count is exactly 2,000.

---

## Step-by-step solution

### 1. The broken version

```js
let counter = 0;

function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function incrementMany(n) {
  for (let i = 0; i < n; i++) {
    const current = counter;        // read
    await delay(0);                 // async gap: other task may run here
    counter = current + 1;          // write (may overwrite another update)
  }
}

async function main() {
  await Promise.all([
    incrementMany(1000),
    incrementMany(1000),
  ]);
  console.log("counter =", counter); // expected 2000, often lower
}

main();
```

Why it fails: JavaScript is single-threaded, but `await` yields control. Task A can read `counter`, pause, then Task B reads the same stale value and writes. Task A resumes and writes the same incremented value, losing B’s update.

### 2. Async mutex using promise chaining

A robust pattern is a mutex whose internal state is just a promise chain. `lock()` waits for the previous holder to finish, then returns an `unlock` function.

```js
class Mutex {
  constructor() {
    // Resolved promise means “lock is free”.
    this._tail = Promise.resolve();
  }

  /**
   * Acquire the lock. Resolves with an unlock function.
   * Always call unlock in finally.
   */
  lock() {
    let unlock;
    const wait = new Promise(resolve => {
      unlock = resolve;
    });

    // Chain: previous lock -> wait for unlock
    const prev = this._tail;
    this._tail = wait;

    // Caller gets control only after previous holder unlocks.
    return prev.then(() => unlock);
  }
}
```

Usage:

```js
const mutex = new Mutex();

async function incrementMany(n) {
  for (let i = 0; i < n; i++) {
    const unlock = await mutex.lock();
    try {
      const current = counter;
      await delay(0);
      counter = current + 1;
    } finally {
      unlock();
    }
  }
}
```

This serializes the critical section: only one async flow reads-modifies-writes at a time.

### 3. Make it ergonomic with `runExclusive`

Repeatedly writing `await lock(); try {...} finally { unlock(); }` is error-prone. Add a helper:

```js
class Mutex {
  constructor() {
    this._tail = Promise.resolve();
  }

  lock() {
    let unlock;
    const wait = new Promise(resolve => (unlock = resolve));
    const prev = this._tail;
    this._tail = wait;
    return prev.then(() => unlock);
  }

  async runExclusive(fn) {
    const unlock = await this.lock();
    try {
      return await fn();
    } finally {
      unlock();
    }
  }
}
```

Now the critical section is concise:

```js
async function incrementMany(n) {
  for (let i = 0; i < n; i++) {
    await mutex.runExclusive(async () => {
      const current = counter;
      await delay(0);
      counter = current + 1;
    });
  }
}
```

### 4. Verification harness

```js
async function main() {
  counter = 0;

  await Promise.all([
    incrementMany(1000),
    incrementMany(1000),
  ]);

  console.log("counter =", counter); // 2000
  console.assert(counter === 2000, "Lost updates detected");
}

main().catch(console.error);
```

Expected output:

```
counter = 2000
```

### 5. Important notes

- This mutex protects **async critical sections** in one JS runtime/thread. It does not protect across processes or Web Workers; for those, use `SharedArrayBuffer` + `Atomics`.
- Keep critical sections short. Holding a lock across long I/O delays throughput.
- Always release in `finally`, otherwise one thrown error can deadlock all future callers.
- The promise-chain mutex is reentrancy-safe for the same mutex instance, but a single async flow should not call `lock()` twice without unlocking; otherwise it will deadlock with itself.

