# Test-Driven Development in JavaScript — Complete Runnable Example

Below is a full TDD walkthrough using the classic **String Calculator kata**. It uses Node's built-in test runner, so you need **no `npm install`** — just Node 18+.

## 1. Project layout

```
string-calc/
├── stringCalculator.js      # implementation
└── stringCalculator.test.js # tests
```

## 2. The TDD cycle

1. **Red** — write a failing test for the next smallest behavior.
2. **Green** — write the minimum code to make it pass.
3. **Refactor** — clean up while tests stay green.

We repeat this, one requirement at a time.

## 3. Step-by-step (Red → Green → Refactor)

### Requirement 1: empty string → 0

**Test (Red):**
```js
test('empty string returns 0', () => {
  assert.equal(add(''), 0);
});
```
Run → fails (`add` is not defined).

**Green:**
```js
function add(numbers) {
  return 0;
}
```
Passes, but is a stub. We'll generalize as more tests arrive.

### Requirement 2: single number

**Test:**
```js
test('single number returns itself', () => {
  assert.equal(add('1'), 1);
});
```
**Green:**
```js
function add(numbers) {
  if (numbers === '') return 0;
  return Number(numbers);
}
```

### Requirement 3: two numbers, comma-delimited

**Test:**
```js
test('two numbers summed', () => {
  assert.equal(add('1,2'), 3);
});
```
**Green:**
```js
function add(numbers) {
  if (numbers === '') return 0;
  return numbers.split(',').reduce((a, n) => a + Number(n), 0);
}
```
(Also still passes requirement 2.)

### Requirement 4: any amount of numbers / newlines

**Tests:**
```js
test('many numbers', () => assert.equal(add('1,2,3,4'), 10));
test('newlines as delimiter', () => assert.equal(add('1\n2,3'), 6));
```
**Green:** replace `,` with `/[,\n]/`.

### Requirement 5: custom delimiter `//[delim]\n...`

**Test:**
```js
test('custom delimiter', () => assert.equal(add('//;\n1;2'), 3));
```
**Green:** parse the first line when it starts with `//`.

### Requirement 6: negatives throw with all negatives listed

**Test:**
```js
test('negatives throw', () => {
  assert.throws(() => add('1,-2,3,-4'), /negatives not allowed: -2,-4/);
});
```

### Requirement 7: ignore numbers > 1000

### Requirement 8: delimiters of any length `//[***]`

### Requirement 9: multiple delimiters `//[*][%]`

Final refactored implementation below.

## 4. Final files

### `stringCalculator.js`

```js
function add(numbers) {
  if (numbers === '') return 0;

  let delimiter = /,|\n/;
  let body = numbers;

  // Custom delimiter header: "//<spec>\n<numbers>"
  if (numbers.startsWith('//')) {
    const newlineIndex = numbers.indexOf('\n');
    const spec = numbers.slice(2, newlineIndex);
    body = numbers.slice(newlineIndex + 1);

    const delimiters = [];
    const bracketRegex = /\[([^\]]+)\]/g;
    let match;
    let hasBrackets = false;

    while ((match = bracketRegex.exec(spec)) !== null) {
      hasBrackets = true;
      delimiters.push(escapeRegex(match[1]));
    }
    if (!hasBrackets) {
      delimiters.push(escapeRegex(spec));
    }
    delimiter = new RegExp(delimiters.join('|'));
  }

  const tokens = body.split(delimiter).filter((t) => t !== '');
  const nums = tokens.map((t) => parseInt(t, 10));

  const negatives = nums.filter((n) => n < 0);
  if (negatives.length > 0) {
    throw new Error(`negatives not allowed: ${negatives.join(',')}`);
  }

  // Ignore numbers greater than 1000
  return nums.filter((n) => n <= 1000).reduce((a, b) => a + b, 0);
}

function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

module.exports = { add };
```

### `stringCalculator.test.js`

```js
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { add } = require('./stringCalculator');

test('returns 0 for empty string', () => {
  assert.equal(add(''), 0);
});

test('returns the number for a single number', () => {
  assert.equal(add('1'), 1);
});

test('returns sum of two comma-separated numbers', () => {
  assert.equal(add('1,2'), 3);
});

test('returns sum of many numbers', () => {
  assert.equal(add('1,2,3,4,5'), 15);
});

test('supports newlines as delimiter', () => {
  assert.equal(add('1\n2,3'), 6);
});

test('supports custom single-char delimiter', () => {
  assert.equal(add('//;\n1;2'), 3);
});

test('throws listing all negatives', () => {
  assert.throws(() => add('1,-2,3,-4'), /negatives not allowed: -2,-4/);
});

test('ignores numbers greater than 1000', () => {
  assert.equal(add('2,1001,6'), 8);
});

test('supports delimiters of any length', () => {
  assert.equal(add('//[***]\n1***2***3'), 6);
});

test('supports multiple delimiters', () => {
  assert.equal(add('//[*][%]\n1*2%3'), 6);
});
```

