Below is a **complete, runnable Node.js example** that:

1. Implements several algorithms with different **time** and **space** complexities.
2. Measures their actual runtime and heap usage.
3. Empirically estimates growth by comparing measurements for `n` and `2n`.
4. Prints a readable table.

Save as `complexity.js` and run with:

```bash
node --expose-gc complexity.js
```

The `--expose-gc` flag makes memory measurements much more stable.

```js
'use strict';

const { performance } = require('perf_hooks');

/* ----------------------------- Utilities ----------------------------- */

function nowNs() {
  return process.hrtime.bigint();
}

function timeFunction(fn, ...args) {
  const start = nowNs();
  const result = fn(...args);
  const end = nowNs();
  return { result, ns: Number(end - start) };
}

function spaceFunction(fn, ...args) {
  if (typeof global.gc === 'function') global.gc();
  const before = process.memoryUsage().heapUsed;
  const result = fn(...args);
  if (typeof global.gc === 'function') global.gc();
  const after = process.memoryUsage().heapUsed;
  return { result, bytes: Math.max(0, after - before) };
}

function median(values) {
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2;
}

function measureTimeMedian(fn, n, trials = 7) {
  const samples = [];
  for (let i = 0; i < trials; i++) {
    samples.push(timeFunction(fn, n).ns);
  }
  return median(samples);
}

function measureSpaceOnce(fn, n) {
  return spaceFunction(fn, n).bytes;
}

function classifyTimeRatio(ratio) {
  if (ratio < 1.25) return 'O(1) / O(log n)';
  if (ratio < 2.6) return 'O(n)';
  if (ratio < 3.2) return 'O(n log n)';
  if (ratio < 5.0) return 'O(n^2)';
  return 'O(2^n) or worse';
}

function classifySpaceRatio(ratio) {
  if (ratio < 1.25) return 'O(1) / O(log n)';
  if (ratio < 2.6) return 'O(n)';
  if (ratio < 5.0) return 'O(n^2)';
  return 'O(2^n) or worse';
}

/* ----------------------------- Algorithms ----------------------------- */

// Time: O(1), Space: O(1)
function constantTime(n) {
  return n * 2 + 7;
}

// Time: O(n), Space: O(1)
function linearTime(n) {
  let sum = 0;
  for (let i = 0; i < n; i++) sum += i;
  return sum;
}

// Time: O(n^2), Space: O(1)
function quadraticTime(n) {
  let sum = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      sum += i * j;
    }
  }
  return sum;
}

// Time: O(log n), Space: O(1)
function logarithmicTime(n) {
  let count = 0;
  let x = Math.max(1, n);
  while (x > 1) {
    x = Math.floor(x / 2);
    count++;
  }
  return count;
}

// Time: O(n log n), Space: O(n) for the temporary array
function linearithmicTime(n) {
  const arr = Array.from({ length: n }, (_, i) => n - i);
  // A simple O(n log n) operation: sort
  return arr.sort((a, b) => a - b).length;
}

// Time: O(2^n), Space: O(n) recursion stack
function exponentialTime(n) {
  if (n <= 1) return n;
  return exponentialTime(n - 1) + exponentialTime(n - 2);
}

// Space: O(n)
function linearSpace(n) {
  const arr = new Array(n);
  for (let i = 0; i < n; i++) arr[i] = i;
  return arr.length;
}

// Space: O(n^2)
function quadraticSpace(n) {
  const matrix = [];
  for (let i = 0; i < n; i++) {
    const row = new Array(n);
    for (let j = 0; j < n; j++) row[j] = i * j;
    matrix.push(row);
  }
  return matrix.length;
}

// Space: O(log n) due to recursion depth
function logarithmicSpace(n, lo = 0, hi = null) {
  if (hi === null) hi = Math.max(1, n) - 1;
  if (lo > hi) return -1;
  const mid = Math.floor((lo + hi) / 2);
  // Recurse on one half only
  return logarithmicSpace(Math.floor(n / 2), lo, mid - 1);
}

/* ----------------------------- Experiment ----------------------------- */

const timeCases = [
  { name: 'constantTime', fn: constantTime, n: 100000, complexity: 'O(1)' },
  { name: 'linearTime', fn: linearTime, n: 100000, complexity: 'O(n)' },
  { name: 'quadraticTime', fn: quadraticTime, n: 300, complexity: 'O(n^2)' },
  { name: 'logarithmicTime', fn: logarithmicTime, n: 100000, complexity: 'O(log n)' },
  { name: 'linearithmicTime', fn: linearithmicTime, n: 100000, complexity: 'O(n log n)' },
  { name: 'exponentialTime', fn: exponentialTime, n: 18, complexity: 'O(2^n)' },
];

const spaceCases = [
  { name: 'constantTime-space', fn: constantTime, n: 100000, complexity: 'O(1)' },
  { name: 'linearSpace', fn: linearSpace, n: 100000, complexity: 'O(n)' },
  { name: 'quadraticSpace', fn: quadraticSpace, n: 300, complexity: 'O(n^2)' },
  { name: 'logarithmicSpace', fn: logarithmicSpace, n: 100000, complexity: 'O(log n)' },
];

console.log('=== TIME COMPLEXITY (measured, n then 2n) ===');
console.log('name'.padEnd(22), 'declared'.padEnd(12), 'n'.padStart(8), 'time(n) ms'.padStart(12), 'time(2n) ms'.padStart(13), 'ratio'.padStart(8), 'estimated'.padStart(20));
for (const c of timeCases) {
  const t1 = measureTimeMedian(c.fn, c.n);
  const t2 = measureTimeMedian(c.fn, c.n * 2);
  const ratio = t2 / (t1 || 1);
  console.log(
    c.name.padEnd(22),
    c.complexity.padEnd(12),
    String(c.n).padStart(8),
    (t1 / 1e6).toFixed(3).padStart(12),
    (t2 / 1e6).toFixed(3).padStart(13),
    ratio.toFixed(2).padStart(8),
    classifyTimeRatio(ratio).padStart(20)
  );
}

console.log('\n=== SPACE COMPLEXITY (heap delta, n then 2n) ===');
console.log('name'.padEnd(22), 'declared'.padEnd(12), 'n'.padStart(8), 'space(n) KB'.padStart(13), 'space(2n) KB'.padStart(14), 'ratio'.padStart(8), 'estimated'.padStart(20));
for (const c of spaceCases) {
  const s1 = measureSpaceOnce(c.fn, c.n);
  const s2 = measureSpaceOnce(c.fn, c.n * 2);
  const ratio = s2 / (s1 || 1);
  console.log(
    c.name.padEnd(22),
    c.complexity.padEnd(12),
    String(c.n).padStart(8),
    (s1 / 1024).toFixed(2).padStart(13),
    (s2 / 1024).toFixed(2).padStart(14),
    ratio.toFixed(2).padStart(8),
    classifySpaceRatio(ratio).padStart(20)
  );
}

console.log('\nNotes:');
console.log('- Ratios are most reliable for polynomial complexities.');
console.log('- Exponential cases grow too fast for large n; keep n small.');
console.log('- Space measurements are noisy due to allocator/GC behavior.');
console.log('- Run with --expose-gc for better memory numbers.');
```

### What this demonstrates

- **Time complexity** is reflected by how runtime grows when input size doubles:
  - `O(1)`: ratio ≈ 1
  - `O(log n)`: ratio ≈ 1
  - `O(n)`: ratio ≈ 2
  - `O(n log n)`: ratio ≈ 2–3
  - `O(n^2)`: ratio ≈ 4
  - `O(2^n)`: ratio explodes

- **Space complexity** is reflected by heap growth:
  - `O(1)`: nearly flat
  - `O(n)`: roughly doubles
  - `O(n^2)`: roughly quadruples

### Important caveats

- JavaScript engines optimize hot code, so tiny functions may appear faster than expected.
- Memory measurements depend on allocation strategy and garbage collection.
- Empirical ratios classify growth trends; they do not prove formal Big-O bounds. Formal analysis still requires reasoning about loops, recursion, and data structures.

## 1. The idea (Big-O in a nutshell)

**Time complexity** estimates how the *number of operations* grows as input size `n` grows.  
**Space complexity** estimates how *extra memory* grows (not counting the input itself, unless stated).

We use **Big-O** to describe the *worst-case* (or sometimes average) growth rate, ignoring constants and lower-order terms:

- `O(1)` — constant
- `O(log n)` — logarithmic
- `O(n)` — linear
- `O(n log n)` — linearithmic
- `O(n²)` — quadratic
- `O(2ⁿ)` — exponential

> Rule of thumb: **drop constants** (`O(2n)` → `O(n)`), **keep the dominant term** (`O(n² + n)` → `O(n²)`).

---

## 2. Time complexity — syntax & examples

### O(1): direct access, no loops over input
```js
function getFirst(arr) {
  return arr[0];        // one operation regardless of length
}
function hasKey(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}
```

### O(n): single pass
```js
function sum(arr) {
  let total = 0;
  for (const x of arr) total += x;  // n iterations
  return total;
}
// Also: arr.forEach, for...of, while with index++
```

### O(n²): nested loops over same input
```js
function hasDuplicateNaive(arr) {
  for (let i = 0; i < arr.length; i++) {
    for (let j = i + 1; j < arr.length; j++) {
      if (arr[i] === arr[j]) return true;
    }
  }
  return false;
}
```

### O(log n): halving the problem each step
```js
function binarySearch(sorted, target) {
  let lo = 0, hi = sorted.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (sorted[mid] === target) return mid;
    if (sorted[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}
```

### O(n log n): divide + conquer / sorting
```js
const sorted = arr.slice().sort((a, b) => a - b); // V8: Timsort ~ O(n log n)
```

---

## 3. Space complexity — syntax & examples

Space = **auxiliary** memory you allocate (call stack, new arrays, hash tables), **excluding** the input unless specified.

### O(1) extra space
```js
function reverseInPlace(arr) {
  let l = 0, r = arr.length - 1;
  while (l < r) {
    [arr[l], arr[r]] = [arr[r], arr[l]];
    l++; r--;
  }
  // only a few variables; array mutated in place
}
```

### O(n) extra space
```js
function doubleAll(arr) {
  const out = new Array(arr.length);
  for (let i = 0; i < arr.length; i++) out[i] = arr[i] * 2;
  return out; // new array of size n
}
```

### O(n) from recursion (call stack)
```js
function factorial(n) {
  if (n <= 1) return 1;
  return n * factorial(n - 1); // n stack frames
}
```

### O(n) from a hash set (classic trade-off)
```js
function hasDuplicateFast(arr) {
  const seen = new Set();
  for (const x of arr) {
    if (seen.has(x)) return true;
    seen.add(x);
  }
  return false; // O(n) time, O(n) space
}
```

---

## 4. JavaScript-specific nuances

| Construct | Typical complexity | Notes |
|---|---|---|
| `arr[i]`, `arr.push`, `arr.pop` | O(1) amortized | `push` may resize underlying buffer occasionally |
| `arr.shift`, `arr.unshift` | O(n) | elements re-indexed |
| `arr.splice` (middle) | O(n) | |
| `obj[key]`, `obj[key]=v`, `delete obj[key]` | O(1) avg | hash table; worst-case O(n) with collisions (rare in V8) |
| `Map`/`Set` get/set/has/delete | O(1) avg | preferred over plain objects for arbitrary keys |
| `str += chunk` in a loop | O(n²) worst-case conceptually | engines optimize, but for huge strings use array + `join` |
| `Array.prototype.sort` | O(n log n) | engine-dependent (Timsort/QuickSort hybrid) |
| `JSON.parse` / `JSON.stringify` | O(n) | n = serialized size |
| Recursion depth | O(depth) space | V8 has stack limits (~10k–100k depending on frame size) |

### String immutability gotcha
```js
// O(n²) conceptually: each += creates a new string
let s = '';
for (let i = 0; i < n; i++) s += 'a';

// O(n): build array, join once
const parts = [];
for (let i = 0; i < n; i++) parts.push('a');
const s2 = parts.join('');
```

---

## 5. Typical use cases / decision guide

- **Small n (< ~100):** clarity > micro-optimization; O(n²) is fine.
- **Hot loops / large data:** prefer O(n) or O(n log n); avoid nested scans.
- **Memory-constrained (mobile, workers):** trade time for space; avoid giant intermediate arrays.
- **API boundaries:** validate size; reject `n` that makes O(n²) explode.
- **Interview / code review:** state both time *and* space; mention amortized when relevant.

### Common pattern: time–space trade-off
```js
// Time O(n²), Space O(1)
function twoSumBrute(nums, target) { /* nested loops */ }

// Time O(n), Space O(n)
function twoSumFast(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need), i];
    seen.set(nums[i], i);
  }
}
```

---

## 6. Quick self-check checklist

1. Count **loop nesting** → multiply complexities.
2. Count **new collections** you allocate → space.
3. Count **recursion depth** → space.
4. Replace `O(n²)` scans with a `Map`/`Set` when possible.
5. Remember: **amortized** `push` is still O(1) per op on average.

If you want, I can walk through analyzing a specific function you have in mind.

## Typical mistake: repeated string concatenation in a loop

```js
function makePadding(n) {
  let result = "";
  for (let i = 0; i < n; i++) {
    result += " "; // strings are immutable in JavaScript
  }
  return result;
}
```

### Why this is bad

JavaScript strings are immutable. Writing `result += " "` does not append to the existing string; it creates a **new string** every iteration and copies all previous characters into it.

- Time: `1 + 2 + ... + n = O(n²)`
- Space: each intermediate string is discarded, creating `O(n²)` total allocated memory churn and extra GC pressure
- The final string itself is only `O(n)`, so most of the work and allocation was wasted

---

## Corrected version

```js
function makePadding(n) {
  return " ".repeat(n);
}
```

Or, if you are building a more complex string from multiple pieces:

```js
function buildMessage(parts) {
  const chunks = [];
  for (const part of parts) {
    chunks.push(part);
  }
  return chunks.join("");
}
```

### Why this is better

- `String.prototype.repeat` is implemented natively, usually as a single efficient allocation followed by copying/filling
- Time becomes `O(n)`
- Space stays proportional to the final output, `O(n)`, without quadratic intermediate allocations
- Using an array plus `join("")` is a good general pattern when multiple variable-sized pieces must be combined

---

## Key takeaway

In JavaScript, avoid patterns that repeatedly concatenate immutable values, especially inside loops. Prefer bulk operations such as `repeat`, `join`, or direct array construction when the final result size is known or can be built in one pass.

Below are common, JavaScript-specific pitfalls when reasoning about time/space complexity. Each includes a short explanation and code.

---

### 1. Assuming array methods are O(1)

Many array operations shift elements and are **O(n)**, even though they look like “just push one item.”

```js
const a = [1, 2, 3];

a.push(4);        // O(1) amortized (usually fine)
a.unshift(0);     // O(n) — shifts ALL elements
a.splice(1, 0, 9); // O(n) — shifts tail
a.indexOf(3);     // O(n)
a.includes(3);    // O(n)
```

**Pitfall:** Using `unshift`/`splice` in a hot loop turns an “O(n) algorithm” into **O(n²)**.

```js
// Bad: O(n²)
const result = [];
for (const x of huge) result.unshift(x);

// Good: O(n) (reverse later if order matters)
const result2 = [];
for (const x of huge) result2.push(x);
result2.reverse();
```

---

### 2. Hidden O(n) copies (spread, slice, concat)

The spread operator and many array helpers **allocate a new array and copy elements**.

```js
const a = [1, 2, 3];

const b = [...a];           // O(n) space + time
const c = a.slice();        // O(n)
const d = a.concat([]);     // O(n)
const e = Array.from(a);    // O(n)
```

**Pitfall:** Doing this inside a loop or recursive function inflates space to **O(n²)** or worse.

```js
// Bad: each recursion level copies; O(n²) space/time
function sum(arr) {
  if (arr.length === 0) return 0;
  return arr[0] + sum(arr.slice(1)); // slice is O(n)
}

// Good: index-based, O(n) time, O(n) stack (or iterative)
function sum2(arr, i = 0) {
  if (i >= arr.length) return 0;
  return arr[i] + sum2(arr, i + 1);
}
```

---

### 3. String concatenation in loops

Modern engines optimize some cases, but repeated `+=` in a loop can still be **O(n²)** worst-case depending on engine/version. `Array.prototype.join` is the safe, linear choice.

```js
// Risky
let s = "";
for (let i = 0; i < n; i++) s += "x"; // may be O(n²) in some engines

// Safe
const parts = [];
for (let i = 0; i < n; i++) parts.push("x");
const s2 = parts.join("");
```

---

### 4. Object vs. Map/Set complexity assumptions

Plain objects are hash maps with **amortized O(1)** access, but with caveats:
- Keys are coerced to strings (`1` and `"1"` collide).
- Prototype chain adds lookups and inherited properties.
- Hash collisions can degrade to **O(n)** in pathological cases.
- `delete` on objects can deoptimize hidden classes.

```js
const o = {};
o[1] = "a"; o["1"] = "b"; // same key

// Better for arbitrary keys / guaranteed average O(1)
const m = new Map();
m.set(1, "a");
m.set("1", "b"); // distinct keys

const s = new Set([1, 2, 3]);
s.has(2); // O(1) average
```

**Pitfall:** Using an object as a generic dictionary with non-string keys, or relying on iteration order guarantees that differ from Map.

---

### 5. `delete` on arrays creates holes (sparse arrays)

`delete arr[i]` does **not** remove the slot; it makes the array sparse, which hurts both correctness and performance.

```js
const arr = [1, 2, 3];
delete arr[1];
console.log(arr);        // [1, <1 empty item>, 3]
console.log(arr.length); // 3 (not 2!)

// Correct removal
arr.splice(1, 1); // O(n), but dense
// or pop/shift if end/start
```

**Space/time pitfall:** Sparse arrays can cause V8 to switch to a slower representation and make future operations slower; length stays inflated.

---

### 6. Catastrophic regex backtracking (ReDoS)

A “simple” regex can have **exponential time** on crafted input, a classic time-complexity pitfall.

```js
const bad = /^(a+)+$/;
// On "aaaaaaaaaaaaaaaaaaaaaaaaaaaaX" this can hang (exponential backtracking)

const good = /^a+$/; // linear
```

**Mitigation:** Avoid nested quantifiers, use atomic groups (not native JS; use alternation carefully), or use the `RegExp` `d`/`y` flags and timeouts. In Node, `safe-regex` / `re2` are options.

---

### 7. Recursion and the call stack (space hidden in stack)

Recursive solutions add **O(depth) stack space**, and V8 has no guaranteed tail-call optimization (unlike JSC/Safari). Deep recursion → `RangeError: Maximum call stack size exceeded`.

```js
// May overflow for n ~ 10^4–10^5
function fact(n) {
  if (n <= 1) return 1;
  return n * fact(n - 1);
}

// Iterative: O(1) extra space
function fact2(n) {
  let r = 1;
  for (let i = 2; i <= n; i++) r *= i;
  return r;
}
```

**Pitfall:** Counting only heap allocations and forgetting **stack frames** in space complexity.

---

### 8. Nested loops disguised as array methods

Chaining methods can hide **O(n²)** (or worse) complexity.

```js
const items = [...];
// O(n²): includes is O(n), inside loop O(n)
const unique = items.filter((x, i) => !items.includes(x, i + 1));

// O(n) using Set
const seen = new Set();
const unique2 = items.filter(x => seen.has(x) ? false : (seen.add(x), true));
```

Also beware: `sort` comparator must be **consistent** (transitive). An inconsistent comparator makes V8’s sort behave unpredictably; even if still O(n log n), results are wrong.

```js
// Bad comparator (inconsistent)
arr.sort((a, b) => Math.random() - 0.5);
```

---

### 9. Sorting is not “free” and not always stable historically

`Array.prototype.sort` is **O(n log n)** time and **O(n)** (or more) auxiliary space depending on engine. Comparators doing heavy work multiply cost.

```js
// O(n log n * cost(comparator))
arr.sort((a, b) => expensive(a) - expensive(b));

// Precompute keys: O(n) + O(n log n)
const keyed = arr.map(x => ({ x, key: expensive(x) }));
keyed.sort((a, b) => a.key - b.key);
```

---

### 10. Memory leaks counted as “space complexity”

Big-O space often ignores real retention. Closures, event listeners, and caches can keep memory alive beyond the algorithm’s stated auxiliary space.

```js
function makeHandler(bigData) {
  // Closure retains bigData even after use
  return () => console.log(bigData.length);
}
const h = makeHandler(new Array(1e7));
// bigData cannot be GC'd while h lives

// Fix: drop reference
function makeHandler2() {
  const bigData = new Array(1e7);
  const len = bigData.length;
  bigData.length = 0; // release
  return () => console.log(len);
}
```

Also: `Map`/`Set` don’t auto-evict; use `WeakMap`/`WeakSet` when keys are objects and you want GC-friendly storage.

---

### 11. `JSON.stringify` / `JSON.parse` and deep clone

These are **O(n)** in nodes but with large constant factors and extra memory; deep cloning via `structuredClone` is usually better and handles more types.

```js
const clone = JSON.parse(JSON.stringify(obj)); // O(n) time, O(n) space, loses types
const clone2 = structuredClone(obj);           // generally preferred
```

---

### 12. Async I/O and concurrency “complexity”

`Promise.all` over *n* tasks isn’t “free parallelism”: it schedules *n* microtasks and, for CPU-bound work, still blocks the event loop. Time complexity of the *algorithm* may be O(n), but wall-clock and memory (holding all results) scale with concurrency.

```js
// CPU-bound: blocks event loop despite Promise.all
await Promise.all(bigArray.map(cpuHeavy));

// Better: batch / worker threads / streaming
```

Also, storing all results of a stream defeats streaming space benefits:

```js
// O(n) memory though source is a stream
const all = [];
for await (const chunk of stream) all.push(chunk);
```

---

### 13. Typed arrays vs. regular arrays

Regular arrays are flexible (sparse, mixed types) but can be slower and memory-heavy. For numeric, fixed-shape data, typed arrays are denser and more predictable.

```js
const regular = new Array(1e6).fill(0); // boxed-ish, larger
const typed = new Float64Array(1e6);   // contiguous, ~8 MB
```

---

### 14. Prototype chain as hidden O(depth)

Property access walks the prototype chain; in hot paths, deep inheritance adds cost. `Object.create(null)` or `Map` avoids it.

```js
const base = { a: 1 };
const derived = Object.create(base);
// derived.b -> walks chain if missing
```

---

### Quick checklist

| Pitfall | Typical surprise |
|---|---|
| `unshift`/`splice`/`shift` | O(n), not O(1) |
| Spread/`slice`/`concat` | Allocate + copy O(n) |
| String `+=` in loop | Possible O(n²) |
| Object as dict | Key coercion, collisions, prototype |
| `delete arr[i]` | Sparse array, length unchanged |
| Regex | Exponential backtracking |
| Recursion | Stack space, no TCO in V8 |
| Nested array methods | O(n²)+ hidden |
| Sort comparator | Must be consistent; precompute keys |
| Closures/caches | Retain memory (real space) |
| JSON clone | Heavy constants; prefer `structuredClone` |
| Async overuse | Memory for all results; blocks loop if CPU-bound |

### Practical takeaway

- Treat **Big-O as a starting point**, not the whole story: engine optimizations (V8), hidden constants, and memory pressure matter.
- Prefer **Set/Map** for membership and lookup-heavy code.
- Prefer **index-based iteration** and avoid repeated copies in hot paths.
- Measure with `performance.now()` and heap snapshots (`--inspect`) rather than trusting theory alone.

## Exercise

**Two Sum with complexity trade-off**

Given an array `nums` of integers and an integer `target`, return the **indices** of the two numbers that add up to `target`. Assume every input has exactly one solution and you may not use the same element twice.

Implement **two** solutions:

1. **Brute force** (no extra data structures).
2. **Hash-map** (extra memory allowed).

Then state the **time** and **space** complexity of each and explain the trade-off.

---

## Step-by-step solution

### Approach 1 — Brute force

Compare every pair `(i, j)` with `i < j`.

```js
function twoSumBrute(nums, target) {
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      if (nums[i] + nums[j] === target) {
        return [i, j];
      }
    }
  }
  return []; // not expected per problem statement
}
```

**Complexity analysis**

- **Time:** Outer loop runs `n` times, inner loop up to `n` times → **O(n²)**.
- **Space:** Only a few variables/indices → **O(1)** auxiliary space.

This is simple and uses no extra memory, but becomes slow for large inputs.

---

### Approach 2 — Hash map (value → index)

As we iterate, check whether the **complement** (`target - nums[i]`) was already seen.

```js
function twoSumHash(nums, target) {
  const seen = new Map(); // value -> index

  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (seen.has(complement)) {
      return [seen.get(complement), i];
    }
    seen.set(nums[i], i);
  }
  return [];
}
```

**Complexity analysis**

- **Time:** Single pass; `Map` operations are amortized O(1) → **O(n)**.
- **Space:** In the worst case we store up to `n` entries → **O(n)** auxiliary space.

---

### Trade-off summary

| Approach | Time | Space | When to prefer |
|---|---|---|---|
| Brute force | O(n²) | O(1) | Tiny inputs, memory-constrained environments |
| Hash map | O(n) | O(n) | Most real-world cases (speed matters more than memory) |

**Rule of thumb:** Trading space for time is often worth it when `n` is large and memory is cheap. If you are extremely memory-constrained or `n` is small, brute force is acceptable.

---

### Edge cases / robustness notes

- **Duplicates:** `Map` stores the latest index per value; with exactly one valid pair this is fine. If you need all pairs, store arrays of indices.
- **Negative numbers / zeros:** Complement logic works unchanged.
- **Large numbers:** Use `Number.isSafeInteger` if integer overflow is a concern (rare in JS, but possible with typed arrays).
- **Input validation:** In production, guard against non-array inputs:

```js
function twoSum(nums, target) {
  if (!Array.isArray(nums)) throw new TypeError("nums must be an array");
  // ...hash-map implementation...
}
```

---

## Final recommended solution

```js
/**
 * Returns indices of two numbers that sum to target.
 * Time:  O(n)
 * Space: O(n)
 */
function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) {
      return [seen.get(need), i];
    }
    seen.set(nums[i], i);
  }
  throw new Error("No solution found");
}
```

**Example usage**

```js
console.log(twoSum([2, 7, 11, 15], 9)); // [0, 1]
console.log(twoSum([3, 2, 4], 6));       // [1, 2]
```

This version is the idiomatic choice for JavaScript: linear time, clear intent, and good readability.

## Time & Space Complexity in JavaScript (interview framing)

**Time complexity** describes how the number of primitive operations grows with input size `n`. We drop constants and lower-order terms, so `O(2n)` becomes `O(n)`.

**Space complexity** describes extra memory allocated beyond the input (auxiliary space). The input itself is usually not counted unless the problem says so.

### JavaScript-specific pitfalls
| Operation | Typical cost | Why it matters |
|---|---|---|
| `arr.push/pop` | `O(1)` amortized | Fast append |
| `arr.shift/unshift/splice` | `O(n)` | Elements shift |
| `arr.includes/indexOf` | `O(n)` | Linear scan |
| Object/`Map`/`Set` get/set | `O(1)` avg | Hash-based |
| String `+=` in a loop | `O(n²)` | Strings are immutable; use array + `join` |
| Recursion | `O(depth)` space | Call stack counts as space |
| `sort()` | `O(n log n)` | V8 uses Timsort/QuickSort hybrid |

### Common classes
- `O(1)` — hash lookup, arithmetic
- `O(log n)` — binary search on sorted data
- `O(n)` — single pass
- `O(n log n)` — efficient sorting
- `O(n²)` — nested loops over same data
- `O(2ⁿ)`, `O(n!)` — exponential/backtracking (usually too slow for large `n`)

---

## Example problem: Longest Substring Without Repeating Characters

**Goal:** Given a string `s`, return the length of the longest substring with all unique characters.

**Approach:** Sliding window with a hash map (`Map`) storing the last index of each character.

```js
/**
 * Returns the length of the longest substring without repeating characters.
 * @param {string} s
 * @returns {number}
 *
 * Time:  O(n) — single pass; each char visited at most twice (once by right,
 *        once effectively skipped by moving left).
 * Space: O(min(n, |Σ|)) — map holds at most window size / alphabet entries.
 */
function lengthOfLongestSubstring(s) {
  // char -> most recent index where it appeared
  const lastSeen = new Map();

  let left = 0;   // left boundary of window (inclusive)
  let best = 0;   // best length found so far

  for (let right = 0; right < s.length; right++) {
    const ch = s[right];

    // If ch was seen inside the current window, shrink left past it.
    // The `>= left` check is crucial: stale entries outside the window
    // must not move left backward.
    if (lastSeen.has(ch) && lastSeen.get(ch) >= left) {
      left = lastSeen.get(ch) + 1;
    }

    lastSeen.set(ch, right);

    // Window [left, right] is now guaranteed unique.
    const windowSize = right - left + 1;
    if (windowSize > best) best = windowSize;
  }

  return best;
}

// ---- Optional: also return the substring itself ----
function longestSubstring(s) {
  const lastSeen = new Map();
  let left = 0, bestStart = 0, bestLen = 0;

  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    if (lastSeen.has(ch) && lastSeen.get(ch) >= left) {
      left = lastSeen.get(ch) + 1;
    }
    lastSeen.set(ch, right);

    const len = right - left + 1;
    if (len > bestLen) {
      bestLen = len;
      bestStart = left;
    }
  }
  return s.slice(bestStart, bestStart + bestLen);
}

// ---- Quick sanity checks ----
console.log(lengthOfLongestSubstring("abcabcbb")); // 3  ("abc")
console.log(lengthOfLongestSubstring("bbbbb"));     // 1  ("b")
console.log(lengthOfLongestSubstring("pwwkew"));    // 3  ("wke")
console.log(lengthOfLongestSubstring(""));          // 0
console.log(longestSubstring("abcabcbb"));          // "abc"
```

### Why this beats the naive approach
- **Brute force** checks all `O(n²)` substrings and validates uniqueness in `O(n)` → `O(n³)` time, `O(1)` space.
- **Sliding window** reuses work: `left` only moves forward, so total work is proportional to `n`, not `n²`.

### Complexity summary for the implementation above
- **Time:** `O(n)` — one `for` loop; `Map` operations are amortized `O(1)`.
- **Space:** `O(min(n, |Σ|))` — at most one entry per distinct character currently in the window; bounded by alphabet size `|Σ|` (e.g., 26 for lowercase letters, 128 for ASCII, or `n` for arbitrary Unicode stored sparsely).

If you want, I can adapt this to another classic (e.g., Two Sum, merge intervals, or BFS shortest path) and walk through its complexity the same way.

Below is a complete, runnable in-memory transaction system for JavaScript. It implements:

- `begin()` / `commit()` / `rollback()`
- Snapshot reads (MVCC-style)
- Buffered writes
- Optimistic concurrency control
- Read/write conflict detection
- Savepoints
- A `transaction(fn)` helper
- Convenience store reads

It runs in modern Node.js or any browser with `structuredClone`.

## Design summary

Each transaction gets a `startVersion`. Reads see the latest committed version that existed when the transaction began, plus its own uncommitted writes. Writes are buffered in the transaction. On commit, the system checks that every key read or written still has the same latest committed version it had at the start. If another committed transaction changed one of those keys, the commit fails with a conflict and the transaction is rolled back.

This gives snapshot isolation with optimistic concurrency control.

## Runnable code

Save this as `transactions.js` and run with `node transactions.js`.

```js
class TransactionConflictError extends Error {
  constructor(message) {
    super(message);
    this.name = 'TransactionConflictError';
  }
}

function cloneValue(value) {
  if (value === undefined) return undefined;
  try {
    return structuredClone(value);
  } catch {
    // Fallback for non-cloneable values.
    return value;
  }
}

class TransactionalStore {
  constructor() {
    // key -> array of committed versions, oldest to newest
    this.history = new Map();
    this.globalVersion = 0;
    this.activeTransactions = new Set();
  }

  _versions(key) {
    return this.history.get(key) || [];
  }

  getVisibleEntry(key, version) {
    const versions = this._versions(key);
    let visible = null;
    for (const entry of versions) {
      if (entry.version <= version) visible = entry;
      else break;
    }
    return visible;
  }

  getLatestVersion(key) {
    const versions = this._versions(key);
    return versions.length ? versions[versions.length - 1].version : 0;
  }

  begin() {
    const tx = new Transaction(this);
    this.activeTransactions.add(tx);
    return tx;
  }

  transaction(fn) {
    const tx = this.begin();
    try {
      const result = fn(tx);

      // Support async transaction functions.
      if (result && typeof result.then === 'function') {
        return result.then(
          (value) => {
            tx.commit();
            return value;
          },
          (error) => {
            if (tx.state === 'active') tx.rollback();
            throw error;
          }
        );
      }

      tx.commit();
      return result;
    } catch (error) {
      if (tx.state === 'active') tx.rollback();
      throw error;
    }
  }

  get(key) {
    const entry = this.getVisibleEntry(key, this.globalVersion);
    if (!entry || entry.deleted) return undefined;
    return cloneValue(entry.value);
  }

  has(key) {
    const entry = this.getVisibleEntry(key, this.globalVersion);
    return !!entry && !entry.deleted;
  }

  snapshot() {
    const result = {};
    for (const key of this.history.keys()) {
      const entry = this.getVisibleEntry(key, this.globalVersion);
      if (entry && !entry.deleted) {
        result[key] = cloneValue(entry.value);
      }
    }
    return result;
  }
}

class Transaction {
  constructor(store) {
    this.store = store;
    this.startVersion = store.globalVersion;
    this.writes = new Map();        // key -> { value, deleted }
    this.baseVersions = new Map();  // key -> committed version seen at transaction start
    this.savepoints = [];
    this.state = 'active';          // active | committed | rolledBack
  }

  _ensureActive() {
    if (this.state !== 'active') {
      throw new Error(`Transaction is not active (state: ${this.state})`);
    }
  }

  _baseVersion(key) {
    if (!this.baseVersions.has(key)) {
      const entry = this.store.getVisibleEntry(key, this.startVersion);
      this.baseVersions.set(key, entry ? entry.version : 0);
    }
    return this.baseVersions.get(key);
  }

  get(key) {
    this._ensureActive();

    if (this.writes.has(key)) {
      const write = this.writes.get(key);
      return write.deleted ? undefined : cloneValue(write.value);
    }

    this._baseVersion(key);
    const entry = this.store.getVisibleEntry(key, this.startVersion);
    if (!entry || entry.deleted) return undefined;
    return cloneValue(entry.value);
  }

  has(key) {
    this._ensureActive();

    if (this.writes.has(key)) {
      return !this.writes.get(key).deleted;
    }

    const entry = this.store.getVisibleEntry(key, this.startVersion);
    return !!entry && !entry.deleted;
  }

  set(key, value) {
    this._ensureActive();
    this._baseVersion(key);
    this.writes.set(key, {
      value: cloneValue(value),
      deleted: false
    });
  }

  delete(key) {
    this._ensureActive();
    this._baseVersion(key);
    this.writes.set(key, {
      deleted: true
    });
  }

  savepoint(name) {
    this._ensureActive();
    const sp = {
      id: Symbol(name || 'savepoint'),
      name,
      writes: new Map(this.writes),
      baseVersions: new Map(this.baseVersions)
    };
    this.savepoints.push(sp);
    return sp;
  }

  rollbackTo(savepoint) {
    this._ensureActive();
    const index = this.savepoints.indexOf(savepoint);
    if (index === -1) {
      throw new Error('Unknown savepoint');
    }

    this.writes = new Map(savepoint.writes);
    this.baseVersions = new Map(savepoint.baseVersions);
    this.savepoints = this.savepoints.slice(0, index + 1);
  }

  release(savepoint) {
    this._ensureActive();
    const index = this.savepoints.indexOf(savepoint);
    if (index === -1) {
      throw new Error('Unknown savepoint');
    }
    this.savepoints.splice(index, 1);
  }

  commit() {
    this._ensureActive();

    // Validate every key that was read or written.
    const touched = new Set([
      ...this.baseVersions.keys(),
      ...this.writes.keys()
    ]);

    for (const key of touched) {
      this._baseVersion(key);
      const base = this.baseVersions.get(key);
      const latest = this.store.getLatestVersion(key);

      if (latest !== base) {
        this.rollback();
        throw new TransactionConflictError(
          `Conflict on key "${key}": expected version ${base}, found ${latest}`
        );
      }
    }

    // Apply writes only if there are any.
    if (this.writes.size > 0) {
      this.store.globalVersion += 1;
      const commitVersion = this.store.globalVersion;

      for (const [key, write] of this.writes) {
        const entry = write.deleted
          ? { value: undefined, version: commitVersion, deleted: true }
          : { value: cloneValue(write.value), version: commitVersion, deleted: false };

        const versions = this.store._versions(key);
        versions.push(entry);
        this.store.history.set(key, versions);
      }
    }

    this.state = 'committed';
    this.store.activeTransactions.delete(this);
  }

  rollback() {
    if (this.state !== 'active') return;

    this.writes.clear();
    this.baseVersions.clear();
    this.savepoints = [];
    this.state = 'rolledBack';
    this.store.activeTransactions.delete(this);
  }
}

// -----------------------------
// Demo / usage
// -----------------------------

const store = new TransactionalStore();

// Initial committed data
store.transaction((tx) => {
  tx.set('balance:alice', 100);
  tx.set('balance:bob', 50);
});

console.log('Initial snapshot:', store.snapshot());

// Basic transaction with rollback
const tx = store.begin();
tx.set('balance:alice', 120);
console.log('Inside tx, alice =', tx.get('balance:alice'));
console.log('Committed store, alice =', store.get('balance:alice'));
tx.rollback();
console.log('After rollback, alice =', store.get('balance:alice'));

// Savepoint example
const tx2 = store.begin();
tx2.set('counter', 1);
const sp = tx2.savepoint('before-extra');
tx2.set('counter', 2);
tx2.rollbackTo(sp);
console.log('After savepoint rollback, counter =', tx2.get('counter'));
tx2.commit();
console.log('Committed counter =', store.get('counter'));

// Optimistic conflict example
const a = store.begin();
const b = store.begin();

a.set('balance:alice', 999);

// b reads the old value, creating a read dependency.
console.log('b sees alice =', b.get('balance:alice'));

a.commit();
console.log('a committed. Store alice =', store.get('balance:alice'));

try {
  // b tries to change alice after a committed a conflicting change.
  b.set('balance:alice', 888);
  b.commit();
} catch (error) {
  console.log('b commit failed:', error.name, '-', error.message);
  console.log('Final alice =', store.get('balance:alice'));
}

// Read/write conflict example
store.transaction((tx) => tx.set('counter', 0));

const reader = store.begin();
const writer = store.begin();

console.log('reader sees counter =', reader.get('counter'));

writer.set('counter', 1);
writer.commit();
console.log('writer committed. Store counter =', store.get('counter'));

try {
  // reader read counter earlier; now it is stale.
  reader.set('counter', 2);
  reader.commit();
} catch (error) {
  console.log('reader commit failed:', error.name, '-', error.message);
  console.log('Final counter =', store.get('counter'));
}
```

## What this gives you

### Transaction lifecycle

```js
const tx = store.begin();
tx.set('key', value);
tx.get('key');
tx.delete('key');
tx.commit();
tx.rollback();
```

### Savepoints

```js
const sp = tx.savepoint('name');
tx.set('key', 2);
tx.rollbackTo(sp); // undo changes after savepoint
tx.release(sp);    // remove savepoint
```

### Automatic transaction wrapper

```js
const result = store.transaction((tx) => {
  tx.set('a', 1);
  tx.set('b', 2);
  return 'done';
});
```

The wrapper commits on success and rolls back on thrown errors. It also supports async functions:

```js
await store.transaction(async (tx) => {
  tx.set('a', await fetchValue());
});
```

### Conflict behavior

If two transactions touch the same key and both try to commit, the first commit succeeds and the second throws `TransactionConflictError`. The failed transaction is automatically rolled back.

```js
try {
  tx.commit();
} catch (e) {
  if (e instanceof TransactionConflictError) {
    // retry, refresh, or report conflict
  }
}
```

## Important limitations

This is an in-memory, process-local transaction implementation. It is useful for application state coordination, undoable operations, tests, simulations, and teaching transaction concepts. It is not durable, not distributed, and not a replacement for a database transaction manager. For production persistence, use your database's transaction API, or combine this pattern with write-ahead logging and recovery logic.

# Transactions in JavaScript

A **transaction** is a group of operations treated as a single unit of work: either **all** succeed (commit) or **none** take effect (rollback). This gives you ACID guarantees (Atomicity, Consistency, Isolation, Durability) so partial failures can't corrupt data.

In JS you encounter transactions in three main places:
1. **IndexedDB** (browser, built-in)
2. **SQL databases** via Node drivers/ORMs
3. **Application-level** saga/process managers for multi-service flows

---

## 1. The idea

Without a transaction:

```js
await debitAccount(from, 100);   // succeeds
await creditAccount(to, 100);    // fails → money disappears
```

With a transaction:

```js
await db.transaction(async (tx) => {
  await tx.debit(from, 100);    // staged
  await tx.credit(to, 100);     // staged
  // commit happens only if no throw
});
// on throw → automatic rollback
```

Key properties:
- **Atomicity** — all-or-nothing.
- **Isolation** — concurrent transactions don't see each other's intermediate state.
- **Commit/Rollback** — explicit or automatic on success/error.

---

## 2. IndexedDB (browser)

IndexedDB is transactional by design. Every read/write happens inside a transaction on one or more object stores.

```js
const req = indexedDB.open('app', 1);
req.onupgradeneeded = (e) => {
  const db = e.target.result;
  db.createObjectStore('users', { keyPath: 'id' });
};

req.onsuccess = (e) => {
  const db = e.target.result;

  // Read/write transaction on 'users'
  const tx = db.transaction('users', 'readwrite');
  const store = tx.objectStore('users');

  store.put({ id: 1, name: 'Ada' });
  store.put({ id: 2, name: 'Linus' });

  tx.oncomplete = () => console.log('committed');
  tx.onerror = () => console.log('rolled back:', tx.error);
  tx.onabort = () => console.log('aborted');
};
```

Notes:
- Mode: `'readonly'` (default) or `'readwrite'`.
- Transactions **auto-commit** when there are no pending requests and the call stack is empty. Don't interleave `await`/`setTimeout` between requests — the transaction may close.
- Version-change transactions (`onupgradeneeded`) can create stores/indexes.

---

## 3. PostgreSQL via `pg` (Node)

```js
import { Pool } from 'pg';
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

async function transfer(fromId, toId, amount) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    const { rows } = await client.query(
      'SELECT balance FROM accounts WHERE id = $1 FOR UPDATE',
      [fromId]
    );
    if (rows[0].balance < amount) throw new Error('insufficient funds');

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );
    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}
```

Patterns:
- `FOR UPDATE` locks rows to prevent races.
- Wrap in `try/catch/finally`; always `release()` the client.
- Use a helper to reduce boilerplate:

```js
async function withTransaction(pool, fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  } finally {
    client.release();
  }
}
```

---

## 4. better-sqlite3 (synchronous, Node)

Excellent for local/edge; transactions are synchronous and very fast.

```js
import Database from 'better-sqlite3';
const db = new Database('app.db');

const transfer = db.transaction((from, to, amount) => {
  const fromBal = db.prepare('SELECT balance FROM accounts WHERE id = ?').get(from).balance;
  if (fromBal < amount) throw new Error('insufficient funds');
  db.prepare('UPDATE accounts SET balance = balance - ? WHERE id = ?').run(amount, from);
  db.prepare('UPDATE accounts SET balance = balance + ? WHERE id = ?').run(amount, to);
});

transfer(1, 2, 100);        // commits
// transfer(1, 2, 999999);  // throws → rolls back
```

`db.transaction(fn)` returns a function; calling it wraps `BEGIN`/`COMMIT`/`ROLLBACK`. You can also nest (savepoints) for partial rollback.

---

## 5. Prisma ORM

```js
await prisma.$transaction(async (tx) => {
  await tx.account.update({ where: { id: from }, data: { balance: { decrement: amount } } });
  await tx.account.update({ where: { id: to },   data: { balance: { increment: amount } } });
  await tx.ledger.create({ data: { from, to, amount } });
});
```

Or batch (interactive not needed):

```js
await prisma.$transaction([
  prisma.user.create({ data: { email } }),
  prisma.profile.create({ data: { userId } }),
]);
```

Prisma also supports `isolationLevel: 'Serializable'` and timeouts.

---

## 6. Typical use cases

| Use case | Why transaction |
|---|---|
| Money transfer | debit + credit atomic |
| Order placement | order + line items + inventory decrement |
| Signup | user + profile + welcome email record |
| Idempotent retries | insert-or-skip with unique constraint |
| Multi-table consistency | FKs across tables |
| Distributed saga | compensate on later failure |

**Application-level saga** (when you can't share one DB transaction across services):

```js
async function placeOrder(input) {
  const order = await orderService.create(input);          // step 1
  try {
    await paymentService.charge(order);                  // step 2
    await inventoryService.reserve(order.items);          // step 3
  } catch (e) {
    await paymentService.refund(order);                  // compensate
    await orderService.cancel(order);
    throw e;
  }
}
```

This is *not* ACID — it's eventual consistency with compensating actions.

---

## 7. Pitfalls & best practices

- **Don't hold transactions open during slow I/O** (HTTP calls, user input). Locks stall others.
- **Set timeouts** to avoid deadlocks: `SET statement_timeout` / Prisma `timeout`.
- **Keep transactions short** and deterministic; retry on serialization failures (Postgres `40001`).
- **Isolation levels**: `Read Committed` (default) vs `Repeatable Read`/`Serializable`. Higher = safer but more contention.
- **IndexedDB auto-commit**: issue all requests synchronously within the same tick; don't `await` between store operations.
- **Idempotency**: make operations safe to replay; use unique keys so retries don't double-apply.
- **Errors must trigger rollback** — never `COMMIT` after a partial failure.

---

### Minimal reusable helper (Node/Postgres)

```js
import { Pool } from 'pg';
const pool = new Pool();

export async function transaction(fn) {
  const c = await pool.connect();
  try {
    await c.query('BEGIN');
    const r = await fn(c);
    await c.query('COMMIT');
    return r;
  } catch (e) {
    await c.query('ROLLBACK');
    throw e;
  } finally {
    c.release();
  }
}

// usage
await transaction(async (tx) => {
  await tx.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2', [100, 1]);
  await tx.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2', [100, 2]);
});
```

That's the core: group writes, commit on success, rollback on any error, and keep the critical section as short as possible.

A very common transaction mistake in Node.js/PostgreSQL code is issuing `BEGIN`, `UPDATE`, and `COMMIT` through `pool.query()`:

```js
// MISTAKE: each pool.query() may use a different connection
async function transfer(pool, fromId, toId, amount) {
  await pool.query('BEGIN');
  await pool.query(
    'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
    [amount, fromId]
  );
  await pool.query(
    'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
    [amount, toId]
  );
  await pool.query('COMMIT');
}
```

### Why this is wrong

`pool.query()` checks out a connection, runs the query, and releases that connection back to the pool. So:

- `BEGIN` might run on connection A
- first `UPDATE` might run on connection B
- second `UPDATE` might run on connection C
- `COMMIT` might run on connection D

The transaction commands are split across different database sessions, so there is no real atomic transaction. You can get partial updates, race conditions, and lost updates. Also, if one of the `UPDATE`s fails, nothing rolls back, and the error is not handled.

### Corrected version

Acquire one client, use it for every statement in the transaction, roll back on error, and always release the client:

```js
async function transfer(pool, fromId, toId, amount) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}
```

### What changed and why

1. **One dedicated connection**  
   `pool.connect()` checks out a single client and holds it for the whole transaction. All statements execute on the same database session, so `BEGIN`, the updates, and `COMMIT`/`ROLLBACK` belong to the same transaction.

2. **Rollback on failure**  
   If either update throws, the `catch` block runs `ROLLBACK`, undoing any partial changes. This preserves atomicity: either both updates succeed or neither does.

3. **Guaranteed release**  
   `finally { client.release(); }` returns the connection to the pool even if an error occurs. Without this, failed transactions can leak connections and exhaust the pool.

4. **Error propagation**  
   The original error is rethrown after rollback, so callers can still react to the failure.

### Additional practical notes

- Add a balance check or constraint inside the transaction if needed, for example `WHERE id = $2 AND balance >= $1` and verify `rowCount`.
- For stronger consistency, consider setting an isolation level before `BEGIN`, e.g. `BEGIN ISOLATION LEVEL SERIALIZABLE`, when business rules require it.
- Keep transactions short; long transactions hold locks and can reduce concurrency.
- If using an ORM such as Prisma, Mongoose, or Sequelize, use its documented transaction API rather than raw `BEGIN`/`COMMIT`, but the same principles apply: one session, commit or rollback, cleanup on error.

Common transaction pitfalls in JavaScript usually come from the combination of **async I/O**, **shared connections/sessions**, and **implicit runtime behavior**. Below are the most common ones, with bad and good code.

## 1. Forgetting `await` on commit/rollback

A floating promise can make the function return before the transaction is actually committed, or swallow errors.

```js
// BAD
await client.query("BEGIN");
await client.query("UPDATE accounts SET balance = balance - 100 WHERE id = $1", [from]);
await client.query("UPDATE accounts SET balance = balance + 100 WHERE id = $1", [to]);
client.query("COMMIT"); // floating promise
```

```js
// GOOD
await client.query("BEGIN");
try {
  await client.query("UPDATE accounts SET balance = balance - 100 WHERE id = $1", [from]);
  await client.query("UPDATE accounts SET balance = balance + 100 WHERE id = $1", [to]);
  await client.query("COMMIT");
} catch (err) {
  await client.query("ROLLBACK");
  throw err;
}
```

## 2. Not using `try / catch / finally`, leaking connections

If an error happens after `BEGIN`, the transaction and connection can remain open. Always release the client.

```js
// BAD
const client = await pool.connect();
await client.query("BEGIN");
await client.query("UPDATE ..."); // throws
await client.query("COMMIT");
client.release(); // never reached
```

```js
// GOOD
const client = await pool.connect();
try {
  await client.query("BEGIN");
  await client.query("UPDATE ...");
  await client.query("COMMIT");
} catch (err) {
  await client.query("ROLLBACK").catch(() => {});
  throw err;
} finally {
  client.release();
}
```

Better: use a transaction helper.

```js
async function withTransaction(pool, fn) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const result = await fn(client);
    await client.query("COMMIT");
    return result;
  } catch (err) {
    await client.query("ROLLBACK").catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}
```

## 3. Running some queries outside the transaction

Reading with the pool and writing with the transaction connection breaks atomicity. The read is not protected by the same transaction/isolation.

```js
// BAD
const { rows } = await pool.query("SELECT balance FROM accounts WHERE id = $1", [id]);
const newBalance = rows[0].balance - 100;
await tx.query("UPDATE accounts SET balance = $1 WHERE id = $2", [newBalance, id]);
```

```js
// GOOD
await withTransaction(pool, async (tx) => {
  const { rows } = await tx.query(
    "SELECT balance FROM accounts WHERE id = $1 FOR UPDATE",
    [id]
  );
  const newBalance = rows[0].balance - 100;
  await tx.query(
    "UPDATE accounts SET balance = $1 WHERE id = $2",
    [newBalance, id]
  );
});
```

## 4. Read-modify-write races

Even inside a transaction, default isolation may allow concurrent updates. Lock the row or use an atomic update.

```js
// BAD
const { rows } = await tx.query("SELECT balance FROM accounts WHERE id = $1", [id]);
await tx.query("UPDATE accounts SET balance = $1 WHERE id = $2", [rows[0].balance - amount, id]);
```

```js
// GOOD: atomic update
await tx.query(
  `UPDATE accounts
   SET balance = balance - $1
   WHERE id = $2 AND balance >= $1`,
  [amount, id]
);
```

Or use locking:

```js
const { rows } = await tx.query(
  "SELECT balance FROM accounts WHERE id = $1 FOR UPDATE",
  [id]
);
```

## 5. Concurrent queries on one transaction connection

In JavaScript, `Promise.all` looks convenient but can interleave statements on the same connection, obscure ordering, or hit driver limitations.

```js
// BAD / risky
await Promise.all(items.map(item =>
  tx.query("INSERT INTO orders(item_id) VALUES ($1)", [item.id])
));
```

```js
// GOOD
for (const item of items) {
  await tx.query("INSERT INTO orders(item_id) VALUES ($1)", [item.id]);
}
```

Even better: batch insert.

```js
await tx.query(
  "INSERT INTO orders(item_id) VALUES " +
    items.map((_, i) => `($${i + 1})`).join(","),
  items.map(i => i.id)
);
```

## 6. Long-running transactions

Holding a transaction open while calling external APIs, sleeping, or processing large data locks rows and can cause timeouts.

```js
// BAD
await tx.begin();
const user = await tx.query("SELECT * FROM users WHERE id = $1", [id]);
const profile = await fetchExternalProfile(user.id); // slow
await tx.query("UPDATE users SET profile = $1", [profile]);
await tx.commit();
```

```js
// GOOD: do external work first, then short transaction
const user = await getUser(id);
const profile = await fetchExternalProfile(user.id);
await withTransaction(pool, async (tx) => {
  await tx.query("UPDATE users SET profile = $1 WHERE id = $2", [profile, id]);
});
```

## 7. Deadlocks from inconsistent lock order

Two transactions updating the same rows in different orders can deadlock.

```js
// Transaction A
await tx.query("UPDATE accounts SET balance = balance - 10 WHERE id = 1");
await tx.query("UPDATE accounts SET balance = balance + 10 WHERE id = 2");

// Transaction B
await tx.query("UPDATE accounts SET balance = balance - 5 WHERE id = 2");
await tx.query("UPDATE accounts SET balance = balance + 5 WHERE id = 1");
```

```js
// GOOD: sort IDs before updating
const ids = [fromId, toId].sort((a, b) => a - b);
for (const id of ids) {
  await tx.query("SELECT id FROM accounts WHERE id = $1 FOR UPDATE", [id]);
}
```

Also retry deadlocks:

```js
async function runWithDeadlockRetry(fn, attempts = 3) {
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      const isDeadlock =
        err.code === "40P01" || // Postgres
        err.code === "ER_LOCK_DEADLOCK"; // MySQL
      if (isDeadlock && i < attempts - 1) {
        await new Promise(r => setTimeout(r, 25 * (i + 1)));
        continue;
      }
      throw err;
    }
  }
}
```

## 8. Assuming serializable isolation by default

Most databases default to `READ COMMITTED`. Code that assumes no concurrent changes can produce lost updates or write skew.

```js
// BAD assumption: no one else changes inventory between read and write
const { rows } = await tx.query("SELECT stock FROM products WHERE id = $1", [id]);
if (rows[0].stock >= qty) {
  await tx.query("UPDATE products SET stock = stock - $1 WHERE id = $2", [qty, id]);
}
```

```js
// GOOD: set isolation or use atomic conditional update
await tx.query("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE");
// Or safer:
const result = await tx.query(
  "UPDATE products SET stock = stock - $1 WHERE id = $2 AND stock >= $1",
  [qty, id]
);
if (result.rowCount === 0) throw new Error("insufficient stock");
```

## 9. MongoDB: forgetting to pass the session

MongoDB transactions require every operation to use the same session.

```js
// BAD
const session = client.startSession();
session.startTransaction();
await users.insertOne({ name: "Alice" }); // no session
await orders.insertOne({ user: "Alice" });   // no session
await session.commitTransaction();
```

```js
// GOOD
const session = client.startSession();
try {
  session.startTransaction();
  await users.insertOne({ name: "Alice" }, { session });
  await orders.insertOne({ user: "Alice" }, { session });
  await session.commitTransaction();
} catch (err) {
  await session.abortTransaction();
  throw err;
} finally {
  await session.endSession();
}
```

## 10. ORM transactions not propagated to helper functions

A helper using the global ORM client bypasses the transaction.

```js
// BAD (Prisma-style)
await prisma.$transaction(async (tx) => {
  await tx.user.create({ data: { email } });
  await createUserProfile(email); // uses global prisma, not tx
});
```

```js
// GOOD
await prisma.$transaction(async (tx) => {
  await tx.user.create({ data: { email } });
  await createUserProfile(tx, email); // pass tx explicitly
});
```

```js
async function createUserProfile(tx, email) {
  await tx.profile.create({ data: { email } });
}
```

## 11. Nested `BEGIN` instead of savepoints

Calling `BEGIN` inside an existing transaction can fail or create confusing state. Use savepoints.

```js
// BAD
await tx.query("BEGIN"); // already in transaction
```

```js
// GOOD
await tx.query("SAVEPOINT sp1");
try {
  await tx.query("INSERT ...");
  await tx.query("RELEASE SAVEPOINT sp1");
} catch (err) {
  await tx.query("ROLLBACK TO SAVEPOINT sp1");
  throw err;
}
```

## 12. Blind retries of non-idempotent operations

Retrying an entire transaction is only safe if the operations are idempotent or the retry re-runs from the beginning without side effects outside the database.

```js
// BAD: charging payment and then retrying may double-charge
await withTransaction(pool, async (tx) => {
  await chargePayment(orderId); // external side effect
  await tx.query("UPDATE orders SET paid = true");
});
```

```js
// GOOD: make external side effect idempotent or do it after commit
await withTransaction(pool, async (tx) => {
  await tx.query("UPDATE orders SET status = 'processing' WHERE id = $1", [orderId]);
});
const charge = await chargePaymentIdempotently(orderId);
await withTransaction(pool, async (tx) => {
  await tx.query("UPDATE orders SET paid = true WHERE id = $1", [orderId]);
});
```

## 13. Query timeouts and hung transactions

Without timeouts, a slow query can hold locks indefinitely.

```js
// GOOD (Postgres example)
await tx.query("SET statement_timeout = '5s'");
await tx.query("SET lock_timeout = '2s'");
```

In MySQL/Sequelize/Prisma, set query timeouts in the client config as well.

## 14. Shared transaction object across requests

Do not store a transaction client on a global/module-level object. Each request should own its connection/session.

```js
// BAD
let globalTx;
app.post("/transfer", async (req, res) => {
  globalTx = await pool.connect();
  await globalTx.query("BEGIN");
});
```

```js
// GOOD: transaction lives only inside the request handler
app.post("/transfer", async (req, res) => {
  await withTransaction(pool, async (tx) => {
    await transfer(tx, req.body);
  });
  res.sendStatus(204);
});
```

## 15. Not validating commit success in clustered/managed databases

In some systems, commit can fail after the client thinks it succeeded (for example, failover). For critical financial operations, verify state or use idempotency keys rather than assuming commit success.

```js
// GOOD pattern: idempotency key
await withTransaction(pool, async (tx) => {
  await tx.query(
    "INSERT INTO transfers(idempotency_key, ...) VALUES ($1, ...) ON CONFLICT DO NOTHING",
    [key]
  );
});
```

## Summary checklist

- Always `await` commit/rollback.
- Use `try/catch/finally` or a transaction helper.
- Read and write through the same transaction connection.
- Avoid `Promise.all` on one connection unless the driver explicitly supports it.
- Keep transactions short; no external API calls inside.
- Lock rows or use atomic conditional updates.
- Use savepoints, not nested `BEGIN`.
- Pass sessions/clients through all layers.
- Retry deadlocks only from the start of the transaction.
- Set statement and lock timeouts.
- Make critical operations idempotent.

## Exercise

Build a small **transactional bank transfer** in JavaScript.

### Requirements
- Store account balances.
- Implement `begin()`, `commit()`, and `rollback()`.
- Transfer money from one account to another.
- If validation fails, such as insufficient funds or an unknown account, **no balance should change**.
- After a successful transfer, both balances should update together.

---

## Step-by-step solution

### Step 1: Model the committed state
Keep one immutable-ish committed store and a separate working copy.

```js
this.committed = new Map(...); // visible state
this.working   = null;        // active transaction copy
```

### Step 2: Begin a transaction
Copy committed state into a working map. All reads and writes during the transaction use the working copy.

### Step 3: Read and write through the transaction
- `tx.get(id)` reads from the working copy.
- `tx.set(id, value)` writes to the working copy.
- Nothing touches committed state yet.

### Step 4: Commit or rollback
- `commit()` replaces committed state with the working copy.
- `rollback()` discards the working copy.
- Always use `try/catch` so failures roll back automatically.

### Step 5: Validate before mutating
Check account existence and sufficient funds before writing anything.

---

## Final solution

```js
class Bank {
  constructor(accounts = {}) {
    this.committed = new Map(
      Object.entries(accounts).map(([id, balance]) => [id, Number(balance)])
    );
    this.working = null;
  }

  begin() {
    if (this.working) {
      throw new Error('A transaction is already active');
    }

    this.working = new Map(this.committed);

    const tx = {
      get(id) {
        if (!this.working) throw new Error('No active transaction');
        return this.working.get(id);
      },

      set(id, value) {
        if (!this.working) throw new Error('No active transaction');
        if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
          throw new Error('Balance must be a finite non-negative number');
        }
        this.working.set(id, value);
      },

      commit() {
        if (!this.working) throw new Error('No active transaction');
        this.committed = this.working;
        this.working = null;
      },

      rollback() {
        this.working = null;
      }
    };

    // Bind methods to the Bank instance so `this` is correct.
    tx.get = tx.get.bind(this);
    tx.set = tx.set.bind(this);
    tx.commit = tx.commit.bind(this);
    tx.rollback = tx.rollback.bind(this);

    return tx;
  }

  balance(id) {
    return this.committed.get(id);
  }

  accounts() {
    return Object.fromEntries(this.committed);
  }
}

function transfer(bank, fromId, toId, amount) {
  if (typeof amount !== 'number' || !Number.isFinite(amount) || amount <= 0) {
    throw new TypeError('Amount must be a positive finite number');
  }

  const tx = bank.begin();

  try {
    const fromBalance = tx.get(fromId);
    const toBalance = tx.get(toId);

    if (fromBalance === undefined) {
      throw new Error(`Unknown account: ${fromId}`);
    }
    if (toBalance === undefined) {
      throw new Error(`Unknown account: ${toId}`);
    }
    if (fromBalance < amount) {
      throw new Error('Insufficient funds');
    }

    tx.set(fromId, fromBalance - amount);
    tx.set(toId, toBalance + amount);

    tx.commit();
  } catch (error) {
    tx.rollback();
    throw error;
  }
}

// Demo
const bank = new Bank({ alice: 100, bob: 50 });

transfer(bank, 'alice', 'bob', 30);
console.log('After successful transfer:', bank.accounts());
// { alice: 70, bob: 80 }

try {
  transfer(bank, 'alice', 'bob', 1000);
} catch (error) {
  console.log('Failed transfer:', error.message);
}

console.log('After failed transfer:', bank.accounts());
// { alice: 70, bob: 80 }  // unchanged
```

### Example output

```text
After successful transfer: { alice: 70, bob: 80 }
Failed transfer: Insufficient funds
After failed transfer: { alice: 70, bob: 80 }
```

---

## Why this works

- **Atomicity:** balances are only published when `commit()` runs.
- **Rollback safety:** any thrown error calls `rollback()`, discarding the working copy.
- **Validation first:** unknown accounts and insufficient funds fail before any state is written.
- **Single-threaded safety:** JavaScript’s synchronous execution means no other code can interleave between `begin()` and `commit()`/`rollback()`.

---

## Practical extension: async database transactions

For real databases, the same pattern is usually wrapped around a connection/client:

```js
async function withTransaction(pool, work) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');
    const result = await work(client);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  } finally {
    client.release();
  }
}
```

Usage:

```js
await withTransaction(pool, async (client) => {
  await client.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2', [30, 'alice']);
  await client.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2', [30, 'bob']);
});
```

The key idea is identical to the in-memory version: **begin, do work, commit on success, rollback on failure**.

## Transactions in JavaScript

A **transaction** is a sequence of operations treated as a single unit of work: either **all** succeed (commit) or **none** take effect (rollback). In JavaScript this shows up in several places:

- **Databases** (IndexedDB, SQL via drivers) – `begin` / `commit` / `rollback`.
- **State management** – batched updates, undo/redo, optimistic updates.
- **In-memory stores** – staging changes so reads inside the transaction see uncommitted writes, while outside observers don’t until commit.

Core properties (ACID-ish in practice):
- **Atomicity** – partial failure rolls everything back.
- **Consistency** – invariants preserved.
- **Isolation** – intermediate state invisible outside the transaction.
- **Durability** – committed state survives (for persistent stores).

Below is a small, self-contained **transactional key-value store** that demonstrates the core mechanics: staging, read-your-writes, nested transactions, commit, and rollback.

```js
/**
 * A minimal transactional key-value store.
 *
 * Semantics:
 *  - Reads inside a transaction see staged (uncommitted) writes.
 *  - Writes are staged per transaction frame; commit applies them atomically.
 *  - Rollback discards the staged changes.
 *  - Transactions may be nested; commit merges into the parent frame.
 */
class TransactionalStore {
  constructor() {
    /** Committed state. */
    this.committed = new Map();
    /** Stack of transaction frames. Each frame is a Map<key, {value, deleted}>. */
    this.frames = [];
  }

  /** True if a transaction is currently active. */
  inTransaction() {
    return this.frames.length > 0;
  }

  /** Begin a new (possibly nested) transaction. */
  begin() {
    this.frames.push(new Map());
  }

  /**
   * Stage a write. If no transaction is active, auto-commit (convenience).
   * Within a transaction, the write is only visible after commit.
   */
  set(key, value) {
    const frame = this._topFrame();
    if (!frame) {
      // No active transaction: write directly to committed state.
      this.committed.set(key, value);
      return;
    }
    // Stage as an upsert. Using a sentinel for deletion keeps rollback simple.
    frame.set(key, { type: "set", value });
  }

  /** Stage a deletion. */
  delete(key) {
    const frame = this._topFrame();
    if (!frame) {
      this.committed.delete(key);
      return;
    }
    frame.set(key, { type: "delete" });
  }

  /**
   * Read with read-your-writes semantics:
   * search from the innermost frame outward, then committed state.
   */
  get(key) {
    for (let i = this.frames.length - 1; i >= 0; i--) {
      const entry = this.frames[i].get(key);
      if (entry) {
        if (entry.type === "delete") return undefined;
        return entry.value;
      }
    }
    return this.committed.get(key);
  }

  /** Check existence considering staged deletes. */
  has(key) {
    return this.get(key) !== undefined || this.committed.has(key) && this._notDeleted(key);
  }

  /** Commit the current transaction: merge its staged ops into the parent/committed state. */
  commit() {
    if (this.frames.length === 0) {
      throw new Error("commit() called with no active transaction");
    }
    const frame = this.frames.pop();
    const target = this.frames.length > 0 ? this.frames[this.frames.length - 1] : this.committed;

    // Apply staged operations to the target (parent frame or committed store).
    for (const [key, op] of frame) {
      if (target instanceof Map && !(target instanceof Map && target.has && target.get && target.set && target.delete)) {
        // target is a committed Map (plain Map) -> apply directly
      }
      if (op.type === "set") {
        if (target === this.committed) {
          this.committed.set(key, op.value);
        } else {
          target.set(key, { type: "set", value: op.value });
        }
      } else if (op.type === "delete") {
        if (target === this.committed) {
          this.committed.delete(key);
        } else {
          target.set(key, { type: "delete" });
        }
      }
    }
  }

  /** Discard the current transaction's staged changes. */
  rollback() {
    if (this.frames.length === 0) {
      throw new Error("rollback() called with no active transaction");
    }
    this.frames.pop();
  }

  // ---------- helpers ----------

  _topFrame() {
    return this.frames.length > 0 ? this.frames[this.frames.length - 1] : null;
  }

  _notDeleted(key) {
    // Best-effort existence check; get() already accounts for deletes.
    return this.get(key) !== undefined;
  }
}

// ---------- Demo ----------
const store = new TransactionalStore();

store.set("a", 1);          // auto-commit
console.log(store.get("a")); // 1

store.begin();
store.set("a", 2);          // staged
store.set("b", 3);          // staged
console.log(store.get("a")); // 2 (read-your-writes)
console.log(store.committed.get("a")); // 1 (still committed value)

store.rollback();
console.log(store.get("a")); // 1
console.log(store.get("b")); // undefined

// Nested transactions
store.begin();
store.set("x", 10);
store.begin();
store.set("x", 20);
store.commit();              // merge into parent
console.log(store.get("x")); // 20 (parent sees it)
store.rollback();            // discard parent
console.log(store.get("x")); // undefined
```

### Key ideas illustrated

1. **Frames as deltas** – each transaction pushes a `Map` of staged operations rather than mutating committed state.
2. **Read-your-writes** – `get()` walks frames from innermost to outermost.
3. **Atomic commit** – all staged ops move to the parent/committed store together.
4. **Rollback** – simply drop the top frame.
5. **Nesting** – commit merges into the parent frame; rollback of parent discards everything.

### Extensions you’d add in production

- **Conflict detection** – track read/write sets and abort on concurrent conflicts (optimistic concurrency).
- **Savepoints** – partial rollback within a transaction.
- **Async commit** – `await store.commit()` with persistence + fsync.
- **Isolation levels** – read committed vs. repeatable read vs. serializable.
- **Locking** – pessimistic locks for write skew prevention.

This pattern (stage → commit/rollback) is the backbone of most transactional systems, from IndexedDB to Redux sagas to database engines.

Below are common transaction edge cases in JavaScript/Node.js, with practical code examples. Most examples use PostgreSQL via `pg`, but the patterns apply broadly.

---

## 1. Forgetting to release the client (pool exhaustion)

If you `pool.connect()` and do not release on every path, the pool drains and the app hangs.

```js
import { Pool } from "pg";

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

async function transfer(fromId, toId, amount) {
  const client = await pool.connect();

  try {
    await client.query("BEGIN");
    await client.query(
      "UPDATE accounts SET balance = balance - $1 WHERE id = $2",
      [amount, fromId]
    );
    await client.query(
      "UPDATE accounts SET balance = balance + $1 WHERE id = $2",
      [amount, toId]
    );
    await client.query("COMMIT");
  } catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch {
      // Connection may already be broken; ignore rollback failure.
    }
    throw err;
  } finally {
    client.release(); // Always release, even on success/failure.
  }
}
```

Better: wrap this in a reusable helper.

```js
async function withTransaction(pool, fn) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const result = await fn(client);
    await client.query("COMMIT");
    return result;
  } catch (err) {
    try { await client.query("ROLLBACK"); } catch {}
    throw err;
  } finally {
    client.release();
  }
}
```

---

## 2. Unhandled async errors leaving an open transaction

A thrown error after `BEGIN` but before `COMMIT` must trigger `ROLLBACK`. Always use `try/catch/finally`.

Bad:

```js
await client.query("BEGIN");
await client.query("INSERT INTO orders ..."); // may throw
await client.query("COMMIT"); // skipped on throw; transaction remains open
```

Good: use the `withTransaction` helper above.

---

## 3. Holding a transaction open across external I/O

Long transactions hold locks and can cause contention, timeouts, or deadlocks. Fetch external data first, then transact.

Bad:

```js
await client.query("BEGIN");
const apiData = await fetch("https://api.example.com/data"); // external wait
await client.query("INSERT INTO events(payload) VALUES ($1)", [apiData]);
await client.query("COMMIT");
```

Good:

```js
const apiData = await fetch("https://api.example.com/data").then(r => r.json());

await withTransaction(pool, async (client) => {
  await client.query("INSERT INTO events(payload) VALUES ($1)", [apiData]);
});
```

---

## 4. Serialization failures and deadlocks need retry logic

Under `SERIALIZABLE` or concurrent updates, Postgres can return:

- `40001` serialization failure
- `40P01` deadlock detected

Retries must be idempotent and bounded.

```js
function isRetryableDbError(err) {
  return err?.code === "40001" || err?.code === "40P01";
}

async function retryTransaction(pool, fn, maxAttempts = 3) {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await withTransaction(pool, fn);
    } catch (err) {
      if (isRetryableDbError(err) && attempt < maxAttempts) {
        await new Promise((r) => setTimeout(r, 25 * attempt));
        continue;
      }
      throw err;
    }
  }
}

// Usage
await retryTransaction(pool, async (client) => {
  await client.query("UPDATE inventory SET qty = qty - 1 WHERE sku = $1", ["A1"]);
});
```

Important: only retry if the operation is idempotent or guarded by constraints/versions.

---

## 5. Lost updates / race conditions

Two transactions read the same row, then both write based on stale data. Use optimistic locking with a version column.

```sql
ALTER TABLE accounts ADD COLUMN version integer NOT NULL DEFAULT 1;
```

```js
async function withdraw(client, accountId, amount, expectedVersion) {
  const res = await client.query(
    `UPDATE accounts
     SET balance = balance - $1, version = version + 1
     WHERE id = $2 AND version = $3
     RETURNING balance, version`,
    [amount, accountId, expectedVersion]
  );

  if (res.rowCount === 0) {
    throw new Error("Concurrent modification detected");
  }

  return res.rows[0];
}

await withTransaction(pool, async (client) => {
  const { rows } = await client.query(
    "SELECT balance, version FROM accounts WHERE id = $1",
    [1]
  );
  const account = rows[0];

  if (account.balance < 100) throw new Error("Insufficient funds");

  await withdraw(client, 1, 100, account.version);
});
```

Alternative: use `SELECT ... FOR UPDATE` for pessimistic locking.

---

## 6. Nested transactions are not real transactions

PostgreSQL does not support nested `BEGIN`. Use savepoints.

```js
async function withSavepoint(client, name, fn) {
  await client.query(`SAVEPOINT ${name}`);
  try {
    const result = await fn();
    await client.query(`RELEASE SAVEPOINT ${name}`);
    return result;
  } catch (err) {
    await client.query(`ROLLBACK TO SAVEPOINT ${name}`);
    throw err;
  }
}

await withTransaction(pool, async (client) => {
  await client.query("INSERT INTO audit_log(action) VALUES ('start')");

  try {
    await withSavepoint(client, "sp_item", async () => {
      await client.query("INSERT INTO items(name) VALUES ($1)", ["x"]);
      throw new Error("item insert failed");
    });
  } catch {
    // Item insert rolled back, outer transaction continues.
  }

  await client.query("INSERT INTO audit_log(action) VALUES ('done')");
});
```

Note: after an error inside a savepoint, PostgreSQL transaction state may require rollback to savepoint before continuing. The helper does that.

---

## 7. Transaction state after an error

In PostgreSQL, once an error occurs, the transaction is aborted. You cannot run more queries until `ROLLBACK` or `ROLLBACK TO SAVEPOINT`.

Bad:

```js
await client.query("BEGIN");
try {
  await client.query("INSERT INTO users(email) VALUES ($1)", ["bad"]);
} catch {
  // Transaction is now aborted.
  await client.query("INSERT INTO logs(msg) VALUES ('failed')"); // ERROR
}
await client.query("ROLLBACK");
```

Good: use savepoints for partial recovery, or rollback the whole transaction.

---

## 8. Side effects must not happen inside transactions

Do not send emails, call third-party APIs, or mutate external state inside a DB transaction. If the transaction rolls back, side effects remain.

Bad:

```js
await withTransaction(pool, async (client) => {
  await client.query("INSERT INTO orders(user_id) VALUES ($1)", [userId]);
  await sendConfirmationEmail(userId); // cannot be rolled back
});
```

Good: use the transactional outbox pattern.

```js
await withTransaction(pool, async (client) => {
  await client.query("INSERT INTO orders(user_id) VALUES ($1)", [userId]);
  await client.query(
    "INSERT INTO outbox(event_type, payload) VALUES ($1, $2)",
    ["order.created", JSON.stringify({ userId })]
  );
});

// Separate worker reads outbox and sends email, then marks sent.
```

---

## 9. Distributed transactions and partial commits

A JavaScript app often touches multiple systems: DB, cache, queue. There is no easy atomic commit across them. Prefer:

- Outbox pattern
- Idempotent consumers
- Saga pattern with compensating actions

Example compensating action:

```js
async function createOrderSaga(input) {
  const order = await createOrderInDb(input); // DB transaction
  try {
    await reserveInventory(order.id); // external service
  } catch (err) {
    await cancelOrderInDb(order.id); // compensate
    throw err;
  }
}
```

---

## 10. ORM hidden transaction behavior

Interactive transactions in ORMs may have timeouts and isolation settings. Always know whether the library commits automatically.

Prisma example:

```js
await prisma.$transaction(
  async (tx) => {
    await tx.user.create({ data: { email: "a@example.com" } });
    await tx.post.create({ data: { title: "Hello", authorId: 1 } });
  },
  {
    isolationLevel: "Serializable",
    timeout: 5000,
    maxWait: 2000,
  }
);
```

Edge cases:

- Do not `await` slow external calls inside the callback.
- If the callback throws, Prisma rolls back.
- Retry serialization errors at the application level.

---

## 11. IndexedDB transactions auto-commit and become inactive

In browser IndexedDB, transactions auto-commit when all requests finish. If you `await` an external or long-running promise between requests, the transaction may commit or become inactive.

Bad:

```js
const tx = db.transaction("users", "readwrite");
const store = tx.objectStore("users");
store.put({ id: 1, name: "Ada" });

await someAsyncValidation(); // transaction may auto-commit here

store.put({ id: 2, name: "Bob" }); // may throw TransactionInactiveError
```

Good: keep all IndexedDB operations synchronous within the transaction, or chain requests.

```js
const tx = db.transaction("users", "readwrite");
const store = tx.objectStore("users");

store.put({ id: 1, name: "Ada" });
store.put({ id: 2, name: "Bob" });

tx.oncomplete = () => console.log("committed");
tx.onerror = () => console.error("rolled back", tx.error);
```

Also handle `versionchange` events, which can close connections and abort transactions.

---

## 12. Read-only transactions and consistency

Use read-only transactions when you need a consistent snapshot across multiple reads.

```js
await withTransaction(pool, async (client) => {
  await client.query("SET TRANSACTION READ ONLY");
  const users = await client.query("SELECT count(*) FROM users");
  const orders = await client.query("SELECT count(*) FROM orders");
  return { users: users.rows[0], orders: orders.rows[0] };
});
```

This avoids accidental writes and can improve performance in some engines.

---

## 13. Timeouts and cancellation

Long transactions can hold locks. Set statement and transaction timeouts.

PostgreSQL:

```js
await client.query("SET statement_timeout = '2s'");
await client.query("SET lock_timeout = '1s'");
```

Application-level AbortController example:

```js
const controller = new AbortController();
const timeout = setTimeout(() => controller.abort(), 3000);

try {
  await withTransaction(pool, async (client) => {
    // Pass signal to any fetch/DB calls if supported.
  });
} finally {
  clearTimeout(timeout);
}
```

If a transaction is aborted by timeout, retry only if safe and idempotent.

---

## 14. Isolation level selection

Default isolation may allow anomalies. Choose deliberately.

```js
await client.query("BEGIN");
await client.query("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE");
// queries...
await client.query("COMMIT");
```

Trade-offs:

- `READ COMMITTED`: fewer conflicts, possible non-repeatable reads.
- `REPEATABLE READ`: stable snapshot, possible serialization failures.
- `SERIALIZABLE`: strongest consistency, more retries needed.

---

## 15. Phantom reads and range locks

When validating uniqueness or ranges, a plain `SELECT` does not prevent another transaction from inserting a conflicting row.

Use constraints and locking reads:

```js
await withTransaction(pool, async (client) => {
  // Lock existing rows in range.
  await client.query(
    "SELECT * FROM bookings WHERE room_id = $1 AND date = $2 FOR UPDATE",
    [roomId, date]
  );

  const { rows } = await client.query(
    "SELECT count(*)::int AS n FROM bookings WHERE room_id = $1 AND date = $2",
    [roomId, date]
  );

  if (rows[0].n > 0) throw new Error("Already booked");

  await client.query(
    "INSERT INTO bookings(room_id, date) VALUES ($1, $2)",
    [roomId, date]
  );
});
```

Even better, add a unique constraint:

```sql
ALTER TABLE bookings ADD CONSTRAINT unique_room_date UNIQUE (room_id, date);
```

Then handle constraint violation as a normal business error.

---

## 16. Idempotency keys for retried transactions

If a client retries due to network timeout, the server may receive the same request twice. Use an idempotency key stored in the same transaction.

```js
await withTransaction(pool, async (client) => {
  const existing = await client.query(
    "SELECT result FROM idempotency_keys WHERE key = $1",
    [idempotencyKey]
  );

  if (existing.rows.length > 0) {
    return existing.rows[0].result;
  }

  const order = await createOrder(client, input);

  await client.query(
    "INSERT INTO idempotency_keys(key, result) VALUES ($1, $2)",
    [idempotencyKey, JSON.stringify(order)]
  );

  return order;
});
```

This makes retries safe even if the first transaction actually committed but the response was lost.

---

## 17. Testing transaction edge cases

Tests should cover:

- Concurrent updates causing serialization errors.
- Rollback on partial failure.
- Deadlock retry.
- Idempotency replay.
- Timeout behavior.

Example concurrency test shape:

```js
test("concurrent withdrawals do not overspend", async () => {
  const results = await Promise.allSettled([
    withdraw(pool, 1, 60),
    withdraw(pool, 1, 60),
  ]);

  const successes = results.filter((r) => r.status === "fulfilled").length;
  expect(successes).toBe(1);
});
```

---

## Summary checklist

- Always use `try/catch/finally` and release clients.
- Never hold transactions open during external I/O.
- Retry only retryable errors (`40001`, `40P01`) with idempotent operations.
- Use version columns or `FOR UPDATE` to prevent lost updates.
- Use savepoints, not nested `BEGIN`.
- Roll back or savepoint after errors before continuing.
- Keep side effects outside transactions; use outbox.
- Avoid awaiting external promises inside IndexedDB transactions.
- Select isolation levels intentionally.
- Add DB constraints for invariants, not just application checks.
- Use idempotency keys for client retries.
- Set timeouts and test concurrency.

## Two‑Pointer Technique in JavaScript

The two‑pointer technique avoids nested loops by moving two indices through a data structure (usually a sorted array or string) in a coordinated way.  
There are two common patterns:

| Pattern | Moves | Typical use |
|---|---|---|
| **Converging (opposite ends)** | `left++`, `right--` | Pair sums, palindrome, container with most water |
| **Same direction (fast/slow)** | both `++`, but at different speeds | Remove duplicates, partition, cycle detection |

Below is a complete, runnable Node.js script that demonstrates all four ideas with assertions.

```js
// two-pointer.js
// Run with: node two-pointer.js

"use strict";

/* ------------------------------------------------------------------ */
/* 1. Converging: find a pair that sums to target in a SORTED array    */
/* ------------------------------------------------------------------ */
function twoSumSorted(nums, target) {
  let left = 0;
  let right = nums.length - 1;

  while (left < right) {
    const sum = nums[left] + nums[right];
    if (sum === target) {
      return [left, right];          // indices of the pair
    }
    if (sum < target) {
      left++;                       // need a larger sum
    } else {
      right--;                      // need a smaller sum
    }
  }
  return null;                      // no such pair
}

/* ------------------------------------------------------------------ */
/* 2. Converging: palindrome check on a string                         */
/* ------------------------------------------------------------------ */
function isPalindrome(s) {
  // Optional: normalize to alphanumeric only
  const clean = s.toLowerCase().replace(/[^a-z0-9]/g, "");
  let left = 0;
  let right = clean.length - 1;

  while (left < right) {
    if (clean[left] !== clean[right]) return false;
    left++;
    right--;
  }
  return true;
}

/* ------------------------------------------------------------------ */
/* 3. Converging: container with most water (classic)                  */
/* ------------------------------------------------------------------ */
function maxArea(heights) {
  let left = 0;
  let right = heights.length - 1;
  let best = 0;

  while (left < right) {
    const width = right - left;
    const h = Math.min(heights[left], heights[right]);
    best = Math.max(best, width * h);

    // Move the shorter wall inward; moving the taller one cannot help
    if (heights[left] < heights[right]) left++;
    else right--;
  }
  return best;
}

/* ------------------------------------------------------------------ */
/* 4. Same direction (fast/slow): remove duplicates in place           */
/* ------------------------------------------------------------------ */
function removeDuplicates(nums) {
  if (!nums.length) return 0;

  let slow = 0; // last kept element
  for (let fast = 1; fast < nums.length; fast++) {
    if (nums[fast] !== nums[slow]) {
      slow++;
      nums[slow] = nums[fast];
    }
  }
  return slow + 1; // new length
}

/* ------------------------------------------------------------------ */
/* 5. Same direction: move all zeros to the end while keeping order    */
/* ------------------------------------------------------------------ */
function moveZeros(nums) {
  let slow = 0;
  for (let fast = 0; fast < nums.length; fast++) {
    if (nums[fast] !== 0) {
      [nums[slow], nums[fast]] = [nums[fast], nums[slow]];
      slow++;
    }
  }
  return nums;
}

/* ------------------------------------------------------------------ */
/* 6. Same direction: partition (Dutch national flag, 0/1/2)            */
/* ------------------------------------------------------------------ */
function sortColors(nums) {
  let low = 0, mid = 0, high = nums.length - 1;
  while (mid <= high) {
    if (nums[mid] === 0) {
      [nums[low], nums[mid]] = [nums[mid], nums[low]];
      low++; mid++;
    } else if (nums[mid] === 1) {
      mid++;
    } else { // === 2
      [nums[mid], nums[high]] = [nums[high], nums[mid]];
      high--;
    }
  }
  return nums;
}

/* ------------------------------------------------------------------ */
/* Tiny assertion helper                                               */
/* ------------------------------------------------------------------ */
function assert(cond, msg) {
  if (!cond) {
    console.error("FAIL:", msg);
    process.exit(1);
  }
  console.log("PASS:", msg);
}

/* ------------------------------------------------------------------ */
/* Demo / tests                                                        */
/* ------------------------------------------------------------------ */
function main() {
  // twoSumSorted
  assert(JSON.stringify(twoSumSorted([1, 2, 3, 4, 6], 6)) === JSON.stringify([1, 3]),
        "twoSumSorted basic");
  assert(twoSumSorted([1, 2, 3], 10) === null, "twoSumSorted none");

  // isPalindrome
  assert(isPalindrome("A man, a plan, a canal: Panama"), "palindrome classic");
  assert(!isPalindrome("race a car"), "not palindrome");
  assert(isPalindrome(""), "empty palindrome");

  // maxArea
  assert(maxArea([1, 8, 6, 2, 5, 4, 8, 3, 7]) === 49, "maxArea classic");
  assert(maxArea([1, 1]) === 1, "maxArea tiny");

  // removeDuplicates
  const r1 = [1, 1, 2, 2, 2, 3];
  assert(removeDuplicates(r1) === 3 && r1.slice(0, 3).every((v, i) => v === [1, 2, 3][i]),
        "removeDuplicates");

  // moveZeros
  const z = [0, 1, 0, 3, 12];
  assert(JSON.stringify(moveZeros(z)) === JSON.stringify([1, 3, 12, 0, 0]),
        "moveZeros");

  // sortColors
  const c = [2, 0, 2, 1, 1, 0];
  assert(JSON.stringify(sortColors(c)) === JSON.stringify([0, 0, 1, 1, 2, 2]),
        "sortColors");

