JavaScript is dynamically typed, so “type checking” is usually done at runtime (or with external tools like TypeScript/JSDoc). Below is a complete, runnable plain-JavaScript mini type-checker with schemas, nested validation, unions, optionals, tuples, and clear error paths.

Save as `typecheck.js` and run with `node typecheck.js`.

```js
'use strict';

// ---------- helpers ----------
function typeOf(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  return typeof v;
}

function err(path, message) {
  return { path: path === '' ? '(root)' : path, message };
}

function joinPath(p, k) {
  return p === '' ? String(k) : `${p}.${k}`;
}

// ---------- Schema base ----------
class Schema {
  constructor(validateFn) {
    this._validate = validateFn;
    this.isOptional = false;
  }
  validate(value, path = '') {
    return this._validate(value, path);
  }
  parse(value) {
    const errors = this.validate(value, '');
    if (errors.length) {
      const msg = errors.map(e => `${e.path}: ${e.message}`).join('; ');
      const e = new TypeError(`Type validation failed: ${msg}`);
      e.errors = errors;
      throw e;
    }
    return value;
  }
  safeParse(value) {
    const errors = this.validate(value, '');
    return errors.length
      ? { success: false, errors }
      : { success: true, data: value };
  }
  optional() {
    return optional(this);
  }
}

function optional(schema) {
  const s = new Schema((v, p) => (v === undefined ? [] : schema.validate(v, p)));
  s.isOptional = true;
  return s;
}

function primitive(check, name) {
  return () =>
    new Schema((v, p) =>
      check(v) ? [] : [err(p, `expected ${name}, got ${typeOf(v)}`)]
    );
}

// ---------- type constructors ----------
const t = {
  string: primitive(v => typeof v === 'string', 'string'),
  number: primitive(v => typeof v === 'number' && !Number.isNaN(v), 'number'),
  boolean: primitive(v => typeof v === 'boolean', 'boolean'),
  null: primitive(v => v === null, 'null'),
  undefined: primitive(v => v === undefined, 'undefined'),
  any: () => new Schema(() => []),
  unknown: () => new Schema(() => []),

  literal: (val) =>
    new Schema((v, p) =>
      Object.is(v, val)
        ? []
        : [err(p, `expected ${JSON.stringify(val)}, got ${JSON.stringify(v)}`)]
    ),

  array: (item) =>
    new Schema((v, p) => {
      if (!Array.isArray(v)) return [err(p, `expected array, got ${typeOf(v)}`)];
      const errs = [];
      v.forEach((el, i) => {
        const ep = p === '' ? `[${i}]` : `${p}[${i}]`;
        errs.push(...item.validate(el, ep));
      });
      return errs;
    }),

  tuple: (schemas) =>
    new Schema((v, p) => {
      if (!Array.isArray(v)) return [err(p, `expected tuple (array), got ${typeOf(v)}`)];
      if (v.length !== schemas.length)
        return [err(p, `expected length ${schemas.length}, got ${v.length}`)];
      const errs = [];
      v.forEach((el, i) => {
        const ep = p === '' ? `[${i}]` : `${p}[${i}]`;
        errs.push(...schemas[i].validate(el, ep));
      });
      return errs;
    }),

  object: (shape) =>
    new Schema((v, p) => {
      if (typeOf(v) !== 'object' || v === null || Array.isArray(v))
        return [err(p, `expected object, got ${typeOf(v)}`)];
      const errs = [];
      for (const [k, sch] of Object.entries(shape)) {
        const has = Object.prototype.hasOwnProperty.call(v, k);
        if (!has && !sch.isOptional) {
          errs.push(err(joinPath(p, k), 'required (missing)'));
          continue;
        }
        if (has) errs.push(...sch.validate(v[k], joinPath(p, k)));
      }
      return errs;
    }),

  union: (...schemas) =>
    new Schema((v, p) => {
      const results = schemas.map(s => s.validate(v, p));
      if (results.some(r => r.length === 0)) return [];
      return results[0]; // show first alternative's errors
    }),

  record: (keySchema, valSchema) =>
    new Schema((v, p) => {
      if (typeOf(v) !== 'object' || v === null || Array.isArray(v))
        return [err(p, `expected object, got ${typeOf(v)}`)];
      const errs = [];
      for (const [k, val] of Object.entries(v)) {
        errs.push(...keySchema.validate(k, p === '' ? `key ${JSON.stringify(k)}` : `${p} key ${JSON.stringify(k)}`));
        errs.push(...valSchema.validate(val, joinPath(p, k)));
      }
      return errs;
    }),

  lazy: (fn) => new Schema((v, p) => fn().validate(v, p)),
};

// ---------- example usage ----------
const User = t.object({
  id: t.number(),
  name: t.string(),
  email: t.string(),
  age: t.optional(t.number()),
  roles: t.array(t.string()),
  status: t.union(t.literal('active'), t.literal('inactive')),
  profile: t.object({
    bio: t.optional(t.string()),
    links: t.tuple([t.string(), t.string()]),
  }),
  metadata: t.optional(t.record(t.string(), t.any())),
});

const goodUser = {
  id: 1,
  name: 'Ada',
  email: 'ada@example.com',
  age: 36,
  roles: ['admin', 'editor'],
  status: 'active',
  profile: {
    bio: 'Loves types',
    links: ['https://a', 'https://b'],
  },
  metadata: { source: 'import' },
};

console.log('GOOD:', User.safeParse(goodUser));

const badUser = {
  id: 'not-a-number',
  name: 42,
  roles: ['admin', 7],
  status: 'deleted',
  profile: {
    links: ['only-one'],
  },
};

try {
  User.parse(badUser);
} catch (e) {
  console.log('\nBAD parse threw:');
  console.log(e.message);
  console.log('\nErrors:');
  for (const er of e.errors) console.log(`  - ${er.path}: ${er.message}`);
}

// Optional chaining demo + lazy recursive type
const Node = t.lazy(() =>
  t.object({
    value: t.number(),
    children: t.optional(t.array(Node)),
  })
);

console.log('\nRECURSIVE:', Node.safeParse({ value: 1, children: [{ value: 2 }] }));
```

### What this gives you
- **Primitive & literal checks** with precise messages.
- **Containers**: `array`, `tuple`, `object`, `record`.
- **Composition**: `union`, `optional`, `lazy` (for recursive types).
- **Paths** in errors like `profile.links[1]` or `roles[1]`.
- **Two APIs**: `parse()` (throws) and `safeParse()` (result object).

### Static checking alternative (not runtime)
If you want compile-time checks in JS files, add a `jsconfig.json` / `tsconfig.json` with `allowJs` + `checkJs`, use JSDoc annotations (`/** @type {number} */`), and run `tsc --noEmit`. That catches type errors before runtime, while the runtime validator above guards untrusted input (API payloads, user data, config files).

### Mistaken version

```js
function getFirst(items) {
  if (typeof items === "array" && items.length > 0) {
    return items[0];
  }
  return null;
}

console.log(getFirst([10, 20, 30])); // expected 10, got null
```

### Corrected version

```js
function getFirst(items) {
  if (Array.isArray(items) && items.length > 0) {
    return items[0];
  }
  return null;
}

console.log(getFirst([10, 20, 30])); // 10
```

### What was wrong and why

- In JavaScript, **`typeof` never returns `"array"`**. It returns `"object"` for arrays (and for `null`, and for plain objects).
- Because of that, the condition `typeof items === "array"` is **always `false`**, so the function never enters the branch and always returns `null`.
- The correct, reliable check is **`Array.isArray(items)`**, which:
  - Returns `true` only for actual arrays (including subclasses created with `class MyArray extends Array`).
  - Works correctly across realms/iframes (unlike `items instanceof Array`, which can fail when an array was created in a different global context).
- As a bonus safety note: if you check `typeof x === "object"` to mean “any object,” you must **also exclude `null`**, because `typeof null === "object"` is a long-standing language quirk:

```js
function isPlainObject(v) {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}
```

Other common, related type-checking pitfalls worth remembering:

| Pitfall | Why it bites | Fix |
|---|---|---|
| `x === NaN` | `NaN` is never equal to itself | Use `Number.isNaN(x)` |
| `typeof x === "object"` for “not null” | `typeof null === "object"` | Add `x !== null` |
| `x instanceof Array` | Fails across iframes/realms | Use `Array.isArray(x)` |
| `if (x)` to check “defined” | Treats `0`, `""`, `false`, `NaN` as missing | Check `x !== undefined` (or `x != null` for both null/undefined) |

## Runtime type-checking pitfalls in JavaScript

### 1. `typeof null === 'object'`
```js
console.log(typeof null); // "object"

function isObject(v) {
  return v !== null && typeof v === 'object';
}
```

### 2. `NaN` is a number, and `NaN !== NaN`
```js
console.log(typeof NaN);        // "number"
console.log(NaN === NaN);       // false
console.log(isNaN('abc'));       // true  (coerces first)

function isFiniteNumber(v) {
  return typeof v === 'number' && Number.isFinite(v);
}
```

### 3. Arrays are objects; check with `Array.isArray`
```js
console.log(typeof []);         // "object"
console.log([] instanceof Array); // true in same realm, false across iframes

console.log(Array.isArray([])); // true
```

### 4. `instanceof` breaks across realms / iframes / VM contexts
```js
// In a different realm, Date is a different constructor
const otherDate = new (window.frames[0].Date)();
console.log(otherDate instanceof Date); // false

// Safer:
console.log(Object.prototype.toString.call(otherDate)); // "[object Date]"
```

### 5. Primitives vs boxed objects
```js
const n = 42;
const boxed = new Number(42);

console.log(typeof n);       // "number"
console.log(typeof boxed);   // "object"

// Prefer primitive checks; avoid relying on boxed types.
```

### 6. Truthiness is not a type check
```js
if (value) { /* skips 0, '', NaN, null, undefined, false */ }
if (arr) { /* true even for empty array */ }

// Explicit:
const hasItems = Array.isArray(arr) && arr.length > 0;
const isNonEmptyString = typeof str === 'string' && str.length > 0;
```

### 7. `==` performs coercion
```js
console.log(0 == false);   // true
console.log('' == false);   // true
console.log(null == undefined); // true

// Use strict equality:
console.log(0 === false);  // false
```

### 8. `hasOwnProperty` can be shadowed or missing
```js
const obj = Object.create(null);
obj.x = 1;

// obj.hasOwnProperty('x') // TypeError
console.log(Object.prototype.hasOwnProperty.call(obj, 'x')); // true
console.log(Object.hasOwn(obj, 'x')); // true (modern)
```

### 9. Constructor name is unreliable
```js
class Foo {}
const x = new Foo();
console.log(x.constructor.name); // "Foo" (may be mangled/minified)

// Prefer structural checks or well-known symbols, not names.
```

### 10. JSON and special values
```js
JSON.stringify({ a: undefined, b: NaN, c: Infinity, d: () => 1 });
// '{"a":...}'? Actually undefined/functions dropped; NaN/Infinity become null

// Don't rely on JSON round-tripping for type info.
```

### 11. `Object.prototype.toString.call` is robust but primitive-aware
```js
console.log(Object.prototype.toString.call(42));     // "[object Number]"
console.log(Object.prototype.toString.call('x'));    // "[object String]"
console.log(Object.prototype.toString.call(null));   // "[object Null]"
console.log(Object.prototype.toString.call(undefined)); // "[object Undefined]"
```

### 12. Promises/thenables are duck-typed
```js
const maybePromise = { then: (resolve) => resolve(1) };
// Don't assume instanceof Promise; check:
function isThenable(v) {
  return v != null && typeof v.then === 'function';
}
```

---

## If you use TypeScript (static type checking)

### 13. `any` silently disables checking
```ts
let x: any = 5;
x.foo.bar(); // no error, runtime crash possible
// Prefer `unknown` and narrow:
let y: unknown = 5;
if (typeof y === 'number') console.log(y.toFixed(2));
```

### 14. Type assertions lie to the compiler
```ts
const el = document.getElementById('app') as HTMLDivElement;
el.textContent = 'hi'; // compiles; may be null at runtime
```

### 15. Non-null assertion `!`
```ts
const el = document.getElementById('app')!; // assumes non-null
```

### 16. Array indexing returns `T`, not `T | undefined` by default
```ts
const arr = [1, 2, 3];
const x = arr[10]; // type: number (but undefined at runtime)
// Enable: "noUncheckedIndexedAccess": true
```

### 17. `Object.keys` returns `string[]`
```ts
const obj = { a: 1, b: 2 };
Object.keys(obj).forEach(k => {
  // obj[k] is number | undefined-ish unless indexed signature
});
```

### 18. Excess property checks only on fresh literals
```ts
type Options = { a?: number };
const o1: Options = { a: 1, b: 2 }; // error
const o2 = { a: 1, b: 2 };
const o3: Options = o2; // OK (structural)
```

### 19. Narrowing can be lost with mutation/closures
```ts
let x: string | number = Math.random() > 0.5 ? 'a' : 1;
if (typeof x === 'string') {
  setTimeout(() => {
    // x may be widened; narrowing isn't always preserved in closures
    console.log(x.length); // possibly error depending on TS version/settings
  });
}
```

### 20. Missing exhaustiveness checks
```ts
type Shape = { kind: 'circle'; r: number } | { kind: 'square'; s: number };

function area(s: Shape) {
  switch (s.kind) {
    case 'circle': return Math.PI * s.r * s.r;
    case 'square': return s.s * s.s;
    default:
      const _exhaustive: never = s; // catches missing cases
      return _exhaustive;
  }
}
```

### 21. Discriminated unions need a real discriminant
```ts
type A = { type: 'a'; value: string };
type B = { type: 'b'; value: number };

function handle(x: A | B) {
  if (x.type === 'a') return x.value.toUpperCase(); // narrowed to string
}
```

### 22. `in` narrowing and prototype pitfalls
```ts
function f(x: Date | { getTime(): number }) {
  if ('getTime' in x) {
    x.getTime(); // narrowed, but property may be inherited
  }
}
```

---

## Practical checklist
- Use `===` and `!==`.
- Treat `null` and `undefined` separately when needed.
- Use `Array.isArray`, `Number.isNaN`, `Number.isFinite`.
- Use `Object.hasOwn` or `Object.prototype.hasOwnProperty.call`.
- Prefer `unknown` over `any` in TypeScript.
- Enable `strict`, `noUncheckedIndexedAccess`.
- Add exhaustiveness checks with `never`.
- Don't trust assertions; validate at boundaries.

## Exercise

Implement two utilities:

1. `getType(value)` — returns a precise, human-readable type name for **any** JavaScript value.
   - Primitives: `"string"`, `"number"`, `"boolean"`, `"undefined"`, `"bigint"`, `"symbol"`, `"null"`
   - Objects: `"array"`, `"date"`, `"map"`, `"set"`, `"regexp"`, `"error"`, `"promise"`, `"function"`, `"object"` (plain object fallback)

2. `assertType(value, expectedType)` — throws a `TypeError` when `getType(value) !== expectedType`.

### Step-by-step solution

#### Step 1: Handle primitives first
`typeof` works for most primitives, but `typeof null === "object"` is a well-known bug, so handle `null` explicitly.

```js
if (value === null) return "null";
const t = typeof value;
if (t !== "object" && t !== "function") return t; // string, number, boolean, undefined, bigint, symbol
```

#### Step 2: Distinguish functions
Functions are objects with `typeof === "function"`. We want `"function"` for them.

```js
if (t === "function") return "function";
```

#### Step 3: Use `Object.prototype.toString`
For everything else (objects), `Object.prototype.toString.call(value)` gives a reliable tag like `[object Array]`.

```js
const tag = Object.prototype.toString.call(value).slice(8, -1).toLowerCase();
// "[object Array]" -> "array"
```

#### Step 4: Map tags to friendly names
Some tags are already the names we want (`array`, `date`, `map`, etc.). For plain objects the tag is `Object`, so map `"object"` → `"object"`.

```js
const known = new Set(["array", "date", "map", "set", "regexp", "error", "promise"]);
if (known.has(tag)) return tag;
if (tag === "object") return "object";
return tag; // fallback for exotic objects
```

#### Step 5: Implement `assertType`
```js
function assertType(value, expectedType) {
  const actual = getType(value);
  if (actual !== expectedType) {
    throw new TypeError(`Expected ${expectedType}, got ${actual}`);
  }
}
```

### Final solution

```js
function getType(value) {
  if (value === null) return "null";

  const t = typeof value;
  if (t !== "object" && t !== "function") return t; // primitives
  if (t === "function") return "function";

  const tag = Object.prototype.toString.call(value).slice(8, -1).toLowerCase();

  // Common built-ins we want to name explicitly
  const special = new Set(["array", "date", "map", "set", "regexp", "error", "promise"]);
  if (special.has(tag)) return tag;

  // Plain object or anything else
  return tag === "object" ? "object" : tag;
}

function assertType(value, expectedType) {
  const actual = getType(value);
  if (actual !== expectedType) {
    throw new TypeError(`Expected type "${expectedType}" but received "${actual}"`);
  }
  return value; // convenient for chaining
}

// ---- Quick checks ----
console.log(getType(null));            // "null"
console.log(getType(42));              // "number"
console.log(getType("hi"));            // "string"
console.log(getType([]));              // "array"
console.log(getType(new Date()));      // "date"
console.log(getType(new Map()));       // "map"
console.log(getType(/x/));             // "regexp"
console.log(getType(Promise.resolve())); // "promise"
console.log(getType({}));              // "object"

try {
  assertType(123, "string");
} catch (e) {
  console.log(e.message); // Expected type "string" but received "number"
}
```

### Notes
- `Object.prototype.toString.call` is the most reliable cross-realm check; `instanceof` can fail across iframes/realms.
- For custom classes, `getType` returns the class name (e.g., `"MyClass"`) because the tag becomes `[object MyClass]` when `Symbol.toStringTag` is set; otherwise it may fall back to `"object"`.
- If you need to distinguish *plain* objects from class instances, combine with `Object.getPrototypeOf(value) === Object.prototype`.

## Type Checking in JavaScript

JavaScript is **dynamically typed**: types are attached to *values*, not variables, and are checked at runtime. The language gives you a few built-in tools, each with quirks:

| Tool | Strengths | Quirks |
|---|---|---|
| `typeof` | Fast, works for primitives | `typeof null === 'object'`, `typeof [] === 'object'`, functions report `'function'` |
| `instanceof` | Works for class instances / custom types | Breaks across iframes/realms; doesn't work for primitives |
| `Array.isArray` | Reliable array check | Only arrays |
| `Object.prototype.toString.call` | Gives `[object X]` for most built-ins | Verbose |
| `=== null` / `=== undefined` | Exact checks | Must be explicit |

Static type checkers (TypeScript, Flow) add a compile-time layer on top: they use **structural typing** (shape-based, not name-based), type inference, and assignability rather than strict equality. At runtime, though, you're back to the tools above.

The "core" of a runtime type checker therefore is: **normalize a value's type, then recursively compare its shape against an expected schema.**

---

## Implementation

```js
/**
 * Returns a normalized, human-readable type string for any JS value.
 * Fixes the well-known `typeof` quirks (`null`, arrays).
 *
 * @param {*} value
 * @returns {string}
 */
function getType(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value; // 'undefined' | 'boolean' | 'number' | 'string' | 'symbol' | 'bigint' | 'function' | 'object'
}

/**
 * Checks whether `value` conforms to `schema`.
 *
 * Schema DSL:
 *   - string primitive type name: 'string', 'number', 'boolean', 'null',
 *     'undefined', 'object', 'array', 'function', 'symbol', 'bigint'
 *   - array with ONE element  -> array of that element type   (e.g. ['string'])
 *   - array with MANY elements -> union: value must match ONE   (e.g. ['string','number'])
 *   - object                   -> structural shape; keys ending in '?' are optional
 *
 * @param {*} value
 * @param {*} schema
 * @param {string} [path='$'] - dotted path used in error messages
 * @param {string[]} [errors=[]] - accumulator for failure reasons
 * @returns {boolean}
 */
function checkType(value, schema, path = '$', errors = []) {
  // ---------- Array schema ----------
  if (Array.isArray(schema)) {
    // Single-element array => "array of X"
    if (schema.length === 1) {
      if (getType(value) !== 'array') {
        errors.push(`${path}: expected array, got ${getType(value)}`);
        return false;
      }
      let allOk = true;
      value.forEach((item, i) => {
        if (!checkType(item, schema[0], `${path}[${i}]`, errors)) {
          allOk = false;
        }
      });
      return allOk;
    }

    // Multi-element array => union: value must satisfy at least one member.
    // Try each member in isolation so partial errors don't leak.
    for (const member of schema) {
      const trialErrors = [];
      if (checkType(value, member, path, trialErrors)) {
        return true;
      }
    }
    errors.push(`${path}: value did not match any union member (${schema.join(' | ')})`);
    return false;
  }

  // ---------- String schema (primitive type name) ----------
  if (typeof schema === 'string') {
    const actual = getType(value);
    if (actual !== schema) {
      errors.push(`${path}: expected ${schema}, got ${actual}`);
      return false;
    }
    return true;
  }

  // ---------- Object schema (structural shape) ----------
  if (typeof schema === 'object' && schema !== null) {
    if (getType(value) !== 'object') {
      errors.push(`${path}: expected object, got ${getType(value)}`);
      return false;
    }

    let ok = true;
    for (const rawKey of Object.keys(schema)) {
      const optional = rawKey.endsWith('?');
      const key = optional ? rawKey.slice(0, -1) : rawKey;
      const fieldSchema = schema[rawKey];

      if (!(key in value)) {
        if (optional) continue; // missing optional field is fine
        errors.push(`${path}.${key}: missing required field`);
        ok = false;
        continue;
      }

      // Recurse into the field.
      if (!checkType(value[key], fieldSchema, `${path}.${key}`, errors)) {
        ok = false;
      }
    }
    // Extra keys in `value` are allowed (structural typing).
    return ok;
  }

  // ---------- Unknown schema ----------
  errors.push(`${path}: invalid schema type ${getType(schema)}`);
  return false;
}

/**
 * Convenience wrapper returning a boolean only.
 */
function isType(value, schema) {
  return checkType(value, schema).ok;
}
```

