## Usage & Demo

```js
const UserSchema = {
  id: 'number',
  name: 'string',
  email: 'string',
  age: 'number?',          // optional
  tags: ['string'],        // string[]
  role: ['admin', 'user'], // union of literals-ish (here: string union)
  address: {
    city: 'string',
    zip: 'string?',
  },
};

const good = {
  id: 1,
  name: 'Ada',
  email: 'ada@example.com',
  tags: ['js', 'ts'],
  role: 'admin',
  address: { city: 'London' },
};

console.log(checkType(good, UserSchema));
// { ok: true, errors: [] }

const bad = {
  id: 'one',               // wrong type
  name: 'Ada',
  email: 'ada@example.com',
  tags: ['js', 42],        // mixed array
  role: 'superuser',       // not in union
  address: { city: 99 },   // wrong type
};

const result = checkType(bad, UserSchema);
console.log(result.ok);      // false
console.log(result.errors);
// [
//   "$.id: expected number, got string",
//   "$.tags[1]: expected string, got number",
//   "$.role: value did not match any union member (admin | user)",
//   "$.address.city: expected string, got number"
// ]
```

