```js
// A small shopping-cart module with sync + async + side-effecting code.

export class Cart {
  constructor({ taxRate = 0.1, currency = 'USD' } = {}) {
    this.taxRate = taxRate;
    this.currency = currency;
    this.items = [];
  }

  add(item) {
    if (!item || typeof item.price !== 'number' || item.price < 0) {
      throw new TypeError('item.price must be a non-negative number');
    }
    if (!item.name || typeof item.name !== 'string') {
      throw new TypeError('item.name must be a non-empty string');
    }
    const existing = this.items.find((i) => i.name === item.name);
    if (existing) {
      existing.qty += item.qty ?? 1;
    } else {
      this.items.push({ name: item.name, price: item.price, qty: item.qty ?? 1 });
    }
    return this; // fluent API
  }

  remove(name) {
    const idx = this.items.findIndex((i) => i.name === name);
    if (idx === -1) return false;
    this.items.splice(idx, 1);
    return true;
  }

  subtotal() {
    return this.items.reduce((sum, i) => sum + i.price * i.qty, 0);
  }

  total() {
    return round2(this.subtotal() * (1 + this.taxRate));
  }

  isEmpty() {
    return this.items.length === 0;
  }

  // Async example: pretend to persist cart to a store.
  async checkout(store) {
    if (this.isEmpty()) throw new Error('Cart is empty');
    const payload = { items: this.items, total: this.total(), currency: this.currency };
    const result = await store.save(payload);
    if (!result?.ok) throw new Error('Checkout failed');
    this.items = [];
    return result.id;
  }
}

function round2(n) {
  return Math.round(n * 100) / 100;
}

export { round2 };
```

