describe('Cart#checkout', () => {
  let cart;
  beforeEach(() => {
    cart = new Cart();
    cart.add({ name: 'Apple', price: 1.5 });
  });

  test('calls store.save with correct payload and clears cart', async () => {
    // Mock the store dependency.
    const save = mock.fn(async (payload) => ({ ok: true, id: 'order-42' }));
    const store = { save };

    const orderId = await cart.checkout(store);

    assert.equal(orderId, 'order-42');
    assert.equal(cart.items.length, 0, 'cart should be cleared');

    // Inspect the mock call.
    assert.equal(save.mock.calls.length, 1);
    const [payload] = save.mock.calls[0].arguments;
    assert.deepEqual(payload.items, [{ name: 'Apple', price: 1.5, qty: 1 }]);
    assert.equal(payload.total, 1.65); // 1.5 * 1.1
    assert.equal(payload.currency, 'USD');
  });

  test('throws when store returns not ok', async () => {
    const store = { save: mock.fn(async () => ({ ok: false })) };
    await assert.rejects(() => cart.checkout(store), /Checkout failed/);
    assert.equal(cart.items.length, 1, 'cart should NOT be cleared on failure');
  });

  test('throws on empty cart before calling store', async () => {
    const emptyCart = new Cart();
    const save = mock.fn(async () => ({ ok: true, id: 'x' }));
    await assert.rejects(() => emptyCart.checkout({ save }), /Cart is empty/);
    assert.equal(save.mock.calls.length, 0);
  });
});

