## Final Solution (Complete Script)

```js
// ---------- Data ----------
const userName = "Ava";
let age = 28;
const isMember = true;
let couponCode = "SAVE5";   // try null or "" to test
let shippingNote;            // undefined
const invoiceId = 9007199254740993n;

const cartItems = [
  { name: "Keyboard", price: 49.99, qty: 1 },
  { name: "Mouse",    price: "25.50", qty: 2 },
  { name: "USB Hub",  price: 19.0,   qty: 1 }
];

// ---------- Helpers ----------
function toNumber(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) throw new TypeError(`Expected finite number, got: ${value}`);
  return n;
}

function normalizeItem(item) {
  if (!item || typeof item !== "object") throw new TypeError("Item must be an object");
  const name = String(item.name ?? "Unnamed");
  const price = toNumber(item.price);
  const qty = toNumber(item.qty);
  if (qty <= 0) throw new RangeError(`Quantity must be > 0 for ${name}`);
  if (price < 0) throw new RangeError(`Price cannot be negative for ${name}`);
  return { name, price, qty };
}

const currency = (n) =>
  n.toLocaleString("en-US", { style: "currency", currency: "USD" });

// ---------- Compute ----------
const normalized = cartItems.map(normalizeItem);

const subtotalRaw = normalized.reduce((s, i) => s + i.price * i.qty, 0);
const subtotal = Math.round(subtotalRaw * 100) / 100;

let discountRate = 0;
if (isMember === true) discountRate += 0.10;

const hasCoupon = typeof couponCode === "string" && couponCode.trim() !== "";
if (hasCoupon) discountRate += 0.05;

const discountAmount = Math.round(subtotal * discountRate * 100) / 100;
const total = Math.round((subtotal - discountAmount) * 100) / 100;

// ---------- Output ----------
const lines = [];
lines.push(`Customer: ${userName} (age ${age})`);
lines.push(`Member: ${isMember ? "Yes" : "No"}`);
lines.push("");
lines.push("Items:");
for (const item of normalized) {
  lines.push(`  - ${item.name}: ${item.qty} x ${currency(item.price)} = ${currency(item.price * item.qty)}`);
}
lines.push("");
lines.push(`Subtotal: ${currency(subtotal)}`);
lines.push(`Discount: ${currency(discountAmount)} (${(discountRate * 100).toFixed(0)}%)`);
lines.push(`Total: ${currency(total)}`);
lines.push(`Invoice ID: ${invoiceId.toString()}`);
lines.push(`Note: ${shippingNote ?? "(no note provided)"}`);

console.log(lines.join("\n"));
