## Clean implementation of core concepts

```js
'use strict';

/**
 * Variables demo: prefer const, then let; avoid var.
 */
const API_URL = 'https://api.example.com'; // constant binding
let requestCount = 0;                      // reassignable binding

function incrementRequests() {
  requestCount += 1; // rebind allowed
  return requestCount;
}

/**
 * Primitive data type examples.
 */
const primitives = Object.freeze({
  text: 'hello',
  count: 42,
  ok: true,
  nothing: null,
  notYet: undefined,
  id: Symbol('user-id'),
  big: 9007199254740993n,
});

/**
 * A reliable type checker that fixes typeof quirks.
 * Returns a lowercase string type name.
 */
function getType(value) {
  if (value === null) return 'null';
  if (value === undefined) return 'undefined';
  if (Array.isArray(value)) return 'array';
  if (value instanceof Date) return 'date';
  if (value instanceof RegExp) return 'regexp';
  if (value instanceof Map) return 'map';
  if (value instanceof Set) return 'set';
  return typeof value; // string, number, boolean, symbol, bigint, function, object
}

/**
 * Safe equality: same type AND same value.
 * Handles NaN and avoids type coercion.
 */
function strictEqual(a, b) {
  // Object.is covers NaN and -0 vs +0 correctly.
  return getType(a) === getType(b) && Object.is(a, b);
}

/**
 * Deep equality for plain objects/arrays (interview-friendly version).
 * Not for cyclic structures or special objects.
 */
function deepEqual(a, b) {
  if (Object.is(a, b)) return true;
  if (getType(a) !== getType(b)) return false;

  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    return a.every((item, i) => deepEqual(item, b[i]));
  }

  if (typeof a === 'object' && a !== null) {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    return keysA.every((k) => Object.prototype.hasOwnProperty.call(b, k) && deepEqual(a[k], b[k]));
  }

  return false; // primitives already handled by Object.is
}

// ---- Demo / sanity checks ----
console.log(getType(primitives.nothing));   // 'null'
console.log(getType(primitives.id));        // 'symbol'
console.log(getType([]));                   // 'array'
console.log(strictEqual(NaN, NaN));         // true
console.log(deepEqual({ x: [1, 2] }, { x: [1, 2] })); // true
```

### Interview talking points
- Use `const` by default; `let` only when reassignment is required.
- Know `typeof null` quirk and use a helper like `getType`.
- Distinguish **value equality** (`===`/`Object.is`) from **reference equality** for objects.
- Avoid `==` unless you explicitly want coercion; prefer explicit conversion (`Number(x)`, `String(x)`).

Below is a complete, runnable, **educational** mini version-control system in Node.js. It implements the core ideas behind Git-style tools:

- content-addressable object store
- blob objects for file contents
- commit objects with parent pointers
- a staging index
- branches and `HEAD`
- `add`, `commit`, `status`, `log`, `checkout`, and simple diffs

Save it as `mini-vcs.js` and run:

```bash
node mini-vcs.js
```

## `mini-vcs.js`

```js
'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const os = require('os');

class MiniVCS {
  constructor(root) {
    this.root = path.resolve(root);
    this.vcsDir = path.join(this.root, '.mvc');
    this.objectsDir = path.join(this.vcsDir, 'objects');
    this.refsDir = path.join(this.vcsDir, 'refs', 'heads');
    this.indexPath = path.join(this.vcsDir, 'index.json');
    this.headPath = path.join(this.vcsDir, 'HEAD');
  }

  // ---------- initialization ----------

  init() {
    fs.mkdirSync(this.objectsDir, { recursive: true });
    fs.mkdirSync(this.refsDir, { recursive: true });
    if (!fs.existsSync(this.indexPath)) {
      fs.writeFileSync(this.indexPath, '{}\n', 'utf8');
    }
    if (!fs.existsSync(this.headPath)) {
      fs.writeFileSync(this.headPath, 'ref: refs/heads/main\n', 'utf8');
    }
  }

  _ensureInitialized() {
    if (!fs.existsSync(this.vcsDir)) {
      throw new Error('Not a repository. Run init() first.');
    }
  }

  // ---------- path helpers ----------

  _toRelative(absPath) {
    return path.relative(this.root, absPath).replace(/\\/g, '/');
  }

  _isInsideRoot(absPath) {
    const rel = path.relative(this.root, absPath);
    return rel !== '' && !rel.startsWith('..') && !path.isAbsolute(rel);
  }

  _objectPath(hash) {
    return path.join(this.objectsDir, hash);
  }

  // ---------- object database ----------

  _hashObject(type, data) {
    const payload = JSON.stringify({ type, data });
    return crypto.createHash('sha1').update(payload).digest('hex');
  }

  _writeObject(type, data) {
    const payload = JSON.stringify({ type, data });
    const hash = crypto.createHash('sha1').update(payload).digest('hex');
    const objectPath = this._objectPath(hash);

    if (!fs.existsSync(objectPath)) {
      fs.writeFileSync(objectPath, payload, 'utf8');
    }
    return hash;
  }

  _readObject(hash) {
    const objectPath = this._objectPath(hash);
    if (!fs.existsSync(objectPath)) {
      throw new Error(`Missing object: ${hash}`);
    }
    return JSON.parse(fs.readFileSync(objectPath, 'utf8'));
  }

  // ---------- index ----------

  _readIndex() {
    this._ensureInitialized();
    if (!fs.existsSync(this.indexPath)) return {};
    const raw = fs.readFileSync(this.indexPath, 'utf8').trim();
    return raw ? JSON.parse(raw) : {};
  }

  _writeIndex(index) {
    this._ensureInitialized();
    fs.writeFileSync(this.indexPath, JSON.stringify(index, null, 2) + '\n', 'utf8');
  }

  // ---------- refs / HEAD ----------

  _readHeadRaw() {
    this._ensureInitialized();
    return fs.readFileSync(this.headPath, 'utf8').trim();
  }

  _currentBranch() {
    const raw = this._readHeadRaw();
    const match = raw.match(/^ref: refs\/heads\/(.+)$/);
    return match ? match[1] : null;
  }

  _branchPath(name) {
    return path.join(this.refsDir, name);
  }

  _branchExists(name) {
    return fs.existsSync(this._branchPath(name));
  }

  _resolveHead() {
    const raw = this._readHeadRaw();
    if (raw.startsWith('ref: ')) {
      const refPath = path.join(this.vcsDir, raw.slice(5));
      if (!fs.existsSync(refPath)) return null;
      const hash = fs.readFileSync(refPath, 'utf8').trim();
      return hash || null;
    }
    return raw || null;
  }

  _resolveRevision(rev) {
    this._ensureInitialized();

    if (rev === 'HEAD') {
      const hash = this._resolveHead();
      if (!hash) throw new Error('HEAD does not point to a commit');
      return hash;
    }

    // Branch name
    const refPath = this._branchPath(rev);
    if (fs.existsSync(refPath)) {
      return fs.readFileSync(refPath, 'utf8').trim();
    }

    // Full hash
    if (fs.existsSync(this._objectPath(rev))) {
      return rev;
    }

    // Unique prefix
    const matches = fs.readdirSync(this.objectsDir).filter((name) => name.startsWith(rev));
    if (matches.length === 1) return matches[0];
    if (matches.length > 1) throw new Error(`Ambiguous revision: ${rev}`);

    throw new Error(`Unknown revision: ${rev}`);
  }

  _updateHeadCommit(hash) {
    const branch = this._currentBranch();
    if (branch) {
      fs.mkdirSync(this.refsDir, { recursive: true });
      fs.writeFileSync(this._branchPath(branch), hash + '\n', 'utf8');
    } else {
      fs.writeFileSync(this.headPath, hash + '\n', 'utf8');
    }
  }

  // ---------- working tree helpers ----------

  _listWorkingFiles(dir = this.root, acc = []) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      if (entry.name === '.mvc') continue;

      const abs = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        this._listWorkingFiles(abs, acc);
      } else if (entry.isFile()) {
        acc.push(this._toRelative(abs));
      }
    }
    return acc;
  }

  // ---------- public commands ----------

  add(filePath) {
    this._ensureInitialized();

    const abs = path.resolve(this.root, filePath);
    if (!this._isInsideRoot(abs)) {
      throw new Error(`Path escapes repository: ${filePath}`);
    }
    if (!fs.existsSync(abs) || !fs.statSync(abs).isFile()) {
      throw new Error(`Not a file: ${filePath}`);
    }

    const content = fs.readFileSync(abs, 'utf8');
    const hash = this._writeObject('blob', content);

    const index = this._readIndex();
    index[this._toRelative(abs)] = hash;
    this._writeIndex(index);

    return hash;
  }

  addAll() {
    this._ensureInitialized();
    for (const file of this._listWorkingFiles()) {
      this.add(file);
    }
  }

  status() {
    this._ensureInitialized();

    const index = this._readIndex();
    const headHash = this._resolveHead();
    const headFiles = headHash ? this._readObject(headHash).data.files || {} : {};

    const staged = [];
    const paths = new Set([...Object.keys(index), ...Object.keys(headFiles)]);

    for (const p of paths) {
      const inIndex = Object.prototype.hasOwnProperty.call(index, p);
      const inHead = Object.prototype.hasOwnProperty.call(headFiles, p);

      if (inIndex && !inHead) staged.push(`A ${p}`);
      else if (!inIndex && inHead) staged.push(`D ${p}`);
      else if (inIndex && inHead && index[p] !== headFiles[p]) staged.push(`M ${p}`);
    }

    const unstaged = [];
    for (const p of Object.keys(index)) {
      const abs = path.join(this.root, p);
      if (!fs.existsSync(abs)) {
        unstaged.push(`D ${p}`);
        continue;
      }
      const content = fs.readFileSync(abs, 'utf8');
      const workingHash = this._hashObject('blob', content);
      if (workingHash !== index[p]) {
        unstaged.push(`M ${p}`);
      }
    }

    const untracked = this._listWorkingFiles().filter(
      (p) => !Object.prototype.hasOwnProperty.call(index, p)
    );

    return { staged, unstaged, untracked };
  }

  commit(message) {
    this._ensureInitialized();
    if (!message || !String(message).trim()) {
      throw new Error('Commit message is required');
    }

    const index = this._readIndex();
    if (Object.keys(index).length === 0) {
      throw new Error('Nothing to commit');
    }

    const parent = this._resolveHead();
    const commitData = {
      message: String(message).trim(),
      timestamp: new Date().toISOString(),
      author: 'Developer <dev@example.com>',
      parent,
      files: { ...index }
    };

    const hash = this._writeObject('commit', commitData);
    this._updateHeadCommit(hash);
    return hash;
  }

  log() {
    this._ensureInitialized();

    const commits = [];
    let hash = this._resolveHead();

    while (hash) {
      const obj = this._readObject(hash);
      if (obj.type !== 'commit') break;
      commits.push({
        hash,
        message: obj.data.message,
        timestamp: obj.data.timestamp,
        author: obj.data.author,
        parent: obj.data.parent
      });
      hash = obj.data.parent;
    }

    return commits;
  }

  branches() {
    this._ensureInitialized();
    if (!fs.existsSync(this.refsDir)) return [];
    return fs.readdirSync(this.refsDir).sort();
  }

  createBranch(name, startPoint = 'HEAD') {
    this._ensureInitialized();
    if (!name || name.includes('/') || name.includes('\\')) {
      throw new Error('Invalid branch name');
    }

    const refPath = this._branchPath(name);
    if (fs.existsSync(refPath)) {
      throw new Error(`Branch already exists: ${name}`);
    }

    const hash = this._resolveRevision(startPoint);
    fs.writeFileSync(refPath, hash + '\n', 'utf8');
    return hash;
  }

  checkout(rev) {
    this._ensureInitialized();

    const hash = this._resolveRevision(rev);
    const commitObj = this._readObject(hash);
    if (commitObj.type !== 'commit') {
      throw new Error(`Not a commit: ${rev}`);
    }

    const targetFiles = commitObj.data.files || {};
    const currentHash = this._resolveHead();
    const currentFiles = currentHash
      ? this._readObject(currentHash).data.files || {}
      : {};

    // Remove files that exist in the current snapshot but not in the target snapshot.
    for (const p of Object.keys(currentFiles)) {
      if (!Object.prototype.hasOwnProperty.call(targetFiles, p)) {
        const abs = path.join(this.root, p);
        if (fs.existsSync(abs)) fs.unlinkSync(abs);
      }
    }

    // Write target snapshot.
    for (const [p, blobHash] of Object.entries(targetFiles)) {
      const blobObj = this._readObject(blobHash);
      const abs = path.join(this.root, p);
      fs.mkdirSync(path.dirname(abs), { recursive: true });
      fs.writeFileSync(abs, blobObj.data, 'utf8');
    }

    // Update index and HEAD.
    this._writeIndex({ ...targetFiles });

    if (this._branchExists(rev)) {
      fs.writeFileSync(this.headPath, `ref: refs/heads/${rev}\n`, 'utf8');
    } else {
      fs.writeFileSync(this.headPath, hash + '\n', 'utf8');
    }

    return hash;
  }

  diffFiles(fromRev, toRev) {
    this._ensureInitialized();

    const fromHash = this._resolveRevision(fromRev);
    const toHash = this._resolveRevision(toRev);

    const fromFiles = this._readObject(fromHash).data.files || {};
    const toFiles = this._readObject(toHash).data.files || {};

    const changes = [];
    const allPaths = new Set([...Object.keys(fromFiles), ...Object.keys(toFiles)]);

    for (const p of [...allPaths].sort()) {
      const inFrom = Object.prototype.hasOwnProperty.call(fromFiles, p);
      const inTo = Object.prototype.hasOwnProperty.call(toFiles, p);

      if (!inFrom && inTo) changes.push({ path: p, type: 'added' });
      else if (inFrom && !inTo) changes.push({ path: p, type: 'deleted' });
      else if (fromFiles[p] !== toFiles[p]) changes.push({ path: p, type: 'modified' });
    }

    return changes;
  }
}

// ---------- runnable demonstration ----------

function writeFile(root, relPath, content) {
  const abs = path.join(root, relPath);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, content, 'utf8');
}

function runDemo() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'mini-vcs-'));
  console.log('Repository:', root);

  const vcs = new MiniVCS(root);
  vcs.init();

  // First commit
  writeFile(root, 'README.md', '# Project\n');
  writeFile(root, 'src/index.js', 'console.log("version 1");\n');
  vcs.addAll();
  const firstCommit = vcs.commit('Initial commit');
  console.log('Created commit:', firstCommit.slice(0, 12));

  // Second commit
  writeFile(root, 'src/index.js', 'console.log("version 2");\n');
  writeFile(root, 'notes.txt', 'TODO: ship it\n');
  vcs.add('src/index.js');
  vcs.add('notes.txt');
  const secondCommit = vcs.commit('Update index and add notes');
  console.log('Created commit:', secondCommit.slice(0, 12));

  console.log('\nCommit log:');
  for (const commit of vcs.log()) {
    console.log(`  ${commit.hash.slice(0, 7)} ${commit.message}`);
  }

  console.log('\nStatus after clean commit:');
  console.log(vcs.status());

  // Working-tree modification
  writeFile(root, 'README.md', '# Project changed\n');
  console.log('\nStatus with unstaged working-tree change:');
  console.log(vcs.status());

  console.log('\nDiff between the two commits:');
  console.log(vcs.diffFiles(firstCommit, secondCommit));

  console.log('\nChecking out first commit...');
  vcs.checkout(firstCommit);
  console.log('README.md:', JSON.stringify(fs.readFileSync(path.join(root, 'README.md'), 'utf8')));
  console.log('notes.txt exists:', fs.existsSync(path.join(root, 'notes.txt')));

  console.log('\nBranches before branch creation:', vcs.branches());
  vcs.createBranch('feature', secondCommit);
  console.log('Branches after branch creation:', vcs.branches());

  console.log('\nChecking out feature branch...');
  vcs.checkout('feature');
  console.log('notes.txt exists:', fs.existsSync(path.join(root, 'notes.txt')));
  console.log('src/index.js:', fs.readFileSync(path.join(root, 'src', 'index.js'), 'utf8').trim());

  console.log('\nDone. Repository preserved at:', root);
}

runDemo();
```

## What this example demonstrates

1. **Object storage**
   - Files are stored as blob objects.
   - Commits are objects containing metadata and a file snapshot.
   - Every object is addressed by the SHA-1 hash of its serialized content.

2. **Staging area**
   - `add()` updates `.mvc/index.json`.
   - `commit()` turns the staged index into a commit snapshot.

3. **History**
   - Each commit stores a `parent` hash.
   - `log()` follows parent links backward.

4. **Branches**
   - A branch is just a file under `.mvc/refs/heads/`.
   - `HEAD` either points to a branch or directly to a commit hash.

5. **Checkout**
   - Restores files from a commit snapshot.
   - Updates the index and `HEAD`.
   - Removes files absent from the target snapshot.

6. **Diff**
   - Compares the file sets of two commits and reports added, deleted, and modified paths.

## Notes for real-world use

This is intentionally small and text-focused. A production VCS would additionally need:

- binary-file handling
- merge algorithms
- three-way merge and conflict markers
- packfiles and delta compression
- rename detection
- ignore rules
- atomic index updates
- fsync and crash safety
- signed commits and tags
- efficient large-repository performance

But the structure above captures the essential mental model: **working tree → index → commit objects → refs**.

## Exercise

Build a tiny in-memory version control system for one text file in Node.js. It should support:

- `write(text)` – change the working file
- `add()` – stage the working file
- `commit(message)` – create a commit from staged content
- `log()` – show commit history from `HEAD`
- `checkout(commitId)` – restore an older version
- `diff(refA, refB)` – show a line diff between two refs (`HEAD`, `WORKING`, `STAGED`, or a commit id)
- `status()` – show whether the working tree or staging area differs from `HEAD`

Then use it to:

1. Create an initial commit.
2. Make and commit a second change.
3. Modify the file again without committing.
4. Show `status()` and `diff('HEAD', 'WORKING')`.
5. Checkout the first commit and verify the content.

## Step-by-step solution

### Step 1: Model commits

A commit needs an id, message, content snapshot, timestamp, and parent pointer. We store all commits in an array and track `HEAD` as the current commit id.

### Step 2: Add staging and commit creation

`write()` changes only the working tree. `add()` copies the working tree into the staging area. `commit()` turns the staged snapshot into a commit and moves `HEAD`.

### Step 3: Implement history and checkout

`log()` follows parent pointers from `HEAD`. `checkout()` replaces the working tree with a commit snapshot and moves `HEAD`.

### Step 4: Implement a readable line diff

Use longest common subsequence (LCS) on lines to produce `+`, `-`, and unchanged lines.

### Step 5: Add ref resolution

Refs can be commit ids or the special names `HEAD`, `WORKING`, and `STAGED`, so `diff()` can compare any two states.

## Final solution

```js
// mini-vcs.js
const crypto = require('crypto');

function lines(text) {
  return text === '' ? [] : text.split('\n');
}

function diffLines(oldLines, newLines) {
  const m = oldLines.length;
  const n = newLines.length;

  // dp[i][j] = LCS length of oldLines[i:] and newLines[j:]
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      if (oldLines[i] === newLines[j]) {
        dp[i][j] = 1 + dp[i + 1][j + 1];
      } else {
        dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1]);
      }
    }
  }

  const result = [];
  let i = 0;
  let j = 0;

  while (i < m && j < n) {
    if (oldLines[i] === newLines[j]) {
      result.push({ type: ' ', line: oldLines[i] });
      i++;
      j++;
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      result.push({ type: '-', line: oldLines[i] });
      i++;
    } else {
      result.push({ type: '+', line: newLines[j] });
      j++;
    }
  }

  while (i < m) {
    result.push({ type: '-', line: oldLines[i] });
    i++;
  }

  while (j < n) {
    result.push({ type: '+', line: newLines[j] });
    j++;
  }

  return result;
}

function formatDiff(diff) {
  return diff.map(entry => `${entry.type} ${entry.line}`).join('\n');
}

class MiniVCS {
  constructor(initialContent = '') {
    this.working = initialContent;
    this.staged = null;
    this.commits = [];
    this.head = null;
  }

  _commitId(content, message) {
    return crypto
      .createHash('sha1')
      .update(`${content}\n${message}\n${Date.now()}\n${this.commits.length}`)
      .digest('hex')
      .slice(0, 8);
  }

  _getCommit(id) {
    return this.commits.find(commit => commit.id === id) || null;
  }

  _resolve(ref) {
    if (ref === 'WORKING') return this.working;
    if (ref === 'STAGED') return this.staged === null ? this.working : this.staged;
    if (ref === 'HEAD') ref = this.head;

    const commit = this._getCommit(ref);
    if (!commit) throw new Error(`Unknown ref: ${ref}`);
    return commit.content;
  }

  write(content) {
    this.working = content;
  }

  add() {
    this.staged = this.working;
  }

  commit(message) {
    if (this.staged === null) {
      throw new Error('Nothing staged. Run add() first.');
    }

    const id = this._commitId(this.staged, message);
    const commit = {
      id,
      message,
      content: this.staged,
      timestamp: new Date().toISOString(),
      parent: this.head
    };

    this.commits.push(commit);
    this.head = id;
    this.working = this.staged;
    this.staged = null;

    return id;
  }

  status() {
    const headContent = this.head ? this._getCommit(this.head).content : '';
    return {
      head: this.head,
      modified: this.working !== headContent,
      staged: this.staged !== null && this.staged !== headContent,
      stagedDiffersFromWorking:
        this.staged !== null && this.staged !== this.working
    };
  }

  log() {
    const history = [];
    let currentId = this.head;
    const byId = new Map(this.commits.map(c => [c.id, c]));

    while (currentId) {
      const commit = byId.get(currentId);
      if (!commit) break;
      history.push({
        id: commit.id,
        message: commit.message,
        timestamp: commit.timestamp
      });
      currentId = commit.parent;
    }

    return history;
  }

  checkout(id) {
    const commit = this._getCommit(id);
    if (!commit) throw new Error(`Unknown commit: ${id}`);

    this.working = commit.content;
    this.staged = null;
    this.head = id;
  }

  diff(leftRef, rightRef) {
    const leftLines = lines(this._resolve(leftRef));
    const rightLines = lines(this._resolve(rightRef));
    return formatDiff(diffLines(leftLines, rightLines));
  }
}

// Example usage
const repo = new MiniVCS('hello\n');

const firstId = repo.commit('initial commit');
// Note: staged is null here, so stage first in a real flow.
```

The above example has a deliberate mistake to illustrate why staging matters. Here is the correct full workflow:

```js
const repo = new MiniVCS('hello\n');

repo.add();
const firstId = repo.commit('initial commit');

repo.write('hello\nworld\n');
repo.add();
const secondId = repo.commit('add world line');

repo.write('hello\nworld\nagain\n');

console.log('STATUS:', repo.status());
console.log('\nDIFF HEAD -> WORKING:\n');
console.log(repo.diff('HEAD', 'WORKING'));

console.log('\nLOG:');
console.log(repo.log());

console.log('\nChecking out first commit...');
repo.checkout(firstId);
console.log('CONTENT AFTER CHECKOUT:\n' + repo.working);

console.log('\nVERIFY:', repo.working === 'hello\n');
```

Run it with:

```bash
node mini-vcs.js
```

Expected behavior:

- `status()` reports `modified: true` because the working tree has an uncommitted `again` line.
- `diff('HEAD', 'WORKING')` shows `+ again`.
- `log()` shows the second commit followed by the first.
- After `checkout(firstId)`, the working content is back to `hello\n`.

## Why this is a good minimal model

This exercise captures the core ideas behind real version control:

- **Snapshots, not deltas**: each commit stores full file content.
- **Staging area**: changes must be explicitly staged before commit.
- **HEAD**: one pointer identifies the current commit.
- **Immutability**: old commits remain available for checkout.
- **Diffing**: any two snapshots can be compared line by line.

In a real system such as Git, the same concepts exist but are optimized with object storage, trees, refs, packfiles, and three-way merges. The JavaScript version above keeps the concepts visible and easy to experiment with.

# Version Control Basics (JavaScript)

## Core concepts

| Concept | Meaning |
|---|---|
| **Blob** | Raw file contents, addressed by hash. |
| **Tree** | A directory snapshot: list of `(name, type, hash)` entries. |
| **Commit** | Immutable snapshot: points to a tree + parent commit(s) + metadata. |
| **Object DB** | Content-addressable store: `hash(object) → object`. |
| **Index (staging area)** | Proposed next commit: `path → blob hash`. |
| **Working tree** | Files you actually edit. |
| **HEAD** | Where you are: a branch name or a detached commit hash. |
| **Branch** | A movable pointer (name → commit hash). |
| **Merge** | Combine two commit graphs; fast-forward if possible, else 3-way merge. |

Key invariants:
- Objects are **immutable** and identified by their content hash → dedup + integrity.
- History is a **DAG** of commits (merge commits have ≥2 parents).
- `HEAD` + branches are the only *mutable* pointers.

Below is a small but complete in-memory implementation (`MiniGit`) with: init/add/commit, branches, checkout, log, diff (line-level), status, and 3-way merge.

```js
// mini-git.js  (Node 18+)
const crypto = require('crypto');

class MiniGit {
  constructor() {
    /** @type {Map<string, any>} content-addressable object store */
    this.objects = new Map();
    /** @type {Map<string, string>} path -> blob hash (staging area) */
    this.index = new Map();
    /** @type {Map<string, string>} path -> content (working tree) */
    this.working = new Map();
    /** @type {Map<string, string>} branch name -> commit hash */
    this.branches = new Map();
    /** @type {{type:'branch',name:string}|{type:'detached',hash:string}|null} */
    this.HEAD = null;
  }

  // ---------- hashing / object store ----------

  _canonical(obj) {
    if (obj === null || typeof obj !== 'object') return JSON.stringify(obj);
    if (Array.isArray(obj)) return '[' + obj.map((x) => this._canonical(x)).join(',') + ']';
    const keys = Object.keys(obj).sort();
    return '{' + keys.map((k) => JSON.stringify(k) + ':' + this._canonical(obj[k])).join(',') + '}';
  }

  _hash(obj) {
    return crypto.createHash('sha256').update(this._canonical(obj)).digest('hex').slice(0, 12);
  }

  _store(obj) {
    const h = this._hash(obj);
    if (!this.objects.has(h)) this.objects.set(h, obj);
    return h;
  }

  _load(h) {
    if (!this.objects.has(h)) throw new Error(`missing object ${h}`);
    return this.objects.get(h);
  }

  // ---------- tree helpers ----------

  /** flatten a tree hash -> Map<path, blobHash> */
  _flattenTree(treeHash, prefix = '') {
    const out = new Map();
    if (!treeHash) return out;
    const tree = this._load(treeHash);
    for (const e of tree.entries) {
      const p = prefix ? prefix + '/' + e.name : e.name;
      if (e.type === 'blob') out.set(p, e.hash);
      else if (e.type === 'tree') {
        for (const [k, v] of this._flattenTree(e.hash, p)) out.set(k, v);
      }
    }
    return out;
  }

  _buildTreeFromIndex() {
    const entries = [...this.index.entries()]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([path, hash]) => ({ name: path, type: 'blob', hash }));
    return this._store({ type: 'tree', entries });
  }

  _treeContent(treeHash, path) {
    const m = this._flattenTree(treeHash);
    const bh = m.get(path);
    return bh ? this._load(bh).content : null;
  }

  // ---------- refs ----------

  _resolveHead() {
    if (!this.HEAD) return null;
    if (this.HEAD.type === 'branch') return this.branches.get(this.HEAD.name) || null;
    return this.HEAD.hash;
  }

  _setHeadCommit(hash) {
    if (this.HEAD.type === 'branch') this.branches.set(this.HEAD.name, hash);
    else this.HEAD.hash = hash;
  }

  // ---------- public API ----------

  init(defaultBranch = 'main') {
    this.branches.set(defaultBranch, null);
    this.HEAD = { type: 'branch', name: defaultBranch };
  }

  /** write/overwrite a file in the working tree */
  writeFile(path, content) {
    this.working.set(path, content);
  }

  /** stage current working-tree version of path (or explicit content) */
  add(path, content) {
    const c = content !== undefined ? content : this.working.get(path);
    if (c === undefined) throw new Error(`path not in working tree: ${path}`);
    this.working.set(path, c);
    const blobHash = this._store({ type: 'blob', content: c });
    this.index.set(path, blobHash);
  }

  rm(path) {
    this.working.delete(path);
    this.index.delete(path);
  }

  status() {
    const headHash = this._resolveHead();
    const headFiles = headHash ? this._flattenTree(this._load(headHash).tree) : new Map();
    const staged = [], unstaged = [], untracked = [];

    // staged: index vs HEAD
    const allPaths = new Set([...this.index.keys(), ...headFiles.keys()]);
    for (const p of allPaths) {
      const i = this.index.get(p);
      const h = headFiles.get(p);
      if (i !== h) staged.push({ path: p, change: !h ? 'added' : !i ? 'deleted' : 'modified' });
    }
    // unstaged: working vs index
    for (const [p, c] of this.working) {
      const ih = this.index.get(p);
      const ic = ih ? this._load(ih).content : undefined;
      if (ic === undefined) untracked.push(p);
      else if (ic !== c) unstaged.push(p);
    }
    // deleted in working but staged
    for (const p of this.index.keys()) {
      if (!this.working.has(p)) unstaged.push(p + ' (deleted)');
    }
    return { staged, unstaged, untracked };
  }

  commit(message, author = 'dev <dev@example.com>') {
    const treeHash = this._buildTreeFromIndex();
    const parent = this._resolveHead();
    const commitObj = {
      type: 'commit',
      tree: treeHash,
      parents: parent ? [parent] : [],
      message,
      author,
      timestamp: Date.now(),
    };
    const hash = this._store(commitObj);
    this._setHeadCommit(hash);
    return hash;
  }

  log(ref) {
    const start = ref ? this._resolveRef(ref) : this._resolveHead();
    const out = [];
    const seen = new Set();
    const stack = [start];
    while (stack.length) {
      const h = stack.pop();
      if (!h || seen.has(h)) continue;
      seen.add(h);
      const c = this._load(h);
      out.push({ hash: h, message: c.message, author: c.author, timestamp: c.timestamp, parents: c.parents });
      for (const p of c.parents) stack.push(p);
    }
    return out.sort((a, b) => b.timestamp - a.timestamp);
  }

  _resolveRef(ref) {
    if (this.branches.has(ref)) return this.branches.get(ref);
    if (this.objects.has(ref)) return ref;
    throw new Error(`unknown ref ${ref}`);
  }

  branch(name, startRef) {
    const base = startRef ? this._resolveRef(startRef) : this._resolveHead();
    if (this.branches.has(name)) throw new Error(`branch exists: ${name}`);
    this.branches.set(name, base);
  }

  checkout(ref) {
    let targetHash;
    if (this.branches.has(ref)) {
      this.HEAD = { type: 'branch', name: ref };
      targetHash = this.branches.get(ref);
    } else {
      targetHash = ref;
      this.HEAD = { type: 'detached', hash: targetHash };
    }
    if (!targetHash) {
      // empty branch (no commits yet): clear
      this.index.clear();
      this.working.clear();
      return;
    }
    const commit = this._load(targetHash);
    const files = this._flattenTree(commit.tree);
    // reset index + working to commit snapshot
    this.index.clear();
    this.working.clear();
    for (const [path, blobHash] of files) {
      const content = this._load(blobHash).content;
      this.index.set(path, blobHash);
      this.working.set(path, content);
    }
  }

  // ---------- diff ----------

  /** line-level diff of two texts (Myers-ish via LCS DP) */
  static diffLines(oldText, newText) {
    const a = (oldText || '').split('\n');
    const b = (newText || '').split('\n');
    const n = a.length, m = b.length;
    // dp[i][j] = LCS length of a[i..] b[j..]
    const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
    for (let i = n - 1; i >= 0; i--)
      for (let j = m - 1; j >= 0; j--)
        dp[i][j] = a[i] === b[j] ? 1 + dp[i + 1][j + 1] : Math.max(dp[i + 1][j], dp[i][j + 1]);

    const out = [];
    let i = 0, j = 0;
    while (i < n || j < m) {
      if (i < n && j < m && a[i] === b[j]) {
        out.push({ type: 'ctx', line: a[i] }); i++; j++;
      } else if (j < m && (i === n || dp[i][j + 1] >= dp[i + 1][j])) {
        out.push({ type: 'add', line: b[j] }); j++;
      } else {
        out.push({ type: 'del', line: a[i] }); i++;
      }
    }
    return out;
  }

  /** diff between two commits (or commit hash) */
  diffCommits(aHash, bHash) {
    const aFiles = aHash ? this._flattenTree(this._load(aHash).tree) : new Map();
    const bFiles = bHash ? this._flattenTree(this._load(bHash).tree) : new Map();
    const result = [];
    const paths = new Set([...aFiles.keys(), ...bFiles.keys()]);
    for (const p of [...paths].sort()) {
      const ha = aFiles.get(p), hb = bFiles.get(p);
      if (ha === hb) continue;
      if (!ha) {
        result.push({ path: p, status: 'added', hunks: MiniGit.diffLines('', this._load(hb).content) });
      } else if (!hb) {
        result.push({ path: p, status: 'deleted', hunks: MiniGit.diffLines(this._load(ha).content, '') });
      } else {
        result.push({ path: p, status: 'modified', hunks: MiniGit.diffLines(this._load(ha).content, this._load(hb).content) });
      }
    }
    return result;
  }

  diffWorking() {
    // working tree vs index
    const result = [];
    const paths = new Set([...this.working.keys(), ...this.index.keys()]);
    for (const p of [...paths].sort()) {
      const wc = this.working.get(p);
      const ih = this.index.get(p);
      const ic = ih ? this._load(ih).content : undefined;
      if (wc === ic) continue;
      result.push({ path: p, hunks: MiniGit.diffLines(ic ?? '', wc ?? '') });
    }
    return result;
  }

  // ---------- merge ----------

  _ancestors(hash) {
    const out = new Set();
    const stack = [hash];
    while (stack.length) {
      const h = stack.pop();
      if (!h || out.has(h)) continue;
      out.add(h);
      const c = this._load(h);
      for (const p of c.parents) stack.push(p);
    }
    return out;
  }

  _isAncestor(a, b) {
    if (!a) return true; // null is ancestor of everything
    return this._ancestors(b).has(a);
  }

  _lca(a, b) {
    const ancA = this._ancestors(a);
    // BFS from b to find first common ancestor (prefer closest)
    const visited = new Set();
    const queue = [b];
    while (queue.length) {
      const h = queue.shift();
      if (!h) continue;
      if (visited.has(h)) continue;
      visited.add(h);
      if (ancA.has(h)) return h;
      const c = this._load(h);
      for (const p of c.parents) queue.push(p);
    }
    return null;
  }

  merge(branchName) {
    const current = this._resolveHead();
    const target = this.branches.get(branchName);
    if (target === undefined) throw new Error(`unknown branch ${branchName}`);
    if (!target) throw new Error('nothing to merge');
    if (this._isAncestor(target, current)) return { status: 'already-up-to-date', conflicts: [] };
    if (this._isAncestor(current, target)) {
      // fast-forward
      this._setHeadCommit(target);
      this.checkout(this.HEAD.type === 'branch' ? this.HEAD.name : target);
      return { status: 'fast-forward', conflicts: [] };
    }
    const base = this._lca(current, target);
    const baseFiles = base ? this._flattenTree(this._load(base).tree) : new Map();
    const curFiles = this._flattenTree(this._load(current).tree);
    const tgtFiles = this._flattenTree(this._load(target).tree);

    const allPaths = new Set([...baseFiles.keys(), ...curFiles.keys(), ...tgtFiles.keys()]);
    const mergedIndex = new Map();   // path -> content (resolved)
    const conflicts = [];
    for (const p of allPaths) {
      const b = baseFiles.has(p) ? this._load(baseFiles.get(p)).content : undefined;
      const c = curFiles.has(p) ? this._load(curFiles.get(p)).content : undefined;
      const t = tgtFiles.has(p) ? this._load(tgtFiles.get(p)).content : undefined;

      let result;
      if (c === t) result = c;                 // both same (or both deleted)
      else if (b === c) result = t;             // only target changed
      else if (b === t) result = c;             // only current changed
      else if (c === undefined && t === undefined) result = undefined; // both deleted
      else {
        // conflict
        conflicts.push(p);
        result = `<<<<<<< HEAD\n${c ?? ''}\n=======\n${t ?? ''}\n>>>>>>> ${branchName}`;
      }
      if (result === undefined) continue; // file removed
      mergedIndex.set(p, result);
    }

    // write merged result to working + index for clean files only
    this.working.clear();
    this.index.clear();
    for (const [p, content] of mergedIndex) {
      this.working.set(p, content);
      if (!conflicts.includes(p)) {
        const blobHash = this._store({ type: 'blob', content });
        this.index.set(p, blobHash);
      }
    }

    if (conflicts.length === 0) {
      const treeHash = this._buildTreeFromIndex();
      const mergeCommit = {
        type: 'commit', tree: treeHash, parents: [current, target],
        message: `Merge branch '${branchName}'`, author: 'dev <dev@example.com>', timestamp: Date.now(),
      };
      const h = this._store(mergeCommit);
      this._setHeadCommit(h);
    }
    return { status: conflicts.length ? 'conflict' : 'merged', conflicts };
  }
}

module.exports = MiniGit;

// ---------------- demo ----------------
if (require.main === module) {
  const g = new MiniGit();
  g.init();

  g.writeFile('README.md', '# Project\n');
  g.add('README.md');
  g.writeFile('src/index.js', 'console.log("hi");\n');
  g.add('src/index.js');
  const c1 = g.commit('initial commit');
  console.log('commit1', c1);

  g.branch('feature');
  g.checkout('feature');
  g.writeFile('src/index.js', 'console.log("hello feature");\n');
  g.add('src/index.js');
  g.writeFile('src/feature.js', 'module.exports = 42;\n');
  g.add('src/feature.js');
  const c2 = g.commit('add feature');
  console.log('commit2', c2);

  g.checkout('main');
  g.writeFile('README.md', '# Project\n\nUpdated on main.\n');
  g.add('README.md');
  const c3 = g.commit('update readme on main');
  console.log('commit3', c3);

  console.log('\n--- diff main..feature ---');
  console.log(JSON.stringify(g.diffCommits(c3, c2), null, 2).slice(0, 400));

  console.log('\n--- merge feature into main ---');
  console.log(g.merge('feature'));

  console.log('\n--- log ---');
  console.log(g.log().map((c) => `${c.hash} ${c.message}`));

  console.log('\n--- status ---');
  console.log(g.status());
}
```

## How to read this

- **Objects** are stored once per content hash (`_store`), so identical files across commits cost nothing.
- **`commit()`** snapshots the *index* into a tree and chains onto `HEAD`'s parent(s). That's the entire history model.
- **`checkout()`** is just "swap index + working tree to that commit's tree."
- **`merge()`** does the standard decision table on a per-file basis (base/current/target), fast-forwards or creates a 2-parent merge commit, and surfaces conflicts.
- **`diffLines()`** is an LCS dynamic program → O(n·m), fine for source files.

### Complexity notes (interview follow-ups)
- Hashing: O(size) per object; storage O(unique objects).
- `diffLines`: time/space O(n·m); could be optimized with Myers O((n+m)d).
- Ancestor walks: O(V) per query; production Git uses commit-graph + bloom filters + reachability bitmaps.
- Merge as implemented is O(files × filesize); real Git also handles renames via similarity.

### What's intentionally omitted
- Packfiles/delta compression, reflog, hooks, submodules, shallow clones, conflict-resolution UI, rename detection, and on-disk `.git` layout. Those are the next layer on top of these same primitives.

## Version Control Basics in JavaScript: Edge Cases & Code

Below are the most common edge cases when you either (1) implement version-comparison logic in JS or (2) drive Git from Node.js. Each section has runnable code.

---

### 1. Semantic-version parsing & comparison

#### Edge cases
- Missing patch/minor components (`"1"`, `"1.2"`)
- Pre-release tags (`1.0.0-rc.1` < `1.0.0`)
- Build metadata must be **ignored** in precedence (`1.0.0+exp.1` == `1.0.0`)
- Leading zeros (`"01.02.03"`) — invalid but often arrive from legacy data
- Non-numeric / `null` / `undefined` inputs
- Whitespace

```js
// semver-lite.js
function parse(v) {
  if (v == null) throw new TypeError("version is null/undefined");
  const s = String(v).trim();
  // split off build metadata first (ignored for ordering)
  const [coreBuild, ...restBuild] = s.split("+");
  const build = restBuild.join("+"); // kept for display only
  const [core, ...preParts] = coreBuild.split("-");
  const pre = preParts.join("-"); // pre-release may contain hyphens

  const nums = core.split(".");
  if (nums.length > 3) throw new Error("too many numeric components");
  while (nums.length < 3) nums.push("0");

  const numeric = nums.map((n) => {
    if (!/^\d+$/.test(n)) throw new Error(`invalid numeric part: ${n}`);
    // reject leading zeros unless the value is exactly "0"
    if (n.length > 1 && n.startsWith("0")) throw new Error(`leading zero: ${n}`);
    return Number(n);
  });

  return { numeric, pre, build, raw: s };
}

function cmpPre(a, b) {
  // no pre-release > any pre-release
  if (!a && !b) return 0;
  if (!a) return 1;
  if (!b) return -1;
  const pa = a.split(".");
  const pb = b.split(".");
  const len = Math.max(pa.length, pb.length);
  for (let i = 0; i < len; i++) {
    const xa = pa[i], xb = pb[i];
    if (xa === undefined) return -1; // shorter pre-release is lower
    if (xb === undefined) return 1;
    const na = /^\d+$/.test(xa), nb = /^\d+$/.test(xb);
    if (na && nb) {
      const d = Number(xa) - Number(xb);
      if (d !== 0) return Math.sign(d);
    } else if (na !== nb) {
      return na ? -1 : 1; // numeric < identifier
    } else {
      const c = xa < xb ? -1 : xa > xb ? 1 : 0;
      if (c !== 0) return c;
    }
  }
  return 0;
}

function compare(a, b) {
  const A = parse(a), B = parse(b);
  for (let i = 0; i < 3; i++) {
    if (A.numeric[i] !== B.numeric[i]) return Math.sign(A.numeric[i] - B.numeric[i]);
  }
  return cmpPre(A.pre, B.pre); // build metadata ignored
}

// demo
console.log(compare("1.0.0", "1.0") === 0);        // true (missing patch)
console.log(compare("1.0.0-rc.1", "1.0.0") < 0);   // true
console.log(compare("1.0.0+abc", "1.0.0+xyz") === 0); // true (build ignored)
try { parse("1.02.3"); } catch (e) { console.log("leading zero rejected"); }
```

---

### 2. Driving Git from Node.js (`child_process`)

#### Edge cases
- Paths with spaces / newlines / non-ASCII
- Large output exceeding `maxBuffer`
- Detached HEAD (branch is `null`)
- Non-zero exit codes on merge conflicts
- CRLF line endings in diffs
- Environment leakage (`GIT_DIR`, hooks)

```js
// git-runner.js
import { execFile } from "node:child_process";
import { promisify } from "node:util";

const exec = promisify(execFile);

export async function git(args, { cwd, maxBuffer = 64 * 1024 * 1024 } = {}) {
  // Use execFile (no shell) so paths with spaces are safe.
  try {
    const { stdout, stderr } = await exec("git", args, { cwd, maxBuffer, encoding: "utf8" });
    return { ok: true, stdout, stderr };
  } catch (err) {
    // err.code may be a number (exit status) or string (ENOENT)
    return { ok: false, code: err.code, stdout: err.stdout ?? "", stderr: err.stderr ?? "", error: err };
  }
}

export async function currentBranch(cwd) {
  // symbolic-ref fails on detached HEAD -> fall back to rev-parse
  const sym = await git(["symbolic-ref", "--short", "HEAD"], { cwd });
  if (sym.ok) return sym.stdout.trim();
  const sha = await git(["rev-parse", "--short", "HEAD"], { cwd });
  if (!sha.ok) return null; // empty repo
  return `detached@${sha.stdout.trim()}`;
}

export async function statusPorcelain(cwd) {
  const r = await git(["status", "--porcelain=v1", "-z"], { cwd });
  if (!r.ok) return r;
  // -z uses NUL separators; handles paths with newlines
  const entries = r.stdout.split("\0").filter(Boolean).map((line) => ({
    xy: line.slice(0, 2),
    path: line.slice(3),
  }));
  return { ok: true, entries };
}

// Usage edge cases
(async () => {
  const repo = process.cwd();
  console.log("branch:", await currentBranch(repo));

  // path with space
  await git(["add", "file with space.txt"], { cwd: repo });

  // large diff (streaming alternative shown below)
  const diff = await git(["diff", "--stat"], { cwd: repo, maxBuffer: 128 * 1024 * 1024 });
  if (!diff.ok) console.error("diff failed", diff.code, diff.stderr);
})();
```

#### Streaming large diffs (avoid `maxBuffer`)

```js
import { spawn } from "node:child_process";

function gitStream(args, cwd) {
  return new Promise((resolve, reject) => {
    const child = spawn("git", args, { cwd });
    let out = "", err = "";
    child.stdout.on("data", (d) => (out += d));
    child.stderr.on("data", (d) => (err += d));
    child.on("close", (code) => {
      if (code === 0) resolve(out);
      else reject(Object.assign(new Error(err), { code, stdout: out }));
    });
    child.on("error", reject);
  });
}
```

---

### 3. Working-tree / index edge cases

```js
// detect unmerged paths (merge conflicts) and special states
async function inspect(cwd) {
  const r = await git(["status", "--porcelain=v2", "-z"], { cwd });
  const states = { conflicts: [], untracked: [], renamed: [] };
  for (const rec of r.stdout.split("\0").filter(Boolean)) {
    // porcelain v2: "1 <xy> ...", "2 <xy> ... <orig>", "u <xy> ...", "? <path>", "! <path>"
    const tag = rec[0];
    if (tag === "u") states.conflicts.push(rec);
    else if (tag === "?") states.untracked.push(rec.slice(2));
    else if (tag === "2") {
      const parts = rec.split("\t"); // renamed: new path \t orig path (with -z, tab becomes... actually use -z carefully)
      states.renamed.push(parts);
    }
  }
  return states;
}
```

Note: with `-z`, renamed entries use a NUL between old/new path names in v2; parse accordingly or use v1 for simplicity.

---

### 4. Concurrency & locking

Git uses `.git/index.lock`. If two Node processes mutate the index concurrently, one fails with `Unable to create ... index.lock: File exists`.

```js
async function withIndexLock(cwd, fn, retries = 5) {
  for (let i = 0; i < retries; i++) {
    try { return await fn(); }
    catch (e) {
      if (String(e.stderr || e.message).includes("index.lock") && i < retries - 1) {
        await new Promise((r) => setTimeout(r, 50 * (i + 1)));
        continue;
      }
      throw e;
    }
  }
}
```

Removing a stale lock file blindly is dangerous — only remove if you are sure no git process is alive (check `ps`/PID). In JS, prefer retry/backoff over deletion.

---

### 5. Commit identity & hooks edge cases

- Missing `user.name`/`user.email` → commit fails. Override per-invocation:
```js
await git(["-c", "user.name=Bot", "-c", "user.email=bot@example.com", "commit", "-m", "msg"], { cwd });
```
- Skip hooks when needed (CI): `["commit", "--no-verify", ...]`
- GPG signing hangs in non-interactive contexts: add `--no-gpg-sign`.

---

### 6. Empty repositories & unborn branches

```js
async function hasCommits(cwd) {
  const r = await git(["rev-parse", "--verify", "HEAD"], { cwd });
  return r.ok; // false on brand-new repo
}

async function ensureInitialCommit(cwd) {
  if (await hasCommits(cwd)) return;
  await git(["config", "user.email", "x@y.z"], { cwd });
  await git(["config", "user.name", "Bot"], { cwd });
  await git(["commit", "--allow-empty", "-m", "initial"], { cwd });
}
```

---

### 7. Cross-platform path & URL quirks

```js
import path from "node:path";

// Never string-concatenate git paths; use path.join + forward slashes for git args
const file = path.join(repo, "sub", "file.js").split(path.sep).join("/");

// Windows drive letters in file:// URLs need special handling
const fileUrl = "file://" + (process.platform === "win32" ? "/" : "") + file.replace(/\\/g, "/");
```

Also normalize line endings before hashing/comparing:
```js
const normalized = content.replace(/\r\n/g, "\n");
```

---

### 8. Safe parsing of `git log` (don't parse porcelain text naively)

```js
async function lastCommit(cwd) {
  // Use a custom format with a record separator unlikely to appear in data
  const RS = "\x1e"; // unit separator
  const r = await git(
    ["log", "-1", `--format=%H${RS}%an${RS}%ae${RS}%s${RS}%B`],
    { cwd }
  );
  if (!r.ok) return null;
  const [sha, name, email, subject, body] = r.stdout.split(RS);
  return { sha: sha.trim(), name, email, subject, body };
}
```

Use `%x00`/NUL separators when paths are involved to survive newlines.

---

### 9. Dirty-state guards before destructive ops

```js
async function isClean(cwd) {
  const r = await git(["status", "--porcelain"], { cwd });
  return r.ok && r.stdout.trim() === "";
}

async function safeReset(cwd) {
  if (!(await isClean(cwd))) throw new Error("working tree dirty; aborting");
  await git(["reset", "--hard", "HEAD"], { cwd });
}
```

---

### 10. Tag/version sorting

```js
// git tag --sort=-v:refname uses version-aware sort
const r = await git(["tag", "--sort=-v:refname"], { cwd });
const latest = r.stdout.split("\n").filter(Boolean)[0];
```

But `v:refname` still mishandles some pre-release cases; combine with the semver `compare()` above and filter to valid tags:

```js
const tags = r.stdout.split("\n").filter(Boolean);
const valid = tags.filter((t) => { try { parse(t.replace(/^v/, "")); return true; } catch { return false; } });
valid.sort((a, b) => compare(b.replace(/^v/, ""), a.replace(/^v/, "")));
```

---

### Quick checklist

| Edge case | Mitigation |
|---|---|
| Spaces/newlines in paths | `execFile` + `-z` / NUL separators |
| Large output | stream or raise `maxBuffer` |
| Detached HEAD | fallback to `rev-parse HEAD` |
| Conflicts | check exit code + porcelain `u` lines |
| Empty repo | `--allow-empty` initial commit |
| Missing identity | `-c user.name=...` per call |
| Lock contention | retry/backoff, never blind-delete lock |
| Build metadata in versions | ignore after `+` for ordering |
| Pre-release precedence | numeric < identifier; shorter < longer |
| Cross-platform paths | `path.join` + forward slashes |

These patterns cover the bulk of "version control basics in JS" failure modes in real codebases.

Below is a complete, production-oriented guide to working with CSV in JavaScript. It covers a robust Node.js workflow (install + read + transform + write + stream), a browser example, and a dependency-free parser/writer you can drop into any project.

---

## 1. Recommended approach: use `csv-parse` + `csv-stringify`

For real CSVs (quoted fields, embedded newlines, commas inside values), hand-rolled string splitting breaks easily. The de-facto standard libs are `csv-parse` and `csv-stringify`.

### Install

```bash
npm init -y
npm install csv-parse csv-stringify
```

### Complete runnable script (`csv-demo.js`)

Create `input.csv`:

```csv
name,age,city
Alice,30,"New York, NY"
Bob,25,"Los Angeles"
Charlie,35,Chicago
```

Then run `node csv-demo.js`:

```js
// csv-demo.js
const fs = require('fs');
const { parseSync } = require('csv-parse/sync');
const { stringifySync } = require('csv-stringify/sync');

// ---------- READ ----------
const raw = fs.readFileSync('input.csv', 'utf8');

// columns:true turns each row into an object keyed by header
const records = parseSync(raw, {
  columns: true,
  skip_empty_lines: true,
  trim: true,          // trim whitespace around unquoted fields
  cast: true           // auto-convert numbers/booleans when safe
});

console.log('Parsed records:');
console.log(records);
/*
[
  { name: 'Alice', age: 30, city: 'New York, NY' },
  { name: 'Bob', age: 25, city: 'Los Angeles' },
  { name: 'Charlie', age: 35, city: 'Chicago' }
]
*/

// ---------- TRANSFORM ----------
const transformed = records.map((r) => ({
  name: r.name.toUpperCase(),
  age: r.age + 1,
  city: r.city
}));

// ---------- WRITE ----------
const output = stringifySync(transformed, {
  header: true,
  columns: ['name', 'age', 'city'] // explicit column order
});

fs.writeFileSync('output.csv', output, 'utf8');
console.log('\nWritten to output.csv:\n' + output);
```

Output (`output.csv`):

```csv
name,age,city
ALICE,31,"New York, NY"
BOB,26,Los Angeles
CHARLIE,36,Chicago
```

### Streaming very large files

Avoid loading everything into memory. Use `stream/promises` + `Transform`:

```js
// stream-csv.js
const fs = require('fs');
const { pipeline } = require('stream/promises');
const { Transform } = require('stream');
const { parse } = require('csv-parse');
const { stringify } = require('csv-stringify');

const transform = new Transform({
  objectMode: true,
  transform(row, _enc, cb) {
    // objectMode: row is already an object because of columns:true
    row.name = String(row.name).toUpperCase();
    row.age = Number(row.age) + 1;
    cb(null, row);
  }
});

(async () => {
  await pipeline(
    fs.createReadStream('input.csv'),
    parse({ columns: true, skip_empty_lines: true }),
    transform,
    stringify({ header: true }),
    fs.createWriteStream('output.csv')
  );
  console.log('Streaming transform complete');
})();
```

Run: `node stream-csv.js`

