## 2. Browser example (upload → parse → download)

In the browser you usually don’t have `fs`. Use `FileReader` for input and a Blob for output. For robust parsing use **PapaParse** (`npm install papaparse` or CDN).

```html
<!doctype html>
<html>
<body>
  <input type="file" id="file" accept=".csv,text/csv">
  <button id="dl">Download transformed CSV</button>
  <pre id="preview"></pre>

  <!-- PapaParse via CDN -->
  <script src="https://cdn.jsdelivr.net/npm/papaparse@5.4.1/papaparse.min.js"></script>
  <script>
    let rows = [];
    document.getElementById('file').addEventListener('change', (e) => {
      const file = e.target.files[0];
      if (!file) return;
      Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: (results) => {
          rows = results.data.map((r) => ({
            ...r,
            name: String(r.name || '').toUpperCase()
          }));
          document.getElementById('preview').textContent =
            JSON.stringify(rows, null, 2);
        },
        error: (err) => console.error(err)
      });
    });

    document.getElementById('dl').addEventListener('click', () => {
      if (!rows.length) return;
      const csv = Papa.unparse(rows, { columns: ['name', 'age', 'city'] });
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'transformed.csv';
      a.click();
      URL.revokeObjectURL(url);
    });
  </script>
</body>
</html>
```

