## 3. Dependency-free CSV parser + writer

Useful for small projects, edge runtimes, or when you can’t install packages. It handles quoted fields, escaped quotes (`""`), embedded newlines, `\r\n`, and BOM.

```js
// csv-utils.js
function parseCSV(text, delimiter = ',') {
  // Strip BOM
  if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);

  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let i = 0;
  const n = text.length;

  while (i < n) {
    const c = text[i];

    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i++; // skip escaped quote
        } else {
          inQuotes = false;
        }
      } else {
        field += c;
      }
    } else {
      if (c === '"') {
        inQuotes = true;
      } else if (c === delimiter) {
        row.push(field);
        field = '';
      } else if (c === '\n') {
        row.push(field);
        rows.push(row);
        row = [];
        field = '';
      } else if (c === '\r') {
        // ignore; \n will finalize the row (handles \r\n)
      } else {
        field += c;
      }
    }
    i++;
  }

  // Final field/row if file didn't end with newline
  if (field !== '' || row.length > 0) {
    row.push(field);
    rows.push(row);
  }

  // Drop a single trailing empty row caused by a final newline
  if (rows.length > 1) {
    const last = rows[rows.length - 1];
    if (last.length === 1 && last[0] === '') rows.pop();
  }

  return rows;
}

function toCSV(rows, delimiter = ',', lineEnding = '\n') {
  const escape = (cell) => {
    const s = cell == null ? '' : String(cell);
    if (/[",\n\r]/.test(s)) {
      return '"' + s.replace(/"/g, '""') + '"';
    }
    return s;
  };

  return rows
    .map((row) => row.map(escape).join(delimiter))
    .join(lineEnding);
}

// Optional helper: array of objects <-> array of arrays
function objectsToRows(objects, columns) {
  const cols = columns || (objects[0] ? Object.keys(objects[0]) : []);
  return [cols, ...objects.map((o) => cols.map((c) => o[c]))];
}

function rowsToObjects(rows) {
  if (!rows.length) return [];
  const [header, ...data] = rows;
  return data.map((r) =>
    header.reduce((acc, h, idx) => {
      acc[h] = r[idx];
      return acc;
    }, {})
  );
}

module.exports = { parseCSV, toCSV, objectsToRows, rowsToObjects };
```

### Using the pure-JS utilities

```js
// pure-demo.js
const fs = require('fs');
const { parseCSV, toCSV, rowsToObjects, objectsToRows } = require('./csv-utils');

const text = fs.readFileSync('input.csv', 'utf8');
const rows = parseCSV(text);
console.log('rows:', rows);

const objects = rowsToObjects(rows);
const transformed = objects.map((o) => ({
  ...o,
  name: String(o.name).toUpperCase(),
  age: Number(o.age) + 1
}));

const outRows = objectsToRows(transformed, ['name', 'age', 'city']);
const csv = toCSV(outRows);
fs.writeFileSync('output-pure.csv', csv, 'utf8');
console.log(csv);
```

