### Node.js: `csv-parse` / `csv-stringify`

Install: `npm i csv-parse csv-stringify`

Read a file (streaming, memory-friendly):

```js
import { createReadStream } from "node:fs";
import { parse } from "csv-parse";

const parser = createReadStream("data.csv").pipe(
  parse({ columns: true, skip_empty_lines: true, trim: true })
);

for await (const row of parser) {
  console.log(row); // { name: "Alice", age: "30", city: "NYC" }
}
```

Write CSV:

```js
import { createWriteStream } from "node:fs";
import { stringify } from "csv-stringify";

const stream = createWriteStream("out.csv");
const stringifier = stringify({ header: true });
stringifier.pipe(stream);

stringifier.write({ name: "Alice", age: 30 });
stringifier.write({ name: "Bob", age: 25 });
stringifier.end();
```

### Manual parsing (small/simple cases only)

```js
function parseCsvLine(line) {
  // Naive: does NOT handle quoted commas/newlines.
  return line.split(",").map(s => s.trim());
}

const text = "a,b,c\n1,2,3";
const rows = text.trim().split("\n").map(parseCsvLine);
```

⚠️ Manual splitting breaks on `"a,b",c` or multiline quoted fields. Use a library for real data.

