function parseCSV(text) { /* as above */ }
function rowsToObjects(rows) { /* as above */ }
function escapeField(value) { /* as above */ }
function toCSV(rows) { /* as above */ }

async function main() {
  const raw = await fs.readFile('people.csv', 'utf8');
  const rows = parseCSV(raw);
  const people = rowsToObjects(rows);
  const adults = people.filter(p => Number(p.age) > 25);

  const outRows = [
    ['name', 'age', 'city'],
    ...adults.map(p => [p.name, p.age, p.city])
  ];

  await fs.writeFile('adults.csv', toCSV(outRows), 'utf8');
  console.log('Wrote adults.csv');
}

main().catch(err => {
  console.error(err);
  process.exit(1);
