## Working with CSV in JavaScript (interview-style)

### 1. What CSV really is
CSV is a **text format**, not a data structure. Its rules (roughly RFC 4180):

- Records are separated by newlines (`\n` or `\r\n`).
- Fields are separated by a delimiter (usually `,`).
- A field may be **quoted** with `"..."` to contain commas, newlines, or quotes.
- Inside quotes, a quote is escaped by doubling it: `""`.
- The first row is often (but not always) a header.

### 2. Common approaches

| Environment | Typical tool |
|---|---|
| Browser | `FileReader` + a parser (PapaParse is the de-facto standard) |
| Node.js (small files) | `fs.readFile` + parser |
| Node.js (large files) | `fs.createReadStream` + streaming parser (`csv-parser`, `fast-csv`) |
| Writing | Build strings carefully or use a serializer library |

**Why not just `split(',')`?**  
Because of quoted fields: `"Doe, John",30,"line1\nline2"` must become 3 fields, not 4+.

### 3. Core implementation (parser + serializer)

Below is a dependency-free, RFC 4180-ish implementation. It handles:
- quoted fields with embedded commas/newlines/quotes
- `\r\n` and `\n`
- optional header row → array of objects
- serialization with proper escaping

```js
/**
 * Parse CSV text into rows.
 * @param {string} text
 * @param {object} [options]
 * @param {string} [options.delimiter=',']
 * @param {boolean} [options.header=false] - if true, first row becomes keys
 * @returns {string[][] | object[]}
 */
function parseCSV(text, { delimiter = ',', header = false } = {}) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let fieldStarted = false; // distinguishes an empty quoted field from "no field yet"

  const pushField = () => { row.push(field); field = ''; fieldStarted = false; };
  const pushRow = () => { rows.push(row); row = []; };

  let i = 0;
  const n = text.length;

  while (i < n) {
    const c = text[i];

    if (inQuotes) {
      if (c === '"') {
        // doubled quote => literal quote
        if (i + 1 < n && text[i + 1] === '"') {
          field += '"';
          i += 2;
        } else {
          inQuotes = false;
          i++;
        }
      } else {
        field += c;
        i++;
      }
    } else {
      if (c === '"') {
        // A quote starts a quoted field only at the very beginning of a field.
        if (field === '' && !fieldStarted) {
          inQuotes = true;
          fieldStarted = true;
          i++;
        } else {
          // Otherwise treat quote as an ordinary character.
          field += c;
          fieldStarted = true;
          i++;
        }
      } else if (c === delimiter) {
        pushField();
        i++;
      } else if (c === '\n' || c === '\r') {
        pushField();
        pushRow();
        // consume \r\n as a single line ending
        if (c === '\r' && i + 1 < n && text[i + 1] === '\n') i += 2;
        else i++;
      } else {
        field += c;
        fieldStarted = true;
        i++;
      }
    }
  }

  // Flush a trailing field/row if there is pending data.
  // (A file ending in \n already pushed its last row, so this avoids a phantom empty row.)
  if (row.length > 0 || fieldStarted || field !== '') {
    pushField();
    pushRow();
  }

  if (!header) return rows;
  if (rows.length === 0) return [];

  const headers = rows[0];
  return rows.slice(1).map((r) => {
    const obj = {};
    headers.forEach((h, idx) => {
      obj[h] = idx < r.length ? r[idx] : '';
    });
    return obj;
  });
}

/**
 * Serialize data to CSV text.
 * @param {Array<Array<any>|object>} data
 * @param {object} [options]
 * @param {string} [options.delimiter=',']
 * @param {string[]} [options.header] - force header order (for objects)
 * @param {string} [options.lineEnding='\n']
 * @returns {string}
 */
function stringifyCSV(data, { delimiter = ',', header = null, lineEnding = '\n' } = {}) {
  if (!Array.isArray(data) || data.length === 0) return '';

  const isObjects = typeof data[0] === 'object' && !Array.isArray(data[0]);

  const escapeField = (value) => {
    if (value === null || value === undefined) value = '';
    const str = String(value);
    if (
      str.includes(delimiter) ||
      str.includes('"') ||
      str.includes('\n') ||
      str.includes('\r')
    ) {
      return '"' + str.replace(/"/g, '""') + '"';
    }
    return str;
  };

  const lines = [];

  if (isObjects) {
    const headers = header || Object.keys(data[0]);
    lines.push(headers.map(escapeField).join(delimiter));
    for (const obj of data) {
      lines.push(headers.map((h) => escapeField(obj[h])).join(delimiter));
    }
  } else {
    if (Array.isArray(header)) {
      lines.push(header.map(escapeField).join(delimiter));
    }
    for (const row of data) {
      lines.push(row.map(escapeField).join(delimiter));
    }
  }

  return lines.join(lineEnding);
}
```

