## `src/client.ts`

```ts
export class HttpError extends Error {
  constructor(
    public readonly status: number,
    public readonly statusText: string,
    public readonly body: unknown,
    public readonly url: string,
  ) {
    super(`HTTP ${status} ${statusText} for ${url}`);
    this.name = "HttpError";
  }
}

export interface RequestOptions {
  method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE" | "HEAD" | "OPTIONS";
  headers?: Record<string, string>;
  body?: unknown;
  query?: Record<string, string | number | boolean | undefined | null>;
  timeoutMs?: number;
  retries?: number;
  signal?: AbortSignal;
}

export interface ClientOptions {
  baseUrl?: string;
  headers?: Record<string, string>;
  timeoutMs?: number;
  retries?: number;
}

const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));
const backoff = (attempt: number) => Math.min(1000 * 2 ** attempt, 8000);

export class HttpClient {
  private readonly baseUrl: string;
  private readonly defaultHeaders: Record<string, string>;
  private readonly defaultTimeout: number;
  private readonly defaultRetries: number;

  constructor(opts: ClientOptions = {}) {
    this.baseUrl = (opts.baseUrl ?? "").replace(/\/+$/, "");
    this.defaultHeaders = opts.headers ?? {};
    this.defaultTimeout = opts.timeoutMs ?? 10_000;
    this.defaultRetries = opts.retries ?? 0;
  }

  // ---------- public verbs ----------

  get<T = unknown>(path: string, opts: Omit<RequestOptions, "method" | "body"> = {}) {
    return this.request<T>(path, { ...opts, method: "GET" });
  }

  post<T = unknown>(path: string, body?: unknown, opts: Omit<RequestOptions, "method" | "body"> = {}) {
    return this.request<T>(path, { ...opts, method: "POST", body });
  }

  put<T = unknown>(path: string, body?: unknown, opts: Omit<RequestOptions, "method" | "body"> = {}) {
    return this.request<T>(path, { ...opts, method: "PUT", body });
  }

  patch<T = unknown>(path: string, body?: unknown, opts: Omit<RequestOptions, "method" | "body"> = {}) {
    return this.request<T>(path, { ...opts, method: "PATCH", body });
  }

  delete<T = unknown>(path: string, opts: Omit<RequestOptions, "method" | "body"> = {}) {
    return this.request<T>(path, { ...opts, method: "DELETE" });
  }

  // ---------- core ----------

  async request<T = unknown>(path: string, opts: RequestOptions = {}): Promise<T> {
    const url = this.buildUrl(path, opts.query);
    const method = opts.method ?? "GET";
    const headers: Record<string, string> = {
      Accept: "application/json",
      ...this.defaultHeaders,
      ...opts.headers,
    };

    let body: BodyInit | undefined;
    if (opts.body !== undefined) {
      const ct = headers["Content-Type"] ?? headers["content-type"];
      if (!ct) headers["Content-Type"] = "application/json";
      body = typeof opts.body === "string" ? opts.body : JSON.stringify(opts.body);
    }

    const retries = opts.retries ?? this.defaultRetries;
    const timeoutMs = opts.timeoutMs ?? this.defaultTimeout;
    const attempts = retries + 1;
    let lastError: unknown;

    for (let attempt = 0; attempt < attempts; attempt++) {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeoutMs);

      // Allow external cancellation to propagate.
      const onExternalAbort = () => controller.abort();
      if (opts.signal) {
        if (opts.signal.aborted) controller.abort();
        else opts.signal.addEventListener("abort", onExternalAbort, { once: true });
      }

      try {
        const res = await fetch(url, {
          method,
          headers,
          body,
          signal: controller.signal,
        });

        clearTimeout(timer);
        opts.signal?.removeEventListener("abort", onExternalAbort);

        const text = await res.text();
        let data: unknown = null;
        if (text) {
          try {
            data = JSON.parse(text);
          } catch {
            data = text; // non-JSON response
          }
        }

        if (!res.ok) {
          const httpErr = new HttpError(res.status, res.statusText, data, url);

          // Retry on 429 / 5xx (unless last attempt).
          const retryable = res.status === 429 || res.status >= 500;
          if (retryable && attempt < attempts - 1) {
            await sleep(backoff(attempt));
            lastError = httpErr;
            continue;
          }
          throw httpErr;
        }

        return data as T;
      } catch (err) {
        clearTimeout(timer);
        opts.signal?.removeEventListener("abort", onExternalAbort);

        // Don't retry HttpErrors that we already decided are final.
        if (err instanceof HttpError) throw err;

        lastError = err;
        if (attempt < attempts - 1) {
          await sleep(backoff(attempt));
          continue;
        }
        throw err;
      }
    }

    throw lastError ?? new Error("request failed");
  }

  // ---------- helpers ----------

  private buildUrl(
    path: string,
    query?: Record<string, string | number | boolean | undefined | null>,
  ): string {
    const full = path.startsWith("http")
      ? path
      : this.baseUrl
        ? this.baseUrl + (path.startsWith("/") ? path : "/" + path)
        : path;

    if (!/^https?:\/\//.test(full)) {
      throw new Error(`No baseUrl configured and path is not absolute: ${path}`);
    }

    const url = new URL(full);
    if (query) {
      for (const [key, value] of Object.entries(query)) {
        if (value !== undefined && value !== null) {
          url.searchParams.set(key, String(value));
        }
      }
    }
    return url.toString();
  }

  // Upload helper (multipart/form-data)
  async upload<T = unknown>(
    path: string,
    file: { name: string; data: Blob | Buffer | Uint8Array; type?: string },
    extraFields: Record<string, string> = {},
    opts: Omit<RequestOptions, "method" | "body" | "headers"> = {},
  ): Promise<T> {
    const form = new FormData();
    const blob =
      file.data instanceof Blob
        ? file.data
        : new Blob([file.data as BlobPart], { type: file.type ?? "application/octet-stream" });
    form.append("file", blob, file.name);
    for (const [k, v] of Object.entries(extraFields)) form.append(k, v);

    // Let fetch set the multipart boundary; do NOT set Content-Type manually.
    return this.request<T>(path, {
      ...opts,
      method: "POST",
      body: form as unknown as BodyInit,
      headers: { ...opts.headers }, // intentionally no Content-Type
    });
  }
}
```

## `src/index.ts` (demo + mock server)

```ts
import { createServer } from "node:http";
import { HttpClient } from "./client";
import type { User, CreateUserInput } from "./types";

// ---------- mock API server ----------
const server = createServer((req, res) => {
  let raw = "";
  req.on("data", (c) => (raw += c));
  req.on("end", () => {
    res.setHeader("Content-Type", "application/json");

    const url = new URL(req.url ?? "/", `http://${req.headers.host}`);
    const pathname = url.pathname;

    // GET /users
    if (pathname === "/users" && req.method === "GET") {
      res.end(JSON.stringify([{ id: 1, name: "Ada" }, { id: 2, name: "Linus" }]));
      return;
    }

    // GET /users/:id
    const m = pathname.match(/^\/users\/(\d+)$/);
    if (m && req.method === "GET") {
      res.end(JSON.stringify({ id: Number(m[1]), name: `User ${m[1]}` }));
      return;
    }

    // POST /users
    if (pathname === "/users" && req.method === "POST") {
      const body = raw ? JSON.parse(raw) : {};
      res.statusCode = 201;
      res.end(JSON.stringify({ id: 42, ...body }));
      return;
    }

    // PATCH /users/:id
    if (m && req.method === "PATCH") {
      const body = raw ? JSON.parse(raw) : {};
      res.end(JSON.stringify({ id: Number(m[1]), ...body }));
      return;
    }

    // DELETE /users/:id
    if (m && req.method === "DELETE") {
      res.statusCode = 204;
      res.end();
      return;
    }

    // POST /echo  (returns whatever was sent)
    if (pathname === "/echo" && req.method === "POST") {
      res.end(JSON.stringify({ received: raw ? JSON.parse(raw) : null }));
      return;
    }

    // GET /slow  (takes 2s — used to demo timeout)
    if (pathname === "/slow") {
      setTimeout(() => res.end(JSON.stringify({ ok: true })), 2000);
      return;
    }

    // GET /fail  (always 500 — used to demo retries)
    if (pathname === "/fail") {
      res.statusCode = 500;
      res.end(JSON.stringify({ error: "boom" }));
      return;
    }

    // GET /search  (echoes query)
    if (pathname === "/search") {
      res.end(JSON.stringify({ query: Object.fromEntries(url.searchParams) }));
      return;
    }

    res.statusCode = 404;
    res.end(JSON.stringify({ error: "not found" }));
  });
});

server.listen(3000, async () => {
  console.log("mock server listening on http://localhost:3000");
  await runDemo();
  server.close(() => console.log("server closed"));
});

// ---------- demo client ----------
async function runDemo() {
  const client = new HttpClient({
    baseUrl: "http://localhost:3000",
    timeoutMs: 5000,
    retries: 2,
    headers: { "X-Client": "ts-demo" },
  });

  try {
    // 1. GET list
    const users = await client.get<User[]>("/users");
    console.log("GET /users ->", users);

    // 2. GET single with query
    const user = await client.get<User>("/users/7");
    console.log("GET /users/7 ->", user);

    const search = await client.get("/search", {
      query: { q: "typescript", page: 2, verbose: true },
    });
    console.log("GET /search ->", search);

    // 3. POST
    const created = await client.post<User, CreateUserInput>("/users", {
      name: "Grace",
      email: "grace@example.com",
    });
    console.log("POST /users ->", created);

    // 4. PATCH
    const patched = await client.patch<User>("/users/7", { name: "Grace Hopper" });
    console.log("PATCH /users/7 ->", patched);

    // 5. DELETE
    await client.delete("/users/7");
    console.log("DELETE /users/7 -> (204, no body)");

    // 6. custom headers + body on echo
    const echoed = await client.post("/echo", { hello: "world" }, {
      headers: { "X-Request-Id": "abc-123" },
    });
    console.log("POST /echo ->", echoed);

    // 7. Timeout demo
    try {
      await client.get("/slow", { timeoutMs: 300 });
    } catch (e) {
      console.log("timeout demo ->", (e as Error).name, (e as Error).message);
    }

    // 8. Retry demo (server returns 500 twice then... actually always 500 here -> fails)
    try {
      await client.get("/fail", { retries: 2 });
    } catch (e) {
      if (e instanceof Error && "status" in e) {
        console.log("retry demo -> final error:", (e as { status: number }).status);
      } else {
        console.log("retry demo ->", e);
      }
    }

    // 9. Cancellation demo
    const ac = new AbortController();
    setTimeout(() => ac.abort(), 50);
    try {
      await client.get("/slow", { signal: ac.signal });
    } catch (e) {
      console.log("cancel demo ->", (e as Error).name);
    }

    // 10. File upload demo
    const uploaded = await client.upload("/echo", {
      name: "hello.txt",
      data: new TextEncoder().encode("file contents"),
      type: "text/plain",
    });
    console.log("upload demo ->", uploaded);

  } catch (err) {
    console.error("demo error:", err);
  }
}
```

