```

### Notes for real projects

- In browsers, `fetch` can be blocked by CORS depending on the endpoint.
- For cancellation, pass an `AbortSignal` to `fetch`.
- For production APIs, replace the simple `isUser` guard with a schema validator such as Zod.
- If you need retries, wrap only network/5xx errors and use exponential backoff.

### 1) How I’d explain HTTP requests in a TypeScript interview

An HTTP request is a message from a client to a server and an HTTP response back. The core pieces are:

- **Method**: `GET`, `POST`, `PUT`, `PATCH`, `DELETE`, etc.
- **URL**: origin + path + query parameters.
- **Headers**: metadata such as `Content-Type`, `Authorization`, `Accept`.
- **Body**: usually JSON, form data, or binary for non-GET requests.
- **Response**: status code, headers, and body.
- **Lifecycle concerns**: timeouts, retries, cancellation, error handling, parsing, and type safety.

In TypeScript, the value is not just “making a request,” but modeling the whole flow:

- Use **generics** for response/body types: `request<User>(...)`.
- Use **union types** for HTTP methods and response kinds.
- Convert unknown runtime data into typed data carefully.
- Handle both **network errors** and **HTTP error statuses**.
- Respect **idempotency**: retries are usually safe for `GET`, `HEAD`, `OPTIONS`, but dangerous for `POST` unless the API is idempotent.
- Support **cancellation** through `AbortSignal`.
- Avoid leaking untyped `any` through the public API.

A practical implementation usually wraps `fetch` and centralizes:

1. URL construction
2. Header merging
3. Body serialization
4. Timeout/cancellation
5. Retry policy
6. Status checking
7. Response parsing
8. Typed error creation

---

### 2) Core implementation

Below is a clean, framework-agnostic TypeScript HTTP client built around `fetch`. It is intentionally small but production-shaped.

```ts
// http-client.ts

type HttpMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE" | "HEAD" | "OPTIONS";

type Primitive = string | number | boolean | null | undefined;
type QueryValue = Primitive | Primitive[];
type QueryParams = Record<string, QueryValue>;

interface HttpClientConfig {
  baseUrl?: string;
  defaultHeaders?: Record<string, string>;
  timeoutMs?: number;
  retries?: number;
  retryDelayMs?: number;
}

interface RequestOptions<TBody = unknown> {
  method?: HttpMethod;
  headers?: Record<string, string>;
  query?: QueryParams;
  body?: TBody;
  timeoutMs?: number;
  retries?: number;
  retryDelayMs?: number;
  responseType?: "json" | "text" | "blob" | "arrayBuffer" | "none";
  signal?: AbortSignal;
}

class HttpError extends Error {
  constructor(
    message: string,
    public readonly status: number,
    public readonly statusText: string,
    public readonly url: string,
    public readonly body?: unknown,
    public readonly headers?: Headers,
  ) {
    super(message);
    this.name = "HttpError";
  }
}

const SAFE_METHODS = new Set<HttpMethod>(["GET", "HEAD", "OPTIONS"]);

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function joinUrl(base: string, path: string): string {
  if (!base) return path;
  return `${base.replace(/\/+$/, "")}/${path.replace(/^\/+/, "")}`;
}

function appendQuery(url: URL, query?: QueryParams): void {
  if (!query) return;

  for (const [key, value] of Object.entries(query)) {
    if (value === undefined || value === null) continue;

    const values = Array.isArray(value) ? value : [value];
    for (const item of values) {
      if (item === undefined || item === null) continue;
      url.searchParams.append(key, String(item));
    }
  }
}

function isBodyInit(value: unknown): value is BodyInit {
  return (
    typeof value === "string" ||
    value instanceof Blob ||
    value instanceof FormData ||
    value instanceof URLSearchParams ||
    value instanceof ArrayBuffer ||
    ArrayBuffer.isView(value)
  );
}

function prepareBody(body: unknown, headers: Headers): BodyInit | undefined {
  if (body === undefined) return undefined;

  // Let fetch handle native body types directly.
  if (isBodyInit(body)) return body;

  // Otherwise, serialize plain objects/arrays as JSON.
  if (!headers.has("content-type")) {
    headers.set("content-type", "application/json");
  }
  return JSON.stringify(body);
}

function withTimeout(
  externalSignal: AbortSignal | undefined,
  timeoutMs: number,
): { signal: AbortSignal; cleanup: () => void } {
  const controller = new AbortController();

  // If there is no timeout, still support external cancellation.
  if (timeoutMs <= 0) {
    if (externalSignal) {
      if (externalSignal.aborted) {
        controller.abort(externalSignal.reason);
      } else {
        const onAbort = () => controller.abort(externalSignal.reason);
        externalSignal.addEventListener("abort", onAbort, { once: true });
        return {
          signal: controller.signal,
          cleanup: () => externalSignal.removeEventListener("abort", onAbort),
        };
      }
    }
    return { signal: controller.signal, cleanup: () => {} };
  }

  const timer = setTimeout(() => {
    controller.abort(new Error("Request timed out"));
  }, timeoutMs);

  const onExternalAbort = () => controller.abort(externalSignal?.reason);

  if (externalSignal) {
    if (externalSignal.aborted) {
      controller.abort(externalSignal.reason);
    } else {
      externalSignal.addEventListener("abort", onExternalAbort, { once: true });
    }
  }

  return {
    signal: controller.signal,
    cleanup: () => {
      clearTimeout(timer);
      externalSignal?.removeEventListener("abort", onExternalAbort);
    },
  };
}

async function parseResponse<T>(
  response: Response,
  responseType: RequestOptions["responseType"] = "auto" as any,
): Promise<T> {
  if (response.status === 204) return undefined as T;

  const effectiveType =
    responseType === "auto" || responseType === undefined
      ? response.headers.get("content-type")?.includes("application/json")
        ? "json"
        : "text"
      : responseType;

  switch (effectiveType) {
    case "json":
      return (await response.json()) as T;
    case "text":
      return (await response.text()) as T;
    case "blob":
      return (await response.blob()) as T;
    case "arrayBuffer":
      return (await response.arrayBuffer()) as T;
    case "none":
      return undefined as T;
    default:
      return (await response.text()) as T;
  }
}

export class HttpClient {
  private readonly baseUrl: string;
  private readonly defaultHeaders: Record<string, string>;
  private readonly timeoutMs: number;
  private readonly retries: number;
  private readonly retryDelayMs: number;

  constructor(config: HttpClientConfig = {}) {
    this.baseUrl = config.baseUrl ?? "";
    this.defaultHeaders = config.defaultHeaders ?? {};
    this.timeoutMs = config.timeoutMs ?? 10_000;
    this.retries = config.retries ?? 0;
    this.retryDelayMs = config.retryDelayMs ?? 300;
  }

  async request<TResponse = unknown, TBody = unknown>(
    path: string,
    options: RequestOptions<TBody> = {},
  ): Promise<TResponse> {
    const method = options.method ?? "GET";
    const url = new URL(
      joinUrl(this.baseUrl, path),
      typeof window !== "undefined" && window.location?.origin
        ? window.location.origin
        : "http://localhost",
    );

    appendQuery(url, options.query);

    const retries = options.retries ?? this.retries;
    const attempts = retries + 1;

    const retryWasExplicitlyConfigured =
      options.retries !== undefined || this.retries !== undefined;

    let lastError: unknown;

    for (let attempt = 0; attempt < attempts; attempt++) {
      if (attempt > 0) {
        const delay =
          options.retryDelayMs ??
          this.retryDelayMs ??
          300 * 2 ** (attempt - 1);
        await sleep(delay);
      }

      const headers = new Headers(this.defaultHeaders);
      for (const [key, value] of Object.entries(options.headers ?? {})) {
        headers.set(key, value);
      }

      const { signal, cleanup } = withTimeout(options.signal, options.timeoutMs ?? this.timeoutMs);

      try {
        const init: RequestInit = {
          method,
          headers,
          signal,
        };

        const body = prepareBody(options.body, headers);
        if (body !== undefined) init.body = body;

        const response = await fetch(url.toString(), init);

        if (!response.ok) {
          let errorBody: unknown;
          try {
            errorBody = await parseResponse(response, "auto");
          } catch {
            errorBody = undefined;
          }

          const httpError = new HttpError(
            `HTTP ${response.status} ${response.statusText}`,
            response.status,
            response.statusText,
            url.toString(),
            errorBody,
            response.headers,
          );

          // Retry only safe methods for 5xx/429 by default.
          // If retries are explicitly configured, also retry configured unsafe methods.
          const canRetryStatus =
            attempt < attempts - 1 &&
            (response.status === 429 || response.status >= 500) &&
            (SAFE_METHODS.has(method) || retryWasExplicitlyConfigured);

          if (canRetryStatus) {
            lastError = httpError;
            continue;
          }

          throw httpError;
        }

        return await parseResponse<TResponse>(response, options.responseType);
      } catch (error) {
        lastError = error;

        // Network/timeout/abort errors.
        const isHttpError = error instanceof HttpError;
        const canRetryNetwork =
          attempt < attempts - 1 &&
          !isHttpError &&
          (SAFE_METHODS.has(method) || retryWasExplicitlyConfigured);

        if (!canRetryNetwork) {
          throw error;
        }
      } finally {
        cleanup();
      }
    }

    throw lastError instanceof Error
      ? lastError
      : new Error("Request failed");
  }

  get<TResponse = unknown>(path: string, options?: Omit<RequestOptions, "method" | "body">) {
    return this.request<TResponse>(path, { ...options, method: "GET" });
  }

  delete<TResponse = unknown>(path: string, options?: Omit<RequestOptions, "method" | "body">) {
    return this.request<TResponse>(path, { ...options, method: "DELETE" });
  }

  post<TResponse = unknown, TBody = unknown>(
    path: string,
    body?: TBody,
    options?: Omit<RequestOptions<TBody>, "method" | "body">,
  ) {
    return this.request<TResponse, TBody>(path, { ...options, method: "POST", body });
  }

  put<TResponse = unknown, TBody = unknown>(
    path: string,
    body?: TBody,
    options?: Omit<RequestOptions<TBody>, "method" | "body">,
  ) {
    return this.request<TResponse, TBody>(path, { ...options, method: "PUT", body });
  }

  patch<TResponse = unknown, TBody = unknown>(
    path: string,
    body?: TBody,
    options?: Omit<RequestOptions<TBody>, "method" | "body">,
  ) {
    return this.request<TResponse, TBody>(path, { ...options, method: "PATCH", body });
  }
}
```

