```ts
/* ============================================================
 * Mini ORM - TypeScript
 * Complete, runnable example (in-memory engine)
 * ============================================================ */

// ---------- Metadata types ----------

type ColumnType = 'string' | 'number' | 'boolean' | 'date';

interface ColumnMeta {
  property: string;
  name: string;
  type: ColumnType;
  primary: boolean;
  generated: boolean;
  nullable: boolean;
}

interface RelationMeta {
  property: string;
  type: 'many-to-one' | 'one-to-many' | 'one-to-one';
  target: () => Function;
  foreignKey?: string;   // column name holding the FK
  mappedBy?: string;    // property name on the other side
}

interface EntityMeta {
  target: Function;
  tableName: string;
  columns: ColumnMeta[];
  relations: RelationMeta[];
}

const ENTITY_METADATA = new Map<Function, EntityMeta>();

function metaOf(target: any): EntityMeta {
  const ctor = typeof target === 'function' ? target : target.constructor;
  if (!ENTITY_METADATA.has(ctor)) {
    ENTITY_METADATA.set(ctor, {
      target: ctor,
      tableName: ctor.name.toLowerCase() + 's',
      columns: [],
      relations: [],
    });
  }
  return ENTITY_METADATA.get(ctor)!;
}

// ---------- Decorators ----------

function Entity(tableName?: string) {
  return function (target: Function) {
    const m = metaOf(target);
    if (tableName) m.tableName = tableName;
  };
}

function Column(options: { name?: string; type?: ColumnType; nullable?: boolean } = {}) {
  return function (target: any, propertyKey: string) {
    const m = metaOf(target.constructor);
    m.columns.push({
      property: propertyKey,
      name: options.name ?? propertyKey,
      type: options.type ?? 'string',
      primary: false,
      generated: false,
      nullable: options.nullable ?? true,
    });
  };
}

function PrimaryColumn(options: { name?: string; type?: ColumnType } = {}) {
  return function (target: any, propertyKey: string) {
    const m = metaOf(target.constructor);
    m.columns.push({
      property: propertyKey,
      name: options.name ?? propertyKey,
      type: options.type ?? 'number',
      primary: true,
      generated: false,
      nullable: false,
    });
  };
}

function PrimaryGeneratedColumn(options: { name?: string; type?: ColumnType } = {}) {
  return function (target: any, propertyKey: string) {
    const m = metaOf(target.constructor);
    m.columns.push({
      property: propertyKey,
      name: options.name ?? propertyKey,
      type: options.type ?? 'number',
      primary: true,
      generated: true,
      nullable: false,
    });
  };
}

function ManyToOne(targetFactory: () => Function, options: { joinColumn?: string } = {}) {
  return function (target: any, propertyKey: string) {
    const m = metaOf(target.constructor);
    m.relations.push({
      property: propertyKey,
      type: 'many-to-one',
      target: targetFactory,
      foreignKey: options.joinColumn ?? propertyKey + 'Id',
    });
  };
}

function OneToMany(targetFactory: () => Function, options: { mappedBy?: string } = {}) {
  return function (target: any, propertyKey: string) {
    const m = metaOf(target.constructor);
    m.relations.push({
      property: propertyKey,
      type: 'one-to-many',
      target: targetFactory,
      mappedBy: options.mappedBy,
    });
  };
}

// ---------- In-memory engine ----------

interface FindResult {
  rows: any[];
  total: number;
}

interface FilterSpec {
  column: string;
  op: string;
  value: any;
}

class InMemoryEngine {
  private tables = new Map<string, any[]>();
  private seq = new Map<string, number>();

  register(meta: EntityMeta) {
    if (!this.tables.has(meta.tableName)) this.tables.set(meta.tableName, []);
  }

  private table(nameOrMeta: string | EntityMeta): any[] {
    const name = typeof nameOrMeta === 'string' ? nameOrMeta : nameOrMeta.tableName;
    if (!this.tables.has(name)) this.tables.set(name, []);
    return this.tables.get(name)!;
  }

  async find(meta: EntityMeta, opts: {
    where?: any;
    filters?: FilterSpec[];
    order?: Record<string, 'ASC' | 'DESC'>;
    skip?: number;
    take?: number;
  } = {}): Promise<FindResult> {
    let rows = [...this.table(meta)];

    // partial equality where (property keys)
    if (opts.where && typeof opts.where === 'object' && !Array.isArray(opts.where)) {
      const w = opts.where;
      rows = rows.filter((r) =>
        Object.keys(w).every((k) => {
          const col = meta.columns.find((c) => c.property === k);
          const colName = col?.name ?? k;
          return r[colName] === w[k];
        })
      );
    }

    // advanced filters (column names)
    if (opts.filters?.length) {
      rows = rows.filter((r) =>
        opts.filters!.every((f) => {
          const v = r[f.column];
          switch (f.op) {
            case '=':  return v === f.value;
            case '>':  return v >  f.value;
            case '<':  return v <  f.value;
            case '>=': return v >= f.value;
            case '<=': return v <= f.value;
            case '!=': return v !== f.value;
            case 'LIKE': {
              const needle = String(f.value).replace(/%/g, '');
              return String(v ?? '').toLowerCase().includes(needle.toLowerCase());
            }
            default: return true;
          }
        })
      );
    }

    // order (property keys)
    if (opts.order) {
      const entries = Object.entries(opts.order);
      rows.sort((a, b) => {
        for (const [k, dir] of entries) {
          const col = meta.columns.find((c) => c.property === k)?.name ?? k;
          const av = a[col];
          const bv = b[col];
          if (av < bv) return dir === 'ASC' ? -1 : 1;
          if (av > bv) return dir === 'ASC' ? 1 : -1;
        }
        return 0;
      });
    }

    const total = rows.length;
    if (opts.skip) rows = rows.slice(opts.skip);
    if (opts.take) rows = rows.slice(0, opts.take);
    return { rows, total };
  }

  async insert(meta: EntityMeta, row: any): Promise<any> {
    const rows = this.table(meta);
    const pk = meta.columns.find((c) => c.primary && c.generated);
    if (pk && row[pk.name] == null) {
      const next = (this.seq.get(meta.tableName) ?? 0) + 1;
      this.seq.set(meta.tableName, next);
      row[pk.name] = next;
    }
    rows.push(row);
    const pkAny = meta.columns.find((c) => c.primary)!;
    return row[pkAny.name];
  }

  async update(meta: EntityMeta, id: any, row: any) {
    const pk = meta.columns.find((c) => c.primary)!;
    const rows = this.table(meta);
    const idx = rows.findIndex((r) => r[pk.name] === id);
    if (idx >= 0) Object.assign(rows[idx], row);
  }

  async delete(meta: EntityMeta, id: any) {
    const pk = meta.columns.find((c) => c.primary)!;
    const rows = this.table(meta);
    const idx = rows.findIndex((r) => r[pk.name] === id);
    if (idx >= 0) rows.splice(idx, 1);
  }
}

// ---------- EntityManager ----------

class EntityManager {
  engine = new InMemoryEngine();
  private identity = new Map<string, any>();

  private key(meta: EntityMeta, id: any) {
    return `${meta.target.name}#${String(id)}`;
  }

  register(meta: EntityMeta) {
    this.engine.register(meta);
  }

  toEntity(meta: EntityMeta, row: any): any {
    const pk = meta.columns.find((c) => c.primary)!;
    const id = row[pk.name];

    let entity: any = null;
    if (id != null) entity = this.identity.get(this.key(meta, id)) ?? null;

    if (!entity) {
      entity = new meta.target();
      if (id != null) this.identity.set(this.key(meta, id), entity);
    }

    for (const col of meta.columns) {
      entity[col.property] = row[col.name];
    }
    for (const rel of meta.relations) {
      if (rel.type === 'many-to-one') {
        entity[rel.foreignKey!] = row[rel.foreignKey!];
      }
    }
    return entity;
  }

  async find(meta: EntityMeta, options: any = {}): Promise<any[]> {
    this.register(meta);
    const { rows } = await this.engine.find(meta, {
      where: options.where,
      filters: options.filters,
      order: options.order,
      skip: options.skip,
      take: options.take,
    });
    const entities = rows.map((r) => this.toEntity(meta, r));

    if (options.relations) {
      for (const ent of entities) {
        for (const relName of options.relations) {
          await this.loadRelation(meta, ent, relName);
        }
      }
    }
    return entities;
  }

  async findOne(meta: EntityMeta, options: any = {}): Promise<any> {
    const res = await this.find(meta, { ...options, take: 1 });
    return res[0] ?? null;
  }

  async loadRelation(ownerMeta: EntityMeta, entity: any, relName: string) {
    const rel = ownerMeta.relations.find((r) => r.property === relName);
    if (!rel) return;
    const targetMeta = metaOf(rel.target());
    this.register(targetMeta);

    if (rel.type === 'many-to-one') {
      const fk = rel.foreignKey!;
      const fkValue = entity[fk];
      const targetPk = targetMeta.columns.find((c) => c.primary)!;
      if (fkValue == null) {
        entity[rel.property] = null;
        return;
      }
      const { rows } = await this.engine.find(targetMeta, {
        filters: [{ column: targetPk.name, op: '=', value: fkValue }],
      });
      entity[rel.property] = rows.length ? this.toEntity(targetMeta, rows[0]) : null;
    } else if (rel.type === 'one-to-many') {
      const targetRel = targetMeta.relations.find((r) => r.property === rel.mappedBy);
      const fk = targetRel?.foreignKey ?? ownerMeta.tableName.replace(/s$/, '') + 'Id';
      const ownerPk = ownerMeta.columns.find((c) => c.primary)!;
      const { rows } = await this.engine.find(targetMeta, {
        filters: [{ column: fk, op: '=', value: entity[ownerPk.property] }],
      });
      entity[rel.property] = rows.map((r) => this.toEntity(targetMeta, r));
    }
  }

  async save(meta: EntityMeta, entity: any): Promise<any> {
    this.register(meta);
    const pk = meta.columns.find((c) => c.primary)!;

    // sync many-to-one foreign keys from relation objects
    for (const rel of meta.relations) {
      if (rel.type === 'many-to-one') {
        const relObj = entity[rel.property];
        if (relObj && typeof relObj === 'object') {
          const targetPk = metaOf(rel.target()).columns.find((c) => c.primary)!;
          entity[rel.foreignKey!] = relObj[targetPk.property];
        }
      }
    }

    const row: any = {};
    for (const col of meta.columns) row[col.name] = entity[col.property];
    for (const rel of meta.relations) {
      if (rel.type === 'many-to-one') row[rel.foreignKey!] = entity[rel.foreignKey!];
    }

    const id = entity[pk.property];
    if (id == null) {
      const newId = await this.engine.insert(meta, row);
      entity[pk.property] = newId;
      this.identity.set(this.key(meta, newId), entity);
    } else {
      await this.engine.update(meta, id, row);
    }
    return entity;
  }

  async remove(meta: EntityMeta, entity: any) {
    const pk = meta.columns.find((c) => c.primary)!;
    await this.engine.delete(meta, entity[pk.property]);
    this.identity.delete(this.key(meta, entity[pk.property]));
  }
}

// ---------- Repository ----------

class Repository<T = any> {
  constructor(public meta: EntityMeta, private manager: EntityManager) {}

  create(partial: Partial<T> = {}): T {
    const e = new this.meta.target() as any;
    Object.assign(e, partial);
    return e as T;
  }

  find(options?: any): Promise<T[]> {
    return this.manager.find(this.meta, options) as Promise<T[]>;
  }

  findOne(options?: any): Promise<T | null> {
    return this.manager.findOne(this.meta, options) as Promise<T | null>;
  }

  save(entity: T): Promise<T> {
    return this.manager.save(this.meta, entity) as Promise<T>;
  }

  remove(entity: T): Promise<void> {
    return this.manager.remove(this.meta, entity);
  }

  createQueryBuilder(alias: string): SelectQueryBuilder<T> {
    return new SelectQueryBuilder<T>(this.meta, this.manager, alias);
  }
}

// ---------- Query Builder ----------

class SelectQueryBuilder<T = any> {
  private filters: FilterSpec[] = [];
  private order: Record<string, 'ASC' | 'DESC'> = {};
  private skipN?: number;
  private takeN?: number;
  private relations: string[] = [];
  private params: Record<string, any> = {};

  constructor(
    private meta: EntityMeta,
    private manager: EntityManager,
    private alias: string
  ) {}

  where(condition: string, params?: Record<string, any>) {
    if (params) Object.assign(this.params, params);
    this.filters = [];
    this.parseCondition(condition);
    return this;
  }

  andWhere(condition: string, params?: Record<string, any>) {
    if (params) Object.assign(this.params, params);
    this.parseCondition(condition);
    return this;
  }

  private parseCondition(condition: string) {
    const m = condition.match(/^([\w.]+)\s*(=|>|<|>=|<=|!=|LIKE)\s*(.+)$/i);
    if (!m) throw new Error('Bad condition: ' + condition);
    let [, field, op, rawVal] = m;
    let col = field.split('.').pop()!;
    const metaCol = this.meta.columns.find((c) => c.property === col);
    if (metaCol) col = metaCol.name;

    let value: any = rawVal.trim();
    if (value.startsWith(':')) {
      value = this.params[value.slice(1)];
    } else {
      const num = Number(value);
      if (!isNaN(num) && value !== '') value = num;
      else value = value.replace(/^['"]|['"]$/g, '');
    }
    this.filters.push({ column: col, op: op.toUpperCase(), value });
  }

  orderBy(property: string, direction: 'ASC' | 'DESC' = 'ASC') {
    this.order[property] = direction;
    return this;
  }

  skip(n: number) { this.skipN = n; return this; }
  take(n: number) { this.takeN = n; return this; }
  leftJoinAndSelect(relation: string, _alias: string) {
    this.relations.push(relation);
    return this;
  }

  async getMany(): Promise<T[]> {
    const { rows } = await this.manager.engine.find(this.meta, {
      filters: this.filters,
      order: this.order,
      skip: this.skipN,
      take: this.takeN,
    });
    const entities = rows.map((r) => this.manager.toEntity(this.meta, r));
    for (const e of entities) {
      for (const r of this.relations) await this.manager.loadRelation(this.meta, e, r);
    }
    return entities as T[];
  }

  async getOne(): Promise<T | null> {
    this.takeN = 1;
    const res = await this.getMany();
    return res[0] ?? null;
  }

  async getCount(): Promise<number> {
    const { total } = await this.manager.engine.find(this.meta, { filters: this.filters });
    return total;
  }

  // Render a human-readable SQL-ish string (for logging/debugging)
  toSql(): string {
    const cols = this.meta.columns.map((c) => c.name).join(', ');
    let sql = `SELECT ${cols} FROM ${this.meta.tableName}`;
    if (this.filters.length) {
      const where = this.filters
        .map((f) => `${f.column} ${f.op} ${typeof f.value === 'string' ? `'${f.value}'` : f.value}`)
        .join(' AND ');
      sql += ` WHERE ${where}`;
    }
    if (Object.keys(this.order).length) {
      const o = Object.entries(this.order).map(([k, v]) => `${k} ${v}`).join(', ');
      sql += ` ORDER BY ${o}`;
    }
    if (this.takeN != null) sql += ` LIMIT ${this.takeN}`;
    if (this.skipN != null) sql += ` OFFSET ${this.skipN}`;
    return sql;
  }
}

// ---------- DataSource ----------

class DataSource {
  manager = new EntityManager();
  constructor(public entities: Function[]) {}

  async initialize() {
    for (const e of this.entities) {
      const m = metaOf(e);
      this.manager.register(m);
    }
  }

  getRepository<T = any>(target: Function): Repository<T> {
    return new Repository<T>(metaOf(target), this.manager);
  }
}

// ---------- Example entities ----------

@Entity('users')
class User {
  @PrimaryGeneratedColumn()
  id!: number;

  @Column()
  name!: string;

  @Column({ type: 'number', nullable: true })
  age?: number;

  @OneToMany(() => Post, { mappedBy: 'author' })
  posts?: Post[];
}

@Entity('posts')
class Post {
  @PrimaryGeneratedColumn()
  id!: number;

  @Column()
  title!: string;

  @ManyToOne(() => User, { joinColumn: 'authorId' })
  author?: User;

  @Column({ type: 'number' })
  authorId!: number;
}

// ---------- Demo ----------

async function main() {
  const ds = new DataSource([User, Post]);
  await ds.initialize();

  const userRepo = ds.getRepository<User>(User);
  const postRepo = ds.getRepository<Post>(Post);

  // Create users
  const alice = await userRepo.save(userRepo.create({ name: 'Alice', age: 30 }));
  const bob   = await userRepo.save(userRepo.create({ name: 'Bob', age: 25 }));

  // Create posts (via FK and via relation object)
  await postRepo.save(postRepo.create({ title: 'Hello ORM', authorId: alice.id }));
  await postRepo.save(postRepo.create({ title: 'Second post', author: alice }));

  console.log('\n--- All users ---');
  console.log(await userRepo.find());

  console.log('\n--- Posts with author (eager) ---');
  console.log(await postRepo.find({ relations: ['author'] }));

  console.log('\n--- QueryBuilder: adults ---');
  const qb = userRepo.createQueryBuilder('u')
    .where('u.age >= :age', { age: 18 })
    .orderBy('name', 'ASC');
  console.log('SQL:', qb.toSql());
  console.log(await qb.getMany());

  console.log('\n--- QueryBuilder: posts leftJoin author ---');
  const pqb = postRepo.createQueryBuilder('p')
    .leftJoinAndSelect('author', 'a')
    .orderBy('title', 'ASC');
  console.log('SQL:', pqb.toSql());
  console.log(await pqb.getMany());

  console.log('\n--- OneToMany: Alice posts ---');
  const aliceWithPosts = await userRepo.findOne({ where: { name: 'Alice' }, relations: ['posts'] });
  console.log(aliceWithPosts?.posts);

  console.log('\n--- Identity map check ---');
  const a1 = await userRepo.findOne({ where: { name: 'Alice' } });
  const a2 = await userRepo.findOne({ where: { name: 'Alice' } });
  console.log('Same instance?', a1 === a2);

  console.log('\n--- Update ---');
  alice.age = 31;
  await userRepo.save(alice);
  console.log(await userRepo.findOne({ where: { name: 'Alice' } }));

  console.log('\n--- Delete ---');
  const toDelete = await postRepo.findOne({ where: { title: 'Hello ORM' } });
  if (toDelete) await postRepo.remove(toDelete);
  console.log('Remaining post count:', await postRepo.createQueryBuilder('p').getCount());

  console.log('\n--- Count of users age >= 26 ---');
  console.log(await userRepo.createQueryBuilder('u').where('u.age >= :age', { age: 26 }).getCount());
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
```

### What this demonstrates

1. **Declarative entities** — classes become tables; properties become columns; relations declared explicitly.
2. **Metadata registry** — decorators populate a global `Map`, and `DataSource.initialize()` registers tables with the engine.
3. **Repository pattern** — `userRepository.find/save/remove` etc. isolate persistence logic from domain code.
4. **Identity map** — repeated `findOne` for the same PK returns the *same instance*, which is critical for consistent object graphs.
5. **Query builder** — composable, parameterized filters with `where/andWhere/orderBy/skip/take`, plus eager relation loading (`leftJoinAndSelect`).
6. **Relations** — `ManyToOne` (FK sync on save + eager load) and `OneToMany` (reverse filter by FK).
7. **Generated keys** — `@PrimaryGeneratedColumn` auto-increments.

### Swapping in a real database

The only DB-specific piece is `InMemoryEngine`. To use SQLite/Postgres/MySQL you implement the same interface:

```ts
interface Engine {
  register(meta: EntityMeta): void;
  find(meta: EntityMeta, opts: any): Promise<{ rows: any[]; total: number }>;
  insert(meta: EntityMeta, row: any): Promise<any>;
  update(meta: EntityMeta, id: any, row: any): Promise<void>;
  delete(meta: EntityMeta, id: any): Promise<void>;
}
```

and have it translate these calls into parameterized SQL (`SELECT ...`, `INSERT ... RETURNING id`, etc.). Everything above (metadata, repositories, query builder, identity map) stays identical. For production you’d also add: a connection pool, transactions (`BEGIN/COMMIT/ROLLBACK`), migrations, lazy loading, dirty checking/unit-of-work flush, caching, and schema validation — but the architecture shown here is the foundation all of them build on.

# ORM basics in TypeScript

An **ORM (Object-Relational Mapper)** lets you work with database rows as typed objects instead of writing raw SQL. You define classes (entities) whose properties map to table columns; the ORM translates method calls into SQL and hydrates results back into objects.

## Core idea

| DB concept | TS/ORM concept |
|---|---|
| Table | Entity class |
| Row | Instance of entity |
| Column | Class property |
| Foreign key | Decorated relation property |
| Query | Repository method / query builder |

Benefits: type safety, auto-migrations, readable CRUD, relation traversal, and easier testing (swap DB or mock repository).

## Syntax example (TypeORM)

TypeORM is decorator-driven and very common in NestJS/Express apps.

```ts
// entity.ts
import { Entity, PrimaryGeneratedColumn, Column, CreateDateColumn } from "typeorm";

@Entity("users")
export class User {
  @PrimaryGeneratedColumn()
  id!: number;

  @Column({ unique: true, length: 255 })
  email!: string;

  @Column()
  name!: string;

  @Column({ default: true })
  isActive!: boolean;

  @CreateDateColumn()
  createdAt!: Date;
}
```

```ts
// data-source.ts
import { DataSource } from "typeorm";
import { User } from "./entity";

export const AppDataSource = new DataSource({
  type: "postgres",
  host: process.env.DB_HOST,
  port: 5432,
  username: process.env.DB_USER,
  password: process.env.DB_PASS,
  database: process.env.DB_NAME,
  entities: [User],
  synchronize: false,   // use migrations in production
  logging: process.env.NODE_ENV === "development",
});

await AppDataSource.initialize();
```

### Basic CRUD

```ts
const repo = AppDataSource.getRepository(User);

// Create
const user = repo.create({ email: "ada@example.com", name: "Ada" });
await repo.save(user);            // INSERT

// Read
const found = await repo.findOneBy({ email: "ada@example.com" });
const all = await repo.find({ where: { isActive: true }, take: 20 });

// Update
await repo.update(found!.id, { name: "Ada Lovelace" });

// Delete
await repo.delete(found!.id);
```

### Relations

```ts
import { ManyToOne, OneToMany } from "typeorm";

@Entity()
export class Post {
  @PrimaryGeneratedColumn()
  id!: number;

  @Column()
  title!: string;

  @ManyToOne(() => User, (u) => u.posts, { onDelete: "CASCADE" })
  author!: User;
}

// add to User:
@OneToMany(() => Post, (p) => p.author)
posts!: Post[];
```

Loading relations:

```ts
const userWithPosts = await repo.findOne({
  where: { id: 1 },
  relations: { posts: true },
});
```

### Transactions

```ts
await AppDataSource.transaction(async (manager) => {
  const u = manager.create(User, { email: "x@y.com", name: "X" });
  await manager.save(u);
  await manager.save(Post, { title: "Hello", author: u });
});
```

### Complex queries (QueryBuilder)

```ts
const result = await repo
  .createQueryBuilder("u")
  .leftJoinAndSelect("u.posts", "p")
  .where("u.isActive = :active", { active: true })
  .andWhere("p.title ILIKE :q", { q: "%orm%" })
  .orderBy("u.createdAt", "DESC")
  .getMany();
```

## Typical use cases

- **CRUD APIs** — repositories keep controllers thin.
- **Domain modeling** — entities encode invariants (validation via class-validator).
- **Multi-tenant / scoped data** — query builders add `tenantId` filters centrally.
- **Migrations** — versioned schema changes instead of `synchronize: true`.
- **Integration tests** — use an in-memory SQLite DB with the same entities.

## Alternative: Prisma (schema-first)

Many TS teams prefer Prisma for stronger inference and safer migrations:

```prisma
// schema.prisma
model User {
  id        Int      @id @default(autoincrement())
  email     String   @unique
  name      String
  posts     Post[]
  createdAt DateTime @default(now())
}

model Post {
  id       Int    @id @default(autoincrement())
  title    String
  author   User   @relation(fields: [authorId], references: [id])
  authorId Int
}
```

```ts
const user = await prisma.user.create({
  data: { email: "ada@example.com", name: "Ada", posts: { create: { title: "ORM" } } },
  include: { posts: true },
});
```

Prisma generates a typed client from the schema; you don’t write entity classes.

## Best practices

- Turn `synchronize` off in production; use migrations (`typeorm migration:generate`).
- Avoid N+1 by using `relations`/`include` or joins.
- Keep entities focused on persistence; put business logic in services.
- Index columns you filter/sort on (`@Index()`).
- Use transactions for multi-write operations.
- Don’t leak ORM entities directly from HTTP handlers—map to DTOs.

If you want, tell me your stack (NestJS/Express, Postgres/MySQL, etc.) and I can tailor a minimal runnable setup.

A common ORM mistake is the **N+1 query problem**: fetching a list of entities, then querying related data inside a loop.

### Mistake

```ts
import { UserRepository } from "./user.repository";
import { PostRepository } from "./post.repository";

async function getUsersWithPosts() {
  const users = await userRepository.find();

  // One extra query per user
  for (const user of users) {
    user.posts = await postRepository.find({
      where: { userId: user.id },
    });
  }

  return users;
}
```

### Corrected version

```ts
import { UserRepository } from "./user.repository";

async function getUsersWithPosts() {
  // Fetch users and their posts in one query using eager loading
  const users = await userRepository.find({
    relations: ["posts"],
  });

  return users;
}
```

### What was wrong and why

- **N+1 queries:** The loop executes one query per user to load posts. If there are 100 users, this becomes 101 database round trips.
- **Performance and latency:** Each query adds network and database overhead. The cost grows linearly with the number of users.
- **Inconsistent timing:** Results can be slower and less predictable under load.

The corrected version uses the ORM’s relation loading feature, so the database can fetch users and related posts with a join or optimized relation query, usually in far fewer round trips. If you need filtering on related data, prefer a query builder with explicit joins instead of looping.

# Common ORM Pitfalls in TypeScript

Below are the most common pitfalls, grouped roughly from “day‑one bugs” to “production incidents.” Examples use TypeORM-style entities because they make the TypeScript-specific issues (decorators, types, nullability) explicit, but the same ideas apply to Prisma, Sequelize, MikroORM, etc.

---

## 1. The N+1 query problem

```ts
// ❌ Bad: 1 query for users + N queries for posts
const users = await userRepo.find();
for (const u of users) {
  u.posts = await postRepo.find({ where: { authorId: u.id } });
}

// ✅ Good: one query with a join
const users = await userRepo.find({ relations: ["posts"] });

// ✅ Also good for large graphs: query builder with pagination
const users = await userRepo
  .createQueryBuilder("u")
  .leftJoinAndSelect("u.posts", "p")
  .take(50)
  .getMany();
```

**Why it hurts:** Looks fine locally with 5 rows; explodes in production.

---

## 2. Floating promises (missing `await`)

```ts
// ❌ Bad: save is not awaited; errors are swallowed
function createUser(dto: CreateUserDto) {
  userRepo.save(dto);          // floating promise
  return { ok: true };
}

// ✅ Good
async function createUser(dto: CreateUserDto) {
  await userRepo.save(dto);
  return { ok: true };
}
```

**Tip:** Enable `no-floating-promises` in ESLint (`@typescript-eslint/no-floating-promises`).

---

## 3. Over-fetching columns

```ts
// ❌ Bad: pulls every column, including large text/blobs
const users = await userRepo.find();

// ✅ Good: project only what you need
const users = await userRepo.find({
  select: ["id", "email", "createdAt"],
});
```

This also reduces accidental leakage of sensitive fields.

---

## 4. Type coercion mismatches (Decimal, BigInt, Date)

```ts
// ❌ Bad: DB returns decimal as string in many drivers
@Entity()
class Account {
  @Column({ type: "decimal", precision: 18, scale: 2 })
  balance: number; // actually string at runtime → NaN bugs
}

// ✅ Good: transformer or string type
@Entity()
class Account {
  @Column({
    type: "decimal",
    precision: 18,
    scale: 2,
    transformer: {
      to: (v: number) => v,
      from: (v: string) => parseFloat(v),
    },
  })
  balance: number;
}

// ❌ Bad: bigint column typed as number (precision loss)
@Column({ type: "bigint" })
legacyId: number;

// ✅ Good
@Column({ type: "bigint" })
legacyId: bigint; // or string if your driver prefers
```

**Date pitfall:** store/compare in UTC; `timestamptz` + `Date` is safest. Avoid mixing `timestamp` (no tz) with JS `Date`.

---

## 5. `null` vs `undefined` confusion

```ts
// ❌ Ambiguous: is "not provided" the same as "set to null"?
@Entity()
class Profile {
  @Column({ nullable: true })
  nickname?: string;
}

// ✅ Be explicit about intent
@Entity()
class Profile {
  @Column({ type: "varchar", nullable: true })
  nickname: string | null; // DB-level nullability is explicit
}
```

In TypeORM, `undefined` often means “don’t touch this column,” while `null` means “set to NULL.” Mixing them causes surprising UPDATEs.

---

## 6. Mutating an entity and forgetting to persist

```ts
// ❌ Bad: change is lost
const user = await userRepo.findOneBy({ id });
user.name = "Ada";
// forgot save/update

// ✅ Good
await userRepo.save(user);

// ✅ Or atomic update (no read needed)
await userRepo.update({ id }, { name: "Ada" });
```

---

## 7. Missing transactions for multi-write operations

```ts
// ❌ Bad: partial failure leaves inconsistent state
await orderRepo.save(order);
await inventoryRepo.decrement({ sku }, "stock", 1);

// ✅ Good
await dataSource.transaction(async (manager) => {
  await manager.save(order);
  await manager.decrement(Inventory, { sku }, "stock", 1);
});
```

---

## 8. Lost updates / race conditions

```ts
// ❌ Bad: read-modify-write race
const product = await repo.findOneBy({ id });
product.stock -= 1;
await repo.save(product); // two requests can both read 10 → both write 9

// ✅ Good: atomic decrement
await repo
  .createQueryBuilder()
  .update(Product)
  .set({ stock: () => "stock - 1" })
  .where("id = :id AND stock > 0", { id })
  .execute();

// ✅ Or optimistic locking
@Entity()
class Product {
  @VersionColumn()
  version: number;
}
```

---

## 9. Cartesian explosion from eager loading

```ts
// ❌ Bad: posts × comments × tags → huge duplicated result set
const users = await userRepo.find({
  relations: ["posts", "posts.comments", "posts.tags"],
});

// ✅ Good: load in stages or use query builder with distinct
const users = await userRepo
  .createQueryBuilder("u")
  .leftJoinAndSelect("u.posts", "p")
  .getMany();

const posts = await postRepo.find({
  where: { authorId: In(userIds) },
  relations: ["comments", "tags"],
});
```

---

## 10. Leaking / circular serialization

```ts
// ❌ Bad: returning ORM entities directly
app.get("/users", async (req, res) => {
  res.json(await userRepo.find()); // circular refs, passwordHash, etc.
});

// ✅ Good: DTO + class-transformer exclusions
@Entity()
class User {
  @Column({ select: false })
  passwordHash: string;

  @Exclude()
  @Column()
  internalNote: string;
}

// in controller
const users = await userRepo.find();
res.json(instanceToPlain(users)); // or map to DTO explicitly
```

---

## 11. `synchronize: true` in production

```ts
// ❌ Dangerous: auto-DDL on startup
new DataSource({
  type: "postgres",
  synchronize: true, // can drop columns/data
});

// ✅ Good: migrations only
new DataSource({
  type: "postgres",
  synchronize: false,
  migrations: ["dist/migrations/*.js"],
});
```

---

## 12. Forgetting soft-deleted rows

```ts
@Entity()
class Post {
  @DeleteDateColumn()
  deletedAt: Date | null;
}

// ❌ Bad assumption: "find() never returns deleted" — true for find(),
// but raw queries / reports bypass it
const all = await dataSource.query("SELECT * FROM post");

// ✅ Good: be explicit
const includingDeleted = await postRepo.find({ withDeleted: true });
const onlyDeleted = await postRepo.find({ onlyDeleted: true } as any);
```

Also remember joins: a soft-deleted parent may still appear via raw SQL.

---

## 13. SQL injection via string interpolation in query builders

```ts
// ❌ Bad
const name = req.query.name as string;
const users = await repo
  .createQueryBuilder("u")
  .where(`u.name = '${name}'`) // injection
  .getMany();

// ✅ Good: parameterized
const users = await repo
  .createQueryBuilder("u")
  .where("u.name = :name", { name })
  .getMany();
```

---

## 14. Connection / resource leaks

```ts
// ❌ Bad: acquiring a connection and not releasing
const conn = await dataSource.getConnection();
const rows = await conn.query("SELECT 1");
// forgot conn.release()

// ✅ Good: use repository/manager (uses pool automatically)
const rows = await dataSource.getRepository(User).find();

// If you must use a connection:
const conn = await dataSource.getConnection();
try {
  await conn.query("SELECT 1");
} finally {
  await conn.release();
}
```

---

## 15. Async work inside loops (performance)

```ts
// ❌ Bad: sequential awaits
for (const id of ids) {
  await userRepo.delete(id);
}

// ✅ Good: bulk operation
await userRepo.delete(ids);

// ✅ Or bounded concurrency for non-bulk work
await Promise.all(ids.map((id) => userRepo.delete(id)));
```

---

## 16. Prisma-specific: forgetting `await` on `$transaction` / nested writes

```ts
// ❌ Bad (Prisma): not awaited; also partial failure risk
prisma.$transaction([
  prisma.user.create({ data: { email } }),
  prisma.profile.create({ data: { userId } }), // userId not known yet in array form
]);

// ✅ Good: interactive transaction
await prisma.$transaction(async (tx) => {
  const user = await tx.user.create({ data: { email } });
  await tx.profile.create({ data: { userId: user.id } });
});
```

---

## Quick checklist

- [ ] No floating promises (lint rule on).
- [ ] Relations loaded intentionally; check query count in dev.
- [ ] Columns typed to match DB (`decimal`/`bigint`/`timestamptz`).
- [ ] `null` vs `undefined` decided per column.
- [ ] Multi-write paths wrapped in transactions.
- [ ] Mutating paths are atomic or use optimistic locking.
- [ ] No `synchronize: true` outside dev.
- [ ] Entities never serialized directly; use DTOs.
- [ ] All raw/interpolated SQL is parameterized.
- [ ] Connections released; pool sized for load.

If you tell me which ORM you’re using (TypeORM, Prisma, Sequelize, Drizzle, MikroORM), I can give a shorter “pitfalls specific to that stack” list with migration/testing tips.

## Exercise

Build a tiny in-memory blog API using **TypeORM + SQLite** in TypeScript.

**Requirements**

1. Define three entities: `User`, `Post`, `Comment`.
2. Relationships:
   - A `User` has many `Post`s.
   - A `Post` belongs to one `User`.
   - A `Post` has many `Comment`s.
   - A `Comment` belongs to one `Post` and optionally to one `User`.
3. Create a data source using an in-memory SQLite database with schema sync enabled.
4. Seed two users, two posts, and two comments.
5. Implement these operations:
   - List all posts with their author and comments.
   - Count posts per user.
   - Create a new post for an existing user.
   - Update a post title.
   - Delete a comment.
   - Create a post and its first comment in one transaction.

---

## Step-by-step solution

### 1. Install dependencies

```bash
npm init -y
npm install typeorm reflect-metadata sqlite3
npm install -D typescript ts-node @types/node
npx tsc --init
```

Update `tsconfig.json`:

```json
{
  "compilerOptions": {
    "target": "ES2020",
    "module": "commonjs",
    "outDir": "./dist",
    "rootDir": "./src",
    "strict": true,
    "esModuleInterop": true,
    "experimentalDecorators": true,
    "emitDecoratorMetadata": true
  }
}
```

### 2. Create the entities

`src/entities/User.ts`

```ts
import { Entity, PrimaryGeneratedColumn, Column, OneToMany } from "typeorm";
import { Post } from "./Post";
import { Comment } from "./Comment";

@Entity()
export class User {
  @PrimaryGeneratedColumn()
  id!: number;

  @Column({ unique: true })
  email!: string;

  @Column()
  name!: string;

  @OneToMany(() => Post, (post) => post.author)
  posts: Post[] = [];

  @OneToMany(() => Comment, (comment) => comment.author)
  comments: Comment[] = [];
}
```

`src/entities/Post.ts`

```ts
import { Entity, PrimaryGeneratedColumn, Column, ManyToOne, OneToMany, JoinColumn } from "typeorm";
import { User } from "./User";
import { Comment } from "./Comment";

@Entity()
export class Post {
  @PrimaryGeneratedColumn()
  id!: number;

  @Column()
  title!: string;

  @Column("text")
  content!: string;

  @ManyToOne(() => User, (user) => user.posts, { onDelete: "CASCADE" })
  @JoinColumn({ name: "authorId" })
  author!: User;

  @Column()
  authorId!: number;

  @OneToMany(() => Comment, (comment) => comment.post, { cascade: true })
  comments: Comment[] = [];
}
```

`src/entities/Comment.ts`

```ts
import { Entity, PrimaryGeneratedColumn, Column, ManyToOne, JoinColumn } from "typeorm";
import { Post } from "./Post";
import { User } from "./User";

@Entity()
export class Comment {
  @PrimaryGeneratedColumn()
  id!: number;

  @Column("text")
  text!: string;

  @ManyToOne(() => Post, (post) => post.comments, { onDelete: "CASCADE" })
  @JoinColumn({ name: "postId" })
  post!: Post;

  @Column()
  postId!: number;

  @ManyToOne(() => User, (user) => user.comments, { nullable: true, onDelete: "SET NULL" })
  @JoinColumn({ name: "authorId" })
  author?: User;

  @Column({ nullable: true })
  authorId?: number;
}
```

### 3. Create the data source

`src/data-source.ts`

```ts
import "reflect-metadata";
import { DataSource } from "typeorm";
import { User } from "./entities/User";
import { Post } from "./entities/Post";
import { Comment } from "./entities/Comment";

export const AppDataSource = new DataSource({
  type: "sqlite",
  database: ":memory:",
  synchronize: true,
  logging: false,
  entities: [User, Post, Comment],
});
```

### 4. Seed data and implement operations

`src/index.ts`

```ts
import "reflect-metadata";
import { AppDataSource } from "./data-source";
import { User } from "./entities/User";
import { Post } from "./entities/Post";
import { Comment } from "./entities/Comment";

async function main() {
  await AppDataSource.initialize();

  const userRepo = AppDataSource.getRepository(User);
  const postRepo = AppDataSource.getRepository(Post);
  const commentRepo = AppDataSource.getRepository(Comment);

  // ---------- Seed ----------
  const alice = userRepo.create({ name: "Alice", email: "alice@example.com" });
  const bob = userRepo.create({ name: "Bob", email: "bob@example.com" });
  await userRepo.save([alice, bob]);

  const welcomePost = postRepo.create({
    title: "Welcome",
    content: "Hello ORM world",
    author: alice,
    authorId: alice.id,
  });

  const secondPost = postRepo.create({
    title: "TypeScript Tips",
    content: "Use strict mode",
    author: bob,
    authorId: bob.id,
  });

  await postRepo.save([welcomePost, secondPost]);

  await commentRepo.save([
    commentRepo.create({
      text: "Great post!",
      post: welcomePost,
      postId: welcomePost.id,
      author: bob,
      authorId: bob.id,
    }),
    commentRepo.create({
      text: "Thanks!",
      post: welcomePost,
      postId: welcomePost.id,
      author: alice,
      authorId: alice.id,
    }),
  ]);

  // ---------- Read posts with author and comments ----------
  const posts = await postRepo.find({
    relations: ["author", "comments", "comments.author"],
    order: { id: "ASC" },
  });

  console.log("\nPosts:");
  for (const post of posts) {
    console.log(`- ${post.title} by ${post.author.name}`);
    for (const comment of post.comments) {
      console.log(`   * ${comment.text} (${comment.author?.name ?? "anonymous"})`);
    }
  }

  // ---------- Count posts per user ----------
  const postCounts = await userRepo
    .createQueryBuilder("user")
    .leftJoin("user.posts", "post")
    .select("user.id", "id")
    .addSelect("user.name", "name")
    .addSelect("COUNT(post.id)", "postCount")
    .groupBy("user.id")
    .orderBy("user.id", "ASC")
    .getRawMany();

  console.log("\nPost counts:");
  console.log(postCounts);

  // ---------- Create a post for an existing user ----------
  const aliceReloaded = await userRepo.findOneByOrFail({ id: alice.id });
  const newPost = postRepo.create({
    title: "Alice's Second Post",
    content: "ORM relations are useful",
    author: aliceReloaded,
    authorId: aliceReloaded.id,
  });
  await postRepo.save(newPost);
  console.log(`\nCreated post: ${newPost.title} (id=${newPost.id})`);

  // ---------- Update a post title ----------
  await postRepo.update(newPost.id, { title: "Alice's Updated Post" });
  const updatedPost = await postRepo.findOneByOrFail({ id: newPost.id });
  console.log(`Updated title: ${updatedPost.title}`);

  // ---------- Delete a comment ----------
  const commentToDelete = await commentRepo.findOneByOrFail({ text: "Thanks!" });
  await commentRepo.delete(commentToDelete.id);
  console.log(`Deleted comment id=${commentToDelete.id}`);

  // ---------- Transaction: post + first comment ----------
  await AppDataSource.transaction(async (manager) => {
    const txUser = await manager.findOneByOrFail(User, { id: bob.id });

    const txPost = manager.create(Post, {
      title: "Bob's Transactional Post",
      content: "Created inside a transaction",
      author: txUser,
      authorId: txUser.id,
    });
    await manager.save(txPost);

    const txComment = manager.create(Comment, {
      text: "First comment created atomically",
      post: txPost,
      postId: txPost.id,
      author: txUser,
      authorId: txUser.id,
    });
    await manager.save(txComment);
  });

  console.log("\nTransactional post and comment created successfully.");

  await AppDataSource.destroy();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
```

### 5. Run it

```bash
npx ts-node src/index.ts
```

Expected output shape:

```text
Posts:
- Welcome by Alice
   * Great post! (Bob)
   * Thanks! (Alice)
- TypeScript Tips by Bob

Post counts:
[ { id: 1, name: 'Alice', postCount: '1' }, { id: 2, name: 'Bob', postCount: '1' } ]

Created post: Alice's Second Post (id=3)
Updated title: Alice's Updated Post
Deleted comment id=2

Transactional post and comment created successfully.
```

