```ts
import { z } from "zod";

export const TodoSchema = z.object({
  id: z.string().uuid(),
  title: z.string().min(1).max(200),
  completed: z.boolean(),
  createdAt: z.string().datetime(),
});

export const CreateTodoSchema = z.object({
  title: z.string().min(1).max(200),
});

export const UpdateTodoSchema = z.object({
  title: z.string().min(1).max(200).optional(),
  completed: z.boolean().optional(),
}).refine((v) => Object.keys(v).length > 0, {
  message: "At least one field must be provided",
});

export type Todo = z.infer<typeof TodoSchema>;
export type CreateTodoInput = z.infer<typeof CreateTodoSchema>;
export type UpdateTodoInput = z.infer<typeof UpdateTodoSchema>;

// Shared API error shape
export const ApiErrorSchema = z.object({
  error: z.string(),
  details: z.unknown().optional(),
});
export type ApiError = z.infer<typeof ApiErrorSchema>;
```

## 4) Server — `src/server/index.ts`

```ts
import express, { Request, Response, NextFunction } from "express";
import { randomUUID } from "node:crypto";
import {
  TodoSchema,
  CreateTodoSchema,
  UpdateTodoSchema,
  type Todo,
  type ApiError,
} from "../shared/schemas.js";

const app = express();
app.use(express.json());

// ---- In-memory store ----
const todos = new Map<string, Todo>();

// ---- Helpers ----
function sendError(res: Response, status: number, error: string, details?: unknown) {
  const body: ApiError = { error, ...(details !== undefined ? { details } : {}) };
  res.status(status).json(body);
}

// ---- Routes ----

// List
app.get("/todos", (_req: Request, res: Response) => {
  res.json(Array.from(todos.values()));
});

// Get one
app.get("/todos/:id", (req: Request, res: Response) => {
  const todo = todos.get(req.params.id);
  if (!todo) return sendError(res, 404, "Todo not found");
  res.json(todo);
});

// Create
app.post("/todos", (req: Request, res: Response) => {
  const parsed = CreateTodoSchema.safeParse(req.body);
  if (!parsed.success) {
    return sendError(res, 400, "Validation failed", parsed.error.flatten());
  }
  const todo: Todo = {
    id: randomUUID(),
    title: parsed.data.title,
    completed: false,
    createdAt: new Date().toISOString(),
  };
  // Double-check the produced object conforms to the shared schema
  const validated = TodoSchema.parse(todo);
  todos.set(validated.id, validated);
  res.status(201).location(`/todos/${validated.id}`).json(validated);
});

// Update (partial)
app.patch("/todos/:id", (req: Request, res: Response) => {
  const existing = todos.get(req.params.id);
  if (!existing) return sendError(res, 404, "Todo not found");

  const parsed = UpdateTodoSchema.safeParse(req.body);
  if (!parsed.success) {
    return sendError(res, 400, "Validation failed", parsed.error.flatten());
  }

  const updated: Todo = {
    ...existing,
    ...parsed.data,
  };
  const validated = TodoSchema.parse(updated);
  todos.set(validated.id, validated);
  res.json(validated);
});

// Delete
app.delete("/todos/:id", (req: Request, res: Response) => {
  const existed = todos.delete(req.params.id);
  if (!existed) return sendError(res, 404, "Todo not found");
  res.status(204).send();
});

// ---- Error handler ----
app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
  console.error(err);
  sendError(res, 500, "Internal server error");
});

const PORT = process.env.PORT ?? 3000;
app.listen(PORT, () => {
  console.log(`Todo API listening on http://localhost:${PORT}`);
});
```

## 5) Typed client — `src/client/client.ts`

```ts
import {
  TodoSchema,
  CreateTodoSchema,
  UpdateTodoSchema,
  type Todo,
  type CreateTodoInput,
  type UpdateTodoInput,
  type ApiError,
} from "../shared/schemas.js";

export class ApiError extends Error {
  constructor(
    public status: number,
    public body: ApiError | null,
    message?: string,
  ) {
    super(message ?? `HTTP ${status}`);
    this.name = "ApiError";
  }
}

export interface ClientOptions {
  baseUrl: string;
  fetchImpl?: typeof fetch;
  headers?: Record<string, string>;
}

export class TodoClient {
  private readonly baseUrl: string;
  private readonly fetchImpl: typeof fetch;
  private readonly headers: Record<string, string>;

  constructor(opts: ClientOptions) {
    this.baseUrl = opts.baseUrl.replace(/\/$/, "");
    this.fetchImpl = opts.fetchImpl ?? fetch;
    this.headers = opts.headers ?? {};
  }

  private async request<T>(
    method: string,
    path: string,
    body?: unknown,
    parser?: (raw: unknown) => T,
  ): Promise<T> {
    const res = await this.fetchImpl(`${this.baseUrl}${path}`, {
      method,
      headers: {
        "content-type": "application/json",
        accept: "application/json",
        ...this.headers,
      },
      body: body !== undefined ? JSON.stringify(body) : undefined,
    });

    // No content
    if (res.status === 204) {
      return undefined as T;
    }

    let raw: unknown = null;
    const text = await res.text();
    if (text) {
      try {
        raw = JSON.parse(text);
      } catch {
        raw = text;
      }
    }

    if (!res.ok) {
      let apiErr: ApiError | null = null;
      const parsed = (raw && typeof raw === "object")
        ? (raw as any)
        : null;
      apiErr = parsed;
      throw new ApiError(res.status, apiErr, `${method} ${path} failed: ${res.status}`);
    }

    return parser ? parser(raw) : (raw as T);
  }

  async list(): Promise<Todo[]> {
    return this.request("GET", "/todos", undefined, (raw) => {
      const arr = zArray(TodoSchema).parse(raw);
      return arr;
    });
  }

  async get(id: string): Promise<Todo> {
    return this.request("GET", `/todos/${encodeURIComponent(id)}`, undefined, (raw) =>
      TodoSchema.parse(raw),
    );
  }

  async create(input: CreateTodoInput): Promise<Todo> {
    const validated = CreateTodoSchema.parse(input);
    return this.request("POST", "/todos", validated, (raw) => TodoSchema.parse(raw));
  }

  async update(id: string, input: UpdateTodoInput): Promise<Todo> {
    const validated = UpdateTodoSchema.parse(input);
    return this.request("PATCH", `/todos/${encodeURIComponent(id)}`, validated, (raw) =>
      TodoSchema.parse(raw),
    );
  }

  async delete(id: string): Promise<void> {
    await this.request("DELETE", `/todos/${encodeURIComponent(id)}`);
  }
}

// tiny helper to avoid importing zod array type inline awkwardness
import { z } from "zod";
function zArray<T extends z.ZodTypeAny>(schema: T) {
  return z.array(schema);
}
```

> Note: the `z` import is placed at the bottom of the file only to keep the example self-contained; in real code move it to the top.

