## 2. Core REST server

```ts
// server.ts
import { createServer, IncomingMessage, ServerResponse } from 'node:http';

import { HttpError } from './types';

export type Middleware = (
  ctx: RequestContext,
  next: () => Promise<void>
) => Promise<void>;

export interface RequestContext {
  req: IncomingMessage;
  res: ServerResponse;
  params: Record<string, string>;
  query: URLSearchParams;
  body: unknown;
  json: <T>(status: number, data: T) => void;
}

type RouteHandler = (ctx: RequestContext) => Promise<void> | void;

interface Route {
  method: HttpMethod;
  pattern: RegExp;
  paramNames: string[];
  handler: RouteHandler;
}

export class RestServer {
  private readonly routes: Route[] = [];
  private readonly middlewares: Middleware[] = [];

  /** Register global middleware, e.g. logging, auth, body parsing. */
  use(middleware: Middleware): this {
    this.middlewares.push(middleware);
    return this;
  }

  get(path: string, handler: RouteHandler): this {
    return this.addRoute('GET', path, handler);
  }

  post(path: string, handler: RouteHandler): this {
    return this.addRoute('POST', path, handler);
  }

  put(path: string, handler: RouteHandler): this {
    return this.addRoute('PUT', path, handler);
  }

  patch(path: string, handler: RouteHandler): this {
    return this.addRoute('PATCH', path, handler);
  }

  delete(path: string, handler: RouteHandler): this {
    return this.addRoute('DELETE', path, handler);
  }

  listen(port: number, host = '0.0.0.0'): Promise<void> {
    return new Promise((resolve) => {
      const server = createServer((req, res) => {
        void this.handle(req, res);
      });

      server.listen(port, host, () => {
        console.log(`REST server listening on http://${host}:${port}`);
        resolve();
      });
    });
  }

  private addRoute(method: HttpMethod, path: string, handler: RouteHandler): this {
    // Convert "/users/:id" into a RegExp and capture param names.
    const paramNames: string[] = [];

    const regexPath = path.replace(/:([A-Za-z_][A-Za-z0-9_]*)/g, (_, name: string) => {
      paramNames.push(name);
      return '([^/]+)';
    });

    this.routes.push({
      method,
      pattern: new RegExp(`^${regexPath}$`),
      paramNames,
      handler,
    });

    return this;
  }

  private async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const url = new URL(req.url ?? '/', `http://${req.headers.host ?? 'localhost'}`);

    const ctx: RequestContext = {
      req,
      res,
      params: {},
      query: url.searchParams,
      body: undefined,
      json: (status, data) => {
        if (!res.writableEnded) {
          res.writeHead(status, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify(data));
        }
      },
    };

    try {
      // 1. Find matching route.
      const route = this.routes.find(
        (r) => r.method === req.method && r.pattern.test(url.pathname)
      );

      if (!route) {
        ctx.json(404, { error: 'Not Found' });
        return;
      }

      // 2. Extract route params, e.g. /users/:id
      const match = url.pathname.match(route.pattern)!;
      route.paramNames.forEach((name, index) => {
        ctx.params[name] = decodeURIComponent(match[index + 1]);
      });

      // 3. Build middleware pipeline ending in the route handler.
      const pipeline = [
        ...this.middlewares,
        async (context: RequestContext, next: () => Promise<void>) => {
          await route.handler(context);
          await next();
        },
      ];

      let index = 0;
      const next = async (): Promise<void> => {
        if (index < pipeline.length) {
          const middleware = pipeline[index++];
          await middleware(ctx, next);
        }
      };

      await next();
    } catch (error) {
      const status = error instanceof HttpError ? error.status : 500;
      const message =
        error instanceof HttpError ? error.message : 'Internal Server Error';

      ctx.json(status, {
        error: message,
        details: error instanceof HttpError ? error.details : undefined,
      });
    }
  }
}

/** Useful reusable middleware. */
export const jsonBodyParser: Middleware = async (ctx, next) => {
  const method = ctx.req.method ?? 'GET';

  // GET/DELETE usually have no body; still allow empty body.
  if (method === 'GET' || method === 'DELETE') {
    await next();
    return;
  }

  const chunks: Buffer[] = [];
  for await (const chunk of ctx.req) {
    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
  }

  const raw = Buffer.concat(chunks).toString('utf8').trim();

  if (raw.length === 0) {
    ctx.body = undefined;
    await next();
    return;
  }

  try {
    ctx.body = JSON.parse(raw);
  } catch {
    throw new HttpError(400, 'Request body must be valid JSON');
  }

  await next();
};

export const requestLogger: Middleware = async (ctx, next) => {
  const start = Date.now();
  await next();
  const duration = Date.now() - start;
  console.log(`${ctx.req.method} ${ctx.req.url} -> ${ctx.res.statusCode} (${duration}ms)`);
};
```

