## 4. Domain-specific API layer on top of the generic client

```ts
// user-api.ts
import { ApiClient } from './client';
import { User, CreateUserInput, UpdateUserInput } from './types';

export class UserApi {
  constructor(private readonly client: ApiClient) {}

  list(): Promise<User[]> {
    return this.client.get<User[]>('/users');
  }

  get(id: string): Promise<User> {
    return this.client.get<User>(`/users/${encodeURIComponent(id)}`);
  }

  create(input: CreateUserInput): Promise<User> {
    return this.client.post<User>('/users', input);
  }

  update(id: string, input: UpdateUserInput): Promise<User> {
    return this.client.patch<User>(`/users/${encodeURIComponent(id)}`, input);
  }

  remove(id: string): Promise<void> {
    return this.client.delete<void>(`/users/${encodeURIComponent(id)}`);
  }
}
