## 5. Full working example: server + client

```ts
// main.ts
import { RestServer, jsonBodyParser, requestLogger } from './server';
import { User, CreateUserInput, UpdateUserInput, HttpError } from './types';
import { ApiClient } from './client';
import { UserApi } from './user-api';
import { randomUUID } from 'node:crypto';

const app = new RestServer();

// Middleware runs in registration order.
app.use(requestLogger);
app.use(jsonBodyParser);

// In-memory store for demo purposes only.
const users = new Map<string, User>();

function validateCreateUser(input: unknown): CreateUserInput {
  if (typeof input !== 'object' || input === null) {
    throw new HttpError(400, 'Body must be an object');
  }

  const candidate = input as Record<string, unknown>;

  if (typeof candidate.name !== 'string' || candidate.name.trim().length === 0) {
    throw new HttpError(400, 'name must be a non-empty string');
  }

  if (typeof candidate.email !== 'string' || !candidate.email.includes('@')) {
    throw new HttpError(400, 'email must be a valid email string');
  }

  return {
    name: candidate.name.trim(),
    email: candidate.email.trim().toLowerCase(),
  };
}

app.get('/users', async (ctx) => {
  ctx.json(200, [...users.values()]);
});

app.get('/users/:id', async (ctx) => {
  const user = users.get(ctx.params.id);

  if (!user) {
    throw new HttpError(404, `User ${ctx.params.id} not found`);
  }

  ctx.json(200, user);
});

app.post('/users', async (ctx) => {
  const input = validateCreateUser(ctx.body);

  const user: User = {
    id: randomUUID(),
    name: input.name,
    email: input.email,
    createdAt: new Date().toISOString(),
  };

  users.set(user.id, user);
  ctx.json(201, user);
});

app.patch('/users/:id', async (ctx) => {
  const existing = users.get(ctx.params.id);

  if (!existing) {
    throw new HttpError(404, `User ${ctx.params.id} not found`);
  }

  const input = ctx.body as UpdateUserInput;

  if (input.name !== undefined && typeof input.name !== 'string') {
    throw new HttpError(400, 'name must be a string');
  }

  if (input.email !== undefined && typeof input.email !== 'string') {
    throw new HttpError(400, 'email must be a string');
  }

  const updated: User = {
    ...existing,
    name: input.name?.trim() ?? existing.name,
    email: input.email?.trim().toLowerCase() ?? existing.email,
  };

  users.set(updated.id, updated);
  ctx.json(200, updated);
});

app.delete('/users/:id', async (ctx) => {
  const deleted = users.delete(ctx.params.id);

  if (!deleted) {
    throw new HttpError(404, `User ${ctx.params.id} not found`);
  }

  ctx.res.writeHead(204);
  ctx.res.end();
});

async function main() {
  await app.listen(3000);

  // Client example
  const apiClient = new ApiClient('http://localhost:3000');
  const userApi = new UserApi(apiClient);

  const created = await userApi.create({
    name: 'Ada Lovelace',
    email: 'ada@example.com',
  });

  console.log('Created:', created);

  const fetched = await userApi.get(created.id);
  console.log('Fetched:', fetched);

  await userApi.update(created.id, { name: 'Ada Augusta' });
  await userApi.remove(created.id);

  console.log('Deleted successfully');
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
```

