## Final solution

```ts
import Database from "better-sqlite3";

export type UserOrderSummary = {
  userId: number;
  userName: string;
  orderCount: number;
  totalSpentCents: number;
  lastOrderAt: string | null;
};

type RawUserOrderSummaryRow = {
  userId: number;
  userName: string;
  orderCount: number;
  totalSpentCents: number | null;
  lastOrderAt: string | null;
};

const SQL = `
  SELECT
    u.id AS userId,
    u.name AS userName,
    COUNT(o.id) AS orderCount,
    COALESCE(SUM(o.total_cents), 0) AS totalSpentCents,
    MAX(o.created_at) AS lastOrderAt
  FROM users u
  LEFT JOIN orders o ON o.user_id = u.id
  WHERE u.id = ?
  GROUP BY u.id, u.name
`;

export function getUserOrderSummary(
  db: Database.Database,
  userId: number
): UserOrderSummary | undefined {
  const row = db.prepare<RawUserOrderSummaryRow, [number]>(SQL).get(userId);

  if (!row) return undefined;

  return {
    userId: row.userId,
    userName: row.userName,
    orderCount: row.orderCount,
    totalSpentCents: row.totalSpentCents ?? 0,
    lastOrderAt: row.lastOrderAt,
  };
}
```

Key takeaways:

- Use `?` placeholders, never string interpolation, to prevent SQL injection.
- `LEFT JOIN` keeps users with no orders.
- `COALESCE` converts SQL `NULL` aggregate results into a safe default.
- Keep raw row types separate from public types so database nullability does not leak into your API.

## Explain SQL in TypeScript terms

| SQL clause | What it means | TypeScript analogue |
|---|---|---|
| `SELECT col1, col2` | Projection: keep only certain columns | `.map(row => pick(row, cols))` |
| `FROM table` | Source dataset | an array of objects `Row[]` |
| `WHERE pred` | Filter rows | `.filter(row => pred(row))` |
| `INNER JOIN t2 ON ...` | Combine matching rows from two tables | nested loops / hash join producing wider rows |
| `LEFT JOIN` | Keep left rows even without match | left rows preserved, right fields `null` |
| `GROUP BY k` | Partition rows into buckets by key | `reduce` into `Map<key, Row[]>` |
| `HAVING agg > x` | Filter *groups* | filter after grouping |
| `ORDER BY col ASC/DESC` | Sort | `.sort((a,b) => compare(a[col], b[col]))` |
| `LIMIT n OFFSET m` | Pagination | `.slice(m, m+n)` |
| Aggregates `COUNT/SUM/AVG` | Reduce a bucket to a scalar | `(rows) => rows.length / reduce(...)` |

So a SQL query is basically a **pipeline over arrays of objects**:  
`source → filter → join → group → project → sort → limit`.

Below is a small, clean, in-memory query engine that mirrors that pipeline. It is intentionally readable over hyper-optimized, but I note where you’d optimize in production.

---

## TypeScript implementation

```ts
// query.ts
// A tiny in-memory SQL-like query engine.

/** A row is just a string-keyed record. */
export type Row = Record<string, unknown>;

/** Direction for ORDER BY. */
export type SortDir = "asc" | "desc";

/** Join kind supported by this engine. */
export type JoinType = "inner" | "left";

/** Aggregate functions receive the rows of one group. */
export type AggregateFn = (rows: Row[]) => unknown;

/** A single join specification. */
export interface JoinSpec {
  table: Row[];
  on: (left: Row, right: Row) => boolean;
  type: JoinType;
  /** Prefix to avoid column-name collisions (e.g. "o." for orders). */
  prefix?: string;
}

/** Full query plan built by the fluent builder. */
export interface QueryPlan {
  source: Row[];
  projection?: string[];
  predicate?: (row: Row) => boolean;
  joins: JoinSpec[];
  groupKeys?: string[];
  aggregates?: Record<string, AggregateFn>;
  having?: (groupRow: Row) => boolean;
  orderBy: { key: string; dir: SortDir }[];
  limit?: number;
  offset?: number;
}

/**
 * Fluent builder. Each method returns `this` so calls chain like SQL.
 *
 * Example:
 *   new Query(users)
 *     .where(u => (u.age as number) >= 18)
 *     .innerJoin(orders, (u, o) => u.id === o.userId, "o")
 *     .select("name", "o.amount")
 *     .orderBy("o.amount", "desc")
 *     .limit(5)
 *     .execute();
 */
export class Query {
  private plan: QueryPlan;

  constructor(source: Row[]) {
    this.plan = {
      source: [...source], // defensive copy
      joins: [],
      orderBy: [],
    };
  }

  /** SELECT col1, col2, ... */
  select(...columns: string[]): this {
    this.plan.projection = columns;
    return this;
  }

  /** WHERE predicate(row) */
  where(predicate: (row: Row) => boolean): this {
    this.plan.predicate = predicate;
    return this;
  }

  /** INNER JOIN */
  innerJoin(
    table: Row[],
    on: (left: Row, right: Row) => boolean,
    prefix?: string
  ): this {
    this.plan.joins.push({ table: [...table], on, type: "inner", prefix });
    return this;
  }

  /** LEFT JOIN: keeps left rows even when no right match exists. */
  leftJoin(
    table: Row[],
    on: (left: Row, right: Row) => boolean,
    prefix?: string
  ): this {
    this.plan.joins.push({ table: [...table], on, type: "left", prefix });
    return this;
  }

  /** GROUP BY keys, with optional aggregate map. */
  groupBy(keys: string[], aggregates?: Record<string, AggregateFn>): this {
    this.plan.groupKeys = keys;
    this.plan.aggregates = aggregates;
    return this;
  }

  /** HAVING predicate(groupRow) — only meaningful after groupBy. */
  having(predicate: (groupRow: Row) => boolean): this {
    this.plan.having = predicate;
    return this;
  }

  /** ORDER BY key ASC/DESC. Multiple calls = multi-key sort. */
  orderBy(key: string, dir: SortDir = "asc"): this {
    this.plan.orderBy.push({ key, dir });
    return this;
  }

  /** LIMIT n */
  limit(n: number): this {
    this.plan.limit = n;
    return this;
  }

  /** OFFSET m */
  offset(m: number): this {
    this.plan.offset = m;
    return this;
  }

  /** Execute the plan and return rows. */
  execute(): Row[] {
    let rows = this.plan.source;

    // 1) WHERE — filter before joining/grouping (matches SQL semantics).
    if (this.plan.predicate) {
      rows = rows.filter(this.plan.predicate);
    }

    // 2) JOINs — applied left-to-right.
    for (const j of this.plan.joins) {
      rows = applyJoin(rows, j);
    }

    // 3) GROUP BY + aggregates + HAVING.
    if (this.plan.groupKeys && this.plan.groupKeys.length > 0) {
      rows = applyGroupBy(
        rows,
        this.plan.groupKeys,
        this.plan.aggregates ?? {},
        this.plan.having
      );
    }

    // 4) SELECT projection. If no projection given, keep all columns.
    if (this.plan.projection && this.plan.projection.length > 0) {
      rows = rows.map((r) => project(r, this.plan.projection!));
    }

    // 5) ORDER BY.
    if (this.plan.orderBy.length > 0) {
      rows = [...rows].sort((a, b) => compareRows(a, b, this.plan.orderBy));
    }

    // 6) OFFSET / LIMIT.
    const start = this.plan.offset ?? 0;
    const end =
      this.plan.limit !== undefined ? start + this.plan.limit : undefined;
    return rows.slice(start, end);
  }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                            */
/* ------------------------------------------------------------------ */

/** Apply one join to the current row set. */
function applyJoin(rows: Row[], spec: JoinSpec): Row[] {
  const out: Row[] = [];
  const prefix = spec.prefix ?? "";

  if (spec.type === "inner") {
    // O(n*m) nested-loop join. For large tables use a hash join:
    // build a Map on the join key of the right table, then probe.
    for (const left of rows) {
      for (const right of spec.table) {
        if (spec.on(left, right)) {
          out.push(mergeRow(left, right, prefix));
        }
      }
    }
    return out;
  }

  // LEFT JOIN: every left row survives; right side is null when no match.
  for (const left of rows) {
    let matched = false;
    for (const right of spec.table) {
      if (spec.on(left, right)) {
        out.push(mergeRow(left, right, prefix));
        matched = true;
      }
    }
    if (!matched) {
      // Pad right-side columns with null so downstream code sees stable keys.
      const padded: Row = { ...left };
      // We don't know right schema here; callers can still reference
      // prefixed keys and get undefined. To be safe, mark matched=false.
      padded[`__${prefix}matched`] = false;
      out.push(padded);
    }
  }
  return out;
}

/** Merge two rows, prefixing right-hand columns to avoid collisions. */
function mergeRow(left: Row, right: Row, prefix: string): Row {
  const result: Row = { ...left };
  for (const [k, v] of Object.entries(right)) {
    result[prefix ? `${prefix}${k}` : k] = v;
  }
  if (prefix) result[`__${prefix}matched`] = true;
  return result;
}

/** Keep only the requested columns. */
function project(row: Row, columns: string[]): Row {
  const out: Row = {};
  for (const c of columns) {
    out[c] = row[c]; // undefined if missing — matches SQL NULL-ish behavior
  }
  return out;
}

/** Group rows and compute aggregates. */
function applyGroupBy(
  rows: Row[],
  keys: string[],
  aggregates: Record<string, AggregateFn>,
  having?: (groupRow: Row) => boolean
): Row[] {
  // Bucket rows by a composite key built from group keys.
  const buckets = new Map<string, Row[]>();

  for (const r of rows) {
    const key = keys.map((k) => serialize(r[k])).join("\u0001");
    const bucket = buckets.get(key);
    if (bucket) bucket.push(r);
    else buckets.set(key, [r]);
  }

  const out: Row[] = [];
  for (const bucket of buckets.values()) {
    // Start with group-key values taken from the first row of the bucket.
    const groupRow: Row = {};
    for (const k of keys) groupRow[k] = bucket[0][k];

    // Compute each aggregate over the whole bucket.
    for (const [name, fn] of Object.entries(aggregates)) {
      groupRow[name] = fn(bucket);
    }

    // HAVING filters groups, not individual rows.
    if (having && !having(groupRow)) continue;

    out.push(groupRow);
  }
  return out;
}

/** Multi-key comparator honoring asc/desc. */
function compareRows(
  a: Row,
  b: Row,
  order: { key: string; dir: SortDir }[]
): number {
  for (const { key, dir } of order) {
    const cmp = compareValues(a[key], b[key]);
    if (cmp !== 0) return dir === "asc" ? cmp : -cmp;
  }
  return 0;
}

/** Nulls last, then natural ordering for strings/numbers. */
function compareValues(a: unknown, b: unknown): number {
  if (a == null && b == null) return 0;
  if (a == null) return 1; // nulls last
  if (b == null) return -1;
  if (typeof a === "number" && typeof b === "number") return a - b;
  if (typeof a === "string" && typeof b === "string")
    return a.localeCompare(b);
  if (a instanceof Date && b instanceof Date)
    return a.getTime() - b.getTime();
  // Fallback: stringify.
  return String(a).localeCompare(String(b));
}

/** Stable serialization for group keys (handles objects/arrays poorly on purpose). */
function serialize(v: unknown): string {
  if (v == null) return "\u0000null";
  if (typeof v === "object") return JSON.stringify(v);
  return String(v);
}
```

