## Usage example (with comments)

```ts
// data.ts
const users: Row[] = [
  { id: 1, name: "Alice", age: 30, dept: "eng" },
  { id: 2, name: "Bob", age: 17, dept: "eng" },
  { id: 3, name: "Carol", age: 25, dept: "sales" },
];

const orders: Row[] = [
  { id: 10, userId: 1, amount: 50 },
  { id: 11, userId: 1, amount: 70 },
  { id: 12, userId: 3, amount: 20 },
];

// Equivalent to:
// SELECT u.name, SUM(o.amount) AS total
// FROM users u
// LEFT JOIN orders o ON u.id = o.userId
// WHERE u.age >= 18
// GROUP BY u.name
// ORDER BY total DESC
// LIMIT 10;
const result = new Query(users)
  .where((u) => (u.age as number) >= 18)
  .leftJoin(orders, (u, o) => u.id === o.userId, "o.")
  .groupBy(["name"], {
    total: (rows) =>
      rows.reduce((s, r) => s + ((r["o.amount"] as number) ?? 0), 0),
  })
  .select("name", "total")
  .orderBy("total", "desc")
  .limit(10)
  .execute();

console.log(result);
// [ { name: 'Alice', total: 120 }, { name: 'Carol', total: 20 } ]
```

