Here is a complete, runnable TypeScript example that implements a singly linked list from scratch, contrasts it with native arrays, and includes small benchmarks for the classic trade-offs (prepend vs. append vs. random access).

```ts
// linked-list-vs-array.ts
// Run with:  npx ts-node linked-list-vs-array.ts   (or tsx / deno / bun)

/* ------------------------------------------------------------------ */
/* 1. Linked list implementation (generic, singly linked)             */
/* ------------------------------------------------------------------ */

class Node<T> {
  value: T;
  next: Node<T> | null = null;
  constructor(value: T) {
    this.value = value;
  }
}

class LinkedList<T> {
  private head: Node<T> | null = null;
  private tail: Node<T> | null = null;
  private _size = 0;

  get size(): number {
    return this._size;
  }

  /** O(1) amortized append */
  push(value: T): this {
    const node = new Node(value);
    if (!this.head) {
      this.head = this.tail = node;
    } else {
      this.tail!.next = node;
      this.tail = node;
    }
    this._size++;
    return this;
  }

  /** O(1) prepend */
  unshift(value: T): this {
    const node = new Node(value);
    node.next = this.head;
    this.head = node;
    if (!this.tail) this.tail = node;
    this._size++;
    return this;
  }

  /** O(n) random access by index */
  get(index: number): T | undefined {
    if (index < 0 || index >= this._size) return undefined;
    let cur = this.head;
    for (let i = 0; i < index; i++) cur = cur!.next;
    return cur?.value;
  }

  /** O(n) removal by index */
  removeAt(index: number): T | undefined {
    if (index < 0 || index >= this._size) return undefined;
    let removed: Node<T>;

    if (index === 0) {
      removed = this.head!;
      this.head = this.head!.next;
      if (!this.head) this.tail = null;
    } else {
      let prev = this.head!;
      for (let i = 0; i < index - 1; i++) prev = prev.next!;
      removed = prev.next!;
      prev.next = removed.next;
      if (removed === this.tail) this.tail = prev;
    }
    this._size--;
    return removed.value;
  }

  /** O(n) search */
  indexOf(value: T, eq: (a: T, b: T) => boolean = (a, b) => a === b): number {
    let cur = this.head;
    let i = 0;
    while (cur) {
      if (eq(cur.value, value)) return i;
      cur = cur.next;
      i++;
    }
    return -1;
  }

  toArray(): T[] {
    const out: T[] = [];
    let cur = this.head;
    while (cur) {
      out.push(cur.value);
      cur = cur.next;
    }
    return out;
  }

  [Symbol.iterator](): Iterator<T> {
    let cur = this.head;
    return {
      next(): IteratorResult<T> {
        if (!cur) return { value: undefined as any, done: true };
        const value = cur.value;
        cur = cur.next;
        return { value, done: false };
      },
    };
  }
}

/* ------------------------------------------------------------------ */
/* 2. Demo / correctness checks                                       */
/* ------------------------------------------------------------------ */

function demo() {
  const list = new LinkedList<number>();
  list.push(10).push(20).push(30);
  list.unshift(5);

  console.log("LinkedList contents:", list.toArray()); // [5,10,20,30]
  console.log("size:", list.size);                    // 4
  console.log("get(2):", list.get(2));               // 20
  console.log("indexOf(30):", list.indexOf(30));     // 3
  console.log("removeAt(1):", list.removeAt(1));     // 10
  console.log("after remove:", list.toArray());       // [5,20,30]

  // Iteration
  console.log("iter:", [...list].join(", "));        // 5, 20, 30

  // Array counterpart
  const arr: number[] = [10, 20, 30];
  arr.unshift(5);
  console.log("Array contents:", arr);               // [5,10,20,30]
}

/* ------------------------------------------------------------------ */
/* 3. Micro-benchmarks (illustrative, not scientific)                 */
/* ------------------------------------------------------------------ */

function time(label: string, fn: () => void): void {
  const t0 = performance.now();
  fn();
  const t1 = performance.now();
  console.log(`${label}: ${(t1 - t0).toFixed(2)} ms`);
}

function benchmarks() {
  const N = 100_000;

  // Prepend (unshift) — linked list O(1) each, array O(n) each
  time("LinkedList unshift x" + N, () => {
    const l = new LinkedList<number>();
    for (let i = 0; i < N; i++) l.unshift(i);
  });

  time("Array unshift x" + N, () => {
    const a: number[] = [];
    for (let i = 0; i < N; i++) a.unshift(i);
  });

  // Append (push) — both amortized O(1); arrays usually faster (cache)
  time("LinkedList push x" + N, () => {
    const l = new LinkedList<number>();
    for (let i = 0; i < N; i++) l.push(i);
  });

  time("Array push x" + N, () => {
    const a: number[] = [];
    for (let i = 0; i < N; i++) a.push(i);
  });

  // Random access — array O(1), linked list O(n)
  const arr = Array.from({ length: N }, (_, i) => i);
  const list = new LinkedList<number>();
  for (let i = 0; i < N; i++) list.push(i);

  time("Array random get x" + N, () => {
    let s = 0;
    for (let i = 0; i < N; i++) s += arr[Math.floor(Math.random() * N)];
    void s;
  });

  time("LinkedList random get x" + N, () => {
    let s = 0;
    for (let i = 0; i < N; i++) s += list.get(Math.floor(Math.random() * N))!;
    void s;
  });
}

/* ------------------------------------------------------------------ */
/* 4. Entry point                                                     */
/* ------------------------------------------------------------------ */

demo();
console.log("\n--- benchmarks ---");
benchmarks();

/* ------------------------------------------------------------------ */
/* 5. Complexity cheat sheet (comments)                              */
/* ------------------------------------------------------------------ */
/*
  Operation          Array (dynamic)   Singly Linked List
  ------------------ ----------------- ------------------
  Access by index    O(1)              O(n)
  Search (unsorted)  O(n)              O(n)
  Insert at head     O(n)              O(1)
  Insert at tail     O(1) amortized    O(1) (with tail ptr)
  Insert at middle   O(n)              O(n) (need traversal)
  Delete at head     O(n)              O(1)
  Delete at tail     O(1) amortized    O(n) (no prev ptr)
  Delete at middle   O(n)              O(n)
  Memory             contiguous, low   per-node overhead, scattered
  Cache locality     excellent         poor
*/
```

### Key takeaways

- **Arrays** win for almost everything in practice on modern hardware: cache-friendly contiguous memory, O(1) indexing, and highly optimized engine implementations (V8, SpiderMonkey).
- **Linked lists** shine when you need **O(1) insertion/deletion at the head** (or anywhere you already hold a node reference) and want to avoid the O(n) element-shifting cost of arrays. They also allow O(1) splicing of two lists.
- Doubly linked lists fix the “delete tail / previous node” problem at the cost of extra memory and complexity.
- If you need both fast append and fast prepend with good cache behavior, consider a **deque** (e.g., `Array` with head/tail indices, or a chunked deque).

Run the file with `npx tsx linked-list-vs-array.ts` to see the timings on your machine.

## Arrays vs. Linked Lists in TypeScript

### The core idea

| | Array | Linked list |
|---|---|---|
| Storage | One contiguous block (conceptually; V8 optimizes this heavily) | Nodes scattered in memory; each node stores `value` + `next` reference |
| Access by index | `O(1)` | `O(n)` — must walk from head |
| Insert/remove at front | `O(n)` (shifts elements) | `O(1)` (change one pointer) |
| Insert/remove in middle | `O(n)` | `O(n)` to find, `O(1)` to link |
| Memory overhead | Low | Higher (one node object + pointer per element) |
| Cache locality | Excellent | Poor |
| Typical TS/JS reality | Almost always preferred | Used for algorithms, specialized structures, or when stable node references matter |

In TypeScript/JavaScript, arrays are the default. Linked lists are mainly useful for **frequent head insertions/removals**, **custom ordering**, or **algorithm interview patterns**.

---

## Arrays in TypeScript

### Syntax and typing

```ts
// Inferred
const nums = [1, 2, 3];                 // number[]

// Explicit
const ids: number[] = [1, 2, 3];
const names: Array<string> = ["Ada", "Grace"];

// Readonly arrays
const frozen: readonly number[] = [1, 2, 3];
// frozen.push(4); // Error

// Tuples: fixed length, fixed types per position
const point: [number, number] = [3, 4];
const entry: [string, number] = ["age", 30];

// Dense arrays with optional/union types
const mixed: (string | number)[] = ["a", 1, "b"];
```

### Common operations

```ts
const arr = [10, 20, 30];

arr.push(40);          // [10,20,30,40]
arr.pop();             // 40
arr.unshift(5);        // [5,10,20,30]
arr.shift();           // 5
arr.splice(1, 1, 99);  // remove 1 at index 1, insert 99 -> [10,99,30]
const slice = arr.slice(0, 2); // [10,99] (non-mutating)

// Functional patterns
const doubled = arr.map(x => x * 2);
const evens = arr.filter(x => x % 2 === 0);
const sum = arr.reduce((a, b) => a + b, 0);
```

### Typical array use cases

- Random access: `users[index]`
- Small or medium collections
- Stacks: `push`/`pop`
- Data transformation pipelines (`map`, `filter`, `reduce`)
- JSON-friendly data
- Typed fixed shapes: tuples

