## Linked lists in TypeScript

A linked list is a chain of **nodes**. Each node holds a value and a pointer to the next node.

### Singly linked list implementation

```ts
interface ListNode<T> {
  value: T;
  next: ListNode<T> | null;
}

class SinglyLinkedList<T> implements Iterable<T> {
  private head: ListNode<T> | null = null;
  private tail: ListNode<T> | null = null;
  private _size = 0;

  get size(): number {
    return this._size;
  }

  isEmpty(): boolean {
    return this._size === 0;
  }

  prepend(value: T): this {
    const node: ListNode<T> = { value, next: this.head };
    this.head = node;
    if (this.tail === null) this.tail = node;
    this._size++;
    return this;
  }

  append(value: T): this {
    const node: ListNode<T> = { value, next: null };
    if (this.tail === null) {
      this.head = this.tail = node;
    } else {
      this.tail.next = node;
      this.tail = node;
    }
    this._size++;
    return this;
  }

  insertAt(index: number, value: T): this {
    if (index < 0 || index > this._size) throw new RangeError("Index out of bounds");
    if (index === 0) return this.prepend(value);
    if (index === this._size) return this.append(value);

    let prev = this.head!;
    for (let i = 0; i < index - 1; i++) prev = prev.next!;
    const node: ListNode<T> = { value, next: prev.next };
    prev.next = node;
    this._size++;
    return this;
  }

  removeAt(index: number): T {
    if (index < 0 || index >= this._size) throw new RangeError("Index out of bounds");

    if (index === 0) {
      const value = this.head!.value;
      this.head = this.head!.next;
      if (this.head === null) this.tail = null;
      this._size--;
      return value;
    }

    let prev = this.head!;
    for (let i = 0; i < index - 1; i++) prev = prev.next!;

    const removed = prev.next!;
    prev.next = removed.next;
    if (removed === this.tail) this.tail = prev;
    this._size--;
    return removed.value;
  }

  find(predicate: (value: T) => boolean): T | undefined {
    let current = this.head;
    while (current !== null) {
      if (predicate(current.value)) return current.value;
      current = current.next;
    }
    return undefined;
  }

  toArray(): T[] {
    const result: T[] = [];
    let current = this.head;
    while (current !== null) {
      result.push(current.value);
      current = current.next;
    }
    return result;
  }

  *[Symbol.iterator](): Iterator<T> {
    let current = this.head;
    while (current !== null) {
      yield current.value;
      current = current.next;
    }
  }
}
```

### Usage

```ts
const list = new SinglyLinkedList<number>();

list.append(2).append(3).prepend(1); // chaining via `this`
console.log(list.toArray());         // [1, 2, 3]

list.insertAt(1, 1.5);
console.log(list.toArray());         // [1, 1.5, 2, 3]

console.log(list.removeAt(2));        // 2
console.log(list.toArray());         // [1, 1.5, 3]

for (const value of list) {
  console.log(value);
}

const found = list.find(x => x > 1.5); // 3
```

### Doubly linked list (when you need backward traversal)

```ts
interface DNode<T> {
  value: T;
  prev: DNode<T> | null;
  next: DNode<T> | null;
}

class DoublyLinkedList<T> {
  private head: DNode<T> | null = null;
  private tail: DNode<T> | null = null;
  private _size = 0;

  get size() { return this._size; }

  append(value: T): this {
    const node: DNode<T> = { value, prev: this.tail, next: null };
    if (this.tail === null) {
      this.head = this.tail = node;
    } else {
      this.tail.next = node;
      this.tail = node;
    }
    this._size++;
    return this;
  }

  prepend(value: T): this {
    const node: DNode<T> = { value, prev: null, next: this.head };
    if (this.head === null) {
      this.head = this.tail = node;
    } else {
      this.head.prev = node;
      this.head = node;
    }
    this._size++;
    return this;
  }

  removeTail(): T | undefined {
    if (this.tail === null) return undefined;
    const value = this.tail.value;
    this.tail = this.tail.prev;
    if (this.tail) this.tail.next = null;
    else this.head = null;
    this._size--;
    return value;
  }
}
```

