  return [
    { id: 1, title: "Hello async", userId },
    { id: 2, title: "TypeScript tips", userId },
  ];
}

async function fetchNotifications(userId: number): Promise<Notification[]> {
  await delay(100);
  return [{ id: 1, message: "Welcome back!", read: false }];
}

// --- core async logic ---

async function loadDashboard(
  userId: number
): Promise<{ user: User; posts: Post[]; notifications: Notification[] }> {
  const user = await fetchUser(userId);

  if (!user) {
    throw new NotFoundError(`User with id ${userId} was not found.`);
  }

  const [posts, notifications] = await Promise.all([
    fetchPosts(user.id),
    fetchNotifications(user.id),
