### Why this is idiomatic

- **Single responsibility**: `loadDashboard` orchestrates; services do I/O.
- **Fail fast**: validate `user` before doing dependent work.
- **Concurrency**: `Promise.all` avoids serializing independent requests.
- **Type safety**: every async boundary has explicit types; `instanceof` narrows errors.
- **Composability**: callers can `await loadDashboard(...)` and handle errors locally.

## 1. What `async`/`await` really is

In TypeScript/JavaScript, `async`/`await` is **not magic runtime syntax**. It is syntactic sugar over **Promises**. Conceptually, an `async function` returns a `Promise`, and every `await` says:

> “Pause this function until the awaited Promise settles; if it resolves, continue with the value; if it rejects, throw inside this function.”

TypeScript lowers it (depending on target) to something like a state machine or a generator runner plus `Promise` chaining. The key ideas:

- `async function f(): Promise<T>` always returns a `Promise<T>`.
- Inside, `const x = await p` unwraps `p: Promise<U>` into `U`.
- `throw` inside an async function becomes `Promise.reject`.
- `return value` becomes `Promise.resolve(value)`.
- Sequential `await`s create sequential dependencies.  
  For true parallelism, use `Promise.all` or `Promise.allSettled`.

Example:

```ts
async function loadUser(id: number): Promise<{ id: number; name: string }> {
  const res = await fetch(`/api/users/${id}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

// Sequential: second waits for first
async function sequential() {
  const a = await loadUser(1);
  const b = await loadUser(2);
  return [a, b];
}

// Parallel: both start immediately
async function parallel() {
  const [a, b] = await Promise.all([loadUser(1), loadUser(2)]);
  return [a, b];
}
```

---

## 2. The core mechanism: generator runner

The classic way to implement the *core* of `async/await` is:

1. Write a function as a **generator** (`function*`).
2. Each `yield` becomes an `await` point.
3. A runner repeatedly calls `generator.next(value)` or `generator.throw(error)`, and when the yielded value is a Promise (or thenable), it waits for it and feeds the result back.

This is exactly what many transpilers did before native `async/await`.

---

## 3. TypeScript implementation

```ts
/**
 * Minimal async/await core built on generators.
 *
 * Usage:
 *
 *   const delay = (ms: number) => new Promise<void>(r => setTimeout(r, ms));
 *
 *   const main = asyncify(function* () {
 *     yield delay(100);
 *     return "done";
 *   });
 *
 *   main().then(console.log); // "done"
 */

/**
 * A coroutine runner.
 *
 * It drives a generator to completion:
 * - generator.next(value) feeds a resolved value back into the generator
 * - generator.throw(error) throws a rejected error into the generator
 * - yielded values are treated as awaitables (Promise-like)
 */
function runGenerator<T>(
  generator: Generator<unknown, T, unknown>
): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    // Feed a successful value into the generator and continue.
    function handleNext(value?: unknown): void {
      let result: IteratorResult<unknown, T>;

      try {
        result = generator.next(value);
      } catch (err) {
        // Exception thrown synchronously by generator body.
        reject(err);
        return;
      }

      if (result.done) {
        resolve(result.value);
        return;
      }

      // The yielded value may be a Promise, thenable, or plain value.
      // Promise.resolve normalizes all of them into a Promise.
      Promise.resolve(result.value)
        .then(
          (resolved) => handleNext(resolved),
          (rejected) => handleThrow(rejected)
        );
    }

    // Throw an error into the generator at the current yield point.
    function handleThrow(error: unknown): void {
      let result: IteratorResult<unknown, T>;

      try {
        result = generator.throw(error);
      } catch (err) {
        // If generator.throw itself throws, the whole async function rejects.
        reject(err);
        return;
      }

      if (result.done) {
        resolve(result.value);
        return;
      }

      Promise.resolve(result.value)
        .then(
          (resolved) => handleNext(resolved),
          (rejected) => handleThrow(rejected)
        );
    }

    // Start the generator. The first next() has no incoming value.
    handleNext();
  });
}

/**
 * Converts a generator function into an async function.
 *
 * The generator function may take arguments and return T.
 * Yielded values are awaited; the final return value is wrapped in Promise<T>.
 */
function asyncify<Args extends unknown[], T>(
  generatorFn: (...args: Args) => Generator<unknown, T, unknown>
): (...args: Args) => Promise<T> {
  return (...args: Args): Promise<T> => {
    const generator = generatorFn(...args);
    return runGenerator(generator);
  };
}

/* ----------------------------- Demo / usage ----------------------------- */

// A simple awaitable helper.
const delay = (ms: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms));

// An "async function" written as a generator.
const loadUser = asyncify(function* (id: number) {
  yield delay(50); // await delay(50)

  if (id === 0) {
    throw new Error("invalid id"); // becomes rejected Promise
  }

  return { id, name: `user-${id}` };
});

// Sequential orchestration.
const sequentialLoad = asyncify(function* () {
  const a = yield loadUser(1); // await loadUser(1)
  const b = yield loadUser(2); // await loadUser(2)
  return [a, b];
});

// Parallel orchestration inside the same model.
const parallelLoad = asyncify(function* () {
  const promiseA = loadUser(1);
  const promiseB = loadUser(2);

  const a = yield promiseA;
  const b = yield promiseB;
  return [a, b];
});

// Run demos.
sequentialLoad()
  .then((users) => console.log("sequential:", users))
  .catch((err) => console.error("sequential error:", err));

parallelLoad()
  .then((users) => console.log("parallel:", users))
  .catch((err) => console.error("parallel error:", err));

loadUser(0)
  .then((user) => console.log("user0:", user))
  .catch((err) => console.error("expected error:", err.message));
```

---

## 4. Important interview points

### Why `Promise.resolve(result.value)` matters
Yielded values do not have to be real Promises. They might be:
- `number`
- `{ then(...) }` (thenables)
- native `Promise`

`Promise.resolve` normalizes all of them, preserving async sequencing.

### Why both `next` and `throw` are needed
- `next(value)` continues after a successful await.
- `throw(error)` continues after a rejected await by throwing into the generator at the exact `yield` position. This is what makes `try/catch` around `await` work.

Example:

```ts
const safeLoad = asyncify(function* () {
  try {
    const user = yield loadUser(0); // rejects
    return user;
  } catch (err) {
    return { id: -1, name: "fallback" };
  }
});
```

### Sequential vs parallel
A common bug:

```ts
// Slow: 200ms total
const a = await delay(100);
const b = await delay(100);

// Fast: ~100ms total
const [a, b] = await Promise.all([delay(100), delay(100)]);
```

### Error propagation
- An unhandled rejection inside an async function rejects the returned Promise.
- A `throw` after an `await` becomes a rejection.
- `finally` blocks run for both success and failure because the runner eventually calls `next` or `throw`.

### Type-checking in TypeScript
In real TypeScript, the compiler infers:

```ts
async function f(): Promise<number> {
  const x = await Promise.resolve(42); // x: number
  return x + 1; // Promise<number>
}
```

The implementation above is runtime-level; TypeScript’s type system already guarantees the `Promise<T>` contract at compile time.

---

## 5. What this implementation intentionally omits

A production engine also handles:
- Microtask queue scheduling and stack preservation
- Cancellation (`AbortSignal`)
- Async iterators (`for await...of`)
- Top-level `await` in modules
- Native async stack traces

But the code above captures the **essential core**: *a generator + Promise runner that turns `yield` into `await`.*

Here are common async/await edge cases in TypeScript, with idiomatic fixes.

## 1. `async` functions never throw synchronously

Calling an async function always returns a Promise. A `try/catch` around the call will not catch a thrown error.

```ts
async function boom(): Promise<void> {
  throw new Error("boom");
}

// BAD: catch never runs
try {
  boom();
} catch (e) {
  console.error("never reached");
}

// GOOD
boom().catch((e) => console.error(e));

// or
await boom(); // inside another async function
```

## 2. `return await` matters inside `try/catch`

If you return a promise without awaiting it, its rejection happens after the function has already returned, so the local `catch` will not handle it.

```ts
async function loadUser(id: string) {
  try {
    // BAD: rejection escapes this try block
    return fetch(`/users/${id}`).then((r) => r.json());
  } catch (e) {
    console.error("not caught");
    return null;
  }
}

async function loadUserFixed(id: string) {
  try {
    // GOOD: rejection occurs inside try
    return await fetch(`/users/${id}`).then((r) => r.json());
  } catch (e) {
    console.error("caught", e);
    return null;
  }
}
```

## 3. `forEach` does not await async callbacks

`Array.prototype.forEach` ignores returned promises, causing floating promises and nondeterministic completion.

```ts
const ids = [1, 2, 3];

// BAD
ids.forEach(async (id) => {
  await save(id);
});

// Sequential
for (const id of ids) {
  await save(id);
}

// Parallel
await Promise.all(ids.map((id) => save(id)));
```

## 4. Floating promises

Any async call that is not awaited or chained can become an unhandled rejection.

```ts
async function save(): Promise<void> {}

// BAD
save();

// Intentional fire-and-forget, but still risky unless handled
void save();

// SAFE
save().catch((e) => logger.error(e));
```

Use linting (`no-floating-promises`) to catch these.

## 5. `Promise.all` fails fast; use `allSettled` when you need all outcomes

```ts
const tasks = [taskA(), taskB(), taskC()];

// Throws on first rejection; other tasks may still be running
const results = await Promise.all(tasks);

// Returns every result, including rejections
const settled = await Promise.allSettled(tasks);
for (const r of settled) {
  if (r.status === "rejected") console.error(r.reason);
  else console.log(r.value);
}
```

## 6. No built-in timeout or cancellation

Native async/await does not cancel work. Use `AbortController` and always clear timers.

```ts
async function fetchWithTimeout(url: string, ms: number): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);

  try {
    return await fetch(url, { signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}
```

`Promise.race` can implement a timeout, but it does not cancel the underlying operation.

## 7. `this` binding in async methods

Passing an async method as a callback loses `this`.

```ts
class Api {
  baseUrl = "/api";

  async get(path: string) {
    return fetch(this.baseUrl + path);
  }

  bad() {
    setTimeout(this.get, 100, "/x"); // this is undefined
  }

  good() {
    setTimeout(() => this.get("/x"), 100);
  }
}
```

## 8. Async constructors are impossible

Use a static factory method.

```ts
class User {
  private constructor(public readonly id: string) {}

  static async create(id: string): Promise<User> {
    const user = new User(id);
    await user.init();
    return user;
  }

  private async init(): Promise<void> {
    // async setup
  }
}

const user = await User.create("123");
```

## 9. Getters should not hide async work

A getter cannot be truly awaited by callers in the way they expect. Prefer an async method.

```ts
class Store {
  // Misleading: returns Promise<number>, not number
  get value(): Promise<number> {
    return fetchData();
  }

  // Better
  async getValue(): Promise<number> {
    return fetchData();
  }
}
```

## 10. Top-level await requires ESM

Top-level `await` works only in ES modules.

```json
// package.json
{ "type": "module" }
```

```ts
// config.ts
const config = await loadConfig();
export { config };
```

In CommonJS, wrap in an async main function:

```ts
async function main() {
  const config = await loadConfig();
  console.log(config);
}
main().catch(console.error);
```

## 11. Microtask ordering surprises

`await` always schedules continuation as a microtask, so synchronous code runs first.

```ts
console.log("1");

(async () => {
  await Promise.resolve();
  console.log("3");
})();

console.log("2");
// Output: 1, 2, 3
```

## 12. Shared mutable state races

`await` yields control, so interleaving can cause lost updates.

```ts
let counter = 0;

async function increment() {
  const current = counter;
  await delay(10);
  counter = current + 1; // lost update under concurrency
}

// Fix: avoid read-modify-write across await, or use a lock/queue
```

## 13. Cleanup must be awaited in `finally`

In an async function, `finally` can await cleanup. If you do not await it, cleanup becomes a floating promise.

```ts
async function withResource() {
  const resource = await acquire();

  try {
    return await use(resource);
  } finally {
    await resource.release(); // GOOD
  }
}
```

## 14. Async iteration and resource cleanup

Use `for await...of` for async iterables, and ensure cleanup on early exit.

```ts
async function readAll(stream: AsyncIterable<string>) {
  const chunks: string[] = [];

  for await (const chunk of stream) {
    chunks.push(chunk);
    if (chunks.length > 100) break; // may need stream.return() depending on implementation
  }

  return chunks;
}
```

## 15. Thenable duck typing

`await` treats any object with a `then` method as a promise. This can be surprising and can throw.

```ts
const thenable = {
  then(resolve: (value: number) => void) {
    resolve(42);
  },
};

const value = await thenable; // 42

// Dangerous custom thenable
const bad = {
  then() {
    throw new Error("bad then");
  },
};

try {
  await bad;
} catch (e) {
  console.error(e);
}
```

`await null`, `await undefined`, and `await 42` are safe and return the value unchanged.

## 16. Concurrency limits

`Promise.all` on thousands of tasks can exhaust sockets, memory, or rate limits. Use bounded concurrency.

```ts
async function mapLimit<T, R>(
  items: T[],
  limit: number,
  fn: (item: T) => Promise<R>
): Promise<R[]> {
  const results: R[] = new Array(items.length);
  let next = 0;

  const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (next < items.length) {
      const index = next++;
      results[index] = await fn(items[index]);
    }
  });

  await Promise.all(workers);
  return results;
}
```

## 17. Error chaining with `cause`

Preserve original errors when rethrowing.

```ts
async function query() {
  try {
    return await db.query("SELECT 1");
  } catch (e) {
    throw new Error("database query failed", { cause: e });
  }
}
```

## 18. Memory retention across `await`

Closures and local variables remain alive until the awaited promise settles.

```ts
async function process(big: Buffer) {
  await delay(5000);
  // `big` is retained for the whole delay
  return big.length;
}

// Better: extract only needed data before awaiting
async function processFixed(big: Buffer) {
  const size = big.length;
  await delay(5000);
  return size;
}
```

## 19. Type-level edge case: `async` always returns `Promise<T>`

```ts
async function answer(): Promise<number> {
  return 42;
}

const p = answer();      // Promise<number>
const n = await answer(); // number
```

When implementing an interface, make sure the expected return type is `Promise<T>`, not `T`.

## 20. Unhandled rejections in Node.js

In modern Node.js, unhandled promise rejections can terminate the process. Add a global handler for diagnostics, but prefer fixing call sites.

```ts
process.on("unhandledRejection", (reason, promise) => {
  console.error("Unhandled rejection:", reason, promise);
});
```

### Practical checklist

- Await or `.catch()` every async call.
- Use `return await` when a returned promise must be caught in the same `try`.
- Avoid `forEach(async ...)`.
- Use `Promise.allSettled` when partial failure is acceptable.
- Add timeouts/cancellation with `AbortController`.
- Avoid shared mutable state across `await`.
- Use factory methods instead of async constructors.
- Bound concurrency for large batches.

```ts
// bigo.ts
// Run with: npx tsx bigo.ts   (or: npx ts-node bigo.ts)

import { performance } from "node:perf_hooks";

/* ------------------------------------------------------------------ */
/* 1. The notation itself                                               */
/* ------------------------------------------------------------------ */

/** Complexity classes we know how to name and reason about. */
type BigO =
  | "O(1)"
  | "O(log n)"
  | "O(n)"
  | "O(n log n)"
  | "O(n^2)"
  | "O(n^3)"
  | "O(2^n)";

/** Growth functions behind the notation. */
const GROWTH: Record<BigO, (n: number) => number> = {
  "O(1)": () => 1,
  "O(log n)": (n) => Math.log2(Math.max(2, n)),
  "O(n)": (n) => n,
  "O(n log n)": (n) => n * Math.log2(Math.max(2, n)),
  "O(n^2)": (n) => n * n,
  "O(n^3)": (n) => n ** 3,
  "O(2^n)": (n) => 2 ** n,
};

/** Simplest -> most complex, used as a tie-break order. */
const ORDER: BigO[] = [
  "O(1)", "O(log n)", "O(n)", "O(n log n)",
  "O(n^2)", "O(n^3)", "O(2^n)",
];

/* ------------------------------------------------------------------ */
/* 2. Attaching complexity to a function (the "notation" as metadata)   */
/* ------------------------------------------------------------------ */

type Annotated<F extends (...a: any[]) => any, C extends BigO> =
  F & { readonly __complexity: C };

function annotate<C extends BigO, F extends (...a: any[]) => any>(
  complexity: C,
  fn: F,
): Annotated<F, C> {
  const out = fn as Annotated<F, C>;
  Object.defineProperty(out, "__complexity", {
    value: complexity,
    writable: false,
    enumerable: false,
  });
  return out;
}

/* ------------------------------------------------------------------ */
/* 3. Empirical measurement                                             */
/* ------------------------------------------------------------------ */

interface Sample { n: number; ms: number }

/** Run `fn(n)` `iters` times and return total elapsed ms. */
function runTimes(fn: (n: number) => number, n: number, iters: number): number {
  const t0 = performance.now();
  let sink = 0;
  for (let i = 0; i < iters; i++) sink += fn(n);
  // keep the work observable so V8 can't delete the loop
  (globalThis as any).__sink = sink;
  return performance.now() - t0;
}

/** Measure a single (n) point, auto-scaling repetitions until stable. */
function measureOne(fn: (n: number) => number, n: number): number {
  let iters = 1;
  let elapsed = runTimes(fn, n, iters);

  // ramp up repetitions until we have a measurable, stable duration
  while (elapsed < 8 && iters < 1_000_000) {
    iters *= 2;
    elapsed = runTimes(fn, n, iters);
    if (elapsed > 2_000) break; // don't hang on heavy functions
  }

  // take the best (minimum) of several runs
  const trials: number[] = [];
  for (let r = 0; r < 5; r++) {
    const e = runTimes(fn, n, iters);
    trials.push(e / iters);
    if (e > 2_000) break;
  }
  return Math.min(...trials);
}

function measure(
  fn: (n: number) => number,
  sizes: number[],
): Sample[] {
  // warmup
  for (const n of sizes) {
    try { fn(n); } catch { /* ignore */ }
  }
  return sizes.map((n) => ({ n, ms: measureOne(fn, n) }));
}

/* ------------------------------------------------------------------ */
/* 4. Classification: which Big-O best fits the measured points?         */
/* ------------------------------------------------------------------ */

function linearFitMape(samples: Sample[], g: (n: number) => number): number {
  const xs = samples.map((s) => g(s.n));
  const ys = samples.map((s) => s.ms);
  const n = xs.length;

  if (xs.some((x) => !isFinite(x))) return Infinity;

  const mx = xs.reduce((a, b) => a + b, 0) / n;
  const my = ys.reduce((a, b) => a + b, 0) / n;

  let sxx = 0, sxy = 0;
  for (let i = 0; i < n; i++) {
    sxx += (xs[i] - mx) ** 2;
    sxy += (xs[i] - mx) * (ys[i] - my);
  }
  const a = sxx === 0 ? 0 : sxy / sxx;
  const b = my - a * mx;

  // mean absolute percentage error (floor avoids div-by-zero)
  let mape = 0;
  for (let i = 0; i < n; i++) {
    const pred = a * xs[i] + b;
    const denom = Math.max(ys[i], 1e-9);
    mape += Math.abs((pred - ys[i]) / denom);
  }
  return mape / n;
}

function classify(samples: Sample[]): BigO {
  let best: BigO = ORDER[0];
  let bestMape = Infinity;

  for (const key of ORDER) {
    const mape = linearFitMape(samples, GROWTH[key]);
    // only switch if meaningfully better (avoids noise-driven flips)
    if (mape < bestMape * 0.995) {
      bestMape = mape;
      best = key;
    }
  }
  return best;
}

/* ------------------------------------------------------------------ */
/* 5. Demo algorithms of known complexity                               */
/* ------------------------------------------------------------------ */

function sizesFor(expected: BigO): number[] {
  switch (expected) {
    case "O(1)":        return [1, 2, 4, 8, 16];
    case "O(log n)":    return [1e3, 1e4, 1e5, 1e6, 1e7];
    case "O(n)":        return [1e3, 2e3, 4e3, 8e3, 16e3];
    case "O(n log n)":  return [1e3, 2e3, 4e3, 8e3, 16e3];
    case "O(n^2)":      return [1e2, 2e2, 4e2, 8e2, 1.6e3];
    case "O(n^3)":      return [20, 40, 80, 120, 160];
    case "O(2^n)":      return [4, 6, 8, 10, 12, 14, 16];
  }
}

const algos: { name: string; expected: BigO; fn: (n: number) => number }[] = [
  {
    name: "constant work",
    expected: "O(1)",
    fn: (n) => {
      let s = 0;
      for (let i = 0; i < 5_000; i++) s += i * i;
      return s + (n & 0); // depends on n trivially, keeps loop honest
    },
  },
  {
    name: "linear scan",
    expected: "O(n)",
    fn: (n) => {
      let s = 0;
      for (let i = 0; i < n; i++) s += i * 3 + 7;
      return s;
    },
  },
  {
    name: "binary search (steps)",
    expected: "O(log n)",
    fn: (n) => {
      let lo = 0, hi = n, steps = 0;
      const target = Math.floor(n / 3);
      while (lo < hi) {
        const mid = (lo + hi) >> 1;
        steps++;
        if (mid < target) lo = mid + 1;
        else hi = mid;
      }
      return steps;
    },
  },
  {
    name: "n log n (loop nest)",
    expected: "O(n log n)",
    fn: (n) => {
      let s = 0;
      for (let i = 1; i < n; i <<= 1)
        for (let j = 0; j < n; j++) s += j;
      return s;
    },
  },
  {
    name: "nested loops (matrix-ish)",
    expected: "O(n^2)",
    fn: (n) => {
      let s = 0;
      for (let i = 0; i < n; i++)
        for (let j = 0; j < n; j++) s += i + j;
      return s;
    },
  },
  {
    name: "triple nested loops",
    expected: "O(n^3)",
    fn: (n) => {
      let s = 0;
      for (let i = 0; i < n; i++)
        for (let j = 0; j < n; j++)
          for (let k = 0; k < n; k++) s += i + j + k;
      return s;
    },
  },
  {
    name: "subset enumeration",
    expected: "O(2^n)",
    fn: (n) => {
      let count = 0;
      for (let mask = 0; mask < (1 << n); mask++) count += mask & 1;
      return count;
    },
  },
];

/* ------------------------------------------------------------------ */
/* 6. Main                                                              */
/* ------------------------------------------------------------------ */

function main() {
  console.log("Empirical Big-O classifier\n");
  console.log(
    "name".padEnd(26),
    "expected".padEnd(12),
    "measured".padEnd(12),
    "samples (n -> ms)",
  );
  console.log("-".repeat(80));

  for (const algo of algos) {
    const samples = measure(algo.fn, sizesFor(algo.expected));
    const measured = classify(samples);
    const ok = measured === algo.expected ? "✓" : "✗";
    const sampleStr = samples
      .map((s) => `${s.n}->${s.ms.toFixed(3)}`)
      .join(", ");
    console.log(
      algo.name.padEnd(26),
      algo.expected.padEnd(12),
      (measured + " " + ok).padEnd(12),
      sampleStr,
    );
  }

  console.log("\nAnnotated functions (notation as metadata):");
  const linear = annotate("O(n)", (n: number) => {
    let s = 0;
    for (let i = 0; i < n; i++) s += i;
    return s;
  });
  console.log("linear.__complexity =", linear.__complexity);
  console.log("linear(10) =", linear(10));
}

main();
```

### How it works

1. **Notation as data** — `BigO` is a union of standard class names, and `GROWTH` maps each name to its mathematical growth function `g(n)`. This is the "implementation" of the notation: you can compare two classes by comparing their `g(n)`.

2. **Notation as metadata** — `annotate(complexity, fn)` returns the original function tagged with a readonly `__complexity` property. This lets you carry the analytical Big-O alongside the code without changing call sites.

3. **Empirical measurement** — `measure` runs each algorithm at several input sizes. `measureOne` auto-scales the number of repetitions so that even microsecond-scale operations produce stable timings, and takes the minimum of several trials to reduce GC/JIT noise.

4. **Classification** — For each candidate class, we fit `time = a·g(n) + b` by least squares and compute the mean absolute percentage error (MAPE). The class with the lowest MAPE wins; a 0.5% improvement threshold prevents noise from flipping between adjacent (e.g. O(n) vs O(n log n)) classes. The tie-break order runs from simplest to most complex.

5. **Demo** — Seven algorithms with known complexity are benchmarked; the measured class is printed next to the expected one (✓/✗), along with the raw timing samples.

### Running

```bash
npm i -D tsx
npx tsx bigo.ts
```

You can adapt `sizesFor`, add new classes to `GROWTH`/`ORDER`, or use `annotate` to label your own functions. For real-world use, pin input sizes to ranges where the algorithm completes in tens of milliseconds, and prefer `min`-of-trials timing to reduce noise.

## Big O in TypeScript: idea, notation, and use cases

Big O notation describes how an algorithm’s **running time or memory usage grows** as the input size grows. In TypeScript (and JavaScript in general), it is used to reason about runtime behavior, compare implementations, and choose data structures—not to measure exact milliseconds.

---

### 1. The idea

- **Input size** is usually called `n`: number of items, length of an array, number of nodes, etc.
- **Growth rate only**: Big O ignores constant factors and lower-order terms.

  ```
  3n + 5  -> O(n)
  2n^2 + 4n + 7 -> O(n^2)
  ```

- It answers: *“If the input gets much larger, how does cost scale?”*
- It is usually an **upper bound** (worst case), though people often colloquially use it for typical/average behavior too.

Common classes from fastest-growing concern:

| Notation | Name | Typical meaning |
|---|---|---|
| `O(1)` | Constant | Same work regardless of input size |
| `O(log n)` | Logarithmic | Work shrinks by a factor each step |
| `O(n)` | Linear | One pass over input |
| `O(n log n)` | Linearithmic | Divide-and-conquer sorting |
| `O(n^2)` | Quadratic | Nested loops over input |
| `O(2^n)` | Exponential | Branching recursion |
| `O(n!)` | Factorial | Permutations |

---

### 2. The “syntax”

Big O is written as `O(f(n))`, where `f(n)` is a function of input size.

Examples:

```ts
// O(1)
function first<T>(arr: T[]): T | undefined {
  return arr[0];
}

// O(n)
function sum(arr: number[]): number {
  return arr.reduce((a, b) => a + b, 0);
}

// O(log n)
function binarySearch(sorted: number[], target: number): number {
  let lo = 0;
  let hi = sorted.length - 1;

  while (lo <= hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (sorted[mid] === target) return mid;
    if (sorted[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}
```

Time complexity is often written as comments above functions:

```ts
/**
 * Time: O(n^2)
 * Space: O(1) extra
 */
function bubbleSort(arr: number[]): number[] {
  const a = [...arr];
  for (let i = 0; i < a.length; i++) {
    for (let j = 0; j < a.length - i - 1; j++) {
      if (a[j] > a[j + 1]) {
        [a[j], a[j + 1]] = [a[j + 1], a[j]];
      }
    }
  }
  return a;
}
```

---

### 3. Short TypeScript examples by complexity

#### `O(1)` — constant

```ts
function hasUser(users: Set<string>, id: string): boolean {
  return users.has(id); // hash lookup, independent of set size
}
```

#### `O(n)` — linear

```ts
function linearSearch<T>(items: T[], target: T): number {
  for (let i = 0; i < items.length; i++) {
    if (items[i] === target) return i;
  }
  return -1;
}
```

#### `O(log n)` — logarithmic

```ts
function findInsertionPoint(sorted: number[], value: number): number {
  let lo = 0;
  let hi = sorted.length;

  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (sorted[mid] < value) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}
```

#### `O(n log n)` — typical efficient sorting

```ts
function sortedCopy(arr: number[]): number[] {
  return [...arr].sort((a, b) => a - b);
  // JS engines usually use a hybrid sort; commonly taught as O(n log n)
}
```

#### `O(n^2)` — quadratic

```ts
function allPairs<T>(items: T[]): [T, T][] {
  const pairs: [T, T][] = [];
  for (const a of items) {
    for (const b of items) {
      pairs.push([a, b]);
    }
  }
  return pairs;
}
```

#### `O(2^n)` — exponential

```ts
function fib(n: number): number {
  if (n <= 1) return n;
  return fib(n - 1) + fib(n - 2);
}
```

This is a classic example of terrible scaling. A memoized version is `O(n)`:

```ts
function fibMemo(n: number, memo = new Map<number, number>()): number {
  if (n <= 1) return n;
  if (memo.has(n)) return memo.get(n)!;
  const result = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  memo.set(n, result);
  return result;
}
```

---

### 4. Typical use cases

#### Choosing data structures

```ts
const items: string[] = ["a", "b", "c"];
const itemSet = new Set(items);

// O(n) lookup
items.includes("b");

// O(1) average lookup
itemSet.has("b");
```

#### Avoiding repeated expensive work

```ts
// Bad: O(n * m) if done naively in a loop
function enrich(users: { id: string }[], lookup: Map<string, unknown>) {
  return users.map(u => ({ ...u, meta: lookup.get(u.id) }));
}
```

#### Pagination and slicing

```ts
function page<T>(items: T[], page: number, size: number): T[] {
  const start = page * size;
  return items.slice(start, start + size);
  // slice is O(size), not O(n), if engine optimizes range copy;
  // conceptually, work scales with page size, not full list
}
```

#### Algorithm selection in interviews and reviews

- Use `Set`/`Map` for membership checks.
- Use sorting + two pointers instead of nested loops.
- Use binary search on sorted data.
- Avoid exponential recursion without memoization.

#### Space complexity too

Big O also describes memory:

```ts
function duplicate(arr: number[]): number[] {
  return arr.map(x => x * 2);
  // Time: O(n)
  // Space: O(n) for new array
}
```

---

### 5. How to actually use it in practice

Big O is a model, not a benchmark. For real TypeScript code, combine it with measurement:

```ts
function measure<T>(label: string, fn: () => T): T {
  const start = performance.now();
  const result = fn();
  const end = performance.now();
  console.log(`${label}: ${(end - start).toFixed(3)} ms`);
  return result;
}

measure("sort 100k", () => Array.from({ length: 100_000 }, () => Math.random()).sort((a, b) => a - b));
```

Practical rules:

1. **Don’t optimize cold code.** Profile first.
2. **Prefer asymptotically better algorithms for large inputs**, even if constants are slightly worse.
3. **Be honest about constants**: `O(n)` with a huge constant can lose to `O(n^2)` for small `n`.
4. **Consider worst-case and average-case separately**, especially for hash-based structures (`Map`, `Set`, object lookups).
5. **Watch hidden costs**: spreading arrays, string concatenation in loops, deep cloning, JSON serialization, React re-rending.

---

### Summary

In TypeScript, Big O is mostly communicated through comments and design decisions. The notation itself is just `O(f(n))`, but its value comes from recognizing patterns: one loop is usually `O(n)`, nested loops over the same input are often `O(n^2)`, divide-and-conquer is often `O(n log n)`, and naive recursion can explode to `O(2^n)`. Use it to pick better algorithms and data structures, then verify with real measurements.

## Mistake: O(n·m) lookup inside a loop

```ts
// ❌ Mistake: O(n * m) because `includes` scans `allowed` every iteration
function filterAllowed(items: string[], allowed: string[]): string[] {
  const result: string[] = [];
  for (const item of items) {
    if (allowed.includes(item)) {   // O(m) each time
      result.push(item);
    }
  }
  return result;
}
```

## Corrected version

```ts
// ✅ Corrected: O(n + m) using a Set for O(1) membership tests
function filterAllowed(items: string[], allowed: string[]): string[] {
  const allowedSet = new Set(allowed); // O(m)
  const result: string[] = [];
  for (const item of items) {         // O(n)
    if (allowedSet.has(item)) {       // O(1) average
      result.push(item);
    }
  }
  return result;
}
```

## What was wrong and why

- **The mistake:** `Array.prototype.includes` performs a linear scan of `allowed` for every element of `items`. If `items` has length `n` and `allowed` has length `m`, the total work is roughly `n × m` — i.e. **O(n·m)**. In the worst case where both arrays grow together (`n ≈ m`), this degrades to **O(n²)**.
- **The fix:** Build a `Set` from `allowed` once. `Set.prototype.has` is **O(1)** on average (hash-based), so the whole pass becomes **O(n + m)** — linear in the total input size.
- **When it matters:** With small arrays the difference is negligible, but with thousands/millions of elements the quadratic version can be orders of magnitude slower and may cause timeouts or UI jank.
- **Trade-off:** The corrected version uses extra memory **O(m)** for the set. That’s the standard time–space trade-off: spend a bit of memory to gain a large time improvement. If memory is extremely tight and `m` is tiny, the original might be acceptable — but then you’d usually just sort + binary search (`O((n+m) log m)`) instead.

# Common Big-O Pitfalls in TypeScript

Below are the most frequent mistakes, each with a short "bad" vs "good" snippet and why it matters.

---

## 1. Treating `Array.includes` / `indexOf` as O(1)

They scan the array linearly.

```ts
// BAD: O(n) per call → O(n²) overall
function hasAll(items: string[], needles: string[]): boolean {
  return needles.every(n => items.includes(n));
}

// GOOD: O(n) build + O(1) lookup → O(n + m)
function hasAllFast(items: string[], needles: string[]): boolean {
  const set = new Set(items);
  return needles.every(n => set.has(n));
}
```

**Pitfall:** Forgetting that "membership test" is only O(1) for `Set`/`Map`, not arrays.

---

## 2. Using an Array as a Queue (`shift` / `unshift`)

Both are O(n) because elements must be re-indexed.

```ts
// BAD: O(n) per shift → O(n²) to drain
const queue: number[] = [1, 2, 3, 4, 5];
while (queue.length) {
  const x = queue.shift(); // O(n)
}

// GOOD: O(1) dequeue with a head pointer
class Queue<T> {
  private buf: T[] = [];
  private head = 0;
  push(v: T) { this.buf.push(v); }
  pop(): T | undefined {
    if (this.head >= this.buf.length) return undefined;
    return this.buf[this.head++];
  }
  get size() { return this.buf.length - this.head; }
}
```

---

## 3. Hidden O(n) inside a loop (nested array methods)

```ts
// BAD: find inside map → O(n·m)
const prices = new Map<string, number>(/* ... */);
function total(cart: { sku: string; qty: number }[]): number {
  return cart.reduce((s, line) => {
    const p = prices.get(line.sku);        // O(1) — fine
    return s + (p ?? 0) * line.qty;
  }, 0);
}

// WORSE variant people actually write:
function totalBad(cart: { sku: string; qty: number }[], catalog: { sku: string; price: number }[]): number {
  return cart.reduce((s, line) => {
    const item = catalog.find(c => c.sku === line.sku); // O(m) inside O(n)
    return s + (item?.price ?? 0) * line.qty;
  }, 0);
}
```

**Pitfall:** `find`, `filter`, `includes`, `indexOf` inside `map`/`reduce`/`forEach` multiply complexities.

---

## 4. Spread inside `reduce` → O(n²)

```ts
// BAD: each concat copies the accumulator → O(n²)
const flattened = chunks.reduce<number[]>((acc, c) => [...acc, ...c], []);

// GOOD: push in place → O(total elements)
const flattened2: number[] = [];
for (const c of chunks) flattened2.push(...c);

// or, if you need immutability, accept the cost consciously
```

---

## 5. String concatenation in a loop

Engines sometimes optimize, but you shouldn't rely on it; `Array.join` is the safe O(n).

```ts
// BAD (conceptually O(n²) without engine elision)
let s = "";
for (const w of words) s += w + " ";

// GOOD
const s2 = words.join(" ");
```

---

## 6. Object/Map keys: reference equality, not value equality

```ts
// PITFALL: two distinct objects are different keys
const m = new Map<{ id: number }, string>();
m.set({ id: 1 }, "a");
console.log(m.get({ id: 1 })); // undefined — O(n) scan won't save you

// GOOD: key by a primitive
const m2 = new Map<number, string>();
m2.set(1, "a");
console.log(m2.get(1)); // "a"

// If you must use objects, normalize to a string key
const key = (o: { id: number }) => `id:${o.id}`;
```

**Pitfall:** Assuming `Map` does deep equality; it does not. Worst case, a `Map` with bad hash distribution degrades to O(n) per op.

---

## 7. `Array.sort` costs and mutation

```ts
// Pitfalls:
// - sort mutates in place (often unexpected)
// - default sort coerces to string → wrong for numbers
// - O(n log n) time, O(n) extra space (engine-dependent)

const nums = [10, 2, 1];
const sorted = [...nums].sort((a, b) => a - b); // non-mutating, numeric
```

Also: sorting to then do `includes` (binary search) is only worth it if you query many times; one-off sort + binary search is O(n log n) vs O(n) linear scan.

---

## 8. Recursion without memoization → exponential blowup

```ts
// BAD: O(2^n)
function fib(n: number): number {
  if (n < 2) return n;
  return fib(n - 1) + fib(n - 2);
}

// GOOD: O(n) time, O(n) space (or O(1) with iteration)
const memo = new Map<number, number>();
function fibFast(n: number): number {
  if (n < 2) return n;
  const cached = memo.get(n);
  if (cached !== undefined) return cached;
  const v = fibFast(n - 1) + fibFast(n - 2);
  memo.set(n, v);
  return v;
}
```

**TS-specific:** deep recursion also risks stack overflow; convert to iterative for large n.

---

## 9. Type-level complexity (a TS-only pitfall)

TypeScript's type checker has its own complexity. Deeply nested conditional/mapped types can make compilation O(n²) or worse, or hit "Type instantiation is excessively deep" (TS2589).

```ts
// BAD: deeply recursive type → slow compile, possible TS2589
type DeepPartial<T> = T extends object
  ? { [K in keyof T]?: DeepPartial<T[K]> }
  : T;

// Mitigations:
// - limit depth with a counter type
// - avoid recursive types over large unions
// - use `unknown`/`any` boundaries to stop inference
```

This doesn't affect runtime Big-O but is a real "complexity" cost in TS codebases.

---

## 10. Ignoring space complexity / allocation pressure

```ts
// BAD: creates many intermediate arrays
function pipeline(data: number[]): number[] {
  return data
    .filter(x => x > 0)
    .map(x => x * 2)
    .sort((a, b) => a - b);
}

// GOOD when hot: single pass, pre-sized output
function pipelineFast(data: number[]): number[] {
  const out: number[] = [];
  for (const x of data) if (x > 0) out.push(x * 2);
  out.sort((a, b) => a - b);
  return out;
}
```

**Pitfall:** Big-O time analysis that ignores O(n) auxiliary space and GC pauses; in TS/JS, allocation is often the real bottleneck.

---

## 11. `delete` on arrays leaves holes

```ts
const a = [1, 2, 3];
delete a[1];          // a = [1, empty, 3]  — length still 3, O(1) but breaks iteration
// Better:
a.splice(1, 1);       // O(n) but correct
// Or mark as undefined and filter later
```

**Pitfall:** Thinking `delete arr[i]` is O(1) removal; it leaves a hole and `length` doesn't change.

---

## 12. Repeated `.length` is fine, but re-slicing isn't

```ts
// BAD: slice inside loop → O(n²)
for (let i = 0; i < arr.length; i++) {
  const tail = arr.slice(i); // O(n)
  // ...
}

// GOOD: iterate with index; use subarray views if needed
```

---

## 13. Mutating a Set/Map while iterating

```ts
const s = new Set([1, 2, 3]);
// BAD: modifying during for...of can skip/visit elements; spec says behavior is defined
// but it's error-prone and O(n) per delete anyway
for (const x of s) {
  if (x === 2) s.delete(x);
}

// GOOD: collect first, then mutate
const toDelete = [...s].filter(x => x === 2);
for (const x of toDelete) s.delete(x);
```

---

## 14. Using `JSON.stringify` for equality / hashing in hot paths

```ts
// BAD: O(n) per comparison, called O(n²) times in a loop
const seen = new Set<string>();
for (const o of objects) {
  const key = JSON.stringify(o);   // O(size of o)
  if (seen.has(key)) continue;
  seen.add(key);
}
```

**Pitfall:** Correct but expensive; prefer a canonical primitive key or a stable hash. Note `JSON.stringify` is also not a valid equality for `undefined`/functions/`Map`/`Set`.

---

## 15. Assuming `Set`/`Map` are always O(1)

They are **amortized** O(1). With adversarial or poorly-hashing keys (e.g., many objects that coerce to the same string, or huge integers), operations can degrade. In TS/JS, keys are compared by `SameValueZero`, and the engine's hash table handles collisions, but pathological inputs (hash flooding) are a known DoS vector. For untrusted input, consider bounding sizes.

---

## Quick checklist

| Symptom | Likely culprit |
|---|---|
| O(n²) where O(n) expected | `includes`/`find`/`indexOf` inside a loop |
| Slow queue processing | `shift`/`unshift` on arrays |
| Memory blowup | spread in `reduce`, intermediate arrays |
| Wrong numeric sort | default `sort()` (string coercion) |
| `undefined` lookups in `Map` | object keys compared by reference |
| Stack overflow | deep recursion; convert to iteration |
| Slow `tsc` | excessively deep recursive types |

**Bottom line:** In TypeScript/JavaScript, the biggest Big-O trap isn't the algorithm you chose—it's the *hidden* linear scans inside array methods and the cost of allocation/GC. Profile with `console.time`/Node's `--prof`, and prefer `Set`/`Map` for membership, index-based queues, and single-pass loops for hot paths.

# Exercise

**Task:** Write a TypeScript function `hasDiscountPair(prices: number[], target: number): boolean` that returns `true` if there exist **two distinct elements** in `prices` whose values sum exactly to `target`. Then:

1. State the Big-O time and space complexity of your first (naïve) version.
2. State the complexity of an optimized version.
3. Explain when the optimization is worth it.

---

## Step-by-step solution

### Step 1 — Naïve (brute-force) approach

Check every unordered pair.

```ts
function hasDiscountPairNaive(prices: number[], target: number): boolean {
  const n = prices.length;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (prices[i] + prices[j] === target) return true;
    }
  }
  return false;
}
```

**Complexity analysis**

- **Time:** The outer loop runs `n` times; the inner loop runs up to `n‑1, n‑2, …` times. Total comparisons ≈ `n(n-1)/2`, so **O(n²)**.
- **Space:** Only loop variables → **O(1)**.

This is simple and easy to verify, but it becomes slow for large catalogs (e.g., 100k prices → ~10¹⁰ operations).

### Step 2 — Optimized approach (hash set)

For each price `p`, we need `target - p` to already have been seen. A `Set` gives O(1) average lookup.

```ts
function hasDiscountPair(prices: number[], target: number): boolean {
  const seen = new Set<number>();
  for (const p of prices) {
    if (seen.has(target - p)) return true;
    seen.add(p);
  }
  return false;
}
```

**Complexity analysis**

- **Time:** Single pass, O(1) work per element → **O(n)** average.
- **Space:** Up to `n` stored values → **O(n)**.

Worst case (hash collisions) degrades to O(n²), but with a good hash function / modern engines this is rare in practice.

### Step 3 — When is the optimization worth it?

| Scenario | Prefer |
|---|---|
| Tiny arrays (n < ~50) or called rarely | Naïve (O(1) space, less overhead) |
| Large or repeated queries | Hash-set (O(n) time) |
| Memory-constrained, sorted input | Two-pointer: O(n log n) sort + O(n) scan, O(1) extra space |
| Need all pairs, not just existence | Either, but collect into results |

**Two-pointer variant** (if input may be sorted or you can sort a copy):

```ts
function hasDiscountPairTwoPointer(prices: number[], target: number): boolean {
  const a = [...prices].sort((x, y) => x - y);
  let lo = 0, hi = a.length - 1;
  while (lo < hi) {
    const sum = a[lo] + a[hi];
    if (sum === target) return true;
    if (sum < target) lo++;
    else hi--;
  }
  return false;
}
```

Complexity: **O(n log n)** time, **O(n)** space (for the copy; O(1) extra if sorting in place is acceptable).

### Edge cases to handle (both versions)

- `prices.length < 2` → no pair possible.
- Duplicates are fine: e.g., `prices = [3, 3]`, `target = 6` should be `true` (distinct indices). The hash-set version handles this because we check `seen` **before** adding the current element.
- `NaN`/`Infinity`: `NaN + x === NaN` never equals target unless target is `NaN`; usually inputs are finite. Add a guard if needed.

---

## Final solution

```ts
/**
 * Returns true if two distinct elements in `prices` sum to `target`.
 * Average time: O(n) | Space: O(n)
 */
export function hasDiscountPair(prices: number[], target: number): boolean {
  if (prices.length < 2) return false;

  const seen = new Set<number>();
  for (const price of prices) {
    if (seen.has(target - price)) return true;
    seen.add(price);
  }
  return false;
}
```

### Quick sanity checks

```ts
console.log(hasDiscountPair([1, 2, 3, 4], 7)); // true  (3+4)
console.log(hasDiscountPair([1, 2, 3, 4], 8)); // false
console.log(hasDiscountPair([3, 3], 6));       // true  (distinct indices)
console.log(hasDiscountPair([], 5));            // false
```

**Takeaway:** Big-O reasoning isn't just about “faster is better” — it's about matching the algorithm to constraints: data size, memory budget, and whether the input is already sorted.

## Big O Notation — Interview-Style Explanation

**Big O** describes how an algorithm’s runtime (or space) **grows as the input size `n` grows**.  
Key ideas interviewers expect:

1. **Asymptotic / upper bound** — worst-case-ish growth, ignoring constants.  
2. **Drop constants & lower-order terms** — `3n² + 5n + 7` → `O(n²)`.  
3. **Focus on dominant term** — the term that wins as `n → ∞`.  
4. **Time vs. space** — both can have their own Big O.  
5. **Best / Average / Worst** — Big O is usually worst-case; Big Ω is best, Big Θ is tight.

### Common complexities (fast → slow)

| Big O | Name | Example |
|---|---|---|
| `O(1)` | Constant | Array index access |
| `O(log n)` | Logarithmic | Binary search |
| `O(n)` | Linear | Single loop |
| `O(n log n)` | Linearithmic | Merge sort |
| `O(n²)` | Quadratic | Nested loops |
| `O(2ⁿ)` | Exponential | Naive Fibonacci |
| `O(n!)` | Factorial | Permutations |

### Rules of thumb
- **Nested loops over same input** → usually `O(n²)` (unless inner loop shrinks).
- **Divide input in half each step** → `O(log n)`.
- **Recurrence `T(n) = 2T(n/2) + O(n)`** → `O(n log n)` (Master Theorem).
- **Hash map lookup** → amortized `O(1)`.

---

## TypeScript Implementation

Below is a clean, well-commented module that:
1. Implements canonical examples for each complexity.
2. Provides a tiny benchmark harness.
3. Includes a **growth-rate classifier** that estimates Big O from measured timings (the “core” analytical piece).

```ts
// ============================================================================
// complexity.ts
// Canonical Big-O examples + a small growth-rate estimator.
// ============================================================================

export type Complexity =
  | "O(1)"
  | "O(log n)"
  | "O(n)"
  | "O(n log n)"
  | "O(n^2)"
  | "O(2^n)";

// ----------------------------------------------------------------------------
// 1. Constant time — O(1)
// ----------------------------------------------------------------------------
/** Returns the first element; work does not depend on n. */
export function constantTime(arr: readonly number[]): number {
  return arr.length > 0 ? arr[0] : 0;
}

// ----------------------------------------------------------------------------
// 2. Logarithmic time — O(log n)
// ----------------------------------------------------------------------------
/** Binary search on a sorted array; halves the search space each step. */
export function logarithmicTime(sorted: readonly number[], target: number): number {
  let lo = 0;
  let hi = sorted.length - 1;

  while (lo <= hi) {
    const mid = (lo + hi) >>> 1; // bitwise floor division
    if (sorted[mid] === target) return mid;
    if (sorted[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

// ----------------------------------------------------------------------------
// 3. Linear time — O(n)
// ----------------------------------------------------------------------------
/** Single pass; work grows linearly with input size. */
export function linearTime(arr: readonly number[]): number {
  let sum = 0;
  for (const value of arr) sum += value;
  return sum;
}

// ----------------------------------------------------------------------------
// 4. Linearithmic time — O(n log n)
// ----------------------------------------------------------------------------
/** Merge sort: divide (log n levels) × merge (n work per level). */
export function linearithmicTime(arr: readonly number[]): number[] {
  if (arr.length <= 1) return [...arr];

  const mid = arr.length >> 1;
  const left = linearithmicTime(arr.slice(0, mid));
  const right = linearithmicTime(arr.slice(mid));

  return merge(left, right);
}

function merge(left: number[], right: number[]): number[] {
  const out: number[] = [];
  let i = 0;
  let j = 0;

  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) out.push(left[i++]);
    else out.push(right[j++]);
  }
  // Append remainder (at most one is non-empty)
  while (i < left.length) out.push(left[i++]);
  while (j < right.length) out.push(right[j++]);

  return out;
}

// ----------------------------------------------------------------------------
// 5. Quadratic time — O(n^2)
// ----------------------------------------------------------------------------
/** All pairs; nested loops over the same n. */
export function quadraticTime(arr: readonly number[]): number {
  let count = 0;
  for (let i = 0; i < arr.length; i++) {
    for (let j = 0; j < arr.length; j++) {
      count += arr[i] * arr[j]; // any O(1) work
    }
  }
  return count;
}

// ----------------------------------------------------------------------------
// 6. Exponential time — O(2^n)
// ----------------------------------------------------------------------------
/** Naive Fibonacci: each call branches into two smaller calls. */
export function exponentialTime(n: number): number {
  if (n <= 1) return n;
  return exponentialTime(n - 1) + exponentialTime(n - 2);
}

// ============================================================================
// Benchmarking + Growth-Rate Estimation (the "core" analytical helper)
// ============================================================================

export interface Timing {
  n: number;
  ms: number;
}

/**
 * Measure a function that takes an input size `n` and performs work.
 * Runs multiple trials and returns the median to reduce noise.
 */
export function benchmark(
  makeInput: (n: number) => unknown,
  run: (input: unknown) => void,
  sizes: number[],
  trials = 5
): Timing[] {
  const results: Timing[] = [];

  for (const n of sizes) {
    const times: number[] = [];
    for (let t = 0; t < trials; t++) {
      const input = makeInput(n);
      const start = performance.now();
      run(input);
      times.push(performance.now() - start);
    }
    times.sort((a, b) => a - b);
    const median = times[Math.floor(times.length / 2)];
    results.push({ n, ms: median });
  }
  return results;
}

/**
 * Estimate Big O from a sequence of (n, time) measurements.
 *
 * Strategy: compare the ratio t(2n)/t(n) against theoretical ratios.
 *   O(1)        -> ratio ~ 1
 *   O(log n)    -> ratio ~ 1 + small
 *   O(n)        -> ratio ~ 2
 *   O(n log n)  -> ratio ~ 2 * (log(2n)/log n)  (slightly > 2)
 *   O(n^2)      -> ratio ~ 4
 *   O(2^n)      -> ratio ~ 2^n  (huge)
 *
 * We compute the median ratio across consecutive doublings and pick the
 * closest theoretical class.
 */
export function estimateComplexity(timings: Timing[]): Complexity {
  if (timings.length < 2) return "O(1)";

  // Build ratios t(n_{i+1}) / t(n_i) for consecutive measurements.
  const ratios: number[] = [];
  for (let i = 1; i < timings.length; i++) {
    const prev = timings[i - 1];
    const curr = timings[i];
    if (prev.ms > 0 && curr.n > prev.n) {
      ratios.push(curr.ms / prev.ms);
    }
  }
  if (ratios.length === 0) return "O(1)";

  ratios.sort((a, b) => a - b);
  const medianRatio = ratios[Math.floor(ratios.length / 2)];

  // Theoretical ratios for a doubling of n (n -> 2n).
  const candidates: { label: Complexity; ratio: number }[] = [
    { label: "O(1)", ratio: 1 },
    { label: "O(log n)", ratio: 1.1 }, // log grows slowly
    { label: "O(n)", ratio: 2 },
    { label: "O(n log n)", ratio: 2.2 }, // 2 * (log 2n / log n) ~ 2.1-2.3
    { label: "O(n^2)", ratio: 4 },
    { label: "O(2^n)", ratio: Infinity }, // handled separately
  ];

  // Detect exponential by super-polynomial blowup.
  if (medianRatio > 8) return "O(2^n)";

  // Pick closest candidate by absolute distance.
  let best: Complexity = "O(n)";
  let bestDist = Infinity;
  for (const c of candidates) {
    const dist = Math.abs(c.ratio - medianRatio);
    if (dist < bestDist) {
      bestDist = dist;
      best = c.label;
    }
  }
  return best;
}

// ============================================================================
// Demo
// ============================================================================
if (require.main === module) {
  const sizes = [256, 512, 1024, 2048, 4096];

  const cases: { name: string; fn: (n: number) => void }[] = [
    { name: "constant", fn: (n) => void constantTime(Array.from({ length: n })) },
    { name: "linear", fn: (n) => void linearTime(Array.from({ length: n })) },
    { name: "quadratic", fn: (n) => void quadraticTime(Array.from({ length: n }, (_, i) => i)) },
  ];

  for (const c of cases) {
    const t = benchmark((n) => Array.from({ length: n }), (input) => c.fn((input as number[]).length), sizes);
    console.log(c.name, "->", estimateComplexity(t), t);
  }
}
```

### How an interviewer might probe this
- **“Why drop constants?”** Because Big O is about growth, not exact speed; hardware/constants vary.
- **“Is hash map really O(1)?”** Amortized; worst-case `O(n)` with collisions.
- **“Recursion space complexity?”** Call stack counts — e.g., naive Fibonacci is `O(n)` space.
- **“Can you improve exponential Fibonacci?”** Yes: memoization → `O(n)` time / `O(n)` space, or iterative → `O(n)` time / `O(1)` space.

### Takeaway
Big O is a **language for comparing scalability**, not a stopwatch. The code above gives you both the **canonical implementations** and a **practical estimator** to verify growth rates empirically.

When you use Big-O in TypeScript, the main edge cases come from the fact that **TypeScript types are erased at runtime**, while **JavaScript engines (V8, etc.) have non-obvious costs** for apparently simple operations. Big-O describes growth, but the *real* cost often hides in array reindexing, prototype traversal, regex backtracking, closure capture, async scheduling, or numeric representation.

Below are important edge cases, with TypeScript examples.

---

## 1. “O(1)” array operations that are actually O(n)

`Array.prototype.shift`, `unshift`, and `splice` reindex elements.

```ts
// Looks like a queue, but dequeue is O(n)
class BadQueue<T> {
  private items: T[] = [];

  enqueue(x: T): void {
    this.items.push(x); // O(1) amortized
  }

  dequeue(): T | undefined {
    return this.items.shift(); // O(n): reindexes every element
  }
}

// Better: keep a head pointer
class Queue<T> {
  private items: T[] = [];
  private head = 0;

  enqueue(x: T): void {
    this.items.push(x);
  }

  dequeue(): T | undefined {
    if (this.head >= this.items.length) return undefined;
    const value = this.items[this.head++];
    // Optional cleanup to avoid unbounded memory
    if (this.head > 1024 && this.head * 2 > this.items.length) {
      this.items = this.items.slice(this.head);
      this.head = 0;
    }
    return value; // O(1) amortized
  }
}
```

Similarly, `arr.splice(i, 1)` inside a loop can turn an O(n) algorithm into O(n²).

---

## 2. Nested loops hidden inside array methods

`includes`, `indexOf`, `find`, and `some` are O(n), so using them inside a loop creates O(n·m).

```ts
// O(n * m)
function hasCommonSlow(a: string[], b: string[]): boolean {
  return a.some(x => b.includes(x));
}

// O(n + m) using a Set
function hasCommonFast(a: string[], b: string[]): boolean {
  const set = new Set(b);
  return a.some(x => set.has(x)); // Set.has is O(1) average
}
```

Also watch `filter` + `includes`:

```ts
// O(n * m)
const uniqueish = a.filter(x => b.includes(x));

// O(n + m)
const bSet = new Set(b);
const unique = a.filter(x => bSet.has(x));
```

---

## 3. String concatenation in loops

Repeated `+=` can be quadratic in some engines/contexts, especially with large strings. Use an array and `join`.

```ts
// Risky for very large n
function buildStringSlow(parts: string[]): string {
  let result = "";
  for (const part of parts) {
    result += part; // may allocate/copy repeatedly
  }
  return result;
}

// Safer: O(total length)
function buildStringFast(parts: string[]): string {
  return parts.join("");
}
```

---

## 4. Recursion depth and stack overflow

TypeScript compiles to JavaScript; engines do not guarantee tail-call optimization. An O(n) recursive algorithm can crash with “Maximum call stack size exceeded.”

```ts
// O(n) time, but O(n) call stack
function sumRecursive(n: number): number {
  if (n <= 0) return 0;
  return n + sumRecursive(n - 1);
}

// O(n) time, O(1) extra stack
function sumIterative(n: number): number {
  let total = 0;
  for (let i = 1; i <= n; i++) total += i;
  return total;
}
```

For tree/graph traversal, recursion is convenient but may overflow on deep inputs. Use an explicit stack:

```ts
type Node = { value: number; children: Node[] };

function dfsIterative(root: Node): number[] {
  const result: number[] = [];
  const stack: Node[] = [root];

  while (stack.length > 0) {
    const node = stack.pop()!;
    result.push(node.value);
    // Push children in reverse if order matters
    for (let i = node.children.length - 1; i >= 0; i--) {
      stack.push(node.children[i]);
    }
  }
  return result;
}
```

---

## 5. Regex catastrophic backtracking (ReDoS)

A regex that looks linear can be exponential.

```ts
// Dangerous: nested quantifiers
const bad = /^(a+)+$/;

function isMatchSlow(input: string): boolean {
  return bad.test(input); // exponential on "aaaa...!"
}

// Safer: avoid nested quantifiers / use atomic-ish patterns
const safer = /^a+$/;

function isMatchFast(input: string): boolean {
  return safer.test(input);
}
```

If you must validate complex input, consider a parser or a regex engine with backtracking limits. Never run untrusted regexes on untrusted input without timeouts/sandboxing.

---

## 6. BigInt is not constant-time for large values

`number` is a 64-bit float, so arithmetic is effectively O(1). `bigint` operations grow with the number of machine words.

```ts
// For huge n, Fibonacci values grow exponentially in digit count
function fibBigInt(n: number): bigint {
  let a = 0n, b = 1n;
  for (let i = 0; i < n; i++) {
    [a, b] = [b, a + b]; // bigint addition cost grows with size
  }
  return a;
}
```

Big-O in terms of *n* is misleading here; the cost also depends on the size of the integers. For cryptographic/large-integer work, use specialized libraries and measure.

---

## 7. Object enumeration includes prototype-chain pitfalls

`for...in` enumerates inherited enumerable properties, so complexity and correctness depend on the prototype chain.

```ts
const base = { inherited: 1 };
const obj = Object.create(base);
obj.own = 2;

// Includes "inherited" — O(properties + prototype chain)
for (const key in obj) {
  console.log(key);
}

// Own enumerable keys only
for (const key of Object.keys(obj)) {
  console.log(key);
}

// Own all string/symbol keys
for (const key of Reflect.ownKeys(obj)) {
  console.log(key);
}
```

Also, `delete obj.key` can deoptimize hidden classes in V8, making later property access slower. For frequent add/remove, prefer `Map`.

---

## 8. Map/Set vs Object for dynamic keys

Objects are optimized for stable shapes. Maps are better for frequent insertion/deletion and non-string keys.

```ts
// Object: good for fixed schema, risky for dynamic deletion
const cache: Record<string, number> = {};
cache["a"] = 1;
delete cache["a"]; // may deoptimize

// Map: O(1) amortized get/set/delete, predictable
const map = new Map<string, number>();
map.set("a", 1);
map.delete("a");
```

Also note: `Map.size` is O(1), while computing object size via `Object.keys(obj).length` is O(n).

---

## 9. Sparse arrays and “length” vs actual elements

`new Array(n)` creates holes. Many methods skip holes, so complexity is often in terms of *actual elements*, not `length`.

```ts
const sparse = new Array(1_000_000); // length 1e6, but no elements

// Iterates over holes? forEach skips holes
sparse.forEach(x => console.log(x)); // O(actual elements) = O(0) here

// fill makes it dense
const dense = new Array(1_000_000).fill(0);
dense.forEach(x => console.log(x)); // O(n)
```

Be careful when Big-O is expressed in terms of `arr.length` for sparse arrays.

---

## 10. Sorting: comparator cost and mutation

`Array.prototype.sort` is O(n log n), but if the comparator is expensive, total cost multiplies. It also mutates in place.

```ts
type Item = { id: number; score: number };

// Comparator does O(k) work; total O(n log n * k)
function sortByExpensive(items: Item[]): Item[] {
  return items.slice().sort((a, b) => {
    const aRank = computeRank(a); // expensive
    const bRank = computeRank(b);
    return aRank - bRank;
  });
}

// Precompute ranks: O(n * k + n log n)
function sortByPrecomputed(items: Item[]): Item[] {
  const ranked = items.map(item => ({ item, rank: computeRank(item) }));
  ranked.sort((a, b) => a.rank - b.rank);
  return ranked.map(x => x.item);
}

function computeRank(item: Item): number {
  // placeholder expensive computation
  return item.score * 42;
}
```

Also, the comparator must be consistent. Inconsistent comparators (e.g., returning random values) can produce engine-dependent, sometimes O(n²)-ish behavior or incorrect results.

---

## 11. Async/await: sequential vs parallel complexity

A loop with `await` is O(n) in *latency*, even if each operation is O(1). `Promise.all` changes latency but increases memory/concurrency.

```ts
async function fetchSequential(urls: string[]): Promise<Response[]> {
  const results: Response[] = [];
  for (const url of urls) {
    results.push(await fetch(url)); // O(n) sequential latency
  }
  return results;
}

async function fetchParallel(urls: string[]): Promise<Response[]> {
  // O(1) batches in latency, but O(n) memory and n concurrent requests
  return Promise.all(urls.map(url => fetch(url)));
}

// Bounded concurrency: O(n / concurrency) latency, O(concurrency) memory
async function fetchBounded(urls: string[], limit: number): Promise<Response[]> {
  const results: Response[] = [];
  let index = 0;

  async function worker(): Promise<void> {
    while (index < urls.length) {
      const i = index++;
      results[i] = await fetch(urls[i]);
    }
  }

  await Promise.all(Array.from({ length: limit }, worker));
  return results;
}
```

Big-O in async code must distinguish CPU work, memory, and wall-clock latency.

---

## 12. Deep cloning and serialization

`structuredClone`, `JSON.parse(JSON.stringify(...))`, and recursive clones are O(size of graph), but also depend on depth and cyclic references.

```ts
type Tree = { value: number; children: Tree[] };

function cloneTreeSlow(root: Tree): Tree {
  return JSON.parse(JSON.stringify(root)); // O(size), but loses types/functions/dates
}

function cloneTreeFast(root: Tree): Tree {
  // Explicit clone avoids JSON overhead and preserves structure
  return {
    value: root.value,
    children: root.children.map(cloneTreeFast),
  };
}
```

`structuredClone` is usually better than JSON for preserving types, but still O(graph size) and can throw on non-cloneable values (functions, DOM nodes, etc.).

---

## 13. Type guards and validation cost

TypeScript types are erased, so runtime validation is your responsibility. A type guard can be O(1) or O(n) depending on depth.

```ts
type User = { id: number; tags: string[] };

// Shallow: O(1)
function isUserShallow(x: unknown): x is User {
  return (
    typeof x === "object" &&
    x !== null &&
    "id" in x &&
    typeof (x as any).id === "number" &&
    "tags" in x &&
    Array.isArray((x as any).tags)
  );
}

// Deep: O(n) in array length
function isUserDeep(x: unknown): x is User {
  if (!isUserShallow(x)) return false;
  return (x as User).tags.every(t => typeof t === "string");
}
```

If you use schema libraries (Zod, io-ts), their validation complexity matters and should be included in your Big-O reasoning.

---

## 14. Closures capturing large scopes

Creating many closures is O(n) in time and memory. Captured variables can also prevent garbage collection.

```ts
function makeHandlers(n: number): Array<() => number> {
  const bigData = new Array(n).fill(0); // captured by every closure
  const handlers: Array<() => number> = [];

  for (let i = 0; i < n; i++) {
    handlers.push(() => bigData[i] + i); // O(n) closures, O(n) retained memory
  }
  return handlers;
}

// Better: avoid capturing large shared data if not needed
function makeHandlersLean(n: number): Array<(i: number) => number> {
  return Array.from({ length: n }, (_, i) => (index: number) => index + i);
}
```

Big-O often ignores memory, but in TS/JS memory pressure affects GC pauses, which affect real runtime.

---

## 15. Weak collections are not size-iterable

`WeakMap` and `WeakSet` allow GC of keys, so they don’t expose size or iteration. Their “emptiness” is non-deterministic.

```ts
const weak = new WeakMap<object, number>();

function track(obj: object, value: number): void {
  weak.set(obj, value); // O(1) average
}

// Cannot do: weak.size or [...weak]
// If you need size/iteration, use Map (but then keys won't be GC'd)
const strong = new Map<object, number>();
```

This matters for caches: WeakMap gives O(1) lookup with automatic cleanup, but you cannot enumerate or bound size deterministically.

---

## Practical takeaway

When writing Big-O claims in TypeScript, specify:

1. **Input size metric**: `n` = array length? graph nodes? string length? value magnitude (for BigInt)?
2. **Average vs worst case**: hash maps/sets are average O(1), worst-case O(n).
3. **Hidden operations**: array shifting, string concatenation, regex backtracking, comparator cost.
4. **Stack depth**: recursion may be linear in stack space and can overflow.
5. **Async latency vs CPU work**: sequential awaits are linear in wall-clock time.
6. **Memory/GC**: closures, clones, and parallel promises all allocate O(n) memory.

A safe annotation style:

```ts
/**
 * Time: O(n + m) average, O(n * m) worst case if Set degrades
 * Space: O(m) for the set
 * Notes: Assumes string hashing is O(1); input arrays may be sparse.
 */
function intersection(a: string[], b: string[]): string[] {
  const set = new Set(b);
  return a.filter(x => set.has(x));
}
```

Here is a complete, runnable TypeScript implementation that treats binary data as a first-class concept. It provides:

- an immutable `Bytes` wrapper around `Uint8Array`
- hex/base64/UTF-8 conversions
- `ArrayBuffer` / typed-array interop
- `BinaryReader` and `BinaryWriter` for structured binary formats
- little/big-endian helpers via `DataView`
- a hex dump utility

## `bytes.ts`

```ts
// bytes.ts
// Run with: npx tsx bytes.ts

export type Byte = number;

function validateByte(value: number): void {
  if (!Number.isInteger(value) || value < 0 || value > 0xff) {
    throw new RangeError(`Expected a byte (0-255), got ${value}`);
  }
}

/* -------------------------------------------------------------------------- */
/* Base64 helpers                                                             */
/* -------------------------------------------------------------------------- */

const BASE64_ALPHABET =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function encodeBase64(
  input: Uint8Array,
  options?: { urlSafe?: boolean; padding?: boolean }
): string {
  const urlSafe = options?.urlSafe ?? false;
  const padding = options?.padding ?? true;
  const alphabet = urlSafe
    ? "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
    : BASE64_ALPHABET;

  let output = "";
  let i = 0;

  for (; i + 3 <= input.length; i += 3) {
    const value = (input[i] << 16) | (input[i + 1] << 8) | input[i + 2];
    output += alphabet[(value >>> 18) & 63];
    output += alphabet[(value >>> 12) & 63];
    output += alphabet[(value >>> 6) & 63];
    output += alphabet[value & 63];
  }

  const remaining = input.length - i;

  if (remaining === 1) {
    const value = input[i] << 16;
    output += alphabet[(value >>> 18) & 63];
    output += alphabet[(value >>> 12) & 63];
    if (padding) output += "==";
  } else if (remaining === 2) {
    const value = (input[i] << 16) | (input[i + 1] << 8);
    output += alphabet[(value >>> 18) & 63];
    output += alphabet[(value >>> 12) & 63];
    output += alphabet[(value >>> 6) & 63];
    if (padding) output += "=";
  }

  return output;
}

function decodeBase64Char(char: string): number {
  const code = char.charCodeAt(0);
  if (code >= 65 && code <= 90) return code - 65;      // A-Z
  if (code >= 97 && code <= 122) return code - 71;     // a-z
  if (code >= 48 && code <= 57) return code + 4;       // 0-9
  if (char === "+") return 62;
  if (char === "/") return 63;
  throw new Error(`Invalid base64 character: ${JSON.stringify(char)}`);
}

function decodeBase64(input: string): Uint8Array {
  const cleaned = input.replace(/\s+/g, "");
  let text = cleaned.replace(/-/g, "+").replace(/_/g, "/");

  if (text.length % 4 === 1) {
    throw new Error("Invalid base64 length");
  }

  while (text.length % 4 !== 0) text += "=";

  const paddingCount = text.endsWith("==") ? 2 : text.endsWith("=") ? 1 : 0;
  const outputLength = (text.length * 3) / 4 - paddingCount;

  if (outputLength < 0) throw new Error("Invalid base64 input");

  const output = new Uint8Array(outputLength);
  let offset = 0;

  for (let i = 0; i < text.length; i += 4) {
    const a = decodeBase64Char(text[i]);
    const b = decodeBase64Char(text[i + 1]);
    const cChar = text[i + 2];
    const dChar = text[i + 3];

    const c = cChar === "=" ? 0 : decodeBase64Char(cChar);
    const d = dChar === "=" ? 0 : decodeBase64Char(dChar);

    const value = (a << 18) | (b << 12) | (c << 6) | d;

    if (offset < outputLength) output[offset++] = (value >>> 16) & 0xff;
    if (offset < outputLength) output[offset++] = (value >>> 8) & 0xff;
    if (offset < outputLength) output[offset++] = value & 0xff;
  }

  return output;
}

/* -------------------------------------------------------------------------- */
/* Bytes                                                                      */
/* -------------------------------------------------------------------------- */

export class Bytes {
  private constructor(private readonly data: Uint8Array) {}

  static fromUint8Array(input: Uint8Array): Bytes {
    return new Bytes(new Uint8Array(input));
  }

  static fromArrayBuffer(
    buffer: ArrayBuffer,
    byteOffset = 0,
    byteLength?: number
  ): Bytes {
    const view = new Uint8Array(buffer, byteOffset, byteLength);
    return new Bytes(new Uint8Array(view));
  }

  static fromArray(values: readonly number[]): Bytes {
    const out = new Uint8Array(values.length);
    values.forEach((value, index) => {
      if (!Number.isInteger(value) || value < 0 || value > 0xff) {
        throw new RangeError(`Invalid byte at index ${index}: ${value}`);
      }
      out[index] = value;
    });
    return new Bytes(out);
  }

  static fromString(text: string): Bytes {
    return new Bytes(new TextEncoder().encode(text));
  }

  static fromHex(hex: string): Bytes {
    const cleaned = hex
      .trim()
      .replace(/\s+/g, "")
      .replace(/^0x/i, "");

    if (cleaned.length % 2 !== 0) {
      throw new Error("Hex string must have an even number of characters");
    }

    const out = new Uint8Array(cleaned.length / 2);

    for (let i = 0; i < out.length; i++) {
      const byte = Number.parseInt(cleaned.slice(i * 2, i * 2 + 2), 16);
      if (Number.isNaN(byte)) {
        throw new Error(`Invalid hex at offset ${i * 2}`);
      }
      out[i] = byte;
    }

    return new Bytes(out);
  }

  static fromBase64(base64: string): Bytes {
    return new Bytes(decodeBase64(base64));
  }

  get length(): number {
    return this.data.length;
  }

  at(index: number): number {
    const i = index < 0 ? this.data.length + index : index;
    if (i < 0 || i >= this.data.length) {
      throw new RangeError("Index out of range");
    }
    return this.data[i];
  }

  toArray(): number[] {
    return Array.from(this.data);
  }

  toUint8Array(): Uint8Array {
    return this.data.slice();
  }

  get buffer(): ArrayBuffer {
    return this.data.buffer.slice(
      this.data.byteOffset,
      this.data.byteOffset + this.data.byteLength
    ) as ArrayBuffer;
  }

  slice(start = 0, end = this.length): Bytes {
    return new Bytes(this.data.slice(start, end));
  }

  concat(...others: readonly (Bytes | Uint8Array)[]): Bytes {
    const otherSizes = others.map((value) =>
      value instanceof Bytes ? value.length : value.byteLength
    );
    const total = this.length + otherSizes.reduce((sum, n) => sum + n, 0);
    const out = new Uint8Array(total);

    out.set(this.data, 0);
    let offset = this.data.length;

    for (const other of others) {
      const view =
        other instanceof Bytes
          ? other.toUint8Array()
          : new Uint8Array(other.buffer, other.byteOffset, other.byteLength);

      out.set(view, offset);
      offset += view.length;
    }

    return new Bytes(out);
  }

  equals(other: Bytes | Uint8Array): boolean {
    const otherView =
      other instanceof Bytes
        ? other.toUint8Array()
        : new Uint8Array(other.buffer, other.byteOffset, other.byteLength);

    if (this.data.length !== otherView.length) return false;

    for (let i = 0; i < this.data.length; i++) {
      if (this.data[i] !== otherView[i]) return false;
    }

    return true;
  }

  toHex(): string {
    return Array.from(this.data)
      .map((byte) => byte.toString(16).padStart(2, "0"))
      .join("");
  }

  toBase64(options?: { urlSafe?: boolean; padding?: boolean }): string {
    return encodeBase64(this.data, options);
  }

  toString(): string {
    return new TextDecoder().decode(this.data);
  }

  [Symbol.iterator](): Iterator<number> {
    return this.data[Symbol.iterator]();
  }
}

/* -------------------------------------------------------------------------- */
/* Binary reader / writer                                                     */
/* -------------------------------------------------------------------------- */

export class BinaryReader {
  private readonly bytes: Uint8Array;
  private readonly view: DataView;
  private offsetValue: number;
  readonly littleEndian: boolean;

  constructor(
    data: Bytes | Uint8Array | ArrayBuffer,
    littleEndian = true,
    offset = 0
  ) {
    if (data instanceof Bytes) {
      this.bytes = data.toUint8Array();
    } else if (data instanceof ArrayBuffer) {
      this.bytes = new Uint8Array(data);
    } else {
      this.bytes = new Uint8Array(data);
    }

    this.view = new DataView(this.bytes.buffer);
    this.littleEndian = littleEndian;

    if (!Number.isInteger(offset) || offset < 0 || offset > this.bytes.length) {
      throw new RangeError("Invalid initial offset");
    }

    this.offsetValue = offset;
  }

  get offset(): number {
    return this.offsetValue;
  }

  set offset(value: number) {
    if (!Number.isInteger(value) || value < 0 || value > this.bytes.length) {
      throw new RangeError("Offset out of range");
    }
    this.offsetValue = value;
  }

  get remaining(): number {
    return this.bytes.length - this.offsetValue;
  }

  private ensure(size: number): void {
    if (this.offsetValue + size > this.bytes.length) {
      throw new RangeError("Unexpected end of binary data");
    }
  }

  readUint8(): number {
    this.ensure(1);
    return this.view.getUint8(this.offsetValue++);
  }

  readInt8(): number {
    this.ensure(1);
    return this.view.getInt8(this.offsetValue++);
  }

  readUint16(littleEndian = this.littleEndian): number {
    this.ensure(2);
    const value = this.view.getUint16(this.offsetValue, littleEndian);
    this.offsetValue += 2;
    return value;
  }

  readInt16(littleEndian = this.littleEndian): number {
    this.ensure(2);
    const value = this.view.getInt16(this.offsetValue, littleEndian);
    this.offsetValue += 2;
    return value;
  }

  readUint32(littleEndian = this.littleEndian): number {
    this.ensure(4);
    const value = this.view.getUint32(this.offsetValue, littleEndian);
    this.offsetValue += 4;
    return value;
  }

  readInt32(littleEndian = this.littleEndian): number {
    this.ensure(4);
    const value = this.view.getInt32(this.offsetValue, littleEndian);
    this.offsetValue += 4;
    return value;
  }

  readFloat32(littleEndian = this.littleEndian): number {
    this.ensure(4);
    const value = this.view.getFloat32(this.offsetValue, littleEndian);
    this.offsetValue += 4;
    return value;
  }

  readFloat64(littleEndian = this.littleEndian): number {
    this.ensure(8);
    const value = this.view.getFloat64(this.offsetValue, littleEndian);
    this.offsetValue += 8;
    return value;
  }

  readUint64(littleEndian = this.littleEndian): bigint {
    this.ensure(8);
    const value = this.view.getBigUint64(this.offsetValue, littleEndian);
    this.offsetValue += 8;
    return value;
  }

  readInt64(littleEndian = this.littleEndian): bigint {
    this.ensure(8);
    const value = this.view.getBigInt64(this.offsetValue, littleEndian);
    this.offsetValue += 8;
    return value;
  }

  readBytes(length: number): Bytes {
    if (!Number.isInteger(length) || length < 0) {
      throw new RangeError("Invalid byte length");
    }
    this.ensure(length);
    const result = this.bytes.slice(this.offsetValue, this.offsetValue + length);
    this.offsetValue += length;
    return Bytes.fromUint8Array(result);
  }

  readUtf8(length?: number): string {
    const count = length ?? this.remaining;
    return this.readBytes(count).toString();
  }

  readCString(maxLength = this.remaining): string {
    const start = this.offsetValue;
    const limit = Math.min(this.bytes.length, start + maxLength);

    let end = start;
    while (end < limit && this.bytes[end] !== 0) end++;

    const text = new TextDecoder().decode(this.bytes.subarray(start, end));

    this.offsetValue =
      end < this.bytes.length && this.bytes[end] === 0 ? end + 1 : end;

    return text;
  }

  skip(length: number): void {
    const next = this.offsetValue + length;
    if (next < 0 || next > this.bytes.length) {
      throw new RangeError("Skip out of range");
    }
    this.offsetValue = next;
  }
}

export class BinaryWriter {
  private buffer: Uint8Array;
  private view: DataView;
  private offsetValue = 0;
  readonly littleEndian: boolean;

  constructor(initialCapacity = 64, littleEndian = true) {
    this.buffer = new Uint8Array(Math.max(1, initialCapacity));
    this.view = new DataView(this.buffer.buffer);
    this.littleEndian = littleEndian;
  }

  get offset(): number {
    return this.offsetValue;
  }

  get capacity(): number {
    return this.buffer.length;
  }

  private ensure(additional: number): void {
    if (this.offsetValue + additional <= this.buffer.length) return;

    let newCapacity = this.buffer.length || 1;
    while (this.offsetValue + additional > newCapacity) {
      newCapacity *= 2;
    }

    const next = new Uint8Array(newCapacity);
    next.set(this.buffer.subarray(0, this.offsetValue));
    this.buffer = next;
    this.view = new DataView(next.buffer);
  }

  writeUint8(value: number): void {
    if (!Number.isInteger(value) || value < 0 || value > 0xff) {
      throw new RangeError("Value must fit in uint8");
    }
    this.ensure(1);
    this.view.setUint8(this.offsetValue++, value);
  }

  writeInt8(value: number): void {
    if (!Number.isInteger(value) || value < -128 || value > 127) {
      throw new RangeError("Value must fit in int8");
    }
    this.ensure(1);
    this.view.setInt8(this.offsetValue++, value);
  }

  writeUint16(value: number, littleEndian = this.littleEndian): void {
    if (!Number.isInteger(value) || value < 0 || value > 0xffff) {
      throw new RangeError("Value must fit in uint16");
    }
    this.ensure(2);
    this.view.setUint16(this.offsetValue, value, littleEndian);
    this.offsetValue += 2;
  }

  writeInt16(value: number, littleEndian = this.littleEndian): void {
    if (!Number.isInteger(value) || value < -32768 || value > 32767) {
      throw new RangeError("Value must fit in int16");
    }
    this.ensure(2);
    this.view.setInt16(this.offsetValue, value, littleEndian);
    this.offsetValue += 2;
  }

  writeUint32(value: number, littleEndian = this.littleEndian): void {
    if (!Number.isInteger(value) || value < 0 || value > 0xffffffff) {
      throw new RangeError("Value must fit in uint32");
    }
    this.ensure(4);
    this.view.setUint32(this.offsetValue, value, littleEndian);
    this.offsetValue += 4;
  }

  writeInt32(value: number, littleEndian = this.littleEndian): void {
    if (!Number.isInteger(value) || value < -2147483648 || value > 2147483647) {
      throw new RangeError("Value must fit in int32");
    }
    this.ensure(4);
    this.view.setInt32(this.offsetValue, value, littleEndian);
    this.offsetValue += 4;
  }

  writeFloat32(value: number, littleEndian = this.littleEndian): void {
    this.ensure(4);
    this.view.setFloat32(this.offsetValue, value, littleEndian);
    this.offsetValue += 4;
  }

  writeFloat64(value: number, littleEndian = this.littleEndian): void {
    this.ensure(8);
    this.view.setFloat64(this.offsetValue, value, littleEndian);
    this.offsetValue += 8;
  }

  writeUint64(value: bigint, littleEndian = this.littleEndian): void {
    this.ensure(8);
    this.view.setBigUint64(this.offsetValue, value, littleEndian);
    this.offsetValue += 8;
  }

  writeInt64(value: bigint, littleEndian = this.littleEndian): void {
    this.ensure(8);
    this.view.setBigInt64(this.offsetValue, value, littleEndian);
    this.offsetValue += 8;
  }

  writeBytes(value: Bytes | Uint8Array | ArrayBuffer): void {
    let source: Uint8Array;

    if (value instanceof Bytes) {
      source = value.toUint8Array();
    } else if (value instanceof ArrayBuffer) {
      source = new Uint8Array(value);
    } else {
      source = new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
    }

    this.ensure(source.length);
    this.buffer.set(source, this.offsetValue);
    this.offsetValue += source.length;
  }

  writeUtf8(text: string): void {
    this.writeBytes(Bytes.fromString(text));
  }

  toBytes(): Bytes {
    return Bytes.fromUint8Array(this.buffer.subarray(0, this.offsetValue));
  }

  toUint8Array(): Uint8Array {
    return this.buffer.slice(0, this.offsetValue);
  }
}

/* -------------------------------------------------------------------------- */
/* Hex dump                                                                   */
/* -------------------------------------------------------------------------- */

export function hexDump(
  data: Bytes | Uint8Array,
  options?: { bytesPerLine?: number; offset?: number }
): string {
  const bytes =
    data instanceof Bytes
      ? data.toUint8Array()
      : new Uint8Array(data.buffer, data.byteOffset, data.byteLength);

  const bytesPerLine = options?.bytesPerLine ?? 16;
  const baseOffset = options?.offset ?? 0;
  const lines: string[] = [];

  for (let i = 0; i < bytes.length; i += bytesPerLine) {
    const chunk = bytes.subarray(i, i + bytesPerLine);

    const hex = Array.from(chunk)
      .map((byte) => byte.toString(16).padStart(2, "0"))
      .join(" ");

    const ascii = Array.from(chunk)
      .map((byte) => (byte >= 32 && byte <= 126 ? String.fromCharCode(byte) : "."))
      .join("");

    lines.push(
      `${(baseOffset + i).toString(16).padStart(8, "0")}  ` +
        `${hex.padEnd(bytesPerLine * 3 - 1, " ")}  |${ascii}|`
    );
  }

  return lines.join("\n");
}

/* -------------------------------------------------------------------------- */
/* Example                                                                    */
/* -------------------------------------------------------------------------- */

function main(): void {
  // 1. Create bytes from different sources.
  const textBytes = Bytes.fromString("Hello, binary world! 🌍");
  const hexBytes = Bytes.fromHex("48 65 6c 6c 6f");
  const base64Bytes = Bytes.fromBase64("SGVsbG8=");

  console.log("text:", textBytes.toString());
  console.log("length:", textBytes.length);
  console.log("hex:", textBytes.toHex());
  console.log("base64:", textBytes.toBase64());

  // 2. Round trips.
  console.log("hex roundtrip:", Bytes.fromHex(textBytes.toHex()).equals(textBytes));
  console.log("base64 roundtrip:", Bytes.fromBase64(textBytes.toBase64()).equals(textBytes));
  console.log("hexBytes equals 'Hello':", hexBytes.equals(Bytes.fromString("Hello")));
  console.log("base64Bytes equals 'Hello':", base64Bytes.equals(Bytes.fromString("Hello")));

  // 3. Concatenation and slicing.
  const combined = Bytes.fromArray([1, 2, 3]).concat(
    Bytes.fromArray([4, 5]),
    new Uint8Array([6, 7])
  );

  console.log("combined:", combined.toArray());
  console.log("slice(1, 4):", combined.slice(1, 4).toArray());
  console.log("last byte via at(-1):", combined.at(-1));

  // 4. Write a small structured binary record.
  const writer = new BinaryWriter(64, true);

  writer.writeUtf8("RIFF");
  writer.writeUint32(0x00001234);
  writer.writeUtf8("WAVE");
  writer.writeUint16(1);      // audio format
  writer.writeUint16(2);      // channels
  writer.writeUint32(44100);  // sample rate
  writer.writeFloat64(3.141592653589793);

  const record = writer.toBytes();

  // 5. Read it back.
  const reader = new BinaryReader(record);

  console.log("\nStructured read:");
  console.log("tag:", reader.readUtf8(4));
  console.log("size:", "0x" + reader.readUint32().toString(16));
  console.log("format tag:", reader.readUtf8(4));
  console.log("audio format:", reader.readUint16());
  console.log("channels:", reader.readUint16());
  console.log("sample rate:", reader.readUint32());
  console.log("pi:", reader.readFloat64());

  // 6. Inspect bytes.
  console.log("\nHex dump:");
  console.log(hexDump(record));

  // 7. Endianness example.
  const endianWriter = new BinaryWriter(8, false); // big-endian
  endianWriter.writeUint32(0x12345678);
  const endianBytes = endianWriter.toBytes();

  const endianReader = new BinaryReader(endianBytes, false);
  console.log("\nbig-endian uint32:", "0x" + endianReader.readUint32().toString(16));
  console.log("raw bytes:", endianBytes.toHex());
}

main();
```

