## Browser file and stream examples

### Blob and File

```ts
const bytes = new Uint8Array([0x89, 0x50, 0x4e, 0x47]); // PNG-ish magic bytes

const blob = new Blob([bytes], { type: "application/octet-stream" });
const file = new File([blob], "data.bin", { type: blob.type });
```

### Fetch binary data

```ts
async function loadBytes(url: string): Promise<Uint8Array> {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);

  const buffer = await response.arrayBuffer();
  return new Uint8Array(buffer);
}
```

### Stream chunks

```ts
async function readStream(stream: ReadableStream<Uint8Array>) {
  const reader = stream.getReader();

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    console.log("chunk bytes:", value.length);
  }
}
```

