## Parsing a tiny binary format

```ts
type Header = {
  magic: number;
  version: number;
  flags: number;
};

function parseHeader(buffer: ArrayBuffer): Header {
  const v = new DataView(buffer);

  return {
    magic: v.getUint32(0, true),
    version: v.getUint16(4, true),
    flags: v.getUint8(6),
  };
}

// Example: build bytes for the parser
const buf = new ArrayBuffer(8);
const v = new DataView(buf);
v.setUint32(0, 0x4d59464d, true); // "MYFM" little-endian-ish
v.setUint16(4, 1, true);
v.setUint8(6, 0b00000011);

console.log(parseHeader(buf));
```

