Here is a complete, type-safe TypeScript implementation of binary search. It supports primitive arrays directly and accepts a comparator for objects or custom ordering. It returns the index of a match, or `-1` if the target is not present.

```ts
// binary-search.ts

export type Comparator<T> = (a: T, b: T) => number;

// Overload: custom comparator.
export function binarySearch<T>(
  sortedArray: readonly T[],
  target: T,
  compare: Comparator<T>
): number;

// Overload: primitive arrays can use the natural ordering.
export function binarySearch<T extends number | string | bigint>(
  sortedArray: readonly T[],
  target: T
): number;

// Implementation.
export function binarySearch<T>(
  sortedArray: readonly T[],
  target: T,
  compare?: Comparator<T>
): number {
  if (!Array.isArray(sortedArray)) {
    throw new TypeError("sortedArray must be an array");
  }

  // Fall back to natural ordering for primitives when no comparator is given.
  const cmp: Comparator<T> =
    compare ?? ((a: any, b: any) => (a < b ? -1 : a > b ? 1 : 0));

  let left = 0;
  let right = sortedArray.length - 1;

  while (left <= right) {
    // Avoids potential overflow in languages with fixed-width integers.
    const mid = left + Math.floor((right - left) / 2);

    const result = cmp(sortedArray[mid], target);

    if (result === 0) {
      return mid;
    }

    if (result < 0) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return -1;
}

// Runnable examples and basic assertions.
if (require.main === module) {
  const numbers = [1, 3, 5, 7, 9, 11];

  console.assert(binarySearch(numbers, 7) === 3, "found middle value");
  console.assert(binarySearch(numbers, 1) === 0, "found first value");
  console.assert(binarySearch(numbers, 11) === 5, "found last value");
  console.assert(binarySearch(numbers, 4) === -1, "missing value");
  console.assert(binarySearch([], 1) === -1, "empty array");

  const words = ["apple", "banana", "cherry", "date"];
  console.assert(binarySearch(words, "cherry") === 2, "string search");

  interface Person {
    id: number;
    name: string;
  }

  const people: Person[] = [
    { id: 1, name: "Ada" },
    { id: 3, name: "Grace" },
    { id: 5, name: "Margaret" },
  ];

  console.assert(
    binarySearch(people, { id: 3, name: "" }, (a, b) => a.id - b.id) === 1,
    "object search by id"
  );

  console.log("All binary search checks passed.");
}
```

