### Design notes

- **Generic type `T`** makes the tree reusable for numbers, strings, or any comparable type.
- **Comparator injection** keeps the tree decoupled from the type’s ordering rules.
- **BST invariants**: for every node, left values are `<=` the node and right values are `>`.
- **Deletion** handles three cases: no child, one child, and two children. For two children it uses the inorder successor from the right subtree.
- **Complexity**: search/insert/delete are `O(h)` where `h` is height; traversals are `O(n)`. For a balanced tree `h ≈ log n`; for a degenerate tree `h = n - 1`.
- **Recursion depth**: recursive traversal/delete can stack-overflow on extremely deep trees. For production systems with arbitrary input, consider iterative traversal or a self-balancing tree such as AVL or red-black.

## Binary Trees in TypeScript

A **binary tree** is a recursive data structure where each node holds a value and up to two children: `left` and `right`.  
Common variants:

- **Plain binary tree** – arbitrary shape, used for expression trees, Huffman coding, etc.
- **Binary Search Tree (BST)** – left < node < right, enabling O(log n) search on balanced data.
- **Heap** – complete binary tree stored in an array (priority queues).
- **Trie / segment tree** – specialized binary trees.

---

### 1. Core idea & types

```ts
// Node definition with generics
interface TreeNode<T> {
  value: T;
  left: TreeNode<T> | null;
  right: TreeNode<T> | null;
}

// A tree is just a reference to its root (possibly null)
type BinaryTree<T> = TreeNode<T> | null;
```

Idiomatic TypeScript choices:
- Use **`null`** for “no child” (explicit absence) rather than `undefined`, so `node.left === null` is unambiguous.
- Use **generics** `<T>` so values can be numbers, strings, or objects.
- Use **`interface`** for the node shape and **`class`** when you want encapsulated behavior.

---

### 2. A minimal BST implementation

```ts
class BSTNode<T> {
  constructor(
    public value: T,
    public left: BSTNode<T> | null = null,
    public right: BSTNode<T> | null = null,
  ) {}
}

class BinarySearchTree<T> {
  private root: BSTNode<T> | null = null;

  constructor(private compare: (a: T, b: T) => number) {}

  insert(value: T): void {
    const node = new BSTNode(value);
    if (!this.root) {
      this.root = node;
      return;
    }
    let cur = this.root;
    while (true) {
      const cmp = this.compare(value, cur.value);
      if (cmp < 0) {
        if (!cur.left) { cur.left = node; return; }
        cur = cur.left;
      } else if (cmp > 0) {
        if (!cur.right) { cur.right = node; return; }
        cur = cur.right;
      } else {
        return; // duplicate policy: ignore
      }
    }
  }

  has(value: T): boolean {
    let cur = this.root;
    while (cur) {
      const cmp = this.compare(value, cur.value);
      if (cmp === 0) return true;
      cur = cmp < 0 ? cur.left : cur.right;
    }
    return false;
  }

  // In-order traversal yields sorted order for a BST
  *inOrder(): Generator<T> {
    function* visit(node: BSTNode<T> | null): Generator<T> {
      if (!node) return;
      yield* visit(node.left);
      yield node.value;
      yield* visit(node.right);
    }
    yield* visit(this.root);
  }
}
```

Usage:

```ts
const tree = new BinarySearchTree<number>((a, b) => a - b);
[5, 3, 7, 1, 4].forEach(n => tree.insert(n));

console.log([...tree.inOrder()]); // [1, 3, 4, 5, 7]
console.log(tree.has(4));         // true
```

---

### 3. Traversals (DFS & BFS)

Traversals are the most common operations; they differ in **when** the current node is visited.

```ts
function preorder<T>(node: TreeNode<T> | null, visit: (v: T) => void): void {
  if (!node) return;
  visit(node.value);          // root first
  preorder(node.left, visit);
  preorder(node.right, visit);
}

function inorder<T>(node: TreeNode<T> | null, visit: (v: T) => void): void {
  if (!node) return;
  inorder(node.left, visit);
  visit(node.value);          // root in middle
  inorder(node.right, visit);
}

function postorder<T>(node: TreeNode<T> | null, visit: (v: T) => void): void {
  if (!node) return;
  postorder(node.left, visit);
  postorder(node.right, visit);
  visit(node.value);          // root last
}

// Level-order (BFS) using a queue
function levelOrder<T>(root: TreeNode<T> | null): T[] {
  if (!root) return [];
  const result: T[] = [];
  const queue: TreeNode<T>[] = [root];
  while (queue.length) {
    const node = queue.shift()!;
    result.push(node.value);
    if (node.left) queue.push(node.left);
    if (node.right) queue.push(node.right);
  }
  return result;
}
```

**When to use which:**
- **Pre-order** – serialize/copy a tree, prefix expressions.
- **In-order** – sorted output from a BST, infix expressions.
- **Post-order** – delete/free a tree, postfix expressions, dependency resolution.
- **Level-order** – shortest path in unweighted tree, “by depth” processing.

---

### 4. Common derived operations

```ts
function height<T>(node: TreeNode<T> | null): number {
  if (!node) return 0;
  return 1 + Math.max(height(node.left), height(node.right));
}

function isBalanced<T>(node: TreeNode<T> | null): boolean {
  function check(n: TreeNode<T> | null): number {
    if (!n) return 0;
    const l = check(n.left);
    if (l === -1) return -1;
    const r = check(n.right);
    if (r === -1 || Math.abs(l - r) > 1) return -1;
    return 1 + Math.max(l, r);
  }
  return check(node) !== -1;
}

function mirror<T>(node: TreeNode<T> | null): TreeNode<T> | null {
  if (!node) return null;
  return {
    value: node.value,
    left: mirror(node.right),
    right: mirror(node.left),
  };
}
```

---

### 5. Functional / immutable style (often preferred in TS)

Instead of mutating nodes, return new trees. Useful for React state, undo/redo, or pure algorithms.

```ts
type Tree<T> = { value: T; left: Tree<T> | null; right: Tree<T> | null } | null;

const insert = <T>(cmp: (a: T, b: T) => number) =>
  (tree: Tree<T>, value: T): Tree<T> => {
    if (!tree) return { value, left: null, right: null };
    const c = cmp(value, tree.value);
    if (c < 0) return { ...tree, left: insert(cmp)(tree.left, value) };
    if (c > 0) return { ...tree, right: insert(cmp)(tree.right, value) };
    return tree; // duplicate
  };
```

---

### 6. Typical use cases

| Use case | Why a binary tree fits |
|---|---|
| **BST / ordered set** | O(log n) lookup/insert/delete when balanced (AVL, Red-Black). |
| **Expression parsing** | Parse tree nodes hold operators/operands; post-order evaluation. |
| **Huffman coding** | Build optimal prefix codes by merging lowest-frequency nodes. |
| **Decision trees** | ML classification: each node tests a feature, leaves hold labels. |
| **Filesystem / DOM** | Directory trees are n-ary, but binary search over sorted children. |
| **Segment / Fenwick trees** | Range queries (sum, min, max) in O(log n). |
| **Heaps** | Priority queues; usually array-backed but logically a complete binary tree. |

---

### 7. Practical caveats

- **Unbalanced BSTs degrade to O(n)** (e.g., inserting sorted data). Use self-balancing variants (AVL, Red-Black) or a skip list in production.
- **Recursion depth**: deep trees can stack-overflow; convert traversals to iterative with an explicit stack, or increase Node stack size.
- **Memory**: pointer-heavy; for heaps, prefer a flat `Array<T>` with index math (`left = 2*i+1`).
- **Serialization**: JSON.stringify works for plain objects but loses methods; store as `{ value, left, right }` and rebuild.

---

### Minimal heap example (array-backed binary tree)

```ts
class MinHeap<T> {
  private data: T[] = [];
  constructor(private compare: (a: T, b: T) => number) {}

  push(x: T) {
    this.data.push(x);
    this.bubbleUp(this.data.length - 1);
  }

  pop(): T | undefined {
    if (!this.data.length) return;
    const top = this.data[0];
    const last = this.data.pop()!;
    if (this.data.length) {
      this.data[0] = last;
      this.bubbleDown(0);
    }
    return top;
  }

  private bubbleUp(i: number) {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.compare(this.data[i], this.data[p]) >= 0) break;
      [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
      i = p;
    }
  }

  private bubbleDown(i: number) {
    const n = this.data.length;
    while (true) {
      let smallest = i;
      const l = 2 * i + 1, r = 2 * i + 2;
      if (l < n && this.compare(this.data[l], this.data[smallest]) < 0) smallest = l;
      if (r < n && this.compare(this.data[r], this.data[smallest]) < 0) smallest = r;
      if (smallest === i) break;
      [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]];
      i = smallest;
    }
  }
}
```

---

### Summary

- Model a node as `{ value, left, right }` (or a class) with `null` for missing children.
- Generics + a comparator function keep the tree reusable across types.
- Choose traversals by the order you need to process nodes.
- Prefer immutable updates for UI/state-heavy code; use mutation + balancing for performance-critical data structures.
- For heaps, use an array; for ordered sets, use a balanced BST or a sorted structure.

A very common binary-tree bug is **forgetting to reassign the recursively updated child** when inserting into a BST.

### Buggy version

```ts
class TreeNode {
  val: number;
  left: TreeNode | null;
  right: TreeNode | null;

  constructor(val: number) {
    this.val = val;
    this.left = null;
    this.right = null;
  }
}

function insert(root: TreeNode | null, value: number): TreeNode {
  if (root === null) {
    return new TreeNode(value);
  }

  if (value < root.val) {
    insert(root.left, value); // BUG: result is discarded
  } else if (value > root.val) {
    insert(root.right, value); // BUG: result is discarded
  }

  return root;
}

// Example usage
let root: TreeNode | null = null;
root = insert(root, 5);
insert(root, 3); // root.left stays null
insert(root, 7); // root.right stays null
```

### Corrected version

```ts
class TreeNode {
  val: number;
  left: TreeNode | null;
  right: TreeNode | null;

  constructor(val: number) {
    this.val = val;
    this.left = null;
    this.right = null;
  }
}

function insert(root: TreeNode | null, value: number): TreeNode {
  if (root === null) {
    return new TreeNode(value);
  }

  if (value < root.val) {
    root.left = insert(root.left, value); // FIX: reassign updated subtree
  } else if (value > root.val) {
    root.right = insert(root.right, value); // FIX: reassign updated subtree
  }

  // If value === root.val, do nothing, or handle duplicates explicitly.
  return root;
}

// Example usage
let root: TreeNode | null = null;
root = insert(root, 5);
root = insert(root, 3);
root = insert(root, 7);

console.log(root?.left?.val);  // 3
console.log(root?.right?.val); // 7
```

### What was wrong and why

In the buggy version, `insert` is recursive and returns the (possibly new) root of the subtree it processed. When the original tree is empty, the function correctly returns a new node. But when descending into an existing child, the caller throws that returned node away:

```ts
insert(root.left, value); // returned node is ignored
```

So if `root.left` was `null`, the new node is created inside the recursive call, returned, and then immediately discarded. The parent node never learns about it, and the tree appears unchanged. The same issue happens on the right side.

The fix is to assign the recursive result back to the corresponding child pointer:

```ts
root.left = insert(root.left, value);
```

This matters because:

1. **The base case creates a new node.** That new node must be linked into the existing tree.
2. **The recursion may replace a subtree root.** Even if you later refactor insertion to be iterative, the recursive style only works if every level connects the returned subtree.
3. **TypeScript’s nullability makes the bug easy to miss.** The compiler sees `root.left` as `TreeNode | null`, and passing it to `insert` is valid. It does not know that ignoring the result breaks the tree structure.
4. **The root itself must be reassigned at the top level.** That is why callers write `root = insert(root, value)` rather than just `insert(root, value)`.

A good mental model is: `insert(root, value)` means “return the root of the tree that contains `value`,” not “mutate `root` in place and return nothing.” If you want a purely mutating API, you would instead write an iterative version or make the function return `void` and handle the empty-tree case separately.

# Common Pitfalls When Working with Binary Trees in TypeScript

Below are the most frequent issues, each with a short explanation and working TypeScript code. I'll use this base type throughout:

```ts
interface TreeNode<T> {
  value: T;
  left: TreeNode<T> | null;
  right: TreeNode<T> | null;
}

function node<T>(value: T, left: TreeNode<T> | null = null, right: TreeNode<T> | null = null): TreeNode<T> {
  return { value, left, right };
}
```

---

## 1. `null` vs `undefined` inconsistency in child pointers

**Pitfall:** Mixing `left?: TreeNode` (optional, possibly `undefined`) with `left: TreeNode | null`. TypeScript narrows them differently, and `undefined` breaks most tree algorithms that expect `null`.

```ts
// ❌ Inconsistent
interface BadNode { value: number; left?: BadNode; right?: BadNode; }

function sizeBad(n: BadNode | undefined): number {
  if (!n) return 0;
  // n.left is BadNode | undefined — fine here, but...
  return 1 + sizeBad(n.left) + sizeBad(n.right);
}

// ✅ Consistent: always null
function size(n: TreeNode<number> | null): number {
  if (n === null) return 0;
  return 1 + size(n.left) + size(n.right);
}
```

**Rule:** Pick `null` for "no child" and stick to it. Use `| null`, never optional children, in recursive structures.

---

## 2. Forgetting the empty-tree base case

**Pitfall:** Algorithms that assume at least one node crash on `null` root.

```ts
// ❌ Crashes on empty tree
function maxBad(root: TreeNode<number>): number {
  return Math.max(root.value, maxBad(root.left!), maxBad(root.right!));
}

// ✅ Handle null explicitly
function maxVal(root: TreeNode<number> | null): number {
  if (root === null) throw new Error("empty tree");
  let m = root.value;
  const l = maxVal(root.left);  // throws if empty subtree? handle:
  // Better: track via helper
  return m;
}

// ✅ Idiomatic: nullable accumulator
function maxOrNull(root: TreeNode<number> | null): number | null {
  if (root === null) return null;
  const l = maxOrNull(root.left);
  const r = maxOrNull(root.right);
  return Math.max(root.value, l ?? -Infinity, r ?? -Infinity);
}
```

---

## 3. Recursion depth / stack overflow

**Pitfall:** Deep trees (e.g., a degenerate linked-list-shaped tree of 10⁵ nodes) blow the call stack.

```ts
// ❌ Recursive DFS on a skewed tree of 200k nodes → RangeError
function depthRecursive(root: TreeNode<number> | null): number {
  if (root === null) return 0;
  return 1 + Math.max(depthRecursive(root.left), depthRecursive(root.right));
}

// ✅ Iterative with explicit stack
function depthIterative(root: TreeNode<number> | null): number {
  if (root === null) return 0;
  const stack: [TreeNode<number>, number][] = [[root, 1]];
  let max = 0;
  while (stack.length) {
    const [n, d] = stack.pop()!;
    max = Math.max(max, d);
    if (n.left) stack.push([n.left, d + 1]);
    if (n.right) stack.push([n.right, d + 1]);
  }
  return max;
}
```

**Rule:** Provide iterative variants for any traversal that may run on untrusted/deep input.

---

## 4. Aliasing: shared subtrees create cycles

**Pitfall:** Reusing a node in two parents creates a DAG/cycle; traversals loop forever or double-count.

```ts
const shared = node(5);
const root = node(1, shared, node(2, shared)); // shared appears twice

// ❌ Infinite loop risk / wrong counts
function contains(root: TreeNode<number> | null, target: number): boolean {
  if (root === null) return false;
  if (root.value === target) return true;
  return contains(root.left, target) || contains(root.right, target);
}

// ✅ Track visited by reference (only if aliasing possible)
function containsSafe(root: TreeNode<number> | null, target: number): boolean {
  const seen = new Set<TreeNode<number>>();
  const stack: (TreeNode<number> | null)[] = [root];
  while (stack.length) {
    const n = stack.pop()!;
    if (n === null) continue;
    if (seen.has(n)) continue;       // break cycle / avoid double work
    seen.add(n);
    if (n.value === target) return true;
    stack.push(n.left, n.right);
  }
  return false;
}
```

**Rule:** Treat nodes as unique; if sharing is intended, use a visited set or restructure to a graph algorithm.

---

## 5. Mutating during traversal

**Pitfall:** Deleting/pruning nodes while iterating the same structure corrupts iteration.

```ts
// ❌ Mutating left while walking left
function pruneBad(root: TreeNode<number> | null): void {
  let cur = root;
  while (cur) {
    if (cur.value < 0) cur.left = null; // may skip siblings
    cur = cur.left;
  }
}

// ✅ Two-pass: collect targets first, then mutate
function pruneNegatives(root: TreeNode<number> | null): void {
  const toPrune: TreeNode<number>[] = [];
  const stack = [root];
  while (stack.length) {
    const n = stack.pop();
    if (!n) continue;
    if (n.left && n.left.value < 0) toPrune.push(n);
    if (n.right && n.right.value < 0) toPrune.push(n);
    stack.push(n.left, n.right);
  }
  for (const p of toPrune) {
    if (p.left && p.left.value < 0) p.left = null;
    if (p.right && p.right.value < 0) p.right = null;
  }
}
```

---

## 6. BST assumption without validation

**Pitfall:** Assuming input is a BST and using BST search; silently wrong on invalid trees.

```ts
// ❌ Assumes BST
function bstSearch(root: TreeNode<number> | null, x: number): boolean {
  if (root === null) return false;
  if (root.value === x) return true;
  return x < root.value ? bstSearch(root.left, x) : bstSearch(root.right, x);
}

// ✅ Validate BST property with range
function isValidBST(root: TreeNode<number> | null): boolean {
  function helper(n: TreeNode<number> | null, lo: number, hi: number): boolean {
    if (n === null) return true;
    if (n.value <= lo || n.value >= hi) return false;
    return helper(n.left, lo, n.value) && helper(n.right, n.value, hi);
  }
  return helper(root, -Infinity, Infinity);
}
```

**Note:** Duplicates need a defined policy (e.g., left = `<=`, right = `>`). Document it.

---

## 7. Parent pointers not updated on rotations/relinks

**Pitfall:** In self-balancing trees, forgetting to fix `parent` after rotations breaks upward traversal and deletion.

```ts
interface PNode { value: number; left: PNode | null; right: PNode | null; parent: PNode | null; }

function rotateRight(y: PNode): PNode {
  const x = y.left!;
  const t2 = x.right;

  x.right = y;
  y.left = t2;

  // ❌ Forgot parent updates → x.parent still points to old parent of y? Actually:
  // Need:
  x.parent = y.parent;
  y.parent = x;
  if (t2) t2.parent = y;

  return x;
}
```

**Rule:** After any structural change, update all affected `parent` links, including the new root's parent (`null`).

---

## 8. Shallow copy / clone bugs

**Pitfall:** `structuredClone` works for plain objects, but class instances lose methods; manual clone must be recursive.

```ts
class BNode {
  constructor(public value: number, public left: BNode | null = null, public right: BNode | null = null) {}
  height(): number { /* ... */ return 0; }
}

// ❌ Shallow: shares children
const shallow = { ...root };

// ❌ structuredClone keeps data but loses prototype methods
const cloned = structuredClone(root);
// cloned.height is undefined if root was BNode instance? Actually structuredClone preserves prototype? It does not preserve methods for class instances in many engines? It preserves enumerable own props only mostly; methods on prototype lost.

// ✅ Recursive deep clone preserving class
function clone<T extends BNode>(n: T | null): T | null {
  if (n === null) return null;
  const c = new (n.constructor as new (v: number) => T)(n.value);
  c.left = clone(n.left as T | null);
  c.right = clone(n.right as T | null);
  return c;
}
```

---

## 9. Serialization losing type information

**Pitfall:** `JSON.stringify` a tree of class instances → plain objects on parse; methods gone.

```ts
// ✅ Serialize values only + explicit revival
function serialize(root: TreeNode<number> | null): string {
  // level-order with null markers
  const out: (number | null)[] = [];
  const q: (TreeNode<number> | null)[] = [root];
  while (q.length) {
    const n = q.shift()!;
    if (n === null) { out.push(null); continue; }
    out.push(n.value);
    q.push(n.left, n.right);
  }
  // trim trailing nulls
  while (out.length && out[out.length - 1] === null) out.pop();
  return JSON.stringify(out);
}

function deserialize(data: string): TreeNode<number> | null {
  const arr = JSON.parse(data) as (number | null)[];
  if (!arr.length || arr[0] === null) return null;
  const root = node(arr[0]);
  const q: TreeNode<number>[] = [root];
  let i = 1;
  while (q.length && i < arr.length) {
    const n = q.shift()!;
    if (i < arr.length && arr[i] !== null) {
      n.left = node(arr[i]!);
      q.push(n.left);
    }
    i++;
    if (i < arr.length && arr[i] !== null) {
      n.right = node(arr[i]!);
      q.push(n.right);
    }
    i++;
  }
  return root;
}
```

