## 10. Level-order / BFS queue pitfalls

**Pitfall:** Using `Array.shift()` is O(n) per op → O(n²) overall; also off-by-one level boundaries.

```ts
// ❌ O(n²) and wrong level grouping
function levelOrderBad(root: TreeNode<number> | null): number[][] {
  const res: number[][] = [];
  const q: (TreeNode<number> | null)[] = [root];
  while (q.length) {
    const level: number[] = [];
    const size = q.length;          // captured before mutations? Actually okay if careful
    for (let i = 0; i < size; i++) {
      const n = q.shift()!;         // O(n) each
      if (n) { level.push(n.value); q.push(n.left, n.right); }
    }
    if (level.length) res.push(level);
  }
  return res;
}

// ✅ Use index pointer (O(n)) and correct level sizing
function levelOrder(root: TreeNode<number> | null): number[][] {
  if (root === null) return [];
  const res: number[][] = [];
  const q: TreeNode<number>[] = [root];
  let head = 0;
  while (head < q.length) {
    const levelSize = q.length - head;
    const level: number[] = [];
    for (let i = 0; i < levelSize; i++) {
      const n = q[head++];
      level.push(n.value);
      if (n.left) q.push(n.left);
      if (n.right) q.push(n.right);
    }
    res.push(level);
  }
  return res;
}
```

---

## 11. Traversal order confusion (pre/in/post)

**Pitfall:** Using preorder when inorder is needed (e.g., BST sorted output, expression tree evaluation).

```ts
// Inorder for BST → sorted
function inorder(root: TreeNode<number> | null, out: number[] = []): number[] {
  if (root === null) return out;
  inorder(root.left, out);
  out.push(root.value);
  inorder(root.right, out);
  return out;
}

// Postorder for deletion / bottom-up (e.g., free, compute height)
function heightPost(root: TreeNode<number> | null): number {
  if (root === null) return 0;
  return 1 + Math.max(heightPost(root.left), heightPost(root.right));
}
```

**Rule:** State the required order in the function name/comment; test with a known small tree.

---

## 12. Modifying tree while iterating externally

**Pitfall:** `for (const n of tree)` then delete node → iterator invalidation.

```ts
// ✅ Collect first, mutate after
function removeLeaves(root: TreeNode<number> | null): TreeNode<number> | null {
  if (root === null) return null;
  if (root.left === null && root.right === null) return null; // leaf
  root.left = removeLeaves(root.left);
  root.right = removeLeaves(root.right);
  return root;
}
```

---

## 13. Generic type inference failures

**Pitfall:** `TreeNode<T>` with `T` inferred as `never` or widened to `any` when constructing.

```ts
// ❌ T inferred as never if no hint
const t = node(null); // T = null

// ✅ Explicit type argument
const t2 = node<number>(42);

// ✅ Or annotate variable
const root: TreeNode<string> = node("a");
```

---

## 14. `this` binding in class-based trees

**Pitfall:** Passing methods as callbacks loses `this`.

```ts
class Tree {
  root: TreeNode<number> | null = null;
  insert(v: number) { /* ... */ }
  // ❌ this lost
  forEach(cb: (n: TreeNode<number>) => void) {
    const walk = (n: TreeNode<number> | null) => { if (n) { cb(n); walk(n.left); walk(n.right); } };
    walk(this.root);
  }
}
const t = new Tree();
const insert = t.insert;
// insert(5); // ❌ this is undefined

// ✅ arrow or bind
const insertBound = t.insert.bind(t);
```

---

## 15. Equality: reference vs value

**Pitfall:** `root === otherRoot` only true if same object; value equality needs custom compare.

```ts
function equals(a: TreeNode<number> | null, b: TreeNode<number> | null): boolean {
  if (a === null || b === null) return a === b;
  return a.value === b.value && equals(a.left, b.left) && equals(a.right, b.right);
}
```

---

## 16. Height vs depth confusion

**Pitfall:** Mixing "height of node" (downward) with "depth" (distance from root) → off-by-one in balancing.

```ts
function depth(root: TreeNode<number> | null, target: number): number | null {
  // returns edges from root to node with value target
  function dfs(n: TreeNode<number> | null, d: number): number | null {
    if (n === null) return null;
    if (n.value === target) return d;
    return dfs(n.left, d + 1) ?? dfs(n.right, d + 1);
  }
  return dfs(root, 0);
}
```

---

## 17. AVL balance factor sign errors

**Pitfall:** Wrong rotation selection due to sign convention confusion (left-heavy vs right-heavy).

```ts
function balanceFactor(n: TreeNode<number>): number {
  return height(n.left) - height(n.right); // positive = left heavy
}
// left heavy (bf > 1) with left child right heavy (bf < 0) → LR case needs double rotation
```

**Rule:** Document convention: `bf = height(left) - height(right)`; left-heavy when `bf > 1`.

---

## 18. Not clearing references (memory)

**Pitfall:** Removing a subtree but keeping a reference in a closure → GC can't free.

```ts
function deleteSubtree(root: TreeNode<number> | null, target: number): TreeNode<number> | null {
  // returns new root; caller must assign. Old refs should be dropped.
  if (root === null) return null;
  if (root.value === target) return null; // drop entire subtree
  root.left = deleteSubtree(root.left, target);
  root.right = deleteSubtree(root.right, target);
  return root;
}
// caller: root = deleteSubtree(root, 5); // reassign, don't keep old root ref
```

---

## 19. Concurrency / reentrancy (async trees)

**Pitfall:** Async traversal with mutable shared state.

```ts
// ❌ Shared mutable visited set across concurrent calls
const visited = new Set<TreeNode<number>>();
async function walk(n: TreeNode<number> | null) { /* uses visited */ }

// ✅ Per-call state
async function walkSafe(root: TreeNode<number> | null) {
  const visited = new Set<TreeNode<number>>();
  // ...
}
```

---

## 20. Testing only "happy path" shapes

**Pitfall:** Tests only use perfectly balanced trees; bugs in skew/empty/single-node cases ship.

```ts
const cases = [
  null,
  node(1),
  node(1, node(2), node(3)),
  node(1, node(2, node(3))), // left skew
];
for (const c of cases) console.log(size(c));
```

