# Edge Cases with Bitwise Operations in TypeScript

Bitwise operators in TS/JS look like C-style integer ops, but they operate on **IEEE-754 doubles** that get coerced to **32-bit signed integers** (except `BigInt`). Most bugs come from that mismatch. Below are the cases that bite people, each with runnable code.

---

## 1. Everything is silently truncated to 32 bits

```ts
const a = 0xFFFFFFFF;   // 4294967295
const b = a | 0;        // -1  (signed 32-bit)
const c = a >>> 0;      // 4294967295 (unsigned view)

console.log(1 << 31);   // -2147483648, NOT 2147483648
console.log((1 << 31) >>> 0); // 2147483648

// High bits are discarded entirely:
console.log(0x1_0000_0000 | 0); // 0
```

**Fix:** use `>>> 0` when you need unsigned 32-bit, or `BigInt` when you need >32 bits.

---

## 2. Floats are truncated toward zero (not floored)

```ts
console.log(2.9 | 0);   // 2
console.log(-2.9 | 0);  // -2  (toward zero, NOT -3)
console.log(Math.floor(-2.9)); // -3

// NaN / Infinity become 0
console.log(NaN | 0);        // 0
console.log(Infinity | 0);   // 0
console.log(-Infinity & 7);  // 0
```

---

## 3. Coercion of non-numbers

```ts
console.log("5" & 3);        // 5 & 3 = 1  (string -> number)
console.log("abc" | 0);      // 0  (NaN -> 0)
console.log(true ^ false);   // 1
console.log(null | 5);      // 5  (null -> 0)
console.log(undefined & 7); // 0  (undefined -> NaN -> 0)

const obj = { valueOf: () => 7 };
console.log(obj & 3);       // 3

// Objects without valueOf/toString-number become 0
console.log({} | 1);        // 1  ("[object Object]" -> NaN -> 0)
```

---

## 4. Negative numbers: sign extension & arithmetic right shift

```ts
const x = -1; // 0xFFFFFFFF as 32-bit
console.log(x >> 1);   // -1  (sign bit propagates: 0xFFFFFFFF >> 1 = 0xFFFFFFFF)
console.log(x >>> 1);  // 2147483647 (zero-filled)

console.log(-8 >> 2);  // -2
console.log(-8 >>> 2); // 1073741822
```

Use `>>` only when you want sign preservation; use `>>>` for unsigned bitfields.

---

## 5. Shift counts are masked modulo 32

```ts
console.log(1 << 0);   // 1
console.log(1 << 32);  // 1   (32 mod 32 = 0)
console.log(1 << 33);  // 2   (33 mod 32 = 1)
console.log(1 << 64);  // 1

// Negative shift counts are also masked:
console.log(1 << -1);  // 1 << 31 = -2147483648
```

This surprises people porting C code where large shifts are UB/zero.

---

## 6. Operator precedence (a classic bug)

Bitwise `&`/`|`/`^` sit **below equality** in precedence:

```ts
const flags = 0b1010;

// BUG: parsed as flags & (flags === 0b1000)
if (flags & flags === 0b1000) { /* rarely what you want */ }

// Correct:
if ((flags & 0b1000) !== 0) { /* ... */ }

// Also: bitwise NOT binds tighter than comparison
if (~arr.indexOf(x)) { /* found? */ }  // see case 7
```

---

## 7. `~` and truthiness: `~-1 === 0`

```ts
const idx = "abc".indexOf("z"); // -1
console.log(~idx);              // 0  (falsy!)

// Idiomatic "contains" check:
if (~str.indexOf(sub)) { console.log("found"); }   // works but obscure
// Better:
if (str.includes(sub)) { /* ... */ }

// ~0 is -1, which is truthy:
if (~0) console.log("this runs");   // -1 is truthy
```

Also `~x === -(x + 1)`, so `~0 === -1`.

---

## 8. BigInt: no mixing, no 32-bit truncation, different shift rules

```ts
// Cannot mix number and bigint:
// 1n & 1;  // TypeError: Cannot mix BigInt and other types

const big = 0x1_0000_0000n;
console.log(big | 0n);        // 0n? no — 0x100000000n | 0n = 0x100000000n (no truncation)
console.log((big & 0xFFFFFFFFn) >>> 0n); // error: >>> not defined on bigint

// BigInt has no >>>; emulate unsigned via masking:
const u32 = (x: bigint) => x & 0xFFFFFFFFn;

// Negative shift count throws:
try { 1n << -1n; } catch (e) { console.log(e instanceof RangeError); } // true

// Huge shifts allocate huge memory:
// 1n << 1_000_000_000n;  // may OOM

// ~ on bigint:
console.log(~0n); // -1n
```

Also TS typing: `number & number` → `number`; `bigint & bigint` → `bigint`; mixing is a compile error.

---

## 9. Enums and "bitwise flags" typing

```ts
enum Perm { Read = 1, Write = 2, Exec = 4 }

const p = Perm.Read | Perm.Write; // type: number (not Perm)
// TS won't narrow; comparisons need masks:
if (p & Perm.Read) { /* truthy number, OK but loose */ }

// Const enums inline; regular enums produce runtime object.
// Prefer a branded/union or `as const` object for type safety:
const Flags = { A: 1, B: 2, C: 4 } as const;
type Flag = (typeof Flags)[keyof typeof Flags];
```

Bitwise results widen to `number`, losing enum identity.

---

## 10. Using bitwise ops as "fast math" (often wrong)

```ts
// ~~x truncates toward zero — fine for 32-bit range only:
console.log(~~2.9);        // 2
console.log(~~2147483648); // -2147483648  (overflow!)

// x | 0 same caveat:
const n = 3_000_000_000;
console.log(n | 0); // -1294967296

// Prefer Math.trunc for clarity and correctness beyond 32 bits:
console.log(Math.trunc(3_000_000_000.7)); // 3000000000
```

---

## 11. Signedness of intermediate values in expressions

```ts
// Comparison after bitwise ops uses signed 32-bit result
console.log((0x80000000 | 0) < 0); // true
console.log((0x80000000 >>> 0) < 0); // false (now unsigned, large positive)

// Hashing / checksums: always normalize with >>> 0
function hash(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
  return h >>> 0; // expose as unsigned
}
```

---

## 12. Bitwise on `boolean` returns `number`

```ts
const a = true, b = false;
const r = a & b; // 0, type number — not boolean
// If you need boolean: (a && b) or Boolean(a & b)
```

---

## 13. Endianness is NOT a bitwise concern (but often confused)

Bitwise ops are on the *numeric value*, not byte layout. `0x0102 >>> 8 === 0x01` always. Endianness only matters for `TypedArray`/`DataView` byte access — use `DataView` with explicit endianness there.

---

## 14. TS-specific: no overflow warnings, `const` inference

```ts
const mask = 1 << 30; // TS infers number, no warning about 32-bit
// Use explicit annotation when intent matters:
const MASK: number = 1 << 30;

// Bitwise on `any`/`unknown`:
function f(x: unknown) { return x & 1; } // error: Operator '&' cannot be applied to 'unknown'
```

---

## Safe patterns checklist

```ts
// Truncate to signed int32:
const toI32 = (x: number) => x | 0;

// Truncate to unsigned int32:
const toU32 = (x: number) => x >>> 0;

// Test a bit safely:
const has = (flags: number, bit: number) => (flags & bit) !== 0;

// Avoid precedence bugs: always parenthesize masks.
// Prefer BigInt for >32 bits; never mix with number.
// Use Math.trunc instead of ~~ for floats outside int32 range.
// Normalize hashes with >>> 0.
```

### Summary of the "gotchas"
| Case | Symptom | Fix |
|---|---|---|
| >32-bit values | high bits vanish | `BigInt` or mask |
| negatives | sign extension in `>>` | use `>>>` for unsigned |
| floats | truncated toward zero | `Math.trunc`/`Math.floor` |
| NaN/Infinity/null/str/obj | becomes 0 or NaN→0 | validate input |
| shift ≥32 | wraps mod 32 | mask shift count |
| `~` | `~-1 === 0` | use `includes`/`indexOf !== -1` |
| precedence | `a & b === c` misparses | parentheses |
| BigInt | can't mix; no `>>>` | mask with `& 0xFFFFFFFFn` |
| enum flags | widened to `number` | `as const` objects |

Here’s a complete, runnable TypeScript example that implements Boolean logic: primitive gates, derived gates, truth-table generation, De Morgan verification, a recursive-descent Boolean expression parser/evaluator, and small digital circuits (half/full adder).

```ts
// boolean-logic.ts
// Run with: npx ts-node boolean-logic.ts  (or tsc then node)

type Bit = 0 | 1;
type Env = Record<string, Bit>;

const asBit = (b: boolean): Bit => (b ? 1 : 0);

/* ---------- Primitive gates ---------- */
const AND = (a: Bit, b: Bit): Bit => (a === 1 && b === 1 ? 1 : 0);
const OR  = (a: Bit, b: Bit): Bit => (a === 1 || b === 1 ? 1 : 0);
const NOT = (a: Bit): Bit => (a === 1 ? 0 : 1);

/* ---------- Derived gates ---------- */
const NAND = (a: Bit, b: Bit): Bit => NOT(AND(a, b));
const NOR  = (a: Bit, b: Bit): Bit => NOT(OR(a, b));
const XOR  = (a: Bit, b: Bit): Bit => (a !== b ? 1 : 0);
const XNOR = (a: Bit, b: Bit): Bit => (a === b ? 1 : 0);
const IMPLIES = (a: Bit, b: Bit): Bit => (a === 1 && b === 0 ? 0 : 1); // a -> b
const IFF     = (a: Bit, b: Bit): Bit => XNOR(a, b);

/* ---------- Truth table helper ---------- */
function truthTable(vars: string[], fn: (env: Env) => Bit, label?: string): void {
  const n = vars.length;
  const rows = 1 << n;
  if (label) console.log(`\n=== ${label} ===`);
  console.log(vars.join(" | ") + " => out");
  console.log("-".repeat(vars.length * 4 + 6));
  for (let i = 0; i < rows; i++) {
    const env: Env = {};
    vars.forEach((v, j) => {
      env[v] = ((i >> (n - 1 - j)) & 1) as Bit;
    });
    const out = fn(env);
    console.log(vars.map((v) => env[v]).join(" | ") + " =>  " + out);
  }
}

/* ---------- Boolean expression parser (recursive descent) ----------
   Grammar (lowest -> highest):
     expr := xor ( '|' xor )*
     xor  := and ( '^' and )*
     and  := not ( '&' not )*
     not  := '!' not | primary
     primary := '(' expr ')' | const | identifier
*/
class Parser {
  private pos = 0;
  constructor(private src: string) {}

  parse(): (env: Env) => Bit {
    const node = this.expr();
    this.skipWs();
    if (this.pos !== this.src.length) {
      throw new Error(`Unexpected trailing input at ${this.pos}: '${this.src[this.pos]}'`);
    }
    return node;
  }

  private peek(): string {
    this.skipWs();
    return this.pos < this.src.length ? this.src[this.pos] : "";
  }

  private skipWs(): void {
    while (this.pos < this.src.length && /\s/.test(this.src[this.pos])) this.pos++;
  }

  private expr(): (env: Env) => Bit {
    let node = this.xor();
    this.skipWs();
    while (this.pos < this.src.length && this.src[this.pos] === "|") {
      this.pos++;
      const right = this.xor();
      const left = node;
      node = (env) => OR(left(env), right(env));
      this.skipWs();
    }
    return node;
  }

  private xor(): (env: Env) => Bit {
    let node = this.and();
    this.skipWs();
    while (this.pos < this.src.length && this.src[this.pos] === "^") {
      this.pos++;
      const right = this.and();
      const left = node;
      node = (env) => XOR(left(env), right(env));
      this.skipWs();
    }
    return node;
  }

  private and(): (env: Env) => Bit {
    let node = this.not();
    this.skipWs();
    while (this.pos < this.src.length && this.src[this.pos] === "&") {
      this.pos++;
      const right = this.not();
      const left = node;
      node = (env) => AND(left(env), right(env));
      this.skipWs();
    }
    return node;
  }

  private not(): (env: Env) => Bit {
    this.skipWs();
    if (this.pos < this.src.length && this.src[this.pos] === "!") {
      this.pos++;
      const inner = this.not();
      return (env) => NOT(inner(env));
    }
    return this.primary();
  }

  private primary(): (env: Env) => Bit {
    this.skipWs();
    if (this.pos >= this.src.length) throw new Error("Unexpected end of expression");

    if (this.src[this.pos] === "(") {
      this.pos++;
      const inner = this.expr();
      this.skipWs();
      if (this.pos >= this.src.length || this.src[this.pos] !== ")") {
        throw new Error("Expected ')'");
      }
      this.pos++;
      return inner;
    }

    const start = this.pos;
    while (this.pos < this.src.length && /[A-Za-z0-9_]/.test(this.src[this.pos])) this.pos++;
    const token = this.src.slice(start, this.pos);
    if (token === "") throw new Error(`Unexpected character '${this.src[this.pos]}'`);

    if (token === "0" || token === "false") return () => 0;
    if (token === "1" || token === "true") return () => 1;
    return (env) => {
      if (!(token in env)) throw new Error(`Unbound variable '${token}'`);
      return env[token];
    };
  }
}

function parseExpr(source: string): (env: Env) => Bit {
  return new Parser(source).parse();
}

/* ---------- Verification helpers ---------- */
function equivalent(a: (env: Env) => Bit, b: (env: Env) => Bit, vars: string[]): boolean {
  const n = vars.length;
  for (let i = 0; i < (1 << n); i++) {
    const env: Env = {};
    vars.forEach((v, j) => (env[v] = ((i >> (n - 1 - j)) & 1) as Bit));
    if (a(env) !== b(env)) return false;
  }
  return true;
}

/* ---------- Demo / self-test ---------- */

// 1. Parse and evaluate
const f = parseExpr("!(A & B) ^ (C | D)");
truthTable(["A", "B", "C", "D"], f, "!(A & B) ^ (C | D)");

// 2. De Morgan's laws
const lhs1 = parseExpr("!(A & B)");
const rhs1 = parseExpr("!A | !B");
const lhs2 = parseExpr("!(A | B)");
const rhs2 = parseExpr("!A & !B");
console.log("\nDe Morgan 1 (AND):", equivalent(lhs1, rhs1, ["A", "B"]));
console.log("De Morgan 2 (OR): ", equivalent(lhs2, rhs2, ["A", "B"]));

// 3. Distributivity
const d1 = parseExpr("A & (B | C)");
const d2 = parseExpr("(A & B) | (A & C)");
console.log("Distributivity AND over OR:", equivalent(d1, d2, ["A", "B", "C"]));

// 4. Half adder
function halfAdder(a: Bit, b: Bit): { sum: Bit; carry: Bit } {
  return { sum: XOR(a, b), carry: AND(a, b) };
}
truthTable(["A", "B"], (env) => halfAdder(env.A, env.B).sum, "Half-adder SUM");
truthTable(["A", "B"], (env) => halfAdder(env.A, env.B).carry, "Half-adder CARRY");

// 5. Full adder
function fullAdder(a: Bit, b: Bit, cin: Bit): { sum: Bit; carry: Bit } {
  const s1 = XOR(a, b);
  const c1 = AND(a, b);
  const s2 = XOR(s1, cin);
  const c2 = AND(s1, cin);
  return { sum: s2, carry: OR(c1, c2) };
}
truthTable(
  ["A", "B", "Cin"],
  (env) => fullAdder(env.A, env.B, env.Cin).sum,
  "Full-adder SUM"
);
truthTable(
  ["A", "B", "Cin"],
  (env) => fullAdder(env.A, env.B, env.Cin).carry,
  "Full-adder CARRY"
);

// 6. NAND is universal: build NOT and AND from NAND
const notFromNand = (a: Bit) => NAND(a, a);
const andFromNand = (a: Bit, b: Bit) => NAND(NAND(a, b), NAND(a, b));
console.log("\nNAND universality checks:");
console.log("NOT via NAND(1,1) =", notFromNand(1), "(expected 0)");
console.log("AND via NAND-NAND(1,1) =", andFromNand(1, 1), "(expected 1)");

// 7. A small 2-bit equality comparator
const eq2 = parseExpr("!(A0 ^ B0) & !(A1 ^ B1)");
truthTable(["A1", "A0", "B1", "B0"], eq2, "2-bit equality (1 = equal)");
```

### What this demonstrates

- **Primitive & derived gates**: `AND, OR, NOT, NAND, NOR, XOR, XNOR, IMPLIES, IFF`, all operating on `Bit = 0 | 1`.
- **Truth tables** for arbitrary `n`-input Boolean functions.
- **Expression language** with variables, constants (`0/1/true/false`), parentheses, and operators `& | ^ !`, parsed with a recursive-descent parser into executable closures.
- **Algebraic verification** by exhaustive enumeration (De Morgan, distributivity).
- **Circuit construction** (half adder, full adder) from gates.
- **Universal gate**: rebuilding `NOT` and `AND` from `NAND` only.

You can extend the parser with additional operators (e.g. `->`, `<->`) or add a simplifier/CNF converter if needed.

## Boolean logic in TypeScript

### 1. The core idea

A **boolean** is a value that can only be `true` or `false`. Boolean logic is how you combine and transform these values to make decisions: “if this AND that”, “this OR that”, “NOT this”. In TypeScript, booleans are a first-class primitive type, but because TS compiles to JavaScript, you also inherit JS’s “truthy/falsy” coercion rules—so it’s worth distinguishing **strict booleans** from **truthy values**.

```ts
const a: boolean = true;
const b: boolean = false;

// Type-level: boolean is `true | false`
type Flag = boolean; // true | false
```

---

### 2. Syntax

#### Literals and comparisons

```ts
const isReady: boolean = true;
const isEqual = 5 === 5;        // true  (strict equality)
const isLoose = 5 == "5";      // true  (coercion — avoid)
const isGreater = 10 > 3;      // true
```

Prefer `===` / `!==` over `==` / `!=` to avoid implicit coercion.

#### Logical operators

| Operator | Meaning | Example |
|----------|---------|---------|
| `&&` | AND (short-circuit) | `a && b` |
| `\|\|` | OR (short-circuit) | `a \|\| b` |
| `!` | NOT | `!a` |
| `??` | Nullish coalescing (not boolean, but related) | `x ?? default` |
| `?.` | Optional chaining | `obj?.flag` |

```ts
const userLoggedIn = true;
const hasPermission = false;

const canEdit = userLoggedIn && hasPermission; // false
const showBanner = !userLoggedIn || hasPermission; // true
```

#### Ternary (conditional expression)

```ts
const label = isActive ? "Active" : "Inactive";
```

---

### 3. Truthiness vs. strict booleans

JS/TS treats many values as “truthy” or “falsy” in boolean contexts.

Falsy values: `false, 0, "", null, undefined, NaN`.

```ts
const name = "";
if (name) {
  // skipped — "" is falsy
}

// Strict check when you need an actual boolean:
const hasName: boolean = name !== "";
```

**Pitfall:** `0` and `""` are falsy but often valid data (e.g., count, empty string input). Prefer explicit comparisons.

```ts
// Risky
if (count) { /* skipped when count === 0 */ }

// Safer
if (count !== undefined && count !== null) { /* ... */ }
// or
if (count ?? 0 > 0) { /* ... */ }
```

---

### 4. Short-circuit evaluation

`&&` and `||` return the first decisive operand, not necessarily a boolean.

```ts
const fallback = input || "default";   // "" would be replaced — maybe not desired
const safe = input ?? "default";      // only null/undefined trigger fallback

// Guard pattern
user && user.save(); // calls save only if user exists

// Conditional render (React/JSX)
{isLoading && <Spinner />}
```

Because `&&` can return non-boolean values, type it carefully:

```ts
const ok: boolean = Boolean(a && b); // coerce to strict boolean
```

---

### 5. Type narrowing with booleans

TypeScript uses boolean expressions to narrow types in control flow.

```ts
function process(value: string | null) {
  if (value) {
    // value is narrowed to `string` here
    console.log(value.toUpperCase());
  } else {
    // value is `null` here (plus other falsy, but TS knows string|null)
  }
}
```

#### User-defined type guards

```ts
function isString(x: unknown): x is string {
  return typeof x === "string";
}

if (isString(input)) {
  input.toUpperCase(); // narrowed
}
```

#### Discriminated unions + exhaustiveness

```ts
type State =
  | { kind: "loading" }
  | { kind: "error"; message: string }
  | { kind: "success"; data: number };

function handle(s: State) {
  switch (s.kind) {
    case "loading": return "…";
    case "error":   return s.message;
    case "success": return s.data;
    default: {
      const _exhaustive: never = s;
      return _exhaustive;
    }
  }
}
```

---

### 6. Typical use cases

#### a) Guards and validation

```ts
function createUser(name: string, age: number) {
  if (!name || age < 0) throw new Error("Invalid input");
  // ...
}
```

#### b) Filtering and searching

```ts
const adults = users.filter(u => u.age >= 18);
const hasAdmin = users.some(u => u.role === "admin");
const allActive = users.every(u => u.isActive);
```

#### c) Feature flags / permissions

```ts
const canDelete = role === "admin" && (isOwner || hasOverride);
```

#### d) Combining multiple conditions (De Morgan)

```ts
// "not (A and B)" === "(not A) or (not B)"
const blocked = !(isAuth && hasToken);
const blocked2 = !isAuth || !hasToken; // equivalent
```

#### e) Boolean aggregation

```ts
const flags = [a, b, c];
const any = flags.some(Boolean);
const all = flags.every(Boolean);
```

---

### 7. Pitfalls and best practices

| Pitfall | Fix |
|---------|-----|
| Truthy `0`/`""` skipped | Use explicit `!== null/undefined` or `??` |
| `&&` returns non-boolean | Wrap with `Boolean(...)` if a strict bool is required |
| `==` coercion bugs | Always use `===` |
| Implicit `any` in callbacks | Annotate: `(x): x is T => ...` |
| Over-narrowing with `if (x)` on unions | Handle `0`/`""` cases explicitly |

**Best practices**

- Enable `strict: true` (and `noImplicitAny`, `strictNullChecks`).
- Prefer `=== true` / `=== false` when a value isn’t already typed as `boolean`.
- Use `??` instead of `||` for defaults that may be `0`/`""`/`false`.
- Name booleans with `is/has/can/should` prefixes for readability.

---

### 8. (Optional) Type-level boolean logic

TypeScript also supports boolean logic at the type level via conditional types:

```ts
type IsString<T> = T extends string ? true : false;

type A = IsString<"hi">;   // true
type B = IsString<number>; // false

// Combining
type And<A extends boolean, B extends boolean> =
  A extends true ? (B extends true ? true : false) : false;
```

This is useful for generic constraints and advanced type utilities, but for everyday code, runtime boolean logic with good narrowing is usually enough.

---

### Quick reference snippet

```ts
// Strict boolean from possibly-truthy value
const ok: boolean = Boolean(user && user.id);

// Safe default
const name = input ?? "anonymous";

// Guard + narrow
if (typeof value === "number" && value > 0) {
  // value: number
}

// Exhaustive check
function assertNever(x: never): never {
  throw new Error("Unexpected: " + x);
}
```

If you want, I can go deeper into any one area—e.g., React conditional rendering patterns, or advanced type guards.

## Exercise

**Boolean Logic in TypeScript — “Can this user view the article?”**

Implement a function `canViewArticle(article, user)` that returns `true` only when all of these hold:

1. The article is **published**, **or** the user is the **owner**, **or** the user is an **admin**.
2. The user is **not banned**.
3. If the article is **premium**, then the user is a **paid subscriber** **or** an **admin**.

Types:

```ts
type Article = {
  published: boolean;
  premium: boolean;
  ownerId: string;
};

type User = {
  id: string;
  isAdmin: boolean;
  isBanned: boolean;
  isPaid: boolean;
};
```

---

## Step-by-step solution

### Step 1 — Translate each rule into a boolean expression

Rule 1 (visibility gate):
```ts
article.published || user.id === article.ownerId || user.isAdmin
```

Rule 2 (not banned):
```ts
!user.isBanned
```

Rule 3 (premium gate). “If premium then (paid or admin)” is an implication `premium → (paid || admin)`. In boolean logic, `A → B` is equivalent to `!A || B`:
```ts
!article.premium || user.isPaid || user.isAdmin
```

### Step 2 — Combine with AND

All three must hold:
```ts
const canView =
  (article.published || user.id === article.ownerId || user.isAdmin) &&
  !user.isBanned &&
  (!article.premium || user.isPaid || user.isAdmin);
```

### Step 3 — Refactor for readability (named predicates)

Pulling conditions into named booleans makes intent clear and debugging easier:

```ts
function canViewArticle(article: Article, user: User): boolean {
  const isOwner = user.id === article.ownerId;
  const canSeeUnpublished = article.published || isOwner || user.isAdmin;
  const notBanned = !user.isBanned;
  const premiumOk = !article.premium || user.isPaid || user.isAdmin;

  return canSeeUnpublished && notBanned && premiumOk;
}
```

### Step 4 — Verify with a truth table of edge cases

| published | premium | owner | admin | banned | paid | expected |
|-----------|---------|-------|-------|--------|------|----------|
| true      | false   | false | false | false  | false| true     |
| false     | false   | true  | false | false  | false| true     |
| false     | false   | false | true  | false  | false| true     |
| true      | true    | false | false | false  | false| false    |
| true      | true    | false | false | false  | true | true     |
| true      | false   | false | false | true   | false| false    |
| true      | true    | false | true  | false  | false| true     |

Quick check in code:

```ts
const cases: Array<[Article, User, boolean]> = [
  [{ published: true,  premium: false, ownerId: "a" }, { id: "x", isAdmin: false, isBanned: false, isPaid: false }, true],
  [{ published: false, premium: false, ownerId: "x" }, { id: "x", isAdmin: false, isBanned: false, isPaid: false }, true],
  [{ published: true,  premium: true,  ownerId: "a" }, { id: "x", isAdmin: false, isBanned: false, isPaid: false }, false],
  [{ published: true,  premium: true,  ownerId: "a" }, { id: "x", isAdmin: false, isBanned: false, isPaid: true  }, true],
  [{ published: true,  premium: false, ownerId: "a" }, { id: "x", isAdmin: false, isBanned: true,  isPaid: false }, false],
];

for (const [a, u, expected] of cases) {
  console.assert(canViewArticle(a, u) === expected, "mismatch", a, u);
}
```

### Step 5 — Note on De Morgan’s law (optional hardening)

If you ever need to express “blocked” instead of “allowed,” apply De Morgan:

```ts
// blocked = !(canSeeUnpublished && notBanned && premiumOk)
//         = !canSeeUnpublished || !notBanned || !premiumOk
//         = !(published || owner || admin) || banned || (premium && !paid && !admin)
```

This is a good exercise in flipping `&&`/`||` and negating each term.

---

## Final solution

```ts
type Article = {
  published: boolean;
  premium: boolean;
  ownerId: string;
};

type User = {
  id: string;
  isAdmin: boolean;
  isBanned: boolean;
  isPaid: boolean;
};

function canViewArticle(article: Article, user: User): boolean {
  const isOwner = user.id === article.ownerId;

  const canSeeUnpublished =
    article.published || isOwner || user.isAdmin;

  const notBanned = !user.isBanned;

  // implication: premium -> (paid || admin)  ===  !premium || paid || admin
  const premiumOk =
    !article.premium || user.isPaid || user.isAdmin;

  return canSeeUnpublished && notBanned && premiumOk;
}

export { canViewArticle };
```

**Key takeaways**
- Implications `A → B` become `!A || B`.
- Prefer named booleans over one giant expression.
- Use `console.assert` (or a test runner) with a small truth table to lock in behavior.

## Boolean Logic in TypeScript (Interview-Style)

### 1) Core concepts

- **Primitive boolean**: `true` / `false`. Prefer the lowercase primitive, not `Boolean` objects.
- **Logical operators**
  - `&&` (AND): returns first falsy value or last value; short-circuits.
  - `||` (OR): returns first truthy value or last value; short-circuits.
  - `!` (NOT): coerces to boolean and negates.
  - `??` (nullish coalescing): returns right side only for `null`/`undefined` (not other falsy values).
- **Truthiness**: values treated as truthy/falsy in conditions (`0`, `""`, `null`, `undefined`, `NaN`, `false` are falsy).
- **Type narrowing**: `if (x)` narrows `x` to truthy branch; `if (!x)` to falsy.
- **Strict equality**: `===` compares value + type; use it for booleans to avoid coercion surprises.

### 2) Implementation: core boolean logic + truth tables

```ts
// booleanLogic.ts

/** Basic boolean alias for readability. */
export type Bool = boolean;

/** Logical AND (conjunction). */
export function and(a: Bool, b: Bool): Bool {
  return a && b;
}

/** Logical OR (disjunction). */
export function or(a: Bool, b: Bool): Bool {
  return a || b;
}

/** Logical NOT (negation). */
export function not(a: Bool): Bool {
  return !a;
}

/** Exclusive OR: true when exactly one input is true. */
export function xor(a: Bool, b: Bool): Bool {
  return a !== b;
}

/** NAND: NOT (A AND B). */
export function nand(a: Bool, b: Bool): Bool {
  return !(a && b);
}

/** NOR: NOT (A OR B). */
export function nor(a: Bool, b: Bool): Bool {
  return !(a || b);
}

/** Implication: A -> B is false only when A is true and B is false. */
export function implies(a: Bool, b: Bool): Bool {
  return !a || b;
}

/** Biconditional / XNOR: true when both inputs match. */
export function iff(a: Bool, b: Bool): Bool {
  return a === b;
}

/**
 * Generate a truth table for a boolean function of `arity` inputs.
 * Inputs are ordered MSB-first for readability.
 */
export function truthTable(
  fn: (...inputs: Bool[]) => Bool,
  arity: number
): { inputs: Bool[]; output: Bool }[] {
  if (!Number.isInteger(arity) || arity < 0) {
    throw new Error("arity must be a non-negative integer");
  }

  const rows: { inputs: Bool[]; output: Bool }[] = [];
  const total = 1 << arity; // 2^arity

  for (let i = 0; i < total; i++) {
    const inputs: Bool[] = Array.from({ length: arity }, (_, k) => {
      // Extract bit for position k (MSB-first).
      const bitPosition = arity - 1 - k;
      return Boolean((i >> bitPosition) & 1);
    });

    rows.push({ inputs, output: fn(...inputs) });
  }

  return rows;
}

/** Pretty-print a truth table to the console. */
export function printTruthTable(
  fn: (...inputs: Bool[]) => Bool,
  arity: number,
  label = "f"
): void {
  const rows = truthTable(fn, arity);
  const header = [...Array.from({ length: arity }, (_, i) => `x${i}`), label].join(" | ");
  console.log(header);
  console.log("-".repeat(header.length));

  for (const row of rows) {
    const line = [...row.inputs.map((v) => (v ? "1" : "0")), row.output ? "1" : "0"].join(" | ");
    console.log(line);
  }
}
```

### 3) Usage example

```ts
import { and, or, not, xor, implies, printTruthTable } from "./booleanLogic";

console.log(and(true, false));   // false
console.log(or(true, false));    // true
console.log(not(true));          // false
console.log(xor(true, false));   // true
console.log(implies(true, false)); // false

// Truth table for XOR
printTruthTable(xor, 2, "xor");
```

### 4) Interview talking points

- **Short-circuiting**: `a && b` won’t evaluate `b` if `a` is falsy; useful for guards like `user && user.id`.
- **`??` vs `||`**: `0 || "default"` gives `"default"`, but `0 ?? "default"` gives `0`.
- **Avoid coercion bugs**: use `=== true` when you need an actual boolean, not just truthiness.
- **Pure functions**: boolean logic functions above are deterministic and side-effect free, easy to test.

