## Build tooling in TypeScript (interview style)

### 1) What “build tooling” means for TS
A TypeScript build usually has several layers:

1. **Transpilation** – convert `.ts` → `.js` (strip types, downlevel syntax).  
2. **Type checking** – `tsc` semantic diagnostics (optional in many modern pipelines).  
3. **Module resolution / bundling** – resolve imports, tree-shake, concatenate.  
4. **Optimization** – minification, splitting, source maps.  
5. **Orchestration** – watch mode, caching, parallel tasks, dev server.

Common tools:
- **`tsc`** – reference type checker + emitter.
- **Babel / SWC / esbuild** – fast transpilers (often skip type checking).
- **Webpack / Rollup / Vite / esbuild** – bundlers.
- **tsup / unbuild** – library bundlers on top of esbuild/rollup.
- **Turborepo / Nx** – monorepo orchestration.

Trade-offs:
- **Correctness vs speed**: `tsc` is slower but type-checks; esbuild is extremely fast but does not type-check.
- **Dev vs prod**: Vite/esbuild for dev, Rollup/Terser for prod.
- **ESM vs CJS**: output format matters for Node/browser compatibility.

---

### 2) Core implementation (minimal but real)

Below is a small, clean “core” that:
- loads `tsconfig.json`,
- creates a TS program,
- type-checks,
- emits JS to disk,
- (optionally) bundles emitted files with a tiny topological bundler.

> This is educational; production tools add caching, incremental builds, workers, etc.

```ts
// build.ts
import * as ts from "typescript";
import * as fs from "node:fs";
import * as path from "node:path";

/* ----------------------------- Types ----------------------------- */

export interface BuildOptions {
  /** Project root containing tsconfig.json */
  projectRoot: string;
  /** Override output directory (falls back to tsconfig outDir) */
  outDir?: string;
  /** Fail the build if type errors exist */
  noEmitOnError?: boolean;
}

export interface BuildResult {
  success: boolean;
  emittedFiles: string[];
  diagnostics: ts.Diagnostic[];
}

/* ------------------------ TypeScript Builder ---------------------- */

export class TypeScriptBuilder {
  constructor(private readonly options: BuildOptions) {}

  build(): BuildResult {
    // 1. Locate and read tsconfig.json
    const configPath = ts.findConfigFile(
      this.options.projectRoot,
      ts.sys.fileExists,
      "tsconfig.json"
    );

    if (!configPath) {
      throw new Error(`tsconfig.json not found in ${this.options.projectRoot}`);
    }

    const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
    if (configFile.error) {
      return this.fail([configFile.error]);
    }

    // 2. Parse config into compiler options + file list
    const parsed = ts.parseJsonConfigFileContent(
      configFile.config,
      ts.sys,
      path.dirname(configPath)
    );

    if (parsed.errors.length > 0) {
      return this.fail(parsed.errors);
    }

    const compilerOptions: ts.CompilerOptions = {
      ...parsed.options,
      // Allow CLI override of outDir
      outDir: this.options.outDir ?? parsed.options.outDir,
      // Keep emit deterministic and simple for this demo
      noEmitOnError: this.options.noEmitOnError ?? true,
    };

    // 3. Create the program (this is the heart of tsc)
    const program = ts.createProgram(parsed.fileNames, compilerOptions);

    // 4. Type check before emit
    const preEmitDiagnostics = ts.getPreEmitDiagnostics(program);

    if (
      compilerOptions.noEmitOnError &&
      preEmitDiagnostics.some((d) => d.category === ts.DiagnosticCategory.Error)
    ) {
      return this.fail(preEmitDiagnostics);
    }

    // 5. Emit files to disk
    const emittedFiles: string[] = [];

    const emitResult = program.emit(
      undefined, // emit all files
      (fileName: string, data: string) => {
        // writeFile callback: create dirs, write content, track output
        fs.mkdirSync(path.dirname(fileName), { recursive: true });
        fs.writeFileSync(fileName, data, "utf8");
        emittedFiles.push(fileName);
      }
    );

    const allDiagnostics = [...preEmitDiagnostics, ...emitResult.diagnostics];

    const success = allDiagnostics.every(
      (d) => d.category !== ts.DiagnosticCategory.Error
    );

    return { success, emittedFiles, diagnostics: allDiagnostics };
  }

  private fail(diagnostics: ts.Diagnostic[]): BuildResult {
    return { success: false, emittedFiles: [], diagnostics };
  }
}

/* --------------------------- Simple Bundler ----------------------- */
/**
 * A tiny, educational bundler.
 * - Resolves relative imports only.
 * - Topologically sorts modules.
 * - Concatenates into one file.
 *
 * NOTE: This is NOT production-grade (no tree-shaking, no code splitting).
 */
export class SimpleBundler {
  constructor(
    private readonly entryFile: string,
    private readonly outputFile: string
  ) {}

  bundle(): void {
    const visited = new Set<string>();
    const order: string[] = [];

    const visit = (file: string): void => {
      const absolute = path.resolve(file);
      if (visited.has(absolute)) return;
      visited.add(absolute);

      const code = fs.readFileSync(absolute, "utf8");
      const imports = extractRelativeImports(code);

      // Visit dependencies first (topological order)
      for (const imp of imports) {
        const resolved = resolveRelativeImport(absolute, imp);
        if (resolved) visit(resolved);
      }

      order.push(absolute);
    };

    visit(this.entryFile);

    // Concatenate in dependency order
    const chunks = order.map((file) => {
      const code = fs.readFileSync(file, "utf8");
      return `// ----- ${path.relative(process.cwd(), file)} -----\n${code}`;
    });

    fs.mkdirSync(path.dirname(this.outputFile), { recursive: true });
    fs.writeFileSync(this.outputFile, chunks.join("\n\n"), "utf8");
  }
}

/* --------------------------- Helpers ------------------------------ */

/** Extract relative import/require paths using a simple regex. */
function extractRelativeImports(code: string): string[] {
  const results: string[] = [];
  const regex = /(?:import|require)\s*\(?['"](\.\.?\/[^'"]+)['"]\)?/g;
  let match: RegExpExecArray | null;

  while ((match = regex.exec(code)) !== null) {
    results.push(match[1]);
  }
  return results;
}

/** Resolve a relative import to an absolute file path (best-effort). */
function resolveRelativeImport(fromFile: string, importPath: string): string | null {
  const base = path.resolve(path.dirname(fromFile), importPath);

  // Try common extensions
  const candidates = [
    base,
    `${base}.js`,
    `${base}.ts`,
    path.join(base, "index.js"),
    path.join(base, "index.ts"),
  ];

  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) return candidate;
  }
  return null;
}

/* --------------------------- Usage Example ------------------------ */

async function main() {
  // 1. Type-check + emit
  const builder = new TypeScriptBuilder({
    projectRoot: process.cwd(),
    outDir: "./dist",
    noEmitOnError: true,
  });

  const result = builder.build();

  if (!result.success) {
    console.error("Build failed with diagnostics:");
    for (const d of result.diagnostics) {
      console.error(ts.formatDiagnostic(d, {
        getCanonicalFileName: (f) => f,
        getCurrentDirectory: () => process.cwd(),
        getNewLine: () => "\n",
      }));
    }
    process.exit(1);
  }

  console.log(`Emitted ${result.emittedFiles.length} files to ./dist`);

  // 2. Optional: bundle emitted entry
  const bundler = new SimpleBundler("./dist/index.js", "./dist/bundle.js");
  bundler.bundle();
  console.log("Bundled -> ./dist/bundle.js");
}

// Run only when executed directly
if (require.main === module) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}
```

### 3) How you’d extend this in a real tool
- **Incremental builds**: use `ts.createIncrementalProgram` + `.tsbuildinfo`.
- **Watch mode**: `ts.createWatchProgram` or chokidar + rebuild.
- **Parallelism**: worker threads for transpile-only mode.
- **Caching**: content-hash based cache keys (like Vite/esbuild).
- **Source maps**: emit `.map` files and compose them during bundling.
- **Tree-shaking**: analyze ESM exports/imports (Rollup-style).
- **Plugins**: hook into resolve/load/transform stages.

### Interview takeaway
If asked “how does a TS build work?”, answer:
> *Load config → create program → type-check → emit → (optionally) bundle/optimize.*  
> Then mention modern fast paths (esbuild/SWC) that transpile without type checking, and how teams split type-checking into CI while dev uses fast transpilation.

# Edge cases when using build tooling with TypeScript

Below are the most common “surprises” that show up when you move from *type-checking* (`tsc --noEmit`) to *building* (emitting JS, bundling, publishing). Each item includes a minimal reproduction and the recommended fix.

---

## 1) Type-only imports that accidentally become runtime `require()`

Fast transpilers (esbuild, SWC, Babel) and `isolatedModules`/`verbatimModuleSyntax` cannot remove an import unless it is explicitly type-only.

```ts
// user.ts
export type User = { id: string };

// bad: `User` is erased at the type level, but the emitter may keep `require("./user")`
import { User } from "./user";
export function label(u: User) { return u.id; }
```

```ts
// good
import type { User } from "./user";
export function label(u: User) { return u.id; }
```

Also use `export type { ... }` for re-exports. With TS 5.0+, enable:

```json
{
  "compilerOptions": {
    "verbatimModuleSyntax": true
  }
}
```

---

## 2) `const enum` values are inlined by `tsc`, but not by most bundlers/transpilers

`const enum` is a compile-time construct. If a dependency is consumed as pre-built JS (or through an isolated transpiler), the member may be `undefined`.

```ts
// status.ts
export const enum Status { Ok = 1, Fail = 2 }

// consumer (transpiled without tsc inlining)
import { Status } from "my-lib";
console.log(Status.Ok); // undefined in some pipelines
```

Fix: in libraries, prefer regular enums or set `preserveConstEnums: true` and ship the JS value; for internal apps with `tsc`, `const enum` is fine but avoid cross-package const enums.

```ts
export enum Status { Ok = 1, Fail = 2 } // safe everywhere
```

---

## 3) Decorators and `emitDecoratorMetadata` (ordering + side effects)

Metadata requires `reflect-metadata` to be imported *first*, and the import is a side effect that bundlers may tree-shake away.

```ts
// must be the very first import in the entry file
import "reflect-metadata";

function Log(_target: any, _key: string) {}

class Service {
  @Log
  run(x: number) { return x; }
}
```

```json
{
  "compilerOptions": {
    "experimentalDecorators": true,
    "emitDecoratorMetadata": true
  }
}
```

Library `package.json`:

```json
{ "sideEffects": ["reflect-metadata", "*.css"] }
```

Also note TS 5.0+ has standard (non-experimental) decorators; do not mix both modes in one project.

---

## 4) `paths` / `baseUrl` are NOT rewritten by `tsc`

`tsc` type-checks against `paths`, but emitted JS still contains `"@/foo"`, which Node cannot resolve.

```ts
// src/main.ts
import { util } from "@/utils"; // resolves via tsconfig paths only
```

```json
{ "compilerOptions": { "baseUrl": ".", "paths": { "@/*": ["src/*"] } } }
```

Options:
- Use a bundler with alias resolution (Vite/Webpack/Rollup), **or**
- Avoid aliases in code that is emitted by plain `tsc` and consumed by Node.

---

## 5) NodeNext / ESM requires explicit `.js` extensions in source

With `"module": "NodeNext"`, TS demands the extension you will emit, even though the source file is `.ts`.

```ts
// src/index.ts
import { foo } from "./foo.js"; // points to foo.ts at build time, foo.js at runtime
```

If you later add a bundler that rewrites extensions, you get mismatches. Pick one strategy: either NodeNext + `.js` everywhere, or bundler-style extensionless imports and `moduleResolution: "bundler"`.

---

## 6) Declaration emit fails on non-exported inferred types

`declaration: true` cannot name a type that isn’t exported.

```ts
// internal.ts (not exported)
class Internal { value = 1 }

// api.ts
export class Api {
  // TS2742: inferred type cannot be named
  make() { return new Internal(); }
}
```

Fix: annotate or export.

```ts
import { Internal } from "./internal";
export class Api {
  make(): Internal { return new Internal(); }
}
```

---

## 7) Composite / project references and stale incremental caches

`composite: true` requires `declaration: true`, `outDir`, and usually `rootDir`. Incremental outputs can become stale in CI; force a clean build.

```json
// tsconfig.base.json
{ "compilerOptions": { "composite": true, "declaration": true, "outDir": "dist", "rootDir": "src" } }
```

```json
// tsconfig.json (solution style)
{ "files": [], "references": [{ "path": "packages/a" }, { "path": "packages/b" }] }
```

Build:

```bash
tsc -b --force   # CI: ignore tsbuildinfo cache
```

---

## 8) Conditional exports: `types` must come first

TypeScript (especially older versions) reads the first matching condition. If `import`/`default` come before `types`, resolution may pick runtime JS instead of `.d.ts`.

```json
{
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.mjs",
      "require": "./dist/index.cjs"
    },
    "./utils": {
      "types": "./dist/utils.d.ts",
      "default": "./dist/utils.js"
    }
  }
}
```

Also keep `typesVersions` for consumers on TS < 4.7 if you publish subpath types.

---

## 9) Tree-shaking vs. side-effect imports

`"sideEffects": false` lets bundlers drop “unused” modules, but it will also drop polyfills or CSS.

```json
{
  "sideEffects": [
    "*.css",
    "*.scss",
    "./src/polyfills.ts",
    "./src/registerComponents.ts"
  ]
}
```

For functions that are safe to drop when unused, add pure annotations:

```ts
export function heavy(x: number) {
  /*#__PURE__*/ return compute(x);
}
```

---

## 10) Circular dependencies and TDZ errors

Cycles can produce `Cannot access 'X' before initialization`. Type-only imports can break the cycle without changing runtime.

```ts
// a.ts
import type { B } from "./b"; // type-only: no runtime edge
import { createB } from "./b";

export class A {
  b?: B;
  make() { return createB(this); }
}
```

```ts
// b.ts
import type { A } from "./a";
import { A } from "./a"; // value import creates runtime cycle
```

Better: push shared types into a third leaf module, and use dynamic `import()` for heavy runtime cycles.

---

## 11) Source maps after bundling / publishing

Bundlers, minifiers, and `tsc` each need source maps enabled; relative paths often break after moving `dist/`.

```json
{
  "compilerOptions": {
    "sourceMap": true,
    "inlineSources": true,
    "declarationMap": true
  }
}
```

Bundler:

```ts
// vite.config.ts
export default { build: { sourcemap: true, minify: "esbuild" } };
```

For libraries, ship `*.d.ts.map` (`declarationMap`) so “Go to Definition” lands in source.

---

## 12) Ambient globals and wrong `lib` in non-browser builds

A Node library can accidentally include DOM types and compile references to `window`, or miss `node` types entirely.

```json
{
  "compilerOptions": {
    "lib": ["ES2022"],
    "types": ["node"],
    "skipLibCheck": true
  }
}
```

Avoid pulling in `@types/*` implicitly from nested `node_modules` in monorepos; pin `typeRoots` if needed.

---

## 13) Web Workers and dynamic imports

Bundlers need a special pattern to discover worker entry points and apply TS transforms to them.

```ts
// main.ts
const worker = new Worker(new URL("./worker.ts", import.meta.url), {
  type: "module",
});
worker.postMessage({ start: true });
```

```ts
// worker.ts
self.onmessage = (e: MessageEvent) => {
  self.postMessage({ ok: true, input: e.data });
};
```

This works in Vite/esbuild; Webpack may require `worker-loader` or `new Worker(new URL(...))` support depending on version.

---

## 14) Case sensitivity and file-name casing

On macOS/Windows (case-insensitive FS), `import "./Foo"` may resolve to `foo.ts` locally but fail in Linux CI.

```json
{
  "compilerOptions": {
    "forceConsistentCasingInFileNames": true
  }
}
```

Also ensure the bundler’s file resolution casing matches; enable in CI on Linux for authoritative checks.

---

## 15) `isolatedDeclarations` (TS 5.5+) and fast declaration emit

Newer tooling can emit `.d.ts` without full type inference, but it requires explicit annotations everywhere.

```json
{ "compilerOptions": { "isolatedDeclarations": true } }
```

```ts
// bad: return type inferred, declaration emitter cannot name it
export function make() { return { x: 1 }; }

// good
export function make(): { x: number } { return { x: 1 }; }
```

---

### Practical baseline config (app + bundler)

```json
{
  "compilerOptions": {
    "target": "ES2022",
    "module": "ESNext",
    "moduleResolution": "bundler",
    "strict": true,
    "isolatedModules": true,
    "verbatimModuleSyntax": true,
    "forceConsistentCasingInFileNames": true,
    "skipLibCheck": true,
    "sourceMap": true,
    "noEmit": true
  }
}
```

Let the bundler (Vite/esbuild/Rollup/tsup) own emission; use `tsc` only for type-checking. If you publish a library, switch to `declaration: true` + `emitDeclarationOnly: true` and set `composite`/`references` for monorepos.

Below is a complete, runnable TypeScript file that demonstrates several caching patterns you’ll actually use in production:

1. **TTL cache** – entries expire after a configurable time.
2. **LRU cache** – bounded size with least-recently-used eviction.
3. **Async cache with request coalescing** – deduplicates concurrent loads for the same key (the “thundering herd” fix).
4. **Type-safe memoization** – wraps a function.

Save as `cache.ts` and run with `npx ts-node cache.ts` (or `bun run cache.ts`, `deno run cache.ts`).

```ts
// cache.ts
// Complete, runnable caching examples in TypeScript.

/* ------------------------------------------------------------------ */
/* 1. TTL Cache                                                       */
/* ------------------------------------------------------------------ */

interface CacheEntry<T> {
  value: T;
  expiresAt: number; // epoch ms
}

export class TTLCache<K, V> {
  private store = new Map<K, CacheEntry<V>>();
  private defaultTtlMs: number;

  constructor(defaultTtlMs = 60_000) {
    this.defaultTtlMs = defaultTtlMs;
  }

  set(key: K, value: V, ttlMs?: number): void {
    const ttl = ttlMs ?? this.defaultTtlMs;
    this.store.set(key, {
      value,
      expiresAt: Date.now() + ttl,
    });
  }

  get(key: K): V | undefined {
    const entry = this.store.get(key);
    if (!entry) return undefined;
    if (Date.now() > entry.expiresAt) {
      this.store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  has(key: K): boolean {
    return this.get(key) !== undefined;
  }

  delete(key: K): boolean {
    return this.store.delete(key);
  }

  clear(): void {
    this.store.clear();
  }

  /** Remove expired entries (call periodically in long-lived processes). */
  prune(): number {
    const now = Date.now();
    let removed = 0;
    for (const [key, entry] of this.store) {
      if (now > entry.expiresAt) {
        this.store.delete(key);
        removed++;
      }
    }
    return removed;
  }

  get size(): number {
    this.prune();
    return this.store.size;
  }
}

/* ------------------------------------------------------------------ */
/* 2. LRU Cache (bounded, evicts least-recently-used)                 */
/* ------------------------------------------------------------------ */

export class LRUCache<K, V> {
  private capacity: number;
  private store = new Map<K, V>();

  constructor(capacity: number) {
    if (capacity <= 0) throw new Error("capacity must be > 0");
    this.capacity = capacity;
  }

  get(key: K): V | undefined {
    if (!this.store.has(key)) return undefined;
    const value = this.store.get(key)!;
    // Move to end (most recently used)
    this.store.delete(key);
    this.store.set(key, value);
    return value;
  }

  set(key: K, value: V): void {
    if (this.store.has(key)) {
      this.store.delete(key);
    } else if (this.store.size >= this.capacity) {
      // First key in Map is least recently used
      const lruKey = this.store.keys().next().value;
      if (lruKey !== undefined) this.store.delete(lruKey);
    }
    this.store.set(key, value);
  }

  has(key: K): boolean {
    return this.store.has(key);
  }

  delete(key: K): boolean {
    return this.store.delete(key);
  }

  clear(): void {
    this.store.clear();
  }

  get size(): number {
    return this.store.size;
  }
}

/* ------------------------------------------------------------------ */
/* 3. Async cache with request coalescing + TTL                       */
/* ------------------------------------------------------------------ */

interface AsyncEntry<V> {
  promise: Promise<V>;
  expiresAt: number;
}

export class AsyncCache<K, V> {
  private store = new Map<K, AsyncEntry<V>>();
  private defaultTtlMs: number;

  constructor(defaultTtlMs = 60_000) {
    this.defaultTtlMs = defaultTtlMs;
  }

  /**
   * Returns cached value if fresh; otherwise calls `loader(key)`.
   * Concurrent calls for the same key share one in-flight promise.
   */
  async getOrLoad(
    key: K,
    loader: (key: K) => Promise<V>,
    ttlMs?: number
  ): Promise<V> {
    const now = Date.now();
    const existing = this.store.get(key);

    if (existing && now <= existing.expiresAt) {
      return existing.promise;
    }

    // Stale or missing: kick off new load
    const ttl = ttlMs ?? this.defaultTtlMs;
    const promise = loader(key).catch((err) => {
      // Don't cache failures
      this.store.delete(key);
      throw err;
    });

    this.store.set(key, { promise, expiresAt: now + ttl });
    return promise;
  }

  invalidate(key: K): void {
    this.store.delete(key);
  }

  clear(): void {
    this.store.clear();
  }
}

/* ------------------------------------------------------------------ */
/* 4. Memoize a (possibly async) function                             */
/* ------------------------------------------------------------------ */

export function memoize<Args extends unknown[], R>(
  fn: (...args: Args) => R | Promise<R>,
  keyFn: (...args: Args) => string = (...args) => JSON.stringify(args),
  ttlMs = 60_000
): (...args: Args) => R | Promise<R> {
  const cache = new AsyncCache<string, R>(ttlMs);

  return (...args: Args) => {
    const key = keyFn(...args);
    // Sync fast-path: if cached value already resolved, return it synchronously
    // (kept simple here: always go through async cache for uniformity)
    return cache.getOrLoad(key, () => Promise.resolve(fn(...args))) as Promise<R>;
  };
}

/* ------------------------------------------------------------------ */
/* Demo / smoke test (runs when executed directly)                    */
/* ------------------------------------------------------------------ */

async function main() {
  console.log("=== TTL Cache ===");
  const ttl = new TTLCache<string, number>(1000);
  ttl.set("a", 42);
  console.log("get a:", ttl.get("a")); // 42
  await sleep(1100);
  console.log("get a after expiry:", ttl.get("a")); // undefined

  console.log("\n=== LRU Cache ===");
  const lru = new LRUCache<string, number>(2);
  lru.set("x", 1);
  lru.set("y", 2);
  lru.set("z", 3); // evicts x
  console.log("has x:", lru.has("x")); // false
  console.log("get y:", lru.get("y")); // 2
  lru.set("w", 4); // evicts z (y was touched)
  console.log("has z:", lru.has("z")); // false

  console.log("\n=== Async Cache (coalescing) ===");
  const asyncCache = new AsyncCache<string, string>(5000);
  let calls = 0;
  const loader = async (key: string) => {
    calls++;
    await sleep(200);
    return `value:${key}`;
  };

  const [r1, r2, r3] = await Promise.all([
    asyncCache.getOrLoad("k", loader),
    asyncCache.getOrLoad("k", loader),
    asyncCache.getOrLoad("k", loader),
  ]);
  console.log("results:", r1, r2, r3);
  console.log("loader calls (should be 1):", calls);

  console.log("\n=== Memoize ===");
  const expensive = (n: number) => {
    console.log(`  computing fib(${n})...`);
    if (n < 2) return n;
    return expensive(n - 1) + expensive(n - 2);
  };
  const memoFib = memoize((n: number) => expensive(n), (n) => String(n), 10_000) as (
    n: number
  ) => number;
  console.log("fib(5):", memoFib(5));
  console.log("fib(5) cached:", memoFib(5));

  console.log("\nAll demos passed.");
}

function sleep(ms: number): Promise<void> {
  return new Promise((res) => setTimeout(res, ms));
}

// Run if executed directly (works with ts-node / bun / deno with appropriate flags)
if (require.main === module) {
  main().catch((e) => {
    console.error(e);
    process.exit(1);
  });
}
```

### How to run

```bash
