# Caching Edge Cases in TypeScript

Below are the most common traps, each with a naive failure and an idiomatic fix. I’ve grouped them by theme.

---

## 1. Cache keys: reference equality vs. value equality

`Map` uses `SameValueZero`. Two distinct object literals with identical contents are different keys, and `NaN` keys collapse.

```ts
const cache = new Map<object, string>();
cache.set({ id: 1 }, "a");
cache.get({ id: 1 }); // undefined — different reference
```

**Fix:** canonicalize keys into a stable string. Handle `undefined`, `NaN`, `Date`, and key ordering.

```ts
function stableKey(value: unknown): string {
  const seen = new WeakSet<object>();
  const normalize = (v: unknown): unknown => {
    if (v === null || typeof v !== "object") {
      // NaN is not equal to itself; normalize to a sentinel
      if (typeof v === "number" && Number.isNaN(v)) return "__NaN__";
      return v;
    }
    if (seen.has(v as object)) throw new Error("Circular reference in cache key");
    seen.add(v as object);

    if (v instanceof Date) return { __type: "Date", v: v.toISOString() };
    if (Array.isArray(v)) return v.map(normalize);

    const out: Record<string, unknown> = {};
    for (const k of Object.keys(v as object).sort()) {
      out[k] = normalize((v as Record<string, unknown>)[k]);
    }
    return out;
  };
  return JSON.stringify(normalize(value));
}
```

---

## 2. Mutating cached values (shared-reference bugs)

Caching a reference and then mutating it corrupts every other consumer.

```ts
const cache = new Map<string, User>();
cache.set("u1", { name: "Ada", roles: ["admin"] });
const u = cache.get("u1")!;
u.roles.push("root"); // mutated the cached instance
```

**Fix:** store immutable data, or return a clone on read. Prefer `structuredClone` for deep safety; `Object.freeze` for shallow.

```ts
function get<T>(key: string): T | undefined {
  const v = store.get(key);
  return v === undefined ? undefined : structuredClone(v); // read isolation
}
function set<T>(key: string, v: T): void {
  store.set(key, structuredClone(v)); // write isolation
}
```

---

## 3. Async thundering herd (cache stampede)

On a cold/expired key, N concurrent requests all miss and all hit the origin.

```ts
async function getUser(id: string) {
  const cached = await redis.get(id);
  if (cached) return cached;
  const fresh = await db.fetchUser(id); // 50 concurrent calls
  await redis.set(id, fresh, "EX", 60);
  return fresh;
}
```

**Fix:** cache the in-flight `Promise`, not just the resolved value. Delete the entry only on failure (or keep a stale fallback).

```ts
class PromiseCache<K, V> {
  private inFlight = new Map<K, Promise<V>>();

  get(key: K, factory: () => Promise<V>): Promise<V> {
    const existing = this.inFlight.get(key);
    if (existing) return existing;

    const p = factory()
      .then((v) => {
        this.values.set(key, v); // separate resolved store
        return v;
      })
      .catch((err) => {
        this.inFlight.delete(key); // allow retry
        throw err;
      })
      .finally(() => {
        // keep promise cached briefly to coalesce near-simultaneous misses
      });

    this.inFlight.set(key, p);
    return p;
  }
  private values = new Map<K, V>();
}
```

A production version also stores a TTL and returns stale data while refreshing.

---

## 4. Stale-while-revalidate & expiry on read

`Date.now()` can move backward (NTP). Use relative monotonic time for TTL checks, and re-check expiry at read time, not just at write.

```ts
class TtlCache<K, V> {
  private store = new Map<K, { value: V; expiresAt: number }>();
  private now = () => performance.now(); // monotonic within process

  get(key: K, ttlMs: number): V | undefined {
    const e = this.store.get(key);
    if (!e) return undefined;
    if (this.now() > e.expiresAt) {
      this.store.delete(key);
      return undefined;
    }
    return structuredClone(e.value);
  }

  set(key: K, value: V, ttlMs: number) {
    this.store.set(key, { value: structuredClone(value), expiresAt: this.now() + ttlMs });
  }
}
```

For distributed caches, expiry is enforced by the store; still validate shape on read (see §7).

---

## 5. Negative caching (errors)

Caching a thrown error or `null` result prevents retry storms—but can also lock out recovery if you cache failures too long.

```ts
// Bad: cache null forever on a transient DB blip
const u = await cache.wrap("u1", () => db.fetchUser("u1"), { ttl: 3600 });
// returns null cached for an hour
```

**Fix:** distinguish "not found" (cacheable, short TTL) from "error" (don't cache, or cache with very short TTL + circuit breaker).

```ts
class ResultCache<K, V> {
  async get(key: K, factory: () => Promise<V | null>): Promise<V | null> {
    const cached = this.store.get(key);
    if (cached?.kind === "value") return cached.value;
    if (cached?.kind === "notfound" && !cached.expired()) return null;

    try {
      const v = await factory();
      if (v === null) this.store.set(key, { kind: "notfound", expiresAt: now() + 30_000 });
      else this.store.set(key, { kind: "value", value: v, expiresAt: now() + 300_000 });
      return v;
    } catch (e) {
      // do NOT cache; optionally cache a "negative" with 5s TTL for overload protection
      throw e;
    }
  }
}
```

---

## 6. Memory bounds & eviction

Unbounded `Map`s leak. Implement LRU (or use `lru-cache`). Also beware that V8 keeps closed-over large values alive.

```ts
import LRU from "lru-cache";

const cache = new LRU<string, Buffer>({
  max: 50 * 1024 * 1024, // 50 MB by size
  sizeCalculation: (v) => v.byteLength,
  ttl: 1000 * 60 * 5,
  allowStale: true, // enable stale-while-revalidate
});
```

**Edge case:** `sizeCalculation` must be accurate; for objects use a heuristic or byte length of serialized form. Also set `maxEntrySize` to reject huge single entries.

---

## 7. Type safety & runtime validation

TypeScript types don't survive serialization. A cached `User` from Redis is `unknown` at runtime.

```ts
const raw = await redis.get("u1");
const user = raw as User; // lie — could be old shape
```

**Fix:** validate with a schema (zod/io-ts) on every read, and version your cache keys.

```ts
import { z } from "zod";

const UserSchema = z.object({ id: z.string(), name: z.string(), v: z.literal(2) });
type User = z.infer<typeof UserSchema>;

async function getUser(id: string): Promise<User> {
  const raw = await redis.get(`user:v2:${id}`); // versioned key
  if (raw) {
    const parsed = UserSchema.safeParse(JSON.parse(raw));
    if (parsed.success) return parsed.data;
    // stale shape → treat as miss
  }
  const fresh = await db.fetchUser(id);
  await redis.set(`user:v2:${id}`, JSON.stringify({ ...fresh, v: 2 }));
  return fresh;
}
```

Bump the version segment (`v2` → `v3`) on breaking schema change to avoid parsing legacy data.

---

## 8. Serialization fidelity (distributed caches)

`JSON.stringify` drops `undefined`, `Date` → string, `Map`/`Set` → `{}`, `BigInt` throws, functions are omitted.

```ts
JSON.stringify({ d: new Date(), m: new Map([["a", 1]]), n: undefined, b: 1n });
// '{"d":"2024-...","m":{}}'  (undefined & BigInt gone/errored)
```

**Fix:** use a serializer that round-trips (superjson, devalue) or normalize to primitives before caching. Also handle `undefined` explicitly.

```ts
import superjson from "superjson";

await redis.set(key, superjson.stringify(value));
const value = superjson.parse(await redis.get(key));
```

For in-process caches, prefer storing native objects to avoid serialization entirely.

---

## 9. Weak references / GC-friendly caches

When keys are objects, a normal `Map` keeps them alive forever. Use `WeakMap` for derived/computed caches keyed by object identity.

```ts
const computed = new WeakMap<object, Result>();
function derive(obj: object): Result {
  let r = computed.get(obj);
  if (!r) {
    r = expensive(obj);
    computed.set(obj, r);
  }
  return r;
}
// when `obj` is GC'd, entry disappears automatically
```

**Edge case:** `WeakMap` keys must be objects (not primitives) and are not enumerable — fine for caches, but you can't iterate or clear.

---

## 10. Concurrency: cache invalidation ordering

Invalidate-then-update vs. update-then-invalidate can both cause stale reads. Use a monotonic version or "delete on write" with short TTL.

```ts
async function updateUser(id: string, patch: Partial<User>) {
  await db.update(id, patch);
  // Invalidate AFTER commit; readers re-fetch. Brief stale window is acceptable.
  await cache.del(`user:v2:${id}`);
}
```

For strict consistency, include a `version` column and check it on read (optimistic concurrency):

```ts
const cached = await cache.get(key);
if (cached && cached.version !== dbVersion) { /* refetch */ }
```

---

## 11. Cache key collisions & namespacing

Flat string keys collide across domains (`"123"` could be user or order). Namespace + version.

```ts
const ns = (domain: string, version: number) => `${domain}:v${version}:`;
const userKey = (id: string) => `${ns("user", 2)}${id}`;
```

---

## 12. Prefetch / warm-up & cold start

A cache miss on the first request after deploy causes latency spike. Warm critical keys at startup, but don't block ready on slow warm-up.

```ts
async function warmup() {
  const ids = await db.topUserIds(1000);
  await Promise.allSettled(ids.map((id) => getUser(id)));
}
// Fire-and-forget; app is ready regardless
warmup().catch(console.error);
```

---

## 13. Observability

Without metrics you can't tune TTL/size. Track hit rate, eviction count, and latency.

```ts
class InstrumentedCache<K, V> {
  private hits = 0, misses = 0;
  get(key: K): V | undefined {
    const v = this.store.get(key);
    if (v !== undefined) { this.hits++; return v; }
    this.misses++; return undefined;
  }
  stats() { return { hitRate: this.hits / (this.hits + this.misses) }; }
}
```

---

## 14. Clock & TTL in distributed systems

A client with a skewed clock can compute wrong expiry. Prefer server-side TTL (`EXPIRE`) over client-computed. When you must compute locally, use `Date.now()` only for relative deltas and re-validate with the store's TTL.

---

## Summary checklist

| Concern | Mitigation |
|---|---|
| Key equality | Stable canonical key + versioning |
| Mutation | Clone on read/write or immutable data |
| Stampede | Cache in-flight promises |
| Staleness | TTL + stale-while-revalidate + monotonic clock |
| Errors | Negative cache with short TTL; don't cache hard errors long |
| Memory | Bounded LRU + accurate size calc |
| Types | Schema validation + versioned keys |
| Serialization | superjson/devalue or normalize primitives |
| GC | WeakMap for object-keyed derived data |
| Consistency | Invalidate after commit; version tokens |
| Collisions | Namespaced keys |
| Cold start | Async warm-up |
| Observability | Hit/miss/eviction metrics |

The single biggest practical upgrade: **cache promises, not values**, combined with **versioned, namespaced keys** and **schema validation on read**. That eliminates most of the subtle bugs above.

Below is a complete, self-contained TypeScript module that implements a broad set of checksums and hashes from scratch, with a small streaming API, a name-based factory, and a runnable demo with known test vectors.

Save as `hashes.ts`, then run with `npx ts-node hashes.ts` (or compile with `tsc` and run with `node`).

```ts
// hashes.ts
// Checksums and hashes implemented in pure TypeScript.

// ---------------------------------------------------------------------------
// Utilities
// ---------------------------------------------------------------------------

export type Input = string | Uint8Array | ArrayBuffer | Buffer;

function toBytes(input: Input): Uint8Array {
  if (typeof input === 'string') return Buffer.from(input, 'utf8');
  if (input instanceof ArrayBuffer) return new Uint8Array(input);
  if (input instanceof Uint8Array) return input;
  // Node Buffer
  return new Uint8Array(input as any);
}

function toHex(bytes: Uint8Array): string {
  return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
}

function rotr(x: number, n: number): number {
  return ((x >>> n) | (x << (32 - n))) >>> 0;
}

// ---------------------------------------------------------------------------
// 1. Trivial checksums
// ---------------------------------------------------------------------------

export function sum8(input: Input): number {
  const b = toBytes(input);
  let s = 0;
  for (const x of b) s = (s + x) & 0xff;
  return s;
}

export function xor8(input: Input): number {
  const b = toBytes(input);
  let x = 0;
  for (const v of b) x ^= v;
  return x;
}

// ---------------------------------------------------------------------------
// 2. Fletcher
// ---------------------------------------------------------------------------

export function fletcher16(input: Input): number {
  const b = toBytes(input);
  let c0 = 0, c1 = 0;
  for (const x of b) {
    c0 = (c0 + x) % 255;
    c1 = (c1 + c0) % 255;
  }
  return (c1 << 8) | c0;
}

export function fletcher32(input: Input): number {
  const b = toBytes(input);
  let c0 = 0, c1 = 0;
  const words = Math.floor(b.length / 2);
  for (let i = 0; i < words; i++) {
    const w = b[i * 2] | (b[i * 2 + 1] << 8);
    c0 = (c0 + w) & 0xffff;
    c1 = (c1 + c0) & 0xffff;
  }
  if (b.length % 2) {
    const w = b[b.length - 1];
    c0 = (c0 + w) & 0xffff;
    c1 = (c1 + c0) & 0xffff;
  }
  return ((c1 & 0xffff) << 16) | (c0 & 0xffff);
}

// ---------------------------------------------------------------------------
// 3. Adler-32
// ---------------------------------------------------------------------------

export function adler32(input: Input): number {
  const b = toBytes(input);
  const MOD = 65521;
  let a = 1, bb = 0;
  for (const x of b) {
    a = (a + x) % MOD;
    bb = (bb + a) % MOD;
  }
  return ((bb << 16) | a) >>> 0;
}

// ---------------------------------------------------------------------------
// 4. CRCs (table-driven)
// ---------------------------------------------------------------------------

// CRC-8 / SMBUS  (poly 0x07, init 0, refin/refout false, xorout 0)
const CRC8_TABLE = (() => {
  const t = new Uint8Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) {
      c = (c & 0x80) ? ((c << 1) ^ 0x07) & 0xff : (c << 1) & 0xff;
    }
    t[i] = c;
  }
  return t;
})();

export function crc8(input: Input): number {
  const b = toBytes(input);
  let crc = 0;
  for (const x of b) crc = CRC8_TABLE[crc ^ x];
  return crc;
}

// CRC-16 / CCITT-FALSE (poly 0x1021, init 0xFFFF, refin/refout false)
const CRC16_TABLE = (() => {
  const t = new Uint16Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i << 8;
    for (let k = 0; k < 8; k++) {
      c = (c & 0x8000) ? ((c << 1) ^ 0x1021) & 0xffff : (c << 1) & 0xffff;
    }
    t[i] = c;
  }
  return t;
})();

export function crc16(input: Input): number {
  const b = toBytes(input);
  let crc = 0xffff;
  for (const x of b) {
    crc = ((crc << 8) ^ CRC16_TABLE[((crc >> 8) ^ x) & 0xff]) & 0xffff;
  }
  return crc;
}

// CRC-32 / IEEE 802.3 (zlib/gzip standard)
const CRC32_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    }
    t[i] = c >>> 0;
  }
  return t;
})();

export function crc32(input: Input): number {
  const b = toBytes(input);
  let crc = 0xffffffff;
  for (const x of b) crc = CRC32_TABLE[(crc ^ x) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

// ---------------------------------------------------------------------------
// 5. Non-cryptographic hashes
// ---------------------------------------------------------------------------

export function fnv1a32(input: Input): number {
  const b = toBytes(input);
  let h = 0x811c9dc5;
  for (const x of b) {
    h ^= x;
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

export function fnv1a64(input: Input): bigint {
  const b = toBytes(input);
  let h = 0xcbf29ce484222325n;
  const prime = 0x100000001b3n;
  for (const x of b) {
    h ^= BigInt(x);
    h = (h * prime) & 0xffffffffffffffffn;
  }
  return h;
}

export function djb2(input: Input): number {
  const b = toBytes(input);
  let h = 5381;
  for (const x of b) h = ((h << 5) + h + x) >>> 0;
  return h >>> 0;
}

export function sdbm(input: Input): number {
  const b = toBytes(input);
  let h = 0;
  for (const x of b) h = (x + (h << 6) + (h << 16) - h) >>> 0;
  return h >>> 0;
}

export function murmur3_32(input: Input, seed = 0): number {
  const b = toBytes(input);
  const c1 = 0xcc9e2d51, c2 = 0x1b873593;
  let h1 = seed >>> 0;
  const nblocks = b.length >>> 2;
  for (let i = 0; i < nblocks; i++) {
    let k1 = b[i * 4] | (b[i * 4 + 1] << 8) | (b[i * 4 + 2] << 16) | (b[i * 4 + 3] << 24);
    k1 = Math.imul(k1, c1) >>> 0;
    k1 = ((k1 << 15) | (k1 >>> 17)) >>> 0;
    k1 = Math.imul(k1, c2) >>> 0;
    h1 ^= k1;
    h1 = ((h1 << 13) | (h1 >>> 19)) >>> 0;
    h1 = (Math.imul(h1, 5) + 0xe6546b64) >>> 0;
  }
  let k1 = 0;
  const tail = nblocks * 4;
  switch (b.length & 3) {
    case 3: k1 ^= b[tail + 2] << 16;
    // eslint-disable-next-line no-fallthrough
    case 2: k1 ^= b[tail + 1] << 8;
    // eslint-disable-next-line no-fallthrough
    case 1:
      k1 ^= b[tail];
      k1 = Math.imul(k1, c1) >>> 0;
      k1 = ((k1 << 15) | (k1 >>> 17)) >>> 0;
      k1 = Math.imul(k1, c2) >>> 0;
      h1 ^= k1;
  }
  h1 ^= b.length;
  // finalization
  h1 ^= h1 >>> 16;
  h1 = Math.imul(h1, 0x85ebca6b) >>> 0;
  h1 ^= h1 >>> 13;
  h1 = Math.imul(h1, 0xc2b2ae35) >>> 0;
  h1 ^= h1 >>> 16;
  return h1 >>> 0;
}

// ---------------------------------------------------------------------------
// 6. SHA-256 (pure TypeScript)
// ---------------------------------------------------------------------------

const SHA256_K = new Uint32Array([
  0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
]);

export function sha256(input: Input): Uint8Array {
  const b = toBytes(input);
  const bitLen = b.length * 8;

  // pad to multiple of 64 bytes, at least +9
  const padLen = (b.length + 9 + 63) & ~63;
  const padded = new Uint8Array(padLen);
  padded.set(b);
  padded[b.length] = 0x80;
  const view = new DataView(padded.buffer);
  // 64-bit big-endian length (high 32 bits then low 32 bits)
  view.setUint32(padLen - 8, Math.floor(bitLen / 0x100000000), false);
  view.setUint32(padLen - 4, bitLen >>> 0, false);

  const H = new Uint32Array([
    0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
    0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
  ]);

  const W = new Uint32Array(64);
  for (let off = 0; off < padLen; off += 64) {
    for (let i = 0; i < 16; i++) W[i] = view.getUint32(off + i * 4, false);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(W[i - 15], 7) ^ rotr(W[i - 15], 18) ^ (W[i - 15] >>> 3);
      const s1 = rotr(W[i - 2], 17) ^ rotr(W[i - 2], 19) ^ (W[i - 2] >>> 10);
      W[i] = (W[i - 16] + s0 + W[i - 7] + s1) >>> 0;
    }
    let a = H[0], bb = H[1], c = H[2], d = H[3];
    let e = H[4], f = H[5], g = H[6], h = H[7];
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + SHA256_K[i] + W[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & bb) ^ (a & c) ^ (bb & c);
      const temp2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + temp1) >>> 0;
      d = c; c = bb; bb = a; a = (temp1 + temp2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + bb) >>> 0;
    H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0;
    H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }

  const out = new Uint8Array(32);
  for (let i = 0; i < 8; i++) {
    out[i * 4] = (H[i] >>> 24) & 0xff;
    out[i * 4 + 1] = (H[i] >>> 16) & 0xff;
    out[i * 4 + 2] = (H[i] >>> 8) & 0xff;
    out[i * 4 + 3] = H[i] & 0xff;
  }
  return out;
}

// ---------------------------------------------------------------------------
// 7. Streaming wrappers
// ---------------------------------------------------------------------------

export interface Hasher {
  update(data: Input): this;
  digestHex(): string;
  digestBytes(): Uint8Array;
  reset(): this;
}

export class Crc32Hasher implements Hasher {
  private crc = 0xffffffff;
  update(data: Input): this {
    const b = toBytes(data);
    for (const x of b) this.crc = CRC32_TABLE[(this.crc ^ x) & 0xff] ^ (this.crc >>> 8);
    return this;
  }
  digestHex(): string { return ((this.crc ^ 0xffffffff) >>> 0).toString(16).padStart(8, '0'); }
  digestBytes(): Uint8Array {
    const v = (this.crc ^ 0xffffffff) >>> 0;
    return new Uint8Array([(v >>> 24) & 0xff, (v >>> 16) & 0xff, (v >>> 8) & 0xff, v & 0xff]);
  }
  reset(): this { this.crc = 0xffffffff; return this; }
}

export class Sha256Hasher implements Hasher {
  private chunks: Uint8Array[] = [];
  update(data: Input): this { this.chunks.push(toBytes(data)); return this; }
  private concat(): Uint8Array {
    const len = this.chunks.reduce((s, c) => s + c.length, 0);
    const out = new Uint8Array(len);
    let off = 0;
    for (const c of this.chunks) { out.set(c, off); off += c.length; }
    return out;
  }
  digestHex(): string { return toHex(sha256(this.concat())); }
  digestBytes(): Uint8Array { return sha256(this.concat()); }
  reset(): this { this.chunks = []; return this; }
}

// ---------------------------------------------------------------------------
// 8. Name-based factory
// ---------------------------------------------------------------------------

export type HashName = 'sum8' | 'xor8' | 'fletcher16' | 'fletcher32' | 'adler32' |
  'crc8' | 'crc16' | 'crc32' | 'fnv1a32' | 'fnv1a64' | 'djb2' | 'sdbm' |
  'murmur3_32' | 'sha256';

export function hash(name: HashName, input: Input): string | number | bigint | Uint8Array {
  switch (name) {
    case 'sum8': return sum8(input);
    case 'xor8': return xor8(input);
    case 'fletcher16': return fletcher16(input);
    case 'fletcher32': return fletcher32(input);
    case 'adler32': return adler32(input);
    case 'crc8': return crc8(input);
    case 'crc16': return crc16(input);
    case 'crc32': return crc32(input);
    case 'fnv1a32': return fnv1a32(input);
    case 'fnv1a64': return fnv1a64(input);
    case 'djb2': return djb2(input);
    case 'sdbm': return sdbm(input);
    case 'murmur3_32': return murmur3_32(input);
    case 'sha256': return toHex(sha256(input));
  }
}

// ---------------------------------------------------------------------------
// Demo / self-test
// ---------------------------------------------------------------------------

function main() {
  const s = '123456789';
  const buf = Buffer.from(s, 'utf8');

  console.log('Input:', s);
  console.log('sum8       :', sum8(s));
  console.log('xor8       :', xor8(s).toString(16));
  console.log('fletcher16 :', fletcher16(s).toString(16));
  console.log('fletcher32 :', fletcher32(s).toString(16));
  console.log('adler32    :', adler32(s).toString(16).padStart(8, '0'),
              '(expect 0910039b)');
  console.log('crc8       :', crc8(s).toString(16).padStart(2, '0'),
              '(expect f4)');
  console.log('crc16      :', crc16(s).toString(16).padStart(4, '0'),
              '(expect 29b1)');
  console.log('crc32      :', crc32(s).toString(16).padStart(8, '0'),
              '(expect cbf43926)');
  console.log('fnv1a32    :', fnv1a32(s).toString(16).padStart(8, '0'));
  console.log('fnv1a64    :', fnv1a64(s).toString(16).padStart(16, '0'));
  console.log('djb2       :', djb2(s).toString(16).padStart(8, '0'));
  console.log('sdbm       :', sdbm(s).toString(16).padStart(8, '0'));
  console.log('murmur3_32 :', murmur3_32(s).toString(16).padStart(8, '0'));
  console.log('sha256     :', toHex(sha256(s)),
              '(expect ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad)');

  // streaming sanity check
  const h = new Sha256Hasher();
  h.update('abc').update('def');
  console.log('streaming sha256(abcdef):', h.digestHex());

  // empty input vectors
