## Final solution

`src/integrity.ts`

```ts
import { createHash } from "crypto";
import { readFile, writeFile, stat } from "fs/promises";
import { existsSync } from "fs";
import path from "path";

export interface FileRecord {
  sha256: string;
  xor: string;        // hex string of 1-byte XOR
  size: number;
  mtimeMs: number;
}

export type Manifest = Record<string, FileRecord>;

export class FileIntegrityChecker {
  private manifestPath: string;
  private manifest: Manifest = {};

  constructor(manifestPath = "manifest.json") {
    this.manifestPath = path.resolve(manifestPath);
    this.load();
  }

  private load(): void {
    if (existsSync(this.manifestPath)) {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      this.manifest = require(this.manifestPath) as Manifest;
    }
  }

  private async save(): Promise<void> {
    await writeFile(
      this.manifestPath,
      JSON.stringify(this.manifest, null, 2),
      "utf8"
    );
  }

  /** Cryptographic hash: SHA-256 of file contents. */
  async computeSha256(filePath: string): Promise<string> {
    const data = await readFile(filePath);
    return createHash("sha256").update(data).digest("hex");
  }

  /** Naive checksum: XOR of all bytes (weak, for teaching). */
  async computeXorChecksum(filePath: string): Promise<string> {
    const data = await readFile(filePath);
    let acc = 0;
    for (const byte of data) acc ^= byte;
    return acc.toString(16).padStart(2, "0");
  }

  /** Record current state of a file into the manifest. */
  async record(filePath: string): Promise<FileRecord> {
    const abs = path.resolve(filePath);
    const [sha256, xor, st] = await Promise.all([
      this.computeSha256(abs),
      this.computeXorChecksum(abs),
      stat(abs),
    ]);
    const rec: FileRecord = {
      sha256,
      xor,
      size: st.size,
      mtimeMs: st.mtimeMs,
    };
    this.manifest[abs] = rec;
    await this.save();
    return rec;
  }

  /** Verify a file against its recorded hash. */
  async verify(filePath: string): Promise<
    | { status: "ok"; record: FileRecord }
    | { status: "changed"; record: FileRecord; current: FileRecord }
    | { status: "unknown" }
  > {
    const abs = path.resolve(filePath);
    const stored = this.manifest[abs];
    if (!stored) return { status: "unknown" };

    const [sha256, xor, st] = await Promise.all([
      this.computeSha256(abs),
      this.computeXorChecksum(abs),
      stat(abs),
    ]);
    const current: FileRecord = {
      sha256,
      xor,
      size: st.size,
      mtimeMs: st.mtimeMs,
    };

    const unchanged = stored.sha256 === current.sha256;
    return unchanged
      ? { status: "ok", record: stored }
      : { status: "changed", record: stored, current };
  }
}
```

`src/demo.ts`

```ts
import { writeFile, unlink } from "fs/promises";
import { FileIntegrityChecker } from "./integrity";

async function main() {
  const checker = new FileIntegrityChecker("manifest.json");

  const file = "sample.txt";
  await writeFile(file, "Hello, checksums!\n", "utf8");

  // 1. Record baseline
  const rec = await checker.record(file);
  console.log("Recorded:", rec);

  // 2. Verify unchanged
  console.log("Verify #1:", await checker.verify(file));

  // 3. Tamper with file
  await writeFile(file, "Hello, checksums?\n", "utf8");
  const result = await checker.verify(file);
  console.log("Verify #2 (tampered):", result);

  // 4. Show XOR weakness: two different strings can share XOR checksum
  const a = Buffer.from("AB");
  const b = Buffer.from("BA");
  const xor = (buf: Buffer) => buf.reduce((x, byte) => x ^ byte, 0);
  console.log("XOR('AB') =", xor(a).toString(16));
  console.log("XOR('BA') =", xor(b).toString(16));

  // cleanup
  await unlink(file);
  console.log("Demo complete.");
}

main().catch(console.error);
```

