### Recommended Utility Module

```ts
// hash-utils.ts
import { createHash, createHmac, timingSafeEqual, randomBytes, scryptSync } from "node:crypto";
import { createReadStream } from "node:fs";

export function hashUtf8(input: string, algo = "sha256"): string {
  return createHash(algo).update(input.normalize("NFC"), "utf8").digest("hex");
}

export function hashBuffer(buf: Buffer, algo = "sha256"): string {
  return createHash(algo).update(buf).digest("hex");
}

export async function hashFile(path: string, algo = "sha256"): Promise<string> {
  return new Promise((resolve, reject) => {
    const h = createHash(algo);
    const s = createReadStream(path);
    s.on("data", (c) => h.update(c));
    s.on("end", () => resolve(h.digest("hex")));
    s.on("error", reject);
  });
}

export function secureEqual(a: string, b: string): boolean {
  const ba = Buffer.from(a.toLowerCase().replace(/^0x/, ""), "hex");
  const bb = Buffer.from(b.toLowerCase().replace(/^0x/, ""), "hex");
  if (ba.length !== bb.length) return false;
  return timingSafeEqual(ba, bb);
}

export function canonicalHash(obj: unknown): string {
  const canon = canonicalJson(obj);
  return createHash("sha256").update(canon).digest("hex");
}

function canonicalJson(v: unknown): string {
  if (v === null) return "null";
  if (v === undefined) return "undefined";
  if (typeof v === "string") return JSON.stringify(v);
  if (typeof v === "number") return Number.isFinite(v) ? v.toString() : "NaN";
  if (typeof v === "boolean") return String(v);
  if (typeof v === "bigint") return `"bigint:${v}"`;
  if (v instanceof Date) return `"date:${v.toISOString()}"`;
  if (Array.isArray(v)) return "[" + v.map(canonicalJson).join(",") + "]";
  if (v instanceof Map) {
    return "{" + [...v.entries()]
      .map(([k, val]) => `${JSON.stringify(k)}:${canonicalJson(val)}`)
      .sort()
      .join(",") + "}";
  }
  if (v instanceof Set) {
    return "[" + [...v].map(canonicalJson).sort().join(",") + "]";
  }
  const keys = Object.keys(v as object).sort();
  return "{" + keys.map((k) => `${JSON.stringify(k)}:${canonicalJson((v as any)[k])}`).join(",") + "}";
}

export function hmac(key: string, msg: string, algo = "sha256"): string {
  return createHmac(algo, key).update(msg).digest("hex");
}

export function hashPassword(password: string): string {
  const salt = randomBytes(16);
  const derived = scryptSync(password, salt, 64);
  return `${salt.toString("hex")}:${derived.toString("hex")}`;
}

export function verifyPassword(password: string, stored: string): boolean {
  const [saltHex, hashHex] = stored.split(":");
  if (!saltHex || !hashHex) return false;
  const salt = Buffer.from(saltHex, "hex");
  const hash = Buffer.from(hashHex, "hex");
  const derived = scryptSync(password, salt, 64);
  if (derived.length !== hash.length) return false;
  return timingSafeEqual(hash, derived);
}
```

This covers the vast majority of real-world pitfalls. The key themes: **normalize inputs, never compare with `===`, stream large data, canonicalize objects, and never reuse hash instances across concurrent work.**

Below is a single, self-contained TypeScript file that demonstrates the main ways to define and use classes and objects in TypeScript, including encapsulation, inheritance, abstraction, generics, and both TypeScript (`private`) and ECMAScript (`#private`) privacy.

Save it as `main.ts`.

```ts
// main.ts
// Run with: npx ts-node main.ts   OR   tsc main.ts && node main.js

/* ------------------------------------------------------------------ */
/* 1. A basic class with fields, constructor, methods, getters/setters */
/* ------------------------------------------------------------------ */
class Person {
  // Public by default
  name: string;
  age: number;

  // TypeScript-only privacy (compile-time)
  private id: string;

  // ECMAScript private field (runtime privacy)
  #secret: string;

  // Static members belong to the class, not instances
  static species = "Homo sapiens";

  constructor(name: string, age: number) {
    this.name = name;
    this.age = age;
    this.id = globalThis.crypto?.randomUUID?.() ?? `id-${Date.now()}`;
    this.#secret = "hidden-value";
  }

  // Instance method
  greet(): string {
    return `Hi, I'm ${this.name}, ${this.age} years old.`;
  }

  // Getter
  get info(): string {
    return `${this.name} (${this.age}) [id=${this.id}]`;
  }

  // Setter
  set years(v: number) {
    if (v < 0) throw new Error("Age cannot be negative");
    this.age = v;
  }

  // Static factory
  static create(name: string, age: number): Person {
    return new Person(name, age);
  }
}

/* ------------------------------------------------------------------ */
/* 2. Parameter properties + readonly + methods                       */
/* ------------------------------------------------------------------ */
class Point {
  // Parameter properties auto-create and assign fields
  constructor(
    public x: number,
    public y: number,
    public readonly z: number = 0
  ) {}

  distanceTo(other: Point): number {
    const dx = this.x - other.x;
    const dy = this.y - other.y;
    const dz = this.z - other.z;
    return Math.sqrt(dx * dx + dy * dy + dz * dz);
  }

  // Method returning a new object (immutable style)
  translate(dx: number, dy: number): Point {
    return new Point(this.x + dx, this.y + dy, this.z);
  }
}

/* ------------------------------------------------------------------ */
/* 3. Inheritance + polymorphism                                      */
/* ------------------------------------------------------------------ */
class Employee extends Person {
  constructor(
    name: string,
    age: number,
    public role: string
  ) {
    super(name, age); // must call super first
  }

  // Override base method
  override greet(): string {
    return `${super.greet()} I work as a ${this.role}.`;
  }
}

/* ------------------------------------------------------------------ */
/* 4. Abstract class + interface                                      */
/* ------------------------------------------------------------------ */
interface Measurable {
  area(): number;
}

abstract class Shape implements Measurable {
  abstract area(): number;

  describe(): string {
    return `This shape has area ${this.area().toFixed(2)}.`;
  }
}

class Circle extends Shape {
  constructor(public radius: number) {
    super();
  }

  area(): number {
    return Math.PI * this.radius ** 2;
  }
}

class Rectangle extends Shape {
  constructor(public width: number, public height: number) {
    super();
  }

  area(): number {
    return this.width * this.height;
  }
}

/* ------------------------------------------------------------------ */
/* 5. Generic class                                                   */
/* ------------------------------------------------------------------ */
class Box<T> {
  constructor(public value: T) {}

  map<U>(fn: (v: T) => U): Box<U> {
    return new Box(fn(this.value));
  }

  toString(): string {
    return `Box(${String(this.value)})`;
  }
}

/* ------------------------------------------------------------------ */
/* 6. Plain object types (not classes) for comparison                  */
/* ------------------------------------------------------------------ */
type User = {
  id: number;
  name: string;
  email?: string; // optional
};

const alice: User = { id: 1, name: "Alice" };

/* ------------------------------------------------------------------ */
/* 7. Runtime demo                                                    */
/* ------------------------------------------------------------------ */
function main(): void {
  const p = Person.create("Bob", 28);
  console.log(p.greet());
  console.log(p.info);
  p.years = 29;
  console.log("After birthday:", p.age);

  const e = new Employee("Carol", 35, "Engineer");
  console.log(e.greet());

  const a = new Point(0, 0, 0);
  const b = new Point(3, 4, 0);
  console.log("distance:", a.distanceTo(b));
  console.log("translated:", a.translate(1, 1));

  const shapes: Shape[] = [new Circle(5), new Rectangle(4, 6)];
  for (const s of shapes) console.log(s.describe());

  const box = new Box<number>(42).map((n) => n * 2).map((n) => `value=${n}`);
  console.log(box.toString());

  // instanceof checks
  console.log("p instanceof Person:", p instanceof Person);
  console.log("e instanceof Employee:", e instanceof Employee);
  console.log("e instanceof Person:", e instanceof Person);

  // Object literal
  console.log("user:", alice);
}

main();
```

