## Practical Example: Encapsulated Domain Model

```ts
class BankAccount {
  private transactions: number[] = [];

  constructor(public owner: string, private balance = 0) {}

  deposit(amount: number) {
    if (amount <= 0) throw new Error("Amount must be positive");
    this.balance += amount;
    this.transactions.push(amount);
  }

  withdraw(amount: number) {
    if (amount > this.balance) throw new Error("Insufficient funds");
    this.balance -= amount;
    this.transactions.push(-amount);
  }

  get currentBalance() { return this.balance; }
  statement() { return [...this.transactions]; }
}

const acc = new BankAccount("Ada", 100);
acc.deposit(50);
console.log(acc.currentBalance); // 150
```

