```typescript
// closures.ts — comprehensive demonstration of closures in TypeScript.

/* ================================================================== */
/* 1. Basic lexical capture                                            */
/* ================================================================== */
// The inner function "closes over" `x`, keeping it alive after makeAdder
// returns. Each call to makeAdder creates a *fresh* binding of x.
function makeAdder(x: number): (y: number) => number {
  return (y: number) => x + y;
}

/* ================================================================== */
/* 2. Mutable private state (counter)                                   */
/* ================================================================== */
interface Counter {
  increment(): number;
  decrement(): number;
  value(): number;
  reset(): void;
}

function createCounter(initial: number = 0): Counter {
  let count = initial; // private, captured by reference
  return {
    increment: () => ++count,
    decrement: () => --count,
    value: () => count,
    reset: () => {
      count = initial;
    },
  };
}

/* ================================================================== */
/* 3. Independent closures from one factory                             */
/* ================================================================== */
// Two calls produce two separate `total` bindings. They do not interfere.
function createAccumulator(initial: number = 0): (n: number) => number {
  let total = initial;
  return (n: number) => (total += n);
}

/* ================================================================== */
/* 4. IIFE module pattern                                               */
/* ================================================================== */
// The outer function runs once; `secret` is never reachable from outside.
const secretModule = (() => {
  let secret = 0;
  const bump = () => ++secret;
  const peek = () => secret;
  return Object.freeze({ bump, peek });
})();

/* ================================================================== */
/* 5. Partial application & currying                                    */
/* ================================================================== */
function partial(
  fn: (...args: any[]) => any,
  ...preset: any[]
): (...rest: any[]) => any {
  return (...rest: any[]) => fn(...preset, ...rest);
}

function curry2<A, B, R>(fn: (a: A, b: B) => R): (a: A) => (b: B) => R {
  return (a: A) => (b: B) => fn(a, b);
}

/* ================================================================== */
/* 6. Encapsulation: bank account with truly private balance            */
/* ================================================================== */
interface BankAccount {
  deposit(amount: number): number;
  withdraw(amount: number): number;
  balance(): number;
}

function createAccount(owner: string, openingBalance: number = 0): BankAccount {
  let balance = openingBalance; // unreachable from outside
  const log = (msg: string) => console.log(`[${owner}] ${msg}`);
  return {
    deposit(amount: number): number {
      if (amount <= 0) throw new Error("deposit amount must be positive");
      balance += amount;
      log(`deposited ${amount}, balance now ${balance}`);
      return balance;
    },
    withdraw(amount: number): number {
      if (amount > balance) throw new Error("insufficient funds");
      balance -= amount;
      log(`withdrew ${amount}, balance now ${balance}`);
      return balance;
    },
    balance: () => balance,
  };
}

/* ================================================================== */
/* 7. Memoization backed by a closure-held cache                        */
/* ================================================================== */
function memoize<Args extends any[], R>(
  fn: (...args: Args) => R
): (...args: Args) => R {
  const cache = new Map<string, R>();
  return (...args: Args): R => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key)!;
    const result = fn(...args);
    cache.set(key, result);
    return result;
  };
}

/* ================================================================== */
/* 8. Loop variable capture: the classic pitfall                        */
/* ================================================================== */
function makeHandlers(count: number): Array<() => number> {
  const handlers: Array<() => number> = [];
  for (let i = 0; i < count; i++) {
    // `let` creates a fresh binding per iteration, so each closure
    // captures its OWN `i`. Output: [0, 1, 2]
    handlers.push(() => i);
  }
  return handlers;
}

function makeHandlersBuggy(count: number): Array<() => number> {
  const handlers: Array<() => number> = [];
  for (var i = 0; i < count; i++) {
    // All closures share the single function-scoped `i`. Output: [3,3,3]
    handlers.push(() => i);
  }
  return handlers;
}

/* ================================================================== */
/* 9. `this` capture: arrow functions vs regular functions             */
/* ================================================================== */
class Timer {
  private ticks = 0;

  start(): () => void {
    // Arrow function captures lexical `this` (the Timer instance).
    const tick = () => {
      this.ticks++;
    };
    const handle = setInterval(tick, 10);
    return () => clearInterval(handle);
  }

  getTicks(): number {
    return this.ticks;
  }
}

/* ================================================================== */
/* 10. Generic closure factory with validation                         */
/* ================================================================== */
function makeValidator<T>(
  predicate: (v: T) => boolean,
  message: string
): (v: T) => void {
  return (v: T) => {
    if (!predicate(v)) throw new Error(message);
  };
}

/* ================================================================== */
/* 11. Closures "as data": implementing a closure explicitly           */
/* ================================================================== */
// This is what a JS engine does conceptually: a closure = environment + code.
interface Closure<Env, Args extends any[], R> {
  readonly env: Env;
  readonly call: (env: Env, ...args: Args) => R;
}

function makeClosure<Env, Args extends any[], R>(
  env: Env,
  call: (env: Env, ...args: Args) => R
): (...args: Args) => R {
  // The returned function closes over both `env` and `call`.
  return (...args: Args) => call(env, ...args);
}

interface Env { x: number; y: number; }

/* ================================================================== */
/* Demo entry point                                                    */
/* ================================================================== */
function main(): void {
  console.log("== 1. Basic adder ==");
  const add5 = makeAdder(5);
  console.log(add5(3), add5(10)); // 8 15

  console.log("== 2. Counter ==");
  const c = createCounter(10);
  console.log(c.increment(), c.increment(), c.decrement(), c.value()); // 11 12 11 11
  c.reset();
  console.log("reset ->", c.value()); // 10

  console.log("== 3. Independent accumulators ==");
  const a = createAccumulator(0);
  const b = createAccumulator(100);
  console.log(a(5), a(3), b(1)); // 5 8 101  (independent state)

  console.log("== 4. IIFE module ==");
  console.log(secretModule.bump(), secretModule.bump(), secretModule.peek()); // 1 2 2

  console.log("== 5. Partial / curry ==");
  const greet = (g: string, n: string) => `${g}, ${n}!`;
  const sayHi = partial(greet, "Hi");
  console.log(sayHi("Ada")); // Hi, Ada!
  const curriedAdd = curry2((x: number, y: number) => x + y);
  console.log(curriedAdd(2)(3)); // 5

  console.log("== 6. Bank account ==");
  const acc = createAccount("Alice", 50);
  acc.deposit(25);
  acc.withdraw(10);
  console.log("balance", acc.balance()); // 65
  // acc.balance = ...  // impossible: only the interface is exposed

  console.log("== 7. Memoize (fibonacci) ==");
  let calls = 0;
  let fib: (n: number) => number;
  fib = memoize((n: number): number => {
    calls++;
    if (n < 2) return n;
    return fib(n - 1) + fib(n - 2);
  });
  console.log("fib(10) =", fib(10), "direct calls =", calls);
  console.log("fib(10) again =", fib(10), "direct calls =", calls); // cached

  console.log("== 8. Loop handlers ==");
  console.log("correct:", makeHandlers(3).map((h) => h())); // [0, 1, 2]
  console.log("buggy:  ", makeHandlersBuggy(3).map((h) => h())); // [3, 3, 3]

  console.log("== 9. Timer (lexical this) ==");
  const t = new Timer();
  const stop = t.start();
  setTimeout(() => {
    stop();
    console.log("ticks ~", t.getTicks()); // ~3
  }, 40);

  console.log("== 10. Validator ==");
  const isPositive = makeValidator<number>((n) => n > 0, "must be positive");
  isPositive(5);
  try {
    isPositive(-1);
  } catch (e) {
    console.log((e as Error).message); // must be positive
  }

  console.log("== 11. Closure as data ==");
  const closure = makeClosure<Env, [number], number>(
    { x: 10, y: 20 },
    (env, delta: number) => env.x + env.y + delta
  );
  console.log(closure(5)); // 35
}

main();
```

