### `src/review.ts`

```ts
// src/review.ts
// A small, dependency-free model of a code-review workflow.
// Run with: npm run demo

import { strict as assert } from "node:assert";

/* ------------------------------------------------------------------ */
/* Domain types                                                       */
/* ------------------------------------------------------------------ */

export type Id = string;

export interface User {
  id: Id;
  name: string;
  role?: "author" | "reviewer" | "maintainer";
}

export type PrStatus = "open" | "merged" | "closed";
export type ReviewVerdict = "approved" | "changes_requested" | "commented";

export interface FileChange {
  path: string;
  oldContent: string;
  newContent: string;
}

export interface Comment {
  id: Id;
  prId: Id;
  authorId: Id;
  filePath: string;
  /** 1-based line number in the *new* version of the file */
  line: number;
  body: string;
  resolved: boolean;
  createdAt: Date;
}

export interface Review {
  id: Id;
  prId: Id;
  reviewerId: Id;
  verdict: ReviewVerdict;
  body: string;
  createdAt: Date;
}

export interface PullRequest {
  id: Id;
  title: string;
  description: string;
  authorId: Id;
  baseBranch: string;
  headBranch: string;
  files: FileChange[];
  comments: Comment[];
  reviews: Review[];
  status: PrStatus;
  createdAt: Date;
  mergedAt?: Date;
}

export interface DiffLine {
  type: "context" | "add" | "remove";
  oldLineNo?: number;
  newLineNo?: number;
  content: string;
}

export interface DiffHunk {
  path: string;
  lines: DiffLine[];
}

export interface LintFinding {
  severity: "info" | "warning" | "error";
  message: string;
}

/* ------------------------------------------------------------------ */
/* Errors                                                             */
/* ------------------------------------------------------------------ */

export class ReviewError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ReviewError";
  }
}

/* ------------------------------------------------------------------ */
/* Diff engine (LCS-based)                                            */
/* ------------------------------------------------------------------ */

export function diffLines(oldContent: string, newContent: string): DiffLine[] {
  const oldLines = oldContent.split("\n");
  const newLines = newContent.split("\n");
  const m = oldLines.length;
  const n = newLines.length;

  // dp[i][j] = LCS length of oldLines[i..] and newLines[j..]
  const dp: number[][] = Array.from({ length: m + 1 }, () =>
    new Array<number>(n + 1).fill(0)
  );

  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      if (oldLines[i] === newLines[j]) {
        dp[i][j] = 1 + dp[i + 1][j + 1];
      } else {
        dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1]);
      }
    }
  }

  const result: DiffLine[] = [];
  let i = 0;
  let j = 0;
  while (i < m && j < n) {
    if (oldLines[i] === newLines[j]) {
      result.push({
        type: "context",
        oldLineNo: i + 1,
        newLineNo: j + 1,
        content: oldLines[i],
      });
      i++;
      j++;
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      result.push({ type: "remove", oldLineNo: i + 1, content: oldLines[i] });
      i++;
    } else {
      result.push({ type: "add", newLineNo: j + 1, content: newLines[j] });
      j++;
    }
  }
  while (i < m) {
    result.push({ type: "remove", oldLineNo: i + 1, content: oldLines[i] });
    i++;
  }
  while (j < n) {
    result.push({ type: "add", newLineNo: j + 1, content: newLines[j] });
    j++;
  }
  return result;
}

export function diffFile(file: FileChange): DiffHunk {
  return { path: file.path, lines: diffLines(file.oldContent, file.newContent) };
}

export function formatDiff(hunk: DiffHunk): string {
  const out: string[] = [`--- a/${hunk.path}`, `+++ b/${hunk.path}`];
  for (const l of hunk.lines) {
    const prefix = l.type === "add" ? "+" : l.type === "remove" ? "-" : " ";
    out.push(`${prefix} ${l.content}`);
  }
  return out.join("\n");
}

/* ------------------------------------------------------------------ */
/* Store / workflow                                                   */
/* ------------------------------------------------------------------ */

export class ReviewStore {
  private users = new Map<Id, User>();
  private prs = new Map<Id, PullRequest>();

  private prCounter = 0;
  private commentCounter = 0;
  private reviewCounter = 0;

  /* ---------- users ---------- */

  addUser(user: User): void {
    if (this.users.has(user.id)) {
      throw new ReviewError(`User ${user.id} already exists`);
    }
    this.users.set(user.id, user);
  }

  getUser(id: Id): User | undefined {
    return this.users.get(id);
  }

  /* ---------- pull requests ---------- */

  createPR(input: {
    title: string;
    description: string;
    authorId: Id;
    baseBranch: string;
    headBranch: string;
    files: FileChange[];
  }): PullRequest {
    const author = this.users.get(input.authorId);
    if (!author) throw new ReviewError(`Unknown author: ${input.authorId}`);
    if (!input.title?.trim()) throw new ReviewError("PR title is required");
    if (!input.files || input.files.length === 0) {
      throw new ReviewError("PR must contain at least one changed file");
    }

    const id = `pr-${++this.prCounter}`;
    const pr: PullRequest = {
      id,
      title: input.title.trim(),
      description: input.description ?? "",
      authorId: input.authorId,
      baseBranch: input.baseBranch,
      headBranch: input.headBranch,
      files: input.files,
      comments: [],
      reviews: [],
      status: "open",
      createdAt: new Date(),
    };
    this.prs.set(id, pr);
    return pr;
  }

  getPR(id: Id): PullRequest {
    const pr = this.prs.get(id);
    if (!pr) throw new ReviewError(`Unknown PR: ${id}`);
    return pr;
  }

  listPRs(filter?: { status?: PrStatus; authorId?: Id }): PullRequest[] {
    return [...this.prs.values()].filter((pr) => {
      if (filter?.status && pr.status !== filter.status) return false;
      if (filter?.authorId && pr.authorId !== filter.authorId) return false;
      return true;
    });
  }

  /* ---------- comments ---------- */

  addComment(
    prId: Id,
    input: { authorId: Id; filePath: string; line: number; body: string }
  ): Comment {
    const pr = this.getPR(prId);
    if (pr.status !== "open") {
      throw new ReviewError(`Cannot comment on a ${pr.status} PR`);
    }
    const author = this.users.get(input.authorId);
    if (!author) throw new ReviewError(`Unknown user: ${input.authorId}`);
    if (!input.body?.trim()) throw new ReviewError("Comment body is required");

    const file = pr.files.find((f) => f.path === input.filePath);
    if (!file) {
      throw new ReviewError(`File not in PR: ${input.filePath}`);
    }

    const newLineCount = file.newContent === "" ? 0 : file.newContent.split("\n").length;
    // Allow line 0 for "file-level" comments on empty files.
    if (input.line < 0 || input.line > newLineCount) {
      throw new ReviewError(
        `Line ${input.line} out of range for ${input.filePath} (1..${newLineCount})`
      );
    }

    const id = `c-${++this.commentCounter}`;
    const comment: Comment = {
      id,
      prId,
      authorId: input.authorId,
      filePath: input.filePath,
      line: input.line,
      body: input.body.trim(),
      resolved: false,
      createdAt: new Date(),
    };
    pr.comments.push(comment);
    return comment;
  }

  resolveComment(prId: Id, commentId: Id, actorId: Id): Comment {
    const pr = this.getPR(prId);
    const comment = pr.comments.find((c) => c.id === commentId);
    if (!comment) throw new ReviewError(`Unknown comment: ${commentId}`);
    if (!this.users.has(actorId)) throw new ReviewError(`Unknown user: ${actorId}`);

    // A comment may be resolved by its author, the PR author, or any reviewer.
    const isReviewer = pr.reviews.some((r) => r.reviewerId === actorId);
    const allowed =
      actorId === comment.authorId ||
      actorId === pr.authorId ||
      isReviewer;
    if (!allowed) {
      throw new ReviewError("Only the comment author, PR author, or a reviewer may resolve a comment");
    }
    comment.resolved = true;
    return comment;
  }

  /* ---------- reviews ---------- */

  submitReview(
    prId: Id,
    input: { reviewerId: Id; verdict: ReviewVerdict; body?: string }
  ): Review {
    const pr = this.getPR(prId);
    if (pr.status !== "open") {
      throw new ReviewError(`Cannot review a ${pr.status} PR`);
    }
    const reviewer = this.users.get(input.reviewerId);
    if (!reviewer) throw new ReviewError(`Unknown reviewer: ${input.reviewerId}`);
    if (input.reviewerId === pr.authorId) {
      throw new ReviewError("Authors cannot review their own pull request");
    }

    const id = `r-${++this.reviewCounter}`;
    const review: Review = {
      id,
      prId,
      reviewerId: input.reviewerId,
      verdict: input.verdict,
      body: (input.body ?? "").trim(),
      createdAt: new Date(),
    };
    pr.reviews.push(review);
    return review;
  }

  /* ---------- merge / close ---------- */

  merge(prId: Id, actorId: Id): PullRequest {
    const pr = this.getPR(prId);
    if (pr.status !== "open") {
      throw new ReviewError(`PR is not open: ${pr.status}`);
    }
    if (!this.users.has(actorId)) {
      throw new ReviewError(`Unknown user: ${actorId}`);
    }

    const approvingReviewers = new Set(
      pr.reviews.filter((r) => r.verdict === "approved").map((r) => r.reviewerId)
    );
    if (approvingReviewers.size === 0) {
      throw new ReviewError("At least one approval from a distinct reviewer is required");
    }

    const unresolved = pr.comments.filter((c) => !c.resolved);
    if (unresolved.length > 0) {
      throw new ReviewError(
        `${unresolved.length} unresolved comment(s) must be resolved before merge`
      );
    }

    // A reviewer who requested changes blocks merge unless they later approved.
    const blocking = new Set(
      pr.reviews
        .filter((r) => r.verdict === "changes_requested")
        .map((r) => r.reviewerId)
    );
    for (const r of approvingReviewers) blocking.delete(r);
    if (blocking.size > 0) {
      throw new ReviewError(
        `Merge blocked by ${blocking.size} reviewer(s) requesting changes`
      );
    }

    pr.status = "merged";
    pr.mergedAt = new Date();
    return pr;
  }

  close(prId: Id, actorId: Id): PullRequest {
    const pr = this.getPR(prId);
    if (pr.status !== "open") throw new ReviewError(`PR is not open: ${pr.status}`);
    if (!this.users.has(actorId)) throw new ReviewError(`Unknown user: ${actorId}`);
    pr.status = "closed";
    return pr;
  }

  /* ---------- convenience ---------- */

  diffPR(prId: Id): DiffHunk[] {
    return this.getPR(prId).files.map(diffFile);
  }
}

/* ------------------------------------------------------------------ */
/* PR hygiene linting ("code review practice" checks)                  */
/* ------------------------------------------------------------------ */

export function lintPR(pr: PullRequest): LintFinding[] {
  const findings: LintFinding[] = [];

  if (pr.title.length < 10) {
    findings.push({ severity: "warning", message: "PR title is very short (< 10 chars)" });
  }
  if (pr.title.length > 72) {
    findings.push({ severity: "warning", message: "PR title exceeds 72 chars" });
  }
  if (!pr.description.trim()) {
    findings.push({ severity: "warning", message: "PR has no description" });
  }
  if (pr.files.length === 0) {
    findings.push({ severity: "error", message: "PR has no changed files" });
  }
  if (pr.files.length > 10) {
    findings.push({ severity: "warning", message: `PR touches ${pr.files.length} files (> 10)` });
  }

  let added = 0;
  let removed = 0;
  for (const file of pr.files) {
    const hunk = diffFile(file);
    for (const line of hunk.lines) {
      if (line.type === "add") added++;
      if (line.type === "remove") removed++;
    }
    // Smell checks on added lines.
    for (const line of hunk.lines) {
      if (line.type !== "add") continue;
      if (/console\.log\b/.test(line.content)) {
        findings.push({
          severity: "warning",
          message: `${file.path}:${line.newLineNo} adds a console.log`,
        });
      }
      if (/TODO|FIXME|XXX/.test(line.content)) {
        findings.push({
          severity: "info",
          message: `${file.path}:${line.newLineNo} adds a TODO/FIXME`,
        });
      }
    }
  }

  const changed = added + removed;
  if (changed > 400) {
    findings.push({
      severity: "error",
      message: `PR is too large: ${changed} changed lines (> 400)`,
    });
  } else if (changed > 200) {
    findings.push({
      severity: "warning",
      message: `PR is sizable: ${changed} changed lines (> 200)`,
    });
  }

  return findings;
}

/* ------------------------------------------------------------------ */
/* Demo                                                               */
/* ------------------------------------------------------------------ */

function demo(): void {
  const store = new ReviewStore();

  store.addUser({ id: "alice", name: "Alice", role: "author" });
  store.addUser({ id: "bob", name: "Bob", role: "reviewer" });
  store.addUser({ id: "carol", name: "Carol", role: "reviewer" });

  const pr = store.createPR({
    title: "Add greeting utility",
    description: "Introduces a small greet() helper with tests.",
    authorId: "alice",
    baseBranch: "main",
    headBranch: "feat/greet",
    files: [
      {
        path: "src/greet.ts",
        oldContent: "",
        newContent: "export function greet(name: string): string {\n  return `Hello, ${name}!`;\n}\n",
      },
      {
        path: "src/greet.test.ts",
        oldContent: "",
        newContent:
          "import { greet } from './greet';\n\ntest('greet', () => {\n  expect(greet('world')).toBe('Hello, world!');\n});\n",
      },
    ],
  });

  console.log("=== PR created ===");
  console.log(`${pr.id}: ${pr.title} by ${pr.authorId}`);
  console.log();

  console.log("=== Diff ===");
  for (const hunk of store.diffPR(pr.id)) {
    console.log(formatDiff(hunk));
    console.log();
  }

  console.log("=== Lint findings ===");
  for (const f of lintPR(pr)) console.log(`[${f.severity}] ${f.message}`);
  console.log();

  // Bob reviews and requests a change.
  const review1 = store.submitReview(pr.id, {
    reviewerId: "bob",
    verdict: "changes_requested",
    body: "Please add input validation.",
  });
  console.log(`Bob submitted review: ${review1.verdict}`);

  // Bob leaves a line comment.
  const comment = store.addComment(pr.id, {
    authorId: "bob",
    filePath: "src/greet.ts",
    line: 1,
    body: "What happens with empty name?",
  });
  console.log(`Bob commented: ${comment.body}`);

  // Alice cannot review her own PR.
  try {
    store.submitReview(pr.id, { reviewerId: "alice", verdict: "approved" });
  } catch (e) {
    console.log(`Expected error: ${(e as Error).message}`);
  }

  // Merge should fail (no approval, unresolved comment, blocking review).
  try {
    store.merge(pr.id, "alice");
  } catch (e) {
    console.log(`Expected merge failure: ${(e as Error).message}`);
  }

  // Alice resolves the comment.
  store.resolveComment(pr.id, comment.id, "alice");
  console.log("Comment resolved.");

  // Carol approves.
  store.submitReview(pr.id, { reviewerId: "carol", verdict: "approved", body: "LGTM" });
  console.log("Carol approved.");

  // Bob re-reviews and approves (clears his earlier block).
  store.submitReview(pr.id, { reviewerId: "bob", verdict: "approved", body: "Validation addressed." });
  console.log("Bob approved.");

  // Now merge succeeds.
  const merged = store.merge(pr.id, "alice");
  console.log(`\nPR ${merged.id} merged at ${merged.mergedAt?.toISOString()}`);

  // Further comments are rejected.
  try {
    store.addComment(pr.id, { authorId: "carol", filePath: "src/greet.ts", line: 1, body: "late" });
  } catch (e) {
    console.log(`Expected error: ${(e as Error).message}`);
  }

  /* ---- assertions (self-test) ---- */
  assert.equal(merged.status, "merged");
  assert.equal(store.listPRs({ status: "open" }).length, 0);
  console.log("\nAll assertions passed.");
}

// Run demo when executed directly.
if (require.main === module) {
  demo();
}
```

### How to run

```bash
cd code-review-practice
npm install
npm run typecheck
npm run demo
```

### What this demonstrates (code-review practice)

1. **Small, focused PRs** – enforced via `lintPR` (size, file count, title length).
2. **Readable diffs** – a real LCS diff (`diffLines`/`formatDiff`), not just string replacement.
3. **Review separation of duties** – authors cannot review/approve their own PR.
4. **Actionable comments** – line-anchored, resolvable, with permission checks.
5. **Merge gates** – requires ≥1 distinct approval, no unresolved comments, and no outstanding “changes requested”.
6. **Hygiene checks** – flags `console.log`, TODOs, oversized PRs.
7. **Immutable-ish state transitions** – `open → merged/closed` with explicit errors for illegal ops.

You can extend it with: persistent storage (SQLite/Postgres), GitHub/GitLab API adapters, a web UI, required-reviewer rules, CODEOWNERS, or signed commits. The core domain logic stays the same.

## Code review in TypeScript: idea, syntax, and typical use cases

### 1. The idea

Code review is a **gate before merge**: a second (or third) pair of eyes checks a diff for correctness, readability, and maintainability. In TypeScript the reviewer’s superpower is the **compiler + linter + tests**, not just style.

Typical flow:

```
branch → commit(s) → PR → CI (tsc --noEmit, eslint, tests) → review comments → changes → approve → merge
```

TypeScript-specific goals during review:
- **Type honesty**: no `any` hiding bugs; prefer `unknown` + narrowing.
- **API stability**: public interfaces/types don’t break callers silently.
- **Exhaustiveness**: `switch`/pattern matching covers all union cases.
- **Null safety**: `strictNullChecks` enforced, no accidental `undefined`.
- **Readability over cleverness**: generics should help, not obscure.

---

### 2. “Syntax” of a review (what reviewers actually write)

Reviews are mostly **markdown comments on a diff**, plus **automated checks**. Common comment shapes:

```markdown
**Blocking**: This returns `any`; narrow with a type guard.
**Nit**: Prefer `const` over `let`.
**Suggestion**:
```suggestion
return result satisfies Foo;
```
```

TypeScript syntax a reviewer scrutinizes:

| Concern | Syntax example |
|---|---|
| Unsafe cast | `x as any` |
| Non-null assertion | `user!.name` |
| Overly broad type | `Record<string, any>` |
| Missing exhaustiveness | `switch (status)` without `default: assertNever` |

---

### 3. Typical use cases with short examples

#### A. Reviewing a new utility function
**Before (author):**
```ts
export function parseId(input: any) {
  return Number(input);
}
```
**Reviewer feedback:**
```markdown
Avoid `any`. Accept `unknown` and validate.
```
**After:**
```ts
export function parseId(input: unknown): number {
  if (typeof input !== 'string' && typeof input !== 'number') {
    throw new Error('Invalid id');
  }
  const n = Number(input);
  if (Number.isNaN(n)) throw new Error('Not a number');
  return n;
}
```

#### B. Reviewing an API/type contract
**Before:**
```ts
interface User {
  id: string;
  email?: string; // optional but used everywhere
}
```
**Reviewer:**
> Make email required or document why optional; “optional everywhere” is a smell.

**After (if truly optional):**
```ts
interface User {
  id: string;
  email: string | null; // explicit
}
```

#### C. Reviewing a discriminated union / exhaustive switch
**Before:**
```ts
type Status = 'idle' | 'loading' | 'success' | 'error';

function label(s: Status) {
  switch (s) {
    case 'idle': return 'Idle';
    case 'loading': return 'Loading';
    // forgot 'success'/'error'
  }
}
```
**Reviewer suggestion (exhaustiveness):**
```ts
function assertNever(x: never): never {
  throw new Error(`Unexpected: ${x}`);
}

function label(s: Status) {
  switch (s) {
    case 'idle': return 'Idle';
    case 'loading': return 'Loading';
    case 'success': return 'Done';
    case 'error': return 'Failed';
    default: return assertNever(s);
  }
}
```

#### D. Reviewing async code + errors
**Before:**
```ts
async function loadUser(id: string) {
  const res = await fetch(`/api/users/${id}`);
  return res.json();
}
```
**Reviewer:**
> Check `res.ok`, type the JSON, handle network errors.

**After:**
```ts
type User = { id: string; name: string };

async function loadUser(id: string): Promise<User> {
  const res = await fetch(`/api/users/${id}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return (await res.json()) as User; // or runtime validate with zod
}
```

#### E. Reviewing React props (common in TS codebases)
**Before:**
```tsx
function Button(props: any) {
  return <button onClick={props.onClick}>{props.children}</button>;
}
```
**After:**
```tsx
type ButtonProps = {
  onClick: () => void;
  children: React.ReactNode;
  disabled?: boolean;
};

function Button({ onClick, children, disabled = false }: ButtonProps) {
  return (
    <button onClick={onClick} disabled={disabled}>
      {children}
    </button>
  );
}
```

---

### 4. Practical review checklist (TypeScript-focused)

- [ ] `tsc --noEmit` passes; no new `any` without justification.
- [ ] Public types are exported and documented.
- [ ] No `!` non-null assertions unless proven safe.
- [ ] Unions handled exhaustively.
- [ ] Async paths typed and error cases considered.
- [ ] Tests updated; coverage not dropped.
- [ ] PR is small enough to review in ~15–30 min.

---

### 5. Tooling that makes reviews reliable

```json
// tsconfig.json (review-enforced baseline)
{
  "compilerOptions": {
    "strict": true,
    "noImplicitAny": true,
    "strictNullChecks": true,
    "noUncheckedIndexedAccess": true
  }
}
```

```yaml
# .github/workflows/review.yml
- run: npx tsc --noEmit
- run: npx eslint . --max-warnings 0
- run: npm test
```

**Bottom line:** In TypeScript, a good review is less about bikeshedding style and more about **making the type system prove the code is safe**—then humans confirm intent and readability.

## Mistake

```ts
function calculateOrderTotal(order: any): number {
  let total = 0;

  for (const item of order.items) {
    total += item.price * item.qty;
  }

  // Apply coupon if present
  const discount = order.coupon ? order.coupon.value : 0;

  // HACK: coupon should always exist in production
  return total - discount!;
}
```

### Why reviewers would reject this

- **`any` removes the type boundary.** `order`, `item`, and `coupon` are all unchecked, so typos like `item.qty` instead of `item.quantity`, missing fields, or malformed API data can compile successfully and fail at runtime.
- **The non-null assertion (`!`) is an unverified assumption.** It tells TypeScript “trust me,” but nothing actually proves `discount` is defined. It can hide real null/undefined errors.
- **No input validation.** Negative prices, `NaN`, missing arrays, or malformed coupon objects are accepted silently.
- **Weak naming and leaky intent.** `qty` is not necessarily wrong, but mixing `price * qty` without a domain type makes the function harder to review and refactor.
- **Magic behavior.** The `HACK` comment signals known uncertainty but does not make the code safe or explicit.

---

## Corrected version

```ts
type OrderItem = {
  price: number;
  quantity: number;
};

type Coupon = {
  value: number;
};

type Order = {
  items: readonly OrderItem[];
  coupon?: Coupon;
};

function isFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

function calculateOrderTotal(order: Order): number {
  if (!Array.isArray(order.items)) {
    throw new TypeError("order.items must be an array");
  }

  const subtotal = order.items.reduce((sum, item) => {
    if (!isFiniteNumber(item.price) || item.price < 0) {
      throw new TypeError("item.price must be a finite non-negative number");
    }
    if (!isFiniteNumber(item.quantity) || item.quantity < 0) {
      throw new TypeError("item.quantity must be a finite non-negative number");
    }
    return sum + item.price * item.quantity;
  }, 0);

  const discount = order.coupon?.value ?? 0;

  if (!isFiniteNumber(discount) || discount < 0) {
    throw new TypeError("coupon.value must be a finite non-negative number");
  }

  return Math.max(0, subtotal - discount);
}
```

---

## What changed and why

### 1. Replaced `any` with explicit domain types

```ts
type OrderItem = { price: number; quantity: number };
type Coupon = { value: number };
type Order = { items: readonly OrderItem[]; coupon?: Coupon };
```

This makes the function’s contract reviewable. A reviewer can see exactly what shape is expected, including that `coupon` is optional and `items` should not be mutated.

### 2. Removed the non-null assertion

```ts
const discount = order.coupon?.value ?? 0;
```

Instead of `discount!`, the code uses optional chaining and nullish coalescing. This expresses the intent directly: “use the coupon value if it exists; otherwise use zero.”

### 3. Validated numeric invariants

The corrected function checks:

- `price` is finite and non-negative
- `quantity` is finite and non-negative
- `discount` is finite and non-negative

This prevents silent bad results such as `NaN` totals or negative pricing producing nonsensical outcomes.

### 4. Made the reducer explicit

Using `reduce` with an initial value of `0` avoids relying on an implicit empty-array behavior and makes the accumulation logic easier to inspect during review.

### 5. Returned a safe total

```ts
return Math.max(0, subtotal - discount);
```

This guards against the unlikely but possible case where a discount exceeds the subtotal. Whether that is desirable depends on business rules, but making the behavior explicit is better than allowing a negative total.

---

## Reviewer-friendly improvements you could add

For production code, reviewers often also want:

- **Schema validation at boundaries**, such as using Zod, io-ts, or a DTO mapper before calling business logic.
- **Unit tests** for normal totals, empty carts, missing coupons, invalid values, and discount edge cases.
- **No mutation of inputs**, preserved here by typing `items` as `readonly OrderItem[]`.
- **Clear error types**, such as custom `ValidationError` instead of generic `TypeError`.
- **No leftover comments like `HACK`**, because uncertainty should be tracked as an issue or handled explicitly.

This version is still small, but it converts an implicit, compiler-silenced shortcut into an explicit and reviewable contract.

# Common TypeScript Code Review Pitfalls

Below are the pitfalls I most often flag in TypeScript code reviews, grouped by theme, each with a short "bad → good" example.

---

## 1. Escape hatches that erase type safety

### 1.1 `any` instead of `unknown`
```ts
// Bad
function parse(input: any) {
  return input.foo.bar; // no checks, no errors
}

// Good
function parse(input: unknown) {
  if (typeof input === "object" && input !== null && "foo" in input) {
    const foo = (input as { foo?: unknown }).foo;
    // ...validate further
  }
  throw new Error("Invalid input");
}
```

### 1.2 Overusing `as` (type assertions)
```ts
// Bad
const user = apiResponse as User; // lies to the compiler

// Good — validate at the boundary
function isUser(x: unknown): x is User {
  return typeof x === "object" && x !== null && "id" in x && "email" in x;
}
const user = isUser(apiResponse) ? apiResponse : null;
```

### 1.3 Non-null assertion `!`
```ts
// Bad
const name = user!.profile!.name; // crashes at runtime

// Good
const name = user?.profile?.name ?? "Anonymous";
```

---

## 2. Null/undefined handling

### 2.1 Truthiness on numbers/strings
```ts
// Bad
if (count) { /* skips 0 */ }
if (name) { /* skips "" */ }

// Good
if (count !== undefined && count !== null) { ... }
if (name !== undefined) { ... }
```

### 2.2 Optional chaining that hides bugs
```ts
// Bad — silently returns undefined, hides missing data
const city = order?.customer?.address?.city;

// Good — fail loudly at the boundary
if (!order?.customer?.address?.city) throw new Error("Missing city");
const city = order.customer.address.city;
```

### 2.3 `noUncheckedIndexedAccess` not enabled
```ts
// With noUncheckedIndexedAccess: true
const arr = [1, 2, 3];
const x = arr[10]; // number | undefined, not number
// Bad
function sum(a: number[]) { return a[0] + a[1]; } // possibly undefined
// Good
function sum(a: number[]) {
  const [a0, a1] = a;
  if (a0 === undefined || a1 === undefined) throw new Error("need 2");
  return a0 + a1;
}
```

---

## 3. Type design

### 3.1 `Object` / `{}` instead of `object` / `Record`
```ts
// Bad
function f(x: {}) { x.foo = 1; } // {} means "any non-nullish", allows writes
function g(x: Object) { }

// Good
function f(x: Record<string, unknown>) { }
function g(x: object) { }
```

### 3.2 Loose generics
```ts
// Bad
function wrap<T = any>(value: T) { return { value }; }

// Good
function wrap<T>(value: T): { value: T } { return { value }; }
```

### 3.3 Mutable types that should be readonly
```ts
// Bad
interface Config { apiUrl: string; }
function apply(cfg: Config) { cfg.apiUrl = "x"; } // mutation leak

// Good
interface Config { readonly apiUrl: string; }
function apply(cfg: Readonly<Config>) { ... }
```

### 3.4 Enums pitfalls
```ts
// Bad — numeric enum, reverse mapping, tree-shaking issues
enum Status { Pending, Done }

// Good — string literal union or const object
type Status = "pending" | "done";
// or
const Status = { Pending: "pending", Done: "done" } as const;
type Status = typeof Status[keyof typeof Status];
```

---

## 4. Control flow & exhaustiveness

### 4.1 Not handling `never` / missing default
```ts
// Bad
type Shape = { kind: "circle"; r: number } | { kind: "square"; side: number };
function area(s: Shape) {
  if (s.kind === "circle") return Math.PI * s.r ** 2;
  // forgot square — silently returns undefined
}

// Good
function area(s: Shape): number {
  switch (s.kind) {
    case "circle": return Math.PI * s.r ** 2;
    case "square": return s.side ** 2;
    default: {
      const _exhaustive: never = s;
      throw new Error(`Unhandled shape: ${JSON.stringify(_exhaustive)}`);
    }
  }
}
```

### 4.2 Type narrowing lost after reassignment
```ts
// Bad
let x: string | number = Math.random() > 0.5 ? "a" : 1;
if (typeof x === "string") {
  x = 42; // now number, narrowing lost for later code
}
console.log(x.toUpperCase()); // error or wrong

// Good — use const or separate variables
const x = Math.random() > 0.5 ? "a" : 1;
if (typeof x === "string") console.log(x.toUpperCase());
```

---

## 5. Async / Promise pitfalls

### 5.1 Floating promises
```ts
// Bad
async function save() {
  db.insert(row); // not awaited, errors swallowed
}

// Good
async function save() {
  await db.insert(row);
}
// and enable no-floating-promises in ESLint
```

### 5.2 `Promise.all` vs `allSettled`
```ts
// Bad — one rejection rejects everything, losing partial results
const results = await Promise.all(items.map(fetch));

// Good when partial failure is OK
const results = await Promise.allSettled(items.map(fetch));
```

### 5.3 `async` function returning wrong type
```ts
// Bad
async function get(): Promise<User> {
  const r = await fetch("/user");
  return r.json(); // Promise<any> implicitly
}

// Good
async function get(): Promise<User> {
  const r = await fetch("/user");
  const data: unknown = await r.json();
  if (!isUser(data)) throw new Error("bad shape");
  return data;
}
```

### 5.4 `catch` variable typed as `unknown` (TS 4.4+)
```ts
// Bad (pre-4.4 style still seen)
try { ... } catch (e) {
  console.log(e.message); // e is unknown now
}

// Good
try { ... } catch (e) {
  if (e instanceof Error) console.log(e.message);
  else console.log(String(e));
}
```

---

## 6. Classes & `this`

### 6.1 Losing `this` when passing methods as callbacks
```ts
class Counter {
  count = 0;
  inc() { this.count++; }
}
const c = new Counter();
setTimeout(c.inc, 100); // `this` is undefined

// Good
setTimeout(() => c.inc(), 100);
// or arrow property
inc = () => { this.count++; };
```

### 6.2 Property initialization order / `useDefineForClassFields`
```ts
// Bad (depends on emit target)
class Foo {
  x = this.compute(); // ordering issues
  compute() { return 1; }
}

// Good — initialize in constructor or factory
class Foo {
  x: number;
  constructor() { this.x = this.compute(); }
  compute() { return 1; }
}
```

---

## 7. Modules & imports

### 7.1 Default exports
```ts
// Bad
export default function foo() {}
import foo from "./foo"; // name drift across files

// Good
export function foo() {}
import { foo } from "./foo";
```

### 7.2 Type-only imports not separated (bundling/eraser)
```ts
// Bad (can pull runtime code into type-only positions)
import { User, fetchUser } from "./api";

// Good
import type { User } from "./api";
import { fetchUser } from "./api";
```

### 7.3 Barrel files causing circular deps
```ts
// index.ts re-exports everything → import cycles, slow builds
// Good: import from specific modules; use `export type` where possible.
```

---

## 8. `satisfies` vs annotation (TS 4.9+)

```ts
// Bad — annotation widens literals
const routes: Record<string, string> = {
  home: "/",
  about: "/about",
}; // routes.home is string, not "/"

// Good — keeps inference, checks shape
const routes = {
  home: "/",
  about: "/about",
} as const satisfies Record<string, string>;
// routes.home === "/"
```

---

## 9. Object/array mutation & reference equality

### 9.1 Mutating props in React / state
```ts
// Bad
state.items.push(x);
setState(state);

// Good
setState(prev => ({ ...prev, items: [...prev.items, x] }));
```

### 9.2 `Array.prototype.sort` mutates
```ts
// Bad
const sorted = items.sort((a, b) => a - b); // mutates items

// Good
const sorted = [...items].sort((a, b) => a - b);
```

---

## 10. Type narrowing in callbacks

```ts
// Bad — narrowing not preserved across closure
function f(x: string | null) {
  if (x) {
    setTimeout(() => console.log(x.toUpperCase()), 0); // x narrowed? In TS yes within closure if const... actually let loses
  }
}
// With `let`, narrowing is not preserved inside closures.

// Good — capture into const
function f(x: string | null) {
  if (!x) return;
  const value = x;
  setTimeout(() => console.log(value.toUpperCase()), 0);
}
```

---

## 11. `in` operator and discriminants

```ts
// Bad — checking property existence on union without narrowing
function handle(e: MouseEvent | KeyboardEvent) {
  if (e.key) { ... } // e.key may not exist → error or wrong
}

// Good
function handle(e: MouseEvent | KeyboardEvent) {
  if ("key" in e) { e.key; } // narrows to KeyboardEvent
}
```

---

## 12. Template literal types & string parsing

```ts
// Bad — parsing with regex and casting
const id = path.split("/")[1] as string;

// Good — validate
function parseId(path: string): string | null {
  const m = path.match(/^\/users\/([^/]+)$/);
  return m?.[1] ?? null;
}
```

---

## 13. `readonly` arrays and tuples

```ts
// Bad — accepts mutable, allows mutation inside
function sum(arr: number[]) { arr.push(0); return arr.reduce((a,b)=>a+b,0); }

// Good
function sum(arr: readonly number[]) { return arr.reduce((a,b)=>a+b,0); }
```

---

## 14. Overload ordering

```ts
// Bad — broader overload first shadows narrower
function f(x: string | number): string;
function f(x: string): "str";
function f(x: any) { return String(x); }

// Good — narrower first
function f(x: string): "str";
function f(x: string | number): string;
function f(x: any) { return String(x); }
```

---

## 15. `const` assertions and literal widening

```ts
// Bad
let config = { env: "prod" }; // env: string

// Good
const config = { env: "prod" } as const; // env: "prod"
```

---

## Recommended tsconfig / lint baseline

```json
{
  "compilerOptions": {
    "strict": true,
    "noUncheckedIndexedAccess": true,
    "exactOptionalPropertyTypes": true,
    "noImplicitOverride": true,
    "noFallthroughCasesInSwitch": true,
    "useUnknownInCatchVariables": true,
    "verbatimModuleSyntax": true
  }
}
```

ESLint (typescript-eslint): `no-explicit-any`, `no-floating-promises`, `no-misused-promises`, `consistent-type-imports`, `switch-exhaustiveness-check`.

---

### Review checklist (quick)
- No `any` / `as` without a comment justifying it.
- No `!` unless preceded by an explicit runtime check.
- All `switch` on unions are exhaustive.
- Promises are awaited or explicitly voided with `void`.
- Public APIs use `readonly` and `unknown` at boundaries.
- Tests cover the "undefined" branches introduced by strict null checks.

If you want, I can drill into any one of these (e.g., generic constraints, conditional types, or React-specific pitfalls) with deeper examples.

## Exercise

Review this TypeScript function as if it were a pull request. Identify correctness, type-safety, maintainability, and side-effect issues, then propose a corrected version.

```ts
function processUsers(users: any[]) {
  const result: any[] = [];
  for (let i = 0; i <= users.length; i++) {
    const user = users[i];
    if (user.active) {
      user.lastSeen = new Date();
      result.push({ id: user.id, name: user.name.toUpperCase() });
    }
  }
  return result;
}
```

---

## Step-by-step code review

### 1. Type safety
- `users: any[]` disables compile-time checking.
- `result: any[]` hides the output contract.
- `user.name.toUpperCase()` can crash if `name` is `null`/`undefined`.
- `user.id` may be missing or of an unexpected type.

### 2. Correctness bug
- `i <= users.length` causes an extra iteration.
- On the last iteration, `users[users.length]` is `undefined`, so `user.active` throws.

### 3. Side effects / mutation
- `user.lastSeen = new Date()` mutates the caller’s objects.
- This makes the function impure and harder to test, and can cause unexpected behavior elsewhere.

### 4. Missing edge cases
- Empty array is fine, but `null`/`undefined` input is not handled.
- Inactive users are skipped, but no explicit typing communicates that.
- `name` may not be a string.

### 5. API design
- No return type.
- No documentation.
- Mixing data transformation with timestamp mutation.

---

## Improved design

Separate concerns:

1. Define a clear input type.
2. Define a clear output type.
3. Avoid mutating input.
4. Use strict, safe transformations.
5. Handle invalid/missing fields deliberately.

```ts
export interface User {
  id: string | number;
  name: string;
  active: boolean;
  lastSeen?: Date;
}

export interface ProcessedUser {
  id: string | number;
  name: string;
}

/**
 * Returns active users in a normalized, non-mutating form.
 */
export function processUsers(users: readonly User[]): ProcessedUser[] {
  const result: ProcessedUser[] = [];

  for (const user of users) {
    if (!user.active) {
      continue;
    }

    result.push({
      id: user.id,
      name: user.name.trim().toUpperCase(),
    });
  }

  return result;
}
```

### Why this is better
- `readonly User[]` prevents accidental mutation of the input array.
- Explicit return type documents the contract.
- No off-by-one loop because `for...of` iterates exactly over elements.
- No mutation of user objects.
- `name` is typed as `string`, so `.trim().toUpperCase()` is safe at compile time.
- If `lastSeen` needs updating, do it in a separate, explicitly named function.

---

## Optional stricter version with runtime validation

If data comes from an external API, compile-time types are not enough. Add a validation boundary:

```ts
function isUser(value: unknown): value is User {
  return (
    typeof value === "object" &&
    value !== null &&
    ("id" in value) &&
    ("name" in value && typeof (value as { name: unknown }).name === "string") &&
    ("active" in value && typeof (value as { active: unknown }).active === "boolean")
  );
}

export function processUnknownUsers(input: unknown): ProcessedUser[] {
  if (!Array.isArray(input)) {
    throw new TypeError("Expected an array of users");
  }

  const validUsers = input.filter(isUser);
  return processUsers(validUsers);
}
```

