## Final solution

```ts
export interface User {
  id: string | number;
  name: string;
  active: boolean;
}

export interface ProcessedUser {
  id: string | number;
  name: string;
}

export function processUsers(users: readonly User[]): ProcessedUser[] {
  const result: ProcessedUser[] = [];

  for (const user of users) {
    if (!user.active) continue;

    result.push({
      id: user.id,
      name: user.name.trim().toUpperCase(),
    });
  }

  return result;
}
```

This version is type-safe, avoids input mutation, has no off-by-one error, and clearly communicates its input/output contract.

## Code Review Practice (TypeScript context)

In a TypeScript codebase, an effective code-review practice usually means:

1. **Automate the boring part first** – formatting, linting (`eslint`), type-checking (`tsc --noEmit`), tests. Humans review intent, not semicolons.
2. **Review small, focused changes** – a PR should be reviewable in ~10–20 minutes. Large diffs hide bugs.
3. **Use a checklist** – correctness, types, edge cases, performance, security, readability, tests, docs.
4. **Comment on *why*, not just *what*** – prefer questions (“What happens if this is null?”) over commands.
5. **Track decisions** – resolve threads, avoid ghost approvals, use “Request changes” when blocking.
6. **CI gates** – a PR cannot merge unless checks pass and at least one reviewer approves.
7. **Post-merge learning** – blameless retros; turn recurring issues into lint rules.

The *core* of a review system is: **parse what changed → run rules → emit structured issues → sort/present**. Below is a small, dependency-free implementation of that core in TypeScript.

---

## Core Implementation

```ts
// code-review-core.ts
// A minimal, framework-agnostic code-review engine.

/* ----------------------------- Domain types ----------------------------- */

export type Severity = "error" | "warning" | "info";

const SEVERITY_RANK: Record<Severity, number> = {
  error: 0,
  warning: 1,
  info: 2,
};

export interface ReviewIssue {
  /** Repository-relative path, e.g. "src/user.ts". */
  filePath: string;
  /** 1-based line number in the *new* file. */
  line: number;
  severity: Severity;
  /** Stable id, e.g. "no-explicit-any". */
  ruleId: string;
  message: string;
  /** Optional actionable fix. */
  suggestion?: string;
}

/** One added/modified line we are reviewing. */
export interface ChangedLine {
  filePath: string;
  line: number;
  text: string;
}

/** Full file contents used by rules that need context. */
export type FileContents = Map<string, string[]>;

export interface RuleContext {
  changedLine: ChangedLine;
  fileLines: string[] | undefined; // all lines of that file (if available)
}

export type Rule = (ctx: RuleContext) => ReviewIssue | null;

/* ----------------------------- Rule engine ----------------------------- */

export class Reviewer {
  private rules: Rule[] = [];

  /** Register a rule. Rules are run in registration order. */
  register(rule: Rule): this {
    this.rules.push(rule);
    return this;
  }

  /** Run all rules over the changed lines and return sorted issues. */
  review(changes: ChangedLine[], files?: FileContents): ReviewIssue[] {
    const issues: ReviewIssue[] = [];

    for (const changedLine of changes) {
      const ctx: RuleContext = {
        changedLine,
        fileLines: files?.get(changedLine.filePath),
      };

      for (const rule of this.rules) {
        const issue = rule(ctx);
        if (issue) issues.push(issue);
      }
    }

    return this.sort(issues);
  }

  private sort(issues: ReviewIssue[]): ReviewIssue[] {
    return [...issues].sort((a, b) => {
      if (SEVERITY_RANK[a.severity] !== SEVERITY_RANK[b.severity]) {
        return SEVERITY_RANK[a.severity] - SEVERITY_RANK[b.severity];
      }
      if (a.filePath !== b.filePath) return a.filePath.localeCompare(b.filePath);
      return a.line - b.line;
    });
  }
}

/* ----------------------------- Built-in rules ----------------------------- */

/** Discourage `any` in new code. */
export const noExplicitAny: Rule = ({ changedLine }) => {
  // Matches `: any`, `<any>`, `any[]`, `as any`, etc. (simple heuristic)
  if (/\bany\b/.test(changedLine.text) && !/\/\/.*\bany\b/.test(changedLine.text)) {
    return {
      filePath: changedLine.filePath,
      line: changedLine.line,
      severity: "error",
      ruleId: "no-explicit-any",
      message: "Avoid `any`; prefer a concrete type or `unknown` with narrowing.",
      suggestion: "Replace `any` with the precise type or `unknown`.",
    };
  }
  return null;
};

/** console.log should not ship to production code. */
export const noConsoleLog: Rule = ({ changedLine }) => {
  if (/\bconsole\.log\s*\(/.test(changedLine.text)) {
    return {
      filePath: changedLine.filePath,
      line: changedLine.line,
      severity: "warning",
      ruleId: "no-console-log",
      message: "Remove debug `console.log` before merging.",
      suggestion: "Use a structured logger or remove the statement.",
    };
  }
  return null;
};

/** TODO must reference a ticket. */
export const todoNeedsTicket: Rule = ({ changedLine }) => {
  if (/\/\/\s*TODO(?!\s*\([A-Z]+-\d+\))/.test(changedLine.text)) {
    return {
      filePath: changedLine.filePath,
      line: changedLine.line,
      severity: "warning",
      ruleId: "todo-needs-ticket",
      message: "TODO comments must reference a ticket, e.g. `// TODO(JIRA-123)`.",
    };
  }
  return null;
};

/** Flag very long lines (readability). */
export const maxLineLength = (limit = 120): Rule => ({ changedLine }) => {
  if (changedLine.text.length > limit) {
    return {
      filePath: changedLine.filePath,
      line: changedLine.line,
      severity: "info",
      ruleId: "max-line-length",
      message: `Line exceeds ${limit} characters (${changedLine.text.length}).`,
      suggestion: "Break the line or extract a variable.",
    };
  }
  return null;
};

/** Detect a function with no tests nearby (heuristic: looks for `export function`). */
export const exportedFunctionNeedsTest: Rule = ({ changedLine, fileLines }) => {
  if (!/export\s+(async\s+)?function\s+\w+/.test(changedLine.text)) return null;

  const match = changedLine.text.match(/export\s+(?:async\s+)?function\s+(\w+)/);
  const name = match?.[1];
  if (!name) return null;

  // Heuristic: check whether a test file references this function name.
  // In a real system you'd inspect the paired *.test.ts file.
  const hasTestReference = (fileLines ?? []).some((l) => l.includes(`${name}(`) && /test|spec/i.test(l));
  if (hasTestReference) return null;

  return {
    filePath: changedLine.filePath,
    line: changedLine.line,
    severity: "info",
    ruleId: "exported-fn-needs-test",
    message: `Exported function \`${name}\` has no obvious test reference.`,
    suggestion: "Add a unit test covering the new behavior.",
  };
};

/* ----------------------------- Diff helpers ----------------------------- */

/**
 * Parse a *very* small unified diff and return the list of added lines.
 * Real systems use a proper diff library; this keeps the core self-contained.
 */
export function parseAddedLines(unifiedDiff: string): ChangedLine[] {
  const result: ChangedLine[] = [];
  let currentFile: string | null = null;
  let newLineNo = 0;

  for (const raw of unifiedDiff.split("\n")) {
    // New file header: "--- a/x" / "+++ b/x"
    if (raw.startsWith("+++ ")) {
      // "+++ b/path" or "+++ /dev/null"
      const m = raw.match(/^\+\+\+ (?:b\/)?(.+)$/);
      currentFile = m && m[1] !== "/dev/null" ? m[1] : null;
      continue;
    }
    // Hunk header: @@ -a,b +c,d @@
    const hunk = raw.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
    if (hunk) {
      newLineNo = parseInt(hunk[1], 10) - 1; // will be incremented on context/added
      continue;
    }
    if (!currentFile) continue;

    if (raw.startsWith("+") && !raw.startsWith("+++")) {
      newLineNo++;
      result.push({ filePath: currentFile, line: newLineNo, text: raw.slice(1) });
    } else if (raw.startsWith(" ")) {
      // context line advances new-file line number
      newLineNo++;
    }
    // removed lines (-) do not advance new-file counter
  }

  return result;
}

/* ----------------------------- Example usage ----------------------------- */

if (require.main === module) {
  const diff = `
--- a/src/user.ts
+++ b/src/user.ts
@@ -1,3 +1,6 @@
 export interface User { id: string; name: string; }
+export function greet(user: any) {
+  console.log("hi", user);
+  // TODO fix this
+  return \`Hello \${user.name}\`; // this line is intentionally very long to trigger the max length rule in our example
+}
`;

  const reviewer = new Reviewer()
    .register(noExplicitAny)
    .register(noConsoleLog)
    .register(todoNeedsTicket)
    .register(maxLineLength(100))
    .register(exportedFunctionNeedsTest);

  const changes = parseAddedLines(diff);
  const issues = reviewer.review(changes);

  for (const issue of issues) {
    console.log(
      `[${issue.severity.toUpperCase()}] ${issue.filePath}:${issue.line} ` +
        `(${issue.ruleId}) ${issue.message}` +
        (issue.suggestion ? ` -> ${issue.suggestion}` : "")
    );
  }
}
```

### How you’d use this in practice

- In CI: parse the PR diff (`git diff origin/main...HEAD`), feed it to `parseAddedLines`, run `reviewer.review(...)`, and post each `ReviewIssue` as a PR comment via the GitHub/GitLab API.
- Locally: wire it into a pre-push hook or a `npm run review` script.
- Extensibility: add rules as pure functions—no framework coupling—so teams can encode their own style (e.g., “no `moment`, use `date-fns`”).

### Why this design

- **Pure functions for rules** → trivial to unit-test.
- **Sorted, structured output** → easy to render in CLI, IDE, or PR UI.
- **Severity levels** → lets CI fail on `error` but only warn on `info`.
- **Context injection (`fileLines`)** → rules can grow from line-level to file-level without changing the engine.

Below are common TypeScript edge cases that code reviewers should actively look for, with “risky” vs “safer” examples. The goal is not just type-checking, but catching places where the compiler is technically happy while runtime behavior is still wrong.

---

## 1. `any` sneaking in through untyped boundaries

**Risk:** `any` disables checking silently, especially from `JSON.parse`, third-party libs, or `catch` variables in older TS.

```ts
// risky
function parseUser(input: string) {
  const data = JSON.parse(input); // any
  return data.name.toUpperCase(); // no compile-time protection
}

// safer
type RawUser = { name?: unknown };

function parseUser(input: string): { name: string } {
  const data: unknown = JSON.parse(input);

  if (
    typeof data !== "object" ||
    data === null ||
    !("name" in data) ||
    typeof (data as RawUser).name !== "string"
  ) {
    throw new Error("Invalid user payload");
  }

  return { name: (data as RawUser).name as string };
}
```

**Review check:** Prefer `unknown`, then narrow. Treat every `JSON.parse`, `fetch().json()`, and `localStorage.getItem()` as untrusted.

---

## 2. Non-null assertions hiding missing data

**Risk:** `!` tells TS “trust me,” but reviewers should require proof.

```ts
// risky
function getUserName(users: Map<string, { name: string }>, id: string) {
  return users.get(id)!.name; // runtime crash if missing
}

// safer
function getUserName(users: Map<string, { name: string }>, id: string) {
  const user = users.get(id);
  if (!user) throw new Error(`User not found: ${id}`);
  return user.name;
}
```

**Review check:** Every `!` should have a nearby comment or guard proving non-nullness.

---

## 3. Array indexing with `noUncheckedIndexedAccess`

**Risk:** Reviewers may assume `arr[0]` is `T`, but under strict indexing it is `T | undefined`.

```ts
// risky under noUncheckedIndexedAccess
function firstLabel(labels: string[]) {
  return labels[0].trim(); // Object is possibly 'undefined'
}

// safer
function firstLabel(labels: string[]) {
  const first = labels[0];
  if (first === undefined) return "";
  return first.trim();
}
```

**Review check:** Enable `noUncheckedIndexedAccess` and verify every indexed access is guarded.

---

## 4. Optional chaining vs. nullish coalescing confusion

**Risk:** `||` treats `0`, `""`, and `false` as missing; `??` only treats `null`/`undefined` as missing.

```ts
// risky
const timeout = config.timeout || 3000; // if timeout is 0, becomes 3000

// safer
const timeout = config.timeout ?? 3000;
```

**Review check:** Search for `||` used for default values on numbers/booleans/strings.

---

## 5. Discriminated unions and exhaustiveness

**Risk:** Adding a new union member later can silently skip handling.

```ts
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number };

// risky
function area(shape: Shape) {
  if (shape.kind === "circle") return Math.PI * shape.radius ** 2;
  return shape.side ** 2; // assumes square, breaks if triangle added
}

// safer
function area(shape: Shape) {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "square":
      return shape.side ** 2;
    default: {
      const exhaustive: never = shape;
      throw new Error(`Unhandled shape: ${JSON.stringify(exhaustive)}`);
    }
  }
}
```

**Review check:** Every `switch` on a discriminated union should have a `never` default.

---

## 6. `as` assertions vs. `satisfies`

**Risk:** `as` can lie to the compiler; `satisfies` validates shape while preserving literal inference.

```ts
// risky
const routes = {
  home: "/",
  about: "/about",
} as Record<string, string>; // widens; typos not caught later

// safer
const routes = {
  home: "/",
  about: "/about",
} satisfies Record<string, string>;

// routes.home is still "/"
```

**Review check:** Prefer `satisfies` for config objects; reserve `as` for interoperability boundaries.

---

## 7. Unsafe mutation of readonly data

**Risk:** `readonly` is shallow and can be bypassed by casts or nested mutation.

```ts
// risky
function normalize(items: readonly string[]) {
  (items as string[]).push("x"); // compiles with cast, mutates caller data
}

// safer
function normalize(items: readonly string[]): string[] {
  return [...items, "x"];
}
```

**Review check:** Flag casts from `readonly` to mutable types, especially in shared state.

---

## 8. `this` loss in callbacks

**Risk:** Passing methods as callbacks detaches `this`.

```ts
class Counter {
  value = 0;
  increment() {
    this.value++;
  }
}

const c = new Counter();

// risky
setTimeout(c.increment, 100); // this is undefined in strict mode

// safer
setTimeout(() => c.increment(), 100);
// or define increment as arrow function property
```

**Review check:** Review all method references passed to timers, event handlers, and array methods.

---

## 9. Promises and `void` async functions

**Risk:** Fire-and-forget async calls can swallow errors.

```ts
// risky
async function save(): Promise<void> {
  await db.save();
}

function onClick() {
  save(); // returned promise ignored; unhandled rejection possible
}

// safer
function onClick() {
  void save().catch((err) => {
    logger.error(err);
    showToast("Save failed");
  });
}
```

**Review check:** Every floating promise should be explicitly handled or assigned to `void`.

---

## 10. Enums: reverse mappings and const enums

**Risk:** Numeric enums allow reverse lookup and can cause surprising object shapes. `const enum` can break across package boundaries.

```ts
// risky
enum Status {
  Active,
  Inactive,
}
const name = Status[0]; // "Active", often unintended

// safer for public APIs
const Status = {
  Active: "active",
  Inactive: "inactive",
} as const;

type Status = (typeof Status)[keyof typeof Status];
```

**Review check:** Prefer string-literal unions or `as const` objects for exported status values.

---

## 11. Type-only imports and circular dependencies

**Risk:** Mixing value and type imports can cause runtime circular dependency issues.

```ts
// risky in large graphs
import { User, createUser } from "./user";

// safer
import type { User } from "./user";
import { createUser } from "./user";
```

**Review check:** Use `import type` for types; enable `isolatedModules` and `verbatimModuleSyntax`.

---

## 12. Generics with implicit `any` and poor constraints

**Risk:** Unconstrained generics can accept nonsensical types or lose inference.

```ts
// risky
function first<T>(items: T[]): T | undefined {
  return items[0];
}

first(42 as any); // T inferred as any

// safer
function first<T extends readonly unknown[]>(items: T): T[number] | undefined {
  return items[0];
}
```

Or for arrays:

```ts
function first<T>(items: readonly T[]): T | undefined {
  return items[0];
}
```

**Review check:** Add constraints (`extends object`, `extends string`) when the generic must support specific operations.

---

## 13. `Date` and timezone pitfalls

**Risk:** TS types `Date`, but parsing is implementation-dependent and often UTC/local confusion.

```ts
// risky
const d = new Date("2024-01-01"); // may be UTC or local depending on format

// safer
const d = new Date(Date.UTC(2024, 0, 1));
```

**Review check:** Require explicit UTC construction or a date library with timezone support.

---

## 14. Optional properties vs. `undefined`-valued properties

**Risk:** `{ x?: number }` is not identical to `{ x: number | undefined }` in many contexts (exact optional property types).

```ts
type A = { x?: number };
type B = { x: number | undefined };

const a: A = {};        // ok
const b: B = {};        // error under exactOptionalPropertyTypes
```

**Review check:** Enable `exactOptionalPropertyTypes` for APIs where “absent” differs from “explicitly undefined.”

---

## 15. Exhaustive object key handling

**Risk:** Index signatures widen access and hide missing keys.

```ts
// risky
const labels: Record<string, string> = {
  a: "A",
};
console.log(labels.b.toUpperCase()); // compiles, runtime crash

// safer
const labels = {
  a: "A",
} as const;

type LabelKey = keyof typeof labels;

function label(key: LabelKey) {
  return labels[key];
}
```

**Review check:** Avoid broad index signatures for finite key sets; use `as const` + `keyof`.

---

## 16. `JSON.stringify` and `undefined` fields

**Risk:** Optional fields disappear during serialization, breaking contracts.

```ts
type Payload = { id: string; note?: string };

// risky
const payload: Payload = { id: "1", note: undefined };
JSON.stringify(payload); // {"id":"1"} — note omitted

// safer: normalize before sending
const wirePayload = {
  id: payload.id,
  note: payload.note ?? null,
};
```

**Review check:** Define wire types explicitly; do not rely on TS optional semantics for serialization.

---

## 17. Overload ordering and broad overloads

**Risk:** Overloads are matched top-to-bottom; a broad overload first can shadow specific ones.

```ts
// risky
function parse(input: string | number): string {
  if (typeof input === "number") return input.toFixed();
  return input.trim();
}

// The above is fine, but overloads can be misordered:
function format(x: any): string;          // too broad, first
function format(x: number): string;       // unreachable
function format(x: any): string {
  return String(x);
}
```

**Review check:** Order overloads from most specific to least specific; avoid `any` in overload signatures.

---

## 18. Template literal types and runtime validation

**Risk:** Template literal types are compile-time only and do not validate runtime strings.

```ts
type Route = `/users/${string}`;

const route: Route = "/users/123"; // OK at compile time

// risky: value from user input
function navigate(path: string) {
  const route = path as Route; // lie
}
```

**Review check:** Pair template literal types with runtime guards or zod/schema validation.

---

## 19. Branded types for domain safety

**Risk:** Primitive types allow mixing semantically different values.

```ts
// risky
function transfer(amount: number, accountId: string) {}

transfer(100, "user-123"); // arguments could be swapped accidentally

// safer
type USD = number & { readonly __brand: "USD" };
type AccountId = string & { readonly __brand: "AccountId" };

function usd(value: number): USD {
  return value as USD;
}

function transfer(amount: USD, accountId: AccountId) {}
```

**Review check:** Consider branded types for IDs, money, and units in domain-heavy code.

---

## 20. `Object.keys` typing

**Risk:** `Object.keys` returns `string[]`, not `keyof T[]`, because objects can have extra runtime properties.

```ts
type User = { name: string; age: number };

const user: User = { name: "Ada", age: 30 };

// risky
for (const key of Object.keys(user)) {
  console.log(user[key]); // Element implicitly has type 'any' under strict settings? Actually error
}

// safer
const keys = Object.keys(user) as Array<keyof User>;
for (const key of keys) {
  console.log(user[key]);
}
```

Better still, use a guarded helper or `Object.entries`.

**Review check:** Do not assume `Object.keys(obj)` is `Array<keyof typeof obj>` without a cast or helper.

---

## Suggested reviewer checklist

- [ ] No unexplained `any`, `!`, or `as`.
- [ ] All indexed array/object accesses are guarded.
- [ ] Discriminated unions are exhaustively handled.
- [ ] Floating promises are handled.
- [ ] Default values use `??`, not `||`, where appropriate.
- [ ] Readonly data is not mutated through casts.
- [ ] External input is validated before being trusted.
- [ ] Enums are avoided in public APIs unless intentional.
- [ ] Type-only imports use `import type`.
- [ ] Serialization behavior is explicitly handled.

