/**
 * Application-wide role constants.
 * Use these instead of raw strings to avoid typos.
 */
export const ROLES = {
  ADMIN: "admin",
  EDITOR: "editor",
  VIEWER: "viewer",
} as const;

/** Union of all allowed roles, derived from the const object. */
export type Role = (typeof ROLES)[keyof typeof ROLES];
```

### `src/types/user.ts`
```ts
import type { Role } from "../constants/roles.js";

/**
 * A user as stored in our data layer.
 * Fields are readonly to prevent accidental mutation.
 */
export interface IUser {
  readonly id: string;
  readonly email: string;
  readonly name: string;
  readonly role: Role;
  readonly createdAt: Date;
}

/**
 * Payload used when creating a new user.
 * `id` and `createdAt` are generated server-side.
 */
export type CreateUserInput = Omit<IUser, "id" | "createdAt">;

/**
 * Patch payload for partial updates.
 * All fields optional; `id` cannot be changed.
 */
export type UpdateUserInput = Partial<Omit<IUser, "id" | "createdAt">>;
```

### `src/utils/validators.ts`
```ts
import { z } from "zod";

/**
 * Validates an email string.
 * @returns `true` when valid, otherwise `false`.
 */
export function isValidEmail(value: string): boolean {
  // Simple, readable check; replace with a stricter lib if needed.
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

/** Zod schema for creating a user (single source of truth). */
export const CreateUserSchema = z.object({
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: z.enum(["admin", "editor", "viewer"]),
});

export type CreateUserValidated = z.infer<typeof CreateUserSchema>;
```

### `src/services/UserService.ts`
```ts
import { randomUUID } from "node:crypto";

import type { IUser, CreateUserInput, UpdateUserInput } from "../types/user.js";
import { ROLES } from "../constants/roles.js";
import { CreateUserSchema } from "../utils/validators.js";

/**
 * In-memory user store.
 * Encapsulated so callers never touch the array directly.
 */
export class UserService {
  private readonly users: IUser[] = [];

  /**
   * Create a user after validating input.
   * @throws {Error} when validation fails.
   */
  public createUser(input: CreateUserInput): IUser {
    const parsed = CreateUserSchema.safeParse(input);
    if (!parsed.success) {
      const messages = parsed.error.issues.map((i) => i.message).join(", ");
      throw new Error(`Invalid user input: ${messages}`);
    }

    const user: IUser = {
      id: randomUUID(),
      email: parsed.data.email,
      name: parsed.data.name,
      role: parsed.data.role,
      createdAt: new Date(),
    };

    this.users.push(user);
    return user;
  }

  /** Find a user by id (returns undefined when not found). */
  public findById(id: string): IUser | undefined {
    return this.users.find((u) => u.id === id);
  }

  /** List users, optionally filtered by role. */
  public list(role?: RoleFilter): readonly IUser[] {
    if (!role) return [...this.users];
    return this.users.filter((u) => u.role === role);
  }

  /** Update mutable fields of an existing user. */
  public update(id: string, patch: UpdateUserInput): IUser {
    const index = this.users.findIndex((u) => u.id === id);
    if (index === -1) {
      throw new Error(`User not found: ${id}`);
    }

    const current = this.users[index]!;
    const next: IUser = {
      ...current,
      ...patch,
      // id & createdAt are intentionally preserved (patch cannot override them)
      id: current.id,
      createdAt: current.createdAt,
    };

    this.users[index] = next;
    return next;
  }

  /** Remove a user; returns true if removed. */
  public remove(id: string): boolean {
    const index = this.users.findIndex((u) => u.id === id);
    if (index === -1) return false;
    this.users.splice(index, 1);
    return true;
  }
}

/** Optional role filter used by `list`. */
type RoleFilter = (typeof ROLES)[keyof typeof ROLES];
```

### `src/index.ts`
```ts
import { UserService } from "./services/UserService.js";
import { ROLES } from "./constants/roles.js";

function main(): void {
  const service = new UserService();

  const alice = service.createUser({
    email: "alice@example.com",
    name: "Alice",
    role: ROLES.ADMIN,
  });

  const bob = service.createUser({
    email: "bob@example.com",
    name: "Bob",
    role: ROLES.VIEWER,
  });

  console.log("Created:", alice.id, alice.name);

  service.update(bob.id, { name: "Robert" });
  console.log("Updated Bob:", service.findById(bob.id)?.name);

  console.log("Admins:", service.list(ROLES.ADMIN).map((u) => u.name));
  console.log("Total users:", service.list().length);

  service.remove(alice.id);
  console.log("After remove, total:", service.list().length);
}

main();
```

