## 3. Typical Use Cases

### A. Domain modeling for an API
```ts
// types/user.ts
export interface User {
  id: string;
  email: string;
  createdAt: string; // ISO date
}

export type CreateUserInput = Pick<User, "email">;

export type ApiError = {
  code: "NOT_FOUND" | "VALIDATION" | "UNKNOWN";
  message: string;
};
```

### B. Result type instead of throwing
```ts
type ParseResult<T> =
  | { success: true; data: T }
  | { success: false; issues: string[] };

function parseAge(input: unknown): ParseResult<number> {
  if (typeof input !== "number" || input < 0) {
    return { success: false, issues: ["age must be a non-negative number"] };
  }
  return { success: true, data: input };
}
```

### C. Safe configuration with validation
```ts
const ConfigSchema = z.object({
  port: z.coerce.number().default(3000),
  nodeEnv: z.enum(["development", "production", "test"]),
});
type Config = z.infer<typeof ConfigSchema>;

function loadConfig(raw: unknown): Config {
  return ConfigSchema.parse(raw);
}
```

### D. React props (if applicable)
```ts
type ButtonProps = {
  label: string;
  onClick: () => void;
  variant?: "primary" | "secondary";
  disabled?: boolean;
};

export function Button({ label, onClick, variant = "primary", disabled = false }: ButtonProps) {
  return (
    <button className={variant} disabled={disabled} onClick={onClick}>
      {label}
    </button>
  );
}
```

### E. Utility types for transformations
```ts
type User = { id: string; name: string; passwordHash: string };

type PublicUser = Omit<User, "passwordHash">;
type UserPatch = Partial<Pick<User, "name">>;
```

