## Summary

- **Idea**: Node passes `process.argv`; TS types it as `string[]`.
- **Syntax**: slice off first two entries; parse flags/positionals manually or via a library.
- **Use cases**: dev tools, automation, migrations, config overrides.
- **Recommendation**: use `commander` or `yargs` for anything beyond a handful of flags; compile + `bin` for distributable CLIs.

A common mistake is forgetting that `process.argv` starts with the Node executable path and the script path, so the first user argument is at index `2`, not `0` or `1`.

## Mistaken version

```ts
// server.ts
const port = Number(process.argv[1]); // Wrong: this is usually the script path
const host = process.argv[2];

console.log(`Starting server on ${host}:${port}`);
```

If run as:

```bash
npx ts-node server.ts 3000 localhost
```

then `process.argv` looks roughly like:

```ts
[
  "/usr/bin/node",
  "/path/to/server.ts",
  "3000",
  "localhost"
]
```

So:

- `process.argv[1]` is `"/path/to/server.ts"`, and `Number(...)` becomes `NaN`.
- `process.argv[2]` is `"3000"`, so `host` is incorrectly set to `"3000"`.
- The real host, `"localhost"`, is ignored.

## Corrected version

```ts
// server.ts
const args = process.argv.slice(2);

if (args.length < 2) {
  console.error("Usage: ts-node server.ts <host> <port>");
  process.exit(1);
}

const [host, portArg] = args;
const port = Number(portArg);

if (!Number.isInteger(port) || port <= 0 || port > 65535) {
  console.error(`Invalid port: ${portArg}`);
  process.exit(1);
}

console.log(`Starting server on ${host}:${port}`);
```

## Why this is better

- `process.argv.slice(2)` removes the Node path and script path, leaving only user-provided arguments.
- It checks that enough arguments were supplied before using them.
- It validates the port instead of blindly converting a string to a number.
- It avoids accidental `NaN` or `undefined` values being used as configuration.

For larger CLI tools, a parser such as `commander`, `yargs`, or Node's built-in `util.parseArgs` is usually preferable because it handles flags, options, defaults, and help text more reliably.

Common pitfalls when working with CLI arguments in TypeScript usually come from four places: `process.argv` is a raw, untyped string array; shells already transform user input before Node sees it; TypeScript types disappear at runtime; and CLI tools need reliable exit codes, paths, and stream flushing.

Below are the most common pitfalls, with bad and better code for each.

## 1. Forgetting that `process.argv` starts with Node and the script path

`process.argv[0]` is the Node executable and `process.argv[1]` is the script path. Using them as arguments causes off-by-two bugs.

Bad:

```ts
// input: node cli.js hello
const name = process.argv[1]; // "/path/to/cli.js", not "hello"
console.log(`Hello ${name}`);
```

Better:

```ts
const args = process.argv.slice(2);
const name = args[0];

if (!name) {
  console.error("Usage: cli <name>");
  process.exitCode = 1;
} else {
  console.log(`Hello ${name}`);
}
```

## 2. Treating CLI values as non-string types

Every CLI argument is a string. `Number`, `Boolean`, and similar conversions can silently produce `NaN` or misleading values.

Bad:

```ts
const port = Number(process.argv[2]); // NaN if missing or invalid
server.listen(port);
```

Better:

```ts
function parsePort(raw: string | undefined): number {
  if (!raw) {
    throw new Error("Missing required --port value");
  }

  const port = Number(raw);

  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error(`Invalid port: ${raw}`);
  }

  return port;
}

const port = parsePort(process.argv[2]);
```

## 3. Not handling missing required arguments

A missing argument often becomes `undefined`, then gets concatenated or coerced.

Bad:

```ts
const [input, output] = process.argv.slice(2);
writeFileSync(output, readFileSync(input)); // crashes obscurely if missing
```

Better:

```ts
const [input, output] = process.argv.slice(2);

if (!input || !output) {
  console.error("Usage: copy <input> <output>");
  process.exitCode = 1;
  process.exit();
}

// Continue only after validation...
```

Prefer throwing a clear error or using a parser with `.requiredOption()` / `.argument('<file>')`.

## 4. Naively parsing `--flag value` and `--flag=value`

Manual splitting breaks with both styles, quoted values, equals signs, and flags at the end.

Bad:

```ts
const args = process.argv.slice(2);
const portIndex = args.indexOf("--port");
const port = args[portIndex + 1]; // fails for --port=3000
```

Better with a small robust parser or, preferably, a library:

```ts
import { Command } from "commander";

const program = new Command();

program
  .option("-p, --port <number>", "port to listen on", (value) => {
    const port = Number(value);
    if (!Number.isInteger(port)) throw new Error("Port must be an integer");
    return port;
  }, 3000)
  .parse(process.argv);

const options = program.opts<{ port: number }>();
console.log(options.port);
```

Commander handles `--port 3000`, `--port=3000`, defaults, and errors.

## 5. Not supporting combined short flags

Code like `-abc` is conventionally `-a -b -c`. Naive parsers often treat it as one unknown option.

Bad:

```ts
if (args.includes("-v")) verbose = true;
if (args.includes("-f")) force = true;
```

Better: use a real parser (`commander`, `yargs`, `minimist`) or explicitly expand:

```ts
function expandShortFlags(arg: string): string[] {
  if (!arg.startsWith("-") || arg.startsWith("--")) return [arg];
  return [...arg.slice(1)].map((char) => `-${char}`);
}

// -vf -> ["-v", "-f"]
```

Again, a library is safer.

## 6. Ignoring the `--` separator

Everything after `--` must be treated as positional, even if it starts with `-`.

Bad:

```ts
for (const arg of args) {
  if (arg.startsWith("--")) {
    // incorrectly treats "--" itself or later flags as options
  }
}
```

Better:

```ts
function splitArgs(argv: string[]): { options: string[]; positional: string[] } {
  const separator = argv.indexOf("--");
  if (separator === -1) {
    return { options: argv, positional: [] };
  }

  return {
    options: argv.slice(0, separator),
    positional: argv.slice(separator + 1),
  };
}
```

Libraries handle this automatically.

## 7. Ambiguous optional option values

`--color auto` can be ambiguous if `auto` looks like another argument. Optional values are a common source of greedy parsing bugs.

Bad conceptual pattern:

```ts
// Is "red" the value for --color or a positional input?
// cli --color red input.txt
```

Better: require the equals form or make the option required-valued:

```ts
import { Command } from "commander";

const program = new Command();

program
  .option("--color <mode>", "color mode: auto or always")
  .argument("<input>", "input file")
  .parse(process.argv);
```

For optional values, document and test both `--color=auto` and `--color auto`.

## 8. Not rejecting unknown options

Typos such as `--prot 3000` may be silently ignored, so the program runs with a default and fails later.

Bad:

```ts
const port = Number(getOption("--port")) || 3000;
// --prot 3000 is ignored
```

Better with Commander strict parsing:

```ts
import { Command } from "commander";

const program = new Command()
  .option("-p, --port <number>", "port")
  .strictOptions() // reject unknown options
  .parse(process.argv);
```

Or validate manually:

```ts
const known = new Set(["--port", "--host", "--verbose"]);
for (const arg of args) {
  if (arg.startsWith("--") && !known.has(arg.split("=")[0])) {
    throw new Error(`Unknown option: ${arg}`);
  }
}
```

## 9. Not awaiting an async `main`

If `main()` is async and not awaited, unhandled promise rejections can terminate the process inconsistently or print stack traces after exit.

Bad:

```ts
async function main() {
  await doWork(process.argv.slice(2));
}

main(); // floating promise
```

Better:

```ts
async function main(argv: string[]): Promise<void> {
  await doWork(argv);
}

main(process.argv.slice(2)).catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
});
```

## 10. Calling `process.exit()` too early

`process.exit()` can truncate buffered stdout/stderr, especially with pipes and large output.

Bad:

```ts
console.log(result);
process.exit(0); // may cut off output
```

Better:

```ts
console.log(result);
process.exitCode = 0; // allows streams to flush naturally
```

Use `process.exit()` only when you truly need immediate termination.

## 11. Assuming relative paths are relative to the script

A CLI argument like `./data.json` is relative to `process.cwd()`, not the location of the compiled JavaScript file.

Bad:

```ts
import { readFileSync } from "node:fs";

const data = readFileSync(process.argv[2]); // depends on where command is run
```

Better:

```ts
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

const inputPath = process.argv[2];
if (!inputPath) throw new Error("Missing input file");

const absolutePath = resolve(process.cwd(), inputPath);
const data = readFileSync(absolutePath, "utf8");
```

If the path should be relative to the package instead, resolve from `import.meta.url` or `__dirname`.

## 12. Passing secrets through argv

Command-line arguments are visible to other users via `ps`, shell history, and process listings.

Bad:

```ts
// cli.js --token super-secret-token
```

Better:

```ts
const token = process.env.API_TOKEN;

if (!token) {
  console.error("Set API_TOKEN in the environment");
  process.exitCode = 1;
  process.exit();
}
```

For sensitive multi-line input, read from stdin instead.

## 13. Hard-coding `process.argv` makes testing difficult

Direct access to global state makes unit tests awkward and non-deterministic.

Bad:

```ts
export function run() {
  const args = process.argv.slice(2);
  return args.includes("--verbose");
}
```

Better:

```ts
export function run(argv: string[]): boolean {
  return argv.includes("--verbose");
}

if (require.main === module) {
  const result = run(process.argv.slice(2));
  console.log(result);
}
```

Now tests can call `run(["--verbose"])` without mutating global state.

## 14. Ignoring shell quoting and word splitting

The shell splits arguments before Node receives them. Spaces, globs, and quotes are handled by the shell, not by your program.

Bad user invocation and bad assumption:

```sh
node cli.js file name.txt   # program sees two args: "file", "name.txt"
```

Better: document quoting and handle arrays:

```ts
const files = process.argv.slice(2);
for (const file of files) {
  console.log(`Processing: ${file}`);
}
```

Users should invoke:

```sh
node cli.js "file name.txt"
```

Also remember that unquoted globs such as `*.json` may be expanded by the shell.

## 15. Breaking when run through `ts-node`, `tsx`, or compiled output

Shebangs, file extensions, and module mode differ between development and production.

Bad shebang for a TypeScript source file:

```ts
#!/usr/bin/env node
import { readFile } from "node:fs/promises";
// Run with: ts-node cli.ts
```

Better production setup:

```ts
#!/usr/bin/env node
import { readFile } from "node:fs/promises";

async function main(argv: string[]) {
  console.log(await readFile(argv[0] ?? "", "utf8"));
}

main(process.argv.slice(2)).catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
```

Compile first, then execute the emitted JavaScript:

```sh
tsc
chmod +x dist/cli.js
./dist/cli.js input.txt
```

During development:

```sh
npx tsx src/cli.ts input.txt
```

## 16. Using TypeScript path aliases without runtime resolution

If `tsconfig.json` has `paths`, the compiled JavaScript may still contain `@/utils` imports that Node cannot resolve.

Bad:

```ts
import { parsePort } from "@/utils/args"; // works in tsc type-check, fails at runtime
```

Better options:

- Use relative imports in CLI entry points.
- Or configure a runtime resolver such as `tsconfig-paths`.
- Or bundle the CLI with `tsup`, `esbuild`, or `rollup`.

Example with relative import:

```ts
import { parsePort } from "./utils/args.js";

const port = parsePort(process.argv[2]);
console.log(port);
```

Note the `.js` extension for ESM-compatible TypeScript output.

## 17. Confusing positional arguments with option values

Positional order can shift when optional flags are omitted.

Bad:

```ts
// Expected: input output
// Actual with flags: node cli.js --verbose input output
const input = process.argv[2];
const output = process.argv[3];
```

Better: parse flags separately or use a parser:

```ts
import { Command } from "commander";

const program = new Command();

program
  .option("-v, --verbose")
  .argument("<input>")
  .argument("<output>")
  .action((input, output, options) => {
    console.log({ input, output, verbose: options.verbose });
  });

program.parse(process.argv);
```

## Recommended minimal robust pattern

For most TypeScript CLIs, combine a parser with an async main, clear validation, and exit-code handling:

```ts
#!/usr/bin/env node
import { Command } from "commander";

async function main(file: string, options: { port: number; verbose: boolean }) {
  console.log(`Reading ${file} on port ${options.port}`);
  if (options.verbose) console.log("Verbose mode enabled");
}

const program = new Command();

program
  .name("my-cli")
  .argument("<file>", "file to process")
  .option("-p, --port <number>", "port number", (value) => {
    const port = Number(value);
    if (!Number.isInteger(port)) throw new Error("Port must be an integer");
    return port;
  }, 3000)
  .option("-v, --verbose", "enable verbose logging", false)
  .action(async (file, options) => {
    await main(file, options);
  });

program.parseAsync(process.argv).catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
});
```

This avoids most of the pitfalls: correct argv slicing, typed parsing, validation, async handling, and safe exit codes.

## Exercise

Build a small TypeScript CLI named `greet` that:

- Takes one **positional** argument: `name` (required).
- Accepts these options:
  - `--times <n>` (default `1`) — how many lines to print
  - `--greeting <text>` (default `"Hello"`)
  - `--upper` — print in uppercase
- Supports `--help` / `-h`.
- Rejects unknown options and invalid values with a non-zero exit code.
- Prints the greeting the requested number of times.

Example:

```bash
npx ts-node src/index.ts Alice --times 2 --upper
# HELLO, ALICE!
# HELLO, ALICE!
```

---

## Step-by-step solution

### 1. Project setup

```bash
mkdir greet-cli && cd greet-cli
npm init -y
npm i -D typescript ts-node @types/node
npx tsc --init
```

Adjust `tsconfig.json` to be strict and target modern Node:

```json
{
  "compilerOptions": {
    "target": "ES2022",
    "module": "CommonJS",
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "outDir": "dist"
  },
  "include": ["src"]
}
```

Add a script to `package.json`:

```json
{
  "scripts": {
    "start": "ts-node src/index.ts",
    "build": "tsc",
    "greet": "node dist/index.js"
  }
}
```

### 2. Design the parser

We’ll parse `process.argv.slice(2)` manually. This keeps the exercise dependency-free and shows how CLI arguments actually work:

- `--key value`
- `--key=value`
- boolean flags like `--upper`
- short flags like `-h`
- positional arguments
- `--` to stop option parsing

### 3. Implement parsing and validation

Create `src/index.ts`:

```ts
#!/usr/bin/env node

type FlagValue = string | boolean;

interface ParsedArgs {
  positional: string[];
  flags: Record<string, FlagValue>;
}

const ALLOWED_FLAGS = new Set([
  'help', 'h',
  'times', 't',
  'greeting', 'g',
  'upper', 'u',
]);

function parseArgs(argv: string[]): ParsedArgs {
  const positional: string[] = [];
  const flags: Record<string, FlagValue> = {};

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];

    // Everything after -- is positional.
    if (arg === '--') {
      positional.push(...argv.slice(i + 1));
      break;
    }

    if (arg.startsWith('--')) {
      const eqIndex = arg.indexOf('=');

      if (eqIndex !== -1) {
        const key = arg.slice(2, eqIndex);
        flags[key] = arg.slice(eqIndex + 1);
      } else {
        const key = arg.slice(2);
        const next = argv[i + 1];

        // If the next token is a value, consume it.
        if (next !== undefined && !next.startsWith('-')) {
          flags[key] = next;
          i++;
        } else {
          flags[key] = true;
        }
      }
      continue;
    }

    if (arg.startsWith('-') && arg.length > 1) {
      // Short flags, possibly clustered: -uh
      for (const ch of arg.slice(1)) {
        flags[ch] = true;
      }
      continue;
    }

    positional.push(arg);
  }

  return { positional, flags };
}

function printHelp(): void {
  console.log(`
Usage: greet <name> [options]

Arguments:
  name                  Name to greet (required)

Options:
  --times, -t <n>       Number of greetings (default: 1)
  --greeting, -g <text> Greeting text (default: "Hello")
  --upper, -u           Uppercase the output
  --help, -h            Show this help
`.trim());
}

function fail(message: string): never {
  console.error(`Error: ${message}`);
  console.error('Run with --help for usage.');
  process.exit(1);
}

function main(): void {
  const { positional, flags } = parseArgs(process.argv.slice(2));

  if (flags.help || flags.h) {
    printHelp();
    return;
  }

  // Reject unknown flags.
  const unknown = Object.keys(flags).filter((k) => !ALLOWED_FLAGS.has(k));
  if (unknown.length > 0) {
    fail(`Unknown option(s): ${unknown.map((k) => `--${k}`).join(', ')}`);
  }

  if (positional.length !== 1) {
    fail(`Expected exactly one name, got ${positional.length}.`);
  }

  const name = positional[0];

  // Resolve option aliases.
  const timesRaw = (flags.times ?? flags.t ?? '1') as string | boolean;
  const greetingRaw = (flags.greeting ?? flags.g ?? 'Hello') as string | boolean;
  const upper = Boolean(flags.upper ?? flags.u);

  const times = Number(timesRaw);
  if (!Number.isInteger(times) || times < 1) {
    fail(`--times must be a positive integer, got "${timesRaw}".`);
  }

  const greeting = String(greetingRaw);

  for (let i = 0; i < times; i++) {
    let line = `${greeting}, ${name}!`;
    if (upper) line = line.toUpperCase();
    console.log(line);
  }
}

main();
```

