## Key takeaways

- `process.argv` contains the Node executable and script path first; slice them off with `.slice(2)`.
- CLI arguments are just strings; you are responsible for converting and validating them.
- Distinguishing `--flag value`, `--flag=value`, and boolean flags is the core of manual parsing.
- Always validate unknown options and types; small CLIs become much more usable with clear errors and `--help`.
- For larger tools, libraries like `commander`, `yargs`, or `cac` handle parsing, help text, and validation for you.

## Command line arguments in TypeScript

In Node.js (and therefore TypeScript running on Node), command line arguments are exposed through the global `process.argv` array:

- `process.argv[0]` — path to the Node executable
- `process.argv[1]` — path to the script being run
- `process.argv[2...]` — the actual arguments passed by the user

Example:

```bash
node dist/cli.js --verbose --output result.txt input1.txt input2.txt
```

```ts
console.log(process.argv);
// [
//   '/usr/bin/node',
//   '/app/dist/cli.js',
//   '--verbose',
//   '--output', 'result.txt',
//   'input1.txt',
//   'input2.txt'
// ]
```

In real projects you usually slice off the first two entries and hand the rest to a parser:

```ts
const argv = process.argv.slice(2);
```

### Why write a parser at all?

Manual indexing (`argv[0]`, `argv[1]`, …) breaks as soon as users reorder flags, combine short flags (`-abc`), use `--key=value`, or pass positional arguments. A small reusable parser keeps the CLI logic clean. (For production, prefer battle-tested libraries like `commander`, `yargs`, or `minimist`; the implementation below demonstrates the core ideas.)

---

## Core implementation

```ts
// cli-parser.ts
// A small, dependency-free argv parser. Intentionally simple but covers the
// common conventions: --long, --long=value, --long value, -s, -s value,
// -s=value, combined short flags (-abc), and `--` to stop option parsing.

export interface ParsedArgs {
  /** Boolean flags, e.g. --verbose, -v */
  flags: Set<string>;
  /** Key/value options. Repeated keys become string[]. */
  options: Map<string, string | string[]>;
  /** Non-option arguments. */
  positionals: string[];
}

/**
 * Parse an argv array (typically process.argv.slice(2)).
 *
 * Conventions:
 *  - `--` ends option parsing; everything after is positional.
 *  - `--key=value` and `-k=value` attach a value directly.
 *  - `--key value` / `-k value` consume the next token as the value,
 *    unless it starts with `-`.
 *  - A lone `--key` / `-k` is treated as a boolean flag.
 *  - Multiple short letters in one token (-abc) are treated as flags.
 */
export function parseArgs(argv: readonly string[]): ParsedArgs {
  const flags = new Set<string>();
  const options = new Map<string, string | string[]>();
  const positionals: string[] = [];

  // Helper to store a value, accumulating repeats into an array.
  const setOption = (key: string, value: string): void => {
    const existing = options.get(key);
    if (existing === undefined) {
      options.set(key, value);
    } else if (Array.isArray(existing)) {
      existing.push(value);
    } else {
      options.set(key, [existing as string, value]);
    }
  };

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    // `--` terminates option parsing.
    if (token === "--") {
      positionals.push(...argv.slice(i + 1));
      break;
    }

    // Long options: --key or --key=value
    if (token.startsWith("--")) {
      const body = token.slice(2);
      const eq = body.indexOf("=");
      if (eq !== -1) {
        const key = body.slice(0, eq);
        const value = body.slice(eq + 1);
        setOption(key, value);
      } else {
        const key = body;
        const next = argv[i + 1];
        // Consume next token as value only if it doesn't look like an option.
        if (next !== undefined && !next.startsWith("-")) {
          setOption(key, next);
          i++;
        } else {
          flags.add(key);
        }
      }
      i++;
      continue;
    }

    // Short options: -k, -k=value, -abc
    if (token.startsWith("-") && token.length > 1) {
      // Handle -k=value form.
      const eq = token.indexOf("=");
      if (eq !== -1) {
        const key = token.slice(1, eq);
        const value = token.slice(eq + 1);
        setOption(key, value);
        i++;
        continue;
      }

      const chars = token.slice(1);

      // Single short option: may take a value.
      if (chars.length === 1) {
        const key = chars;
        const next = argv[i + 1];
        if (next !== undefined && !next.startsWith("-")) {
          setOption(key, next);
          i++;
        } else {
          flags.add(key);
        }
        i++;
        continue;
      }

      // Combined short flags, e.g. -abc -> flags a, b, c.
      // (Without a schema we can't know if one of them takes a value,
      // so combined forms are treated as boolean flags only.)
      for (const ch of chars) {
        flags.add(ch);
      }
      i++;
      continue;
    }

    // Anything else is a positional argument.
    positionals.push(token);
    i++;
  }

  return { flags, options, positionals };
}

// ---------- Convenience accessors ----------

/** Get an option value or undefined. */
export function getOption(parsed: ParsedArgs, key: string): string | string[] | undefined {
  return parsed.options.get(key);
}

/** Whether a flag was set. */
export function hasFlag(parsed: ParsedArgs, key: string): boolean {
  return parsed.flags.has(key);
}
```

### Usage example

```ts
// main.ts
import { parseArgs, hasFlag, getOption } from "./cli-parser";

const parsed = parseArgs(process.argv.slice(2));

if (hasFlag(parsed, "help") || hasFlag(parsed, "h")) {
  console.log("Usage: tool [--verbose] [--output FILE] [inputs...]");
  process.exit(0);
}

const verbose = hasFlag(parsed, "verbose") || hasFlag(parsed, "v");
const output = getOption(parsed, "output") ?? getOption(parsed, "o");
const inputs = parsed.positionals;

console.log({ verbose, output, inputs });
```

### Running it

```bash
# Compile
npx tsc main.ts cli-parser.ts --target es2020 --module commonjs

# Run
node main.js --verbose --output result.txt -v input1.txt input2.txt
# { verbose: true, output: 'result.txt', inputs: [ 'input1.txt', 'input2.txt' ] }
```

### Notes / tradeoffs (interview talking points)

1. **Schema-less vs. schema-driven**: This parser is *schema-less*—it guesses value consumption by looking at the next token. A schema-driven parser (commander/yargs) knows which flags take values, which avoids ambiguity (e.g. `--output --verbose` where `--verbose` might be intended as a value).
2. **Repeated keys** accumulate into arrays, which is convenient for `--include a --include b`.
3. **`--`** is important for passing values that start with `-` (e.g. `-- --weird-filename`).
4. **Combined short flags** (`-abc`) are treated as pure booleans; supporting `-abc value` for the last flag requires a schema.
5. **Validation** (types, required args, choices) is intentionally out of scope for the "core"; add a thin layer on top or use a library.

If you'd like, I can extend this with a typed schema layer (zod/commander-style) or show how `commander` wraps the same concepts.

When writing a TypeScript CLI, `process.argv` is still the underlying JavaScript/Node.js mechanism, so most edge cases come from **shell tokenization, option parsing, type coercion, runtime validation, and process lifecycle**. TypeScript types do not protect you at runtime.

## 1. Start at the right index

`process.argv[0]` is the executable and `process.argv[1]` is the script path. User arguments start at index 2.

```ts
// src/cli.ts
const userArgs = process.argv.slice(2);

console.log(JSON.stringify(userArgs));
```

On Deno, this is different:

```ts
const userArgs = Deno.args;
```

---

## 2. `--` ends option parsing

Everything after `--` must be treated as positional, even if it starts with `-`.

```ts
function splitTerminator(argv: string[]) {
  const index = argv.indexOf("--");
  if (index === -1) return { options: argv, positionals: [] };

  return {
    options: argv.slice(0, index),
    positionals: argv.slice(index + 1),
  };
}
```

Example:

```sh
my-cli -- --not-an-option -x "value with spaces"
```

---

## 3. Do not trust argument order

Users may pass options before, between, or after positional arguments.

```ts
interface Parsed {
  verbose: boolean;
  files: string[];
}

function parse(argv: string[]): Parsed {
  const result: Parsed = { verbose: false, files: [] };

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === "--verbose" || token === "-v") {
      result.verbose = true;
      continue;
    }

    if (token === "--") {
      // Everything after is positional.
      result.files.push(...argv.slice(i + 1));
      break;
    }

    // Treat unknown non-option tokens as positionals.
    if (!token.startsWith("-")) {
      result.files.push(token);
    } else {
      throw new Error(`Unknown option: ${token}`);
    }
  }

  return result;
}
```

---

## 4. Long options with and without `=`

Support both `--port 3000` and `--port=3000`. Empty values are valid unless your domain forbids them.

```ts
function readValue(token: string, argv: string[], i: number) {
  const eq = token.indexOf("=");

  if (eq >= 0) {
    return { value: token.slice(eq + 1), nextIndex: i };
  }

  const next = argv[i + 1];
  if (next === undefined) {
    throw new Error(`Missing value for ${token}`);
  }

  return { value: next, nextIndex: i + 1 };
}

const argv = ["--name=", "--port", "3000"];
// --name= means an empty string, which is a valid value.
```

---

## 5. Negative numbers

A `-5` can be either an unknown option or a value. The safest rule:

- If an option **expects a value**, consume the next token unconditionally.
- Otherwise, treat `-5` as positional only if it is not a known flag.

```ts
function isNumberToken(token: string): boolean {
  return /^-?\d+(\.\d+)?$/.test(token);
}

// Example: --offset -5 should consume -5 as the value.
if (token === "--offset") {
  const next = argv[i + 1];
  if (next === undefined || !isNumberToken(next)) {
    throw new Error("--offset requires a number");
  }
  offset = Number(next);
  i++;
}
```

Also handle inline negative values:

```ts
parse("--offset=-5");
```

---

## 6. Short flag clustering and aliases

`-abc` may mean `-a -b -c`, and `-p8080` may mean `--port 8080`.

```ts
const shortAliases: Record<string, string> = {
  v: "verbose",
  p: "port",
  o: "output",
};

function parseShortCluster(cluster: string, argv: string[], i: number) {
  let index = i;

  for (let j = 0; j < cluster.length; j++) {
    const alias = shortAliases[cluster[j]];
    if (!alias) throw new Error(`Unknown short option: -${cluster[j]}`);

    if (alias === "verbose") {
      state.verbose = true;
      continue;
    }

    // Value-taking option: rest of cluster or next token.
    const rest = cluster.slice(j + 1);
    const value = rest.length > 0 ? rest : argv[index + 1];
    if (value === undefined) throw new Error(`Missing value for -${cluster[j]}`);

    if (rest.length === 0) index++;
    state.port = assertInteger(value, "--port");
    break;
  }

  return index;
}
```

---

## 7. Boolean negation

Support `--no-color`, `--no-cache`, etc. Be careful not to confuse `--not-...`.

```ts
function parseBooleanOption(key: string, value?: string) {
  if (key.startsWith("no-")) {
    const positive = key.slice(3);
    if (positive === "color") return { color: false };
  }

  return { [key]: true };
}
```

---

## 8. Repeated options and arrays

Users may repeat `--tag foo --tag bar`, or pass comma-separated values. Decide one and document it.

```ts
interface Config {
  tags: string[];
}

function parseTags(argv: string[]): Config {
  const tags: string[] = [];

  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === "--tag") {
      const value = argv[i + 1];
      if (!value) throw new Error("--tag requires a value");
      tags.push(value);
      i++;
    }
  }

  return { tags };
}
```

For comma input, split deliberately:

```ts
const tags = raw.split(",").map(s => s.trim()).filter(Boolean);
```

But do not silently accept both unless documented.

---

## 9. Positional arguments with spaces are already tokenized by the shell

Your code receives separate tokens. Quoting is the shell's job, not TypeScript's.

```sh
my-cli "first file.txt" 'second file.txt'
```

```ts
// argv already contains:
// ["first file.txt", "second file.txt"]
```

Do not call `JSON.parse`, `eval`, or shell interpolation on arguments.

---

## 10. Runtime validation is required

TypeScript cannot validate `process.argv`. Convert and validate at the boundary.

```ts
function asPort(value: string): number {
  const port = Number(value);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error(`Invalid port: ${value}`);
  }
  return port;
}

function asPath(value: string): string {
  if (value.includes("\0")) throw new Error("Path contains NUL");
  if (value.trim() === "") throw new Error("Path cannot be empty");
  return value;
}
```

For more complex validation, use a runtime validator such as Zod:

```ts
import { z } from "zod";

const Schema = z.object({
  port: z.coerce.number().int().min(1).max(65535).default(3000),
  host: z.string().min(1).default("localhost"),
});

const parsed = Schema.parse(rawArgs);
```

---

## 11. Environment variables as fallback

CLI args usually win over env vars. Validate both sources the same way.

```ts
function getPort(argvPort?: string): number {
  const raw = argvPort ?? process.env.PORT;
  if (raw === undefined) return 3000;

  const port = Number(raw);
  if (!Number.isInteger(port)) throw new Error(`Invalid port: ${raw}`);
  return port;
}
```

Precedence:

```text
CLI flag > environment variable > config file > default
```

---

## 12. Unknown options and strict mode

Decide whether unknown options are errors. Strict mode is usually better for CLIs.

```ts
const known = new Set(["--port", "--host", "--verbose", "-v", "-h"]);

for (const token of argv) {
  if (token.startsWith("-") && !known.has(token.split("=")[0])) {
    throw new Error(`Unknown option: ${token}`);
  }
}
```

With Commander:

```ts
import { Command } from "commander";

const program = new Command()
  .option("-p, --port <number>", "port", "3000")
  .allowUnknownOption(false)
  .parse(process.argv);
```

---

## 13. Exit codes, stdout, and stderr

Use exit code `0` for success, `1` for expected user errors, and `2` for usage errors if following common conventions. Print errors to `stderr`.

```ts
function fail(message: string, code = 1): never {
  console.error(`error: ${message}`);
  process.exit(code);
}

function usage(): never {
  console.error("Usage: my-cli [options] <file>");
  process.exit(2);
}
```

Keep data on stdout and diagnostics on stderr so piping works:

```sh
my-cli input.txt > output.json
```

---

## 14. Help and version should exit immediately

Handle `--help` and `--version` before heavy work.

```ts
if (argv.includes("--help") || argv.includes("-h")) {
  console.log("Usage: my-cli [options] <files...>");
  process.exit(0);
}

if (argv.includes("--version") || argv.includes("-V")) {
  console.log("1.0.0");
  process.exit(0);
}
```

Be careful: only treat these as flags when used exactly as options, not as positional file names. With a `--` terminator, `--help` after `--` is a filename.

---

## 15. Secrets and process listings

CLI arguments are visible in `ps`. Avoid accepting secrets directly when possible; use environment variables or stdin. Never log raw `process.argv` if it may contain tokens.

```ts
function redactArgs(args: string[]): string[] {
  return args.map((arg, i) =>
    args[i - 1]?.startsWith("--token") || args[i - 1] === "-t"
      ? "[redacted]"
      : arg
  );
}
```

---

## 16. Path and security edge cases

If arguments represent filesystem paths:

```ts
import path from "node:path";

function safeResolve(input: string, root: string): string {
  const resolved = path.resolve(root, input);
  const relative = path.relative(root, resolved);

  if (relative.startsWith("..") || path.isAbsolute(relative)) {
    throw new Error(`Path escapes allowed root: ${input}`);
  }

  return resolved;
}
```

Also avoid shelling out unsafely. Use `execFile`, not `exec`, and pass arguments as an array:

```ts
import { execFile } from "node:child_process";

execFile("git", ["log", userInput], (error, stdout) => {
  // userInput is not interpreted by a shell
});
```

---

## 17. Signals and partial output

If your CLI performs long work, handle interruption and clean up.

```ts
process.on("SIGINT", () => {
  console.error("\nInterrupted");
  process.exit(130); // 128 + SIGINT(2)
});

process.on("SIGTERM", () => {
  process.exit(143); // 128 + SIGTERM(15)
});
```

---

## 18. A compact robust parser example

```ts
// src/parse.ts
export interface CliOptions {
  verbose: boolean;
  host: string;
  port: number;
  files: string[];
  tags: string[];
}

const BOOLEAN = new Set(["verbose"]);
const VALUE = new Set(["host", "port"]);
const ARRAY = new Set(["tag"]);
const SHORT: Record<string, string> = {
  v: "verbose",
  h: "host",
  p: "port",
  t: "tag",
};

export function parseCli(argv: readonly string[]): CliOptions {
  const result: CliOptions = {
    verbose: false,
    host: "localhost",
    port: 3000,
    files: [],
    tags: [],
  };

  let endOptions = false;

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (endOptions) {
      result.files.push(token);
      continue;
    }

    if (token === "--") {
      endOptions = true;
      continue;
    }

    if (token.startsWith("--")) {
      const eq = token.indexOf("=");
      const key = eq >= 0 ? token.slice(2, eq) : token.slice(2);
      const inline = eq >= 0 ? token.slice(eq + 1) : undefined;

      if (key.startsWith("no-") && key.slice(3) === "verbose") {
        result.verbose = false;
        continue;
      }

      if (BOOLEAN.has(key)) {
        result.verbose = true;
        continue;
      }

      if (!VALUE.has(key) && !ARRAY.has(key)) {
        throw new Error(`Unknown option: --${key}`);
      }

      const value = inline ?? argv[++i];
      if (value === undefined) throw new Error(`Missing value for --${key}`);

      if (ARRAY.has(key)) {
        result.tags.push(value);
      } else if (key === "host") {
        result.host = value;
      } else if (key === "port") {
        const port = Number(value);
        if (!Number.isInteger(port) || port < 1 || port > 65535) {
          throw new Error(`Invalid port: ${value}`);
        }
        result.port = port;
      }

      continue;
    }

    if (token.startsWith("-") && token.length > 1) {
      const chars = token.slice(1);

      for (let j = 0; j < chars.length; j++) {
        const name = SHORT[chars[j]];
        if (!name) throw new Error(`Unknown short option: -${chars[j]}`);

        if (name === "verbose") {
          result.verbose = true;
          continue;
        }

        const rest = chars.slice(j + 1);
        const value = rest.length > 0 ? rest : argv[++i];
        if (value === undefined) throw new Error(`Missing value for -${chars[j]}`);

        if (name === "host") result.host = value;
        if (name === "port") {
          const port = Number(value);
          if (!Number.isInteger(port)) throw new Error(`Invalid port: ${value}`);
          result.port = port;
        }
        if (name === "tag") result.tags.push(value);

        break; // value consumed the rest of the cluster
      }

      continue;
    }

    result.files.push(token);
  }

  return result;
}
```

