## 4. `src/lib/store.ts` — persistence layer

```ts
import { promises as fs } from "node:fs";
import path from "node:path";
import os from "node:os";
import type { Task, TaskStore } from "../types.js";

const DEFAULT_STORE: TaskStore = { nextId: 1, tasks: [] };

export class TaskStoreManager {
  constructor(private readonly filePath: string) {}

  async load(): Promise<TaskStore> {
    try {
      const raw = await fs.readFile(this.filePath, "utf8");
      const parsed = JSON.parse(raw) as TaskStore;
      // defensive normalization
      return {
        nextId: parsed.nextId ?? 1,
        tasks: Array.isArray(parsed.tasks) ? parsed.tasks : [],
      };
    } catch (err: unknown) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") {
        return { ...DEFAULT_STORE };
      }
      throw new Error(`Failed to read store: ${(err as Error).message}`);
    }
  }

  async save(store: TaskStore): Promise<void> {
    await fs.mkdir(path.dirname(this.filePath), { recursive: true });
    const tmp = this.filePath + ".tmp";
    await fs.writeFile(tmp, JSON.stringify(store, null, 2), "utf8");
    await fs.rename(tmp, this.filePath); // atomic-ish write
  }

  async add(title: string, tags: string[] = []): Promise<Task> {
    const store = await this.load();
    const task: Task = {
      id: store.nextId++,
      title,
      done: false,
      createdAt: new Date().toISOString(),
      tags,
    };
    store.tasks.push(task);
    await this.save(store);
    return task;
  }

  async list(filter: "all" | "open" | "done" = "all"): Promise<Task[]> {
    const store = await this.load();
    return store.tasks.filter((t) => {
      if (filter === "open") return !t.done;
      if (filter === "done") return t.done;
      return true;
    });
  }

  async complete(id: number): Promise<Task> {
    const store = await this.load();
    const task = store.tasks.find((t) => t.id === id);
    if (!task) throw new Error(`No task with id ${id}`);
    if (task.done) throw new Error(`Task ${id} is already done`);
    task.done = true;
    task.doneAt = new Date().toISOString();
    await this.save(store);
    return task;
  }

  async remove(id: number): Promise<void> {
    const store = await this.load();
    const idx = store.tasks.findIndex((t) => t.id === id);
    if (idx === -1) throw new Error(`No task with id ${id}`);
    store.tasks.splice(idx, 1);
    await this.save(store);
  }

  static defaultPath(): string {
    return path.join(os.homedir(), ".task-cli", "tasks.json");
  }
}
```

