## 6. `src/lib/output.ts`

```ts
import chalk from "chalk";
import { isColorEnabled } from "./config.js";

export const c = {
  ok: (s: string) => (isColorEnabled() ? chalk.green(s) : s),
  warn: (s: string) => (isColorEnabled() ? chalk.yellow(s) : s),
  err: (s: string) => (isColorEnabled() ? chalk.red(s) : s),
  dim: (s: string) => (isColorEnabled() ? chalk.gray(s) : s),
  bold: (s: string) => (isColorEnabled() ? chalk.bold(s) : s),
  cyan: (s: string) => (isColorEnabled() ? chalk.cyan(s) : s),
};

export function printTask(t: { id: number; title: string; done: boolean; tags: string[] }): void {
  const status = t.done ? c.ok("✓") : c.warn("○");
  const title = t.done ? c.dim(t.title) : t.title;
  const tags = t.tags.length ? c.cyan(` [${t.tags.join(", ")}]`) : "";
  console.log(`${status} ${c.bold(String(t.id))}. ${title}${tags}`);
}

export function fail(msg: string): never {
  console.error(c.err(`error: ${msg}`));
  process.exit(1);
}
```

## 7. Commands

### `src/commands/add.ts`

```ts
import { Command } from "commander";
import { TaskStoreManager } from "../lib/store.js";
import { getDataFile } from "../lib/config.js";
import { c, printTask } from "../lib/output.js";

export function registerAdd(program: Command): void {
  program
    .command("add <title...>")
    .description("Add a new task")
    .option("-t, --tag <tag>", "tag to attach (repeatable)", (v, acc: string[]) => [...acc, v], [])
    .action(async (titleParts: string[], opts: { tag: string[] }) => {
      const title = titleParts.join(" ").trim();
      if (!title) {
        console.error(c.err("title cannot be empty"));
        process.exit(1);
      }
      const store = new TaskStoreManager(getDataFile());
      const task = await store.add(title, opts.tag);
      console.log(c.ok(`Added task ${task.id}`));
      printTask(task);
    });
}
```

### `src/commands/list.ts`

```ts
import { Command } from "commander";
import { TaskStoreManager } from "../lib/store.js";
import { getDataFile } from "../lib/config.js";
import { c, printTask } from "../lib/output.js";

export function registerList(program: Command): void {
  program
    .command("list")
    .alias("ls")
    .description("List tasks")
    .option("-a, --all", "show all tasks (default)")
    .option("-o, --open", "show only open tasks")
    .option("-d, --done", "show only completed tasks")
    .option("--json", "output as JSON")
    .action(async (opts) => {
      const filter = opts.done ? "done" : opts.open ? "open" : "all";
      const store = new TaskStoreManager(getDataFile());
      const tasks = await store.list(filter);

      if (opts.json) {
        console.log(JSON.stringify(tasks, null, 2));
        return;
      }
      if (tasks.length === 0) {
        console.log(c.dim("No tasks. Add one with `task add <title>`"));
        return;
      }
      for (const t of tasks) printTask(t);
      const open = tasks.filter((t) => !t.done).length;
      console.log(c.dim(`\n${open} open, ${tasks.length - open} done`));
    });
}
```

### `src/commands/done.ts`

```ts
import { Command } from "commander";
import { TaskStoreManager } from "../lib/store.js";
import { getDataFile } from "../lib/config.js";
import { c, printTask } from "../lib/output.js";

export function registerDone(program: Command): void {
  program
    .command("done <id>")
    .description("Mark a task as done")
    .action(async (idStr: string) => {
      const id = Number(idStr);
      if (!Number.isInteger(id) || id <= 0) {
        console.error(c.err("id must be a positive integer"));
        process.exit(1);
      }
      const store = new TaskStoreManager(getDataFile());
      try {
        const task = await store.complete(id);
        console.log(c.ok(`Completed task ${id}`));
        printTask(task);
      } catch (e) {
        console.error(c.err((e as Error).message));
        process.exit(1);
      }
    });
}
```

### `src/commands/remove.ts`

```ts
import { Command } from "commander";
import { TaskStoreManager } from "../lib/store.js";
import { getDataFile } from "../lib/config.js";
import { c } from "../lib/output.js";

export function registerRemove(program: Command): void {
  program
    .command("remove <id>")
    .alias("rm")
    .description("Remove a task")
    .option("-y, --yes", "skip confirmation")
    .action(async (idStr: string, opts: { yes?: boolean }) => {
      const id = Number(idStr);
      if (!Number.isInteger(id) || id <= 0) {
        console.error(c.err("id must be a positive integer"));
        process.exit(1);
      }
      const store = new TaskStoreManager(getDataFile());

      if (!opts.yes) {
        // tiny inline prompt without extra deps
        process.stdout.write(`Remove task ${id}? [y/N] `);
        const answer = await new Promise<string>((resolve) => {
          process.stdin.once("data", (d) => resolve(d.toString().trim().toLowerCase()));
        });
        if (answer !== "y" && answer !== "yes") {
          console.log(c.dim("cancelled"));
          return;
        }
      }

      try {
        await store.remove(id);
        console.log(c.ok(`Removed task ${id}`));
      } catch (e) {
        console.error(c.err((e as Error).message));
        process.exit(1);
      }
    });
}
```

### `src/commands/config.ts`

```ts
import { Command } from "commander";
import { config, getDataFile, setDataFile } from "../lib/config.js";
import { c } from "../lib/output.js";

export function registerConfig(program: Command): void {
  const cmd = program.command("config").description("Manage configuration");

  cmd
    .command("show")
    .description("Show current config")
    .action(() => {
      console.log(JSON.stringify(config.store, null, 2));
      console.log(c.dim(`\nconfig file: ${config.path}`));
    });

  cmd
    .command("set <key> <value>")
    .description("Set a config value (dataFile | defaultTags | color)")
    .action((key: string, value: string) => {
      const allowed = ["dataFile", "defaultTags", "color"];
      if (!allowed.includes(key)) {
        console.error(c.err(`unknown key: ${key}`));
        process.exit(1);
      }
      if (key === "color") {
        config.set("color", value === "true" || value === "1");
      } else if (key === "defaultTags") {
        config.set("defaultTags", value.split(",").map((s) => s.trim()).filter(Boolean));
      } else if (key === "dataFile") {
        setDataFile(value);
      }
      console.log(c.ok(`set ${key} = ${value}`));
    });

  cmd
    .command("get <key>")
    .description("Get a config value")
    .action((key: string) => {
      console.log(config.get(key as never));
    });

  cmd
    .command("path")
    .description("Print data file path")
    .action(() => {
      console.log(getDataFile());
    });
}
```

## 8. `src/index.ts` — entry point

```ts
#!/usr/bin/env node
import { Command } from "commander";
import { registerAdd } from "./commands/add.js";
import { registerList } from "./commands/list.js";
import { registerDone } from "./commands/done.js";
import { registerRemove } from "./commands/remove.js";
import { registerConfig } from "./commands/config.js";
import { c } from "./lib/output.js";
import { getDataFile } from "./lib/config.js";
import { TaskStoreManager } from "./lib/store.js";

const program = new Command();

program
  .name("task")
  .description("A tiny task tracker")
  .version("1.0.0")
  .option("-f, --file <path>", "override data file")
  .hook("preAction", (thisCommand) => {
    const opts = thisCommand.opts();
    if (opts.file) {
      // mutate config for this run
      process.env.TASK_DATA_FILE = opts.file;
    }
  });

// global --file handling is simpler via env; wire it in store usage instead:
// (see note below)

registerAdd(program);
registerList(program);
registerDone(program);
registerRemove(program);
registerConfig(program);

// Top-level convenience: `task` with no command shows help-ish list
program.action(async () => {
  const store = new TaskStoreManager(getDataFile());
  const tasks = await store.list("open");
  if (tasks.length === 0) {
    console.log(c.dim("No open tasks. Try `task add <title>`"));
    return;
  }
  for (const t of tasks) {
    // eslint-disable-next-line no-console
    console.log(`${t.id}. ${t.title}`);
  }
});

program.parseAsync(process.argv).catch((err) => {
  console.error(c.err(err instanceof Error ? err.message : String(err)));
  process.exit(1);
});
```

> **Simplification note:** The `--file` global flag is cleaner if you resolve the data file through a single helper. Replace `getDataFile()` calls with a helper that checks `process.env.TASK_DATA_FILE` first:

```ts
// in config.ts
export function getDataFile(): string {
  return process.env.TASK_DATA_FILE || config.get("dataFile");
}
```

and drop the `preAction` hook. This keeps `--file` working if you add it as an option on each command, or you can keep the hook. For brevity, the env approach is shown.

