#!/usr/bin/env node
import { Command } from "commander";
import { readFileSync } from "node:fs";

const program = new Command();

program
  .name("mycli")
  .description("A small TypeScript CLI")
  .version("1.0.0");

program
  .command("greet")
  .description("Greet someone")
  .argument("<name>", "person to greet")
  .option("-u, --upper", "uppercase the name")
  .option("-n, --repeat <count>", "repeat count", "1")
  .action((name: string, opts: { upper?: boolean; repeat: string }) => {
    const out = opts.upper ? name.toUpperCase() : name;
    for (let i = 0; i < Number(opts.repeat); i++) {
      console.log(`Hello, ${out}!`);
    }
  });

program
  .command("info")
  .description("Print package info")
  .action(() => {
    const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
    console.log(pkg.name, pkg.version);
  });

program.parse();
```

Usage:

```bash
mycli greet Alice --upper --repeat 3
mycli info
mycli --help
```

### `yargs` (alternative, strong typing via `.options`)

```ts
import yargs from "yargs";
import { hideBin } from "yargs/helpers";

interface Args {
  name: string;
  verbose: boolean;
}

yargs(hideBin(process.argv))
  .command<Args>("greet <name>", "greet", (y) =>
    y.positional("name", { type: "string", demandOption: true })
     .option("verbose", { type: "boolean", default: false }),
    (argv) => {
      console.log(`Hello, ${argv.name}`);
      if (argv.verbose) console.log("verbose on");
    }
  )
  .strict()
  .parse();
```

