### 2. Create the CSV/statistics module

`src/csv.ts`:

```ts
export interface ColumnStats {
  count: number;
  min: number;
  max: number;
  sum: number;
  mean: number;
}

export function parseCsv(text: string, delimiter = ","): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
      continue;
    }

    if (ch === '"') {
      inQuotes = true;
    } else if (ch === delimiter) {
      row.push(field);
      field = "";
    } else if (ch === "\n") {
      row.push(field);
      rows.push(row);
      row = [];
      field = "";
    } else if (ch !== "\r") {
      field += ch;
    }
  }

  if (field !== "" || row.length > 0) {
    row.push(field);
    rows.push(row);
  }

  return rows.filter((r) => !(r.length === 1 && r[0] === ""));
}

export function computeStats(
  rows: string[][],
  columns?: string[]
): Record<string, ColumnStats> {
  if (rows.length < 2) return {};

  const header = rows[0].map((h) => h.trim());
  const selectedColumns = columns && columns.length > 0 ? columns : header;
  const result: Record<string, ColumnStats> = {};

  for (const requested of selectedColumns) {
    const name = requested.trim();
    const index = header.indexOf(name);
    if (index < 0) continue;

    const values = rows
      .slice(1)
      .map((r) => r[index]?.trim() ?? "")
      .filter((v) => v !== "")
      .map(Number)
      .filter((n) => !Number.isNaN(n));

    if (values.length === 0) {
      result[name] = {
        count: 0,
        min: NaN,
        max: NaN,
        sum: 0,
        mean: NaN,
      };
      continue;
    }

    const sum = values.reduce((a, b) => a + b, 0);

    result[name] = {
      count: values.length,
      min: Math.min(...values),
      max: Math.max(...values),
      sum,
      mean: sum / values.length,
    };
  }

  return result;
}
```

### 3. Create the CLI entry point

`src/cli.ts`:

```ts
#!/usr/bin/env node

import { Command } from "commander";
import { readFileSync } from "node:fs";
import { computeStats, parseCsv } from "./csv.js";

async function readInput(file?: string): Promise<string> {
  if (file) {
    return readFileSync(file, "utf8");
  }

  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) {
    chunks.push(chunk as Buffer);
  }
  return Buffer.concat(chunks).toString("utf8");
}

const program = new Command();

program
  .name("csvstats")
  .description("Compute numeric column statistics from a CSV file")
  .argument("[file]", "CSV file path; defaults to stdin")
  .option("-d, --delimiter <char>", "field delimiter", ",")
  .option("-c, --columns <names>", "comma-separated column names")
  .action(async (file: string | undefined, options) => {
    const text = await readInput(file);
    const rows = parseCsv(text, options.delimiter);
    const columns = options.columns
      ? options.columns.split(",").map((s) => s.trim())
      : undefined;

    const stats = computeStats(rows, columns);
    process.stdout.write(JSON.stringify(stats, null, 2) + "\n");
  });

program.parse();
```

