```ts
/**
 * Domain models for the demo.
 *
 * @packageDocumentation
 */

/**
 * Public representation of a user.
 */
export interface User {
  /** Stable unique identifier. */
  readonly id: string;

  /** Display name. */
  name: string;

  /** Optional email address. */
  email?: string;
}

/**
 * A simple in-memory user repository.
 *
 * @remarks
 * This repository is not thread-safe and is intended for teaching/demo purposes.
 */
export class UserRepository {
  private readonly users = new Map<string, User>();

  /**
   * Create a repository, optionally seeded with users.
   *
   * @param initial - Seed users. Defaults to an empty list.
   */
  constructor(initial: readonly User[] = []) {
    for (const user of initial) {
      this.users.set(user.id, user);
    }
  }

  /**
   * Find a user by id.
   *
   * @param id - User id.
   * @returns The user if found; otherwise `undefined`.
   */
  get(id: string): User | undefined {
    return this.users.get(id);
  }

  /**
   * Add or replace a user.
   *
   * @param user - User to store.
   * @returns `this`, enabling method chaining.
   */
  upsert(user: User): this {
    this.users.set(user.id, user);
    return this;
  }

  /**
   * Remove a user.
   *
   * @param id - User id.
   * @returns `true` if a user was removed.
   */
  delete(id: string): boolean {
    return this.users.delete(id);
  }

  /**
   * Number of stored users.
   */
  get size(): number {
    return this.users.size;
  }
}
```

