/**
 * Generic collection helpers.
 *
 * @packageDocumentation
 */

/**
 * Group items by a key derived from each item.
 *
 * @typeParam T - Item type.
 * @typeParam K - Key type. Must be usable as a `Map` key.
 * @param items - Items to group.
 * @param getKey - Function returning the grouping key.
 * @returns A `Map` from key to the list of items with that key.
 * @example
 * ```ts
 * const byParity = groupBy([1, 2, 3, 4], (n) => (n % 2 === 0 ? "even" : "odd"));
 * // Map { "odd" => [1, 3], "even" => [2, 4] }
 * ```
 */
export function groupBy<T, K extends string | number | symbol>(
  items: readonly T[],
  getKey: (item: T) => K,
): Map<K, T[]> {
  const result = new Map<K, T[]>();

  for (const item of items) {
    const key = getKey(item);
    const bucket = result.get(key);
    if (bucket) {
      bucket.push(item);
    } else {
      result.set(key, [item]);
    }
  }

  return result;
}

/**
 * Supported log levels.
 */
export enum LogLevel {
  /** Debugging output. */
  Debug = 0,
  /** Informational messages. */
  Info = 1,
  /** Error messages. */
  Error = 2,
}

/**
 * A factory that returns a promise of `T`.
 */
export type AsyncFactory<T> = () => Promise<T>;

/**
 * Parse a string into a number.
 *
 * @param input - String to parse.
 * @returns Parsed number, or `NaN` if parsing fails.
 */
export function parseNumber(input: string): number;

/**
 * Parse a string into a number using a radix.
 *
 * @param input - String to parse.
 * @param radix - Radix between 2 and 36.
 * @returns Parsed number, or `NaN` if parsing fails.
 */
export function parseNumber(input: string, radix: number): number;

/**
 * Implementation of {@link parseNumber}.
 *
 * @internal
 */
export function parseNumber(input: string, radix?: number): number {
  return parseInt(input, radix);
}
