```ts
import { describe, it, expect } from "vitest";
import { comprehend, comprehendNested, toArray } from "./comprehension";

describe("comprehend", () => {
  it("maps and filters", () => {
    expect(toArray(comprehend([1,2,3,4], x=>x*x, x=>x%2===0)))
      .toEqual([4, 16]);
