# Conditionals and Branches in TypeScript

TypeScript conditionals look like JavaScript, but they're special because the compiler **narrows types** based on which branch is taken. Below is a complete, runnable example that demonstrates every major construct plus the type-system features that make TS conditionals powerful.

## Complete runnable example (`conditionals.ts`)

```ts
// ============================================================
// 1. Basic if / else if / else
// ============================================================
function grade(score: number): string {
  if (score >= 90) {
    return "A";
  } else if (score >= 80) {
    return "B";
  } else if (score >= 70) {
    return "C";
  } else {
    return "F";
  }
}

// ============================================================
// 2. Type narrowing via typeof guards
// ============================================================
function describe(value: string | number | boolean): string {
  if (typeof value === "string") {
    // TS narrows `value` to `string` here
    return `string of length ${value.length}`;
  } else if (typeof value === "number") {
    // TS narrows `value` to `number` here
    return `number squared = ${value * value}`;
  }
  // After the checks above, `value` is narrowed to `boolean`
  return value ? "true boolean" : "false boolean";
}

// ============================================================
// 3. Truthiness / nullish narrowing
// ============================================================
function greet(name: string | null | undefined): string {
  if (!name) {
    return "Hello, stranger";
  }
  // `name` is narrowed to `string` here
  return `Hello, ${name.toUpperCase()}`;
}

// ============================================================
// 4. Ternary operator (expression-level branch)
// ============================================================
const isEven = (n: number) => (n % 2 === 0 ? "even" : "odd");

// ============================================================
// 5. Logical AND / OR short-circuit (branching without if)
// ============================================================
function renderUser(user: { name: string } | null): string {
  return user && `Welcome, ${user.name}`; // null short-circuits to null
}

// ============================================================
// 6. Nullish coalescing (??) vs OR (||)
// ============================================================
function displayName(input: string | null | undefined): string {
  // ?? only falls back on null/undefined, not "" or 0
  return input ?? "anonymous";
}

// ============================================================
// 7. Optional chaining with branch-like semantics
// ============================================================
type User = { profile?: { avatar?: string } };
function avatarUrl(u: User): string {
  return u.profile?.avatar ?? "/default.png";
}

// ============================================================
// 8. switch statement + exhaustiveness checking
// ============================================================
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "rect"; width: number; height: number }
  | { kind: "triangle"; base: number; height: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "rect":
      return shape.width * shape.height;
    case "triangle":
      return (shape.base * shape.height) / 2;
    default: {
      // Exhaustiveness check: if a new variant is added to Shape,
      // this line fails to compile.
      const _exhaustive: never = shape;
      throw new Error(`Unhandled shape: ${JSON.stringify(_exhaustive)}`);
    }
  }
}

// ============================================================
// 9. Discriminated-union narrowing with `in` operator
// ============================================================
type Bird = { fly: () => void; layEggs: () => void };
type Fish = { swim: () => void; layEggs: () => void };

function move(animal: Bird | Fish): void {
  if ("swim" in animal) {
    animal.swim(); // narrowed to Fish
  } else {
    animal.fly(); // narrowed to Bird
  }
}

// ============================================================
// 10. instanceof narrowing
// ============================================================
class ApiError extends Error {
  constructor(public status: number, message: string) {
    super(message);
  }
}

function handleError(err: unknown): string {
  if (err instanceof ApiError) {
    return `HTTP ${err.status}: ${err.message}`;
  }
  if (err instanceof Error) {
    return `Error: ${err.message}`;
  }
  return `Unknown: ${String(err)}`;
}

// ============================================================
// 11. Custom type guard (user-defined narrowing)
// ============================================================
interface Cat { meow(): void }
interface Dog { bark(): void }

function isCat(animal: Cat | Dog): animal is Cat {
  return (animal as Cat).meow !== undefined;
}

function speak(animal: Cat | Dog): void {
  if (isCat(animal)) {
    animal.meow(); // narrowed to Cat
  } else {
    animal.bark(); // narrowed to Dog
  }
}

// ============================================================
// 12. Assertion functions (narrow via throws)
// ============================================================
function assertDefined<T>(value: T | null | undefined, msg?: string): asserts value is T {
  if (value == null) throw new Error(msg ?? "value is null/undefined");
}

function useValue(v: string | null): number {
  assertDefined(v, "v must be defined");
  // After the assertion, `v` is narrowed to `string`
  return v.length;
}

// ============================================================
// 13. Control-flow: early returns / guard clauses
// ============================================================
function processOrder(order: { items: string[]; paid: boolean } | null): string {
  if (!order) return "no order";
  if (order.items.length === 0) return "empty cart";
  if (!order.paid) return "awaiting payment";
  return `shipping ${order.items.length} items`;
}

// ============================================================
// 14. Branching over literal unions with `satisfies`
// ============================================================
type Status = "idle" | "loading" | "success" | "error";

const handlers = {
  idle: () => "waiting",
  loading: () => "spinner",
  success: () => "done",
  error: () => "retry",
} satisfies Record<Status, () => string>;

function renderStatus(s: Status): string {
  return handlers[s](); // lookup table acts as a branch
}

// ============================================================
// DEMO / self-test
// ============================================================
function main(): void {
  console.log("grade(85) =", grade(85));
  console.log("describe('hi') =", describe("hi"));
  console.log("describe(4) =", describe(4));
  console.log("describe(true) =", describe(true));
  console.log("greet(null) =", greet(null));
  console.log("greet('Ada') =", greet("Ada"));
  console.log("isEven(7) =", isEven(7));
  console.log("renderUser(null) =", renderUser(null));
  console.log("displayName('') =", JSON.stringify(displayName("")));
  console.log("displayName(undefined) =", displayName(undefined));
  console.log("avatarUrl({}) =", avatarUrl({}));
  console.log("area circle =", area({ kind: "circle", radius: 2 }));
  console.log("area rect =", area({ kind: "rect", width: 3, height: 4 }));
  console.log("handleError =", handleError(new ApiError(404, "not found")));
  console.log("useValue('abc') =", useValue("abc"));
  console.log("processOrder =", processOrder({ items: ["x"], paid: true }));
  console.log("renderStatus =", renderStatus("loading"));
}

main();
```

