// crypto-basics.ts
// Run with: npx ts-node crypto-basics.ts  (or tsc && node crypto-basics.js)
// Requires Node.js >= 16 (for ed25519 + scrypt sync).

import crypto from "node:crypto";

/* ------------------------------------------------------------------ */
/* Encoding helpers                                                   */
/* ------------------------------------------------------------------ */
const b64 = (b: Buffer) => b.toString("base64");
const fromB64 = (s: string) => Buffer.from(s, "base64");
const hex = (b: Buffer | string) =>
  Buffer.isBuffer(b) ? b.toString("hex") : Buffer.from(b).toString("hex");

/* ------------------------------------------------------------------ */
/* 1. Hashing                                                         */
/* ------------------------------------------------------------------ */
function sha256(data: string | Buffer): string {
  return crypto.createHash("sha256").update(data).digest("hex");
}
function sha512(data: string | Buffer): string {
  return crypto.createHash("sha512").update(data).digest("hex");
}

/* ------------------------------------------------------------------ */
/* 2. HMAC (message authentication)                                   */
/* ------------------------------------------------------------------ */
function hmacSha256(key: string | Buffer, data: string | Buffer): string {
  return crypto.createHmac("sha256", key).update(data).digest("hex");
}

/* ------------------------------------------------------------------ */
/* 3. Key derivation (password -> cryptographic key)                  */
/* ------------------------------------------------------------------ */
function deriveKey(password: string, salt: Buffer, keyLen = 32): Buffer {
  // scrypt is memory-hard; good default for password-based keys.
  return crypto.scryptSync(password, salt, keyLen);
}

/* ------------------------------------------------------------------ */
/* 4. Symmetric authenticated encryption (AES-256-GCM)                */
/* ------------------------------------------------------------------ */
interface EncryptedPayload {
  iv: string;          // base64
  tag: string;         // base64 (auth tag)
  ciphertext: string;  // base64
}

function encryptAesGcm(plaintext: string, key: Buffer): EncryptedPayload {
  if (key.length !== 32) throw new Error("AES-256 requires a 32-byte key");
  const iv = crypto.randomBytes(12); // 96-bit IV recommended for GCM
  const cipher = crypto.createCipheriv("aes-256-gcm", key, iv);
  const ciphertext = Buffer.concat([
    cipher.update(plaintext, "utf8"),
    cipher.final(),
  ]);
  const tag = cipher.getAuthTag();
  return { iv: b64(iv), tag: b64(tag), ciphertext: b64(ciphertext) };
}

function decryptAesGcm(payload: EncryptedPayload, key: Buffer): string {
  const iv = fromB64(payload.iv);
  const tag = fromB64(payload.tag);
  const ciphertext = fromB64(payload.ciphertext);
  const decipher = crypto.createDecipheriv("aes-256-gcm", key, iv);
  decipher.setAuthTag(tag);
  const plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  return plaintext.toString("utf8");
}

/* ------------------------------------------------------------------ */
/* 5. Password hashing + verification (scrypt)                        */
/* ------------------------------------------------------------------ */
interface PasswordRecord {
  salt: string; // base64
  hash: string; // base64
}

function hashPassword(password: string): PasswordRecord {
  const salt = crypto.randomBytes(16);
  const hash = crypto.scryptSync(password, salt, 64);
  return { salt: b64(salt), hash: b64(hash) };
}

function verifyPassword(password: string, record: PasswordRecord): boolean {
  const salt = fromB64(record.salt);
  const expected = fromB64(record.hash);
  const actual = crypto.scryptSync(password, salt, expected.length);
  if (actual.length !== expected.length) return false;
  return crypto.timingSafeEqual(actual, expected);
}

/* ------------------------------------------------------------------ */
/* 6. Asymmetric crypto: Ed25519 sign / verify                        */
/* ------------------------------------------------------------------ */
function generateEd25519KeyPair() {
  const { publicKey, privateKey } = crypto.generateKeyPairSync("ed25519");
  return { publicKey, privateKey };
}

function signEd25519(message: string, privateKey: crypto.KeyObject): Buffer {
  // Ed25519 does not use a separate digest algorithm.
  return crypto.sign(null, Buffer.from(message, "utf8"), privateKey);
}

function verifyEd25519(
  message: string,
  signature: Buffer,
  publicKey: crypto.KeyObject
): boolean {
  return crypto.verify(null, Buffer.from(message, "utf8"), publicKey, signature);
}

/* ------------------------------------------------------------------ */
/* 7. Constant-time comparison (avoid timing leaks)                   */
/* ------------------------------------------------------------------ */
function safeEqual(a: string, b: string): boolean {
  const ba = Buffer.from(a);
  const bb = Buffer.from(b);
  if (ba.length !== bb.length) return false;
  return crypto.timingSafeEqual(ba, bb);
}

/* ------------------------------------------------------------------ */
/* Demo                                                               */
/* ------------------------------------------------------------------ */
function main() {
  console.log("=== Hashing ===");
  console.log("SHA-256('hello'):", sha256("hello"));
  console.log("SHA-512('hello'):", sha512("hello").slice(0, 40) + "...");

  console.log("\n=== HMAC ===");
  console.log("HMAC-SHA256('secret','msg'):", hmacSha256("secret", "msg"));

  console.log("\n=== Key derivation (scrypt) ===");
  const salt = crypto.randomBytes(16);
  const key = deriveKey("correct horse battery staple", salt, 32);
  console.log("Derived key (hex):", hex(key));

  console.log("\n=== AES-256-GCM ===");
  const aesKey = crypto.randomBytes(32);
  const payload = encryptAesGcm("Top secret message!", aesKey);
  console.log("Encrypted:", payload);
  const decrypted = decryptAesGcm(payload, aesKey);
  console.log("Decrypted:", decrypted);
  // tampering check
  try {
    const tampered = { ...payload, ciphertext: payload.ciphertext };
    // flip a bit in ciphertext
    const buf = fromB64(payload.ciphertext);
    buf[0] ^= 1;
    tampered.ciphertext = b64(buf);
    decryptAesGcm(tampered, aesKey);
    console.log("Tampering NOT detected (unexpected)");
  } catch {
    console.log("Tampering detected (auth tag failed) ✓");
  }

  console.log("\n=== Password hashing ===");
  const record = hashPassword("hunter2");
  console.log("Record:", record);
  console.log("verify('hunter2'):", verifyPassword("hunter2", record));
  console.log("verify('wrong')  :", verifyPassword("wrong", record));

  console.log("\n=== Ed25519 sign / verify ===");
  const { publicKey, privateKey } = generateEd25519KeyPair();
  const msg = "I approved this transaction";
  const sig = signEd25519(msg, privateKey);
  console.log("Signature (base64):", b64(sig));
  console.log("Verify (original):", verifyEd25519(msg, sig, publicKey));
  console.log("Verify (tampered):", verifyEd25519(msg + "!", sig, publicKey));

  console.log("\n=== Constant-time compare ===");
  console.log("safeEqual('abc','abc'):", safeEqual("abc", "abc"));
  console.log("safeEqual('abc','abd'):", safeEqual("abc", "abd"));

  console.log("\nAll demos completed.");
}

main();
```

