## Final solution

Save as `indexes-exercise.ts`.

```ts
import Database from "better-sqlite3";

type DbRow = Record<string, unknown>;

const db = new Database(":memory:");

// A larger table makes index differences visible.
const ROW_COUNT = 200_000;
const USER_COUNT = 1_000;

db.exec(`
  CREATE TABLE orders (
    id INTEGER PRIMARY KEY,
    user_id INTEGER NOT NULL,
    status TEXT NOT NULL,
    created_at TEXT NOT NULL,
    amount REAL NOT NULL
  );
`);

const statuses = ["pending", "paid", "shipped", "cancelled"] as const;

// Seed without indexes first. Bulk-load-then-index is usually faster.
const seed = db.transaction(() => {
  const insert = db.prepare(`
    INSERT INTO orders (user_id, status, created_at, amount)
    VALUES (?, ?, ?, ?)
  `);

  for (let i = 0; i < ROW_COUNT; i++) {
    const createdAt = new Date(
      Date.now() - Math.floor(Math.random() * 365 * 24 * 60 * 60 * 1000)
    ).toISOString();

    insert.run(
      (i % USER_COUNT) + 1,
      statuses[i % statuses.length],
      createdAt,
      Math.round((Math.random() * 100 + 5) * 100) / 100
    );
  }
});

seed();

const cutoffDate = new Date(Date.now() - 180 * 24 * 60 * 60 * 1000).toISOString();

const sql1 = `
  SELECT id, user_id, status, created_at, amount
  FROM orders
  WHERE user_id = ? AND status = ?
  ORDER BY created_at DESC
  LIMIT 20
`;

const sql2 = `
  SELECT id, user_id, created_at, amount
  FROM orders
  WHERE status = 'pending' AND created_at < ?
  ORDER BY created_at ASC
  LIMIT 100
`;

const sql3 = `
  SELECT
    user_id,
    substr(created_at, 1, 7) AS month,
    SUM(amount) AS revenue
  FROM orders
  WHERE user_id = ?
  GROUP BY user_id, substr(created_at, 1, 7)
  ORDER BY substr(created_at, 1, 7)
`;

const q1 = db.prepare(sql1);
const q2 = db.prepare(sql2);
const q3 = db.prepare(sql3);

function showPlan(label: string, sql: string): void {
  console.log(`\n${label}`);
  const rows = db.prepare(`EXPLAIN QUERY PLAN ${sql}`).all() as DbRow[];
  for (const row of rows) {
    console.log(`  ${String(row.detail)}`);
  }
}

function measure(label: string, run: () => void, iterations = 300): void {
  const start = performance.now();

  for (let i = 0; i < iterations; i++) {
    run();
  }

  const elapsed = performance.now() - start;
  console.log(
    `${label}: ${elapsed.toFixed(2)} ms total, ` +
      `${(elapsed / iterations).toFixed(4)} ms/query`
  );
}

console.log("=== BASELINE: no secondary indexes ===");
showPlan("Q1 plan", sql1);
showPlan("Q2 plan", sql2);
showPlan("Q3 plan", sql3);

measure("Q1 baseline", () => q1.all(42, "pending"));
measure("Q2 baseline", () => q2.all(cutoffDate));
measure("Q3 baseline", () => q3.all(42));

console.log("\nCreating indexes...");
db.exec(`
  CREATE INDEX idx_orders_user_status_created
    ON orders(user_id, status, created_at DESC);

  CREATE INDEX idx_orders_status_created
    ON orders(status, created_at);

  CREATE INDEX idx_orders_user_month_amount
    ON orders(user_id, substr(created_at, 1, 7), amount);

  ANALYZE;
`);

console.log("\n=== INDEXED ===");
showPlan("Q1 plan", sql1);
showPlan("Q2 plan", sql2);
showPlan("Q3 plan", sql3);

measure("Q1 indexed", () => q1.all(42, "pending"));
measure("Q2 indexed", () => q2.all(cutoffDate));
measure("Q3 indexed", () => q3.all(42));

db.close();
```

Run it:

```bash
npx ts-node indexes-exercise.ts
```

