## 3. Domain types and repositories

`src/repositories/userRepository.ts`

```ts
import type { Db } from '../db.js';

export interface User {
  id: number;
  email: string;
  name: string;
  created_at: string;
}

export interface CreateUserInput {
  email: string;
  name: string;
}

export class UserRepository {
  private readonly insertStmt;
  private readonly findByIdStmt;
  private readonly findByEmailStmt;
  private readonly listStmt;
  private readonly updateStmt;
  private readonly deleteStmt;

  constructor(private readonly db: Db) {
    this.insertStmt = db.prepare(
      'INSERT INTO users (email, name) VALUES (@email, @name)'
    );
    this.findByIdStmt = db.prepare('SELECT * FROM users WHERE id = ?');
    this.findByEmailStmt = db.prepare('SELECT * FROM users WHERE email = ?');
    this.listStmt = db.prepare('SELECT * FROM users ORDER BY id');
    this.updateStmt = db.prepare(
      'UPDATE users SET email = @email, name = @name WHERE id = @id'
    );
    this.deleteStmt = db.prepare('DELETE FROM users WHERE id = ?');
  }

  create(input: CreateUserInput): User {
    const info = this.insertStmt.run(input);
    const user = this.findById(Number(info.lastInsertRowid));
    if (!user) throw new Error('Failed to read inserted user');
    return user;
  }

  findById(id: number): User | undefined {
    return this.findByIdStmt.get(id) as User | undefined;
  }

  findByEmail(email: string): User | undefined {
    return this.findByEmailStmt.get(email) as User | undefined;
  }

  list(): User[] {
    return this.listStmt.all() as User[];
  }

  update(id: number, input: Partial<CreateUserInput>): User {
    const current = this.findById(id);
    if (!current) throw new Error(`User ${id} not found`);

    const next = {
      id,
      email: input.email ?? current.email,
      name: input.name ?? current.name,
    };

    this.updateStmt.run(next);
    return this.findById(id)!;
  }

  delete(id: number): boolean {
    const info = this.deleteStmt.run(id);
    return info.changes > 0;
  }
}
```

`src/repositories/postRepository.ts`

```ts
import type { Db } from '../db.js';

export interface Post {
  id: number;
  user_id: number;
  title: string;
  body: string | null;
  created_at: string;
}

export interface CreatePostInput {
  user_id: number;
  title: string;
  body?: string | null;
}

export interface PostWithAuthor extends Post {
  author_name: string;
  author_email: string;
}

export class PostRepository {
  private readonly insertStmt;
  private readonly findByUserStmt;
  private readonly listWithAuthorStmt;

  constructor(private readonly db: Db) {
    this.insertStmt = db.prepare(
      'INSERT INTO posts (user_id, title, body) VALUES (@user_id, @title, @body)'
    );
    this.findByUserStmt = db.prepare(
      'SELECT * FROM posts WHERE user_id = ? ORDER BY id'
    );
    this.listWithAuthorStmt = db.prepare(`
      SELECT
        p.*,
        u.name  AS author_name,
        u.email AS author_email
      FROM posts p
      JOIN users u ON u.id = p.user_id
      ORDER BY p.id
    `);
  }

  create(input: CreatePostInput): Post {
    const info = this.insertStmt.run({
      user_id: input.user_id,
      title: input.title,
      body: input.body ?? null,
    });
    const post = this.db
      .prepare('SELECT * FROM posts WHERE id = ?')
      .get(Number(info.lastInsertRowid)) as Post | undefined;
    if (!post) throw new Error('Failed to read inserted post');
    return post;
  }

  findByUser(userId: number): Post[] {
    return this.findByUserStmt.all(userId) as Post[];
  }

  listWithAuthor(): PostWithAuthor[] {
    return this.listWithAuthorStmt.all() as PostWithAuthor[];
  }
}
```

