## 4. Transactions example

`src/services/userService.ts`

```ts
import type { Db } from '../db.js';
import { UserRepository } from '../repositories/userRepository.js';
import { PostRepository } from '../repositories/postRepository.js';

export function createUserWithPost(
  db: Db,
  userRepo: UserRepository,
  postRepo: PostRepository,
  input: { email: string; name: string; postTitle: string; postBody?: string }
) {
  // better-sqlite3 transactions are synchronous and atomic.
  const tx = db.transaction((data: typeof input) => {
    const user = userRepo.create({ email: data.email, name: data.name });
    const post = postRepo.create({
      user_id: user.id,
      title: data.postTitle,
      body: data.postBody ?? null,
    });
    return { user, post };
  });

  return tx(input);
}
```

