const bob = users.create({ email: 'bob@example.com', name: 'Bob' });
console.log('Users:', users.list());

// 2. Create a post for Alice
const post = posts.create({
  user_id: alice.id,
  title: 'Hello Database',
  body: 'This is a typed SQLite example.',
});
console.log('Post:', post);

// 3. Transactional create: user + post atomically
const { user: charlie, post: charliePost } = createUserWithPost(db, users, posts, {
  email: 'charlie@example.com',
  name: 'Charlie',
  postTitle: 'Transactional Post',
  postBody: 'Created in one transaction.',
});
console.log('Transactional user:', charlie);
console.log('Transactional post:', charliePost);

// 4. Join query
console.log('Posts with authors:', posts.listWithAuthor());

// 5. Update + delete
const updatedAlice = users.update(alice.id, { name: 'Alice A.' });
console.log('Updated user:', updatedAlice);

console.log('Delete Bob:', users.delete(bob.id));

// 6. Foreign key cascade demo: deleting Alice removes her posts
console.log('Alice posts before delete:', posts.findByUser(alice.id).length);
users.delete(alice.id);
console.log('Alice posts after delete:', posts.findByUser(alice.id).length);

db.close();
