## Syntax basics

### 1. Raw SQL with `pg` (typed with generics)

```ts
import { Pool } from "pg";

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

interface User {
  id: number;
  email: string;
  created_at: Date;
}

// Typed query helper
async function getUserById(id: number): Promise<User | null> {
  const result = await pool.query<User>(
    "SELECT id, email, created_at FROM users WHERE id = $1",
    [id]
  );
  return result.rows[0] ?? null;
}
```

Key points:
- `pool.query<T>(text, params)` types rows as `T`.
- `$1`, `$2` are parameter placeholders; never concatenate user input.
- `?? null` handles “no row found” cleanly.

### 2. Insert / update with returning

```ts
async function createUser(email: string): Promise<User> {
  const result = await pool.query<User>(
    `INSERT INTO users (email) VALUES ($1)
     RETURNING id, email, created_at`,
    [email]
  );
  return result.rows[0];
}
```

### 3. Transactions

```ts
async function transfer(fromId: number, toId: number, amount: number) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query(
      "UPDATE accounts SET balance = balance - $1 WHERE id = $2",
      [amount, fromId]
    );
    await client.query(
      "UPDATE accounts SET balance = balance + $1 WHERE id = $2",
      [amount, toId]
    );
    await client.query("COMMIT");
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}
```

### 4. Type-safe ORM example (Prisma)

```ts
// schema.prisma:
// model User { id Int @id @default(autoincrement()) email String @unique }

import { PrismaClient } from "@prisma/client";
const prisma = new PrismaClient();

async function main() {
  const user = await prisma.user.create({
    data: { email: "a@example.com" },
  });

  const users = await prisma.user.findMany({
    where: { email: { endsWith: "@example.com" } },
    select: { id: true, email: true },
  });
}
```

Prisma generates types from the schema, so `user.email` is known at compile time.

### 5. Document DB example (MongoDB + Mongoose)

```ts
import mongoose from "mongoose";

interface IUser {
  email: string;
  createdAt: Date;
}

const UserSchema = new mongoose.Schema<IUser>({
  email: { type: String, required: true, unique: true },
  createdAt: { type: Date, default: Date.now },
});

const User = mongoose.model<IUser>("User", UserSchema);

async function createUser(email: string) {
  return User.create({ email });
}
```

