### `src/logger.ts`

```ts
export type LogLevel = "debug" | "info" | "warn" | "error";

const order: Record<LogLevel, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

let threshold: LogLevel = (process.env.LOG_LEVEL as LogLevel) ?? "info";

export function setLogLevel(level: LogLevel): void {
  threshold = level;
}

export function log(level: LogLevel, message: string, meta?: unknown): void {
  if (order[level] < order[threshold]) return;

  const fn =
    level === "error" ? "error" : level === "warn" ? "warn" : "log";

  // Structured-ish output makes logs easier to filter.
  console[fn](
    JSON.stringify({
      time: new Date().toISOString(),
      level,
      message,
      meta: meta ?? null,
    })
  );
}

export const debug = (message: string, meta?: unknown) =>
  log("debug", message, meta);
export const info = (message: string, meta?: unknown) =>
  log("info", message, meta);
export const warn = (message: string, meta?: unknown) =>
  log("warn", message, meta);
export const error = (message: string, meta?: unknown) =>
  log("error", message, meta);
```

