```ts
import * as logger from "./logger";

/**
 * Deliberately contains an off-by-one bug for debugging practice:
 * sumRange(3) returns 3 instead of 6.
 */
export function sumRange(n: number): number {
  if (!Number.isInteger(n) || n < 0) {
    throw new RangeError(`sumRange expects a non-negative integer, got ${n}`);
  }

  let total = 0;
  for (let i = 1; i < n; i++) {
    // BUG: should be i <= n
    total += i;
  }
  return total;
}

export function fetchUser(id: string): Promise<{ id: string; name: string }> {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (!id) {
        reject(new Error("fetchUser: id is required"));
        return;
      }
      resolve({ id, name: `User ${id}` });
    }, 25);
  });
}

/**
 * Runtime assertion with TypeScript assertion signature.
 * After calling this, TypeScript knows `value` is not null/undefined.
 */
export function assertDefined<T>(
  value: T | null | undefined,
  message: string
): asserts value is T {
  if (value == null) {
    throw new Error(message);
  }
}

export function measure<T>(label: string, fn: () => T): T {
  const start = performance.now();
  try {
    return fn();
  } finally {
    const ms = performance.now() - start;
    logger.debug(`${label} took ${ms.toFixed(3)} ms`);
  }
}
```

### `src/index.ts`

```ts
import * as logger from "./logger";
import {
  sumRange,
  fetchUser,
  assertDefined,
  measure,
} from "./utils";

interface ProcessedUser {
  id: string;
  score: number;
}

function processUsers(ids: string[]): ProcessedUser[] {
  logger.debug("processing users", { count: ids.length });

  const result = measure("sumRange batch", () =>
    ids.map((id) => ({
      id,
      // BUG: called with 3, but sumRange(3) is currently wrong (returns 3).
      score: sumRange(3),
    }))
  );

  // Great for inspecting arrays/objects in DevTools.
  console.table(result);
  return result;
}

async function main(): Promise<void> {
  // Capture fuller stacks for async code.
  Error.stackTraceLimit = 50;

  console.time("main");

  try {
    const ids = ["alice", "bob", ""];

    // Promise.all fails fast; the empty id triggers fetchUser rejection.
    const users = await Promise.all(ids.map(fetchUser));

    // This line will not run because the promise above rejects.
    assertDefined(users[0], "first user is missing");

    const processed = processUsers(users.map((user) => user.id));
    logger.info("finished", { processedCount: processed.length });
  } catch (err) {
    if (err instanceof Error) {
      logger.error("main failed", {
        name: err.name,
        message: err.message,
        stack: err.stack,
      });

      // console.trace is useful when you need the call site, not just the error.
      console.trace("failure trace");
    } else {
      logger.error("unknown non-Error thrown", { value: err });
    }
  } finally {
    console.timeEnd("main");
  }

  // Explicit breakpoint: pauses when an inspector is attached.
  const answer = 42;
  debugger;
  logger.info("debugger statement reached", { answer });
}

main().catch((err) => {
  console.error("unhandled main error", err);
  process.exitCode = 1;
});
```

