### Summary checklist

| Pattern | Must handle |
|---|---|
| Singleton | bypass via `any`, subclassing, module caching, test reset |
| Factory | exhaustiveness, async errors, return-type narrowing |
| Builder | required fields, fluent `this`, mutation |
| Observer | leaks, mutation during emit, listener errors, `this` binding |
| Strategy | `this`, function vs class, exhaustive selection |
| Decorator (wrapper) | `instanceof`, forwarding, interface drift |
| Proxy | `this` via receiver, revocation, function traps |
| Command | undo state, async partial failure, history memory |
| Cross-cutting | strict null, `private` vs `#`, class fields, variance, decorators |

If you want, I can expand any single pattern into a full production-ready module with tests.

Below is a complete, runnable TypeScript example. It shows:

1. **TypeScript “dictionary” styles**: index signatures, `Record`, and `Map`.
2. A **from-scratch generic `HashMap<K, V>`** with:
   - pluggable hashing/equality,
   - default hashing for strings, numbers, booleans, symbols, and object identity,
   - separate chaining for collisions,
   - automatic resizing at a configurable load factor,
   - iterators and `forEach`.

You can run it with `ts-node`, `bun`, `deno`, or compile with `tsc`.

```ts
// hashmap.ts

/* -------------------------------------------------------------------------- */
/*  Built-in TypeScript dictionary styles (for reference)                      */
/* -------------------------------------------------------------------------- */

// 1. Index signature dictionary
type StringNumberDict = { [key: string]: number };
const counts: StringNumberDict = {};
counts.apple = 3;
counts.banana = 5;

// 2. Record utility type
type User = { id: number; name: string };
const usersById: Record<number, User> = {};
usersById[42] = { id: 42, name: "Ada" };

// 3. Built-in Map (most flexible, preserves insertion order)
const map = new Map<string, number>();
map.set("a", 1);
map.set("b", 2);

/* -------------------------------------------------------------------------- */
/*  Custom hash map implementation                                            */
/* -------------------------------------------------------------------------- */

type HashFn<K> = (key: K) => number;
type EqualsFn<K> = (a: K, b: K) => boolean;

interface Entry<K, V> {
  key: K;
  value: V;
  hash: number;
}

// Object identity hash cache. This lets object keys work by reference.
const objectIdCache = new WeakMap<object, number>();
let nextObjectId = 1;

function identityHash(obj: object): number {
  let id = objectIdCache.get(obj);
  if (id === undefined) {
    id = nextObjectId++;
    objectIdCache.set(obj, id);
  }
  return id;
}

function djb2(str: string): number {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash + str.charCodeAt(i)) >>> 0;
  }
  return hash >>> 0;
}

function mixNumber(n: number): number {
  // Handle NaN, Infinity, and normal numbers reasonably.
  if (Number.isNaN(n)) return 0x9e3779b9;
  if (!Number.isFinite(n)) return n > 0 ? 0x7fffffff : 0x80000000;
  // SplitMix-like mixing for finite numbers.
  let x = Math.trunc(n * 2654435761) >>> 0;
  x ^= x >>> 16;
  x = Math.imul(x, 0x85ebca6b) >>> 0;
  x ^= x >>> 13;
  x = Math.imul(x, 0xc2b2ae35) >>> 0;
  x ^= x >>> 16;
  return x >>> 0;
}

function defaultHash<K>(key: K): number {
  switch (typeof key) {
    case "string":
      return djb2(key);
    case "number":
      return mixNumber(key);
    case "boolean":
      return key ? 1 : 0;
    case "bigint":
      return mixNumber(Number(key % (2n ** 53n - 1n)));
    case "symbol":
      return djb2(key.toString());
    case "undefined":
      return 0;
    case "function":
      return identityHash(key as object);
    case "object":
      if (key === null) return 0;
      return identityHash(key as object);
    default:
      return djb2(String(key));
  }
}

function defaultEquals<K>(a: K, b: K): boolean {
  if (Number.isNaN(a as unknown) && Number.isNaN(b as unknown)) return true;
  return a === b;
}

export class HashMap<K, V> implements Iterable<[K, V]> {
  private buckets: (Entry<K, V>[] | undefined)[];
  private _size = 0;

  private readonly loadFactor: number;
  private readonly hashFn: HashFn<K>;
  private readonly equalsFn: EqualsFn<K>;

  constructor(
    initialCapacity = 16,
    loadFactor = 0.75,
    hashFn: HashFn<K> = defaultHash,
    equalsFn: EqualsFn<K> = defaultEquals
  ) {
    if (initialCapacity < 1) throw new RangeError("initialCapacity must be >= 1");
    if (loadFactor <= 0 || loadFactor >= 1) {
      throw new RangeError("loadFactor must be between 0 and 1 (exclusive)");
    }
    // Power of two capacity makes masking cheap.
    let capacity = 1;
    while (capacity < initialCapacity) capacity <<= 1;

    this.buckets = new Array(capacity);
    this.loadFactor = loadFactor;
    this.hashFn = hashFn;
    this.equalsFn = equalsFn;
  }

  get size(): number {
    return this._size;
  }

  get capacity(): number {
    return this.buckets.length;
  }

  private indexFor(hash: number): number {
    return hash & (this.buckets.length - 1);
  }

  set(key: K, value: V): this {
    const hash = this.hashFn(key) >>> 0;
    const idx = this.indexFor(hash);
    let bucket = this.buckets[idx];

    if (!bucket) {
      bucket = [];
      this.buckets[idx] = bucket;
    }

    for (const entry of bucket) {
      if (entry.hash === hash && this.equalsFn(entry.key, key)) {
        entry.value = value;
        return this;
      }
    }

    bucket.push({ key, value, hash });
    this._size++;

    if (this._size / this.buckets.length > this.loadFactor) {
      this.resize(this.buckets.length * 2);
    }

    return this;
  }

  get(key: K): V | undefined {
    const hash = this.hashFn(key) >>> 0;
    const idx = this.indexFor(hash);
    const bucket = this.buckets[idx];
    if (!bucket) return undefined;

    for (const entry of bucket) {
      if (entry.hash === hash && this.equalsFn(entry.key, key)) {
        return entry.value;
      }
    }
    return undefined;
  }

  has(key: K): boolean {
    const hash = this.hashFn(key) >>> 0;
    const idx = this.indexFor(hash);
    const bucket = this.buckets[idx];
    if (!bucket) return false;

    return bucket.some(
      (entry) => entry.hash === hash && this.equalsFn(entry.key, key)
    );
  }

  delete(key: K): boolean {
    const hash = this.hashFn(key) >>> 0;
    const idx = this.indexFor(hash);
    const bucket = this.buckets[idx];
    if (!bucket) return false;

    const pos = bucket.findIndex(
      (entry) => entry.hash === hash && this.equalsFn(entry.key, key)
    );

    if (pos === -1) return false;

    bucket.splice(pos, 1);
    this._size--;

    if (bucket.length === 0) {
      this.buckets[idx] = undefined;
    }

    return true;
  }

  clear(): void {
    this.buckets = new Array(this.buckets.length);
    this._size = 0;
  }

  private resize(newCapacity: number): void {
    const oldBuckets = this.buckets;
    this.buckets = new Array(newCapacity);
    this._size = 0;

    for (const bucket of oldBuckets) {
      if (!bucket) continue;
      for (const entry of bucket) {
        // Re-insert; this recomputes the bucket index for the new capacity.
        this.set(entry.key, entry.value);
      }
    }
  }

  *entries(): IterableIterator<[K, V]> {
    for (const bucket of this.buckets) {
      if (!bucket) continue;
      for (const entry of bucket) {
        yield [entry.key, entry.value];
      }
    }
  }

  *keys(): IterableIterator<K> {
    for (const [key] of this.entries()) yield key;
  }

  *values(): IterableIterator<V> {
    for (const [, value] of this.entries()) yield value;
  }

  [Symbol.iterator](): IterableIterator<[K, V]> {
    return this.entries();
  }

  forEach(callback: (value: V, key: K, map: this) => void, thisArg?: unknown): void {
    for (const [key, value] of this.entries()) {
      callback.call(thisArg, value, key, this);
    }
  }

  toArray(): [K, V][] {
    return [...this.entries()];
  }
}

/* -------------------------------------------------------------------------- */
/*  Demonstration and lightweight tests                                        */
/* -------------------------------------------------------------------------- */

function assert(condition: boolean, message: string): void {
  if (!condition) {
    console.error("FAIL:", message);
    throw new Error(message);
  }
  console.log("PASS:", message);
}

function main(): void {
  console.log("\n=== Basic string keys ===");
  const hm = new HashMap<string, number>();
  hm.set("one", 1).set("two", 2).set("three", 3);

  assert(hm.get("one") === 1, "get existing key");
  assert(hm.get("missing") === undefined, "get missing key");
  assert(hm.has("two"), "has existing key");
  assert(!hm.has("missing"), "has missing key");
  assert(hm.size === 3, "size after inserts");
  assert(hm.delete("two"), "delete existing key");
  assert(!hm.delete("two"), "delete missing key");
  assert(hm.size === 2, "size after delete");
  assert([...hm.keys()].sort().join(",") === "one,three", "keys iterator");

  console.log("\n=== Update existing key ===");
  hm.set("one", 100);
  assert(hm.get("one") === 100, "updated value");
  assert(hm.size === 2, "size unchanged on update");

  console.log("\n=== Number keys ===");
  const nums = new HashMap<number, string>();
  nums.set(NaN, "not a number");
  nums.set(1, "one");
  nums.set(2, "two");
  assert(nums.get(NaN) === "not a number", "NaN key equality");
  assert(nums.size === 3, "number key size");

  console.log("\n=== Object identity keys ===");
  const objMap = new HashMap<object, string>();
  const a = { id: 1 };
  const b = { id: 1 }; // Different object, same contents.

  objMap.set(a, "first");
  objMap.set(b, "second");

  assert(objMap.get(a) === "first", "first object key");
  assert(objMap.get(b) === "second", "second object key");
  assert(objMap.size === 2, "distinct object keys");

  console.log("\n=== Custom key type with custom hash/equals ===");
  type Point = { x: number; y: number };
  const points = new HashMap<Point, string>(
    8,
    0.75,
    (p) => djb2(`${p.x},${p.y}`),
    (a, b) => a.x === b.x && a.y === b.y
  );

  points.set({ x: 1, y: 2 }, "A");
  points.set({ x: 1, y: 2 }, "B"); // Same logical key, should update.
  points.set({ x: 3, y: 4 }, "C");

  assert(points.get({ x: 1, y: 2 }) === "B", "value semantics for Point key");
  assert(points.size === 2, "Point key size");

  console.log("\n=== Resizing stress test ===");
  const big = new HashMap<number, number>(4, 0.75);
  const n = 10_000;
  for (let i = 0; i < n; i++) big.set(i, i * 2);
  assert(big.size === n, "large insert size");
  assert(big.get(9999) === 19998, "large insert lookup");
  assert(big.get(-1) === undefined, "missing large key");

  console.log("\n=== Iteration ===");
  const small = new HashMap<string, number>();
  small.set("x", 10);
  small.set("y", 20);
  const collected = [...small.entries()]
    .map(([k, v]) => `${k}=${v}`)
    .sort()
    .join(", ");
  console.log("Entries:", collected);

  console.log("\n=== forEach ===");
  small.forEach((value, key) => {
    console.log(`  ${key} -> ${value}`);
  });

  console.log("\nAll demonstrations completed.");
}

main();
```

### Why this design works

- **Power-of-two capacity + bitmasking**: `hash & (capacity - 1)` is fast and keeps bucket distribution simple.
- **Separate chaining**: each bucket is an array of entries. Collisions are handled by scanning the bucket.
- **Load factor resizing**: when `size / capacity > loadFactor`, capacity doubles and all entries are rehashed. This keeps average lookup time close to **O(1)**.
- **Pluggable hashing/equality**: built-in types have sensible defaults, while custom key types (like `Point`) can provide value-based hashing and equality.
- **Object keys by identity**: a `WeakMap` assigns each object a unique numeric id without preventing garbage collection.

### Complexity

| Operation | Average | Worst case |
|-----------|---------|------------|
| `set`     | O(1)    | O(n)       |
| `get`     | O(1)    | O(n)       |
| `has`     | O(1)    | O(n)       |
| `delete`  | O(1)    | O(n)       |
| `resize`  | O(n)    | O(n)       |

Worst-case O(n) happens when many keys collide into the same bucket, which good hash functions and resizing make unlikely.

### When to use which approach

- Use **`Record<K, V>`** or index signatures for simple JSON-like dictionaries with string keys.
- Use **`Map<K, V>`** for most production code: it is highly optimized, preserves insertion order, and supports any key type.
- Use a **custom `HashMap`** when you need specialized behavior such as custom hash functions, immutable snapshots, persistent data structures, or educational/control purposes.

In TypeScript/JavaScript, a “dictionary” or “hash map” is an associative collection of **key → value** pairs. At the engine level, objects and `Map` are both hash-map-like structures; TypeScript mainly adds static types on top.

## 1. The idea

- You look up values by **key** (usually a string or symbol for objects; any value for `Map`).
- Average-case lookup/insert/delete is **O(1)**.
- Keys must be unique; a new value overwrites the old one for the same key.
- Think of it as a phone book: name (key) → phone number (value).

## 2. Syntax

### A. Plain object (most common)

```ts
// Index signature
interface Scores {
  [player: string]: number;
}

const scores: Scores = {};
scores["alice"] = 10;
scores["bob"] = 7;

// Or Record utility type
const counts: Record<string, number> = {};
counts["apple"] = 3;
```

### B. `Map<K, V>` (ES2015+)

```ts
const m = new Map<string, number>();
m.set("alice", 10);
m.set("bob", 7);

console.log(m.get("alice")); // 10
console.log(m.has("bob"));   // true
m.delete("bob");
```

### C. `WeakMap` (keys must be objects; GC-friendly)

```ts
const cache = new WeakMap<object, string>();
const key = { id: 1 };
cache.set(key, "cached value");
```

## 3. Common differences (object vs. `Map`)

| Feature | Plain object | `Map` |
|---|---|---|
| Key types | string / symbol | any value |
| Prototype keys | can collide (`toString`) | none |
| Iteration order | string keys sorted-ish | insertion order |
| Size | `Object.keys(obj).length` | `map.size` |
| Performance for frequent add/remove | okay | better |

## 4. Typical use cases

### Frequency counting

```ts
function countWords(text: string): Record<string, number> {
  const out: Record<string, number> = {};
  for (const w of text.split(/\s+/)) {
    out[w] = (out[w] ?? 0) + 1;
  }
  return out;
}
```

### Memoization / cache

```ts
const memo = new Map<number, number>();
function fib(n: number): number {
  if (n < 2) return n;
  if (memo.has(n)) return memo.get(n)!;
  const v = fib(n - 1) + fib(n - 2);
  memo.set(n, v);
  return v;
}
```

### Grouping

```ts
type User = { id: number; role: string };
const byRole = new Map<string, User[]>();
for (const u of users) {
  const arr = byRole.get(u.role) ?? [];
  arr.push(u);
  byRole.set(u.role, arr);
}
```

### Lookup table

```ts
const httpStatus: Record<number, string> = {
  200: "OK",
  404: "Not Found",
  500: "Server Error",
};
```

## 5. Practical tips

- Prefer **`Record<K, V>`** or index signatures for simple string-keyed dictionaries.
- Prefer **`Map`** when keys are not strings, when you need guaranteed insertion order, or when you frequently add/remove entries.
- Avoid `obj[key]` collisions with inherited properties; use `Object.create(null)` or `Map` if needed.
- In TS, mark optional/possibly-undefined values carefully: use `??` or `?.`.

```ts
const dict: Record<string, number> = {};
const v = dict["missing"]; // number | undefined at runtime; TS may say number
const safe = dict["missing"] ?? 0;
```

If you want, I can also show a small custom hash-map implementation in TypeScript for learning purposes.

## Typical mistake

```ts
type Counts = { [key: string]: number };

const counts: Counts = {};

function increment(key: string): void {
  // BUG 1: a stored value of 0 is treated as "missing"
  if (counts[key]) {
    counts[key] = counts[key] + 1;
  } else {
    counts[key] = 1;
  }
}

function exists(key: string): boolean {
  // BUG 2: `in` also matches inherited properties
  return key in counts;
}

increment("a");
increment("a");
increment("toString");   // inherited property name
console.log(counts);      // { a: 2, toString: NaN }
console.log(exists("constructor")); // true, even though never added
```

### What went wrong

1. **Falsy zero** – `if (counts[key])` cannot distinguish “key not present” from “value is `0`”. Any counter that legitimately reaches `0` is then reset to `1`.
2. **Prototype pollution / inherited keys** – A plain `{}` inherits from `Object.prototype`. Keys such as `"toString"`, `"constructor"`, and `"hasOwnProperty"` already “exist” via `in`, and reading/writing them can shadow or corrupt inherited methods.
3. **Key coercion** – Object keys are always strings (or symbols). A key like `1` becomes `"1"`, so `counts[1]` and `counts["1"]` collide. This is subtle in numeric-heavy code.
4. **No real “has” semantics** – `key in obj` checks the prototype chain, not just own properties.

## Corrected version

Using `Map` is the idiomatic fix for an arbitrary dictionary in TypeScript:

```ts
const counts = new Map<string, number>();

function increment(key: string): void {
  counts.set(key, (counts.get(key) ?? 0) + 1);
}

function exists(key: string): boolean {
  return counts.has(key);
}

increment("a");
increment("a");
increment("toString");

console.log(counts.get("a"));        // 2
console.log(counts.get("toString")); // 1
console.log(exists("constructor"));  // false
```

### Why this is better

- **`Map.has` / `Map.get`** distinguish “missing” from `0` (or `undefined`, `null`, etc.).
- **No prototype chain** – arbitrary strings like `"toString"` or `"__proto__"` are ordinary keys.
- **Any key type** – `Map<number, ...>`, `Map<object, ...>`, etc., without string coercion collisions.
- **Predictable iteration** – `Map` preserves insertion order and exposes `.keys()`, `.values()`, `.entries()`.
- **TypeScript ergonomics** – `Map<K, V>` gives precise `get: (key: K) => V | undefined`, unlike index signatures that often force `undefined` checks manually.

### Alternative: null-prototype object

If you must use a plain object (e.g., for JSON serialization), create it without a prototype and guard existence with `Object.prototype.hasOwnProperty.call`:

```ts
const counts: Record<string, number> = Object.create(null);

function increment(key: string): void {
  const current = Object.prototype.hasOwnProperty.call(counts, key)
    ? counts[key]
    : 0;
  counts[key] = current + 1;
}

function exists(key: string): boolean {
  return Object.prototype.hasOwnProperty.call(counts, key);
}
```

This avoids prototype keys, but `Map` remains the safer and more expressive choice for in-memory dictionaries.

# Common pitfalls with dictionaries / hash maps in TypeScript

Below are the most common pitfalls, each with a short explanation and idiomatic code. Examples assume `strict: true` (and often `noUncheckedIndexedAccess: true`, which is highly recommended for dictionary work).

---

## 1. Index signatures lie about `undefined`

```ts
type Dict = { [key: string]: number };

const d: Dict = {};
const x = d.missing; // type: number, but actually undefined at runtime
```

**Fix:** enable `noUncheckedIndexedAccess`, or model the value as `number | undefined`.

```ts
type Dict = { [key: string]: number | undefined };
const d: Dict = {};
const x = d.missing; // number | undefined
if (x !== undefined) console.log(x + 1);
```

---

## 2. `Record<K, V>` vs. index signature

`Record` is great for *exhaustive* finite key sets; an index signature is for open-ended maps. Mixing them causes confusion.

```ts
type Status = "idle" | "loading" | "done";

// Exhaustive: compiler ensures all keys exist
const labels: Record<Status, string> = {
  idle: "Idle",
  loading: "Loading",
  done: "Done",
  // error if missing a key
};

// Open-ended: keys unknown at compile time
type Counts = Record<string, number>; // same as index signature
```

**Pitfall:** `Record<string, V>` still allows arbitrary keys and (without `noUncheckedIndexedAccess`) returns `V` for missing keys.

---

## 3. Number keys are coerced to strings

```ts
const obj: Record<number, string> = {};
obj[1] = "one";
obj["1"] = "ONE";
console.log(Object.keys(obj)); // ["1"] — only one entry!
```

**Fix:** use a `Map<number, string>` when keys are not strings.

```ts
const m = new Map<number, string>();
m.set(1, "one");
m.set(1.0, "ONE"); // overwrites — Map uses SameValueZero
```

---

## 4. Inherited / prototype keys

Plain objects inherit from `Object.prototype`, so `"toString" in obj` is `true` even if you never set it.

```ts
const d: Record<string, number> = {};
console.log("toString" in d);        // true (inherited)
console.log(d.toString);             // function
```

**Fix:** use `Object.create(null)` for a “pure” dictionary, or `Map`.

```ts
const pure = Object.create(null) as Record<string, number>;
console.log("toString" in pure); // false

// Or check own property
console.log(Object.hasOwn(d, "toString")); // false (modern)
// console.log(Object.prototype.hasOwnProperty.call(d, "toString"));
```

---

## 5. `for...in` walks inherited enumerable keys

```ts
const d = { a: 1 };
Object.prototype.z = 999 as any; // don't do this, but libraries might
for (const k in d) console.log(k); // "a", "z"
delete (Object.prototype as any).z;
```

**Fix:** use `Object.keys`, `Object.entries`, or `Object.getOwnPropertyNames`.

```ts
for (const [k, v] of Object.entries(d)) console.log(k, v);
```

---

## 6. Existence checks vs. `undefined` values

If a value can legitimately be `undefined`, `if (d.key)` and `d.key !== undefined` both fail to distinguish “missing” from “present-but-undefined”.

```ts
const d: Record<string, number | undefined> = { a: undefined };
console.log(d.a !== undefined); // false, but key exists
console.log("a" in d);          // true
console.log(Object.hasOwn(d, "a")); // true
```

**Fix:** use `Object.hasOwn` / `hasOwnProperty` for existence; use a sentinel or `Map` if you need “present with undefined value”.

---

## 7. Object keys are always strings/symbols

You cannot use objects, arrays, or dates as keys in a plain object — they get stringified (`"[object Object]"`).

```ts
const d: any = {};
const key = { id: 1 };
d[key] = "value";
console.log(d["[object Object]"]); // "value"
console.log(Object.keys(d));        // ["[object Object]"]
```

**Fix:** use `Map` (or `WeakMap`) for non-string keys.

```ts
const m = new Map<object, string>();
const key = { id: 1 };
m.set(key, "value");
console.log(m.get(key)); // "value"
```

---

## 8. `Map` vs. plain object confusion

- `Map` preserves insertion order, allows any key type, has `.size`, is iterable.
- Plain objects are better for JSON, static shapes, and small fixed sets.

```ts
const m = new Map<string, number>();
m.set("a", 1);
console.log(m.size);        // 1
console.log(m.get("a"));    // 1
console.log(JSON.stringify(m)); // "{}"  ← pitfall!
```

**Fix:** convert before serializing.

```ts
const obj = Object.fromEntries(m); // { a: 1 }
const back = new Map(Object.entries(obj));
```

---

## 9. Mutating while iterating

Deleting/adding keys during `for...of` over a `Map` or `Object.entries` can skip entries or behave unpredictably.

```ts
const m = new Map([["a", 1], ["b", 2], ["c", 3]]);
for (const [k] of m) {
  if (k === "b") m.delete(k); // may skip "c" in some engines
}
```

**Fix:** collect keys first.

```ts
for (const k of [...m.keys()]) {
  if (k === "b") m.delete(k);
}
```

---

## 10. Shallow copy / shared references

Spread copies only the top level; nested objects are shared.

```ts
const original = { nested: { x: 1 } };
const copy = { ...original };
copy.nested.x = 99;
console.log(original.nested.x); // 99
```

**Fix:** deep clone when needed (or restructure).

```ts
const copy = structuredClone(original); // modern
// or: JSON.parse(JSON.stringify(original)) (loses Map/Date/etc.)
```

---

## 11. `Object.keys` returns `string[]`, not `keyof T`

Even for a typed object, `Object.keys` is typed as `string[]`, so indexing back into the object needs a cast.

```ts
const d = { a: 1, b: 2 } as const;
const keys = Object.keys(d); // string[]
// const v = d[keys[0]];    // error: Element implicitly has any type
const v = d[keys[0] as keyof typeof d];
```

**Fix:** a typed helper or `satisfies`.

```ts
function keysOf<T extends object>(o: T): (keyof T)[] {
  return Object.keys(o) as (keyof T)[];
}
```

---

## 12. `delete` and type safety

With a typed dictionary, `delete obj.key` may be flagged, and deleted keys still appear in the type.

```ts
const d: Record<string, number> = { a: 1 };
delete d.a; // ok at runtime, but type still claims number
console.log(d.a); // undefined at runtime, type says number
```

**Fix:** model values as optional or use `Map` (`.delete` is first-class).

```ts
type D = Record<string, number | undefined>;
const d: D = { a: 1 };
delete d.a; // or d.a = undefined
```

---

## 13. Enum keys in dictionaries

String enums work okay, but numeric enums produce reverse mappings and surprising keys.

```ts
enum E { A, B }
const d: Partial<Record<E, string>> = {};
d[E.A] = "x";
console.log(Object.keys(d)); // ["0"] (numeric enum)
```

**Fix:** prefer string enums or `as const` objects.

```ts
const E = { A: "A", B: "B" } as const;
type E = typeof E[keyof typeof E];
```

---

## 14. `Map` equality and object keys

`Map` uses `SameValueZero` (like `===`, but `NaN === NaN`). Two distinct objects are never equal even if structurally identical.

```ts
const m = new Map<object, number>();
m.set({ id: 1 }, 10);
console.log(m.get({ id: 1 })); // undefined
```

**Fix:** key by a primitive id, or use a `WeakMap` with the object as key consistently.

```ts
const m = new Map<number, number>();
m.set(1, 10);
console.log(m.get(1)); // 10
```

---

## 15. `WeakMap` / `WeakSet` constraints

Keys must be objects (not primitives); they are not iterable and have no `.size`.

```ts
const wm = new WeakMap<object, number>();
// wm.set(1, 2); // error: Argument of type 'number' is not assignable to 'object'
```

**Use case:** attach metadata to objects without preventing GC. Don't use it as a general dictionary.

---

## 16. Mutating a frozen/sealed object

```ts
const d = Object.freeze({ a: 1 });
// d.b = 2; // runtime throws in strict mode; TS may not catch depending on type
```

**Fix:** type as `Readonly<...>` and use `Map`/new object for mutations.

---

## 17. Performance: large plain objects vs `Map`

For frequent add/remove of many keys, `Map` is generally faster and has predictable performance; plain objects can deoptimize (hidden class transitions) and have prototype overhead.

```ts
// Hot path with many dynamic keys:
const cache = new Map<string, Expensive>();
cache.set(key, value);
cache.delete(key);
```

---

## 18. Spreading `undefined` / conditional entries

```ts
const extra: { b?: number } = {};
const d = { a: 1, ...extra }; // fine
// But: ...undefined is allowed; ...null throws
const d2 = { a: 1, ...(null as any) }; // runtime error
```

**Fix:** guard with `?? {}`.

```ts
const d3 = { a: 1, ...(extra ?? {}) };
```

---

## Quick decision guide

| Need | Use |
|---|---|
| Fixed/known keys, JSON-friendly | `Record` / interface |
| Open-ended string keys, small | plain object + `noUncheckedIndexedAccess` |
| Non-string keys, frequent mutation, size/iteration | `Map` |
| Attach data to objects, avoid GC leaks | `WeakMap` |
| Need “pure” dict without prototype | `Object.create(null)` |

## Recommended tsconfig

```json
{
  "compilerOptions": {
    "strict": true,
    "noUncheckedIndexedAccess": true,
    "exactOptionalPropertyTypes": true
  }
}
```

These flags turn many of the above from silent runtime bugs into compile-time errors.

## Exercise

**Task:** You have an array of `Product` objects. Build a function that:

1. Groups products by `category`.
2. For each category, computes the **total price** and **count** of products.
3. Returns a dictionary keyed by category name, where each value is `{ total, count, average }`.
4. Also returns the category with the highest total (the “best seller”).

Use a `Map` (or `Record`) as the hash map, and make everything fully typed.

---

## Step-by-step solution

### Step 1 — Define the types

We want the input and output shapes explicit so TypeScript can catch mistakes.

```ts
type Product = {
  id: string;
  name: string;
  category: string;
  price: number;
};

type CategoryStats = {
  total: number;
  count: number;
  average: number;
};

type AggregationResult = {
  stats: Record<string, CategoryStats>; // dictionary: category -> stats
  bestSeller: string | null;           // category with highest total
};
```

### Step 2 — Choose the hash map

A `Map<string, CategoryStats>` is ideal when keys are dynamic strings and you want O(1) lookups/inserts. We can convert it to a plain object (`Record`) at the end for a JSON-friendly result.

### Step 3 — Accumulate in one pass

Iterate once over the products. For each product, update (or create) the entry for its category. This is O(n) overall.

### Step 4 — Compute the best seller

After accumulation, scan the map entries to find the maximum `total`.

### Step 5 — Convert and return

Turn the `Map` into a `Record` and return both pieces.

---

## Final solution

```ts
type Product = {
  id: string;
  name: string;
  category: string;
  price: number;
};

type CategoryStats = {
  total: number;
  count: number;
  average: number;
};

type AggregationResult = {
  stats: Record<string, CategoryStats>;
  bestSeller: string | null;
};

function aggregateByCategory(products: Product[]): AggregationResult {
  // Hash map: category -> mutable accumulator
  const map = new Map<string, { total: number; count: number }>();

  for (const p of products) {
    const current = map.get(p.category);
    if (current) {
      current.total += p.price;
      current.count += 1;
    } else {
      map.set(p.category, { total: p.price, count: 1 });
    }
  }

  // Build the final dictionary with computed averages
  const stats: Record<string, CategoryStats> = {};
  let bestSeller: string | null = null;
  let bestTotal = -Infinity;

  for (const [category, { total, count }] of map) {
    const average = count === 0 ? 0 : total / count;
    stats[category] = { total, count, average };

    if (total > bestTotal) {
      bestTotal = total;
      bestSeller = category;
    }
  }

  return { stats, bestSeller };
}

// ---- Demo ----
const products: Product[] = [
  { id: "1", name: "Laptop",   category: "Electronics", price: 1200 },
  { id: "2", name: "Phone",    category: "Electronics", price: 800 },
  { id: "3", name: "Shirt",    category: "Clothing",    price: 40 },
  { id: "4", name: "Jeans",    category: "Clothing",    price: 60 },
  { id: "5", name: "Apple",    category: "Food",        price: 2 },
];

const result = aggregateByCategory(products);
console.log(JSON.stringify(result, null, 2));
```

### Expected output

```json
{
  "stats": {
    "Electronics": { "total": 2000, "count": 2, "average": 1000 },
    "Clothing":    { "total": 100,  "count": 2, "average": 50 },
    "Food":        { "total": 2,    "count": 1, "average": 2 }
  },
  "bestSeller": "Electronics"
}
```

### Key takeaways

- **`Map`** gives O(1) average insert/lookup and preserves insertion order.
- **One pass** for accumulation keeps it O(n).
- **Separate accumulation (`total`, `count`) from derived values (`average`)** avoids recomputing and keeps the hash map values simple.
- Converting to `Record<string, CategoryStats>` at the end makes the result easy to serialize or pass to UI/API code.

## Dictionaries / Hash Maps in TypeScript

A **dictionary** (map) is an associative container that stores **key → value** pairs and lets you look up a value by its key. In TypeScript, the closest built-in is `Map<K, V>` (plus `Record`/index signatures for plain objects).

A **hash map** is the usual implementation of a dictionary:

1. **Hash function** maps a key to an integer index.
2. **Bucket array** stores entries at that index.
3. **Collision handling** deals with two keys mapping to the same index (separate chaining or open addressing).
4. **Load factor** (`size / capacity`) triggers **rehashing** (growing the bucket array) to keep average time **O(1)**.

### Complexity

| Operation | Average | Worst |
|-----------|---------|-------|
| `get`     | O(1)    | O(n)  |
| `set`     | O(1)    | O(n)  |
| `delete`  | O(1)    | O(n)  |

Worst case happens when many keys collide into the same bucket.

### TypeScript notes

- Prefer `Map<K, V>` over `{ [k: string]: V }` when keys are not strings, insertion order matters, or you need `.size`.
- Generic constraints help: `K` must be hashable/equatable. For primitives, identity/equality is easy; for objects, you usually hash by reference or provide a custom hash.
- Always separate **hashing** from **equality**; two keys must have the same hash to be equal, but equal keys must have the same hash.

---

## Implementation: Generic Hash Map (Separate Chaining)

```ts
// A small, dependency-free hash map using separate chaining.
// Generic over key type K and value type V.

type HashFn<K> = (key: K) => number;
type EqualsFn<K> = (a: K, b: K) => boolean;

// ---- default helpers -------------------------------------------------------

// djb2 string hash: fast, decent distribution for typical keys.
function djb2(str: string): number {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    // hash = hash * 33 + charCode
    hash = ((hash << 5) + hash + str.charCodeAt(i)) >>> 0;
  }
  return hash;
}

// Identity-based hashing for objects: assigns a stable numeric id per object.
const objectIdMap = new WeakMap<object, number>();
let nextObjectId = 1;

function defaultHash<K>(key: K): number {
  if (typeof key === "string") return djb2(key);
  if (typeof key === "number") {
    // Mix bits so nearby numbers don't all land in the same bucket.
    return (Math.trunc(key) * 2654435761) >>> 0;
  }
  if (typeof key === "boolean") return key ? 1 : 0;
  if (typeof key === "symbol") return djb2(key.toString());
  if (typeof key === "bigint") return Number(key % BigInt(2 ** 32));
  // Objects / arrays / functions: hash by reference identity.
  if (key !== null && typeof key === "object") {
    let id = objectIdMap.get(key as object);
    if (id === undefined) {
      id = nextObjectId++;
      objectIdMap.set(key as object, id);
    }
    return id;
  }
  // Fallback for null / undefined / other.
  return djb2(String(key));
}

function defaultEquals<K>(a: K, b: K): boolean {
  return Object.is(a, b);
}

// ---- HashMap class ---------------------------------------------------------

interface Entry<K, V> {
  key: K;
  value: V;
}

export class HashMap<K, V> {
  private buckets: Array<Array<Entry<K, V>>>;
  private _size = 0;
  private capacity: number;
  private readonly hashFn: HashFn<K>;
  private readonly equalsFn: EqualsFn<K>;

  // Load factor threshold: resize when exceeded.
  private static readonly LOAD_FACTOR = 0.75;

  constructor(
    initialCapacity = 16,
    hashFn: HashFn<K> = defaultHash,
    equalsFn: EqualsFn<K> = defaultEquals
  ) {
    if (initialCapacity < 1) throw new RangeError("capacity must be >= 1");
    this.capacity = initialCapacity;
    this.buckets = Array.from({ length: this.capacity }, () => []);
    this.hashFn = hashFn;
    this.equalsFn = equalsFn;
  }

  get size(): number {
    return this._size;
  }

  // ---- core operations ----------------------------------------------------

  set(key: K, value: V): this {
    const idx = this.bucketIndex(key);
    const bucket = this.buckets[idx];

    // Update existing entry if key already present.
    for (const entry of bucket) {
      if (this.equalsFn(entry.key, key)) {
        entry.value = value;
        return this;
      }
    }

    // Otherwise append a new entry (chaining on collision).
    bucket.push({ key, value });
    this._size++;

    // Resize if load factor exceeded.
    if (this._size / this.capacity > HashMap.LOAD_FACTOR) {
      this.resize(this.capacity * 2);
    }
    return this;
  }

  get(key: K): V | undefined {
    const bucket = this.buckets[this.bucketIndex(key)];
    for (const entry of bucket) {
      if (this.equalsFn(entry.key, key)) return entry.value;
    }
    return undefined;
  }

  has(key: K): boolean {
    return this.get(key) !== undefined && this.containsKey(key);
  }

  // has() above is tricky with undefined values; provide a safe contains check.
  private containsKey(key: K): boolean {
    const bucket = this.buckets[this.bucketIndex(key)];
    return bucket.some((e) => this.equalsFn(e.key, key));
  }

  delete(key: K): boolean {
    const idx = this.bucketIndex(key);
    const bucket = this.buckets[idx];
    const pos = bucket.findIndex((e) => this.equalsFn(e.key, key));
    if (pos === -1) return false;
    bucket.splice(pos, 1);
    this._size--;
    return true;
  }

  clear(): void {
    this.buckets = Array.from({ length: this.capacity }, () => []);
    this._size = 0;
  }

  // ---- iteration ---------------------------------------------------------

  *entries(): IterableIterator<[K, V]> {
    for (const bucket of this.buckets) {
      for (const { key, value } of bucket) {
        yield [key, value];
      }
    }
  }

  *keys(): IterableIterator<K> {
    for (const [k] of this.entries()) yield k;
  }

  *values(): IterableIterator<V> {
    for (const [, v] of this.entries()) yield v;
  }

  forEach(cb: (value: V, key: K, map: this) => void): void {
    for (const [k, v] of this.entries()) cb(v, k, this);
  }

  // ---- internals ---------------------------------------------------------

  private bucketIndex(key: K): number {
    const h = this.hashFn(key);
    // Force non-negative before modulo.
    return (h >>> 0) % this.capacity;
  }

  private resize(newCapacity: number): void {
    const oldBuckets = this.buckets;
    this.capacity = newCapacity;
    this.buckets = Array.from({ length: newCapacity }, () => []);
    this._size = 0; // re-added during re-insertion

    for (const bucket of oldBuckets) {
      for (const { key, value } of bucket) {
        this.set(key, value);
      }
    }
  }
}
```

### Usage example

```ts
const m = new HashMap<string, number>();
m.set("apple", 1).set("banana", 2);
console.log(m.get("apple")); // 1
console.log(m.has("pear"));  // false
m.delete("banana");
console.log(m.size);        // 1

// Object keys by reference:
const o1 = { id: 1 };
const o2 = { id: 1 };
const objMap = new HashMap<object, string>();
objMap.set(o1, "first");
console.log(objMap.get(o2)); // undefined (different reference)
console.log(objMap.get(o1)); // "first"
```

### Key takeaways to mention in an interview

- **Collision strategy chosen**: separate chaining (array per bucket). Alternative: open addressing (linear/quadratic probing) with tombstones for deletes.
- **Rehashing**: triggered by load factor; amortized O(1) insert.
- **Equality contract**: if `equals(a,b)` then `hash(a) === hash(b)`. Violating this breaks the map.
- **`has` gotcha**: values can be `undefined`, so check key presence directly rather than relying on `get !== undefined`.
- For production in TypeScript, usually just use built-in `Map`, which is highly optimized; a custom implementation is for learning, special constraints (e.g., custom equality), or interview demonstrations.

# Edge Cases with Dictionaries and Hash Maps in TypeScript

Below are the most important edge cases, grouped by **plain objects (dictionary pattern)** and **`Map`/`WeakMap`**, with runnable examples.

---

## 1. Plain Objects Used as Dictionaries

### 1.1 Prototype pollution & inherited keys
```ts
const dict: Record<string, number> = {};

// These look "present" even though you never set them
console.log(dict.toString);        // [Function: toString]
console.log('constructor' in dict); // true

// Dangerous lookup
function get(d: Record<string, number>, k: string) {
  return d[k]; // may return inherited junk
}
```
**Fix:** use `Object.create(null)` or check `hasOwnProperty`.
```ts
const safe = Object.create(null) as Record<string, number>;
safe.a = 1;
console.log(Object.prototype.hasOwnProperty.call(safe, 'a')); // true
console.log('toString' in safe); // false
```

### 1.2 `in` vs `hasOwnProperty`
```ts
const d = { a: 0 };
console.log('a' in d); // true
console.log('toString' in d); // true  (inherited)
console.log(Object.prototype.hasOwnProperty.call(d, 'toString')); // false
```

### 1.3 Key coercion to strings
All object keys become strings (except Symbols).
```ts
const d: any = {};
d[1] = 'one';
d['1'] = 'string-one';
console.log(d); // { '1': 'string-one' }  (collision!)

const o = { x: 1 };
d[o] = 'obj';
console.log(d['[object Object]']); // 'obj'
```

### 1.4 Symbol keys are not enumerated
```ts
const sym = Symbol('id');
const d: any = { [sym]: 42, a: 1 };
console.log(Object.keys(d));        // ['a']
console.log(Object.getOwnPropertySymbols(d)); // [Symbol(id)]
```

### 1.5 Numeric keys are sorted, string keys keep insertion order
```ts
const d: any = {};
d['b'] = 1; d['2'] = 2; d['a'] = 3; d['1'] = 4;
console.log(Object.keys(d)); // ['1', '2', 'b', 'a']  (numeric first, sorted)
```
**Impact:** don't rely on insertion order for numeric-like keys.

### 1.6 `undefined` values vs missing keys
```ts
const d: Record<string, number | undefined> = { a: undefined };
console.log('a' in d);          // true
console.log(d.a === undefined); // true
// Can't distinguish "missing" from "set to undefined" with `in` alone
// JSON.stringify drops undefined:
console.log(JSON.stringify(d)); // "{}"
```

### 1.7 Accidental shadowing of built-ins
```ts
const d: any = {};
d.toString = () => 'oops';
console.log(String(d)); // 'oops' — breaks debugging/logging
```

### 1.8 Shallow copy / spread loses prototype
```ts
const proto = Object.create(null);
const d = Object.assign(proto, { a: 1 });
const copy = { ...d };
console.log(Object.getPrototypeOf(copy) === Object.prototype); // true, not null
```

### 1.9 Type-safety: index signatures are too permissive
```ts
type Dict = { [k: string]: number };
const d: Dict = { a: 1 };
const x: number = d['nope']; // TS says number, runtime undefined!
// Fix: use Partial or explicit undefined
type Safe = { [k: string]: number | undefined };
```

### 1.10 `Object.keys` returns `string[]`, losing literal types
```ts
const d = { a: 1, b: 2 } as const;
const keys = Object.keys(d); // string[], not ('a'|'b')[]
// Workaround:
const typedKeys = Object.keys(d) as Array<keyof typeof d>;
```

### 1.11 Mutating while iterating
```ts
const d: Record<string, number> = { a: 1, b: 2, c: 3 };
for (const k in d) {
  if (k === 'b') delete d.b;        // may skip 'c' in some engines
  if (k === 'a') d.z = 99;          // newly added may or may not be visited
}
```

### 1.12 Freezing / sealing
```ts
const d = Object.freeze({ a: 1 });
d.a = 2;       // silently fails (or throws in strict mode)
d.b = 3;       // fails
```

### 1.13 Large integer keys (BigInt not allowed as keys directly)
```ts
const d: any = {};
const big = 9007199254740993n; // beyond safe integer
d[big] = 'x';                 // coerced to "9007199254740992" (precision loss!)
console.log(Object.keys(d));  // ['9007199254740992']
```

---

## 2. `Map<K, V>`

### 2.1 Reference equality for object keys
```ts
const m = new Map<object, string>();
const o1 = { id: 1 };
const o2 = { id: 1 };
m.set(o1, 'first');
console.log(m.get(o2)); // undefined — different reference
```

### 2.2 `NaN` is treated as equal (unlike `===`)
```ts
const m = new Map<number, string>();
m.set(NaN, 'nan');
console.log(m.get(NaN));        // 'nan'
console.log(m.has(NaN));        // true
console.log(NaN === NaN);       // false  (Map uses SameValueZero)
```

### 2.3 `+0` and `-0` are the same key
```ts
const m = new Map<number, string>();
m.set(+0, 'plus');
m.set(-0, 'minus');
console.log(m.size);     // 1
console.log(m.get(-0));  // 'plus'
```

### 2.4 `undefined` and `null` are valid keys
```ts
const m = new Map<any, string>();
m.set(undefined, 'u');
m.set(null, 'n');
console.log(m.get(undefined)); // 'u'
console.log(m.size);           // 2
```

### 2.5 Iteration order is insertion order (but deletion+re-add moves)
```ts
const m = new Map<string, number>();
m.set('a', 1); m.set('b', 2);
m.delete('a'); m.set('a', 10);
console.log([...m.keys()]); // ['b', 'a']  (a moved to end)
```

### 2.6 Mutating during iteration
```ts
const m = new Map([['a', 1], ['b', 2]]);
for (const [k, v] of m) {
  if (k === 'a') m.set('c', 3); // added — may or may not be visited
  if (k === 'b') m.delete('a'); // deleted — already visited, fine
}
```
**Best practice:** collect keys first.
```ts
for (const k of [...m.keys()]) { /* safe */ }
```

### 2.7 No JSON serialization by default
```ts
const m = new Map([['a', 1]]);
console.log(JSON.stringify(m)); // "{}"
// Fix:
console.log(JSON.stringify(Object.fromEntries(m))); // '{"a":1}'
```

### 2.8 `Map` size vs array length; no index access
```ts
const m = new Map([['a', 1]]);
console.log(m[0]); // undefined (no numeric indexing)
console.log(m.size); // 1
```

### 2.9 WeakMap: keys must be objects; GC-dependent
```ts
const wm = new WeakMap<object, string>();
wm.set({ x: 1 }, 'v'); // key immediately eligible for GC
// wm.get({ x: 1 }) // undefined — new object, no reference

let key = { id: 1 };
wm.set(key, 'v');
key = null as any; // key may be collected; entry disappears
```

### 2.10 WeakMap is not iterable / no `size`
```ts
const wm = new WeakMap();
// wm.size; // Property 'size' does not exist
// for (const x of wm) {} // not iterable
```

### 2.11 Using `Map` with class instances as keys (identity)
```ts
class User { constructor(public id: number) {} }
const m = new Map<User, string>();
const u1 = new User(1), u2 = new User(1);
m.set(u1, 'A');
console.log(m.get(u2)); // undefined
```

---

## 3. Comparison: Object vs Map Decision Matrix

| Concern | Object dict | Map |
|---|---|---|
| Key types | string/Symbol only | any |
| Prototype pollution | yes (risk) | no |
| Order guarantee | mostly insertion (numeric sorted) | strict insertion |
| Size | manual count | `.size` |
| Iteration | `Object.keys` etc. | direct iterable |
| Performance (add/remove) | moderate | better for churn |
| Serialization | native JSON | needs conversion |
| Memory | lighter for small | heavier |

---

## 4. Recommended Patterns

### 4.1 Type-safe dictionary with `Map`
```ts
type UserId = string & { readonly __brand: 'UserId' };
const users = new Map<UserId, { name: string }>();

function makeId(s: string): UserId { return s as UserId; }
users.set(makeId('u1'), { name: 'Ada' });
```

### 4.2 Safe object dictionary helper
```ts
function createDict<V>(): Record<string, V | undefined> {
  return Object.create(null);
}
const d = createDict<number>();
d.a = 1;
// no prototype methods
```

### 4.3 Exhaustive key handling
```ts
type Status = 'ok' | 'err';
const counts: Record<Status, number> = { ok: 0, err: 0 };
// TS enforces all keys at creation; safe indexing returns number (not undefined)
// but runtime still needs care if keys come from external data
```

### 4.4 Guarding external keys
```ts
function read(d: Record<string, number>, key: string): number | undefined {
  if (!Object.prototype.hasOwnProperty.call(d, key)) return undefined;
  return d[key];
}
```

### 4.5 Immutable update (avoid mutation bugs)
```ts
const d = { a: 1, b: 2 };
const next = { ...d, b: 99, c: 3 }; // new object, old untouched
```

---

## 5. Quick Checklist

- [ ] Use `Map` when keys are non-strings, need guaranteed order, or frequent add/remove.
- [ ] Use `Object.create(null)` or `hasOwnProperty` for object dicts to avoid prototype issues.
- [ ] Type dictionaries as `{ [k: string]: V | undefined }` to force undefined checks.
- [ ] Never rely on `in` alone for existence.
- [ ] Avoid mutating collections during iteration; snapshot keys first.
- [ ] Convert `Map` to plain object before `JSON.stringify`.
- [ ] Remember `NaN`/`+0`/`-0` equality rules in `Map`.
- [ ] Don't use `WeakMap` if you need enumeration or size.
- [ ] Beware of key coercion (`1` vs `'1'`, objects → `'[object Object]'`).

These cover the vast majority of real-world bugs developers hit with dictionaries and hash maps in TypeScript.

# Dynamic Programming in TypeScript

Dynamic programming (DP) solves overlapping subproblems by caching results.  
Two common styles:

- **Top-down (memoization):** recursive, cache results in a `Map`.
- **Bottom-up (tabulation):** iterative, fill a table from smaller subproblems.

Below is a complete, runnable TypeScript file with examples of both styles.

## `dp.ts`

```ts
/* eslint-disable no-console */

// ---------- 1. Top-down memoization: Fibonacci ----------

function makeFib(): (n: number) => number {
  const memo = new Map<number, number>();

  const fib = (n: number): number => {
    if (n <= 1) return n;
    const cached = memo.get(n);
    if (cached !== undefined) return cached;

    const value = fib(n - 1) + fib(n - 2);
    memo.set(n, value);
    return value;
  };

  return fib;
}

// ---------- 2. Bottom-up tabulation: Coin Change (min coins) ----------

function coinChange(coins: readonly number[], amount: number): number {
  if (amount === 0) return 0;
  if (coins.length === 0) return -1;

  const INF = amount + 1; // larger than any feasible answer
  const dp: number[] = new Array(amount + 1).fill(INF);
  dp[0] = 0;

  for (let a = 1; a <= amount; a++) {
    for (const coin of coins) {
      if (coin <= a && dp[a - coin] + 1 < dp[a]) {
        dp[a] = dp[a - coin] + 1;
      }
    }
  }

  return dp[amount] > amount ? -1 : dp[amount];
}

// ---------- 3. Bottom-up: Longest Common Subsequence ----------

function lcs(a: string, b: string): number {
  const m = a.length;
  const n = b.length;

  // (m+1) x (n+1) table, zero-initialized
  const dp: number[][] = Array.from({ length: m + 1 }, () =>
    new Array<number>(n + 1).fill(0)
  );

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (a[i - 1] === b[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  return dp[m][n];
}

// ---------- 4. Bottom-up: 0/1 Knapsack ----------

function knapsack(
  weights: readonly number[],
  values: readonly number[],
  capacity: number
): number {
  const n = weights.length;
  if (n !== values.length) {
    throw new Error("weights and values must have the same length");
  }
  if (capacity < 0) return 0;

  // dp[i][w] = best value using first i items with capacity w
  const dp: number[][] = Array.from({ length: n + 1 }, () =>
    new Array<number>(capacity + 1).fill(0)
  );

  for (let i = 1; i <= n; i++) {
    const wi = weights[i - 1];
    const vi = values[i - 1];
    for (let w = 0; w <= capacity; w++) {
      if (wi <= w) {
        dp[i][w] = Math.max(dp[i - 1][w], vi + dp[i - 1][w - wi]);
      } else {
        dp[i][w] = dp[i - 1][w];
      }
    }
  }

  return dp[n][capacity];
}

// ---------- 5. Reusable memoization helper ----------

function memoize<Args extends unknown[], R>(
  fn: (...args: Args) => R,
  keyFn: (...args: Args) => string = (...args) =>
    JSON.stringify(args)
): (...args: Args) => R {
  const cache = new Map<string, R>();
  return (...args: Args): R => {
    const key = keyFn(...args);
    if (cache.has(key)) return cache.get(key)!;
    const result = fn(...args);
    cache.set(key, result);
    return result;
  };
}

// ---------- Demo / smoke tests ----------

function main(): void {
  const fib = makeFib();
  console.log("fib(10) =", fib(10)); // 55
  console.log("fib(40) =", fib(40)); // 102334155

  console.log("coinChange([1,2,5], 11) =", coinChange([1, 2, 5], 11)); // 3
  console.log("coinChange([2], 3) =", coinChange([2], 3)); // -1

  console.log('lcs("abcde", "ace") =', lcs("abcde", "ace")); // 3
  console.log('lcs("abc", "def") =', lcs("abc", "def")); // 0

  const weights = [1, 3, 4, 5];
  const values = [1, 4, 5, 7];
  console.log("knapsack(capacity=7) =", knapsack(weights, values, 7)); // 9

  // Using the generic memoize helper for a pure function
  const square = memoize((x: number) => x * x);
  console.log("square(12) =", square(12)); // 144
  console.log("square(12) (cached) =", square(12)); // 144

  // Simple assertions
  console.assert(fib(10) === 55, "fib(10)");
  console.assert(coinChange([1, 2, 5], 11) === 3, "coinChange");
  console.assert(lcs("abcde", "ace") === 3, "lcs");
  console.assert(knapsack(weights, values, 7) === 9, "knapsack");
  console.log("All assertions passed.");
}

main();
```

## How to run

1. Save as `dp.ts`.
2. Run with `ts-node` (no compile step):

