## Edge cases to handle in TypeScript DP

Below are the most common edge cases, with idiomatic TypeScript examples. Many are generic DP issues, but the code highlights TypeScript-specific pitfalls (`undefined` from indexing, strict null checks, typing memo caches, BigInt, etc.).

---

### 1. Empty / trivial inputs
Always short-circuit before allocating tables.

```ts
function maxSubarraySum(nums: number[]): number {
  if (nums.length === 0) return 0;          // empty
  if (nums.length === 1) return nums[0];     // single element

  let best = nums[0];
  let cur = nums[0];
  for (let i = 1; i < nums.length; i++) {
    cur = Math.max(nums[i], cur + nums[i]);
    best = Math.max(best, cur);
  }
  return best;
}
```

---

### 2. Negative indices / out-of-bounds access
In top-down DP, guard transitions that reference `i-1`, `j-1`, etc.

```ts
function countPaths(m: number, n: number): number {
  if (m <= 0 || n <= 0) return 0;

  const dp: number[][] = Array.from({ length: m }, () =>
    Array(n).fill(0)
  );
  dp[0][0] = 1;

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (i > 0) dp[i][j] += dp[i - 1][j];
      if (j > 0) dp[i][j] += dp[i][j - 1];
    }
  }
  return dp[m - 1][n - 1];
}
```

---

### 3. `undefined` from array indexing (`noUncheckedIndexedAccess`)
With strict settings, `dp[i]` may be `number | undefined`. Use nullish coalescing or non-null assertions carefully.

```ts
function fib(n: number): number {
  if (n < 0) throw new RangeError("n must be non-negative");
  if (n <= 1) return n;

  const dp: (number | undefined)[] = new Array(n + 1);
  dp[0] = 0;
  dp[1] = 1;

  for (let i = 2; i <= n; i++) {
    const a = dp[i - 1] ?? 0;
    const b = dp[i - 2] ?? 0;
    dp[i] = a + b;
  }
  return dp[n] ?? 0;
}
```

Alternative: initialize the whole array to avoid `undefined`.

```ts
const dp = new Array<number>(n + 1).fill(0);
```

---

### 4. Memoization sentinel problem (falsy cached values)
Using an object/array as cache breaks when the answer is `0`. Use `Map` + `has`.

```ts
const memo = new Map<number, number>();

function climbStairs(n: number): number {
  if (n < 0) return 0;
  if (n <= 1) return 1;

  if (memo.has(n)) return memo.get(n)!;

  const res = climbStairs(n - 1) + climbStairs(n - 2);
  memo.set(n, res);
  return res;
}
```

For string keys / composite states:

```ts
const memo = new Map<string, number>();
const key = `${i}|${j}|${mask}`;
```

---

### 5. Stale caches across calls
Module-level memo can leak between test cases or inputs. Make the cache local or clear it.

```ts
function solveWithMemo(n: number): number {
  const memo = new Map<number, number>();

  function dfs(x: number): number {
    if (x <= 1) return x;
    if (memo.has(x)) return memo.get(x)!;
    const r = dfs(x - 1) + dfs(x - 2);
    memo.set(x, r);
    return r;
  }
  return dfs(n);
}
```

---

### 6. Recursion depth / stack overflow
Deep top-down DP (e.g., `n = 100000`) can exceed the JS call stack. Prefer bottom-up or iterative.

```ts
// Dangerous for large n:
function fibRecursive(n: number): number { ... }

// Safe:
function fibIterative(n: number): number {
  if (n <= 1) return n;
  let a = 0, b = 1;
  for (let i = 2; i <= n; i++) {
    [a, b] = [b, a + b];
  }
  return b;
}
```

If recursion is unavoidable, convert to an explicit stack or use trampolining.

---

### 7. All-negative inputs
Initialize DP with `-Infinity` (or `Number.NEGATIVE_INFINITY`), not `0`.

```ts
function maxSubarray(nums: number[]): number {
  if (nums.length === 0) throw new Error("empty input");

  const dp = new Array<number>(nums.length);
  dp[0] = nums[0];
  let best = nums[0];

  for (let i = 1; i < nums.length; i++) {
    dp[i] = Math.max(nums[i], (dp[i - 1] ?? nums[i]) + nums[i]);
    best = Math.max(best, dp[i]);
  }
  return best;
}
```

---

### 8. 2D table sizing (off-by-one)
Use `(n+1) x (m+1)` when representing “up to i items / capacity j”.

```ts
function knapsack(weights: number[], values: number[], cap: number): number {
  const n = weights.length;
  // dp[i][w] = best value using first i items with capacity w
  const dp: number[][] = Array.from({ length: n + 1 }, () =>
    Array(cap + 1).fill(0)
  );

  for (let i = 1; i <= n; i++) {
    for (let w = 0; w <= cap; w++) {
      const skip = dp[i - 1][w];
      const take =
        weights[i - 1] <= w
          ? values[i - 1] + dp[i - 1][w - weights[i - 1]]
          : 0;
      dp[i][w] = Math.max(skip, take);
    }
  }
  return dp[n][cap];
}
```

---

### 9. Rolling-array overwrite bugs
When optimizing space, do not overwrite values still needed by the current transition.

```ts
// 0/1 knapsack: iterate capacity DOWNWARDS so each item is used once.
function knapsack1D(weights: number[], values: number[], cap: number): number {
  const dp = new Array<number>(cap + 1).fill(0);
  for (let i = 0; i < weights.length; i++) {
    for (let w = cap; w >= weights[i]; w--) {
      dp[w] = Math.max(dp[w], values[i] + dp[w - weights[i]]);
    }
  }
  return dp[cap];
}
```

Unbounded knapsack would iterate `w` upwards instead.

---

### 10. Numeric overflow / huge counts
JavaScript numbers are IEEE-754 doubles. For combinatorial DP, use `BigInt` or modulo.

```ts
// Factorial-style growth with BigInt
function factorialDP(n: number): bigint {
  if (n < 0) throw new RangeError("negative");
  const dp: bigint[] = new Array(n + 1);
  dp[0] = 1n;
  for (let i = 1; i <= n; i++) dp[i] = dp[i - 1] * BigInt(i);
  return dp[n];
}
```

Counting with modulo:

```ts
const MOD = 1_000_000_007;
function countWays(n: number): number {
  const dp = new Array<number>(n + 1).fill(0);
  dp[0] = 1;
  for (let i = 1; i <= n; i++) {
    dp[i] = (dp[i - 1] + (i >= 2 ? dp[i - 2] : 0)) % MOD;
  }
  return dp[n];
}
```

---

### 11. Floating-point precision
Avoid equality comparisons on accumulated floats; use epsilon or scale to integers.

```ts
function canPartition(nums: number[]): boolean {
  const sum = nums.reduce((a, b) => a + b, 0);
  if (sum % 2 !== 0) return false; // works if integers
  const target = sum / 2;
  const dp = new Array<boolean>(target + 1).fill(false);
  dp[0] = true;
  for (const x of nums) {
    for (let s = target; s >= x; s--) {
      dp[s] = dp[s] || dp[s - x];
    }
  }
  return dp[target];
}
```

If inputs are decimals, multiply by a power of 10 first.

---

### 12. Input mutation / ordering assumptions
Some DP (interval scheduling, LIS) depends on sorting. Do not mutate caller data unexpectedly.

```ts
function lengthOfLIS(nums: number[]): number {
  const sortedCopy = [...nums].sort((a, b) => a - b); // if needed
  // Prefer patience sorting / binary search for O(n log n)
  const tails: number[] = [];
  for (const x of nums) {
    let lo = 0, hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < x) lo = mid + 1;
      else hi = mid;
    }
    tails[lo] = x;
  }
  return tails.length;
}
```

---

### 13. State encoding for bitmask DP
Ensure bitmasks fit in JS safe integers (`<= 2^53 - 1`). For larger, use `BigInt` masks.

```ts
function tsp(dist: number[][]): number {
  const n = dist.length;
  if (n === 0) return 0;
  const INF = Number.POSITIVE_INFINITY;
  const dp: number[][] = Array.from({ length: 1 << n }, () =>
    Array(n).fill(INF)
  );
  dp[1][0] = 0;

  for (let mask = 1; mask < (1 << n); mask++) {
    for (let last = 0; last < n; last++) {
      if (!(mask & (1 << last))) continue;
      if (!Number.isFinite(dp[mask][last])) continue;
      for (let nxt = 0; nxt < n; nxt++) {
        if (mask & (1 << nxt)) continue;
        const nm = mask | (1 << nxt);
        dp[nm][nxt] = Math.min(
          dp[nm][nxt],
          dp[mask][last] + dist[last][nxt]
        );
      }
    }
  }
  const full = (1 << n) - 1;
  return Math.min(...dp[full]);
}
```

---

### 14. Typed DP with `undefined` during construction
When building 2D arrays lazily, type them as `(T | undefined)[][]` or fill eagerly.

```ts
type Cell = { best: number } | undefined;

function buildTable(rows: number, cols: number): Cell[][] {
  return Array.from({ length: rows }, () =>
    Array<Cell>(cols).fill(undefined)
  );
}
```

---

### 15. Handling “no valid solution” (impossible states)
Distinguish “not computed” from “impossible”. Use `null` or `Infinity`.

```ts
function minCoins(coins: number[], amount: number): number {
  const INF = Number.POSITIVE_INFINITY;
  const dp = new Array<number>(amount + 1).fill(INF);
  dp[0] = 0;

  for (let a = 1; a <= amount; a++) {
    for (const c of coins) {
      if (c <= a && Number.isFinite(dp[a - c])) {
        dp[a] = Math.min(dp[a], dp[a - c] + 1);
      }
    }
  }
  return Number.isFinite(dp[amount]) ? dp[amount] : -1;
}
```

