### Quick checklist

| Edge case | Typical fix |
|---|---|
| Empty input | early return |
| Negative index | guard `if (i > 0)` |
| Falsy memo values | `Map.has` |
| Deep recursion | iterative DP |
| All negatives | init with `-Infinity` |
| 2D sizing | `n+1`, `m+1` |
| Space optimization | correct loop direction |
| Huge values | `BigInt` or modulo |
| Floats | scale to integers |
| Mutating input | copy/sort copy |
| Large bitmasks | `BigInt` |
| Impossible states | `Infinity` / `-1` |

If you want, I can turn one of these into a full production-ready module (e.g., typed memoized DP with tests).

Below is a complete, dependency-free TypeScript module that implements encoding/decoding for the most common character sets and related text operations. It runs in Node.js (and most of the primitives also work in browsers).

### `encoding.ts`

```ts
// encoding.ts
// A self-contained toolkit for encodings & character sets in TypeScript/Node.js.
// Run with:  npx tsx encoding.ts   (or: npx ts-node encoding.ts)

import { Buffer } from 'node:buffer';

export type Charset =
  | 'utf-8'
  | 'utf-16le'
  | 'utf-16be'
  | 'ascii'
  | 'latin1'        // ISO-8859-1
  | 'windows-1252'; // CP1252

export interface EncodeOptions { bom?: boolean; }
export interface DecodeOptions { stripBom?: boolean; }

/* ============================================================
 * 1. UTF-8 (manual, byte-exact, with validation on decode)
 * ============================================================ */

export function utf8Encode(input: string): Uint8Array {
  const bytes: number[] = [];
  for (let i = 0; i < input.length; ) {
    const cp = input.codePointAt(i)!;
    i += cp > 0xffff ? 2 : 1;

    if (cp <= 0x7f) {
      bytes.push(cp);
    } else if (cp <= 0x7ff) {
      bytes.push(0xc0 | (cp >> 6));
      bytes.push(0x80 | (cp & 0x3f));
    } else if (cp <= 0xffff) {
      bytes.push(0xe0 | (cp >> 12));
      bytes.push(0x80 | ((cp >> 6) & 0x3f));
      bytes.push(0x80 | (cp & 0x3f));
    } else {
      bytes.push(0xf0 | (cp >> 18));
      bytes.push(0x80 | ((cp >> 12) & 0x3f));
      bytes.push(0x80 | ((cp >> 6) & 0x3f));
      bytes.push(0x80 | (cp & 0x3f));
    }
  }
  return new Uint8Array(bytes);
}

export function utf8Decode(bytes: Uint8Array, replacement = '\uFFFD'): string {
  let result = '';
  let i = 0;
  const len = bytes.length;
  while (i < len) {
    const b0 = bytes[i];
    let cp = 0;
    let extra = 0;

    if (b0 < 0x80) { cp = b0; extra = 0; }
    else if ((b0 & 0xe0) === 0xc0) { cp = b0 & 0x1f; extra = 1; }
    else if ((b0 & 0xf0) === 0xe0) { cp = b0 & 0x0f; extra = 2; }
    else if ((b0 & 0xf8) === 0xf0) { cp = b0 & 0x07; extra = 3; }
    else { result += replacement; i++; continue; }

    if (i + extra >= len) { result += replacement; break; }

    let valid = true;
    for (let j = 1; j <= extra; j++) {
      const b = bytes[i + j];
      if ((b & 0xc0) !== 0x80) { valid = false; break; }
      cp = (cp << 6) | (b & 0x3f);
    }
    if (!valid) { result += replacement; i++; continue; }

    const minCp = [0, 0x80, 0x800, 0x10000][extra];
    if (cp < minCp || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) {
      result += replacement; i++; continue;
    }
    result += String.fromCodePoint(cp);
    i += extra + 1;
  }
  return result;
}

/* ============================================================
 * 2. Windows-1252 (CP1252) tables
 * ============================================================ */

const WIN1252_DECODE: number[] = (() => {
  const t = new Array<number>(256);
  for (let i = 0; i < 256; i++) t[i] = i;

  const overrides: Record<number, number> = {
    0x80: 0x20ac, 0x82: 0x201a, 0x83: 0x0192, 0x84: 0x201e, 0x85: 0x2026,
    0x86: 0x2020, 0x87: 0x2021, 0x88: 0x02c6, 0x89: 0x2030, 0x8a: 0x0160,
    0x8b: 0x2039, 0x8c: 0x0152, 0x8e: 0x017d, 0x91: 0x2018, 0x92: 0x2019,
    0x93: 0x201c, 0x94: 0x201d, 0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014,
    0x98: 0x02dc, 0x99: 0x2122, 0x9a: 0x0161, 0x9b: 0x203a, 0x9c: 0x0153,
    0x9e: 0x017e, 0x9f: 0x0178,
  };
  for (const [b, cp] of Object.entries(overrides)) t[+b] = cp;
  return t;
})();

const WIN1252_ENCODE = new Map<number, number>();
for (let b = 0; b < 256; b++) {
  const cp = WIN1252_DECODE[b];
  if (!WIN1252_ENCODE.has(cp)) WIN1252_ENCODE.set(cp, b);
}

export function windows1252Encode(input: string): Uint8Array {
  const bytes: number[] = [];
  for (const ch of input) {
    const cp = ch.codePointAt(0)!;
    if (WIN1252_ENCODE.has(cp)) {
      bytes.push(WIN1252_ENCODE.get(cp)!);
    } else if (cp <= 0x7f || (cp >= 0xa0 && cp <= 0xff)) {
      bytes.push(cp);
    } else {
      bytes.push(0x3f); // '?'
    }
  }
  return new Uint8Array(bytes);
}

export function windows1252Decode(bytes: Uint8Array): string {
  let s = '';
  for (const b of bytes) s += String.fromCodePoint(WIN1252_DECODE[b]);
  return s;
}

/* ============================================================
 * 3. BOM (Byte Order Mark) handling
 * ============================================================ */

export function detectBom(bytes: Uint8Array): { encoding: Charset | null; offset: number } {
  if (bytes.length >= 4) {
    if (bytes[0] === 0xff && bytes[1] === 0xfe && bytes[2] === 0x00 && bytes[3] === 0x00)
      return { encoding: 'utf-32le', offset: 4 }; // not in Charset union? keep as any
    if (bytes[0] === 0x00 && bytes[1] === 0x00 && bytes[2] === 0xfe && bytes[3] === 0xff)
      return { encoding: null, offset: 4 };
  }
  if (bytes.length >= 3 && bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf)
    return { encoding: 'utf-8', offset: 3 };
  if (bytes.length >= 2) {
    if (bytes[0] === 0xff && bytes[1] === 0xfe) return { encoding: 'utf-16le', offset: 2 };
    if (bytes[0] === 0xfe && bytes[1] === 0xff) return { encoding: 'utf-16be', offset: 2 };
  }
  return { encoding: null, offset: 0 };
}

// widen detectBom return type for utf-32 (kept informational)
export type BomInfo = { encoding: string | null; offset: number };

/* ============================================================
 * 4. Generic encode / decode
 * ============================================================ */

function bomBytes(charset: Charset): Uint8Array | null {
  switch (charset) {
    case 'utf-8': return new Uint8Array([0xef, 0xbb, 0xbf]);
    case 'utf-16le': return new Uint8Array([0xff, 0xfe]);
    case 'utf-16be': return new Uint8Array([0xfe, 0xff]);
    default: return null;
  }
}

export function encode(input: string, charset: Charset, opts: EncodeOptions = {}): Uint8Array {
  let out: Uint8Array;
  switch (charset) {
    case 'utf-8':
      out = utf8Encode(input);
      break;
    case 'ascii': {
      const b = new Uint8Array(input.length);
      for (let i = 0; i < input.length; i++) b[i] = input.charCodeAt(i) & 0x7f;
      out = b;
      break;
    }
    case 'latin1':
      out = new Uint8Array(Buffer.from(input, 'latin1'));
      break;
    case 'windows-1252':
      out = windows1252Encode(input);
      break;
    case 'utf-16le':
      out = new Uint8Array(Buffer.from(input, 'utf16le'));
      break;
    case 'utf-16be': {
      const le = Buffer.from(input, 'utf16le');
      const be = Buffer.alloc(le.length);
      for (let i = 0; i < le.length; i += 2) {
        be[i] = le[i + 1];
        be[i + 1] = le[i];
      }
      out = new Uint8Array(be);
      break;
    }
    default:
      throw new Error(`Unsupported charset: ${charset}`);
  }

  if (opts.bom) {
    const bom = bomBytes(charset);
    if (bom) {
      const merged = new Uint8Array(bom.length + out.length);
      merged.set(bom);
      merged.set(out, bom.length);
      out = merged;
    }
  }
  return out;
}

export function decode(bytes: Uint8Array, charset: Charset, opts: DecodeOptions = {}): string {
  let data = bytes;
  if (opts.stripBom) {
    const d = detectBom(bytes);
    if (d.offset > 0) data = bytes.subarray(d.offset);
  }
  switch (charset) {
    case 'utf-8':
      return utf8Decode(data);
    case 'ascii':
      return Buffer.from(data).toString('ascii');
    case 'latin1':
      return Buffer.from(data).toString('latin1');
    case 'windows-1252':
      return windows1252Decode(data);
    case 'utf-16le':
      return Buffer.from(data).toString('utf16le');
    case 'utf-16be': {
      const be = Buffer.from(data);
      const le = Buffer.alloc(be.length);
      for (let i = 0; i < be.length; i += 2) {
        le[i] = be[i + 1];
        le[i + 1] = be[i];
      }
      return le.toString('utf16le');
    }
    default:
      throw new Error(`Unsupported charset: ${charset}`);
  }
}

export function decodeAuto(bytes: Uint8Array): { text: string; charset: string; bom: boolean } {
  const d = detectBom(bytes);
  const charset = d.encoding ?? 'utf-8';
  const text = decode(bytes, charset as Charset, { stripBom: true });
  return { text, charset, bom: d.offset > 0 };
}

/* ============================================================
 * 5. Charset conversion
 * ============================================================ */

export function convert(bytes: Uint8Array, from: Charset, to: Charset): Uint8Array {
  const text = decode(bytes, from, { stripBom: true });
  return encode(text, to);
}

/* ============================================================
 * 6. Binary / text encodings: hex, base64, base64url, percent
 * ============================================================ */

export function toHex(bytes: Uint8Array): string {
  return Buffer.from(bytes).toString('hex');
}
export function fromHex(hex: string): Uint8Array {
  return new Uint8Array(Buffer.from(hex.replace(/\s+/g, ''), 'hex'));
}
export function toBase64(bytes: Uint8Array): string {
  return Buffer.from(bytes).toString('base64');
}
export function fromBase64(b64: string): Uint8Array {
  return new Uint8Array(Buffer.from(b64, 'base64'));
}
export function toBase64Url(bytes: Uint8Array): string {
  return Buffer.from(bytes).toString('base64url');
}
export function fromBase64Url(b64url: string): Uint8Array {
  return new Uint8Array(Buffer.from(b64url, 'base64url'));
}
export function percentEncode(str: string): string {
  return encodeURIComponent(str);
}
export function percentDecode(str: string): string {
  return decodeURIComponent(str);
}

/* ============================================================
 * 7. Unicode normalization & grapheme segmentation
 * ============================================================ */

export function normalize(text: string, form: 'NFC' | 'NFD' | 'NFKC' | 'NFKD' = 'NFC'): string {
  return text.normalize(form);
}

export function graphemes(text: string): string[] {
  const Seg = (Intl as any).Segmenter;
  if (!Seg) return Array.from(text);
  const seg = new Seg(undefined, { granularity: 'grapheme' });
  return Array.from(seg.segment(text), (s: any) => s.segment as string);
}

/* ============================================================
 * 8. ICU-backed arbitrary labels (Node may support many)
 * ============================================================ */

export function decodeWithLabel(bytes: Uint8Array, label: string): string {
  const td = new TextDecoder(label, { fatal: false });
  return td.decode(bytes);
}

export function encodeWithLabel(text: string, label: string): Uint8Array {
  try {
    return new Uint8Array(Buffer.from(text, label as any));
  } catch {
    throw new Error(`Encoding to "${label}" is not supported by this runtime.`);
  }
}

/* ============================================================
 * 9. Streaming decode + validation helpers
 * ============================================================ */

export function createUtf8Decoder() {
  const td = new TextDecoder('utf-8', { fatal: false });
  return {
    decode(chunk: Uint8Array, stream = true): string {
      return td.decode(chunk, { stream });
    },
    flush(): string {
      return td.decode();
    },
  };
}

export function isValidUtf8(bytes: Uint8Array): boolean {
  try {
    new TextDecoder('utf-8', { fatal: true }).decode(bytes);
    return true;
  } catch {
    return false;
  }
}

/* ============================================================
 * 10. Demo / self-tests
 * ============================================================ */

function assert(cond: any, msg: string) {
  if (!cond) {
    console.error('FAIL:', msg);
    process.exitCode = 1;
  } else {
    console.log('ok  :', msg);
  }
}

function main() {
  console.log('=== Encoding & Character Sets Demo ===\n');

  // --- UTF-8 round trip (emoji, CJK, astral plane) ---
  const samples = ['Hello, world!', 'café', '😀🚀', '日本語', 'Привет', 'مرحبا'];
  for (const s of samples) {
    const b = utf8Encode(s);
    const back = utf8Decode(b);
    assert(back === s, `UTF-8 roundtrip: ${s}`);
  }

  // --- Invalid UTF-8 -> replacement char ---
  const bad = new Uint8Array([0xff, 0xfe, 0x80]);
  assert(utf8Decode(bad).includes('\uFFFD'), 'invalid UTF-8 produces replacement char');

  // --- Windows-1252 euro sign & smart quotes ---
  const w = 'Price: €100 — “quoted”';
  const wb = windows1252Encode(w);
  assert(toHex(wb).includes('80'), 'windows-1252 encodes € as 0x80');
  assert(windows1252Decode(wb) === w, 'windows-1252 roundtrip');

  // --- Latin-1 vs Windows-1252 difference ---
  const euroBytes = new Uint8Array([0x80]);
  assert(decode(euroBytes, 'latin1') === '\u0080', 'latin1 0x80 -> control char');
  assert(decode(euroBytes, 'windows-1252') === '€', 'windows-1252 0x80 -> euro');

  // --- BOM detection ---
  const bomUtf8 = new Uint8Array([0xef, 0xbb, 0xbf, ...utf8Encode('hi')]);
  const bomInfo = detectBom(bomUtf8);
  assert(bomInfo.encoding === 'utf-8' && bomInfo.offset === 3, 'BOM detected (UTF-8)');

  const auto = decodeAuto(bomUtf8);
  assert(auto.text === 'hi' && auto.bom === true, 'decodeAuto strips BOM');

  // --- encode with BOM ---
  const withBom = encode('hi', 'utf-8', { bom: true });
  assert(toHex(withBom) === 'efbbbf6869', 'encode adds BOM');

  // --- UTF-16 LE/BE ---
  const u16 = 'Ab😀';
  const le = encode(u16, 'utf-16le');
  const be = encode(u16, 'utf-16be');
  assert(decode(le, 'utf-16le') === u16, 'UTF-16LE roundtrip');
  assert(decode(be, 'utf-16be') === u16, 'UTF-16BE roundtrip');

  // --- Charset conversion ---
  const cp1252Bytes = encode('café', 'windows-1252');
  const utf8Bytes = convert(cp1252Bytes, 'windows-1252', 'utf-8');
  assert(decode(utf8Bytes, 'utf-8') === 'café', 'charset conversion');

  // --- Hex / Base64 / Base64URL ---
  const raw = utf8Encode('Man');
  assert(toHex(raw) === '4d616e', 'toHex');
  assert(new TextDecoder().decode(fromHex('4d 61 6e')) === 'Man', 'fromHex');
  assert(toBase64(raw) === 'TWFu', 'toBase64');
  assert(new TextDecoder().decode(fromBase64('TWFu')) === 'Man', 'fromBase64');
  assert(toBase64Url(utf8Encode('subjects?_d=1')) !== toBase64(utf8Encode('subjects?_d=1')), 'base64url differs');

  // --- Percent encoding ---
  assert(percentEncode('a b') === 'a%20b', 'percentEncode');
  assert(percentDecode('a%20b') === 'a b', 'percentDecode');

  // --- Normalization ---
  const composed = '\u00e9';          // é (NFC)
  const decomposed = 'e\u0301';        // e + combining acute (NFD)
  assert(normalize(decomposed, 'NFC') === composed, 'NFD -> NFC normalization');
  assert(normalize(composed, 'NFD') === decomposed, 'NFC -> NFD normalization');

  // --- Grapheme clusters ---
  const family = '👨‍👩‍👧‍👦';
  assert(graphemes(family).length === 1, 'family emoji is one grapheme');
  assert(graphemes('a😀b').length === 3, 'grapheme count with emoji');

  // --- Streaming decode ---
  const sd = createUtf8Decoder();
  const part1 = utf8Encode('Hel');
  const part2 = utf8Encode('lo 🌍');
  const r1 = sd.decode(part1);
  const r2 = sd.decode(part2);
  const r3 = sd.flush();
  assert(r1 + r2 + r3 === 'Hello 🌍', 'streaming UTF-8 decode');

  // --- Validation ---
  assert(isValidUtf8(utf8Encode('ok')) === true, 'valid UTF-8');
  assert(isValidUtf8(new Uint8Array([0x80])) === false, 'invalid UTF-8 detected');

  // --- ICU label decode (if available) ---
  try {
    const txt = decodeWithLabel(windows1252Encode('café'), 'windows-1252');
    assert(txt === 'café', 'ICU decode windows-1252');
  } catch (e) {
    console.log('skip: ICU label decode not available');
  }

  console.log('\nDone. exitCode =', process.exitCode ?? 0);
}

main();
