## Summary checklist

| Area | Pitfall | Fix |
|---|---|---|
| String indexing | surrogate pairs | `Array.from`, `for...of`, `Intl.Segmenter` |
| Equality | NFC vs NFD | `.normalize("NFC")` |
| Filenames | macOS NFD | normalize before compare |
| Decoding | invalid bytes | `fatal: true` |
| BOM | leaks into tokens | strip `\uFEFF` |
| Base64 | `btoa` Latin-1 only | encode UTF-8 first |
| URLs | double encoding | use `URL`/`URLSearchParams` |
| Regex | no `u` flag | add `u`/`v` |
| Casing | Turkish I | `toLocaleLowerCase(locale)` |
| Whitespace | ZWSP not trimmed | explicit regex |
| Hashing | encoding mismatch | normalize + UTF-8 |
| Streaming | split multibyte | `{ stream: true }` + flush |
| JSON | lone surrogates | validate input |
| CSV | Excel mojibake | BOM + CRLF |

The overarching rule: **treat strings as Unicode text, bytes as encoding-specific, and never assume a 1:1 mapping between "characters", code points, and UTF-16 code units.** Normalize at system boundaries, validate before encoding, and use the platform's `Intl`/`TextDecoder` APIs rather than hand-rolled byte manipulation.

# Enums in TypeScript — Complete Guide

TypeScript enums are **runtime objects** (except `const enum`) with a corresponding nominal type.  
They come in several flavors; below is a runnable tour of all of them plus the modern alternatives.

---

## 1. Numeric enums (default)

```ts
// enums.ts
enum Direction {
  Up,        // 0
  Down,      // 1
  Left,      // 2
  Right,     // 3
}

// Explicit values
enum Status {
  Pending = 10,
  Running = 20,
  Done = 30,
}

// Computed / referenced members
enum FileAccess {
  None   = 0,
  Read   = 1 << 0,   // 1
  Write  = 1 << 1,   // 2
  ReadWrite = Read | Write, // 3
}
```

Numeric enums get **reverse mappings** at runtime:

```ts
console.log(Direction.Up);        // 0
console.log(Direction[0]);        // "Up"
console.log(FileAccess.ReadWrite); // 3
```

---

## 2. String enums

```ts
enum Color {
  Red   = "RED",
  Green = "GREEN",
  Blue  = "BLUE",
}

console.log(Color.Red);   // "RED"
// No reverse mapping for string enums:
// Color["RED"] is undefined
```

String enums are usually preferred over numeric ones for debugging and serialization.

---

## 3. `const enum` (compile-time only)

```ts
const enum LogLevel {
  Debug = 0,
  Info  = 1,
  Warn  = 2,
  Error = 3,
}

const lvl = LogLevel.Info; // compiled to: const lvl = 1; (no object emitted)
```

- **Zero runtime cost** — values are inlined.
- **No reverse mapping** at all.
- Caveat: tools that only transpile (Babel, `isolatedModules`) may need special config, because const enums are erased and inlined by `tsc`.

---

## 4. Heterogeneous enums (avoid)

```ts
enum Mixed {
  No = 0,
  Yes = "YES",
}
```

Legal but discouraged; mixing types destroys type safety and tooling support.

---

## 5. Using enums as types & in APIs

```ts
function paint(c: Color): void {
  if (c === Color.Red) console.log("painting red");
}

// Enum as a namespace for related constants
enum HttpStatus {
  Ok = 200,
  NotFound = 404,
  ServerError = 500,
}

interface Response {
  status: HttpStatus;
  body: string;
}
```

---

## 6. Modern alternative: string-union + `as const`

For many codebases, the preferred pattern is a **union of literal types** or an `as const` object:

```ts
// Option A — pure union (zero runtime, perfect tree-shaking)
type Direction2 = "Up" | "Down" | "Left" | "Right";

// Option B — const object with derived union
const Direction3 = {
  Up: "UP",
  Down: "DOWN",
} as const;
type Direction3 = (typeof Direction3)[keyof typeof Direction3];
```

These give exhaustive `switch` checking and avoid the runtime-object pitfalls of enums.

---

## 7. Complete runnable example

Save as `main.ts`:

```ts
// main.ts
enum Priority {
  Low    = "LOW",
  Medium = "MEDIUM",
  High   = "HIGH",
}

enum TaskState {
  Todo       = 0,
  InProgress = 1,
  Done       = 2,
}

interface Task {
  title: string;
  priority: Priority;
  state: TaskState;
}

function label(t: Task): string {
  const stateName = TaskState[t.state]; // reverse mapping (numeric only)
  return `[${t.priority}] ${t.title} — ${stateName}`;
}

const tasks: Task[] = [
  { title: "Write docs", priority: Priority.High,  state: TaskState.Todo },
  { title: "Ship feature", priority: Priority.Medium, state: TaskState.Done },
];

for (const t of tasks) console.log(label(t));

// Exhaustive switch with never-check
function assertNever(x: never): never {
  throw new Error("Unexpected value: " + x);
}

function stateColor(s: TaskState): string {
  switch (s) {
    case TaskState.Todo:       return "gray";
    case TaskState.InProgress: return "blue";
    case TaskState.Done:       return "green";
    default:                   return assertNever(s);
  }
}

console.log(stateColor(TaskState.InProgress));
```

### Run it

```bash
# Compile + run with Node
npx tsc main.ts --target es2020 --module commonjs
node main.js

# Or directly with ts-node / tsx
npx tsx main.ts
```

Expected output:

```
[HIGH] Write docs — Todo
[MEDIUM] Ship feature — Done
blue
```

