## `src/config/schema.ts`

```ts
import { z } from "zod";

const nodeEnv = z.enum(["development", "test", "production"]).default("development");

const commaList = (s: string) =>
  s
    .split(",")
    .map((x) => x.trim())
    .filter(Boolean);

export const ConfigSchema = z.object({
  // Runtime
  NODE_ENV: nodeEnv,
  PORT: z.coerce.number().int().min(1).max(65535).default(3000),
  HOST: z.string().min(1).default("0.0.0.0"),
  LOG_LEVEL: z.enum(["trace", "debug", "info", "warn", "error", "fatal"]).default("info"),

  // Data stores
  DATABASE_URL: z.string().url("DATABASE_URL must be a valid URL"),
  REDIS_URL: z.string().url("REDIS_URL must be a valid URL").optional(),

  // Security
  JWT_SECRET: z.string().min(32, "JWT_SECRET must be at least 32 characters"),
  JWT_EXPIRES_IN: z.string().default("15m"),
  BCRYPT_ROUNDS: z.coerce.number().int().min(4).max(31).default(12),

  // SMTP
  SMTP_HOST: z.string().optional(),
  SMTP_PORT: z.coerce.number().int().min(1).max(65535).optional(),
  SMTP_USER: z.string().optional(),
  SMTP_PASS: z.string().optional(),

  // Feature flags
  FEATURE_FLAGS: z
    .string()
    .default("")
    .transform(commaList),

  // CORS
  CORS_ORIGINS: z
    .string()
    .default("")
    .transform(commaList),
});

export type RawConfig = z.infer<typeof ConfigSchema>;

// Derived, computed config layered on top of raw env.
export interface AppConfig {
  env: RawConfig["NODE_ENV"];
  isDev: boolean;
  isTest: boolean;
  isProd: boolean;
  server: {
    host: string;
    port: number;
  };
  logLevel: RawConfig["LOG_LEVEL"];
  database: {
    url: string;
  };
  redis: {
    url: string | undefined;
  };
  security: {
    jwtSecret: string;
    jwtExpiresIn: string;
    bcryptRounds: number;
  };
  smtp: {
    host: string | undefined;
    port: number | undefined;
    user: string | undefined;
    pass: string | undefined;
    enabled: boolean;
  };
  features: {
    flags: string[];
    isEnabled: (flag: string) => boolean;
  };
  cors: {
    origins: string[];
  };
}

export function buildAppConfig(raw: RawConfig): AppConfig {
  const isDev = raw.NODE_ENV === "development";
  const isTest = raw.NODE_ENV === "test";
  const isProd = raw.NODE_ENV === "production";
  const flags = raw.FEATURE_FLAGS;

  return {
    env: raw.NODE_ENV,
    isDev,
    isTest,
    isProd,
    server: { host: raw.HOST, port: raw.PORT },
    logLevel: raw.LOG_LEVEL,
    database: { url: raw.DATABASE_URL },
    redis: { url: raw.REDIS_URL },
    security: {
      jwtSecret: raw.JWT_SECRET,
      jwtExpiresIn: raw.JWT_EXPIRES_IN,
      bcryptRounds: raw.BCRYPT_ROUNDS,
    },
    smtp: {
      host: raw.SMTP_HOST,
      port: raw.SMTP_PORT,
      user: raw.SMTP_USER,
      pass: raw.SMTP_PASS,
      enabled: Boolean(raw.SMTP_HOST && raw.SMTP_PORT),
    },
    features: {
      flags,
      isEnabled: (flag: string) => flags.includes(flag),
    },
    cors: { origins: raw.CORS_ORIGINS },
  };
}
```

## `src/config/redact.ts`

```ts
// Keys (case-insensitive) whose values must never be logged.
const SENSITIVE_KEYS = new Set([
  "JWT_SECRET",
  "SMTP_PASS",
  "DATABASE_URL", // may contain password
  "REDIS_URL",
  "API_KEY",
  "SECRET",
  "PASSWORD",
  "TOKEN",
]);

export function isSensitiveKey(key: string): boolean {
  const upper = key.toUpperCase();
  if (SENSITIVE_KEYS.has(upper)) return true;
  // catch anything containing secret/password/token
  return /SECRET|PASSWORD|TOKEN|API_KEY|PRIVATE_KEY/i.test(upper);
}

export function redactValue(key: string, value: unknown): unknown {
  if (isSensitiveKey(key)) {
    if (typeof value === "string") {
      if (value.length <= 4) return "***";
      return `${value.slice(0, 2)}…${value.slice(-2)} (redacted)`;
    }
    return "***";
  }
  return value;
}

export function redactObject(obj: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(obj)) {
    out[k] = redactValue(k, v);
  }
  return out;
}
```

## `src/config/load.ts`

```ts
import { config as dotenvConfig } from "dotenv";
import { existsSync } from "node:fs";
import { resolve } from "node:path";
import { ConfigSchema, buildAppConfig, type AppConfig, type RawConfig } from "./schema.js";

export interface LoadOptions {
  /** Override env file search root (defaults to process.cwd()). */
  root?: string;
  /** Force a specific NODE_ENV for file selection (defaults to process.env.NODE_ENV). */
  env?: string;
  /** Skip loading .env files entirely (useful in tests). */
  skipDotenv?: boolean;
}

const ENV_FILES = (env: string) => [
  ".env",
  ".env.local",
  `.env.${env}`,
  `.env.${env}.local`,
];

function loadDotenvFiles(root: string, env: string, skip: boolean): void {
  if (skip) return;

  for (const file of ENV_FILES(env)) {
    const path = resolve(root, file);
    if (existsSync(path)) {
      // dotenv does not override already-set env vars by default when using config()
      // but to get proper precedence (later files win), we parse and apply manually.
      const result = dotenvConfig({ path, override: true });
      if (result.error) {
        throw new Error(`Failed to load ${file}: ${result.error.message}`);
      }
    }
  }
}

/**
 * Load, validate and return the application config.
 * Throws a descriptive error if validation fails.
 */
export function loadConfig(options: LoadOptions = {}): AppConfig {
  const root = options.root ?? process.cwd();
  const env = options.env ?? process.env.NODE_ENV ?? "development";

  // Make NODE_ENV available to dotenv selection even if not yet set.
  process.env.NODE_ENV = process.env.NODE_ENV ?? env;

  loadDotenvFiles(root, env, options.skipDotenv ?? false);

  const parsed = ConfigSchema.safeParse(process.env);
  if (!parsed.success) {
    const issues = parsed.error.issues
      .map((i) => `  - ${i.path.join(".") || "(root)"}: ${i.message}`)
      .join("\n");
    throw new Error(`Invalid configuration:\n${issues}`);
  }

  const raw: RawConfig = parsed.data;
  const appConfig = buildAppConfig(raw);

  // Freeze to prevent accidental mutation at runtime.
  return deepFreeze(appConfig);
}

function deepFreeze<T>(obj: T): T {
  if (obj && typeof obj === "object") {
    Object.freeze(obj);
    for (const v of Object.values(obj as Record<string, unknown>)) {
      deepFreeze(v);
    }
  }
  return obj;
}
```

## `src/config/index.ts`

```ts
import { loadConfig } from "./load.js";
import { redactObject } from "./redact.js";

// Singleton: load once at import time.
// In tests, use loadConfig({ skipDotenv: true }) directly.
export const config = loadConfig();

export { loadConfig } from "./load.js";
export { isSensitiveKey, redactValue, redactObject } from "./redact.js";
export type { AppConfig, RawConfig } from "./schema.js";
export { ConfigSchema, buildAppConfig } from "./schema.js";

// Convenience: a safe, redacted snapshot for logging.
export function configSnapshot(): Record<string, unknown> {
  return redactObject(flattenConfig(config));
}

function flattenConfig(c: unknown, prefix = ""): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  if (c && typeof c === "object") {
    for (const [k, v] of Object.entries(c as Record<string, unknown>)) {
      const key = prefix ? `${prefix}.${k}` : k;
      if (v && typeof v === "object" && !Array.isArray(v) && !(v instanceof Function)) {
        Object.assign(out, flattenConfig(v, key));
      } else if (typeof v !== "function") {
        out[key] = v;
      }
    }
  }
  return out;
}
