import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { loadConfig } from "../src/config/load.js";

describe("loadConfig", () => {
  const originalEnv = { ...process.env };

  beforeEach(() => {
    // Reset to a minimal valid env
    process.env = {
      NODE_ENV: "test",
      DATABASE_URL: "postgres://u:p@localhost:5432/db",
      JWT_SECRET: "a".repeat(40),
    } as NodeJS.ProcessEnv;
  });

  afterEach(() => {
    process.env = originalEnv;
  });

  it("applies defaults", () => {
    const c = loadConfig({ skipDotenv: true });
    expect(c.server.port).toBe(3000);
    expect(c.logLevel).toBe("info");
    expect(c.security.bcryptRounds).toBe(12);
  });

  it("coerces PORT", () => {
    process.env.PORT = "8080";
    const c = loadConfig({ skipDotenv: true });
    expect(c.server.port).toBe(8080);
  });

  it("parses feature flags", () => {
    process.env.FEATURE_FLAGS = "a, b ,,c";
    const c = loadConfig({ skipDotenv: true });
    expect(c.features.flags).toEqual(["a", "b", "c"]);
    expect(c.features.isEnabled("b")).toBe(true);
    expect(c.features.isEnabled("z")).toBe(false);
  });

  it("throws on invalid config", () => {
    process.env.JWT_SECRET = "short";
    expect(() => loadConfig({ skipDotenv: true })).toThrow(/JWT_SECRET/);
  });

  it("throws on missing DATABASE_URL", () => {
    delete process.env.DATABASE_URL;
    expect(() => loadConfig({ skipDotenv: true })).toThrow(/DATABASE_URL/);
  });

  it("env helpers", () => {
    process.env.NODE_ENV = "production";
    const c = loadConfig({ skipDotenv: true });
    expect(c.isProd).toBe(true);
    expect(c.isDev).toBe(false);
  });
