## Final solution (single file)

```ts
// config.ts
export type NodeEnv = "development" | "test" | "production";
export type LogLevel = "debug" | "info" | "warn" | "error";

export interface AppConfig {
  nodeEnv: NodeEnv;
  port: number;
  databaseUrl: string;
  apiKey?: string;
  logLevel: LogLevel;
}

export class ConfigError extends Error {
  constructor(public readonly errors: string[]) {
    super(`Invalid configuration:\n- ${errors.join("\n- ")}`);
    this.name = "ConfigError";
  }
}

function parseEnum<T extends string>(
  name: string,
  value: string | undefined,
  allowed: readonly T[],
  fallback?: T
): T {
  if (value === undefined || value === "") {
    if (fallback !== undefined) return fallback;
    throw new Error(`${name} is required`);
  }
  if (!allowed.includes(value as T)) {
    throw new Error(`${name} must be one of ${allowed.join(", ")}, got "${value}"`);
  }
  return value as T;
}

function parseNumber(name: string, value: string | undefined, fallback?: number): number {
  if (value === undefined || value === "") {
    if (fallback !== undefined) return fallback;
    throw new Error(`${name} is required`);
  }
  const n = Number(value);
  if (!Number.isFinite(n)) {
    throw new Error(`${name} must be a finite number, got "${value}"`);
  }
  return n;
}

function parseRequiredString(name: string, value: string | undefined): string {
  if (!value) throw new Error(`${name} is required`);
  return value;
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const errors: string[] = [];
  const collect = <T>(fn: () => T): T | undefined => {
    try {
      return fn();
    } catch (e) {
      errors.push((e as Error).message);
      return undefined;
    }
  };

  const nodeEnv = collect(() =>
    parseEnum("NODE_ENV", env.NODE_ENV, ["development", "test", "production"], "development")
  );
  const port = collect(() => parseNumber("PORT", env.PORT, 3000));
  const databaseUrl = collect(() => parseRequiredString("DATABASE_URL", env.DATABASE_URL));
  const logLevel = collect(() =>
    parseEnum("LOG_LEVEL", env.LOG_LEVEL, ["debug", "info", "warn", "error"], "info")
  );
  const apiKey = env.API_KEY?.trim() || undefined;

  if (errors.length > 0) throw new ConfigError(errors);

  return {
    nodeEnv: nodeEnv!,
    port: port!,
    databaseUrl: databaseUrl!,
    apiKey,
    logLevel: logLevel!,
  };
}

let cached: AppConfig | undefined;

export function getConfig(): AppConfig {
  if (!cached) cached = loadConfig();
  return cached;
}

export function resetConfigForTests(): void {
  cached = undefined;
}
```

**Notes for real projects**

- Load a `.env` file in development with `dotenv` before calling `getConfig()`.
- Keep secrets out of logs; never print `apiKey` or `databaseUrl` directly.
- If you need more complex validation (URLs, ports range), extend the parsers or adopt `zod`/`envalid`.

## Environment variables & configuration in TypeScript

### 1. Core ideas

- **Environment variables are always strings at runtime.** Even `PORT=3000` arrives as `"3000"`. TypeScript types don’t exist at runtime, so you must **parse + validate** at startup.
- **Fail fast.** Validate all configuration when the process boots. If `DATABASE_URL` is missing, crash immediately with a clear error instead of failing 10 minutes later inside a request handler.
- **Single source of truth.** Define a schema once; derive both the runtime parser and the compile-time TypeScript type from it.
- **Precedence** (typical): CLI args > env vars > `.env.local` / `.env.<env>` > `.env` > code defaults. Never commit secrets; use a secrets manager in production.
- **Secrets hygiene.** Don’t log the whole config object. Mark secret fields or redact them.
- **Environment-specific behavior.** `NODE_ENV` (or `APP_ENV`) drives defaults: dev uses localhost DB, prod requires real URLs, test uses in-memory fixtures.
- **Browser vs server.** In Node, use `process.env`. In Vite/Webpack, only variables prefixed (e.g. `VITE_`, `NEXT_PUBLIC_`) are inlined into the client bundle — never put secrets there.

### 2. Minimal, production-ish implementation

The implementation below:
- declares a schema as a `const` object,
- infers TypeScript types from the schema,
- coerces strings → `number` / `boolean`,
- applies defaults,
- validates required fields,
- supports per-field validation,
- converts `camelCase` keys to `SCREAMING_SNAKE_CASE` env names automatically (override with `env`).

```ts
// config.ts

type EnvScalar = string | number | boolean;
type EnvType = 'string' | 'number' | 'boolean';

interface FieldSpec {
  /** Expected runtime type. */
  type: EnvType;
  /** Environment variable name. Defaults to SCREAMING_SNAKE of the key. */
  env?: string;
  /** Must be present (or have a default). */
  required?: boolean;
  /** Fallback when the env var is missing/empty. */
  default?: EnvScalar;
  /** Custom validation. */
  validate?: (value: EnvScalar) => boolean;
}

type Schema = Record<string, FieldSpec>;

/** Map a field spec to its TS type. */
type FieldType<S extends FieldSpec> =
  S['type'] extends 'number' ? number :
  S['type'] extends 'boolean' ? boolean :
  string;

/** A field is required when marked required OR has a default. */
type IsRequired<S extends FieldSpec> =
  S['required'] extends true ? true :
  S['default'] extends undefined ? false : true;

/** Final config value type per field. */
type ConfigValue<S extends FieldSpec> =
  IsRequired<S> extends true ? FieldType<S> : FieldType<S> | undefined;

/** Config object type derived from schema. */
type ConfigOf<S extends Schema> = { [K in keyof S]: ConfigValue<S[K]> };

class ConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ConfigError';
  }
}

export class Config<S extends Schema> {
  private readonly values: ConfigOf<S>;

  constructor(schema: S, env: NodeJS.ProcessEnv = process.env) {
    this.values = this.load(schema, env) as ConfigOf<S>;
  }

  private load(schema: S, env: NodeJS.ProcessEnv): Record<string, unknown> {
    const result: Record<string, unknown> = {};

    for (const [key, spec] of Object.entries(schema)) {
      const envName = spec.env ?? toEnvName(key);
      const raw = env[envName];

      // Missing or empty value.
      if (raw === undefined || raw === '') {
        if (spec.default !== undefined) {
          result[key] = spec.default;
          continue;
        }
        if (spec.required) {
          throw new ConfigError(
            `Missing required config: ${key} (env: ${envName})`,
          );
        }
        result[key] = undefined;
        continue;
      }

      // Coerce string -> typed value.
      let value: EnvScalar;
      switch (spec.type) {
        case 'number': {
          const n = Number(raw);
          if (!Number.isFinite(n)) {
            throw new ConfigError(`Invalid number for ${key}: "${raw}"`);
          }
          value = n;
          break;
        }
        case 'boolean': {
          if (raw !== 'true' && raw !== 'false') {
            throw new ConfigError(
              `Invalid boolean for ${key}: "${raw}" (use "true"/"false")`,
            );
          }
          value = raw === 'true';
          break;
        }
        default:
          value = raw;
      }

      if (spec.validate && !spec.validate(value)) {
        throw new ConfigError(`Validation failed for ${key}: ${value}`);
      }

      result[key] = value;
    }

    return result;
  }

  get<K extends keyof S>(key: K): ConfigOf<S>[K] {
    return this.values[key as string] as ConfigOf<S>[K];
  }

  /** Debug snapshot. Redact secrets before logging in real apps. */
  toJSON(): ConfigOf<S> {
    return { ...this.values };
  }
}

function toEnvName(key: string): string {
  // camelCase / PascalCase -> SCREAMING_SNAKE_CASE
  return key.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toUpperCase();
}

// ------------------------------------------------------------------
// Usage
// ------------------------------------------------------------------
const schema = {
  port: { type: 'number', default: 3000 },
  nodeEnv: { type: 'string', env: 'NODE_ENV', default: 'development' },
  databaseUrl: { type: 'string', required: true, env: 'DATABASE_URL' },
  enableCache: { type: 'boolean', default: false },
  maxConnections: {
    type: 'number',
    default: 10,
    validate: (v) => typeof v === 'number' && v > 0 && v <= 100,
  },
} as const;

const config = new Config(schema);

// Compile-time: port is number, databaseUrl is string, etc.
const port: number = config.get('port');
console.log('listening on', port);

export { config };
```

### 3. Interview talking points you can add

- **Why not just `process.env.PORT`?** No types, no validation, no defaults, easy typos; also `process.env` is mutable global state.
- **dotenv:** Load `.env` in dev only (`if (process.env.NODE_ENV !== 'production') require('dotenv').config()`), and never in prod where the platform injects env.
- **Schema libraries:** In real projects use **Zod** (or Joi/Valibot) + `zod-to-ts` or `@t3-oss/env-nextjs`; the principle is identical—parse unknown into typed, validated config at the edge.
- **Hot reload vs restart:** Env changes usually require a process restart; don’t mutate `process.env` at runtime to “change config.”
- **Testing:** Inject a fake `env` object into the constructor (as the code allows) instead of monkey-patching `process.env`.
- **Observability:** Expose a `/health` or startup log showing non-secret config (e.g. `nodeEnv`, `port`) to confirm the right environment loaded.

If you want, I can extend this with Zod-based validation, multi-file `.env` loading, or Next.js/Vite-specific patterns.

# Edge cases when using environment variables & configuration in TypeScript

Environment variables are **always strings** (or `undefined`) at runtime, but TypeScript types can lie. Most bugs come from trusting types, implicit coercion, bundler quirks, and late validation.

Below are the important edge cases, each with idiomatic TypeScript.

---

## 1. “Typed but missing” — `process.env` types vs runtime reality

```ts
// env.d.ts
declare global {
  namespace NodeJS {
    interface ProcessEnv {
      DATABASE_URL: string; // looks non-optional
      PORT?: string;
    }
  }
}
export {};
```

```ts
// ❌ compiles, crashes at runtime
const url = process.env.DATABASE_URL.toUpperCase(); // undefined.toUpperCase()
```

**Fix: validate at startup (fail fast).**

```ts
function required(name: string): string {
  const v = process.env[name];
  if (typeof v !== 'string' || v.trim() === '') {
    throw new Error(`Missing/empty required env: ${name}`);
  }
  return v.trim();
}

const DATABASE_URL = required('DATABASE_URL');
```

---

## 2. String coercion traps

Env vars are strings; naive conversion produces `NaN`, `false`-as-truthy, etc.

```ts
const port = Number(process.env.PORT);          // NaN if missing/empty
const debug = Boolean(process.env.DEBUG);       // "false" → true!
const timeout = parseInt(process.env.TIMEOUT); // NaN
```

**Fix: typed coercion helpers.**

```ts
function num(name: string, fallback?: number): number {
  const raw = process.env[name];
  if (raw === undefined || raw.trim() === '') {
    if (fallback !== undefined) return fallback;
    throw new Error(`Missing env ${name}`);
  }
  const n = Number(raw);
  if (!Number.isFinite(n)) throw new Error(`Invalid number for ${name}: ${raw}`);
  return n;
}

function bool(name: string, fallback = false): boolean {
  const raw = process.env[name]?.trim().toLowerCase();
  if (raw === undefined || raw === '') return fallback;
  if (raw === 'true' || raw === '1' || raw === 'yes') return true;
  if (raw === 'false' || raw === '0' || raw === 'no') return false;
  throw new Error(`Invalid boolean for ${name}: ${raw}`);
}
```

---

## 3. Schema validation with Zod (recommended)

```ts
import { z } from 'zod';

const EnvSchema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  PORT: z.coerce.number().int().positive().default(3000),
  DATABASE_URL: z.string().url(),
  DEBUG: z
    .string()
    .optional()
    .transform((v) => v === 'true' || v === '1'),
  ALLOWED_ORIGINS: z
    .string()
    .default('')
    .transform((s) => s.split(',').map((x) => x.trim()).filter(Boolean)),
  JWT_SECRET: z.string().min(32),
  FEATURES: z
    .string()
    .optional()
    .transform((s) => (s ? s.split(',').map((x) => x.trim()) : [])),
});

export type Env = z.infer<typeof EnvSchema>;

// Throws at import time if invalid → fail fast
export const env: Env = EnvSchema.parse(process.env);
```

**Edge cases handled:**
- Empty string defaults
- Boolean coercion via explicit transform (not `z.coerce.boolean()`, which makes `"false"` truthy)
- Lists split on commas, trimmed, empties removed
- Type inference (`Env`)

---

## 4. `z.coerce.boolean()` trap

```ts
// ❌ "false" becomes true
z.coerce.boolean().parse('false'); // true
```

Always use explicit transform for booleans (see above).

---

## 5. Empty string vs missing (`undefined`)

Many validators treat `''` differently from `undefined`.

```ts
// ❌ empty DATABASE_URL passes .string() but breaks pg driver
z.string().parse(''); 

// ✅ reject empties for required secrets
z.string().min(1).url();
```

Also normalize:

```ts
function emptyToUndefined<T extends string | undefined>(v: T): T | undefined {
  return v === '' ? undefined : v;
}
```

---

## 6. `.env` loading location & monorepos

`dotenv` resolves relative to `process.cwd()`, not the file importing it.

```ts
import dotenv from 'dotenv';
import path from 'node:path';

dotenv.config({
  path: path.resolve(process.cwd(), '.env'),
  override: false, // don't clobber real env vars
});
```

**Edge cases:**
- Running from a different cwd (`node apps/api/dist/index.js` from repo root)
- Multiple env files: `.env`, `.env.local`, `.env.test`
- Precedence: real env > `.env.local` > `.env`

```ts
for (const f of ['.env', '.env.local', `.env.${process.env.NODE_ENV}`]) {
  dotenv.config({ path: path.resolve(process.cwd(), f), override: false });
}
```

---

## 7. JSON in environment variables

```ts
function parseJsonEnv<T>(name: string, fallback: T): T {
  const raw = process.env[name];
  if (raw === undefined || raw.trim() === '') return fallback;
  try {
    return JSON.parse(raw) as T;
  } catch (e) {
    throw new Error(`Invalid JSON in ${name}: ${(e as Error).message}`);
  }
}

const features = parseJsonEnv<{ darkMode: boolean }>('FEATURE_FLAGS', { darkMode: false });
```

**Edge cases:**
- Trailing commas invalid in JSON
- Single quotes invalid
- Large JSON hits OS env size limits (~128KB on Linux)
- Newlines in values (must be quoted in `.env`)

---

## 8. Lists, paths, and quoting

```ts
// .env
ALLOWED_ORIGINS="https://a.com, https://b.com"
PATHS=/a,/b   # no spaces unless quoted
```

```ts
const origins = (process.env.ALLOWED_ORIGINS ?? '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);
```

**Edge case:** values with commas inside (e.g., base64) — don’t split naively; use JSON array instead.

---

## 9. Base64 secrets

```ts
function base64Env(name: string): Buffer {
  const raw = required(name);
  const buf = Buffer.from(raw, 'base64');
  if (buf.toString('base64').replace(/=+$/, '') !== raw.replace(/=+$/, '')) {
    throw new Error(`${name} is not valid base64`);
  }
  return buf;
}
```

---

## 10. URL validation & defaults

```ts
const RedisUrl = z.string().url().refine((u) => {
  const parsed = new URL(u);
  return parsed.protocol === 'redis:' || parsed.protocol === 'rediss:';
}, 'Must be redis:// or rediss://');
```

---

## 11. Client bundles vs server (Vite / Next / Webpack)

**Vite:** only `VITE_`-prefixed vars are exposed; accessed via `import.meta.env`.

```ts
// vite-env.d.ts
interface ImportMetaEnv {
  readonly VITE_API_URL: string;
  readonly VITE_APP_TITLE?: string;
}
interface ImportMeta {
  readonly env: ImportMetaEnv;
}

const apiUrl = import.meta.env.VITE_API_URL; // string (per our declaration)
```

**Edge cases:**
- `process.env` does not exist in browser
- Vars are **inlined at build time** — changing env requires rebuild
- Secrets prefixed with `VITE_` leak to client bundle
- `import.meta.env.MODE`, `DEV`, `PROD` are built-in and boolean-ish

**Next.js:** `NEXT_PUBLIC_` for client; everything else server-only. Never destructure in shared modules.

---

## 12. Build-time inlining of `process.env.X`

Bundlers (Webpack, esbuild) may statically replace `process.env.NODE_ENV`.

```ts
if (process.env.NODE_ENV === 'production') {
  // bundler may drop this branch entirely in prod builds
}
```

**Edge case:** Never mutate `process.env` expecting runtime changes in bundled code; it may be replaced at build time.

---

## 13. `NODE_ENV` misuse

```ts
const isProd = process.env.NODE_ENV === 'production';
```

**Edge cases:**
- Typos (`'prod'`, `'Production'`) → silently dev mode
- Frameworks (Next/Vite) set their own; don’t override manually
- Use exact string comparison, not truthiness

---

## 14. Mutation & global state

```ts
// ❌ mutating process.env couples modules
process.env.API_URL = 'https://...';
```

**Fix:** build an immutable config object once.

```ts
export const config = Object.freeze({
  port: env.PORT,
  dbUrl: env.DATABASE_URL,
  isProd: env.NODE_ENV === 'production',
} as const);
```

---

## 15. Config precedence (env > file > defaults)

```ts
function withPrecedence<T>(envVal: T | undefined, fileVal: T | undefined, def: T): T {
  if (envVal !== undefined) return envVal;
  if (fileVal !== undefined) return fileVal;
  return def;
}
```

Read config files lazily and merge, then validate the final object.

---

## 16. Validation at startup (fail fast)

```ts
// config.ts
import { z } from 'zod';

const Schema = z.object({ ... });

function loadConfig() {
  const parsed = Schema.safeParse(process.env);
  if (!parsed.success) {
    console.error('Invalid configuration:');
    console.error(parsed.error.flatten().fieldErrors);
    process.exit(1); // fail fast in Node
  }
  return parsed.data;
}

export const config = loadConfig();
```

**Edge case:** In serverless/edge, `process.exit` may not exist — throw instead and let the runtime fail the cold start.

---

## 17. Secrets hygiene

- Never log full config; redact secrets.
- `.env` in `.gitignore`, commit `.env.example`.
- Don’t put secrets in client bundles (see §11).
- Rotate & validate length/entropy.

```ts
function redact(config: Record<string, unknown>): Record<string, unknown> {
  const out = { ...config };
  for (const k of Object.keys(out)) {
    if (/secret|password|token|key/i.test(k)) out[k] = '[REDACTED]';
  }
  return out;
}
```

---

## 18. Testing environment variables

```ts
import { afterEach } from 'node:test';

const saved = { ...process.env };
afterEach(() => {
  // reset to avoid cross-test leakage
  for (const k of Object.keys(process.env)) delete process.env[k];
  Object.assign(process.env, saved);
});
```

**Edge cases:**
- Modules caching `config` at import time — tests can’t override without module reset (`vi.resetModules()`).
- Use dependency injection / accept config as param instead of reading `process.env` deep in code.

---

## 19. Cross-runtime differences (Node vs Deno vs Bun)

```ts
// Node
process.env.FOO;

// Deno
Deno.env.get('FOO');

// Bun
Bun.env.FOO; // or process.env
```

Abstract behind a small interface for portable libs.

---

## 20. `env-var` / typed env libraries

For stricter parsing without Zod boilerplate:

```ts
import env from 'env-var';

export const PORT = env.get('PORT').default('3000').asPortNumber();
export const DB = env.get('DATABASE_URL').required().asUrlString();
export const DEBUG = env.get('DEBUG').default('false').asBoolStrict();
```

`asBoolStrict` rejects `"false"` ambiguity better than loose coercion.

---

## 21. Configuration objects: immutability & freezing

```ts
const cfg = {
  port: 3000,
  cors: { origins: ['https://a.com'] },
} as const;

// Still mutable nested! Use deep freeze or readonly types
type DeepReadonly<T> = { readonly [K in keyof T]: T[K] extends object ? DeepReadonly<T[K]> : T[K] };
```

---

## 22. Defaults that depend on other values

```ts
const base = env.DATABASE_URL;
const readReplica = process.env.DATABASE_READ_URL ?? base; // fallback chain
```

Validate the resolved chain, not each raw var.

---

## 23. OS-level limits & encoding

- Max env size ~128KB total on Linux; individual ~32KB.
- No embedded NUL bytes; some shells strip them.
- Use UTF-8; base64 for binary.

---

## 24. CI/CD injection quirks

- GitHub Actions: secrets with newlines → use base64.
- Docker: `ENV` persists; `ARG` build-only. Don’t bake secrets into image layers.
- Kubernetes: configmaps vs secrets; mount as env or files.

---

## Summary checklist

| Edge case | Mitigation |
|---|---|
| Type says string, runtime undefined | Startup validation, `required()` |
| `"false"` truthy | Explicit bool transform |
| Empty string | `.min(1)` / normalize |
| NaN ports | `Number.isFinite` checks |
| `.env` wrong cwd | Resolve absolute path |
| Client leakage | Prefix rules, audit bundles |
| Build-time inlining | Don’t rely on runtime mutation |
| Tests leaking | Reset `process.env`, reset modules |
| Secrets logging | Redact by key pattern |
| JSON env | Try/catch + size limits |

Use **Zod (or `env-var`) + a single validated `config` module imported by the app** — that resolves ~90% of these.

Below is a complete, runnable TypeScript example that demonstrates a production-style approach to errors and exceptions. It covers custom error classes, normalization of unknown values, `try/catch/finally`, async/await, `Promise.allSettled`, a `Result` type alternative, validation errors, error cause chaining, and exhaustiveness checking.

Save as `errors.ts` and run with:

```bash
npx tsx errors.ts
# or: bun run errors.ts
# or: deno run errors.ts
```

```ts
// errors.ts

// ---------- Result type (functional alternative to exceptions) ----------

type Result<T, E = Error> =
  | { ok: true; value: T }
  | { ok: false; error: E };

const ok = <T>(value: T): Result<T, never> => ({ ok: true, value });
const err = <E>(error: E): Result<never, E> => ({ ok: false, error });

// ---------- Error codes ----------

type ErrorCode = "NOT_FOUND" | "VALIDATION" | "UNEXPECTED";

// ---------- Custom error hierarchy ----------

class AppError extends Error {
  readonly code: ErrorCode;
  readonly status: number;

  constructor(
    message: string,
    opts: { code: ErrorCode; status?: number; cause?: unknown }
  ) {
    super(message, { cause: opts.cause });
    this.name = this.constructor.name;
    this.code = opts.code;
    this.status = opts.status ?? 500;

    // Preserve prototype chain when targeting ES5/older runtimes.
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

class NotFoundError extends AppError {
  constructor(resource: string, id: string) {
    super(`${resource} not found: ${id}`, {
      code: "NOT_FOUND",
      status: 404,
    });
  }
}

class ValidationError extends AppError {
  readonly fields: Record<string, string[]>;

  constructor(fields: Record<string, string[]>) {
    super("Validation failed", { code: "VALIDATION", status: 400 });
    this.fields = fields;
  }
}

// ---------- Type guards and normalization ----------

function isAppError(e: unknown): e is AppError {
  return e instanceof AppError;
}

/**
 * Normalize any thrown value into an AppError.
 * Important: `catch (e)` is `unknown` under strict TS, so never assume `e` is Error.
 */
function toAppError(e: unknown): AppError {
  if (e instanceof AppError) return e;

  if (e instanceof Error) {
    return new AppError(e.message, {
      code: "UNEXPECTED",
      status: 500,
      cause: e,
    });
  }

  return new AppError(String(e), {
    code: "UNEXPECTED",
    status: 500,
    cause: e,
  });
}

// ---------- Async helper: try/catch without throwing ----------

async function tryCatch<T>(
  fn: () => Promise<T>
): Promise<Result<T, AppError>> {
  try {
    return ok(await fn());
  } catch (e) {
    return err(toAppError(e));
  }
}

// ---------- Exhaustiveness helper ----------

function assertNever(x: never): never {
  throw new Error(`Unhandled case: ${String(x)}`);
}

// ---------- Domain example ----------

interface User {
  id: string;
  email: string;
  age: number;
}

const db = new Map<string, User>();
let idCounter = 0;
const newId = () => `u_${++idCounter}`;

function validateEmail(email: string): string[] {
  const errors: string[] = [];
  if (!email.includes("@")) errors.push("must contain @");
  if (email.length < 3) errors.push("too short");
  return errors;
}

async function createUser(input: {
  email: string;
  age: number;
}): Promise<User> {
  const fields: Record<string, string[]> = {};

  const emailErrors = validateEmail(input.email);
  if (emailErrors.length) fields.email = emailErrors;

  if (input.age < 0 || input.age > 150) {
    fields.age = ["must be between 0 and 150"];
  }

  if (Object.keys(fields).length > 0) {
    throw new ValidationError(fields);
  }

  const user: User = {
    id: newId(),
    email: input.email,
    age: input.age,
  };

  db.set(user.id, user);
  return user;
}

async function getUser(id: string): Promise<User> {
  const user = db.get(id);
  if (!user) throw new NotFoundError("User", id);
  return user;
}

// ---------- Main demonstration ----------

async function main() {
  console.log("=== 1. Validation error via Result ===");
  const r1 = await tryCatch(() =>
    createUser({ email: "bad", age: -1 })
  );

  if (!r1.ok) {
    const e = r1.error;
    if (e instanceof ValidationError) {
      console.log("Validation fields:", e.fields);
    } else {
      console.log("Other error:", e.code, e.message);
    }
  }

  console.log("\n=== 2. Success ===");
  const r2 = await tryCatch(() =>
    createUser({ email: "alice@example.com", age: 30 })
  );

  if (!r2.ok) {
    console.error("Unexpected failure:", r2.error);
    return;
  }
  const user = r2.value;
  console.log("Created user:", user);

  console.log("\n=== 3. Not found via Result ===");
  const r3 = await tryCatch(() => getUser("missing"));
  if (!r3.ok) {
    console.log("Expected not found:", r3.error.code, r3.error.message);
  }

  console.log("\n=== 4. try/catch/finally with normalization and rethrow ===");
  let released = false;
  try {
    await getUser("missing");
  } catch (e) {
    // e is `unknown` here in strict mode
    const ae = toAppError(e);
    console.log("Caught and normalized:", ae.code, ae.message);

    if (ae.code === "NOT_FOUND") {
      // Graceful handling
      console.log("Handled 404 gracefully");
    } else {
      throw ae; // rethrow unexpected errors
    }
  } finally {
    released = true;
  }
  console.log("finally released:", released);

  console.log("\n=== 5. Promise.allSettled ===");
  const results = await Promise.allSettled([
    getUser(user.id),
    getUser("nope"),
  ]);

  for (const r of results) {
    if (r.status === "fulfilled") {
      console.log("Found:", r.value.id);
    } else {
      console.log("Rejected:", toAppError(r.reason).code);
    }
  }

  console.log("\n=== 6. Error cause chaining ===");
  try {
    try {
      JSON.parse("{bad json");
    } catch (inner) {
      throw new AppError("Failed to parse config", {
        code: "UNEXPECTED",
        status: 500,
        cause: inner,
      });
    }
  } catch (e) {
    const ae = toAppError(e);
    console.log("Outer:", ae.message);
    console.log("Cause:", ae.cause instanceof Error ? ae.cause.message : ae.cause);
  }

  console.log("\n=== 7. Exhaustive status mapping ===");
  function httpStatus(code: ErrorCode | "OK"): number {
    switch (code) {
      case "OK":
        return 200;
      case "NOT_FOUND":
        return 404;
      case "VALIDATION":
        return 400;
      case "UNEXPECTED":
        return 500;
      default:
        return assertNever(code);
    }
  }

  console.log("status(NOT_FOUND) =", httpStatus("NOT_FOUND"));
  console.log("status(OK) =", httpStatus("OK"));
}

// Top-level boundary: convert anything to a normalized error.
main().catch((e) => {
  const ae = toAppError(e);
  console.error("Fatal:", ae.code, ae.message);
  if (ae.cause) console.error("Cause:", ae.cause);
  process.exitCode = 1;
});
```

### What this demonstrates

- **Custom error classes** with `code`, `status`, and `name`, extending `Error` and preserving `cause`.
- **`unknown`-safe catch blocks**: `catch (e)` is `unknown` under strict TS, so `toAppError` normalizes anything.
- **`Result<T, E>` pattern**: avoids throwing for expected failures and makes error handling explicit at call sites.
- **`tryCatch` helper**: wraps async work into a `Result`, keeping `try/catch` localized.
- **Validation aggregation**: multiple field errors collected into one `ValidationError`.
- **Re-throwing**: unexpected errors are rethrown after normalization.
- **`finally`**: cleanup always runs.
- **`Promise.allSettled`**: handles partial failures without short-circuiting.
- **Error cause chaining**: using the standard `cause` option.
- **Exhaustiveness checking**: `assertNever` ensures all error codes are handled.

### Practical tips

- Enable `strict: true` and `useUnknownInCatchVariables: true` in `tsconfig.json`.
- At application boundaries (HTTP handlers, CLI entrypoints), catch once and convert with `toAppError`.
- Prefer `Result` for expected domain failures; reserve exceptions for truly exceptional conditions.
- Avoid swallowing errors; always log or propagate with context.

# Error Handling & Exceptions in TypeScript

## 1. Core idea

TypeScript follows JavaScript’s exception model: an error is an **object thrown at runtime** that unwinds the call stack until something catches it. TypeScript adds **static typing** around *where* and *how* you catch and propagate errors, but the runtime behavior is still JS.

Two philosophies coexist:

| Approach | When to use |
|---|---|
| **Exceptions (`throw`/`try…catch`)** | Unexpected, exceptional failures (network down, parse failure, invariant violation). |
| **Result / discriminated-union types** | Expected, recoverable outcomes (validation errors, “not found”, user input). |

Most real codebases mix both.

---

## 2. Basic syntax

### `throw`

Any value can be thrown, but **always throw `Error` instances** (or subclasses) so stack traces and `instanceof` work.

```ts
function divide(a: number, b: number): number {
  if (b === 0) throw new Error("Division by zero");
  return a / b;
}
```

### `try / catch / finally`

```ts
try {
  const r = divide(10, 0);
  console.log(r);
} catch (err) {
  // err is `unknown` under strict mode (TS 4.4+)
  if (err instanceof Error) {
    console.error(err.message);
  } else {
    console.error("Unknown thrown value:", err);
  }
} finally {
  console.log("cleanup runs always");
}
```

> **Important (TS 4.4+):** With `useUnknownInCatchVariables: true` (default under `strict`), `err` is `unknown`, not `any`. You must narrow before using `.message`.

### Rethrowing

```ts
catch (err) {
  if (err instanceof Error && err.message.includes("network")) {
    throw err; // propagate
  }
  throw new Error("Unexpected failure", { cause: err }); // wrap, preserve cause
}
```

`{ cause }` (ES2022) is supported in modern TS targets and keeps the original error attached.

---

## 3. Custom error classes

Subclass `Error` and set `name` + `prototype` (or use `Object.setPrototypeOf` for older targets).

```ts
class ValidationError extends Error {
  constructor(public field: string, message: string) {
    super(message);
    this.name = "ValidationError";
    // Fix prototype chain when targeting ES5
    Object.setPrototypeOf(this, ValidationError.prototype);
  }
}

function parseAge(input: string): number {
  const n = Number(input);
  if (!Number.isInteger(n) || n < 0) {
    throw new ValidationError("age", `Invalid age: ${input}`);
  }
  return n;
}

try {
  parseAge("abc");
} catch (err) {
  if (err instanceof ValidationError) {
    console.log(err.field, err.message); // field-aware handling
  }
}
```

---

## 4. Async error handling

### Promises

```ts
fetch("/api")
  .then(r => r.json())
  .catch((err: unknown) => {
    if (err instanceof Error) console.error(err.message);
  });
```

### `async/await` (preferred)

```ts
async function loadUser(id: string): Promise<User> {
  const res = await fetch(`/users/${id}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json() as Promise<User>;
}

async function main() {
  try {
    const u = await loadUser("42");
  } catch (err) {
    // narrow as above
  }
}
```

Unhandled rejections become uncaught exceptions in Node / browsers; always attach `.catch` or wrap in `try/await`.

---

## 5. Type-safe error narrowing helpers

Because `catch` gives `unknown`, centralize narrowing:

```ts
function toError(err: unknown): Error {
  if (err instanceof Error) return err;
  if (typeof err === "string") return new Error(err);
  return new Error("Unknown error", { cause: err });
}

try { ... }
catch (err) { const e = toError(err); logger.error(e); }
```

### Assertion functions

TS supports *assertion functions* that narrow types via `asserts`:

```ts
function assert(condition: unknown, msg = "Assertion failed"): asserts condition {
  if (!condition) throw new Error(msg);
}

function process(x: string | null) {
  assert(x !== null, "x required");
  // x is now `string`
  console.log(x.toUpperCase());
}
```

---

## 6. Result type pattern (no exceptions for expected failures)

For domain logic, prefer returning a tagged union instead of throwing:

```ts
type Result<T, E = Error> =
  | { ok: true; value: T }
  | { ok: false; error: E };

function parseEmail(s: string): Result<string, ValidationError> {
  if (!s.includes("@")) {
    return { ok: false, error: new ValidationError("email", "bad format") };
  }
  return { ok: true, value: s.trim().toLowerCase() };
}

const r = parseEmail("a@b.com");
if (r.ok) console.log(r.value);
else console.log(r.error.message);
```

Benefits: exhaustive handling via `switch`/`if`, no hidden control flow, easier testing.

---

## 7. Top-level & module boundaries

- **Entry points** (route handlers, CLI main, React error boundaries) should catch and convert errors to user-facing messages / HTTP responses.
- **Libraries** should document thrown errors and prefer Result types for recoverable cases.
- Use `process.on("uncaughtException")` / `unhandledRejection` only as last-resort logging, then exit.

```ts
process.on("unhandledRejection", (reason) => {
  console.error("Unhandled rejection:", reason);
  process.exit(1);
});
```

---

## 8. Common pitfalls & best practices

| Pitfall | Fix |
|---|---|
| `throw "string"` | Throw `new Error(...)` |
| Catching `any` and accessing `.message` blindly | Narrow `unknown` first |
| Swallowing errors (`catch {}`) | At least log; rethrow or return Result |
| Throwing for control flow in hot paths | Use Result / boolean checks |
| Forgetting `Object.setPrototypeOf` in ES5 targets | Add it (or target ES2015+) |
| Mixing sync throw with async code | Wrap sync code or use `Promise.resolve().then` |

---

## 9. Quick reference snippet

```ts
// custom error
class HttpError extends Error {
  constructor(public status: number, message: string) {
    super(message);
    this.name = "HttpError";
    Object.setPrototypeOf(this, HttpError.prototype);
  }
}

// throwing + wrapping
async function getJson<T>(url: string): Promise<T> {
  let res: Response;
  try {
    res = await fetch(url);
  } catch (err) {
    throw new HttpError(0, "Network failure", { cause: toError(err) });
  }
  if (!res.ok) throw new HttpError(res.status, res.statusText);
  return res.json() as Promise<T>;
}

// consumer
try {
  await getJson("/api");
} catch (err) {
  const e = toError(err);
  if (e instanceof HttpError && e.status === 404) console.log("not found");
  else console.error(e);
}
```

---

**Summary:** Use `throw`/`try…catch` for truly exceptional failures, narrow `unknown` catch variables, subclass `Error` for domain errors, preserve causes, and prefer Result types for expected, recoverable outcomes. Wrap async boundaries and never swallow errors silently.

## Mistake

```ts
// mistake.ts
import { promises as fs } from 'node:fs';

async function readConfig(path: string): Promise<string | null> {
  try {
    const data = await fs.readFile(path, 'utf8');
    return data;
  } catch (err) {
    // "Handle" the error by logging and returning null.
    console.error('Failed to read config:', err);
    return null;
  }
}

// Caller
const cfg = await readConfig('/etc/app/config.json');
console.log(cfg!.toUpperCase()); // 💥 null dereference at runtime
```

### What’s wrong

1. **The error is swallowed.** Returning `null` erases the distinction between “file missing”, “permission denied”, “disk I/O failure”, and “invalid encoding”. The caller cannot react appropriately (e.g., create a default config vs. fail startup).
2. **The type signature lies.** `Promise<string | null>` promises the caller a value or `null`, but it never communicates *why* it’s null. The `!` non-null assertion then crashes at runtime.
3. **`err` is `unknown` (TS ≥ 4.4).** Logging it is fine, but treating it as a string/`Error` without narrowing would be a type error; here we avoid that only by coincidence.
4. **No causal chain.** If a higher layer wants to report “config load failed”, the original stack/errno is lost.

---

## Corrected version

```ts
// corrected.ts
import { promises as fs } from 'node:fs';

class ConfigNotFoundError extends Error {
  constructor(public readonly path: string, options?: ErrorOptions) {
    super(`Config not found: ${path}`, options);
    this.name = 'ConfigNotFoundError';
  }
}

class ConfigReadError extends Error {
  constructor(public readonly path: string, options?: ErrorOptions) {
    super(`Failed to read config: ${path}`, options);
    this.name = 'ConfigReadError';
  }
}

async function readConfig(path: string): Promise<string> {
  try {
    return await fs.readFile(path, 'utf8');
  } catch (err: unknown) {
    // Narrow the unknown error before inspecting it.
    if (err instanceof Error && 'code' in err && (err as NodeJS.ErrnoException).code === 'ENOENT') {
      throw new ConfigNotFoundError(path, { cause: err });
    }
    throw new ConfigReadError(path, { cause: err });
  }
}

// Caller: handle explicitly, no non-null assertions.
try {
  const cfg = await readConfig('/etc/app/config.json');
  console.log(cfg.toUpperCase());
} catch (err) {
  if (err instanceof ConfigNotFoundError) {
    console.warn('No config found; using defaults.');
  } else {
    console.error('Unexpected failure loading config:', err);
    process.exit(1);
  }
}
```

### Why this is better

- **Errors propagate with meaning.** The caller can branch on `ConfigNotFoundError` vs. `ConfigReadError` instead of guessing from `null`.
- **Type safety.** `readConfig` returns `Promise<string>`; no `!` assertions and no silent `null`.
- **`cause` preserves the original.** Node’s `ENOENT` errno and stack remain attached for debugging/logging.
- **`err: unknown` is narrowed.** We check `instanceof Error` and the `code` property before casting, avoiding unsafe assumptions about arbitrary thrown values (including non-Error throws).
- **No swallowed failures.** If reading fails for an unexpected reason, the process fails loudly instead of continuing with a bogus `null`.

### Alternative: Result type

If you prefer not to throw, return a discriminated union instead of `null`:

```ts
type Result<T, E = Error> =
  | { ok: true; value: T }
  | { ok: false; error: E };

async function readConfig(path: string): Promise<Result<string>> {
  try {
    const data = await fs.readFile(path, 'utf8');
    return { ok: true, value: data };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err : new Error(String(err)) };
  }
}
```

Either approach is fine; the key is **never lose the error’s identity** by collapsing it into `null`/`undefined`.

## Common TypeScript error-handling pitfalls

Below are the pitfalls I see most often, each with bad vs. good code. Examples assume `strict: true` in `tsconfig.json`.

---

### 1. Throwing non-`Error` values

Primitives/objects lose the stack trace and break `instanceof Error` checks.

```ts
// ❌ Bad
throw "user not found";
throw { code: 404, msg: "not found" };

// ✅ Good
throw new Error("user not found");
```

If you need structured data, subclass `Error` (see #2) rather than throwing a plain object.

---

### 2. Custom error classes with a broken prototype chain

With downlevel targets (ES5/ES2015) or some bundlers, `instanceof` can fail unless you repair the prototype.

```ts
// ❌ Bad (instanceof may be false after transpilation)
class NotFoundError extends Error {
  constructor(message: string) {
    super(message);
  }
}

// ✅ Good
class NotFoundError extends Error {
  readonly code = "NOT_FOUND" as const;
  constructor(message: string) {
    super(message);
    this.name = "NotFoundError";
    Object.setPrototypeOf(this, NotFoundError.prototype);
  }
}
```

Always set `name` for readable stack traces and logs.

---

### 3. Casting `catch` variables to `any`

Since TS 4.4, `catch (e)` is `unknown` under `useUnknownInCatchVariables`. Casting to `any` defeats that safety.

```ts
// ❌ Bad
try {
  await loadUser(id);
} catch (e: any) {
  console.log(e.message); // runtime crash if e is a string
}

// ✅ Good
try {
  await loadUser(id);
} catch (e) {
  if (e instanceof Error) {
    console.error(e.message);
  } else {
    console.error("Unknown error:", e);
  }
}
```

A small helper keeps call sites clean:

```ts
function toError(e: unknown): Error {
  return e instanceof Error ? e : new Error(String(e));
}
```

---

### 4. Swallowing errors in empty `catch` blocks

Silent failures make debugging nearly impossible.

```ts
// ❌ Bad
try {
  await saveOrder(order);
} catch {
  // ignored
}

// ✅ Good: at least log, or rethrow with context
try {
  await saveOrder(order);
} catch (e) {
  logger.error({ err: toError(e), orderId: order.id }, "saveOrder failed");
  throw toError(e);
}
```

---

### 5. Rethrowing without preserving the original cause

Creating a new error discards the original stack/cause unless you link them.

```ts
// ❌ Bad
try {
  await fetchUser(id);
} catch {
  throw new Error("failed to load user");
}

// ✅ Good (ES2022 Error.cause)
try {
  await fetchUser(id);
} catch (e) {
  throw new Error("failed to load user", { cause: e });
}
```

When logging, walk `error.cause` recursively.

---

### 6. Using exceptions for expected control flow

Throwing for “not found” / “invalid input” that callers expect forces expensive stack capture and awkward try/catch at every call site.

```ts
// ❌ Bad
function getUser(id: string): User {
  const u = db.find(id);
  if (!u) throw new NotFoundError("missing");
  return u;
}

// ✅ Good: return a Result/Option or null for expected cases
type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

function getUser(id: string): Result<User, "not_found"> {
  const u = db.find(id);
  return u ? { ok: true, value: u } : { ok: false, error: "not_found" };
}
```

Reserve `throw` for truly exceptional/unexpected failures.

---

### 7. `return` in `finally` masking thrown errors

A `return` (or `throw`) in `finally` overrides the original exception.

```ts
// ❌ Bad: the thrown error is lost
function load() {
  try {
    throw new Error("boom");
  } finally {
    return "ok"; // masks "boom"
  }
}

// ✅ Good: finally only cleans up
function load2() {
  let handle: Handle | undefined;
  try {
    handle = openHandle();
    throw new Error("boom");
  } finally {
    handle?.close(); // no return here
  }
}
```

---

### 8. Synchronous `try/catch` around async work

A missing `await` means the rejection escapes the `try` block.

```ts
// ❌ Bad
try {
  doAsyncWork(); // returns a promise; throw happens later
} catch (e) {
  // never runs for the async failure
}

// ✅ Good
try {
  await doAsyncWork();
} catch (e) {
  handle(e);
}
```

Also remember: `forEach` callbacks that throw don’t propagate out of the surrounding function cleanly; prefer `for...of` with `await`.

---

### 9. `Promise.all` failing fast and losing sibling errors

One rejection discards the rest; you can’t tell which failed.

```ts
// ❌ Bad
const [a, b] = await Promise.all([fetchA(), fetchB()]);

// ✅ Good
const results = await Promise.allSettled([fetchA(), fetchB()]);
for (const r of results) {
  if (r.status === "rejected") {
    console.error("one failed:", r.reason);
  }
}
```

---

### 10. Relying on `instanceof` across realms/bundles

`instanceof` can be false for errors created in another iframe, worker, or duplicate module instance.

```ts
// ❌ Fragile
if (err instanceof NotFoundError) { ... }

// ✅ More robust: duck-type on a stable `code`/`name`
function isNotFoundError(e: unknown): e is NotFoundError {
  return (
    e instanceof Error &&
    (e as { code?: unknown }).code === "NOT_FOUND"
  );
}
```

For cross-realm safety, prefer checking `e?.name === "NotFoundError"` and a `code` field rather than prototype identity.

---

### 11. Serializing `Error` objects (they become `{}`)

`JSON.stringify(new Error("boom"))` yields `{}` because `message`/`stack` are non-enumerable.

```ts
// ❌ Bad
res.status(500).json({ error: err }); // {}

// ✅ Good
res.status(500).json({
  name: err.name,
  message: err.message,
  stack: process.env.NODE_ENV === "production" ? undefined : err.stack,
  cause: err.cause,
});
```

Or write a dedicated serializer that walks `cause`.

---

### 12. Not distinguishing operational vs. programmer errors

Treating a bug (e.g., `TypeError: Cannot read properties of undefined`) like a normal 400/404 leads to wrong HTTP status codes and retry behavior.

```ts
// ❌ Bad: everything becomes 500 or everything becomes 400
app.use((err, req, res, next) => {
  res.status(400).json({ message: err.message });
});

// ✅ Good: classify
class HttpError extends Error {
  constructor(public status: number, message: string) {
    super(message);
    this.name = "HttpError";
    Object.setPrototypeOf(this, HttpError.prototype);
  }
}

app.use((err: unknown, req: any, res: any, next: any) => {
  if (err instanceof HttpError) {
    res.status(err.status).json({ message: err.message });
  } else {
    logger.error(err);
    res.status(500).json({ message: "Internal Server Error" });
  }
});
```

---

### 13. Throwing inside callbacks/event emitters

A `throw` inside a callback isn’t caught by the surrounding `try/catch`; in Node it can crash the process or become an unhandled rejection.

```ts
// ❌ Bad
try {
  emitter.on("data", (x) => {
    if (!x) throw new Error("bad data"); // uncaught
  });
} catch {}

// ✅ Good: emit an "error" event or handle locally
emitter.on("data", (x) => {
  if (!x) {
    emitter.emit("error", new Error("bad data"));
    return;
  }
  handle(x);
});
emitter.on("error", (e) => logger.error(e));
```

---

### 14. Forgetting unhandled-rejection / uncaught-exception handlers

In Node, unhandled promise rejections terminate the process (by default in recent versions).

```ts
// ✅ Add process-level safety nets (last resort, not a substitute for handling)
process.on("unhandledRejection", (reason) => {
  logger.fatal({ err: reason }, "unhandledRejection");
  process.exit(1);
});

process.on("uncaughtException", (err) => {
  logger.fatal({ err }, "uncaughtException");
  process.exit(1);
});
```

These should log and exit; don’t try to “recover” and continue.

---

### 15. Not making error handling exhaustive

When you branch on error kinds, TypeScript won’t warn about missing cases unless you use `never`.

```ts
type AppError = { kind: "not_found" } | { kind: "forbidden" } | { kind: "conflict" };

function toStatus(e: AppError): number {
  switch (e.kind) {
    case "not_found": return 404;
    case "forbidden": return 403;
    // ❌ missing "conflict" — no compile error without default
  }
  return 500;
}

// ✅ Good
function toStatus2(e: AppError): number {
  switch (e.kind) {
    case "not_found": return 404;
    case "forbidden": return 403;
    case "conflict": return 409;
    default: {
      const _exhaustive: never = e.kind;
      throw new Error(`unhandled error kind: ${_exhaustive}`);
    }
  }
}
```

---

### Bonus: hiding constructor noise in stack traces

V8-specific but useful for library authors:

```ts
class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
    Error.captureStackTrace?.(this, this.constructor);
    Object.setPrototypeOf(this, new.target.prototype);
  }
}
```

---

### Quick checklist

- Throw `Error` (or subclasses), never primitives/objects.
- Repair prototype in custom errors; set `name`.
- Treat `catch (e)` as `unknown`; narrow before use.
- Never leave empty catch; don’t `return` in `finally`.
- `await` async calls inside `try`.
- Use `Error.cause` when wrapping.
- Prefer `Promise.allSettled` over `Promise.all` when partial failure matters.
- Don’t rely solely on `instanceof` across boundaries; use `code`/`name`.
- Serialize errors explicitly.
- Separate operational errors (expected, typed) from programmer errors (bugs).
- Add process-level handlers as a safety net, not as primary handling.

## Exercise

**Task:** Implement a typed, robust loader for a user profile.

Write a TypeScript function `loadUserProfile(userId: string): Promise<UserProfile>` that:

1. Validates `userId` (non-empty, alphanumeric only).
2. Fetches `/users/{userId}` from a (mock) API.
3. Handles failures explicitly:
   - invalid input → `InvalidUserIdError`
   - network failure → `NetworkError`
   - HTTP 404 → `NotFoundError`
   - other non-2xx → `HttpError`
   - invalid JSON → `ParseError`
   - invalid shape → `ValidationError`
4. Preserves the original cause using `Error.cause`.
5. Also implement `loadUserProfileSafe` returning a `Result<UserProfile>` instead of throwing.

Then consume it with exhaustive error handling.

---

## Step-by-step solution

### Step 1 — Domain model and error hierarchy

Create a base error so all app errors share a `code` and a normalized `name`. Use `Object.setPrototypeOf` so `instanceof` works after transpilation.

```ts
type UserProfile = {
  id: string;
  name: string;
  email: string;
  age: number;
};

class DomainError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    options?: ErrorOptions,
  ) {
    super(message, options);
    this.name = new.target.name;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

class InvalidUserIdError extends DomainError {
  constructor(userId: string) {
    super(`Invalid user id: "${userId}"`, 'INVALID_USER_ID');
  }
}

class NetworkError extends DomainError {
  constructor(cause?: unknown) {
    super('Network request failed', 'NETWORK_ERROR', { cause });
  }
}

class HttpError extends DomainError {
  constructor(public readonly status: number) {
    super(`HTTP ${status}`, 'HTTP_ERROR');
  }
}

class NotFoundError extends DomainError {
  constructor(userId: string) {
    super(`User "${userId}" not found`, 'NOT_FOUND');
  }
}

class ParseError extends DomainError {
  constructor(cause?: unknown) {
    super('Failed to parse JSON response', 'PARSE_ERROR', { cause });
  }
}

class ValidationError extends DomainError {
  constructor(public readonly issues: string[]) {
    super(`Invalid profile: ${issues.join('; ')}`, 'VALIDATION_ERROR');
  }
}
```

### Step 2 — Validation (no external deps)

Keep validation explicit and collect all issues at once.

```ts
function validateProfile(data: unknown): UserProfile {
  if (typeof data !== 'object' || data === null || Array.isArray(data)) {
    throw new ValidationError(['expected a plain object']);
  }

  const d = data as Record<string, unknown>;
  const issues: string[] = [];

  if (typeof d.id !== 'string' || d.id.trim() === '') issues.push('id must be a non-empty string');
  if (typeof d.name !== 'string' || d.name.trim() === '') issues.push('name must be a non-empty string');
  if (typeof d.email !== 'string' || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(d.email)) {
    issues.push('email must be a valid email');
  }
  if (typeof d.age !== 'number' || !Number.isInteger(d.age) || d.age < 0) {
    issues.push('age must be a non-negative integer');
  }

  if (issues.length > 0) throw new ValidationError(issues);
  return d as UserProfile;
}
```

> In production, prefer **Zod** / **Valibot**; the shape stays identical.

### Step 3 — Mock fetch with controllable scenarios

This makes the exercise runnable without a server.

```ts
type Scenario = 'ok' | 'notfound' | 'network' | 'badjson' | 'invalid' | 'http500';
let scenario: Scenario = 'ok';

async function mockFetch(url: string): Promise<Response> {
  await new Promise((r) => setTimeout(r, 10));
  if (scenario === 'network') throw new TypeError('fetch failed');
  const status = scenario === 'notfound' ? 404 : scenario === 'http500' ? 500 : 200;
  const body =
    scenario === 'badjson'
      ? '{not json'
      : scenario === 'invalid'
        ? JSON.stringify({ id: '1' })
        : JSON.stringify({ id: '1', name: 'Ada', email: 'ada@example.com', age: 30 });
  return new Response(body, { status, headers: { 'content-type': 'application/json' } });
}
```

### Step 4 — Core loader with typed errors

Under `useUnknownInCatchVariables`, catch values are `unknown`; narrow with `instanceof`.

```ts
async function loadUserProfile(userId: string): Promise<UserProfile> {
  if (!/^[a-zA-Z0-9]+$/.test(userId)) {
    throw new InvalidUserIdError(userId);
  }

  let response: Response;
  try {
    response = await mockFetch(`/users/${encodeURIComponent(userId)}`);
  } catch (e) {
    throw new NetworkError(e);
  }

  if (response.status === 404) throw new NotFoundError(userId);
  if (!response.ok) throw new HttpError(response.status);

  let data: unknown;
  try {
    data = await response.json();
  } catch (e) {
    throw new ParseError(e);
  }

  return validateProfile(data);
}
```

### Step 5 — Safe wrapper (Result type)

Avoid throwing across boundaries (e.g., UI layers) by returning a discriminated union.

```ts
type Result<T, E = DomainError> =
  | { ok: true; value: T }
  | { ok: false; error: E };

async function loadUserProfileSafe(userId: string): Promise<Result<UserProfile>> {
  try {
    const value = await loadUserProfile(userId);
    return { ok: true, value };
  } catch (e) {
    const error =
      e instanceof DomainError
        ? e
        : new DomainError('Unexpected error', 'UNKNOWN', { cause: e });
    return { ok: false, error };
  }
}
```

### Step 6 — Exhaustive consumption

```ts
async function showProfile(userId: string) {
  const result = await loadUserProfileSafe(userId);

  if (!result.ok) {
    const { error } = result;
    switch (error.code) {
      case 'INVALID_USER_ID':
      case 'NOT_FOUND':
        console.warn(error.message);
        return;
      case 'NETWORK_ERROR':
      case 'HTTP_ERROR':
        console.error('Retry later:', error.message);
        return;
      case 'PARSE_ERROR':
      case 'VALIDATION_ERROR':
        console.error('Bad data:', error.message, (error as ValidationError).issues ?? '');
        return;
      default:
        // exhaustiveness check
        const _exhaustive: never = error.code;
        throw new Error(`Unhandled error code: ${_exhaustive}`);
    }
  }

  const { id, name, email, age } = result.value;
  console.log(`${name} <${email}> (id=${id}, age=${age})`);
}
```

### Step 7 — Quick test harness

```ts
async function main() {
  const cases: Scenario[] = ['ok', 'notfound', 'network', 'badjson', 'invalid', 'http500'];
  for (const s of cases) {
    scenario = s;
    console.log('\n--- scenario:', s);
    await showProfile('u1');
  }

  scenario = 'ok';
  console.log('\n--- invalid id');
  await showProfile('bad id!');
}

main().catch(console.error);
```

