## Final solution

```ts
type Task = () => void;

class EventLoopSimulator {
  private readonly microtasks: Task[] = [];
  private readonly macrotasks: Task[] = [];

  enqueueMicrotask(task: Task): void {
    this.microtasks.push(task);
  }

  enqueueMacrotask(task: Task): void {
    this.macrotasks.push(task);
  }

  run(): void {
    this.drainMicrotasks();

    while (this.macrotasks.length > 0) {
      const macrotask = this.macrotasks.shift();
      macrotask?.();
      this.drainMicrotasks();
    }
  }

  private drainMicrotasks(): void {
    let index = 0;
    while (index < this.microtasks.length) {
      const task = this.microtasks[index];
      index++;
      task();
    }
    this.microtasks.length = 0;
  }
}

const loop = new EventLoopSimulator();

console.log('1: sync start');

loop.enqueueMacrotask(() => console.log('2: timeout'));
loop.enqueueMicrotask(() => console.log('3: promise microtask'));
loop.enqueueMicrotask(() => console.log('4: queueMicrotask'));

console.log('5: sync end');

loop.run();
```

This demonstrates the core event-loop rule: **synchronous code first, then microtasks, then macrotasks**, with FIFO ordering within each queue.

## Event Loop (TypeScript) — Interview-Style Answer

### 1) What the event loop is

JavaScript/TypeScript runtimes are **single-threaded** for your code, but they still need to handle:

- timers (`setTimeout`, `setInterval`)
- I/O (files, sockets, HTTP)
- microtasks (Promises, `queueMicrotask`)
- “immediate” callbacks (`setImmediate` in Node)
- process-level hooks (`process.nextTick` in Node)

The **event loop** is the scheduler that decides **which callback runs next** and **when**.  
It keeps cycling through phases until there is no more work.

A useful mental model:

- **Call stack**: currently running synchronous code.
- **Task queues (macrotasks)**: timers, I/O callbacks, `setImmediate`, close callbacks.
- **Microtask queue**: Promise `.then`, `queueMicrotask`, `process.nextTick` (Node-specific, higher priority than Promise microtasks).

### 2) Node.js event loop phases (high level)

1. **Timers** — run expired `setTimeout` / `setInterval` callbacks.
2. **Pending callbacks** — run some I/O callbacks deferred from previous loop.
3. **Idle / prepare** — internal.
4. **Poll** — retrieve new I/O events; run I/O callbacks; may block if nothing else to do.
5. **Check** — run `setImmediate` callbacks.
6. **Close callbacks** — e.g. `socket.on('close', ...)`.

After **each** callback (and at phase boundaries), the runtime drains:

- `process.nextTick` queue (Node, highest priority)
- microtask queue (Promises)

So microtasks can run “between” macrotasks, and `nextTick` runs before Promise microtasks.

Browser event loops are similar but simpler: macrotask queue + microtask queue, with rendering opportunities between.

---

## Core implementation (simplified but faithful)

Below is a **teaching implementation** of a Node-like event loop in TypeScript.  
It models phases, timers, I/O, check, close, microtasks, and `nextTick`.  
It is not production-grade (no real kernel I/O, no thread pool), but it demonstrates the scheduling core.

```ts
// event-loop.ts

type Task = () => void;

interface Timer {
  id: number;
  delay: number;          // ms
  createdAt: number;      // ms
  callback: Task;
  repeat: boolean;
  interval?: number;
}

class EventLoop {
  private timers: Timer[] = [];
  private ioQueue: Task[] = [];
  private checkQueue: Task[] = [];
  private closeQueue: Task[] = [];
  private microtaskQueue: Task[] = [];
  private nextTickQueue: Task[] = [];

  private timerIdCounter = 0;
  private running = false;

  // ---------- Public scheduling API ----------

  setTimeout(callback: Task, delay = 0): number {
    const id = ++this.timerIdCounter;
    this.timers.push({
      id,
      delay: Math.max(0, delay),
      createdAt: Date.now(),
      callback,
      repeat: false,
    });
    return id;
  }

  setInterval(callback: Task, interval: number): number {
    const id = ++this.timerIdCounter;
    this.timers.push({
      id,
      delay: Math.max(0, interval),
      createdAt: Date.now(),
      callback,
      repeat: true,
      interval,
    });
    return id;
  }

  clearTimeout(id: number): void {
    this.timers = this.timers.filter((t) => t.id !== id);
  }

  clearInterval(id: number): void {
    this.clearTimeout(id);
  }

  setImmediate(callback: Task): void {
    this.checkQueue.push(callback);
  }

  // Node-style: higher priority than Promise microtasks
  processNextTick(callback: Task): void {
    this.nextTickQueue.push(callback);
  }

  queueMicrotask(callback: Task): void {
    this.microtaskQueue.push(callback);
  }

  // Test helper: pretend an I/O operation completed
  simulateIO(callback: Task): void {
    this.ioQueue.push(callback);
  }

  // ---------- Internal helpers ----------

  private now(): number {
    return Date.now();
  }

  private hasWork(): boolean {
    return (
      this.timers.length > 0 ||
      this.ioQueue.length > 0 ||
      this.checkQueue.length > 0 ||
      this.closeQueue.length > 0 ||
      this.microtaskQueue.length > 0 ||
      this.nextTickQueue.length > 0
    );
  }

  private hasImmediateWork(): boolean {
    return (
      this.ioQueue.length > 0 ||
      this.checkQueue.length > 0 ||
      this.closeQueue.length > 0 ||
      this.microtaskQueue.length > 0 ||
      this.nextTickQueue.length > 0 ||
      this.timers.some((t) => this.now() - t.createdAt >= t.delay)
    );
  }

  private nextTimerDelay(): number {
    if (this.timers.length === 0) return 0;
    const now = this.now();
    return Math.min(...this.timers.map((t) => Math.max(0, t.delay - (now - t.createdAt))));
  }

  // Drain microtasks: nextTick first, then Promise microtasks.
  // Repeat because callbacks may schedule more microtasks.
  private drainMicrotasks(): void {
    // Safety guard to avoid infinite loops in buggy user code
    let guard = 10_000;
    while ((this.nextTickQueue.length > 0 || this.microtaskQueue.length > 0) && guard-- > 0) {
      // Drain all nextTick callbacks first
      while (this.nextTickQueue.length > 0) {
        const cb = this.nextTickQueue.shift()!;
        this.safeRun(cb);
      }
      // Then drain microtasks
      while (this.microtaskQueue.length > 0) {
        const cb = this.microtaskQueue.shift()!;
        this.safeRun(cb);
      }
    }
    if (guard <= 0) {
      throw new Error("Microtask queue did not drain (possible infinite loop)");
    }
  }

  private safeRun(cb: Task): void {
    try {
      cb();
    } catch (err) {
      // In real runtimes, uncaught errors may terminate the process
      // or be reported via uncaughtException. Here we log and continue.
      console.error("Uncaught error in callback:", err);
    }
  }

  private runTimers(now: number): void {
    const expired: Timer[] = [];
    const remaining: Timer[] = [];

    for (const t of this.timers) {
      if (now - t.createdAt >= t.delay) expired.push(t);
      else remaining.push(t);
    }

    this.timers = remaining;

    // Timers fire in order of delay, then creation time
    expired.sort((a, b) => a.delay - b.delay || a.createdAt - b.createdAt);

    for (const t of expired) {
      this.safeRun(t.callback);
      this.drainMicrotasks(); // microtasks can run after each timer callback

      if (t.repeat && t.interval !== undefined) {
        t.createdAt = now;
        t.delay = t.interval;
        this.timers.push(t);
      }
    }
  }

  private runQueue(queue: Task[]): void {
    // Splice so callbacks can safely schedule into the same queue
    const batch = queue.splice(0);
    for (const cb of batch) {
      this.safeRun(cb);
      this.drainMicrotasks(); // microtasks run after each macrotask
    }
  }

  // ---------- Main loop ----------

  async run(): Promise<void> {
    if (this.running) return;
    this.running = true;

    while (this.hasWork()) {
      const now = this.now();

      // Phase 1: timers
      this.runTimers(now);
      this.drainMicrotasks();

      // Phase 2: pending I/O callbacks
      this.runQueue(this.ioQueue);
      this.drainMicrotasks();

      // Phase 3/4: idle/prepare + poll (simulated as: already queued I/O)
      // In a real runtime, poll may block here waiting for I/O.
      // We skip blocking and continue.

      // Phase 5: check (setImmediate)
      this.runQueue(this.checkQueue);
      this.drainMicrotasks();

      // Phase 6: close callbacks
      this.runQueue(this.closeQueue);
      this.drainMicrotasks();

      // If only future timers remain, wait (simulated) instead of busy-looping.
      if (this.hasWork() && !this.hasImmediateWork()) {
        const waitMs = this.nextTimerDelay();
        if (waitMs > 0) {
          await new Promise<void>((resolve) => setTimeout(resolve, waitMs));
        }
      }
    }

    this.running = false;
  }
}

export { EventLoop };
```

### Demo

```ts
// demo.ts
import { EventLoop } from "./event-loop";

const loop = new EventLoop();

console.log("1: sync start");

loop.setTimeout(() => console.log("5: timeout 0ms"), 0);

loop.setImmediate(() => console.log("6: setImmediate"));

loop.processNextTick(() => console.log("2: nextTick"));

loop.queueMicrotask(() => console.log("3: microtask"));

Promise.resolve().then(() => console.log("4: promise microtask"));

loop.simulateIO(() => console.log("7: I/O callback"));

loop.setTimeout(() => {
  console.log("8: timeout 10ms");
  loop.queueMicrotask(() => console.log("9: microtask after timeout"));
}, 10);

loop.run().then(() => console.log("10: loop finished"));
```

Expected ordering (approximate):

```
1: sync start
2: nextTick
3: microtask
4: promise microtask
5: timeout 0ms
7: I/O callback   (phase order may vary slightly by implementation)
6: setImmediate
8: timeout 10ms
9: microtask after timeout
10: loop finished
```

The exact interleaving of timers vs I/O vs `setImmediate` can differ in real Node depending on timing and phase entry, but the **priority rules** (`nextTick` > microtasks > macrotasks) and **phase ordering** are the key ideas.

---

## Interview talking points

- **Why single-threaded but non-blocking?**  
  The main thread runs JS; I/O is offloaded to the OS/libuv thread pool, and completions are queued for the loop.

- **Macrotask vs microtask:**  
  Macrotasks are scheduled by the loop phases. Microtasks run after the current task and before the next macrotask.

- **Starvation risk:**  
  Infinite `process.nextTick` or microtask chains can starve the event loop (no timers/I/O run). This is why Node docs warn against recursive `nextTick`.

- **Browser difference:**  
  Browsers have rendering between tasks; Node has no DOM rendering, but has `setImmediate`/`nextTick` not present in browsers.

- **Real loop blocks in poll:**  
  If no work is ready, the loop waits (blocks) for I/O instead of busy-spinning. My demo simulates waiting with `setTimeout`.

If you want, I can also show a **minimal browser-style loop** (just macrotask + microtask queues) or a **libuv-inspired handle-based design**.

Below are common edge cases when working with event loops in TypeScript (Node.js and browsers), with runnable examples and mitigations.

## 1) Microtask starvation (Promise recursion blocks macrotasks)

Recursive microtasks can postpone timers, I/O, and rendering indefinitely.

```ts
// BAD: starves setTimeout / I/O
function spin(): void {
  Promise.resolve().then(spin);
}
spin();

setTimeout(() => console.log("timeout fired"), 0);
```

**Mitigation:** yield to the macrotask queue periodically.

```ts
function spinYielding(count = 0): void {
  if (count % 1000 === 0) {
    setTimeout(() => spinYielding(count + 1), 0);
    return;
  }
  // do work...
  Promise.resolve().then(() => spinYielding(count + 1));
}
```

---

## 2) `process.nextTick` starvation (Node.js)

`nextTick` has higher priority than the promise microtask queue and can starve I/O.

```ts
// BAD
function tick(): void {
  process.nextTick(tick);
}
tick();
```

**Mitigation:** prefer `setImmediate` or `setTimeout` for recursive scheduling, or batch work.

```ts
function betterTick(count = 0): void {
  if (count > 1000) {
    setImmediate(() => betterTick(0));
    return;
  }
  // work...
  process.nextTick(() => betterTick(count + 1));
}
```

---

## 3) Task ordering: `setTimeout(0)` vs `setImmediate`

At top level in Node.js the order is not guaranteed; inside an I/O callback `setImmediate` always wins.

```ts
setTimeout(() => console.log("timeout"), 0);
setImmediate(() => console.log("immediate"));

// Inside I/O callback:
import { readFile } from "node:fs";
readFile(__filename, () => {
  setTimeout(() => console.log("timeout (io)"), 0);
  setImmediate(() => console.log("immediate (io)")); // always first
});
```

---

## 4) Microtask ordering: `process.nextTick` vs `queueMicrotask` vs `Promise.then`

```ts
process.nextTick(() => console.log("1 nextTick"));
queueMicrotask(() => console.log("2 queueMicrotask"));
Promise.resolve().then(() => console.log("3 promise then"));

// Typical Node output:
// 1 nextTick
// 2 queueMicrotask
// 3 promise then
```

**Edge case:** mixing these can make ordering assumptions fragile. Keep scheduling strategy consistent.

---

## 5) Timer minimum delay and clamping

`setTimeout(fn, 0)` is not immediate; delays are rounded/clamped (browsers often clamp nested timers to 4ms).

```ts
const start = Date.now();
setTimeout(() => {
  console.log("elapsed:", Date.now() - start); // >= 1, often 4+
}, 0);
```

**Mitigation:** use `queueMicrotask`/`process.nextTick` if you need “as soon as possible” within the same turn.

---

## 6) Timer delay overflow (very large delays)

Delays beyond the 32-bit signed range are not reliable.

```ts
// Dangerous: may warn and be treated as ~1ms
setTimeout(() => console.log("maybe too soon"), 2 ** 31);

// Safer: chunk or check dates
function waitUntil(target: number): void {
  const now = Date.now();
  if (now >= target) return;
  const delay = Math.min(target - now, 2 ** 31 - 1);
  setTimeout(() => waitUntil(target), delay);
}
```

---

## 7) `setInterval` drift and overlapping execution

If the handler takes longer than the interval, callbacks can pile up or drift.

```ts
// Risky
setInterval(async () => {
  await slowWork(); // may overlap
}, 100);
```

**Mitigation:** recursive `setTimeout` guarantees no overlap.

```ts
async function loop(): Promise<void> {
  await slowWork();
  setTimeout(loop, 100);
}
loop();
```

---

## 8) Lost `this` in timer callbacks

```ts
class Worker {
  value = 42;
  startBad() {
    setTimeout(this.tick, 0); // `this` is undefined in strict mode
  }
  startGood() {
    setTimeout(() => this.tick(), 0);
    // or: setTimeout(this.tick.bind(this), 0);
  }
  tick() {
    console.log(this.value);
  }
}
```

---

## 9) Uncleared timers causing memory leaks

Timers keep closures/references alive.

```ts
function leaky() {
  const big = new Array(1_000_000).fill("x");
  const t = setInterval(() => {
    console.log(big.length); // keeps `big` alive
  }, 1000);
  // forgot clearInterval(t)
}
```

**Mitigation:** store handles and clear on teardown; use `WeakRef` where appropriate.

```ts
const t = setInterval(() => {}, 1000);
// later:
clearInterval(t);
```

---

## 10) Promise executor runs synchronously

Code before `resolve()`/`reject()` in the executor runs immediately, not in a later turn.

```ts
console.log("A");
new Promise<void>((resolve) => {
  console.log("B"); // synchronous
  resolve();
}).then(() => console.log("D"));
console.log("C");

// Output: A B C D
```

**Edge case:** putting heavy work in the executor blocks the current call stack.

---

## 11) Unhandled promise rejections terminate (Node 15+)

```ts
Promise.reject(new Error("boom")); // unhandled

process.on("unhandledRejection", (reason, promise) => {
  console.error("Unhandled rejection:", reason);
  // decide whether to exit
});
```

In modern Node, an unhandled rejection can exit the process by default. Always attach `.catch()` or use `try/await`.

---

## 12) Uncaught exceptions inside callbacks crash the process

`try/catch` around scheduling does not catch errors thrown later.

```ts
try {
  setTimeout(() => {
    throw new Error("async boom");
  }, 0);
} catch {
  // never catches
}

process.on("uncaughtException", (err) => {
  console.error("Uncaught:", err);
  // last resort only; prefer fixing at source
});
```

**Better:** wrap callback bodies.

```ts
setTimeout(() => {
  try {
    risky();
  } catch (e) {
    console.error(e);
  }
}, 0);
```

---

## 13) `async/await` error handling and floating promises

```ts
async function work(): Promise<void> {
  throw new Error("fail");
}

// BAD: floating promise
work();

// GOOD
work().catch((e) => console.error(e));

// or
await work(); // inside async function
```

---

## 14) Sequential vs parallel async work

```ts
const urls = ["/a", "/b", "/c"];

// Slow: sequential
for (const u of urls) {
  await fetch(u);
}

// Fast: parallel, but fails fast
await Promise.all(urls.map((u) => fetch(u)));

// Safer: allSettled
const results = await Promise.allSettled(urls.map((u) => fetch(u)));
```

**Edge case:** `Promise.all` rejects on first failure; earlier in-flight requests continue.

---

## 15) EventEmitter `"error"` event crashes if unhandled

```ts
import { EventEmitter } from "node:events";

const e = new EventEmitter();
// e.emit("error", new Error("boom")); // throws if no listener

e.on("error", (err: Error) => {
  console.error("handled:", err.message);
});
e.emit("error", new Error("boom"));
```

Also watch for max-listener warnings:

```ts
e.setMaxListeners(20); // default 10
```

---

## 16) Blocking the event loop with synchronous work

```ts
// Blocks everything: timers, I/O, rendering
const end = Date.now() + 2000;
while (Date.now() < end) {}
```

**Mitigation:** chunk CPU work or move to Worker Threads.

```ts
function chunked(items: number[], i = 0): void {
  const batch = 1000;
  const end = Math.min(i + batch, items.length);
  for (; i < end; i++) {
    // work on items[i]
  }
  if (i < items.length) setImmediate(() => chunked(items, i));
}
```

---

## 17) Graceful shutdown and lingering handles

Open servers/timers keep the process alive.

```ts
import { createServer } from "node:http";

const server = createServer((_, res) => res.end("ok"));
server.listen(3000);

process.on("SIGTERM", () => {
  console.log("shutting down");
  server.close(() => process.exit(0));
  // also clear timers / close DB pools
});
```

**Edge case:** forgetting to close handles prevents exit; `process.exit()` skips cleanup.

---

## 18) Top-level `await` in ESM blocks module evaluation

```ts
// module.ts (ESM)
const data = await fetch("/config").then((r) => r.json());
export { data };
```

Dependents wait for this module’s event-loop turn to complete. Avoid heavy top-level await in hot paths; lazy-load instead.

---

## 19) Cancellation with `AbortController`

Timers and async operations should be cancellable to avoid leaks.

```ts
const ac = new AbortController();
const t = setTimeout(() => ac.abort(), 1000);

try {
  const res = await fetch("https://example.com", { signal: ac.signal });
  console.log(await res.text());
} catch (e) {
  if ((e as Error).name === "AbortError") console.log("aborted");
  else throw e;
} finally {
  clearTimeout(t);
}
```

---

## 20) Browser: `requestAnimationFrame` vs timers

For visual updates, timers can cause jank; `rAF` aligns with refresh.

```ts
let id = 0;
function frame() {
  // update DOM
  id = requestAnimationFrame(frame);
}
id = requestAnimationFrame(frame);

// cleanup
cancelAnimationFrame(id);
```

---

## Practical checklist

- Never recursively schedule microtasks without yielding.
- Prefer recursive `setTimeout` over `setInterval`.
- Always clear timers/listeners on teardown.
- Wrap async callback bodies in `try/catch`.
- Handle `unhandledRejection` and `uncaughtException` as safety nets, not primary control flow.
- Avoid blocking the loop; chunk work or use workers.
- Make long-lived operations cancellable (`AbortController`).
- Be explicit about `this` binding in callbacks.

The **Factory Pattern** family in TypeScript typically covers three related ideas:

| Pattern | Intent |
|---|---|
| **Simple Factory** | One function/class decides which concrete class to instantiate based on input. |
| **Factory Method** | An abstract creator declares a factory method; subclasses decide which product to create. |
| **Abstract Factory** | A factory of factories creating related products (e.g., Windows vs. macOS UI). |

Below is one complete, runnable file (`factory.ts`) that demonstrates all three with idiomatic TypeScript: interfaces, discriminant unions, strict typing, and `readonly` where appropriate.

### `factory.ts`

```ts
// ============================================================
// 1. SIMPLE FACTORY  –  Shapes
// ============================================================

interface Shape {
  area(): number;
  describe(): string;
}

class Circle implements Shape {
  constructor(private readonly radius: number) {}
  area(): number {
    return Math.PI * this.radius ** 2;
  }
  describe(): string {
    return `Circle(r=${this.radius}) area=${this.area().toFixed(2)}`;
  }
}

class Square implements Shape {
  constructor(private readonly side: number) {}
  area(): number {
    return this.side ** 2;
  }
  describe(): string {
    return `Square(s=${this.side}) area=${this.area()}`;
  }
}

class Rectangle implements Shape {
  constructor(
    private readonly width: number,
    private readonly height: number
  ) {}
  area(): number {
    return this.width * this.height;
  }
  describe(): string {
    return `Rectangle(${this.width}x${this.height}) area=${this.area()}`;
  }
}

// Discriminated union keeps construction type-safe.
type ShapeSpec =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number }
  | { kind: "rectangle"; width: number; height: number };

class ShapeFactory {
  static create(spec: ShapeSpec): Shape {
    switch (spec.kind) {
      case "circle":
        return new Circle(spec.radius);
      case "square":
        return new Square(spec.side);
      case "rectangle":
        return new Rectangle(spec.width, spec.height);
      default: {
        // Exhaustiveness check – if a new kind is added, TS errors here.
        const _exhaustive: never = spec;
        throw new Error(`Unknown shape kind: ${_exhaustive}`);
      }
    }
  }
}

// ============================================================
// 2. FACTORY METHOD  –  Documents
// ============================================================

interface Document {
  open(): void;
  save(): void;
  kind: string;
}

class WordDocument implements Document {
  kind = "Word";
  open(): void {
    console.log("[Word] Document opened.");
  }
  save(): void {
    console.log("[Word] Document saved as .docx");
  }
}

class PdfDocument implements Document {
  kind = "PDF";
  open(): void {
    console.log("[PDF] Document opened.");
  }
  save(): void {
    console.log("[PDF] Document saved as .pdf");
  }
}

// Abstract creator: declares the factory method.
abstract class Application {
  /** Factory method – subclasses decide. */
  abstract createDocument(): Document;

  /** Template method using the factory. */
  newDocument(): Document {
    const doc = this.createDocument();
    doc.open();
    return doc;
  }
}

class WordApplication extends Application {
  createDocument(): Document {
    return new WordDocument();
  }
}

class PdfApplication extends Application {
  createDocument(): Document {
    return new PdfDocument();
  }
}

// ============================================================
// 3. ABSTRACT FACTORY  –  Cross-platform GUI
// ============================================================

interface Button {
  render(): string;
  onClick(handler: () => void): void;
}

interface Checkbox {
  render(): string;
  toggle(): void;
}

class WinButton implements Button {
  private handler?: () => void;
  render(): string {
    return "<WinButton/>";
  }
  onClick(handler: () => void): void {
    this.handler = handler;
  }
}

class MacButton implements Button {
  private handler?: () => void;
  render(): string {
    return "<MacButton/>";
  }
  onClick(handler: () => void): void {
    this.handler = handler;
  }
}

class WinCheckbox implements Checkbox {
  private checked = false;
  render(): string {
    return `<WinCheckbox checked=${this.checked}/>`;
  }
  toggle(): void {
    this.checked = !this.checked;
  }
}

class MacCheckbox implements Checkbox {
  private checked = false;
  render(): string {
    return `<MacCheckbox checked=${this.checked}/>`;
  }
  toggle(): void {
    this.checked = !this.checked;
  }
}

// Abstract factory interface.
interface GUIFactory {
  createButton(): Button;
  createCheckbox(): Checkbox;
}

class WinFactory implements GUIFactory {
  createButton(): Button {
    return new WinButton();
  }
  createCheckbox(): Checkbox {
    return new WinCheckbox();
  }
}

class MacFactory implements GUIFactory {
  createButton(): Button {
    return new MacButton();
  }
  createCheckbox(): Checkbox {
    return new MacCheckbox();
  }
}

// Client code depends only on the abstract factory.
function buildUI(factory: GUIFactory): { button: Button; checkbox: Checkbox } {
  const button = factory.createButton();
  const checkbox = factory.createCheckbox();
  return { button, checkbox };
}

// ============================================================
// Demo
// ============================================================

function main(): void {
  console.log("=== Simple Factory ===");
  const shapes: Shape[] = [
    ShapeFactory.create({ kind: "circle", radius: 3 }),
    ShapeFactory.create({ kind: "square", side: 4 }),
    ShapeFactory.create({ kind: "rectangle", width: 2, height: 5 }),
  ];
  for (const s of shapes) console.log(s.describe());

  console.log("\n=== Factory Method ===");
  const wordApp = new WordApplication();
  const pdfApp = new PdfApplication();
  const doc1 = wordApp.newDocument();
  const doc2 = pdfApp.newDocument();
  doc1.save();
  doc2.save();

  console.log("\n=== Abstract Factory ===");
  for (const factory of [new WinFactory(), new MacFactory()]) {
    const ui = buildUI(factory);
    console.log(ui.button.render());
    console.log(ui.checkbox.render());
    ui.checkbox.toggle();
    console.log(ui.checkbox.render());
  }
}

main();
```

