## Source code

Create `src/index.ts`:

```ts
import {
  readFile,
  writeFile,
  appendFile,
  mkdir,
  access,
  rename,
  unlink,
  constants,
} from "node:fs/promises";
import { createReadStream, createWriteStream } from "node:fs";
import { pipeline } from "node:stream/promises";
import path from "node:path";
import { randomUUID } from "node:crypto";

// ---------- Types ----------

type User = {
  id: string;
  name: string;
  email: string;
};

type AppConfig = {
  appName: string;
  version: number;
  debug: boolean;
};

// ---------- Helpers ----------

const DATA_DIR = path.resolve(process.cwd(), "data");

async function ensureDir(dir: string): Promise<void> {
  await mkdir(dir, { recursive: true });
}

function isNodeError(err: unknown): err is NodeJS.ErrnoException {
  return err instanceof Error && "code" in err;
}

async function fileExists(filePath: string): Promise<boolean> {
  try {
    await access(filePath, constants.F_OK);
    return true;
  } catch {
    return false;
  }
}

// ---------- Text I/O ----------

async function writeText(filePath: string, content: string): Promise<void> {
  await ensureDir(path.dirname(filePath));
  await writeFile(filePath, content, { encoding: "utf8" });
}

async function readText(filePath: string): Promise<string> {
  return readFile(filePath, { encoding: "utf8" });
}

// ---------- JSON I/O ----------

async function writeJson<T>(filePath: string, value: T): Promise<void> {
  const json = JSON.stringify(value, null, 2);
  await writeText(filePath, json + "\n");
}

async function readJson<T>(filePath: string): Promise<T> {
  const text = await readText(filePath);
  return JSON.parse(text) as T;
}

// ---------- Atomic write ----------
// Useful for config files: readers never see a partially written file.

async function atomicWriteText(filePath: string, content: string): Promise<void> {
  await ensureDir(path.dirname(filePath));
  const tempPath = `${filePath}.${randomUUID()}.tmp`;

  try {
    await writeFile(tempPath, content, { encoding: "utf8" });
    await rename(tempPath, filePath); // atomic on most filesystems
  } catch (err) {
    await unlink(tempPath).catch(() => undefined);
    throw err;
  }
}

// ---------- Binary I/O ----------

async function writeBinary(filePath: string, data: Buffer): Promise<void> {
  await ensureDir(path.dirname(filePath));
  await writeFile(filePath, data);
}

async function readBinary(filePath: string): Promise<Buffer> {
  return readFile(filePath);
}

// ---------- Streaming large files ----------

async function copyLargeFile(source: string, destination: string): Promise<void> {
  await ensureDir(path.dirname(destination));
  await pipeline(
    createReadStream(source),
    createWriteStream(destination)
  );
}

async function countLines(filePath: string): Promise<number> {
  let lines = 0;
  const stream = createReadStream(filePath, { encoding: "utf8" });

  for await (const chunk of stream) {
    // Count newline characters; good enough for typical text files.
    for (const char of chunk) {
      if (char === "\n") lines++;
    }
  }

  return lines;
}

// ---------- Append ----------

async function logLine(filePath: string, line: string): Promise<void> {
  await ensureDir(path.dirname(filePath));
  await appendFile(filePath, line + "\n", { encoding: "utf8" });
}

// ---------- Main demo ----------

async function main(): Promise<void> {
  const textFile = path.join(DATA_DIR, "notes.txt");
  const jsonFile = path.join(DATA_DIR, "users.json");
  const configFile = path.join(DATA_DIR, "config.json");
  const binaryFile = path.join(DATA_DIR, "payload.bin");
  const largeFile = path.join(DATA_DIR, "large.txt");
  const copyFile = path.join(DATA_DIR, "large.copy.txt");
  const logFile = path.join(DATA_DIR, "app.log");

  // 1. Text write/read
  await writeText(textFile, "Hello from TypeScript!\nSecond line.\n");
  console.log("Text file:", await readText(textFile));

  // 2. JSON write/read
  const users: User[] = [
    { id: "1", name: "Ada", email: "ada@example.com" },
    { id: "2", name: "Grace", email: "grace@example.com" },
  ];
  await writeJson(jsonFile, users);
  const loadedUsers = await readJson<User[]>(jsonFile);
  console.log("Users:", loadedUsers);

  // 3. Atomic config write
  const config: AppConfig = {
    appName: "FileIO Demo",
    version: 1,
    debug: true,
  };
  await atomicWriteText(configFile, JSON.stringify(config, null, 2) + "\n");
  console.log("Config exists:", await fileExists(configFile));

  // 4. Binary write/read
  const bytes = Buffer.from([0x48, 0x69, 0x21]); // "Hi!"
  await writeBinary(binaryFile, bytes);
  const readBytes = await readBinary(binaryFile);
  console.log("Binary:", readBytes.toString("utf8"));

  // 5. Large file + streaming copy + line count
  await writeText(
    largeFile,
    Array.from({ length: 100_000 }, (_, i) => `line ${i + 1}`).join("\n") + "\n"
  );
  await copyLargeFile(largeFile, copyFile);
  console.log("Copied file lines:", await countLines(copyFile));

  // 6. Append log
  await logLine(logFile, `[${new Date().toISOString()}] app started`);
  await logLine(logFile, `[${new Date().toISOString()}] work done`);
  console.log("Log:\n" + (await readText(logFile)));

  // 7. Error handling example
  try {
    await readText(path.join(DATA_DIR, "does-not-exist.txt"));
  } catch (err) {
    if (isNodeError(err) && err.code === "ENOENT") {
      console.log("Expected missing file error:", err.code);
    } else {
      throw err;
    }
  }
}

main().catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});
```

