# Mark-and-Sweep Garbage Collector in TypeScript

Below is a complete, self-contained implementation. It models a small heap of objects whose fields may contain primitive values or references to other heap objects. A **mark-and-sweep** collector handles cycles (unlike naive reference counting) and reuses freed slots via a free list.

## `gc.ts`

```ts
// gc.ts — a self-contained mark-and-sweep garbage collector

export type Value =
  | { kind: "nil" }
  | { kind: "int"; v: number }
  | { kind: "str"; v: string }
  | { kind: "ref"; id: number };

export interface HeapObject {
  id: number;
  tag: string;
  fields: Map<string, Value>;
  marked: boolean;
}

export interface GCStats {
  allocations: number;
  collections: number;
  freed: number;
}

export class GarbageCollector {
  private heap: (HeapObject | null)[] = [];
  private freeList: number[] = [];
  private roots = new Set<number>();
  private scopes: Set<number>[] = [];
  stats: GCStats = { allocations: 0, collections: 0, freed: 0 };

  // ---------- allocation ----------
  alloc(tag = "object", fields: Record<string, Value> = {}): number {
    const id = this.freeList.pop() ?? this.heap.length;
    if (id === this.heap.length) this.heap.push(null);

    const obj: HeapObject = {
      id,
      tag,
      fields: new Map(Object.entries(fields)),
      marked: false,
    };
    this.heap[id] = obj;
    this.stats.allocations++;
    return id;
  }

  get(id: number): HeapObject {
    const o = this.heap[id];
    if (!o) throw new Error(`dangling reference: ${id}`);
    return o;
  }

  set(objId: number, field: string, value: Value): void {
    this.get(objId).fields.set(field, value);
  }

  read(objId: number, field: string): Value {
    return this.get(objId).fields.get(field) ?? { kind: "nil" };
  }

  // ---------- roots ----------
  addRoot(id: number): void {
    this.roots.add(id);
  }

  removeRoot(id: number): void {
    this.roots.delete(id);
  }

  /** Lexical root scope: everything rooted inside is released on popScope(). */
  pushScope(): void {
    this.scopes.push(new Set());
  }

  popScope(): void {
    const s = this.scopes.pop();
    if (s) for (const id of s) this.roots.delete(id);
  }

  rootInScope(id: number): void {
    const s = this.scopes[this.scopes.length - 1];
    if (!s) throw new Error("rootInScope() called without an active scope");
    s.add(id);
    this.roots.add(id);
  }

  // ---------- collection ----------
  collect(): number {
    // MARK: iterative DFS from all roots (avoids recursion-depth crashes)
    const stack: number[] = [...this.roots];
    while (stack.length > 0) {
      const id = stack.pop()!;
      const obj = this.heap[id];
      if (!obj || obj.marked) continue;
      obj.marked = true;
      for (const v of obj.fields.values()) {
        if (v.kind === "ref") stack.push(v.id);
      }
    }

    // SWEEP: free anything unmarked, reuse its slot
    let freed = 0;
    for (let i = 0; i < this.heap.length; i++) {
      const obj = this.heap[i];
      if (!obj) continue;
      if (obj.marked) {
        obj.marked = false; // reset for next cycle
      } else {
        this.heap[i] = null;
        this.freeList.push(i);
        freed++;
      }
    }

    this.stats.collections++;
    this.stats.freed += freed;
    return freed;
  }

  // ---------- introspection ----------
  aliveCount(): number {
    return this.heap.filter((o) => o !== null).length;
  }

  dump(label = ""): void {
    if (label) console.log(`--- ${label} ---`);
    for (const o of this.heap) {
      if (!o) continue;
      const fields = [...o.fields.entries()]
        .map(([k, v]) =>
          v.kind === "ref" ? `${k}->#${v.id}` : `${k}=${JSON.stringify(v)}`
        )
        .join(", ");
      console.log(`  #${o.id} [${o.tag}] { ${fields} }${o.marked ? " *marked*" : ""}`);
    }
    console.log(`  roots: [${[...this.roots].join(", ")}]  alive=${this.aliveCount()}`);
  }
}

// ---------- demo ----------
function main() {
  const gc = new GarbageCollector();

  console.log("=== Building a reachable list ===");
  gc.pushScope();
  const head = gc.alloc("node", { value: { kind: "int", v: 1 } });
  gc.rootInScope(head);

  const n2 = gc.alloc("node", { value: { kind: "int", v: 2 } });
  gc.set(head, "next", { kind: "ref", id: n2 });

  const n3 = gc.alloc("node", { value: { kind: "int", v: 3 } });
  gc.set(n2, "next", { kind: "ref", id: n3 });

  gc.dump("after building list");

  console.log("\n=== Creating unreachable garbage (incl. a cycle) ===");
  const a = gc.alloc("node", { value: { kind: "str", v: "garbage" } });
  const b = gc.alloc("node", { value: { kind: "int", v: 99 } });
  gc.set(a, "next", { kind: "ref", id: b });
  gc.set(b, "next", { kind: "ref", id: a }); // cycle: a <-> b
  // neither a nor b is rooted -> both should be collected
  gc.dump("before collection");

  const freed1 = gc.collect();
  console.log(`\ncollect() freed ${freed1} object(s)`);
  gc.dump("after first collection");

  console.log("\n=== Dropping the list root, then collecting ===");
  gc.popScope(); // releases 'head'
  const freed2 = gc.collect();
  console.log(`collect() freed ${freed2} object(s) (the whole list)`);
  gc.dump("after dropping root");

  console.log("\n=== Reusing freed slots ===");
  const reused = gc.alloc("node", { value: { kind: "int", v: 42 } });
  console.log(`new object id = ${reused} (reused a freed slot)`);
  gc.dump("final");

  console.log("\nstats:", gc.stats);
}

// Run when executed directly (works with ts-node / node after tsc)
if (require.main === module) {
  main();
}
```

## How it works

1. **Heap & allocation** — `alloc()` returns an integer handle. Freed slots are pushed onto `freeList` and reused, mimicking a real allocator and avoiding unbounded growth.
2. **Values** — A `Value` is either a primitive (`nil`/`int`/`str`) or `{ kind: "ref", id }`. Only refs participate in traversal.
3. **Roots** — Objects reachable from `roots` are live. `pushScope`/`popScope`/`rootInScope` give lexical scoping, which mirrors stack frames in a real VM.
4. **Mark phase** — Iterative DFS from every root, following `ref` fields. Iteration (not recursion) avoids stack overflow on deep heaps. Cycles are handled because already-marked objects are skipped.
5. **Sweep phase** — Unmarked objects become garbage: their slot is nulled and added to `freeList`; marked bits are reset for the next cycle.
6. **Demonstration** — Builds a 3-node list, creates an unreachable 2-node cycle (proving cycle collection), drops the list root, then shows slot reuse and final stats.

## Running it

```bash
# Option A: ts-node
npx ts-node gc.ts

# Option B: compile then run
npx tsc gc.ts --target es2020 --module commonjs && node gc.js
```

## Extensions you could add

- **Write barriers + incremental/concurrent marking** (tri-color marking) to reduce pause times.
- **Generational collection** (nursery + old gen) with remembered sets for cross-generational refs.
- **Compaction / copying** (Cheney's algorithm) to eliminate fragmentation.
- **Finalizers** invoked during sweep (careful: they can resurrect objects).
- **Weak references** cleared when their target is unreachable.

Garbage collection (GC) in TypeScript is really **JavaScript engine GC**, because TypeScript compiles to JavaScript. TypeScript itself adds types and syntax, but memory management happens at runtime in engines such as V8, SpiderMonkey, or JavaScriptCore.

## 1. The idea

GC automatically reclaims memory occupied by objects that are no longer reachable.

Key concepts:

- **Reachability**: an object is kept alive if it can be reached from a “root” (global object, current call stack, active closures, DOM, etc.).
- **Mark-and-sweep**: the engine marks reachable objects, then frees unmarked ones.
- **Generational GC**: short-lived objects are collected frequently (young generation); long-lived objects less often (old generation).
- **Cycles are okay in modern engines**: circular references are collected if the cycle is unreachable.
- **No manual `free`**: you do not explicitly deallocate objects in TypeScript/JavaScript.

TypeScript-specific note: type annotations, interfaces, and generics are erased at compile time and do not affect GC.

## 2. Syntax and language features

There is no “GC syntax” in TypeScript. Instead, memory lifetime is controlled indirectly by references.

### Reassign or null out references

```ts
let user: { name: string } | null = { name: "Ada" };

// Object becomes eligible for GC if no other references exist
user = null;
```

### Remove properties

```ts
const obj: Record<string, unknown> = { large: new Array(1_000_000).fill(0) };

// Removes the property reference; object may become collectible
delete obj.large;
```

`delete` removes a property, not necessarily the whole object.

### Weak references and registries

```ts
let data: { value: number } | null = { value: 42 };

const ref = new WeakRef(data);
const registry = new FinalizationRegistry((heldValue: string) => {
  console.log("collected:", heldValue);
});

registry.register(data, "my-data");
data = null; // object may now be collected later
```

`WeakRef` and `FinalizationRegistry` are advanced tools. Collection timing is not guaranteed.

### Explicit resource management (deterministic cleanup)

TypeScript 5.2+ supports `using`, which calls `Symbol.dispose` at scope exit. This is about resource cleanup, not GC timing.

```ts
class FileHandle implements Disposable {
  constructor(private path: string) {}

  read(): string {
    return `contents of ${this.path}`;
  }

  [Symbol.dispose](): void {
    console.log(`closing ${this.path}`);
  }
}

function processFile() {
  using handle = new FileHandle("data.txt");
  console.log(handle.read());
  // handle is disposed automatically here
}
```

## 3. Typical use cases

### Avoiding memory leaks

#### Leaking timer/closure

```ts
function startLeak() {
  const bigArray = new Array(1_000_000).fill(0);

  // Keeps bigArray alive forever
  setInterval(() => {
    console.log(bigArray.length);
  }, 1000);
}
```

Fix:

```ts
function startSafe() {
  const bigArray = new Array(1_000_000).fill(0);

  const id = setInterval(() => {
    console.log(bigArray.length);
  }, 1000);

  // Later, when no longer needed:
  clearInterval(id);
}
```

#### Leaking event listener

```ts
const button = document.querySelector("button")!;

function onClick() {
  console.log("clicked");
}

button.addEventListener("click", onClick);

// Cleanup when done:
button.removeEventListener("click", onClick);
```

#### Leaking collection

```ts
const cache = new Map<string, object>();

function store(key: string, value: object) {
  cache.set(key, value);
}

// If values are no longer needed:
cache.clear();
// or
cache.delete("some-key");
```

### WeakMap for object-keyed metadata

Use `WeakMap` when metadata should not keep the key object alive.

```ts
const metadata = new WeakMap<object, { createdAt: number }>();

function attachMetadata(obj: object) {
  metadata.set(obj, { createdAt: Date.now() });
}

let item: object | null = { id: 1 };
attachMetadata(item);

item = null; // object and its metadata can be collected
```

### WeakRef for caches

```ts
class ImageCache {
  private ref: WeakRef<ImageBitmap> | null = null;

  set(image: ImageBitmap) {
    this.ref = new WeakRef(image);
  }

  get(): ImageBitmap | undefined {
    return this.ref?.deref();
  }
}
```

If the image is no longer referenced elsewhere, `get()` may return `undefined`.

### FinalizationRegistry for external cleanup

```ts
const registry = new FinalizationRegistry((resourceId: string) => {
  console.log(`Cleaning up external resource: ${resourceId}`);
});

function createResource() {
  const resource = { id: "gpu-buffer-1" };
  registry.register(resource, resource.id);
  return resource;
}

let r = createResource();
r = null; // cleanup callback may run later, not immediately
```

Do not rely on finalizers for correctness or timing.

## 4. Practical guidelines

- Do not try to force GC; there is no standard `gc()` in normal web/Node runtime APIs.
- Remove listeners, timers, observers, and subscriptions.
- Clear large arrays/maps when done.
- Use `WeakMap`/`WeakSet` for caches keyed by objects.
- Avoid retaining DOM nodes in long-lived closures.
- Use heap snapshots in Chrome DevTools or Node `--inspect` to find leaks.
- Treat `FinalizationRegistry` as a last-resort cleanup aid, not a destructor.

## Summary

TypeScript has no special GC syntax. You manage memory by managing references: reassign, remove listeners, clear collections, and use weak references where appropriate. The JavaScript engine then collects unreachable objects automatically.

## Typical garbage-collection mistake in TypeScript

### Mistaken version

```ts
function makeLogger(): () => void {
  // A large temporary value is created.
  const hugePayload = new Array(100_000).fill("x").join("");

  // The returned closure captures `hugePayload` by reference.
  // Even though we only need its length, the entire string stays reachable
  // as long as the returned function exists.
  return () => {
    console.log("payload length:", hugePayload.length);
  };
}

const log = makeLogger();
// ...later, `log` is still referenced somewhere...
```

### Corrected version

```ts
function makeLogger(): () => void {
  const hugePayload = new Array(100_000).fill("x").join("");

  // Extract only the small piece of data needed by the closure.
  const payloadLength = hugePayload.length;

  // `hugePayload` can now become unreachable once this function returns,
  // because the closure no longer references it.
  return () => {
    console.log("payload length:", payloadLength);
  };
}

const log = makeLogger();
// ...later...
```

---

### What was wrong and why

1. **Closures capture variables, not values**  
   In JavaScript/TypeScript, a closure keeps the entire lexical environment alive. If the closure references `hugePayload` *even indirectly* (for example by reading `.length`), the garbage collector must treat `hugePayload` as reachable for as long as the closure itself is reachable. The large string cannot be collected until every reference to the closure is gone.

2. **The “live” set is determined by reachability**  
   The GC does not collect objects that are still reachable from roots such as global variables, active closures, DOM nodes, timers, or event listeners. In the mistaken version, `hugePayload` remains reachable through the returned function.

3. **The fix narrows the retained graph**  
   By copying the needed primitive (`payloadLength`) into a new variable and referencing only that primitive in the closure, `hugePayload` becomes unreachable as soon as `makeLogger` finishes (assuming no other references). The GC can then reclaim the large string while the cheap logger function remains alive.

### Other common variants of the same class of bug

- **Event listeners keeping DOM nodes alive**  
  ```ts
  // Mistake: listener retains `element` and `data`
  element.addEventListener("click", () => use(data));

  // Fix: remove listener when done, or use WeakRef / AbortController
  const controller = new AbortController();
  element.addEventListener("click", () => use(data), { signal: controller.signal });
  // later: controller.abort();
  ```

- **Timers / intervals**  
  ```ts
  // Mistake: interval keeps `cache` alive forever
  setInterval(() => refresh(cache), 1000);

  // Fix: store id and clear when no longer needed
  const id = setInterval(() => refresh(cache), 1000);
  clearInterval(id);
  ```

- **Global caches without eviction**  
  ```ts
  // Mistake: unbounded Map retains everything
  const cache = new Map<string, LargeObject>();

  // Fix: use WeakMap when keys are objects, or add LRU eviction
  const cache = new WeakMap<object, LargeObject>();
  ```

- **Detached DOM trees**  
  Keeping a JavaScript reference to a removed DOM subtree keeps the whole subtree (and its event listeners) alive.

### Practical habit to reduce GC pressure

- Prefer **deriving small values early** instead of capturing large objects in long-lived closures.  
- Use **`WeakMap` / `WeakSet` / `WeakRef`** when you need metadata keyed by objects but don’t want to prolong their lifetime.  
- **Remove listeners and clear timers** in cleanup paths (component unmount, route change, `AbortController.abort()`).  
- Avoid accidental globals (e.g., assigning to an undeclared variable, which becomes a property of `globalThis` in non-strict mode).

These changes don’t make the GC “better”; they simply reduce the set of objects the runtime must treat as reachable.

## Common garbage-collection pitfalls in TypeScript / JavaScript

JavaScript engines (V8 in Node.js and Chromium) use tracing garbage collectors. Most “memory leaks” are not collector bugs; they are **unintended retained references**. The pitfalls below are the ones that show up repeatedly in TypeScript codebases.

---

### 1. Accidental global variables

In non-strict code, assigning to an undeclared identifier creates a property on the global object.

```ts
// bad
function leak() {
  // @ts-ignore (or compiled with strict:false)
  huge = "x".repeat(10_000_000);
}

// good
function noLeak() {
  const huge = "x".repeat(10_000_000);
  return huge.length;
}
```

**Fix:** use `"strict": true` in `tsconfig.json`, lint with `no-undef`, and avoid implicit globals.

---

### 2. Closures capturing more than they need

A closure keeps its entire lexical environment alive. Even if you only use one field, the engine may retain the whole outer scope in some cases.

```ts
type BigData = { meta: string; payload: Uint8Array };

// bad: returned function keeps `data` alive
function makeReporter(data: BigData) {
  return () => data.meta.toUpperCase();
}

// better: extract only what is needed
function makeReporter2(data: BigData) {
  const meta = data.meta;
  return () => meta.toUpperCase();
}
```

---

### 3. Forgotten event listeners

Listeners are strong references from the emitter to the callback and its captured scope.

```ts
class Widget {
  private onClick = () => this.render();

  mount(el: HTMLElement) {
    el.addEventListener("click", this.onClick);
  }

  // bad: never removed
  // good:
  unmount(el: HTMLElement) {
    el.removeEventListener("click", this.onClick);
  }
}
```

**Tip:** prefer `AbortController` for groups of listeners:

```ts
const ac = new AbortController();
el.addEventListener("click", handler, { signal: ac.signal });
// later
ac.abort(); // removes all listeners registered with this signal
```

---

### 4. Uncleared timers and intervals

```ts
// bad
setInterval(() => {
  console.log("still running");
}, 1000);

// good
const id = setInterval(() => {
  console.log("running");
}, 1000);

// on teardown
clearInterval(id);
```

Also clear timeouts in component unmount / process exit paths.

---

### 5. Detached DOM nodes (browser)

Removing a node from the document does not free it if JavaScript still references it or if a listener closure captures it.

```ts
let detached: HTMLDivElement | null = document.createElement("div");
detached.textContent = "huge".repeat(1000);
document.body.appendChild(detached);

// remove from DOM
detached.remove();

// bad: still referenced
// console.log(detached.textContent);

// good: drop reference
detached = null;
```

Also remove listeners attached to the node before dropping references.

---

### 6. Unbounded caches and collections

`Map`/`Set`/arrays grow forever unless you evict.

```ts
// bad
const cache = new Map<string, ExpensiveResult>();

function get(key: string) {
  if (!cache.has(key)) cache.set(key, compute(key));
  return cache.get(key)!;
}

// better: bounded LRU or WeakMap when keys are objects
import { LRUCache } from "lru-cache";
const cache2 = new LRUCache<string, ExpensiveResult>({ max: 500 });
```

For object-keyed metadata, use `WeakMap` so entries disappear when keys are collected:

```ts
const meta = new WeakMap<object, Meta>();
```

---

### 7. Arrays used as queues without trimming

`shift()` removes the element but engines may keep backing storage; repeated push/shift can retain capacity.

```ts
// bad for huge streams
const q: Item[] = [];
q.push(item);
const next = q.shift();

// better: index-based ring or linked list
class Queue<T> {
  private buf: T[] = [];
  private head = 0;

  push(v: T) { this.buf.push(v); }
  pop(): T | undefined {
    if (this.head >= this.buf.length) return undefined;
    const v = this.buf[this.head++];
    // periodically compact
    if (this.head > 1024 && this.head * 2 >= this.buf.length) {
      this.buf = this.buf.slice(this.head);
      this.head = 0;
    }
    return v;
  }
}
```

---

### 8. Promises and async work retaining scopes

An unresolved promise keeps its executor closure alive; chained `.then` keeps intermediate values alive until resolution.

```ts
// bad: `data` retained until promise resolves/rejects
function work(data: Huge) {
  return new Promise((resolve) => {
    setTimeout(() => resolve(data.id), 10_000);
  });
}

// better: resolve with primitive and avoid capturing large objects
function work2(data: Huge) {
  const id = data.id;
  return new Promise((resolve) => {
    setTimeout(() => resolve(id), 10_000);
  });
}
```

Also avoid storing promises in long-lived maps without cleanup.

---

### 9. Streams not destroyed

Node streams hold buffers and file descriptors until closed/destroyed.

```ts
import fs from "node:fs";

// bad
const s = fs.createReadStream("big.bin");
s.on("data", (chunk) => { /* ... */ });
// if error occurs, stream may hang

// good
const s2 = fs.createReadStream("big.bin");
s2.on("error", (err) => {
  console.error(err);
  s2.destroy();
});
s2.on("end", () => s2.destroy());
```

For HTTP responses, ensure `res.destroy()` on client disconnect.

---

### 10. `console.log` in DevTools / Node

Logging an object keeps it reachable in DevTools until the console is cleared; in Node, `console.log` is synchronous-ish but can retain in inspector sessions.

```ts
// bad in dev/prod hot paths
console.log("user", hugeUserObject);

// good
console.log("user id", hugeUserObject.id);
```

---

### 11. Not using weak references where appropriate

Use `WeakMap`, `WeakSet`, `WeakRef`, and `FinalizationRegistry` for caches and observers that should not keep objects alive.

```ts
// Metadata that should not extend object lifetime
const metadata = new WeakMap<object, { createdAt: number }>();

function annotate(obj: object) {
  metadata.set(obj, { createdAt: Date.now() });
}

// WeakRef for a cache entry
class Cache {
  private store = new Map<string, WeakRef<Expensive>>();

  get(key: string): Expensive | undefined {
    const ref = this.store.get(key);
    const val = ref?.deref();
    if (!val) this.store.delete(key);
    return val;
  }

  set(key: string, value: Expensive) {
    this.store.set(key, new WeakRef(value));
  }
}
```

**Caveat:** `FinalizationRegistry` callbacks are not deterministic and must not be used for correctness (e.g., releasing critical resources). Use explicit `dispose()` / `using` (TC39 explicit resource management) for determinism.

---

### 12. Circular references involving native resources

Modern GC handles JS object cycles fine, but native handles (file descriptors, GPU buffers, C++ addon objects) may require explicit cleanup.

```ts
class NativeBuffer {
  private handle: any; // from addon
  constructor(size: number) {
    this.handle = createNativeBuffer(size);
  }
  dispose() {
    freeNativeBuffer(this.handle);
    this.handle = null;
  }
  [Symbol.dispose]() { this.dispose(); }
}

// usage with explicit resource management (TS 5.2+ target)
{
  using buf = new NativeBuffer(1024);
  // ...
} // dispose() called here
```

---

### 13. Module-level singletons accumulating state

```ts
// bad: grows forever across requests
export const requestLog: Request[] = [];

export function handle(req: Request) {
  requestLog.push(req);
}
```

**Fix:** bound the log, use a ring buffer, or stream to disk/external store.

---

### 14. Binding functions in hot paths

Creating new bound functions or arrow functions in loops/render passes creates many short-lived closures. Usually fine, but in tight loops or with listeners it can amplify GC pressure.

```ts
// in a hot loop
for (const item of items) {
  // bad: new closure each iteration retained by listener
  el.addEventListener("click", () => onClick(item));
}

// better: delegate
el.addEventListener("click", (e) => {
  const id = (e.target as HTMLElement).dataset.id;
  onClick(id);
});
```

---

### 15. Holding references in error objects / stack traces

Errors capture stack traces and sometimes local variables in optimized code; storing errors long-term retains their scopes.

```ts
// bad
const errors: Error[] = [];
try { ... } catch (e) {
  errors.push(e as Error); // retains stack + closure scope
}

// better: store minimal info
errors.push({ message: (e as Error).message, stack: (e as Error).stack });
```

---

## Practical debugging checklist

1. **Node.js flags**
   ```bash
   node --expose-gc --inspect app.js
   ```
   Then in code:
   ```ts
   if (global.gc) global.gc();
   console.log(process.memoryUsage());
   ```

2. **Heap snapshots** in Chrome DevTools / Node inspector; look for retained detached DOM nodes, closures, and arrays.

3. **Allocation timeline** to find hot allocation sites.

4. **Leak detection tools**: `clinic.js`, `memwatch-next`, `heapdump`.

5. **TypeScript config**
   ```json
   {
     "compilerOptions": {
       "strict": true,
       "noImplicitAny": true,
       "strictNullChecks": true
     }
   }
   ```

6. **Lint rules**: `eslint-plugin-no-undef`, custom rules for `addEventListener`/`setTimeout` pairing.

---

### Summary mental model

- GC frees objects **only when unreachable** from roots (globals, stack, active closures, DOM, etc.).
- In TypeScript, the compiler does not manage memory; runtime references do.
- Prefer **explicit cleanup** (remove listeners, clear timers, destroy streams, dispose native resources) and **weak references** for caches/observers.
- Treat `FinalizationRegistry` as a safety net, not a resource-management strategy.

## Exercise

You have a `ProfileCache` that stores profiles by `User` object, plus a polling helper that calls a callback every second. In a long-running app, users are created and discarded. The current code keeps discarded users alive and never stops timers.

**Task:** refactor the code so that:

1. The cache does not prevent a `User` from being garbage collected.
2. Callers can stop the polling when they are done.
3. The code remains type-safe TypeScript.

### Starter code

```ts
type User = { id: string };
type Profile = { bio: string; avatar: Uint8Array };

class ProfileCache {
  private entries = new Map<User, Profile>();

  get(user: User): Profile | undefined {
    return this.entries.get(user);
  }

  set(user: User, profile: Profile): void {
    this.entries.set(user, profile);
  }
}

function watchUser(user: User, onSeen: (u: User) => void): void {
  setInterval(() => onSeen(user), 1000);
}
```

---

## Step-by-step solution

### Step 1: Identify the strong references

- `Map<User, Profile>` stores a strong reference to each `User` key. Even if the rest of the app drops the user, the cache keeps it alive, along with its `Profile`, including the large `avatar` buffer.
- `setInterval` returns a timer handle, but the starter code ignores it. The closure captures `user` and `onSeen`, so the timer keeps both alive forever.

### Step 2: Use `WeakMap` for object-keyed caches

`WeakMap` keys are held weakly. If a `User` becomes unreachable elsewhere, the cache entry can be collected too. This is exactly the intended tool for caches keyed by objects.

```ts
private entries = new WeakMap<User, Profile>();
```

Important limitation: `WeakMap` is not iterable and has no `size`. That is acceptable for a cache lookup; you usually do not need to enumerate cache entries.

### Step 3: Return a cleanup function for polling

Instead of fire-and-forget `setInterval`, return a function that clears the interval. Callers own the lifetime of the polling.

```ts
function watchUser(user: User, onSeen: (u: User) => void): () => void {
  const timer = setInterval(() => onSeen(user), 1000);
  return () => clearInterval(timer);
}
```

### Step 4: Optional: observe collection with `FinalizationRegistry`

If you need cleanup when an object is collected, use `FinalizationRegistry`. Do not use it for essential program logic because collection timing is not guaranteed.

```ts
const registry = new FinalizationRegistry<string>((id) => {
  console.log("User collected:", id);
});
```

### Step 5: Usage pattern

```ts
const cache = new ProfileCache();

let user: User | null = { id: "42" };
cache.set(user, { bio: "hello", avatar: new Uint8Array(1024) });

const stopWatching = watchUser(user, (u) => {
  console.log("seen", u.id);
});

// Later, when done:
stopWatching();
user = null; // cache no longer keeps the user alive
```

---

## Final solution

```ts
type User = { id: string };
type Profile = { bio: string; avatar: Uint8Array };

class ProfileCache {
  // WeakMap does not keep keys alive.
  private entries = new WeakMap<User, Profile>();

  get(user: User): Profile | undefined {
    return this.entries.get(user);
  }

  set(user: User, profile: Profile): void {
    this.entries.set(user, profile);
  }

  has(user: User): boolean {
    return this.entries.has(user);
  }
}

/**
 * Polls a user until the returned cleanup function is called.
 * The caller is responsible for stopping the timer.
 */
function watchUser(user: User, onSeen: (u: User) => void): () => void {
  const timer = setInterval(() => onSeen(user), 1000);
  return () => clearInterval(timer);
}

// Optional diagnostic helper. Do not rely on this for required cleanup.
const collectedUsers = new FinalizationRegistry<string>((id) => {
  // This runs only if/when the observed object is collected.
  // Timing is implementation-dependent and not guaranteed.
  console.debug("Collected user:", id);
});

export { ProfileCache, watchUser, collectedUsers };
```

### Key takeaways

- Prefer `WeakMap` for caches keyed by objects.
- Always store and clear timer handles.
- Never assume garbage collection happens immediately or predictably.
- Use `FinalizationRegistry` only for diagnostics or non-critical cleanup, not correctness.

## Garbage Collection in TypeScript (JavaScript runtime)

TypeScript itself has no garbage collector; it compiles to JavaScript and relies on the host engine (V8 in Node/Chrome, SpiderMonkey in Firefox, JavaScriptCore in Safari). The core ideas:

1. **Reachability, not reference counting alone**  
   An object is kept alive if it is reachable from a *root* (global object, current stack frames, CPU registers, closures, etc.). Reference counting alone cannot collect cycles, so engines use **tracing GC**.

2. **Generational hypothesis**  
   Most objects die young. V8 splits the heap into:
   - **Young generation** (nursery + survivor): collected frequently with a fast **Scavenge** (semi-space copying) collector.
   - **Old generation**: collected less often with **Mark-Sweep-Compact** (mark reachable, sweep dead, compact to reduce fragmentation).

3. **Mark phase**  
   Start from roots, traverse references, mark every reachable object.

4. **Sweep phase**  
   Walk the heap; unmarked objects are freed. (Compact phase may move survivors to reduce fragmentation.)

5. **Write barriers**  
   When an old object gets a reference to a young object, a write barrier records it so young GC doesn’t miss it.

6. **Modern features**  
   Incremental/concurrent marking, idle-time GC, `WeakRef`, `FinalizationRegistry`, `WeakMap`/`WeakSet`.

---

## Toy implementation: core of a tracing mark-and-sweep GC

Below is a minimal, educational GC in TypeScript. It models objects, references, roots, marking, and sweeping.

```ts
// gc.ts

/** A heap object tracked by our mini GC. */
class HeapObject {
  constructor(
    public readonly id: number,
    public refs: HeapObject[] = [],
    public data: unknown = null,
  ) {
    this.marked = false;
  }
  marked: boolean;
}

/**
 * Minimal tracing garbage collector.
 * Core algorithm: mark reachable objects from roots, then sweep the rest.
 */
class MiniGC {
  private objects = new Map<number, HeapObject>();
  private roots = new Set<HeapObject>();
  private nextId = 1;

  /** Allocate a new object on the (simulated) heap. */
  allocate(refs: HeapObject[] = [], data: unknown = null): HeapObject {
    const obj = new HeapObject(this.nextId++, refs, data);
    this.objects.set(obj.id, obj);
    return obj;
  }

  /** Register an object as a GC root (e.g. global variable). */
  addRoot(obj: HeapObject): void {
    this.roots.add(obj);
  }

  /** Remove a root (variable goes out of scope / reassigned). */
  removeRoot(obj: HeapObject): void {
    this.roots.delete(obj);
  }

  /** Run a full collection cycle. */
  collect(): void {
    // 1. Reset marks for all currently allocated objects.
    for (const obj of this.objects.values()) {
      obj.marked = false;
    }

    // 2. MARK: iterative DFS from roots to avoid recursion-depth issues.
    const worklist: HeapObject[] = [...this.roots];
    while (worklist.length > 0) {
      const current = worklist.pop()!;

      // Already visited; skip to avoid infinite loops on cycles.
      if (current.marked) continue;

      current.marked = true;

      // Push all outgoing references for traversal.
      for (const ref of current.refs) {
        if (!ref.marked) {
          worklist.push(ref);
        }
      }
    }

    // 3. SWEEP: delete every object that was not marked.
    for (const [id, obj] of this.objects) {
      if (!obj.marked) {
        // Detach references to help the host GC if this were real memory.
        obj.refs = [];
        this.objects.delete(id);
      }
    }
  }

  /** Number of live objects after last collection (for tests/metrics). */
  size(): number {
    return this.objects.size;
  }

  /** Debug helper: print heap state. */
  dump(): void {
    console.log(`Heap size: ${this.objects.size}`);
    for (const obj of this.objects.values()) {
      console.log(`  #${obj.id} marked=${obj.marked} refs=[${obj.refs.map(r => r.id).join(",")}] data=${obj.data}`);
    }
  }
}

// ---------------- Example usage ----------------

const gc = new MiniGC();

// Create a cycle: A <-> B
const a = gc.allocate([], "A");
const b = gc.allocate([], "B");
a.refs.push(b);
b.refs.push(a);

// Root only A (B becomes reachable through A)
const rootA = a;
gc.addRoot(rootA);

console.log("Before collect:", gc.size()); // 2
gc.collect();
console.log("After collect (cycle kept):", gc.size()); // 2

// Drop the root: both A and B should be collected despite the cycle.
gc.removeRoot(rootA);
gc.collect();
console.log("After dropping root:", gc.size()); // 0

// Demonstrate an unreachable island
const x = gc.allocate([], "X");
const y = gc.allocate([x], "Y");
// neither x nor y is rooted
gc.collect();
console.log("Island collected:", gc.size()); // 0
```

### Key points to mention in an interview

- **TypeScript/JS GC is not manually controlled**; you only influence it by removing references (`null`, clearing arrays/maps, removing listeners).
- **Cycles are fine** for tracing GC; not fine for naive reference counting.
- **Performance knobs**: avoid creating garbage in hot loops, reuse objects, use object pools, be careful with closures capturing large scopes.
- **Node.js**: run with `node --expose-gc` and call `global.gc()` only for debugging/benchmarks, never in production logic.
- **Weak references**: use `WeakMap`/`WeakRef`/`FinalizationRegistry` when you need caches that don’t keep objects alive.

If you want, I can extend this toy GC with **generations (young/old)** or **incremental marking** next.

TypeScript itself has no manual “free”/“delete”; GC is performed by the JS engine (V8, SpiderMonkey, etc.). The edge cases are therefore **patterns that accidentally keep references alive**, plus modern weak-reference APIs whose semantics are easy to misuse.

Below are the common cases, each with a “leaky” example and a corrected version.

---

## 1. Closures capturing more than needed

A closure keeps the entire lexical environment alive, even variables it never reads.

```ts
function processLargeData() {
  const huge = new Array(1_000_000).fill("x");
  const small = huge.length;

  // BAD: closure captures `huge` too (engine may retain whole scope)
  return () => console.log(small);
}

// GOOD: isolate the value so the big object can be collected
function processLargeDataFixed() {
  const huge = new Array(1_000_000).fill("x");
  const small = huge.length;
  // drop reference before returning closure
  // (reassigning isn't always required, but scoping helps)
  return (() => {
    // only `small` is in this closure's scope
    return () => console.log(small);
  })();
}
```

**Rule:** return closures that close over the smallest possible scope; avoid keeping “temporary” large objects in the same function scope as long-lived callbacks.

---

## 2. Event listeners never removed

```ts
class Widget {
  private handler = (e: MouseEvent) => this.onClick(e);

  mount(el: HTMLElement) {
    // BAD: anonymous arrow or bound method keeps `this` alive forever
    el.addEventListener("click", this.handler);
  }

  unmount(el: HTMLElement) {
    // GOOD: remove the exact same reference
    el.removeEventListener("click", this.handler);
  }

  private onClick(e: MouseEvent) { /* ... */ }
}
```

**Edge case:** `addEventListener` with `{ once: true }` auto-removes after first fire, but still holds the listener until then. Also, removing requires **reference equality**—a fresh arrow function won’t match.

---

## 3. Timers holding closures

```ts
function startPolling() {
  const data = loadHugeObject();

  // BAD: interval keeps `data` alive until cleared
  const id = setInterval(() => {
    console.log(data.id);
  }, 1000);

  // GOOD: store id and clear; null references inside callback
  return () => {
    clearInterval(id);
  };
}
```

`setTimeout` with long delays has the same issue. Always pair creation with cleanup (React `useEffect` cleanup, `AbortController`, etc.).

---

## 4. Detached DOM nodes (browser)

```ts
let detached: HTMLDivElement | null = document.createElement("div");
detached.textContent = "big".repeat(100_000);

// BAD: global/module variable keeps detached subtree alive
// (and its event listeners)

// GOOD: null it when done, and remove listeners first
function release() {
  detached?.removeEventListener("click", onClick);
  detached = null;
}
```

**Edge case:** A node removed from the document but still referenced by JS (or by an event listener closure) is “detached” and won’t be GC’d. Also, `childNodes`/`parent` references can keep whole subtrees alive.

---

## 5. Unbounded caches (Map/Set)

```ts
// BAD: grows forever
const cache = new Map<string, BigObject>();
function get(key: string) {
  if (!cache.has(key)) cache.set(key, compute(key));
  return cache.get(key)!;
}

// GOOD: bounded LRU or WeakMap when keys are objects
const weakCache = new WeakMap<object, Result>();
function getFor(obj: object) {
  let r = weakCache.get(obj);
  if (!r) {
    r = compute(obj);
    weakCache.set(obj, r);
  }
  return r;
}
```

**Edge case:** `WeakMap` keys must be objects (not primitives). Values are strongly held while the key is alive—so a WeakMap won’t save you if values capture keys (circular strong reference).

---

## 6. Circular references

Modern engines collect cycles, but **external resources** (file handles, sockets) are not GC-managed automatically.

```ts
class Node {
  parent?: Node;
  children: Node[] = [];
}

// Cycle alone is fine for GC:
const a = new Node();
const b = new Node();
a.children.push(b);
b.parent = a;

// But if you attach a non-GC resource, break manually:
class ResourceHolder {
  private socket: WebSocket;
  private node: Node;
  dispose() {
    this.socket.close();
    this.node = null as any; // help GC + prevent use-after-dispose
  }
}
```

**Edge case:** In older engines (and some interop boundaries like COM/ActiveX), cycles leak. In TS/Node, cycles are collectible, but **finalizers are not guaranteed to run promptly**, so don’t rely on GC for resource cleanup—use `dispose()`/`using` (TC39 Explicit Resource Management).

```ts
class FileHandle implements Disposable {
  [Symbol.dispose]() { this.close(); }
  close() { /* ... */ }
}

// TS 5.2+ with --lib esnext.disposable
{
  using f = new FileHandle();
  // auto-disposed at block end
}
```

---

## 7. `WeakRef` and `FinalizationRegistry` misuse

```ts
const ref = new WeakRef({ data: "big" });

// BAD: assuming deref() is non-null
function use() {
  const o = ref.deref();
  o!.data; // may be undefined after GC
}

// GOOD: always null-check
function useFixed() {
  const o = ref.deref();
  if (!o) return; // object was collected
  console.log(o.data);
}

// FinalizationRegistry: non-deterministic timing
const registry = new FinalizationRegistry((held: string) => {
  console.log("collected:", held);
});
registry.register({ id: 1 }, "id-1");
// Do NOT rely on this for correctness (e.g., releasing locks, closing files).
```

**Edge cases:**
- `WeakRef` target may be collected between any two lines; never cache `deref()` result across async boundaries without re-checking.
- `FinalizationRegistry` callbacks run on the main thread, possibly much later, and may not run at all on process exit.
- Holding the registry itself or the target strongly prevents collection.

---

## 8. Streams and buffers (Node.js)

```ts
import { createReadStream } from "fs";

// BAD: stream not consumed/destroyed keeps fd + buffers
const s = createReadStream("big.txt");
s.on("data", () => {}); // if paused/abandoned, fd leaks

// GOOD
const s2 = createReadStream("big.txt");
s2.on("data", chunk => process(chunk));
s2.on("end", () => s2.destroy());
s2.on("error", () => s2.destroy());

// ArrayBuffer views keep the whole buffer alive
const buf = new ArrayBuffer(100_000_000);
const view = new Uint8Array(buf, 0, 10); // still pins entire 100MB
// For large slices, copy:
const small = new Uint8Array(buf.slice(0, 10)); // new backing store
```

---

## 9. Observers not disconnected

```ts
const observer = new IntersectionObserver(entries => { /* ... */ });
observer.observe(el);

// BAD: observer keeps callback + target alive

// GOOD
observer.disconnect(); // or unobserve(el)
```

Same for `MutationObserver`, `ResizeObserver`, `PerformanceObserver`.

---

## 10. `console.log` / DevTools retaining objects

```ts
const obj = { huge: new Array(1e6) };
console.log(obj); // DevTools keeps a reference for inspection
```

In production this is usually fine, but in long-running debugging sessions, logged objects won’t be collected. Avoid logging large objects; log summaries instead.

---

## 11. Promises and async closures

```ts
async function run() {
  const huge = await fetchHuge();
  // BAD: returned promise chain keeps `huge` alive until resolved
  return delay(1000).then(() => huge.id);

  // GOOD: extract primitive, let `huge` go out of scope
  const id = huge.id;
  // huge can be collected once this scope exits (modulo engine optimizations)
  return delay(1000).then(() => id);
}
```

Also, unhandled promise rejections can keep closures alive; always `catch`.

---

## 12. Module-level / global state

```ts
// module.ts
export const globalCache = new Map(); // lives for process lifetime

// BAD: storing per-request data here leaks across requests (server)
export function handle(req: Request) {
  globalCache.set(req.id, req); // never evicted
}

// GOOD: request-scoped weak map or LRU with TTL
```

In SSR/Node servers, module singletons are a common source of cross-request leaks.

---

## 13. Array methods creating references

```ts
const arr = [bigA, bigB, bigC];
const slice = arr.slice(1); // new array, but elements shared (fine)
const filtered = arr.filter(x => x.id > 1); // new array, elements shared

// Danger: storing derived arrays that retain elements you thought were dropped
```

Not a leak per se, but note that “removing” from an array with `splice` drops references; reassigning `arr.length = 0` drops all.

---

## 14. TypeScript-specific: type-only imports and metadata

Type-only constructs are erased, so they don’t affect GC. But `emitDecoratorMetadata` + `reflect-metadata` can retain constructor references:

```ts
// With reflect-metadata, class metadata is stored in a global Map keyed by class
@Reflect.metadata("design:type", Object)
class Foo { bar!: BigType; }
// This keeps `BigType` referenced via metadata even if unused at runtime.
```

If you use decorators heavily, audit metadata retention; prefer `erasableSyntaxOnly` / no metadata where not needed.

---

## Practical checklist

- Pair every `addEventListener`/`observe`/`subscribe` with removal.
- Pair every `setInterval`/`setTimeout` with `clear*`.
- Use `WeakMap`/`WeakSet` for object-keyed caches; add bounds/TTL to others.
- Null out large temporaries and detached nodes.
- Never rely on `FinalizationRegistry` for correctness or prompt cleanup; use explicit `dispose()`/`using`.
- Copy slices of large `ArrayBuffer`s instead of keeping views.
- Disconnect streams/observers; destroy on error.
- Audit module-level state in server code.
- Test with `--expose-gc` (Node) + `global.gc()` in tests to assert collection, and use Chrome DevTools heap snapshots.

Example test snippet:

```ts
// node --expose-gc test.mjs
global.gc?.();
const before = process.memoryUsage().heapUsed;
// ... allocate + release ...
global.gc?.();
const after = process.memoryUsage().heapUsed;
console.log("delta", after - before);
```

If you want, I can tailor this to a specific runtime (Node, browser, Deno/Bun) or framework (React, Angular).

## 1. Native generators (the idiomatic way)

TypeScript supports ES2015 generators directly. Save as `generators.ts`:

```ts
// generators.ts
// Run with: npx ts-node generators.ts   (or tsc && node generators.js)

// ---------- 1. Basic generator ----------
function* countdown(n: number): Generator<number, string, unknown> {
  while (n > 0) {
    yield n--;          // pause here, send value out
  }
  return "done";       // final value, ends iteration
}

console.log("--- countdown ---");
const g = countdown(3);
console.log(g.next()); // { value: 3, done: false }
console.log(g.next()); // { value: 2, done: false }
console.log(g.next()); // { value: 1, done: false }
console.log(g.next()); // { value: "done", done: true }

// Generators are iterable, so for...of works:
for (const v of countdown(3)) console.log("for..of:", v);

// ---------- 2. Infinite sequence ----------
function* naturals(): Generator<number> {
  let i = 0;
  while (true) yield i++;
}
// Take only first 5:
console.log("--- naturals(5) ---");
console.log([...take(naturals(), 5)]); // [0,1,2,3,4]

function* take<T>(it: Iterable<T>, n: number): Generator<T> {
  let i = 0;
  for (const x of it) {
    if (i++ >= n) return;
    yield x;
  }
}

// ---------- 3. Two-way communication ----------
function* echo(): Generator<string, void, string> {
  let msg = yield "ready";   // receives value passed to next(msg)
  console.log("received:", msg);
  yield "ack";
}
const e = echo();
console.log(e.next());        // { value: "ready", done: false }
console.log(e.next("hello")); // received: hello -> { value: "ack", done: false }

// ---------- 4. Delegation with yield* ----------
function* inner(): Generator<number> {
  yield 10;
  yield 20;
}
function* outer(): Generator<number | string> {
  yield "start";
  yield* inner();   // delegates to inner generator
  yield "end";
}
console.log("--- delegation ---");
console.log([...outer()]); // [ 'start', 10, 20, 'end' ]

// ---------- 5. Async generator ----------
async function* fetchPages(urls: string[]): AsyncGenerator<string> {
  for (const url of urls) {
    // simulate async work
    const data = await Promise.resolve(`data from ${url}`);
    yield data;
  }
}
(async () => {
  console.log("--- async ---");
  for await (const page of fetchPages(["a", "b"])) console.log(page);
})();
```

