## 2. Implementing a generator-like iterator *by hand*

Generators are syntactic sugar over the **Iterator protocol**. Here is a manual re-implementation of `range(start, end, step)` that behaves like a generator, without `function*`:

```ts
// manual-iterator.ts

interface RangeOptions {
  start: number;
  end: number;       // exclusive
  step?: number;
}

class RangeIterator implements Iterator<number>, Iterable<number> {
  private current: number;
  private readonly end: number;
  private readonly step: number;
  private done = false;

  constructor({ start, end, step = 1 }: RangeOptions) {
    if (step === 0) throw new Error("step cannot be 0");
    this.current = start;
    this.end = end;
    this.step = step;
  }

  next(): IteratorResult<number> {
    if (this.done) return { value: undefined, done: true };

    // handle direction correctly for negative steps
    const inRange =
      this.step > 0 ? this.current < this.end : this.current > this.end;

    if (!inRange) {
      this.done = true;
      return { value: undefined, done: true };
    }

    const value = this.current;
    this.current += this.step;
    return { value, done: false };
  }

  // Iterable protocol: allows for...of / spread
  [Symbol.iterator](): Iterator<number> {
    return this;
  }

  // Optional but polite: support early termination
  return(value?: any): IteratorResult<number> {
    this.done = true;
    return { value, done: true };
  }
}

// Factory with ergonomics similar to a generator function:
function range(start: number, end: number, step = 1): Iterable<number> {
  return new RangeIterator({ start, end, step });
}

// ---- usage ----
console.log([...range(0, 5)]);        // [0,1,2,3,4]
console.log([...range(5, 0, -1)]);    // [5,4,3,2,1]

for (const n of range(2, 8, 2)) console.log("manual:", n);

// Early termination triggers return() via for...of break:
for (const n of range(0, 100)) {
  if (n === 3) break;
  console.log("break at", n);
}
```

---

## 3. A tiny “coroutine” scheduler (advanced)

To show *why* generators are powerful, here is a minimal cooperative scheduler that runs generator-based “tasks”. Each task `yield`s a delay (ms); the scheduler resumes it later:

```ts
// scheduler.ts

type Task = Generator<number, void, unknown>;

function run(tasks: Task[]): void {
  const queue: Task[] = [...tasks];

  const tick = () => {
    // snapshot current size; newly pushed tasks run next tick
    const batch = queue.splice(0, queue.length);
    for (const t of batch) {
      const { value, done } = t.next();
      if (done) continue;
      // value is ms to wait
      setTimeout(() => {
        queue.push(t);
        // resume loop if queue empty trigger
        if (queue.length === 1) tick();
      }, value as number);
    }
    if (queue.length === 0) return;
  };

  tick();
}

function* taskA(): Task {
  console.log("A: start");
  yield 100;
  console.log("A: after 100ms");
  yield 50;
  console.log("A: done");
}

function* taskB(): Task {
  console.log("B: start");
  yield 30;
  console.log("B: after 30ms");
  yield 200;
  console.log("B: done");
}

run([taskA(), taskB()]);
```

