## Generators in TypeScript

A **generator** is a function that can be *paused* and *resumed*. Instead of running to completion, it yields values one at a time (lazily) and keeps its local state between calls.

```ts
function* counter(start = 0) {
  let n = start;
  while (true) {
    // `yield` pauses here and sends `n` to the caller;
    // the next `next(v)` resumes and makes `v` the result of this yield.
    const reset = yield n++;
    if (reset) n = start;
  }
}

const g = counter(10);
g.next();        // { value: 10, done: false }
g.next();        // { value: 11, done: false }
g.next(true);    // { value: 10, done: false }  // sent value back in
g.return(999);   // { value: 999, done: true }  // force completion
```

Key ideas:
- **Lazy**: nothing runs until you call `.next()`.
- **Stateful**: locals survive across pauses.
- **Bidirectional**: `next(value)` feeds a value *into* the generator; `yield` produces one *out*.
- **Protocol**: a generator is an iterator — it implements `{ next, return, throw, [Symbol.iterator] }`.
- **`yield*`** delegates to another iterable/generator.
- Under the hood, a compiler transforms `function*` into a **state machine** (a `switch` over states) plus a resume mechanism.

---

## Implementing the core (state machine + protocol)

Below is a hand-written generator equivalent to `function* range(start, end)` with full `next/return/throw` support. This is essentially what a transpiler (e.g. Babel/TS `downlevelIteration`) produces.

```ts
// ---------- Types ----------

type IteratorResult<T, TReturn> =
  | { value: T; done: false }
  | { value: TReturn; done: true };

interface Generator<T = unknown, TReturn = any, TNext = unknown>
  extends Iterator<T, TReturn, TNext> {
  next(value?: TNext): IteratorResult<T, TReturn>;
  return(value?: TReturn): IteratorResult<T, TReturn>;
  throw(error?: any): IteratorResult<T, TReturn>;
  [Symbol.iterator](): Generator<T, TReturn, TNext>;
}

// ---------- A manual state-machine generator ----------

/**
 * Equivalent to:
 *   function* range(start, end) {
 *     for (let i = start; i < end; i++) yield i;
 *     return end;
 *   }
 *
 * Implemented as a switch-based state machine so you can see the "core".
 */
function rangeGenerator(start: number, end: number): Generator<number, number, unknown> {
  // --- mutable closure state (survives across pauses) ---
  let i = start;
  let state = 0;          // 0 = loop check, 1 = resumed after yield, 2 = done
  let completed = false;
  let returnValue: number | undefined;

  const gen: Generator<number, number, unknown> = {
    // Advance one step. `value` is what the caller sends back in.
    next(_value?: unknown): IteratorResult<number, number> {
      if (completed) return { value: returnValue as number, done: true };

      // Run until we either yield or finish.
      while (true) {
        switch (state) {
          case 0: // check loop condition
            if (i < end) {
              const yielded = i++;
              state = 1; // pause point: next call resumes at case 1
              return { value: yielded, done: false };
            }
            // loop finished -> produce return value
            state = 2;
            returnValue = end;
            completed = true;
            return { value: end, done: true };

          case 1: // resumed after a yield (value sent via next() is ignored here)
            state = 0;
            break; // re-check loop condition

          case 2:
            completed = true;
            return { value: returnValue as number, done: true };
        }
      }
    },

    // Force completion with a value (runs finally blocks in real generators).
    return(value?: number): IteratorResult<number, number> {
      completed = true;
      returnValue = value ?? end;
      return { value: returnValue, done: true };
    },

    // Propagate an error into the generator (would be thrown at the yield point).
    throw(error?: any): IteratorResult<number, number> {
      completed = true;
      throw error; // in a real generator this is thrown at the suspended yield
    },

    [Symbol.iterator](): Generator<number, number, unknown> {
      return gen; // generators are their own iterators
    },
  };

  return gen;
}

// ---------- Demo ----------

const g = rangeGenerator(2, 5);

console.log(g.next()); // { value: 2, done: false }
console.log(g.next()); // { value: 3, done: false }
console.log(g.next()); // { value: 4, done: false }
console.log(g.next()); // { value: 5, done: true }
console.log(g.next()); // { value: 5, done: true }  (already done)

// Lazy + iterable protocol:
const collected = [...rangeGenerator(0, 4)];
console.log(collected); // [0, 1, 2, 3]

// Early termination via return():
const g2 = rangeGenerator(0, 10);
console.log(g2.next());    // { value: 0, done: false }
console.log(g2.return(42)); // { value: 42, done: true }
```

### What this demonstrates

1. **State machine**: `state` encodes where execution is paused; `next()` advances it. A real compiler does exactly this, with each `yield` becoming a `case` + `return`.
2. **Closure state**: `i` survives across calls because it lives in the closure, mimicking generator locals.
3. **Protocol**: `.next/.return/.throw/[Symbol.iterator]` make it a valid iterator/`Iterable`.
4. **Laziness**: values are produced only on `.next()`, so infinite generators are possible (just never set `completed`).

### What's simplified vs. real generators

- **`next(value)` feeding in**: here `_value` is ignored; a real implementation routes the sent value to become the result of the current `yield` expression (requires the state machine to store and use it).
- **`throw`**: real generators throw *at the suspension point*, allowing `try/catch` inside the generator to handle it; here we just terminate.
- **`finally` / cleanup**: real `.return()` resumes the generator so `finally` blocks run before completion.
- **`yield*`**: delegation is handled by the runtime pushing/popping generator frames.
- **Async generators** (`async function*`) add a Promise layer on top of the same protocol.

In production TypeScript, you almost never write this by hand — you write `function*` and let the compiler/runtime handle the state machine. But this is the core mechanism behind it.

Generators in TypeScript look simple (`function*` + `yield`), but most bugs come from **types that lie about runtime**, **partial consumption**, **cleanup**, and **async boundaries**. Below are the edge cases that matter most, with runnable examples.

---

## 1. `yield`’s received value is typed, but may be `undefined` at runtime

TypeScript types `const x = yield value` as `TNext`, but calling `.next()` without an argument passes `undefined`.

```ts
function* gen(): Generator<number, void, string> {
  const received = yield 1; // TS: string
  console.log(received.toUpperCase()); // runtime crash if next() has no arg
}

const g = gen();
g.next();          // { value: 1, done: false }
g.next();          // received is undefined -> crash
```

**Handle it:** include `undefined` in `TNext`, or guard.

```ts
function* gen(): Generator<number, void, string | undefined> {
  const received = yield 1;
  if (received !== undefined) {
    console.log(received.toUpperCase());
  }
}
```

---

## 2. You must narrow `done` before using `value`

`IteratorResult<TYield, TReturn>` is a union. TypeScript narrows only after checking `done`.

```ts
function* gen(): Generator<number, string, void> {
  yield 1;
  return "finished";
}

const g = gen();
let r = g.next();

while (!r.done) {
  console.log(r.value); // number
  r = g.next();
}

console.log(r.value); // string
// console.log(r.value.toUpperCase()); // OK here, but not before narrowing
```

If you skip the check, `r.value` is `number | string`.

---

## 3. `for...of` ignores the generator’s return value

`for...of` consumes yields and stops at `done: true`, discarding `TReturn`.

```ts
function* gen(): Generator<number, string, void> {
  yield 1;
  yield 2;
  return "ignored by for...of";
}

for (const x of gen()) {
  console.log(x); // 1, 2 only
}
```

**Handle it:** use manual iteration or `yield*` if you need the final value.

```ts
function* outer() {
  const result = yield* gen(); // result: string
  yield `got: ${result}`;
}
```

---

## 4. Partial consumption must trigger cleanup

If a consumer breaks early, TypeScript/JS calls `.return()` on the generator, which runs `finally`.

```ts
function* gen() {
  try {
    yield 1;
    yield 2;
    yield 3;
  } finally {
    console.log("cleanup runs on break/return/throw");
  }
}

for (const x of gen()) {
  if (x === 2) break; // triggers return()
}
```

**Handle it:** put resource cleanup in `finally`, not after the last `yield`.

---

## 5. `return()` and `throw()` can resume or close the generator

- `.return(value)` forces completion; `finally` runs.
- `.throw(error)` resumes at the current `yield` as if that yield threw.

```ts
function* gen() {
  try {
    yield 1;
  } catch (e) {
    yield `caught: ${e}`;
  } finally {
    console.log("finally");
  }
}

const g = gen();
g.next();
console.log(g.throw(new Error("boom")).value); // "caught: Error: boom"
console.log(g.next().done);                    // true
```

If there is **no** matching `catch`, the thrown error propagates and the generator closes.

---

## 6. A closed generator ignores later `.next(arg)`

After completion, further `next()` calls return `{ done: true, value: undefined }`, ignoring any argument.

```ts
function* gen() {
  yield 1;
  return 2;
}

const g = gen();
g.next();              // { value: 1, done: false }
g.next();              // { value: 2, done: true }
console.log(g.next("ignored")); // { value: undefined, done: true }
```

---

## 7. `yield*` delegates both values and control operations

`yield*` delegates iteration, `.return()`, and `.throw()` to the inner generator. Its expression type is the inner generator’s `TReturn`.

```ts
function* inner(): Generator<number, string, void> {
  try {
    yield 1;
    yield 2;
  } finally {
    console.log("inner cleanup");
  }
  return "inner done";
}

function* outer() {
  const result: string = yield* inner();
  yield result;
}

const g = outer();
console.log(g.next().value); // 1
g.return("stop");            // propagates return to inner -> cleanup runs
console.log(g.next().done);  // true
```

---

## 8. `this` binding when extracting generator methods

Generator functions are not arrow functions. Extracting a method loses `this`.

```ts
class Counter {
  value = 0;
  *gen() {
    yield this.value;
  }
}

const c = new Counter();
const fn = c.gen;     // unbound
// const g = fn();    // this is undefined -> runtime error

const bound = c.gen.bind(c);
const g2 = bound();
console.log(g2.next().value); // 0
```

---

## 9. Async generators: cleanup must be awaited

Async generators return promises from `.return()` and `.throw()`. If you don’t await them, cleanup may not finish.

```ts
async function* agen() {
  try {
    yield 1;
    await new Promise(r => setTimeout(r, 1000));
    yield 2;
  } finally {
    await new Promise(r => setTimeout(r, 100));
    console.log("async cleanup done");
  }
}

const g = agen();
g.next();
await g.return(undefined); // await cleanup
```

---

## 10. Async generators do not cancel themselves

There is no built-in cancellation. You must check an `AbortSignal` (or a flag) between yields.

```ts
async function* agen(signal: AbortSignal) {
  let i = 0;
  while (!signal.aborted) {
    await new Promise(r => setTimeout(r, 50));
    yield i++;
  }
}

const controller = new AbortController();
const g = agen(controller.signal);

for await (const n of g) {
  console.log(n);
  if (n === 3) controller.abort();
}
```

---

## 11. Infinite generators need explicit termination

Spreading or `Array.from` an infinite generator hangs.

```ts
function* naturals() {
  let n = 0;
  while (true) yield n++;
}

// BAD: [...naturals()] // never finishes

// OK: manual limit
function take<T>(it: Iterable<T>, n: number): T[] {
  const out: T[] = [];
  for (const x of it) {
    if (out.length >= n) break;
    out.push(x);
  }
  return out;
}

console.log(take(naturals(), 5)); // [0,1,2,3,4]
```

---

## 12. `yield*` on strings yields code points, not UTF-16 units

```ts
function* chars(s: string) {
  yield* s;
}

console.log([...chars("a😀b")]); // ['a', '😀', 'b']
```

If you need UTF-16 code units, iterate by index instead.

---

## 13. `yield` inside `finally` can keep a generator alive unexpectedly

A `finally` block that yields suspends the generator again, delaying completion.

```ts
function* gen() {
  try {
    yield 1;
  } finally {
    yield 2; // generator is not done until resumed again
  }
}

const g = gen();
console.log(g.next()); // { value: 1, done: false }
console.log(g.return("x")); // runs finally, yields 2 -> { value: 2, done: false }
console.log(g.next()); // { value: undefined, done: true }
```

Avoid yielding in `finally` unless you truly want lazy cleanup.

---

## 14. Sync generators are async-iterable, but values are awaited

`for await...of` accepts sync iterables, awaiting each value. This can mask timing or type issues.

```ts
function* sync() {
  yield 1;
  yield 2;
}

(async () => {
  for await (const x of sync()) {
    console.log(x); // works, but x is number, not Promise<number>
  }
})();
```

If you intended an async generator, annotate with `async function*`.

---

## 15. Generator classes and `Symbol.iterator`

When implementing `Iterable`, generator methods are the cleanest approach, but keep types explicit.

```ts
class Range implements Iterable<number> {
  constructor(private start: number, private end: number) {}

  *[Symbol.iterator](): Generator<number, void, unknown> {
    for (let i = this.start; i <= this.end; i++) {
      yield i;
    }
  }
}
```

---

## 16. `next()` after `.throw()` that is caught can continue; otherwise it closes

```ts
function* gen() {
  try {
    yield 1;
  } catch {
    yield 2;
  }
}

const g = gen();
g.next();
g.throw(new Error("x")); // caught, yields 2
console.log(g.next());   // { value: undefined, done: true }
```

If the catch block itself throws or the generator has no catch, the generator becomes closed.

---

## 17. Don’t share one generator across concurrent async consumers

Async generators serialize `.next()` calls internally, but interleaving multiple consumers makes ordering and cleanup hard to reason about.

```ts
async function* agen() {
  yield 1;
  await new Promise(r => setTimeout(r, 10));
  yield 2;
}

const g = agen();
const a = g.next();
const b = g.next(); // queued internally; avoid this pattern
await Promise.all([a, b]);
```

Prefer one consumer per generator, or create a fresh generator per consumer.

---

## 18. Type defaults can make `yield` expressions `unknown`

If you omit `TNext`, many lib definitions default it to `unknown`, so `const x = yield 1` may be `unknown`.

```ts
function* gen() {
  const x = yield 1; // x: unknown in many setups
  // x.toFixed(); // error
}
```

**Handle it:** annotate fully:

```ts
function* gen(): Generator<number, void, number> {
  const x = yield 1; // number
  console.log(x.toFixed());
}
```

---

## Practical checklist

- Annotate `Generator<Yield, Return, Next>` explicitly.
- Treat `TNext` as possibly `undefined` unless you control every caller.
- Narrow with `if (!result.done)` before using `result.value`.
- Put cleanup in `finally`.
- Await `.return()` / `.throw()` on async generators.
- Add cancellation checks in long-running async generators.
- Avoid yielding in `finally`.
- Don’t spread infinite generators.
- Bind generator methods when passing them around.
- Remember `for...of` discards the final return value.

These cover the majority of generator-related runtime and type surprises in TypeScript.

# Generics in TypeScript — complete runnable example

Generics let you write **reusable, type-safe code** that works with many types while preserving precise type information at compile time.  
Below is one self-contained file (`generics-demo.ts`) that demonstrates:

- generic functions  
- constraints (`extends`)  
- multiple type parameters and defaults  
- generic classes and interfaces  
- `keyof`, indexed access, mapped types  
- conditional types with `infer`  
- a small real-world repository + box example  
- runtime assertions so you can run it and see everything work  

## `generics-demo.ts`

```ts
import * as assert from 'assert';

/* ------------------------------------------------------------------ */
/* 1. Basic generic function                                           */
/* ------------------------------------------------------------------ */

function identity<T>(value: T): T {
  return value;
}

function first<T>(items: readonly T[]): T | undefined {
  return items[0];
}

/* ------------------------------------------------------------------ */
/* 2. Constraints: T must have an id                                   */
/* ------------------------------------------------------------------ */

interface HasId {
  id: string;
}

function getId<T extends HasId>(entity: T): T['id'] {
  return entity.id;
}

/* ------------------------------------------------------------------ */
/* 3. Multiple type parameters + default type parameter                */
/* ------------------------------------------------------------------ */

function mapPair<A, B = string>(a: A, b: B): [A, B] {
  return [a, b];
}

function createArray<T = string>(length: number, value: T): T[] {
  return Array.from({ length }, () => value);
}

/* ------------------------------------------------------------------ */
/* 4. Generic class: Stack<T>                                          */
/* ------------------------------------------------------------------ */

class Stack<T> {
  private items: T[] = [];

  push(item: T): void {
    this.items.push(item);
  }

  pop(): T | undefined {
    return this.items.pop();
  }

  peek(): T | undefined {
    return this.items[this.items.length - 1];
  }

  get size(): number {
    return this.items.length;
  }

  [Symbol.iterator](): Iterator<T> {
    return this.items[Symbol.iterator]();
  }
}

/* ------------------------------------------------------------------ */
/* 5. Generic class + interface: Box<T> with a map method             */
/* ------------------------------------------------------------------ */

class Box<T> {
  constructor(public value: T) {}

  map<U>(fn: (value: T) => U): Box<U> {
    return new Box(fn(this.value));
  }

  static of<T>(value: T): Box<T> {
    return new Box(value);
  }
}

/* ------------------------------------------------------------------ */
/* 6. keyof, Pick, and a generic "pluck" helper                        */
/* ------------------------------------------------------------------ */

function pluck<T, K extends keyof T>(
  obj: T,
  keys: readonly K[],
): Pick<T, K> {
  const result = {} as Pick<T, K>;
  for (const key of keys) {
    result[key] = obj[key];
  }
  return result;
}

/* ------------------------------------------------------------------ */
/* 7. Merge with intersection type                                     */
/* ------------------------------------------------------------------ */

function merge<T extends object, U extends object>(a: T, b: U): T & U {
  return { ...a, ...b };
}

/* ------------------------------------------------------------------ */
/* 8. Generic type guard                                               */
/* ------------------------------------------------------------------ */

function isDefined<T>(value: T | null | undefined): value is T {
  return value != null;
}

/* ------------------------------------------------------------------ */
/* 9. Conditional type with infer                                      */
/* ------------------------------------------------------------------ */

type UnwrapPromise<T> = T extends PromiseLike<infer U> ? U : T;

/* ------------------------------------------------------------------ */
/* 10. Mapped type + template literal type                             */
/* ------------------------------------------------------------------ */

type Getters<T> = {
  [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K];
};

/* ------------------------------------------------------------------ */
/* 11. Recursive mapped type                                           */
/* ------------------------------------------------------------------ */

type DeepReadonly<T> =
  T extends (infer U)[]
    ? ReadonlyArray<DeepReadonly<U>>
    : T extends object
      ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
      : T;

/* ------------------------------------------------------------------ */
/* 12. Small real-world generic repository                             */
/* ------------------------------------------------------------------ */

interface Entity {
  id: string;
}

class InMemoryRepository<T extends Entity> {
  private store = new Map<string, T>();

  save(entity: T): T {
    this.store.set(entity.id, entity);
    return entity;
  }

  findById(id: string): T | undefined {
    return this.store.get(id);
  }

  findAll(): T[] {
    return [...this.store.values()];
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

/* ------------------------------------------------------------------ */
/* 13. A tiny generic "fetch JSON" wrapper (no network in tests)       */
/* ------------------------------------------------------------------ */

interface HttpLike {
  get<T>(url: string): Promise<T>;
}

class FakeHttp implements HttpLike {
  async get<T>(url: string): Promise<T> {
    // Pretend we fetched and parsed JSON.
    return { url, ok: true } as T;
  }
}

async function loadJson<T>(http: HttpLike, url: string): Promise<T> {
  return http.get<T>(url);
}

/* ------------------------------------------------------------------ */
/* 14. Compile-time type checks (must compile, no runtime effect)      */
/* ------------------------------------------------------------------ */

type Equals<A, B> =
  [A] extends [B] ? ([B] extends [A] ? true : false) : false;

// These lines only compile if the generic machinery works as expected.
const _typeCheck1: Equals<UnwrapPromise<Promise<number>>, number> = true;
const _typeCheck2: Equals<
  Getters<{ name: string; age: number }>,
  { getName: () => string; getAge: () => number }
> = true;

/* ------------------------------------------------------------------ */
/* 15. Runtime tests                                                   */
/* ------------------------------------------------------------------ */

interface User extends Entity {
  name: string;
}

function main(): void {
  // identity / first
  assert.strictEqual(identity(42), 42);
  assert.strictEqual(identity('hello'), 'hello');
  assert.strictEqual(first([10, 20, 30]), 10);
  assert.strictEqual(first([]), undefined);

  // constraints
  const user: User = { id: 'u1', name: 'Ada' };
  assert.strictEqual(getId(user), 'u1');

  // multiple params + defaults
  assert.deepStrictEqual(mapPair(7, true), [7, true]);
  assert.deepStrictEqual(mapPair(7), [7, '']);
  assert.deepStrictEqual(createArray(3, 0), [0, 0, 0]);
  assert.deepStrictEqual(createArray(2, 'x'), ['x', 'x']);

  // Stack
  const stack = new Stack<number>();
  stack.push(1);
  stack.push(2);
  assert.strictEqual(stack.peek(), 2);
  assert.strictEqual(stack.pop(), 2);
  assert.strictEqual(stack.size, 1);
  assert.deepStrictEqual([...stack], [1]);

  // Box
  const box = Box.of(5);
  const text = box.map((n) => n.toString());
  assert.strictEqual(text.value, '5');
  assert.ok(text instanceof Box);

  // pluck
  const obj = { a: 1, b: 'x', c: true };
  const picked = pluck(obj, ['a', 'b'] as const);
  assert.deepStrictEqual(picked, { a: 1, b: 'x' });

  // merge
  const merged = merge({ a: 1 }, { b: 'two' });
  assert.deepStrictEqual(merged, { a: 1, b: 'two' });

  // type guard
  const maybe: string | null = 'hi';
  if (isDefined(maybe)) {
    // `maybe` is `string` here
    assert.strictEqual(maybe.toUpperCase(), 'HI');
  }

  // repository
  const repo = new InMemoryRepository<User>();
  repo.save({ id: '1', name: 'Ada' });
  repo.save({ id: '2', name: 'Bob' });
  assert.deepStrictEqual(repo.findById('1'), { id: '1', name: 'Ada' });
  assert.strictEqual(repo.findAll().length, 2);
  assert.strictEqual(repo.delete('2'), true);
  assert.strictEqual(repo.findById('2'), undefined);

  // DeepReadonly (runtime shape check only; immutability is compile-time)
  const readonlyValue: DeepReadonly<{ nested: { n: number } }> = {
    nested: { n: 7 },
  };
  assert.strictEqual(readonlyValue.nested.n, 7);

  // fake http
  const http = new FakeHttp();
  loadJson<{ url: string; ok: boolean }>(http, '/api/data').then((data) => {
    assert.deepStrictEqual(data, { url: '/api/data', ok: true });
    console.log('All tests passed ✅');
  });
}

main();
```

