  ["A", ["B", "C"]],
  ["B", ["D"]],
  ["C", ["D", "E"]],
  ["D", ["F"]],
  ["E", ["F"]],
  ["F", []],
]);

console.log(shortestPath(graph, "A", "F"));
// Possible output: ["A", "B", "D", "F"] or ["A", "C", "D", "F"]

console.log(shortestPath(graph, "A", "A")); // ["A"]
console.log(shortestPath(graph, "A", "Z")); // null
console.log(shortestPath(graph, "Z", "A")); // null
