## Complexity

- **Time:** `O(V + E)` where `V` is the number of cities and `E` is the number of connections.
- **Space:** `O(V)` for the queue, visited set, and parent map.

---

## Optional DFS variant: reachability

If you only need to know whether a destination is reachable, not the shortest route, DFS is simpler:

```ts
function isReachable(graph: CityGraph, start: string, destination: string): boolean {
  if (start === destination) return graph.has(start);

  const visited = new Set<string>();
  const stack: string[] = [start];

  while (stack.length > 0) {
    const current = stack.pop()!;

    if (current === destination) return true;
    if (visited.has(current)) continue;
    visited.add(current);

    for (const neighbor of graph.get(current) ?? []) {
      if (!visited.has(neighbor)) stack.push(neighbor);
    }
  }

  return false;
}
```

This is still `O(V + E)`, but it does not preserve shortest-path information.

## Graphs and Traversals in TypeScript

### 1. Core concepts

A **graph** is a collection of **vertices** (nodes) connected by **edges**.

- **Directed vs undirected**: edges have direction or not.
- **Weighted vs unweighted**: edges may carry costs.
- **Representation**:
  - **Adjacency list**: `Map<Vertex, Edge[]>` — best for sparse graphs, O(V+E) space.
  - **Adjacency matrix**: `number[][]` — O(V²) space, O(1) edge lookup; better for dense graphs.

For most interview problems, **adjacency list** is the default.

### 2. Traversals

| Traversal | Data structure | Order | Typical use |
|---|---|---|---|
| **BFS** | Queue (FIFO) | Level by level | Shortest path in unweighted graph, nearest neighbors |
| **DFS** | Stack (LIFO) or recursion | Deep first | Cycle detection, topological sort, connected components, backtracking |

Both are **O(V + E)** time and **O(V)** extra space (visited + frontier).

**Key details interviewers like:**
- Always guard against revisiting nodes with a `visited` set.
- For disconnected graphs, loop over all vertices and start a traversal from each unvisited one.
- Recursive DFS can stack-overflow on large graphs; iterative DFS avoids that.
- BFS gives shortest path **only when all edges have equal weight**.

### 3. Clean TypeScript implementation

```ts
/**
 * A generic, adjacency-list based graph.
 * Vertices are strings for readability; swap to number if preferred.
 */
type Vertex = string;

interface Edge {
  to: Vertex;
  weight?: number;
}

export class Graph {
  private readonly adj = new Map<Vertex, Edge[]>();
  private readonly directed: boolean;

  constructor(directed = false) {
    this.directed = directed;
  }

  // ---------- mutation ----------

  addVertex(v: Vertex): this {
    if (!this.adj.has(v)) this.adj.set(v, []);
    return this; // fluent API
  }

  addEdge(u: Vertex, v: Vertex, weight?: number): this {
    this.addVertex(u);
    this.addVertex(v);
    this.adj.get(u)!.push({ to: v, weight });

    if (!this.directed) {
      this.adj.get(v)!.push({ to: u, weight });
    }
    return this;
  }

  // ---------- read ----------

  vertices(): Vertex[] {
    return [...this.adj.keys()];
  }

  neighbors(v: Vertex): Edge[] {
    return this.adj.get(v) ?? [];
  }

  hasVertex(v: Vertex): boolean {
    return this.adj.has(v);
  }

  // ---------- traversals ----------

  /**
   * Breadth-First Search.
   * Returns vertices in visitation order.
   * Works for disconnected graphs (starts from every unvisited vertex).
   */
  bfs(start: Vertex, visit?: (v: Vertex) => void): Vertex[] {
    if (!this.hasVertex(start)) return [];

    const visited = new Set<Vertex>();
    const queue: Vertex[] = [start];
    visited.add(start);
    const order: Vertex[] = [];

    while (queue.length > 0) {
      const curr = queue.shift()!; // FIFO
      order.push(curr);
      visit?.(curr);

      for (const { to } of this.neighbors(curr)) {
        if (!visited.has(to)) {
          visited.add(to);
          queue.push(to);
        }
      }
    }

    // Handle disconnected components
    for (const v of this.vertices()) {
      if (!visited.has(v)) {
        // restart BFS from this component
        const compOrder = this.bfsFrom(v, visited, visit);
        order.push(...compOrder);
      }
    }

    return order;
  }

  private bfsFrom(
    start: Vertex,
    visited: Set<Vertex>,
    visit?: (v: Vertex) => void,
  ): Vertex[] {
    const queue: Vertex[] = [start];
    visited.add(start);
    const order: Vertex[] = [];

    while (queue.length > 0) {
      const curr = queue.shift()!;
      order.push(curr);
      visit?.(curr);

      for (const { to } of this.neighbors(curr)) {
        if (!visited.has(to)) {
          visited.add(to);
          queue.push(to);
        }
      }
    }
    return order;
  }

  /**
   * Iterative Depth-First Search (avoids recursion stack overflow).
   */
  dfsIterative(start: Vertex, visit?: (v: Vertex) => void): Vertex[] {
    if (!this.hasVertex(start)) return [];

    const visited = new Set<Vertex>();
    const stack: Vertex[] = [start];
    const order: Vertex[] = [];

    while (stack.length > 0) {
      const curr = stack.pop()!; // LIFO

      if (visited.has(curr)) continue;
      visited.add(curr);
      order.push(curr);
      visit?.(curr);

      // Push neighbors in reverse so left-to-right order is preserved
      const nbrs = this.neighbors(curr).map((e) => e.to).reverse();
      for (const n of nbrs) {
        if (!visited.has(n)) stack.push(n);
      }
    }

    // Disconnected components
    for (const v of this.vertices()) {
      if (!visited.has(v)) {
        const comp = this.dfsIterativeFrom(v, visited, visit);
        order.push(...comp);
      }
    }

    return order;
  }

  private dfsIterativeFrom(
    start: Vertex,
    visited: Set<Vertex>,
    visit?: (v: Vertex) => void,
  ): Vertex[] {
    const stack: Vertex[] = [start];
    const order: Vertex[] = [];

    while (stack.length > 0) {
      const curr = stack.pop()!;
      if (visited.has(curr)) continue;
      visited.add(curr);
      order.push(curr);
      visit?.(curr);

      for (const n of this.neighbors(curr).map((e) => e.to).reverse()) {
        if (!visited.has(n)) stack.push(n);
      }
    }
    return order;
  }

  /**
   * Recursive DFS — elegant but risky on deep graphs.
   */
  dfsRecursive(start: Vertex, visit?: (v: Vertex) => void): Vertex[] {
    if (!this.hasVertex(start)) return [];

    const visited = new Set<Vertex>();
    const order: Vertex[] = [];

    const dfs = (v: Vertex) => {
      if (visited.has(v)) return;
      visited.add(v);
      order.push(v);
      visit?.(v);
      for (const { to } of this.neighbors(v)) {
        dfs(to);
      }
    };

    dfs(start);

    // Disconnected components
    for (const v of this.vertices()) {
      if (!visited.has(v)) dfs(v);
    }

    return order;
  }

  // ---------- classic derived algorithms ----------

  /** Shortest path (by hop count) in an unweighted graph. */
  shortestPath(start: Vertex, target: Vertex): Vertex[] | null {
    if (!this.hasVertex(start) || !this.hasVertex(target)) return null;
    if (start === target) return [start];

    const parent = new Map<Vertex, Vertex | null>();
    const visited = new Set<Vertex>([start]);
    const queue: Vertex[] = [start];
    parent.set(start, null);

    while (queue.length > 0) {
      const curr = queue.shift()!;
      if (curr === target) break;

      for (const { to } of this.neighbors(curr)) {
        if (!visited.has(to)) {
          visited.add(to);
          parent.set(to, curr);
          queue.push(to);
        }
      }
    }

    if (!parent.has(target)) return null;

    // Reconstruct path
    const path: Vertex[] = [];
    let node: Vertex | null = target;
    while (node !== null) {
      path.unshift(node);
      node = parent.get(node)!;
    }
    return path;
  }

  /** Detect cycle in directed graph (DFS coloring). */
  hasCycleDirected(): boolean {
    const WHITE = 0, GRAY = 1, BLACK = 2;
    const color = new Map<Vertex, number>();

    for (const v of this.vertices()) color.set(v, WHITE);

    const dfs = (v: Vertex): boolean => {
      color.set(v, GRAY);
      for (const { to } of this.neighbors(v)) {
        const c = color.get(to)!;
        if (c === GRAY) return true; // back edge -> cycle
        if (c === WHITE && dfs(to)) return true;
      }
      color.set(v, BLACK);
      return false;
    };

    for (const v of this.vertices()) {
      if (color.get(v) === WHITE && dfs(v)) return true;
    }
    return false;
  }
}

/* ---------------- Example usage ---------------- */

const g = new Graph(); // undirected by default
g.addEdge("A", "B")
  .addEdge("A", "C")
  .addEdge("B", "D")
  .addEdge("C", "D")
  .addEdge("D", "E");

console.log("BFS:", g.bfs("A"));          // A B C D E
console.log("DFS iter:", g.dfsIterative("A")); // A C D E B (or similar)
console.log("Shortest A->E:", g.shortestPath("A", "E")); // [A, B/D, E] (2 hops)

const dg = new Graph(true);
dg.addEdge("A", "B").addEdge("B", "C").addEdge("C", "A");
console.log("Has cycle (directed):", dg.hasCycleDirected()); // true
```

### 4. Interview tips

- **Always ask**: directed or undirected? weighted? can revisit? self-loops?
- **Prefer iterative DFS** for production; recursive is fine for small inputs.
- **BFS shortest path** only valid for unit weights; otherwise use Dijkstra.
- **Disconnected graphs**: don’t forget the outer loop over all vertices.
- **Complexity**: state time/space as O(V+E), not O(V²), unless using matrix.

This gives you a solid, reusable core you can extend with Dijkstra, topological sort, or union-find as needed.

# Edge Cases in Graphs & Traversals (TypeScript)

Below are the most common (and dangerous) edge cases, each with a small runnable TypeScript example and a note on how to handle it.

---

## 1. Empty graph

```ts
type Graph<T> = Map<T, T[]>;

function bfs<T>(g: Graph<T>, start: T): T[] {
  if (!g.has(start)) return [];          // empty / missing start
  const seen = new Set<T>([start]);
  const q: T[] = [start];
  const out: T[] = [];
  while (q.length) {
    const u = q.shift()!;
    out.push(u);
    for (const v of g.get(u) ?? []) {
      if (!seen.has(v)) { seen.add(v); q.push(v); }
    }
  }
  return out;
}

const empty: Graph<number> = new Map();
console.log(bfs(empty, 1)); // []
```

**Handle:** check `g.has(start)` before seeding; treat missing node as empty result, not an error, unless your API contract says otherwise.

---

## 2. Single node with no edges

```ts
const g: Graph<number> = new Map([[1, []]]);
console.log(bfs(g, 1)); // [1]
```

**Handle:** adjacency list must allow `[]`; don't assume every node has neighbors.

---

## 3. Disconnected components

A traversal starting at one component never reaches the others.

```ts
function allComponents<T>(g: Graph<T>): T[][] {
  const seen = new Set<T>();
  const comps: T[][] = [];
  for (const node of g.keys()) {
    if (seen.has(node)) continue;
    // BFS one component
    const comp: T[] = [];
    const q: T[] = [node];
    seen.add(node);
    while (q.length) {
      const u = q.shift()!;
      comp.push(u);
      for (const v of g.get(u) ?? []) {
        if (!seen.has(v)) { seen.add(v); q.push(v); }
      }
    }
    comps.push(comp);
  }
  return comps;
}

const g: Graph<number> = new Map([
  [1, [2]], [2, [1]],
  [3, [4]], [4, [3]],   // disconnected
]);
console.log(allComponents(g)); // [[1,2],[3,4]]
```

**Handle:** iterate over *all* keys, not just the start node.

---

## 4. Self-loops

```ts
function hasCycleDFS<T>(g: Graph<T>): boolean {
  const color = new Map<T, 0 | 1 | 2>(); // 0=unvisited 1=in-stack 2=done
  const dfs = (u: T): boolean => {
    color.set(u, 1);
    for (const v of g.get(u) ?? []) {
      if (v === u) return true;            // self-loop
      const c = color.get(v) ?? 0;
      if (c === 1) return true;            // back edge
      if (c === 0 && dfs(v)) return true;
    }
    color.set(u, 2);
    return false;
  };
  for (const n of g.keys()) if ((color.get(n) ?? 0) === 0 && dfs(n)) return true;
  return false;
}

const g: Graph<number> = new Map([[1, [1]]]);
console.log(hasCycleDFS(g)); // true
```

**Handle:** explicitly treat `v === u` as a cycle; don't rely on "visited" alone.

---

## 5. Parallel / duplicate edges

```ts
function dedupeNeighbors<T>(g: Graph<T>): Graph<T> {
  const out: Graph<T> = new Map();
  for (const [u, ns] of g) out.set(u, [...new Set(ns)]);
  return out;
}

// Or during traversal:
function bfsDedupe<T>(g: Graph<T>, start: T): T[] {
  const seen = new Set<T>([start]);
  const q: T[] = [start];
  const out: T[] = [];
  while (q.length) {
    const u = q.shift()!;
    out.push(u);
    for (const v of new Set(g.get(u) ?? [])) { // dedupe on the fly
      if (!seen.has(v)) { seen.add(v); q.push(v); }
    }
  }
  return out;
}
```

**Handle:** dedupe adjacency lists, or use a `Set` when iterating. Otherwise you waste work and may enqueue the same node many times.

---

## 6. Cycles causing infinite loops

```ts
// WRONG: no visited set
function dfsBad<T>(g: Graph<T>, u: T, out: T[] = []): T[] {
  out.push(u);
  for (const v of g.get(u) ?? []) dfsBad(g, v, out); // infinite on cycle
  return out;
}

// RIGHT
function dfsGood<T>(g: Graph<T>, start: T): T[] {
  const seen = new Set<T>();
  const out: T[] = [];
  const rec = (u: T) => {
    if (seen.has(u)) return;
    seen.add(u);
    out.push(u);
    for (const v of g.get(u) ?? []) rec(v);
  };
  rec(start);
  return out;
}
```

**Handle:** always maintain a visited set; for *directed* cycle detection you need 3-coloring, not just a boolean.

---

## 7. Recursion depth / stack overflow on large graphs

```ts
// Iterative DFS avoids call-stack limits
function dfsIterative<T>(g: Graph<T>, start: T): T[] {
  if (!g.has(start)) return [];
  const seen = new Set<T>([start]);
  const stack: T[] = [start];
  const out: T[] = [];
  while (stack.length) {
    const u = stack.pop()!;
    out.push(u);
    for (const v of g.get(u) ?? []) {
      if (!seen.has(v)) { seen.add(v); stack.push(v); }
    }
  }
  return out;
}
```

**Handle:** use iterative traversal for graphs with > ~10⁴ nodes; Node default stack is small.

---

## 8. Mutating the graph during traversal

```ts
// DANGEROUS: deleting while iterating Map keys
function badRemove<T>(g: Graph<T>) {
  for (const [u] of g) {
    if ((g.get(u)?.length ?? 0) === 0) g.delete(u); // ConcurrentModification
  }
}

// SAFE: snapshot keys first
function safeRemove<T>(g: Graph<T>) {
  for (const u of [...g.keys()]) {
    if ((g.get(u)?.length ?? 0) === 0) g.delete(u);
  }
}
```

**Handle:** snapshot ` [...g.keys()]` or collect deletions, then apply.

---

## 9. Missing / dangling neighbors

```ts
const g: Graph<number> = new Map([[1, [2, 99]]]); // 99 doesn't exist
function safeNeighbors<T>(g: Graph<T>, u: T): T[] {
  return (g.get(u) ?? []).filter(v => g.has(v));
}
// or, if missing nodes are allowed as "lazy" nodes:
function neighborsOrEmpty<T>(g: Graph<T>, u: T): T[] {
  return g.get(u) ?? [];
}
```

**Handle:** decide policy — strict (filter) vs permissive (treat missing as leaf). Document it.

---

## 10. Negative edge weights with Dijkstra

```ts
// Dijkstra assumes non-negative weights
function dijkstra<V>(
  adj: Map<V, [V, number][]>,
  src: V
): Map<V, number> {
  const dist = new Map<V, number>([[src, 0]]);
  const pq: [number, V][] = [[0, src]];
  // ... standard impl; WRONG if any weight < 0
  return dist;
}

// Use Bellman-Ford when negative weights possible:
function bellmanFord<V>(
  nodes: V[],
  edges: [V, V, number][],
  src: V
): Map<V, number> | null {   // null => negative cycle
  const dist = new Map<V, number>(nodes.map(n => [n, Infinity]));
  dist.set(src, 0);
  for (let i = 0; i < nodes.length - 1; i++) {
    for (const [u, v, w] of edges) {
      const du = dist.get(u)!;
      if (du + w < (dist.get(v) ?? Infinity)) dist.set(v, du + w);
    }
  }
  // negative cycle check
  for (const [u, v, w] of edges) {
    if (dist.get(u)! + w < (dist.get(v) ?? Infinity)) return null;
  }
  return dist;
}
```

**Handle:** validate weights (`w >= 0`) before Dijkstra, or switch algorithms.

---

## 11. Topological sort on a cyclic DAG assumption

```ts
function topoSort<T>(g: Graph<T>): T[] | null {
  const indeg = new Map<T, number>();
  for (const u of g.keys()) indeg.set(u, 0);
  for (const [, ns] of g) for (const v of ns) indeg.set(v, (indeg.get(v) ?? 0) + 1);
  const q: T[] = [...indeg.entries()].filter(([, d]) => d === 0).map(([u]) => u);
  const out: T[] = [];
  while (q.length) {
    const u = q.shift()!;
    out.push(u);
    for (const v of g.get(u) ?? []) {
      const d = indeg.get(v)! - 1;
      indeg.set(v, d);
      if (d === 0) q.push(v);
    }
  }
  return out.length === g.size ? out : null; // null => cycle
}
```

**Handle:** compare output length to node count; `null` means cycle exists.

---

## 12. Type-safety: string vs number keys & `Map`

```ts
// Map<number,...> coerces? No — Map uses SameValueZero, so 1 !== "1".
const g = new Map<number, number[]>();
g.set(1, [2]);
console.log(g.has("1" as any)); // false

// If you need string keys, normalize:
type NodeId = string;
function normalize(id: unknown): NodeId { return String(id); }
```

**Handle:** pick one key type and normalize at boundaries; avoid `any`.

---

## 13. Undirected graph: add both directions

```ts
function addUndirected<T>(g: Map<T, Set<T>>, u: T, v: T) {
  if (!g.has(u)) g.set(u, new Set());
  if (!g.has(v)) g.set(v, new Set());
  g.get(u)!.add(v);
  g.get(v)!.add(u);
  if (u === v) { /* self-loop: added once, not twice */ }
}
```

**Handle:** self-loop should add once; otherwise you double-count in degree calculations.

---

## 14. Visited semantics in undirected graphs (parent tracking)

```ts
function isTree<T>(g: Graph<T>): boolean {
  // undirected, connected, acyclic
  if (g.size === 0) return true;
  const seen = new Set<T>();
  let edges = 0;
  const dfs = (u: T, parent: T | null): boolean => {
    seen.add(u);
    for (const v of g.get(u) ?? []) {
      edges++;
      if (v === parent) continue; // skip the edge we came from
      if (seen.has(v)) return false; // cross/back edge => cycle
      if (!dfs(v, u)) return false;
    }
    return true;
  };
  const start = g.keys().next().value!;
  if (!dfs(start, null)) return false;
  return seen.size === g.size && edges / 2 === g.size - 1;
}
```

**Handle:** in undirected traversal, skip the *parent edge*, not just the parent node (parallel edges matter).

---

## 15. `for...of` over Map while mutating

Already covered (#8). Also: never `g.delete` inside `for (const [u, ns] of g)`.

---

## 16. Large graph memory / adjacency representation

```ts
// Object map is slower & has prototype pitfalls
const bad: any = {};
bad["toString"] = [1]; // collision with Object.prototype

// Use Map + Set for sparse, array-of-arrays for dense
const good = new Map<number, Set<number>>();
```

**Handle:** prefer `Map`/`Set`; avoid plain objects as dictionaries for arbitrary keys.

---

## 17. Async traversal (I/O-bound expansion)

```ts
async function bfsAsync<T>(
  start: T,
  expand: (u: T) => Promise<T[]>
): Promise<T[]> {
  const seen = new Set<T>([start]);
  const q: T[] = [start];
  const out: T[] = [];
  while (q.length) {
    const u = q.shift()!;
    out.push(u);
    for (const v of await expand(u)) {
      if (!seen.has(v)) { seen.add(v); q.push(v); }
    }
  }
  return out;
}
```

**Handle:** don't fire all expansions concurrently without a concurrency limit; can OOM.

---

## 18. Node equality / custom objects

```ts
class Node { constructor(public id: number) {} }
// Map uses reference equality by default
const a = new Node(1), b = new Node(1);
const g = new Map<Node, Node[]>();
g.set(a, [b]);
console.log(g.has(b)); // false (different ref), and b isn't even a key

// Fix: key by primitive id
type G = Map<number, number[]>;
```

**Handle:** key graphs by primitive IDs, not object references, unless you control identity.

---

## 19. Snapshotting for repeated traversals

```ts
function cachedBFS<T>(g: Graph<T>) {
  const cache = new Map<T, T[]>();
  return (start: T) => {
    if (cache.has(start)) return cache.get(start)!;
    const r = bfs(g, start);
    cache.set(start, r);
    return r;
  };
}
```

**Handle:** invalidate cache on mutation; otherwise stale traversals.

---

## 20. Off-by-one in "levels" / shortest path (unweighted)

```ts
function bfsLevels<T>(g: Graph<T>, start: T): Map<T, number> {
  const dist = new Map<T, number>([[start, 0]]);
  const q: T[] = [start];
  while (q.length) {
    const u = q.shift()!;
    for (const v of g.get(u) ?? []) {
      if (!dist.has(v)) {
        dist.set(v, dist.get(u)! + 1);
        q.push(v);
      }
    }
  }
  return dist;
}
```

**Handle:** set distance when *enqueuing*, not when dequeuing, to avoid duplicate level assignments.

---

## Quick checklist

| Edge case | Guard |
|---|---|
| Empty / missing start | `if (!g.has(start)) return []` |
| Disconnected | iterate all keys |
| Cycle | visited set (DFS: 3-color) |
| Self-loop | `v === u` check |
| Parallel edges | dedupe with `Set` |
| Deep graph | iterative DFS |
| Negative weights | Bellman-Ford / validate |
| DAG assumption | topo-sort length check |
| Mutation during traversal | snapshot keys |
| Object keys | use primitive IDs + `Map` |
| Undirected parent | skip parent edge, not node |
| Async expansion | bounded concurrency |

If you want, I can wrap these into a single reusable `Graph<T>` class with safe traversal methods.

Here is a complete, runnable TypeScript example implementing several classic greedy algorithms: fractional knapsack, activity selection, Huffman coding, job sequencing, coin change, and Kruskal’s MST.

Save it as `greedy.ts`, then run with:

```bash
npx ts-node greedy.ts
# or
tsc greedy.ts && node greedy.js
```

```ts
// greedy.ts
// Complete runnable examples of common greedy algorithms in TypeScript.

/* -------------------------------------------------------------------------- */
/* 1. Fractional Knapsack                                                     */
/* -------------------------------------------------------------------------- */

interface KnapsackItem {
  name: string;
  weight: number;
  value: number;
}

interface KnapsackChoice {
  name: string;
  takenWeight: number;
  fraction: number;
  value: number;
}

function fractionalKnapsack(
  capacity: number,
  items: KnapsackItem[]
): { totalValue: number; choices: KnapsackChoice[] } {
  const sorted = [...items].sort(
    (a, b) => b.value / b.weight - a.value / a.weight
  );

  let remaining = capacity;
  let totalValue = 0;
  const choices: KnapsackChoice[] = [];

  for (const item of sorted) {
    if (remaining <= 0) break;

    const take = Math.min(item.weight, remaining);
    const fraction = take / item.weight;

    choices.push({
      name: item.name,
      takenWeight: take,
      fraction,
      value: item.value * fraction,
    });

    totalValue += item.value * fraction;
    remaining -= take;
  }

  return { totalValue, choices };
}

/* -------------------------------------------------------------------------- */
/* 2. Activity Selection / Interval Scheduling                                */
/* -------------------------------------------------------------------------- */

interface Activity {
  id: string;
  start: number;
  end: number;
}

function activitySelection(activities: Activity[]): Activity[] {
  if (activities.length === 0) return [];

  const sorted = [...activities].sort((a, b) => a.end - b.end);
  const selected: Activity[] = [sorted[0]];
  let lastEnd = sorted[0].end;

  for (let i = 1; i < sorted.length; i++) {
    const activity = sorted[i];
    if (activity.start >= lastEnd) {
      selected.push(activity);
      lastEnd = activity.end;
    }
  }

  return selected;
}

/* -------------------------------------------------------------------------- */
/* 3. Huffman Coding                                                          */
/* -------------------------------------------------------------------------- */

interface HuffmanNode {
  symbol?: string;
  freq: number;
  left?: HuffmanNode;
  right?: HuffmanNode;
}

function buildHuffmanCodes(
  frequencies: Record<string, number>
): { codes: Record<string, string>; root: HuffmanNode | undefined } {
  const forest: HuffmanNode[] = Object.entries(frequencies).map(
    ([symbol, freq]) => ({ symbol, freq })
  );

  if (forest.length === 0) return { codes: {}, root: undefined };

  // Combine two smallest trees until one tree remains.
  while (forest.length > 1) {
    forest.sort((a, b) => a.freq - b.freq);
    const left = forest.shift()!;
    const right = forest.shift()!;
    forest.push({ freq: left.freq + right.freq, left, right });
  }

  const root = forest[0];
  const codes: Record<string, string> = {};

  function dfs(node: HuffmanNode, prefix: string): void {
    if (node.symbol !== undefined) {
      codes[node.symbol] = prefix || "0";
      return;
    }
    if (node.left) dfs(node.left, prefix + "0");
    if (node.right) dfs(node.right, prefix + "1");
  }

  dfs(root, "");
  return { codes, root };
}

/* -------------------------------------------------------------------------- */
/* 4. Job Sequencing with Deadlines                                           */
/* -------------------------------------------------------------------------- */

interface Job {
  id: string;
  deadline: number;
  profit: number;
}

function jobSequencing(
  jobs: Job[],
  maxDeadline?: number
): { totalProfit: number; schedule: (Job | null)[] } {
  const deadlineLimit =
    maxDeadline ?? Math.max(0, ...jobs.map((j) => j.deadline));

  const sorted = [...jobs].sort((a, b) => b.profit - a.profit);
  const slots: (Job | null)[] = Array.from(
    { length: deadlineLimit + 1 },
    () => null
  );

  let totalProfit = 0;

  for (const job of sorted) {
    const latest = Math.min(job.deadline, deadlineLimit);
    for (let t = latest; t > 0; t--) {
      if (slots[t] === null) {
        slots[t] = job;
        totalProfit += job.profit;
        break;
      }
    }
  }

  return { totalProfit, schedule: slots.slice(1) };
}

/* -------------------------------------------------------------------------- */
/* 5. Greedy Coin Change (canonical coin systems)                             */
/* -------------------------------------------------------------------------- */

function greedyCoinChange(
  amount: number,
  denominations: number[]
): { coins: { denomination: number; count: number }[]; remainder: number } {
  const sorted = [...denominations].sort((a, b) => b - a);
  let remaining = amount;
  const coins: { denomination: number; count: number }[] = [];

  for (const coin of sorted) {
    if (coin <= 0) continue;
    const count = Math.floor(remaining / coin);
    if (count > 0) {
      coins.push({ denomination: coin, count });
      remaining -= count * coin;
    }
  }

  return { coins, remainder: remaining };
}

/* -------------------------------------------------------------------------- */
/* 6. Kruskal’s Minimum Spanning Tree                                         */
/* -------------------------------------------------------------------------- */

interface WeightedEdge {
  u: number;
  v: number;
  weight: number;
}

class UnionFind {
  private parent: number[];
  private rank: number[];

  constructor(size: number) {
    this.parent = Array.from({ length: size }, (_, i) => i);
    this.rank = Array(size).fill(0);
  }

  find(x: number): number {
    if (this.parent[x] !== x) {
      this.parent[x] = this.find(this.parent[x]); // path compression
    }
    return this.parent[x];
  }

  union(x: number, y: number): boolean {
    const rootX = this.find(x);
    const rootY = this.find(y);

    if (rootX === rootY) return false;

    if (this.rank[rootX] < this.rank[rootY]) {
      this.parent[rootX] = rootY;
    } else if (this.rank[rootX] > this.rank[rootY]) {
      this.parent[rootY] = rootX;
    } else {
      this.parent[rootY] = rootX;
      this.rank[rootX]++;
    }

    return true;
  }
}

function kruskalMST(
  vertexCount: number,
  edges: WeightedEdge[]
): { mst: WeightedEdge[]; totalWeight: number } {
  const sorted = [...edges].sort((a, b) => a.weight - b.weight);
  const uf = new UnionFind(vertexCount);
  const mst: WeightedEdge[] = [];
  let totalWeight = 0;

  for (const edge of sorted) {
    if (uf.union(edge.u, edge.v)) {
      mst.push(edge);
      totalWeight += edge.weight;
      if (mst.length === vertexCount - 1) break;
    }
  }

  return { mst, totalWeight };
}

